ect.Visible = Callback\n\t    end\n\t})\n\tAutoJumpCustom = Speed:CreateToggle({\n\t    Name = \"Custom Jump\",\n\t    Function = function(Callback: boolean)\n\t        AutoJumpValue.Object.Visible = Callback\n\t    end,\n\t    Tooltip = \"Allows you to adjust the jump power\",\n\t    Darker = true,\n\t    Visible = false\n\t})\n\tAutoJumpValue = Speed:CreateSlider({\n\t    Name = \"Jump Power\",\n\t    Min = 1,\n\t    Max = 50,\n\t    Default = 30,\n\t    Darker = true,\n\t    Visible = false\n\t})\nend)\n\nRun(function()\n\tlocal AutoLeave\n\t\n\tAutoLeave = vape.Categories.Utility:CreateModule({\n\t    Name = \"AutoLeave\",\n\t    Function = function(Callback: boolean)\n\t        if Callback then\n\t            AutoLeave:Clean(Blockwars.RemoteIndex.Victory_Show.OnClientEvent:Connect(function()\n\t                ReplicatedStorage.GameEvents.BedWarsRemotes.Return_To_Lobby:FireServer()\n\t            end))\n\t        end\n\t    end,\n\t    Tooltip = \"Automatically leave after the match ends.\"\n\t})\nend)\n\nRun(function()\n\tlocal AutoQueue\n\t\n\tAutoQueue = vape.Categories.Utility:CreateModule({\n\t    Name = \"AutoQueue\",\n\t    Function = function(Callback: boolean)\n\t        if Callback then\n\t            if workspace:GetAttribute(\"ServerType\") == \"Lobby\" then\n\t                task.spawn(function()\n\t                    Blockwars.RemoteIndex.Matchmaking_Request:InvokeServer(\"queue\")\n\t                end)\n\t            end\n\t        end\n\t    end,\n\t    Tooltip = \"Automatically queue in the lobby.\"\n\t})\nend)\n\nRun(function()\n\tlocal AutoToxic\n\tlocal GG\n\tlocal Toggles, Lists, Cloned, Presets = {}, {}, {}, {}\n\t\n\tlocal function SendMessage(Name: string, Object: string?, Default: string?)\n\t    local Message = Default\n\t    if #Lists[Name].ListEnabled > 0 then\n\t        if #Cloned[Name] <= 0 then\n\t            Cloned[Name] = table.clone(Lists[Name].ListEnabled)\n\t        end\n\t\n\t        local Entry: number = Random.new():NextInteger(1, #Cloned[Name])\n\t        Message = Cloned[Name][Entry]\n\t        table.remove(Cloned[Name], Entry)\n\t    end\n\t\n\t    if not Message then\n\t        return\n\t    end\n\t\n\t    Message = Message and Message:gsub(\"<obj>\", Object or \"\") or \"\"\n\t    if TextChatService.ChatVersion == Enum.ChatVersion.TextChatService then\n\t        if TextChatService:CanUserChatAsync(LocalPlayer.UserId) then\n\t            TextChatService.ChatInputBarConfiguration.TargetTextChannel:SendAsync(Message)\n\t        else\n\t            TextChatService.ChatInputBarConfiguration.TargetTextChannel:SendPresetAsync(Presets[Message] or Presets[\"So close\"])\n\t        end\n\t    else\n\t        ReplicatedStorage.DefaultChatSystemChatEvents.SayMessageRequest:FireServer(Message, \"All\")\n\t    end\n\tend\n\t\n\tAutoToxic = vape.Categories.Utility:CreateModule({\n\t    Name = \"AutoToxic\",\n\t    Function = function(Callback: boolean)\n\t        if Callback then\n\t            AutoToxic:Clean(Blockwars.RemoteIndex.Round_Event.OnClientEvent:Connect(function(Data)\n\t                if type(Data) == \"table\" and Data.id == \"final_kill\" then\n\t                    if GG.Enabled then\n\t                        if TextChatService.ChatVersion == Enum.ChatVersion.TextChatService then\n\t                            if TextChatService:CanUserChatAsync(LocalPlayer.UserId) then\n\t                                TextChatService.ChatInputBarConfiguration.TargetTextChannel:SendAsync(\"gg\")\n\t                            else\n\t                                TextChatService.ChatInputBarConfiguration.TargetTextChannel:SendPresetAsync(Presets[\"Good game\"])\n\t                            end\n\t                        else\n\t                            ReplicatedStorage.DefaultChatSystemChatEvents.SayMessageRequest:FireServer(\"gg\", \"All\")\n\t                        end\n\t                    end\n\t\n\t                    if LocalPlayer.Team and LocalPlayer.Team.Name == Data.teamId then\n\t                        if Toggles.Win.Enabled then\n\t                            SendMessage(\"Win\", nil, \"yall garbage\")\n\t                        end\n\t                    end\n\t                end\n\t            end))\n\t        end\n\t    end,\n\t    Tooltip = \"Says a message after a certain action\"\n\t})\n\tGG = AutoToxic:CreateToggle({\n\t    Name = \"AutoGG\",\n\t    Default = true\n\t})\n\tfor _, v: string in {\"Win\"} do\n\t    Cloned[v] = {}\n\t    Toggles[v] = AutoToxic:CreateToggle({\n\t        Name = `{v} `,\n\t        Function = function(Callback: boolean)\n\t            if Lists[v] then\n\t                Lists[v].Object.Visible = Callback\n\t            end\n\t        end\n\t    })\n\t    Lists[v] = AutoToxic:CreateTextList({\n\t        Name = v,\n\t        Darker = true,\n\t        Visible = false,\n\t        Function = function()\n\t            table.clear(Cloned[v])\n\t        end\n\t    })\n\tend\n\t\n\tpcall(function()\n\t    for _, Group: any in TextChatService:GetPresetsAsync().categoryGroups do\n\t        for _, Category: any in Group.categories do\n\t            for _, Message: any in Category.messages do\n\t                Presets[Message.value] = Message.presetId\n\t            end\n\t        end\n\t    end\n\tend)\nend)\n\nRun(function()\n\tlocal Breaker\n\tlocal Range\n\tlocal BreakSpeed\n\tlocal UpdateRate\n\tlocal Custom\n\tlocal Bed\n\tlocal LuckyBlock\n\tlocal IronOre\n\tlocal Effect\n\tlocal CustomHealth = {}\n\tlocal Animation\n\tlocal SelfBreak\n\tlocal InstantBreak\n\tlocal LimitItem\n\tlocal CustomList, Parts = {}, {}\n\t\n\tlocal function GetPick()\n\t    local Inventory: {Instance} = GetInventory()\n\t    for _, Tool: Instance in Inventory do\n\t        if Tool:GetAttribute(\"Tier\") then\n\t            return Tool\n\t        end\n\t    end\n\tend\n\t\n\tlocal function AttemptBreak(List, LocalPosition: Vector3, Tool: Tool): boolean?\n\t    if not List then\n\t        return\n\t    end\n\t    for _, v: BasePart in List do\n\t        if (v.Position - LocalPosition).Magnitude < Range.Value and v:GetAttribute(\"BedTeamId\") ~= (LocalPlayer.Team and LocalPlayer.Team.Name or \"\") and (v:GetAttribute(\"HP\") or 10) > 0 then\n\t            if Tool.Parent ~= LocalPlayer.Character then\n\t                Entity.character.Humanoid:EquipTool(Tool)\n\t            end\n\t\n\t            if v:HasTag(\"BedWarsX_BedSpawn\") then\n\t                local NotCovered: boolean = false\n\t                for _, Normal: Enum.NormalId in Enum.NormalId:GetEnumItems() do\n\t                    if Normal ~= Enum.NormalId.Bottom then\n\t                        if not Blocks[v.Position // 3 + Vector3.fromNormalId(Normal)] then\n\t                            NotCovered = true\n\t                            break\n\t                        end\n\t                    end\n\t                end\n\t\n\t                if NotCovered then\n\t                    Blockwars.RemoteIndex.Block_AttemptHit:FireServer({\n\t                        camPos = LocalPosition,\n\t                        hitPos = v:GetClosestPointOnSurface(LocalPosition),\n\t                        blockInstance = v\n\t                    })\n\t                else\n\t                    local AboveBlock = Blocks[v.Position // 3 + Vector3.new(0, 1, 0)]\n\t\n\t                    if AboveBlock then\n\t                        Blockwars.RemoteIndex.Block_AttemptHit:FireServer({\n\t                            camPos = LocalPosition,\n\t                            hitPos = AboveBlock:GetClosestPointOnSurface(LocalPosition),\n\t                            blockInstance = AboveBlock\n\t                        })\n\t                    end\n\t                end\n\t\n\t                task.wait(0.15)\n\t            else\n\t                Blockwars.RemoteIndex.Mine_AttemptHit:FireServer(v)\n\t            end\n\t\n\t            task.wait(0.05)\n\t            return true\n\t        end\n\t    end\n\t\n\t    return false\n\tend\n\t\n\tBreaker = vape.Categories.World:CreateModule({\n\t    Name = \"Breaker\",\n\t    Function = function(Callback: boolean)\n\t        if Callback then\n\t            local Beds = Collection(\"BedWarsX_BedSpawn\", Breaker)\n\t            local Generators = Collection(\"BedWarsX_Resource\", Breaker)\n\t\n\t            repeat\n\t                task.wait(1 / UpdateRate.Value)\n\t                if not Breaker.Enabled then\n\t                    break\n\t                end\n\t\n\t                local Tool = GetPick()\n\t                if Entity.isAlive and Tool and not IsAttacking then\n\t                    local LocalPosition: Vector3 = BypassRoot and BypassRoot.Position or Entity.character.RootPart.Position\n\t\n\t                    if AttemptBreak(Beds, LocalPosition, Tool) then\n\t                        continue\n\t                    end\n\t                    if AttemptBreak(Generators, LocalPosition, Tool) then\n\t                        continue\n\t                    end\n\t                end\n\t            until not Breaker.Enabled\n\t        end\n\t    end,\n\t    Tooltip = \"Break blocks around you automatically\"\n\t})\n\tRange = Breaker:CreateSlider({\n\t    Name = \"Break range\",\n\t    Min = 1,\n\t    Max = 12,\n\t    Default = 12,\n\t    Suffix = function(Val: number)\n\t        return Val == 1 and \"stud\" or \"studs\"\n\t    end\n\t})\n\tBreakSpeed = Breaker:CreateSlider({\n\t    Name = \"Break speed\",\n\t    Min = 0,\n\t    Max = 0.3,\n\t    Default = 0.25,\n\t    Decimal = 100,\n\t    Suffix = \"seconds\"\n\t})\n\tUpdateRate = Breaker:CreateSlider({\n\t    Name = \"Update rate\",\n\t    Min = 1,\n\t    Max = 120,\n\t    Default = 60,\n\t    Suffix = \"hz\"\n\t})\nend)\n\nRun(function()\n\tlocal FastBreak\n\tlocal Value\n\tlocal Old\n\t\n\tFastBreak = vape.Categories.World:CreateModule({\n\t    Name = \"FastBreak\",\n\t    Function = function(Callback: boolean)\n\t        if Callback then\n\t            Old = hookfunction(Blockwars.BlockBreakConstants.CooldownFor, function(...)\n\t                return Old(...) * (Value.Value / 100)\n\t            end)\n\t        else\n\t            if Old then\n\t                hookfunction(Blockwars.BlockBreakConstants.CooldownFor, Old)\n\t                Old = nil\n\t            end\n\t        end\n\t    end,\n\t    Tooltip = \"Allow you to swing the pickaxe faster.\"\n\t})\n\tValue = FastBreak:CreateSlider({\n\t    Name = \"Break Speed Percent\",\n\t    Min = 0,\n\t    Max = 100,\n\t    Default = 50,\n\t    Suffix = \"%\"\n\t})\nend)\n\nRun(function()\n\tlocal AutoBuy\n\tlocal Shops = {}\n\tlocal Requirements = {\n\t    armor = {\n\t        [\"Leather Armor\"] = \"pickaxe_iron\"\n\t    },\n\t    pickaxe = {\n\t        [\"pickaxe_gold\"] = \"Golden Armor\",\n\t        [\"pickaxe_diamond\"] = \"Diamond Armor\"\n\t    }\n\t}\n\t\n\tlocal function BuyCategory(Ladder: string, Default: boolean?): boolean\n\t    local TierItems = {}\n\t    for _, Item: any in Blockwars.ShopConfig.Items do\n\t        if Item.ladder == Ladder then\n\t            table.insert(TierItems, Item)\n\t        end\n\t    end\n\t\n\t    table.sort(TierItems, function(A, B)\n\t        return (A.tier or -1) < (B.tier or -1)\n\t    end)\n\t\n\t    local NextTier = Default and TierItems[1] or nil\n\t    for _, Item: any in TierItems do\n\t        if Blockwars.Inventory.items[Item.id] then\n\t            NextTier = TierItems[table.find(TierItems, Item) + 1]\n\t            break\n\t        end\n\t    end\n\t\n\t    if NextTier then\n\t        for i: number, Currency: string in {\"Block\", \"Gold\", \"Diamond\"} do\n\t            if (NextTier.cost and NextTier.cost[Currency] or 0) > (Blockwars.Inventory[i == 1 and \"blocks\" or Currency:lower()] or 0) then\n\t                return false\n\t            end\n\t        end\n\t\n\t        if Requirements[Ladder] and Requirements[Ladder][NextTier.id] and not Blockwars.Inventory.items[Requirements[Ladder][NextTier.id]] then\n\t            return false\n\t        end\n\t\n\t        Blockwars.RemoteIndex.Shop_Purchase:InvokeServer({itemId = NextTier.id})\n\t        return true\n\t    end\n\t\n\t    return false\n\tend\n\t\n\tAutoBuy = vape.Categories.Inventory:CreateModule({\n\t    Name = \"AutoBuy\",\n\t    Function = function(Callback: boolean)\n\t        if Callback then\n\t            Shops = Collection(\"BedWarsX_ShopNPC\")\n\t\n\t            repeat\n\t                if Entity.isAlive then\n\t                    local LocalPosition: Vector3 = Entity.character.RootPart.Position\n\t                    for _, Shop: BasePart in Shops do\n\t                        if (Shop.Position - LocalPosition).Magnitude < 20 then\n\t                            if BuyCategory(\"armor\", true) then\n\t                                break\n\t                            end\n\t                            if BuyCategory(\"pickaxe\") then\n\t                                break\n\t                            end\n\t                            if BuyCategory(\"sword\") then\n\t                                break\n\t                            end\n\t                            break\n\t                        end\n\t                    end\n\t                end\n\t\n\t                task.wait(0.2)\n\t            until not AutoBuy.Enabled\n\t        end\n\t    end,\n\t    Tooltip = \"lol\"\n\t})\nend)\n\nRun(function()\n\tlocal FixGUIs\n\t\n\tFixGUIs = vape.Legit:CreateModule({\n\t    Name = \"FixGUIs\",\n\t    Category = \"Game\",\n\t    Icon = GetVapeAsset(`{vape.Directory}/assets/new/legit_fixguis.png`),\n\t    Function = function(Callback: boolean)\n\t        if Callback then\n\t            local Guis = {LocalPlayer.PlayerGui:FindFirstChild(\"Team_UpgradesV3\", true), LocalPlayer.PlayerGui:FindFirstChild(\"ItemShopV3\", true)}\n\t            if #Guis < 2 then\n\t                repeat\n\t                    Guis = {LocalPlayer.PlayerGui:FindFirstChild(\"Team_UpgradesV3\", true), LocalPlayer.PlayerGui:FindFirstChild(\"ItemShopV3\", true)}\n\t                    task.wait()\n\t                until #Guis >= 2 or not FixGUIs.Enabled\n\t\n\t                if not FixGUIs.Enabled then\n\t                    return\n\t                end\n\t            end\n\t\n\t            local Visible: boolean = false\n\t            local Mouse: ImageLabel = Instance.new(\"ImageLabel\")\n\t            Mouse.Size = UDim2.fromOffset(20, 20)\n\t            Mouse.Visible = false\n\t            Mouse.Parent = vape.gui\n\t            FixGUIs:Clean(Mouse)\n\t\n\t            for _, Gui: Instance? in Guis do\n\t                if Gui then\n\t                    for _, v: TextButton in Gui:QueryDescendants(\"TextButton\") do\n\t                        local Ancestor: ScrollingFrame? = v:FindFirstAncestorWhichIsA(\"ScrollingFrame\")\n\t                        if not Ancestor then\n\t                            v.Modal = true\n\t                        end\n\t                    end\n\t\n\t                    Visible = Visible or Gui.Visible\n\t                    FixGUIs:Clean(Gui:GetPropertyChangedSignal(\"Visible\"):Connect(function()\n\t                        Visible = Gui.Visible\n\t                    end))\n\t                end\n\t            end\n\t\n\t            FixGUIs:Clean(RunService.Heartbeat:Connect(function()\n\t                local Location: Vector2 = UserInputService:GetMouseLocation()\n\t                Mouse.Visible = Visible\n\t                if Mouse.Visible then\n\t                    Mouse.Position = UDim2.fromOffset(Location.X, Location.Y)\n\t                end\n\t            end))\n\t        end\n\t    end,\n\t    Tooltip = \"Fix GUI's in first person.\"\n\t})\nend)\n\nRun(function()\n\tlocal HideShield\n\tlocal Parts: {BasePart} = {}\n\t\n\tlocal function Added(Entity)\n\t    local Shield: Instance? = Entity.Character:WaitForChild(\"ShieldModel\", 10)\n\t    if Shield then\n\t        Parts = Shield:QueryDescendants(\"BasePart\")\n\t    end\n\tend\n\t\n\tHideShield = vape.Legit:CreateModule({\n\t    Name = \"HideShield\",\n\t    Category = \"Game\",\n\t    Icon = GetVapeAsset(`{vape.Directory}/assets/new/legit_hideshield.png`),\n\t    Function = function(Callback: boolean)\n\t        if Callback then\n\t            HideShield:Clean(Entity.Events.LocalAdded:Connect(Added))\n\t            if Entity.isAlive then\n\t                task.spawn(Added, Entity.character)\n\t            end\n\t\n\t            repeat\n\t                for _, v: BasePart in Parts do\n\t                    v.Transparency = 1\n\t                end\n\t\n\t                task.wait()\n\t            until not HideShield.Enabled\n\t        else\n\t            table.clear(Parts)\n\t        end\n\t    end,\n\t    Tooltip = \"Hide the shield entirely.\"\n\t})\nend)"},{"path":"src/games/135564683255158.lua","name":"135564683255158.lua","size":1199,"sha":"ac3040e595087a2a57e0aad59fbeb86231024323","encoding":"utf8","content":"local vape = shared.vape\nlocal loadstring = function(...)\n    local Chunk, Message = loadstring(...)\n    if Message and vape then\n        vape:CreateNotification(\"Vape\", `Failed to load : {Message}`, 30, \"alert\")\n    end\n    return Chunk\nend\nlocal isfile = isfile or function(File: string)\n    local Success, Result = pcall(function()\n        return readfile(File)\n    end)\n    return Success and Result ~= nil and Result ~= \"\"\nend\nlocal function DownloadFile(FilePath: string, Func)\n    if not isfile(FilePath) then\n        local Success, Result = pcall(function()\n            return game:HttpGet(`https://api.catvape.dev/download/src/{select(1, FilePath:gsub(`^{vape.Directory}/`, \"\"))}`, true)\n        end)\n        if not Success or Result == \"404: Not Found\" then\n            error(Result)\n        end\n        if FilePath:find(\".lua\") then\n            Result = `--This watermark is used to delete the file if its cached, remove it to make the file persist after vape updates.\\n{Result}`\n        end\n        writefile(FilePath, Result)\n    end\n    return (Func or readfile)(FilePath)\nend\n\nvape.Place = 155615604\nloadstring(DownloadFile(`{vape.Directory}/games/{vape.Place}.lua`), \"prison life\")()"},{"path":"src/games/139566161526375.lua","name":"139566161526375.lua","size":42587,"sha":"9637fbb8190ed25fb9e68f99351ead45378aa678","encoding":"utf8","content":"local Run = function(Func: () -> ())\n    Func()\nend\nlocal cloneref = cloneref or function(Reference: Instance)\n    return Reference\nend\n\nlocal Players: Players = cloneref(game:GetService(\"Players\"))\nlocal UserInputService: UserInputService = cloneref(game:GetService(\"UserInputService\"))\nlocal ReplicatedStorage: ReplicatedStorage = cloneref(game:GetService(\"ReplicatedStorage\"))\nlocal CollectionService: CollectionService = cloneref(game:GetService(\"CollectionService\"))\nlocal RunService: RunService = cloneref(game:GetService(\"RunService\"))\n\nlocal Camera: Camera = workspace.CurrentCamera\nlocal LocalPlayer: Player = Players.LocalPlayer\nlocal vape = shared.vape\nlocal Entity = vape.Libraries.entity\nlocal TargetInfo = vape.Libraries.targetinfo\nlocal PredictionLib = vape.Libraries.prediction\n\nlocal BridgeDuel = {}\nlocal Store = {\n    blocks = {},\n    serverBlocks = {}\n}\n\nlocal function GetTool(): Tool?\n    return LocalPlayer.Character and LocalPlayer.Character:FindFirstChildWhichIsA(\"Tool\", true) or nil\nend\n\nlocal function SendNotification(...)\n    return vape:CreateNotification(...)\nend\n\nlocal function ParsePositions(Part: Instance, Func: (Vector3) -> ())\n    if Part:IsA(\"Part\") then\n        local Start: Vector3 = -(Part.Size / 2) + Vector3.new(1.5, 1.5, 1.5)\n        for X: number = 0, Part.Size.X - 1, 3 do\n            for Y: number = 0, Part.Size.Y - 1, 3 do\n                for Z: number = 0, Part.Size.Z - 1, 3 do\n                    local Position: Vector3 = Start + Vector3.new(X, Y, Z)\n                    Position = Part.CFrame:PointToWorldSpace(Position)\n                    Position = Vector3.new(math.round(Position.X), math.round(Position.Y), math.round(Position.Z))\n                    Func(Position)\n                end\n            end\n        end\n    end\nend\n\nRun(function()\n    local Knit = require(ReplicatedStorage.Modules.Knit.Client)\n    if not debug.getupvalue(Knit.Start, 1) then\n        repeat\n            task.wait()\n        until debug.getupvalue(Knit.Start, 1)\n    end\n\n    BridgeDuel = setmetatable({\n        BedwarsShop = require(ReplicatedStorage.Constants.BedWarsShop),\n        BedwarsUpgrades = require(ReplicatedStorage.Constants.BedWarsTeamUpgrades),\n        Blink = require(ReplicatedStorage.Blink.Client),\n        BreakTimes = require(ReplicatedStorage.Constants.Blocks),\n        BowClient = require(ReplicatedStorage.Client.Components.All.Tools.BowClient),\n        CombatConstants = require(ReplicatedStorage.Constants.Melee),\n        Communication = require(ReplicatedStorage.Client.Communication),\n        Knit = Knit,\n        Entity = require(ReplicatedStorage.Modules.Entity),\n        ServerData = require(ReplicatedStorage.Modules.ServerData),\n    }, {\n        __index = function(self, Index: string)\n            rawset(self, Index, Index:find(\"Service\") and Knit.GetService(Index) or Knit.GetController(Index))\n            return rawget(self, Index)\n        end\n    })\n\n    task.spawn(function()\n        local Map: Instance? = workspace:WaitForChild(\"Map\", 99999)\n        if Map and vape.Loaded ~= nil then\n            vape:Clean(Map.DescendantAdded:Connect(function(Part: Instance)\n                ParsePositions(Part, function(Position: Vector3)\n                    Store.blocks[Position] = Part\n                end)\n            end))\n            vape:Clean(Map.DescendantRemoving:Connect(function(Part: Instance)\n                ParsePositions(Part, function(Position: Vector3)\n                    if Store.blocks[Position] == Part then\n                        Store.blocks[Position] = nil\n                        Store.serverBlocks[Position] = nil\n                    end\n                end)\n            end))\n            for _, v: Instance in Map:GetDescendants() do\n                ParsePositions(v, function(Position: Vector3)\n                    Store.blocks[Position] = v\n                    Store.serverBlocks[Position] = v\n                end)\n            end\n        end\n    end)\n\n    vape:Clean(function()\n        table.clear(Store.blocks)\n        table.clear(Store)\n    end)\nend)\n\nfor _, v: string in {\"Reach\", \"SilentAim\", \"Disabler\", \"HitBoxes\", \"MurderMystery\", \"AutoRejoin\"} do\n    vape:Remove(v)\nend\n\nRun(function()\n\tlocal AutoClicker\n\tlocal CPS\n\t\n\tAutoClicker = vape.Categories.Combat:CreateModule({\n\t    Name = \"AutoClicker\",\n\t    Function = function(Callback: boolean)\n\t        if Callback then\n\t            repeat\n\t                local Tool: Tool? = GetTool()\n\t                if Tool and UserInputService:IsMouseButtonPressed(0) then\n\t                    Tool:Activate()\n\t                end\n\t\n\t                task.wait(1 / CPS.GetRandomValue())\n\t            until not AutoClicker.Enabled\n\t        end\n\t    end,\n\t    Tooltip = \"Automatically clicks for you\"\n\t})\n\tCPS = AutoClicker:CreateTwoSlider({\n\t    Name = \"CPS\",\n\t    Min = 1,\n\t    Max = 20,\n\t    DefaultMin = 8,\n\t    DefaultMax = 12\n\t})\nend)\n\nRun(function()\n\t--[[local old\n\t\n\tvape.Categories.Combat:CreateModule({\n\t\tName = 'Reach',\n\t\tFunction = function(callback)\n\t\t\tif callback then\n\t\t\t\t--old = rawget(bd.CombatConstants, 'REACH_IN_STUDS')\n\t\t\t\t--rawset(bd.CombatConstants, 'REACH_IN_STUDS', 18)\n\t\t\t\t--rawset(bd.Entity.LocalEntity, 'Reach', 18)\n\t\t\telse\n\t\t\t\t--rawset(bd.CombatConstants, 'REACH_IN_STUDS', old)\n\t\t\t\t--rawset(bd.Entity.LocalEntity, 'Reach', old)\n\t\t\t\t--old = nil\n\t\t\tend\n\t\tend,\n\t\tTooltip = 'Extends attack reach'\n\t})]]\nend)\n\nRun(function()\n\tlocal Velocity\n\tlocal Horizontal\n\tlocal Vertical\n\tlocal Chance\n\tlocal Targeting\n\tlocal Old\n\tlocal Connection\n\t\n\tlocal function VelocityFunction(KnockbackVelocity: Vector3, ...)\n\t    if Random.new():NextNumber(0, 100) > Chance.Value then\n\t        return Old(KnockbackVelocity, ...)\n\t    end\n\t\n\t    local Check = (not Targeting.Enabled) or Entity.EntityPosition({\n\t        Range = 50,\n\t        Part = \"RootPart\",\n\t        Players = true\n\t    })\n\t\n\t    if Check then\n\t        local HorizontalScale, VerticalScale = (Horizontal.Value / 100), (Vertical.Value / 100)\n\t        if HorizontalScale == 0 and VerticalScale == 0 then\n\t            return\n\t        end\n\t        KnockbackVelocity = Vector3.new(KnockbackVelocity.X * HorizontalScale, KnockbackVelocity.Y * VerticalScale, KnockbackVelocity.Z * HorizontalScale)\n\t    end\n\t\n\t    return Old(KnockbackVelocity, ...)\n\tend\n\t\n\tVelocity = vape.Categories.Combat:CreateModule({\n\t    Name = \"Velocity\",\n\t    Function = function(Callback: boolean)\n\t        if Callback then\n\t            Connection = getconnections(BridgeDuel.CombatService.KnockBackApplied._re.OnClientEvent)[1]\n\t            if not Connection then\n\t                return\n\t            end\n\t\n\t            Old = hookfunction(Connection.Function, function(...)\n\t                return VelocityFunction(...)\n\t            end)\n\t        else\n\t            if Old then\n\t                hookfunction(Connection.Function, Old)\n\t            end\n\t            Connection = nil\n\t        end\n\t    end,\n\t    Tooltip = \"Reduces knockback taken\"\n\t})\n\tHorizontal = Velocity:CreateSlider({\n\t    Name = \"Horizontal\",\n\t    Min = 0,\n\t    Max = 100,\n\t    Default = 0,\n\t    Suffix = \"%\"\n\t})\n\tVertical = Velocity:CreateSlider({\n\t    Name = \"Vertical\",\n\t    Min = 0,\n\t    Max = 100,\n\t    Default = 0,\n\t    Suffix = \"%\"\n\t})\n\tChance = Velocity:CreateSlider({\n\t    Name = \"Chance\",\n\t    Min = 0,\n\t    Max = 100,\n\t    Default = 100,\n\t    Suffix = \"%\"\n\t})\n\tTargeting = Velocity:CreateToggle({Name = \"Only when targeting\"})\nend)\n\nRun(function()\n\tlocal Old\n\t\n\tvape.Categories.Blatant:CreateModule({\n\t    Name = \"Criticals\",\n\t    Function = function(Callback: boolean)\n\t        if Callback then\n\t            Old = hookfunction(BridgeDuel.Blink.item_action.attack_entity.fire, function(...)\n\t                local Data = ...\n\t                if type(Data) == \"table\" then\n\t                    rawset(Data, \"is_crit\", true)\n\t                end\n\t\n\t                return Old(...)\n\t            end)\n\t        else\n\t            hookfunction(BridgeDuel.Blink.item_action.attack_entity.fire, Old)\n\t            Old = nil\n\t        end\n\t    end,\n\t    Tooltip = \"Always hit criticals\"\n\t})\nend)\n\nRun(function()\n\tlocal Old\n\t\n\tvape.Categories.Blatant:CreateModule({\n\t    Name = \"InvMove\",\n\t    Function = function(Callback: boolean)\n\t        if Callback then\n\t            Old = hookfunction(BridgeDuel.MovementController.AddSpeedOverride, function(...)\n\t                if select(2, ...) == \"MenuOpen\" then\n\t                    return\n\t                end\n\t\n\t                return Old(...)\n\t            end)\n\t\n\t            BridgeDuel.MovementController:RemoveSpeedOverride(\"MenuOpen\")\n\t        else\n\t            if Old then\n\t                hookfunction(BridgeDuel.MovementController.AddSpeedOverride, Old)\n\t                Old = nil\n\t            end\n\t        end\n\t    end,\n\t    Tooltip = \"Allows you to have continuous movement in menus\"\n\t})\nend)\n\nRun(function()\n\tlocal Killaura\n\tlocal Targets\n\tlocal CPS\n\tlocal SwingRange\n\tlocal AttackRange\n\tlocal AngleSlider\n\tlocal Max\n\tlocal Mouse\n\tlocal Swing\n\tlocal Block\n\tlocal AutoBlock\n\tlocal BoxSwingColor\n\tlocal BoxAttackColor\n\tlocal ParticleTexture\n\tlocal ParticleColor1\n\tlocal ParticleColor2\n\tlocal Particle