               if not Ent.Character:GetAttribute(\"Arrested\") then\n\t                            local Toggle = Ent.Player.Team and Toggles[Ent.Player.Team.Name]\n\t                            if Toggle and not Toggle.Enabled then\n\t                                continue\n\t                            end\n\t\n\t                            if Ent.Player.Team == Teams.Inmates and Ent.Character:GetAttribute(\"Hostile\") and not Ent.Character:GetAttribute(\"Tased\") then\n\t                                continue\n\t                            end\n\t\n\t                            if ReplicatedStorage.Remotes.ArrestPlayer:InvokeServer(Ent.Player, 1) then\n\t                                ArrestCooldown = os.clock() + 7\n\t                                VapeEvents.Arrested:Fire()\n\t                                SendNotification(\"AutoArrest\", `Arrested {Ent.Player.Name}`, 7)\n\t                            end\n\t\n\t                            break\n\t                        end\n\t                    end\n\t                end\n\t\n\t                if CooldownHolder then\n\t                    CooldownHolder.Visible = ArrestCooldown > os.clock()\n\t\n\t                    if CooldownHolder.Visible then\n\t                        local Remaining: number = (ArrestCooldown - os.clock())\n\t                        CooldownFrame.Size = UDim2.new(math.clamp(Remaining / 7, 0, 1), -2, 1, -2)\n\t                        CooldownLabel.Text = `{math.round(Remaining * 10) / 10}s`\n\t                    end\n\t                end\n\t\n\t                task.wait(0.05)\n\t            until not AutoArrest.Enabled\n\t        else\n\t            if CooldownHolder then\n\t                CooldownHolder.Visible = false\n\t            end\n\t        end\n\t    end,\n\t    Tooltip = \"Automatically uses handcuffs on nearby entities\"\n\t})\n\tRange = AutoArrest:CreateSlider({\n\t    Name = \"Range\",\n\t    Min = 1,\n\t    Max = 8,\n\t    Default = 8,\n\t    Suffix = function(Val: number)\n\t        return Val == 1 and \"stud\" or \"studs\"\n\t    end\n\t})\n\tHandCheck = AutoArrest:CreateToggle({\n\t    Name = \"Hand Check\",\n\t    Tooltip = \"Only arrest if you have handcuffs equipped.\"\n\t})\n\tCooldownBar = AutoArrest:CreateToggle({\n\t    Name = \"Cooldown Bar\",\n\t    Function = function(Callback: boolean)\n\t        if Callback then\n\t            CooldownHolder = Instance.new(\"Frame\")\n\t            CooldownHolder.Visible = false\n\t            CooldownHolder.BorderSizePixel = 0\n\t            CooldownHolder.BackgroundTransparency = 0.7\n\t            CooldownHolder.AnchorPoint = Vector2.new(0.5, 0)\n\t            CooldownHolder.BackgroundColor3 = Color3.new(1, 1, 1)\n\t            CooldownHolder.Size = UDim2.new(0.1, 0, 0, 5)\n\t            CooldownHolder.Position = UDim2.fromScale(0.5, 0.55)\n\t            CooldownHolder.Parent = vape.gui\n\t            CooldownFrame = Instance.new(\"Frame\")\n\t            CooldownFrame.BorderSizePixel = 0\n\t            CooldownFrame.BackgroundTransparency = 0.3\n\t            CooldownFrame.BackgroundColor3 = Color3.new(1, 1, 1)\n\t            CooldownFrame.Size = UDim2.new(1, -2, 1, -2)\n\t            CooldownFrame.Position = UDim2.fromOffset(1, 1)\n\t            CooldownFrame.Parent = CooldownHolder\n\t            CooldownLabel = Instance.new(\"TextLabel\")\n\t            CooldownLabel.Size = UDim2.new(1, 0, 0, 14)\n\t            CooldownLabel.Position = UDim2.fromOffset(0, 10)\n\t            CooldownLabel.BackgroundTransparency = 1\n\t            CooldownLabel.TextColor3 = Color3.new(1, 1, 1)\n\t            CooldownLabel.TextScaled = true\n\t            CooldownLabel.TextStrokeTransparency = 0\n\t            CooldownLabel.Font = Enum.Font.Arial\n\t            CooldownLabel.Parent = CooldownHolder\n\t        else\n\t            if CooldownFrame then\n\t                CooldownFrame:Destroy()\n\t                CooldownFrame = nil\n\t            end\n\t        end\n\t    end,\n\t    Tooltip = \"Show the cooldown for arresting\"\n\t})\n\t\n\tfor _, v: string in {\"Inmates\", \"Criminals\"} do\n\t    Toggles[v] = AutoArrest:CreateToggle({\n\t        Name = `Arrest {v}`,\n\t        Default = true\n\t    })\n\tend\nend)\n\nRun(function()\n\tlocal AutoReset\n\t\n\tAutoReset = vape.Categories.Blatant:CreateModule({\n\t    Name = \"AutoReset\",\n\t    Function = function(Callback: boolean)\n\t        if Callback then\n\t            AutoReset:Clean(LocalPlayer:GetPropertyChangedSignal(\"Team\"):Connect(function()\n\t                if LocalPlayer.Team == Teams.Criminals and Entity.isAlive then\n\t                    Entity.character.Humanoid:ChangeState(Enum.HumanoidStateType.Dead)\n\t                end\n\t            end))\n\t        end\n\t    end,\n\t    Tooltip = \"Automatically reset after becoming a criminal.\"\n\t})\nend)\n\nRun(function()\n\tlocal AutoTaser\n\tlocal Range\n\tlocal VelocityCheck\n\tlocal Cooldown: number = 0\n\t\n\tAutoTaser = vape.Categories.Blatant:CreateModule({\n\t    Name = \"AutoTaser\",\n\t    Function = function(Callback: boolean)\n\t        if Callback then\n\t            repeat\n\t                local Backpack = LocalPlayer:FindFirstChildWhichIsA(\"Backpack\")\n\t                local Taser = Backpack and Backpack:FindFirstChild(\"Taser\")\n\t\n\t                if Taser and (Taser:GetAttribute(\"CurrentAmmo\") or 1) > 0 and Cooldown < os.clock() and (ArrestCooldown - os.clock()) < 3 then\n\t                    if not VelocityCheck.Enabled or Entity.isAlive and Entity.character.RootPart.AssemblyLinearVelocity.Magnitude < 40 then\n\t                        local Entities = Entity.AllPosition({\n\t                            Range = Range.Value,\n\t                            AttackCheck = false,\n\t                            Wallcheck = true,\n\t                            Part = \"Head\",\n\t                            Origin = Entity.isAlive and Entity.character.Head.Position or Vector3.zero,\n\t                            Players = true\n\t                        })\n\t\n\t                        for _, Ent: any in Entities do\n\t                            if not (Ent.Character:GetAttribute(\"Tased\") or Ent.Character:GetAttribute(\"Arrested\")) then\n\t                                Cooldown = os.clock() + 2\n\t                                local Equipped = LocalPlayer.Character:FindFirstChildWhichIsA(\"Tool\")\n\t                                if Equipped then\n\t                                    Equipped.Parent = Backpack\n\t                                end\n\t\n\t                                Taser.Parent = LocalPlayer.Character\n\t                                break\n\t                            end\n\t                        end\n\t                    end\n\t                end\n\t\n\t                task.wait(0.05)\n\t            until not AutoTaser.Enabled\n\t        end\n\t    end,\n\t    Tooltip = \"Automatically taze people around you. (only works with SilentAim AutoFire with Position Mode enabled)\"\n\t})\n\tRange = AutoTaser:CreateSlider({\n\t    Name = \"Range\",\n\t    Min = 1,\n\t    Max = 52,\n\t    Default = 52,\n\t    Suffix = function(Val: number)\n\t        return Val == 1 and \"stud\" or \"studs\"\n\t    end\n\t})\n\tVelocityCheck = AutoTaser:CreateToggle({\n\t    Name = \"Velocity Check\",\n\t    Default = true\n\t})\nend)\n\nRun(function()\n\tlocal FenceGodmode\n\t\n\tFenceGodmode = vape.Categories.Blatant:CreateModule({\n\t    Name = \"FenceGodmode\",\n\t    Function = function(Callback: boolean)\n\t        for _, Fence: BasePart in workspace.Prison_Fences:QueryDescendants(\"BasePart:has(> TouchTransmitter)\") do\n\t            Fence.CanTouch = not Callback\n\t        end\n\t    end,\n\t    Tooltip = \"Ignore damage from standing ontop of fences.\"\n\t})\nend)\n\nRun(function()\n\tlocal GunModifications\n\tlocal Spread\n\tlocal FireRate\n\tlocal Automatic\n\tlocal OldData, Old = {}\n\tlocal OldHook\n\t\n\tlocal function Modify()\n\t    local Data = debug.getupvalue(OldShoot or PrisonLife.Shoot, 10)\n\t    if Data and GunModifications.Enabled then\n\t        if Old ~= Data then\n\t            OldData = table.clone(Data)\n\t            Old = Data\n\t        end\n\t\n\t        Data.SpreadRadius = Spread.Enabled and 0 or OldData.SpreadRadius\n\t        Data.FireRate = (OldData.FireRate or 0) * (FireRate.Value / 100)\n\t        Data.AutoFire = Automatic.Enabled or OldData.AutoFire\n\t    end\n\tend\n\t\n\t\n\tGunModifications = vape.Categories.Blatant:CreateModule({\n\t    Name = \"GunModifications\",\n\t    Function = function(Callback: boolean)\n\t        if Callback then\n\t            OldEquip = hookfunction(PrisonLife.Equip, function(...)\n\t                local Results = table.pack(OldEquip(...))\n\t                Modify()\n\t                return unpack(Results, 1, Results.n)\n\t            end)\n\t\n\t            Modify()\n\t        else\n\t            if OldEquip then\n\t                if restorefunction then\n\t                    restorefunction(PrisonLife.Equip)\n\t                else\n\t                    hookfunction(PrisonLife.Equip, OldEquip)\n\t                end\n\t                OldEquip = nil\n\t            end\n\t\n\t            if Old then\n\t                for Key: string, v: any in OldData do\n\t                    Old[Key] = v\n\t                end\n\t                table.clear(OldData)\n\t                Old = nil\n\t            end\n\t        end\n\t    end,\n\t    Tooltip = \"Apply various modifications to enhance any firearm\"\n\t})\n\tFireRate = GunModifications:CreateSlider({\n\t    Name = \"FireRate Multiplier\",\n\t    Min = 1,\n\t    Max = 100,\n\t    Default = 100,\n\t    Suffix = \"%\",\n\t    Function = Modify\n\t})\n\tSpread = GunModifications:CreateToggle({\n\t    Name = \"No Spread\",\n\t    Function = Modify\n\t})\n\tAutomatic = GunModifications:CreateToggle({\n\t    Name = \"Full Automatic\",\n\t    Function = Modify\n\t})\nend)\n\nRun(function()\n\tlocal Killaura\n\tlocal Targets\n\tlocal AttackRange\n\tlocal AngleSlider\n\tlocal Max\n\tlocal Mouse\n\tlocal BoxSwingColor\n\tlocal BoxAttackColor\n\tlocal ParticleTexture\n\tlocal ParticleColor1\n\tlocal ParticleColor2\n\tlocal ParticleSize\n\tlocal Face\n\tlocal Overlay: OverlapParams = OverlapParams.new()\n\tOverlay.FilterType = Enum.RaycastFilterType.Include\n\tlocal Particles, Boxes, AttackDelay = {}, {}, tick()\n\t\n\tlocal function GetAttackData()\n\t    if Mouse.Enabled then\n\t        if not UserInputService:IsMouseButtonPressed(0) then\n\t            return false\n\t        end\n\t    end\n\t\n\t    return true\n\tend\n\t\n\tKillaura = vape.Categories.Blatant:CreateModule({\n\t    Name = \"Killaura\",\n\t    Function = function(Callback: boolean)\n\t        if Callback then\n\t            repeat\n\t                local CanAttack: boolean = GetAttackData()\n\t                local Attacked = {}\n\t                if CanAttack then\n\t                    local Entities = Entity.AllPosition({\n\t                        Range = AttackRange.Value,\n\t                        Wallcheck = Targets.Walls.Enabled or nil,\n\t                        Part = \"RootPart\",\n\t                        Players = Targets.Players.Enabled,\n\t                        NPCs = Targets.NPCs.Enabled,\n\t                        Priority = Targets.Priority.Value,\n\t                        Limit = Max.Value,\n\t                        AttackCheck = true\n\t                    })\n\t\n\t                    if #Entities > 0 then\n\t                        local SelfPosition: Vector3 = Entity.character.RootPart.Position\n\t                        local LocalFacing: Vector3 = Entity.character.RootPart.CFrame.LookVector * Vector3.new(1, 0, 1)\n\t\n\t                        for _, v: any in Entities do\n\t                            local Delta: Vector3 = (v.RootPart.Position - SelfPosition)\n\t                            local Angle: number = math.acos(LocalFacing:Dot((Delta * Vector3.new(1, 0, 1)).Unit))\n\t                            if Angle > (math.rad(AngleSlider.Value) / 2) then\n\t                                continue\n\t                            end\n\t                            if LocalPlayer.Team == Teams.Guards and v.Player.Team == Teams.Inmates and not v.Character:GetAttribute(\"Hostile\") then\n\t                                continue\n\t                            end\n\t\n\t                            table.insert(Attacked, {\n\t                                Entity = v,\n\t                                Check = BoxAttackColor\n\t                            })\n\t                            TargetInfo.Targets[v] = tick() + 1\n\t                            ReplicatedStorage.meleeEvent:FireServer(v.Player, 1, 1)\n\t                        end\n\t                    end\n\t                end\n\t\n\t                for i: number, v: BoxHandleAdornment in Boxes do\n\t                    v.Adornee = Attacked[i] and Attacked[i].Entity.RootPart or nil\n\t                    if v.Adornee then\n\t                        v.Color3 = Color3.fromHSV(Attacked[i].Check.Hue, Attacked[i].Check.Sat, Attacked[i].Check.Value)\n\t                        v.Transparency = 1 - Attacked[i].Check.Opacity\n\t                    end\n\t                end\n\t\n\t                for i: number, v: Part in Particles do\n\t                    v.Position = Attacked[i] and Attacked[i].Entity.RootPart.Position or Vector3.new(9e9, 9e9, 9e9)\n\t                    v.Parent = Attacked[i] and Camera or nil\n\t                end\n\t\n\t                if Face.Enabled and Attacked[1] then\n\t                    local TargetPosition: Vector3 = Attacked[1].Entity.RootPart.Position * Vector3.new(1, 0, 1)\n\t                    Entity.character.RootPart.CFrame = CFrame.lookAt(Entity.character.RootPart.Position, Vector3.new(TargetPosition.X, Entity.character.RootPart.Position.Y + 0.01, TargetPosition.Z))\n\t                end\n\t\n\t                task.wait(0.05)\n\t            until not Killaura.Enabled\n\t        else\n\t            for _, v: BoxHandleAdornment in Boxes do\n\t                v.Adornee = nil\n\t            end\n\t\n\t            for _, v: Part in Particles do\n\t                v.Parent = nil\n\t            end\n\t        end\n\t    end,\n\t    Tooltip = \"Attack players around you\\nwithout aiming at them.\"\n\t})\n\tTargets = Killaura:CreateTargets({Players = true})\n\tAttackRange = Killaura:CreateSlider({\n\t    Name = \"Attack range\",\n\t    Min = 1,\n\t    Max = 12,\n\t    Default = 12,\n\t    Suffix = function(Val: number)\n\t        return Val == 1 and \"stud\" or \"studs\"\n\t    end\n\t})\n\tAngleSlider = Killaura:CreateSlider({\n\t    Name = \"Max angle\",\n\t    Min = 1,\n\t    Max = 360,\n\t    Default = 360\n\t})\n\tMax = Killaura:CreateSlider({\n\t    Name = \"Max targets\",\n\t    Min = 1,\n\t    Max = 10,\n\t    Default = 10\n\t})\n\tMouse = Killaura:CreateToggle({Name = \"Require mouse down\"})\n\tKillaura:CreateToggle({\n\t    Name = \"Show target\",\n\t    Function = function(Callback: boolean)\n\t        BoxSwingColor.Object.Visible = Callback\n\t        BoxAttackColor.Object.Visible = Callback\n\t        if Callback then\n\t            for i: number = 1, 10 do\n\t                local Box: BoxHandleAdornment = Instance.new(\"BoxHandleAdornment\")\n\t                Box.Adornee = nil\n\t                Box.AlwaysOnTop = true\n\t                Box.Size = Vector3.new(3, 5, 3)\n\t                Box.CFrame = CFrame.new(0, -0.5, 0)\n\t                Box.ZIndex = 0\n\t                Box.Parent = vape.gui\n\t                Boxes[i] = Box\n\t            end\n\t        else\n\t            for _, v: BoxHandleAdornment in Boxes do\n\t                v:Destroy()\n\t            end\n\t            table.clear(Boxes)\n\t        end\n\t    end\n\t})\n\tBoxSwingColor = Killaura:CreateColorSlider({\n\t    Name = \"Target Color\",\n\t    Darker = true,\n\t    DefaultHue = 0.6,\n\t    DefaultOpacity = 0.5,\n\t    Visible = false\n\t})\n\tBoxAttackColor = Killaura:CreateColorSlider({\n\t    Name = \"Attack Color\",\n\t    Darker = true,\n\t    DefaultOpacity = 0.5,\n\t    Visible = false\n\t})\n\tKillaura:CreateToggle({\n\t    Name = \"Target particles\",\n\t    Function = function(Callback: boolean)\n\t        ParticleTexture.Object.Visible = Callback\n\t        ParticleColor1.Object.Visible = Callback\n\t        ParticleColor2.Object.Visible = Callback\n\t        ParticleSize.Object.Visible = Callback\n\t        if Callback then\n\t            for i: number = 1, 10 do\n\t                local Part: Part = Instance.new(\"Part\")\n\t                Part.Size = Vector3.new(2, 4, 2)\n\t                Part.Anchored = true\n\t                Part.CanCollide = false\n\t                Part.Transparency = 1\n\t                Part.CanQuery = false\n\t                Part.Parent = Killaura.Enabled and Camera or nil\n\t                local Emitter: ParticleEmitter = Instance.new(\"ParticleEmitter\")\n\t                Emitter.Brightness = 1.5\n\t                Emitter.Size = NumberSequence.new(ParticleSize.Value)\n\t                Emitter.Shape = Enum.ParticleEmitterShape.Sphere\n\t                Emitter.Texture = ParticleTexture.Value\n\t                Emitter.Transparency = NumberSequence.new(0)\n\t                Emitter.Lifetime = NumberRange.new(0.4)\n\t                Emitter.Speed = NumberRange.new(16)\n\t                Emitter.Rate = 128\n\t                Emitter.Drag = 16\n\t                Emitter.ShapePartial = 1\n\t                Emitter.Color = ColorSequence.new({\n\t                    ColorSequenceKeypoint.new(0, Color3.fromHSV(ParticleColor1.Hue, ParticleColor1.Sat, ParticleColor1.Value)),\n\t                    ColorSequenceKeypoint.new(1, Color3.fromHSV(ParticleColor2.Hue, ParticleColor2.Sat, ParticleColor2.Value))\n\t                })\n\t                Emitter.Parent = Part\n\t                Particles[i] = Part\n\t            end\n\t        else\n\t            for _, v: Part in Particles do\n\t                v:Destroy()\n\t            end\n\t            table.clear(Particles)\n\t        end\n\t    end\n\t})\n\tParticleTexture = Killaura:CreateTextBox({\n\t    Name = \"Texture\",\n\t    Default = \"rbxassetid://14736249347\",\n\t    Function = function()\n\t        for _, v: Part in Particles do\n\t            v.ParticleEmitter.Texture = ParticleTexture.Value\n\t        end\n\t    end,\n\t    Darker = true,\n\t    Visible = false\n\t})\n\tParticleColor1 = Killaura:CreateColorSlider({\n\t    Name = \"Color Begin\",\n\t    Function = function(Hue: number, Sat: number, Val: number)\n\t        for _, v: Part in Particles do\n\t            v.ParticleEmitter.Color = ColorSequence.new({\n\t                ColorSequenceKeypoint.new(0, Color3.fromHSV(Hue, Sat, Val)),\n\t                ColorSequenceKeypoint.new(1, Color3.fromHSV(ParticleColor2.Hue, ParticleColor2.Sat, ParticleColor2.Value))\n\t            })\n\t        end\n\t    end,\n\t    Darker = true,\n\t    Visible = false\n\t})\n\tParticleColor2 = Killaura:CreateColorSlider({\n\t    Name = \"Color End\",\n\t    Function = function(Hue: number, Sat: number, Val: number)\n\t        for _, v: Part in Particles do\n\t            v.ParticleEmitter.Color = ColorSequence.new({\n\t                ColorSequenceKeypoint.new(0, Color3.fromHSV(ParticleColor1.Hue, ParticleColor1.Sat, ParticleColor1.Value)),\n\t                ColorSequenceKeypoint.new(1, Color3.fromHSV(Hue, Sat, Val))\n\t            })\n\t        end\n\t    end,\n\t    Darker = true,\n\t    Visible = false\n\t})\n\tParticleSize = Killaura:CreateSlider({\n\t    Name = \"Size\",\n\t    Min = 0,\n\t    Max = 1,\n\t    Default = 0.2,\n\t    Decimal = 100,\n\t    Function = function(Val: number)\n\t        for _, v: Part in Particles do\n\t            v.ParticleEmitter.Size = NumberSequence.new(Val)\n\t        end\n\t    end,\n\t    Darker = true,\n\t    Visible = false\n\t})\n\tFace = Killaura:CreateToggle({Name = \"Face target\"})\nend)\n\nRun(function()\n\tlocal NoJumpCooldown\n\tlocal Old\n\t\n\tlocal function EntityAdded(Ent)\n\t    Old = getconnections(Ent.Humanoid:GetPropertyChangedSignal(\"Jump\"))[1]\n\t    if not Old then\n\t        repeat\n\t            Old = getconnections(Ent.Humanoid:GetPropertyChangedSignal(\"Jump\"))[1]\n\t            task.wait()\n\t        until Old or not NoJumpCooldown.Enabled\n\t\n\t        if not NoJumpCooldown.Enabled then\n\t            return\n\t        end\n\t    end\n\t\n\t    if Old then\n\t        Old:Disable()\n\t    end\n\tend\n\t\n\tNoJumpCooldown = vape.Categories.Blatant:CreateModule({\n\t    Name = \"NoJumpCooldown\",\n\t    Function = function(Callback: boolean)\n\t        if Callback then\n\t            NoJumpCooldown:Clean(Entity.Events.LocalAdded:Connect(EntityAdded))\n\t            if Entity.isAlive then\n\t                task.spawn(EntityAdded, Entity.character)\n\t            end\n\t        else\n\t            if Old then\n\t                Old:Enable()\n\t                Old = nil\n\t            end\n\t        end\n\t    end,\n\t    Tooltip = \"Remove the stamina cooldown from jumping\"\n\t})\nend)\n\nRun(function()\n\tlocal VehicleFly\n\tlocal Mode\n\tlocal Speed\n\tlocal Welds = {}\n\tlocal Up, Down = 0, 0\n\t\n\tVehicleFly = vape.Categories.Blatant:CreateModule({\n\t    Name = \"VehicleFly\",\n\t    Function = function(Callback: boolean)\n\t        if Callback then\n\t            Up, Down = 0, 0\n\t            for _, v: string in {\"InputBegan\", \"InputEnded\"} do\n\t                VehicleFly:Clean(UserInputService[v]:Connect(function(Input: InputObject)\n\t                    if not UserInputService:GetFocusedTextBox() then\n\t                        if Input.KeyCode == Enum.KeyCode.E then\n\t                            Up = v == \"InputBegan\" and 1 or 0\n\t                        elseif Input.KeyCode == Enum.KeyCode.Q then\n\t                            Down = v == \"InputBegan\" and -1 or 0\n\t                        end\n\t                    end\n\t                end))\n\t            end\n\t\n\t            if Mode.Value == \"Part\" then\n\t                local Part: Part = Instance.new(\"Part\")\n\t                Part.Size = Vector3.new(50, 1, 50)\n\t                Part.Anchored = true\n\t                Part.CanQuery = false\n\t                Part.Transparency = 1\n\t\n\t                VehicleFly:Clean(Part)\n\t                repeat\n\t                    local Seat = Entity.isAlive and Entity.character.Humanoid.SeatPart\n\t                    if Seat then\n\t                        Part.CFrame = CFrame.new(Seat.Position - Vector3.new(0, 2.2 - (Up + Down), 0))\n\t                        Part.Parent = workspace\n\t                    else\n\t                        Part.Parent = nil\n\t                    end\n\t\n\t                    task.wait(0.05)\n\t                until not VehicleFly.Enabled\n\t            else\n\t                local InCar: boolean = false\n\t                local OldSeat\n\t                VehicleFly:Clean(RunService.PreSimulation:Connect(function(Delta: number)\n\t                    local Seat = Entity.isAlive and Entity.character.Humanoid.SeatPart\n\t                    local Root = Seat and Entity.character.RootPart\n\t\n\t                    if Root then\n\t                        if Seat ~= OldSeat then\n\t                            InCar = Seat:IsDescendantOf(workspace.CarContainer) and Seat:IsA(\"VehicleSeat\")\n\t                            if InCar then\n\t                                Welds = Seat.Parent.Parent.Wheels:QueryDescendants(\"Rotate\")\n\t                                for _, v: Rotate in Welds do\n\t                                    v.Enabled = false\n\t                                end\n\t                            end\n\t\n\t                            OldSeat = Seat\n\t                        end\n\t\n\t                        if InCar then\n\t                            Root.AssemblyLinearVelocity = Vector3.new(0, 2.25, 0)\n\t                            Root.CFrame = CFrame.lookAlong(Root.Position, Camera.CFrame.LookVector) + (Entity.character.Humanoid.MoveDirection + Vector3.new(0, Up + Down, 0)) * Speed.Value * Delta\n\t                            Camera.CameraSubject = Entity.character.Humanoid\n\t                        end\n\t                    elseif OldSeat then\n\t                        for _, v: Rotate in Welds do\n\t                            v.Enabled = true\n\t                        end\n\t                        OldSeat = nil\n\t                    end\n\t                end))\n\t            end\n\t        else\n\t            for _, v: Rotate in Welds do\n\t                v.Enabled = true\n\t            end\n\t            table.clear(Welds)\n\t        end\n\t    end,\n\t    Tooltip = \"Allow you to fly with a vehicle\"\n\t})\n\tMode = VehicleFly:CreateDropdown({\n\t    Name = \"Mode\",\n\t    List = {\"CFrame\", \"Part\"},\n\t    Function = function(Val: string)\n\t        Speed.Object.Visible = Val == \"CFrame\"\n\t        if VehicleFly.Enabled then\n\t            VehicleFly:Toggle()\n\t            VehicleFly:Toggle()\n\t        end\n\t    end\n\t})\n\tSpeed = VehicleFly:CreateSlider({\n\t    Name = \"Speed\",\n\t    Min = 1,\n\t    Max = 100,\n\t    Default = 60,\n\t    Darker = true\n\t})\nend)\n\nRun(function()\n\tlocal VehicleSpeed\n\tlocal Speed\n\tlocal OldSeat\n\tlocal Seats = {}\n\t\n\tVehicleSpeed = vape.Categories.Blatant:CreateModule({\n\t    Name = \"VehicleSpeed\",\n\t    Function = function(Callback: boolean)\n\t        if Callback then\n\t            repeat\n\t                local Seat = Entity.isAlive and Entity.character.Humanoid.SeatPart\n\t                if Seat then\n\t                    if Seat ~= OldSeat then\n\t                        if Seat:IsDescendantOf(workspace.CarContainer) then\n\t                            Seats = Seat.Parent.Parent:QueryDescendants(\"VehicleSeat\")\n\t                        end\n\t\n\t                        OldSeat = Seat\n\t                    end\n\t\n\t                    for _, v: VehicleSeat in Seats do\n\t                        v.MaxSpeed = Speed.Value\n\t                        v.Torque = 4\n\t                    end\n\t                end\n\t\n\t                task.wait()\n\t            until not VehicleSpeed.Enabled\n\t        else\n\t            table.clear(Seats)\n\t        end\n\t    end,\n\t    Tooltip = \"Increase vehicle speed\"\n\t})\n\tSpeed = VehicleSpeed:CreateSlider({\n\t    Name = \"Speed\",\n\t    Min = 80,\n\t    Max = 200,\n\t    Default = 140\n\t})\nend)\n\nRun(function()\n\tlocal VehicleWallbang\n\tlocal Modified: {[BasePart]: boolean} = {}\n\t\n\tlocal function Modify(Part: Instance)\n\t    if Part:IsA(\"BasePart\") then\n\t        if not Modified[Part] then\n\t            Modified[Part] = Part.CanQuery\n\t        end\n\t\n\t        Part.CanQuery = false\n\t    end\n\tend\n\t\n\tVehicleWallbang = vape.Categories.Blatant:CreateModule({\n\t    Name = \"VehicleWallbang\",\n\t    Function = function(Callback: boolean)\n\t        if Callback then\n\t            VehicleWallbang:Clean(workspace.CarContainer.DescendantAdded:Connect(Modify))\n\t            for _, Part: BasePart in workspace.CarContainer:QueryDescendants(\"BasePart\") do\n\t                Modify(Part)\n\t            end\n\t        else\n\t            for Part: BasePart, v: boolean in Modified do\n\t                Part.CanQuery = v\n\t            end\n\t            table.clear(Modified)\n\t        end\n\t    end,\n\t    Tooltip = \"Allow you to shoot through vehicles.\"\n\t})\nend)\n\nRun(function()\n\tlocal C4ESP\n\tlocal FillColor\n\tlocal OutlineColor\n\tlocal FillTransparency\n\tlocal OutlineTransparency\n\tlocal Reference = {}\n\tlocal Folder: Folder = Instance.new(\"Folder\")\n\tFolder.Parent = vape.gui\n\t\n\tlocal function Added(Object: Instance)\n\t    local Highlight: Highlight = Instance.new(\"Highlight\")\n\t    Highlight.Adornee = Object\n\t    Highlight.DepthMode = Enum.HighlightDepthMode.AlwaysOnTop\n\t    Highlight.FillColor = Color3.fromHSV(FillColor.Hue, FillColor.Sat, FillColor.Value)\n\t    Highlight.OutlineColor = Color3.fromHSV(OutlineColor.Hue, OutlineColor.Sat, OutlineColor.Value)\n\t    Highlight.FillTransparency = FillTransparency.Value\n\t    Highlight.OutlineTransparency = OutlineTransparency.Value\n\t    Highlight.Parent = Folder\n\t\n\t    Reference[Object] = Highlight\n\tend\n\t\n\tlocal function Removed(Object: Instance)\n\t    if Reference[Object] then\n\t        if vape.ThreadFix then\n\t            setthreadidentity(8)\n\t        end\n\t\n\t        Reference[Object]:Destroy()\n\t        Reference[Object] = nil\n\t    end\n\tend\n\t\n\tC4ESP = vape.Categories.Render:CreateModule({\n\t    Name = \"C4ESP\",\n\t    Function = function(Callback: boolean)\n\t        if Callback then\n\t            C4ESP:Clean(CollectionService:GetInstanceAddedSignal(\"C4\"):Connect(Added))\n\t            C4ESP:Clean(CollectionService:GetInstanceRemovedSignal(\"C4\"):Connect(Removed))\n\t\n\t            for _, Object: Instance in CollectionService:GetTagged(\"C4\") do\n\t                task.spawn(Added, Object)\n\t            end\n\t        else\n\t            for _, v: Highlight in Reference do\n\t                v:Destroy()\n\t            end\n\t            table.clear(Reference)\n\t        end\n\t    end,\n\t    Tooltip = \"Display all C4's placed\"\n\t})\n\tFillColor = C4ESP:CreateColorSlider({\n\t    Name = \"Color\",\n\t    Function = function(Hue: number, Sat: number, Val: number)\n\t        for _, v: Highlight in Reference do\n\t            v.FillColor = Color3.fromHSV(Hue, Sat, Val)\n\t        end\n\t    end\n\t})\n\tOutlineColor = C4ESP:CreateColorSlider({\n\t    Name = \"Outline Color\",\n\t    DefaultSat = 0,\n\t    Function = function(Hue: number, Sat: number, Val: number)\n\t        for _, v: Highlight in Reference do\n\t            v.OutlineColor = Color3.fromHSV(Hue, Sat, Val)\n\t        end\n\t    end\n\t})\n\tFillTransparency = C4ESP:CreateSlider({\n\t    Name = \"Transparency\",\n\t    Min = 0,\n\t    Max = 1,\n\t    Default = 0.5,\n\t    Function = function(Val: number)\n\t        for _, v: Highlight in Reference do\n\t            v.FillTransparency = Val\n\t        end\n\t    end,\n\t    Decimal = 10\n\t})\n\tOutlineTransparency = C4ESP:CreateSlider({\n\t    Name = \"Outline Transparency\",\n\t    Min = 0,\n\t    Max = 1,\n\t    Default = 0.5,\n\t    Function = function(Val: number)\n\t        for _, v: Highlight in Reference do\n\t            v.OutlineTransparency = Val\n\t        end\n\t    end,\n\t    Decimal = 10\n\t})\nend)\n\nRun(function()\n\tlocal CameraPhase\n\tlocal Old\n\t\n\tCameraPhase = vape.Categories.Render:CreateModule({\n\t    Name = \"CameraPhase\",\n\t    Function = function(Callback: boolean)\n\t        if Callback then\n\t            local Popper = require(LocalPlayer.PlayerScripts.PlayerModule.CameraModule.ZoomController.Popper)\n\t            Old = debug.getupvalue(debug.getupvalue(Popper, 3), 7)\n\t            debug.setconstant(Old, 16, 0)\n\t        else\n\t            if Old then\n\t                debug.setconstant(Old, 16, 0.25)\n\t                Old = nil\n\t            end\n\t        end\n\t    end,\n\t    Tooltip = \"Allow the camera to phase through walls.\"\n\t})\nend)\n\nRun(function()\n\tlocal KillNotifications\n\t\n\tKillNotifications = vape.Categories.Render:CreateModule({\n\t    Name = \"KillNotifications\",\n\t    Function = function(Callback: boolean)\n\t        if Callback then\n\t            KillNotifications:Clean(VapeEvents.PlayerKill.Event:Connect(function(Killer: string, Victim: string)\n\t                if Victim == LocalPlayer.Name and Killer ~= LocalPlayer.Name then\n\t                    SendNotification(\"KillNotifications\", `{Killer} killed you!`, 5)\n\t                end\n\t            end))\n\t        end\n\t    end,\n\t    Tooltip = \"Sends a notification of who killed you.\"\n\t})\nend)\n\nRun(function()\n\tlocal AutoDetonate\n\tlocal SafeCheck\n\tlocal LocalC4\n\tlocal Ticks: number = 0\n\tlocal RayParams: RaycastParams = RaycastParams.new()\n\tRayParams.CollisionGroup = \"ClientBullet\"\n\tRayParams.FilterType = Enum.RaycastFilterType.Exclude\n\t\n\tAutoDetonate = vape.Categories.Utility:CreateModule({\n\t    Name = \"AutoDetonate\",\n\t    Function = function(Callback: boolean)\n\t        if Callback then\n\t            AutoDetonate:Clean(CollectionService:GetInstanceAddedSignal(\"C4\"):Connect(function(Object: Instance)\n\t                if Object:GetAttribute(\"UserId\") == LocalPlayer.UserId then\n\t                    LocalC4 = Object\n\t                end\n\t            end))\n\t\n\t            for _, Object: Instance in CollectionService:GetTagged(\"C4\") do\n\t                if Object:GetAttribute(\"UserId\") == LocalPlayer.UserId then\n\t                    LocalC4 = Object\n\t                end\n\t            end\n\t\n\t            repeat\n\t                local Backpack = LocalPlayer:FindFirstChildWhichIsA(\"Backpack\")\n\t\n\t                if Backpack and LocalC4 then\n\t                    local Tool = Backpack:FindFirstChild(\"C4 Explosive\")\n\t\n\t                    if Tool then\n\t                        local Ent = Entity.EntityPosition({\n\t                            Players = true,\n\t                            Part = \"RootPart\",\n\t                            Range = 25,\n\t                            Origin = LocalC4.Position\n\t                        })\n\t\n\t                        if Ent then\n\t                            RayParams.FilterDescendantsInstances = {Ent.Character, LocalPlayer.Character, LocalC4}\n\t\n\t                            local RootOffset: Vector3 = (Entity.character.RootPart.Position - LocalC4.Position)\n\t                            local Obstruction = workspace:Raycast(LocalC4.Position, (Ent.RootPart.Position - LocalC4.Position), RayParams)\n\t                            if SafeCheck.Enabled and not Obstruction then\n\t                                Obstruction = not (workspace:Raycast(LocalC4.Position, RootOffset, RayParams) or RootOffset.Magnitude > 40)\n\t                            end\n\t\n\t                            if not Obstruction then\n\t                                Ticks += 1\n\t                                if Ticks > 3 then\n\t                                    local Equipped = LocalPlayer.Character:FindFirstChildWhichIsA(\"Tool\")\n\t                                    if Equipped then\n\t                                        Equipped.Parent = Backpack\n\t                                    end\n\t\n\t                                    Tool.Parent = LocalPlayer.Character\n\t                                    task.spawn(function()\n\t                                        ReplicatedStorage.Remotes.C4.ActivateC4:InvokeServer()\n\t                                    end)\n\t                                    Tool.Parent = Backpack\n\t\n\t                                    if Equipped then\n\t                                        Equipped.Parent = LocalPlayer.Character\n\t                                    end\n\t                                end\n\t\n\t                                task.wait(0.05)\n\t                                continue\n\t                            end\n\t                        end\n\t                    end\n\t                end\n\t\n\t                Ticks = 0\n\t                task.wait(0.05)\n\t            until not AutoDetonate.Enabled\n\t        end\n\t    end,\n\t    Tooltip = \"Automatically detonate when enemies are nearby.\"\n\t})\n\tSafeCheck = AutoDetonate:CreateToggle({\n\t    Name = \"Safety Check\"\n\t})\nend)\n\nRun(function()\n\tlocal AutoReload\n\tlocal HotSwap\n\tlocal Thread, OldPlaySound\n\tlocal Priority: {[string]: number} = {\n\t    M4A1 = 1,\n\t    [\"AK-47\"] = 1,\n\t    MP5 = 1,\n\t    FAL = 1,\n\t    [\"Remington 870\"] = 2,\n\t    M9 = 3,\n\t    Revolver = 4\n\t}\n\t\n\tlocal function GetWeapon()\n\t    local Weapons: {Instance} = {}\n\t    local Backpack = LocalPlayer:FindFirstChildWhichIsA(\"Backpack\")\n\t    if Backpack then\n\t        for _, Tool: Instance in Backpack:GetChildren() do\n\t            if Tool:GetAttribute(\"FireRate\") and (Tool:GetAttribute(\"Local_ReloadSession\") or 0) <= 0 and Tool.Name ~= \"Taser\" and Tool.Name ~= \"M700\" then\n\t                table.insert(Weapons, Tool)\n\t            end\n\t        end\n\t\n\t        table.sort(Weapons, function(A: Instance, B: Instance)\n\t            return (Priority[A.Name] or 100) < (Priority[B.Name] or 100)\n\t        end)\n\t\n\t        return Weapons[1]\n\t    end\n\tend\n\t\n\tAutoReload = vape.Categories.Utility:CreateModule({\n\t    Name = \"AutoReload\",\n\t    Function = function(Callback: boolean)\n\t        if Callback then\n\t            TracerHook:Add(\"AutoReload\", function(...)\n\t                if Thread then\n\t                    return\n\t                end\n\t\n\t                Thread = task.defer(function()\n\t                    Thread = nil\n\t\n\t                    local Tool = debug.getupvalue(PrisonLife.Shoot, 1)\n\t                    if Tool and Tool:GetAttribute(\"Local_CurrentAmmo\") <= 0 then\n\t                        task.spawn(PrisonLife.Reload)\n\t\n\t                        if HotSwap.Enabled then\n\t                            local Weapon = GetWeapon()\n\t\n\t                            if Weapon then\n\t                                Tool.Parent = LocalPlayer.Backpack\n\t                                Weapon.Parent = LocalPlayer.Character\n\t                            end\n\t                        end\n\t                    end\n\t                end)\n\t            end)\n\t\n\t            OldPlaySound = hookfunction(PrisonLife.PlaySound, function(SoundName: string)\n\t                local SoundObject = debug.getupvalue(PrisonLife.Shoot, 1)\n\t                SoundObject = SoundObject and SoundObject:FindFirstChild(\"Handle\")\n\t                SoundObject = SoundObject and SoundObject:FindFirstChild(SoundName)\n\t\n\t                if SoundObject then\n\t                    local Clone = SoundObject:Clone()\n\t                    Clone.Parent = SoundObject.Parent\n\t                    Clone:Play()\n\t                    task.delay(5, Clone.Destroy, Clone)\n\t                end\n\t            end)\n\t        else\n\t            TracerHook:Remove(\"AutoReload\")\n\t            if OldPlaySound then\n\t                if restorefunction then\n\t                    restorefunction(PrisonLife.PlaySound)\n\t                else\n\t                    hookfunction(PrisonLife.PlaySound, OldPlaySound)\n\t                end\n\t                OldPlaySound = nil\n\t            end\n\t        end\n\t    end,\n\t    Tooltip = \"Automatically reload after reaching 0 bullets\"\n\t})\n\tHotSwap = AutoReload:CreateToggle({\n\t    Name = \"Auto Swap\",\n\t    Tooltip = \"Automatically swap weapons when reloading\"\n\t})\nend)\n\nRun(function()\n\tlocal AutoToxic\n\tlocal Toggles, Lists, Cloned, Presets = {}, {}, {}, {}\n\t\n\tlocal function SendMessage(Name: string, Target: string?, Default: string)\n\t    local Message = Default\n\t    if #Lists[Name].ListEnabled > 0 then\n\t        if #Cloned[Name] <= 0 then\n\t            Cloned[Name] = table.clone(Lists[Name].ListEnabled)\n\t        end\n\t\n\t        local Entry: number = Random.new():NextInteger(1, #Cloned[Name])\n\t        Message = Cloned[Name][Entry]\n\t        table.remove(Cloned[Name], Entry)\n\t    end\n\t\n\t    if not Message then\n\t        return\n\t    end\n\t\n\t    Message = Message and Message:gsub(\"<obj>\", Target or \"\") or \"\"\n\t    if TextChatService.ChatVersion == Enum.ChatVersion.TextChatService then\n\t        if TextChatService:CanUserChatAsync(LocalPlayer.UserId) then\n\t            TextChatService.ChatInputBarConfiguration.TargetTextChannel:SendAsync(Message)\n\t        else\n\t            TextChatService.ChatInputBarConfiguration.TargetTextChannel:SendPresetAsync(Presets[Message] or Presets[\"So close\"])\n\t        end\n\t    else\n\t        ReplicatedStorage.DefaultChatSystemChatEvents.SayMessageRequest:FireServer(Message, \"All\")\n\t    end\n\tend\n\t\n\tAutoToxic = vape.Categories.Utility:CreateModule({\n\t    Name = \"AutoToxic\",\n\t    Function = function(Callback: boolean)\n\t        if Callback then\n\t            AutoToxic:Clean(VapeEvents.CheaterKicked.Event:Connect(function(PlayerName: string)\n\t                SendMessage(\"Kicked\", PlayerName, \"skill issue cheat | <obj>\")\n\t            end))\n\t        end\n\t    end,\n\t    Tooltip = \"Says a message after a cheater gets kicked with CheatDetector enabled.\"\n\t})\n\tfor _, v: string in {\"Kicked\"} do\n\t    Cloned[v] = {}\n\t    Toggles[v] = AutoToxic:CreateToggle({\n\t        Name = `{v} `,\n\t        Function = function(Callback: boolean)\n\t            if Lists[v] then\n\t                Lists[v].Object.Visible = Callback\n\t            end\n\t        end,\n\t        Default = true\n\t    })\n\t    Lists[v] = AutoToxic:CreateTextList({\n\t        Name = v,\n\t        Darker = true,\n\t        Function = function()\n\t            table.clear(Cloned[v])\n\t        end\n\t    })\n\tend\n\t\n\tpcall(function()\n\t    for _, Group: any in TextChatService:GetPresetsAsync().categoryGroups do\n\t        for _, Category: any in Group.categories do\n\t            for _, Preset: any in Category.messages do\n\t                Presets[Preset.value] = Preset.presetId\n\t            end\n\t        end\n\t    end\n\tend)\nend)\n\nRun(function()\n\tlocal CheatDetector\n\tlocal AddTarget\n\tlocal Overlap: OverlapParams = OverlapParams.new()\n\tOverlap.CollisionGroup = \"Players\"\n\tOverlap.FilterDescendantsInstances = {workspace.CarContainer, workspace.Doors}\n\tOverlap.FilterType = Enum.RaycastFilterType.Exclude\n\tlocal CarOverlap: OverlapParams = OverlapParams.new()\n\tCarOverlap.FilterDescendantsInstances = {workspace.CarContainer}\n\tCarOverlap.FilterType = Enum.RaycastFilterType.Include\n\tCarOverlap.MaxParts = 1\n\t\n\tlocal WhitelistStates = {\n\t    [Enum.HumanoidStateType.Running] = true,\n\t    [Enum.HumanoidStateType.Jumping] = true,\n\t    [Enum.HumanoidStateType.Freefall] = true,\n\t    [Enum.HumanoidStateType.Landed] = true,\n\t    [Enum.HumanoidStateType.FallingDown] = true,\n\t    [Enum.HumanoidStateType.GettingUp] = true,\n\t    [Enum.HumanoidStateType.Climbing] = true,\n\t    [Enum.HumanoidStateType.Seated] = true,\n\t    [Enum.HumanoidStateType.Ragdoll] = true,\n\t    [Enum.HumanoidStateType.Dead] = true,\n\t    [Enum.HumanoidStateType.None] = true\n\t}\n\t\n\tCheatDetector = vape.Categories.Utility:CreateModule({\n\t    Name = \"CheatDetector\",\n\t    Function = function(Callback: boolean)\n\t        if Callback then\n\t            CheatDetector:Clean(VapeEvents.CheatFlagged.Event:Connect(function(Player: Player, FlagName: string)\n\t                SendNotification(\"CheatDetector\", `This player may be cheating! ({FlagName}): {Player.Name}`, 60, \"warning\")\n\t                if AddTarget.Enabled then\n\t                    TempTargets[Player.Name] = true\n\t                end\n\t\n\t                local Ent = Entity.getEntity(Player)\n\t                if Ent then\n\t                    Entity.Events.EntityUpdated:Fire(Ent)\n\t                    if AddTarget.Enabled then\n\t                        Ent.Target = true\n\t                    end\n\t                end\n\t            end))\n\t\n\t            repeat\n\t                for _, Ent: any in Entity.List do\n\t                    if Ent.Health > 0 and Ent.Player then\n\t                        if not CheckPoint(Ent.Head.Position, Overlap) then\n\t                            CheatFlags:Flag(Ent.Player, \"phase/noclip\", 20)\n\t                        end\n\t\n\t                        if not WhitelistStates[Ent.Humanoid:GetState()] then\n\t                            CheatFlags:Flag(Ent.Player, `invalid state {Ent.Humanoid:GetState().Name}`, 1)\n\t                        end\n\t\n\t                        local Velocity: Vector3 = Ent.RootPart.AssemblyLinearVelocity\n\t                        if not Ent.Humanoid.SeatPart then\n\t                            if (Velocity * Vector3.new(1, 0, 1)).Magnitude > 26 then\n\t                                if #workspace:GetPartBoundsInRadius(Ent.RootPart.Position, 30, CarOverlap) <= 0 then\n\t                                    CheatFlags:Flag(Ent.Player, \"speed\", 20)\n\t                                end\n\t                            end\n\t\n\t                            if Velocity.Y > 50 then\n\t                                CheatFlags:Flag(Ent.Player, \"highjump\", 20)\n\t                            end\n\t                        end\n\t                    end\n\t                end\n\t\n\t                task.wait(0.05)\n\t            until not CheatDetector.Enabled\n\t        else\n\t            CheatFlags:Clear()\n\t        end\n\t    end,\n\t    Tooltip = \"Sends alerts for any possible cheaters.\"\n\t})\n\tAddTarget = CheatDetector:CreateToggle({\n\t    Name = \"Temporary Target\",\n\t    Tooltip = \"Add temporary combat module priority for cheaters.\",\n\t    Default = true\n\t})\nend)\n\nRun(function()\n\tlocal Disabler\n\tlocal Old\n\t\n\tlocal function EntityAdded(Ent)\n\t    task.defer(function()\n\t        Old = getconnections(Ent.Head:GetPropertyChangedSignal(\"CanCollide\"))[1]\n\t        if Old then\n\t            Old:Disable()\n\t        end\n\t    end)\n\tend\n\t\n\tDisabler = vape.Categories.Utility:CreateModule({\n\t    Name = \"Disabler\",\n\t    Function = function(Callback: boolean)\n\t        if Callback then\n\t            Disabler:Clean(Entity.Events.LocalAdded:Connect(EntityAdded))\n\t            if Entity.isAlive then\n\t                task.spawn(EntityAdded, Entity.character)\n\t            end\n\t        else\n\t            if Old then\n\t                Old:Enable()\n\t                Old = nil\n\t            end\n\t        end\n\t    end,\n\t    Tooltip = \"Fixes phase with Character mode.\",\n\t    ExtraText = function()\n\t        return \"Phase\"\n\t    end\n\t})\nend)\n\nRun(function()\n\tlocal AutoArmor\n\tlocal Pickups: {Instance} = {}\n\t\n\tAutoArmor = vape.Categories.Inventory:CreateModule({\n\t    Name = \"AutoArmor\",\n\t    Function = function(Callback: boolean)\n\t        if Callback then\n\t            Pickups = workspace.Prison_ITEMS.clothes:GetChildren()\n\t\n\t            AutoArmor:Clean(workspace.Prison_ITEMS.clothes.ChildAdded:Connect(function(Object: Instance)\n\t                table.insert(Pickups, Object)\n\t            end))\n\t\n\t            AutoArmor:Clean(workspace.Prison_ITEMS.clothes.ChildRemoved:Connect(function(Object: Instance)\n\t                local Index: number? = table.find(Pickups, Object)\n\t                if Index then\n\t                    table.remove(Pickups, Index)\n\t                end\n\t            end))\n\t\n\t            repeat\n\t                if Entity.isAlive and Entity.character.Humanoid.MaxHealth <= 100 then\n\t                    local LocalPosition: Vector3 = Entity.character.RootPart.Position\n\t\n\t                    for _, v: Instance in Pickups do\n\t                        if (v:GetPivot().Position - LocalPosition).Magnitude < 10 and Gamepasses[v:GetAttribute(\"RequiredGamepass\")] and AutoArmor.Enabled then\n\t                            if v.Name == \"Light Vest\" and Gamepasses[LocalPlayer.Team == Teams.Criminals and \"Mafia\" or \"Riot Police\"] then\n\t                                continue\n\t                            end\n\t\n\t                            ReplicatedStorage.Remotes.InteractWithItem:InvokeServer(v:FindFirstChildWhichIsA(\"BasePart\"))\n\t                        end\n\t                    end\n\t                end\n\t\n\t                task.wait(0.05)\n\t            until not AutoArmor.Enabled\n\t        else\n\t            table.clear(Pickups)\n\t        end\n\t    end,\n\t    Tooltip = \"Automatically equip armor from the wall.\"\n\t})\nend)\n\nRun(function()\n\tlocal AutoHeal\n\tlocal HealItems: {[string]: boolean} = {\n\t    Breakfast = true,\n\t    Lunch = true,\n\t    Dinner = true\n\t}\n\t\n\tAutoHeal = vape.Categories.Inventory:CreateModule({\n\t    Name = \"AutoHeal\",\n\t    Function = function(Callback: boolean)\n\t        if Callback then\n\t            repeat\n\t                local Ent = Entity.isAlive and Entity.character\n\t                if Ent and Ent.Humanoid.Health <= 85 then\n\t                    local HealTool\n\t                    local Backpack = LocalPlayer:FindFirstChildWhichIsA(\"Backpack\")\n\t                    if Backpack then\n\t                        for _, v: Instance in Backpack:GetChildren() do\n\t                            if HealItems[v.Name] then\n\t                                HealTool = v\n\t                            end\n\t                        end\n\t\n\t                        if HealTool and (os.clock() - (HealTool:GetAttribute(\"Client_LastConsumedAt\") or 0)) >= 3 then\n\t                            local Equipped = Ent.Character:FindFirstChildWhichIsA(\"Tool\")\n\t                            if Equipped then\n\t                                Equipped.Parent = Backpack\n\t                            end\n\t\n\t                            HealTool.Parent = Ent.Character\n\t                            HealTool:SetAttribute(\"Quantity\", HealTool:GetAttribute(\"Quantity\") - 1)\n\t                            HealTool:SetAttribute(\"Client_LastConsumedAt\", os.clock())\n\t                            SendNotification(\"AutoHeal\", `Quantity: {HealTool:GetAttribute(\"Quantity\")}`, 3)\n\t                            ReplicatedStorage.Remotes.EatFood:FireServer()\n\t                            HealTool.Parent = Backpack\n\t\n\t                            if Equipped then\n\t                                Equipped.Parent = Ent.Character\n\t                            end\n\t                        end\n\t                    end\n\t                end\n\t\n\t                task.wait(0.05)\n\t            until not AutoHeal.Enabled\n\t        end\n\t    end,\n\t    Tooltip = \"Automatically heal damage with consumables.\"\n\t})\nend)\n\nRun(function()\n\tlocal AutoHotbar\n\tlocal SortList: {[string]: number} = {}\n\t\n\tlocal function DoSorting()\n\t    table.sort(PrisonLife.SwitchTable, function(A, B)\n\t        return (SortList[A.Tool.name] or 999 + A.Slot) < (SortList[B.Tool.name] or 999 + B.Slot)\n\t    end)\n\t\n\t    task.spawn(PrisonLife.SwitchUpdate)\n\tend\n\t\n\tlocal function EntityAdded()\n\t    local Backpack = LocalPlayer:FindFirstChildWhichIsA(\"Backpack\")\n\t    if Backpack then\n\t        AutoHotbar:Clean(Backpack.ChildAdded:Connect(function(Tool: Instance)\n\t            if SortList[Tool.Name] then\n\t                task.defer(DoSorting)\n\t            end\n\t        end))\n\t    end\n\t\n\t    DoSorting()\n\tend\n\t\n\tAutoHotbar = vape.Categories.Inventory:CreateModule({\n\t    Name = \"AutoHotbar\",\n\t    Function = function(Callback: boolean)\n\t        if Callback then\n\t            AutoHotbar:Clean(Entity.Events.LocalAdded:Connect(EntityAdded))\n\t            if Entity.isAlive then\n\t                task.spawn(EntityAdded)\n\t            end\n\t        end\n\t    end,\n\t    Tooltip = \"Automatically sort hotbar entries\"\n\t})\n\tAutoHotbar:CreateTextList({\n\t    Name = \"Sort Order\",\n\t    Default = {\"1/AK-47\", \"1/MP5\", \"1/M4A1\", \"2/Remington 870\", \"2/M700\", \"3/M9\", \"3/Revolver\", \"4/Taser\"},\n\t    Function = function(List: {string})\n\t        table.clear(SortList)\n\t        for _, Entry: string in List do\n\t            local Parts: {string} = Entry:split(\"/\")\n\t            local Priority: number? = tonumber(Parts[1])\n\t            SortList[Parts[2]] = Priority or 999\n\t        end\n\t    end\n\t})\nend)\n\nRun(function()\n\tlocal AutoPickup\n\tlocal Lists = {}\n\tlocal Items = {}\n\tlocal SortedPickups = {Guard = {}, Prisoner = {}, Criminal = {}}\n\t\n\tlocal function AddPickup(Object: Instance)\n\t    if Object:IsA(\"Model\") and Object.Name ~= \"Model\" and Object:GetAttribute(\"ToolName\") then\n\t        table.insert(Items, {Object, Object.Name == \"TouchGiver\"})\n\t    end\n\tend\n\t\n\tAutoPickup = vape.Categories.Inventory:CreateModule({\n\t    Name = \"AutoPickup\",\n\t    Function = function(Callback: boolean)\n\t        if Callback then\n\t            for _, Object: Instance in workspace:GetChildren() do\n\t                task.spawn(AddPickup, Object)\n\t            end\n\t\n\t            for _, Object: Instance in workspace:QueryDescendants(\"Model > .TouchGiver\") do\n\t                task.spawn(AddPickup, Object)\n\t            end\n\t\n\t            AutoPickup:Clean(workspace.ChildAdded:Connect(AddPickup))\n\t            AutoPickup:Clean(workspace.ChildRemoved:Connect(function(Object: Instance)\n\t                for i: number, Entry: any in Items do\n\t                    if Entry[1] == Object then\n\t                        table.remove(Items, i)\n\t                        break\n\t                    end\n\t                end\n\t            end))\n\t\n\t            repeat\n\t                if Entity.isAlive then\n\t                    local LocalPosition: Vector3 = Entity.character.RootPart.Position\n\t                    local Backpack = LocalPlayer:FindFirstChildWhichIsA(\"Backpack\")\n\t\n\t                    if Backpack then\n\t                        for _, v: any in Items do\n\t                            if v[1].PrimaryPart and (v[1].PrimaryPart.Position - LocalPosition).Magnitude < 12 then\n\t                                local ToolName = v[1]:GetAttribute(\"ToolName\")\n\t                                if v[2] then\n\t                                    local Found: boolean = false\n\t                                    for _, Entry: string in SortedPickups[LocalPlayer.Team == Teams.Guards and \"Guard\" or (LocalPlayer.Team == Teams.Criminals and \"Criminal\" or \"Prisoner\")] do\n\t                                        if not Backpack:FindFirstChild(Entry) then\n\t                                            Found = ToolName ~= Entry\n\t                                            break\n\t                                        end\n\t                                    end\n\t\n\t                                    if Found then\n\t                                        continue\n\t                                    end\n\t                                end\n\t\n\t                                if not Backpack:FindFirstChild(ToolName) then\n\t                                    ReplicatedStorage.Remotes.GiverPressed:FireServer(v[1])\n\t                                end\n\t                            end\n\t                        end\n\t                    end\n\t                end\n\t\n\t                task.wait(0.05)\n\t            until not AutoPickup.Enabled\n\t        else\n\t            table.clear(Items)\n\t        end\n\t    end,\n\t    Tooltip = \"Automatically grab item pickups\"\n\t})\n\t\n\tfor _, v: string in {\"Prisoner\", \"Guard\", \"Criminal\"} do\n\t    AutoPickup:CreateTextList({\n\t        Name = `{v} Pickups`,\n\t        Default = {v == \"Criminal\" and \"1/AK-47\" or \"1/MP5\", \"2/Remington 870\"},\n\t        Placeholder = \"priority/item\",\n\t        Function = function(List: {string})\n\t            table.clear(SortedPickups[v])\n\t            for _, Entry: string in List do\n\t                local Parts: {string} = Entry:split(\"/\")\n\t                local Priority: number? = tonumber(Parts[1])\n\t                SortedPickups[v][Priority or 999] = Parts[2]\n\t            end\n\t        end\n\t    })\n\tend\nend)\n\nRun(function()\n\tlocal BulletTracers\n\tlocal Material\n\tlocal Color\n\tlocal Lifetime\n\tlocal Fade\n\tlocal DrawingToggle\n\tlocal DrawingObjects = {}\n\t\n\tBulletTracers = vape.Legit:CreateModule({\n\t    Name = \"BulletTracers\",\n\t    Category = \"Game\",\n\t    Icon = GetVapeAsset(`{vape.Directory}/assets/new/legit_bullettracers.png`),\n\t    Function = function(Callback: boolean)\n\t        if Callback then\n\t            TracerHook:Add(\"BulletTracers\", function(...)\n\t                local Origin, Direction = ...\n\t                if vtool then\n\t                    Origin = vtool.Muzzle.Position\n\t                end\n\t\n\t                local Velocity: Vector3 = CFrame.lookAt(Origin, Direction).LookVector * 1000\n\t                if DrawingToggle.Enabled then\n\t                    local Line = Drawing.new(\"Line\")\n\t                    Line.Thickness = 2\n\t                    Line.Color = Color3.fromHSV(Color.Hue, Color.Sat, Color.Value)\n\t                    DrawingObjects[Line] = {Origin, Origin + Velocity, os.clock()}\n\t                    task.delay(Lifetime.Value, function()\n\t                        DrawingObjects[Line] = nil\n\t                        Line.Visible = false\n\t                        Line:Remove()\n\t                    end)\n\t                else\n\t                    local Tracer: Part = Instance.new(\"Part\")\n\t                    Tracer.Size = Vector3.new(0.1, 0.1, Velocity.Magnitude)\n\t                    Tracer.CFrame = CFrame.lookAt(Origin + (Velocity / 2), Origin + Velocity)\n\t                    Tracer.CanCollide = false\n\t                    Tracer.CanQuery = false\n\t                    Tracer.Anchored = true\n\t                    Tracer.Material = Enum.Material[Material.Value]\n\t                    Tracer.Color = Color3.fromHSV(Color.Hue, Color.Sat, Color.Value)\n\t                    Tracer.Transparency = 1 - Color.Opacity\n\t                    Tracer.Parent = workspace\n\t                    if Fade.Enabled then\n\t                        local Tween: Tween = TweenService:Create(Tracer, TweenInfo.new(Lifetime.Value), {\n\t                            Transparency = 1\n\t                        })\n\t                        Tween.Completed:Connect(function()\n\t                            Tween:Destroy()\n\t                        end)\n\t                        Tween:Play()\n\t                    end\n\t\n\t                    task.delay(Lifetime.Value, Tracer.Destroy, Tracer)\n\t                end\n\t\n\t                return true\n\t            end, 1)\n\t\n\t            if DrawingToggle.Enabled then\n\t                BulletTracers:Clean(RunService.RenderStepped:Connect(function()\n\t                    for Line: any, Data: any in DrawingObjects do\n\t                        local FromPoint, FromVisible = Camera:WorldToViewportPoint(Data[1])\n\t                        local ToPoint, ToVisible = Camera:WorldToViewportPoint(Data[2])\n\t                        if FromVisible and ToVisible then\n\t                            Line.Visible = true\n\t                            Line.From = Vector2.new(FromPoint.X, FromPoint.Y)\n\t                            Line.To = Vector2.new(ToPoint.X, ToPoint.Y)\n\t                            if Fade.Enabled then\n\t                                Line.Transparency = Color.Opacity * (1 - math.clamp((os.clock() - Data[3]) / Lifetime.Value, 0, 1))\n\t                            end\n\t                        else\n\t                            Line.Visible = false\n\t                        end\n\t                    end\n\t                end))\n\t            end\n\t        else\n\t            TracerHook:Remove(\"BulletTracers\")\n\t        end\n\t    end,\n\t    Tooltip = \"Allow you to customize bullet tracers.\"\n\t})\n\tlocal Materials: {string} = {\"SmoothPlastic\"}\n\tfor _, v: EnumItem in Enum.Material:GetEnumItems() do\n\t    if v.Name ~= \"SmoothPlastic\" then\n\t        table.insert(Materials, v.Name)\n\t    end\n\tend\n\tMaterial = BulletTracers:CreateDropdown({\n\t    Name = \"Material\",\n\t    List = Materials\n\t})\n\tColor = BulletTracers:CreateColorSlider({\n\t    Name = \"Tracer Color\",\n\t    DefaultOpacity = 0.5\n\t})\n\tLifetime = BulletTracers:CreateSlider({\n\t    Name = \"Lifetime\",\n\t    Min = 0,\n\t    Max = 0.5,\n\t    Default = 0.2,\n\t    Decimal = 10\n\t})\n\tFade = BulletTracers:CreateToggle({\n\t    Name = \"Fade\",\n\t    Default = true\n\t})\n\tDrawingToggle = BulletTracers:CreateToggle({\n\t    Name = \"Drawing\",\n\t    Function = function()\n\t        if BulletTracers.Enabled then\n\t            BulletTracers:Toggle()\n\t            BulletTracers:Toggle()\n\t        end\n\t    end\n\t})\nend)\n\nRun(function()\n\tlocal Crosshair\n\tlocal Image\n\tlocal Old\n\t\n\tCrosshair = vape.Legit:CreateModule({\n\t    Name = \"Crosshair\",\n\t    Category = \"Game\",\n\t    Icon = GetVapeAsset(`{vape.Directory}/assets/new/legit_crosshair.png`),\n\t    Function = function(Callback: boolean)\n\t        if Callback then\n\t            debug.setconstant(OldEquip or PrisonLife.Equip, 30, Image.Value:find(\"rbxasset\") and Image.Value or isfile(Image.Value) and getcustomasset(Image.Value) or \"\")\n\t        else\n\t            debug.setconstant(OldEquip or PrisonLife.Equip, 30, \"rbxassetid://98794608762931\")\n\t        end\n\t    end,\n\t    Tooltip = \"Change the crosshair icon\"\n\t})\n\tImage = Crosshair:CreateTextBox({\n\t    Name = \"Image\",\n\t    Placeholder = \"assetid\",\n\t    Function = function()\n\t        if Crosshair.Enabled then\n\t            debug.setconstant(OldEquip or PrisonLife.Equip, 30, Image.Value:find(\"rbxasset\") and Image.Value or isfile(Image.Value) and getcustomasset(Image.Value) or \"\")\n\t        end\n\t    end\n\t})\nend)\n\nRun(function()\n\tlocal DamageIndicator\n\tlocal FontOption\n\tlocal ColorV\n\tlocal Size\n\tlocal TargetEntity, LastEntity\n\tlocal TargetHealth, TargetTimer = 0, 0\n\tlocal Indicator, IndicatorPart, IndicatorThread\n\t\n\tlocal function RenderStepForLoop(StartValue: number, EndValue: number, Increment: number, Callback)\n\t    while true do\n\t        if EndValue >= StartValue then\n\t            if Callback(StartValue) then\n\t                return\n\t            else\n\t                local StartTick: number = tick()\n\t                RunService.RenderStepped:Wait()\n\t                StartValue = StartValue + Increment * (tick() - StartTick) * 60\n\t            end\n\t        else\n\t            Callback(EndValue)\n\t            return\n\t        end\n\t    end\n\tend\n\t\n\tlocal function CreateIndicator(Damage: number, Position: Vector3)\n\t    if IndicatorThread then\n\t        task.cancel(IndicatorThread)\n\t        Indicator.Text = math.ceil(tonumber(Indicator.Text) + Damage)\n\t        IndicatorPart.Position = Position\n\t    else\n\t        IndicatorPart = Instance.new(\"Part\")\n\t        IndicatorPart.Size = Vector3.zero\n\t        IndicatorPart.Position = Position\n\t        IndicatorPart.CanCollide = false\n\t        IndicatorPart.CanQuery = false\n\t        IndicatorPart.Anchored = true\n\t        IndicatorPart.Parent = workspace\n\t        local Billboard: BillboardGui = Instance.new(\"BillboardGui\")\n\t        Billboard.Adornee = IndicatorPart\n\t        Billboard.Size = UDim2.new(15, 250, 15, 250)\n\t        Billboard.AlwaysOnTop = true\n\t        Billboard.Parent = IndicatorPart\n\t        Indicator = Instance.new(\"TextLabel\")\n\t        Indicator.BackgroundTransparency = 1\n\t        Indicator.TextStrokeTransparency = 0\n\t        Indicator.Size = UDim2.fromScale(1, 0.075)\n\t        Indicator.Position = UDim2.fromScale(0.5, 0.5)\n\t        Indicator.AnchorPoint = Vector2.new(0.5, 0.5)\n\t        Indicator.Text = math.ceil(Damage)\n\t        Indicator.TextColor3 = Color3.fromHSV(ColorV.Hue, ColorV.Sat, ColorV.Value)\n\t        Indicator.TextScaled = true\n\t        Indicator.Font = Enum.Font[FontOption.Value]\n\t        Indicator.Parent = Billboard\n\t    end\n\t\n\t    if IndicatorThread then\n\t        task.cancel(IndicatorThread)\n\t        IndicatorThread = nil\n\t    end\n\t\n\t    IndicatorThread = task.spawn(function()\n\t        local Sign: number = math.sign(math.random() - 0.5)\n\t        RenderStepForLoop(0, 100, 3, function(Value: number)\n\t            local Percent: number = Value / 100\n\t            local SineValue: number = TweenService:GetValue(Percent, Enum.EasingStyle.Sine, Enum.EasingDirection.In)\n\t            local BackValue: number = TweenService:GetValue(Percent, Enum.EasingStyle.Back, Enum.EasingDirection.In)\n\t            local Scale: number = 1 - 0.5 * BackValue\n\t            Indicator.Position = UDim2.new(0.5 + 0.125 * SineValue * Sign, 0, 0.5 + 0.125 * BackValue, 0)\n\t            Indicator.Size = UDim2.new(1 * Scale, 0, 0.075 * Scale * (v197 and 1 or 0.75), 0)\n\t            Indicator.Rotation = Percent ^ 4 * 260 * Sign\n\t        end)\n\t\n\t        IndicatorPart:Destroy()\n\t        IndicatorPart = nil\n\t        IndicatorThread = nil\n\t    end)\n\tend\n\t\n\tDamageIndicator = vape.Legit:CreateModule({\n\t    Name = \"DamageIndicator\",\n\t    Category = \"Game\",\n\t    Icon = GetVapeAsset(`{vape.Directory}/assets/new/legit_damageindicator.png`),\n\t    Function = function(Callback: boolean)\n\t        if Callback then\n\t            TracerHook:Add(\"DamageIndicator\", function(...)\n\t                local Part = debug.getstack(4, 17)\n\t                if typeof(Part) == \"Instance\" then\n\t                    for _, v: any in Entity.List do\n\t                        if Part:IsDescendantOf(v.Character) and Entity.isVulnerable(v, true) then\n\t                            if TargetTimer <= os.clock() or v ~= TargetEntity then\n\t                                TargetHealth = v.Health\n\t                            end\n\t\n\t                            TargetEntity = v\n\t                            TargetTimer = os.clock() + 0.5\n\t                            break\n\t                        end\n\t                    end\n\t                end\n\t            end)\n\t\n\t            DamageIndicator:Clean(Entity.Events.EntityUpdated:Connect(function(Ent)\n\t                if Ent == TargetEntity and TargetTimer > os.clock() then\n\t                    if Ent ~= LastEntity then\n\t                        if Indicator then\n\t                            Indicator.Text = \"0\"\n\t                        end\n\t\n\t                        LastEntity = Ent\n\t                    end\n\t\n\t                    if TargetHealth > Ent.Health then\n\t                        CreateIndicator(TargetHealth - Ent.Health, Ent.Head.Position + Vector3.new(0, 2, 0))\n\t                        TargetHealth = Ent.Health\n\t                    end\n\t                end\n\t            end))\n\t        else\n\t            TracerHook:Remove(\"DamageIndicator\")\n\t        end\n\t    end,\n\t    Tooltip = \"Add custom damage indicators for gun damage.\"\n\t})\n\tlocal FontItems: {string} = {\"GothamBlack\"}\n\tfor _, v: EnumItem in Enum.Font:GetEnumItems() do\n\t    if v.Name ~= \"GothamBlack\" then\n\t        table.insert(FontItems, v.Name)\n\t    end\n\tend\n\tFontOption = DamageIndicator:CreateDropdown({\n\t    Name = \"Font\",\n\t    List = FontItems,\n\t    Function = function(Val: string)\n\t        if Indicator then\n\t            Indicator.Font = Enum.Font[Val]\n\t        end\n\t    end\n\t})\n\tColorV = DamageIndicator:CreateColorSlider({\n\t    Name = \"Color\",\n\t    DefaultHue = 0,\n\t    Function = function(Hue: number, Sat: number, Val: number)\n\t        if Indicator then\n\t            Indicator.TextColor3 = Color3.fromHSV(Hue, Sat, Val)\n\t        end\n\t    end\n\t})\nend)\n\nRun(function()\n\tlocal HitSound\n\tlocal Value\n\tlocal Volume\n\tlocal PitchShift\n\tlocal Old, Sounds = nil, {}\n\t\n\tHitSound = vape.Legit:CreateModule({\n\t    Name = \"HitSound\",\n\t    Category = \"Game\",\n\t    Icon = GetVapeAsset(`{vape.Directory}/assets/new/legit_hitsound.png`),\n\t    Function = function(Callback: boolean)\n\t        if Callback then\n\t            local Played\n\t            TracerHook:Add(\"HitSound\", function(...)\n\t                local Part = debug.getstack(4, 17)\n\t                if typeof(Part) == \"Instance\" then\n\t                    for _, v: any in Entity.List do\n\t                        if Part:IsDescendantOf(v.Character) and Entity.isVulnerable(v, true) then\n\t                            if #Sounds > 0 and not Played then\n\t                                local Sound: Sound = Instance.new(\"Sound\")\n\t                                Sound.SoundId = Sounds[math.random(1, #Sounds)]\n\t                                Sound.PlayOnRemove = true\n\t                                Sound.PlaybackSpeed = PitchShift.Enabled and 1 + ((0.5 - math.random()) / 10) or 1\n\t                                Sound.Volume = Volume.Value\n\t                                Sound.Parent = workspace\n\t                                Sound:Destroy()\n\t                                Played = task.defer(function()\n\t                                    Played = nil\n\t                                end)\n\t                            end\n\t\n\t                            break\n\t                        end\n\t                    end\n\t                end\n\t            end)\n\t        else\n\t            TracerHook:Remove(\"HitSound\")\n\t        end\n\t    end,\n\t    Tooltip = \"Custom hit sound\"\n\t})\n\tValue = HitSound:CreateTextList({\n\t    Name = \"Sounds\",\n\t    Placeholder = \"sound id (roblox or file path)\",\n\t    Function = function(List)\n\t        table.clear(Sounds)\n\t        for i: number, v: string in List or {} do\n\t            Sounds[i] = v:find(\"rbxasset\") and v or isfile(v) and getcustomasset(v) or nil\n\t        end\n\t    end\n\t})\n\tVolume = HitSound:CreateSlider({\n\t    Name = \"Volume\",\n\t    Min = 0,\n\t    Max = 2,\n\t    Default = 1,\n\t    Decimal = 10\n\t})\n\tPitchShift = HitSound:CreateToggle({\n\t    Name = \"Pitch Shift\"\n\t})\nend)\n\nRun(function()\n\tlocal KillSound\n\tlocal Value\n\tlocal Volume\n\tlocal PitchShift\n\tlocal Old, Sounds = nil, {}\n\t\n\tKillSound = vape.Legit:CreateModule({\n\t    Name = \"KillSound\",\n\t    Category = \"Game\",\n\t    Icon = GetVapeAsset(`{vape.Directory}/assets/new/legit_killsound.png`),\n\t    Function = function(Callback: boolean)\n\t        if Callback then\n\t            KillSound:Clean(VapeEvents.PlayerKill.Event:Connect(function(PlayerName: string)\n\t                if PlayerName == LocalPlayer.Name and #Sounds > 0 then\n\t                    local Sound: Sound = Instance.new(\"Sound\")\n\t                    Sound.SoundId = Sounds[math.random(1, #Sounds)]\n\t                    Sound.PlayOnRemove = true\n\t                    Sound.PlaybackSpeed = PitchShift.Enabled and 1 + ((0.5 - math.random()) / 10) or 1\n\t                    Sound.Volume = Volume.Value\n\t                    Sound.Parent = workspace\n\t                    Sound:Destroy()\n\t                end\n\t            end))\n\t        end\n\t    end,\n\t    Tooltip = \"Custom kill sound\"\n\t})\n\tValue = KillSound:CreateTextList({\n\t    Name = \"Sounds\",\n\t    Placeholder = \"sound id (roblox or file path)\",\n\t    Function = function(List)\n\t        table.clear(Sounds)\n\t        for i: number, v: string in List or {} do\n\t            Sounds[i] = v:find(\"rbxasset\") and v or isfile(v) and getcustomasset(v) or nil\n\t        end\n\t    end\n\t})\n\tVolume = KillSound:CreateSlider({\n\t    Name = \"Volume\",\n\t    Min = 0,\n\t    Max = 2,\n\t    Default = 1,\n\t    Decimal = 10\n\t})\n\tPitchShift = KillSound:CreateToggle({\n\t    Name = \"Pitch Shift\"\n\t})\nend)\n\nRun(function()\n\tlocal Viewmodel\n\tlocal Depth\n\tlocal Horizontal\n\tlocal Vertical\n\tlocal Sway\n\tlocal ForceField\n\tlocal ColorSl\n\tlocal Handle\n\tlocal OldTool\n\tlocal MoveSpring = Spring.new()\n\tlocal AimSpring = Spring.new({Speed = 15})\n\t\n\tlocal function ToolAdded(Tool: Instance?)\n\t    if Tool and Tool:IsA(\"Tool\") then\n\t        if OldTool then\n\t            for _, v: Instance in OldTool:QueryDescendants(\"BasePart, Texture, Decal\") do\n\t                v.LocalTransparencyModifier = 0\n\t            end\n\t        end\n\t\n\t        if vtool then\n\t            vtool:Destroy()\n\t        end\n\t\n\t        OldTool = Tool\n\t        vtool = Tool:Clone()\n\t        Handle = vtool:FindFirstChild(\"Handle\")\n\t        vtool.Parent = Camera\n\t\n\t        for _, v: BasePart in vtool:QueryDescendants(\"BasePart\") do\n\t            v.Material = ForceField.Enabled and Enum.Material.ForceField or v.Material\n\t            v.Color = ForceField.Enabled and Color3.fromHSV(ColorSl.Hue, ColorSl.Sat, ColorSl.Value) or v.Color\n\t        end\n\t\n\t        for _, v: Instance in OldTool:QueryDescendants(\"BasePart, Texture, Decal\") do\n\t            v.LocalTransparencyModifier = 1\n\t        end\n\t    end\n\tend\n\t\n\tlocal function EntityAdded(Ent)\n\t    if vtool then\n\t        vtool:Destroy()\n\t        vtool = nil\n\t        Handle = nil\n\t    end\n\t\n\t    Viewmodel:Clean(Ent.Character.ChildAdded:Connect(ToolAdded))\n\t    Viewmodel:Clean(Ent.Character.ChildRemoved:Connect(function(Child: Instance)\n\t        if Child == OldTool then\n\t            if vtool then\n\t                vtool:Destroy()\n\t                vtool = nil\n\t            end\n\t\n\t            for _, v: Instance in OldTool:QueryDescendants(\"BasePart, Texture, Decal\") do\n\t                v.LocalTransparencyModifier = 0\n\t            end\n\t\n\t            OldTool = nil\n\t        end\n\t    end))\n\t\n\t    ToolAdded(Ent.Character:FindFirstChildWhichIsA(\"Tool\"))\n\tend\n\t\n\tViewmodel = vape.Legit:CreateModule({\n\t    Name = \"Viewmodel\",\n\t    Category = \"Game\",\n\t    Icon = GetVapeAsset(`{vape.Directory}/assets/new/legit_viewmodel.png`),\n\t    Function = function(Callback: boolean)\n\t        if Callback then\n\t            TracerHook:Add(\"Viewmodel\", function(...)\n\t                ShootTimer = os.clock() + 0.3\n\t            end, 0)\n\t\n\t            Viewmodel:Clean(Entity.Events.LocalAdded:Connect(EntityAdded))\n\t            if Entity.isAlive then\n\t                task.spawn(EntityAdded, Entity.character)\n\t            end\n\t\n\t            Viewmodel:Clean(RunService.RenderStepped:Connect(function(Delta: number)\n\t                if Handle then\n\t                    MoveSpring.Target = Entity.isAlive and Entity.character.RootPart.AssemblyLinearVelocity * 0.005 or Vector3.zero\n\t                    if Sway.Enabled then\n\t                        if MoveSpring.Target.Magnitude > 0.1 then\n\t                            MoveSpring.Target += (Camera.CFrame * CFrame.new(math.sin(tick() * 10) * 0.06, 0, 0)).Position - Camera.CFrame.Position\n\t                        else\n\t                            MoveSpring.Target += (Camera.CFrame * CFrame.new(0, math.sin(tick()) * 0.04, 0)).Position - Camera.CFrame.Position\n\t                        end\n\t                    end\n\t\n\t                    local ViewCFrame: CFrame = (Camera.CFrame * CFrame.new(Horizontal.Value, Vertical.Value, -Depth.Value)) + MoveSpring:Update(Delta)\n\t                    AimSpring.Target = AimTimer > os.clock() and CFrame.lookAt(ViewCFrame.Position, AimVector).LookVector or Camera.CFrame.LookVector\n\t                    Handle.CFrame = CFrame.lookAlong(ViewCFrame.Position, AimSpring:Update(Delta)) * (CFrame.Angles(math.rad(math.max(ShootTimer - os.clock(), 0) * 10), 0, 0) * CFrame.new(0, 0, math.max(ShootTimer - os.clock(), 0)))\n\t                    Handle.AssemblyLinearVelocity = Vector3.zero\n\t                end\n\t            end))\n\t        else\n\t            TracerHook:Remove(\"Viewmodel\")\n\t\n\t            if OldTool then\n\t                for _, v: Instance in OldTool:QueryDescendants(\"BasePart, Texture, Decal\") do\n\t                    v.LocalTransparencyModifier = 0\n\t                end\n\t                OldTool = nil\n\t            end\n\t\n\t            if vtool then\n\t                vtool:Destroy()\n\t                vtool = nil\n\t                Handle = nil\n\t            end\n\t        end\n\t    end,\n\t    Tooltip = \"Custom viewmodel for guns\"\n\t})\n\tDepth = Viewmodel:CreateSlider({\n\t    Name = \"Depth\",\n\t    Min = 0,\n\t    Max = 3,\n\t    Default = 3,\n\t    Decimal = 10\n\t})\n\tHorizontal = Viewmodel:CreateSlider({\n\t    Name = \"Horizontal\",\n\t    Min = 0,\n\t    Max = 2,\n\t    Default = 2,\n\t    Decimal = 10\n\t})\n\tVertical = Viewmodel:CreateSlider({\n\t    Name = \"Vertical\",\n\t    Min = -1.5,\n\t    Max = 2,\n\t    Default = -1.5,\n\t    Decimal = 10\n\t})\n\tSway = Viewmodel:CreateToggle({\n\t    Name = \"Sway Effect\",\n\t    Default = true\n\t})\n\tForceField = Viewmodel:CreateToggle({\n\t    Name = \"ForceField Effect\",\n\t    Function = function(Callback: boolean)\n\t        ColorSl.Object.Visible = Callback\n\t        if Callback and Viewmodel.Enabled then\n\t            Viewmodel:Toggle()\n\t            Viewmodel:Toggle()\n\t        end\n\t    end\n\t})\n\tColorSl = Viewmodel:CreateColorSlider({\n\t    Name = \"Color\",\n\t    Function = function(Hue: number, Sat: number, Val: number)\n\t        if vtool then\n\t            for _, v: BasePart in vtool:QueryDescendants(\"BasePart\") do\n\t                v.Color = Color3.fromHSV(Hue, Sat, Val)\n\t            end\n\t        end\n\t    end,\n\t    Visible = false\n\t})\nend)"},{"path":"src/games/16483433878.lua","name":"16483433878.lua","size":25253,"sha":"4ef35c57178c3e62f57bc86df709cf85c04fbb16","encoding":"utf8","content":"local Run = function(Func: () -> ())\n    Func()\nend\nlocal cloneref = cloneref or function(Reference: Instance)\n    return Reference\nend\n\nlocal Players: Players = cloneref(game:GetService(\"Players\"))\nlocal UserInputService: UserInputService = cloneref(game:GetService(\"UserInputService\"))\nlocal ReplicatedStorage: ReplicatedStorage = cloneref(game:GetService(\"ReplicatedStorage\"))\nlocal ReplicatedFirst: ReplicatedFirst = cloneref(game:GetService(\"ReplicatedFirst\"))\nlocal CollectionService: CollectionService = cloneref(game:GetService(\"CollectionService\"))\nlocal RunService: RunService = cloneref(game:GetService(\"RunService\"))\nlocal CoreGui: CoreGui = cloneref(game:GetService(\"CoreGui\"))\n\nlocal Camera: Camera = workspace.CurrentCamera\nlocal LocalPlayer: Player = Players.LocalPlayer\nlocal vape = shared.vape\nlocal Entity = vape.Libraries.entity\nlocal TargetInfo = vape.Libraries.targetinfo\nlocal Blocktales = {}\n\nlocal function SendNotification(...)\n    return vape:CreateNotification(...)\nend\n\nRun(function()\n    Blocktales = {\n        Ambassador = require(ReplicatedFirst.Ambassador),\n        BattleClient = getsenv(LocalPlayer.PlayerScripts.Battle.BattleClient),\n        Enemy = require(ReplicatedFirst.Classes.Entities.Enemy),\n        Network = require(ReplicatedFirst.Network),\n        Shucky = require(ReplicatedFirst.Modules.Shucky),\n        Variables = require(ReplicatedFirst.Variables)\n    }\n\n    vape:Clean(function()\n        table.clear(Blocktales)\n    end)\nend)\n\nfor _, v: string in {\"AimAssist\", \"Reach\", \"SilentAim\", \"TriggerBot\", \"AntiFall\", \"HitBoxes\", \"Invisible\", \"Jesus\", \"Killaura\", \"TargetStrafe\", \"AntiRagdoll\", \"Disabler\", \"MurderMystery\", \"Freecam\", \"ChatSpammer\", \"SpinBot\"} do\n    vape:Remove(v)\nend\n\nRun(function()\n\tlocal AutoAction\n\tlocal Attack\n\tlocal Block\n\tlocal Actions = {\n\t    press = function(Impact: number?, ActionTick: number)\n\t        if Impact and (Blocktales.Variables.window or 0) > 0 then\n\t            local Difference: number = (Impact - (Blocktales.Variables.window * 0.3))\n\t\n\t            if ActionTick < Impact and Difference <= ActionTick then\n\t                Blocktales.Ambassador.Fire(\"ButtonA\", \"down\")\n\t                Blocktales.Ambassador.Fire(\"ButtonA\", \"up\")\n\t            end\n\t        end\n\t    end,\n\t    hold = function(Impact: number?, ActionTick: number)\n\t        if Blocktales.Variables.promptuheld then\n\t            if ActionTick <= (Blocktales.Variables.promptuheld + Blocktales.Variables.holdingtime) then\n\t                local HoldTick: number = (tick() + 0.01 - Blocktales.Variables.atick - Blocktales.Variables.promptuheld) % Blocktales.Variables.loopfor / Blocktales.Variables.loopfor\n\t                if HoldTick > 0.5 then\n\t                    HoldTick = 1 - HoldTick\n\t                end\n\t\n\t                HoldTick = math.clamp(HoldTick * 2, 0, 1)\n\t                if HoldTick > Blocktales.Variables.greenmin + ((Blocktales.Variables.greenmax - Blocktales.Variables.greenmin) / 2) and HoldTick < Blocktales.Variables.greenmax then\n\t                    Blocktales.Ambassador.Fire(\"ButtonA\", \"up\")\n\t                end\n\t            end\n\t        else\n\t            if Blocktales.Variables.holdfrom <= ActionTick and ActionTick <= (Blocktales.Variables.holdfrom + Blocktales.Variables.holdtimeout) then\n\t                Blocktales.Ambassador.Fire(\"ButtonA\", \"down\")\n\t            end\n\t        end\n\t    end,\n\t    mash = function(Impact: number?, ActionTick: number)\n\t        if Blocktales.Variables.filled and Blocktales.Variables.filled[1] and (tick() - Blocktales.Variables.filled[1]) > 0.5 then\n\t            local Gui = LocalPlayer.PlayerGui.HUD.Battle.DOITNOW3\n\t            local Checker = Gui.Meter.checker\n\t            local FillBar = Gui.Meter.Fill\n\t            local FillPosition: number = FillBar.AbsoluteSize.X + FillBar.AbsolutePosition.X\n\t\n\t            for _, v: GuiObject in Checker:GetChildren() do\n\t                if not v:GetAttribute(\"Skipped\") then\n\t                    local CheckPosition: number = (v.AbsolutePosition.X - 6)\n\t                    if FillPosition > CheckPosition + (v.AbsoluteSize.X / 2) and FillPosition <= (CheckPosition + v.AbsoluteSize.X + 12) then\n\t                        Blocktales.Ambassador.Fire(\"ButtonA\", \"down\")\n\t                        Blocktales.Ambassador.Fire(\"ButtonA\", \"up\")\n\t                        break\n\t                    end\n\t                end\n\t            end\n\t        end\n\t    end\n\t}\n\t\n\tlocal function IsMyTurn(): boolean\n\t    if Blocktales.Variables.myturn and Blocktales.Variables.arena and Blocktales.Variables.arena:GetAttribute(\"State\") == \"Attacking\" then\n\t        if Attack.Enabled and Blocktales.Variables.itsme then\n\t            return true\n\t        end\n\t\n\t        if Block.Enabled and not Blocktales.Variables.itsme then\n\t            return true\n\t        end\n\t    end\n\t\n\t    return false\n\tend\n\t\n\tAutoAction = vape.Categories.Combat:CreateModule({\n\t    Name = \"AutoAction\",\n\t    Function = function(Callback: boolean)\n\t        if Callback then\n\t            repeat\n\t                if IsMyTurn() then\n\t                    local Impact: number? = Blocktales.Variables.timehere or Blocktales.Variables.impact\n\t                    local ActionTick: number = tick() - (Blocktales.Variables.atick or 0)\n\t\n\t                    if Actions[Blocktales.Variables.atktype] then\n\t                        Actions[Blocktales.Variables.atktype](Impact, ActionTick)\n\t                    end\n\t                end\n\t\n\t                task.wait()\n\t            until not AutoAction.Enabled\n\t        end\n\t    end,\n\t    Tooltip = \"Automatically dodge any incoming attacks to negate damage.\"\n\t})\n\tAttack = AutoAction:CreateToggle({\n\t    Name = \"Attacks\",\n\t    Default = true,\n\t    Tooltip = \"Automatically input for attack moves.\"\n\t})\n\tBlock = AutoAction:CreateToggle({\n\t    Name = \"Block\",\n\t    Default = true,\n\t    Tooltip = \"Automatically dodge incoming attack moves.\"\n\t})\nend)\n\nRun(function()\n\tlocal MissCooldown\n\tlocal ConstantIndex: number = game.PlaceId ~= 16483433878 and 20 or 53\n\t\n\tMissCooldown = vape.Categories.Combat:CreateModule({\n\t    Name = \"MissCooldown\",\n\t    Function = function(Callback: boolean)\n\t        if Callback then\n\t            debug.setconstant(Blocktales.BattleClient.input, ConstantIndex, 0)\n\t        else\n\t            debug.setconstant(Blocktales.BattleClient.input, ConstantIndex, 0.2)\n\t        end\n\t    end,\n\t    Tooltip = \"Remove the cooldown when missing a block or action.\"\n\t})\nend)\n\nRun(function()\n\tlocal AntiHazard\n\tlocal Old\n\t\n\tAntiHazard = vape.Categories.Blatant:CreateModule({\n\t    Name = \"AntiHazard\",\n\t    Function = function(Callback: boolean)\n\t        if Callback then\n\t            Old = hookfunction(Blocktales.Network.FireServer, function(...)\n\t                local Event = ...\n\t                if Event == \"TakeDamage\" then\n\t                    return\n\t                end\n\t\n\t                return Old(...)\n\t            end)\n\t        else\n\t            if Old then\n\t                hookfunction(Blocktales.Network.FireServer, Old)\n\t                Old = nil\n\t            end\n\t        end\n\t    end,\n\t    Tooltip = \"Prevent you from taking damage in the overworld section.\"\n\t})\nend)\n\nlocal Fly\nlocal LongJump\nRun(function()\n    local Value\n    local VerticalValue\n    local Up, Down = 0, 0\n\n    Fly = vape.Categories.Blatant:CreateModule({\n        Name = \"Fly\",\n        Function = function(Callback: boolean)\n            if Callback then\n                Fly:Clean(RunService.PreSimulation:Connect(function(Delta: number)\n                    if Entity.isAlive then\n                        local Root: BasePart = Entity.character.RootPart\n                        local State: Enum.HumanoidStateType = Entity.character.Humanoid:GetState()\n                        if State == Enum.HumanoidStateType.Climbing or Blocktales.Variables.transitioning then\n                            return\n                        end\n\n                        local MoveVector: Vector3 = Entity.character.Humanoid.MoveDirection * Value.Value\n                        Root.AssemblyLinearVelocity = Vector3.new(MoveVector.X, 1 + ((Up + Down) * VerticalValue.Value), MoveVector.Z)\n                    end\n                end))\n\n                Up, Down = 0, 0\n                for _, v: string in {\"InputBegan\", \"InputEnded\"} do\n                    Fly:Clean(UserInputService[v]:Connect(function(Input: InputObject)\n                        if not UserInputService:GetFocusedTextBox() then\n                            if Input.KeyCode == Enum.KeyCode.Space then\n                                Up = v == \"InputBegan\" and 1 or 0\n                            elseif Input.KeyCode == Enum.KeyCode.LeftControl then\n                                Down = v == \"InputBegan\" and -1 or 0\n                            end\n                        end\n                    end))\n                end\n\n                if UserInputService.TouchEnabled then\n                    pcall(function()\n                        local JumpButton: ImageButton = LocalPlayer.PlayerGui.TouchGui.TouchControlFrame.JumpButton\n                        Fly:Clean(JumpButton:GetPropertyChangedSignal(\"ImageRectOffset\"):Connect(function()\n                            Up = JumpButton.ImageRectOffset.X == 146 and 1 or 0\n                        end))\n                    end)\n                end\n            end\n        end,\n        ExtraText = function()\n            return \"Velocity\"\n        end,\n        Tooltip = \"Makes you go zoom.\"\n    })\n    Value = Fly:CreateSlider({\n        Name = \"Speed\",\n        Min = 1,\n        Max = 150,\n        Default = 50,\n        Suffix = function(Val: number)\n            return Val == 1 and \"stud\" or \"studs\"\n        end\n    })\n    VerticalValue = Fly:CreateSlider({\n        Name = \"Vertical Speed\",\n        Min = 1,\n        Max = 150,\n        Default = 50,\n        Suffix = function(Val: number)\n            return Val == 1 and \"stud\" or \"studs\"\n        end\n    })\nend)\n\nRun(function()\n\tlocal FlyingAttack\n\t\n\tFlyingAttack = vape.Categories.Blatant:CreateModule({\n\t    Name = \"FlyingAttack\",\n\t    Function = function(Callback: boolean)\n\t        if Callback then\n\t            debug.setconstant(Blocktales.Shucky.PossibleFirst, 7, \"_Flying\")\n\t        else\n\t            debug.setconstant(Blocktales.Shucky.PossibleFirst, 7, \"Flying\")\n\t        end\n\t    end,\n\t    Tooltip = \"Allow you to attack flying enemies with onground attacks.\"\n\t})\nend)\n\nRun(function()\n\tlocal Value\n\tlocal AutoDisable\n\t\n\tLongJump = vape.Categories.Blatant:CreateModule({\n\t    Name = \"LongJump\",\n\t    Function = function(Callback: boolean)\n\t        if Callback then\n\t            local Exempt: number = tick() + 0.1\n\t            LongJump:Clean(RunService.PreSimulation:Connect(function(Delta: number)\n\t                if Entity.isAlive then\n\t                    if Entity.character.Humanoid.FloorMaterial ~= Enum.Material.Air then\n\t                        if Exempt < tick() and AutoDisable.Enabled then\n\t                            if LongJump.Enabled then\n\t                                LongJump:Toggle()\n\t                            end\n\t                        else\n\t                            Entity.character.Humanoid:ChangeState(Enum.HumanoidStateType.Jumping)\n\t                        end\n\t                    end\n\t\n\t                    local Root: BasePart = Entity.character.RootPart\n\t                    local State: Enum.HumanoidStateType = Entity.character.Humanoid:GetState()\n\t                    if State == Enum.HumanoidStateType.Climbing or Blocktales.Variables.transitioning then\n\t                        return\n\t                    end\n\t\n\t                    local MoveVector: Vector3 = Entity.character.Humanoid.MoveDirection * Value.Value\n\t                    Root.AssemblyLinearVelocity = Vector3.new(MoveVector.X, Root.AssemblyLinearVelocity.Y, MoveVector.Z)\n\t                end\n\t            end))\n\t        end\n\t    end,\n\t    ExtraText = function()\n\t        return \"Velocity\"\n\t    end,\n\t    Tooltip = \"Lets you jump farther\"\n\t})\n\tValue = LongJump:CreateSlider({\n\t    Name = \"Speed\",\n\t    Min = 1,\n\t    Max = 150,\n\t    Default = 50,\n\t    Suffix = function(Val: number)\n\t        return Val == 1 and \"stud\" or \"studs\"\n\t    end\n\t})\n\tAutoDisable = LongJump:CreateToggle({\n\t    Name = \"Auto Disable\",\n\t    Default = true\n\t})\nend)\n\nRun(function()\n\tlocal PickupTP\n\t\n\tPickupTP = vape.Categories.Blatant:CreateModule({\n\t    Name = \"PickupTP\",\n\t    Function = function(Callback: boolean)\n\t        if Callback then\n\t            local Old: CFrame?\n\t            repeat\n\t                if Entity.isAlive then\n\t                    local Success: boolean = true\n\t                    for _, v: BasePart in CollectionService:GetTagged(\"Pickup\") do\n\t                        if not v:GetAttribute(\"Inactive\") then\n\t                            if not Old then\n\t                                Old = Entity.character.RootPart.CFrame\n\t                            end\n\t\n\t                            Success = false\n\t                            Entity.character.RootPart.CFrame = v.CFrame\n\t                            break\n\t                        end\n\t                    end\n\t\n\t                    if Success and Old then\n\t                        Entity.character.RootPart.CFrame = Old\n\t                        Old = nil\n\t                    end\n\t                else\n\t                    Old = nil\n\t                end\n\t\n\t                task.wait(0.4)\n\t            until not PickupTP.Enabled\n\t        end\n\t    end,\n\t    Tooltip = \"Teleport to any nearby active pickups.\"\n\t})\nend)\n\nRun(function()\n\tlocal Speed\n\tlocal Value\n\t\n\tSpeed = vape.Categories.Blatant:CreateModule({\n\t    Name = \"Speed\",\n\t    Function = function(Callback: boolean)\n\t        if Callback then\n\t            Speed:Clean(RunService.PreSimulation:Connect(function(Delta: number)\n\t                if Entity.isAlive and not Fly.Enabled and not LongJump.Enabled then\n\t                    local Root: BasePart = Entity.character.RootPart\n\t                    local State: Enum.HumanoidStateType = Entity.character.Humanoid:GetState()\n\t                    if State == Enum.HumanoidStateType.Climbing or Blocktales.Variables.transitioning then\n\t                        return\n\t                    end\n\t\n\t                    local MoveVector: Vector3 = Entity.character.Humanoid.MoveDirection * Value.Value\n\t                    Root.AssemblyLinearVelocity = Vector3.new(MoveVector.X, Root.AssemblyLinearVelocity.Y, MoveVector.Z)\n\t                end\n\t            end))\n\t        end\n\t    end,\n\t    ExtraText = function()\n\t        return \"Velocity\"\n\t    end,\n\t    Tooltip = \"Increases your movement with various methods.\"\n\t})\n\tValue = Speed:CreateSlider({\n\t    Name = \"Speed\",\n\t    Min = 1,\n\t    Max = 150,\n\t    Default = 50,\n\t    Suffix = function(Val: number)\n\t        return Val == 1 and \"stud\" or \"studs\"\n\t    end\n\t})\nend)\n\nRun(function()\n\tlocal SpeedSpin\n\tlocal Value\n\tlocal Old\n\t\n\tSpeedSpin = vape.Categories.Blatant:CreateModule({\n\t    Name = \"SpeedSpin\",\n\t    Function = function(Callback: boolean)\n\t        if Callback then\n\t            Old = hookfunction(Blocktales.Shucky.HasBadge, function(...)\n\t                local self, Badge = ...\n\t                if Badge == \"Speed Spin\" then\n\t                    return Value.Value\n\t                end\n\t\n\t                return Old(...)\n\t            end)\n\t        else\n\t            if Old then\n\t                hookfunction(Blocktales.Shucky.HasBadge, Old)\n\t                Old = nil\n\t            end\n\t        end\n\t    end,\n\t    Tooltip = \"Spoof the amount of speed spin cards you possess.\"\n\t})\n\tValue = SpeedSpin:CreateSlider({\n\t    Name = \"Card Amount\",\n\t    Min = 0,\n\t    Max = 10,\n\t    Default = 4\n\t})\nend)\n\nRun(function()\n\tlocal PickupTracers\n\tlocal Color\n\tlocal Transparency\n\tlocal Bux\n\tlocal Reference = {}\n\t\n\tlocal function Added(Pickup: BasePart)\n\t    if vape.ThreadFix then\n\t        setthreadidentity(8)\n\t    end\n\t\n\t    if Bux.Enabled and Pickup.Name ~= \"BUX\" then\n\t        return\n\t    end\n\t\n\t    local EntityTracer = Drawing.new(\"Line\")\n\t    EntityTracer.Thickness = 1\n\t    EntityTracer.Transparency = 1 - Transparency.Value\n\t    EntityTracer.Color = Color3.fromHSV(Color.Hue, Color.Sat, Color.Value)\n\t    Reference[Pickup] = EntityTracer\n\tend\n\t\n\tlocal function Removed(Pickup: BasePart)\n\t    local Tracer = Reference[Pickup]\n\t    if Tracer then\n\t        if vape.ThreadFix then\n\t            setthreadidentity(8)\n\t        end\n\t\n\t        Reference[Pickup] = nil\n\t        pcall(function()\n\t            Tracer.Visible = false\n\t            Tracer:Remove()\n\t        end)\n\t    end\n\tend\n\t\n\tlocal function ColorFunc(Hue: number, Sat: number, Val: number)\n\t    local TracerColor: Color3 = Color3.fromHSV(Hue, Sat, Val)\n\t    for Pickup: BasePart, EntityTracer: any in Reference do\n\t        EntityTracer.Color = TracerColor\n\t    end\n\tend\n\t\n\tlocal function Loop()\n\t    local ScreenSize: Vector2 = vape.gui.AbsoluteSize\n\t    local StartVector: Vector2 = Vector2.new(ScreenSize.X / 2, ScreenSize.Y / 2)\n\t\n\t    for Pickup: BasePart, EntityTracer: any in Reference do\n\t        if Pickup:GetAttribute(\"Inactive\") then\n\t            EntityTracer.Visible = false\n\t            continue\n\t        end\n\t\n\t        local Position: Vector3 = Pickup.Position\n\t        local RootPos, RootVisible = Camera:WorldToViewportPoint(Position)\n\t\n\t        if not RootVisible then\n\t            local TempPosition: Vector3 = Camera.CFrame:PointToObjectSpace(Position)\n\t            TempPosition = CFrame.Angles(0, 0, (math.atan2(TempPosition.Y, TempPosition.X) + math.pi)):VectorToWorldSpace((CFrame.Angles(0, math.rad(89.9), 0):VectorToWorldSpace(Vector3.new(0, 0, -1))))\n\t            RootPos = Camera:WorldToViewportPoint(Camera.CFrame:pointToWorldSpace(TempPosition))\n\t            RootVisible = true\n\t        end\n\t\n\t        local EndVector: Vector2 = Vector2.new(RootPos.X, RootPos.Y)\n\t        EntityTracer.Visible = RootVisible\n\t        EntityTracer.From = StartVector\n\t        EntityTracer.To = EndVector\n\t    end\n\tend\n\t\n\tPickupTracers = vape.Categories.Render:CreateModule({\n\t    Name = \"PickupTracers\",\n\t    Function = function(Callback: boolean)\n\t        if Callback then\n\t            PickupTracers:Clean(CollectionService:GetInstanceAddedSignal(\"Pickup\"):Connect(function(Pickup: BasePart)\n\t                if Reference[Pickup] then\n\t                    Removed(Pickup)\n\t                end\n\t                Added(Pickup)\n\t            end))\n\t            PickupTracers:Clean(CollectionService:GetInstanceRemovedSignal(\"Pickup\"):Connect(Removed))\n\t            for _, v: BasePart in CollectionService:GetTagged(\"Pickup\") do\n\t                if Reference[v] then\n\t                    Removed(v)\n\t                end\n\t                Added(v)\n\t            end\n\t            PickupTracers:Clean(RunService.RenderStepped:Connect(Loop))\n\t        else\n\t            for Pickup: BasePart in Reference do\n\t                Removed(Pickup)\n\t            end\n\t        end\n\t    end,\n\t    Tooltip = \"Renders tracers on pickups.\"\n\t})\n\tColor = PickupTracers:CreateColorSlider({\n\t    Name = \"BUX Color\",\n\t    Function = function(Hue: number, Sat: number, Val: number)\n\t        if PickupTracers.Enabled then\n\t            ColorFunc(Hue, Sat, Val)\n\t        end\n\t    end\n\t})\n\tTransparency = PickupTracers:CreateSlider({\n\t    Name = \"Transparency\",\n\t    Min = 0,\n\t    Max = 1,\n\t    Function = function(Val: number)\n\t        for _, v: any in Reference do\n\t            v.Transparency = 1 - Val\n\t        end\n\t    end,\n\t    Decimal = 10\n\t})\n\tBux = PickupTracers:CreateToggle({\n\t    Name = \"Bux Only\",\n\t    Function = function()\n\t        if PickupTracers.Enabled then\n\t            PickupTracers:Toggle()\n\t            PickupTracers:Toggle()\n\t        end\n\t    end,\n\t    Tooltip = \"Hides non BUX pickups\"\n\t})\nend)\n\nRun(function()\n\tlocal AutoCamel\n\t\n\tAutoCamel = vape.Categories.Utility:CreateModule({\n\t    Name = \"AutoCamel\",\n\t    Function = function(Callback: boolean)\n\t        if Callback then\n\t            local Camel: Instance? = workspace.NPCs:FindFirstChild(\"Abu Baba\")\n\t            if not Camel then\n\t                SendNotification(\"AutoCamel\", \"Missing camel seller!\", 5, \"warning\")\n\t                AutoCamel:Toggle()\n\t                return\n\t            end\n\t\n\t            local RunModule = require(Camel.Dialogue:FindFirstChild(\"RunScript\", true).ModuleScript)\n\t            repeat\n\t                if (LocalPlayer:GetAttribute(\"TIX\") or 0) >= 30 then\n\t                    RunModule:Run()\n\t                end\n\t\n\t                task.wait(0.5)\n\t            until not AutoCamel.Enabled\n\t        end\n\t    end,\n\t    Tooltip = \"Automatically buy camels\"\n\t})\nend)\n\nRun(function()\n\tlocal AutoCloudGrind\n\t\n\tAutoCloudGrind = vape.Categories.Utility:CreateModule({\n\t    Name = \"AutoCloudGrind\",\n\t    Function = function(Callback: boolean)\n\t        if Callback then\n\t            repeat\n\t                if Blocktales.Variables.arena and Blocktales.Variables.arena:GetAttribute(\"State\") == \"Picking\" then\n\t                    local ShouldRun: boolean = true\n\t                    for _, v: ObjectValue in Blocktales.Variables.arena.Goon:GetChildren() do\n\t                        local Drop = v.Value and v.Value:GetAttribute(\"Item_Drop\")\n\t\n\t                        if Drop and Drop:find(\"FX \") and not Blocktales.Variables.data.CardCollection[Drop] then\n\t                            ShouldRun = false\n\t                        end\n\t                    end\n\t\n\t                    if ShouldRun then\n\t                        Blocktales.Network.FireServer(\"CommitToMove\", \"Run Away\", nil, nil)\n\t                        task.wait(3)\n\t                    else\n\t                        workspace.Sounds.Money:Play()\n\t                        workspace.Sounds.Money.Ended:Wait()\n\t                    end\n\t                end\n\t\n\t                task.wait(0.05)\n\t            until not AutoCloudGrind.Enabled\n\t        end\n\t    end,\n\t    Tooltip = \"Automatically grind for SFX Cards from Cloudie (floor 51)\"\n\t})\nend)\n\nRun(function()\n\tlocal AutoFish\n\tlocal KeepList\n\tlocal Old\n\t\n\tAutoFish = vape.Categories.Utility:CreateModule({\n\t    Name = \"AutoFish\",\n\t    Function = function(Callback: boolean)\n\t        if Callback then\n\t            local Fisherman: Instance? = workspace.NPCs:FindFirstChild(\"The Seller\")\n\t            if not Fisherman then\n\t                SendNotification(\"AutoFish\", \"Missing fisherman!\", 5, \"warning\")\n\t                AutoFish:Toggle()\n\t                return\n\t            end\n\t\n\t            Old = workspace.Sounds.Money.Volume\n\t            workspace.Sounds.Money.Volume = 0\n\t\n\t            repeat\n\t                local Fish = LocalPlayer.Status:GetAttribute(\"NextFish\")\n\t                local Result = Blocktales.Network.InvokeServer(\"FishItem\")\n\t                if Result == true then\n\t                    if not table.find(KeepList.ListEnabled, Fish) then\n\t                        Blocktales.Network.InvokeServer(\"UseItem\", Fish, Fisherman)\n\t                    end\n\t\n\t                    Blocktales.Network.InvokeServer(\"BuyItem\", Fisherman.ShopItems:GetChildren()[1], Fisherman)\n\t                end\n\t\n\t                task.wait()\n\t            until not AutoFish.Enabled\n\t        else\n\t            if Old then\n\t                workspace.Sounds.Money.Volume = Old\n\t            end\n\t        end\n\t    end,\n\t    Tooltip = \"Automatically sell and buy fish\"\n\t})\n\tKeepList = AutoFish:CreateTextList({\n\t    Name = \"Keep List\",\n\t    Placeholder = \"item\"\n\t})\nend)\n\nRun(function()\n\tlocal AutoPaint\n\t\n\tAutoPaint = vape.Categories.Utility:CreateModule({\n\t    Name = \"AutoPaint\",\n\t    Function = function(Callback: boolean)\n\t        if Callback then\n\t            local Gui = LocalPlayer.PlayerGui.HUD.Painter\n\t            local Canvas = Gui:FindFirstChild(\"CanvasTime\", true).Parent\n\t            local ColorPicker = Gui.ColorPicker\n\t\n\t            repeat\n\t                if Gui.Visible and Blocktales.Variables.paintingflag and not Blocktales.Variables.canvas:GetAttribute(\"Completed\") then\n\t                    local Solution = Blocktales.Variables.canvas.Parent:FindFirstChild(\"Solution Easel\")\n\t\n\t                    if Solution then\n\t                        for _, v: Instance in Solution.solution:GetDescendants() do\n\t                            if v:IsA(\"BasePart\") and Blocktales.Variables.canvas[v.Parent.Name][v.Name].BrickColor ~= v.BrickColor then\n\t                                local Element = Canvas:FindFirstChild(`{v.Parent.Name:sub(4)}_{v.Name}`)\n\t                                if Element then\n\t                                    for _, ColorButton: GuiObject in ColorPicker:GetChildren() do\n\t                                        if ColorButton:GetAttribute(\"BGColor\") == v.BrickColor.Color then\n\t                                            Blocktales.Ambassador.Fire(\"ButtonPress\", ColorButton)\n\t                                            break\n\t                                        end\n\t                                    end\n\t\n\t                                    Blocktales.Ambassador.Fire(\"ButtonPress\", Element)\n\t                                end\n\t\n\t                                break\n\t                            end\n\t                        end\n\t                    end\n\t                end\n\t\n\t                task.wait(0.05)\n\t            until not AutoPaint.Enabled\n\t        end\n\t    end,\n\t    Tooltip = \"Automatically paint canvas photos\"\n\t})\nend)"},{"path":"src/games/1962086868.lua","name":"1962086868.lua","size":76430,"sha":"3ff8db8a14e16735fe86e9ea3ba6da829450ff41","encoding":"utf8","content":"local Run = function(Func: () -> ())\n    Func()\nend\nlocal cloneref = cloneref or function(Reference: Instance)\n    return Reference\nend\n\nlocal Players: Players = cloneref(game:GetService(\"Players\"))\nlocal RunService: RunService = cloneref(game:GetService(\"RunService\"))\nlocal CollectionService: CollectionService = cloneref(game:GetService(\"CollectionService\"))\nlocal ReplicatedStorage: ReplicatedStorage = cloneref(game:GetService(\"ReplicatedStorage\"))\n\nlocal LocalPlayer: Player = Players.LocalPlayer\nlocal vape = shared.vape\n\nlocal TowerOfHell = {}\n\nRun(function()\n    TowerOfHell = {\n        Controls = require(LocalPlayer.PlayerScripts.PlayerModule).controls\n    }\n\n    vape:Clean(function()\n        table.clear(TowerOfHell)\n    end)\nend)\n\nRun(function()\n\tlocal AutoPlay\n\tlocal Path\n\tlocal Color\n\t\n\tlocal Folder, Probe, Rig, Route, Step, Began, Launched, Airborne, Peak, Aim, Bent, Waited, Movement, Planning, Building, Built, Tower, Escape, Sunk, Hovered, Old\n\tlocal Slip: Vector3 = Vector3.zero\n\tlocal Nodes, Cells, Sections, Moving, Hazards, Platforms, Trusses, Blocked, Parts, Tracks, Demos, Strikes, Watched = {}, {}, {}, {}, {}, {}, {}, {}, {}, {}, {}, {}, {}\n\tlocal Version, Changed, Sampled, Checked = 0, 0, 0, 0\n\tlocal Overlap: OverlapParams = OverlapParams.new()\n\tOverlap.RespectCanCollide = true\n\tOverlap.FilterType = Enum.RaycastFilterType.Include\n\tlocal KillOverlap: OverlapParams = OverlapParams.new()\n\tKillOverlap.FilterType = Enum.RaycastFilterType.Include\n\tlocal FinishOverlap: OverlapParams = OverlapParams.new()\n\tFinishOverlap.FilterType = Enum.RaycastFilterType.Include\n\tlocal Params: RaycastParams = RaycastParams.new()\n\tParams.RespectCanCollide = true\n\tParams.FilterType = Enum.RaycastFilterType.Include\n\tlocal KillParams: RaycastParams = RaycastParams.new()\n\tKillParams.FilterType = Enum.RaycastFilterType.Include\n\tlocal Include: RaycastParams = RaycastParams.new()\n\tInclude.FilterType = Enum.RaycastFilterType.Include\n\t\n\tlocal function Push(Heap, Item)\n\t    table.insert(Heap, Item)\n\t    local Index: number = #Heap\n\t    while Index > 1 and Heap[Index // 2][2] > Item[2] do\n\t        Heap[Index] = Heap[Index // 2]\n\t        Index //= 2\n\t    end\n\t    Heap[Index] = Item\n\tend\n\t\n\tlocal function Pop(Heap)\n\t    local Top, Last = Heap[1], table.remove(Heap)\n\t    if Heap[1] then\n\t        local Index: number = 1\n\t        while Index * 2 <= #Heap do\n\t            local Child: number = Index * 2\n\t            if Child < #Heap and Heap[Child + 1][2] < Heap[Child][2] then\n\t                Child += 1\n\t            end\n\t            if Heap[Child][2] >= Last[2] then\n\t                break\n\t            end\n\t            Heap[Index] = Heap[Child]\n\t            Index = Child\n\t        end\n\t        Heap[Index] = Last\n\t    end\n\t    return Top\n\tend\n\t\n\tlocal function GetRig()\n\t    local Root: BasePart = LocalPlayer.Character.HumanoidRootPart\n\t    local Humanoid: Humanoid? = LocalPlayer.Character:FindFirstChildOfClass(\"Humanoid\")\n\t    local Low, High = Vector3.one * math.huge, Vector3.one * -math.huge\n\t    local CollideLow, CollideHigh, LegLow, LegHigh = Low, High, Low, High\n\t    for _, v: BasePart in LocalPlayer.Character:GetChildren() do\n\t        if v:IsA(\"BasePart\") then\n\t            local LocalFrame: CFrame = Root.CFrame:ToObjectSpace(v.CFrame)\n\t            local Half: Vector3 = ((LocalFrame.RightVector * v.Size.X):Abs() + (LocalFrame.UpVector * v.Size.Y):Abs() + (LocalFrame.LookVector * v.Size.Z):Abs()) * 0.5\n\t            Low, High = Low:Min(LocalFrame.Position - Half), High:Max(LocalFrame.Position + Half)\n\t            if LocalFrame.Position.Y - Half.Y < -1.2 then\n\t                LegLow, LegHigh = LegLow:Min(LocalFrame.Position - Half), LegHigh:Max(LocalFrame.Position + Half)\n\t            end\n\t            if v.CanCollide then\n\t                CollideLow, CollideHigh = CollideLow:Min(LocalFrame.Position - Half), CollideHigh:Max(LocalFrame.Position + Half)\n\t            end\n\t        end\n\t    end\n\t\n\t    local Width: number = math.max(-CollideLow.X, CollideHigh.X, -CollideLow.Z, CollideHigh.Z) * 2 - 0.4\n\t    local Hover: number = Humanoid.RigType == Enum.HumanoidRigType.R15 and Humanoid.HipHeight + Root.Size.Y / 2 or Root.Size.Y / 2 + 2\n\t    return {\n\t        hover = Hover,\n\t        lift = Hover + CollideLow.Y - 0.25,\n\t        slope = math.max(math.cos(math.rad(Humanoid.MaxSlopeAngle)), 0.25),\n\t        speed = Humanoid.WalkSpeed,\n\t        gravity = workspace.Gravity,\n\t        jump = Rig and Rig.jump or math.max(Humanoid.JumpPower, math.sqrt(2 * workspace.Gravity * Humanoid.JumpHeight)),\n\t        size = Vector3.new(Width, CollideHigh.Y - CollideLow.Y, Width),\n\t        offset = Vector3.new(0, (CollideLow.Y + CollideHigh.Y) / 2, 0),\n\t        kills = {\n\t            {Vector3.new(math.max(-LegLow.X, LegHigh.X) * 2 + 0.4, -1 - Low.Y + 0.3, math.max(-LegLow.Z, LegHigh.Z) * 2 + 1), Vector3.new(0, (Low.Y - 1.3) / 2, 0)},\n\t            {Vector3.new(math.max(-Low.X, High.X) * 2 + 0.4, High.Y + 1.2, math.max(-Low.Z, High.Z) * 2 + 1.8), Vector3.new(0, (High.Y - 0.8) / 2, 0)}\n\t        }\n\t    }\n\tend\n\t\n\tlocal function GetFloor(Position: Vector3): RaycastResult?\n\t    return workspace:Blockcast(CFrame.new(Position), Vector3.new(Rig.size.X, 0.2, Rig.size.Z), Vector3.new(0, -Rig.hover - 1.5, 0), Params)\n\tend\n\t\n\tlocal function GetRunway(Point: Vector3, Direction: Vector3, Limit: number)\n\t    local Distance: number = 0\n\t    for i: number = 1, 6 do\n\t        local Ahead: Vector3 = Point + Direction * (i * 0.25)\n\t        Probe.Size, Probe.CFrame = Rig.kills[1][1], CFrame.lookAt(Vector3.zero, Direction) + Ahead + Vector3.new(0, Rig.hover, 0) + Rig.kills[1][2]\n\t        if i * 0.25 > Limit or workspace:GetPartsInPart(Probe, KillOverlap)[1] then\n\t            return Distance, false\n\t        elseif not workspace:Raycast(Ahead + Vector3.new(0, 0.5, 0), Vector3.new(0, -1.5, 0), Params) then\n\t            return workspace:Raycast(Ahead - Direction * 0.125 + Vector3.new(0, 0.5, 0), Vector3.new(0, -1.5, 0), Params) and Distance + 0.125 or Distance, true\n\t        end\n\t        Distance = i * 0.25\n\t    end\n\t    return Distance, false\n\tend\n\t\n\tlocal function GetNodes()\n\t    local Current, Snapshot, Clock, Group, Count, Recorded, Rungs = Version, {}, os.clock(), LocalPlayer.Character.HumanoidRootPart.CollisionGroup, 0, 0, {}\n\t    table.clear(Nodes)\n\t    table.clear(Cells)\n\t    table.clear(Sections)\n\t    table.clear(Moving)\n\t    table.clear(Hazards)\n\t    table.clear(Platforms)\n\t    table.clear(Trusses)\n\t    table.clear(Blocked)\n\t    for _, v: BasePart in workspace.tower:GetDescendants() do\n\t        if v:IsA(\"BasePart\") then\n\t            Snapshot[v] = v.CFrame\n\t        end\n\t    end\n\t    task.wait(1)\n\t    for Part: BasePart, v: CFrame in Snapshot do\n\t        if (Part.Position - v.Position).Magnitude > 0.05 or Part.CFrame.LookVector:Dot(v.LookVector) < 0.9999 or not Part:IsGrounded() then\n\t            Moving[Part] = true\n\t        end\n\t    end\n\t\n\t    local Kills: {Instance} = CollectionService:GetTagged(\"LobbyPortal\")\n\t    for _, v: Instance in ReplicatedStorage.GameValues.killbricksDisabled.Value and {} or CollectionService:GetTagged(\"KillBrick\") do\n\t        table.insert(Kills, v)\n\t    end\n\t    Overlap.CollisionGroup = Group\n\t    Params.CollisionGroup = Group\n\t    Overlap.FilterDescendantsInstances = {workspace.tower}\n\t    Params.FilterDescendantsInstances = {workspace.tower}\n\t    KillOverlap.FilterDescendantsInstances = Kills\n\t    KillParams.FilterDescendantsInstances = Kills\n\t    table.clear(Watched)\n\t    for _, v: Instance in Kills do\n\t        if Moving[v] then\n\t            Hazards[v] = {part = v, linear = Vector3.zero, angular = Vector3.zero, center = v.Position}\n\t        else\n\t            Watched[v] = v.CFrame\n\t        end\n\t    end\n\t    FinishOverlap.FilterDescendantsInstances = {workspace.tower.finishes}\n\t    local Box, Extents = workspace.tower.finishes:GetBoundingBox()\n\t    local Recorder: RBXScriptConnection = RunService.Heartbeat:Connect(function()\n\t        if os.clock() - Recorded > 0.25 then\n\t            Recorded = os.clock()\n\t            for _, v: any in Platforms do\n\t                table.insert(v.track, v.part.CFrame)\n\t            end\n\t        end\n\t    end)\n\t\n\t    for _, Section: Instance in workspace.tower.sections:GetChildren() do\n\t        if Section:FindFirstChild(\"i\") then\n\t            Sections[Section.i.Value] = Section\n\t            for _, v: BasePart in Section:GetDescendants() do\n\t                if v:IsA(\"BasePart\") and v.CanCollide and not CollectionService:HasTag(v, \"KillBrick\") and v.Position.Y - (math.abs(v.CFrame.RightVector.Y) * v.Size.X + math.abs(v.CFrame.UpVector.Y) * v.Size.Y + math.abs(v.CFrame.LookVector.Y) * v.Size.Z) / 2 < Box.Y + Extents.Y / 2 + 2 then\n\t                    local Half: Vector3 = ((v.CFrame.RightVector * v.Size.X):Abs() + (v.CFrame.UpVector * v.Size.Y):Abs() + (v.CFrame.LookVector * v.Size.Z):Abs()) * 0.5\n\t                    local Footprint: number = math.abs(v.CFrame.UpVector.Y) >= math.max(math.abs(v.CFrame.RightVector.Y), math.abs(v.CFrame.LookVector.Y)) and math.min(v.Size.X, v.Size.Z) or math.abs(v.CFrame.RightVector.Y) >= math.abs(v.CFrame.LookVector.Y) and math.min(v.Size.Y, v.Size.Z) or math.min(v.Size.X, v.Size.Y)\n\t                    local Spacing: number = Footprint > 16 and 2 or 1\n\t                    local Columns, Rows = math.max(math.floor(Half.X * 2 / Spacing), 1) - 1, math.max(math.floor(Half.Z * 2 / Spacing), 1) - 1\n\t                    local Platform\n\t                    if Moving[v] then\n\t                        Count += 1\n\t                        Platform = {part = v, samples = {}, track = {}, swept = {}, linear = Vector3.zero, angular = Vector3.zero, center = v.Position}\n\t                        Platform.node = {position = v.Position, section = Section.i.Value, links = {}, border = true, index = -Count, island = -Count, platform = Platform}\n\t                    end\n\t                    Include.FilterDescendantsInstances = {v}\n\t                    for X: number = v.Position.X - Columns * Spacing / 2, v.Position.X + Columns * Spacing / 2 + 0.01, Spacing do\n\t                        for Z: number = v.Position.Z - Rows * Spacing / 2, v.Position.Z + Rows * Spacing / 2 + 0.01, Spacing do\n\t                            local Hit: RaycastResult? = workspace:Raycast(Vector3.new(X, v.Position.Y + Half.Y + 0.1, Z), Vector3.new(0, -Half.Y * 2 - 0.2, 0), Include)\n\t                            if Hit and Hit.Normal.Y > Rig.slope and Platform then\n\t                                table.insert(Platform.samples, v.CFrame:PointToObjectSpace(Hit.Position))\n\t                            elseif Hit and Hit.Normal.Y > Rig.slope then\n\t                                Probe.Size, Probe.CFrame = Vector3.new(1, 0.2, 1), CFrame.new(Hit.Position + Vector3.new(0, 0.2, 0))\n\t                                local Buried: {BasePart} = workspace:GetPartsInPart(Probe, Overlap)\n\t                                local Safe: boolean = not Buried[1] or Buried[1] == v and not Buried[2]\n\t                                Probe.Size, Probe.CFrame = Rig.size, CFrame.new(Hit.Position + Vector3.new(0, Rig.hover + (1 - Hit.Normal.Y) * 2, 0) + Rig.offset)\n\t                                Safe = Safe and not workspace:GetPartsInPart(Probe, Overlap)[1]\n\t                                for _, Kill: {Vector3} in Rig.kills do\n\t                                    if not Safe then\n\t                                        break\n\t                                    end\n\t                                    Probe.Size, Probe.CFrame = Vector3.new(Kill[1].Z, Kill[1].Y, Kill[1].Z), CFrame.new(Hit.Position + Vector3.new(0, Rig.hover, 0) + Kill[2])\n\t                                    Safe = not workspace:GetPartsInPart(Probe, KillOverlap)[1]\n\t                                end\n\t                                if Safe then\n\t                                    local Node = {\n\t                                        position = Hit.Position,\n\t                                        section = Section.i.Value,\n\t                                        spacing = Spacing,\n\t                                        links = {},\n\t                                        index = #Nodes + 1,\n\t                                        belt = CollectionService:HasTag(v, \"Conveyor\") and v.AssemblyLinearVelocity or nil,\n\t                                        finish = workspace:GetPartsInPart(Probe, FinishOverlap)[1] ~= nil\n\t                                    }\n\t                                    local Key: string = `{Hit.Position.X // 4},{Hit.Position.Y // 4},{Hit.Position.Z // 4}`\n\t                                    Cells[Key] = Cells[Key] or {}\n\t                                    table.insert(Cells[Key], Node)\n\t                                    table.insert(Nodes, Node)\n\t                                end\n\t                            end\n\t                            if os.clock() - Clock > 0.004 then\n\t                                task.wait()\n\t                                Clock = os.clock()\n\t                                if Current ~= Version then\n\t                                    Recorder:Disconnect()\n\t                                    return\n\t                                end\n\t                            end\n\t                        end\n\t                    end\n\t                    if Platform and Platform.samples[1] then\n\t                        Platforms[v] = Platform\n\t                    end\n\t                    if not Platform and (v:IsA(\"TrussPart\") and math.abs((v.Size.Y >= math.max(v.Size.X, v.Size.Z) and v.CFrame.UpVector or v.Size.X >= v.Size.Z and v.CFrame.RightVector or v.CFrame.LookVector).Y) > 0.85 or Half.Y <= 0.8) then\n\t                        local Key: string = `{math.floor(v.Position.X + 0.5)},{math.floor(v.Position.Z + 0.5)}`\n\t                        Rungs[Key] = Rungs[Key] or {}\n\t                        table.insert(Rungs[Key], {v.Position, Half, v:IsA(\"TrussPart\")})\n\t                    end\n\t                end\n\t            end\n\t        end\n\t    end\n\t\n\t    for _, Stack: {any} in Rungs do\n\t        table.sort(Stack, function(A, B)\n\t            return A[1].Y < B[1].Y\n\t        end)\n\t        local First: number = 1\n\t        for i: number, Rung: any in Stack do\n\t            local Gap: number? = Stack[i + 1] and Stack[i + 1][1].Y - Stack[i + 1][2].Y - Rung[1].Y - Rung[2].Y\n\t            if not Gap or Gap > 2.5 or Gap < 0.2 and not (Rung[3] and Stack[i + 1][3]) then\n\t                if i - First >= 2 or Rung[3] and Rung[1].Y + Rung[2].Y - Stack[First][1].Y + Stack[First][2].Y >= 4 then\n\t                    table.insert(Trusses, {position = Stack[First][1], half = Rung[2] * Vector3.new(1, 0, 1), bottom = Stack[First][1].Y - Stack[First][2].Y, top = Rung[1].Y + Rung[2].Y})\n\t                end\n\t                First = i + 1\n\t            end\n\t        end\n\t    end\n\t\n\t    for _, v: any in Nodes do\n\t        for CellX: number = v.position.X // 4 - 1, v.position.X // 4 + 1 do\n\t            for CellY: number = v.position.Y // 4 - 1, v.position.Y // 4 + 1 do\n\t                for CellZ: number = v.position.Z // 4 - 1, v.position.Z // 4 + 1 do\n\t                    for _, Other: any in Cells[`{CellX},{CellY},{CellZ}`] or {} do\n\t                        local Offset: Vector3 = Other.position - v.position\n\t                        local Flat: Vector3 = Offset * Vector3.new(1, 0, 1)\n\t                        if Other.index > v.index and math.abs(Offset.Y) <= math.max(1.2, Flat.Magnitude * math.sqrt(1 - Rig.slope * Rig.slope) / Rig.slope) and Flat.Magnitude > 0.1 and Flat.Magnitude <= math.max(v.spacing, Other.spacing) * 1.5 then\n\t                            local Hit: RaycastResult? = workspace:Raycast((v.position + Other.position) / 2 + Vector3.new(0, 1.5, 0), Vector3.new(0, -3, 0), Params)\n\t                            local Safe = Hit and Hit.Normal.Y > Rig.slope and (math.abs(Offset.Y) <= 1.2 or Hit.Normal.Y < 0.95)\n\t                            for _, Kill: {Vector3} in Rig.kills do\n\t                                if not Safe then\n\t                                    break\n\t                                end\n\t                                Probe.Size, Probe.CFrame = Kill[1], CFrame.lookAt(v.position, v.position + Flat) + Vector3.new(0, Rig.hover, 0) + Kill[2]\n\t                                Safe = not workspace:GetPartsInPart(Probe, KillOverlap)[1]\n\t                                Probe.CFrame += Offset\n\t                                Safe = Safe and not workspace:GetPartsInPart(Probe, KillOverlap)[1]\n\t                            end\n\t                            if Safe then\n\t                                table.insert(v.links, Other)\n\t                                table.insert(Other.links, v)\n\t                            end\n\t                        end\n\t                    end\n\t                end\n\t            end\n\t        end\n\t        if os.clock() - Clock > 0.004 then\n\t            task.wait()\n\t            Clock = os.clock()\n\t            if Current ~= Version then\n\t                Recorder:Disconnect()\n\t                return\n\t            end\n\t        end\n\t    end\n\t    Recorder:Disconnect()\n\t\n\t    local Island: number = 0\n\t    for _, v: any in Nodes do\n\t        local Directions: number = 0\n\t        for _, Link: any in v.links do\n\t            Directions = bit32.bor(Directions, bit32.lshift(1, math.floor(math.atan2(Link.position.Z - v.position.Z, Link.position.X - v.position.X) / math.pi * 4 + 8.5) % 8))\n\t        end\n\t        v.border = Directions ~= 255\n\t        if not v.island then\n\t            Island += 1\n\t            v.island = Island\n\t            local Queue, Head = {v}, 1\n\t            while Queue[Head] do\n\t                for _, Link: any in Queue[Head].links do\n\t                    if not Link.island then\n\t                        Link.island = Island\n\t                        table.insert(Queue, Link)\n\t                    end\n\t                end\n\t                Head += 1\n\t            end\n\t        end\n\t    end\n\t\n\t    for _, v: any in Platforms do\n\t        local Total: Vector3 = Vector3.zero\n\t        for _, Frame: CFrame in v.track do\n\t            for i: number, Sample: Vector3 in v.samples do\n\t                if i % math.ceil(#v.samples / 5) == 0 then\n\t                    table.insert(v.swept, Frame * Sample)\n\t                    Total += Frame * Sample\n\t                end\n\t            end\n\t        end\n\t        v.node.position = v.swept[1] and Total / #v.swept or v.part.Position\n\t    end\n\t\n\t    return Current == Version\n\tend\n\t\n\tlocal function GetJumps(Node)\n\t    local Candidates, Counts = {}, {}\n\t    Node.jumps = {}\n\t    for i: number, v: Vector3 in Node.platform and Node.platform.swept or {Node.position} do\n\t        if i % 3 == 1 or not Node.platform then\n\t            for CellX: number = v.X // 4 - 4, v.X // 4 + 4 do\n\t                for CellY: number = (v.Y - 12) // 4, (v.Y + 10) // 4 do\n\t                    for CellZ: number = v.Z // 4 - 4, v.Z // 4 + 4 do\n\t                        for _, Other: any in Cells[`{CellX},{CellY},{CellZ}`] or {} do\n\t                            if Other.island ~= Node.island and ((Other.position - v) * Vector3.new(1, 0, 1)).Magnitude <= 14 then\n\t                                table.insert(Candidates, {Other, ((Other.position - v) * Vector3.new(1, 0, 1)).Magnitude, v, Other.position})\n\t                            end\n\t                        end\n\t                    end\n\t                end\n\t            end\n\t            for _, Platform: any in Platforms do\n\t                if Platform.node ~= Node then\n\t                    for _, Swept: Vector3 in Platform.swept do\n\t                        if Swept.Y - v.Y > -12 and Swept.Y - v.Y < 10 and ((Swept - v) * Vector3.new(1, 0, 1)).Magnitude <= 14 then\n\t                            table.insert(Candidates, {Platform.node, ((Swept - v) * Vector3.new(1, 0, 1)).Magnitude, v, Swept})\n\t                        end\n\t                    end\n\t                end\n\t            end\n\t        end\n\t    end\n\t    table.sort(Candidates, function(A, B)\n\t        return A[2] < B[2]\n\t    end)\n\t\n\t    for _, v: any in Trusses do\n\t        local Reach: number = (((Node.position - v.position) * Vector3.new(1, 0, 1)):Abs() - v.half):Max(Vector3.zero).Magnitude\n\t        if not Node.platform and Reach <= 7.5 and Node.position.Y > v.bottom - 6 and Node.position.Y < v.top - 1 then\n\t            for CellX: number = (v.position.X - v.half.X - 4) // 4, (v.position.X + v.half.X + 4) // 4 do\n\t                for CellY: number = Node.position.Y // 4, (v.top + 2) // 4 do\n\t                    for CellZ: number = (v.position.Z - v.half.Z - 4) // 4, (v.position.Z + v.half.Z + 4) // 4 do\n\t                        for _, Other: any in Cells[`{CellX},{CellY},{CellZ}`] or {} do\n\t                            local Count = Counts[Other.island] or {0, 0, {}}\n\t                            Counts[Other.island] = Count\n\t                            if Count[1] < 2 and Other.island ~= Node.island and Other.position.Y > Node.position.Y + 1.5 and Other.position.Y < v.top + 2.5 and (((Other.position - v.position) * Vector3.new(1, 0, 1)):Abs() - v.half):Max(Vector3.zero).Magnitude <= 3.5 then\n\t                                Count[1] += 1\n\t                                table.insert(Node.jumps, {from = Node, node = Other, time = (Other.position.Y - Node.position.Y) / (Rig.speed * 0.7) + Reach / Rig.speed + 1, delay = 0, jump = 0, climb = v})\n\t                            end\n\t                        end\n\t                    end\n\t                end\n\t            end\n\t        end\n\t    end\n\t\n\t    for _, v: any in Candidates do\n\t        local Dynamic = Node.platform or v[1].platform\n\t        local Count = Counts[v[1].island] or {0, 0, {}}\n\t        Counts[v[1].island] = Count\n\t        local Fresh: boolean = true\n\t        for _, Used: Vector3 in Count[3] do\n\t            Fresh = Fresh and (Used - v[4]).Magnitude > 1.5\n\t        end\n\t        if Count[1] < 2 and Count[2] < (Dynamic and 12 or 8) and Fresh then\n\t            Count[2] += 1\n\t            table.insert(Count[3], v[4])\n\t            local Offset: Vector3 = v[4] - v[3]\n\t            local Direction: Vector3 = Offset * Vector3.new(1, 0, 1)\n\t            Direction = Direction.Magnitude > 0.01 and Direction.Unit or Vector3.zAxis\n\t            local Edge: number = Node.platform and 0 or GetRunway(v[3], Direction, v[2] - 0.5)\n\t            local Origin: Vector3 = v[3] + Direction * Edge + Vector3.new(0, Rig.hover, 0)\n\t            Offset -= Direction * Edge\n\t            local Land, Lip = 0, false\n\t            if not v[1].platform then\n\t                Land, Lip = GetRunway(v[4], -Direction, (Offset * Vector3.new(1, 0, 1)).Magnitude - 0.5)\n\t            end\n\t            Offset -= Direction * (Land + (Lip and 0.35 or 0))\n\t            local Flat: Vector3 = Offset * Vector3.new(1, 0, 1)\n\t            local Facing: CFrame = CFrame.lookAt(Vector3.zero, Direction)\n\t            local Move, Found, Safe = Flat.Magnitude / Rig.speed, nil, true\n\t            for _, Kill: {Vector3} in Rig.kills do\n\t                Probe.Size, Probe.CFrame = Kill[1], Facing + Origin + Kill[2]\n\t                Safe = Safe and (Node.platform or not workspace:GetPartsInPart(Probe, KillOverlap)[1])\n\t            end\n\t            for _, Jump: number in {Rig.jump, 0} do\n\t                if Safe and not Found and Jump * Jump - 2 * Rig.gravity * (Offset.Y - Rig.lift + 0.1) >= 0 and (Jump > 0 or Offset.Y < -1) then\n\t                    local Time: number = (Jump + math.sqrt(Jump * Jump - 2 * Rig.gravity * (Offset.Y - Rig.lift))) / Rig.gravity\n\t                    local Stop: number = math.min(Time, Jump * Jump - 2 * Rig.gravity * (Offset.Y + 0.3) >= 0 and (Jump + math.sqrt(Jump * Jump - 2 * Rig.gravity * (Offset.Y + 0.3))) / Rig.gravity or Time)\n\t                    if Dynamic and Move <= Time - 0.05 then\n\t                        Found = {from = Node, node = v[1], time = Time, delay = 0, jump = Jump, takeoff = Edge}\n\t                    elseif not Dynamic then\n\t                        local Bends, BendIndex = {Origin + Flat / 2}, 1\n\t                        while Bends[BendIndex] and not Found do\n\t                            local Bend: Vector3 = Bends[BendIndex]\n\t                            local First, Second = Bend - Origin, Origin + Flat - Bend\n\t                            local Length: number = First.Magnitude + Second.Magnitude\n\t                            if Length / Rig.speed <= Time - 0.02 then\n\t                                for _, StartDelay: number in Jump > 0 and {math.max(Time - Length / Rig.speed - 0.06, 0), 0} or {0} do\n\t                                    local Last, Clear = Origin, true\n\t                                    for i: number = 1, math.ceil(Stop / 0.04) do\n\t                                        local Elapsed: number = math.min(i * 0.04, Stop)\n\t                                        local Travelled: number = math.clamp((Elapsed - StartDelay) * Rig.speed, 0, Length)\n\t                                        local Segment: Vector3 = Travelled < First.Magnitude and First or Second\n\t                                        local Turn: CFrame = CFrame.lookAt(Vector3.zero, Segment.Magnitude > 0.01 and Segment or Direction)\n\t                                        local Point: Vector3 = (Travelled < First.Magnitude and Origin + (First.Magnitude > 0.01 and First.Unit or Vector3.zero) * Travelled or Bend + (Second.Magnitude > 0.01 and Second.Unit or Vector3.zero) * (Travelled - First.Magnitude)) + Vector3.new(0, Jump * Elapsed - Rig.gravity * Elapsed * Elapsed / 2, 0)\n\t                                        local Hit = (Point - Last).Magnitude > 0.001 and workspace:Blockcast(CFrame.new(Last + Rig.offset), Rig.size, Point - Last, Params)\n\t                                        if Hit and BendIndex == 1 and not Bends[2] and math.max(Hit.Instance.Size.X, Hit.Instance.Size.Z) <= 24 then\n\t                                            for _, Sign: Vector3 in {Vector3.new(1, 0, 1), Vector3.new(1, 0, -1), Vector3.new(-1, 0, 1), Vector3.new(-1, 0, -1)} do\n\t                                                local Corner: Vector3 = Hit.Instance.CFrame * (Hit.Instance.Size / 2 * Sign + Sign * 1.3)\n\t                                                table.insert(Bends, Vector3.new(Corner.X, Origin.Y, Corner.Z))\n\t                                            end\n\t                                            for _, EndPoint: Vector3 in {Origin, Origin + Flat} do\n\t                                                local Pad: Vector3 = Hit.Instance.Size / 2 + Vector3.new(1.3, 0, 1.3)\n\t                                                local Relative: Vector3 = Hit.Instance.CFrame:PointToObjectSpace(EndPoint)\n\t                                                Relative = Vector3.new(math.clamp(Relative.X, -Pad.X, Pad.X), 0, math.clamp(Relative.Z, -Pad.Z, Pad.Z))\n\t                                                local Outline: Vector3 = Hit.Instance.CFrame * (Pad.X - math.abs(Relative.X) < Pad.Z - math.abs(Relative.Z) and Vector3.new(Relative.X >= 0 and Pad.X or -Pad.X, 0, Relative.Z) or Vector3.new(Relative.X, 0, Relative.Z >= 0 and Pad.Z or -Pad.Z))\n\t                                                table.insert(Bends, Vector3.new(Outline.X, Origin.Y, Outline.Z))\n\t                                            end\n\t                                        end\n\t                                        if Hit or (Point - Last).Magnitude > 0.001 and (workspace:Blockcast(Turn + Last + Rig.kills[1][2], Rig.kills[1][1], Point - Last, KillParams) or workspace:Blockcast(Turn + Last + Rig.kills[2][2], Rig.kills[2][1], Point - Last, KillParams)) then\n\t                                            Clear = false\n\t                                            break\n\t                                        end\n\t                                        Last = Point\n\t                                    end\n\t                                    if Clear then\n\t                                        Found = {from = Node, node = v[1], time = Time, delay = StartDelay, jump = Jump, takeoff = Edge, bend = BendIndex > 1 and Bend - Vector3.new(0, Rig.hover, 0) or nil}\n\t                                        break\n\t                                    end\n\t                                end\n\t                            end\n\t                            BendIndex += 1\n\t                        end\n\t                    end\n\t                end\n\t            end\n\t            if Found then\n\t                Count[1] += 1\n\t                table.insert(Node.jumps, Found)\n\t            end\n\t        end\n\t    end\n\t\n\t    return Node.jumps\n\tend\n\t\n\tlocal function GetPath(Start, Goals)\n\t    local Current, Target = Version, Sections[Start.section + 1] and Sections[Start.section + 1]:FindFirstChild(\"start\")\n\t    Target = Target and Target.Position or workspace.tower.finishes:GetPivot().Position\n\t    local Heap, Costs, Parents, Closed, Clock, Count = {{Start, 0}}, {[Start] = 0}, {}, {}, os.clock(), 0\n\t    while Heap[1] and Current == Version and Count < 60000 do\n\t        local Node = Pop(Heap)[1]\n\t        if not Closed[Node] then\n\t            Closed[Node] = true\n\t            if Node.section > Start.section or Node.finish or Goals and Goals[Node] then\n\t                local List = {}\n\t                while Parents[Node] do\n\t                    table.insert(List, 1, Parents[Node])\n\t                    Node = Parents[Node].from\n\t                end\n\t                return List\n\t            end\n\t\n\t            for _, v: any in Node.links do\n\t                local Flat: Vector3 = (v.position - Node.position) * Vector3.new(1, 0, 1)\n\t                local Speed: number = Rig.speed + (Node.belt and Node.belt:Dot(Flat.Unit) or 0)\n\t                local Cost: number = Costs[Node] + Flat.Magnitude / math.max(Speed, 0.1)\n\t                if Speed > 3 and Cost < (Costs[v] or math.huge) and (Blocked[`{Node.index},{v.index}`] or 0) < 2 then\n\t                    Costs[v], Parents[v] = Cost, {from = Node, node = v, time = Flat.Magnitude / Speed}\n\t                    Push(Heap, {v, Cost + (Target - v.position).Magnitude / Rig.speed * 2})\n\t                end\n\t            end\n\t            if Node.border then\n\t                for _, v: any in Node.jumps or GetJumps(Node) do\n\t                    local Cost: number = Costs[Node] + v.time + ((Node.platform or v.node.platform) and 1.5 or 0.3)\n\t                    if Cost < (Costs[v.node] or math.huge) and (Blocked[`{Node.index},{v.node.index}`] or 0) < 2 then\n\t                        Costs[v.node], Parents[v.node] = Cost, v\n\t                        Push(Heap, {v.node, Cost + (Target - v.node.position).Magnitude / Rig.speed * 2})\n\t                    end\n\t                end\n\t            end\n\t\n\t            Count += 1\n\t            if os.clock() - Clock > 0.004 then\n\t                task.wait()\n\t                Clock = os.clock()\n\t            end\n\t        end\n\t    end\n\t\n\t    return nil\n\tend\n\t\n\tlocal function GetDemo(Samples, Feet: Vector3)\n\t    local List, Index, Distance = {}, nil, 24\n\t    local function Anchor(Sample, Position: Vector3, Name: string, Snap: boolean?)\n\t        for Part: BasePart, v: CFrame in Sample.frames or {} do\n\t            if Platforms[Part] and (v:PointToObjectSpace(Position):Abs() - Part.Size / 2):Max(Vector3.zero).Magnitude < 1.5 then\n\t                return {position = Position, index = Name, part = Part, frame = v, offset = v:PointToObjectSpace(Position)}\n\t            end\n\t        end\n\t        if Snap and not workspace:Raycast(Position + Vector3.new(0, 1, 0), Vector3.new(0, -3.5, 0), Params) then\n\t            local Best, BestDistance = nil, 2.5\n\t            for CellX: number = Position.X // 4 - 1, Position.X // 4 + 1 do\n\t                for CellY: number = Position.Y // 4 - 1, Position.Y // 4 do\n\t                    for CellZ: number = Position.Z // 4 - 1, Position.Z // 4 + 1 do\n\t                        for _, v: any in Cells[`{CellX},{CellY},{CellZ}`] or {} do\n\t                            local Flat: number = ((v.position - Position) * Vector3.new(1, 0, 1)).Magnitude\n\t                            if Flat < BestDistance and v.position.Y > Position.Y - 3.5 and v.position.Y < Position.Y + 1 then\n\t                                Best, BestDistance = v, Flat\n\t                            end\n\t                        end\n\t                    end\n\t                end\n\t            end\n\t            Position = Best and Best.position or Position\n\t        end\n\t        return {position = Position, index = Name}\n\t    end\n\t    for SampleIndex: number, v: any in Samples do\n\t        local Offset: Vector3 = v.position - Vector3.new(0, Rig.hover, 0) - Feet\n\t        if v.grounded and math.abs(Offset.Y) < 3 and (Offset * Vector3.new(1, 0, 1)).Magnitude < 4 then\n\t            Index = SampleIndex\n\t        end\n\t    end\n\t    if not Index then\n\t        for SampleIndex: number, v: any in Samples do\n\t            local Offset: Vector3 = v.position - Vector3.new(0, Rig.hover, 0) - Feet\n\t            if v.grounded and math.abs(Offset.Y) < 3 and (Offset * Vector3.new(1, 0, 1)).Magnitude < Distance and workspace:Blockcast(CFrame.new(Feet + Offset * 0.5 + Vector3.new(0, 1, 0)), Vector3.new(Rig.size.X, 0.2, Rig.size.Z), Vector3.new(0, -4, 0), Params) then\n\t                Index, Distance = SampleIndex, (Offset * Vector3.new(1, 0, 1)).Magnitude\n\t            end\n\t        end\n\t    end\n\t    if not Index then\n\t        return nil\n\t    end\n\t\n\t    local Last: Vector3 = Feet\n\t    while Samples[Index] do\n\t        local Finish: number = Index\n\t        while Samples[Finish] and not Samples[Finish].grounded do\n\t            Finish += 1\n\t        end\n\t        if not Samples[Finish] then\n\t            break\n\t        end\n\t\n\t        local Rise: number = math.max(Index - 1, 1)\n\t        for SampleIndex: number = Rise, Finish - 1 do\n\t            if Samples[SampleIndex + 1].position.Y - Samples[SampleIndex].position.Y > 0.5 then\n\t                Rise = SampleIndex\n\t                break\n\t            end\n\t        end\n\t        while Rise > Index and not workspace:Blockcast(CFrame.new(Samples[Rise].position - Vector3.new(0, Rig.hover - 1, 0)), Vector3.new(Rig.size.X, 0.2, Rig.size.Z), Vector3.new(0, -3.5, 0), Params) do\n\t            Rise -= 1\n\t        end\n\t        local Takeoff, Landing = Samples[Rise].position - Vector3.new(0, Rig.hover, 0), Samples[Finish].position - Vector3.new(0, Rig.hover, 0)\n\t        for _, v: any in Trusses do\n\t            if v.bottom < Landing.Y + 1 and v.top > Landing.Y and (((Landing - v.position) * Vector3.new(1, 0, 1)):Abs() - v.half):Max(Vector3.zero).Magnitude < 2.5 and not workspace:Raycast(Landing + Vector3.new(0, 0.5, 0), Vector3.new(0, -1.5, 0), Params) then\n\t                Landing = Vector3.new(v.position.X, Landing.Y, v.position.Z) + ((Landing - v.position) * Vector3.new(1, 0, 1)):Max(-v.half):Min(v.half)\n\t            end\n\t        end\n\t        local Line, Duration = (Landing - Takeoff) * Vector3.new(1, 0, 1), Samples[Finish].time - Samples[Rise].time\n\t        local Apex, Spread, Climb = Takeoff.Y, 0, nil\n\t        for SampleIndex: number = Index, Finish do\n\t            local Offset: Vector3 = (Samples[SampleIndex].position - Vector3.new(0, Rig.hover, 0) - Takeoff) * Vector3.new(1, 0, 1)\n\t            Apex, Spread = math.max(Apex, Samples[SampleIndex].position.Y - Rig.hover), math.max(Spread, Offset.Magnitude)\n\t        end\n\t        for _, v: any in Trusses do\n\t            if Finish > Index and Landing.Y - Takeoff.Y > 4 and v.bottom < Landing.Y and v.top > Takeoff.Y and (Spread < 3 and (((Samples[(Index + Finish) // 2].position - v.position) * Vector3.new(1, 0, 1)):Abs() - v.half):Max(Vector3.zero).Magnitude < 3 or Landing.Y - Takeoff.Y > Rig.jump * Rig.jump / Rig.gravity / 2 + Rig.lift and (((Landing - v.position) * Vector3.new(1, 0, 1)):Abs() - v.half):Max(Vector3.zero).Magnitude < 3) then\n\t                Climb = v\n\t            end\n\t        end\n\t\n\t        if Climb or Finish > Index and Duration <= 1.6 and Line.Magnitude <= 14 and Line.Magnitude <= Rig.speed * Duration + 2 then\n\t            for SampleIndex: number = Index, Rise do\n\t                local Position: Vector3 = Samples[SampleIndex].position - Vector3.new(0, Rig.hover, 0)\n\t                if (Position - Last).Magnitude >= 2 then\n\t                    local Offset: Vector3 = (Position - Last) * Vector3.new(1, 0, 1)\n\t                    table.insert(List, Offset.Magnitude > 0.1 and workspace:Blockcast(CFrame.lookAt(Last, Last + Offset) + Vector3.new(0, Rig.hover, 0) + Rig.kills[1][2], Rig.kills[1][1], Position - Last, KillParams) and {from = Anchor(Samples[SampleIndex], Last, `hop{SampleIndex}`, true), node = Anchor(Samples[SampleIndex], Position, `demo{SampleIndex}`, true), time = 0.6, delay = 0, jump = Rig.jump, takeoff = 0} or {node = Anchor(Samples[SampleIndex], Position, `demo{SampleIndex}`, true), time = (Position - Last).Magnitude / Rig.speed})\n\t                    Last = Position\n\t                end\n\t            end\n\t            local Nearby, Phase = {}, {}\n\t            for Part: BasePart, v: CFrame in Samples[Rise].frames or {} do\n\t                local Along: number = math.clamp((v.Position - Takeoff):Dot(Landing - Takeoff) / math.max((Landing - Takeoff).Magnitude ^ 2, 0.001), 0, 1)\n\t                local Gap: number = (v.Position - Takeoff:Lerp(Landing, Along)).Magnitude - Part.Size.Magnitude / 2\n\t                if Gap < 6 then\n\t                    table.insert(Nearby, {Part, v, Gap})\n\t                end\n\t            end\n\t            table.sort(Nearby, function(A, C)\n\t                return A[3] < C[3]\n\t            end)\n\t            for Rank: number, v: any in Nearby do\n\t                if Rank > 2 then\n\t                    break\n\t                end\n\t                Phase[v[1]] = v[2]\n\t            end\n\t            local Jump, JumpDelay, AirPath = not Climb and Apex > Takeoff.Y + 1 and Rig.jump or 0, 0, {}\n\t            if Jump > 0 and Samples[Rise + 1] then\n\t                local Airtime: number = (Jump - math.sqrt(math.max(Jump * Jump - 2 * Rig.gravity * math.max(Samples[Rise + 1].position.Y - Samples[Rise].position.Y, 0), 0))) / Rig.gravity\n\t                local Gap: number = math.max(Samples[Rise + 1].time - Samples[Rise].time, 0.001)\n\t                local LaunchTime: number = Samples[Rise + 1].time - math.min(Airtime, Gap)\n\t                Takeoff = Vector3.new(0, Takeoff.Y, 0) + Samples[Rise].position:Lerp(Samples[Rise + 1].position, 1 - math.min(Airtime, Gap) / Gap) * Vector3.new(1, 0, 1)\n\t                JumpDelay = ((Samples[Rise + 1].position - Samples[Rise].position) * Vector3.new(1, 0, 1)).Magnitude / Gap < 6 and 0.06 or 0\n\t                table.insert(AirPath, {0, Takeoff * Vector3.new(1, 0, 1)})\n\t                for SampleIndex: number = Rise + 1, Finish do\n\t                    table.insert(AirPath, {Samples[SampleIndex].time - LaunchTime, Samples[SampleIndex].position * Vector3.new(1, 0, 1)})\n\t                end\n\t            end\n\t            local From, Node, Edge = Anchor(Samples[Rise], Takeoff, `demo{Rise}`, true), Anchor(Samples[Finish], Landing, `demo{Finish}`), 0\n\t            local Direction: Vector3 = (Landing - From.position) * Vector3.new(1, 0, 1)\n\t            for Nudge: number = 1, Jump > 0 and not From.part and Direction.Magnitude > 2 and 6 or 0 do\n\t                local Point: Vector3 = From.position + Direction.Unit * (Nudge * 0.25)\n\t                Probe.Size, Probe.CFrame = Rig.kills[1][1], CFrame.lookAt(Vector3.zero, Direction) + Point + Vector3.new(0, Rig.hover, 0) + Rig.kills[1][2]\n\t                if not workspace:Raycast(Point + Vector3.new(0, 0.5, 0), Vector3.new(0, -1.5, 0), Params) or workspace:GetPartsInPart(Probe, KillOverlap)[1] then\n\t                    break\n\t                end\n\t                Edge = Nudge * 0.25\n\t            end\n\t            table.insert(List, {from = From, node = Node, time = Duration, delay = JumpDelay, jump = Jump, takeoff = Edge, path = AirPath[2] and not From.part and not Node.part and AirPath or nil, climb = Climb, phase = Nearby[1] and Phase or nil})\n\t            Last = Landing\n\t        else\n\t            for SampleIndex: number = Index, Finish do\n\t                local Position: Vector3 = Samples[SampleIndex].position - Vector3.new(0, Rig.hover, 0)\n\t                if (Position - Last).Magnitude >= 2 then\n\t                    local Offset: Vector3 = (Position - Last) * Vector3.new(1, 0, 1)\n\t                    table.insert(List, Offset.Magnitude > 0.1 and workspace:Blockcast(CFrame.lookAt(Last, Last + Offset) + Vector3.new(0, Rig.hover, 0) + Rig.kills[1][2], Rig.kills[1][1], Position - Last, KillParams) and {from = Anchor(Samples[SampleIndex], Last, `hop{SampleIndex}`, true), node = Anchor(Samples[SampleIndex], Position, `demo{SampleIndex}`, true), time = 0.6, delay = 0, jump = Rig.jump, takeoff = 0} or {node = Anchor(Samples[SampleIndex], Position, `demo{SampleIndex}`, true), time = (Position - Last).Magnitude / Rig.speed})\n\t                    Last = Position\n\t                end\n\t            end\n\t        end\n\t        Index = Finish + 1\n\t    end\n\t\n\t    return List[1] and List or nil\n\tend\n\t\n\tlocal function GetDanger(From: Vector3, To: Vector3, Duration: number, Jump: number?)\n\t    for Part: BasePart in Hazards do\n\t        if Part.Parent and ((Part.Position - From) * Vector3.new(1, 0, 1)).Magnitude < (To - From).Magnitude + Part.Size.Magnitude / 2 + 12 then\n\t            local Center, Angular = Hazards[Part].center, Hazards[Part].angular\n\t            for Slice: number = 0, 8 do\n\t                local Elapsed: number = Duration * Slice / 8\n\t                local Frame: CFrame = CFrame.new(Center + Hazards[Part].linear * Elapsed) * CFrame.fromAxisAngle(Angular.Magnitude > 0.0001 and Angular.Unit or Vector3.yAxis, Angular.Magnitude * Elapsed) * (Part.CFrame - Center)\n\t                local Point: Vector3 = From:Lerp(To, Slice / 8)\n\t                if Jump then\n\t                    local Height: number = From.Y + Jump * Elapsed - Rig.gravity * Elapsed * Elapsed / 2\n\t                    Point = Vector3.new(Point.X, Elapsed > Jump / Rig.gravity and math.max(Height, To.Y) or Height, Point.Z)\n\t                end\n\t                for _, v: number in {1.5, 0, -1.5, -2.8} do\n\t                    if (Frame:PointToObjectSpace(Point + Vector3.new(0, v, 0)):Abs() - Part.Size / 2):Max(Vector3.zero).Magnitude < 1.2 then\n\t                        return true, v < 0\n\t                    end\n\t                end\n\t            end\n\t        end\n\t    end\n\t\n\t    return false, false\n\tend\n\t\n\tAutoPlay = vape.Categories.Utility:CreateModule({\n\t    Name = \"AutoPlay\",\n\t    Function = function(Callback: boolean)\n\t        if Callback then\n\t            Folder = Instance.new(\"Folder\")\n\t            Folder.Name = \"catvapetower\"\n\t            Folder.Parent = workspace\n\t            Probe = Instance.new(\"Part\")\n\t            Probe.Anchored = true\n\t            for i: number = 1, 80 do\n\t                local Part: Part = Instance.new(\"Part\")\n\t                Part.Anchored = true\n\t                Part.CanCollide = false\n\t                Part.CanQuery = false\n\t                Part.CanTouch = false\n\t                Part.Color = Color3.fromHSV(Color.Hue, Color.Sat, Color.Value)\n\t                Part.Material = Enum.Material.Neon\n\t                Part.Shape = Enum.PartType.Ball\n\t                Part.Size = Vector3.new(0.5, 0.5, 0.5)\n\t                Part.Transparency = 1\n\t                Part.Parent = Folder\n\t                Parts[i] = Part\n\t            end\n\t\n\t            Old = TowerOfHell.Controls.moveFunction\n\t            TowerOfHell.Controls.moveFunction = function(self, Vector: Vector3, Face: boolean)\n\t                return Old(self, Movement or Vector3.zero, false)\n\t            end\n\t\n\t            AutoPlay:Clean(LocalPlayer.CharacterAdded:Connect(function()\n\t                Route, Launched = nil, nil\n\t            end))\n\t            AutoPlay:Clean(RunService.Heartbeat:Connect(function()\n\t                if not Rig or os.clock() - Sampled < 0.066 then\n\t                    return\n\t                end\n\t                if os.clock() - Checked > 0.5 then\n\t                    Checked = os.clock()\n\t                    for Part: BasePart, v: CFrame in Watched do\n\t                        if (Part.Position - v.Position).Magnitude > 0.05 or Part.CFrame.LookVector:Dot(v.LookVector) < 0.9999 then\n\t                            Hazards[Part], Watched[Part] = {part = Part, linear = Vector3.zero, angular = Vector3.zero, center = Part.Position}, nil\n\t                        end\n\t                    end\n\t                end\n\t                Sampled = os.clock()\n\t                local Frames: {[BasePart]: CFrame} = {}\n\t                for Part: BasePart in Hazards do\n\t                    Frames[Part] = Part.CFrame\n\t                end\n\t                for Part: BasePart in Platforms do\n\t                    Frames[Part] = Part.CFrame\n\t                end\n\t                for _, v: Player in Players:GetPlayers() do\n\t                    local Root = v ~= LocalPlayer and v.Character and v.Character:FindFirstChild(\"HumanoidRootPart\")\n\t                    local Section = Root and v.Character:FindFirstChild(\"currentSection\")\n\t                    if Section then\n\t                        local Track = Tracks[v] or {}\n\t                        local Last, Entrance = Track[#Track], Track[1] and Sections[Track[1].section] and Sections[Track[1].section]:FindFirstChild(\"start\")\n\t                        Tracks[v] = Track\n\t                        if Last and Entrance and Section.Value == Last.section + 1 and (Root.Position - Last.position).Magnitude < 25 and #Track > (Last.time - Track[1].time) * 8 and Track[1].position.Y - Rig.hover > Entrance.Position.Y - 2 then\n\t                            local Valid, Rising = Last.time - Track[1].time > 1.5, 0\n\t                            for i: number = 2, #Track do\n\t                                Rising = Track[i].velocity > 30 and Rising + 1 or 0\n\t                                if Rising >= 3 or ((Track[i].position - Track[i - 1].position) * Vector3.new(1, 0, 1)).Magnitude / math.max(T