ines.Events[Frontlines.Main.exe_func_t.INIT_TPV_SOL_JOINTS](Id)\n\t                    Frontlines.Events[Frontlines.Main.exe_func_t.INIT_TPV_SOL_EQUIPMENT_JOINTS](Id, Gun)\n\t                    Frontlines.Events[Frontlines.Main.exe_func_t.SET_SOLDIER_ANIMATION_VALUES](Id, Gun)\n\t                    Actor.main.alive.Value = true\n\t                end\n\t\n\t                for _, v: BasePart in Ent.Character:GetDescendants() do\n\t                    if v:IsA(\"BasePart\") then\n\t                        v.LocalTransparencyModifier = v.Parent ~= Ent.Character and 1 or 0\n\t                    end\n\t                end\n\t            end))\n\t        else\n\t            if Entity.isAlive then\n\t                local Character: Model = Entity.character.Character\n\t                for _, v: BasePart in Character:GetDescendants() do\n\t                    if v:IsA(\"BasePart\") then\n\t                        v.LocalTransparencyModifier = v.Parent ~= Character and 0 or 1\n\t                    end\n\t                end\n\t            end\n\t        end\n\t    end,\n\t    Tooltip = \"View your character in third person\"\n\t})\n\tDistance = ThirdPerson:CreateSlider({\n\t    Name = \"Distance\",\n\t    Min = 1,\n\t    Max = 15,\n\t    Default = 8\n\t})\nend)\n\nRun(function()\n\tlocal AutoRespawn\n\t\n\tAutoRespawn = vape.Categories.Utility:CreateModule({\n\t    Name = \"AutoRespawn\",\n\t    Function = function(Callback: boolean)\n\t        if Callback then\n\t            AutoRespawn:Clean(HookEvent(\"ENTER_CLI_KILLCAM\", function(Id, Health: number)\n\t                task.delay(0, function()\n\t                    Frontlines.Main.exe_set(Frontlines.Main.exe_set_t.CTRL_KILLCAM_TO_COMBAT_RELEASE)\n\t                end)\n\t            end))\n\t        end\n\t    end,\n\t    Tooltip = \"Automatically respawns after death\"\n\t})\nend)\n\nRun(function()\n\tlocal ChatSpammer\n\tlocal Lines\n\tlocal Mode\n\tlocal Delay\n\tlocal Hide\n\tlocal OldChat\n\t\n\tChatSpammer = vape.Categories.Utility:CreateModule({\n\t    Name = \"ChatSpammer\",\n\t    Function = function(Callback: boolean)\n\t        if Callback then\n\t            local Index: number = 1\n\t            repeat\n\t                local Message: string = (#Lines.ListEnabled > 0 and Lines.ListEnabled[math.random(1, #Lines.ListEnabled)] or \"vxpe on top\")\n\t                if Mode.Value == \"Order\" and #Lines.ListEnabled > 0 then\n\t                    Message = Lines.ListEnabled[Index] or Lines.ListEnabled[1]\n\t                    Index += 1\n\t                    if Index > #Lines.ListEnabled then\n\t                        Index = 1\n\t                    end\n\t                end\n\t                Frontlines.Main.utils.net_msg_util.c_prep_net_msg(Frontlines.Main.globals.null_net_msg_state, Frontlines.Main.enums.c_net_msg.CHAT, Message:sub(1, 100))\n\t                task.wait(1)\n\t            until not ChatSpammer.Enabled\n\t        end\n\t    end,\n\t    Tooltip = \"Automatically types in chat\"\n\t})\n\tLines = ChatSpammer:CreateTextList({Name = \"Lines\"})\n\tMode = ChatSpammer:CreateDropdown({\n\t    Name = \"Mode\",\n\t    List = {\"Random\", \"Order\"}\n\t})\nend)\n\nRun(function()\n\tlocal PickupRange\n\tlocal Range\n\t\n\tPickupRange = vape.Categories.Utility:CreateModule({\n\t    Name = \"PickupRange\",\n\t    Function = function(Callback: boolean)\n\t        if Callback then\n\t            repeat\n\t                if Entity.isAlive then\n\t                    for _, v: number in Frontlines.Main.globals.equipment_drop_ids do\n\t                        local Equipment = Frontlines.Main.globals.equipments[v]\n\t                        if Equipment and Equipment.model and Equipment.model.PrimaryPart and (Equipment.model.PrimaryPart.Position - Entity.character.RootPart.Position).Magnitude < Range.Value then\n\t                            if Frontlines.Main.matrix_bit(Frontlines.PickupBit, v) == 0 then\n\t                                Frontlines.Main.set_matrix_bit(Frontlines.PickupBit, v, true)\n\t                                Frontlines.Main.utils.net_msg_util.c_prep_net_msg(Frontlines.Main.globals.combat_net_msg_state, Frontlines.Main.enums.c_net_msg.PICKUP_AMMO, v)\n\t                                break\n\t                            end\n\t                        end\n\t                    end\n\t                end\n\t\n\t                task.wait(0.05)\n\t            until not PickupRange.Enabled\n\t        end\n\t    end,\n\t    Tooltip = \"Picks up ammo from dropped guns in the proximity\"\n\t})\n\tRange = PickupRange:CreateSlider({\n\t    Name = \"Range\",\n\t    Min = 1,\n\t    Max = 20,\n\t    Default = 20\n\t})\nend)\n\nRun(function()\n\tlocal BulletTracers\n\tlocal Material\n\tlocal Color\n\tlocal Lifetime\n\tlocal Fade\n\tlocal DrawingToggle\n\tlocal DrawingObjects = {}\n\t\n\tBulletTracers = vape.Legit:CreateModule({\n\t    Name = \"BulletTracers\",\n\t    Category = \"Game\",\n\t    Icon = GetVapeAsset(`{vape.Directory}/assets/new/legit_bullettracers.png`),\n\t    Function = function(Callback: boolean)\n\t        if Callback then\n\t            BulletTracers:Clean(HookEvent(\"SPAWN_FPV_SOL_BULLET\", function(Id, BulletType, Origin: Vector3, Velocity: Vector3)\n\t                if DrawingToggle.Enabled then\n\t                    local Line = Drawing.new(\"Line\")\n\t                    Line.Color = Color3.fromHSV(Color.Hue, Color.Sat, Color.Value)\n\t                    DrawingObjects[Line] = {Origin, Origin + (Velocity.Unit * 1000), tick()}\n\t                    task.delay(Lifetime.Value, function()\n\t                        DrawingObjects[Line] = nil\n\t                        Line.Visible = false\n\t                        Line:Remove()\n\t                    end)\n\t                else\n\t                    local Tracer: Part = Instance.new(\"Part\")\n\t                    Tracer.Size = Vector3.new(0.05, 0.05, 1000)\n\t                    Tracer.CFrame = CFrame.lookAt(Origin + (Velocity.Unit * 500), Origin + (Velocity.Unit * 1000))\n\t                    Tracer.CanCollide = false\n\t                    Tracer.CanQuery = false\n\t                    Tracer.Anchored = true\n\t                    Tracer.Material = Enum.Material[Material.Value]\n\t                    Tracer.Color = Color3.fromHSV(Color.Hue, Color.Sat, Color.Value)\n\t                    Tracer.Transparency = 1 - Color.Opacity\n\t                    Tracer.Parent = workspace\n\t                    if Fade.Enabled then\n\t                        local Tween: Tween = TweenService:Create(Tracer, TweenInfo.new(Lifetime.Value), {\n\t                            Transparency = 1\n\t                        })\n\t                        Tween.Completed:Connect(function()\n\t                            Tween:Destroy()\n\t                        end)\n\t                        Tween:Play()\n\t                    end\n\t                    Debris:AddItem(Tracer, Lifetime.Value)\n\t                end\n\t            end))\n\t\n\t            if DrawingToggle.Enabled then\n\t                BulletTracers:Clean(RunService.RenderStepped:Connect(function()\n\t                    for Line: any, Data: any in DrawingObjects do\n\t                        local From, FromVisible = Camera:WorldToViewportPoint(Data[1])\n\t                        local To, ToVisible = Camera:WorldToViewportPoint(Data[2])\n\t                        if FromVisible and ToVisible then\n\t                            Line.Visible = true\n\t                            Line.From = Vector2.new(From.X, From.Y)\n\t                            Line.To = Vector2.new(To.X, To.Y)\n\t                            if Fade.Enabled then\n\t                                Line.Transparency = Color.Opacity * (1 - math.clamp((tick() - Data[3]) / Lifetime.Value, 0, 1))\n\t                            end\n\t                        else\n\t                            Line.Visible = false\n\t                        end\n\t                    end\n\t                end))\n\t            end\n\t        end\n\t    end,\n\t    Tooltip = \"Replacement tracers for bullets\"\n\t})\n\tlocal Materials: {string} = {\"SmoothPlastic\"}\n\tfor _, v: EnumItem in Enum.Material:GetEnumItems() do\n\t    if v.Name ~= \"SmoothPlastic\" then\n\t        table.insert(Materials, v.Name)\n\t    end\n\tend\n\tMaterial = BulletTracers:CreateDropdown({\n\t    Name = \"Material\",\n\t    List = Materials\n\t})\n\tColor = BulletTracers:CreateColorSlider({\n\t    Name = \"Tracer Color\",\n\t    DefaultOpacity = 0.5\n\t})\n\tLifetime = BulletTracers:CreateSlider({\n\t    Name = \"Lifetime\",\n\t    Min = 0,\n\t    Max = 0.5,\n\t    Default = 0.2,\n\t    Decimal = 10\n\t})\n\tFade = BulletTracers:CreateToggle({\n\t    Name = \"Fade\",\n\t    Default = true\n\t})\n\tDrawingToggle = BulletTracers:CreateToggle({\n\t    Name = \"Drawing\",\n\t    Function = function()\n\t        if BulletTracers.Enabled then\n\t            BulletTracers:Toggle()\n\t            BulletTracers:Toggle()\n\t        end\n\t    end\n\t})\nend)"},{"path":"src/games/606849621.lua","name":"606849621.lua","size":30424,"sha":"360a54e238ada87fa5669cc24d0b3aadd17c9f2a","encoding":"utf8","content":"local vape = shared.vape\nlocal loadstring = function(...)\n    local Chunk, Message = loadstring(...)\n    if Message and vape then\n        vape:CreateNotification(\"Vape\", `Failed to load : {Message}`, 30, \"alert\")\n    end\n    return Chunk\nend\nlocal isfile = isfile or function(File: string)\n    local Success, Result = pcall(function()\n        return readfile(File)\n    end)\n    return Success and Result ~= nil and Result ~= \"\"\nend\nlocal function DownloadFile(FilePath: string, Func)\n    if not isfile(FilePath) then\n        local Success, Result = pcall(function()\n            return game:HttpGet(`https://api.catvape.dev/download/src/{select(1, FilePath:gsub(`^{vape.Directory}/`, \"\"))}`, true)\n        end)\n        if not Success or Result == \"404: Not Found\" then\n            error(Result)\n        end\n        if FilePath:find(\".lua\") then\n            Result = `--This watermark is used to delete the file if its cached, remove it to make the file persist after vape updates.\\n{Result}`\n        end\n        writefile(FilePath, Result)\n    end\n    return (Func or readfile)(FilePath)\nend\nlocal Run = function(Func: () -> ())\n    Func()\nend\nlocal cloneref = cloneref or function(Reference: Instance)\n    return Reference\nend\n\nlocal Players: Players = cloneref(game:GetService(\"Players\"))\nlocal ReplicatedStorage: ReplicatedStorage = cloneref(game:GetService(\"ReplicatedStorage\"))\nlocal RunService: RunService = cloneref(game:GetService(\"RunService\"))\nlocal UserInputService: UserInputService = cloneref(game:GetService(\"UserInputService\"))\nlocal TextService: TextService = cloneref(game:GetService(\"TextService\"))\nlocal TweenService: TweenService = cloneref(game:GetService(\"TweenService\"))\nlocal Teams: Teams = cloneref(game:GetService(\"Teams\"))\nlocal CollectionService: CollectionService = cloneref(game:GetService(\"CollectionService\"))\nlocal ContextActionService: ContextActionService = cloneref(game:GetService(\"ContextActionService\"))\n\nlocal Camera: Camera = workspace.CurrentCamera\nlocal LocalPlayer: Player = Players.LocalPlayer\n\nlocal Entity = vape.Libraries.entity\nlocal Whitelist = vape.Libraries.whitelist\nlocal PredictionLib = vape.Libraries.prediction\nlocal TargetInfo = vape.Libraries.targetinfo\nlocal SessionInfo = vape.Libraries.sessioninfo\nlocal VirtualMachine = loadstring(DownloadFile(`{vape.Directory}/libraries/vm.lua`), \"vm\")()\n\nlocal Jailbreak = {}\nlocal InfNitro = {Enabled = false}\nlocal LazerGodmode = {Enabled = false}\n\nlocal function GetVehicle(Ent)\n    if Ent.Player then\n        for _, Car: Model in CollectionService:GetTagged(\"Vehicle\") do\n            for _, Seat: Instance in Car:GetChildren() do\n                if (Seat.Name == \"Seat\" or Seat.Name == \"Passenger\") then\n                    Seat = Seat:FindFirstChild(\"PlayerName\")\n                    if Seat and Seat.Value == Ent.Player.Name then\n                        return Car\n                    end\n                end\n            end\n        end\n    end\nend\n\nlocal function IsArrested(Name: string)\n    for _, v: any in Jailbreak.CircleAction.Specs do\n        if v.Name == \"Arrest\" and v.PlayerName == Name then\n            return not v.ShouldArrest\n        end\n    end\n    return false\nend\n\nlocal function IsFriend(Player: Player, Recolor: boolean?)\n    if vape.Categories.Friends.Options[\"Use friends\"].Enabled then\n        local Friend = table.find(vape.Categories.Friends.ListEnabled, Player.Name) and true\n        if Recolor then\n            Friend = Friend and vape.Categories.Friends.Options[\"Recolor visuals\"].Enabled\n        end\n        return Friend\n    end\n    return nil\nend\n\nlocal function IsIllegal(Ent)\n    if Ent.Player and Ent.Player.Team == Teams.Prisoner then\n        local Items = Ent.Player:FindFirstChild(\"CurrentInventory\")\n        Items = Items and Items.Value\n        if Items then\n            for _, v: Instance in Items:GetChildren() do\n                if v.Name ~= \"MansionInvite\" then\n                    return true\n                end\n            end\n        end\n\n        return Ent.Illegal\n    end\n    return true\nend\n\nlocal function IsTarget(Player: Player)\n    return table.find(vape.Categories.Targets.ListEnabled, Player.Name) and true\nend\n\nlocal function SendNotification(...)\n    return vape:CreateNotification(...)\nend\n\nRun(function()\n    Entity.getUpdateConnections = function(Ent)\n        local Humanoid: Humanoid = Ent.Humanoid\n        return {\n            Humanoid:GetPropertyChangedSignal(\"Health\"),\n            Humanoid:GetPropertyChangedSignal(\"MaxHealth\"),\n            {\n                Connect = function()\n                    Ent.Friend = Ent.Player and IsFriend(Ent.Player) or nil\n                    Ent.Target = Ent.Player and IsTarget(Ent.Player) or nil\n                    return {Disconnect = function() end}\n                end\n            },\n            {\n                Connect = function()\n                    return Humanoid:GetPropertyChangedSignal(\"Sit\"):Connect(function()\n                        if GetVehicle(Ent) then\n                            Ent.Illegal = true\n                        end\n                    end)\n                end\n            }\n        }\n    end\n\n    Entity.targetCheck = function(Ent)\n        if Ent.TeamCheck then\n            return Ent:TeamCheck()\n        end\n        if Ent.NPC then\n            return true\n        end\n        if IsFriend(Ent.Player) then\n            return false\n        end\n        if not select(2, Whitelist:get(Ent.Player)) then\n            return false\n        end\n        if LocalPlayer.Team == Teams.Police then\n            return Ent.Player.Team ~= Teams.Police\n        else\n            return Ent.Player.Team == Teams.Police\n        end\n        return true\n    end\nend)\nEntity.start()\n\nRun(function()\n    local function DumpRemotes(Scripts: {Instance}, Renamed: {[string]: string})\n        local Returned = {}\n\n        for _, Script: Instance in Scripts do\n            local Deserialized = VirtualMachine.luau_deserialize(getscriptbytecode(Script))\n\n            for _, Proto: any in Deserialized.protoList do\n                local Stack, Top, Code = {}, -1, Proto.code\n                for i: number, Instruction: any in Code do\n                    if Instruction.opcode == 4 then\n                        Stack[Instruction.A] = Instruction.D\n                    elseif Instruction.opcode == 5 then\n                        Stack[Instruction.A] = Instruction.K\n                    elseif Instruction.opcode == 6 then\n                        Stack[Instruction.A] = Stack[Instruction.B]\n                    elseif Instruction.opcode == 12 then\n                        local Count, Import = Instruction.KC, getrenv()[Instruction.K0]\n\n                        if Count == 1 then\n                            Stack[Instruction.A] = Import\n                        elseif Count == 2 then\n                            Stack[Instruction.A] = Import[Instruction.K1]\n                        elseif Count == 3 then\n                            Stack[Instruction.A] = Import[Instruction.K1][Instruction.K2]\n                        end\n                    elseif Instruction.opcode == 20 then\n                        local A, B, Method = Instruction.A, Instruction.B, Instruction.K\n                        Stack[A + 1] = Stack[B]\n\n                        local CallInstruction = Code[i + 2]\n                        local CallA, CallB, CallC = CallInstruction.A, CallInstruction.B, CallInstruction.C\n                        local Params: number = if CallB == 0 then Top - CallA else CallB - 1\n                        if Method == \"sub\" or Method == \"reverse\" then\n                            local Arg1, Arg2, Arg3 = table.unpack(Stack, CallA + 1, CallA + Params)\n                            if Method == \"reverse\" and not Arg1 then\n                                Arg1 = \"a\"\n                            end\n\n                            local Results = table.pack(string[Method](Arg1, Arg2, Arg3))\n                            local ResultCount: number = Results.n - 1\n                            if CallC == 0 then\n                                Top = CallA + ResultCount - 1\n                            else\n                                ResultCount = CallC - 1\n                            end\n\n                            table.move(Results, 1, ResultCount, CallA, Stack)\n                        elseif Method == \"FireServer\" then\n                            local Name, Value = Proto.debugname == \"(??)\" and Script.Name or Proto.debugname, Stack[CallA + 2]\n                            if Name == Value then\n                                table.insert(Returned, Value)\n                                continue\n                            end\n                            if Returned[Name] then\n                                for Suffix: number = 1, 10 do\n                                    if not Returned[`{Name}{Suffix}`] then\n                                        Name ..= Suffix\n                                        break\n                                    end\n                                end\n                            end\n\n                            Returned[Name] = Value\n                        end\n                    elseif Instruction.opcode == 49 then\n                        local Concatenated: string = \"\"\n                        for Register: number = Instruction.B, Instruction.C do\n                            if type(Stack[Register]) ~= \"string\" then\n                                continue\n                            end\n                            Concatenated ..= Stack[Register]\n                        end\n                        Stack[Instruction.A] = Concatenated\n                    end\n                end\n            end\n        end\n\n        for Name: string, v: any in table.clone(Returned) do\n            if Renamed[Name] then\n                Returned[Name] = nil\n                Returned[Renamed[Name]] = v\n            end\n        end\n\n        return Returned\n    end\n\n    local function GetCash()\n        for i: number, v: any in debug.getupvalue(Jailbreak.TeamChooseController.Init, 2) do\n            if type(v) == \"function\" then\n                for _, Constant: any in debug.getconstants(v) do\n                    if tostring(Constant):find(\"PlusCash\") then\n                        return v, i\n                    end\n                end\n            end\n        end\n    end\n\n    local function ToMoney(Amount: number)\n        local Prefix, Digits, Suffix = string.match(tostring(Amount), \"^([^%d]*%d)(%d*)(.-)$\")\n        return `{Prefix}{Digits:reverse():gsub(\"(%d%d%d)\", \"%1,\"):reverse()}{Suffix}$`\n    end\n\n    Jailbreak = {\n        BulletEmitter = require(ReplicatedStorage.Game.ItemSystem.BulletEmitter),\n        CircleAction = require(ReplicatedStorage.Module.UI).CircleAction,\n        CargoController = require(ReplicatedStorage.Game.Robbery.RobberyPassengerTrain),\n        FallingController = require(ReplicatedStorage.Game.Falling),\n        GunController = require(ReplicatedStorage.Game.Item.Gun),\n        HotbarItemSystem = require(ReplicatedStorage.Hotbar.HotbarItemSystem),\n        InventoryItemSystem = require(ReplicatedStorage.Inventory.InventoryItemSystem),\n        ItemSystemController = require(ReplicatedStorage.Game.ItemSystem.ItemSystem),\n        PlayerUtils = require(ReplicatedStorage.Game.PlayerUtils),\n        RagdollController = require(ReplicatedStorage.Module.AlexRagdoll),\n        TaserController = require(ReplicatedStorage.Game.Item.Taser),\n        TeamChooseController = require(ReplicatedStorage.TeamSelect.TeamChooseUI),\n        VehicleController = require(ReplicatedStorage.Vehicle.VehicleUtils)\n    }\n\n    if not Jailbreak.VehicleController.toggleLocalLocked or not Jailbreak.VehicleController.NitroShopVisible then\n        repeat task.wait() until (Jailbreak.VehicleController.toggleLocalLocked and Jailbreak.VehicleController.NitroShopVisible) or vape.Loaded == nil\n        if vape.Loaded == nil then\n            return\n        end\n    end\n    local RemoteTable = debug.getupvalue(Jailbreak.VehicleController.toggleLocalLocked, 2)\n    local FireServer, Hook = RemoteTable.FireServer\n\n    local Remotes = DumpRemotes({\n        ReplicatedStorage.Game.TrainSystem.LocomotiveFront,\n        ReplicatedStorage.Game.ItemSystem.ItemSystem,\n        ReplicatedStorage.Game.CashBuyUI,\n        ReplicatedStorage.Game.Item.Taser,\n        ReplicatedStorage.Game.Item.Gun,\n        ReplicatedStorage.Game.Falling,\n        LocalPlayer.PlayerScripts.LocalScript\n    }, {\n        Action = \"Pickup\",\n        Action3 = \"StartRob\",\n        Action2 = \"EndRob\",\n        AttemptArrest = \"Arrest\",\n        attemptPunch = \"Punch\",\n        AttemptVehicleEject = \"Eject\",\n        AttemptVehicleEnter = \"GetIn\",\n        BroadcastInputBegan = \"InputBegan\",\n        BroadcastInputEnded = \"InputEnded\",\n        CalculateDelta = \"UseNitro\",\n        Draw = \"TaseReplicate\",\n        Gun = \"PopTires\",\n        LocalScript2 = \"LookAngle\",\n        LocalScript = \"SelfDamage\",\n        onPressed = \"FlipVehicle\",\n        OnJump = \"GetOut\",\n        OnJump1 = \"GetOut\",\n        UpdateMousePosition = \"AimPosition\"\n    })\n\n    local function FireHook(self, Id, ...)\n        local RemoteName\n        for Name: string, v: any in Remotes do\n            if v == Id then\n                RemoteName = Name\n            end\n        end\n\n        if InfNitro.Enabled and RemoteName == \"UseNitro\" then\n            return\n        end\n        if LazerGodmode.Enabled and RemoteName == \"SelfDamage\" then\n            return\n        end\n        if RemoteName ~= \"LookAngle\" and RemoteName ~= \"AimPosition\" and shared.VapeDeveloper then\n            local Caller = getfenv(3)\n            Caller = Caller and Caller.script\n            if Caller and (not RemoteName) then\n                print(Id, \"called with\", Caller:GetFullName())\n            end\n            print(Id, RemoteName or Id, ...)\n        end\n\n        return Hook(self, Id, ...)\n    end\n\n    Hook = hookfunction(FireServer, function(self, Id, ...)\n        return FireHook(self, Id, ...)\n    end)\n\n    function Jailbreak:FireServer(Id, ...)\n        if not Remotes[Id] then\n            SendNotification(\"Vape\", `Failed to find remote ({Id})`, 10, \"alert\")\n            return\n        end\n\n        return Hook(RemoteTable, Remotes[Id], ...)\n    end\n\n    local Arrests = SessionInfo:AddItem(\"Arrested\")\n    local MoneyMade = SessionInfo:AddItem(\"Money Made\", 0, ToMoney, true)\n    local Bounty = SessionInfo:AddItem(\"Bounty List\", \"\", function()\n        local Text, Board = \"\", workspace.MostWanted:FindFirstChild(\"Board\", true)\n        Board = Board and Board:GetChildren() or {}\n\n        for _, v: Instance in Board do\n            if v:IsA(\"Frame\") then\n                local PlayerName = v:FindFirstChild(\"PlayerName\", true)\n                local BountyLabel = v:FindFirstChild(\"Bounty\", true)\n                if PlayerName and BountyLabel then\n                    Text = `{Text}\\n{PlayerName.Text}: {BountyLabel.Text:gsub(\" Bounty\", \"\")}`\n                end\n            end\n        end\n\n        return Text\n    end, false)\n\n    local CashFunction, CashHook = GetCash()\n    if CashFunction then\n        CashHook = hookfunction(CashFunction, function(Amount, Text, ...)\n            MoneyMade:Increment(Amount)\n            if Text == \"Arrest\" then\n                Arrests:Increment()\n            end\n            return CashHook(Amount, Text, ...)\n        end)\n    end\n\n    vape:Clean(function()\n        table.clear(Remotes)\n        table.clear(Jailbreak)\n        hookfunction(FireServer, Hook)\n        hookfunction(CashFunction, CashHook)\n    end)\nend)\n\nfor _, v: string in {\"Reach\", \"TriggerBot\", \"Disabler\", \"AntiFall\", \"HitBoxes\", \"Killaura\", \"MurderMystery\"} do\n    vape:Remove(v)\nend\n\nRun(function()\n\tlocal ForceHeadshot\n\t\n\tForceHeadshot = vape.Categories.Combat:CreateModule({\n\t    Name = \"ForceHeadshot\",\n\t    Function = function(Callback: boolean)\n\t        if Callback then\n\t            local Hook\n\t            Hook = hookfunction(Jailbreak.GunController.BulletEmitterOnLocalHitPlayer, function(...)\n\t                local ShotData = select(15, ...)\n\t                ShotData.isHeadshot = true\n\t                return Hook(...)\n\t            end)\n\t        else\n\t            restorefunction(Jailbreak.GunController.BulletEmitterOnLocalHitPlayer)\n\t        end\n\t    end,\n\t    Tooltip = \"Modifies bullets to always do headshot damage.\"\n\t})\nend)\n\nRun(function()\n\tlocal SilentAim\n\tlocal Target\n\tlocal Mode\n\tlocal Range\n\tlocal HitChance\n\tlocal HeadshotChance\n\tlocal CircleColor\n\tlocal CircleTransparency\n\tlocal CircleThickness\n\tlocal CircleFilled\n\tlocal CircleObject\n\tlocal Instant\n\tlocal Hooked\n\tlocal ProjectileRaycast: RaycastParams = RaycastParams.new()\n\tProjectileRaycast.RespectCanCollide = true\n\t\n\tSilentAim = vape.Categories.Combat:CreateModule({\n\t    Name = \"SilentAim\",\n\t    Function = function(Callback: boolean)\n\t        if CircleObject then\n\t            CircleObject.Visible = Callback and Mode.Value == \"Mouse\"\n\t        end\n\t\n\t        if Callback then\n\t            Hooked = Jailbreak.GunController.TransformLocalMousePosition\n\t            Jailbreak.GunController.TransformLocalMousePosition = function(self, Position: Vector3)\n\t                local Ent = Entity[`Entity{Mode.Value}`]({\n\t                    Range = Range.Value,\n\t                    Wallcheck = Target.Walls.Enabled or nil,\n\t                    Part = \"RootPart\",\n\t                    Origin = Entity.isAlive and Entity.character.RootPart.Position or nil,\n\t                    Players = Target.Players.Enabled,\n\t                    NPCs = Target.NPCs.Enabled\n\t                })\n\t\n\t                if Ent then\n\t                    local Item = Jailbreak.ItemSystemController:GetLocalEquipped()\n\t                    if Item and ((self.Tip.CFrame.Position - Ent.RootPart.Position).Magnitude / (Item.Config.BulletSpeed or 1000)) < Item.BulletEmitter.LifeSpan then\n\t                        ProjectileRaycast.FilterDescendantsInstances = {Camera, Ent.Character, workspace.Vehicles}\n\t                        ProjectileRaycast.CollisionGroup = Ent.RootPart.CollisionGroup\n\t                        local Solution = PredictionLib.SolveTrajectory(self.Tip.CFrame.Position, Item.Config.BulletSpeed or 1000, math.abs(Item.BulletEmitter.GravityVector.Y), Ent.RootPart.Position, Instant.Enabled and Vector3.zero or Ent.RootPart.Velocity, workspace.Gravity, Ent.HipHeight, nil, ProjectileRaycast)\n\t                        if Solution then\n\t                            TargetInfo.Targets[Ent] = tick() + 1\n\t                            return Solution\n\t                        end\n\t                    end\n\t                end\n\t\n\t                return Position\n\t            end\n\t\n\t            repeat\n\t                if CircleObject then\n\t                    CircleObject.Position = UserInputService:GetMouseLocation()\n\t                end\n\t\n\t                if Instant.Enabled then\n\t                    local Item = Jailbreak.ItemSystemController:GetLocalEquipped()\n\t                    if Item and Item.BulletEmitter then\n\t                        rawset(Item.BulletEmitter, \"LastUpdate\", tick() - (Item.BulletEmitter.LifeSpan - 0.1))\n\t                    end\n\t                end\n\t\n\t                task.wait()\n\t            until not SilentAim.Enabled\n\t        else\n\t            Jailbreak.GunController.TransformLocalMousePosition = Hooked\n\t        end\n\t    end,\n\t    Tooltip = \"Silently adjusts your aim towards the enemy\"\n\t})\n\tTarget = SilentAim:CreateTargets({Players = true})\n\tMode = SilentAim:CreateDropdown({\n\t    Name = \"Mode\",\n\t    List = {\"Mouse\", \"Position\"},\n\t    Function = function(Val: string)\n\t        if CircleObject then\n\t            CircleObject.Visible = SilentAim.Enabled and Val == \"Mouse\"\n\t        end\n\t    end,\n\t    Tooltip = \"Mouse - Checks for entities near the mouses position\\nPosition - Checks for entities near the local character\"\n\t})\n\tRange = SilentAim:CreateSlider({\n\t    Name = \"Range\",\n\t    Min = 1,\n\t    Max = 1000,\n\t    Default = 150,\n\t    Function = function(Val: number)\n\t        if CircleObject then\n\t            CircleObject.Radius = Val\n\t        end\n\t    end,\n\t    Suffix = function(Val: number)\n\t        return Val == 1 and \"stud\" or \"studs\"\n\t    end\n\t})\n\tSilentAim:CreateToggle({\n\t    Name = \"Range Circle\",\n\t    Function = function(Callback: boolean)\n\t        if Callback then\n\t            CircleObject = Drawing.new(\"Circle\")\n\t            CircleObject.Filled = CircleFilled.Enabled\n\t            CircleObject.Color = Color3.fromHSV(CircleColor.Hue, CircleColor.Sat, CircleColor.Value)\n\t            CircleObject.Position = vape.gui.AbsoluteSize / 2\n\t            CircleObject.Radius = Range.Value\n\t            CircleObject.NumSides = 100\n\t            CircleObject.Thickness = CircleThickness.Value\n\t            CircleObject.Transparency = 1 - CircleTransparency.Value\n\t            CircleObject.Visible = SilentAim.Enabled and Mode.Value == \"Mouse\"\n\t        else\n\t            pcall(function()\n\t                CircleObject.Visible = false\n\t                CircleObject:Remove()\n\t            end)\n\t            CircleObject = nil\n\t        end\n\t        CircleColor.Object.Visible = Callback\n\t        CircleTransparency.Object.Visible = Callback\n\t        CircleThickness.Object.Visible = Callback\n\t        CircleFilled.Object.Visible = Callback\n\t    end\n\t})\n\tCircleColor = SilentAim:CreateColorSlider({\n\t    Name = \"Circle Color\",\n\t    Function = function(Hue: number, Sat: number, Val: number)\n\t        if CircleObject then\n\t            CircleObject.Color = Color3.fromHSV(Hue, Sat, Val)\n\t        end\n\t    end,\n\t    Darker = true,\n\t    Visible = false\n\t})\n\tCircleTransparency = SilentAim:CreateSlider({\n\t    Name = \"Transparency\",\n\t    Min = 0,\n\t    Max = 1,\n\t    Decimal = 10,\n\t    Default = 0.5,\n\t    Function = function(Val: number)\n\t        if CircleObject then\n\t            CircleObject.Transparency = 1 - Val\n\t        end\n\t    end,\n\t    Darker = true,\n\t    Visible = false\n\t})\n\tCircleThickness = SilentAim:CreateSlider({\n\t    Name = \"Thickness\",\n\t    Min = 1,\n\t    Max = 10,\n\t    Decimal = 10,\n\t    Default = 1,\n\t    Function = function(Val: number)\n\t        if CircleObject then\n\t            CircleObject.Thickness = Val\n\t        end\n\t    end,\n\t    Darker = true,\n\t    Visible = false,\n\t    Tooltip = \"How wide the circle's outline is, has no effect while Circle Filled is on\"\n\t})\n\tCircleFilled = SilentAim:CreateToggle({\n\t    Name = \"Circle Filled\",\n\t    Function = function(Callback: boolean)\n\t        if CircleObject then\n\t            CircleObject.Filled = Callback\n\t        end\n\t    end,\n\t    Darker = true,\n\t    Visible = false\n\t})\n\tInstant = SilentAim:CreateToggle({Name = \"Hitscan Bullets\"})\nend)\n\nRun(function()\n\tlocal AutoArrest\n\tlocal Cooldown: number = 0\n\t\n\tAutoArrest = vape.Categories.Blatant:CreateModule({\n\t    Name = \"AutoArrest\",\n\t    Function = function(Callback: boolean)\n\t        if Callback then\n\t            repeat\n\t                local Item = Jailbreak.ItemSystemController:GetLocalEquipped()\n\t                if Item and Item.__ClassName == \"Handcuffs\" then\n\t                    local LocalPosition: Vector3 = Entity.character.Humanoid.HumanoidUnloadServerPosition.Value\n\t                    local Entities = Entity.AllPosition({\n\t                        Players = true,\n\t                        Part = \"RootPart\",\n\t                        Range = 50\n\t                    })\n\t\n\t                    for _, Ent: any in Entities do\n\t                        if Ent.Player and IsIllegal(Ent) then\n\t                            local Vehicle = Ent.Humanoid.Sit and GetVehicle(Ent) or nil\n\t                            if Vehicle then\n\t                                Jailbreak:FireServer(\"Eject\", Vehicle)\n\t                            elseif not IsArrested(Ent.Player.Name) and (LocalPosition - Ent.RootPart.Position).Magnitude < 18.4 and Cooldown < os.clock() then\n\t                                Jailbreak:FireServer(\"Arrest\", Ent.Player.Name)\n\t                                Cooldown = os.clock() + 0.5\n\t                            end\n\t                        end\n\t                    end\n\t                end\n\t\n\t                task.wait(0.016)\n\t            until not AutoArrest.Enabled\n\t        end\n\t    end,\n\t    Tooltip = \"Automatically uses handcuffs on nearby entities\"\n\t})\nend)\n\nRun(function()\n\tlocal AutoPop\n\tlocal Range\n\tlocal TeamCheck\n\tlocal Delays: {[Model]: number} = {}\n\t\n\tlocal function GetEntitiesInVehicle(Car: Model)\n\t    local Entities = {}\n\t\n\t    for _, Seat: Instance in Car:GetChildren() do\n\t        if (Seat.Name == \"Seat\" or Seat.Name == \"Passenger\") then\n\t            Seat = Seat:FindFirstChild(\"PlayerName\")\n\t            if Seat then\n\t                for _, Ent: any in Entity.List do\n\t                    if Ent.Player and Ent.Player.Name == Seat.Value then\n\t                        table.insert(Entities, Ent)\n\t                    end\n\t                end\n\t            end\n\t        end\n\t    end\n\t\n\t    return Entities\n\tend\n\t\n\tlocal function GetVehiclesNear()\n\t    local Allowed: {Model} = {}\n\t\n\t    if Entity.isAlive then\n\t        local LocalPosition: Vector3 = Entity.character.HumanoidRootPart.Position\n\t        for _, Car: Model in CollectionService:GetTagged(\"Vehicle\") do\n\t            if Car.PrimaryPart and (Car.PrimaryPart.Position - LocalPosition).Magnitude <= Range.Value then\n\t                local Entities = GetEntitiesInVehicle(Car)\n\t                local Check: boolean = #Entities > 0\n\t                if TeamCheck.Enabled then\n\t                    for _, Ent: any in Entities do\n\t                        if not Ent.Targetable then\n\t                            Check = false\n\t                            break\n\t                        end\n\t                    end\n\t                end\n\t\n\t                if Check then\n\t                    table.insert(Allowed, Car)\n\t                end\n\t            end\n\t        end\n\t    end\n\t\n\t    return Allowed\n\tend\n\t\n\tAutoPop = vape.Categories.Blatant:CreateModule({\n\t    Name = \"AutoPop\",\n\t    Function = function(Callback: boolean)\n\t        if Callback then\n\t            task.spawn(function()\n\t                repeat\n\t                    local Item = Jailbreak.ItemSystemController:GetLocalEquipped()\n\t                    if Item and Item.BulletEmitter and Item.Model then\n\t                        for _, Car: Model in GetVehiclesNear() do\n\t                            if (Car:GetAttribute(\"VehicleTireHealth\") or 10) <= 0 then\n\t                                continue\n\t                            end\n\t\n\t                            if (Delays[Car] or 0) > os.clock() then\n\t                                continue\n\t                            end\n\t\n\t                            Delays[Car] = os.clock() + 0.1\n\t                            Jailbreak:FireServer(\"PopTires\", Car, Item.Model.Name)\n\t                        end\n\t                    end\n\t\n\t                    task.wait(0.016)\n\t                until not AutoPop.Enabled\n\t            end)\n\t        else\n\t            table.clear(Delays)\n\t        end\n\t    end,\n\t    Tooltip = \"Automatically pops vehicles tires around you\"\n\t})\n\tRange = AutoPop:CreateSlider({\n\t    Name = \"Range\",\n\t    Min = 1,\n\t    Max = 600,\n\t    Default = 600\n\t})\n\tTeamCheck = AutoPop:CreateToggle({Name = \"Team Check\"})\nend)\n\nRun(function()\n\tlocal AutoPunch\n\t\n\tAutoPunch = vape.Categories.Blatant:CreateModule({\n\t    Name = \"AutoPunch\",\n\t    Function = function(Callback: boolean)\n\t        if Callback then\n\t            repeat\n\t                if Entity.isAlive then\n\t                    Jailbreak:FireServer(\"Punch\")\n\t                end\n\t\n\t                task.wait(0.3)\n\t            until not AutoPunch.Enabled\n\t        end\n\t    end,\n\t    Tooltip = \"Always punches people infront of you\"\n\t})\nend)\n\nRun(function()\n\tlocal AutoTaze\n\tlocal HandCheck\n\tlocal Cooldown: number = 0\n\t\n\tAutoTaze = vape.Categories.Blatant:CreateModule({\n\t    Name = \"AutoTaze\",\n\t    Function = function(Callback: boolean)\n\t        if Callback then\n\t            repeat\n\t                local Item = Jailbreak.ItemSystemController:GetLocalEquipped()\n\t                Item = Item and Item.__ClassName == \"Taser\" or nil\n\t                if not HandCheck.Enabled or Item then\n\t                    local Ent = Entity.EntityPosition({\n\t                        Players = true,\n\t                        Part = \"RootPart\",\n\t                        Range = 50\n\t                    })\n\t\n\t                    if Ent and IsIllegal(Ent) and not IsArrested(Ent.Player.Name) and Cooldown < os.clock() then\n\t                        if Item then\n\t                            Jailbreak:FireServer(\"TaseReplicate\", Ent.Head.Position)\n\t                        end\n\t\n\t                        Jailbreak:FireServer(\"Tase\", Ent.Humanoid, Ent.Head, Ent.Head.Position)\n\t                        Cooldown = os.clock() + 10\n\t                    end\n\t                end\n\t\n\t                task.wait(0.016)\n\t            until not AutoTaze.Enabled\n\t        end\n\t    end,\n\t    Tooltip = \"Immobilizes entities around you\"\n\t})\n\tHandCheck = AutoTaze:CreateToggle({Name = \"Hand Check\"})\nend)\n\nRun(function()\n\tLazerGodmode = vape.Categories.Blatant:CreateModule({Name = \"LazerGodmode\"})\nend)\n\nRun(function()\n\tvape.Categories.Blatant:CreateModule({\n\t    Name = \"NoFall\",\n\t    Function = function(Callback: boolean)\n\t        debug.setconstant(debug.getupvalue(Jailbreak.FallingController.Init, 20), 9, Callback and \"Archivable\" or \"Sit\")\n\t    end,\n\t    Tooltip = \"Disables ragdoll handling & fall damage\"\n\t})\nend)\n\nRun(function()\n\tlocal NitroTable = debug.getupvalue(Jailbreak.VehicleController.NitroShopVisible, 1)\n\tlocal OldNitro: number\n\t\n\tInfNitro = vape.Categories.Utility:CreateModule({\n\t    Name = \"InfiniteNitro\",\n\t    Function = function(Callback: boolean)\n\t        if Callback then\n\t            OldNitro = NitroTable.Nitro\n\t            Jailbreak.VehicleController.updateSpdBarRatio(1)\n\t\n\t            repeat\n\t                NitroTable.Nitro = 250\n\t                task.wait(0.1)\n\t            until not InfNitro.Enabled\n\t        else\n\t            NitroTable.Nitro = OldNitro\n\t            Jailbreak.VehicleController.updateSpdBarRatio(OldNitro / 250)\n\t        end\n\t    end,\n\t    Tooltip = \"Infinite boost for the local car\"\n\t})\nend)\n\nRun(function()\n\tvape.Categories.Utility:CreateModule({\n\t    Name = \"InstantAction\",\n\t    Function = function(Callback: boolean)\n\t        debug.setconstant(Jailbreak.CircleAction.Press, 3, Callback and \"Timeda\" or \"Timed\")\n\t    end,\n\t    Tooltip = \"Allows you to instantly complete ProximityPrompt actions\"\n\t})\nend)"},{"path":"src/games/6872265039.lua","name":"6872265039.lua","size":38708,"sha":"9398efb8e93c0f3345e978c64950705c8e6aceae","encoding":"utf8","content":"if table.find({\"Solara\", \"Xeno\"}, ({identifyexecutor()})[1]) then\n    return false\nend\nlocal Run = function(Func: () -> ())\n    xpcall(Func, function(Message)\n        warn(`[catvape] {Message}\\n{debug.traceback(nil, 2)}`)\n        if shared.vape then\n            shared.vape:CreateNotification(\"Vape\", `A module failed to load : {Message}`, 15, \"alert\")\n        end\n    end)\n\n    shared.vape.YieldBuild()\nend\nlocal cloneref = cloneref or function(Reference: Instance)\n    return Reference\nend\nlocal Players: Players = cloneref(game:GetService(\"Players\"))\nlocal ReplicatedStorage: ReplicatedStorage = cloneref(game:GetService(\"ReplicatedStorage\"))\nlocal UserInputService: UserInputService = cloneref(game:GetService(\"UserInputService\"))\nlocal TweenService: TweenService = cloneref(game:GetService(\"TweenService\"))\nlocal HttpService: HttpService = cloneref(game:GetService(\"HttpService\"))\nlocal CoreGui: CoreGui = cloneref(game:GetService(\"CoreGui\"))\nlocal TeleportService: TeleportService = cloneref(game:GetService(\"TeleportService\"))\n\nlocal LocalPlayer: Player = Players.LocalPlayer\nlocal vape = shared.vape\nlocal Entity = vape.Libraries.entity\nlocal SessionInfo = vape.Libraries.sessioninfo\nlocal bedwars = {}\n\nlocal function SendNotification(...)\n    return vape:CreateNotification(...)\nend\n\nRun(function()\n    local function DumpRemote(Remotes: {string}): string\n        local Index: number? = table.find(Remotes, \"Client\")\n        return Index and Remotes[Index + 1] or \"\"\n    end\n\n    local KnitInit, Knit\n    repeat\n        KnitInit, Knit = pcall(function()\n            return debug.getupvalue(require(LocalPlayer.PlayerScripts.TS.knit).setup, 9)\n        end)\n        if KnitInit then\n            break\n        end\n        task.wait()\n    until KnitInit\n    if not debug.getupvalue(Knit.Start, 1) then\n        repeat\n            task.wait()\n        until debug.getupvalue(Knit.Start, 1)\n    end\n    local Flamework = require(ReplicatedStorage[\"rbxts_include\"][\"node_modules\"][\"@flamework\"].core.out).Flamework\n    local Client = require(ReplicatedStorage.TS.remotes).default.Client\n\n    bedwars = setmetatable({\n        Client = Client,\n        CrateItemMeta = debug.getupvalue(Flamework.resolveDependency(\"client/controllers/global/reward-crate/crate-controller@CrateController\").onStart, 3),\n        EmoteDisplayMeta = require(ReplicatedStorage.TS.locker.emote[\"emote-display-meta\"]).EmoteDisplayMeta,\n        EmoteMeta = require(ReplicatedStorage.TS.locker.emote[\"emote-meta\"]).EmoteMeta,\n        EmoteType = require(ReplicatedStorage.TS.locker.emote[\"emote-type\"]).EmoteType,\n        Flamework = Flamework,\n        GameAnimationUtil = require(ReplicatedStorage.TS.animation[\"animation-util\"]).GameAnimationUtil,\n        GamePlayerUtil = require(ReplicatedStorage.TS.player[\"player-util\"]).GamePlayerUtil,\n        AchievementUtil = require(ReplicatedStorage.TS.achievement[\"achievement-util\"]).AchievementUtil,\n        ModerationApp = require(LocalPlayer.PlayerScripts.TS.controllers.global[\"match-history\"].ui[\"match-history-moderation-app\"]).MatchHistoryModerationApp,\n        MilestoneRewards = require(ReplicatedStorage.TS.milestones.milestones).MilestoneRewards,\n        QueueMeta = require(ReplicatedStorage.TS.game[\"queue-meta\"]).QueueMeta,\n        Store = require(LocalPlayer.PlayerScripts.TS.ui.store).ClientStore\n    }, {\n        __index = function(self, Index: string)\n            rawset(self, Index, Knit.Controllers[Index])\n            return rawget(self, Index)\n        end\n    })\n\n    local Kills = SessionInfo:AddItem(\"Kills\")\n    local Beds = SessionInfo:AddItem(\"Beds\")\n    local Wins = SessionInfo:AddItem(\"Wins\")\n    local Games = SessionInfo:AddItem(\"Games\")\n\n    vape:Clean(function()\n        table.clear(bedwars)\n    end)\nend)\n\nfor Name: string, v: any in vape.Modules do\n    if v.Category == \"Combat\" then\n        vape:Remove(Name)\n    end\nend\n\nRun(function()\n\tlocal Sprint\n\tlocal Old: (...any) -> ...any\n\t\n\tSprint = vape.Categories.Combat:CreateModule({\n\t    Name = \"Sprint\",\n\t    Function = function(Callback: boolean)\n\t        if Callback then\n\t            Old = bedwars.SprintController.stopSprinting\n\t            bedwars.SprintController.stopSprinting = function(...)\n\t                local Call = Old(...)\n\t                bedwars.SprintController:startSprinting()\n\t                return Call\n\t            end\n\t\n\t            Sprint:Clean(Entity.Events.LocalAdded:Connect(function()\n\t                bedwars.SprintController:stopSprinting()\n\t            end))\n\t\n\t            bedwars.SprintController:stopSprinting()\n\t        else\n\t            bedwars.SprintController.stopSprinting = Old\n\t            bedwars.SprintController:stopSprinting()\n\t        end\n\t    end,\n\t    Tooltip = \"Sets your sprinting to true.\"\n\t})\nend)\n\nRun(function()\n\tlocal AutoGamble\n\t\n\tAutoGamble = vape.Categories.Utility:CreateModule({\n\t    Name = \"AutoGamble\",\n\t    Function = function(Callback: boolean)\n\t        if Callback then\n\t            AutoGamble:Clean(bedwars.Client:GetNamespace(\"RewardCrate\"):Get(\"CrateOpened\"):Connect(function(Data)\n\t                if Data.openingPlayer == LocalPlayer then\n\t                    local ItemMeta = bedwars.CrateItemMeta[Data.reward.itemType] or {displayName = Data.reward.itemType or \"unknown\"}\n\t                    SendNotification(\"AutoGamble\", `Won {ItemMeta.displayName}`, 5)\n\t                end\n\t            end))\n\t\n\t            repeat\n\t                if not bedwars.CrateAltarController.activeCrates[1] then\n\t                    for _, v: any in bedwars.Store:getState().Consumable.inventory do\n\t                        if v.consumable:find(\"crate\") then\n\t                            bedwars.CrateAltarController:pickCrate(v.consumable, 1)\n\t                            task.wait(1.2)\n\t                            if bedwars.CrateAltarController.activeCrates[1] and bedwars.CrateAltarController.activeCrates[1][2] then\n\t                                bedwars.Client:GetNamespace(\"RewardCrate\"):Get(\"OpenRewardCrate\"):SendToServer({\n\t                                    crateId = bedwars.CrateAltarController.activeCrates[1][2].attributes.crateId\n\t                                })\n\t                            end\n\t                            break\n\t                        end\n\t                    end\n\t                end\n\t                task.wait(1)\n\t            until not AutoGamble.Enabled\n\t        end\n\t    end,\n\t    Tooltip = \"Automatically opens lucky crates, piston inspired!\"\n\t})\nend)\n\nRun(function()\n\tlocal AutoQueue\n\tlocal QueueType\n\tlocal Delay\n\tlocal Leave\n\t\n\tlocal Categories = {}\n\t\n\tAutoQueue = vape.Categories.Utility:CreateModule({\n\t    Name = \"AutoQueue\",\n\t    Function = function(Callback: boolean)\n\t        if Callback then\n\t            local ReadySince: number?\n\t            local NextAction: number = 0\n\t            repeat\n\t                local PartyData = bedwars.Store:getState().Party\n\t                local Selected: string? = Categories[QueueType.Value]\n\t                if PartyData.leader.userId ~= LocalPlayer.UserId then\n\t                    ReadySince = nil\n\t                    if Leave.Enabled and os.clock() >= NextAction then\n\t                        ReplicatedStorage[\"events-@easy-games/lobby:shared/event/lobby-events@getEvents.Events\"].leaveParty:FireServer()\n\t                        NextAction = os.clock() + 1\n\t                    end\n\t                elseif PartyData.queueState ~= 0 then\n\t                    ReadySince = nil\n\t                    if Selected and PartyData.queueState == 2 and PartyData.queueData and PartyData.queueData.queueType ~= Selected and os.clock() >= NextAction then\n\t                        ReplicatedStorage[\"events-@easy-games/lobby:shared/event/lobby-events@getEvents.Events\"].leaveQueue:FireServer()\n\t                        NextAction = os.clock() + 1\n\t                    end\n\t                elseif Selected then\n\t                    ReadySince = ReadySince or os.clock()\n\t                    if os.clock() - ReadySince >= Delay.Value and os.clock() >= NextAction then\n\t                        bedwars.QueueController:joinQueue(Selected)\n\t                        NextAction = os.clock() + 5\n\t                    end\n\t                end\n\t                task.wait(0.1)\n\t            until not AutoQueue.Enabled\n\t        else\n\t            ReplicatedStorage[\"events-@easy-games/lobby:shared/event/lobby-events@getEvents.Events\"].leaveQueue:FireServer()\n\t        end\n\t    end,\n\t    Tooltip = \"Joins the queue for the selected mode from the lobby, and joins again whenever you are out of a queue\"\n\t})\n\t\n\tlocal List: {string} = {}\n\tfor Queue: string, v: any in bedwars.QueueMeta do\n\t    if not v.disabled and v.title and not Categories[v.title] then\n\t        Categories[v.title] = Queue\n\t        table.insert(List, v.title)\n\t    end\n\tend\n\ttable.sort(List)\n\tQueueType = AutoQueue:CreateDropdown({\n\t    Name = \"Queue Type\",\n\t    List = List,\n\t    Default = \"Duels (2v2)\"\n\t})\n\tDelay = AutoQueue:CreateSlider({\n\t    Name = \"Delay\",\n\t    Min = 0,\n\t    Max = 10,\n\t    Decimal = 10,\n\t    Default = 0,\n\t    Suffix = function(Value: number)\n\t        return Value == 1 and \"second\" or \"seconds\"\n\t    end,\n\t    Tooltip = \"How long to wait once you are free to queue before joining. Failed joins are retried every 5 seconds\"\n\t})\n\tLeave = AutoQueue:CreateToggle({\n\t    Name = \"Leave Party\",\n\t    Default = true\n\t})\nend)\n\nRun(function()\n\tlocal ClaimRewards\n\tlocal CratesOnly\n\tlocal Notify\n\t\n\tClaimRewards = vape.Categories.Utility:CreateModule({\n\t    Name = \"ClaimRewards\",\n\t    Function = function(Callback: boolean)\n\t        if Callback then\n\t            repeat\n\t                local Level: number = bedwars.Store:getState().Bedwars.playerLevel or 0\n\t                local Claimed = bedwars.MilestonesController.milestoneRewardsClaimed\n\t                if not Claimed then\n\t                    local State = bedwars.Store:getState().Bedwars\n\t                    Claimed = State and State.milestoneRewardsClaimed or {}\n\t                end\n\t\n\t                for _, v: any in bedwars.MilestoneRewards do\n\t                    if v.levelRequirement <= Level and not table.find(Claimed, v.id) and (not CratesOnly.Enabled or v.instantClaim) then\n\t                        if bedwars.Client:Get(\"ClaimMilestoneReward\"):CallServer(v.id) then\n\t                            table.insert(Claimed, v.id)\n\t                            if Notify.Enabled then\n\t                                SendNotification(\"ClaimRewards\", `Claimed {v.description or v.id}`, 5)\n\t                            end\n\t                        end\n\t                        task.wait(1)\n\t                        if not ClaimRewards.Enabled then\n\t                            break\n\t                        end\n\t                    end\n\t                end\n\t\n\t                task.wait(5)\n\t            until not ClaimRewards.Enabled\n\t        end\n\t    end,\n\t    Tooltip = \"Automatically claims every level milestone reward as soon as you unlock it\"\n\t})\n\t\n\tCratesOnly = ClaimRewards:CreateToggle({\n\t    Name = \"Crates only\",\n\t    Tooltip = \"Only claims the instant rewards like the lucky and diamond crates, leaves kits and cosmetics alone\"\n\t})\n\tNotify = ClaimRewards:CreateToggle({\n\t    Name = \"Notify\",\n\t    Default = true,\n\t    Tooltip = \"Tells you what got claimed\"\n\t})\nend)\n\nRun(function()\n\tlocal DeviceSpoofer\n\tlocal Device\n\tlocal OldDevice, Old\n\t\n\tDeviceSpoofer = vape.Categories.Utility:CreateModule({\n\t    Name = \"DeviceSpoofer\",\n\t    Function = function(Callback: boolean)\n\t        if Callback then\n\t            OldDevice, Old = bedwars.UserInputController:getUserInputType(), bedwars.UserInputController.getUserInputType\n\t            bedwars.UserInputController.getUserInputType = function()\n\t                return Device.Value:upper()\n\t            end\n\t            bedwars.Client:Get(\"SendUserInputType\"):SendToServer({userInputType = Device.Value:upper()})\n\t        else\n\t            bedwars.UserInputController.getUserInputType = Old\n\t            bedwars.Client:Get(\"SendUserInputType\"):SendToServer({userInputType = OldDevice})\n\t            Old = nil\n\t        end\n\t    end,\n\t    Tooltip = \"Spoofs the device you show up as to the server\",\n\t    ExtraText = function()\n\t        return Device.Value\n\t    end\n\t})\n\t\n\tDevice = DeviceSpoofer:CreateDropdown({\n\t    Name = \"Device\",\n\t    List = {\"Mobile\", \"PC\", \"Gamepad\"},\n\t    Function = function(Val: string)\n\t        if DeviceSpoofer.Enabled then\n\t            bedwars.Client:Get(\"SendUserInputType\"):SendToServer({userInputType = Val:upper()})\n\t        end\n\t    end\n\t})\nend)\n\nRun(function()\n\tlocal OriginalLevels: {[any]: number} = {}\n\t\n\tvape.Categories.Utility:CreateModule({\n\t    Name = \"LevelBypass\",\n\t    Function = function(Callback: boolean)\n\t        if Callback then\n\t            for _, Metadata: any in bedwars.QueueMeta do\n\t                if type(Metadata.playerLevelReq) == \"number\" and Metadata.playerLevelReq > 0 then\n\t                    OriginalLevels[Metadata] = Metadata.playerLevelReq\n\t                    Metadata.playerLevelReq = 0\n\t                end\n\t            end\n\t        else\n\t            for Metadata: any, Level: number in OriginalLevels do\n\t                if Metadata.playerLevelReq == 0 then\n\t                    Metadata.playerLevelReq = Level\n\t                end\n\t            end\n\t            table.clear(OriginalLevels)\n\t        end\n\t    end,\n\t    Tooltip = \"Removes local level locks on lobby queues. Reopen the play menu after toggling. Server level restrictions still apply\"\n\t})\nend)\n\nRun(function()\n\tlocal MatchDodge\n\tlocal AutoUndodge\n\tlocal UndodgeMode\n\tlocal Blacklist\n\tlocal Ping\n\tlocal Timeout\n\tlocal VetoAt\n\tlocal MaxWait\n\tlocal Advanced\n\tlocal RankAdvantage\n\tlocal DeviceCheck\n\tlocal Device\n\tlocal LowRank\n\tlocal LowRankAt\n\tlocal Guaranteed\n\tlocal Tiers: {string} = {\"Bronze\", \"Silver\", \"Gold\", \"Platinum\", \"Diamond\", \"Emerald\", \"Nightmare\"}\n\t\n\tMatchDodge = vape.Categories.Utility:CreateModule({\n\t    Name = \"AutoMatchDodge\",\n\t    Function = function(Callback: boolean)\n\t        writefile(`{vape.Directory}/profiles/matchdodge.txt`, tostring(Callback))\n\t        getgenv().matchDodgeActive = Callback\n\t    end,\n\t    Tooltip = \"Sets the dodge checks for your next match; settings carry over from the lobby\"\n\t})\n\t\n\tMatchDodge:CreateButton({\n\t    Name = \"Load\",\n\t    Function = function()\n\t        bedwars.Handler:Get(\"PlayerConnect\"):Fire(nil, TeleportService:GetLocalPlayerTeleportData())\n\t    end\n\t})\n\tMatchDodge:CreateToggle({\n\t    Name = \"Rank only\",\n\t    Tooltip = \"Loads straight away when the match is not ranked\"\n\t})\n\tAutoUndodge = MatchDodge:CreateToggle({\n\t    Name = \"Auto Undodge\",\n\t    Function = function(Callback: boolean)\n\t        if UndodgeMode then\n\t            UndodgeMode.Object.Visible = Callback\n\t        end\n\t        if Blacklist then\n\t            Blacklist.Object.Visible = Callback and UndodgeMode.Value == \"Rank\"\n\t        end\n\t        if Ping then\n\t            Ping.Object.Visible = Callback and UndodgeMode.Value == \"Latency\"\n\t        end\n\t    end,\n\t    Tooltip = \"Automatically loads when the selected checks pass\"\n\t})\n\tUndodgeMode = MatchDodge:CreateDropdown({\n\t    Name = \"Mode\",\n\t    List = {\"Rank\", \"Latency\"},\n\t    Function = function(Val: string)\n\t        if Blacklist then\n\t            Blacklist.Object.Visible = AutoUndodge.Enabled and Val == \"Rank\"\n\t        end\n\t        if Ping then\n\t            Ping.Object.Visible = AutoUndodge.Enabled and Val == \"Latency\"\n\t        end\n\t    end,\n\t    Darker = true,\n\t    Visible = false,\n\t    Tooltip = \"Rank waits for opponents to load, Latency waits for your ping to reach the threshold\"\n\t})\n\tBlacklist = MatchDodge:CreateTextList({\n\t    Name = \"Rank Blacklist\",\n\t    Placeholder = \"bronze / silver / gold / platinum / diamond / emerald / nightmare\",\n\t    Darker = true,\n\t    Visible = false,\n\t    Function = function()\n\t        for i: number, v: string in Blacklist.List do\n\t            Blacklist.List[i] = v:lower()\n\t        end\n\t        for i: number, v: string in Blacklist.ListEnabled do\n\t            Blacklist.ListEnabled[i] = v:lower()\n\t        end\n\t    end\n\t})\n\tPing = MatchDodge:CreateSlider({\n\t    Name = \"Ping\",\n\t    Min = 50,\n\t    Max = 1000,\n\t    Default = 200,\n\t    Darker = true,\n\t    Visible = false,\n\t    Suffix = \"ms\",\n\t    Tooltip = \"How high your ping has to be before loading\"\n\t})\n\tMatchDodge:CreateToggle({\n\t    Name = \"Rank Veto\",\n\t    Function = function(Callback: boolean)\n\t        if VetoAt then\n\t            VetoAt.Object.Visible = Callback\n\t        end\n\t    end,\n\t    Tooltip = \"Keeps dodging opponents at or above the selected rank, even after Max Wait\"\n\t})\n\tVetoAt = MatchDodge:CreateDropdown({\n\t    Name = \"Veto At\",\n\t    List = Tiers,\n\t    Default = \"Diamond\",\n\t    Darker = true,\n\t    Visible = false,\n\t    Tooltip = \"The lowest enemy rank that blocks automatic loading\"\n\t})\n\tMatchDodge:CreateToggle({\n\t    Name = \"4v5 Check\",\n\t    Tooltip = \"In 5v5 queues, waits if fewer teammates than opponents are loaded, counting you\"\n\t})\n\tMatchDodge:CreateToggle({\n\t    Name = \"Requeue\",\n\t    Tooltip = \"Needs Auto Undodge. When a check rejects the match, or still blocks it after Max Wait, queues the same mode again from the loading screen (party leader only, up to 3 tries). Once requeued, this match only loads if you press Load\"\n\t})\n\tMaxWait = MatchDodge:CreateSlider({\n\t    Name = \"Max Wait\",\n\t    Min = 0,\n\t    Max = 120,\n\t    Function = function(Val: number)\n\t        if Timeout then\n\t            Timeout.Value = Val\n\t        end\n\t    end,\n\t    Default = 20,\n\t    Suffix = function(Val: number)\n\t        return Val == 1 and \"second\" or \"seconds\"\n\t    end,\n\t    Tooltip = \"Skips the mode wait after this long. Rank vetoes, blacklist, team and Advanced checks still apply. 0 waits forever\"\n\t})\n\tTimeout = MatchDodge:CreateSlider({\n\t    Name = \"Timeout\",\n\t    Min = 0,\n\t    Max = 120,\n\t    Function = function(Val: number)\n\t        MaxWait:SetValue(Val)\n\t    end,\n\t    Default = 20,\n\t    Visible = false\n\t})\n\tAdvanced = MatchDodge:CreateToggle({\n\t    Name = \"Advanced\",\n\t    Function = function(Callback: boolean)\n\t        for _, v: any in {RankAdvantage, DeviceCheck, LowRank, Guaranteed} do\n\t            v.Object.Visible = Callback\n\t        end\n\t        if Device then\n\t            Device.Object.Visible = Callback and DeviceCheck.Enabled\n\t        end\n\t        if LowRankAt then\n\t            LowRankAt.Object.Visible = Callback and LowRank.Enabled\n\t        end\n\t    end,\n\t    Tooltip = \"Enables extra conditions for automatic loading\"\n\t})\n\tRankAdvantage = MatchDodge:CreateToggle({\n\t    Name = \"Rank Advantage\",\n\t    Darker = true,\n\t    Visible = false,\n\t    Tooltip = \"Requires your team, including you, to have a higher average rank division\"\n\t})\n\tDeviceCheck = MatchDodge:CreateToggle({\n\t    Name = \"Device Check\",\n\t    Function = function(Callback: boolean)\n\t        if Device then\n\t            Device.Object.Visible = Advanced.Enabled and Callback\n\t        end\n\t    end,\n\t    Darker = true,\n\t    Visible = false,\n\t    Tooltip = \"Requires every opponent to use one of the selected devices\"\n\t})\n\tDevice = MatchDodge:CreateDropdown({\n\t    Name = \"Device\",\n\t    List = {\"Mobile / Gamepad\", \"Mobile\", \"Gamepad\", \"PC\"},\n\t    Darker = true,\n\t    Visible = false\n\t})\n\tLowRank = MatchDodge:CreateToggle({\n\t    Name = \"Low Rank\",\n\t    Function = function(Callback: boolean)\n\t        if LowRankAt then\n\t            LowRankAt.Object.Visible = Advanced.Enabled and Callback\n\t        end\n\t    end,\n\t    Darker = true,\n\t    Visible = false,\n\t    Tooltip = \"Requires every opponent to be at or below the selected rank\"\n\t})\n\tLowRankAt = MatchDodge:CreateDropdown({\n\t    Name = \"Low Rank At\",\n\t    List = Tiers,\n\t    Default = \"Gold\",\n\t    Darker = true,\n\t    Visible = false\n\t})\n\tGuaranteed = MatchDodge:CreateToggle({\n\t    Name = \"Guaranteed 5v4\",\n\t    Darker = true,\n\t    Visible = false,\n\t    Tooltip = \"Waits for the match to start with 5 on your side and 4 opponents, with nobody still loading. Later reconnects can change the teams\"\n\t})\n\ttask.spawn(function()\n\t    repeat\n\t        task.wait()\n\t    until vape.Loaded or vape.Loaded == nil\n\t    local Last = isfile(`{vape.Directory}/profiles/matchdodge.json`) and readfile(`{vape.Directory}/profiles/matchdodge.json`)\n\t    if vape.Loaded and Last then\n\t        local Success, Result = pcall(HttpService.JSONDecode, HttpService, Last)\n\t        if Success and type(Result) == \"table\" then\n\t            if Result.Options and Result.Options[\"Max Wait\"] then\n\t                Result.Options.Timeout = Result.Options[\"Max Wait\"]\n\t            end\n\t            MatchDodge:Load(Result)\n\t        end\n\t    end\n\t\n\t    repeat\n\t        if vape.Loaded then\n\t            local Data = {}\n\t            MatchDodge:Save(Data)\n\t            Data.AutoMatchDodge.Favorited = nil\n\t            local Encoded: string = HttpService:JSONEncode(Data.AutoMatchDodge)\n\t            if Encoded ~= Last then\n\t                Last = Encoded\n\t                writefile(`{vape.Directory}/profiles/matchdodge.json`, Encoded)\n\t            end\n\t        end\n\t        task.wait(1)\n\t    until vape.Loaded == nil\n\tend)\nend)\n\nRun(function()\n\tlocal MatchHistory\n\t\n\tMatchHistory = vape.Categories.Utility:CreateModule({\n\t    Name = \"ViewMatchHistory\",\n\t    Function = function(Callback: boolean)\n\t        if Callback then\n\t            bedwars.Flamework.resolveDependency(\"@easy-games/game-core:client/controllers/app-controller@AppController\"):openApp({\n\t                appId = \"MatchHistoryApp\",\n\t                app = bedwars.ModerationApp\n\t            }, {\n\t                player = LocalPlayer,\n\t                matchHistory = {}\n\t            })\n\t            MatchHistory:Toggle()\n\t        end\n\t    end\n\t})\nend)\n\nRun(function()\n\tlocal NickHider\n\tlocal Replacement\n\tlocal ChatTags\n\tlocal Level\n\tlocal HideOthers\n\tlocal Swapped: {[Instance]: string} = setmetatable({}, {__mode = \"k\"})\n\tlocal Watched: {[Instance]: RBXScriptConnection} = setmetatable({}, {__mode = \"k\"})\n\tlocal Patterns: {string} = {}\n\tlocal Plain: {string} = {}\n\tlocal Shortest: number = math.huge\n\tlocal TextClasses: {[string]: boolean} = {TextLabel = true, TextButton = true, TextBox = true}\n\tlocal FakeName: string = \"hidden\"\n\tlocal Writing: Instance?\n\tlocal OldUsername, OldDisplayName, OldClanTag, OldLevel\n\t\n\tlocal Refreshing: boolean = false\n\t\n\tlocal function QueueRefresh()\n\t    if Refreshing or not NickHider or not NickHider.Enabled then\n\t        return\n\t    end\n\t    Refreshing = true\n\t\n\t    task.delay(0.35, function()\n\t        Refreshing = false\n\t        if NickHider.Enabled then\n\t            NickHider:Toggle()\n\t            NickHider:Toggle()\n\t        end\n\t    end)\n\tend\n\t\n\tlocal function ShouldHidePlayer(Player: Player?)\n\t    return Player and (Player.UserId == LocalPlayer.UserId or HideOthers.Enabled)\n\tend\n\t\n\tlocal function AddPlayerNames(Player: Player)\n\t    for _, v: string in {Player.Name, Player.DisplayName} do\n\t        if v ~= \"\" then\n\t            local LowerName: string = v:lower()\n\t            if not table.find(Plain, LowerName) then\n\t                table.insert(Plain, LowerName)\n\t                Shortest = math.min(Shortest, #LowerName)\n\t            end\n\t        end\n\t        for _, Variant: string in {v, v:lower(), v:upper()} do\n\t            local Pattern: string = (Variant:gsub(\"%W\", \"%%%0\"))\n\t            if Variant ~= \"\" and not table.find(Patterns, Pattern) then\n\t                table.insert(Patterns, Pattern)\n\t            end\n\t        end\n\t    end\n\tend\n\t\n\tlocal function IsLocal(GamePlayer): boolean\n\t    local Player: Player? = GamePlayer:getPlayer()\n\t    return Player ~= nil and Player.UserId == LocalPlayer.UserId\n\tend\n\t\n\tlocal function GetGamePlayerClass()\n\t    local GamePlayer = bedwars.GamePlayerUtil and bedwars.GamePlayerUtil.getGamePlayer(LocalPlayer)\n\t    local Meta = GamePlayer and getmetatable(GamePlayer)\n\t    return Meta and Meta.__index\n\tend\n\t\n\tlocal function HasPlayerName(Object: Instance)\n\t    local Ancestor: Instance? = Object.Parent\n\t    for _ = 1, 3 do\n\t        if not Ancestor then\n\t            return nil\n\t        end\n\t        local Label = Ancestor:FindFirstChild(\"PlayerName\", true)\n\t        if Label then\n\t            return Label\n\t        end\n\t        Ancestor = Ancestor.Parent\n\t    end\n\t    return nil\n\tend\n\t\n\tlocal function HideLevelObject(Object: Instance)\n\t    if not (Level.Enabled or HideOthers.Enabled) or not TextClasses[Object.ClassName] then\n\t        return\n\t    end\n\t    if not Object.Name:lower():find(\"level\", 1, true) then\n\t        return\n\t    end\n\t    local PlayerName = HasPlayerName(Object)\n\t    if not PlayerName or (not HideOthers.Enabled and not PlayerName.Text:find(FakeName, 1, true)) then\n\t        return\n\t    end\n\t\n\t    local function Apply()\n\t        if Writing == Object or not Object.Parent then\n\t            return\n\t        end\n\t        local Text = Object.Text\n\t        if type(Text) ~= \"string\" or Text == \"\" then\n\t            return\n\t        end\n\t\n\t        Swapped[Object] = Swapped[Object] or Text\n\t        Writing = Object\n\t        Object.Text = \"\"\n\t        Writing = nil\n\t    end\n\t\n\t    Apply()\n\t    if not Watched[Object] then\n\t        Watched[Object] = Object:GetPropertyChangedSignal(\"Text\"):Connect(Apply)\n\t    end\n\tend\n\t\n\tlocal function HideLevelSiblings(Object: Instance?)\n\t    if not Object then\n\t        return\n\t    end\n\t    for _, v: Instance in Object:GetDescendants() do\n\t        HideLevelObject(v)\n\t    end\n\tend\n\t\n\tlocal function ReplaceText(Object: Instance)\n\t    if Writing == Object then\n\t        return\n\t    end\n\t\n\t    local Text = Object.Text\n\t    if type(Text) ~= \"string\" or #Text < Shortest then\n\t        return\n\t    end\n\t\n\t    local Hit: boolean = false\n\t    for _, v: string in Plain do\n\t        if Text:find(v, 1, true) then\n\t            Hit = true\n\t            break\n\t        end\n\t    end\n\t    if not Hit then\n\t        local LowerText: string = Text:lower()\n\t        for _, v: string in Plain do\n\t            if LowerText:find(v, 1, true) then\n\t                Hit = true\n\t                break\n\t            end\n\t        end\n\t    end\n\t    if not Hit then\n\t        return\n\t    end\n\t\n\t    local NewText: string = Text\n\t    for _, v: string in Patterns do\n\t        if NewText:find(v) then\n\t            NewText = NewText:gsub(v, FakeName)\n\t        end\n\t    end\n\t    if NewText == Text then\n\t        return\n\t    end\n\t\n\t    Swapped[Object] = Text\n\t    Object:SetAttribute(\"NickHiderOriginalText\", Text)\n\t    Writing = Object\n\t    Object.Text = NewText\n\t    Writing = nil\n\t    HideLevelSiblings(Object.Parent)\n\t\n\t    if not Watched[Object] then\n\t        Watched[Object] = Object:GetPropertyChangedSignal(\"Text\"):Connect(function()\n\t            ReplaceText(Object)\n\t        end)\n\t    end\n\tend\n\t\n\tlocal function HideObject(Object: Instance)\n\t    if TextClasses[Object.ClassName] then\n\t        ReplaceText(Object)\n\t    end\n\tend\n\t\n\tlocal function Watch(Root: Instance?)\n\t    if not Root then\n\t        return\n\t    end\n\t\n\t    if vape.ThreadFix then\n\t        setthreadidentity(8)\n\t    end\n\t    NickHider:Clean(Root.DescendantAdded:Connect(function(Object: Instance)\n\t        if NickHider.Enabled then\n\t            HideObject(Object)\n\t            HideLevelObject(Object)\n\t        end\n\t    end))\n\t\n\t    local Clock: number = os.clock()\n\t    for _, v: Instance in Root:GetDescendants() do\n\t        HideObject(v)\n\t        HideLevelObject(v)\n\t\n\t        if os.clock() - Clock > 0.002 then\n\t            task.wait()\n\t            if not NickHider.Enabled then\n\t                return\n\t            end\n\t            Clock = os.clock()\n\t\n\t            if vape.ThreadFix then\n\t                setthreadidentity(8)\n\t            end\n\t        end\n\t    end\n\tend\n\t\n\tNickHider = vape.Categories.Utility:CreateModule({\n\t    Name = \"NickHider\",\n\t    ConfigName = \"NameHider\",\n\t    Function = function(Callback: boolean)\n\t        if Callback then\n\t            table.clear(Patterns)\n\t            table.clear(Plain)\n\t            Shortest = math.huge\n\t            for _, v: Player in Players:GetPlayers() do\n\t                if v == LocalPlayer or HideOthers.Enabled then\n\t                    AddPlayerNames(v)\n\t                end\n\t            end\n\t\n\t            FakeName = Replacement.Value ~= \"\" and Replacement.Value or \"hidden\"\n\t            for _, v: string in Patterns do\n\t                if FakeName:find(v) then\n\t                    FakeName = \"hidden\"\n\t                    break\n\t                end\n\t            end\n\t\n\t            local GamePlayer = GetGamePlayerClass()\n\t            if GamePlayer and not OldUsername then\n\t                OldUsername, OldDisplayName = GamePlayer.getUsername, GamePlayer.getDisplayName\n\t                OldClanTag, OldLevel = GamePlayer.getClanTag, GamePlayer.getLevel\n\t                GamePlayer.getUsername = function(self, ...)\n\t                    local Player: Player? = self:getPlayer()\n\t                    return ShouldHidePlayer(Player) and FakeName or OldUsername(self, ...)\n\t                end\n\t                GamePlayer.getDisplayName = function(self, ...)\n\t                    local Player: Player? = self:getPlayer()\n\t                    return ShouldHidePlayer(Player) and FakeName or OldDisplayName(self, ...)\n\t                end\n\t                GamePlayer.getClanTag = function(self, ...)\n\t                    return IsLocal(self) and ChatTags.Enabled and \"\" or OldClanTag(self, ...)\n\t                end\n\t                GamePlayer.getLevel = function(self, ...)\n\t                    local Player: Player? = self:getPlayer()\n\t                    if Player and (HideOthers.Enabled or (Player.UserId == LocalPlayer.UserId and Level.Enabled)) then\n\t                        return -1\n\t                    end\n\t                    return OldLevel(self, ...)\n\t                end\n\t            end\n\t\n\t            for _, v: Instance? in {LocalPlayer:FindFirstChildOfClass(\"PlayerGui\"), CoreGui, gethui and gethui() or nil, LocalPlayer.Character} do\n\t                Watch(v)\n\t            end\n\t\n\t            NickHider:Clean(LocalPlayer.CharacterAdded:Connect(function(Character: Model)\n\t                if NickHider.Enabled then\n\t                    Watch(Character)\n\t                end\n\t            end))\n\t            NickHider:Clean(Players.PlayerAdded:Connect(function()\n\t                if HideOthers.Enabled then\n\t                    QueueRefresh()\n\t                end\n\t            end))\n\t            NickHider:Clean(Players.PlayerRemoving:Connect(function()\n\t                if HideOthers.Enabled then\n\t                    QueueRefresh()\n\t                end\n\t            end))\n\t        else\n\t            local GamePlayer = GetGamePlayerClass()\n\t            if OldUsername and GamePlayer then\n\t                GamePlayer.getUsername, GamePlayer.getDisplayName = OldUsername, OldDisplayName\n\t                GamePlayer.getClanTag, GamePlayer.getLevel = OldClanTag, OldLevel\n\t                OldUsername, OldDisplayName, OldClanTag, OldLevel = nil, nil, nil, nil\n\t            end\n\t            if vape.ThreadFix then\n\t                setthreadidentity(8)\n\t            end\n\t\n\t            for _, v: RBXScriptConnection in Watched do\n\t                v:Disconnect()\n\t            end\n\t            table.clear(Watched)\n\t\n\t            for Object: Instance, v: string in Swapped do\n\t                if Object.Parent then\n\t                    Writing = Object\n\t                    Object.Text = v\n\t                    Object:SetAttribute(\"NickHiderOriginalText\", nil)\n\t                end\n\t            end\n\t            Writing = nil\n\t            table.clear(Swapped)\n\t        end\n\t    end,\n\t    Tooltip = \"Replaces your username and display name everywhere it shows up on your screen\",\n\t    ExtraText = function()\n\t        return Replacement.Value ~= \"\" and Replacement.Value or \"hidden\"\n\t    end\n\t})\n\t\n\tReplacement = NickHider:CreateTextBox({\n\t    Name = \"Name\",\n\t    Function = QueueRefresh,\n\t    Default = \"hidden\"\n\t})\n\tHideOthers = NickHider:CreateToggle({\n\t    Name = \"Hide others\",\n\t    Function = QueueRefresh,\n\t    Tooltip = \"Hides every player's username and level\"\n\t})\n\tChatTags = NickHider:CreateToggle({\n\t    Name = \"Hide chat tags\",\n\t    Tooltip = \"Hides your clan tag wherever it renders\"\n\t})\n\tLevel = NickHider:CreateToggle({\n\t    Name = \"Hide level\",\n\t    Function = QueueRefresh,\n\t    Tooltip = \"Hides your level wherever it renders\"\n\t})\nend)\n\nRun(function()\n\tlocal RegionLock\n\tlocal Regions\n\t\n\tRegionLock = vape.Categories.Utility:CreateModule({\n\t    Name = \"RegionLock\",\n\t    Function = function(Callback: boolean)\n\t        writefile(`{vape.Directory}/profiles/regionlock.txt`, tostring(Callback))\n\t        getgenv().regionLockActive = Callback\n\t    end,\n\t    Tooltip = \"Stays out of matches that are not hosted in one of your selected server regions; settings carry over into the match. BedWars only hosts NA, EU and SEA and picks yours from your account country\"\n\t})\n\t\n\tRegions = RegionLock:CreateTextList({\n\t    Name = \"Regions\",\n\t    Placeholder = \"NA / EU / SEA\",\n\t    Default = {\"NA\", \"EU\", \"SEA\"},\n\t    Function = function()\n\t        if not Regions then\n\t            return\n\t        end\n\t        for i: number, v: string in Regions.List do\n\t            Regions.List[i] = v:gsub(\"%s+\", \"\"):upper()\n\t        end\n\t        for i: number, v: string in Regions.ListEnabled do\n\t            Regions.ListEnabled[i] = v:gsub(\"%s+\", \"\"):upper()\n\t        end\n\t    end,\n\t    Tooltip = \"Turn off the regions you do not want. AUS, OCE, AU and NZ all count as SEA, US counts as NA. Leaving every region on accepts anything\"\n\t})\n\t\n\ttask.spawn(function()\n\t    repeat\n\t        task.wait()\n\t    until vape.Loaded or vape.Loaded == nil\n\t    local Last = isfile(`{vape.Directory}/profiles/regionlock.json`) and readfile(`{vape.Directory}/profiles/regionlock.json`)\n\t    if vape.Loaded and Last then\n\t        local Success, Result = pcall(HttpService.JSONDecode, HttpService, Last)\n\t        if Success and type(Result) == \"table\" then\n\t            RegionLock:Load(Result)\n\t        end\n\t    end\n\t\n\t    repeat\n\t        if vape.Loaded then\n\t            local Data = {}\n\t            RegionLock:Save(Data)\n\t            Data.RegionLock.Favorited = nil\n\t            local Encoded: string = HttpService:JSONEncode(Data.RegionLock)\n\t            if Encoded ~= Last then\n\t                Last = Encoded\n\t                writefile(`{vape.Directory}/profiles/regionlock.json`, Encoded)\n\t            end\n\t        end\n\t        task.wait(1)\n\t    until vape.Loaded == nil\n\tend)\nend)\n\nRun(function()\n\tlocal SetEmote\n\tlocal Emote\n\tlocal Track: AnimationTrack?\n\tlocal Billboard: BillboardGui?\n\tlocal Moved: RBXScriptConnection?\n\t\n\tlocal List, EmoteTypes = {}, {}\n\tfor EmoteType: any, v: any in bedwars.EmoteMeta do\n\t    if EmoteType ~= bedwars.EmoteType.NONE and v.name and not EmoteTypes[v.name] then\n\t        EmoteTypes[v.name] = EmoteType\n\t        table.insert(List, v.name)\n\t    end\n\tend\n\ttable.sort(List)\n\t\n\tlocal function CancelEmote()\n\t    if Moved then\n\t        Moved:Disconnect()\n\t        Moved = nil\n\t    end\n\t    if Track then\n\t        Track:Stop()\n\t        Track:Destroy()\n\t        Track = nil\n\t    end\n\t    if Billboard then\n\t        Billboard:Destroy()\n\t        Billboard = nil\n\t    end\n\t\n\t    local Maid = bedwars.EmoteController and bedwars.EmoteController.emoteAudioMaids and bedwars.EmoteController.emoteAudioMaids[LocalPlayer.UserId]\n\t    if Maid then\n\t        Maid:DoCleaning()\n\t    end\n\t\n\t    if Entity.isAlive and LocalPlayer.Character:GetAttribute(\"PlayingEmote\") then\n\t        LocalPlayer.Character:SetAttribute(\"PlayingEmote\", nil)\n\t    end\n\tend\n\t\n\tSetEmote = vape.Categories.Utility:CreateModule({\n\t    Name = \"SetEmote\",\n\t    Function = function(Callback: boolean)\n\t        if Callback then\n\t            SetEmote:Toggle()\n\t            if Entity.isAlive then\n\t                local EmoteType = EmoteTypes[Emote.Value]\n\t                local Meta = bedwars.EmoteMeta[EmoteType]\n\t                if Meta then\n\t                    LocalPlayer.Character:SetAttribute(\"PlayingEmote\", EmoteType)\n\t                    local PlayBeginSounds = bedwars.EmoteController and (bedwars.EmoteController.createEmoteBeginAudioPlayers or bedwars.EmoteController.playEmoteBeginSounds)\n\t                    if PlayBeginSounds then\n\t                        PlayBeginSounds(bedwars.EmoteController, EmoteType, LocalPlayer)\n\t                    end\n\t                    local Animation = Meta.animation\n\t                    if not Animation and Meta.emoteDisplayType then\n\t                        local Display = bedwars.EmoteDisplayMeta[Meta.emoteDisplayType]\n\t                        Animation = Display and Display.animation\n\t                    end\n\t                    if Animation then\n\t                        Track = LocalPlayer.Character.Humanoid:LoadAnimation(bedwars.GameAnimationUtil:getAnimation(Animation.type))\n\t                        Track.Looped = Animation.looped or false\n\t                        Track:Play(nil, nil, Animation.speed or 1)\n\t                    end\n\t                    if not Meta.animation then\n\t                        local Gui: BillboardGui = Instance.new(\"BillboardGui\")\n\t                        Billboard = Gui\n\t                        Gui.Size = UDim2.fromScale(6, 2.5)\n\t                        Gui.StudsOffset = Vector3.new(0, 2, 0)\n\t                        Gui.AlwaysOnTop = true\n\t                        Gui.Adornee = LocalPlayer.Character.Head\n\t\n\t                        local Image: ImageLabel = Instance.new(\"ImageLabel\")\n\t                        Image.AnchorPoint = Vector2.new(0.5, 1)\n\t                        Image.Position = UDim2.fromScale(0.5, 1)\n\t                        Image.Size = UDim2.fromScale(0, 0)\n\t                        Image.Image = Meta.image\n\t                        Image.BackgroundTransparency = 1\n\t                        Image.ImageTransparency = 1\n\t                        Image.ScaleType = Enum.ScaleType.Fit\n\t                        Image.Parent = Gui\n\t\n\t                        Gui.Parent = LocalPlayer.Character.Head\n\t                        TweenService:Create(Image, TweenInfo.new(0.4, Enum.EasingStyle.Exponential, Enum.EasingDirection.Out), {\n\t                            Position = UDim2.fromScale(0.5, 0.5),\n\t                            Size = UDim2.fromScale(1, 1),\n\t                            ImageTransparency = 0\n\t                        }):Play()\n\t                    end\n\t                    if Meta.allowMovement then\n\t                        task.delay(6, CancelEmote)\n\t                    else\n\t                        Moved = LocalPlayer.Character.Humanoid:GetPropertyChangedSignal(\"MoveDirection\"):Connect(CancelEmote)\n\t                    end\n\t                end\n\t            end\n\t        end\n\t    end,\n\t    Tooltip = \"Plays the selected emote on your character, other players can see it too\"\n\t})\n\t\n\tEmote = SetEmote:CreateDropdown({\n\t    Name = \"Emote\",\n\t    List = List,\n\t    Default = \"nightmare\"\n\t})\nend)"},{"path":"src/games/6872274481.lua","name":"6872274481.lua","size":1774215,"sha":"af0633983c0508aa76b38891b1e6ab4635d11ece","encoding":"utf8","content":"local vape = shared.vape\nlocal loadstring = function(...)\n    local Chunk, Message = loadstring(...)\n    if Message and vape then\n        vape:CreateNotification(\"Vape\", `Failed to load : {Message}`, 30, \"alert\")\n    end\n    return Chunk\nend\nlocal isfile = isfile or function(File: string): boolean\n    local Success, Result = pcall(function()\n        return readfile(File)\n    end)\n    return Success and Result ~= nil and Result ~= \"\"\nend\nlocal function DownloadFile(FilePath: string, Func)\n    if not isfile(FilePath) then\n        local Success, Result = pcall(function()\n            return game:HttpGet(`https://api.catvape.dev/download/src/{select(1, FilePath:gsub(`^{vape.Directory}/`, \"\"))}`, true)\n        end)\n        if not Success or Result == \"404: Not Found\" then\n            error(Result)\n        end\n        if FilePath:find(\".lua\") then\n            Result = `--This watermark is used to delete the file if its cached, remove it to make the file persist after vape updates.\\n{Result}`\n        end\n        writefile(FilePath, Result)\n    end\n    return (Func or readfile)(FilePath)\nend\nvape.Libraries.replayvisuals = loadstring(DownloadFile(`{vape.Directory}/libraries/replayvisuals.lua`), \"ReplayVisuals\")()\nvape.Libraries.swordtiming = loadstring(DownloadFile(`{vape.Directory}/libraries/swordtiming.lua`), \"SwordTiming\")()\nlocal Run = function(Func: () -> ())\n    xpcall(Func, function(Message)\n        task.spawn(error, Message)\n        vape:CreateNotification(\"Vape\", `A module failed to load: {Message}`, 15, \"alert\")\n    end)\n\n    vape.YieldBuild()\nend\nlocal cloneref = cloneref or function(Reference: Instance)\n    return Reference\nend\nlocal VapeEvents = setmetatable({}, {\n    __index = function(self, Index: string)\n        local Bindable: BindableEvent = Instance.new(\"BindableEvent\")\n        self[Index] = {\n            Event = {\n                Connect = function(_, Callback: (...any) -> ())\n                    return Bindable.Event:Connect(function(...)\n                        if vape.ThreadFix then\n                            setthreadidentity(8)\n                        end\n                        Callback(...)\n                    end)\n                end,\n                Wait = function()\n                    return Bindable.Event:Wait()\n                end\n            },\n            Fire = function(_, ...)\n                Bindable:Fire(...)\n            end,\n            Destroy = function()\n                Bindable:Destroy()\n            end\n        }\n        return self[Index]\n    end\n})\ngetgenv().vapeEvents = VapeEvents\n\nlocal Players: Players = cloneref(game:GetService(\"Players\"))\nlocal ReplicatedStorage: ReplicatedStorage = cloneref(game:GetService(\"ReplicatedStorage\"))\nlocal RunService: RunService = cloneref(game:GetService(\"RunService\"))\nlocal UserInputService: UserInputService = cloneref(game:GetService(\"UserInputService\"))\nlocal TweenService: TweenService = cloneref(game:GetService(\"TweenService\"))\nlocal HttpService: HttpService = cloneref(game:GetService(\"HttpService\"))\nlocal TextChatService: TextChatService = cloneref(game:GetService(\"TextChatService\"))\nlocal CollectionService: CollectionService = cloneref(game:GetService(\"CollectionService\"))\nlocal ContextActionService: ContextActionService = cloneref(game:GetService(\"ContextActionService\"))\nlocal ProximityPromptService: ProximityPromptService = cloneref(game:GetService(\"ProximityPromptService\"))\nlocal Lighting: Lighting = cloneref(game:GetService(\"Lighting\"))\nlocal GuiService: GuiService = cloneref(game:GetService(\"GuiService\"))\nlocal CoreGui: CoreGui = cloneref(game:GetService(\"CoreGui\"))\nlocal StarterGui: StarterGui = cloneref(game:GetService(\"StarterGui\"))\nlocal TeleportService: TeleportService = cloneref(game:GetService(\"TeleportService\"))\n\nlocal isnetworkowner = isnetworkowner or function()\n    return true\nend\nlocal Camera: Camera = workspace.CurrentCamera\nlocal LocalPlayer: Player = Players.LocalPlayer\nlocal AssetFunction = getcustomasset\n\nvape.Libraries.navigation = loadstring(DownloadFile(`{vape.Directory}/libraries/navigation.lua`), \"navigation\")()\nvape.Libraries.bedwarsbrain = vape.Libraries.navigation.Brain\nvape.Libraries.bedwarscontroller = vape.Libraries.navigation.Controller\nvape.Libraries.bedwarsadapter = vape.Libraries.navigation.Adapter\n\nlocal Entity = vape.Libraries.entity\nlocal TargetInfo = vape.Libraries.targetinfo\nlocal SessionInfo = vape.Libraries.sessioninfo\nlocal UIPallet = vape.Libraries.uipallet\nlocal Tween = vape.Libraries.tween\nlocal Color = vape.Libraries.color\nlocal Whitelist = vape.Libraries.whitelist\nlocal PredictionLib = vape.Libraries.prediction\nlocal GetFontBounds = vape.Libraries.getfontbounds\nlocal GetVapeAsset = vape.Libraries.getvapeasset\nlocal Navigation = vape.Libraries.navigation\n\nfor _, v: string in {\"markKnockback\", \"reportHit\", \"trackShot\", \"expectKnockback\"} do\n    PredictionLib[v] = PredictionLib[v] or function() end\nend\n\nlocal RankCache = setmetatable({}, {__mode = \"k\"})\nlocal bedwars = {}\nlocal Store = {\n    attackReach = 0,\n    lastAttack = 0,\n    lastHit = 0,\n    attackReachUpdate = tick(),\n    damageBlockFail = tick(),\n    hand = {},\n    swordSpeeds = {},\n    inventory = {\n        inventory = {\n            items = {},\n            armor = {}\n        },\n        hotbar = {}\n    },\n    rank = setmetatable({}, {\n        __index = function(self, Player: Player)\n            return {async = function()\n                if RankCache[Player] then\n                    return RankCache[Player]\n                end\n\n                if Player then\n                    local Rank = bedwars.Handler:Get(\"FetchRanks\"):Fire(\"CallServer\", {Player.UserId})\n                    if typeof(Rank) == \"table\" and Rank[1] and Rank[1].rankDivision then\n                        RankCache[Player] = Rank[1].rankDivision\n                        return RankCache[Player]\n                    end\n                end\n\n                return nil\n            end}\n        end\n    }),\n    inventories = setmetatable({}, {__mode = \"k\"}),\n    hitchance = {},\n    matchState = 0,\n    queueType = \"bedwars_test\",\n    tools = {},\n    ping = {},\n    readyHold = getgenv().matchDodgeHold or {}\n}\nfunction Store.readyHold.Release()\n    if not Store.readyHold.Held then\n        return\n    end\n\n    Store.readyHold.Held = false\n    getgenv().dodged = false\n    if Store.readyHold.Remote then\n        Store.readyHold.Remote:FireServer()\n        Store.readyHold.Remote = nil\n    end\nend\n\nif not getgenv().matchDodgeHold and (getgenv().matchDodgeActive or getgenv().regionLockActive) and not LocalPlayer:GetAttribute(\"PlayerConnected\") and hookmetamethod and not table.find({\"Madium\", \"Solara\", \"Xeno\"}, ({identifyexecutor()})[1]) then\n    local Old: (...any) -> ...any\n    Store.readyHold.Held = true\n    Store.readyHold.Started = os.clock()\n    Old = hookmetamethod(game, \"__namecall\", newcclosure(function(...)\n        local self = ...\n        if Store.readyHold.Held and not checkcaller() and getnamecallmethod() == \"FireServer\" and tostring(self) == \"PlayerReady\" then\n            Store.readyHold.Remote = self\n            return\n        end\n        return Old(...)\n    end))\n\n    task.delay(45, function()\n        if not Store.readyHold.Claimed then\n            Store.readyHold.Release()\n        end\n    end)\nend\nvape:Clean(function()\n    Store.readyHold.Release()\nend)\nlocal Reach = {}\nlocal HitBoxes = {}\nlocal TrapDisabler = {}\nlocal TrapSnap, TrapMine, TrapTeleport, TrapPortal = {}, {}, {}, {}\nlocal KnockbackSpoof = {}\nlocal KnockbackMode, KnockbackDelay, KnockbackRewind = {}, {}, {}\nlocal AntiFallPart\nlocal Sides, OldInventoryRender = {}\n\nlocal function AddBlur(Parent: Instance): ImageLabel\n    local Blur: ImageLabel = Instance.new(\"ImageLabel\")\n    Blur.Name = \"Blur\"\n    Blur.Size = UDim2.new(1, 89, 1, 52)\n    Blur.Position = UDim2.fromOffset(-48, -31)\n    Blur.BackgroundTransparency = 1\n    Blur.Image = GetVapeAsset(`{vape.Directory}/assets/new/blur.png`)\n    Blur.ScaleType = Enum.ScaleType.Slice\n    Blur.SliceCenter = Rect.new(52, 31, 261, 502)\n    Blur.Parent = Parent\n    return Blur\nend\ngetgenv().addBlur = AddBlur\n\nlocal function CreateProgressBar()\n    local Frame: Frame = Instance.new(\"Frame\")\n    Frame.AnchorPoint = Vector2.new(0.5, 0)\n    Frame.Position = UDim2.new(0.5, 0, 1, -200)\n    Frame.Size = UDim2.new(0.2, 0, 0, 20)\n    Frame.BackgroundTransparency = 0.5\n    Frame.BorderSizePixel = 0\n    Frame.BackgroundColor3 = Color3.new(0, 0, 0)\n    Frame.Visible = false\n    if vape.ThreadFix then\n        setthreadidentity(8)\n    end\n    Frame.Parent = vape.gui\n\n    local Fill: Frame = Instance.new(\"Frame\")\n    Fill.Size = UDim2.new(1, 0, 0, 20)\n    Fill.BorderSizePixel = 0\n    Fill.BackgroundColor3 = Color3.fromHSV(vape.GUIColor.Hue, vape.GUIColor.Sat, vape.GUIColor.Value)\n    Fill.Parent = Frame\n\n    local Label: TextLabel = Instance.new(\"TextLabel\")\n    Label.Font = Enum.Font.Gotham\n    Label.TextStrokeTransparency = 0\n    Label.TextColor3 = Color3.new(0.9, 0.9, 0.9)\n    Label.TextSize = 20\n    Label.Size = UDim2.fromScale(1, 1)\n    Label.Position = UDim2.fromScale(0, -1)\n    Label.BackgroundTransparency = 1\n    Label.Parent = Frame\n\n    local LastText, LastScale, LastColor = \"\", -1, nil\n    return {\n        Frame = Frame,\n        Set = function(Remaining: number, Total: number)\n            local Color: Color3 = Color3.fromHSV(vape.GUIColor.Hue, vape.GUIColor.Sat, vape.GUIColor.Value)\n            if Color ~= LastColor then\n                LastColor = Color\n                Fill.BackgroundColor3 = Color\n            end\n\n            local Scale: number = math.clamp(Remaining / Total, 0, 1)\n            if Scale ~= LastScale then\n                LastScale = Scale\n                Fill.Size = UDim2.new(Scale, 0, 0, 20)\n            end\n\n            local Text: string = `{string.format(\"%.1f\", math.max(Remaining, 0))}s`\n            if Text ~= LastText then\n                LastText = Text\n                Label.Text = Text\n            end\n        end\n    }\nend\ngetgenv().createProgressBar = CreateProgressBar\n\nlocal function Collection(Tags, Module, CustomAdd, CustomRemove)\n    Tags = typeof(Tags) ~= \"table\" and {Tags} or Tags\n    local Objects, Indexes, Connections = {}, {}, {}\n\n    for _, v: string in Tags do\n        table.insert(Connections, CollectionService:GetInstanceAddedSignal(v):Connect(function(Object: Instance)\n            if CustomAdd then\n                CustomAdd(Objects, Object, v)\n                return\n            end\n            Objects[#Objects + 1] = Object\n            Indexes[Object] = #Objects\n        end))\n        table.insert(Connections, CollectionService:GetInstanceRemovedSignal(v):Connect(function(Object: Instance)\n            if CustomRemove then\n                CustomRemove(Objects, Object, v)\n                return\n            end\n            if CustomAdd then\n                local Index: number? = table.find(Objects, Object)\n                if Index then\n                    table.remove(Objects, Index)\n                end\n                return\n            end\n\n            local Index: number? = Indexes[Object]\n            if Index then\n                local Size: number = #Objects\n                local Last = Objects[Size]\n                Objects[Index] = Last\n                Indexes[Last] = Index\n                Objects[Size] = nil\n                Indexes[Object] = nil\n            end\n        end))\n\n        for _, Object: Instance in CollectionService:GetTagged(v) do\n            if CustomAdd then\n                CustomAdd(Objects, Object, v)\n                continue\n            end\n            Objects[#Objects + 1] = Object\n            Indexes[Object] = #Objects\n        end\n    end\n\n    local function CleanFunc(self)\n        for _, v: RBXScriptConnection in Connections do\n            v:Disconnect()\n        end\n        table.clear(Connections)\n        table.clear(Objects)\n        table.clear(Indexes)\n        table.clear(self)\n    end\n    if Module then\n        Module:Clean(CleanFunc)\n    end\n    return Objects, CleanFunc\nend\ngetgenv().collection = Collection\n\nlocal function GetBestArmor(Slot: number)\n    local Best, BestReduction = nil, 0\n\n    for _, v: any in Store.inventory.inventory.items do\n        local Meta = v and bedwars.ItemMeta[v.itemType] or {}\n        if Meta.armor and Meta.armor.slot == Slot then\n            local Reduction: number = (Meta.armor.damageReductionMultiplier or 0)\n            if Reduction > BestReduction then\n                Best, BestReduction = v, Reduction\n            end\n        end\n    end\n\n    return Best\nend\ngetgenv().getBestArmor = GetBestArmor\n\nlocal function GetBow()\n    local BestBow, BestBowSlot, BestBowDamage = nil, nil, 0\n    for Slot: number, v: any in Store.inventory.inventory.items do\n        local BowMeta = bedwars.ItemMeta[v.itemType].projectileSource\n        if BowMeta and table.find(BowMeta.ammoItemTypes, \"arrow\") then\n            local BowDamage: number = bedwars.ProjectileMeta[BowMeta.projectileType(\"arrow\")].combat.damage or 0\n            if BowDamage > BestBowDamage then\n                BestBow, BestBowSlot, BestBowDamage = v, Slot, BowDamage\n            end\n        end\n    end\n    return BestBow, BestBowSlot\nend\ngetgenv().getBow = GetBow\n\nlocal function MatchesList(List, Names): boolean\n    for _, v: string in List do\n        local Needle: string = (tostring(v):lower():gsub(\"[_%s]+\", \" \"))\n        if #Needle > 0 then\n            for _, Name: string in Names do\n                if Name then\n                    Name = (tostring(Name):lower():gsub(\"[_%s]+\", \" \"))\n                    if Name == Needle or (` {Name}`):find(` {Needle}`, 1, true) then\n                        return true\n                    end\n                end\n            end\n        end\n    end\n    return false\nend\n\nlocal function GetMageSource(ItemType: string)\n    if ItemType ~= \"wizard_stick\" then\n        return nil\n    end\n\n    local Util = bedwars.MageKitUtil\n    local Elements = Util and Util.MageElementMeta\n    if not Elements then\n        return nil\n    end\n\n    local Chosen = Elements.BASE\n    local Success, Unlocked = pcall(Util.getUnlockedMageElements, LocalPlayer)\n    if Success and type(Unlocked) == \"table\" then\n        for i: number, v: string in Unlocked do\n            local Element = Elements[v] or Elements[i]\n            if Element and Element.projectileSource then\n                Chosen = Element\n            end\n        end\n    end\n\n    return Chosen and Chosen.projectileSource\nend\n\nlocal SophiaStaffs: {string} = {\"frost_staff_3\", \"frost_staff_2\", \"frost_staff_1\"}\nlocal NextSophiaSwap: number = 0\n\nlocal function GetSophiaSource(ItemType: string)\n    if not table.find(SophiaStaffs, ItemType) then\n        return nil\n    end\n\n    local Controller = bedwars.FrostyGunController\n    if not Controller then\n        return nil\n    end\n\n    if Controller.projectileMode ~= bedwars.FrostyGunMode.PROJECTILE then\n        if tick() >= NextSophiaSwap and bedwars.AbilityController:canUseAbility(\"frosty_gun_swap\", {disableBlockedAbilityAlert = true}) then\n            NextSophiaSwap = tick() + 1\n            bedwars.AbilityController:useAbility(\"frosty_gun_swap\")\n        end\n        return nil\n    end\n\n    local Meta = bedwars.ItemMeta[ItemType]\n    return Meta and Meta.projectileSource or nil\nend\n\nlocal function GetWhimSource(ItemType: string)\n    if ItemType ~= \"mage_spellbook\" then\n        return nil\n    end\n\n    local Util = bedwars.MageKitUtil\n    local Elements = Util and Util.MageElementMeta\n    if not Elements then\n        return nil\n    end\n\n    local Element = bedwars.BalanceFile.MAGE_ELEMENT_CYCLE[(LocalPlayer:GetAttribute(\"MageElementIndex\") or 0) + 1]\n    local Success, Unlocked = pcall(Util.getUnlockedMageElements, LocalPlayer)\n    if not Element or not Success or type(Unlocked) ~= \"table\" or table.find(Unlocked, Element) == nil then\n        Element = \"BASE\"\n    end\n\n    local Meta = Elements[Element]\n    return Meta and Meta.projectileSource or nil\nend\n\nlocal NazarWeapons: {string} = {\"life_bow\", \"life_crossbow\", \"life_headhunter\"}\n\nlocal function GetNazarSource(ItemType: string)\n    if not table.find(NazarWeapons, ItemType) then\n        return nil\n    end\n\n    local Meta = bedwars.ItemMeta[ItemType]\n    return Meta and Meta.projectileSource or nil\nend\n\nlocal function GetUmekoSource(ItemType: string)\n    if not ItemType:match(\"^ninja_chakram_%d+$\") then\n        return nil\n    end\n\n    local Controller = bedwars.ChakramController\n    if Controller and Controller.chakramIsLaunched then\n        return nil\n    end\n\n    local Meta = bedwars.ItemMeta[ItemType]\n    return Meta and Meta.projectileSource or nil\nend\n\nlocal function GetProjectiles(Whitelist, Sophia: boolean?, Whim: boolean?, Nazar: boolean?, Umeko: boolean?)\n    local Items = {}\n    for _, v: any in Store.inventory.inventory.items do\n        local Meta = bedwars.ItemMeta[v.itemType]\n        local Kit = (Sophia and GetSophiaSource(v.itemType)) or (Whim and GetWhimSource(v.itemType)) or (Nazar and GetNazarSource(v.itemType)) or (Umeko and GetUmekoSource(v.itemType)) or nil\n        local Projectile = Kit or (Meta and (Meta.projectileSource or GetMageSource(v.itemType)))\n        if Projectile then\n            local Ammo\n            if Projectile.ammoItemTypes and #Projectile.ammoItemTypes > 0 then\n                for _, Item: any in Store.inventory.inventory.items do\n                    if table.find(Projectile.ammoItemTypes, Item.itemType) then\n                        Ammo = Item.itemType\n                        break\n                    end\n                end\n            else\n                Ammo = v.itemType\n            end\n\n            if Ammo and (Kit or not Whitelist or MatchesList(Whitelist, {Ammo, v.itemType, Meta.displayName})) then\n                table.insert(Items, {\n                    v,\n                    Ammo,\n                    Projectile.projectileType(Ammo),\n                    Projectile\n                })\n            end\n        end\n    end\n\n    return Items\nend\ngetgenv().getProjectiles = GetProjectiles\n\nlocal function GetFacingEntity(EntitySettings)\n    if not Entity.isAlive then\n        return nil\n    end\n\n    local RootPart: BasePart = Entity.character.RootPart\n    local Origin: Vector3 = EntitySettings.Origin or RootPart.Position\n    local Facing: Vector3 = RootPart.CFrame.LookVector * Vector3.new(1, 0, 1)\n    local Cone: number = math.rad((EntitySettings.Angle or 120) / 2)\n    EntitySettings.Angle = nil\n    EntitySettings.Origin = Origin\n\n    for _, v: any in Entity.AllPosition(EntitySettings) do\n        local Delta: Vector3 = (v.RootPart.Position - Origin) * Vector3.new(1, 0, 1)\n        if Facing.Magnitude == 0 or Delta.Magnitude == 0 or math.acos(math.clamp(Facing.Unit:Dot(Delta.Unit), -1, 1)) <= Cone then\n            return v\n        end\n    end\n    return nil\nend\ngetgenv().getFacingEntity = GetFacingEntity\n\nlocal function SolveProjectile(Origin: Vector3, Speed: number, Gravity: number, Target)\n    return PredictionLib.SolveTrajectory(Origin, Speed, Gravity, Target.RootPart.Position, Target.RootPart.AssemblyLinearVelocity, workspace.Gravity, Target.HipHeight, Target.Jumping and 42.6 or nil, nil, Target.Humanoid.FloorMaterial == Enum.Material.Air or math.abs(Target.RootPart.AssemblyLinearVelocity.Y) > 0.01, Target.RootPart.Position, Target.RootPart, nil, true)\nend\n\nlocal function WatchProjectile(RefId: string, Origin: Vector3, Velocity: Vector3, Gravity: number, Target, Lifetime: number?)\n    local Character: Model? = Target and Target.Character\n    if not Character or Velocity.Magnitude <= 0 then\n        return\n    end\n\n    local Overlap: OverlapParams = OverlapParams.new()\n    Overlap.FilterType = Enum.RaycastFilterType.Include\n    Overlap.FilterDescendantsInstances = {Character}\n    local Box: Vector3 = Vector3.new(3, 1, 3)\n    local Drop: Vector3 = Vector3.new(0, -Gravity, 0)\n    local Steps: number = math.clamp(math.ceil(Velocity.Magnitude / 170), 1, 16)\n    local Started: number = os.clock()\n    local Last: Vector3 = Origin\n    local Watcher: RBXScriptConnection\n    Watcher = RunService.Heartbeat:Connect(function()\n        local Elapsed: number = os.clock() - Started\n        if Elapsed > (Lifetime or 2) or not Character.Parent then\n            Watcher:Disconnect()\n            return\n        end\n\n        local Position: Vector3 = Origin + Velocity * Elapsed + Drop * (0.5 * Elapsed * Elapsed)\n        for Step: number = 1, Steps do\n            if #workspace:GetPartBoundsInBox(CFrame.new(Last:Lerp(Position, Step / Steps)), Box, Overlap) > 0 then\n                Watcher:Disconnect()\n                bedwars.Handler:Get(\"ProjectileHit\"):Fire(\"SendToServer\", RefId, Character)\n                return\n            end\n        end\n\n        if Store.airRay and workspace:Raycast(Last, Position - Last, Store.airRay) then\n            Watcher:Disconnect()\n            return\n        end\n        Last = Position\n    end)\nend\ngetgenv().watchProjectile = WatchProjectile\n\nlocal ArcParams: RaycastParams = RaycastParams.new()\nArcParams.FilterType = Enum.RaycastFilterType.Exclude\n\nlocal function FireProjectile(Item, Ammo: string, Projectile: string, Target): boolean\n    local Meta = bedwars.ProjectileMeta[Projectile]\n    if not Meta then\n        return false\n    end\n\n    local Origin: Vector3 = Entity.character.RootPart.Position\n    local Speed, Gravity = Meta.launchVelocity, Meta.gravitationalAcceleration or 196.2\n    local Solution = SolveProjectile(Origin, Speed, Gravity, Target)\n    if not Solution then\n        return false\n    end\n\n    local ShootPosition: Vector3 = (CFrame.new(Origin, Solution) * CFrame.new(Vector3.new(-bedwars.BowConstantsTable.RelX, -bedwars.BowConstantsTable.RelY, -bedwars.BowConstantsTable.RelZ))).Position\n    local Aim, _, Flight = SolveProjectile(ShootPosition, Speed, Gravity, Target)\n    Aim = Aim or Solution\n    local Velocity, Id = CFrame.lookAt(ShootPosition, Aim).LookVector * Speed, bedwars.IdUtil.generateId(8)\n    ArcParams.FilterDescendantsInstances = {LocalPlayer.Character, Camera}\n    if Flight and not PredictionLib.IsTrajectoryClear(ShootPosition, Velocity, Gravity, Flight, ArcParams, Target.Character) then\n        return false\n    end\n    bedwars.Handler:Get(\"ProjectileFire\"):Fire(\"CallServerAsync\",\n        Item.tool,\n        Ammo,\n        Projectile,\n        ShootPosition,\n        Origin,\n        Velocity,\n        Id,\n        bedwars.getShotData(Item.itemType),\n        workspace:GetServerTimeNow() - 0.045\n    ):andThen(function(Result)\n        if type(Result) == \"table\" and Result.accepted and Result.model then\n            Result.model.Parent = ReplicatedStorage\n        end\n    end)\n    WatchProjectile(Id, ShootPosition, Velocity, Gravity, Target, Meta.lifetimeSec)\n    PredictionLib.trackShot(Target.RootPart)\n    return true\nend\ngetgenv().fireProjectile = FireProjectile\n\nlocal function GetItem(ItemName: string, Inventory, Find: boolean?)\n    for Slot: number, v: any in (Inventory or Store.inventory.inventory.items) do\n        if v.itemType == ItemName or (Find and v.itemType:find(ItemName)) then\n            return v, Slot\n        end\n    end\n    return nil\nend\ngetgenv().getItem = GetItem\n\nlocal function GetRoactRender(Func)\n    return debug.getupvalue(debug.getupvalue(debug.getupvalue(Func, 3).render, 2).render, 1)\nend\n\nlocal function CreateGuiOverrides()\n    local Objects: {[Instance]: any} = {}\n    local function Restore()\n        for Object: Instance, Saved: any in Objects do\n            Saved.Destroying:Disconnect()\n            for Property: string, Value: any in Saved.Properties do\n                Value.Connection:Disconnect()\n                if Object.Parent and Object[Property] == Value.Applied then\n                    Object[Property] = Value.Original\n                end\n            end\n        end\n        table.clear(Objects)\n    end\n\n    local function Apply(Object: Instance, Properties: {[string]: any})\n        local Saved = Objects[Object]\n        if not Saved then\n            Saved = {Properties = {}}\n            Objects[Object] = Saved\n            Saved.Destroying = Object.Destroying:Connect(function()\n                Objects[Object] = nil\n            end)\n        end\n\n        for Property: string, Applied: any in Properties do\n            local Value = Saved.Properties[Property]\n            if not Value then\n                Value = {Original = Object[Property], Applied = Applied}\n                Saved.Properties[Property] = Value\n                Value.Connection = Object:GetPropertyChangedSignal(Property):Connect(function()\n                    if Objects[Object] == Saved and Object[Property] ~= Value.Applied then\n                        Value.Original = Object[Property]\n                        Object[Property] = Value.Applied\n                    end\n                end)\n            end\n            Value.Applied = Applied\n            Object[Property] = Applied\n        end\n    end\n\n    return {Apply = Apply, Restore = Restore}\nend\n\nlocal function GetSword()\n    local BestSword, BestSwordSlot, BestSwordDamage, BestSwordRange = nil, nil, -1, -1\n    for Slot: number, v: any in Store.inventory.inventory.items do\n        local ItemMeta = bedwars.ItemMeta[v.itemType]\n        local SwordMeta = ItemMeta and ItemMeta.sword or nil\n        if SwordMeta then\n            local SwordDamage: number = SwordMeta.damage or 0\n            local SwordRange: number = SwordMeta.attackRange or Store.swordDistance or 0\n            if SwordDamage > BestSwordDamage or (SwordDamage == BestSwordDamage and SwordRange > BestSwordRange) then\n                BestSword, BestSwordSlot, BestSwordDamage, BestSwordRange = v, Slot, SwordDamage, SwordRange\n            end\n        end\n    end\n    return BestSword, BestSwordSlot\nend\ngetgenv().getSword = GetSword\n\nlocal function GetTool(BreakType: string)\n    local BestTool, BestToolSlot, BestToolDamage = nil, nil, 0\n    for Slot: number, v: any in Store.inventory.inventory.items do\n        local ToolMeta = bedwars.ItemMeta[v.itemType].breakBlock\n        if ToolMeta then\n            local ToolDamage: number = ToolMeta[BreakType] or 0\n            if ToolDamage > BestToolDamage then\n                BestTool, BestToolSlot, BestToolDamage = v, Slot, ToolDamage\n            end\n        end\n    end\n    return BestTool, BestToolSlot\nend\ngetgenv().getTool = GetTool\n\nlocal function GetWool()\n    for _, v: any in Store.inventory.inventory.items do\n        if v.itemType:find(\"wool\") then\n            return v.itemType, v.amount\n        end\n    end\nend\ngetgenv().getWool = GetWool\n\nlocal function GetStrength(Ent): number\n    if not Ent.Player then\n        return 0\n    end\n\n    local Strength: number = 0\n    for _, v: any in (Store.inventories[Ent.Player] or {items = {}}).items do\n        local ItemMeta = bedwars.ItemMeta[v.itemType]\n        if ItemMeta and ItemMeta.sword and ItemMeta.sword.damage > Strength then\n            Strength = ItemMeta.sword.damage\n        end\n    end\n\n    return Strength\nend\ngetgenv().getStrength = GetStrength\n\nlocal function IsCasting()\n    local Casting = LocalPlayer:GetAttribute(\"IsCasting\")\n    return Casting and Casting ~= 0 and Casting ~= \"\"\nend\ngetgenv().isCasting = IsCasting\n\nlocal function CanSwing()\n    if bedwars.SwordController:getSwordSwingDisabled() or IsCasting() then\n        return false\n    end\n\n    local ItemMeta = Store.hand.tool and bedwars.ItemMeta[Store.hand.tool.Name]\n    return ItemMeta and ItemMeta.sword ~= nil and ItemMeta.sword.chargedAttack == nil\nend\ngetgenv().canSwing = CanSwing\n\nlocal function CanPlace(): boolean\n    return not bedwars.BlockPlacementController.disabled and not IsCasting()\nend\ngetgenv().canPlace = CanPlace\n\nStore.lastInput = tick()\nlocal function MarkInput(Input: InputObject)\n    if Input.UserInputType ~= Enum.UserInputType.MouseMovement or Input.Delta.Magnitude > 0 then\n        Store.lastInput = tick()\n    end\nend\nvape:Clean(UserInputService.InputBegan:Connect(MarkInput))\nvape:Clean(UserInputService.InputChanged:Connect(MarkInput))\n\nlocal function IsAfk(): boolean\n    return (tick() - Store.lastInput) >= 30\nend\ngetgenv().isAfk = IsAfk\n\nlocal function GetReach(Tool: Tool?)\n    local ItemMeta = Tool and bedwars.ItemMeta[Tool.Name]\n    return ItemMeta and ItemMeta.sword and ItemMeta.sword.attackRange or Store.swordDistance\nend\ngetgenv().getReach = GetReach\n\nlocal function GetSwordSpeed(Tool: Tool?): number\n    local ItemMeta = Tool and bedwars.ItemMeta[Tool.Name]\n    return Store.swordSpeeds[Tool and Tool.Name] or (ItemMeta and ItemMeta.sword and ItemMeta.sword.attackSpeed) or 0.3\nend\ngetgenv().getSwordSpeed = GetSwordSpeed\n\nlocal function GetTinkerMount(): Model?\n    local Controller = bedwars.TinkerKitController\n    local Mount = Controller and Controller.userMap and Controller.userMap[LocalPlayer]\n    if typeof(Mount) == \"Instance\" and Mount.Parent then\n        return Mount\n    end\n\n    local Character: Model? = LocalPlayer.Character\n    if Character then\n        for _, v: Instance in Character:GetChildren() do\n            if v:IsA(\"Model\") and v.Name:match(\"tinker$\") then\n                return v\n            end\n        end\n    end\n\n    return nil\nend\ngetgenv().getTinkerMount = GetTinkerMount\n\nlocal TargetLimbs: {[string]: {string}} = {\n    Torso = {\"UpperTorso\", \"LowerTorso\"},\n    [\"Left arm\"] = {\"LeftUpperArm\", \"LeftLowerArm\", \"LeftHand\"},\n    [\"Right arm\"] = {\"RightUpperArm\", \"RightLowerArm\", \"RightHand\"},\n    [\"Left leg\"] = {\"LeftUpperLeg\", \"LeftLowerLeg\", \"LeftFoot\"},\n    [\"Right leg\"] = {\"RightUpperLeg\", \"RightLowerLeg\", \"RightFoot\"}\n}\nlocal LimbOrder: {string} = {\"Head\", \"Torso\", \"Left arm\", \"Right arm\", \"Left leg\", \"Right leg\"}\nlocal PartList: {string} = {\"RootPart\", \"Head\", \"Torso\", \"Left arm\", \"Right arm\", \"Left leg\", \"Right leg\", \"Random\"}\ngetgenv().partlist = PartList\n\nlocal function IsHeadshotProjectile(ItemType: string?)\n    return ItemType and (ItemType:find(\"headhunter\", 1, true) or ItemType:find(\"tactical\", 1, true) or Store.equippedKit == \"archer\")\nend\ngetgenv().isHeadshotProjectile = IsHeadshotProjectile\n\nlocal RandomLimb = setmetatable({}, {__mode = \"k\"})\n\nlocal function GetTargetPart(Ent, Mode: string)\n    if Mode == \"Random\" and Ent.Character then\n        local Pick = RandomLimb[Ent.Character]\n        if not Pick or tick() > Pick.Clock then\n            Pick = {Value = LimbOrder[math.random(1, #LimbOrder)], Clock = tick() + 1}\n            RandomLimb[Ent.Character] = Pick\n        end\n        Mode = Pick.Value\n    end\n\n    if Mode == \"Head\" then\n        return (Ent.Character and Ent.Character:FindFirstChild(\"Head\")) or Ent.Head or Ent.RootPart\n    end\n\n    local Limbs = TargetLimbs[Mode]\n    if Limbs and Ent.Character then\n        for _, v: string in Limbs do\n            local Part = Ent.Character:FindFirstChild(v)\n            if Part then\n                return Part\n            end\n        end\n    end\n\n    return Ent.RootPart\nend\ngetgenv().getTargetPart = GetTargetPart\n\nlocal function GetPlacedBlock(Position: Vector3?)\n    if not Position then\n        return\n    end\n    local RoundedPosition: Vector3 = bedwars.BlockController:getBlockPosition(Position)\n    return bedwars.BlockController:getStore():getBlockAt(RoundedPosition), RoundedPosition\nend\ngetgenv().getPlacedBlock = GetPlacedBlock\n\nlocal function GetBlocksInPoints(From: Vector3, To: Vector3): {Vector3}\n    local Blocks, List = bedwars.BlockController:getStore(), {}\n    for X: number = From.X, To.X do\n        for Y: number = From.Y, To.Y do\n            for Z: number = From.Z, To.Z do\n                local Vector: Vector3 = Vector3.new(X, Y, Z)\n                if Blocks:getBlockAt(Vector) then\n                    table.insert(List, Vector * 3)\n                end\n            end\n        end\n    end\n    return List\nend\ngetgenv().getBlocksInPoints = GetBlocksInPoints\n\nlocal function GetNearGround(Range)\n    Range = Vector3.new(3, 3, 3) * (Range or 10)\n    local LocalPosition, Distance, Closest = Entity.character.RootPart.Position, 60\n    local Blocks = GetBlocksInPoints(bedwars.BlockController:getBlockPosition(LocalPosition - Range), bedwars.BlockController:getBlockPosition(LocalPosition + Range))\n    for _, v: Vector3 in Blocks do\n        if not GetPlacedBlock(v + Vector3.new(0, 3, 0)) then\n            local NewDistance: number = (LocalPosition - v).Magnitude\n            if NewDistance < Distance then\n                Distance, Closest = NewDistance, v + Vector3.new(0, 3, 0)\n            end\n        end\n    end\n\n    table.clear(Blocks)\n    return Closest\nend\ngetgenv().getNearGround = GetNearGround\n\nlocal function GetShieldAttribute(Character: Model): number\n    return math.max(Character:GetAttribute(\"TotalShield\") or 0, 0)\nend\ngetgenv().getShieldAttribute = GetShieldAttribute\n\nlocal function MarkKnockback(DamageTable)\n    local Character = DamageTable.entityInstance\n    local Multiplier = DamageTable.knockbackMultiplier\n    if typeof(Character) ~= \"Instance\" or (Multiplier and Multiplier.disabled) then\n        return\n    end\n\n    local Root = Character:IsA(\"Model\") and Character.PrimaryPart or Character:IsA(\"BasePart\") and Character or nil\n    local From = DamageTable.fromPosition\n    local Impulse\n    if Root and From then\n        local Direction = bedwars.KnockbackUtil.getDirection(Root.Position, From)\n        if Direction.Magnitude > 0 then\n            Impulse = bedwars.KnockbackUtil.calculateKnockbackVelocity(Direction, 1, Multiplier)\n        end\n    end\n\n    PredictionLib.markKnockback(Character, Multiplier, Impulse)\nend\n\nlocal function ExpectKnockback(Root, Flight: number?, From: Vector3?, Multiplier)\n    if typeof(Root) ~= \"Instance\" or not Flight or not From then\n        return\n    end\n    if Multiplier and Multiplier.disabled then\n        return\n    end\n\n    local Direction = bedwars.KnockbackUtil.getDirection(Root.Position, From)\n    if Direction.Magnitude <= 0 then\n        return\n    end\n\n    PredictionLib.expectKnockback(Root, workspace:GetServerTimeNow() + Flight, bedwars.KnockbackUtil.calculateKnockbackVelocity(Direction, 1, Multiplier), Multiplier)\nend\ngetgenv().expectKnockback = ExpectKnockback\n\nlocal function ScanProjectile(Origin: Vector3, Velocity: Vector3, ProjectileType: string, Shooter)\n    if not Entity.isAlive then\n        return\n    end\n\n    local Meta = bedwars.ProjectileMeta[ProjectileType]\n    local Drop: Vector3 = Vector3.new(0, -(Meta and Meta.gravitationalAcceleration or 196.2), 0)\n\n    for _, v: any in Entity.List do\n        if v.Character == Shooter then\n            continue\n        end\n\n        local Root, Hit = v.RootPart\n        local RootVelocity: Vector3 = Root.AssemblyLinearVelocity\n        local RootPosition: Vector3 = Root.Position\n        local HipHeight: number = v.HipHeight\n        for Step: number = 1, 40 do\n            local Flight: number = Step * 0.05\n            local Point: Vector3 = Origin + Velocity * Flight + Drop * (0.5 * Flight * Flight)\n            if (Point - (RootPosition + RootVelocity * Flight)).Magnitude <= HipHeight then\n                Hit = Flight\n                break\n            end\n        end\n\n        if Hit then\n            ExpectKnockback(Root, Hit, Origin, Meta and Meta.knockback)\n        end\n    end\nend\ngetgenv().scanProjectile = ScanProjectile\n\nlocal function ReportProjectileHit(DamageTable)\n    local Character = DamageTable.entityInstance\n    local From = DamageTable.fromEntity\n    if (From ~= LocalPlayer.Character and From ~= LocalPlayer) or typeof(Character) ~= \"Instance\" then\n        return\n    end\n\n    local Root = Character:IsA(\"Model\") and Character.PrimaryPart or Character:IsA(\"BasePart\") and Character or nil\n    if Root then\n        PredictionLib.reportHit(Root)\n    end\nend\n\nlocal KnockbackSpeed, KnockbackBoost = 0, tick()\nlocal function GetSpeed(): number\n    local Multiplier, Increase, Modifiers = 0, true, bedwars.SprintController:getMovementStatusModifier():getModifiers()\n    for Modifier: any in Modifiers do\n        local Value = Modifier.constantSpeedMultiplier and Modifier.constantSpeedMultiplier or 0\n        if Value and Value > math.max(Multiplier, 1) then\n            Increase = false\n            Multiplier = Value - (0.06 * math.round(Value))\n        end\n    end\n\n    for Modifier: any in Modifiers do\n        Multiplier += math.max((Modifier.moveSpeedMultiplier or 0) - 1, 0)\n    end\n\n    if Multiplier > 0 and Increase then\n        Multiplier += 0.16 + (0.02 * math.round(Multiplier))\n    end\n\n    return (20 + (KnockbackBoost > tick() and KnockbackSpeed or 0)) * (Multiplier + 1)\nend\ngetgenv().getSpeed = GetSpeed\n\nlocal function GetTableSize(Table): number\n    local Size: number = 0\n    for _ in Table do\n        Size += 1\n    end\n    return Size\nend\ngetgenv().getTableSize = GetTableSize\n\nlocal function SwitchItem(Tool: Tool, DelayTime: number?)\n    DelayTime = DelayTime or 0.05\n    local HandValue: ObjectValue? = LocalPlayer.Character and LocalPlayer.Character:FindFirstChild(\"HandInvItem\") or nil\n    if HandValue and HandValue.Value ~= Tool and Tool.Parent ~= nil then\n        task.spawn(function()\n            bedwars.Handler:Get(\"SetInvItem\"):Fire(\"CallServerAsync\", {hand = Tool})\n        end)\n        HandValue.Value = Tool\n        if DelayTime > 0 then\n            task.wait(DelayTime)\n        end\n        return true\n    end\nend\ngetgenv().switchItem = SwitchItem\n\nlocal function GetHotbar(Tool)\n    for i: number, v: any in (Store.inventory.hotbar or {}) do\n        if v.item and v.item.tool == Tool then\n            return i - 1\n        end\n    end\n    return nil\nend\ngetgenv().getHotbar = GetHotbar\n\nlocal function HotbarSwitch(Slot: number?): boolean\n    if not Slot then\n        return false\n    end\n\n    if not canDebug then\n        local Entry = Store.inventory.hotbar and Store.inventory.hotbar[Slot + 1]\n        local Tool: Tool? = Entry and Entry.item and Entry.item.tool\n        if not Tool then\n            return false\n        end\n\n        local Visual = vape.Libraries.cheatengine and vape.Libraries.cheatengine.HotbarVisual\n        local Real: number? = Visual and Visual.GetSlot(Tool)\n        if Real then\n            Visual.Select(Real)\n            local Deadline: number = tick() + 0.3\n            repeat\n                task.wait()\n            until Store.hand.tool == Tool or tick() > Deadline\n            if Store.hand.tool ~= Tool then\n                SwitchItem(Tool, 0)\n            end\n\n            return true\n        end\n\n        return SwitchItem(Tool, 0) == true\n    end\n\n    if Store.inventory.hotbarSlot ~= Slot then\n        bedwars.Store:dispatch({\n            type = \"InventorySelectHotbarSlot\",\n            slot = Slot\n        })\n        VapeEvents.InventoryChanged.Event:Wait()\n        return true\n    end\n    return false\nend\ngetgenv().hotbarSwitch = HotbarSwitch\n\nlocal function IsFriend(Player: Player, Recolor: boolean?)\n    if vape.Categories.Friends.Options[\"Use friends\"].Enabled then\n        local Friend = table.find(vape.Categories.Friends.ListEnabled, Player.Name) and true\n        if Recolor then\n            Friend = Friend and vape.Categories.Friends.Options[\"Recolor visuals\"].Enabled\n        end\n        return Friend\n    end\n    return nil\nend\n\nlocal function IsTarget(Player: Player)\n    return table.find(vape.Categories.Targets.ListEnabled, Player.Name) and true\nend\n\nlocal function SendNotification(...)\n    return vape:CreateNotification(...)\nend\ngetgenv().notif = SendNotification\n\nlocal function RemoveTags(Text: string): string\n    Text = Text:gsub(\"<br%s*/>\", \"\\n\")\n    return (Text:gsub(\"<[^<>]->\", \"\"))\nend\ngetgenv().removeTags = RemoveTags\n\nlocal function RoundPosition(Vector: Vector3): Vector3\n    return Vector3.new(math.round(Vector.X / 3) * 3, math.round(Vector.Y / 3) * 3, math.round(Vector.Z / 3) * 3)\nend\ngetgenv().roundPos = RoundPosition\n\nlocal function WaitForChildOfType(Object, Name: string, Timeout: number, Property: boolean?)\n    local Deadline, Returned = tick() + Timeout\n    repeat\n        Returned = Property and Object[Name] or Object:FindFirstChildOfClass(Name)\n        if Returned and Returned.Name ~= \"UpperTorso\" or Deadline < tick() then\n            break\n        end\n        task.wait()\n    until false\n    return Returned\nend\n\nlocal FrictionTable, OldFriction = {}, setmetatable({}, {__mode = \"k\"})\nlocal FrictionConnection\nlocal FrictionState\n\nlocal function ModifyVelocity(Part: Instance)\n    if Part:IsA(\"BasePart\") and Part.Name ~= \"HumanoidRootPart\" and not OldFriction[Part] then\n        OldFriction[Part] = Part.CustomPhysicalProperties or \"none\"\n        Part.CustomPhysicalProperties = PhysicalProperties.new(0.0001, 0.2, 0.5, 1, 1)\n    end\nend\n\nlocal function UpdateVelocity(Force)\n    local NewState: boolean = next(FrictionTable) ~= nil\n    if FrictionState ~= NewState or Force then\n        if FrictionConnection then\n            FrictionConnection:Disconnect()\n        end\n        if NewState then\n            if Entity.isAlive then\n                for _, v: Instance in Entity.character.Character:GetDescendants() do\n                    ModifyVelocity(v)\n                end\n                FrictionConnection = Entity.character.Character.DescendantAdded:Connect(ModifyVelocity)\n            end\n        else\n            for Part: BasePart, v: PhysicalProperties | string in OldFriction do\n                Part.CustomPhysicalProperties = v ~= \"none\" and v or nil\n            end\n            table.clear(OldFriction)\n        end\n    end\n    FrictionState = NewState\nend\n\nlocal KitOrder: {[string]: number} = {\n    hannah = 5,\n    spirit_assassin = 4,\n    dasher = 3,\n    jade = 2,\n    regent = 1\n}\n\nlocal SortMethods = {\n    Damage = function(A, B): boolean\n        return (A.Entity.Character:GetAttribute(\"LastDamageTakenTime\") or 0) < (B.Entity.Character:GetAttribute(\"LastDamageTakenTime\") or 0)\n    end,\n    Threat = function(A, B): boolean\n        return GetStrength(A.Entity) > GetStrength(B.Entity)\n    end,\n    Kit = function(A, B): boolean\n        return (A.Entity.Player and KitOrder[A.Entity.Player:GetAttribute(\"PlayingAsKits\")] or 0) > (B.Entity.Player and KitOrder[B.Entity.Player:GetAttribute(\"PlayingAsKits\")] or 0)\n    end,\n    Health = function(A, B): boolean\n        return A.Entity.Health < B.Entity.Health\n    end,\n    Angle = function(A, B): boolean\n        local SelfRootPosition: Vector3 = Entity.character.RootPart.Position\n        local LocalFacing: Vector3 = Entity.character.RootPart.CFrame.LookVector * Vector3.new(1, 0, 1)\n        local DirectionA: Vector3 = (A.Entity.RootPart.Position - SelfRootPosition) * Vector3.new(1, 0, 1)\n        local DirectionB: Vector3 = (B.Entity.RootPart.Position - SelfRootPosition) * Vector3.new(1, 0, 1)\n        local AngleA: number = DirectionA.Magnitude > 0 and math.acos(math.clamp(LocalFacing:Dot(DirectionA.Unit), -1, 1)) or 0\n        local AngleB: number = DirectionB.Magnitude > 0 and math.acos(math.clamp(LocalFacing:Dot(DirectionB.Unit), -1, 1)) or 0\n        return AngleA < AngleB\n    end,\n    Mouse = function(A, B): boolean\n        local Mouse: Mouse = LocalPlayer:GetMouse()\n        local Origin: Vector2 = Vector2.new(Mouse.X, Mouse.Y)\n\n        local PositionA, VisibleA = Camera:WorldToScreenPoint(A.Entity.RootPart.Position)\n        local PositionB, VisibleB = Camera:WorldToScreenPoint(B.Entity.RootPart.Position)\n        local DistanceA: number = VisibleA and (Vector2.new(PositionA.X, PositionA.Y) - Origin).Magnitude or math.huge\n        local DistanceB: number = VisibleB and (Vector2.new(PositionB.X, PositionB.Y) - Origin).Magnitude or math.huge\n        return (DistanceA == DistanceA and DistanceA or math.huge) < (DistanceB == DistanceB and DistanceB or math.huge)\n    end\n}\ngetgenv().sortmethods = SortMethods\n\nlocal SortList: {string} = {}\nfor Name: string in SortMethods do\n    table.insert(SortList, Name)\nend\ntable.sort(SortList)\ngetgenv().sortlist = SortList\n\nlocal Motion = setmetatable({}, {__mode = \"k\"})\n\nlocal function GetHitChance(Ent, Flight: number?): number\n    if not Flight or Flight ~= Flight or Flight <= 0 then\n        return 0\n    end\n\n    local Root: BasePart = Ent.RootPart\n    local Velocity: Vector3 = Root.AssemblyLinearVelocity * Vector3.new(1, 0, 1)\n    local Sample = Motion[Root]\n    if not Sample then\n        Sample = {velocity = Velocity, clock = os.clock(), accel = 0, speed = Velocity.Magnitude}\n        Motion[Root] = Sample\n    end\n\n    local Step: number = os.clock() - Sample.clock\n    if Step >= 0.05 then\n        local Blend: number = math.min(Step * 5, 1)\n        Sample.accel += (((Velocity - Sample.velocity).Magnitude / Step) - Sample.accel) * Blend\n        Sample.speed += (Velocity.Magnitude - Sample.speed) * Blend\n        Sample.velocity, Sample.clock = Velocity, os.clock()\n    end\n\n    local Drift: number = math.max(Sample.speed, Velocity.Magnitude) * math.min(Flight, 0.4) * math.clamp(Sample.accel / 120, 0, 1)\n    return 1 / (1 + ((Drift / 3) ^ 2))\nend\ngetgenv().getHitChance = GetHitChance\n\nlocal GetBlockHits\nlocal BreakMethods = {\n    Health = function(Block, BlockPosition)\n        return GetBlockHits(Block, BlockPosition)\n    end,\n    Distance = function(Block, BlockPosition)\n        local Position: Vector3 = (Entity.isAlive and (Entity.character.RootPart.Position - Vector3.new(0, 1, 0)) or Vector3.zero)\n        return (Position - Vector3.new(Block.Position.X, Position.Y, Block.Position.Z)).Magnitude + GetBlockHits(Block, BlockPosition) * 0.01\n    end\n}\n\nRun(function()\n    local OldStart = Entity.start\n    local function CustomEntity(Character: Model)\n        if Character:HasTag(\"inventory-entity\") and not Character:HasTag(\"Monster\") and not Character:HasTag(\"trainingRoomDummy\") then\n            return\n        end\n\n        Entity.addEntity(Character, nil, Character:HasTag(\"Drone\") and function(self)\n            local DronePlayer: Player? = Players:GetPlayerByUserId(self.Character:GetAttribute(\"PlayerUserId\"))\n            return not DronePlayer or LocalPlayer:GetAttribute(\"Team\") ~= DronePlayer:GetAttribute(\"Team\")\n        end or function(self)\n            return LocalPlayer:GetAttribute(\"Team\") ~= self.Character:GetAttribute(\"Team\")\n        end)\n    end\n\n    Entity.start = function()\n        OldStart()\n        if Entity.Running then\n            for _, v: Model in CollectionService:GetTagged(\"entity\") do\n                CustomEntity(v)\n            end\n            table.insert(Entity.Connections, CollectionService:GetInstanceAddedSignal(\"entity\"):Connect(CustomEntity))\n            table.insert(Entity.Connections, CollectionService:GetInstanceRemovedSignal(\"entity\"):Connect(function(Character: Model)\n                Entity.removeEntity(Character)\n            end))\n        end\n    end\n\n    Entity.addPlayer = function(Player: Player)\n        if Player.Character then\n            Entity.refreshEntity(Player.Character, Player)\n        end\n        Entity.PlayerConnections[Player] = {\n            Player.CharacterAdded:Connect(function(Character: Model)\n                Entity.refreshEntity(Character, Player)\n            end),\n            Player.CharacterRemoving:Connect(function(Character: Model)\n                Entity.removeEntity(Character, Player == LocalPlayer)\n            end),\n            Player:GetAttributeChangedSignal(\"Team\"):Connect(function()\n                for _, v: any in Entity.List do\n                    if v.Targetable ~= Entity.targetCheck(v) then\n                        Entity.refreshEntity(v.Character, v.Player)\n                    end\n                end\n\n                if Player == LocalPlayer then\n                    Entity.start()\n                else\n                    Entity.refreshEntity(Player.Character, Player)\n                end\n            end)\n        }\n    end\n\n    Entity.addEntity = function(Character: Model, Player: Player?, TeamFunction)\n        if not Character then\n            return\n        end\n        Entity.EntityThreads[Character] = task.spawn(function()\n            local Humanoid, HumanoidRootPart, Head\n            if Player then\n                Humanoid = WaitForChildOfType(Character, \"Humanoid\", 10)\n                HumanoidRootPart = Humanoid and WaitForChildOfType(Humanoid, \"RootPart\", workspace.StreamingEnabled and 9e9 or 10, true)\n                Head = Character:WaitForChild(\"Head\", 10) or HumanoidRootPart\n            else\n                Humanoid = Character:FindFirstChildOfClass(\"Humanoid\") or {HipHeight = 0.5}\n                HumanoidRootPart = WaitForChildOfType(Character, \"PrimaryPart\", 10, true)\n                Head = HumanoidRootPart\n            end\n            local UpdateObjects = Player and Player ~= LocalPlayer and {\n                Character:WaitForChild(\"ArmorInvItem_0\", 5),\n                Character:WaitForChild(\"ArmorInvItem_1\", 5),\n                Character:WaitForChild(\"ArmorInvItem_2\", 5),\n                Character:WaitForChild(\"HandInvItem\", 5)\n            } or {}\n\n            if Humanoid and HumanoidRootPart then\n                local Ent = {\n                    Connections = {},\n                    Character = Character,\n                    Health = (Character:GetAttribute(\"Health\") or 100) + GetShieldAttribute(Character),\n                    Head = Head,\n                    Humanoid = Humanoid,\n                    HumanoidRootPart = HumanoidRootPart,\n                    HipHeight = Humanoid.HipHeight + (HumanoidRootPart.Size.Y / 2) + (Humanoid.RigType == Enum.HumanoidRigType.R6 and 2 or 0),\n                    Jumps = 0,\n                    JumpTick = tick(),\n                    Jumping = false,\n                    LandTick = tick(),\n                    MaxHealth = Character:GetAttribute(\"MaxHealth\") or 100,\n                    NPC = Player == nil,\n                    Player = Player,\n                    RootPart = HumanoidRootPart,\n                    TeamCheck = TeamFunction\n                }\n\n                if Player == LocalPlayer then\n                    Ent.AirTime = tick()\n                    Entity.character = Ent\n                    Entity.isAlive = true\n                    Entity.Events.LocalAdded:Fire(Ent)\n                    table.insert(Ent.Connections, Character.AttributeChanged:Connect(function(Attribute: string)\n                        VapeEvents.AttributeChanged:Fire(Attribute)\n                    end))\n                    table.insert(Ent.Connections, Character.AttributeChanged:Connect(function(Attribute: string)\n                        if Attribute == \"Health\" or Attribute == \"MaxHealth\" or Attribute:find(\"Shield\") then\n                            Ent.Health = (Character:GetAttribute(\"Health\") or 100) + GetShieldAttribute(Character)\n                            Ent.MaxHealth = Character:GetAttribute(\"MaxHealth\") or 100\n                        end\n                    end))\n                    for _, v: RBXScriptSignal in {Humanoid:GetPropertyChangedSignal(\"HipHeight\"), HumanoidRootPart:GetPropertyChangedSignal(\"Size\")} do\n                        table.insert(Ent.Connections, v:Connect(function()\n                            Ent.HipHeight = Humanoid.HipHeight + (HumanoidRootPart.Size.Y / 2) + (Humanoid.RigType == Enum.HumanoidRigType.R6 and 2 or 0)\n                        end))\n                    end\n                else\n                    Ent.Targetable = Entity.targetCheck(Ent)\n\n                    for _, v: any in Entity.getUpdateConnections(Ent) do\n                        table.insert(Ent.Connections, v:Connect(function()\n                            Ent.Health = (Character:GetAttribute(\"Health\") or 100) + GetShieldAttribute(Character)\n                            Ent.MaxHealth = Character:GetAttribute(\"MaxHealth\") or 100\n                            Ent.HipHeight = Humanoid.HipHeight + (HumanoidRootPart.Size.Y / 2) + (Humanoid.RigType == Enum.HumanoidRigType.R6 and 2 or 0)\n                            Entity.Events.EntityUpdated:Fire(Ent)\n                        end))\n                    end\n\n                    for _, v: ObjectValue in UpdateObjects do\n                        table.insert(Ent.Connections, v:GetPropertyChangedSignal(\"Value\"):Connect(function()\n                            task.delay(0.1, function()\n                                if bedwars.getInventory then\n                                    Store.inventories[Player] = bedwars.getInventory(Player)\n                                    Entity.Events.EntityUpdated:Fire(Ent)\n                                end\n                            end)\n                        end))\n                    end\n\n                    if Player then\n                        local JumpAnimation = Character:FindFirstChild(\"Animate\")\n                        if JumpAnimation then\n                            pcall(function()\n                                JumpAnimation = JumpAnimation.jump:FindFirstChildWhichIsA(\"Animation\").AnimationId\n                                table.insert(Ent.Connections, Humanoid.Animator.AnimationPlayed:Connect(function(PlayedAnimation: AnimationTrack)\n                                    if PlayedAnimation.Animation.AnimationId == JumpAnimation then\n                                        Ent.JumpTick = tick()\n                                        Ent.Jumps += 1\n                                        Ent.LandTick = tick() + 1\n                                        Ent.Jumping = Ent.Jumps > 1\n                                    end\n                                end))\n                            end)\n                        end\n\n                        task.delay(0.1, function()\n                            if bedwars.getInventory then\n                                Store.inventories[Player] = bedwars.getInventory(Player)\n                            end\n                        end)\n                    end\n                    table.insert(Entity.List, Ent)\n                    Entity.Events.EntityAdded:Fire(Ent)\n                end\n\n                table.insert(Ent.Connections, Character.ChildRemoved:Connect(function(Part: Instance)\n                    if Part == HumanoidRootPart or Part == Humanoid or Part == Head then\n                        if Part == HumanoidRootPart and Humanoid.RootPart then\n                            HumanoidRootPart = Humanoid.RootPart\n                            Ent.RootPart = Humanoid.RootPart\n                            Ent.HumanoidRootPart = Humanoid.RootPart\n                            return\n                        end\n                        Entity.removeEntity(Character, Player == LocalPlayer)\n                    end\n                end))\n            end\n            Entity.EntityThreads[Character] = nil\n        end)\n    end\n\n    Entity.getUpdateConnections = function(Ent)\n        local Character: Model = Ent.Character\n        local Signals = {\n            Character:GetAttributeChangedSignal(\"Health\"),\n            Character:GetAttributeChangedSignal(\"MaxHealth\"),\n            {\n                Connect = function()\n                    Ent.Friend = Ent.Player and IsFriend(Ent.Player) or nil\n                    Ent.Target = Ent.Player and IsTarget(Ent.Player) or nil\n                    return {Disconnect = function() end}\n                end\n            }\n        }\n\n        if Ent.Player then\n            table.insert(Signals, Ent.Player:GetAttributeChangedSignal(\"PlayingAsKits\"))\n        end\n\n        table.insert(Signals, Character:GetAttributeChangedSignal(\"TotalShield\"))\n\n        return Signals\n    end\n\n    Entity.targetCheck = function(Ent)\n        if Ent.TeamCheck then\n            return Ent:TeamCheck()\n        end\n        if Ent.NPC then\n            return true\n        end\n        if IsFriend(Ent.Player) then\n            return false\n        end\n        return LocalPlayer:GetAttribute(\"Team\") ~= Ent.Player:GetAttribute(\"Team\")\n    end\n    vape:Clean(Entity.Events.LocalAdded:Connect(UpdateVelocity))\nend)\nEntity.start()\n\nlocal require, debug, CheatEngineLib = require, debug, nil\nRun(function()\n    getgenv().canDebug = not table.find({\"Solara\", \"Xeno\"}, ({identifyexecutor()})[1]) and true or false\n    if not canDebug then\n        CheatEngineLib = loadstring(DownloadFile(`{vape.Directory}/libraries/cheatengine.lua`), \"cheatengine\")(vape, VapeEvents, Entity)\n        require = function(Module: Instance)\n            return CheatEngineLib[({Module:GetFullName():gsub(LocalPlayer.Name, \"PlayerTemplate\")})[1]]:await()\n        end\n        debug = CheatEngineLib.Debug\n    end\nend)\n\nlocal CalculatePath\nRun(function()\n    local Client, OldGet, OldBreak, OldHit, OldWallcheck, OldSetBlock\n    local WrapRemote\n    local KnitInit, Knit\n    repeat\n        KnitInit, Knit = pcall(function()\n            if not canDebug then\n                return require(ReplicatedStorage[\"rbxts_include\"][\"node_modules\"][\"@easy-games\"].knit.src).KnitClient\n            end\n            return debug.getupvalue(require(LocalPlayer.PlayerScripts.TS.knit).setup, 9)\n        end)\n        if KnitInit and Knit then\n            break\n        end\n        task.wait()\n    until KnitInit and Knit\n\n    if canDebug and not debug.getupvalue(Knit.Start, 1) then\n        repeat\n            task.wait()\n        until debug.getupvalue(Knit.Start, 1)\n    end\n\n    local Flamework = require(ReplicatedStorage[\"rbxts_include\"][\"node_modules\"][\"@flamework\"].core.out).Flamework\n    local InventoryUtil = require(ReplicatedStorage.TS.inventory[\"inventory-util\"]).InventoryUtil\n    local ItemMetaModule = require(ReplicatedStorage.TS.item[\"item-meta\"])\n    local TeamUpgradeModule = require(ReplicatedStorage.TS.games.bedwars[\"team-upgrade\"][\"team-upgrade-meta\"])\n    local Remotes = require(ReplicatedStorage.TS.remotes).default\n    Client = Remotes.Client\n    OldGet = Client.Get\n\n    local RemoteHandler = {}\n    RemoteHandler.CachedRemotes = {}\n    RemoteHandler.__index = RemoteHandler\n\n    local RemoteDefinitionConstruct, RemotesInConstruct\n    if canDebug then\n        RemoteDefinitionConstruct, RemotesInConstruct = next(getupvalue(getrawmetatable(Remotes.Server).Get, 1))\n    end\n\n    local GlobalMiddleware = RemoteDefinitionConstruct and getupvalue(RemoteDefinitionConstruct.globalMiddleware[2], 1)\n    if canDebug and (not GlobalMiddleware or typeof(GlobalMiddleware) ~= \"table\") then\n        SendNotification(\"Cat\", \"Failed to load ratelimits, report this to a developer.\", 30, \"alert\")\n    end\n\n    local function GetRemote(RemoteID: string)\n        local Found, Remote = pcall(Client.GetOrThrow, Client, RemoteID)\n        if not Found or not Remote then\n            return Client:Get(RemoteID)\n        end\n\n        return WrapRemote and WrapRemote(Remote, RemoteID) or Remote\n    end\n\n    function RemoteHandler.Get(self, RemoteID: string)\n        if RemoteHandler.CachedRemotes[RemoteID] then\n            return RemoteHandler.CachedRemotes[RemoteID]\n        end\n\n        local Remote = {}\n        setmetatable(Remote, RemoteHandler)\n\n        Remote.ID = RemoteID\n        Remote.RequestsInLastMinute = 0\n        Remote.MaxRequestsPerMinute = Remote:GetRateLimit()\n        Remote.LastRateLimitReset = 0\n\n        local Success, AttemptedRemote = pcall(GetRemote, Remote.ID)\n        Remote.Success = Success\n        Remote.Remote = AttemptedRemote\n\n        if not Success or not Remote.Remote then\n            SendNotification(\"Cat\", `Tried to Get remote {Remote.ID}, remote is invalid`, 15, \"alert\")\n            Remote.Remote = nil\n        end\n\n        RemoteHandler.CachedRemotes[RemoteID] = Remote\n        return Remote\n    end\n\n    function RemoteHandler:Fire(Method: string?, ...)\n        local Remote = self.Remote\n        if not self.Success or not Remote then\n            return {andThen = function() end}\n        end\n\n        if (os.clock() - self.LastRateLimitReset) >= 60 then\n            self:ResetRateLimit()\n        end\n\n        if self:GetCurrentRequests() >= self:GetRateLimit() then\n            return {andThen = function() end}\n        end\n\n        self:IncrementRequests()\n        local CallingFunction = (Method and Remote[Method]) or (Remote.CallServer or Remote.CallServerAsync or Remote.SendToServer)\n        if CallingFunction then\n            return CallingFunction(Remote, ...)\n        end\n\n        return\n    end\n\n    function RemoteHandler:ResetRateLimit()\n        self.RequestsInLastMinute = 0\n        self.LastRateLimitReset = os.clock()\n    end\n\n    function RemoteHandler:GetCurrentRequests(): number\n        return self.RequestsInLastMinute\n    end\n\n    function RemoteHandler:IncrementRequests()\n        self.RequestsInLastMinute = self.RequestsInLastMinute + 1\n    end\n\n    function RemoteHandler:GetRateLimit(): number\n        local RemoteName: string = self.ID\n        if self.CachedRemotes[RemoteName] then\n            return self.CachedRemotes[RemoteName].MaxRequestsPerMinute\n        end\n\n        if not GlobalMiddleware then\n            local CachedLimits = CheatEngineLib and CheatEngineLib.RateLimits\n            return CachedLimits and CachedLimits[RemoteName] or 300\n        end\n\n        local GlobalFind = GlobalMiddleware[RemoteName]\n        local RateLimitValue: number = (typeof(GlobalFind) ~= \"number\" and 300) or GlobalFind\n\n        if not GlobalFind then\n            local TargetRemote = RemotesInConstruct[RemoteName]\n            local RemoteRateLimit = (TargetRemote and TargetRemote.ServerMiddleware)\n            if RemoteRateLimit and typeof(RemoteRateLimit) == \"table\" then\n                for _, v: any in RemoteRateLimit do\n                    if typeof(v) == \"function\" and (#getupvalues(v) >= 6 and tostring(getupvalue(v, 6)):find(\"Request limit\")) then\n                        local Value = getupvalue(v, 3)\n                        RateLimitValue = (typeof(Value) == \"number\" and Value) or RateLimitValue\n                        break\n                    end\n                end\n            end\n        end\n\n        return RateLimitValue\n    end\n\n    local function FindBowConstants()\n        local EnableBeam = Knit.Controllers.ProjectileController.enableBeam\n        if typeof(EnableBeam) == \"function\" then\n            for _, Value: any in debug.getupvalues(EnableBeam) do\n                if typeof(Value) == \"table\" and Value.RelX and Value.RelY and Value.RelZ then\n                    return Value\n                end\n            end\n        end\n\n        return CheatEngineLib and CheatEngineLib.BowConstantsTable\n    end\n\n    bedwars = setmetatable({\n        AbilityController = Flamework.resolveDependency(\"@easy-games/game-core:client/controllers/ability/ability-controller@AbilityController\"),\n        AbilityIndicatorUtil = require(ReplicatedStorage.TS.games.bedwars.items[\"ability-indicator\"][\"ability-indicator-util\"]).AbilityIndicatorUtil,\n        AnimationType = require(ReplicatedStorage.TS.animation[\"animation-type\"]).AnimationType,\n        AnimationUtil = require(ReplicatedStorage[\"rbxts_include\"][\"node_modules\"][\"@easy-games\"][\"game-core\"].out[\"shared\"].util[\"animation-util\"]).AnimationUtil,\n        AdetundeUtil = require(ReplicatedStorage.TS.games.bedwars.items[\"frosty-hammer\"][\"frosty-hammer-util\"]).FrostyHammerUtil,\n        AdetundeUpgradeMeta = require(ReplicatedStorage.TS.games.bedwars.items[\"frosty-hammer\"][\"frosty-hammer-upgrades\"]).FrostyHammerUpgradeMeta,\n        AppController = require(ReplicatedStorage[\"rbxts_include\"][\"node_modules\"][\"@easy-games\"][\"game-core\"].out.client.controllers[\"app-controller\"]).AppController,\n        BalanceFile = require(ReplicatedStorage.TS.balance[\"balance-file\"]).BalanceFile,\n        BedBreakEffectMeta = require(Re