bug.getupvalue(TeamUpgradeModule.getTeamUpgradeMetaForQueue, 2) or (CheatEngineLib and CheatEngineLib.TeamUpgradeMeta),\n        UILayers = require(ReplicatedStorage[\"rbxts_include\"][\"node_modules\"][\"@easy-games\"][\"game-core\"].out).UILayers,\n        VisualizerUtils = require(LocalPlayer.PlayerScripts.TS.lib.visualizer[\"visualizer-utils\"]).VisualizerUtils,\n        VoidRegentBalance = require(ReplicatedStorage.TS.balance[\"void-regent-balance\"]).VoidRegentBalance,\n        VoidHunterBalance = require(ReplicatedStorage.TS.games.bedwars.kit.kits[\"void-hunter\"][\"void-hunter-kit-balance\"]).VoidHunterKitBalance,\n        VoidWalkerDamageBuff = require(ReplicatedStorage.TS[\"status-effect\"][\"status-effect-meta\"]).StatusEffectMeta and require(ReplicatedStorage.TS[\"status-effect\"][\"status-effect-meta\"]).StatusEffectMeta.void_walker_damage_buff,\n        VoidWalkerKitBalance = require(ReplicatedStorage.TS.games.bedwars.kit.kits[\"void-walker\"][\"void-walker-kit-balance\"]).VoidWalkerKitBalance,\n        WarlockBalance = require(ReplicatedStorage.TS.balance[\"balance-file\"]).WarlockBalance,\n        WeldTable = require(ReplicatedStorage.TS.util[\"weld-util\"]).WeldUtil,\n        WinEffectMeta = require(ReplicatedStorage.TS.locker[\"win-effect\"][\"win-effect-meta\"]).WinEffectMeta,\n        WizardUtil = require(ReplicatedStorage.TS.games.bedwars.kit.kits.wizard[\"wizard-util\"]).WizardUtil,\n        ZapNetworking = require(LocalPlayer.PlayerScripts.TS.lib.network)\n    }, {\n        __index = function(self, Index: string)\n            rawset(self, Index, Knit.Controllers[Index])\n            return rawget(self, Index)\n        end\n    })\n    Store.enchants = setmetatable({}, {\n        __index = function(self, Player: Player)\n            return {\n                async = function()\n                    if Player and Player.Character then\n                        for Attribute: string in Player.Character:GetAttributes() do\n                            if Attribute:find(\"StatusEffect_\") and not Attribute:find(\"_stacks\") then\n                                local Name = bedwars.StatusEffectMeta[({Attribute:gsub(\"StatusEffect_\", \"\")})[1]]\n                                if bedwars.StatusEffectMeta[Name] then\n                                    Name = bedwars.StatusEffectMeta[Name]\n                                    for Tier: number = 1, 3 do\n                                        Name = Name:gsub(`_{Tier}`, \"\")\n                                    end\n\n                                    if bedwars.EnchantMeta[Name] then\n                                        return bedwars.EnchantMeta[Name].image\n                                    end\n                                end\n                            end\n                        end\n                    end\n                    return nil\n                end,\n            }\n        end\n    })\n    getgenv().store = Store\n    getgenv().bedwars = bedwars\n\n    if canDebug then\n        local Shop: any = require(ReplicatedStorage.TS.games.bedwars.shop[\"bedwars-shop\"]).BedwarsShop\n        local ShopUtil: any = require(ReplicatedStorage.TS.shop[\"shop-util\"]).ShopUtil\n        local OldSuperiorItems: (...any) -> ...any = ShopUtil.getAllSuperiorItems\n        local OldOwnsSuperiorItem: (...any) -> ...any = ShopUtil.ownsSuperiorItem\n        local ShopItems: {[string]: any}?\n\n        local function ClearShopItems()\n            ShopItems = nil\n        end\n\n        local function GetSuperiorItems(self, Player: Player, ShopItem: any): {string}\n            if Player ~= LocalPlayer then\n                return OldSuperiorItems(self, Player, ShopItem)\n            end\n            if not ShopItem or not ShopItem.superiorItems then\n                return {}\n            end\n            if not ShopItems then\n                ShopItems = {}\n                for _, v: any in Shop.getShop(Player) do\n                    ShopItems[v.itemType] = v\n                end\n            end\n\n            local Pending: {string} = table.clone(ShopItem.superiorItems)\n            local Seen: {[string]: boolean} = {}\n            local Result: {string} = {}\n            while #Pending > 0 do\n                local ItemType: string = table.remove(Pending)\n                if Seen[ItemType] then\n                    continue\n                end\n                Seen[ItemType] = true\n                table.insert(Result, ItemType)\n                local Item: any = ShopItems[ItemType]\n                if Item and Item.superiorItems then\n                    for _, v: string in Item.superiorItems do\n                        if not Seen[v] then\n                            table.insert(Pending, v)\n                        end\n                    end\n                end\n            end\n            return Result\n        end\n\n        local function OwnsSuperiorItem(self, Player: Player, ShopItem: any): boolean\n            if Player ~= LocalPlayer then\n                return OldOwnsSuperiorItem(self, Player, ShopItem)\n            end\n\n            local SuperiorItems: {string} = self:getAllSuperiorItems(Player, ShopItem)\n            for _, v: {string} in {Shop.Pickaxes, Shop.Axes} do\n                local Tier: number? = table.find(v, ShopItem.itemType)\n                if Tier then\n                    for i: number = Tier + 1, #v do\n                        table.insert(SuperiorItems, v[i])\n                    end\n                    break\n                end\n            end\n            if #SuperiorItems == 0 then\n                return false\n            end\n\n            local Amounts: {[string]: number} = {}\n            local Seen: {[Instance]: boolean} = {}\n            for _, v: any in InventoryUtil.getInventory(Player).items do\n                if not Seen[v.tool] then\n                    Seen[v.tool] = true\n                    Amounts[v.itemType] = (Amounts[v.itemType] or 0) + v.amount\n                end\n            end\n            for _, v: string in SuperiorItems do\n                if (Amounts[v] or 0) >= 1 then\n                    return true\n                end\n            end\n            return false\n        end\n\n        ShopUtil.getAllSuperiorItems = GetSuperiorItems\n        ShopUtil.ownsSuperiorItem = OwnsSuperiorItem\n        vape:Clean(RunService.PreSimulation:Connect(ClearShopItems))\n        vape:Clean(bedwars.Store.changed:connect(ClearShopItems))\n        vape:Clean(LocalPlayer.AttributeChanged:Connect(ClearShopItems))\n        vape:Clean(VapeEvents.AttributeChanged.Event:Connect(ClearShopItems))\n        vape:Clean(function()\n            if ShopUtil.getAllSuperiorItems == GetSuperiorItems then\n                ShopUtil.getAllSuperiorItems = OldSuperiorItems\n            end\n            if ShopUtil.ownsSuperiorItem == OwnsSuperiorItem then\n                ShopUtil.ownsSuperiorItem = OldOwnsSuperiorItem\n            end\n            ClearShopItems()\n        end)\n    end\n\n    Entity.Raycast = function(Origin: Vector3, Direction: Vector3, Params: RaycastParams?)\n        return bedwars.QueryUtil:raycast(Origin, Direction, Params)\n    end\n    PredictionLib.Raycast = Entity.Raycast\n\n    OldWallcheck = Entity.Wallcheck\n    local WallcheckParams: RaycastParams = RaycastParams.new()\n    WallcheckParams.FilterType = Enum.RaycastFilterType.Exclude\n    local WallcheckFilter: {Instance} = {}\n\n    Entity.Wallcheck = function(Origin: Vector3, Position: Vector3, IgnoreObject, Ent)\n        local Character = Ent and Ent.Character\n        local SelfCharacter = LocalPlayer.Character\n        local SelfRoot = SelfCharacter and SelfCharacter.PrimaryPart\n        local TargetRoot = Character and Character.PrimaryPart\n        if not SelfRoot or not TargetRoot then\n            return OldWallcheck(Origin, Position, IgnoreObject)\n        end\n\n        local Humanoid: Humanoid? = SelfCharacter:FindFirstChildWhichIsA(\"Humanoid\")\n        local TargetHumanoid: Humanoid? = Character:FindFirstChildWhichIsA(\"Humanoid\")\n        local Scale = Humanoid and Humanoid:FindFirstChild(\"BodyHeightScale\")\n        local Height: Vector3 = Vector3.new(0, 5 * (Scale and Scale.Value or 1), 0)\n        local SelfFeet: Vector3 = SelfRoot.Position - Vector3.new(0, (Humanoid and Humanoid.HipHeight or 0) + (SelfRoot.Size.Y / 2), 0)\n        local TargetFeet: Vector3 = TargetRoot.Position - Vector3.new(0, (TargetHumanoid and TargetHumanoid.HipHeight or 0) + (TargetRoot.Size.Y / 2), 0)\n        local SelfHead, TargetHead = SelfFeet + Height, TargetFeet + Height\n        local SelfMiddle, TargetMiddle = (SelfFeet + SelfHead) / 2, (TargetFeet + TargetHead) / 2\n\n        table.clear(WallcheckFilter)\n        table.insert(WallcheckFilter, SelfCharacter)\n        table.insert(WallcheckFilter, Character)\n        for _, v: Instance in CollectionService:GetTagged(\"DontBlockSwordRaycast\") do\n            table.insert(WallcheckFilter, v)\n        end\n        if typeof(IgnoreObject) == \"table\" then\n            for _, v: Instance in IgnoreObject do\n                table.insert(WallcheckFilter, v)\n            end\n        end\n        WallcheckParams.FilterDescendantsInstances = WallcheckFilter\n        table.clear(WallcheckFilter)\n\n        return (Entity.Raycast(SelfFeet, TargetFeet - SelfFeet, WallcheckParams) or Entity.Raycast(TargetFeet, SelfFeet - TargetFeet, WallcheckParams)) and (Entity.Raycast(SelfHead, TargetHead - SelfHead, WallcheckParams) or Entity.Raycast(TargetHead, SelfHead - TargetHead, WallcheckParams)) and (Entity.Raycast(SelfMiddle, TargetMiddle - SelfMiddle, WallcheckParams) or Entity.Raycast(TargetMiddle, SelfMiddle - TargetMiddle, WallcheckParams)) or nil\n    end\n\n    local function ClearStaleHooks()\n        if not canDebug or not isexecutorclosure then\n            return\n        end\n        local Seen = {}\n        local function Clear(Object)\n            if type(Object) ~= \"table\" or Seen[Object] then\n                return\n            end\n            Seen[Object] = true\n            local Meta = getmetatable(Object)\n            local Class = type(Meta) == \"table\" and rawget(Meta, \"__index\")\n            if type(Class) ~= \"table\" then\n                return\n            end\n            for Key: string, Value: any in Object do\n                if type(Value) == \"function\" and isexecutorclosure(Value) and type(Class[Key]) == \"function\" then\n                    rawset(Object, Key, nil)\n                end\n            end\n        end\n        pcall(function()\n            for _, v: any in Knit.Controllers do\n                Clear(v)\n            end\n            for _, v: any in bedwars do\n                Clear(v)\n            end\n        end)\n    end\n    ClearStaleHooks()\n\n    OldBreak = bedwars.BlockController.isBlockBreakable\n    OldHit = bedwars.BlockBreaker.hitBlock\n\n    WrapRemote = function(Remote, RemoteName: string)\n        if RemoteName == \"SwordHit\" then\n            return {\n                instance = Remote.instance,\n                SendToServer = function(_, AttackTable, ...)\n                    local SelfPosition: Vector3 = AttackTable.validate.selfPosition.value\n                    local TargetPosition: Vector3 = AttackTable.validate.targetPosition.value\n                    Store.attackReach = ((SelfPosition - TargetPosition).Magnitude * 100) // 1 / 100\n                    Store.attackReachUpdate = tick() + 1\n\n                    if Reach.Enabled or HitBoxes.Enabled then\n                        local Delta: Vector3 = TargetPosition - SelfPosition\n                        AttackTable.validate.selfPosition.value += Delta.Magnitude > 0.001 and Delta.Unit * math.max(Delta.Magnitude - (GetReach(AttackTable.weapon) - 0.001), 0) or Vector3.zero\n                    end\n\n                    return Remote:SendToServer(AttackTable, ...)\n                end\n            }\n        elseif TrapDisabler.Enabled and (RemoteName == \"StepOnSnapTrap\" and TrapSnap.Enabled or RemoteName == \"TriggerInvisibleLandmine\" and TrapMine.Enabled or RemoteName == \"StepOnTeleportBlock\" and TrapTeleport.Enabled or RemoteName == \"StepOnVoidPortal\" and TrapPortal.Enabled) then\n            return {SendToServer = function() end}\n        elseif KnockbackSpoof.Enabled and RemoteName == \"AckKnockback\" then\n            return {\n                instance = Remote.instance,\n                SendToServer = function(_, AckTable)\n                    if KnockbackMode.Value == \"Drop\" then\n                        Store.knockbackAcks = (Store.knockbackAcks or 0) + 1\n                        return\n                    end\n\n                    if KnockbackMode.Value == \"Rewind\" and typeof(AckTable.playerPosition) == \"Vector3\" and Entity.isAlive then\n                        AckTable.playerPosition -= Entity.character.RootPart.AssemblyLinearVelocity * (KnockbackRewind.Value / 1000)\n                    end\n\n                    Store.knockbackAcks = (Store.knockbackAcks or 0) + 1\n                    if KnockbackDelay.Value > 0 then\n                        task.delay(KnockbackDelay.Value / 1000, function()\n                            Remote:SendToServer(AckTable)\n                        end)\n                        return\n                    end\n\n                    return Remote:SendToServer(AckTable)\n                end\n            }\n        end\n\n        return Remote\n    end\n\n    Client.Get = function(self, RemoteName: string)\n        return WrapRemote(OldGet(self, RemoteName), RemoteName)\n    end\n\n    local BlockBreakCallbacks: {[string]: (...any) -> ()} = {}\n    bedwars.BlockBreakCallbacks = BlockBreakCallbacks\n    local HitBlock = function(self, ...)\n        if vape.Loaded ~= nil then\n            Store.lastHit = tick()\n            for _, Callback: (...any) -> () in BlockBreakCallbacks do\n                Callback(self, ...)\n            end\n        end\n        return OldHit(self, ...)\n    end\n    bedwars.BlockBreaker.hitBlock = HitBlock\n\n    local BreakRequest, BreakFocus\n    local BreakRequests = {}\n    local PathCache, BlockHealthbar = {}, {blockHealth = -1, breakingBlockPosition = Vector3.zero}\n    Store.swordDistance = bedwars.CombatConstant.RAYCAST_SWORD_CHARACTER_DISTANCE\n    Store.blockPlacer = bedwars.BlockPlacer.new(bedwars.BlockEngine, \"wool_white\")\n\n    local BlockStore = bedwars.BlockController:getStore()\n    local NavigationMap = workspace:FindFirstChild(\"Map\")\n    local NavigationParams: OverlapParams = OverlapParams.new()\n    NavigationParams.FilterType = Enum.RaycastFilterType.Include\n    local NavigationSolids: {Instance} = {}\n\n    local SolidTags: {string} = {\"BedwarsItemShop\", \"TeamUpgradeShopkeeper\"}\n\n    local function RefreshSolids()\n        table.clear(NavigationSolids)\n        table.insert(NavigationSolids, NavigationMap or workspace.Terrain)\n        for _, Tag: string in SolidTags do\n            for _, v: Instance in CollectionService:GetTagged(Tag) do\n                table.insert(NavigationSolids, v)\n            end\n        end\n        NavigationParams.FilterDescendantsInstances = NavigationSolids\n    end\n    RefreshSolids()\n    for _, Tag: string in SolidTags do\n        vape:Clean(CollectionService:GetInstanceAddedSignal(Tag):Connect(function()\n            RefreshSolids()\n            if Navigation.World then\n                Navigation.World:Touch()\n            end\n        end))\n    end\n\n    Navigation:SetWorld(Navigation.newWorld({\n        GetBlocks = function()\n            return BlockStore:getAllBlockPositions()\n        end,\n        GetBlock = function(X: number, Y: number, Z: number)\n            return BlockStore:getBlockAt(Vector3.new(X, Y, Z))\n        end,\n        IsSolid = function(X: number, Y: number, Z: number): boolean\n            if not NavigationMap then\n                NavigationMap = workspace:FindFirstChild(\"Map\")\n                RefreshSolids()\n            end\n            return #workspace:GetPartBoundsInBox(CFrame.new(X * 3, Y * 3, Z * 3), Navigation.CellBounds, NavigationParams) > 0\n        end\n    }))\n\n    OldSetBlock = BlockStore.setBlock\n    BlockStore.setBlock = function(self, Position: Vector3, Block)\n        Navigation.World:Invalidate(Position.X, Position.Y, Position.Z)\n        return OldSetBlock(self, Position, Block)\n    end\n\n    local function GetBlockHealth(Block, BlockPosition: Vector3)\n        local BlockData = bedwars.BlockController:getStore():getBlockData(BlockPosition)\n        return (BlockData and (BlockData:GetAttribute(\"1\") or BlockData:GetAttribute(\"Health\")) or Block:GetAttribute(\"Health\"))\n    end\n\n    GetBlockHits = function(Block, BlockPosition: Vector3): number\n        if not Block then\n            return 0\n        end\n        local BreakType = bedwars.ItemMeta[Block.Name].block.breakType\n        local Tool = Store.tools[BreakType]\n        Tool = Tool and bedwars.ItemMeta[Tool.itemType].breakBlock[BreakType] or 2\n        return GetBlockHealth(Block, bedwars.BlockController:getBlockPosition(BlockPosition)) / Tool\n    end\n\n    CalculatePath = function(Target, BlockPosition: Vector3, SolidOnly: boolean?, BreakMethod)\n        local Origin: Vector3 = Entity.character.RootPart.Position\n        local Cell: Vector3 = bedwars.BlockController:getBlockPosition(Origin)\n        local Key: string = `{BlockPosition.X},{BlockPosition.Y},{BlockPosition.Z}|{SolidOnly and 1 or 0}|{BreakMethod == BreakMethods.Distance and 1 or 0}`\n        local Cached = PathCache[Key]\n        if Cached and Cached.cell == Cell and (SolidOnly or Cached.camera == Camera.CFrame.Position and Cached.head == Entity.character.Head.Position) and os.clock() - Cached.clock < 0.25 then\n            return Cached.pos, Cached.cost, Cached.path\n        end\n\n        local Placed, Hits = {}, {}\n        local function GetCellBlock(Position: Vector3)\n            local Block: any = Placed[Position]\n            if Block == nil then\n                Block = GetPlacedBlock(Position) or false\n                Placed[Position] = Block\n            end\n            return Block or nil\n        end\n\n        local function GetCellHits(Block, Position: Vector3): number | boolean\n            local Value: number | boolean? = Hits[Position]\n            if Value == nil then\n                Value = (Position - Origin).Magnitude <= 30 and not Block:GetAttribute(\"NoBreak\") and bedwars.BlockController:isBlockBreakable({blockPosition = bedwars.BlockController:getBlockPosition(Position)}, LocalPlayer) and math.max(math.ceil(GetBlockHits(Block, Position)), 1)\n                Hits[Position] = Value\n            end\n            return Value\n        end\n\n        local Routes = {}\n        local function IsOpen(Open: Vector3): boolean\n            if Routes[Open] ~= nil then\n                return Routes[Open]\n            end\n            local Queue, Seen, Reached = {Open}, {[Open] = true}, true\n\n            for _ = 1, 400 do\n                local Current = table.remove(Queue)\n                if not Current then\n                    Reached = false\n                    break\n                end\n                if (Current - BlockPosition).Magnitude > 15 then\n                    break\n                end\n\n                for _, v: Vector3 in Sides do\n                    v = Current + v\n                    if Seen[v] or GetCellBlock(v) then\n                        continue\n                    end\n                    Seen[v] = true\n                    table.insert(Queue, v)\n                end\n            end\n\n            for SeenCell: Vector3 in Seen do\n                Routes[SeenCell] = Reached\n            end\n            return Reached\n        end\n\n        local function Boundary(Index: number, Component: number, Delta: number)\n            if Delta == 0 then\n                return 0, math.huge, math.huge\n            end\n            local Step: number = Delta > 0 and 1 or -1\n            return Step, ((((Index + (Step * 0.5)) * 3) - Component) / Delta), (3 / math.abs(Delta))\n        end\n\n        local Eyes: {Vector3} = {Entity.character.Head.Position, Camera.CFrame.Position}\n        if not SolidOnly then\n            local Nearest: boolean = BreakMethod == BreakMethods.Distance\n            local Previous = Store.breakTarget\n            local BestPosition, BestCost, BestScore, BestDistance, BestFacing, BestDirect\n            local BestPath = {}\n            local function TracePath(From: Vector3, Aim: Vector3)\n                local Start, Direction = bedwars.BlockController:getBlockPosition(From), Aim - From\n                local X, Y, Z = Start.X, Start.Y, Start.Z\n                local StepX, NextX, DeltaX = Boundary(X, From.X, Direction.X)\n                local StepY, NextY, DeltaY = Boundary(Y, From.Y, Direction.Y)\n                local StepZ, NextZ, DeltaZ = Boundary(Z, From.Z, Direction.Z)\n                local Path = {}\n                local Cost: number = 0\n                for _ = 1, 100 do\n                    local Position: Vector3 = Vector3.new(X, Y, Z) * 3\n                    local Block = GetCellBlock(Position)\n                    if Block == Target and Target.Name == \"bed\" then\n                        if (Position - Origin).Magnitude > 30 then return end\n                        if Position ~= BlockPosition then table.insert(Path, Position) end\n                        return Path, Cost\n                    end\n                    if Position == BlockPosition then\n                        if (Position - Origin).Magnitude > 30 then return end\n                        return Path, Cost\n                    end\n                    if Block then\n                        local Hits: number | boolean = GetCellHits(Block, Position)\n                        if not Hits then return end\n                        Cost += Hits\n                        table.insert(Path, Position)\n                    end\n                    if NextX > 1 and NextY > 1 and NextZ > 1 then break end\n                    if NextX <= NextY and NextX <= NextZ then\n                        X, NextX = X + StepX, NextX + DeltaX\n                    elseif NextY <= NextZ then\n                        Y, NextY = Y + StepY, NextY + DeltaY\n                    else\n                        Z, NextZ = Z + StepZ, NextZ + DeltaZ\n                    end\n                end\n                return\n            end\n            for _, Eye: Vector3 in Eyes do\n                for X: number = -1, 1 do\n                    for Y: number = -1, 1 do\n                        for Z: number = -1, 1 do\n                            local Path, Cost = TracePath(Eye, BlockPosition + Vector3.new(X, Y, Z) * 1.35)\n                            if not Path then continue end\n                            local Position: Vector3 = Path[1] or BlockPosition\n                            local Delta: Vector3 = Position - Origin\n                            local Distance: number = Delta.Magnitude\n                            if Distance > 30 then continue end\n                            local Facing: number = Distance > 0 and Delta:Dot(Camera.CFrame.LookVector) / Distance or 1\n                            local Direct: boolean = GetCellBlock(Position) == Target\n                            local Score: number = Nearest and Cost + Distance / 6 - (Position == Previous and 1.5 or 0) or Cost\n                            local Better: boolean = not BestScore or Direct and not BestDirect or Direct == BestDirect and Score < BestScore\n                            if BestScore and Direct == BestDirect and Score == BestScore then\n                                if not Nearest and Previous and (Position == Previous) ~= (BestPosition == Previous) then\n                                    Better = Position == Previous\n                                elseif Distance ~= BestDistance then\n                                    Better = Distance < BestDistance\n                                else\n                                    Better = Facing > BestFacing\n                                end\n                            end\n                            if Better then\n                                BestPosition, BestCost, BestScore, BestDistance, BestFacing, BestDirect = Position, Cost, Score, Distance, Facing, Direct\n                                table.clear(BestPath)\n                                for Index: number, Node: Vector3 in Path do BestPath[Node] = Path[Index + 1] or BlockPosition end\n                            end\n                        end\n                    end\n                end\n            end\n            PathCache[Key] = {cell = Cell, camera = Camera.CFrame.Position, head = Entity.character.Head.Position, clock = os.clock(), pos = BestPosition, cost = BestCost, path = BestPath}\n            return BestPosition, BestCost, BestPath\n        end\n\n        if (BlockPosition - Origin).Magnitude > 30 then return end\n        if GetCellBlock(BlockPosition) then\n            for _, v: Vector3 in Sides do\n                v = BlockPosition + v\n                if not GetCellBlock(v) and IsOpen(v) then\n                    local Direct = {}\n                    PathCache[Key] = {cell = Cell, camera = Camera.CFrame.Position, head = Entity.character.Head.Position, clock = os.clock(), pos = BlockPosition, cost = 0, path = Direct}\n                    return BlockPosition, 0, Direct\n                end\n            end\n        end\n\n        local Visited, Queue, Distances, Exposed, BreakPath = {}, {{0, BlockPosition}}, {[BlockPosition] = 0}, {}, {}\n        local function Push(Node)\n            local i: number = #Queue + 1\n            Queue[i] = Node\n            while i > 1 do\n                local Parent: number = i // 2\n                if Queue[Parent][1] <= Node[1] then\n                    break\n                end\n                Queue[i], Queue[Parent] = Queue[Parent], Node\n                i = Parent\n            end\n        end\n\n        local function Pop()\n            local Node = Queue[1]\n            local Last = table.remove(Queue)\n            if #Queue > 0 then\n                Queue[1] = Last\n                local i: number = 1\n                while i * 2 <= #Queue do\n                    local Child: number = i * 2\n                    if Child < #Queue and Queue[Child + 1][1] < Queue[Child][1] then\n                        Child += 1\n                    end\n                    if Queue[i][1] <= Queue[Child][1] then\n                        break\n                    end\n                    Queue[i], Queue[Child] = Queue[Child], Queue[i]\n                    i = Child\n                end\n            end\n            return Node\n        end\n\n        for _ = 1, 10000 do\n            local Node = Pop()\n            if not Node then\n                break\n            end\n            if Visited[Node[2]] then\n                continue\n            end\n            Visited[Node[2]] = true\n\n            for _, v: Vector3 in Sides do\n                v = Node[2] + v\n                if Visited[v] then\n                    continue\n                end\n\n                local Block = GetCellBlock(v)\n                local BlockHits: number | boolean? = Block and Block ~= Target and GetCellHits(Block, v)\n                if not Block then\n                    if GetCellBlock(Node[2]) then\n                        local Cells = Exposed[Node[2]]\n                        if Cells then\n                            table.insert(Cells, v)\n                        else\n                            Exposed[Node[2]] = {v}\n                        end\n                    end\n                    BlockHits = not IsOpen(v) and 0\n                end\n                if not BlockHits then\n                    continue\n                end\n\n                local CurrentDistance: number = Node[1] + BlockHits\n                if CurrentDistance < (Distances[v] or math.huge) then\n                    Distances[v] = CurrentDistance\n                    BreakPath[v] = Node[2]\n                    Push({CurrentDistance, v})\n                end\n            end\n        end\n\n        local Nearest: boolean = BreakMethod == BreakMethods.Distance\n        local Previous = Store.breakTarget\n        local Look: Vector3 = Camera.CFrame.LookVector\n        local Candidates = {}\n        for Position: Vector3, Openings: {Vector3} in Exposed do\n            local Delta: Vector3 = Position - Origin\n            local Magnitude: number = Delta.Magnitude\n            if Magnitude <= 30 then\n                local Facing: number = Magnitude > 0 and Delta:Dot(Look) / Magnitude or 1\n                table.insert(Candidates, {Distances[Position], Position, Openings, Magnitude, Facing, Distances[Position] + (Magnitude / 6) - (Position == Previous and 1.5 or 0)})\n            end\n        end\n\n        table.sort(Candidates, function(A, B): boolean\n            if Nearest then\n                if A[6] ~= B[6] then\n                    return A[6] < B[6]\n                end\n            else\n                if A[1] ~= B[1] then\n                    return A[1] < B[1]\n                end\n                if Previous and (A[2] == Previous) ~= (B[2] == Previous) then\n                    return A[2] == Previous\n                end\n            end\n            if A[4] ~= B[4] then\n                return A[4] < B[4]\n            end\n            return A[5] > B[5]\n        end)\n\n        local BestPosition, BestCost\n        for _, v: any in Candidates do\n            for _, Opening: Vector3 in v[3] do\n                if IsOpen(Opening) then\n                    BestPosition, BestCost = v[2], v[1]\n                    break\n                end\n            end\n            if BestPosition then\n                break\n            end\n        end\n\n        PathCache[Key] = {cell = Cell, camera = Camera.CFrame.Position, head = Entity.character.Head.Position, clock = os.clock(), pos = BestPosition, cost = BestCost, path = BreakPath}\n        return BestPosition, BestCost, BreakPath\n    end\n\n    bedwars.getShotData = function(ItemType: string)\n        local Meta = bedwars.ItemMeta[ItemType]\n        local Source = Meta and Meta.projectileSource\n        return {\n            shotId = bedwars.IdUtil.generateId(8),\n            drawDurationSec = math.max(1, Source and Source.maxStrengthChargeSec or 0)\n        }\n    end\n\n    bedwars.placeBlock = function(Position: Vector3, Item: string)\n        if not CanPlace() then\n            return\n        end\n\n        if GetItem(Item) then\n            Store.blockPlacer.blockType = Item\n            return Store.blockPlacer:placeBlock(bedwars.BlockController:getBlockPosition(Position))\n        end\n    end\n\n    local function ClearBreakRequest(Request)\n        local Index: number? = table.find(BreakRequests, Request)\n        if Index then table.remove(BreakRequests, Index) end\n        \n        BreakRequest = BreakRequests[#BreakRequests]\n    end\n\n    local function CanAimBlock(Position: Vector3): boolean\n        local function Boundary(Index: number, Component: number, Delta: number)\n            if Delta == 0 then\n                return 0, math.huge, math.huge\n            end\n            local Step: number = Delta > 0 and 1 or -1\n            return Step, ((((Index + Step * 0.5) * 3) - Component) / Delta), (3 / math.abs(Delta))\n        end\n\n        local function Trace(From: Vector3, Aim: Vector3): boolean\n            local Start, Direction = bedwars.BlockController:getBlockPosition(From), Aim - From\n            local X, Y, Z = Start.X, Start.Y, Start.Z\n            local StepX, NextX, DeltaX = Boundary(X, From.X, Direction.X)\n            local StepY, NextY, DeltaY = Boundary(Y, From.Y, Direction.Y)\n            local StepZ, NextZ, DeltaZ = Boundary(Z, From.Z, Direction.Z)\n            for _ = 1, 100 do\n                local Cell: Vector3 = Vector3.new(X, Y, Z) * 3\n                if Cell == Position then\n                    return true\n                end\n                if GetPlacedBlock(Cell) or NextX > 1 and NextY > 1 and NextZ > 1 then\n                    return false\n                end\n                if NextX <= NextY and NextX <= NextZ then\n                    X, NextX = X + StepX, NextX + DeltaX\n                elseif NextY <= NextZ then\n                    Y, NextY = Y + StepY, NextY + DeltaY\n                else\n                    Z, NextZ = Z + StepZ, NextZ + DeltaZ\n                end\n            end\n            return false\n        end\n\n        for _, Eye: Vector3 in {Entity.character.Head.Position, Camera.CFrame.Position} do\n            if Trace(Eye, Position) then\n                return true\n            end\n            for X: number = -1, 1 do\n                for Y: number = -1, 1 do\n                    for Z: number = -1, 1 do\n                        if Trace(Eye, Position + Vector3.new(X, Y, Z) * 1.35) then\n                            return true\n                        end\n                    end\n                end\n            end\n        end\n        return false\n    end\n\n    bedwars.breakBlock = function(Block, Effects, AnimationMode, CustomHealthbar, AutoTool, Wallcheck, Method, DirectOnly, Sequential: boolean?, Session)\n        if LocalPlayer:GetAttribute(\"DenyBlockBreak\") or not Entity.isAlive or (vape.Modules.InfiniteFly or {}).Enabled or Session and Session.Cancelled then\n            return\n        end\n        local Timeout: number = math.max(1, LocalPlayer:GetNetworkPing() * 4 + 0.5)\n        for i: number = #BreakRequests, 1, -1 do\n            local Request = BreakRequests[i]\n            if tick() - Request.sent >= Timeout or GetPlacedBlock(Request.position) ~= Request.hit then\n                table.remove(BreakRequests, i)\n            end\n        end\n        BreakRequest = BreakRequests[#BreakRequests]\n        if BreakRequest and (not Sequential or #BreakRequests >= 4) then\n            return BreakRequest.position, BreakRequest.path, BreakRequest.target, false\n        end\n        local Handler = bedwars.BlockController:getHandlerRegistry():getHandler(Block.Name)\n        local LocalPosition: Vector3 = Entity.character.RootPart.Position\n        local Cost, Position, Target, BreakPath = math.huge\n        local Direct: boolean = false\n\n        if BreakFocus then\n            local Focus = BreakFocus\n            local HitBlock, HitPosition = GetPlacedBlock(Focus.position)\n            if Session and Focus.session == Session and Focus.block == Block and HitBlock and not HitBlock:GetAttribute(\"NoBreak\") and HitBlock.Name == Focus.name and (LocalPosition - Focus.position).Magnitude <= 30 and bedwars.BlockController:isBlockBreakable({blockPosition = HitPosition}, LocalPlayer) and (not Wallcheck or CanAimBlock(Focus.position)) then\n                Position, Target, BreakPath, Direct = Focus.position, Focus.target, Focus.path, Focus.direct\n            else\n                BreakFocus = nil\n            end\n        end\n\n        if not Position then\n            for _, v: Vector3 in (Handler and Handler:getContainedPositions(Block) or {bedwars.BlockController:getBlockPosition(Block.Position)}) do\n                local CellPosition, CellCost, CellPath = CalculatePath(Block, v * 3, not Wallcheck, Method or nil)\n                local Distance: number = CellPosition and (LocalPosition - CellPosition).Magnitude or math.huge\n                local Hit: boolean = CellPosition ~= nil and GetPlacedBlock(CellPosition) == Block\n                if CellPosition and (Hit and not Direct or Hit == Direct and (CellCost < Cost or (CellCost == Cost and Position ~= Store.breakTarget and (CellPosition == Store.breakTarget or Distance < (LocalPosition - Position).Magnitude)))) then\n                    Cost, Position, Target, BreakPath, Direct = CellCost, CellPosition, v * 3, CellPath, Hit\n                end\n            end\n        end\n\n        if DirectOnly and not Direct then\n            return\n        end\n\n        Store.breakTarget = Position\n\n        if Position then\n            if (Entity.character.RootPart.Position - Position).Magnitude > 30 then\n                return\n            end\n            local HitBlock, HitPosition = GetPlacedBlock(Position)\n            if not HitBlock then\n                return\n            end\n            if BreakRequest and (BreakRequest.hit ~= HitBlock or BreakRequest.position ~= Position) then\n                return BreakRequest.position, BreakRequest.path, BreakRequest.target, false\n            end\n\n            if (workspace:GetServerTimeNow() - bedwars.SwordController.lastAttack) > 0.4 then\n                local BreakType = bedwars.ItemMeta[HitBlock.Name].block.breakType\n                local Tool = Store.tools[BreakType]\n                if Tool then\n                    local HandValue: ObjectValue? = LocalPlayer.Character and LocalPlayer.Character:FindFirstChild(\"HandInvItem\")\n                    local Changed: boolean = not Store.breakTool or Store.breakTool.tool ~= Tool.tool or not HandValue or HandValue.Value ~= Tool.tool\n                    local Mining = {tool = Tool.tool, expires = tick() + Timeout, session = Session}\n                    Store.breakTool = Mining\n                    if AutoTool then\n                        local Hotbar = GetHotbar(Tool.tool)\n                        if Hotbar then\n                            HotbarSwitch(Hotbar)\n                        end\n                    end\n                    if Changed then\n                        local Success, Equipped = bedwars.Handler:Get(\"SetInvItem\"):Fire(\"CallServerAsync\", {hand = Tool.tool}):await()\n                        if not Success or Equipped == false or not Entity.isAlive or Session and Session.Cancelled or not HandValue or not HandValue.Parent then\n                            return Position, BreakPath, Target, false\n                        end\n                        HandValue.Value = Tool.tool\n                    end\n                    Mining.expires = tick() + 0.5\n                end\n            end\n\n            if BlockHealthbar.blockHealth == -1 or HitPosition ~= BlockHealthbar.breakingBlockPosition then\n                BlockHealthbar.blockHealth = GetBlockHealth(HitBlock, HitPosition)\n                BlockHealthbar.breakingBlockPosition = HitPosition\n            end\n\n            if not Entity.isAlive or Session and Session.Cancelled or GetPlacedBlock(Position) ~= HitBlock or not bedwars.BlockController:isBlockBreakable({blockPosition = HitPosition}, LocalPlayer) then\n                table.clear(PathCache)\n                return nil, nil, nil, false\n            end\n            local BeforeHealth: number = GetBlockHealth(HitBlock, HitPosition) or 0\n            if Session and not BreakFocus then\n                BreakFocus = {block = Block, position = Position, target = Target, path = BreakPath, name = HitBlock.Name, direct = Direct, session = Session}\n            end\n            local Request = {position = Position, target = Target, path = BreakPath, hit = HitBlock, sent = tick(), focus = BreakFocus}\n            table.insert(BreakRequests, Request)\n            BreakRequest = Request\n            local Promise = bedwars.ClientDamageBlock:Get(\"DamageBlock\"):CallServerAsync({\n                blockRef = {blockPosition = HitPosition},\n                hitPosition = Position,\n                hitNormal = Vector3.FromNormalId(Enum.NormalId.Top)\n            })\n            Promise:andThen(function(Result)\n                ClearBreakRequest(Request)\n                if (not Result or Result == \"cancelled\" or Result == \"destroyed\") and BreakFocus == Request.focus then\n                    BreakFocus = nil\n                end\n                if Result then\n                    if Result == \"cancelled\" then\n                        table.clear(PathCache)\n                        Store.damageBlockFail = tick() + 0.1\n                        return\n                    end\n\n                    if Effects and Store.breakTarget == Position then\n                        local AfterHealth: number = Result == \"destroyed\" and 0 or GetBlockHealth(HitBlock, HitPosition) or BeforeHealth\n                        local BlockDamage: number = math.max(BeforeHealth - AfterHealth, 0)\n                        BlockHealthbar.blockHealth = BeforeHealth\n                        BlockHealthbar.breakingBlockPosition = HitPosition\n                        CustomHealthbar = CustomHealthbar or bedwars.BlockBreaker.updateHealthbar\n                        CustomHealthbar(bedwars.BlockBreaker, {blockPosition = HitPosition}, BlockHealthbar.blockHealth, HitBlock:GetAttribute(\"MaxHealth\"), BlockDamage, HitBlock)\n                        BlockHealthbar.blockHealth = math.max(BlockHealthbar.blockHealth - BlockDamage, 0)\n\n                        if BlockHealthbar.blockHealth <= 0 then\n                            bedwars.BlockBreaker.breakEffect:playBreak(HitBlock.Name, HitPosition, LocalPlayer)\n                            bedwars.BlockBreaker.blockHealthbar:destroy()\n                            BlockHealthbar.breakingBlockPosition = Vector3.zero\n                        else\n                            bedwars.BlockBreaker.breakEffect:playHit(HitBlock.Name, HitPosition, LocalPlayer)\n                        end\n                    end\n\n                    if AnimationMode then\n                        local Animation\n                        if AnimationMode ~= \"Minimal\" or Random.new(os.clock() * 1.2):NextInteger(0, 1) == 1 then\n                            Animation = bedwars.AnimationUtil:playAnimation(LocalPlayer, bedwars.BlockController:getAnimationController():getAssetId(1))\n                        end\n                        bedwars.ViewmodelController:playAnimation(15)\n                        task.wait(AnimationMode == \"Minimal\" and 0.01 or 0.3)\n                        if Animation then\n                            Animation:Stop()\n                            Animation:Destroy()\n                        end\n                    end\n                end\n                if Result == \"destroyed\" then\n                    table.clear(PathCache)\n                end\n            end):catch(function()\n                ClearBreakRequest(Request)\n                if BreakFocus == Request.focus then\n                    BreakFocus = nil\n                end\n                table.clear(PathCache)\n            end)\n\n            return Position, BreakPath, Target, true\n        end\n        return nil\n    end\n\n    for _, v: EnumItem in Enum.NormalId:GetEnumItems() do\n        table.insert(Sides, Vector3.FromNormalId(v) * 3)\n    end\n\n    local function UpdateKits(StoreKit: string?)\n        local Primary: string = string.split(StoreKit or \"\", \",\")[1]\n        Store.equippedKit = Primary ~= \"none\" and Primary or \"\"\n\n        local Kits: {string} = {}\n        local Attribute = LocalPlayer:GetAttribute(\"PlayingAsKits\")\n        for _, v: string in string.split(`{Store.equippedKit},{typeof(Attribute) == \"string\" and Attribute or \"\"}`, \",\") do\n            if v ~= \"\" and v ~= \"none\" and not table.find(Kits, v) then\n                table.insert(Kits, v)\n            end\n        end\n\n        if not Store.equippedKits or table.concat(Kits, \",\") ~= table.concat(Store.equippedKits, \",\") then\n            Store.equippedKits = Kits\n        end\n    end\n\n    local function UpdateStore(New, Old)\n        if New.Bedwars ~= Old.Bedwars then\n            UpdateKits(New.Bedwars.kit)\n        end\n\n        if New.Game ~= Old.Game then\n            Store.matchState = New.Game.matchState\n            Store.queueType = New.Game.queueType or \"bedwars_test\"\n        end\n\n        if New.Inventory ~= Old.Inventory then\n            local NewInventory = (New.Inventory and New.Inventory.observedInventory or {inventory = {}})\n            local OldInventory = (Old.Inventory and Old.Inventory.observedInventory or {inventory = {}})\n            Store.inventory = NewInventory\n\n            if not NewInventory.hotbar then\n                local Hand = NewInventory.inventory.hand\n                NewInventory.hotbar = {}\n                for Index: number, Item: any in NewInventory.inventory.items or {} do\n                    table.insert(NewInventory.hotbar, {item = Item})\n                    if Hand and Item.tool == Hand.tool then\n                        NewInventory.hotbarSlot = Index - 1\n                    end\n                end\n            end\n\n            if NewInventory ~= OldInventory then\n                VapeEvents.InventoryChanged:Fire()\n            end\n\n            if NewInventory.inventory.items ~= OldInventory.inventory.items then\n                VapeEvents.InventoryAmountChanged:Fire()\n                Store.tools.sword = GetSword()\n                for _, v: string in {\"stone\", \"wood\", \"wool\"} do\n                    Store.tools[v] = GetTool(v)\n                end\n            end\n\n            if NewInventory.inventory.hand ~= OldInventory.inventory.hand then\n                local CurrentHand, ToolType = New.Inventory.observedInventory.inventory.hand, \"\"\n                if CurrentHand then\n                    local HandData = bedwars.ItemMeta[CurrentHand.itemType] or {}\n                    ToolType = HandData.sword and \"sword\" or HandData.block and \"block\" or CurrentHand.itemType:find(\"bow\") and \"bow\"\n                end\n\n                Store.hand = {\n                    tool = CurrentHand and CurrentHand.tool,\n                    amount = CurrentHand and CurrentHand.amount or 0,\n                    toolType = ToolType\n                }\n            end\n        end\n    end\n\n    local StoreChanged = bedwars.Store.changed:connect(UpdateStore)\n    UpdateStore(bedwars.Store:getState(), {})\n    vape:Clean(LocalPlayer:GetAttributeChangedSignal(\"PlayingAsKits\"):Connect(function()\n        UpdateKits(bedwars.Store:getState().Bedwars.kit)\n    end))\n\n    for _, v: string in {\"MatchEndEvent\", \"EntityDeathEvent\", \"BedwarsBedBreak\", \"BalloonPopped\", \"AngelProgress\", \"GrapplingHookFunctions\"} do\n        if not vape.Connections then\n            return\n        end\n        bedwars.Client:WaitFor(v):andThen(function(Connection)\n            vape:Clean(Connection:Connect(function(...)\n                VapeEvents[v]:Fire(...)\n            end))\n        end)\n    end\n\n    vape:Clean(bedwars.ZapNetworking.EntityDamageEventZap.On(function(...)\n        local DamageTable = {\n            entityInstance = ...,\n            damage = select(2, ...),\n            damageType = select(3, ...),\n            fromPosition = select(4, ...),\n            fromEntity = select(5, ...),\n            knockbackMultiplier = select(6, ...),\n            knockbackId = select(7, ...),\n            disableDamageHighlight = select(13, ...)\n        }\n        MarkKnockback(DamageTable)\n        ReportProjectileHit(DamageTable)\n        VapeEvents.EntityDamageEvent:Fire(DamageTable)\n    end))\n\n    local SwordSwing = bedwars.SyncEvents.SwordSwing:setPriority(500):connect(function(Event)\n        if Store.swordSpeeds and Event.swordType and typeof(Event.attackSpeed) == \"number\" then\n            Store.swordSpeeds[Event.swordType] = Event.attackSpeed\n        end\n    end)\n    vape:Clean(function()\n        SwordSwing:Destroy()\n    end)\n\n    local ProjectileLaunched = bedwars.SyncEvents.ProjectileLaunched:connect(function(Event)\n        if not Store.matchState or typeof(Event.origin) ~= \"Vector3\" or typeof(Event.launchVelocity) ~= \"Vector3\" or Event.shooter == LocalPlayer.Character then\n            return\n        end\n        ScanProjectile(Event.origin, Event.launchVelocity, Event.projectileType, Event.shooter)\n    end)\n    vape:Clean(function()\n        ProjectileLaunched:Destroy()\n    end)\n\n    vape:Clean(bedwars.ZapNetworking.BreakBlockEventZap.On(function(...)\n        local Data = {\n            blockRef = {\n                blockPosition = ...,\n            },\n            player = select(5, ...)\n        }\n        table.clear(PathCache)\n        VapeEvents.BreakBlockEvent:Fire(Data)\n    end))\n\n    Store.blocks = Collection(\"block\", vape)\n    Store.shop = Collection({\"BedwarsItemShop\", \"TeamUpgradeShopkeeper\"}, vape, function(List, Object: Instance)\n        table.insert(List, {\n            Id = Object.Name,\n            RootPart = Object,\n            Shop = Object:HasTag(\"BedwarsItemShop\"),\n            Upgrades = Object:HasTag(\"TeamUpgradeShopkeeper\")\n        })\n    end)\n    Store.enchant = Collection({\"enchant-table\", \"broken-enchant-table\"}, vape, nil, function(List, Object, Tag: string)\n        if Object:HasTag(\"enchant-table\") and Tag == \"broken-enchant-table\" then\n            return\n        end\n        Object = table.find(List, Object)\n        if Object then\n            table.remove(List, Object)\n        end\n    end)\n\n    local Kills = SessionInfo:AddItem(\"Kills\")\n    local Beds = SessionInfo:AddItem(\"Beds\")\n    local Wins = SessionInfo:AddItem(\"Wins\")\n    local Games = SessionInfo:AddItem(\"Games\")\n\n    local MapName: string = \"Unknown\"\n    SessionInfo:AddItem(\"Map\", 0, function()\n        return MapName\n    end, false)\n\n    task.delay(1, function()\n        Games:Increment()\n    end)\n\n    task.spawn(function()\n        pcall(function()\n            repeat\n                task.wait()\n            until Store.matchState ~= 0 or vape.Loaded == nil\n            if vape.Loaded == nil then\n                return\n            end\n            local Map = workspace:WaitForChild(\"Map\", 9e9):WaitForChild(\"Worlds\", 9e9):GetChildren()[1]\n            MapName = Map.Name\n            MapName = string.gsub(string.split(MapName, \"_\")[2] or MapName, \"-\", \"\") or \"Blank\"\n            Store.map = Map\n            vape:Clean(Map.Blocks.ChildRemoved:Connect(function()\n                table.clear(PathCache)\n            end))\n            vape:Clean(Map.Blocks.ChildAdded:Connect(function(Block: Instance)\n                table.clear(PathCache)\n                task.defer(function()\n                    if Block:IsA(\"BasePart\") and Block:GetAttribute(\"Block\") and (Block:GetAttribute(\"PlacedByUserId\") or 0) ~= 0 then\n                        local Position: Vector3 = Block.Position / 3\n                        VapeEvents.PlaceBlockEvent:Fire({\n                            blockRef = {blockPosition = Vector3.new(math.floor(Position.X), math.floor(Position.Y), math.floor(Position.Z))},\n                            player = Players:GetPlayerByUserId(Block:GetAttribute(\"PlacedByUserId\"))\n                        })\n                    end\n                end)\n            end))\n        end)\n    end)\n\n    vape:Clean(VapeEvents.BedwarsBedBreak.Event:Connect(function(BedTable)\n        if BedTable.player and BedTable.player.UserId == LocalPlayer.UserId then\n            Beds:Increment()\n        end\n    end))\n\n    vape:Clean(VapeEvents.MatchEndEvent.Event:Connect(function(WinTable)\n        if (bedwars.Store:getState().Game.myTeam or {}).id == WinTable.winningTeamId or LocalPlayer.Neutral then\n            Wins:Increment()\n        end\n    end))\n\n    vape:Clean(VapeEvents.EntityDeathEvent.Event:Connect(function(DeathTable)\n        local Killer: Player? = Players:GetPlayerFromCharacter(DeathTable.fromEntity)\n        local Killed: Player? = Players:GetPlayerFromCharacter(DeathTable.entityInstance)\n        if not Killed or not Killer then\n            return\n        end\n\n        if Killed ~= LocalPlayer and Killer == LocalPlayer then\n            Kills:Increment()\n        end\n    end))\n\n    task.spawn(function()\n        repeat\n            task.wait()\n        until Store.map or vape.Loaded == nil\n        if vape.Loaded == nil then\n            return\n        end\n        local RayParams: RaycastParams = RaycastParams.new()\n        RayParams.FilterType = Enum.RaycastFilterType.Include\n        RayParams.FilterDescendantsInstances = {Store.map}\n        Store.airRay = RayParams\n\n        repeat\n            if Entity.isAlive then\n                Entity.character.AirTime = Entity.character.Humanoid.FloorMaterial ~= Enum.Material.Air and tick() or Entity.character.AirTime\n            end\n\n            local LocalPosition = Entity.isAlive and Entity.character.RootPart.Position or nil\n            local Gravity, Now = workspace.Gravity, tick()\n            for _, v: any in Entity.List do\n                local Velocity: Vector3 = v.RootPart.AssemblyLinearVelocity\n                v.LandTick = math.abs(Velocity.Y) < 0.1 and v.LandTick or Now\n                if (Now - v.LandTick) > 0.2 and v.Jumps ~= 0 then\n                    v.Jumps = 0\n                    v.Jumping = false\n                end\n\n                local Moving: boolean = Velocity.Magnitude > 1\n                if v.Targetable and (Now - (v.TrackTick or 0)) >= (Moving and 1 / 30 or 0.2) then\n                    v.TrackTick = Now\n                    PredictionLib.Observe(v.RootPart, v.RootPart.Position, Velocity, v.Humanoid.FloorMaterial == Enum.Material.Air or math.abs(Velocity.Y) > 0.01, Gravity, Moving and LocalPosition or nil, v.HipHeight, v.Jumping and 42.6 or nil)\n                end\n            end\n            task.wait()\n        until vape.Loaded == nil\n    end)\n\n    local KitModules = {\n        agni = {\"AutoAgni\"},\n        airbender = {\"AutoRamil\"},\n        alchemist = {\"AutoMushroom\"},\n        beast = {\"AutoCrocowolf\"},\n        beekeeper = {\"AutoBeekeeper\", \"KitSpy\"},