cal Gravity: number = LaunchValues and LaunchValues.gravitationalAcceleration or ProjectileMeta.gravitationalAcceleration or 196.2\n\t    LaunchPosition = LaunchValues and LaunchValues.positionFrom or LaunchPosition\n\t    local TargetVelocity: Vector3 = Ent.RootPart.AssemblyLinearVelocity\n\t    local AimPosition, _, TravelTime = PredictionLib.SolveTrajectory(LaunchPosition, Speed, Gravity, TargetPosition, TargetVelocity, workspace.Gravity, Ent.HipHeight, Ent.Jumping and 42.6 or nil, nil, Ent.Humanoid.FloorMaterial == Enum.Material.Air or math.abs(TargetVelocity.Y) > 0.01, Ent.RootPart.Position, Ent.RootPart, nil, true)\n\t    if not AimPosition or not TravelTime or TravelTime > (ProjectileMeta.lifetimeSec or 3) then\n\t        return nil\n\t    end\n\t\n\t    return GetCameraAim(LaunchPosition, AimPosition, Handler)\n\tend\n\t\n\tlocal Started, LastTarget, NextSearch = 0, nil, 0\n\tlocal RolledSpeed: number = 0\n\tlocal AimFunctions = {\n\t    Simple = function(LocalCFrame: CFrame, Point: Vector3, DeltaTime: number)\n\t        local Speed: number = (RolledSpeed + (StrafeIncrease.Enabled and (UserInputService:IsKeyDown(Enum.KeyCode.A) or UserInputService:IsKeyDown(Enum.KeyCode.D)) and 10 or 0)) / Smoothness.Value\n\t        return LocalCFrame:Lerp(CFrame.lookAt(LocalCFrame.p, Point + Vector3.new((RandomGenerator:NextNumber() - 0.5) * Shake.Value * DeltaTime, (RandomGenerator:NextNumber() - 0.5) * Shake.Value * DeltaTime, (RandomGenerator:NextNumber() - 0.5) * Shake.Value * DeltaTime)), math.clamp(Speed * DeltaTime, 0, 1)), Speed\n\t    end,\n\t    Adaptive = function(LocalCFrame: CFrame, Point: Vector3, DeltaTime: number)\n\t        local T: number = math.min(tick() - Started, 1)\n\t        local Progress: number = T < 0.5 and 4 * T * T * T or 1 - math.pow(-2 * T + 2, 3) / 2\n\t        local Speed: number = ((RolledSpeed * 0.1 * Progress) + (1 - Progress) + (StrafeIncrease.Enabled and (UserInputService:IsKeyDown(Enum.KeyCode.A) or UserInputService:IsKeyDown(Enum.KeyCode.D)) and 10 or 5)) / Smoothness.Value\n\t        return LocalCFrame:Lerp(CFrame.lookAt(LocalCFrame.p, Point + Vector3.new((RandomGenerator:NextNumber() - 0.5) * Shake.Value * DeltaTime, (RandomGenerator:NextNumber() - 0.5) * Shake.Value * DeltaTime, (RandomGenerator:NextNumber() - 0.5) * Shake.Value * DeltaTime)), math.clamp(Speed * DeltaTime, 0, 1)), Speed\n\t    end\n\t}\n\t\n\tAimAssist = vape.Categories.Combat:CreateModule({\n\t    Name = \"AimAssist\",\n\t    Function = function(Callback: boolean)\n\t        if Callback then\n\t            local RotateTime: number = 0\n\t            AimAssist:Clean(RunService.PostSimulation:Connect(function(DeltaTime: number)\n\t                if Entity.isAlive then\n\t                    Entity.character.Humanoid.AutoRotate = tick() > RotateTime\n\t\n\t                    local ProjectileMeta, Handler = GetProjectile()\n\t                    local Charging: boolean = ProjectileMeta ~= nil and (bedwars.ProjectileController.isTargeting == true or (not canDebug and UserInputService:IsMouseButtonPressed(Enum.UserInputType.MouseButton1)))\n\t                    local Range: number = ProjectileMeta and ProjectileRange.Value or Distance.Value\n\t\n\t                    local Blocked: boolean = Mouse.Enabled and not Charging and not UserInputService:IsMouseButtonPressed(0) and (tick() - bedwars.SwordController.lastSwing) > 0.15\n\t                    Blocked = Blocked or (ClickAim.Enabled and not Charging and (tick() - bedwars.SwordController.lastSwing) > 0.3)\n\t                    Blocked = Blocked or (BlockBreak.Enabled and (tick() - Store.lastHit) < 0.3)\n\t                    Blocked = Blocked or (Limit.Enabled and Store.hand.toolType ~= \"sword\" and not ProjectileMeta)\n\t\n\t                    local Ent\n\t                    if not Blocked then\n\t                        if Entity.isAlive and LastTarget and LastTarget.Character and LastTarget.Character.Parent and LastTarget.RootPart and LastTarget.RootPart.Parent and LastTarget.Targetable and Entity.isVulnerable(LastTarget) and (Entity.character.RootPart.Position - LastTarget.RootPart.Position).Magnitude <= Range and not (Targets.Walls.Enabled and Entity.Wallcheck(Entity.character.RootPart.Position, LastTarget.RootPart.Position, Targets.Walls.Enabled, LastTarget)) and tick() < NextSearch then\n\t                            Ent = LastTarget\n\t                        else\n\t                            local Target = Store.KillauraTarget\n\t                            Ent = KillauraTarget.Enabled and Entity.isAlive and Target and Target.Character and Target.Character.Parent and Target.RootPart and Target.RootPart.Parent and Target.Targetable and Entity.isVulnerable(Target) and (Entity.character.RootPart.Position - Target.RootPart.Position).Magnitude <= Range and not (Targets.Walls.Enabled and Entity.Wallcheck(Entity.character.RootPart.Position, Target.RootPart.Position, Targets.Walls.Enabled, Target)) and Target or Entity.EntityPosition({\n\t                                Range = Range,\n\t                                Part = \"RootPart\",\n\t                                Wallcheck = Targets.Walls.Enabled,\n\t                                Players = Targets.Players.Enabled,\n\t                                NPCs = Targets.NPCs.Enabled,\n\t                                Priority = Targets.Priority.Value,\n\t                                Sort = SortMethods[Sort.Value]\n\t                            })\n\t                            if Ent ~= LastTarget then\n\t                                Started = tick()\n\t                            end\n\t                            LastTarget = Ent\n\t                            NextSearch = tick() + 1\n\t                            RolledSpeed = AimSpeed:GetRandomValue()\n\t                        end\n\t                    end\n\t\n\t                    if Ent then\n\t                        local Root: BasePart = Entity.character.RootPart\n\t                        local Offset: Vector3 = (Ent.RootPart.Position - Root.Position)\n\t                        local LocalFacing: Vector3 = Root.CFrame.LookVector * Vector3.new(1, 0, 1)\n\t                        local Horizontal: Vector3 = Offset * Vector3.new(1, 0, 1)\n\t                        local Angle: number = LocalFacing.Magnitude > 0 and Horizontal.Magnitude > 0 and math.acos(math.clamp(LocalFacing.Unit:Dot(Horizontal.Unit), -1, 1)) or 0\n\t                        if Angle >= (math.rad(AngleSlider.Value) / 2) then\n\t                            return\n\t                        end\n\t\n\t                        local AimPoint: Vector3? = if ProjectileMeta then Ent.RootPart.Position else GetAim(Ent)\n\t                        if ProjectileMeta then\n\t                            AimPoint = GetProjectileAim(Ent, AimPoint, ProjectileMeta, Handler)\n\t                            if not AimPoint then\n\t                                return\n\t                            end\n\t                        end\n\t                        TargetInfo.Targets[Ent] = tick() + 1\n\t\n\t                        local FirstPerson: boolean = Entity.character.Head.LocalTransparencyModifier == 1\n\t                        local Perspective: string = AimMode.Value\n\t                        if Perspective == \"Mouse\" then\n\t                            local AimCFrame, Speed = AimFunctions[Mode.Value](Camera.CFrame, AimPoint, DeltaTime)\n\t                            local Viewport: Vector3 = Camera:WorldToViewportPoint(AimCFrame.Position + AimCFrame.LookVector * (AimPoint - AimCFrame.Position).Magnitude)\n\t                            local MouseOffset: Vector2 = (Vector2.new(Viewport.X, Viewport.Y) - UserInputService:GetMouseLocation()) * (Speed / 15)\n\t                            mousemoverel(MouseOffset.X, MouseOffset.Y)\n\t                        elseif Perspective == \"First person\" or (Perspective == \"Dynamic\" and FirstPerson) then\n\t                            if not FirstPerson then\n\t                                return\n\t                            end\n\t                            local AimCFrame: CFrame = AimFunctions[Mode.Value](Camera.CFrame, AimPoint, DeltaTime)\n\t                            Camera.CFrame = AimCFrame\n\t                        elseif Perspective == \"Third person\" or (Perspective == \"Dynamic\" and not FirstPerson) then\n\t                            if FirstPerson then\n\t                                return\n\t                            end\n\t\n\t                            if ProjectileMeta then\n\t                                local AimCFrame: CFrame = AimFunctions[Mode.Value](Camera.CFrame, AimPoint, DeltaTime)\n\t                                Camera.CFrame = AimCFrame\n\t                            else\n\t                                local AimCFrame: CFrame = AimFunctions[Mode.Value](Root.CFrame, AimPoint, DeltaTime)\n\t                                local Direction: Vector3 = AimCFrame.LookVector * Vector3.new(1, 0, 1)\n\t                                if Direction.Magnitude > 0 then\n\t                                    Entity.character.Humanoid.AutoRotate = false\n\t                                    Root.CFrame = CFrame.lookAlong(Root.Position, Direction)\n\t                                    RotateTime = tick() + 0.1\n\t                                end\n\t                            end\n\t                        end\n\t                    end\n\t                else\n\t                    LastTarget = nil\n\t                end\n\t            end))\n\t        else\n\t            LastTarget = nil\n\t            if Entity.isAlive then\n\t                Entity.character.Humanoid.AutoRotate = true\n\t            end\n\t        end\n\t    end,\n\t    Tooltip = \"Smoothly aims to closest valid target with sword\"\n\t})\n\t\n\tAimMode = AimAssist:CreateDropdown({\n\t    Name = \"Aim perspective\",\n\t    Tooltip = \"First person - Uses your camera to aim\\nThird person - Moves your character to where your supposed to look\\nMouse - Moves your mouse & camera\\nDynamic - Uses first person mode if ur in first person, and uses third person if ur in third person\",\n\t    List = {\"First person\", \"Third person\", \"Dynamic\"},\n\t    Default = \"First person\"\n\t})\n\tMode = AimAssist:CreateDropdown({\n\t    Name = \"Mode\",\n\t    List = {\"Simple\", \"Adaptive\"},\n\t    Tooltip = \"Simple - Smooth aiming\\nAdaptive - Advanced tracking with adaptive behavior\",\n\t    Default = \"Simple\"\n\t})\n\tTargets = AimAssist:CreateTargets({\n\t    Players = true,\n\t    Walls = true\n\t})\n\tlocal Methods: {string} = {\"Angle\", \"Damage\", \"Distance\"}\n\tfor _, v: string in SortList do\n\t    if not table.find(Methods, v) then\n\t        table.insert(Methods, v)\n\t    end\n\tend\n\tClickAim = AimAssist:CreateToggle({\n\t    Name = \"Click aim\",\n\t    Default = true\n\t})\n\tMouse = AimAssist:CreateToggle({Name = \"Require mouse down\"})\n\tStrafeIncrease = AimAssist:CreateToggle({Name = \"Strafe increase\"})\n\tBlockBreak = AimAssist:CreateToggle({Name = \"Check block break\"})\n\tKillauraTarget = AimAssist:CreateToggle({Name = \"Use killaura target\"})\n\tAimSpeed = AimAssist:CreateTwoSlider({\n\t    Name = \"Aim speed\",\n\t    Min = 1,\n\t    Max = 20,\n\t    DefaultMin = 6,\n\t    DefaultMax = 6,\n\t    Tooltip = \"Picks a random speed between the two values every time it looks for a target, so on each lock-on and once a second while it stays on the same one\"\n\t})\n\tSmoothness = AimAssist:CreateSlider({\n\t    Name = \"Smoothness\",\n\t    Min = 1,\n\t    Max = 20,\n\t    Default = 1,\n\t    Decimal = 10,\n\t    Tooltip = \"Divides the aim speed to soften the snap, 1 leaves aiming unchanged\"\n\t})\n\tDistance = AimAssist:CreateSlider({\n\t    Name = \"Distance\",\n\t    Min = 1,\n\t    Max = 30,\n\t    Default = 30,\n\t    Suffix = function(Val: number)\n\t        return Val == 1 and \"stud\" or \"studs\"\n\t    end\n\t})\n\tShake = AimAssist:CreateSlider({\n\t    Name = \"Shake\",\n\t    Min = 0,\n\t    Max = 100,\n\t    Default = 0,\n\t    Tooltip = \"Adds random jitter to simulate human aim\"\n\t})\n\tAngleSlider = AimAssist:CreateSlider({\n\t    Name = \"Max angle\",\n\t    Min = 1,\n\t    Max = 360,\n\t    Default = 70\n\t})\n\tLimit = AimAssist:CreateToggle({\n\t    Name = \"Limit to items\",\n\t    Tooltip = \"Only attacks when sword is held, or a projectile weapon while Projectiles is on\"\n\t})\n\tProjectiles = AimAssist:CreateToggle({\n\t    Name = \"Projectiles\",\n\t    Function = function(Callback: boolean)\n\t        ProjectileRange.Object.Visible = Callback\n\t    end,\n\t    Tooltip = \"While you hold a bow or another damaging projectile, aims where the shot will meet a moving target instead of at their body, always at the body's center. Click aim then aims while you draw, and third person turns your camera since shots follow it\"\n\t})\n\tProjectileRange = AimAssist:CreateSlider({\n\t    Name = \"Projectile Range\",\n\t    Min = 1,\n\t    Max = 300,\n\t    Default = 200,\n\t    Darker = true,\n\t    Visible = false,\n\t    Suffix = function(Val: number)\n\t        return Val == 1 and \"stud\" or \"studs\"\n\t    end,\n\t    Tooltip = \"How far away a target can be while you hold a projectile, used instead of Distance\"\n\t})\n\tSort = AimAssist:CreateDropdown({\n\t    Name = \"Target mode\",\n\t    List = Methods,\n\t    Default = \"Angle\"\n\t})\n\tAimPart = AimAssist:CreateDropdown({\n\t    Name = \"Target area\",\n\t    List = {\"Center\", \"Closest\"},\n\t    Default = \"Center\"\n\t})\nend)\n\nRun(function()\n\tlocal AutoClicker\n\tlocal CPS\n\tlocal Place\n\tlocal Wool\n\tlocal BlockCPS = {}\n\tlocal Thread: thread?\n\t\n\tlocal function IsAttackInput(Input: InputObject): boolean\n\t    local Controller = bedwars.KeybindLoadController\n\t    local Keybinds = Controller and typeof(Controller.getKeybinds) == \"function\" and Controller:getKeybinds()\n\t    local Keyboard = Keybinds and Keybinds.keyboard and Keybinds.keyboard.controlActions.Attack\n\t    local Gamepad = Keybinds and Keybinds.gamepad and Keybinds.gamepad.controlActions.Attack\n\t    Keyboard = typeof(Keyboard) == \"EnumItem\" and Keyboard or Enum.UserInputType.MouseButton1\n\t    Gamepad = typeof(Gamepad) == \"EnumItem\" and Gamepad or Enum.KeyCode.ButtonR2\n\t\n\t    return Input.UserInputType == Keyboard or Input.KeyCode == Keyboard or Input.KeyCode == Gamepad\n\tend\n\t\n\tlocal function IsHeld(Input: InputObject?): boolean\n\t    if not Input then\n\t        return true\n\t    end\n\t\n\t    local Type: Enum.UserInputType = Input.UserInputType\n\t    if Type == Enum.UserInputType.Keyboard then\n\t        return UserInputService:IsKeyDown(Input.KeyCode)\n\t    elseif Type.Name:find(\"MouseButton\") then\n\t        return UserInputService:IsMouseButtonPressed(Type)\n\t    elseif Type.Name:find(\"Gamepad\") then\n\t        return UserInputService:IsGamepadButtonDown(Type, Input.KeyCode)\n\t    end\n\t\n\t    return true\n\tend\n\t\n\tlocal function LastPlaced(): number\n\t    local Stamp = vape.Libraries.cheatengine.LastOwnPlace\n\t    return typeof(Stamp) == \"number\" and Stamp or 0\n\tend\n\t\n\tlocal function AutoClick(Held: InputObject?)\n\t    if Thread then\n\t        task.cancel(Thread)\n\t    end\n\t\n\t    local Interval: number = Store.hand.toolType == \"block\" and math.max(1 / BlockCPS:GetRandomValue(), 1 / (bedwars.SharedConstants.BLOCK_PLACE_CPS or 12)) or 1 / CPS:GetRandomValue()\n\t    Thread = task.delay(canDebug and Interval or 0.05, function()\n\t        local First: boolean = true\n\t        repeat\n\t            if not IsHeld(Held) then\n\t                break\n\t            end\n\t\n\t            local Native: boolean = First and not canDebug and (os.clock() - LastPlaced() < 0.1 or tick() - bedwars.SwordController.lastSwing < 0.1)\n\t            First = false\n\t\n\t            if not Native and not bedwars.AppController:isLayerOpen(bedwars.UILayers.MAIN) then\n\t                local BlockPlacer = bedwars.BlockPlacementController.blockPlacer\n\t                if Store.hand.toolType == \"block\" and Place.Enabled and (Wool.Enabled and Store.hand.tool.Name:find(\"wool_\") or not Wool.Enabled) and BlockPlacer and CanPlace() then\n\t                    if (workspace:GetServerTimeNow() - bedwars.BlockCpsController.lastPlaceTimestamp) >= ((1 / (bedwars.SharedConstants.BLOCK_PLACE_CPS or 12)) * 0.5) then\n\t                        if UserInputService.TouchEnabled then\n\t                            task.spawn(BlockPlacer.autoBridge, BlockPlacer, workspace:GetServerTimeNow() - bedwars.KnockbackController:getLastKnockbackTime() >= 0.2)\n\t                        else\n\t                            local Selector = BlockPlacer.clientManager:getBlockSelector()\n\t                            local MouseInfo = Selector and Selector:getMouseInfo(0)\n\t                            if MouseInfo and MouseInfo.placementPosition == MouseInfo.placementPosition then\n\t                                task.spawn(BlockPlacer.placeBlock, BlockPlacer, MouseInfo.placementPosition, MouseInfo)\n\t                            end\n\t                        end\n\t                    end\n\t                elseif Store.hand.toolType == \"sword\" then\n\t                    if UserInputService.TouchEnabled then\n\t                        bedwars.SwordController:mobileSwingPressed()\n\t                    elseif CanSwing() and not bedwars.SwordController.disableSwingState then\n\t                        bedwars.SwordController:swingSwordAtMouse(0.39)\n\t                    end\n\t                elseif Store.hand.tool and bedwars.IsItemClaw(Store.hand.tool.Name) then\n\t                    bedwars.SummonerClawHandController:attack(Store.hand.tool.Name)\n\t                end\n\t            end\n\t\n\t            task.wait(Store.hand.toolType == \"block\" and math.max(1 / BlockCPS:GetRandomValue(), 1 / (bedwars.SharedConstants.BLOCK_PLACE_CPS or 12)) or 1 / CPS:GetRandomValue())\n\t        until not AutoClicker.Enabled\n\t    end)\n\tend\n\t\n\tAutoClicker = vape.Categories.Combat:CreateModule({\n\t    Name = \"AutoClicker\",\n\t    Function = function(Callback: boolean)\n\t        if Callback then\n\t            AutoClicker:Clean(UserInputService.InputBegan:Connect(function(Input: InputObject)\n\t                if IsAttackInput(Input) then\n\t                    AutoClick(Input)\n\t                end\n\t            end))\n\t\n\t            AutoClicker:Clean(UserInputService.InputEnded:Connect(function(Input: InputObject)\n\t                if IsAttackInput(Input) and Thread then\n\t                    task.cancel(Thread)\n\t                    Thread = nil\n\t                end\n\t            end))\n\t\n\t            if UserInputService.TouchEnabled then\n\t                local Hooked: {[Instance]: boolean} = {}\n\t                local function HookButton(Button: Instance)\n\t                    if Hooked[Button] or not Button:IsA(\"GuiButton\") or not tonumber(Button.Name) then\n\t                        return\n\t                    end\n\t                    Hooked[Button] = true\n\t                    AutoClicker:Clean(Button.MouseButton1Down:Connect(function()\n\t                        AutoClick()\n\t                    end))\n\t                    AutoClicker:Clean(Button.MouseButton1Up:Connect(function()\n\t                        if Thread then\n\t                            task.cancel(Thread)\n\t                            Thread = nil\n\t                        end\n\t                    end))\n\t                end\n\t\n\t                task.spawn(function()\n\t                    local MobileUI: Instance? = LocalPlayer.PlayerGui:WaitForChild(\"MobileUI\", 20)\n\t                    if not MobileUI or not AutoClicker.Enabled then\n\t                        return\n\t                    end\n\t\n\t                    for _, v: Instance in MobileUI:GetChildren() do\n\t                        HookButton(v)\n\t                    end\n\t                    AutoClicker:Clean(MobileUI.ChildAdded:Connect(HookButton))\n\t                end)\n\t            end\n\t        else\n\t            if Thread then\n\t                task.cancel(Thread)\n\t                Thread = nil\n\t            end\n\t        end\n\t    end,\n\t    Tooltip = \"Hold attack button to automatically click\"\n\t})\n\t\n\tCPS = AutoClicker:CreateTwoSlider({\n\t    Name = \"CPS\",\n\t    Min = 1,\n\t    Max = 20,\n\t    DefaultMin = 7,\n\t    DefaultMax = 7\n\t})\n\tPlace = AutoClicker:CreateToggle({\n\t    Name = \"Place Blocks\",\n\t    Function = function(Callback: boolean)\n\t        if BlockCPS.Object then\n\t            BlockCPS.Object.Visible = Callback\n\t        end\n\t\n\t        if Wool then\n\t            Wool.Object.Visible = Callback\n\t        end\n\t    end,\n\t    Default = true\n\t})\n\tWool = AutoClicker:CreateToggle({Name = \"Wool only\", Tooltip = \"Only clicks when you are holding wool.\", Darker = true})\n\tBlockCPS = AutoClicker:CreateTwoSlider({\n\t    Name = \"Block CPS\",\n\t    Min = 1,\n\t    Max = 20,\n\t    DefaultMin = 20,\n\t    DefaultMax = 20,\n\t    Darker = true\n\t})\nend)\n\nRun(function()\n\tlocal BowAssist\n\tlocal Targets\n\tlocal Sort\n\tlocal AimPart\n\tlocal FOV\n\tlocal AimSpeed\n\tlocal Smoothness\n\tlocal Distance\n\tlocal Shake\n\tlocal Clear\n\tlocal Blacklist\n\t\n\tlocal DrawStart, OldStart, OldStop = 0\n\tlocal RandomGenerator: Random = Random.new()\n\t\n\tlocal ArcCheck: RaycastParams = RaycastParams.new()\n\tArcCheck.FilterType = Enum.RaycastFilterType.Exclude\n\t\n\tBowAssist = vape.Categories.Combat:CreateModule({\n\t    Name = \"BowAssist\",\n\t    Function = function(Callback: boolean)\n\t        if Callback then\n\t            OldStart = bedwars.DefaultProjectileSourceController.onStartCharging\n\t            bedwars.DefaultProjectileSourceController.onStartCharging = function(self, ...)\n\t                DrawStart = tick()\n\t                return OldStart(self, ...)\n\t            end\n\t\n\t            OldStop = bedwars.DefaultProjectileSourceController.onStopCharging\n\t            bedwars.DefaultProjectileSourceController.onStopCharging = function(self, ...)\n\t                DrawStart = 0\n\t                return OldStop(self, ...)\n\t            end\n\t\n\t            BowAssist:Clean(RunService.PostSimulation:Connect(function(DeltaTime: number)\n\t                if DrawStart == 0 or not Entity.isAlive then\n\t                    return\n\t                end\n\t\n\t                local ItemMeta = Store.hand.tool and bedwars.ItemMeta[Store.hand.tool.Name]\n\t                local ProjectileSource = ItemMeta and ItemMeta.projectileSource\n\t                if not ProjectileSource or not ProjectileSource.projectileType then\n\t                    return\n\t                end\n\t\n\t                local Ammo = Store.hand.tool.Name\n\t                if ProjectileSource.ammoItemTypes and #ProjectileSource.ammoItemTypes > 0 then\n\t                    Ammo = nil\n\t                    for _, v: any in Store.inventory.inventory.items do\n\t                        if table.find(ProjectileSource.ammoItemTypes, v.itemType) then\n\t                            Ammo = v.itemType\n\t                            break\n\t                        end\n\t                    end\n\t                end\n\t                if not Ammo then\n\t                    return\n\t                end\n\t\n\t                local ProjectileType: string = ProjectileSource.projectileType(Ammo)\n\t                if table.find(Blacklist.ListEnabled or {}, ((ProjectileType == \"glue_trap\" or ProjectileType == \"glue_projectile\") and \"gloop\" or ProjectileType)) then\n\t                    return\n\t                end\n\t\n\t                local ProjectileMeta = bedwars.ProjectileMeta[ProjectileType]\n\t                if not ProjectileMeta or type(ProjectileMeta.launchVelocity) ~= \"number\" then\n\t                    return\n\t                end\n\t\n\t                local Scalar: number = ProjectileSource.minStrengthScalar or 1\n\t                local Ratio: number = ProjectileSource.maxStrengthChargeSec and math.clamp((tick() - DrawStart) / ProjectileSource.maxStrengthChargeSec, 0, 1) or 1\n\t                local ProjectileSpeed: number = ProjectileMeta.launchVelocity * (Scalar + (1 - Scalar) * Ratio)\n\t\n\t                local LocalPosition: Vector3 = Entity.character.RootPart.Position\n\t                local Ent = Entity.EntityMouse({\n\t                    Range = FOV.Value,\n\t                    Part = \"RootPart\",\n\t                    Wallcheck = Targets.Walls.Enabled,\n\t                    Players = Targets.Players.Enabled,\n\t                    NPCs = Targets.NPCs.Enabled,\n\t                    Priority = Targets.Priority.Value,\n\t                    Origin = LocalPosition,\n\t                    Sort = SortMethods[Sort.Value]\n\t                })\n\t                if not Ent or (LocalPosition - Ent.RootPart.Position).Magnitude > Distance.Value then\n\t                    return\n\t                end\n\t\n\t                local TargetPosition: Vector3 = Ent[AimPart.Value].Position\n\t                local ShootPosition: Vector3 = (CFrame.new(LocalPosition, TargetPosition) * CFrame.new(Vector3.new(-bedwars.BowConstantsTable.RelX, -bedwars.BowConstantsTable.RelY, -bedwars.BowConstantsTable.RelZ))).Position\n\t                local Gravity: number = ProjectileMeta.gravitationalAcceleration or 196.2\n\t                local AimPosition, _, TravelTime = PredictionLib.SolveTrajectory(ShootPosition, ProjectileSpeed, Gravity, TargetPosition, Ent.RootPart.AssemblyLinearVelocity, workspace.Gravity, Ent.HipHeight, Ent.Jumping and 42.6 or nil, nil, Ent.Humanoid.FloorMaterial == Enum.Material.Air or math.abs(Ent.RootPart.AssemblyLinearVelocity.Y) > 0.01, Ent.RootPart.Position, Ent.RootPart, nil, true)\n\t                if not AimPosition then\n\t                    return\n\t                end\n\t\n\t                if Clear.Enabled and TravelTime then\n\t                    local IgnoreList: {Instance} = {Camera, LocalPlayer.Character}\n\t                    for _, v: any in Entity.List do\n\t                        if v.Character then\n\t                            table.insert(IgnoreList, v.Character)\n\t                        end\n\t                    end\n\t                    ArcCheck.FilterDescendantsInstances = IgnoreList\n\t                    if not PredictionLib.IsTrajectoryClear(ShootPosition, AimPosition - ShootPosition, Gravity, TravelTime, ArcCheck) then\n\t                        return\n\t                    end\n\t                end\n\t\n\t                TargetInfo.Targets[Ent] = tick() + 1\n\t                local Jitter: Vector3 = Vector3.new((RandomGenerator:NextNumber() - 0.5) * Shake.Value * DeltaTime, (RandomGenerator:NextNumber() - 0.5) * Shake.Value * DeltaTime, (RandomGenerator:NextNumber() - 0.5) * Shake.Value * DeltaTime)\n\t                Camera.CFrame = Camera.CFrame:Lerp(CFrame.lookAt(Camera.CFrame.Position, AimPosition + Jitter), math.clamp((AimSpeed.Value / Smoothness.Value) * DeltaTime, 0, 1))\n\t            end))\n\t        else\n\t            DrawStart = 0\n\t            bedwars.DefaultProjectileSourceController.onStartCharging = OldStart\n\t            bedwars.DefaultProjectileSourceController.onStopCharging = OldStop\n\t        end\n\t    end,\n\t    Tooltip = \"Eases your camera onto the arrow drop while you draw a bow\"\n\t})\n\t\n\tTargets = BowAssist:CreateTargets({\n\t    Players = true,\n\t    Walls = true\n\t})\n\tlocal Methods: {string} = {\"Distance\", \"Damage\"}\n\tfor _, v: string in SortList do\n\t    if not table.find(Methods, v) then\n\t        table.insert(Methods, v)\n\t    end\n\tend\n\tSort = BowAssist:CreateDropdown({\n\t    Name = \"Target mode\",\n\t    List = Methods,\n\t    Default = \"Distance\"\n\t})\n\tAimPart = BowAssist:CreateDropdown({\n\t    Name = \"Part\",\n\t    List = {\"RootPart\", \"Head\"}\n\t})\n\tFOV = BowAssist:CreateSlider({\n\t    Name = \"FOV\",\n\t    Min = 1,\n\t    Max = 1000,\n\t    Default = 220,\n\t    Tooltip = \"How far from your crosshair a target can sit before it gets ignored\"\n\t})\n\tDistance = BowAssist:CreateSlider({\n\t    Name = \"Distance\",\n\t    Min = 1,\n\t    Max = 300,\n\t    Default = 200,\n\t    Suffix = function(Val: number)\n\t        return Val == 1 and \"stud\" or \"studs\"\n\t    end\n\t})\n\tAimSpeed = BowAssist:CreateSlider({\n\t    Name = \"Aim speed\",\n\t    Min = 1,\n\t    Max = 20,\n\t    Default = 5\n\t})\n\tSmoothness = BowAssist:CreateSlider({\n\t    Name = \"Smoothness\",\n\t    Min = 1,\n\t    Max = 20,\n\t    Default = 2,\n\t    Decimal = 10,\n\t    Tooltip = \"Divides the aim speed to soften the pull, 1 leaves it unchanged\"\n\t})\n\tShake = BowAssist:CreateSlider({\n\t    Name = \"Shake\",\n\t    Min = 0,\n\t    Max = 100,\n\t    Default = 0,\n\t    Tooltip = \"Adds random jitter so the pull does not read as a straight line\"\n\t})\n\tClear = BowAssist:CreateToggle({\n\t    Name = \"Clear shot only\",\n\t    Default = true,\n\t    Tooltip = \"Stops assisting when a block is in the way of the arc\"\n\t})\n\tBlacklist = BowAssist:CreateTextList({\n\t    Name = \"Blacklist\",\n\t    Default = {\"gloop\", \"telepearl\"},\n\t    Darker = true,\n\t    Placeholder = \"projectile\",\n\t    Tooltip = \"Projectile types the assist leaves alone\"\n\t})\nend)\n\nRun(function()\n\tlocal SwordTiming = vape.Libraries.swordtiming\n\tlocal HitregAdjuster\n\tlocal Hitreg\n\tlocal SwordSpeed, SwingSpeed, SwingRestore\n\tlocal HitBudget: number = 60 / bedwars.Handler:Get(\"SwordHit\"):GetRateLimit()\n\t\n\tHitregAdjuster = vape.Categories.Combat:CreateModule({\n\t    Name = \"HitregAdjuster\",\n\t    Function = function(Callback: boolean)\n\t        if Callback then\n\t            SwingSpeed = bedwars.SyncEvents.SwordSwing:setPriority(150):connect(function(Event)\n\t                SwordSpeed = Event.attackSpeed\n\t                local Fury: number = bedwars.StatusEffectUtil:isActive(LocalPlayer.Character, \"fury_potion\") and 1 - (bedwars.BlackMarketeerBalance.FURY_POTION_ATTACK_SPEED_MULTIPLIER - 1) or 1\n\t                local BaseSpeed: number = SwordSpeed / Fury\n\t                local Meta = bedwars.ItemMeta[Event.swordType]\n\t                local MetaSpeed: number? = Meta and Meta.sword and Meta.sword.attackSpeed\n\t                if MetaSpeed and math.abs(BaseSpeed - MetaSpeed) < 0.000001 then BaseSpeed = MetaSpeed end\n\t                local Spacing, _, _, Cooldown = SwordTiming.Calculate(BaseSpeed, Fury, Hitreg.Value >= 35, HitBudget, Hitreg.Value)\n\t                Event.attackSpeed = math.max(Spacing, Cooldown)\n\t            end)\n\t            SwingRestore = bedwars.SyncEvents.SwordSwing:setPriority(300):connect(function(Event)\n\t                Event.attackSpeed = SwordSpeed\n\t            end)\n\t            HitregAdjuster:Clean(function()\n\t                SwingSpeed:Destroy()\n\t                SwingRestore:Destroy()\n\t            end)\n\t        end\n\t    end,\n\t    Tooltip = \"Swaps the games attack cooldown for a hit count of your own\"\n\t})\n\t\n\tHitreg = HitregAdjuster:CreateSlider({\n\t    Name = \"Hitreg\",\n\t    Min = 1,\n\t    Max = 36,\n\t    Default = 35,\n\t    Suffix = function(Val: number)\n\t        return Val == 1 and \"hit / 10s\" or \"hits / 10s\"\n\t    end,\n\t    Tooltip = \"Spacing your manual and autoclicker hits fire at, 35 is the killaura spacing (fury potion still speeds it up)\"\n\t})\nend)\n\nRun(function()\n\tlocal NoClickDelay\n\tlocal SwingLock\n\tlocal Drill\n\tlocal Old, OldDrill, OldLock\n\t\n\tNoClickDelay = vape.Categories.Combat:CreateModule({\n\t    Name = \"NoClickDelay\",\n\t    Function = function(Callback: boolean)\n\t        if Callback then\n\t            Old = bedwars.SwordController.isClickingTooFast\n\t            bedwars.SwordController.isClickingTooFast = function(self)\n\t                self.lastSwing = tick()\n\t                return false\n\t            end\n\t\n\t            if SwingLock.Enabled then\n\t                OldLock = bedwars.SwordController.getSwordSwingDisabled\n\t                bedwars.SwordController.getSwordSwingDisabled = function()\n\t                    return false\n\t                end\n\t            end\n\t\n\t            if Drill.Enabled then\n\t                OldDrill = bedwars.DrillTabletController.isClickingTooFast\n\t                bedwars.DrillTabletController.isClickingTooFast = function()\n\t                    return false\n\t                end\n\t            end\n\t        else\n\t            bedwars.SwordController.isClickingTooFast = Old\n\t\n\t            if OldLock then\n\t                bedwars.SwordController.getSwordSwingDisabled = OldLock\n\t                OldLock = nil\n\t            end\n\t\n\t            if OldDrill then\n\t                bedwars.DrillTabletController.isClickingTooFast = OldDrill\n\t                OldDrill = nil\n\t            end\n\t        end\n\t    end,\n\t    Tooltip = \"Removes the 9 clicks a second cap the client puts on swinging\"\n\t})\n\t\n\tSwingLock = NoClickDelay:CreateToggle({\n\t    Name = \"Swing lock\",\n\t    Function = function()\n\t        if NoClickDelay.Enabled then\n\t            NoClickDelay:Toggle()\n\t            NoClickDelay:Toggle()\n\t        end\n\t    end,\n\t    Tooltip = \"Also lets you swing while a kit ability has swinging turned off, like sigrid on her elk\"\n\t})\n\tDrill = NoClickDelay:CreateToggle({\n\t    Name = \"Drill\",\n\t    Function = function()\n\t        if NoClickDelay.Enabled then\n\t            NoClickDelay:Toggle()\n\t            NoClickDelay:Toggle()\n\t        end\n\t    end,\n\t    Default = true,\n\t    Tooltip = \"Removes the same cap on the drill tablet\"\n\t})\nend)\n\nRun(function()\n\tlocal BlockReach\n\tlocal BlockRange\n\tlocal BreakReach\n\tlocal BreakRange\n\tlocal SwordReach\n\tlocal SwordRange\n\tlocal AirHits\n\t\n\tlocal RandomGenerator, Old, OldSend = Random.new()\n\tlocal SwingConnection\n\tlocal LastExtendedSwing: number = 0\n\t\n\tlocal function ExtendedSwordHit()\n\t    if not Entity.isAlive then\n\t        return\n\t    end\n\t\n\t    local Sword = GetSword()\n\t    if not Sword or (tick() - LastExtendedSwing) < GetSwordSpeed(Sword.tool) then\n\t        return\n\t    end\n\t\n\t    local ReachDistance: number = GetReach(Sword.tool)\n\t    local LocalPosition: Vector3 = Entity.character.RootPart.Position\n\t    local Target = Entity.EntityPosition({\n\t        Origin = LocalPosition,\n\t        Range = SwordRange.Value + 2,\n\t        Part = \"RootPart\",\n\t        Players = true,\n\t        NPCs = true,\n\t        Wallcheck = true\n\t    })\n\t    if not Target then\n\t        return\n\t    end\n\t\n\t    local Delta: Vector3 = Target.RootPart.Position - LocalPosition\n\t    if Delta.Magnitude <= ReachDistance or (Target.Humanoid and Target.Humanoid.FloorMaterial == Enum.Material.Air or math.abs(Target.RootPart.AssemblyLinearVelocity.Y) > 0.01) and RandomGenerator:NextNumber(0, 100) > AirHits:GetRandomValue() then\n\t        return\n\t    end\n\t\n\t    local Direction: Vector3 = CFrame.lookAt(LocalPosition, Target.RootPart.Position).LookVector\n\t    LastExtendedSwing = tick()\n\t    bedwars.SwordController.lastAttack = workspace:GetServerTimeNow()\n\t    bedwars.Handler:Get(\"SwordHit\"):Fire(\"SendToServer\", {\n\t        weapon = Sword.tool,\n\t        chargedAttack = {chargeRatio = 0},\n\t        entityInstance = Target.Character,\n\t        validate = {\n\t            raycast = {\n\t                cameraPosition = {value = Camera.CFrame.Position},\n\t                cursorDirection = {value = Direction}\n\t            },\n\t            targetPosition = {value = Target.Character:GetPivot().Position},\n\t            selfPosition = {value = LocalPosition + Direction * math.max(Delta.Magnitude - (ReachDistance - 0.001), 0)}\n\t        }\n\t    })\n\tend\n\t\n\tReach = vape.Categories.Combat:CreateModule({\n\t    Name = \"Reach\",\n\t    Function = function(Callback: boolean)\n\t        bedwars.CombatConstant.RAYCAST_SWORD_CHARACTER_DISTANCE = Callback and SwordReach.Enabled and SwordRange.Value + 2 or 14.4\n\t        if Callback then\n\t            Old = bedwars.BlockSelector.getMouseInfo\n\t            bedwars.BlockSelector.getMouseInfo = function(self, Mode: number, Arguments)\n\t                Arguments = Arguments or {}\n\t                if Mode == 0 then\n\t                    Arguments.range = BlockReach.Enabled and BlockRange.Value or 24\n\t                elseif Mode == 1 then\n\t                    Arguments.range = BreakReach.Enabled and BreakRange.Value or 18\n\t                end\n\t                return Old(self, Mode, Arguments)\n\t            end\n\t            if not canDebug then\n\t                Reach:Clean(vape.Libraries.cheatengine.BlockReach.Bind({\n\t                    Place = function(): number?\n\t                        return BlockReach.Enabled and BlockRange.Value or nil\n\t                    end,\n\t                    Break = function(): number?\n\t                        return BreakReach.Enabled and BreakRange.Value or nil\n\t                    end\n\t                }))\n\t            end\n\t            OldSend = bedwars.SwordController.sendServerRequest\n\t            bedwars.SwordController.sendServerRequest = function(self, Ent, ...)\n\t                local Character = Ent and Ent:getInstance()\n\t                local Humanoid: Humanoid? = Character and Character:FindFirstChildWhichIsA(\"Humanoid\")\n\t                if Character and Character.PrimaryPart and Entity.isAlive and (Character.PrimaryPart.Position - Entity.character.RootPart.Position).Magnitude > GetReach(self:getHandItem().tool) and (Humanoid and Humanoid.FloorMaterial == Enum.Material.Air or math.abs(Character.PrimaryPart.AssemblyLinearVelocity.Y) > 0.01) and RandomGenerator:NextNumber(0, 100) > AirHits:GetRandomValue() then\n\t                    return\n\t                end\n\t\n\t                return OldSend(self, Ent, ...)\n\t            end\n\t        else\n\t            bedwars.BlockSelector.getMouseInfo = Old\n\t            bedwars.SwordController.sendServerRequest = OldSend\n\t        end\n\t\n\t        if SwingConnection then\n\t            SwingConnection:Disconnect()\n\t            SwingConnection = nil\n\t        end\n\t        if not canDebug and Reach.Enabled and SwordReach.Enabled then\n\t            SwingConnection = UserInputService.InputBegan:Connect(function(Input: InputObject, Processed: boolean)\n\t                if Processed then\n\t                    return\n\t                end\n\t                if Input.UserInputType ~= Enum.UserInputType.MouseButton1 and Input.UserInputType ~= Enum.UserInputType.Touch then\n\t                    return\n\t                end\n\t\n\t                ExtendedSwordHit()\n\t            end)\n\t        end\n\t    end,\n\t    Tooltip = \"Allows you to place, attack, and break further\"\n\t})\n\t\n\tSwordReach = Reach:CreateToggle({\n\t    Name = \"Sword Reach\",\n\t    Function = function(Callback: boolean)\n\t        bedwars.CombatConstant.RAYCAST_SWORD_CHARACTER_DISTANCE = Reach.Enabled and Callback and SwordRange.Value + 2 or 14.4\n\t        if AirHits then\n\t            SwordRange.Object.Visible = Callback\n\t            AirHits.Object.Visible = Callback\n\t        end\n\t\n\t        if SwingConnection then\n\t            SwingConnection:Disconnect()\n\t            SwingConnection = nil\n\t        end\n\t        if not canDebug and Reach.Enabled and Callback then\n\t            SwingConnection = UserInputService.InputBegan:Connect(function(Input: InputObject, Processed: boolean)\n\t                if Processed then\n\t                    return\n\t                end\n\t                if Input.UserInputType ~= Enum.UserInputType.MouseButton1 and Input.UserInputType ~= Enum.UserInputType.Touch then\n\t                    return\n\t                end\n\t\n\t                ExtendedSwordHit()\n\t            end)\n\t        end\n\t    end,\n\t    Default = true\n\t})\n\tSwordRange = Reach:CreateSlider({\n\t    Name = \"Sword Range\",\n\t    Min = 1,\n\t    Max = 18,\n\t    Decimal = 5,\n\t    Darker = true,\n\t    Suffix = function(Val: number)\n\t        return Val <= 1 and \"stud\" or \"studs\"\n\t    end,\n\t    Function = function(Val: number)\n\t        bedwars.CombatConstant.RAYCAST_SWORD_CHARACTER_DISTANCE = Reach.Enabled and SwordReach.Enabled and Val or 14.4\n\t    end,\n\t    Default = 18\n\t})\n\tAirHits = Reach:CreateTwoSlider({\n\t    Name = \"Air reach hit chance\",\n\t    Min = 0,\n\t    Max = 100,\n\t    DefaultMin = 100,\n\t    DefaultMax = 100,\n\t    Darker = true,\n\t    Tooltip = \"Chance for a hit past normal reach to land while the target is off the ground, rolled fresh between the two values on every swing\"\n\t})\n\tBlockReach = Reach:CreateToggle({\n\t    Name = \"Placement Reach\",\n\t    Function = function(Callback: boolean)\n\t        BlockRange.Object.Visible = Callback\n\t    end\n\t})\n\tBlockRange = Reach:CreateSlider({\n\t    Name = \"Placement Range\",\n\t    Min = 1,\n\t    Max = 60,\n\t    Default = 18,\n\t    Darker = true,\n\t    Suffix = function(Val: number)\n\t        return Val <= 1 and \"stud\" or \"studs\"\n\t    end,\n\t    Visible = false\n\t})\n\tBreakReach = Reach:CreateToggle({\n\t    Name = \"Break Reach\",\n\t    Function = function(Callback: boolean)\n\t        BreakRange.Object.Visible = Callback\n\t    end\n\t})\n\tBreakRange = Reach:CreateSlider({\n\t    Name = \"Break Range\",\n\t    Min = 1,\n\t    Max = 30,\n\t    Default = 30,\n\t    Decimal = 5,\n\t    Darker = true,\n\t    Suffix = function(Val: number)\n\t        return Val <= 1 and \"stud\" or \"studs\"\n\t    end,\n\t    Visible = false\n\t})\n\tReach:CreateButton({\n\t    Name = \"Reset to default reach\",\n\t    Function = function()\n\t        BreakRange:SetValue(18)\n\t        BlockRange:SetValue(24)\n\t        SwordRange:SetValue(12.4)\n\t    end,\n\t    Tooltip = \"Resets every range back to default\"\n\t})\nend)\n\nRun(function()\n\tlocal SilentAim\n\tlocal Targets\n\tlocal TargetPart\n\tlocal Sort\n\tlocal Prediction\n\tlocal FOV\n\tlocal HitChance\n\tlocal HeadshotChance\n\tlocal OtherProjectiles\n\tlocal Blacklist\n\t\n\tlocal RayCheck: RaycastParams = RaycastParams.new()\n\tRayCheck.FilterType = Enum.RaycastFilterType.Include\n\t\n\tlocal OldNamecall\n\tlocal LastWarn: number = 0\n\tlocal RandomGenerator: Random = Random.new()\n\t\n\tlocal function SolveSilent(Arguments): Vector3?\n\t    local Origin, Velocity, ProjectileType = Arguments[4], Arguments[6], Arguments[3]\n\t    if typeof(Origin) ~= \"Vector3\" or typeof(Velocity) ~= \"Vector3\" or type(ProjectileType) ~= \"string\" then\n\t        return\n\t    end\n\t\n\t    if (not OtherProjectiles.Enabled) and not ProjectileType:find(\"arrow\") then\n\t        return\n\t    end\n\t\n\t    if table.find(Blacklist.ListEnabled or {}, ((ProjectileType == \"glue_trap\" or ProjectileType == \"glue_projectile\") and \"gloop\" or ProjectileType)) then\n\t        return\n\t    end\n\t\n\t    local ProjectileMeta = bedwars.ProjectileMeta[ProjectileType]\n\t    if not ProjectileMeta then\n\t        return\n\t    end\n\t\n\t    local Speed: number = Velocity.Magnitude\n\t    if Speed <= 0 then\n\t        return\n\t    end\n\t\n\t    if RandomGenerator:NextNumber(0, 100) > HitChance:GetRandomValue() then\n\t        return\n\t    end\n\t\n\t    local Map: Instance? = workspace:FindFirstChild(\"Map\")\n\t    if Map ~= RayCheck.FilterDescendantsInstances[1] then\n\t        RayCheck.FilterDescendantsInstances = Map and {Map} or {}\n\t    end\n\t    local Gravity: number = ProjectileMeta.gravitationalAcceleration or 196.2\n\t\n\t    local Target = Entity.EntityMouse({\n\t        Part = \"RootPart\",\n\t        Range = FOV.Value,\n\t        Players = Targets.Players.Enabled,\n\t        NPCs = Targets.NPCs.Enabled,\n\t        Priority = Targets.Priority.Value,\n\t        Wallcheck = Targets.Walls.Enabled,\n\t        Sort = SortMethods[Sort.Value or \"Distance\"],\n\t        MouseOrigin = Camera.ViewportSize / 2,\n\t        Origin = Origin\n\t    })\n\t    if not Target then\n\t        return\n\t    end\n\t\n\t    local PartName: string = RandomGenerator:NextNumber(0, 100) < HeadshotChance:GetRandomValue() and \"Head\" or TargetPart.Value\n\t    local SelectedPart = GetTargetPart(Target, PartName)\n\t    local TargetPosition: Vector3?\n\t    if PartName == \"Closest\" then\n\t        local Center, ClosestDistance = Camera.ViewportSize / 2, 9e9\n\t        for _, v: Instance in Target.Character:GetChildren() do\n\t            if v:IsA(\"BasePart\") then\n\t                local ScreenPosition, Visible = Camera:WorldToViewportPoint(v.Position)\n\t                if Visible then\n\t                    local PartDistance: number = (Center - Vector2.new(ScreenPosition.X, ScreenPosition.Y)).Magnitude\n\t                    if PartDistance < ClosestDistance then\n\t                        ClosestDistance, TargetPosition = PartDistance, v.Position\n\t                    end\n\t                end\n\t            end\n\t        end\n\t        TargetPosition = TargetPosition or Target.Character.PrimaryPart and Target.Character.PrimaryPart.Position\n\t    elseif PartName == \"Dynamic\" then\n\t        local Tool = Store.hand.tool\n\t        if IsHeadshotProjectile(Tool and Tool.Name) and Target.Character:FindFirstChild(\"Head\") then\n\t            TargetPosition = Target.Character.Head.Position\n\t        else\n\t            TargetPosition = Target.Character.PrimaryPart and Target.Character.PrimaryPart.Position\n\t        end\n\t    end\n\t\n\t    TargetPosition = TargetPosition or SelectedPart and SelectedPart.Position\n\t    if not TargetPosition then\n\t        return\n\t    end\n\t    local PlayerGravity: number = workspace.Gravity\n\t    local Balloons = Target.Character:GetAttribute(\"InflatedBalloons\")\n\t    if Balloons and Balloons > 0 then\n\t        PlayerGravity = workspace.Gravity * (1 - (Balloons >= 4 and 1.2 or Balloons >= 3 and 1 or 0.975))\n\t    end\n\t\n\t    if Target.Character.PrimaryPart and Target.Character.PrimaryPart:FindFirstChild(\"rbxassetid://8200754399\") then\n\t        PlayerGravity = 6\n\t    end\n\t\n\t    if Target.Player and Target.Player:GetAttribute(\"IsOwlTarget\") then\n\t        for _, v: Instance in CollectionService:GetTagged(\"Owl\") do\n\t            if v:GetAttribute(\"Target\") == Target.Player.UserId and v:GetAttribute(\"Status\") == 2 then\n\t                PlayerGravity = 0\n\t            end\n\t        end\n\t    end\n\t\n\t    local IsPearl: boolean = ProjectileType == \"telepearl\"\n\t    local TargetVelocity: Vector3 = IsPearl and Vector3.zero or Target.RootPart.AssemblyLinearVelocity\n\t    local TargetAirborne: boolean = not IsPearl and Target.Humanoid.FloorMaterial == Enum.Material.Air or math.abs(TargetVelocity.Y) > 0.01\n\t    local AimPosition, _, TravelTime = PredictionLib.SolveTrajectory(Origin, Speed * Prediction.Value, Gravity, TargetPosition, TargetVelocity, PlayerGravity, Target.HipHeight, Target.Jumping and 42.6 or nil, RayCheck, TargetAirborne, Target.RootPart.Position, Target.RootPart, nil, true)\n\t    if not AimPosition or not TravelTime or TravelTime > (ProjectileMeta.lifetimeSec or 3) then\n\t        return\n\t    end\n\t\n\t    TargetInfo.Targets[Target] = tick() + 1\n\t    Store.hitchance.SilentAim = {Value = GetHitChance(Target, TravelTime), Clock = tick()}\n\t    return CFrame.lookAt(Origin, AimPosition).LookVector * Speed\n\tend\n\t\n\tSilentAim = vape.Categories.Combat:CreateModule({\n\t    Name = \"SilentAim\",\n\t    Function = function(Callback: boolean)\n\t        if Callback and not canDebug then\n\t            SilentAim:Clean(vape.Libraries.cheatengine.ProjectileAim.Bind({\n\t                Solve = function(LaunchData, Origin: Vector3, Speed: number): Vector3?\n\t                    local Success, Velocity = pcall(SolveSilent, {nil, nil, LaunchData.projectile, Origin, nil, Camera.CFrame.LookVector * Speed})\n\t                    if Success and typeof(Velocity) == \"Vector3\" then\n\t                        return Velocity.Unit\n\t                    elseif not Success and shared.VapeDeveloper and tick() > LastWarn then\n\t                        LastWarn = tick() + 5\n\t                        warn(`[catvape] silentaim solve failed: {Velocity}`)\n\t                    end\n\t\n\t                    return nil\n\t                end\n\t            }))\n\t            return\n\t        end\n\t        if Callback and not OldNamecall then\n\t            OldNamecall = hookmetamethod(game, \"__namecall\", newcclosure(function(...)\n\t                if SilentAim.Enabled and not checkcaller() and getnamecallmethod() == \"InvokeServer\" and tostring(...) == \"ProjectileFire\" then\n\t                    local self = ...\n\t                    local Arguments = table.pack(select(2, ...))\n\t                    local Success, NewVelocity = pcall(SolveSilent, Arguments)\n\t                    if Success and typeof(NewVelocity) == \"Vector3\" then\n\t                        Arguments[6] = NewVelocity\n\t                    elseif not Success and shared.VapeDeveloper and tick() > LastWarn then\n\t                        LastWarn = tick() + 5\n\t                        warn(`[catvape] silentaim solve failed: {NewVelocity}`)\n\t                    end\n\t                    return self.InvokeServer(self, table.unpack(Arguments, 1, Arguments.n))\n\t                end\n\t                return OldNamecall(...)\n\t            end))\n\t        end\n\t    end,\n\t    Tooltip = \"Redirects only the projectile values sent to the server, so enemies get hit while your shot flies exactly where you aimed on your own screen. Without native hooks (Solara, Xeno) the shot is turned at release instead and the trajectory preview is left untouched\"\n\t})\n\t\n\tTargets = SilentAim:CreateTargets({\n\t    Players = true,\n\t    Walls = true\n\t})\n\tTargetPart = SilentAim:CreateDropdown({\n\t    Name = \"Part\",\n\t    List = {\"RootPart\", \"Head\", \"Torso\", \"Left arm\", \"Right arm\", \"Left leg\", \"Right leg\", \"Random\", \"Dynamic\", \"Closest\"}\n\t})\n\tlocal Methods: {string} = {\"Damage\", \"Distance\"}\n\tfor _, v: string in SortList do\n\t    if not table.find(Methods, v) then\n\t        table.insert(Methods, v)\n\t    end\n\tend\n\tSort = SilentAim:CreateDropdown({\n\t    Name = \"Target Mode\",\n\t    List = Methods,\n\t    Default = \"Distance\"\n\t})\n\tPrediction = SilentAim:CreateSlider({\n\t    Name = \"Prediction\",\n\t    Min = 0.1,\n\t    Max = 2,\n\t    Default = 1,\n\t    Decimal = 10\n\t})\n\tFOV = SilentAim:CreateSlider({\n\t    Name = \"FOV\",\n\t    Min = 1,\n\t    Max = 1000,\n\t    Default = 1000\n\t})\n\tHitChance = SilentAim:CreateTwoSlider({\n\t    Name = \"Hit Chance\",\n\t    Min = 0,\n\t    Max = 100,\n\t    DefaultMin = 100,\n\t    DefaultMax = 100,\n\t    Tooltip = \"Chance in % for each shot to be redirected, rolled fresh between the two values on every shot. A missed roll leaves the shot where you aimed\"\n\t})\n\tHeadshotChance = SilentAim:CreateTwoSlider({\n\t    Name = \"Headshot Chance\",\n\t    Min = 0,\n\t    Max = 100,\n\t    DefaultMin = 0,\n\t    DefaultMax = 0,\n\t    Tooltip = \"Chance in % for each redirected shot to aim at the head instead of the Part setting, rolled fresh between the two values on every shot\"\n\t})\n\tOtherProjectiles = SilentAim:CreateToggle({\n\t    Name = \"Other Projectiles\",\n\t    Function = function(Callback: boolean)\n\t        if Blacklist then\n\t            Blacklist.Object.Visible = Callback\n\t        end\n\t    end,\n\t    Default = true\n\t})\n\tBlacklist = SilentAim:CreateTextList({\n\t    Name = \"Blacklist\",\n\t    Default = {\"gloop\", \"telepearl\"},\n\t    Darker = true,\n\t    Placeholder = \"projectile\"\n\t})\nend)\n\nRun(function()\n\tlocal SilentAura\n\tlocal Targets\n\tlocal Speed\n\tlocal Range\n\tlocal Angle\n\tlocal Mode\n\tlocal Area\n\tlocal LegitAura\n\tlocal Mouse\n\tlocal Dynamic\n\tlocal Limit\n\tlocal SilentAim\n\tlocal SwingTime\n\tlocal Perfect\n\tlocal AirHits\n\t\n\tlocal Show\n\tlocal TargetColor\n\tlocal AttackColor\n\t\n\tlocal RandomGenerator: Random = Random.new()\n\tlocal CharacterParts: {[Model]: {Instance}} = setmetatable({}, {__mode = \"k\"})\n\tlocal LastEffect, LastAttack, LastSwing, OldSwing, SwingHook = 0, 0, 0, nil, nil\n\tlocal TinkerSwing: number = 0\n\tlocal Session = nil\n\tlocal HitBudget, HitSpacing, GapFloor = 0.2, 0.296, 0.296\n\tlocal SafeSpacing, SafeFloor, HighSpacing, HighFloor = 0.296, 0.296, 0.2925, 0.2925\n\tlocal WeaponSpacing: {[number]: number} = {\n\t    [0.21] = 0.229,\n\t    [0.25] = 0.249,\n\t    [0.35] = 0.345,\n\t    [0.4] = 0.341,\n\t    [0.6] = 0.63\n\t}\n\tlocal WeaponMargin: number = 0.03\n\tlocal FuryScale: number = 1 - (bedwars.BlackMarketeerBalance.FURY_POTION_ATTACK_SPEED_MULTIPLIER - 1)\n\ttask.spawn(function()\n\t    HitBudget = 60 / bedwars.Handler:Get(\"SwordHit\"):GetRateLimit()\n\tend)\n\t\n\tlocal Box: BoxHandleAdornment = Instance.new(\"BoxHandleAdornment\")\n\tBox.Adornee = nil\n\tBox.AlwaysOnTop = true\n\tBox.Size = Vector3.new(3, 5, 3)\n\tBox.CFrame = CFrame.new(0, -0.5, 0)\n\tBox.ZIndex = 0\n\tif vape.ThreadFix then\n\t    setthreadidentity(8)\n\tend\n\tBox.Parent = vape.gui\n\t\n\tSilentAura = vape.Categories.Combat:CreateModule({\n\t    Name = \"SilentAura\",\n\t    Function = function(Callback: boolean)\n\t        if Callback then\n\t            local Current = {}\n\t            local Hook\n\t            Session = Current\n\t            local PreviousSwing = bedwars.SwordController.playSwordEffect\n\t            OldSwing = PreviousSwing\n\t            Hook = function(self, Meta, Charged, Config)\n\t                if not SilentAura.Enabled or SwingHook ~= Hook or (Config and Config.playAnimation == false) then\n\t                    return PreviousSwing(self, Meta, Charged, Config)\n\t                end\n\t                local EffectFloor: number = Perfect.Enabled and 0.11 or math.max(SwingTime.Value, 0.11)\n\t                if ((tick() - LastAttack) < 0.4 or (tick() - LastSwing) < 0.4) and (tick() - LastEffect) < EffectFloor then\n\t                    return\n\t                end\n\t                LastEffect = tick()\n\t                return PreviousSwing(self, Meta, Charged, Config)\n\t            end\n\t            SwingHook = Hook\n\t            bedwars.SwordController.playSwordEffect = SwingHook\n\t\n\t            local LastEnt, LastFound = nil, 0\n\t            local FoundAt: number = tick()\n\t            local LastAttacked: number = tick()\n\t\n\t            SilentAura:Clean(RunService.PostSimulation:Connect(function(DeltaTime: number)\n\t                if Entity.isAlive and LastEnt and LastEnt.RootPart and LastEnt.RootPart.Parent and tick() - LastFound < 0.5 then\n\t                    TargetInfo.Targets[LastEnt] = tick() + 0.5\n\t                    Entity.character.Humanoid.AutoRotate = not SilentAim.Enabled\n\t                    local T: number = math.min((tick() - FoundAt) / (1 / (Speed.Value * 0.5)), 1)\n\t                    local AimSpeed: number = Speed.Value * (T < 0.5 and 4 * T * T * T or 1 - math.pow(-2 * T + 2, 3) / 2)\n\t                    local AimPosition: Vector3 = LastEnt.RootPart.Position\n\t                    if Area.Value == \"Closest\" then\n\t                        if not CharacterParts[LastEnt.Character] then\n\t                            CharacterParts[LastEnt.Character] = LastEnt.Character:GetChildren()\n\t                        end\n\t\n\t                        local Center, ClosestDistance = UserInputService:GetMouseLocation(), 9e9\n\t                        for _, v: Instance in CharacterParts[LastEnt.Character] do\n\t                            if v and v.Parent and v:IsA(\"BasePart\") then\n\t                                local ScreenPosition, Visible = Camera:WorldToViewportPoint(v.Position)\n\t                                if Visible then\n\t                                    local PartDistance: number = (Center - Vector2.new(ScreenPosition.X, ScreenPosition.Y)).Magnitude\n\t                                    if PartDistance < ClosestDistance then\n\t                                        ClosestDistance, AimPosition = PartDistance, v.Position\n\t                                    end\n\t                                end\n\t                            end\n\t                        end\n\t                    end\n\t\n\t                    local AimCFrame: CFrame = Camera.CFrame:Lerp(CFrame.lookAt(Camera.CFrame.p, AimPosition + Vector3.new((RandomGenerator:NextNumber() - 0.5) * 15 * DeltaTime, (RandomGenerator:NextNumber() - 0.5) * 15 * DeltaTime, (RandomGenerator:NextNumber() - 0.5) * 15 * DeltaTime)), AimSpeed * DeltaTime)\n\t                    if SilentAim.Enabled then\n\t                        local Root: BasePart = Entity.character.RootPart\n\t                        local Direction: Vector3 = Vector3.new(LastEnt.RootPart.Position.X - Root.Position.X, 0, LastEnt.RootPart.Position.Z - Root.Position.Z)\n\t                        if Direction.Magnitude > 0 then\n\t                            Root.CFrame = Root.CFrame:Lerp(CFrame.lookAlong(Root.Position, Direction), math.clamp((AimSpeed + 2) * DeltaTime, 0, 1))\n\t                        end\n\t                    else\n\t                        Camera.CFrame = AimCFrame\n\t                    end\n\t                elseif Entity.isAlive then\n\t                    Entity.character.Humanoid.AutoRotate = true\n\t                end\n\t            end))\n\t\n\t            local SwingCooldown, LastHit = 0, 0\n\t            local Swung\n\t            ;(function()\n\t                repeat\n\t                    task.wait()\n\t                    if not SilentAura.Enabled or Session ~= Current then break end\n\t                    local Sword, ItemMeta = nil, nil\n\t                    local Blocked: boolean = not Entity.isAlive\n\t                    Blocked = Blocked or (Mouse.Enabled and not UserInputService:IsMouseButtonPressed(0) and (bedwars.SwordController.lastSwing == Swung or (tick() - bedwars.SwordController.lastSwing) > 0.3))\n\t                    Blocked = Blocked or (LegitAura.Enabled and (tick() - bedwars.SwordController.lastSwing) > 0.3)\n\t                    Blocked = Blocked or ((LocalPlayer.Character:GetAttribute(\"StunnedUntilTime\") or 0) - workspace:GetServerTimeNow() > 0)\n\t                    Blocked = Blocked or bedwars.AppController:isLayerOpen(bedwars.UILayers.MAIN)\n\t                    if not Blocked then\n\t                        Sword = Limit.Enabled and store.hand or store.tools.sword\n\t                        if not Sword or not Sword.tool then\n\t                            Sword = nil\n\t                        elseif Limit.Enabled and (store.hand.toolType ~= \"sword\" or bedwars.DaoController.chargingMaid) then\n\t                            Sword = nil\n\t                        else\n\t                            ItemMeta = bedwars.ItemMeta[Sword.tool.Name]\n\t                        end\n\t                    end\n\t\n\t                    if Sword then\n\t                        local LocalPosition: Vector3 = Entity.character.RootPart.Position\n\t                        local Ent = Entity.EntityPosition({\n\t                            Origin = LocalPosition,\n\t                            Range = bedwars.CombatConstant.RAYCAST_SWORD_CHARACTER_DISTANCE + Range.Value,\n\t                            Wallcheck = Targets.Walls.Enabled or nil,\n\t                            Part = \"RootPart\",\n\t                            Players = Targets.Players.Enabled,\n\t                            NPCs = Targets.NPCs.Enabled,\n\t                            Priority = Targets.Priority.Value,\n\t                            Sort = sortmethods[Mode.Value or \"Distance\"]\n\t                        })\n\t                        local ColorSlider = tick() - LastAttacked < 0.1 and AttackColor or TargetColor\n\t                        Box.Adornee = Show.Enabled and Ent and Ent.RootPart or nil\n\t                        Box.Transparency = 1 - ColorSlider.Opacity\n\t                        Box.Color3 = Color3.fromHSV(ColorSlider.Hue, ColorSlider.Sat, ColorSlider.Value)\n\t                        if Ent then\n\t                            if not store.hand or store.hand.tool ~= Sword.tool then\n\t                                local Hotbar = getHotbar(Sword.tool)\n\t                                if Hotbar then\n\t                                    hotbarSwitch(Hotbar)\n\t                                else\n\t                                    continue\n\t                                end\n\t                            end\n\t                            if store.hand.tool ~= Sword.tool then\n\t                                continue\n\t                            end\n\t\n\t                            local LocalFacing: Vector3 = (UserInputService.KeyboardEnabled and Camera or Entity.character.RootPart).CFrame.LookVector * Vector3.new(1, 0, 1)\n\t                            local Delta, Flat = (Ent.RootPart.Position - LocalPosition), ((Ent.RootPart.Position - LocalPosition) * Vector3.new(1, 0, 1))\n\t                            local FacingDot: number = Flat.Magnitude > 0 and LocalFacing.Magnitude > 0 and (LocalFacing / LocalFacing.Magnitude):Dot(Flat / Flat.Magnitude) or 0\n\t                            if FacingDot < math.cos(math.rad(Angle.Value) / 2) then\n\t                                continue\n\t                            end\n\t\n\t                            if not LegitAura.Enabled and (tick() - bedwars.SwordController.lastSwing) >= (Perfect.Enabled and (ItemMeta.sword.attackSpeed or 0.11) or math.max(SwingTime.Value, 0.11)) then\n\t                                Swung = tick()\n\t                                LastSwing = Swung\n\t                                local Mount: Model? = getTinkerMount()\n\t                                if Mount then\n\t                                    if tick() >= TinkerSwing + 0.35 then\n\t                                        TinkerSwing = tick()\n\t                                        bedwars.AudioManager:playAudio(bedwars.SoundList.DRILL_ATTACK_1)\n\t                                        bedwars.MountAnimationController:playAnimationInMount(Mount, bedwars.AnimationType.TINKER_ATTACK, 1.85)\n\t                                    end\n\t                                else\n\t                                    bedwars.SwordController:playSwordEffect(ItemMeta, false, {itemSkin = Sword.itemSkin})\n\t                                end\n\t                                bedwars.SwordController.lastSwing = Swung\n\t                            end\n\t\n\t                            if LastEnt ~= Ent or FacingDot < -0.5 then\n\t                                FoundAt = tick()\n\t                            end\n\t                            LastEnt, LastFound = Ent, tick()\n\t\n\t                            if Delta.Magnitude > bedwars.CombatConstant.RAYCAST_SWORD_CHARACTER_DISTANCE then\n\t                                continue\n\t                            end\n\t                            LastAttacked = tick()\n\t\n\t                            local SwordSpeed: number = ItemMeta and ItemMeta.sword and ItemMeta.sword.attackSpeed or 0.3\n\t                            local Fury: number = LocalPlayer.Character:GetAttribute(\"StatusEffect_fury_potion\") and FuryScale or 1\n\t                            local Stock: boolean = SwordSpeed == 0.3\n\t                            local Spacing: number = (Stock and HitSpacing or WeaponSpacing[SwordSpeed] or (SwordSpeed + WeaponMargin)) * Fury\n\t                            local AttackSpeed: number = (SwordSpeed * Fury) - ((0.017999999225139618 / 10) + 0.013412)\n\t                            local HitFloor: number = Stock and GapFloor * Fury or Spacing\n\t                            local HitDelay: number = math.max(HitBudget, Spacing, (bedwars.SwordController.lastAttack + AttackSpeed) - workspace:GetServerTimeNow())\n\t                            if Dynamic.Enabled then\n\t                                local ReachDistance: number = math.max(getReach(Sword.tool), 0.001)\n\t                                local Ratio: number = math.min((Entity.character.RootPart.Position - Ent.RootPart.Position).Magnitude, ReachDistance) / ReachDistance\n\t                                HitDelay = math.clamp(HitDelay * Ratio, HitFloor, HitDelay)\n\t                            end\n\t\n\t                            if tick() >= SwingCooldown + HitDelay and (tick() - LastHit) >= HitFloor then\n\t                                local Airborne: boolean = (Ent.Humanoid and Ent.Humanoid.FloorMaterial == Enum.Material.Air) or math.abs(Ent.RootPart.AssemblyLinearVelocity.Y) > 0.01\n\t                                local Direction: Vector3 = CFrame.lookAt(LocalPosition, Ent.RootPart.Position).LookVector\n\t                                local SelfPosition: Vector3 = LocalPosition + Direction * math.max(Delta.Magnitude - (getReach(Sword.tool) - 0.001), 0)\n\t                                bedwars.SwordController.lastAttack = workspace:GetServerTimeNow()\n\t                                LastAttack = tick()\n\t                                SwingCooldown = math.max(SwingCooldown + HitDelay, tick())\n\t                                LastHit = tick()\n\t\n\t                                if (not Airborne) or RandomGenerator:NextNumber(0, 100) <= AirHits:GetRandomValue() then\n\t                                    bedwars.Handler:Get(\"SwordHit\"):Fire(\"SendToServer\", {\n\t                                        weapon = Sword.tool,\n\t                                        chargedAttack = {chargeRatio = 0},\n\t                                        entityInstance = Ent.Character,\n\t                                        validate = {\n\t                                            raycast = {\n\t                                                cameraPosition = {value = Camera.CFrame.Position},\n\t                                                cursorDirection = {value = Direction}\n\t                                            },\n\t                                            targetPosition = {value = Ent.Character:GetPivot().Position},\n\t                                            selfPosition = {value = SelfPosition}\n\t                                        }\n\t                                    })\n\t                                end\n\t                            end\n\t                        else\n\t                            LastFound = 0\n\t                        end\n\t                    else\n\t                        Box.Adornee = nil\n\t                        LastFound = 0\n\t                    end\n\t                until not SilentAura.Enabled or Session ~= Current\n\t            end)()\n\t        else\n\t            if bedwars.SwordController.playSwordEffect == SwingHook then\n\t                bedwars.SwordController.playSwordEffect = OldSwing\n\t            end\n\t            OldSwing = nil\n\t            SwingHook = nil\n\t            LastEffect, LastAttack, LastSwing = 0, 0, 0\n\t            if Entity.isAlive then\n\t                Entity.character.Humanoid.AutoRotate = true\n\t            end\n\t            Box.Adornee = nil\n\t        end\n\t    end,\n\t    Tooltip = \"Automatically aims and attacks nearby target\"\n\t})\n\t\n\tTargets = SilentAura:CreateTargets({\n\t    Players = true,\n\t    NPCs = true\n\t})\n\tSpeed = SilentAura:CreateSlider({\n\t    Name = \"Aim speed\",\n\t    Min = 1,\n\t    Max = 10,\n\t    Default = 6,\n\t    Decimal = 5,\n\t    Tooltip = \"How fast the Aura is going to aim\"\n\t})\n\tSwingTime = SilentAura:CreateSlider({\n\t    Name = \"Swing time\",\n\t    Darker = true,\n\t    Visible = false,\n\t    Min = 0,\n\t    Max = 0.5,\n\t    Default = 0.42,\n\t    Decimal = 100\n\t})\n\tRange = SilentAura:CreateSlider({\n\t    Name = \"Extra swing distance\",\n\t    Tooltip = \"Where you will start swinging, not attacking\",\n\t    Min = 0,\n\t    Max = 6,\n\t    Suffix = function(Val: number)\n\t        return Val <= 1 and \"stud\" or \"studs\"\n\t    end,\n\t    Decimal = 5,\n\t    Default = 3\n\t})\n\tAngle = SilentAura:CreateSlider({\n\t    Name = \"Max angle\",\n\t    Min = 1,\n\t    Max = 360,\n\t    Default = 180\n\t})\n\tAirHits = SilentAura:CreateTwoSlider({\n\t    Name = \"Air hit chance\",\n\t    Min = 0,\n\t    Max = 100,\n\t    DefaultMin = 100,\n\t    DefaultMax = 100,\n\t    Tooltip = \"Chance to land a hit while the target is off the ground, rolled fresh between the two values on every swing\"\n\t})\n\tlocal Methods: {string} = {\"Health\", \"Damage\", \"Distance\"}\n\tfor _, v: string in sortlist do\n\t    if not table.find(Methods, v) then\n\t        table.insert(Methods, v)\n\t    end\n\tend\n\tMode = SilentAura:CreateDropdown({\n\t    Name = \"Target mode\",\n\t    Default = \"Health\",\n\t    List = Methods,\n\t    Tooltip = \"How Aura should prioritize targets\"\n\t})\n\tArea = SilentAura:CreateDropdown({\n\t    Name = \"Target area\",\n\t    List = {\"Center\", \"Closest\"},\n\t    Default = \"Center\",\n\t    Visible = false,\n\t    Tooltip = \"Where the Aura will aim towards\"\n\t})\n\tPerfect = SilentAura:CreateToggle({\n\t    Name = \"Perfect Swing\",\n\t    Function = function(Callback: boolean)\n\t        SwingTime.Object.Visible = not Callback\n\t    end,\n\t    Default = true,\n\t    Tooltip = \"Follows sword item's swing time\"\n\t})\n\tMouse = SilentAura:CreateToggle({Name = \"Require mouse down\"})\n\tDynamic = SilentAura:CreateToggle({\n\t    Name = \"Dynamic hits\",\n\t    Function = function(Callback: boolean)\n\t        HitSpacing = Callback and HighSpacing or SafeSpacing\n\t        GapFloor = Callback and HighFloor or SafeFloor\n\t    end,\n\t    Default = true,\n\t    Tooltip = \"Goes for 35 hits every 10 seconds instead of a safe 34, at the cost of ghosting a hit now and then\"\n\t})\n\tLegitAura = SilentAura:CreateToggle({Name = \"Swing only\"})\n\tSilentAim = SilentAura:CreateToggle({\n\t    Name = \"Silent Aim\",\n\t    Function = function(Callback: boolean)\n\t        Area.Object.Visible = not Callback\n\t    end,\n\t    Default = true,\n\t    Tooltip = \"Uses catvape's aiming technology to silently aim while looking legit\"\n\t})\n\tShow = SilentAura:CreateToggle({\n\t    Name = \"Show target\",\n\t    Function = function(Callback: boolean)\n\t        if TargetColor then\n\t            TargetColor.Object.Visible = Callback\n\t        end\n\t        if AttackColor then\n\t            AttackColor.Object.Visible = Callback\n\t        end\n\t    end,\n\t    Default = true\n\t})\n\tTargetColor = SilentAura:CreateColorSlider({\n\t    Name = \"Target color\",\n\t    Darker = true,\n\t    DefaultOpacity = 0.5,\n\t    DefaultHue = 1\n\t})\n\tAttackColor = SilentAura:CreateColorSlider({\n\t    Name = \"Attack color\",\n\t    Darker = true,\n\t    DefaultOpacity = 0.5\n\t})\n\tLimit = SilentAura:CreateToggle({Name = \"Limit to items\"})\nend)\n\nRun(function()\n\tlocal Sprint\n\tlocal Old: (...any) -> ...any\n\t\n\tSprint = vape.Categories.Combat:CreateModule({\n\t    Name = \"Sprint\",\n\t    Function = function(Callback: boolean)\n\t        if Callback then\n\t            Old = bedwars.SprintController.stopSprinting\n\t            bedwars.SprintController.stopSprinting = function(...)\n\t                local Call = Old(...)\n\t                bedwars.SprintController:startSprinting()\n\t                return Call\n\t            end\n\t\n\t            Sprint:Clean(Entity.Events.LocalAdded:Connect(function()\n\t                task.delay(0.1, function()\n\t                    bedwars.SprintController:stopSprinting()\n\t                end)\n\t            end))\n\t\n\t            bedwars.SprintController:stopSprinting()\n\t        else\n\t            bedwars.SprintController.stopSprinting = Old\n\t            bedwars.SprintController:stopSprinting()\n\t        end\n\t    end,\n\t    Tooltip = \"Sets your sprinting to true.\"\n\t})\nend)\n\nRun(function()\n\tlocal TriggerBot\n\tlocal Targets\n\tlocal Range\n\tlocal Angle\n\tlocal CPS\n\tlocal Limit\n\tlocal Region\n\tlocal Continue\n\tlocal Duration\n\tlocal Mouse\n\tlocal AFKCheck\n\tlocal GUI\n\tlocal BoxColor\n\tlocal BoxTween\n\tlocal BoxSpeed\n\t\n\tlocal Box: BoxHandleAdornment?\n\tlocal SizeTween: Tween?\n\tlocal SizeGoal: Vector3?\n\tlocal LastTarget, LastSwing, KillUntil = nil, 0, 0\n\tlocal RayParams: RaycastParams = RaycastParams.new()\n\t\n\tlocal function GetTarget(LocalPosition: Vector3, AttackRange: number, ConeAngle: number)\n\t    if ConeAngle > 0 then\n\t        local Origin, Facing = Camera.CFrame.Position, Camera.CFrame.LookVector\n\t        local CosineLimit: number = math.cos(math.rad(math.min(ConeAngle, 360)) / 2)\n\t        for _, v: any in Entity.AllPosition({\n\t            Part = \"RootPart\",\n\t            Range = AttackRange,\n\t            Origin = LocalPosition,\n\t            Players = Targets.Players.Enabled,\n\t            NPCs = Targets.NPCs.Enabled,\n\t            Priority = Targets.Priority.Value,\n\t            Wallcheck = Targets.Walls.Enabled or nil,\n\t            Sort = SortMethods.Distance\n\t        }) do\n\t            local Delta: Vector3 = v.RootPart.Position - Origin\n\t            if Delta.Magnitude < 0.001 or Facing:Dot(Delta.Unit) >= CosineLimit then\n\t                return v\n\t            end\n\t        end\n\t\n\t        return nil\n\t    end\n\t\n\t    local MouseRay: Ray = LocalPlayer:GetMouse().UnitRay\n\t    RayParams.FilterDescendantsInstances = {LocalPlayer.Character}\n\t    local RayResult: RaycastResult? = bedwars.QueryUtil:raycast(MouseRay.Origin, MouseRay.Direction * 200, RayParams)\n\t    if not RayResult then\n\t        return nil\n\t    end\n\t\n\t    for _, v: any in Entity.List do\n\t        if v.Targetable and RayResult.Instance:IsDescendantOf(v.Character) and (LocalPosition - v.RootPart.Position).Magnitude <= AttackRange then\n\t            if Targets.Players.Enabled and v.Player or Targets.NPCs.Enabled and not v.Player then\n\t                if not Targets.Walls.Enabled or not Entity.Wallcheck(LocalPosition, v.RootPart.Position, true, v) then\n\t                    return v\n\t                end\n\t            end\n\t        end\n\t    end\n\t\n\t    return nil\n\tend\n\t\n\tTriggerBot = vape.Categories.Combat:CreateModule({\n\t    Name = \"TriggerBot\",\n\t    Function = function(Callback: boolean)\n\t        if Callback then\n\t            LastTarget, LastSwing, KillUntil = nil, 0, 0\n\t\n\t            repeat\n\t                local Ent, DoAttack\n\t                if Entity.isAlive and (not GUI.Enabled or not bedwars.AppController:isLayerOpen(bedwars.UILayers.MAIN)) and (not Mouse.Enabled or UserInputService:IsMouseButtonPressed(0)) and (not AFKCheck.Enabled or not IsAfk()) then\n\t                    if (not Limit.Enabled or Store.hand.toolType == \"sword\") and bedwars.DaoController.chargingMaid == nil then\n\t                        local AttackRange: number = math.clamp(Range.Value, 0, GetReach(Store.hand.tool) * 2)\n\t                        Ent = GetTarget(Entity.character.RootPart.Position, AttackRange, Angle.Value)\n\t                        DoAttack = Ent ~= nil\n\t\n\t                        if LastTarget and LastTarget.Health <= 0 then\n\t                            if tick() - LastSwing <= 1 then\n\t                                KillUntil = tick() + Duration.Value\n\t                            end\n\t                            LastTarget = nil\n\t                        end\n\t\n\t                        if not DoAttack and Region.Enabled then\n\t                            DoAttack = bedwars.SwordController:getTargetInRegion(AttackRange, 0) ~= nil\n\t                        end\n\t\n\t                        if not DoAttack and Continue.Enabled and tick() < KillUntil then\n\t                            DoAttack = true\n\t                        end\n\t\n\t                        if Ent then\n\t                            LastTarget = Ent\n\t                            TargetInfo.Targets[Ent] = tick() + 1\n\t                        end\n\t\n\t                        if DoAttack and CanSwing() then\n\t                            if Ent then\n\t                                LastSwing = tick()\n\t                            end\n\t                            bedwars.SwordController:swingSwordAtMouse()\n\t                        end\n\t                    end\n\t                end\n\t\n\t                if Box then\n\t                    Box.Adornee = Ent and Ent.RootPart or nil\n\t                    local Goal: Vector3 = Ent and Vector3.new(4, 6, 4) or Vector3.zero\n\t                    if Goal ~= SizeGoal or not SizeTween or SizeTween.PlaybackState ~= Enum.PlaybackState.Completed then\n\t                        SizeTween = TweenService:Create(Box, TweenInfo.new(BoxSpeed.Value, Enum.EasingStyle[BoxTween.Value]), {\n\t                            Size = Goal\n\t                        })\n\t                        SizeTween:Play()\n\t                        SizeGoal = Goal\n\t                    end\n\t\n\t                    if Ent then\n\t                        Box.Color3 = Color3.fromHSV(BoxColor.Hue, BoxColor.Sat, BoxColor.Value)\n\t                        Box.Transparency = 1 - BoxColor.Opacity\n\t                    end\n\t                end\n\t\n\t                task.wait(DoAttack and 1 / CPS:GetRandomValue() or 0.016)\n\t            until not TriggerBot.Enabled\n\t        end\n\t    end,\n\t    Tooltip = \"Automatically swings when hovering over a entity\"\n\t})\n\t\n\tTargets = TriggerBot:CreateTargets({\n\t    Players = true,\n\t    NPCs = true,\n\t    Walls = true\n\t})\n\tRange = TriggerBot:CreateSlider({\n\t    Name = \"Range\",\n\t    Min = 1,\n\t    Max = 18,\n\t    Default = 18,\n\t    Decimal = 10,\n\t    Suffix = function(Val: number)\n\t        return Val <= 1 and \"stud\" or \"studs\"\n\t    end,\n\t    Tooltip = \"Clamped by the reach of whatever you are holding\"\n\t})\n\tAngle = TriggerBot:CreateSlider({\n\t    Name = \"Angle\",\n\t    Min = 0,\n\t    Max = 360,\n\t    Default = 0,\n\t    Suffix = \"degrees\",\n\t    Tooltip = \"Swings at anything within this cone of where you are looking instead of only the one under your cursor, 360 reaches behind you\"\n\t})\n\tCPS = TriggerBot:CreateTwoSlider({\n\t    Name = \"CPS\",\n\t    Min = 1,\n\t    Max = 9,\n\t    DefaultMin = 7,\n\t    DefaultMax = 7\n\t})\n\tLimit = TriggerBot:CreateToggle({\n\t    Name = \"Limit to items\",\n\t    Default = true,\n\t    Tooltip = \"Only swings when the sword is held\"\n\t})\n\tRegion = TriggerBot:CreateToggle({\n\t    Name = \"Region check\",\n\t    Default = true,\n\t    Tooltip = \"Also swings when the game reports anything inside your sword region\"\n\t})\n\tContinue = TriggerBot:CreateToggle({\n\t    Name = \"Continue after kill\",\n\t    Function = function(Callback: boolean)\n\t        Duration.Object.Visible = Callback\n\t    end,\n\t    Tooltip = \"Keeps swinging for a moment after the entity you were on dies, so a second one walking in gets hit right away\"\n\t})\n\tDuration = TriggerBot:CreateSlider({\n\t    Name = \"Continue time\",\n\t    Min = 0.05,\n\t    Max = 2,\n\t    Default = 0.4,\n\t    Decimal = 100,\n\t    Darker = true,\n\t    Visible = false,\n\t    Suffix = \"seconds\"\n\t})\n\tMouse = TriggerBot:CreateToggle({Name = \"Require mouse down\"})\n\tAFKCheck = TriggerBot:CreateToggle({\n\t    Name = \"AFK check\",\n\t    Tooltip = \"Stops attacking once you have not touched your mouse or keyboard for 30 seconds\"\n\t})\n\tGUI = TriggerBot:CreateToggle({Name = \"GUI check\"})\n\tTriggerBot:CreateToggle({\n\t    Name = \"Show target\",\n\t    Function = function(Callback: boolean)\n\t        BoxColor.Object.Visible = Callback\n\t        BoxTween.Object.Visible = Callback\n\t        BoxSpeed.Object.Visible = Callback\n\t        if Callback then\n\t            Box = Instance.new(\"BoxHandleAdornment\")\n\t            Box.Adornee = nil\n\t            Box.AlwaysOnTop = true\n\t            Box.Size = Vector3.zero\n\t            Box.CFrame = CFrame.new(0, -0.5, 0)\n\t            Box.ZIndex = 0\n\t            if vape.ThreadFix then\n\t                setthreadidentity(8)\n\t            end\n\t            Box.Parent = vape.gui\n\t            SizeTween = nil\n\t        elseif Box then\n\t            Box:Destroy()\n\t            Box = nil\n\t        end\n\t    end\n\t})\n\tlocal AnimationList: {string} = {\"Bounce\"}\n\tfor _, v: EnumItem in Enum.EasingStyle:GetEnumItems() do\n\t    if not table.find(AnimationList, v.Name) then\n\t        table.insert(AnimationList, v.Name)\n\t    end\n\tend\n\tBoxTween = TriggerBot:CreateDropdown({\n\t    Name = \"Box Animation\",\n\t    List = AnimationList,\n\t    Darker = true,\n\t    Visible = false\n\t})\n\tBoxSpeed = TriggerBot:CreateSlider({\n\t    Name = \"Animation Speed\",\n\t    Min = 0,\n\t    Max = 10,\n\t    Default = 0.9,\n\t    Decimal = 30,\n\t    Darker = true,\n\t    Visible = false\n\t})\n\tBoxColor = TriggerBot:CreateColorSlider({\n\t    Name = \"Target Color\",\n\t    Darker = true,\n\t    DefaultHue = 0.6,\n\t    DefaultOpacity = 0.5,\n\t    Visible = false\n\t})\nend)\n\nRun(function()\n\tlocal Velocity\n\tlocal Horizontal\n\tlocal Vertical\n\tlocal Chance\n\tlocal TargetCheck\n\tlocal AFKCheck\n\tlocal AFKTime\n\tlocal RandomGenerator, Old, LastInput = Random.new()\n\tlocal KnockbackModule: Instance = ReplicatedStorage.TS.damage[\"knockback-util\"]\n\tlocal Defaults\n\t\n\tVelocity = vape.Categories.Combat:CreateModule({\n\t    Name = \"Velocity\",\n\t    Function = function(Callback: boolean)\n\t        if not canDebug then\n\t            if Callback then\n\t                Defaults = Defaults or {\n\t                    horizontal = KnockbackModule:GetAttribute(\"ConstantManager_kbDirectionStrength\"),\n\t                    vertical = KnockbackModule:GetAttribute(\"ConstantManager_kbUpwardStrength\")\n\t                }\n\t                KnockbackModule:SetAttribute(\"ConstantManager_kbDirectionStrength\", Defaults.horizontal * (Horizontal.Value / 100))\n\t                KnockbackModule:SetAttribute(\"ConstantManager_kbUpwardStrength\", Defaults.vertical * (Vertical.Value / 100))\n\t            elseif Defaults then\n\t                KnockbackModule:SetAttribute(\"ConstantManager_kbDirectionStrength\", Defaults.horizontal)\n\t                KnockbackModule:SetAttribute(\"ConstantManager_kbUpwardStrength\", Defaults.vertical)\n\t            end\n\t            return\n\t        end\n\t\n\t        if Callback then\n\t            LastInput = tick()\n\t            Velocity:Clean(UserInputService.InputBegan:Connect(function()\n\t                LastInput = tick()\n\t            end))\n\t            Old = bedwars.KnockbackUtil.applyKnockback\n\t            bedwars.KnockbackUtil.applyKnockback = function(Root, Mass, Direction, Knockback, ...)\n\t                if RandomGenerator:NextNumber(0, 100) > Chance:GetRandomValue() or AFKCheck.Enabled and (tick() - LastInput) >= AFKTime.Value and Entity.isAlive and Entity.character.Humanoid.MoveDirection.Magnitude == 0 then\n\t                    return Old(Root, Mass, Direction, Knockback, ...)\n\t                end\n\t                local Check = (not TargetCheck.Enabled) or Entity.EntityPosition({\n\t                    Range = 50,\n\t                    Part = \"RootPart\",\n\t                    Players = true\n\t                })\n\t\n\t                if Check then\n\t                    Knockback = Knockback or {}\n\t                    if Horizontal.Value == 0 and Vertical.Value == 0 then\n\t                        return\n\t                    end\n\t                    Knockback.horizontal = (Knockback.horizontal or 1) * (Horizontal.Value / 100)\n\t                    Knockback.vertical = (Knockback.vertical or 1) * (Vertical.Value / 100)\n\t                end\n\t\n\t                return Old(Root, Mass, Direction, Knockback, ...)\n\t            end\n\t        else\n\t            bedwars.KnockbackUtil.applyKnockback = Old\n\t        end\n\t    end,\n\t    Tooltip = \"Reduces knockback taken\"\n\t})\n\t\n\tHorizontal = Velocity:CreateSlider({\n\t    Name = \"Horizontal\",\n\t    Min = 0,\n\t    Max = 100,\n\t    Suffix = \"%\",\n\t    Function = function()\n\t        if not canDebug and Velocity.Enabled and Defaults then\n\t            KnockbackModule:SetAttribute(\"ConstantManager_kbDirectionStrength\", Defaults.horizontal * (Horizontal.Value / 100))\n\t            KnockbackModule:SetAttribute(\"ConstantManager_kbUpwardStrength\", Defaults.vertical * (Vertical.Value / 100))\n\t        end\n\t    end,\n\t    Default = 0\n\t})\n\tVertical = Velocity:CreateSlider({\n\t    Name = \"Vertical\",\n\t    Min = 0,\n\t    Max = 100,\n\t    Suffix = \"%\",\n\t    Function = function()\n\t        if not canDebug and Velocity.Enabled and Defaults then\n\t            KnockbackModule:SetAttribute(\"ConstantManager_kbDirectionStrength\", Defaults.horizontal * (Horizontal.Value / 100))\n\t            KnockbackModule:SetAttribute(\"ConstantManager_kbUpwardStrength\", Defaults.vertical * (Vertical.Value / 100))\n\t        end\n\t    end,\n\t    Default = 0\n\t})\n\tChance = Velocity:CreateTwoSlider({\n\t    Name = \"Chance\",\n\t    Min = 0,\n\t    Max = 100,\n\t    DefaultMin = 100,\n\t    DefaultMax = 100,\n\t    Tooltip = \"Chance in % for each knockback to be reduced, rolled fresh between the two values on every hit\"\n\t})\n\tTargetCheck = Velocity:CreateToggle({Name = \"Only when targeting\"})\n\tAFKCheck = Velocity:CreateToggle({\n\t    Name = \"AFK check\",\n\t    Function = function(Callback: boolean)\n\t        AFKTime.Object.Visible = Callback\n\t    end,\n\t    Tooltip = \"Takes full knockback while you stand still and have not pressed anything for the AFK time\"\n\t})\n\tAFKTime = Velocity:CreateSlider({\n\t    Name = \"AFK time\",\n\t    Min = 1,\n\t    Max = 60,\n\t    Default = 10,\n\t    Darker = true,\n\t    Visible = false,\n\t    Suffix = function(Val: number)\n\t        return Val == 1 and \"second\" or \"seconds\"\n\t    end\n\t})\nend)\n\nRun(function()\n\tlocal AntiDeath\n\tlocal StopThreshold\n\tlocal Threshold\n\tlocal Notify\n\tlocal Delay\n\tlocal Mode\n\t\n\tlocal OldRoot, OldCharacter, Clone, HipHeight\n\tlocal Paused, Activated = 0, 0\n\t\n\tlocal function DestroyClone()\n\t    if not OldRoot then\n\t        return false\n\t    end\n\t\n\t    local Restored: boolean = false\n\t    if OldRoot.Parent and OldCharacter and OldCharacter.Parent then\n\t        OldCharacter.Parent = ReplicatedStorage\n\t        OldRoot.Parent = OldCharacter\n\t        if Clone then\n\t            Clone:Destroy()\n\t        end\n\t        OldCharacter.PrimaryPart = OldRoot\n\t        OldCharacter.Parent = workspace\n\t        OldRoot.CanCollide = true\n\t        local Humanoid: Humanoid? = OldCharacter:FindFirstChildOfClass(\"Humanoid\")\n\t        if Humanoid then\n\t            Humanoid.HipHeight = HipHeight\n\t        end\n\t        Restored = true\n\t    elseif Clone then\n\t        Clone:Destroy()\n\t    end\n\t\n\t    OldRoot, OldCharacter, Clone = nil, nil, nil\n\t    Store.rootpart = nil\n\t    return Restored\n\tend\n\t\n\tAntiDeath = vape.Categories.Blatant:CreateModule({\n\t    Name = \"AntiDeath\",\n\t    Function = function(Callback: boolean)\n\t        if Callback then\n\t            local FloatTime: number = tick()\n\t            AntiDeath:Clean(RunService.PreSimulation:Connect(function()\n\t                if not OldRoot or not OldRoot.Parent or not Entity.isAlive then\n\t                    return\n\t                end\n\t\n\t                if (tick() - Entity.character.AirTime) > 1.7 then\n\t                    FloatTime = tick() + 0.2\n\t                end\n\t                OldRoot.AssemblyLinearVelocity = Vector3.new(0, 1, 0)\n\t                OldRoot.CFrame = Clone.CFrame - (tick() > FloatTime and Vector3.new(0, 200, 0) or Vector3.zero)\n\t            end))\n\t\n\t            repeat\n\t                if tick() > Paused and Entity.isAlive and (Entity.character.Health / Entity.character.MaxHealth) <= (Threshold.Value / 100) and (tick() - Activated) >= Delay.Value then\n\t                    Activated = tick()\n\t                    if Notify.Enabled then\n\t                        SendNotification(\"AntiDeath\", `Health below {Threshold.Value}%`, 12, \"warning\")\n\t                    end\n\t\n\t                    if Mode.Value == \"Teleport\" then\n\t                        LocalPlayer.Character.PrimaryPart.CFrame += Vector3.new(0, 100, 0)\n\t                        Paused = tick() + 5\n\t                    elseif Mode.Value == \"Invincibility\" and not Store.rootpart and Entity.isAlive and Entity.character.Humanoid.Health > 0 and not (OldRoot and OldRoot.Parent) and LocalPlayer.Character.Parent then\n\t                        OldCharacter = LocalPlayer.Character\n\t                        OldRoot = Entity.character.HumanoidRootPart\n\t                        HipHeight = Entity.character.Humanoid.HipHeight\n\t                        OldCharacter.Parent = ReplicatedStorage\n\t                        Clone = OldRoot:Clone()\n\t                        Clone.Parent = OldCharacter\n\t                        OldRoot.Transparency = 1\n\t                        OldRoot.Parent = workspace\n\t                        Store.rootpart = OldRoot\n\t                        OldCharacter.PrimaryPart = Clone\n\t                        OldCharacter.Parent = workspace\n\t                        bedwars.QueryUtil:setQueryIgnored(Clone, true)\n\t                        bedwars.QueryUtil:setQueryIgnored(OldRoot, true)\n\t                        Paused = tick() + 5\n\t                        task.delay(0, function()\n\t                            repeat\n\t                                task.wait()\n\t                            until not AntiDeath.Enabled or not Entity.isAlive or (Entity.character.Health / Entity.character.MaxHealth) >= (StopThreshold.Value / 100)\n\t                            local OldCFrame: CFrame? = Clone and Clone.CFrame or nil\n\t                            if DestroyClone() and OldCFrame then\n\t                                Entity.character.RootPart.CFrame = OldCFrame\n\t                            end\n\t\n\t                            Paused = tick() + 5\n\t\n\t                            if AntiDeath.Enabled and Notify.Enabled then\n\t                                SendNotification(\"AntiDeath\", \"You are visible again\", 12, \"info\")\n\t                            end\n\t                        end)\n\t                    end\n\t                end\n\t                task.wait()\n\t            until not AntiDeath.Enabled\n\t        else\n\t            DestroyClone()\n\t        end\n\t    end,\n\t    Tooltip = \"Uses selected mode when on a threshold\"\n\t})\n\t\n\tMode = AntiDeath:CreateDropdown({\n\t    Name = \"Mode\",\n\t    List = {\"Invincibility\", \"Teleport\"},\n\t    Default = \"Invincibility\",\n\t    Tooltip = \"Teleport - Teleports you high up\\nInvincibility - Makes you unhittable\"\n\t})\n\tStopThreshold = AntiDeath:CreateSlider({\n\t    Name = \"Stop Threshold\",\n\t    Min = 1,\n\t    Max = 100,\n\t    Default = 30,\n\t    Suffix = function()\n\t        return \"%\"\n\t    end,\n\t    Tooltip = \"Health percentage to untrigger at\"\n\t})\n\tThreshold = AntiDeath:CreateSlider({\n\t    Name = \"Threshold\",\n\t    Min = 1,\n\t    Max = 100,\n\t    Default = 30,\n\t    Suffix = function()\n\t        return \"%\"\n\t    end,\n\t    Tooltip = \"Health percentage to trigger at\"\n\t})\n\tDelay = AntiDeath:CreateSlider({\n\t    Name = \"Delay\",\n\t    Min = 1,\n\t    Max = 20,\n\t    Default = 5,\n\t    Suffix = function(Val: number)\n\t        return Val <= 1 and \"sec\" or \"secs\"\n\t    end,\n\t    Tooltip = \"Delay between triggers\"\n\t})\n\tNotify = AntiDeath:CreateToggle({\n\t    Name = \"Notify on trigger\",\n\t    Default = true\n\t})\nend)\n\nlocal AntiFallDirection\nRun(function()\n    local AntiFall\n    local Mode\n    local Material\n    local Color\n    local Connection: RBXScriptConnection?\n    local RayCheck: RaycastParams = RaycastParams.new()\n    RayCheck.RespectCanCollide = true\n\n    AntiFall = vape.Categories.Blatant:CreateModule({\n        Name = \"AntiFall\",\n        Function = function(Callback: boolean)\n            if Callback then\n                repeat\n                    task.wait()\n                until Store.matchState ~= 0 or not AntiFall.Enabled\n                if not AntiFall.Enabled then\n                    return\n                end\n\n                local LowGround, Debounce = math.huge, tick()\n                for _, v: Vector3 in bedwars.BlockController:getStore():getAllBlockPositions() do\n                    v = v * 3\n                    if v.Y < LowGround and not GetPlacedBlock(v + Vector3.new(0, 3, 0)) then\n                        LowGround = v.Y\n                    end\n                end\n                if LowGround == math.huge then\n                    return\n                end\n\n                AntiFallPart = Instance.new(\"Part\")\n                AntiFallPart.Size = Vector3.new(10000, 1, 10000)\n                AntiFallPart.Transparency = 1 - Color.Opacity\n                AntiFallPart.Material = Enum.Material[Material.Value]\n                AntiFallPart.Color = Color3.fromHSV(Color.Hue, Color.Sat, Color.Value)\n                AntiFallPart.Position = Vector3.new(0, LowGround - 2, 0)\n                AntiFallPart.CanCollide = Mode.Value == \"Collide\"\n                AntiFallPart.Anchored = true\n                AntiFallPart.CanQuery = false\n                AntiFallPart.Parent = workspace\n                AntiFall:Clean(AntiFallPart)\n                AntiFall:Clean(AntiFallPart.Touched:Connect(function(TouchedPart: BasePart)\n                    if TouchedPart.Parent ~= LocalPlayer.Character or not Entity.isAlive or vape.MovementOwner or Debounce >= tick() then\n                        return\n                    end\n                    Debounce = tick() + 0.1\n\n                    if Mode.Value == \"Normal\" then\n                        local Top: Vector3? = GetNearGround()\n                        if not Top then\n                            return\n                        end\n\n                        local LastTeleport = LocalPlayer:GetAttribute(\"LastTeleported\")\n                        RayCheck.FilterDescendantsInstances = {Camera, LocalPlayer.Character}\n                        RayCheck.CollisionGroup = Entity.character.RootPart.CollisionGroup\n                        if Connection then\n                            Connection:Disconnect()\n                        end\n                        Connection = RunService.PreSimulation:Connect(function()\n                            if vape.Modules.Fly.Enabled or vape.Modules.LongJump.Enabled or vape.MovementOwner or not Entity.isAlive or LocalPlayer:GetAttribute(\"LastTeleported\") ~= LastTeleport then\n                                Connection:Disconnect()\n                                AntiFallDirection = nil\n                                return\n                            end\n\n                            local Root: BasePart = Entity.character.RootPart\n                            local Delta: Vector3 = (Top - Root.Position) * Vector3.new(1, 0, 1)\n                            AntiFallDirection = Delta.Unit == Delta.Unit and Delta.Unit or Vector3.zero\n                            Root.AssemblyLinearVelocity *= Vector3.new(1, 0, 1)\n\n                            local WallRay: RaycastResult? = workspace:Raycast(Root.Position, AntiFallDirection, RayCheck)\n                            if WallRay then\n                                local BlockPosition: Vector3 = RoundPosition(WallRay.Position + WallRay.Normal * 1.5) + Vector3.new(0, 3, 0)\n                                for _ = 1, 10 do\n                                    if not GetPlacedBlock(BlockPosition) then\n                                        Top = Vector3.new(Top.X, BlockPosition.Y, Top.Z)\n                                        break\n                                    end\n                                    BlockPosition += Vector3.new(0, 3, 0)\n                                end\n                            end\n\n                            Root.CFrame += Vector3.new(0, Top.Y - Root.Position.Y, 0)\n                            if not FrictionTable.Speed then\n                                Root.AssemblyLinearVelocity = (AntiFallDirection * GetSpeed()) + Vector3.new(0, Root.AssemblyLinearVelocity.Y, 0)\n                            end\n\n                            if Delta.Magnitude < 1 then\n                                Connection:Disconnect()\n                                AntiFallDirection = nil\n                            end\n                        end)\n                    elseif Mode.Value == \"Velocity\" then\n                        local Root: BasePart = Entity.character.RootPart\n                        Root.AssemblyLinearVelocity = Vector3.new(Root.AssemblyLinearVelocity.X, 100, Root.AssemblyLinearVelocity.Z)\n                    end\n                end))\n            else\n                if Connection then\n                    Connection:Disconnect()\n                    Connection = nil\n                end\n                AntiFallDirection = nil\n                AntiFallPart = nil\n            end\n        end,\n        Tooltip = \"Help's you with your Parkinson's\\nPrevents you from falling into the void.\"\n    })\n\n    Mode = AntiFall:CreateDropdown({\n        Name = \"Move Mode\",\n        List = {\"Normal\", \"Collide\", \"Velocity\"},\n        Function = function(Val: string)\n            if AntiFallPart then\n                AntiFallPart.CanCollide = Val == \"Collide\"\n            end\n        end,\n        Tooltip = \"Normal - Smoothly moves you towards the nearest safe point\\nVelocity - Launches you upward after touching\\nCollide - Allows you to walk on the part\"\n    })\n    local Materials: {string} = {\"ForceField\"}\n    for _, v: EnumItem in Enum.Material:GetEnumItems() do\n        if v.Name ~= \"ForceField\" then\n            table.insert(Materials, v.Name)\n        end\n    end\n    Material = AntiFall:CreateDropdown({\n        Name = \"Material\",\n        List = Materials,\n        Function = function(Val: string)\n            if AntiFallPart then\n                AntiFallPart.Material = Enum.Material[Val]\n            end\n        end\n    })\n    Color = AntiFall:CreateColorSlider({\n        Name = \"Color\",\n        DefaultOpacity = 0.5,\n        Function = function(Hue: number, Sat: number, Val: number, Opacity: number)\n            if AntiFallPart then\n                AntiFallPart.Color = Color3.fromHSV(Hue, Sat, Val)\n                AntiFallPart.Transparency = 1 - Opacity\n            end\n        end\n    })\nend)\n\nlocal replicatesignal = replicatesignal and (clonefunction and clonefunction(replicatesignal) or replicatesignal) or nil\nRun(function()\n    local AntiVoidFlag\n\n    local function FindNearGround(Origin: Vector3)\n        local Positions: {Vector3} = {}\n        for _, v: Vector3 in {Vector3.new(1, 0, 0), Vector3.new(0, 0, 1), Vector3.new(-1, 0, 0), Vector3.new(0, 0, -1)} do\n            for Step: number = 1, 18 do\n                local GroundRay: RaycastResult? = workspace:Raycast((Origin + Vector3.new(0, 500, 0)) + (v * Step), Vector3.new(0, -1000, 0), store.airRay)\n                if GroundRay then\n                    table.insert(Positions, GroundRay.Position)\n                end\n            end\n        end\n\n        table.sort(Positions, function(A: Vector3, B: Vector3)\n            return (Vector3.new(Origin.X, A.Y, Origin.Z) - A).Magnitude < (Vector3.new(Origin.X, B.Y, Origin.Z) - B).Magnitude\n        end)\n        return Positions[1]\n    end\n\n    AntiVoidFlag = vape.Categories.Blatant:CreateModule({\n        Name = \"AntiVoidFlag\",\n        Function = function(Callback: boolean)\n            if Callback and replicatesignal then\n                local Seat, Welded = ReplicatedStorage.Assets.Effects.snowball_rider.Handle.Seat, false\n                ;(function()\n                    repeat\n                        if Entity.isAlive then\n                            local Root: BasePart? = LocalPlayer.Character:FindFirstChild(\"HumanoidRootPart\")\n                            local Humanoid: Humanoid? = LocalPlayer.Character:FindFirstChildOfClass(\"Humanoid\")\n                            \n                            if Root and Humanoid and not isnetworkowner(Root) and not workspace:Raycast(Root.Position, Vector3.new(0, -1000, 0), store.airRay) then\n                                Root.AssemblyLinearVelocity = Vector3.zero\n                                Welded = true\n                                Humanoid:ChangeState(Enum.HumanoidStateType.Jumping)\n                                replicatesignal(Seat.RemoteCreateSeatWeld, Humanoid)\n                            elseif Root and isnetworkowner(Root) and Welded or not Root and Welded then\n                                if Root then\n                                    local Ground: Vector3? = FindNearGround(Root.Position)\n                                    if Ground then\n                                        notif(\"AntiVoidFlag\", \"Teleported.\", 8, \"info\")\n                                        Root.AssemblyLinearVelocity = Vector3.new(0, 2.5, 0)\n                                        Root.CFrame = CFrame.lookAlong(Ground + Vector3.new(0, 2.5, 0), Root.CFrame.LookVector)\n                                    end\n                                end\n                                replicatesignal(Seat.RemoteDestroySeatWeld)\n                                Welded = false\n                            end\n                        elseif Welded then\n                            replicatesignal(Seat.RemoteDestroySeatWeld)\n                            Welded = false\n                        end\n                        task.wait()\n                    until not AntiVoidFlag.Enabled\n\n                    if Welded then\n                        replicatesignal(Seat.RemoteDestroySeatWeld)\n                    end\n                end)()\n            end\n        end\n    })\nend)\n\nRun(function()\n\tlocal AutoChargeProj\n\tlocal Percentage\n\tlocal Items\n\t\n\tlocal Old, Hook\n\t\n\tlocal function MatchesSelected(Selected: {string}, Tool: string?, Projectile: string)\n\t    for _, Name: string in Selected do\n\t        if Name == Tool or Name == Projectile then\n\t            return true\n\t        end\n\t    end\n\t    return false\n\tend\n\t\n\tAutoChargeProj = vape.Categories.Blatant:CreateModule({\n\t    Name = \"AutoChargeProj\",\n\t    Function = function(Callback: boolean)\n\t        if Callback then\n\t            if Hook then\n\t                return\n\t            end\n\t            Old = bedwars.ProjectileController.calculateImportantLaunchValues\n\t            Hook = function(self, LaunchData, ...)\n\t                if not AutoChargeProj.Enabled then\n\t                    return Old(self, LaunchData, ...)\n\t                end\n\t                local ProjectileMeta = bedwars.ProjectileMeta[LaunchData.projectile]\n\t                local Tool: Tool? = Store.hand.tool\n\t                local Selected: {string} = Items.ListEnabled or {}\n\t                local Allowed: boolean = #Selected == 0 or MatchesSelected(Selected, Tool and Tool.Name, LaunchData.projectile)\n\t                if Allowed and ProjectileMeta and ProjectileMeta.predictionLifetimeSec and LaunchData.drawDurationSeconds then\n\t                    LaunchData.drawDurationSeconds = math.max(LaunchData.drawDurationSeconds, ProjectileMeta.predictionLifetimeSec * (Percentage.Value / 100))\n\t                    LaunchData.velocityMultiplier = math.max(LaunchData.velocityMultiplier or 0, Percentage.Value / 100)\n\t                end\n\t                return Old(self, LaunchData, ...)\n\t            end\n\t            bedwars.ProjectileController.calculateImportantLaunchValues = Hook\n\t        elseif Hook and bedwars.ProjectileController.calculateImportantLaunchValues == Hook then\n\t            bedwars.ProjectileController.calculateImportantLaunchValues = Old\n\t            Old, Hook = nil, nil\n\t        end\n\t    end,\n\t    Tooltip = \"Instantly charges your projectile item to a certain percentage\"\n\t})\n\t\n\tPercentage = AutoChargeProj:CreateSlider({\n\t    Name = \"Percentage\",\n\t    Min = 0,\n\t    Max = 100,\n\t    Default = 50,\n\t    Suffix = \"%\"\n\t})\n\t\n\tItems = AutoChargeProj:CreateTextList({\n\t    Name = \"Items\",\n\t    Default = {},\n\t    Tooltip = \"Item or projectile ids to charge; empty charges every chargeable projectile\"\n\t})\nend)\n\nRun(function()\n\tlocal CannonSpeed\n\tlocal Value\n\t\n\tlocal function SetSpeed(Speed: number)\n\t    if not canDebug then\n\t        return\n\t    end\n\t\n\t    local LaunchSelf: (self: {any}, Part) -> () = rawget(getmetatable(bedwars.CannonHandController).__index, \"launchSelf\")\n\t    if LaunchSelf and typeof(LaunchSelf) == \"function\" then\n\t        for i: number, v: any in debug.getconstants(LaunchSelf) do\n\t            if type(v) == \"number\" then\n\t                debug.setconstant(LaunchSelf, i, Speed)\n\t                break\n\t            end\n\t        end\n\t    end\n\tend\n\t\n\tCannonSpeed = vape.Categories.Blatant:CreateModule({\n\t    Name = \"CannonSpeed\",\n\t    Function = function(Callback: boolean)\n\t        if not canDebug then\n\t            if Callback then\n\t                CannonSpeed:Clean(vape.Libraries.cheatengine.CannonBoost.Bind(function(): number\n\t                    return Value.Value\n\t                end))\n\t            end\n\t\n\t            return\n\t        end\n\t\n\t        SetSpeed(Callback and Value.Value or 200)\n\t    end,\n\t    Tooltip = \"Makes you go faster with cannon.\"\n\t})\n\t\n\tValue = CannonSpeed:CreateSlider({\n\t    Name = \"Speed\",\n\t    Min = 1,\n\t    Max = 400,\n\t    Function = function(Val: number)\n\t        if CannonSpeed.Enabled then\n\t            SetSpeed(Val)\n\t        end\n\t    end,\n\t    Default = 200,\n\t    Suffix = function(Val: number)\n\t        return Val <= 1 and \"stud\" or \"studs\"\n\t    end\n\t})\n\tCannonSpeed:CreateButton({\n\t    Name = \"Sync to legit speed\",\n\t    Function = function()\n\t        Value:SetValue(200)\n\t    end\n\t})\nend)\n\nRun(function()\n\tlocal DamageBoost\n\tlocal Stack: number?\n\t\n\tDamageBoost = vape.Categories.Blatant:CreateModule({\n\t    Name = \"DamageBoost\",\n\t    Function = function(Callback: boolean)\n\t        if Callback then\n\t            DamageBoost:Clean(VapeEvents.EntityDamageEvent.Event:Connect(function(DamageTable)\n\t                if Entity.isAlive and tick() > (Stack or 0) and DamageTable.entityInstance == LocalPlayer.Character and not vape.Modules.LongJump.Enabled then\n\t                    local Horizontal: number = DamageTable.knockbackMultiplier and DamageTable.knockbackMultiplier.horizontal or 0\n\t                    KnockbackSpeed = bedwars.KnockbackUtil.calculateKnockbackVelocity(Vector3.one, 1, {\n\t                        vertical = 0,\n\t                        horizontal = Horizontal\n\t                    }).Magnitude * (0.9 + (Store.ping.total or 0))\n\t                    Stack = tick() + (KnockbackSpeed / 45)\n\t                    KnockbackBoost = tick() + (Horizontal / 3.5)\n\t                end\n\t            end))\n\t        end\n\t    end,\n\t    Tooltip = \"Makes you go slightly faster when damaged\"\n\t})\nend)\n\nRun(function()\n\tlocal DeathAdderAimbot\n\tlocal Mode\n\tlocal BedRange\n\tlocal Targets\n\tlocal Sort\n\tlocal TargetPart\n\tlocal FOV\n\t\n\tlocal Old: (...any) -> ...any\n\t\n\tDeathAdderAimbot = vape.Categories.Blatant:CreateModule({\n\t    Name = \"DeathAdderAimbot\",\n\t    Function = function(Callback: boolean)\n\t        if Callback then\n\t            Old = bedwars.SorcererController.getProjectileDirection\n\t            bedwars.SorcererController.getProjectileDirection = function(self, ...)\n\t                if Entity.isAlive then\n\t                    local LocalPosition: Vector3 = Entity.character.RootPart.Position\n\t                    local Aim: Vector3?\n\t                    if Mode.Value == \"Bed\" then\n\t                        local ClosestDistance: number = BedRange.Value\n\t                        for _, v: BasePart in CollectionService:GetTagged(\"bed\") do\n\t                            if not v:GetAttribute(`Team{LocalPlayer:GetAttribute(\"Team\") or -1}NoBreak`) then\n\t                                local Distance: number = (LocalPosition - v.Position).Magnitude\n\t                                if Distance <= ClosestDistance then\n\t                                    Aim, ClosestDistance = v.Position, Distance\n\t                                end\n\t                            end\n\t                        end\n\t                    else\n\t                        local Ent = Entity.EntityMouse({\n\t                            Range = FOV.Value,\n\t                            Part = \"RootPart\",\n\t                            Wallcheck = Targets.Walls.Enabled,\n\t                            Players = Targets.Players.Enabled,\n\t                            NPCs = Targets.NPCs.Enabled,\n\t                            Priority = Targets.Priority.Value,\n\t                            Origin = LocalPosition,\n\t                            Sort = SortMethods[Sort.Value]\n\t                        })\n\t                        if Ent then\n\t                            TargetInfo.Targets[Ent] = tick() + 1\n\t                            local TierData = bedwars.SorcererBalance.getSorcererTierData(bedwars.SorcererBalance.getSorcererTier(LocalPlayer))\n\t                            local Point: Vector3 = Ent[TargetPart.Value].Position\n\t                            local ProjectileSpeed: number = TierData and TierData.projectileVelocity or 70\n\t                            Aim = Point + (Ent.RootPart.AssemblyLinearVelocity * ((Point - LocalPosition).Magnitude / ProjectileSpeed))\n\t                        end\n\t                    end\n\t\n\t                    if Aim and Aim ~= LocalPosition then\n\t                        return (Aim - LocalPosition).Unit\n\t                    end\n\t                end\n\t\n\t                return Old(self, ...)\n\t            end\n\t        else\n\t            bedwars.SorcererController.getProjectileDirection = Old\n\t        end\n\t    end,\n\t    Tooltip = \"Silently aims Death Adder's spell at a bed or a player\"\n\t})\n\t\n\tMode = DeathAdderAimbot:CreateDropdown({\n\t    Name = \"Mode\",\n\t    List = {\"Player\", \"Bed\"},\n\t    Function = function(Val: string)\n\t        if BedRange then\n\t            BedRange.Object.Visible = Val == \"Bed\"\n\t            FOV.Object.Visible = Val == \"Player\"\n\t            TargetPart.Object.Visible = Val == \"Player\"\n\t            Sort.Object.Visible = Val == \"Player\"\n\t        end\n\t    end,\n\t    Tooltip = \"Bed aims at the closest enemy bed, Player leads the closest enemy\"\n\t})\n\tBedRange = DeathAdderAimbot:CreateSlider({\n\t    Name = \"Bed range\",\n\t    Min = 1,\n\t    Max = 60,\n\t    Default = 60,\n\t    Darker = true,\n\t    Visible = false,\n\t    Suffix = function(Val: number)\n\t        return Val == 1 and \"stud\" or \"studs\"\n\t    end\n\t})\n\tTargets = DeathAdderAimbot:CreateTargets({\n\t    Players = true,\n\t    Walls = true\n\t})\n\tlocal Methods: {string} = {\"Distance\", \"Damage\"}\n\tfor _, v: string in SortList do\n\t    if not table.find(Methods, v) then\n\t        table.insert(Methods, v)\n\t    end\n\tend\n\tSort = DeathAdderAimbot:CreateDropdown({\n\t    Name = \"Target mode\",\n\t    List = Methods,\n\t    Default = \"Distance\",\n\t    Darker = true\n\t})\n\tTargetPart = DeathAdderAimbot:CreateDropdown({\n\t    Name = \"Part\",\n\t    List = {\"RootPart\", \"Head\"},\n\t    Darker = true\n\t})\n\tFOV = DeathAdderAimbot:CreateSlider({\n\t    Name = \"FOV\",\n\t    Min = 1,\n\t    Max = 1000,\n\t    Default = 1000,\n\t    Darker = true\n\t})\nend)\n\nRun(function()\n\tlocal FastBreak\n\tlocal BedCheck\n\tlocal HiveCheck\n\tlocal Blacklist\n\tlocal Blacklisted\n\tlocal Time\n\tlocal Session\n\t\n\tlocal BlockList = {}\n\t\n\tlocal function IsAllowed(Block: Instance?): boolean\n\t    if not Block then\n\t        return false\n\t    end\n\t\n\t    if Blacklist.Enabled then\n\t        for _, v: string in BlockList do\n\t            if v == Block.Name or Block.Name:find(v, 1, true) then\n\t                return false\n\t            end\n\t        end\n\t    end\n\t\n\t    return (not BedCheck.Enabled or Block.Name ~= \"bed\") and (not HiveCheck.Enabled or Block.Name ~= \"beehive\")\n\tend\n\t\n\tFastBreak = vape.Categories.Blatant:CreateModule({\n\t    Name = \"FastBreak\",\n\t    Function = function(Callback: boolean)\n\t        if Callback and not canDebug then\n\t            local Library = vape.Libraries.cheatengine\n\t            if not Library.GetBlockBreaker() then\n\t                SendNotification(\"FastBreak\", \"Could not reach the game's block breaker on this executor\", 5)\n\t                FastBreak:Toggle()\n\t                return\n\t            end\n\t\n\t            local Current = {}\n\t            Session = Current\n\t            repeat\n\t                bedwars.BlockBreakController.blockBreaker:setCooldown(IsAllowed(Library.BlockTarget.GetBlock()) and Time.Value or 0.3)\n\t                task.wait(0.05)\n\t            until not FastBreak.Enabled or Session ~= Current\n\t            return\n\t        end\n\t\n\t        if Callback then\n\t            local Current = {}\n\t            Session = Current\n\t            bedwars.BlockBreakCallbacks.FastBreak = function(self, ...)\n\t                local RayParams = select(2, ...)\n\t                pcall(function()\n\t                    local MouseInfo = self.clientManager:getBlockSelector():getMouseInfo(1, {ray = RayParams})\n\t                    local Block = MouseInfo and MouseInfo.target and MouseInfo.target.blockInstance\n\t                    if IsAllowed(Block) then\n\t                        bedwars.BlockBreakController.blockBreaker:setCooldown(Time.Value)\n\t                    end\n\t                end)\n\t            end\n\t\n\t            repeat\n\t                if (tick() - Store.lastHit) > 0.3 then\n\t                    bedwars.BlockBreakController.blockBreaker:setCooldown(0.3)\n\t                end\n\t                task.wait(0.1)\n\t            until not FastBreak.Enabled or Session ~= Current\n\t        else\n\t            Session = nil\n\t            bedwars.BlockBreakCallbacks.FastBreak = nil\n\t            bedwars.BlockBreakController.blockBreaker:setCooldown(0.3)\n\t        end\n\t    end,\n\t    Tooltip = \"Decreases block hit cooldown\"\n\t})\n\t\n\tTime = FastBreak:CreateSlider({\n\t    Name = \"Break speed\",\n\t    Min = 0,\n\t    Max = 0.3,\n\t    Default = 0.25,\n\t    Decimal = 100,\n\t    Suffix = \"seconds\"\n\t})\n\tFastBreak:CreateButton({\n\t    Name = \"Sync to legit speed\",\n\t    Function = function()\n\t        Time:SetValue(0.3)\n\t    end\n\t})\n\tBedCheck = FastBreak:CreateToggle({\n\t    Name = \"Bed Check\",\n\t    Tooltip = \"Doesn't increase speed if ur breaking a bed\"\n\t})\n\tHiveCheck = FastBreak:CreateToggle({\n\t    Name = \"Blacklist Beehive\",\n\t    Tooltip = \"Doesn't increase speed if ur breaking a beehive\"\n\t})\n\tBlacklist = FastBreak:CreateToggle({\n\t    Name = \"Use blacklist\",\n\t    Function = function(Callback: boolean)\n\t        if Blacklisted then\n\t            Blacklisted.Object.Visible = Callback\n\t        end\n\t    end\n\t})\n\tBlacklisted = FastBreak:CreateTextList({\n\t    Name = \"Blocks\",\n\t    Function = function(List: {string})\n\t        BlockList = {}\n\t        for _, v: string in List do\n\t            if v:find(\"iron\") then\n\t                table.insert(BlockList, \"iron_ore_mesh_block\")\n\t            else\n\t                table.insert(BlockList, v)\n\t            end\n\t        end\n\t    end,\n\t    Darker = true,\n\t    Visible = false\n\t})\nend)\n\nlocal Fly\nlocal LongJump\nRun(function()\n    local Value\n    local VerticalValue\n    local WallCheck\n    local PopBalloons\n    local TeleportDown\n    local ShowProgressbar\n    local Bar = nil\n    local AirLimit: number = 1.7\n    local RayCheck: RaycastParams = RaycastParams.new()\n    RayCheck.RespectCanCollide = true\n    local FilterCharacter: Model?\n    local FilterFallPart: Part?\n    local Up, Down, Old = 0, 0\n\n    local function RemoveBar()\n        if Bar then\n            Bar.Frame:Destroy()\n            Bar = nil\n        end\n    end\n\n    Fly = vape.Categories.Blatant:CreateModule({\n        Name = \"Fly\",\n        Function = function(Callback: boolean)\n            FrictionTable.Fly = Callback or nil\n            UpdateVelocity()\n            if Callback then\n                Up, Down, Old = 0, 0, bedwars.BalloonController.deflateBalloon\n                bedwars.BalloonController.deflateBalloon = function() end\n                local TeleportTick, TeleportToggle, OldY = tick(), true\n                if ShowProgressbar.Enabled then\n                    Bar = CreateProgressBar()\n                end\n                Fly:Clean(RemoveBar)\n\n                if LocalPlayer.Character and (LocalPlayer.Character:GetAttribute(\"InflatedBalloons\") or 0) == 0 and GetItem(\"balloon\") then\n                    bedwars.BalloonController:inflateBalloon()\n                end\n                Fly:Clean(VapeEvents.AttributeChanged.Event:Connect(function(AttributeName: string)\n                    if AttributeName == \"InflatedBalloons\" and (LocalPlayer.Character:GetAttribute(\"InflatedBalloons\") or 0) == 0 and GetItem(\"balloon\") then\n                        bedwars.BalloonController:inflateBalloon()\n                    end\n                end))\n                Fly:Clean(RunService.PreSimulation:Connect(function(Delta: number)\n                    if Entity.isAlive and not vape.MovementOwner and isnetworkowner(Entity.character.RootPart) then\n                        local FlyAllowed: boolean = (LocalPlayer.Character:GetAttribute(\"InflatedBalloons\") or 0) > 0 or Store.matchState == 2\n                        if Bar then\n                            local Waiting: boolean = not FlyAllowed and TeleportDown.Enabled\n                            Bar.Frame.Visible = Waiting\n                            if Waiting then\n                                Bar.Set(AirLimit - (tick() - Entity.character.AirTime), AirLimit)\n                            end\n                        end\n                        local Mass: number = (-0.02 + (FlyAllowed and 6 or 0) * (tick() % 0.4 < 0.2 and -1 or 1)) + ((Up + Down) * VerticalValue.Value)\n                        local Root, MoveDirection = Entity.character.RootPart, Entity.character.Humanoid.MoveDirection\n                        local CurrentSpeed: number = GetSpeed()\n                        local Destination: Vector3 = MoveDirection * math.max(Value.Value - CurrentSpeed, 0) * Delta\n                        if not LocalPlayer.Character or FilterCharacter ~= LocalPlayer.Character or FilterFallPart ~= AntiFallPart then\n                            FilterCharacter, FilterFallPart = LocalPlayer.Character, AntiFallPart\n                            RayCheck.FilterDescendantsInstances = {FilterCharacter, Camera, FilterFallPart}\n                        end\n                        RayCheck.CollisionGroup = Root.CollisionGroup\n\n                        if WallCheck.Enabled then\n                            local WallRay: RaycastResult? = workspace:Raycast(Root.Position, Destination, RayCheck)\n                            if WallRay then\n                                Destination = (WallRay.Position + WallRay.Normal) - Root.Position\n                            end\n                        end\n\n                        if not FlyAllowed then\n                            if TeleportToggle and not OldY and (tick() - Entity.character.AirTime) > AirLimit then\n                                local GroundRay: RaycastResult? = workspace:Raycast(Root.Position, Vector3.new(0, -1000, 0), RayCheck)\n                                if GroundRay and TeleportDown.Enabled then\n                                    TeleportToggle = false\n                                    OldY = Root.Position.Y\n                                    TeleportTick = tick() + 0.11\n                                    Root.CFrame = CFrame.lookAlong(Vector3.new(Root.Position.X, GroundRay.Position.Y + Entity.character.HipHeight, Root.Position.Z), Root.CFrame.LookVector)\n                                end\n                            elseif not TeleportToggle and OldY then\n                                if TeleportTick < tick() then\n                                    Root.CFrame = CFrame.lookAlong(Vector3.new(Root.Position.X, OldY, Root.Position.Z), Root.CFrame.LookVector)\n                                    TeleportToggle = true\n                                    OldY = nil\n                                else\n                                    Mass = 0\n                                end\n                            end\n                        end\n\n                        Root.CFrame += Destination\n                        Root.AssemblyLinearVelocity = (MoveDirection * CurrentSpeed) + Vector3.new(0, Mass, 0)\n                    elseif Bar then\n                        Bar.Frame.Visible = false\n                    end\n                end))\n                Fly:Clean(UserInputService.InputBegan:Connect(function(Input: InputObject)\n                    if not UserInputService:GetFocusedTextBox() then\n                        if Input.KeyCode == Enum.KeyCode.Space or Input.KeyCode == Enum.KeyCode.ButtonA then\n                            Up = 1\n                        elseif Input.KeyCode == Enum.KeyCode.LeftShift or Input.KeyCode == Enum.KeyCode.ButtonL2 then\n                            Down = -1\n                        end\n                    end\n                end))\n                Fly:Clean(UserInputService.InputEnded:Connect(function(Input: InputObject)\n                    if Input.KeyCode == Enum.KeyCode.Space or Input.KeyCode == Enum.KeyCode.ButtonA then\n                        Up = 0\n                    elseif Input.KeyCode == Enum.KeyCode.LeftShift or Input.KeyCode == Enum.KeyCode.ButtonL2 then\n                        Down = 0\n                    end\n                end))\n                if UserInputService.TouchEnabled then\n                    pcall(function()\n                        local JumpButton: ImageButton = LocalPlayer.PlayerGui.TouchGui.TouchControlFrame.JumpButton\n                        Fly:Clean(JumpButton:GetPropertyChangedSignal(\"ImageRectOffset\"):Connect(function()\n                            Up = JumpButton.ImageRectOffset.X == 146 and 1 or 0\n                        end))\n                    end)\n                end\n            else\n                bedwars.BalloonController.deflateBalloon = Old\n                if PopBalloons.Enabled and Entity.isAlive and (LocalPlayer.Character:GetAttribute(\"InflatedBalloons\") or 0) > 0 then\n                    for _ = 1, 3 do\n                        bedwars.BalloonController:deflateBalloon()\n                    end\n                end\n            end\n        end,\n        ExtraText = function()\n            return \"Heatseeker\"\n        end,\n        Tooltip = \"Makes you go zoom.\"\n    })\n\n    Value = Fly:CreateSlider({\n        Name = \"Speed\",\n        Min = 1,\n        Max = 23,\n        Default = 23,\n        Suffix = function(Val: number)\n            return Val == 1 and \"stud\" or \"studs\"\n        end\n    })\n    VerticalValue = Fly:CreateSlider({\n        Name = \"Vertical Speed\",\n        Min = 1,\n        Max = 150,\n        Default = 50,\n        Suffix = function(Val: number)\n            return Val == 1 and \"stud\" or \"studs\"\n        end\n    })\n    WallCheck = Fly:CreateToggle({\n        Name = \"Wall Check\",\n        Default = true\n    })\n    PopBalloons = Fly:CreateToggle({\n        Name = \"Pop Balloons\",\n        Default = true\n    })\n    TeleportDown = Fly:CreateToggle({\n        Name = \"TP Down\",\n        Default = true\n    })\n    ShowProgressbar = Fly:CreateToggle({\n        Name = \"Show Progressbar\",\n        Default = true,\n        Function = function(Callback: boolean)\n            RemoveBar()\n            if Callback and Fly.Enabled then\n                Bar = CreateProgressBar()\n            end\n        end,\n        Tooltip = \"Shows a bar counting down to the next TP Down while you have no balloons\"\n    })\nend)\n\nRun(function()\n\tlocal Mode\n\tlocal Expand\n\tlocal Objects, Patched = setmetatable({}, {__mode = \"k\"})\n\t\n\tlocal function CreateHitbox(Ent)\n\t    if Ent.Targetable and Ent.Player then\n\t        local Hitbox: Part = Instance.new(\"Part\")\n\t        Hitbox.Size = Vector3.new(3, 6, 3) + Vector3.one * (Expand.Value / 5)\n\t        Hitbox.Position = Ent.RootPart.Position\n\t        Hitbox.CanCollide = false\n\t        Hitbox.Massless = true\n\t        Hitbox.Transparency = 1\n\t        Hitbox.LocalTransparencyModifier = 1\n\t        Hitbox.Parent = Ent.Character\n\t        local Weld: Motor6D = Instance.new(\"Motor6D\")\n\t        Weld.Part0 = Hitbox\n\t        Weld.Part1 = Ent.RootPart\n\t        Weld.Parent = Hitbox\n\t        Objects[Ent] = Hitbox\n\t    end\n\tend\n\t\n\tHitBoxes = vape.Categories.Blatant:CreateModule({\n\t    Name = \"HitBoxes\",\n\t    Function = function(Callback: boolean)\n\t        if Callback then\n\t            if Mode.Value == \"Sword\" then\n\t                debug.setconstant(bedwars.SwordController.swingSwordInRegion, 6, (Expand.Value / 3))\n\t                Patched = true\n\t            else\n\t                HitBoxes:Clean(Entity.Events.EntityAdded:Connect(CreateHitbox))\n\t                HitBoxes:Clean(Entity.Events.EntityRemoved:Connect(function(Ent)\n\t                    if Objects[Ent] then\n\t                        Objects[Ent]:Destroy()\n\t                        Objects[Ent] = nil\n\t                    end\n\t                end))\n\t                for _, v: any in Entity.List do\n\t                    CreateHitbox(v)\n\t                end\n\t            end\n\t        else\n\t            if Patched then\n\t                debug.setconstant(bedwars.SwordController.swingSwordInRegion, 6, 3.8)\n\t                Patched = nil\n\t            end\n\t            for _, v: Part in Objects do\n\t                v:Destroy()\n\t            end\n\t            table.clear(Objects)\n\t        end\n\t    end,\n\t    Tooltip = \"Expands attack hitbox\"\n\t})\n\t\n\tMode = HitBoxes:CreateDropdown({\n\t    Name = \"Mode\",\n\t    List = {\"Sword\", \"Player\"},\n\t    Function = function()\n\t        if HitBoxes.Enabled then\n\t            HitBoxes:Toggle()\n\t            HitBoxes:Toggle()\n\t        end\n\t    end,\n\t    Tooltip = \"Sword - Increases the range around you to hit entities\\nPlayer - Increases the players hitbox\"\n\t})\n\tExpand = HitBoxes:CreateSlider({\n\t    Name = \"Expand amount\",\n\t    Min = 0,\n\t    Max = 14.4,\n\t    Decimal = 10,\n\t    Function = function(Val: number)\n\t        if HitBoxes.Enabled then\n\t            if Mode.Value == \"Sword\" then\n\t                debug.setconstant(bedwars.SwordController.swingSwordInRegion, 6, (Val / 3))\n\t            else\n\t                for _, v: Part in Objects do\n\t                    v.Size = Vector3.new(3, 6, 3) + Vector3.one * (Val / 5)\n\t                end\n\t            end\n\t        end\n\t    end,\n\t    Default = 14.4,\n\t    Suffix = function(Val: number)\n\t        return Val == 1 and \"stud\" or \"studs\"\n\t    end\n\t})\nend)\n\nRun(function()\n\tlocal InfiniteFly\n\tlocal VerticalValue\n\tlocal Label, ShadowLabel\n\tlocal Up, Down = 0, 0\n\tlocal Landing: boolean = false\n\t\n\tlocal HiddenPart: Part = Instance.new(\"Part\")\n\tHiddenPart.Parent = workspace\n\tHiddenPart.Transparency = 1\n\tHiddenPart.CanQuery = false\n\tHiddenPart.CanTouch = false\n\tHiddenPart.CanCollide = false\n\tHiddenPart.Anchored = true\n\tvape:Clean(HiddenPart)\n\t\n\tlocal OldTransparency: {[BasePart]: number} = setmetatable({}, {__mode = \"k\"})\n\t\n\tlocal function FindGround()\n\t    for _, v: Vector3 in {Entity.character.Humanoid.MoveDirection, Vector3.new(1, 0, 0), Vector3.new(0, 0, 1), Vector3.new(-1, 0, 0), Vector3.new(0, 0, -1)} do\n\t        for Step: number = 1, 4 do\n\t            local Ground: RaycastResult? = workspace:Blockcast((Entity.character.RootPart.CFrame + Vector3.new(0, 200, 0)) + (v * Step), Vector3.new(3, 3, 3), Vector3.new(0, -1000, 0), store.airRay)\n\t            if Ground then\n\t                return Ground\n\t            end\n\t        end\n\t    end\n\t    return false\n\tend\n\t\n\tInfiniteFly = vape.Categories.Blatant:CreateModule({\n\t    Name = \"InfiniteFly\",\n\t    Function = function(Callback: boolean)\n\t        if Label and ShadowLabel then\n\t            Label.Visible = Callback\n\t            ShadowLabel.Visible = Callback\n\t        end\n\t        \n\t        if Callback then\n\t            if not Entity.isAlive or Landing or workspace:Raycast(Entity.character.RootPart.Position, Vector3.new(0, -1000, 0), store.airRay) then\n\t                notif(\"InfiniteFly\", \"Cannot fly at this state.\", 8, \"warning\")\n\t                InfiniteFly:Toggle()\n\t                return\n\t            end\n\t            if Entity.isAlive then\n\t                Camera.CameraSubject = HiddenPart\n\t                for _, v: BasePart in Entity.character.Character:QueryDescendants(\"BasePart\") do\n\t                    OldTransparency[v] = v.Transparency\n\t                    v.Transparency = 1\n\t                end\n\t            end\n\t\n\t            HiddenPart.CFrame = Entity.character.Character.Head.CFrame\n\t            store.infinitefly = true\n\t            vape.MovementOwner = \"InfiniteFly\"\n\t            Landing = true\n\t\n\t            local Root: BasePart = Entity.character.RootPart\n\t            local Start: CFrame = CFrame.new(Root.Position)\n\t            Root.CFrame = Start\n\t            InfiniteFly:Clean(UserInputService.InputBegan:Connect(function(Input: InputObject)\n\t                if not UserInputService:GetFocusedTextBox() then\n\t                    if Input.KeyCode == Enum.KeyCode.Space or Input.KeyCode == Enum.KeyCode.ButtonA then\n\t                        Up = 1\n\t                    elseif Input.KeyCode == Enum.KeyCode.LeftShift or Input.KeyCode == Enum.KeyCode.ButtonL2 then\n\t                        Down = -1\n\t                    end\n\t                end\n\t            end))\n\t            InfiniteFly:Clean(UserInputService.InputEnded:Connect(function(Input: InputObject)\n\t                if Input.KeyCode == Enum.KeyCode.Space or Input.KeyCode == Enum.KeyCode.ButtonA then\n\t                    Up = 0\n\t                elseif Input.KeyCode == Enum.KeyCode.LeftShift or Input.KeyCode == Enum.KeyCode.ButtonL2 then\n\t                    Down = 0\n\t                end\n\t            end))\n\t            InfiniteFly:Clean(RunService.PreSimulation:Connect(function(Delta: number)\n\t                if vape.ThreadFix then\n\t                    setthreadidentity(8)\n\t                end\n\t\n\t                if not Entity.isAlive or not Root or not isnetworkowner(Root) then\n\t                    notif(\"InfiniteFly\", \"Network ownership disowned\", 10, \"alert\")\n\t                    InfiniteFly:Toggle()\n\t                    return\n\t                end\n\t\n\t                if workspace:Raycast(Root.Position, Vector3.new(0, -1000, 0), store.airRay) then\n\t                    notif(\"InfiniteFly\", \"Landing\", 3.5, \"alert\")\n\t                    InfiniteFly:Toggle()\n\t                    return\n\t                end\n\t\n\t                local AnchorCFrame: CFrame = CFrame.new(Vector3.new(Root.Position.X, HiddenPart.CFrame.Y, Root.Position.Z))\n\t                if vape.ThreadFix then\n\t                    setthreadidentity(8)\n\t                end\n\t\n\t                HiddenPart.CFrame = AnchorCFrame + Vector3.new(0, Delta * ((Up + Down) * VerticalValue.Value), 0)\n\t                if Label and ShadowLabel then\n\t                    if vape.ThreadFix then\n\t                        setthreadidentity(8)\n\t                    end\n\t\n\t                    Label.Text = `{math.round((Start.Position - AnchorCFrame.Position).Magnitude / 3)} blocks`\n\t                    ShadowLabel.Text = Label.Text\n\t                end\n\t                if Root.CFrame.Y <= (HiddenPart.CFrame.Y + 4) or FindGround() then\n\t                    if vape.ThreadFix then\n\t                        setthreadidentity(8)\n\t                    end\n\t\n\t                    Root.CFrame = CFrame.lookAlong(Vector3.new(Root.CFrame.X, (HiddenPart.CFrame.Y + 4) + 125, Root.CFrame.Z), Root.CFrame.LookVector)\n\t                end\n\t            end))\n\t        elseif store.infinitefly then\n\t            store.infinitefly = false\n\t            local NoFall = vape.Modules.NoFall\n\t            if NoFall and not NoFall.Enabled then\n\t                NoFall:Toggle()\n\t            end\n\t            task.wait(0.3)\n\t            local Ground = Entity.isAlive and FindGround()\n\t            if Ground then\n\t                Entity.character.RootPart.CFrame = CFrame.new(Ground.Position + Vector3.new(0, 3.5, 0))\n\t                Entity.character.RootPart.AssemblyLinearVelocity = Vector3.zero\n\t            end\n\t            notif(\"InfiniteFly\", \"Landed\", 2.5, \"info\")\n\t            Landing = false\n\t            if Entity.isAlive then\n\t                for _, v: BasePart in Entity.character.Character:QueryDescendants(\"BasePart\") do\n\t                    v.Transparency = OldTransparency[v] or v.Transparency\n\t                end\n\t                Camera.CameraSubject = Entity.character.Character\n\t            end\n\t            if vape.MovementOwner == \"InfiniteFly\" then\n\t                vape.MovementOwner = nil\n\t            end\n\t        end\n\t    end,\n\t    Tooltip = \"Makes you go zoom. Fly, InfiniteJump, HighJump, LongJump and the other movement modules except Speed stop working until it has fully landed\",\n\t    ExtraText = function()\n\t        return \"Heatseeker\"\n\t    end\n\t})\n\t\n\tVerticalValue = InfiniteFly:CreateSlider({\n\t    Name = \"Vertical Speed\",\n\t    Min = 1,\n\t    Max = 150,\n\t    Default = 50,\n\t    Suffix = function(Val: number)\n\t        return Val <= 1 and \"stud\" or \"studs\"\n\t    end\n\t})\n\tInfiniteFly:CreateToggle({\n\t    Name = \"Show distance\",\n\t    Function = function(Callback: boolean)\n\t        if Callback then\n\t            if vape.ThreadFix then\n\t                setthreadidentity(8)\n\t            end\n\t\n\t            Label = Instance.new(\"TextLabel\")\n\t            Label.Size = UDim2.fromOffset(100, 20)\n\t            Label.Position = UDim2.new(0.5, 6, 0.5, 60)\n\t            Label.BackgroundTransparency = 1\n\t            Label.AnchorPoint = Vector2.new(0.5, 0)\n\t            Label.Text = \"0 blocks\"\n\t            Label.ZIndex = 6\n\t            Label.TextColor3 = Color3.new(1, 1, 1)\n\t            Label.TextSize = 18\n\t            Label.RichText = true\n\t            Label.FontFace = vape.Libraries.uipallet.FontDisplay\n\t            Label.Visible = InfiniteFly.Enabled\n\t            if vape.ThreadFix then\n\t                setthreadidentity(8)\n\t            end\n\t            Label.Parent = vape.gui\n\t            ShadowLabel = Label:Clone()\n\t            ShadowLabel.ZIndex = 5\n\t            ShadowLabel.AnchorPoint = Vector2.new(0.5, 0)\n\t            ShadowLabel.Position += UDim2.fromOffset(1, 1)\n\t            ShadowLabel.Text = Label.ContentText\n\t            ShadowLabel.TextColor3 = Color3.new()\n\t            if vape.ThreadFix then\n\t                setthreadidentity(8)\n\t            end\n\t            ShadowLabel.Parent = vape.gui\n\t        else\n\t            if ShadowLabel then\n\t                if vape.ThreadFix then\n\t                    setthreadidentity(8)\n\t                end\n\t\n\t                ShadowLabel:Destroy()\n\t                ShadowLabel = nil\n\t            end\n\t            if Label then\n\t                if vape.ThreadFix then\n\t                    setthreadidentity(8)\n\t                end\n\t\n\t                Label:Destroy()\n\t                Label = nil\n\t            end\n\t        end\n\t    end,\n\t    Default = true\n\t})\n\t\nend)\n\nRun(function()\n\tvape.Categories.Blatant:CreateModule({\n\t    Name = \"KeepSprint\",\n\t    Function = function(Callback: boolean)\n\t        debug.setconstant(bedwars.SprintController.startSprinting, 5, Callback and \"blockSprinting\" or \"blockSprint\")\n\t        bedwars.SprintController:stopSprinting()\n\t    end,\n\t    Tooltip = \"Lets you sprint with a speed potion.\"\n\t})\nend)\n\nRun(function()\n\tlocal SwordTiming = vape.Libraries.swordtiming\n\tlocal Killaura\n\tlocal Targets\n\tlocal Sort\n\tlocal FastHits\n\tlocal UseSophia\n\tlocal UseWhim\n\tlocal UseNazar\n\tlocal UseUmeko\n\tlocal UseLasso\n\tlocal SwingRange\n\tlocal AttackRange\n\tlocal SwingTime\n\tlocal AttackSpeed\n\tlocal HighHitreg\n\tlocal Hitreg\n\tlocal BurstHits\n\tlocal BurstDelay\n\tlocal AngleSlider\n\tlocal AirHits\n\tlocal MaxTargets\n\tlocal Mouse\n\tlocal AFKCheck\n\tlocal Attackable\n\tlocal Swing\n\tlocal ContinueSwing\n\tlocal GUI\n\tlocal BoxSwingColor\n\tlocal BoxAttackColor\n\tlocal BoxAttackTween\n\tlocal BoxAttackSpeed\n\tlocal BoxAttackSpeedEnd\n\tlocal ParticleTexture\n\tlocal ParticleColor1\n\tlocal ParticleColor2\n\tlocal ParticleSize\n\tlocal Face\n\tlocal Animation\n\tlocal AnimationMode\n\tlocal AnimationSpeed\n\tlocal AnimationTween\n\tlocal Limit\n\tlocal LegitAura\n\tlocal Whitelist\n\tlocal Legit\n\tlocal FireRate\n\tlocal Particles, Boxes = {}, {}\n\tlocal HitRandom: Random = Random.new()\n\tlocal ContinueUntil: number = 0\n\tlocal SwingGap: number = 0.11\n\tlocal LastEffect, LastAttack, OldSwing, SwingHook = 0, 0, nil, nil\n\tlocal EffectSwing: number = 0\n\tlocal Session = nil\n\tlocal GhostDelay, GhostHold, GhostStep = 0, 0, 0\n\tlocal GhostCount, GhostWindow = 0, 0\n\tlocal GhostPending: {number} = {}\n\tlocal HitPending = {}\n\tlocal HitDeadline, TransitMin, ConfirmMin = 0, nil, nil\n\tlocal TransitSamples: {number} = {}\n\tlocal TransitRecent: {number} = {}\n\tlocal HitregTiming = {\n\t    Window = 8,\n\t    FloorWindow = 32,\n\t    ExcessCap = 0.25,\n\t    Spread = 0,\n\t    Noise = 0.03,\n\t    Margin = 0,\n\t    AlignFrames = false,\n\t    MatchTransit = true,\n\t    Peak = 0,\n\t    PeakUntil = 0,\n\t    MarginHold = 2,\n\t    MinimumMargin = 0,\n\t    ColdMargin = 0,\n\t    BootSamples = 0,\n\t    FrameBootSamples = 2,\n\t    LatencyScale = 1,\n\t    RecoveryCap = 0,\n\t    RecoveryStep = 0.015\n\t}\n\tlocal function GetHitLifetime(): number\n\t    return math.max(2, LocalPlayer:GetNetworkPing() * 2 + 0.3, (ConfirmMin or 0) + HitregTiming.Spread + 0.5)\n\tend\n\t\n\tlocal Animations, AnimDelay, AnimTween, ArmC0 = vape.Libraries.auraanims, tick()\n\tlocal ArmWrist: Motor6D?\n\tlocal ArcCheck: RaycastParams = RaycastParams.new()\n\tArcCheck.FilterType = Enum.RaycastFilterType.Exclude\n\tlocal AttackRemote = {FireServer = function() end}\n\tlocal SwordSwingMiss = {FireServer = function() end}\n\tlocal ProjectileRemote = bedwars.Handler:Get(\"ProjectileFire\")\n\tlocal FastHitPending, LastShot = nil, 0\n\tlocal ArrivalFloor: number = SwordTiming.ArrivalFloor\n\tlocal HitBudget, HitFloor, GapFloor = 0.2, SwordTiming.HitFloor, SwordTiming.GapFloor\n\tlocal CleanFloor: number = SwordTiming.HighSpacing\n\tlocal TargetLag: number = 0.12\n\tlocal SelfLag: number = 0.09\n\tlocal SelfLagLow: number = 0.07\n\tlocal SelfLagHigh: number = 0.11\n\tlocal ClaimLag: number = 0.05\n\tlocal ServerReach: number = 3.6\n\tlocal RangeMargin: number = 0.4\n\tlocal ClaimMargin: number = 1\n\tlocal LagCap: number = 8\n\tlocal TrailLength: number = 0.3\n\tlocal TrailTimes: {number} = {}\n\tlocal TrailPositions: {Vector3} = {}\n\tlocal SelfReference = {Low = Vector3.zero, High = Vector3.zero, Claim = Vector3.zero}\n\tlocal BurstShots, BurstWait = 0, 0\n\tlocal FuryScale: number = 1 - (bedwars.BlackMarketeerBalance.FURY_POTION_ATTACK_SPEED_MULTIPLIER - 1)\n\tlocal SwordEffect = getmetatable(bedwars.SwordController).__index.playSwordEffect -- fully detected\n\tlocal ScanInterval: number = 1 / 75\n\tlocal FlatScale: Vector3 = Vector3.new(1, 0, 1)\n\tlocal ParkedPosition: Vector3 = Vector3.new(9e9, 9e9, 9e9)\n\tlocal ParticleShown: {[Part]: boolean} = setmetatable({}, {__mode = \"k\"})\n\t\n\tlocal function IsCombatTarget(Ent): boolean\n\t    local Character: Instance? = Ent.Character\n\t    local Drops: Instance? = workspace:FindFirstChild(\"ItemDrops\")\n\t    return Character ~= nil and Character:IsA(\"Model\") and Character.Parent ~= nil\n\t        and Ent.RootPart ~= nil and Ent.RootPart:IsDescendantOf(Character)\n\t        and Ent.Health > 0 and Ent.Targetable and Entity.isVulnerable(Ent)\n\t        and not Character:HasTag(\"ItemDrop\") and not Ent.RootPart:HasTag(\"ItemDrop\")\n\t        and not (Drops and Character:IsDescendantOf(Drops))\n\tend\n\t\n\tlocal function TrackTrail(Position: Vector3, Now: number)\n\t    local Count: number = #TrailTimes\n\t    if Count > 0 and Now - TrailTimes[Count] > 0.25 then\n\t        table.clear(TrailTimes)\n\t        table.clear(TrailPositions)\n\t    end\n\t    table.insert(TrailTimes, Now)\n\t    table.insert(TrailPositions, Position)\n\t    while #TrailTimes > 2 and Now - TrailTimes[2] >= TrailLength do\n\t        table.remove(TrailTimes, 1)\n\t        table.remove(TrailPositions, 1)\n\t    end\n\tend\n\t\n\tlocal function GetTrailPosition(Moment: number, Fallback: Vector3): Vector3\n\t    local Count: number = #TrailTimes\n\t    if Count == 0 then\n\t        return Fallback\n\t    end\n\t    if Moment <= TrailTimes[1] then\n\t        return TrailPositions[1]\n\t    end\n\t    for i: number = Count, 2, -1 do\n\t        if TrailTimes[i - 1] <= Moment then\n\t            local Span: number = TrailTimes[i] - TrailTimes[i - 1]\n\t            local Alpha: number = Span > 0 and (Moment - TrailTimes[i - 1]) / Span or 1\n\t            return TrailPositions[i - 1]:Lerp(TrailPositions[i], math.clamp(Alpha, 0, 1))\n\t        end\n\t    end\n\t    return TrailPositions[Count]\n\tend\n\t\n\tlocal function UpdateSelfReference(Now: number, Fallback: Vector3)\n\t    SelfReference.Low = GetTrailPosition(Now - SelfLagLow, Fallback)\n\t    SelfReference.High = GetTrailPosition(Now - SelfLagHigh, Fallback)\n\t    SelfReference.Claim = GetTrailPosition(Now - SelfLag, Fallback)\n\tend\n\t\n\tlocal function GetLagOffset(Velocity: Vector3, Lag: number): Vector3\n\t    local Offset: Vector3 = Velocity * Lag\n\t    return Offset.Magnitude > LagCap and Offset.Unit * LagCap or Offset\n\tend\n\t\n\tlocal function GetTargetState(Seen: Vector3, Velocity: Vector3): (Vector3, number)\n\t    local Reference: Vector3 = Seen - GetLagOffset(Velocity, TargetLag)\n\t    local Distance: number = math.max(\n\t        (Seen - SelfReference.Low).Magnitude,\n\t        (Seen - SelfReference.High).Magnitude,\n\t        (Reference - SelfReference.Low).Magnitude,\n\t        (Reference - SelfReference.High).Magnitude\n\t    )\n\t    return Seen - GetLagOffset(Velocity, ClaimLag), Distance\n\tend\n\t\n\tlocal function GetSelfClaim(Claim: Vector3, Reach: number): (Vector3, Vector3)\n\t    local Delta: Vector3 = Claim - SelfReference.Claim\n\t    local Direction: Vector3 = Delta.Magnitude > 0.001 and Delta.Unit or Vector3.new(0, -1, 0)\n\t    return Claim - Direction * math.min(Delta.Magnitude, Reach - ClaimMargin), Direction\n\tend\n\t\n\tlocal function GetRangeLimit(Reach: number): number\n\t    return math.min(AttackRange.Value, Reach + ServerReach - RangeMargin)\n\tend\n\t\n\ttask.spawn(function()\n\t    AttackRemote = bedwars.Handler:Get(\"SwordHit\")\n\t    SwordSwingMiss = bedwars.Handler:Get(\"SwordSwingMiss\")\n\t    HitBudget = 60 / AttackRemote:GetRateLimit()\n\tend)\n\t\n\tlocal FireRates: {[string]: number} = {}\n\t\n\tlocal function GetShots(): {{any}}\n\t    local Shots: {{any}} = getProjectiles(Whitelist.ListEnabled, UseSophia.Enabled, UseWhim.Enabled, UseNazar.Enabled, UseUmeko.Enabled)\n\t    local Lasso = UseLasso.Enabled and getItem(\"lasso\") or nil\n\t    local Source = Lasso and bedwars.ItemMeta.lasso.projectileSource or nil\n\t    if not Source then\n\t        return Shots\n\t    end\n\t\n\t    for _, v: {any} in Shots do\n\t        if v[1].itemType == \"lasso\" then\n\t            return Shots\n\t        end\n\t    end\n\t    table.insert(Shots, {Lasso, \"lasso\", Source.projectileType(\"lasso\"), Source})\n\t    return Shots\n\tend\n\t\n\tlocal function UpdateVisuals(Attacked: {any}, BoxData: {[BoxHandleAdornment]: any})\n\t    for i: number, v: BoxHandleAdornment in Boxes do\n\t        if BoxData[v] == nil and Attacked[i] then\n\t            if vape.ThreadFix then\n\t                setthreadidentity(8)\n\t            end\n\t            v.Size = Vector3.zero\n\t            if vape.ThreadFix then\n\t                setthreadidentity(8)\n\t            end\n\t            local Tween = TweenService:Create(v, TweenInfo.new(BoxAttackSpeed.Value, Enum.EasingStyle[BoxAttackTween.Value]), {\n\t                Size = Vector3.new(4, 6, 4)\n\t            })\n\t            if vape.ThreadFix then\n\t                setthreadidentity(8)\n\t            end\n\t            Tween:Play()\n\t        elseif BoxData[v] and not Attacked[i] then\n\t            if vape.ThreadFix then\n\t                setthreadidentity(8)\n\t            end\n\t            local Tween = TweenService:Create(v, TweenInfo.new(BoxAttackSpeedEnd.Value, Enum.EasingStyle[BoxAttackTween.Value]), {\n\t                Size = Vector3.zero\n\t            })\n\t            if vape.ThreadFix then\n\t                setthreadidentity(8)\n\t            end\n\t            Tween:Play()\n\t        end\n\t        BoxData[v] = Attacked[i] or nil\n\t\n\t        if Attacked[i] then\n\t            if vape.ThreadFix then\n\t                setthreadidentity(8)\n\t            end\n\t            v.Adornee = Attacked[i].Entity.RootPart\n\t            if vape.ThreadFix then\n\t                setthreadidentity(8)\n\t            end\n\t            v.Color3 = Color3.fromHSV(Attacked[i].Check.Hue, Attacked[i].Check.Sat, Attacked[i].Check.Value)\n\t            if vape.ThreadFix then\n\t                setthreadidentity(8)\n\t            end\n\t            v.Transparency = 1 - Attacked[i].Check.Opacity\n\t        end\n\t    end\n\t\n\t    for i: number, v: Part in Particles do\n\t        if Attacked[i] then\n\t            if vape.ThreadFix then\n\t                setthreadidentity(8)\n\t            end\n\t            v.Position = Attacked[i].Entity.RootPart.Position\n\t            if not ParticleShown[v] then\n\t                if vape.ThreadFix then\n\t                    setthreadidentity(8)\n\t                end\n\t                v.Parent = Camera\n\t                ParticleShown[v] = true\n\t            end\n\t        elseif ParticleShown[v] ~= false then\n\t            if vape.ThreadFix then\n\t                setthreadidentity(8)\n\t            end\n\t            v.Position = ParkedPosition\n\t            if vape.ThreadFix then\n\t                setthreadidentity(8)\n\t            end\n\t            v.Parent = nil\n\t            ParticleShown[v] = false\n\t        end\n\t    end\n\tend\n\t\n\tKillaura = vape.Categories.Blatant:CreateModule({\n\t    Name = \"Killaura\",\n\t    Function = function(Callback: boolean)\n\t        if Callback then\n\t            local PreviousSwing = bedwars.SwordController.playSwordEffect\n\t            local Current = {}\n\t            local Hook\n\t            Session = Current\n\t            GhostDelay, GhostHold, GhostStep, GhostCount, GhostWindow = 0, 0, 0, 0, 0\n\t            table.clear(GhostPending)\n\t            table.clear(TransitSamples)\n\t            table.clear(TransitRecent)\n\t            HitregTiming.Spread = 0\n\t            HitregTiming.Peak = 0\n\t            HitregTiming.PeakUntil = 0\n\t            OldSwing = PreviousSwing\n\t            Hook = function(self, SwordMeta, Charged, Config)\n\t                if not Killaura.Enabled or SwingHook ~= Hook then\n\t                    return PreviousSwing(self, SwordMeta, Charged, Config)\n\t                end\n\t                if Config and Config.playAnimation == false then\n\t                    return PreviousSwing(self, SwordMeta, Charged, Config)\n\t                end\n\t                if LegitAura.Enabled then\n\t                    local Clicked: number = bedwars.SwordController.lastSwing\n\t                    if (tick() - LastAttack) < 0.4 and Clicked == EffectSwing then\n\t                        return\n\t                    end\n\t                    EffectSwing = Clicked\n\t                    return PreviousSwing(self, SwordMeta, Charged, Config)\n\t                end\n\t                if ((tick() - LastAttack) < 0.4 or (tick() - AnimDelay) < 0.4) and (tick() - LastEffect) < SwingGap then\n\t                    return\n\t                end\n\t                LastEffect = tick()\n\t                SwingGap = math.max(SwingTime:GetRandomValue(), 0.11)\n\t                return PreviousSwing(self, SwordMeta, Charged, Config)\n\t            end\n\t            SwingHook = Hook\n\t            bedwars.SwordController.playSwordEffect = SwingHook\n\t\n\t            Killaura:Clean(vapeEvents.EntityDamageEvent.Event:Connect(function(DamageTable)\n\t                if DamageTable.fromEntity == LocalPlayer.Character and DamageTable.damageType == 0 and DamageTable.entityInstance then\n\t                    local Stamp = DamageTable.entityInstance:GetAttribute(\"LastDamageTakenTime\")\n\t                    if type(Stamp) == \"number\" and Stamp == Stamp then\n\t                        local Selected: number?\n\t                        local Received: number = os.clock()\n\t                        if HitregTiming.MatchTransit then\n\t                            local Lifetime: number = GetHitLifetime()\n\t                            local Center: number = TransitMin and (TransitMin + HitregTiming.Spread * 0.5) or 0\n\t                            local Best: number = math.huge\n\t                            for Index: number, Entry: any in HitPending do\n\t                                local Elapsed: number = Received - Entry.timer\n\t                                if Entry.target == DamageTable.entityInstance and Elapsed >= 0 and Elapsed < Lifetime then\n\t                                    local Difference: number = TransitMin and math.abs((Stamp - Entry.timer) - Center) or Index - 1\n\t                                    if Difference < Best then\n\t                                        Selected, Best = Index, Difference\n\t                                    end\n\t                                end\n\t                            end\n\t                        else\n\t                            for Index: number = #HitPending, 1, -1 do\n\t                                local Entry = HitPending[Index]\n\t                                if Entry.target == DamageTable.entityInstance and Stamp >= Entry.clock and (Stamp - Entry.clock) < 1 then\n\t                                    Selected = Index\n\t                                    break\n\t                                end\n\t                            end\n\t                        end\n\t                        if Selected then\n\t                            local Entry = HitPending[Selected]\n\t                            local Transit: number = Stamp - (HitregTiming.MatchTransit and Entry.timer or Entry.clock)\n\t                            local Confirmation: number = HitregTiming.MatchTransit and (Received - Entry.timer) or (tick() - Entry.sent)\n\t                            table.insert(TransitSamples, Transit)\n\t                            if #TransitSamples > HitregTiming.Window then\n\t                                table.remove(TransitSamples, 1)\n\t                            end\n\t                            table.insert(TransitRecent, Transit)\n\t                            if #TransitRecent > HitregTiming.FloorWindow then\n\t                                table.remove(TransitRecent, 1)\n\t                            end\n\t                            local TransitFloor: number = Transit\n\t                            for _, Recent: number in TransitRecent do\n\t                                TransitFloor = math.min(TransitFloor, Recent)\n\t                            end\n\t                            local Minimum, Maximum = Transit, Transit\n\t                            for _, Delay: number in TransitSamples do\n\t                                Minimum = math.min(Minimum, Delay)\n\t                                Maximum = math.max(Maximum, Delay)\n\t                            end\n\t                            HitregTiming.Spread = Maximum - Minimum\n\t                            if HitregTiming.MarginHold > 0 and HitregTiming.Spread > HitregTiming.Noise then\n\t                                HitregTiming.Peak = math.max(tick() < HitregTiming.PeakUntil and HitregTiming.Peak or 0, HitregTiming.Spread)\n\t                                HitregTiming.PeakUntil = tick() + HitregTiming.MarginHold\n\t                            end\n\t                            TransitMin = math.min(TransitMin and (TransitMin + 0.001) or Transit, Transit)\n\t                            ConfirmMin = math.min(ConfirmMin and (ConfirmMin + 0.001) or Confirmation, Confirmation)\n\t                            HitDeadline = math.max(HitDeadline, Entry.sent + Entry.gap + math.clamp(Transit - TransitFloor, 0, HitregTiming.ExcessCap))\n\t                            for _ = 1, Selected do\n\t                                table.remove(HitPending, 1)\n\t                            end\n\t                        end\n\t                    end\n\t                end\n\t                if DamageTable.fromEntity == LocalPlayer.Character and DamageTable.damageType == 0 and GhostPending[1] then\n\t                    table.remove(GhostPending, 1)\n\t                end\n\t            end))\n\t\n\t            if Animation.Enabled then\n\t                local FakeKnit = {\n\t                    Controllers = {\n\t                        ViewmodelController = {\n\t                            isVisible = function()\n\t                                return bedwars.ViewmodelController:isVisible()\n\t                            end,\n\t                            playAnimation = function(...)\n\t                                if LegitAura.Enabled or not store.attacking or not (ArmWrist and ArmWrist.Parent) then\n\t                                    bedwars.ViewmodelController:playAnimation(select(2, ...))\n\t                                end\n\t                            end\n\t                        }\n\t                    }\n\t                }\n\t                debug.setupvalue(SwordEffect, 7, FakeKnit)\n\t                debug.setupvalue(bedwars.ScytheController.playLocalAnimation, 3, FakeKnit)\n\t\n\t                task.spawn(function()\n\t                    local Started: boolean = false\n\t                    repeat\n\t                        local Viewmodel: Instance? = Camera:FindFirstChild(\"Viewmodel\")\n\t                        local Hand: Instance? = Viewmodel and Viewmodel:FindFirstChild(\"RightHand\")\n\t                        local Wrist: Motor6D? = Hand and Hand:FindFirstChild(\"RightWrist\")\n\t                        if not Wrist then\n\t                            ArmWrist, ArmC0 = nil, nil\n\t                            Started = false\n\t                            task.wait()\n\t                            continue\n\t                        end\n\t                        if ArmWrist ~= Wrist then\n\t                            ArmWrist, ArmC0 = Wrist, Wrist.C0\n\t                            Started = false\n\t                        end\n\t                        if store.attacking then\n\t                            local First: boolean = not Started\n\t                            Started = true\n\t\n\t                            if AnimationMode.Value == \"Random\" then\n\t                                Animations.Random = {{CFrame = CFrame.Angles(math.rad(math.random(1, 360)), math.rad(math.random(1, 360)), math.rad(math.random(1, 360))), Time = 0.12}}\n\t                            end\n\t\n\t                            for _, v: {CFrame: CFrame, Time: number} in Animations[AnimationMode.Value] do\n\t                                AnimTween = TweenService:Create(ArmWrist, TweenInfo.new(First and (AnimationTween.Enabled and 0.001 or 0.1) or v.Time / AnimationSpeed.Value, Enum.EasingStyle.Linear), {\n\t                                    C0 = ArmC0 * v.CFrame\n\t                                })\n\t                   