hreadFix then\n\t    setthreadidentity(8)\n\tend\n\tFolder.Parent = vape.gui\n\t\n\tlocal function Added(Ent: Instance)\n\t    local NameTag: TextLabel = Instance.new(\"TextLabel\")\n\t    NameTag.TextSize = 14 * Scale.Value\n\t    NameTag.Font = Enum.Font.Arial\n\t    NameTag.Text = bedwars.ItemMeta[Ent.Name] and bedwars.ItemMeta[Ent.Name].displayName or \"Crop\"\n\t    local Size: Vector2 = GetFontBounds(NameTag.Text, NameTag.TextSize, NameTag.FontFace)\n\t    NameTag.Name = Ent.Name\n\t    NameTag.Size = UDim2.fromOffset(Size.X + 8, Size.Y + 7)\n\t    NameTag.AnchorPoint = Vector2.new(0.5, 1)\n\t    NameTag.BackgroundColor3 = Color3.new()\n\t    NameTag.BackgroundTransparency = Transparency.Value\n\t    NameTag.BorderSizePixel = 0\n\t    NameTag.Visible = false\n\t    NameTag.TextColor3 = Color3.fromHSV(Color.Hue, Color.Sat, Color.Value)\n\t    NameTag.RichText = true\n\t    NameTag.Parent = Folder\n\t    Reference[Ent] = NameTag\n\tend\n\t\n\tCropESP = vape.Categories.Render:CreateModule({\n\t    Name = \"CropESP\",\n\t    Function = function(Callback: boolean)\n\t        if Callback then\n\t            for _, v: Instance in CollectionService:GetTagged(\"HarvestableCrop\") do\n\t                Added(v)\n\t            end\n\t            CropESP:Clean(CollectionService:GetInstanceAddedSignal(\"HarvestableCrop\"):Connect(Added))\n\t            CropESP:Clean(CollectionService:GetInstanceRemovedSignal(\"HarvestableCrop\"):Connect(function(Ent: Instance)\n\t                if Reference[Ent] then\n\t                    Reference[Ent]:Destroy()\n\t                    Reference[Ent] = nil\n\t                end\n\t            end))\n\t            CropESP:Clean(RunService.PreRender:Connect(function()\n\t                for Crop: Instance, v: TextLabel in Reference do\n\t                    if not Crop.Parent then\n\t                        v:Destroy()\n\t                        Reference[Crop] = nil\n\t                        continue\n\t                    end\n\t\n\t                    local ScreenPos, Visible = Camera:WorldToViewportPoint((Crop:IsA(\"Model\") and Crop:GetPivot().Position or Crop.Position) + Vector3.new(0, 1, 0))\n\t                    v.Visible = Visible\n\t                    if Visible then\n\t                        v.Position = UDim2.fromOffset(ScreenPos.X, ScreenPos.Y)\n\t                    end\n\t                end\n\t            end))\n\t        else\n\t            for Crop: Instance, v: TextLabel in Reference do\n\t                v:Destroy()\n\t                Reference[Crop] = nil\n\t            end\n\t        end\n\t    end,\n\t    Tooltip = \"Renders crops that are ready to harvest\"\n\t})\n\t\n\tColor = CropESP:CreateColorSlider({\n\t    Name = \"Text Color\",\n\t    Function = function()\n\t        if not CropESP.Enabled then return end\n\t        for _, v: TextLabel in Reference do\n\t            v.TextColor3 = Color3.fromHSV(Color.Hue, Color.Sat, Color.Value)\n\t        end\n\t    end\n\t})\n\tTransparency = CropESP:CreateSlider({\n\t    Name = \"Transparency\",\n\t    Min = 0,\n\t    Max = 1,\n\t    Decimal = 100,\n\t    Function = function(Value: number)\n\t        if not CropESP.Enabled then return end\n\t        for _, v: TextLabel in Reference do\n\t            v.BackgroundTransparency = Value\n\t        end\n\t    end,\n\t    Default = 0.5\n\t})\n\tScale = CropESP:CreateSlider({\n\t    Name = \"Scale\",\n\t    Min = 0.1,\n\t    Max = 1.5,\n\t    Decimal = 10,\n\t    Function = function(Value: number)\n\t        if not CropESP.Enabled then return end\n\t        for _, v: TextLabel in Reference do\n\t            v.TextSize = 14 * Value\n\t            local Size: Vector2 = GetFontBounds(v.Text, v.TextSize, v.FontFace)\n\t            v.Size = UDim2.fromOffset(Size.X + 8, Size.Y + 7)\n\t        end\n\t    end,\n\t    Default = 1\n\t})\nend)\n\nRun(function()\n\tlocal FPSBooster\n\tlocal Cosmetics\n\tlocal Accessories\n\tlocal Animations\n\tlocal Clouds\n\tlocal Quality\n\tlocal Shadows\n\tlocal Lights\n\tlocal Post\n\tlocal Water\n\tlocal Reflections\n\tlocal Compatibility\n\tlocal Kill\n\tlocal Visualizer\n\tlocal Particles\n\tlocal Explosions\n\tlocal Nametags\n\tlocal Hidden: {[Instance]: Instance} = {}\n\tlocal Watching: {[Instance]: RBXScriptConnection} = setmetatable({}, {__mode = \"k\"})\n\tlocal Saved: {[Instance]: {[string]: any}} = {}\n\tlocal Effects = {}\n\tlocal KillEffects, Visualizers = {}, {}\n\tlocal WaterOld\n\tlocal QualityOld\n\tlocal TechnologyOld\n\tlocal NametagOld\n\tlocal PostHook: RBXScriptConnection?\n\tlocal Generation: number = 0\n\tlocal ParticleClasses: {string} = {\"ParticleEmitter\", \"Trail\", \"Beam\", \"Smoke\", \"Fire\", \"Sparkles\"}\n\t\n\tlocal function Override(Object: Instance, Property: string, Value: any)\n\t    local Properties: {[string]: any} = Saved[Object] or {}\n\t    Saved[Object] = Properties\n\t\n\t    if Properties[Property] == nil then\n\t        Properties[Property] = Object[Property]\n\t    end\n\t    Object[Property] = Value\n\tend\n\t\n\tlocal function Pin(Object: Instance, Property: string, Value: any)\n\t    Override(Object, Property, Value)\n\t    FPSBooster:Clean(Object:GetPropertyChangedSignal(Property):Connect(function()\n\t        if Object[Property] ~= Value then\n\t            Saved[Object][Property] = Object[Property]\n\t            Object[Property] = Value\n\t        end\n\t    end))\n\tend\n\t\n\tlocal function SilenceParticle(Object: Instance)\n\t    if not table.find(ParticleClasses, Object.ClassName) or Object.Parent and Object.Parent.Name == \"ProjectileTargeting\" then return end\n\t    Override(Object, \"Enabled\", false)\n\tend\n\t\n\tlocal function Scan(Object: Instance)\n\t    if Particles.Enabled then\n\t        SilenceParticle(Object)\n\t    end\n\t\n\t    if Lights.Enabled and Object:IsA(\"Light\") then\n\t        Override(Object, \"Enabled\", false)\n\t    elseif Reflections.Enabled and Object:IsA(\"BasePart\") and Object.Reflectance > 0 then\n\t        Override(Object, \"Reflectance\", 0)\n\t    elseif Explosions.Enabled and Object:IsA(\"Explosion\") then\n\t        Override(Object, \"Visible\", false)\n\t    end\n\tend\n\t\n\tlocal function Sweep(Current: number)\n\t    local Clock: number = os.clock()\n\t    local Stack: {Instance} = {workspace}\n\t\n\t    while #Stack > 0 do\n\t        local Container: Instance = table.remove(Stack)\n\t        for _, v: Instance in Container:GetChildren() do\n\t            Scan(v)\n\t            table.insert(Stack, v)\n\t\n\t            if os.clock() - Clock > 0.002 then\n\t                task.wait()\n\t                if Generation ~= Current then return end\n\t                Clock = os.clock()\n\t            end\n\t        end\n\t    end\n\tend\n\t\n\tlocal function StripEffect(Effect: Instance)\n\t    if Effects[Effect] ~= nil then return end\n\t    for _, v: Instance in vape.BlurEffects or {} do\n\t        if v == Effect then return end\n\t    end\n\t\n\t    if Effect:IsA(\"PostEffect\") then\n\t        Effects[Effect] = Effect.Enabled\n\t        Effect.Enabled = false\n\t    elseif Effect:IsA(\"Atmosphere\") then\n\t        Effects[Effect] = Effect.Density\n\t        Effect.Density = 0\n\t    end\n\tend\n\t\n\tlocal function SetSpeed(Speed: number)\n\t    for _, v: any in Entity.List do\n\t        if v.Player ~= LocalPlayer then\n\t            local Humanoid: Humanoid? = v.Character:FindFirstChildWhichIsA(\"Humanoid\")\n\t            local Animator: Animator? = Humanoid and Humanoid:FindFirstChildWhichIsA(\"Animator\")\n\t            for _, Track: AnimationTrack in Animator and Animator:GetPlayingAnimationTracks() or {} do\n\t                Track:AdjustSpeed(Speed)\n\t            end\n\t        end\n\t    end\n\tend\n\t\n\tlocal function IsAvatarAccessory(Object: Instance): boolean\n\t    return Object:IsA(\"Accessory\") and not bedwars.ItemMeta[Object.Name] and not Object:GetAttribute(\"ArmorSlot\") and not Object:GetAttribute(\"IsBackpack\") and not Object:GetAttribute(\"NoArmorHide\")\n\tend\n\t\n\tlocal function Strip(Ent, Child: Instance)\n\t    if Cosmetics.Enabled and (Child.Name == \"Clothing\" or Child.Name == \"3DClothing\") then\n\t        Hidden[Child] = Ent.Character\n\t        Child.Parent = nil\n\t    elseif Accessories.Enabled and Ent.Player and IsAvatarAccessory(Child) then\n\t        for _, v: Instance in Child:GetDescendants() do\n\t            if v:IsA(\"BasePart\") then\n\t                Override(v, \"LocalTransparencyModifier\", 1)\n\t            end\n\t        end\n\t    end\n\tend\n\t\n\tlocal function Added(Ent)\n\t    if Ent.Player == LocalPlayer or not (Cosmetics.Enabled or Accessories.Enabled) then return end\n\t\n\t    for _, v: Instance in Ent.Character:GetChildren() do\n\t        Strip(Ent, v)\n\t    end\n\t\n\t    if not Watching[Ent.Character] then\n\t        Watching[Ent.Character] = Ent.Character.ChildAdded:Connect(function(Child: Instance)\n\t            task.defer(function()\n\t                if FPSBooster.Enabled and Child.Parent == Ent.Character then\n\t                    Strip(Ent, Child)\n\t                end\n\t            end)\n\t        end)\n\t    end\n\tend\n\t\n\tlocal function Removed(Ent)\n\t    if Watching[Ent.Character] then\n\t        Watching[Ent.Character]:Disconnect()\n\t        Watching[Ent.Character] = nil\n\t    end\n\t\n\t    for Object: Instance, Parent: Instance in Hidden do\n\t        if Parent == Ent.Character then\n\t            Hidden[Object] = nil\n\t        end\n\t    end\n\tend\n\t\n\tFPSBooster = vape.Categories.Render:CreateModule({\n\t    Name = \"FPSBooster\",\n\t    Function = function(Callback: boolean)\n\t        Generation += 1\n\t\n\t        if Callback then\n\t            if Quality.Enabled then\n\t                pcall(function()\n\t                    QualityOld = settings().Rendering.QualityLevel\n\t                    settings().Rendering.QualityLevel = Enum.QualityLevel.Level01\n\t                end)\n\t            end\n\t\n\t            if Shadows.Enabled then\n\t                Pin(Lighting, \"GlobalShadows\", false)\n\t            end\n\t\n\t            if Reflections.Enabled then\n\t                Pin(Lighting, \"EnvironmentSpecularScale\", 0)\n\t            end\n\t\n\t            if Post.Enabled then\n\t                for _, v: Instance in Lighting:GetChildren() do\n\t                    StripEffect(v)\n\t                end\n\t\n\t                PostHook = Lighting.ChildAdded:Connect(function(Child: Instance)\n\t                    if FPSBooster.Enabled and Post.Enabled then\n\t                        task.defer(StripEffect, Child)\n\t                    end\n\t                end)\n\t            end\n\t\n\t            if Water.Enabled then\n\t                WaterOld = {\n\t                    Size = workspace.Terrain.WaterWaveSize,\n\t                    Speed = workspace.Terrain.WaterWaveSpeed,\n\t                    Reflectance = workspace.Terrain.WaterReflectance,\n\t                    Transparency = workspace.Terrain.WaterTransparency\n\t                }\n\t                workspace.Terrain.WaterWaveSize = 0\n\t                workspace.Terrain.WaterWaveSpeed = 0\n\t                workspace.Terrain.WaterReflectance = 0\n\t                workspace.Terrain.WaterTransparency = 1\n\t            end\n\t\n\t            if Compatibility.Enabled then\n\t                TechnologyOld = Lighting.Technology\n\t                Lighting.Technology = Enum.Technology.Compatibility\n\t            end\n\t\n\t            if Kill.Enabled then\n\t                for Name: string, KillEffect: any in bedwars.KillEffectController.killEffects do\n\t                    if not Name:find(\"Custom\") then\n\t                        KillEffects[Name] = KillEffect\n\t                        bedwars.KillEffectController.killEffects[Name] = {\n\t                            new = function()\n\t                                return {\n\t                                    onKill = function() end,\n\t                                    isPlayDefaultKillEffect = function()\n\t                                        return true\n\t                                    end\n\t                                }\n\t                            end\n\t                        }\n\t                    end\n\t                end\n\t            end\n\t\n\t            if Visualizer.Enabled and bedwars.VisualizerUtils then\n\t                for Name: string, Utility: (...any) -> ...any in bedwars.VisualizerUtils do\n\t                    Visualizers[Name] = Utility\n\t                    bedwars.VisualizerUtils[Name] = function() end\n\t                end\n\t            end\n\t\n\t            if Particles.Enabled or Lights.Enabled or Reflections.Enabled or Explosions.Enabled then\n\t                FPSBooster:Clean(workspace.DescendantAdded:Connect(Scan))\n\t                task.spawn(Sweep, Generation)\n\t            end\n\t\n\t            if Explosions.Enabled then\n\t                local ExplosionFolder: Instance? = workspace:FindFirstChild(\"Explosions\")\n\t                if ExplosionFolder then\n\t                    FPSBooster:Clean(ExplosionFolder.ChildAdded:Connect(function(Child: Instance)\n\t                        task.defer(function()\n\t                            if FPSBooster.Enabled and Explosions.Enabled and Child.Parent == ExplosionFolder then\n\t                                Child.Parent = nil\n\t                            end\n\t                        end)\n\t                    end))\n\t                end\n\t            end\n\t\n\t            if Nametags.Enabled then\n\t                task.spawn(function()\n\t                    repeat task.wait() until Store.matchState ~= 0 or not FPSBooster.Enabled\n\t                    if not FPSBooster.Enabled or not Nametags.Enabled or not bedwars.AppController then return end\n\t\n\t                    NametagOld = bedwars.NametagController.addGameNametag\n\t                    bedwars.NametagController.addGameNametag = function() end\n\t                    for _, v: any in bedwars.AppController:getOpenApps() do\n\t                        if tostring(v):find(\"Nametag\") then\n\t                            bedwars.AppController:closeApp(tostring(v))\n\t                        end\n\t                    end\n\t                end)\n\t            end\n\t\n\t            if Clouds.Enabled then\n\t                local CloudsFolder: Instance? = workspace:FindFirstChild(\"Clouds\")\n\t                if CloudsFolder then\n\t                    Hidden[CloudsFolder] = CloudsFolder.Parent\n\t                    CloudsFolder.Parent = nil\n\t                end\n\t            end\n\t\n\t            if Cosmetics.Enabled or Accessories.Enabled then\n\t                FPSBooster:Clean(Entity.Events.EntityAdded:Connect(Added))\n\t                FPSBooster:Clean(Entity.Events.EntityRemoved:Connect(Removed))\n\t                for _, v: any in Entity.List do\n\t                    Added(v)\n\t                end\n\t            end\n\t\n\t            if Animations.Enabled then\n\t                task.spawn(function()\n\t                    repeat\n\t                        SetSpeed(0)\n\t                        task.wait(0.5)\n\t                    until not FPSBooster.Enabled or not Animations.Enabled\n\t                end)\n\t            end\n\t        else\n\t            if PostHook then\n\t                PostHook:Disconnect()\n\t                PostHook = nil\n\t            end\n\t\n\t            for Effect: Instance, OldValue: boolean | number in Effects do\n\t                if Effect.Parent then\n\t                    if Effect:IsA(\"Atmosphere\") then\n\t                        Effect.Density = OldValue\n\t                    else\n\t                        Effect.Enabled = OldValue\n\t                    end\n\t                end\n\t            end\n\t            table.clear(Effects)\n\t\n\t            for Object: Instance, Properties: {[string]: any} in Saved do\n\t                if Object.Parent then\n\t                    for Property: string, Value: any in Properties do\n\t                        Object[Property] = Value\n\t                    end\n\t                end\n\t            end\n\t            table.clear(Saved)\n\t\n\t            for Name: string, KillEffect: any in KillEffects do\n\t                bedwars.KillEffectController.killEffects[Name] = KillEffect\n\t            end\n\t            table.clear(KillEffects)\n\t\n\t            for Name: string, Utility: (...any) -> ...any in Visualizers do\n\t                bedwars.VisualizerUtils[Name] = Utility\n\t            end\n\t            table.clear(Visualizers)\n\t\n\t            if NametagOld then\n\t                bedwars.NametagController.addGameNametag = NametagOld\n\t                NametagOld = nil\n\t            end\n\t\n\t            if TechnologyOld then\n\t                Lighting.Technology = TechnologyOld\n\t                TechnologyOld = nil\n\t            end\n\t\n\t            if WaterOld then\n\t                workspace.Terrain.WaterWaveSize = WaterOld.Size\n\t                workspace.Terrain.WaterWaveSpeed = WaterOld.Speed\n\t                workspace.Terrain.WaterReflectance = WaterOld.Reflectance\n\t                workspace.Terrain.WaterTransparency = WaterOld.Transparency\n\t                WaterOld = nil\n\t            end\n\t\n\t            for _, v: RBXScriptConnection in Watching do\n\t                v:Disconnect()\n\t            end\n\t            table.clear(Watching)\n\t\n\t            for Object: Instance, Parent: Instance in Hidden do\n\t                if Parent.Parent then\n\t                    Object.Parent = Parent\n\t                end\n\t            end\n\t\n\t            table.clear(Hidden)\n\t            SetSpeed(1)\n\t\n\t            if QualityOld then\n\t                pcall(function()\n\t                    settings().Rendering.QualityLevel = QualityOld\n\t                end)\n\t                QualityOld = nil\n\t            end\n\t        end\n\t    end,\n\t    Tooltip = \"Strips the parts of the scene that actually cost frames\"\n\t})\n\t\n\tCosmetics = FPSBooster:CreateToggle({\n\t    Name = \"Cosmetics\",\n\t    Function = function()\n\t        if FPSBooster.Enabled then\n\t            FPSBooster:Toggle()\n\t            FPSBooster:Toggle()\n\t        end\n\t    end,\n\t    Default = true,\n\t    Tooltip = \"Hides everyone else's skins, the biggest win of the four.\\nBodies and held items stay visible\"\n\t})\n\tAccessories = FPSBooster:CreateToggle({\n\t    Name = \"Accessories\",\n\t    Function = function()\n\t        if FPSBooster.Enabled then\n\t            FPSBooster:Toggle()\n\t            FPSBooster:Toggle()\n\t        end\n\t    end,\n\t    Tooltip = \"Hides everyone else's avatar hats, hair and other accessories.\\nHeld items, armor and backpacks stay visible\"\n\t})\n\tAnimations = FPSBooster:CreateToggle({\n\t    Name = \"Freeze animations\",\n\t    Function = function(Callback: boolean)\n\t        if FPSBooster.Enabled and not Callback then\n\t            SetSpeed(1)\n\t        end\n\t\n\t        if FPSBooster.Enabled and Callback then\n\t            FPSBooster:Toggle()\n\t            FPSBooster:Toggle()\n\t        end\n\t    end,\n\t    Tooltip = \"Stops everyone else animating, they slide around instead.\\nUnverified on your machine, A/B it yourself\"\n\t})\n\tClouds = FPSBooster:CreateToggle({\n\t    Name = \"Clouds\",\n\t    Function = function()\n\t        if FPSBooster.Enabled then\n\t            FPSBooster:Toggle()\n\t            FPSBooster:Toggle()\n\t        end\n\t    end,\n\t    Default = true,\n\t    Tooltip = \"Removes the cloud decoration, around 700 parts on most maps\"\n\t})\n\tQuality = FPSBooster:CreateToggle({\n\t    Name = \"Render quality\",\n\t    Function = function()\n\t        if FPSBooster.Enabled then\n\t            FPSBooster:Toggle()\n\t            FPSBooster:Toggle()\n\t        end\n\t    end,\n\t    Default = true,\n\t    Tooltip = \"Drops the engine render quality to its lowest level\"\n\t})\n\tShadows = FPSBooster:CreateToggle({\n\t    Name = \"Shadows\",\n\t    Function = function()\n\t        if FPSBooster.Enabled then\n\t            FPSBooster:Toggle()\n\t            FPSBooster:Toggle()\n\t        end\n\t    end,\n\t    Default = true,\n\t    Tooltip = \"Turns off global shadows and keeps them off when the game turns them back on\"\n\t})\n\tLights = FPSBooster:CreateToggle({\n\t    Name = \"Lights\",\n\t    Function = function()\n\t        if FPSBooster.Enabled then\n\t            FPSBooster:Toggle()\n\t            FPSBooster:Toggle()\n\t        end\n\t    end,\n\t    Default = true,\n\t    Tooltip = \"Turns off every point, spot and surface light in the map\"\n\t})\n\tPost = FPSBooster:CreateToggle({\n\t    Name = \"Post effects\",\n\t    Function = function()\n\t        if FPSBooster.Enabled then\n\t            FPSBooster:Toggle()\n\t            FPSBooster:Toggle()\n\t        end\n\t    end,\n\t    Default = true,\n\t    Tooltip = \"Turns off sun rays, depth of field and colour correction, whole render passes the card does every frame.\\nThe GUI blur is left alone\"\n\t})\n\tWater = FPSBooster:CreateToggle({\n\t    Name = \"Water\",\n\t    Function = function()\n\t        if FPSBooster.Enabled then\n\t            FPSBooster:Toggle()\n\t            FPSBooster:Toggle()\n\t        end\n\t    end,\n\t    Default = true,\n\t    Tooltip = \"Flattens terrain water, no waves and no reflection.\\nOnly does anything on maps that have water\"\n\t})\n\tReflections = FPSBooster:CreateToggle({\n\t    Name = \"Reflections\",\n\t    Function = function()\n\t        if FPSBooster.Enabled then\n\t            FPSBooster:Toggle()\n\t            FPSBooster:Toggle()\n\t        end\n\t    end,\n\t    Default = true,\n\t    Tooltip = \"Turns off sky reflections and shiny part reflections.\\nThe sky reflections stay off when the game turns them back on\"\n\t})\n\tCompatibility = FPSBooster:CreateToggle({\n\t    Name = \"Compatibility lighting\",\n\t    Function = function()\n\t        if FPSBooster.Enabled then\n\t            FPSBooster:Toggle()\n\t            FPSBooster:Toggle()\n\t        end\n\t    end,\n\t    Default = true,\n\t    Tooltip = \"Drops the map to compatibility lighting, the cheapest renderer Roblox has\"\n\t})\n\tKill = FPSBooster:CreateToggle({\n\t    Name = \"Kill effects\",\n\t    Function = function()\n\t        if FPSBooster.Enabled then\n\t            FPSBooster:Toggle()\n\t            FPSBooster:Toggle()\n\t        end\n\t    end,\n\t    Default = true,\n\t    Tooltip = \"Stops other peoples kill effects from playing\"\n\t})\n\tVisualizer = FPSBooster:CreateToggle({\n\t    Name = \"Visualizer\",\n\t    Function = function()\n\t        if FPSBooster.Enabled then\n\t            FPSBooster:Toggle()\n\t            FPSBooster:Toggle()\n\t        end\n\t    end,\n\t    Default = true,\n\t    Tooltip = \"Turns off the games own visual effect helpers\"\n\t})\n\tParticles = FPSBooster:CreateToggle({\n\t    Name = \"Particles\",\n\t    Function = function()\n\t        if FPSBooster.Enabled then\n\t            FPSBooster:Toggle()\n\t            FPSBooster:Toggle()\n\t        end\n\t    end,\n\t    Default = true,\n\t    Tooltip = \"Stops every particle, trail and beam in the map from rendering\"\n\t})\n\tExplosions = FPSBooster:CreateToggle({\n\t    Name = \"Explosions\",\n\t    Function = function()\n\t        if FPSBooster.Enabled then\n\t            FPSBooster:Toggle()\n\t            FPSBooster:Toggle()\n\t        end\n\t    end,\n\t    Default = true,\n\t    Tooltip = \"Hides TNT, fireball and other explosion effects.\\nThe blast itself still happens\"\n\t})\n\tNametags = FPSBooster:CreateToggle({\n\t    Name = \"Nametags\",\n\t    Function = function()\n\t        if FPSBooster.Enabled then\n\t            FPSBooster:Toggle()\n\t            FPSBooster:Toggle()\n\t        end\n\t    end,\n\t    Default = true,\n\t    Tooltip = \"Hides the game nametags once the match starts\"\n\t})\nend)\n\nRun(function()\n\tlocal GeneratorESP\n\tlocal Transparency\n\tlocal Scale\n\tlocal ShowIron\n\tlocal ShowDiamond\n\tlocal ShowEmerald\n\tlocal Window, InfoLabel\n\tlocal Expanded: boolean = false\n\tlocal Timers = setmetatable({}, {__mode = \"k\"})\n\tlocal Order: {string} = {\"iron\", \"diamond\", \"emerald\"}\n\tlocal Names: {[string]: string} = {\n\t    iron = \"Iron\",\n\t    diamond = \"Diamond\",\n\t    emerald = \"Emerald\"\n\t}\n\tlocal Colors: {[string]: string} = {\n\t    iron = \"rgb(255,255,255)\",\n\t    diamond = \"rgb(85,170,255)\",\n\t    emerald = \"rgb(85,255,85)\"\n\t}\n\t\n\tlocal function IsShown(Resource: string): boolean\n\t    if Resource == \"diamond\" then\n\t        return ShowDiamond.Enabled\n\t    elseif Resource == \"emerald\" then\n\t        return ShowEmerald.Enabled\n\t    end\n\t    return ShowIron.Enabled\n\tend\n\t\n\tlocal function GetResource(Generator: Instance): string?\n\t    local Id: string = Generator:GetAttribute(\"Id\") or \"\"\n\t    local Owner: string? = Id:match(\"^(.-)_generator$\")\n\t    if Owner then\n\t        return Owner == tostring(LocalPlayer:GetAttribute(\"Team\")) and \"iron\" or nil\n\t    end\n\t    return Id:match(\"^(diamond)_\") or Id:match(\"^(emerald)_\")\n\tend\n\t\n\tlocal function GetCountdown(Generator: Instance): number?\n\t    local Label = Timers[Generator]\n\t    if not Label or not Label.Parent then\n\t        local App: Instance? = Generator:FindFirstChild(\"RoactTree\")\n\t        App = App and App:FindFirstChild(\"TeamOreGeneratorApp\")\n\t        Label = App and (App:FindFirstChild(\"Countdown\", true) or App:FindFirstChild(\"Timer\", true))\n\t        Timers[Generator] = Label\n\t    end\n\t\n\t    local Text: string? = Label and Label.Text\n\t    local Seconds: number? = Text and tonumber(Text:match(\"%[([%d%.]+)%]\") or Text:match(\"([%d%.]+)\"))\n\t    return Seconds and math.ceil(Seconds)\n\tend\n\t\n\tlocal function GetStored(Position: Vector3, Resource: string, Drops: {Instance}): number\n\t    local Stored: number = 0\n\t    for _, v: Instance in Drops do\n\t        if v.Name == Resource and v:IsA(\"BasePart\") then\n\t            local Offset: Vector3 = v.Position - Position\n\t            if Vector2.new(Offset.X, Offset.Z).Magnitude <= 6 and Offset.Y >= -12 and Offset.Y <= 4 then\n\t                Stored += v:GetAttribute(\"Amount\") or 1\n\t            end\n\t        end\n\t    end\n\t    return Stored\n\tend\n\t\n\tlocal function Describe(Entry, ShowDistance: boolean): string\n\t    local Parts: {string} = {`{Names[Entry.Resource]} T{Entry.Level}`}\n\t    if Entry.Countdown then\n\t        table.insert(Parts, `{Entry.Countdown}s`)\n\t    end\n\t    table.insert(Parts, `{Entry.Stored} stored`)\n\t    if ShowDistance then\n\t        table.insert(Parts, `{math.floor(Entry.Distance)} studs`)\n\t    end\n\t    return `<font color=\"{Colors[Entry.Resource]}\">{table.concat(Parts, \" | \")}</font>`\n\tend\n\t\n\tlocal function Refresh()\n\t    if not Window then\n\t        return\n\t    end\n\t\n\t    local Origin: Vector3 = Entity.isAlive and Entity.character.RootPart.Position or Camera.CFrame.Position\n\t    local Drops: {Instance} = CollectionService:GetTagged(\"ItemDrop\")\n\t    local Entries = {}\n\t    for _, v: Instance in CollectionService:GetTagged(\"Generator\") do\n\t        local Resource: string? = v:IsA(\"BasePart\") and GetResource(v) or nil\n\t        if Resource and IsShown(Resource) then\n\t            table.insert(Entries, {\n\t                Resource = Resource,\n\t                Level = v:GetAttribute(\"GeneratorLevel\") or 0,\n\t                Countdown = GetCountdown(v),\n\t                Stored = GetStored(v.Position, Resource, Drops),\n\t                Distance = (v.Position - Origin).Magnitude\n\t            })\n\t        end\n\t    end\n\t    table.sort(Entries, function(First, Second): boolean\n\t        return First.Distance < Second.Distance\n\t    end)\n\t\n\t    local Lines: {string} = {\"<b>GeneratorESP</b>\", '<font size=\"4\"> </font>'}\n\t    for _, Resource: string in Order do\n\t        for _, Entry: any in Entries do\n\t            if Entry.Resource == Resource then\n\t                table.insert(Lines, Describe(Entry, false))\n\t                break\n\t            end\n\t        end\n\t    end\n\t    if #Entries == 0 then\n\t        table.insert(Lines, \"No generators\")\n\t    end\n\t\n\t    local ShowList: boolean = Expanded and #Entries > 0\n\t    if ShowList then\n\t        table.insert(Lines, '<font size=\"4\"> </font>')\n\t        for i: number, Entry: any in Entries do\n\t            if i > 8 then\n\t                break\n\t            end\n\t            table.insert(Lines, Describe(Entry, true))\n\t        end\n\t    end\n\t\n\t    InfoLabel.Text = table.concat(Lines, \"\\n\")\n\t    local Bounds: Vector2 = GetFontBounds(RemoveTags(InfoLabel.Text), InfoLabel.TextSize, InfoLabel.FontFace)\n\t    local TitleBounds: Vector2 = GetFontBounds(\"GeneratorESP\", InfoLabel.TextSize, Font.new(InfoLabel.FontFace.Family, Enum.FontWeight.Bold))\n\t    Window.Size = UDim2.fromOffset(math.max(Bounds.X, TitleBounds.X) + 16, Bounds.Y + (ShowList and -8 or 4))\n\tend\n\t\n\tlocal function CreateWindow()\n\t    Window = Instance.new(\"TextButton\")\n\t    Window.Name = \"GeneratorViewer\"\n\t    Window.Position = UDim2.fromOffset(12, 330)\n\t    Window.BackgroundColor3 = Color3.new()\n\t    Window.BackgroundTransparency = Transparency.Value\n\t    Window.Text = \"\"\n\t    Window.AutoButtonColor = false\n\t    Window.Visible = false\n\t    if vape.ThreadFix then\n\t        setthreadidentity(8)\n\t    end\n\t    Window.Parent = vape.gui.ScaledGui\n\t    AddBlur(Window)\n\t    local Corner: UICorner = Instance.new(\"UICorner\")\n\t    Corner.CornerRadius = UDim.new(0, 5)\n\t    Corner.Parent = Window\n\t\n\t    InfoLabel = Instance.new(\"TextLabel\")\n\t    InfoLabel.Size = UDim2.new(1, -16, 1, -16)\n\t    InfoLabel.Position = UDim2.fromOffset(8, 8)\n\t    InfoLabel.BackgroundTransparency = 1\n\t    InfoLabel.TextXAlignment = Enum.TextXAlignment.Left\n\t    InfoLabel.TextYAlignment = Enum.TextYAlignment.Top\n\t    InfoLabel.TextSize = 16 * Scale.Value\n\t    InfoLabel.TextColor3 = Color3.new(1, 1, 1)\n\t    InfoLabel.TextStrokeColor3 = Color3.new()\n\t    InfoLabel.TextStrokeTransparency = 0.8\n\t    InfoLabel.Font = Enum.Font.Arial\n\t    InfoLabel.RichText = true\n\t    InfoLabel.Parent = Window\n\t    GeneratorESP:AddHUD(Window)\n\t\n\t    local PressPosition: UDim2? = nil\n\t    Window.MouseButton1Down:Connect(function()\n\t        PressPosition = Window.Position\n\t    end)\n\t\n\t    Window.MouseButton1Click:Connect(function()\n\t        if PressPosition == Window.Position then\n\t            Expanded = not Expanded\n\t            Refresh()\n\t        end\n\t    end)\n\tend\n\t\n\tGeneratorESP = vape.Categories.Render:CreateModule({\n\t    Name = \"GeneratorESP\",\n\t    Function = function(Callback: boolean)\n\t        if Callback then\n\t            if not Window then\n\t                CreateWindow()\n\t            end\n\t            Window.Visible = true\n\t\n\t            repeat\n\t                Refresh()\n\t                task.wait(0.25)\n\t            until not GeneratorESP.Enabled\n\t        elseif Window then\n\t            Window.Visible = false\n\t        end\n\t    end,\n\t    Tooltip = \"Shows a panel with the nearest generator of each type: its tier, the time until its next drop and how much is waiting at it.\\nClick the panel to list every generator by distance, drag it while the GUI is open to move it.\\nIron only counts your own team's generator\"\n\t})\n\t\n\tTransparency = GeneratorESP:CreateSlider({\n\t    Name = \"Transparency\",\n\t    Min = 0,\n\t    Max = 1,\n\t    Decimal = 100,\n\t    Function = function(Value: number)\n\t        if Window then\n\t            Window.BackgroundTransparency = Value\n\t        end\n\t    end,\n\t    Default = 0.5\n\t})\n\tScale = GeneratorESP:CreateSlider({\n\t    Name = \"Scale\",\n\t    Min = 0.5,\n\t    Max = 1.5,\n\t    Decimal = 10,\n\t    Function = function(Value: number)\n\t        if InfoLabel then\n\t            InfoLabel.TextSize = 16 * Value\n\t            Refresh()\n\t        end\n\t    end,\n\t    Default = 1\n\t})\n\tShowIron = GeneratorESP:CreateToggle({\n\t    Name = \"Show Iron Generator\",\n\t    Function = Refresh,\n\t    Default = true,\n\t    Tooltip = \"Shows your team's iron generator\"\n\t})\n\tShowDiamond = GeneratorESP:CreateToggle({\n\t    Name = \"Show Diamond Generator\",\n\t    Function = Refresh,\n\t    Default = true,\n\t    Tooltip = \"Shows diamond generators, in blue\"\n\t})\n\tShowEmerald = GeneratorESP:CreateToggle({\n\t    Name = \"Show Emerald Generator\",\n\t    Function = Refresh,\n\t    Tooltip = \"Shows emerald generators, in green\"\n\t})\nend)\n\nRun(function()\n\tlocal Headless\n\tlocal Hats\n\t\n\tlocal Hidden: {[Decal]: number} = setmetatable({}, {__mode = \"k\"})\n\tlocal Decals, Handles = {}, {}\n\tlocal Watchers: {RBXScriptConnection} = {}\n\tlocal Head\n\t\n\tlocal function Refresh(Character)\n\t    for _, v: RBXScriptConnection in Watchers do\n\t        v:Disconnect()\n\t    end\n\t\n\t    table.clear(Watchers)\n\t    table.clear(Decals)\n\t    table.clear(Handles)\n\t    Head = Character and Character:FindFirstChild(\"Head\")\n\t    if not Head then return end\n\t\n\t    for _, v: Instance in Head:GetChildren() do\n\t        if v:IsA(\"Decal\") then\n\t            if not Hidden[v] then\n\t                Hidden[v] = v.Transparency\n\t            end\n\t\n\t            table.insert(Decals, v)\n\t            v.Transparency = 1\n\t        end\n\t    end\n\t\n\t    for _, v: Instance in Character:GetChildren() do\n\t        if v:IsA(\"Accessory\") and v.Handle and v.Handle:FindFirstChild(\"HatAttachment\") then\n\t            table.insert(Handles, v.Handle)\n\t        end\n\t    end\n\t\n\t    for _, v: RBXScriptSignal in {Character.ChildAdded, Character.ChildRemoved, Head.ChildAdded} do\n\t        table.insert(Watchers, v:Connect(function()\n\t            task.defer(function()\n\t                if Headless.Enabled and Character.Parent then\n\t                    Refresh(Character)\n\t                end\n\t            end)\n\t        end))\n\t    end\n\tend\n\t\n\tHeadless = vape.Categories.Render:CreateModule({\n\t    Name = \"Headless\",\n\t    Function = function(Callback: boolean)\n\t        if Callback then\n\t            Refresh(Entity.isAlive and LocalPlayer.Character)\n\t\n\t            Headless:Clean(LocalPlayer.CharacterAdded:Connect(function(Character: Model)\n\t                Character:WaitForChild(\"Head\", 5)\n\t                Refresh(Character)\n\t            end))\n\t\n\t            Headless:Clean(RunService.PreRender:Connect(function()\n\t                if not Head then return end\n\t\n\t                Head.LocalTransparencyModifier = 1\n\t                if Hats.Enabled then\n\t                    for _, v: BasePart in Handles do\n\t                        v.LocalTransparencyModifier = 1\n\t                    end\n\t                end\n\t            end))\n\t\n\t            Headless:Clean(function()\n\t                if Head then\n\t                    Head.LocalTransparencyModifier = 0\n\t                end\n\t\n\t                for _, v: Decal in Decals do\n\t                    v.Transparency = Hidden[v] or 0\n\t                end\n\t\n\t                for _, v: BasePart in Handles do\n\t                    v.LocalTransparencyModifier = 0\n\t                end\n\t\n\t                for _, v: RBXScriptConnection in Watchers do\n\t                    v:Disconnect()\n\t                end\n\t\n\t                Head = nil\n\t                table.clear(Watchers)\n\t                table.clear(Decals)\n\t                table.clear(Handles)\n\t            end)\n\t        end\n\t    end,\n\t    Tooltip = \"Hides your own head\"\n\t})\n\tHats = Headless:CreateToggle({\n\t    Name = \"Hide hats\",\n\t    Function = function(Callback: boolean)\n\t        if not Callback then\n\t            for _, v: BasePart in Handles do\n\t                v.LocalTransparencyModifier = 0\n\t            end\n\t        end\n\t    end,\n\t    Default = true,\n\t    Tooltip = \"Hides anything worn on your head too\"\n\t})\nend)\n\nRun(function()\n\tlocal Health\n\t\n\tHealth = vape.Categories.Render:CreateModule({\n\t    Name = \"Health\",\n\t    Function = function(Callback: boolean)\n\t        if Callback then\n\t            local Label: TextLabel = Instance.new(\"TextLabel\")\n\t            Label.Size = UDim2.fromOffset(100, 20)\n\t            Label.Position = UDim2.new(0.5, 6, 0.5, 30)\n\t            Label.BackgroundTransparency = 1\n\t            Label.AnchorPoint = Vector2.new(0.5, 0)\n\t            Label.Text = Entity.isAlive and `{math.round(LocalPlayer.Character:GetAttribute(\"Health\"))} ❤️` or \"\"\n\t            Label.TextColor3 = Entity.isAlive and Color3.fromHSV((LocalPlayer.Character:GetAttribute(\"Health\") / LocalPlayer.Character:GetAttribute(\"MaxHealth\")) / 2.8, 0.86, 1) or Color3.new()\n\t            Label.TextSize = 18\n\t            Label.Font = Enum.Font.Arial\n\t            if vape.ThreadFix then\n\t                setthreadidentity(8)\n\t            end\n\t            Label.Parent = vape.gui\n\t            Health:Clean(Label)\n\t            Health:Clean(VapeEvents.AttributeChanged.Event:Connect(function()\n\t                if vape.ThreadFix then\n\t                    setthreadidentity(8)\n\t                end\n\t\n\t                Label.Text = Entity.isAlive and `{math.round(LocalPlayer.Character:GetAttribute(\"Health\"))} ❤️` or \"\"\n\t                Label.TextColor3 = Entity.isAlive and Color3.fromHSV((LocalPlayer.Character:GetAttribute(\"Health\") / LocalPlayer.Character:GetAttribute(\"MaxHealth\")) / 2.8, 0.86, 1) or Color3.new()\n\t            end))\n\t        end\n\t    end,\n\t    Tooltip = \"Displays your health in the center of your screen.\"\n\t})\n\t\nend)\n\nRun(function()\n\tlocal HitAccuracy\n\tlocal ShowColor\n\tlocal HideUnused\n\tlocal Sources: {string} = {\"ProjectileAura\", \"ProjectileAimbot\", \"SilentAim\", \"TerraAimbot\"}\n\tlocal Rows = {}\n\tlocal Holder: Frame?\n\t\n\tlocal function AddRow(Name: string)\n\t    local Row: Frame = Instance.new(\"Frame\")\n\t    Row.BackgroundTransparency = 1\n\t    Row.Name = Name\n\t    Row.Size = UDim2.new(1, 0, 0, 20)\n\t    Row.Parent = Holder\n\t    local Title: TextLabel = Instance.new(\"TextLabel\")\n\t    Title.BackgroundTransparency = 1\n\t    Title.FontFace = UIPallet.Font\n\t    Title.Position = UDim2.fromOffset(10, 0)\n\t    Title.Size = UDim2.new(1, -20, 1, 0)\n\t    Title.Text = Name\n\t    Title.TextColor3 = Color3.new(1, 1, 1)\n\t    Title.TextSize = 14\n\t    Title.TextStrokeColor3 = Color3.new()\n\t    Title.TextStrokeTransparency = 0.8\n\t    Title.TextXAlignment = Enum.TextXAlignment.Left\n\t    Title.Parent = Row\n\t    local Value: TextLabel = Title:Clone()\n\t    Value.Name = \"Value\"\n\t    Value.Text = \"--\"\n\t    Value.TextXAlignment = Enum.TextXAlignment.Right\n\t    Value.Parent = Row\n\t\n\t    Rows[Name] = {Object = Row, Title = Title, Value = Value}\n\tend\n\t\n\tlocal function Refresh()\n\t    if vape.ThreadFix then\n\t        setthreadidentity(8)\n\t    end\n\t\n\t    local Shown: number = 0\n\t    for _, v: string in Sources do\n\t        local Chance = Store.hitchance[v]\n\t        local Live = Chance and (tick() - Chance.Clock) < 2\n\t        local Row = Rows[v]\n\t        Row.Object.Visible = Live or not HideUnused.Enabled\n\t\n\t        if Row.Object.Visible then\n\t            Row.Object.Position = UDim2.fromOffset(0, 6 + (Shown * 20))\n\t            Row.Value.Text = Live and `{math.round(Chance.Value * 100)}%` or \"--\"\n\t            Row.Value.TextColor3 = (Live and ShowColor.Enabled) and Color3.fromHSV(Chance.Value * 0.33, 0.75, 1) or Color3.new(1, 1, 1)\n\t            Shown += 1\n\t        end\n\t    end\n\t\n\t    Rows.Waiting.Object.Visible = Shown == 0\n\t    Holder.Size = UDim2.fromOffset(190, 12 + (math.max(Shown, 1) * 20))\n\tend\n\t\n\tHitAccuracy = vape:CreateOverlay({\n\t    Name = \"Hit Accuracy\",\n\t    Icon = GetVapeAsset(`{vape.Directory}/assets/new/aim.png`),\n\t    Size = UDim2.fromOffset(18, 12),\n\t    Position = UDim2.fromOffset(11, 14),\n\t    Function = function(Callback: boolean)\n\t        if Callback then\n\t            repeat\n\t                Refresh()\n\t                task.wait(0.05)\n\t            until not HitAccuracy.Button or not HitAccuracy.Button.Enabled\n\t        end\n\t    end\n\t})\n\t\n\tHitAccuracy:CreateFont({\n\t    Name = \"Font\",\n\t    Blacklist = \"Gotham\",\n\t    Function = function(Val: Font)\n\t        for _, v: {Object: Frame, Title: TextLabel, Value: TextLabel} in Rows do\n\t            v.Title.FontFace = Val\n\t            v.Value.FontFace = Val\n\t        end\n\t    end\n\t})\n\tHideUnused = HitAccuracy:CreateToggle({\n\t    Name = \"Hide unused\",\n\t    Function = function()\n\t        if Holder then\n\t            Refresh()\n\t        end\n\t    end,\n\t    Default = true,\n\t    Tooltip = \"Leaves out a module until it is actually aiming at someone\"\n\t})\n\tShowColor = HitAccuracy:CreateToggle({\n\t    Name = \"Color the number\",\n\t    Default = true,\n\t    Tooltip = \"Red through green as the chance climbs\"\n\t})\n\tHitAccuracy:CreateColorSlider({\n\t    Name = \"Background Color\",\n\t    DefaultValue = 0,\n\t    DefaultOpacity = 0.5,\n\t    Function = function(Hue: number, Sat: number, Val: number, Opacity: number)\n\t        if Holder then\n\t            Holder.BackgroundColor3 = Color3.fromHSV(Hue, Sat, Val)\n\t            Holder.BackgroundTransparency = 1 - Opacity\n\t        end\n\t    end\n\t})\n\t\n\tHolder = Instance.new(\"Frame\")\n\tHolder.BackgroundColor3 = Color3.new()\n\tHolder.BackgroundTransparency = 0.5\n\tHolder.Size = UDim2.fromOffset(190, 32)\n\tHolder.Parent = HitAccuracy.Children\n\tlocal Corner: UICorner = Instance.new(\"UICorner\")\n\tCorner.CornerRadius = UDim.new(0, 5)\n\tCorner.Parent = Holder\n\tAddBlur(Holder)\n\tfor _, v: string in Sources do\n\t    AddRow(v)\n\tend\n\tAddRow(\"Waiting\")\n\tRows.Waiting.Object.Position = UDim2.fromOffset(0, 6)\n\tRows.Waiting.Title.Text = \"Hit chance\"\n\tRefresh()\n\tvape:Clean(HitAccuracy.Children:GetPropertyChangedSignal(\"AbsolutePosition\"):Connect(function()\n\t    if vape.ThreadFix then\n\t        setthreadidentity(8)\n\t    end\n\t\n\t    local NewSide: boolean = HitAccuracy.Children.AbsolutePosition.X > (vape.gui.AbsoluteSize.X / 2)\n\t    Holder.AnchorPoint = Vector2.new(NewSide and 1 or 0, 0)\n\t    Holder.Position = UDim2.fromScale(NewSide and 1 or 0, 0)\n\tend))\nend)\n\nRun(function()\n\tlocal InventoryESP\n\tlocal Armor\n\tlocal Empty\n\tlocal BackgroundColor = {}\n\tlocal Window, Headshot, NameTag, Grid, ArmorHolder, ArmorDivider\n\tlocal Slots, ArmorSlots = {}, {}\n\tlocal SlotCount: number = 24\n\tlocal SlotSize: number = 32\n\tlocal SlotPadding: number = 4\n\tlocal Columns: number = 6\n\tlocal HeaderHeight: number = 46\n\t\n\tlocal function CreateSlot(Parent: Instance)\n\t    local Slot: Frame = Instance.new(\"Frame\")\n\t    Slot.Size = UDim2.fromOffset(SlotSize, SlotSize)\n\t    Slot.BackgroundColor3 = Color.Dark(UIPallet.Main, 0.02)\n\t    Slot.BorderSizePixel = 0\n\t    Slot.Visible = false\n\t    Slot.Parent = Parent\n\t    local Corner: UICorner = Instance.new(\"UICorner\")\n\t    Corner.CornerRadius = UDim.new(0, 4)\n\t    Corner.Parent = Slot\n\t    local Stroke: UIStroke = Instance.new(\"UIStroke\")\n\t    Stroke.Color = Color.Light(UIPallet.Main, 0.034)\n\t    Stroke.Parent = Slot\n\t    local Icon: ImageLabel = Instance.new(\"ImageLabel\")\n\t    Icon.Name = \"Icon\"\n\t    Icon.Size = UDim2.fromOffset(SlotSize - 8, SlotSize - 8)\n\t    Icon.Position = UDim2.fromScale(0.5, 0.5)\n\t    Icon.AnchorPoint = Vector2.new(0.5, 0.5)\n\t    Icon.BackgroundTransparency = 1\n\t    Icon.Parent = Slot\n\t    local Amount: TextLabel = Instance.new(\"TextLabel\")\n\t    Amount.Name = \"Amount\"\n\t    Amount.Size = UDim2.fromOffset(SlotSize - 4, 11)\n\t    Amount.Position = UDim2.fromOffset(0, SlotSize - 13)\n\t    Amount.BackgroundTransparency = 1\n\t    Amount.Text = \"\"\n\t    Amount.TextXAlignment = Enum.TextXAlignment.Right\n\t    Amount.TextSize = 11\n\t    Amount.TextColor3 = UIPallet.Text\n\t    Amount.TextStrokeColor3 = Color3.new()\n\t    Amount.TextStrokeTransparency = 0.4\n\t    Amount.FontFace = UIPallet.Font\n\t    Amount.Parent = Slot\n\t    return Slot\n\tend\n\t\n\tlocal function SetSlot(Slot: Frame, Item, Highlight: boolean?)\n\t    if not Item or not Item.itemType then\n\t        Slot.Visible = false\n\t        return\n\t    end\n\t\n\t    Slot.Visible = true\n\t    Slot.Icon.Image = bedwars.getIcon(Item, true)\n\t    Slot.Amount.Text = (Item.amount or 1) > 1 and tostring(Item.amount) or \"\"\n\t    Slot.UIStroke.Color = Highlight and Color3.fromHSV(BackgroundColor.Hue, BackgroundColor.Sat, BackgroundColor.Value) or Color.Light(UIPallet.Main, 0.034)\n\tend\n\t\n\tlocal function Refresh()\n\t    local Ent, Highest = nil, tick()\n\t    for Target: any, Expiry: number in TargetInfo.Targets do\n\t        if Expiry < tick() then\n\t            TargetInfo.Targets[Target] = nil\n\t            continue\n\t        end\n\t        if Expiry > Highest then\n\t            Ent, Highest = Target, Expiry\n\t        end\n\t    end\n\t\n\t    local Player: Player? = Ent and Ent.Player or nil\n\t    local Inventory = Player and Store.inventories[Player] or nil\n\t    if not Ent or (not Inventory and not Empty.Enabled) then\n\t        Window.Visible = false\n\t        return\n\t    end\n\t\n\t    Window.Visible = true\n\t    NameTag.Text = Player and Player.DisplayName or (Ent.Character and Ent.Character.Name) or \"\"\n\t    Headshot.Image = `rbxthumb://type=AvatarHeadShot&id={Player and Player.UserId or 1}&w=420&h=420`\n\t\n\t    Inventory = Inventory or {items = {}, armor = {}}\n\t    local Hand = Inventory.hand\n\t    local Shown: number = 0\n\t    for i: number, v: Frame in Slots do\n\t        local Item = Inventory.items[i]\n\t        SetSlot(v, Item, Item and Hand and Item.tool == Hand.tool)\n\t        if v.Visible then\n\t            Shown = i\n\t        end\n\t    end\n\t\n\t    local Rows: number = math.max(math.ceil(Shown / Columns), 1)\n\t    local GridHeight: number = (Rows * SlotSize) + ((Rows - 1) * SlotPadding)\n\t    Grid.Size = UDim2.new(1, -28, 0, GridHeight)\n\t\n\t    local Height: number = HeaderHeight + 10 + GridHeight + 10\n\t    if Armor.Enabled then\n\t        ArmorDivider.Visible = true\n\t        ArmorHolder.Visible = true\n\t        ArmorDivider.Position = UDim2.fromOffset(0, Height - 1)\n\t\n\t        for i: number = 1, 3 do\n\t            SetSlot(ArmorSlots[i], Inventory.armor[i + 3])\n\t        end\n\t        SetSlot(ArmorSlots[4], Hand, true)\n\t\n\t        ArmorHolder.Position = UDim2.fromOffset(14, Height + 9)\n\t        Height += SlotSize + 19\n\t    else\n\t        ArmorDivider.Visible = false\n\t        ArmorHolder.Visible = false\n\t    end\n\t\n\t    Window.Size = UDim2.fromOffset(240, Height)\n\tend\n\t\n\tInventoryESP = vape.Categories.Render:CreateModule({\n\t    Name = \"InventoryESP\",\n\t    Function = function(Callback: boolean)\n\t        if Callback then\n\t            if not Window then\n\t                Window = Instance.new(\"Frame\")\n\t                Window.Name = \"InventoryESP\"\n\t                Window.Size = UDim2.fromOffset(240, HeaderHeight)\n\t                Window.Position = UDim2.fromOffset(12, 260)\n\t                Window.BackgroundColor3 = Color3.fromHSV(BackgroundColor.Hue, BackgroundColor.Sat, BackgroundColor.Value)\n\t                Window.BackgroundTransparency = 1 - BackgroundColor.Opacity\n\t                Window.Visible = false\n\t                if vape.ThreadFix then\n\t                    setthreadidentity(8)\n\t                end\n\t                Window.Parent = vape.gui.ScaledGui\n\t                AddBlur(Window)\n\t                local Corner: UICorner = Instance.new(\"UICorner\")\n\t                Corner.CornerRadius = UDim.new(0, 5)\n\t                Corner.Parent = Window\n\t\n\t                Headshot = Instance.new(\"ImageLabel\")\n\t                Headshot.Name = \"Headshot\"\n\t                Headshot.Size = UDim2.fromOffset(26, 26)\n\t                Headshot.Position = UDim2.fromOffset(14, 11)\n\t                Headshot.BackgroundColor3 = Color.Dark(UIPallet.Main, 0.02)\n\t                Headshot.Image = \"\"\n\t                Headshot.Parent = Window\n\t                local HeadCorner: UICorner = Instance.new(\"UICorner\")\n\t                HeadCorner.CornerRadius = UDim.new(0, 4)\n\t                HeadCorner.Parent = Headshot\n\t\n\t                NameTag = Instance.new(\"TextLabel\")\n\t                NameTag.Name = \"Name\"\n\t                NameTag.Size = UDim2.new(1, -60, 0, 26)\n\t                NameTag.Position = UDim2.fromOffset(48, 11)\n\t                NameTag.BackgroundTransparency = 1\n\t                NameTag.Text = \"\"\n\t                NameTag.TextXAlignment = Enum.TextXAlignment.Left\n\t                NameTag.TextSize = 13\n\t                NameTag.TextColor3 = UIPallet.Text\n\t                NameTag.TextTruncate = Enum.TextTruncate.AtEnd\n\t                NameTag.FontFace = UIPallet.Font\n\t                NameTag.Parent = Window\n\t\n\t                local Divider: Frame = Instance.new(\"Frame\")\n\t                Divider.Name = \"Divider\"\n\t                Divider.Size = UDim2.new(1, 0, 0, 1)\n\t                Divider.Position = UDim2.fromOffset(0, HeaderHeight - 1)\n\t                Divider.BackgroundColor3 = Color.Light(UIPallet.Main, 0.04)\n\t                Divider.BorderSizePixel = 0\n\t                Divider.Parent = Window\n\t\n\t                Grid = Instance.new(\"Frame\")\n\t                Grid.Name = \"Items\"\n\t                Grid.Size = UDim2.new(1, -28, 0, 0)\n\t                Grid.Position = UDim2.fromOffset(14, HeaderHeight + 10)\n\t                Grid.BackgroundTransparency = 1\n\t                Grid.Parent = Window\n\t                local Layout: UIGridLayout = Instance.new(\"UIGridLayout\")\n\t                Layout.CellSize = UDim2.fromOffset(SlotSize, SlotSize)\n\t                Layout.CellPadding = UDim2.fromOffset(SlotPadding, SlotPadding)\n\t                Layout.SortOrder = Enum.SortOrder.LayoutOrder\n\t                Layout.Parent = Grid\n\t\n\t                for i: number = 1, SlotCount do\n\t                    local Slot: Frame = CreateSlot(Grid)\n\t                    Slot.LayoutOrder = i\n\t                    Slots[i] = Slot\n\t                end\n\t\n\t                ArmorDivider = Instance.new(\"Frame\")\n\t                ArmorDivider.Name = \"ArmorDivider\"\n\t                ArmorDivider.Size = UDim2.new(1, 0, 0, 1)\n\t                ArmorDivider.BackgroundColor3 = Color.Light(UIPallet.Main, 0.04)\n\t                ArmorDivider.BorderSizePixel = 0\n\t                ArmorDivider.Parent = Window\n\t\n\t                ArmorHolder = Instance.new(\"Frame\")\n\t                ArmorHolder.Name = \"Armor\"\n\t                ArmorHolder.Size = UDim2.fromOffset(240, SlotSize)\n\t                ArmorHolder.BackgroundTransparency = 1\n\t                ArmorHolder.Parent = Window\n\t                local ArmorLayout: UIListLayout = Instance.new(\"UIListLayout\")\n\t                ArmorLayout.FillDirection = Enum.FillDirection.Horizontal\n\t                ArmorLayout.Padding = UDim.new(0, SlotPadding)\n\t                ArmorLayout.Parent = ArmorHolder\n\t\n\t                for i: number = 1, 4 do\n\t                    local Slot: Frame = CreateSlot(ArmorHolder)\n\t                    Slot.LayoutOrder = i\n\t                    ArmorSlots[i] = Slot\n\t                end\n\t            end\n\t\n\t            repeat\n\t                Refresh()\n\t                task.wait(0.1)\n\t            until not InventoryESP.Enabled\n\t\n\t            Window.Visible = false\n\t        elseif Window then\n\t            Window.Visible = false\n\t        end\n\t    end,\n\t    Tooltip = \"Shows the inventory of whoever you are currently targeting\"\n\t})\n\t\n\tArmor = InventoryESP:CreateToggle({\n\t    Name = \"Show armor\",\n\t    Function = function()\n\t        if InventoryESP.Enabled then\n\t            Refresh()\n\t        end\n\t    end,\n\t    Default = true\n\t})\n\tEmpty = InventoryESP:CreateToggle({\n\t    Name = \"Show without data\",\n\t    Tooltip = \"Keeps the panel up when the server has not shared their inventory yet\"\n\t})\n\tBackgroundColor = InventoryESP:CreateColorSlider({\n\t    Name = \"Background Color\",\n\t    DefaultValue = 0,\n\t    DefaultOpacity = 0.5,\n\t    Function = function(Hue: number, Sat: number, Val: number, Opacity: number)\n\t        if Window then\n\t            Window.BackgroundColor3 = Color3.fromHSV(Hue, Sat, Val)\n\t            Window.BackgroundTransparency = 1 - Opacity\n\t        end\n\t    end\n\t})\nend)\n\nRun(function()\n\tlocal ItemESP\n\tlocal Distance\n\tlocal Transparency\n\tlocal Scale\n\tlocal Whitelist = {}\n\tlocal Reference = {}\n\tlocal Labels = setmetatable({}, {__mode = \"k\"})\n\tlocal Folder: Folder = Instance.new(\"Folder\")\n\tif vape.ThreadFix then\n\t    setthreadidentity(8)\n\tend\n\tFolder.Parent = vape.gui\n\t\n\tlocal function IsAllowed(Ent: Instance, Name: string): boolean\n\t    if #Whitelist.ListEnabled == 0 then return true end\n\t\n\t    for _, v: string in Whitelist.ListEnabled do\n\t        local Entry: string = v:lower()\n\t        if Entry == Ent.Name:lower() or Entry == Name:lower() then\n\t            return true\n\t        end\n\t    end\n\t    return false\n\tend\n\t\n\tlocal function Added(Ent: Instance)\n\t    local Name: string = bedwars.ItemMeta[Ent.Name] and bedwars.ItemMeta[Ent.Name].displayName or Ent.Name\n\t    if not IsAllowed(Ent, Name) then return end\n\t\n\t    local Amount: number = Ent:GetAttribute(\"Amount\") or 1\n\t    local NameTag: TextLabel = Instance.new(\"TextLabel\")\n\t    NameTag.Name = Name\n\t    NameTag.Text = `{Name}{Amount >= 2 and ` x{Amount}` or \"\"}`\n\t    NameTag.TextSize = 14 * Scale.Value\n\t    NameTag.Font = Enum.Font.Arial\n\t    local Size: Vector2 = GetFontBounds(RemoveTags(NameTag.Text), NameTag.TextSize, NameTag.FontFace)\n\t    NameTag.Size = UDim2.fromOffset(Size.X + 8, Size.Y + 7)\n\t    NameTag.AnchorPoint = Vector2.new(0.5, 1)\n\t    NameTag.BackgroundColor3 = Color3.new()\n\t    NameTag.BackgroundTransparency = Transparency.Value\n\t    NameTag.BorderSizePixel = 0\n\t    NameTag.Visible = false\n\t    NameTag.TextColor3 = Color3.new(1, 1, 1)\n\t    NameTag.RichText = true\n\t    NameTag.Parent = Folder\n\t    Labels[Ent] = nil\n\t    Reference[Ent] = NameTag\n\tend\n\t\n\tItemESP = vape.Categories.Render:CreateModule({\n\t    Name = \"ItemESP\",\n\t    Function = function(Callback: boolean)\n\t        if Callback then\n\t            for _, v: Instance in CollectionService:GetTagged(\"ItemDrop\") do\n\t                Added(v)\n\t            end\n\t            ItemESP:Clean(CollectionService:GetInstanceAddedSignal(\"ItemDrop\"):Connect(Added))\n\t            ItemESP:Clean(CollectionService:GetInstanceRemovedSignal(\"ItemDrop\"):Connect(function(Ent: Instance)\n\t                if Reference[Ent] then\n\t                    Reference[Ent]:Destroy()\n\t                    Reference[Ent] = nil\n\t                end\n\t            end))\n\t            ItemESP:Clean(RunService.PreRender:Connect(function()\n\t                local LocalPosition = Entity.isAlive and Entity.character.RootPart.Position\n\t\n\t                for Item: BasePart, v: TextLabel in Reference do\n\t                    if not Item.Parent then\n\t                        v:Destroy()\n\t                        Reference[Item] = nil\n\t                        continue\n\t                    end\n\t\n\t                    local ItemPosition: Vector3 = Item.Position\n\t                    local ScreenPos, Visible = Camera:WorldToViewportPoint(ItemPosition + Vector3.new(0, 1, 0))\n\t                    local Shown: boolean = Visible and ItemPosition.Y > -200\n\t                    v.Visible = Shown\n\t                    if not Shown then continue end\n\t\n\t                    local Amount: number = Item:GetAttribute(\"Amount\") or 1\n\t                    local ItemDistance: number? = Distance.Enabled and (LocalPosition and math.floor((LocalPosition - ItemPosition).Magnitude) or 0) or nil\n\t                    local Label = Labels[Item]\n\t\n\t                    if not Label or Label.Amount ~= Amount or Label.Distance ~= ItemDistance then\n\t                        local Text: string = `{v.Name}{Amount >= 2 and ` x{Amount}` or \"\"}`\n\t                        if ItemDistance then\n\t                            Text = `<font color=\"rgb(85, 255, 85)\">[</font><font color=\"rgb(255, 255, 255)\">{ItemDistance}</font><font color=\"rgb(85, 255, 85)\">]</font> {Text}`\n\t                        end\n\t\n\t                        Labels[Item] = {Amount = Amount, Distance = ItemDistance}\n\t                        v.Text = Text\n\t                        local Size: Vector2 = GetFontBounds(RemoveTags(Text), v.TextSize, v.FontFace)\n\t                        v.Size = UDim2.fromOffset(Size.X + 8, Size.Y + 7)\n\t                    end\n\t                    v.Position = UDim2.fromOffset(ScreenPos.X, ScreenPos.Y)\n\t                end\n\t            end))\n\t        else\n\t            for Item: Instance, v: TextLabel in Reference do\n\t                v:Destroy()\n\t                Reference[Item] = nil\n\t            end\n\t        end\n\t    end,\n\t    Tooltip = \"Renders tags dropped items\"\n\t})\n\t\n\tDistance = ItemESP:CreateToggle({\n\t    Name = \"Distance\",\n\t    Tooltip = \"Shows the distance of the item\"\n\t})\n\tTransparency = ItemESP:CreateSlider({\n\t    Name = \"Transparency\",\n\t    Min = 0,\n\t    Max = 1,\n\t    Decimal = 100,\n\t    Function = function(Value: number)\n\t        if not ItemESP.Enabled then return end\n\t        for _, v: TextLabel in Reference do\n\t            v.BackgroundTransparency = Value\n\t        end\n\t    end,\n\t    Default = 0.5\n\t})\n\tScale = ItemESP:CreateSlider({\n\t    Name = \"Scale\",\n\t    Min = 0.1,\n\t    Max = 1.5,\n\t    Decimal = 10,\n\t    Function = function(Value: number)\n\t        if not ItemESP.Enabled then return end\n\t        for _, v: TextLabel in Reference do\n\t            v.TextSize = 14 * Value\n\t            local Size: Vector2 = GetFontBounds(RemoveTags(v.Text), v.TextSize, v.FontFace)\n\t            v.Size = UDim2.fromOffset(Size.X + 8, Size.Y + 7)\n\t        end\n\t    end,\n\t    Default = 1\n\t})\n\tWhitelist = ItemESP:CreateTextList({\n\t    Name = \"Allowed items\",\n\t    Function = function()\n\t        if ItemESP.Enabled then\n\t            ItemESP:Toggle()\n\t            ItemESP:Toggle()\n\t        end\n\t    end,\n\t    Darker = true,\n\t    Tooltip = \"Only shows the items in this list, by name or item id.\\nLeave it empty to show every item\"\n\t})\nend)\n\nRun(function()\n\tlocal ItemPlates\n\tlocal Whitelist\n\tlocal Background\n\tlocal Color = {}\n\tlocal Reference = {}\n\tlocal Folder: Folder = Instance.new(\"Folder\")\n\tif vape.ThreadFix then\n\t    setthreadidentity(8)\n\tend\n\tFolder.Parent = vape.gui\n\t\n\tlocal function ScanSide(self, Start: Vector3, Found: {string})\n\t    for _, v: Vector3 in Sides do\n\t        for i: number = 1, 15 do\n\t            local Block: Instance? = GetPlacedBlock(Start + (v * i))\n\t            if not Block or Block == self then break end\n\t            if not Block:GetAttribute(\"NoBreak\") and not table.find(Found, Block.Name) then\n\t                table.insert(Found, Block.Name)\n\t            end\n\t        end\n\t    end\n\tend\n\t\n\tlocal function RefreshAdornee(Billboard: BillboardGui)\n\t    local Adornee: Instance? = Billboard.Adornee\n\t    if not Adornee or not Adornee.Parent then\n\t        Billboard.Enabled = false\n\t        return\n\t    end\n\t\n\t    for _, v: Instance in Billboard.Frame:GetChildren() do\n\t        if v:IsA(\"ImageLabel\") then\n\t            v:Destroy()\n\t        end\n\t    end\n\t\n\t    local AlreadyGot: {string} = {}\n\t    ScanSide(Adornee, Adornee.Position, AlreadyGot)\n\t    ScanSide(Adornee, Adornee.Position + Vector3.new(0, 0, 3), AlreadyGot)\n\t    table.sort(AlreadyGot, function(A: string, B: string)\n\t        local First = bedwars.ItemMeta[A]\n\t        local Second = bedwars.ItemMeta[B]\n\t        return (First and First.block and First.block.health or 0) > (Second and Second.block and Second.block.health or 0)\n\t    end)\n\t    Billboard.Enabled = #AlreadyGot > 0\n\t\n\t    for _, v: string in AlreadyGot do\n\t        local BlockImage: ImageLabel = Instance.new(\"ImageLabel\")\n\t        BlockImage.Size = UDim2.fromOffset(32, 32)\n\t        BlockImage.BackgroundTransparency = 1\n\t        BlockImage.Image = bedwars.getIcon({itemType = v}, true)\n\t        BlockImage.Parent = Billboard.Frame\n\t    end\n\tend\n\t\n\tlocal function Added(Part: Instance)\n\t    if not table.find(Whitelist.ListEnabled, Part.Name) or Reference[Part] then return end\n\t\n\t    local Billboard: BillboardGui = Instance.new(\"BillboardGui\")\n\t    Billboard.Parent = Folder\n\t    Billboard.Name = \"bed\"\n\t    Billboard.StudsOffsetWorldSpace = Vector3.new(0, 3, 0)\n\t    Billboard.Size = UDim2.fromOffset(36, 36)\n\t    Billboard.AlwaysOnTop = true\n\t    Billboard.ClipsDescendants = false\n\t    Billboard.Adornee = Part\n\t    local Blur: ImageLabel = AddBlur(Billboard)\n\t    Blur.Visible = Background.Enabled\n\t    local Frame: Frame = Instance.new(\"Frame\")\n\t    Frame.Size = UDim2.fromScale(1, 1)\n\t    Frame.BackgroundColor3 = Color3.fromHSV(Color.Hue, Color.Sat, Color.Value)\n\t    Frame.BackgroundTransparency = 1 - (Background.Enabled and Color.Opacity or 0)\n\t    Frame.Parent = Billboard\n\t    local Layout: UIListLayout = Instance.new(\"UIListLayout\")\n\t    Layout.FillDirection = Enum.FillDirection.Horizontal\n\t    Layout.Padding = UDim.new(0, 4)\n\t    Layout.VerticalAlignment = Enum.VerticalAlignment.Center\n\t    Layout.HorizontalAlignment = Enum.HorizontalAlignment.Center\n\t    Layout:GetPropertyChangedSignal(\"AbsoluteContentSize\"):Connect(function()\n\t        Billboard.Size = UDim2.fromOffset(math.max(Layout.AbsoluteContentSize.X + 4, 36), 36)\n\t    end)\n\t    Layout.Parent = Frame\n\t    local Corner: UICorner = Instance.new(\"UICorner\")\n\t    Corner.CornerRadius = UDim.new(0, 4)\n\t    Corner.Parent = Frame\n\t    Reference[Part] = Billboard\n\t    RefreshAdornee(Billboard)\n\tend\n\t\n\tItemPlates = vape.Categories.Render:CreateModule({\n\t    Name = \"ItemPlates\",\n\t    Function = function(Callback: boolean)\n\t        if Callback then\n\t            for _, v: Instance in CollectionService:GetTagged(\"block\") do\n\t                task.spawn(Added, v)\n\t            end\n\t            ItemPlates:Clean(VapeEvents.PlaceBlockEvent.Event:Connect(function(Data)\n\t                local Position: Vector3 = Data.blockRef.blockPosition * 3\n\t                for Block: BasePart, v: BillboardGui in Reference do\n\t                    if (Position - Block.Position).Magnitude <= 30 then\n\t                        RefreshAdornee(v)\n\t                    end\n\t                end\n\t            end))\n\t            ItemPlates:Clean(VapeEvents.BreakBlockEvent.Event:Connect(function(Data)\n\t                local Position: Vector3 = Data.blockRef.blockPosition * 3\n\t                for Block: BasePart, v: BillboardGui in Reference do\n\t                    if (Position - Block.Position).Magnitude <= 30 then\n\t                        RefreshAdornee(v)\n\t                    end\n\t                end\n\t            end))\n\t            ItemPlates:Clean(CollectionService:GetInstanceAddedSignal(\"block\"):Connect(Added))\n\t            ItemPlates:Clean(CollectionService:GetInstanceRemovedSignal(\"block\"):Connect(function(Part: Instance)\n\t                if Reference[Part] then\n\t                    Reference[Part]:Destroy()\n\t                    Reference[Part] = nil\n\t                end\n\t            end))\n\t        else\n\t            table.clear(Reference)\n\t            Folder:ClearAllChildren()\n\t        end\n\t    end,\n\t    Tooltip = \"Displays surrounding blocks around the item.\"\n\t})\n\t\n\tWhitelist = ItemPlates:CreateTextList({\n\t    Name = \"Whitelist\",\n\t    Function = function()\n\t        if ItemPlates.Enabled then\n\t            ItemPlates:Toggle()\n\t            ItemPlates:Toggle()\n\t        end\n\t    end,\n\t    Default = {\"beehive\"}\n\t})\n\tBackground = ItemPlates:CreateToggle({\n\t    Name = \"Background\",\n\t    Function = function(Callback: boolean)\n\t        if Color.Object then\n\t            Color.Object.Visible = Callback\n\t        end\n\t        for _, v: BillboardGui in Reference do\n\t            v.Frame.BackgroundTransparency = 1 - (Callback and Color.Opacity or 0)\n\t            v.Blur.Visible = Callback\n\t        end\n\t    end,\n\t    Default = true\n\t})\n\tColor = ItemPlates:CreateColorSlider({\n\t    Name = \"Background Color\",\n\t    DefaultValue = 0,\n\t    DefaultOpacity = 0.5,\n\t    Function = function(Hue: number, Sat: number, Val: number, Opacity: number)\n\t        for _, v: BillboardGui in Reference do\n\t            v.Frame.BackgroundColor3 = Color3.fromHSV(Hue, Sat, Val)\n\t            v.Frame.BackgroundTransparency = 1 - (Background.Enabled and Opacity or 0)\n\t        end\n\t    end,\n\t    Darker = true\n\t})\nend)\n\nRun(function()\n\tlocal KitDisplay\n\tlocal ShowPrevious\n\t\n\tlocal Histories: {[number]: {string}} = {}\n\tlocal Fetching: {[number]: boolean} = {}\n\tlocal Thumbnails: {[number]: string} = {}\n\tlocal Connections: {[Instance]: {RBXScriptConnection}} = {}\n\t\n\tlocal function GetKitImage(Kit: string?): string\n\t    local Meta = bedwars.BedwarsKitMeta[string.split(Kit or \"none\", \",\")[1]] or bedwars.BedwarsKitMeta.none\n\t    return Meta and Meta.renderImage or \"\"\n\tend\n\t\n\tlocal function GetPlayer(Entry: Instance, Name: string): Player?\n\t    for _, v: Player in Players:GetPlayers() do\n\t        if v.Name == Name or v.DisplayName == Name or v:GetAttribute(\"DisguiseDisplayName\") == Name then\n\t            return v\n\t        end\n\t    end\n\t\n\t    local Controller = bedwars.StreamerModeController\n\t    if Controller and type(Controller.getDisplayName) == \"function\" then\n\t        for _, v: Player in Players:GetPlayers() do\n\t            local Success, DisplayName = pcall(Controller.getDisplayName, Controller, v)\n\t            if Success and DisplayName == Name then\n\t                return v\n\t            end\n\t        end\n\t    end\n\t\n\t    local PlayerRender = Entry:FindFirstChild(\"PlayerRender\", true)\n\t    if PlayerRender and PlayerRender:IsA(\"ImageLabel\") and PlayerRender.Image ~= \"\" then\n\t        for _, v: Player in Players:GetPlayers() do\n\t            if not Thumbnails[v.UserId] then\n\t                local Success, Thumbnail, Ready = pcall(Players.GetUserThumbnailAsync, Players, v.UserId, Enum.ThumbnailType.HeadShot, Enum.ThumbnailSize.Size352x352)\n\t                if Success and Ready then\n\t                    Thumbnails[v.UserId] = Thumbnail\n\t                end\n\t            end\n\t            if Thumbnails[v.UserId] == PlayerRender.Image then\n\t                return v\n\t            end\n\t        end\n\t    end\n\t\n\t    if Name == Entry:GetAttribute(\"KitDisplayOriginalName\") then\n\t        return Players:GetPlayerByUserId(Entry:GetAttribute(\"KitDisplayUserId\") or 0)\n\t    end\n\t    return nil\n\tend\n\t\n\tlocal function GetPreviousKits(Player: Player)\n\t    local UserId: number = Player.UserId\n\t    if Histories[UserId] then return Histories[UserId] end\n\t\n\t    local Deadline: number = os.clock() + 15\n\t    while Fetching[UserId] do\n\t        if not KitDisplay.Enabled or os.clock() >= Deadline then return {} end\n\t        task.wait()\n\t    end\n\t    if Histories[UserId] then return Histories[UserId] end\n\t\n\t    Fetching[UserId] = true\n\t    local Success, Kits = pcall(function()\n\t        local Data\n\t        if not canDebug then\n\t            local Remote: Instance? = ReplicatedStorage.rbxts_include.node_modules[\"@rbxts\"].net.out._NetManaged:FindFirstChild(\"RequestMatchHistory\")\n\t            if Remote and Remote:IsA(\"RemoteFunction\") then\n\t                Data = Remote:InvokeServer(Player.Name)\n\t            end\n\t        else\n\t            Data = bedwars.Handler:Get(\"RequestMatchHistory\"):Fire(\"CallServer\", Player.Name)\n\t        end\n\t        if type(Data) ~= \"table\" or type(Data.matchHistory) ~= \"table\" then return nil end\n\t\n\t        local Kits: {string} = {}\n\t        table.sort(Data.matchHistory, function(A, B)\n\t            return (tonumber(A.matchStartTime) or 0) > (tonumber(B.matchStartTime) or 0)\n\t        end)\n\t        for i: number, Match: any in Data.matchHistory do\n\t            if i > 8 then break end\n\t            local Kit: string = \"none\"\n\t            for _, MatchPlayer: any in Match.players or {} do\n\t                if MatchPlayer.playerInfo and MatchPlayer.playerInfo.userId == UserId then\n\t                    Kit = MatchPlayer.bedwars and MatchPlayer.bedwars.kit or \"none\"\n\t                    break\n\t                end\n\t            end\n\t            table.insert(Kits, Kit)\n\t        end\n\t        return Kits\n\t    end)\n\t    Fetching[UserId] = nil\n\t    if Success and type(Kits) == \"table\" then\n\t        Histories[UserId] = Kits\n\t        return Kits\n\t    end\n\t    return {}\n\tend\n\t\n\tlocal function RenderPreviousKits(Card: Instance, Player: Player)\n\t    local Old: Instance? = Card:FindFirstChild(\"PreviousKits\")\n\t    if Old then Old:Destroy() end\n\t    if not ShowPrevious.Enabled then return end\n\t\n\t    local Holder: Frame = Instance.new(\"Frame\")\n\t    Holder.Name = \"PreviousKits\"\n\t    Holder.AnchorPoint = Vector2.new(0.5, 0)\n\t    Holder.Position = UDim2.fromScale(0.5, 0.03)\n\t    Holder.Size = UDim2.fromScale(0.86, 0.24)\n\t    Holder.BackgroundColor3 = Color3.new()\n\t    Holder.BackgroundTransparency = 1\n\t    Holder.BorderSizePixel = 0\n\t    Holder.ClipsDescendants = true\n\t    Holder.ZIndex = 3\n\t    Holder.Parent = Card\n\t    KitDisplay:Clean(Holder)\n\t\n\t    local Corner: UICorner = Instance.new(\"UICorner\")\n\t    Corner.CornerRadius = UDim.new(0, 4)\n\t    Corner.Parent = Holder\n\t\n\t    local Padding: UIPadding = Instance.new(\"UIPadding\")\n\t    Padding.PaddingLeft = UDim.new(0, 3)\n\t    Padding.PaddingRight = UDim.new(0, 3)\n\t    Padding.Parent = Holder\n\t\n\t    local Layout: UIListLayout = Instance.new(\"UIListLayout\")\n\t    Layout.FillDirection = Enum.FillDirection.Horizontal\n\t    Layout.HorizontalAlignment = Enum.HorizontalAlignment.Center\n\t    Layout.VerticalAlignment = Enum.VerticalAlignment.Center\n\t    Layout.Padding = UDim.new(0, 2)\n\t    Layout.SortOrder = Enum.SortOrder.LayoutOrder\n\t    Layout.Parent = Holder\n\t\n\t    local Kits: {string} = GetPreviousKits(Player)\n\t    if not KitDisplay.Enabled or not ShowPrevious.Enabled or not Holder.Parent then return end\n\t    if #Kits == 0 then\n\t        Holder:Destroy()\n\t        return\n\t    end\n\t    Holder.BackgroundTransparency = 1\n\t    for i: number, Kit: string in Kits do\n\t        local Icon: ImageLabel = Instance.new(\"ImageLabel\")\n\t        Icon.Name = `Kit{i}`\n\t        Icon.LayoutOrder = i\n\t        Icon.Size = UDim2.fromScale(1, 1)\n\t        Icon.SizeConstraint = Enum.SizeConstraint.RelativeYY\n\t        Icon.BackgroundTransparency = 1\n\t        Icon.Image = GetKitImage(Kit)\n\t        Icon.ScaleType = Enum.ScaleType.Fit\n\t        Icon.ZIndex = 4\n\t        Icon.Parent = Holder\n\t        local Order: TextLabel = Instance.new(\"TextLabel\")\n\t        Order.Name = \"Order\"\n\t        Order.Position = UDim2.fromOffset(1, 1)\n\t        Order.Size = UDim2.fromOffset(13, 13)\n\t        Order.BackgroundColor3 = Color3.new()\n\t        Order.BackgroundTransparency = 1\n\t        Order.BorderSizePixel = 0\n\t        Order.FontFace = UIPallet.FontBold\n\t        Order.Text = tostring(i)\n\t        Order.TextColor3 = Color3.new(1, 1, 1)\n\t        Order.TextSize = 9\n\t        Order.ZIndex = 5\n\t        Order.Parent = Icon\n\t        local OrderCorner: UICorner = Instance.new(\"UICorner\")\n\t        OrderCorner.CornerRadius = UDim.new(0, 4)\n\t        OrderCorner.Parent = Order\n\t    end\n\tend\n\t\n\tlocal function RenderKit(Entry: Instance)\n\t    task.wait(0.3)\n\t    if not KitDisplay.Enabled or not Entry.Parent then return end\n\t    local PlayerName = Entry:FindFirstChild(\"PlayerName\", true)\n\t    if not PlayerName then return end\n\t\n\t    local OriginalName: string = PlayerName:GetAttribute(\"NickHiderOriginalText\") or PlayerName.Text\n\t    local Player: Player? = GetPlayer(Entry, OriginalName)\n\t    if not KitDisplay.Enabled or not Entry.Parent then return end\n\t    if not Player then return end\n\t\n\t    local Frame: Instance? = Entry:FindFirstChild(\"1\")\n\t    local Card: Instance? = Frame and Frame:FindFirstChild(\"MatchDraftPlayerCard\")\n\t    if not Card then return end\n\t\n\t    for _, Connection: RBXScriptConnection in Connections[Entry] or {} do\n\t        Connection:Disconnect()\n\t    end\n\t\n\t    local Roact = Card:FindFirstChild(\"KitImage\")\n\t    if not Roact then\n\t        Roact = Instance.new(\"ImageLabel\")\n\t        Roact.BackgroundTransparency = 1\n\t        Roact.AnchorPoint = Vector2.new(1, 0.5)\n\t        Roact.Position = UDim2.fromScale(1.05, 0)\n\t        Roact.Name = \"KitImage\"\n\t        Roact.Size = UDim2.fromScale(1.5, 1.5)\n\t        Roact.ZIndex = 1\n\t        Roact.ImageTransparency = 0.4\n\t        Roact.SliceCenter = Rect.new(0, 0, 0, 0)\n\t        Roact.SliceScale = 1\n\t        Roact.ScaleType = Enum.ScaleType.Crop\n\t        Roact.Parent = Card\n\t        KitDisplay:Clean(Roact)\n\t\n\t        local Ratio: UIAspectRatioConstraint = Instance.new(\"UIAspectRatioConstraint\")\n\t        Ratio.Name = \"1\"\n\t        Ratio.AspectRatio = 1\n\t        Ratio.AspectType = Enum.AspectType.FitWithinMaxSize\n\t        Ratio.DominantAxis = Enum.DominantAxis.Width\n\t        Ratio.Parent = Roact\n\t    end\n\t\n\t    Roact.Image = GetKitImage(Player:GetAttribute(\"PlayingAsKits\"))\n\t    Roact.Position = UDim2.fromScale(1.05, 0)\n\t    TweenService:Create(Roact, TweenInfo.new(0.2, Enum.EasingStyle.Cubic, Enum.EasingDirection.Out), {\n\t        Position = UDim2.fromScale(1.05, 0.5)\n\t    }):Play()\n\t    task.spawn(RenderPreviousKits, Card, Player)\n\t\n\t    Entry:SetAttribute(\"KitDisplayUserId\", Player.UserId)\n\t    Entry:SetAttribute(\"KitDisplayOriginalName\", OriginalName)\n\t    local Connection: RBXScriptConnection? = Player:GetAttributeChangedSignal(\"PlayingAsKits\"):Connect(function()\n\t        if not KitDisplay.Enabled or not Roact.Parent then return end\n\t        Roact.Image = GetKitImage(Player:GetAttribute(\"PlayingAsKits\"))\n\t        Roact.Position = UDim2.fromScale(1.05, 0)\n\t        TweenService:Create(Roact, TweenInfo.new(0.2, Enum.EasingStyle.Cubic, Enum.EasingDirection.Out), {\n\t            Position = UDim2.fromScale(1.05, 0.5)\n\t        }):Play()\n\t    end)\n\t    local NameConnection: RBXScriptConnection = PlayerName:GetPropertyChangedSignal(\"Text\"):Once(function()\n\t        if Connection then\n\t            Connection:Disconnect()\n\t            Connection = nil\n\t        end\n\t        RenderKit(Entry)\n\t    end)\n\t    Connections[Entry] = {Connection, NameConnection}\n\t    KitDisplay:Clean(NameConnection)\n\t    KitDisplay:Clean(Connection)\n\tend\n\t\n\tKitDisplay = vape.Categories.Render:CreateModule({\n\t    Name = \"KitDisplay\",\n\t    Function = function(Callback: boolean)\n\t        if Callback then\n\t            local BodyContainer\n\t            repeat\n\t                local App: Instance? = LocalPlayer.PlayerGui:FindFirstChild(\"MatchDraftApp\")\n\t                local Background: Instance? = App and App:FindFirstChild(\"DraftAppBackground\")\n\t                local Frame: Instance? = Background and Background:FindFirstChild(\"1\")\n\t                BodyContainer = Frame and Frame:FindFirstChild(\"BodyContainer\")\n\t                if not BodyContainer then task.wait(0.1) end\n\t            until BodyContainer or not KitDisplay.Enabled\n\t\n\t            if not KitDisplay.Enabled or not BodyContainer then return end\n\t\n\t            for Team: number = 1, 2 do\n\t                if not KitDisplay.Enabled then break end\n\t                local Column: Instance?\n\t                local Deadline: number = tick() + 10\n\t                repeat\n\t                    Column = BodyContainer:FindFirstChild(`Team{Team}Column`)\n\t                    if not Column then task.wait(0.1) end\n\t                until Column or not KitDisplay.Enabled or tick() >= Deadline\n\t\n\t                if Column then\n\t                    KitDisplay:Clean(Column.ChildAdded:Connect(RenderKit))\n\t                    for _, v: Instance in Column:GetChildren() do\n\t                        task.spawn(RenderKit, v)\n\t                    end\n\t                end\n\t            end\n\t        else\n\t            table.clear(Connections)\n\t        end\n\t    end,\n\t    Tooltip = \"Allows you to view opponent's kit in match draft.\"\n\t})\n\t\n\tShowPrevious = KitDisplay:CreateToggle({\n\t    Name = \"Show previous kits\",\n\t    Function = function()\n\t        if KitDisplay.Enabled then\n\t            KitDisplay:Toggle()\n\t            KitDisplay:Toggle()\n\t        end\n\t    end,\n\t    Default = true,\n\t    Tooltip = \"Shows the kits each player used in their last 8 games, newest first\"\n\t})\nend)\n\nRun(function()\n\tlocal KitESP\n\tlocal Background\n\tlocal Color = {}\n\tlocal Scale\n\tlocal Reference = {}\n\tlocal Connections: {RBXScriptConnection} = {}\n\tlocal Folder: Folder = Instance.new(\"Folder\")\n\tif vape.ThreadFix then\n\t    setthreadidentity(8)\n\tend\n\tFolder.Parent = vape.gui\n\t\n\tlocal ESPKits: {[string]: {string}} = {\n\t    alchemist = {\"alchemist_ingedients\", \"wild_flower\"},\n\t    beekeeper = {\"bee\", \"bee\"},\n\t    bigman = {\"treeOrb\", \"natures_essence_1\"},\n\t    ghost_catcher = {\"ghost\", \"ghost_orb\"},\n\t    metal_detector = {\"hidden-metal\", \"iron\"},\n\t    sheep_herder = {\"SheepModel\", \"purple_hay_bale\"},\n\t    sorcerer = {\"alchemy_crystal\", \"wild_flower\"},\n\t    star_collector = {\"stars\", \"crit_star\"}\n\t}\n\t\n\tlocal function Added(Ent: Instance, Icon: string)\n\t    local Part = Ent:IsA(\"BasePart\") and Ent or Ent:IsA(\"Model\") and (Ent.PrimaryPart or Ent:FindFirstChild(\"Root\") or Ent:FindFirstChildWhichIsA(\"BasePart\"))\n\t    if not Part or Reference[Ent] then return end\n\t\n\t    local Billboard: BillboardGui = Instance.new(\"BillboardGui\")\n\t    Billboard.Name = Icon\n\t    Billboard.StudsOffsetWorldSpace = Vector3.new(0, 3, 0)\n\t    Billboard.Size = UDim2.fromOffset(36 * Scale.Value, 36 * Scale.Value)\n\t    Billboard.AlwaysOnTop = true\n\t    Billboard.ClipsDescendants = false\n\t    Billboard.Adornee = Part\n\t    Billboard.Parent = Folder\n\t    local Blur: ImageLabel = AddBlur(Billboard)\n\t    Blur.Size = UDim2.new(1, 89 * Scale.Value, 1, 52 * Scale.Value)\n\t    Blur.Position = UDim2.fromOffset(-48 * Scale.Value, -31 * Scale.Value)\n\t    Blur.Visible = Background.Enabled\n\t    local Image: ImageLabel = Instance.new(\"ImageLabel\")\n\t    Image.Size = UDim2.fromOffset(36 * Scale.Value, 36 * Scale.Value)\n\t    Image.Position = UDim2.fromScale(0.5, 0.5)\n\t    Image.AnchorPoint = Vector2.new(0.5, 0.5)\n\t    Image.BackgroundColor3 = Color3.fromHSV(Color.Hue, Color.Sat, Color.Value)\n\t    Image.BackgroundTransparency = 1 - (Background.Enabled and Color.Opacity or 0)\n\t    Image.BorderSizePixel = 0\n\t    Image.Image = bedwars.getIcon({itemType = Icon}, true)\n\t    Image.Parent = Billboard\n\t    local Corner: UICorner = Instance.new(\"UICorner\")\n\t    Corner.CornerRadius = UDim.new(0, 4)\n\t    Corner.Parent = Image\n\t    Reference[Ent] = Billboard\n\tend\n\t\n\tlocal function Clear()\n\t    for _, v: RBXScriptConnection in Connections do\n\t        v:Disconnect()\n\t    end\n\t    table.clear(Connections)\n\t    table.clear(Reference)\n\t    Folder:ClearAllChildren()\n\tend\n\t\n\tlocal function Watch(Kit: {string})\n\t    table.insert(Connections, CollectionService:GetInstanceAddedSignal(Kit[1]):Connect(function(Ent: Instance)\n\t        Added(Ent, Kit[2])\n\t    end))\n\t    table.insert(Connections, CollectionService:GetInstanceRemovedSignal(Kit[1]):Connect(function(Ent: Instance)\n\t        if Reference[Ent] then\n\t            Reference[Ent]:Destroy()\n\t            Reference[Ent] = nil\n\t        end\n\t    end))\n\t    for _, v: Instance in CollectionService:GetTagged(Kit[1]) do\n\t        Added(v, Kit[2])\n\t    end\n\tend\n\t\n\tKitESP = vape.Categories.Render:CreateModule({\n\t    Name = \"KitESP\",\n\t    Function = function(Callback: boolean)\n\t        if Callback then\n\t            local Current: string?\n\t            repeat\n\t                local Kits: {string} = Store.equippedKits or {}\n\t                local Key: string = table.concat(Kits, \",\")\n\t                if Key ~= Current then\n\t                    Current = Key\n\t                    Clear()\n\t\n\t                    for _, v: string in Kits do\n\t                        local Kit: {string}? = ESPKits[v]\n\t                        if Kit then\n\t                            Watch(Kit)\n\t                        end\n\t                    end\n\t                end\n\t                task.wait(1)\n\t            until not KitESP.Enabled\n\t        else\n\t            Clear()\n\t        end\n\t    end,\n\t    Tooltip = \"ESP for certain kit related objects, for every kit you have (both kits in Kit Fusion)\"\n\t})\n\t\n\tBackground = KitESP:CreateToggle({\n\t    Name = \"Background\",\n\t    Function = function(Callback: boolean)\n\t        if Color.Object then\n\t            Color.Object.Visible = Callback\n\t        end\n\t        for _, v: BillboardGui in Reference do\n\t            v.ImageLabel.BackgroundTransparency = 1 - (Callback and Color.Opacity or 0)\n\t            v.Blur.Visible = Callback\n\t        end\n\t    end,\n\t    Default = true\n\t})\n\tColor = KitESP:CreateColorSlider({\n\t    Name = \"Background Color\",\n\t    DefaultValue = 0,\n\t    DefaultOpacity = 0.5,\n\t    Function = function(Hue: number, Sat: number, Val: number, Opacity: number)\n\t        for _, v: BillboardGui in Reference do\n\t            v.ImageLabel.BackgroundColor3 = Color3.fromHSV(Hue, Sat, Val)\n\t            v.ImageLabel.BackgroundTransparency = 1 - (Background.Enabled and Opacity or 0)\n\t        end\n\t    end,\n\t    Darker = true\n\t})\n\tScale = KitESP:CreateSlider({\n\t    Name = \"Scale\",\n\t    Function = function(Val: number)\n\t        for _, v: BillboardGui in Reference do\n\t            v.Size = UDim2.fromOffset(36 * Val, 36 * Val)\n\t            v.ImageLabel.Size = UDim2.fromOffset(36 * Val, 36 * Val)\n\t            v.Blur.Size = UDim2.new(1, 89 * Val, 1, 52 * Val)\n\t            v.Blur.Position = UDim2.fromOffset(-48 * Val, -31 * Val)\n\t        end\n\t    end,\n\t    Default = 1,\n\t    Min = 0.1,\n\t    Max = 1.5,\n\t    Decimal = 10\n\t})\nend)\n\nRun(function()\n\tlocal NameTags\n\tlocal Targets\n\tlocal Color\n\tlocal Background\n\tlocal DisplayName\n\tlocal Health\n\tlocal Distance\n\tlocal Rank\n\tlocal Enchant\n\tlocal Equipment\n\tlocal Inventory\n\tlocal InventoryList\n\tlocal DrawingToggle\n\tlocal Scale\n\tlocal FontOption\n\tlocal Teammates\n\tlocal DistanceCheck\n\tlocal DistanceLimit\n\tlocal Strings, Sizes, Reference, Refreshes = {}, {}, {}, {}\n\tif vape.ThreadFix then\n\t    setthreadidentity(8)\n\tend\n\t\n\tlocal Folder: Folder = Instance.new(\"Folder\")\n\tif vape.ThreadFix then\n\t    setthreadidentity(8)\n\tend\n\tFolder.Parent = vape.gui\n\tlocal MethodUsed: string\n\t\n\tlocal function UpdateInventory(Ent, NameTag: TextLabel)\n\t    local Holder = Ent.Player and NameTag:FindFirstChild(\"Inventory\")\n\t    local PlayerInventory = Holder and Store.inventories[Ent.Player]\n\t    if not PlayerInventory then return end\n\t\n\t    local Shown: number = 0\n\t    for _, v: any in PlayerInventory.items or {} do\n\t        if #InventoryList.ListEnabled > 0 and not table.find(InventoryList.ListEnabled, v.itemType) then continue end\n\t\n\t        Shown += 1\n\t        local Icon = Holder:FindFirstChild(tostring(Shown))\n\t        if not Icon then\n\t            Icon = Instance.new(\"ImageLabel\")\n\t            Icon.Name = tostring(Shown)\n\t            Icon.Size = UDim2.fromOffset(24, 24)\n\t            Icon.BackgroundTransparency = 1\n\t            Icon.Parent = Holder\n\t            local Amount: TextLabel = Instance.new(\"TextLabel\")\n\t            Amount.Name = \"Amount\"\n\t            Amount.Size = UDim2.fromOffset(23, 11)\n\t            Amount.Position = UDim2.fromOffset(0, 13)\n\t            Amount.BackgroundTransparency = 1\n\t            Amount.FontFace = NameTag.FontFace\n\t            Amount.TextSize = 11\n\t            Amount.TextColor3 = Color3.new(1, 1, 1)\n\t            Amount.TextStrokeColor3 = Color3.new()\n\t            Amount.TextStrokeTransparency = 0.4\n\t            Amount.TextXAlignment = Enum.TextXAlignment.Right\n\t            Amount.Parent = Icon\n\t        end\n\t\n\t        Icon.LayoutOrder = Shown\n\t        Icon.Visible = true\n\t        Icon.Image = bedwars.getIcon(v, true)\n\t        Icon.Amount.Text = (v.amount or 1) > 1 and tostring(v.amount) or \"\"\n\t    end\n\t\n\t    for _, v: Instance in Holder:GetChildren() do\n\t        if v:IsA(\"ImageLabel\") and tonumber(v.Name) > Shown then\n\t            v.Visible = false\n\t        end\n\t    end\n\tend\n\t\n\tlocal Added = {\n\t    Normal = function(Ent)\n\t        if not Targets.Players.Enabled and Ent.Player then return end\n\t        if not Targets.NPCs.Enabled and Ent.NPC then return end\n\t        if Teammates.Enabled and (not Ent.Targetable) and (not Ent.Friend) then return end\n\t\n\t        local NameTag: TextLabel = Instance.new(\"TextLabel\")\n\t        Strings[Ent] = Ent.Player and `{Whitelist:tag(Ent.Player, true, true)}{DisplayName.Enabled and Ent.Player.DisplayName or Ent.Player.Name}` or Ent.Character.Name\n\t\n\t        if Health.Enabled then\n\t            local HealthColor: Color3 = Color3.fromHSV(math.clamp(Ent.Health / Ent.MaxHealth, 0, 1) / 2.5, 0.89, 0.75)\n\t            Strings[Ent] = `{Strings[Ent]} <font color=\"rgb({math.floor(HealthColor.R * 255)},{math.floor(HealthColor.G * 255)},{math.floor(HealthColor.B * 255)})\">{math.round(Ent.Health)}</font>`\n\t        end\n\t\n\t        if Distance.Enabled then\n\t            Strings[Ent] = `<font color=\"rgb(85, 255, 85)\">[</font><font color=\"rgb(255, 255, 255)\">%s</font><font color=\"rgb(85, 255, 85)\">]</font> {Strings[Ent]}`\n\t        end\n\t\n\t        if Equipment.Enabled then\n\t            for i: number, Slot: string in {\"Hand\", \"Helmet\", \"Chestplate\", \"Boots\", \"Kit\"} do\n\t                local Icon: ImageLabel = Instance.new(\"ImageLabel\")\n\t                Icon.Name = Slot\n\t                Icon.Size = UDim2.fromOffset(30, 30)\n\t                Icon.Position = UDim2.fromOffset(-60 + (i * 30), -30)\n\t                Icon.BackgroundTransparency = 1\n\t                Icon.Image = \"\"\n\t                Icon.Parent = NameTag\n\t            end\n\t        end\n\t\n\t        if Inventory.Enabled and Ent.Player then\n\t            local Holder: Frame = Instance.new(\"Frame\")\n\t            Holder.Name = \"Inventory\"\n\t            Holder.AnchorPoint = Vector2.new(0.5, 0)\n\t            Holder.AutomaticSize = Enum.AutomaticSize.X\n\t            Holder.BackgroundTransparency = 1\n\t            Holder.Position = UDim2.new(0.5, 0, 1, 2)\n\t            Holder.Size = UDim2.fromOffset(0, 24)\n\t            Holder.Parent = NameTag\n\t            local Layout: UIListLayout = Instance.new(\"UIListLayout\")\n\t            Layout.FillDirection = Enum.FillDirection.Horizontal\n\t            Layout.HorizontalAlignment = Enum.HorizontalAlignment.Center\n\t            Layout.Padding = UDim.new(0, 2)\n\t            Layout.SortOrder = Enum.SortOrder.LayoutOrder\n\t            Layout.Parent = Holder\n\t        end\n\t\n\t        local TagScale: UIScale = Instance.new(\"UIScale\")\n\t        TagScale.Scale = Scale.Value\n\t        TagScale.Parent = NameTag\n\t\n\t        NameTag.TextSize = 14\n\t        NameTag.FontFace = FontOption.Value\n\t        local Size: Vector2 = GetFontBounds(RemoveTags(Strings[Ent]), NameTag.TextSize, NameTag.FontFace)\n\t\n\t        task.spawn(function()\n\t            if Rank.Enabled and Ent.Player then\n\t                local Icon: ImageLabel = Instance.new(\"ImageLabel\")\n\t                Icon.Name = \"RankIcon\"\n\t                Icon.Size = UDim2.fromOffset(30, 30)\n\t                Icon.Position = UDim2.fromOffset(Size.X + 10, -4)\n\t                Icon.BackgroundTransparency = 1\n\t                Icon.Image = Store.rank[Ent.Player]:async() and bedwars.RankMeta[Store.rank[Ent.Player]:async()].image or \"\"\n\t                Icon.Parent = NameTag\n\t            end\n\t        end)\n\t\n\t        task.spawn(function()\n\t            if Enchant.Enabled and Ent.Player then\n\t                local Icon: ImageLabel = Instance.new(\"ImageLabel\")\n\t                Icon.Name = \"EnchantIcon\"\n\t                Icon.Size = UDim2.fromOffset(30, 30)\n\t                Icon.Position = UDim2.fromOffset(-30, -4)\n\t                Icon.BackgroundTransparency = 1\n\t                Icon.Image = Store.enchants[Ent.Player]:async() or \"\"\n\t                Icon.Parent = NameTag\n\t            end\n\t        end)\n\t\n\t        NameTag.Name = Ent.Player and Ent.Player.Name or Ent.Character.Name\n\t        NameTag.Size = UDim2.fromOffset(Size.X + 8, Size.Y + 7)\n\t        NameTag.AnchorPoint = Vector2.new(0.5, 1)\n\t        NameTag.BackgroundColor3 = Color3.new()\n\t        NameTag.BackgroundTransparency = Background.Value\n\t        NameTag.BorderSizePixel = 0\n\t        NameTag.Visible = false\n\t        NameTag.Text = Distance.Enabled and Entity.isAlive and string.format(Strings[Ent], math.floor((Entity.character.RootPart.Position - Ent.RootPart.Position).Magnitude)) or Strings[Ent]\n\t        NameTag.TextColor3 = Entity.getEntityColor(Ent) or Color3.fromHSV(Color.Hue, Color.Sat, Color.Value)\n\t        NameTag.RichText = true\n\t\n\t        NameTag.Parent = Folder\n\t        Reference[Ent] = NameTag\n\t    end,\n\t    Drawing = function(Ent)\n\t        if not Targets.Players.Enabled and Ent.Player then return end\n\t        if not Targets.NPCs.Enabled and Ent.NPC then return end\n\t        if Teammates.Enabled and (not Ent.Targetable) and (not Ent.Friend) then return end\n\t\n\t        local NameTag = {}\n\t        NameTag.BG = Drawing.new(\"Square\")\n\t        NameTag.BG.Filled = true\n\t        NameTag.BG.Transparency = 1 - Background.Value\n\t        NameTag.BG.Color = Color3.new()\n\t        NameTag.BG.ZIndex = 1\n\t        NameTag.Text = Drawing.new(\"Text\")\n\t        NameTag.Text.Size = 15 * Scale.Value\n\t        NameTag.Text.Font = 0\n\t        NameTag.Text.ZIndex = 2\n\t        Strings[Ent] = Ent.Player and `{Whitelist:tag(Ent.Player, true)}{DisplayName.Enabled and Ent.Player.DisplayName or Ent.Player.Name}` or Ent.Character.Name\n\t\n\t        if Health.Enabled then\n\t            Strings[Ent] = `{Strings[Ent]} {math.round(Ent.Health)}`\n\t        end\n\t\n\t        if Distance.Enabled then\n\t            Strings[Ent] = `[%s] {Strings[Ent]}`\n\t        end\n\t\n\t        NameTag.Text.Text = Strings[Ent]\n\t        NameTag.Text.Color = Entity.getEntityColor(Ent) or Color3.fromHSV(Color.Hue, Color.Sat, Color.Value)\n\t        NameTag.BG.Size = Vector2.new(NameTag.Text.TextBounds.X + 8, NameTag.Text.TextBounds.Y + 7)\n\t        Reference[Ent] = NameTag\n\t    end\n\t}\n\t\n\tlocal Removed = {\n\t    Normal = function(Ent)\n\t        local NameTag = Reference[Ent]\n\t        if NameTag then\n\t            Reference[Ent] = nil\n\t            Strings[Ent] = nil\n\t            Sizes[Ent] = nil\n\t            Refreshes[Ent] = nil\n\t            NameTag:Destroy()\n\t        end\n\t    end,\n\t    Drawing = function(Ent)\n\t        local NameTag = Reference[Ent]\n\t        if NameTag then\n\t            Reference[Ent] = nil\n\t            Strings[Ent] = nil\n\t            Sizes[Ent] = nil\n\t            for _, Object: any in NameTag do\n\t                pcall(function()\n\t                    Object.Visible = false\n\t                    Object:Remove()\n\t                end)\n\t            end\n\t        end\n\t    end\n\t}\n\t\n\tlocal Updated = {\n\t    Normal = function(Ent)\n\t        local NameTag = Reference[Ent]\n\t        if NameTag then\n\t            Sizes[Ent] = nil\n\t            Strings[Ent] = Ent.Player and `{Whitelist:tag(Ent.Player, true, true)}{DisplayName.Enabled and Ent.Player.DisplayName or Ent.Player.Name}` or Ent.Character.Name\n\t\n\t            if Health.Enabled then\n\t                local HealthColor: Color3 = Color3.fromHSV(math.clamp(Ent.Health / Ent.MaxHealth, 0, 1) / 2.5, 0.89, 0.75)\n\t                Strings[Ent] = `{Strings[Ent]} <font color=\"rgb({math.floor(HealthColor.R * 255)},{math.floor(HealthColor.G * 255)},{math.floor(HealthColor.B * 255)})\">{math.round(Ent.Health)}</font>`\n\t            end\n\t\n\t            if Distance.Enabled then\n\t                Strings[Ent] = `<font color=\"rgb(85, 255, 85)\">[</font><font color=\"rgb(255, 255, 255)\">%s</font><font color=\"rgb(85, 255, 85)\">]</font> {Strings[Ent]}`\n\t            end\n\t\n\t            if Equipment.Enabled and Store.inventories[Ent.Player] then\n\t                local Kit: string? = Ent.Player:GetAttribute(\"PlayingAsKits\")\n\t                local KitMeta = Kit and Kit ~= \"none\" and bedwars.BedwarsKitMeta[Kit]\n\t                local PlayerInventory = Store.inventories[Ent.Player]\n\t                local Armor = {}\n\t                for _, v: any in PlayerInventory.armor or {} do\n\t                    local ItemMeta = typeof(v) == \"table\" and bedwars.ItemMeta[v.itemType]\n\t                    if ItemMeta and ItemMeta.armor then\n\t                        Armor[ItemMeta.armor.slot] = v\n\t                    end\n\t                end\n\t\n\t                NameTag.Hand.Image = bedwars.getIcon(PlayerInventory.hand or {itemType = \"\"}, true)\n\t                NameTag.Helmet.Image = bedwars.getIcon(Armor[0] or {itemType = \"\"}, true)\n\t                NameTag.Chestplate.Image = bedwars.getIcon(Armor[1] or {itemType = \"\"}, true)\n\t                NameTag.Boots.Image = bedwars.getIcon(Armor[2] or {itemType = \"\"}, true)\n\t                NameTag.Kit.Image = KitMeta and KitMeta.renderImage or \"\"\n\t            end\n\t\n\t            if Inventory.Enabled then\n\t                UpdateInventory(Ent, NameTag)\n\t            end\n\t\n\t            if Enchant.Enabled and NameTag:FindFirstChild(\"EnchantIcon\") then\n\t                NameTag.EnchantIcon.Image = Store.enchants[Ent.Player]:async() or \"\"\n\t            end\n\t\n\t            local Text: string = Distance.Enabled and Entity.isAlive and string.format(Strings[Ent], math.floor((Entity.character.RootPart.Position - Ent.RootPart.Position).Magnitude)) or Strings[Ent]\n\t            local Size: Vector2 = GetFontBounds(RemoveTags(Text), NameTag.TextSize, NameTag.FontFace)\n\t            NameTag.Size = UDim2.fromOffset(Size.X + 8, Size.Y + 7)\n\t            NameTag.Text = Text\n\t        end\n\t    end,\n\t    Drawing = function(Ent)\n\t        local NameTag = Reference[Ent]\n\t        if NameTag then\n\t            Sizes[Ent] = nil\n\t            Strings[Ent] = Ent.Player and `{Whitelist:tag(Ent.Player, true)}{DisplayName.Enabled and Ent.Player.DisplayName or Ent.Player.Name}` or Ent.Character.Name\n\t\n\t            if Health.Enabled then\n\t                Strings[Ent] = `{Strings[Ent]} {math.round(Ent.Health)}`\n\t            end\n\t\n\t            if Distance.Enabled then\n\t                Strings[Ent] = `[%s] {Strings[Ent]}`\n\t                NameTag.Text.Text = Entity.isAlive and string.format(Strings[Ent], math.floor((Entity.character.RootPart.Position - Ent.RootPart.Position).Magnitude)) or Strings[Ent]\n\t            else\n\t                NameTag.Text.Text = Strings[Ent]\n\t            end\n\t\n\t            NameTag.BG.Size = Vector2.new(NameTag.Text.TextBounds.X + 8, NameTag.Text.TextBounds.Y + 7)\n\t            NameTag.Text.Color = Entity.getEntityColor(Ent) or Color3.fromHSV(Color.Hue, Color.Sat, Color.Value)\n\t        end\n\t    end\n\t}\n\t\n\tlocal ColorFunc = {\n\t    Normal = function(Hue: number, Sat: number, Val: number)\n\t        local DefaultColor: Color3 = Color3.fromHSV(Hue, Sat, Val)\n\t        for Ent: any, v: TextLabel in Reference do\n\t            v.TextColor3 = Entity.getEntityColor(Ent) or DefaultColor\n\t        end\n\t    end,\n\t    Drawing = function(Hue: number, Sat: number, Val: number)\n\t        local DefaultColor: Color3 = Color3.fromHSV(Hue, Sat, Val)\n\t        for Ent: any, v: any in Reference do\n\t            v.Text.Color = Entity.getEntityColor(Ent) or DefaultColor\n\t        end\n\t    end\n\t}\n\t\n\tlocal Loop = {\n\t    Normal = function()\n\t        if vape.ThreadFix then\n\t            setthreadidentity(8)\n\t        end\n\t\n\t        local LocalPosition = Entity.isAlive and Entity.character.RootPart.Position\n\t\n\t        for Ent: any, v: TextLabel in Reference do\n\t            local RootPosition: Vector3 = Ent.RootPart.Position\n\t\n\t            if DistanceCheck.Enabled then\n\t                local EntityDistance: number = LocalPosition and (LocalPosition - RootPosition).Magnitude or math.huge\n\t                if EntityDistance < DistanceLimit.ValueMin or EntityDistance > DistanceLimit.ValueMax then\n\t                    v.Visible = false\n\t                    continue\n\t                end\n\t            end\n\t\n\t            local HeadPos, HeadVisible = Camera:WorldToViewportPoint(RootPosition + Vector3.new(0, Ent.HipHeight + 1, 0))\n\t            v.Visible = HeadVisible\n\t            if not HeadVisible then\n\t                continue\n\t            end\n\t\n\t            if Inventory.Enabled and Ent.Player and (Refreshes[Ent] or 0) < tick() then\n\t                Refreshes[Ent] = tick() + 0.5\n\t                Store.inventories[Ent.Player] = bedwars.getInventory(Ent.Player)\n\t                UpdateInventory(Ent, v)\n\t            end\n\t\n\t            if Distance.Enabled then\n\t                local RoundedDistance: number = LocalPosition and math.floor((LocalPosition - RootPosition).Magnitude) or 0\n\t                if Sizes[Ent] ~= RoundedDistance then\n\t                    local Text: string = string.format(Strings[Ent], RoundedDistance)\n\t                    v.Text = Text\n\t                    local Size: Vector2 = GetFontBounds(RemoveTags(Text), v.TextSize, v.FontFace)\n\t                    v.Size = UDim2.fromOffset(Size.X + 8, Size.Y + 7)\n\t                    Sizes[Ent] = RoundedDistance\n\t                end\n\t            end\n\t            v.Position = UDim2.fromOffset(HeadPos.X, HeadPos.Y)\n\t        end\n\t    end,\n\t    Drawing = function()\n\t        if vape.ThreadFix then\n\t            setthreadidentity(8)\n\t        end\n\t\n\t        local LocalPosition = Entity.isAlive and Entity.character.RootPart.Position\n\t\n\t        for Ent: any, v: any in Reference do\n\t            local RootPosition: Vector3 = Ent.RootPart.Position\n\t\n\t            if DistanceCheck.Enabled then\n\t                local EntityDistance: number = LocalPosition and (LocalPosition - RootPosition).Magnitude or math.huge\n\t                if EntityDistance < DistanceLimit.ValueMin or EntityDistance > DistanceLimit.ValueMax then\n\t                    v.Text.Visible = false\n\t                    v.BG.Visible = false\n\t                    continue\n\t                end\n\t            end\n\t\n\t            local HeadPos, HeadVisible = Camera:WorldToViewportPoint(RootPosition + Vector3.new(0, Ent.HipHeight + 1, 0))\n\t            v.Text.Visible = HeadVisible\n\t            v.BG.Visible = HeadVisible\n\t            if not HeadVisible then\n\t                continue\n\t            end\n\t\n\t            if Distance.Enabled then\n\t                local RoundedDistance: number = LocalPosition and math.floor((LocalPosition - RootPosition).Magnitude) or 0\n\t                if Sizes[Ent] ~= RoundedDistance then\n\t                    v.Text.Text = string.format(Strings[Ent], RoundedDistance)\n\t                    local TextBounds: Vector2 = v.Text.TextBounds\n\t                    v.BG.Size = Vector2.new(TextBounds.X + 8, TextBounds.Y + 7)\n\t                    Sizes[Ent] = RoundedDistance\n\t                end\n\t            end\n\t            local Size: Vector2 = v.BG.Size\n\t            local Position: Vector2 = Vector2.new(HeadPos.X - (Size.X / 2), HeadPos.Y - Size.Y)\n\t            v.BG.Position = Position\n\t            v.Text.Position = Position + Vector2.new(4, 3)\n\t        end\n\t    end\n\t}\n\t\n\tNameTags = vape.Categories.Render:CreateModule({\n\t    Name = \"NameTags\",\n\t    Function = function(Callback: boolean)\n\t        if Callback then\n\t            MethodUsed = DrawingToggle.Enabled and \"Drawing\" or \"Normal\"\n\t            if Removed[MethodUsed] then\n\t                NameTags:Clean(Entity.Events.EntityRemoved:Connect(Removed[MethodUsed]))\n\t            end\n\t            if Added[MethodUsed] then\n\t                for _, v: any in Entity.List do\n\t                    if Reference[v] then\n\t                        Removed[MethodUsed](v)\n\t                    end\n\t                    Added[MethodUsed](v)\n\t                end\n\t                NameTags:Clean(Entity.Events.EntityAdded:Connect(function(Ent)\n\t                    if Reference[Ent] then\n\t                        Removed[MethodUsed](Ent)\n\t                    end\n\t                    Added[MethodUsed](Ent)\n\t                end))\n\t            end\n\t            if Updated[MethodUsed] then\n\t                NameTags:Clean(Entity.Events.EntityUpdated:Connect(Updated[MethodUsed]))\n\t                for _, v: any in Entity.List do\n\t                    Updated[MethodUsed](v)\n\t                end\n\t            end\n\t            if ColorFunc[MethodUsed] then\n\t                NameTags:Clean(vape.Categories.Friends.ColorUpdate.Event:Connect(function()\n\t                    ColorFunc[MethodUsed](Color.Hue, Color.Sat, Color.Value)\n\t                end))\n\t            end\n\t            if Loop[MethodUsed] then\n\t                NameTags:Clean(RunService.RenderStepped:Connect(Loop[MethodUsed]))\n\t            end\n\t        else\n\t            if Removed[MethodUsed] then\n\t                for Ent: any in Reference do\n\t                    Removed[MethodUsed](Ent)\n\t                end\n\t            end\n\t        end\n\t    end,\n\t    Tooltip = \"Renders nametags on entities through walls.\"\n\t})\n\t\n\tTargets = NameTags:CreateTargets({\n\t    Players = true,\n\t    Function = function()\n\t        if NameTags.Enabled then\n\t            NameTags:Toggle()\n\t            NameTags:Toggle()\n\t        end\n\t    end\n\t})\n\tFontOption = NameTags:CreateFont({\n\t    Name = \"Font\",\n\t    Blacklist = \"Arial\",\n\t    Function = function()\n\t        if NameTags.Enabled then\n\t            NameTags:Toggle()\n\t            NameTags:Toggle()\n\t        end\n\t    end\n\t})\n\tColor = NameTags:CreateColorSlider({\n\t    Name = \"Player Color\",\n\t    Function = function(Hue: number, Sat: number, Val: number)\n\t        if NameTags.Enabled and ColorFunc[MethodUsed] then\n\t            ColorFunc[MethodUsed](Hue, Sat, Val)\n\t        end\n\t    end\n\t})\n\tScale = NameTags:CreateSlider({\n\t    Name = \"Scale\",\n\t    Function = function()\n\t        if NameTags.Enabled then\n\t            NameTags:Toggle()\n\t            NameTags:Toggle()\n\t        end\n\t    end,\n\t    Default = 1,\n\t    Min = 0.1,\n\t    Max = 1.5,\n\t    Decimal = 10\n\t})\n\tBackground = NameTags:CreateSlider({\n\t    Name = \"Transparency\",\n\t    Function = function()\n\t        if NameTags.Enabled then\n\t            NameTags:Toggle()\n\t            NameTags:Toggle()\n\t        end\n\t    end,\n\t    Default = 0.5,\n\t    Min = 0,\n\t    Max = 1,\n\t    Decimal = 10\n\t})\n\tHealth = NameTags:CreateToggle({\n\t    Name = \"Health\",\n\t    Function = function()\n\t        if NameTags.Enabled then\n\t            NameTags:Toggle()\n\t            NameTags:Toggle()\n\t        end\n\t    end\n\t})\n\tDistance = NameTags:CreateToggle({\n\t    Name = \"Distance\",\n\t    Function = function()\n\t        if NameTags.Enabled then\n\t            NameTags:Toggle()\n\t            NameTags:Toggle()\n\t        end\n\t    end\n\t})\n\tEquipment = NameTags:CreateToggle({\n\t    Name = \"Equipment\",\n\t    Function = function()\n\t        if NameTags.Enabled then\n\t            NameTags:Toggle()\n\t            NameTags:Toggle()\n\t        end\n\t    end\n\t})\n\tInventory = NameTags:CreateToggle({\n\t    Name = \"Inventory\",\n\t    Function = function(Callback: boolean)\n\t        if InventoryList then\n\t            InventoryList.Object.Visible = Callback\n\t        end\n\t        if NameTags.Enabled then\n\t            NameTags:Toggle()\n\t            NameTags:Toggle()\n\t        end\n\t    end,\n\t    Tooltip = \"Shows how many of each listed item they are carrying\"\n\t})\n\tInventoryList = NameTags:CreateTextList({\n\t    Name = \"Inventory Items\",\n\t    Default = {\"fireball\", \"glue_projectile\", \"telepearl\", \"tnt\"},\n\t    Darker = true,\n\t    Visible = false,\n\t    Tooltip = \"Item types to count, empty shows everything they hold\"\n\t})\n\tEnchant = NameTags:CreateToggle({\n\t    Name = \"Show Enchant\",\n\t    Function = function()\n\t        if NameTags.Enabled then\n\t            NameTags:Toggle()\n\t            NameTags:Toggle()\n\t        end\n\t    end\n\t})\n\tRank = NameTags:CreateToggle({\n\t    Name = \"Show Rank\",\n\t    Function = function()\n\t        if NameTags.Enabled then\n\t            NameTags:Toggle()\n\t            NameTags:Toggle()\n\t        end\n\t    end\n\t})\n\tDisplayName = NameTags:CreateToggle({\n\t    Name = \"Use Displayname\",\n\t    Function = function()\n\t        if NameTags.Enabled then\n\t            NameTags:Toggle()\n\t            NameTags:Toggle()\n\t        end\n\t    end,\n\t    Default = true\n\t})\n\tTeammates = NameTags:CreateToggle({\n\t    Name = \"Priority Only\",\n\t    Function = function()\n\t        if NameTags.Enabled then\n\t            NameTags:Toggle()\n\t            NameTags:Toggle()\n\t        end\n\t    end,\n\t    Default = true\n\t})\n\tDrawingToggle = NameTags:CreateToggle({\n\t    Name = \"Drawing\",\n\t    Function = function()\n\t        if NameTags.Enabled then\n\t            NameTags:Toggle()\n\t            NameTags:Toggle()\n\t        end\n\t    end,\n\t})\n\tDistanceCheck = NameTags:CreateToggle({\n\t    Name = \"Distance Check\",\n\t    Function = function(Callback: boolean)\n\t        DistanceLimit.Object.Visible = Callback\n\t    end\n\t})\n\tDistanceLimit = NameTags:CreateTwoSlider({\n\t    Name = \"Player Distance\",\n\t    Min = 0,\n\t    Max = 256,\n\t    DefaultMin = 0,\n\t    DefaultMax = 64,\n\t    Darker = true,\n\t    Visible = false\n\t})\nend)\n\nRun(function()\n\tlocal NoTextures\n\tlocal Materials = {}\n\tlocal Decals = {}\n\tlocal Meshes = {}\n\tlocal Reference = {}\n\t\n\tlocal function Remember(Object: Instance, Property: string)\n\t    local Properties = Reference[Object]\n\t    if not Properties then\n\t        Properties = {}\n\t        Reference[Object] = Properties\n\t    end\n\t\n\t    if Properties[Property] == nil then\n\t        Properties[Property] = Object[Property]\n\t    end\n\tend\n\t\n\tlocal function StripObject(Object: Instance)\n\t    if Decals.Enabled and Object:IsA(\"Decal\") then\n\t        local Parent: Instance? = Object.Parent\n\t        if Parent and Parent:IsA(\"BasePart\") and Parent.Transparency > 0.5 then\n\t            return\n\t        end\n\t\n\t        Remember(Object, \"Transparency\")\n\t        Object.Transparency = 1\n\t        return\n\t    end\n\t\n\t    if Decals.Enabled and Object:IsA(\"SurfaceAppearance\") then\n\t        Remember(Object, \"Parent\")\n\t        Object.Parent = nil\n\t        return\n\t    end\n\t\n\t    if Meshes.Enabled and Object:IsA(\"SpecialMesh\") then\n\t        Remember(Object, \"TextureId\")\n\t        Object.TextureId = \"\"\n\t        return\n\t    end\n\t\n\t    if Object:IsA(\"BasePart\") then\n\t        if Meshes.Enabled and Object:IsA(\"MeshPart\") then\n\t            Remember(Object, \"TextureID\")\n\t            Object.TextureID = \"\"\n\t        end\n\t\n\t        if Materials.Enabled then\n\t            Remember(Object, \"Material\")\n\t            Object.Material = Enum.Material.SmoothPlastic\n\t        end\n\t    end\n\tend\n\t\n\tlocal function Scan()\n\t    local Descendants: {Instance} = Store.map:GetDescendants()\n\t    for i: number, v: Instance in Descendants do\n\t        if not NoTextures.Enabled then return end\n\t        StripObject(v)\n\t\n\t        if i % 500 == 0 then\n\t            task.wait()\n\t        end\n\t    end\n\tend\n\t\n\tlocal function Refresh()\n\t    if not NoTextures.Enabled then return end\n\t    for Object: Instance, Properties: {[string]: any} in Reference do\n\t        pcall(function()\n\t            for Property: string, Value: any in Properties do\n\t                Object[Property] = Value\n\t            end\n\t        end)\n\t    end\n\t    table.clear(Reference)\n\t    Scan()\n\tend\n\t\n\tNoTextures = vape.Categories.Render:CreateModule({\n\t    Name = \"NoTextures\",\n\t    Function = function(Callback: boolean)\n\t        if Callback then\n\t            repeat task.wait() until Store.map or not NoTextures.Enabled\n\t            if not NoTextures.Enabled then return end\n\t\n\t            NoTextures:Clean(Store.map.DescendantAdded:Connect(function(Object: Instance)\n\t                task.defer(StripObject, Object)\n\t            end))\n\t            Scan()\n\t        else\n\t            for Object: Instance, Properties: {[string]: any} in Reference do\n\t                pcall(function()\n\t                    for Property: string, Value: any in Properties do\n\t                        Object[Property] = Value\n\t                    end\n\t                end)\n\t            end\n\t            table.clear(Reference)\n\t        end\n\t    end,\n\t    Tooltip = \"Removes textures and materials from the map\"\n\t})\n\t\n\tMaterials = NoTextures:CreateToggle({\n\t    Name = \"Materials\",\n\t    Function = Refresh,\n\t    Default = true,\n\t    Tooltip = \"Flattens every part to smooth plastic\"\n\t})\n\tDecals = NoTextures:CreateToggle({\n\t    Name = \"Decals\",\n\t    Function = Refresh,\n\t    Default = true,\n\t    Tooltip = \"Hides decals, textures and PBR surfaces, but keeps the textures of see-through blocks since they are all you can see of them\"\n\t})\n\tMeshes = NoTextures:CreateToggle({\n\t    Name = \"Meshes\",\n\t    Function = Refresh,\n\t    Default = true,\n\t    Tooltip = \"Clears textures off meshes\"\n\t})\nend)\n\nRun(function()\n\tlocal OverlayEditor\n\tlocal FillColor\n\tlocal OutlineColor\n\tlocal Thickness\n\tlocal Animate\n\tlocal Speed\n\tlocal Overlay, OverlayBox, OverlayTween\n\tlocal ActivePart: BasePart?\n\t\n\tlocal function BindPart(Part: Instance)\n\t    if not OverlayEditor.Enabled or not Overlay then return end\n\t    if not Part:IsA(\"BasePart\") or not Part.Anchored or Part.Transparency ~= 1 then return end\n\t    local Box: SelectionBox? = Part:FindFirstChildOfClass(\"SelectionBox\")\n\t    if not Box then return end\n\t\n\t    Box.Visible = false\n\t    ActivePart = Part\n\t    if OverlayTween then\n\t        OverlayTween:Cancel()\n\t        OverlayTween = nil\n\t    end\n\t\n\t    if Animate.Enabled and Overlay.Parent == Camera then\n\t        OverlayTween = TweenService:Create(Overlay, TweenInfo.new(Speed.Value, Enum.EasingStyle.Quad, Enum.EasingDirection.Out), {\n\t            CFrame = Part.CFrame,\n\t            Size = Part.Size\n\t        })\n\t        OverlayTween:Play()\n\t    else\n\t        Overlay.CFrame = Part.CFrame\n\t        Overlay.Size = Part.Size\n\t        Overlay.Parent = Camera\n\t    end\n\tend\n\t\n\tOverlayEditor = vape.Categories.Render:CreateModule({\n\t    Name = \"OverlayEditor\",\n\t    Function = function(Callback: boolean)\n\t        if Callback then\n\t            Overlay = Instance.new(\"Part\")\n\t            Overlay.Size = Vector3.one * 3\n\t            Overlay.Anchored = true\n\t            Overlay.CanCollide = false\n\t            Overlay.CanQuery = false\n\t            Overlay.CanTouch = false\n\t            Overlay.CastShadow = false\n\t            Overlay.Transparency = 1\n\t            OverlayBox = Instance.new(\"SelectionBox\")\n\t            OverlayBox.Adornee = Overlay\n\t            OverlayBox.LineThickness = Thickness.Value\n\t            OverlayBox.Color3 = Color3.fromHSV(OutlineColor.Hue, OutlineColor.Sat, OutlineColor.Value)\n\t            OverlayBox.Transparency = 1 - OutlineColor.Opacity\n\t            OverlayBox.SurfaceColor3 = Color3.fromHSV(FillColor.Hue, FillColor.Sat, FillColor.Value)\n\t            OverlayBox.SurfaceTransparency = 1 - FillColor.Opacity\n\t            OverlayBox.Parent = Overlay\n\t            bedwars.QueryUtil:setQueryIgnored(Overlay, true)\n\t\n\t            for _, v: Instance in workspace:GetChildren() do\n\t                BindPart(v)\n\t            end\n\t\n\t            OverlayEditor:Clean(workspace.ChildAdded:Connect(function(Child: Instance)\n\t                task.defer(BindPart, Child)\n\t            end))\n\t            OverlayEditor:Clean(workspace.ChildRemoved:Connect(function(Child: Instance)\n\t                if Child ~= ActivePart then return end\n\t\n\t                ActivePart = nil\n\t                task.delay(0.06, function()\n\t                    if ActivePart or not OverlayEditor.Enabled then return end\n\t                    if OverlayTween then\n\t                        OverlayTween:Cancel()\n\t                        OverlayTween = nil\n\t                    end\n\t                    if Overlay then\n\t                        Overlay.Parent = nil\n\t                    end\n\t                end)\n\t            end))\n\t        else\n\t            if ActivePart then\n\t                local Box: SelectionBox? = ActivePart:FindFirstChildOfClass(\"SelectionBox\")\n\t                if Box then\n\t                    Box.Visible = true\n\t                end\n\t                ActivePart = nil\n\t            end\n\t\n\t            if OverlayTween then\n\t                OverlayTween:Cancel()\n\t                OverlayTween = nil\n\t            end\n\t            if Overlay then\n\t                Overlay:Destroy()\n\t                Overlay, OverlayBox = nil, nil\n\t            end\n\t        end\n\t    end,\n\t    Tooltip = \"Restyles the outline on the block you are aiming at\"\n\t})\n\t\n\tFillColor = OverlayEditor:CreateColorSlider({\n\t    Name = \"Fill Color\",\n\t    DefaultSat = 0,\n\t    DefaultOpacity = 0.25,\n\t    Darker = true,\n\t    Function = function(Hue: number, Sat: number, Val: number, Opacity: number)\n\t        if OverlayBox then\n\t            OverlayBox.SurfaceColor3 = Color3.fromHSV(Hue, Sat, Val)\n\t            OverlayBox.SurfaceTransparency = 1 - Opacity\n\t        end\n\t    end\n\t})\n\tOutlineColor = OverlayEditor:CreateColorSlider({\n\t    Name = \"Outline Color\",\n\t    DefaultSat = 0,\n\t    Darker = true,\n\t    Function = function(Hue: number, Sat: number, Val: number, Opacity: number)\n\t        if OverlayBox then\n\t            OverlayBox.Color3 = Color3.fromHSV(Hue, Sat, Val)\n\t            OverlayBox.Transparency = 1 - Opacity\n\t        end\n\t    end\n\t})\n\tThickness = OverlayEditor:CreateSlider({\n\t    Name = \"Thickness\",\n\t    Min = 0.01,\n\t    Max = 0.2,\n\t    Decimal = 100,\n\t    Function = function(Value: number)\n\t        if OverlayBox then\n\t            OverlayBox.LineThickness = Value\n\t        end\n\t    end,\n\t    Default = 0.04\n\t})\n\tAnimate = OverlayEditor:CreateToggle({\n\t    Name = \"Animate\",\n\t    Default = true,\n\t    Tooltip = \"Glides the overlay onto the next block instead of snapping to it\"\n\t})\n\tSpeed = OverlayEditor:CreateSlider({\n\t    Name = \"Animation time\",\n\t    Min = 0.01,\n\t    Max = 0.5,\n\t    Default = 0.08,\n\t    Decimal = 100,\n\t    Suffix = \"s\"\n\t})\nend)\n\nRun(function()\n\tlocal PotESP\n\tlocal Background\n\tlocal Color = {}\n\tlocal Reference = {}\n\tlocal Template\n\tlocal Folder: Folder = Instance.new(\"Folder\")\n\tif vape.ThreadFix then\n\t    setthreadidentity(8)\n\tend\n\tFolder.Parent = vape.gui\n\t\n\tlocal function Added(Block: Instance)\n\t    if Block.Name ~= \"desert_pot\" or Reference[Block] then return end\n\t\n\t    local Billboard: BillboardGui = Instance.new(\"BillboardGui\")\n\t    Billboard.Parent = Folder\n\t    Billboard.Name = Block.Name\n\t    Billboard.StudsOffsetWorldSpace = Vector3.new(0, 3, 0)\n\t    Billboard.Size = UDim2.fromOffset(36, 36)\n\t    Billboard.AlwaysOnTop = true\n\t    Billboard.ClipsDescendants = false\n\t    Billboard.Adornee = Block\n\t    local Blur: ImageLabel = AddBlur(Billboard)\n\t    Blur.Visible = Background.Enabled\n\t    local Viewport: ViewportFrame = Instance.new(\"ViewportFrame\")\n\t    Viewport.Size = UDim2.fromOffset(36, 36)\n\t    Viewport.Position = UDim2.fromScale(0.5, 0.5)\n\t    Viewport.AnchorPoint = Vector2.new(0.5, 0.5)\n\t    Viewport.BackgroundColor3 = Color3.fromHSV(Color.Hue, Color.Sat, Color.Value)\n\t    Viewport.BackgroundTransparency = 1 - (Background.Enabled and Color.Opacity or 0)\n\t    Viewport.BorderSizePixel = 0\n\t    Viewport.Ambient = Color3.new(1, 1, 1)\n\t    Viewport.LightColor = Color3.new(1, 1, 1)\n\t    Viewport.Parent = Billboard\n\t    local Corner: UICorner = Instance.new(\"UICorner\")\n\t    Corner.CornerRadius = UDim.new(0, 4)\n\t    Corner.Parent = Viewport\n\t\n\t    if Template == nil then\n\t        local Assets: Instance? = ReplicatedStorage:FindFirstChild(\"Assets\")\n\t        local Blocks: Instance? = Assets and Assets:FindFirstChild(\"Blocks\")\n\t        local Model: Instance? = Blocks and Blocks:FindFirstChild(\"desert_pot\")\n\t        Template = Model and Model:FindFirstChildWhichIsA(\"MeshPart\", true) or false\n\t    end\n\t\n\t    if Template then\n\t        local Mesh: MeshPart = Template:Clone()\n\t        Mesh.CFrame = CFrame.Angles(0, math.rad(25), 0)\n\t        Mesh.Parent = Viewport\n\t        local Camera: Camera = Instance.new(\"Camera\")\n\t        Camera.CFrame = CFrame.lookAt(Vector3.new(0, 0.75, 3.9), Vector3.new(0, 0.05, 0))\n\t        Camera.Parent = Viewport\n\t        Viewport.CurrentCamera = Camera\n\t    end\n\t\n\t    Reference[Block] = Billboard\n\tend\n\t\n\tPotESP = vape.Categories.Render:CreateModule({\n\t    Name = \"PotESP\",\n\t    Function = function(Callback: boolean)\n\t        if Callback then\n\t            for _, v: Instance in CollectionService:GetTagged(\"block\") do\n\t                Added(v)\n\t            end\n\t            PotESP:Clean(CollectionService:GetInstanceAddedSignal(\"block\"):Connect(Added))\n\t            PotESP:Clean(CollectionService:GetInstanceRemovedSignal(\"block\"):Connect(function(Block: Instance)\n\t                if Reference[Block] then\n\t                    Reference[Block]:Destroy()\n\t                    Reference[Block] = nil\n\t                end\n\t            end))\n\t        else\n\t            for Block: Instance, v: BillboardGui in Reference do\n\t                v:Destroy()\n\t                Reference[Block] = nil\n\t            end\n\t        end\n\t    end,\n\t    Tooltip = \"Renders an icon over desert pots\"\n\t})\n\t\n\tBackground = PotESP:CreateToggle({\n\t    Name = \"Background\",\n\t    Function = function(Callback: boolean)\n\t        if Color.Object then\n\t            Color.Object.Visible = Callback\n\t        end\n\t        for _, v: BillboardGui in Reference do\n\t            v.ViewportFrame.BackgroundTransparency = 1 - (Callback and Color.Opacity or 0)\n\t            v.Blur.Visible = Callback\n\t        end\n\t    end,\n\t    Default = true\n\t})\n\tColor = PotESP:CreateColorSlider({\n\t    Name = \"Background Color\",\n\t    DefaultValue = 0,\n\t    DefaultOpacity = 0.5,\n\t    Function = function(Hue: number, Sat: number, Val: number, Opacity: number)\n\t        for _, v: BillboardGui in Reference do\n\t            v.ViewportFrame.BackgroundColor3 = Color3.fromHSV(Hue, Sat, Val)\n\t            v.ViewportFrame.BackgroundTransparency = 1 - (Background.Enabled and Opacity or 0)\n\t        end\n\t    end,\n\t    Darker = true\n\t})\nend)\n\nRun(function()\n\tlocal BulletTracers\n\tlocal Material\n\tlocal Lifetime\n\tlocal Curve\n\tlocal Opacity\n\tlocal Thickness\n\tlocal Color\n\tlocal Fade\n\t\n\tlocal RayCheck: RaycastParams = RaycastParams.new()\n\tRayCheck.FilterType = Enum.RaycastFilterType.Exclude\n\t\n\tBulletTracers = vape.Categories.Render:CreateModule({\n\t    Name = \"ProjectileTracers\",\n\t    Function = function(Callback: boolean)\n\t        if Callback then\n\t            BulletTracers:Clean(workspace.ChildAdded:Connect(function(Projectile: Instance)\n\t                task.delay(0, function()\n\t                    if not BulletTracers.Enabled or not Projectile.Parent or Projectile:GetAttribute(\"ProjectileShooter\") ~= LocalPlayer.UserId then\n\t                        return\n\t                    end\n\t                    local Filter: {Instance} = {Projectile}\n\t                    if LocalPlayer.Character then table.insert(Filter, LocalPlayer.Character) end\n\t                    RayCheck.FilterDescendantsInstances = Filter\n\t                    local Root = Projectile:IsA(\"BasePart\") and Projectile or Projectile:IsA(\"Model\") and Projectile.PrimaryPart\n\t                    local Meta = bedwars.ProjectileMeta[Projectile.Name]\n\t                    if not Root or not Meta then return end\n\t                    local Origin: Vector3 = Root.Position\n\t                    local Velocity: Vector3 = Root.AssemblyLinearVelocity\n\t                    local VelocityMagnitude: number = Velocity.Magnitude\n\t                    if VelocityMagnitude <= 0 then\n\t                        return\n\t                    end\n\t                    local VelocityUnit: Vector3 = Velocity / VelocityMagnitude\n\t                    local Gravity: number = Meta.gravitationalAcceleration or workspace.Gravity\n\t                    local Ray: RaycastResult? = workspace:Raycast(Origin, VelocityUnit * 2000, RayCheck)\n\t                    local Endpoint: Vector3 = Ray and Ray.Position or (Origin + VelocityUnit * 2000)\n\t                    local TravelTime: number = (Endpoint - Origin).Magnitude / VelocityMagnitude\n\t                    PredictionLib.SpawnArcTracer(Origin, VelocityUnit, VelocityMagnitude, Gravity, TravelTime, Curve.Value, {\n\t                        Color = Color3.fromHSV(Color.Hue, Color.Sat, Color.Value),\n\t                        Transparency = Opacity.Value,\n\t                        Thick = Thickness.Value,\n\t                        Material = Enum.Material[Material.Value],\n\t                        Lifetime = Lifetime.Value,\n\t                        Fade = Fade.Enabled\n\t                    })\n\t                end)\n\t            end))\n\t        end\n\t    end,\n\t    Tooltip = \"Replacement tracers for projectiles\"\n\t})\n\t\n\tlocal Materials: {string} = {\"SmoothPlastic\"}\n\tfor _, v: EnumItem in Enum.Material:GetEnumItems() do\n\t    if v.Name ~= \"SmoothPlastic\" then\n\t        table.insert(Materials, v.Name)\n\t    end\n\tend\n\tMaterial = BulletTracers:CreateDropdown({\n\t    Name = \"Material\",\n\t    List = Materials\n\t})\n\tColor = BulletTracers:CreateColorSlider({\n\t    Name = \"Tracer Color\",\n\t    DefaultOpacity = 0.5\n\t})\n\tThickness = BulletTracers:CreateSlider({\n\t    Name = \"Thickness\",\n\t    Min = 0.01,\n\t    Max = 1,\n\t    Default = 0.1,\n\t    Decimal = 100\n\t})\n\tCurve = BulletTracers:CreateSlider({\n\t    Name = \"Curveness\",\n\t    Min = 1,\n\t    Max = 100,\n\t    Default = 40,\n\t    Tooltip = \"How curve the projectile is gonna be\\n(More curve = more lag)\"\n\t})\n\tOpacity = BulletTracers:CreateSlider({\n\t    Name = \"Opacity\",\n\t    Min = 0,\n\t    Max = 1,\n\t    Default = 0,\n\t    Decimal = 100\n\t})\n\tLifetime = BulletTracers:CreateSlider({\n\t    Name = \"Lifetime\",\n\t    Min = 0,\n\t    Max = 5,\n\t    Decimal = 100,\n\t    Default = 2,\n\t    Suffix = \"secs\"\n\t})\n\tFade = BulletTracers:CreateToggle({\n\t    Name = \"Fade\",\n\t    Default = true\n\t})\nend)\n\nRun(function()\n\tlocal SkinChanger\n\tlocal Options = {}\n\tlocal Skins, Families, Groups, Order = {}, {}, {}, {}\n\tlocal Names, Extras = {}, {}\n\tlocal Sounds = {}\n\tlocal Applied = setmetatable({}, {__mode = \"k\"})\n\tlocal Watching, LastHand, Queued\n\tlocal Tiers: {[string]: boolean} = {leather = true, chainmail = true, wood = true, stone = true, gold = true, iron = true, diamond = true, emerald = true}\n\t\n\tfor _, v: string in bedwars.ItemSkinType do\n\t    local Meta = bedwars.getItemSkinMeta(v)\n\t    local Item = Meta and Meta.itemType and bedwars.ItemMeta[Meta.itemType]\n\t    if Item then\n\t        local Label: string = `_{v}_`\n\t        for Segment: string in Meta.itemType:gmatch(\"[^_]+\") do\n\t            Label = Label:gsub(`_{Segment}_`, \"_\")\n\t        end\n\t        Label = Label:gsub(\"^_+\", \"\"):gsub(\"_+$\", \"\")\n\t        Label = (tostring(Label ~= \"\" and Label or v):gsub(\"_\", \" \"):gsub(\"%a+\", function(Word: string)\n\t            return `{Word:sub(1, 1):upper()}{Word:sub(2)}`\n\t        end))\n\t\n\t        Skins[Meta.itemType] = Skins[Meta.itemType] or {}\n\t        Skins[Meta.itemType][Label] = v\n\t    end\n\tend\n\t\n\tfor ItemType: string in Skins do\n\t    local Family: string = ItemType:gsub(\"_%d+$\", \"\")\n\t    local Tier, Base = Family:match(\"^([^_]+)_(.+)$\")\n\t    Family = Tier and Tiers[Tier] and Base or Family\n\t    if not Groups[Family] then\n\t        Groups[Family] = {}\n\t        table.insert(Order, Family)\n\t    end\n\t    Families[ItemType] = Family\n\t    table.insert(Groups[Family], ItemType)\n\tend\n\t\n\tfor Family: string, Members: {string} in Groups do\n\t    Names[Family] = (tostring(#Members > 1 and Family or Members[1]):gsub(\"_\", \" \"):gsub(\"%a+\", function(Word: string)\n\t        return `{Word:sub(1, 1):upper()}{Word:sub(2)}`\n\t    end))\n\tend\n\ttable.sort(Order, function(A: string, B: string)\n\t    return Names[A] < Names[B]\n\tend)\n\t\n\tfor _, v: string in {\"lobby_kaida_claw\", \"bear_claws\", \"summoner_claw_1\", \"summoner_claw_2\", \"summoner_claw_3\", \"summoner_claw_4\"} do\n\t    if ReplicatedStorage.Items:FindFirstChild(v) then\n\t        local Label: string = (tostring((v:gsub(\"^lobby_\", \"\"))):gsub(\"_\", \" \"):gsub(\"%a+\", function(Word: string)\n\t            return `{Word:sub(1, 1):upper()}{Word:sub(2)}`\n\t        end))\n\t        Extras[Label] = v\n\t    end\n\tend\n\t\n\tlocal function GetModel(ItemType: string): string?\n\t    local Family = SkinChanger.Enabled and Families[ItemType]\n\t    local Option = Family and Options[Family]\n\t    local Label = Option and Option.Value\n\t    return Label and (Extras[Label] or Skins[ItemType][Label]) or nil\n\tend\n\t\n\tlocal function ApplyModel(Accessory: Instance)\n\t    local Model: string? = GetModel(Accessory.Name)\n\t    if not Model then return end\n\t\n\t    local Handle: Instance? = Accessory:FindFirstChild(\"Handle\")\n\t    local Template: Instance? = ReplicatedStorage.Items:FindFirstChild(Model)\n\t    if not Handle or not Template or Applied[Accessory] then return end\n\t\n\t    local Grip: Instance? = Handle:FindFirstChild(\"RightGripAttachment\")\n\t    local TemplateGrip: Instance? = Template.Handle:FindFirstChild(\"RightGripAttachment\")\n\t    local Record = {\n\t        Model = Model,\n\t        Parts = {},\n\t        Size = Handle.Size,\n\t        Grip = Grip and Grip.CFrame or nil\n\t    }\n\t    Applied[Accessory] = Record\n\t\n\t    for _, v: Instance in Handle:GetChildren() do\n\t        if v:IsA(\"BasePart\") and v:GetAttribute(\"SkinHidden\") == nil then\n\t            v:SetAttribute(\"SkinHidden\", v.Transparency)\n\t            v.Transparency = 1\n\t        end\n\t    end\n\t\n\t    if Handle:IsA(\"MeshPart\") and Template.Handle:IsA(\"MeshPart\") then\n\t        Handle:ApplyMesh(Template.Handle)\n\t    end\n\t    Handle.Size = Template.Handle.Size\n\t    if Grip and TemplateGrip then\n\t        Grip.CFrame = TemplateGrip.CFrame\n\t    end\n\t\n\t    for _, v: Instance in Template.Handle:GetChildren() do\n\t        if v:IsA(\"BasePart\") then\n\t            local Part: BasePart = v:Clone()\n\t            Part.CanCollide = false\n\t            Part.CanTouch = false\n\t            Part.CanQuery = false\n\t            Part.Massless = true\n\t            Part.CFrame = Handle.CFrame * (Template.Handle.CFrame:Inverse() * v.CFrame)\n\t            Part.Parent = Handle\n\t\n\t            local Weld: WeldConstraint = Instance.new(\"WeldConstraint\")\n\t            Weld.Part0 = Handle\n\t            Weld.Part1 = Part\n\t            Weld.Parent = Part\n\t            table.insert(Record.Parts, Part)\n\t        end\n\t    end\n\tend\n\t\n\tlocal function ApplySounds()\n\t    for ItemType: string in Skins do\n\t        local Meta = bedwars.ItemMeta[ItemType]\n\t        if Meta and Meta.sword then\n\t            local Family = SkinChanger.Enabled and Families[ItemType]\n\t            local Option = Family and Options[Family]\n\t            local Label = Option and Option.Value\n\t            local Skin = Label and not Extras[Label] and Skins[ItemType][Label] or nil\n\t            local SkinMeta = Skin and bedwars.getItemSkinMeta(Skin)\n\t            local Sword = SkinMeta and SkinMeta.sword\n\t            if Sword and (Sword.swingSounds or Sword.hitSounds) then\n\t                if not Sounds[ItemType] then\n\t                    Sounds[ItemType] = {swing = Meta.sword.swingSounds, hit = Meta.sword.hitSounds}\n\t                end\n\t                Meta.sword.swingSounds = Sword.swingSounds or Sounds[ItemType].swing\n\t                Meta.sword.hitSounds = Sword.hitSounds or Sounds[ItemType].hit\n\t            elseif Sounds[ItemType] then\n\t                Meta.sword.swingSounds = Sounds[ItemType].swing\n\t                Meta.sword.hitSounds = Sounds[ItemType].hit\n\t                Sounds[ItemType] = nil\n\t            end\n\t        end\n\t    end\n\tend\n\t\n\tlocal function ApplySkins()\n\t    local Inventory = Store.inventory.inventory\n\t    local HandSkin: string? = Inventory.hand and Inventory.hand.itemSkin\n\t    local Changed: boolean = false\n\t    for _, v: any in Inventory.items do\n\t        local Family = SkinChanger.Enabled and Families[v.itemType]\n\t        local Option = Family and Options[Family]\n\t        local Label = Option and Option.Value\n\t        local Skin = Label and not Extras[Label] and Skins[v.itemType][Label] or nil\n\t        if v.itemSkin ~= Skin then\n\t            v.itemSkin = Skin\n\t            Changed = true\n\t        end\n\t    end\n\t    if Inventory.hand then\n\t        local Family = SkinChanger.Enabled and Families[Inventory.hand.itemType]\n\t        local Option = Family and Options[Family]\n\t        local Label = Option and Option.Value\n\t        local Skin = Label and not Extras[Label] and Skins[Inventory.hand.itemType][Label] or nil\n\t        if Inventory.hand.itemSkin ~= Skin then\n\t            Inventory.hand.itemSkin = Skin\n\t            Changed = true\n\t        end\n\t    end\n\t\n\t    local Hand = Inventory.hand and Inventory.hand.itemType\n\t    if not Changed and Hand == LastHand then return end\n\t\n\t    local HandChanged: boolean = Hand ~= LastHand or (Inventory.hand and Inventory.hand.itemSkin) ~= HandSkin\n\t    LastHand = Hand\n\t    if HandChanged then\n\t        bedwars.InventoryViewmodelController:handleStore(bedwars.Store:getState())\n\t    end\n\t    if not LocalPlayer.Character then return end\n\t\n\t    for _, v: Instance in LocalPlayer.Character:GetChildren() do\n\t        if not v:IsA(\"Accessory\") then continue end\n\t\n\t        local Record = Applied[v]\n\t        if Record then\n\t            if Record.Model == GetModel(v.Name) then continue end\n\t\n\t            local Handle: Instance? = v:FindFirstChild(\"Handle\")\n\t            local Template: Instance? = ReplicatedStorage.Items:FindFirstChild(v.Name)\n\t            for _, Part: BasePart in Record.Parts do\n\t                Part:Destroy()\n\t            end\n\t\n\t            for _, Child: Instance in Handle and Handle:GetChildren() or {} do\n\t                local Transparency: number? = Child:GetAttribute(\"SkinHidden\")\n\t                if Transparency then\n\t                    Child.Transparency = Transparency\n\t                    Child:SetAttribute(\"SkinHidden\", nil)\n\t                end\n\t            end\n\t            Applied[v] = nil\n\t\n\t            if Handle then\n\t                if Template and Handle:IsA(\"MeshPart\") and Template.Handle:IsA(\"MeshPart\") then\n\t                    Handle:ApplyMesh(Template.Handle)\n\t                end\n\t                Handle.Size = Record.Size\n\t\n\t                local Grip: Instance? = Handle:FindFirstChild(\"RightGripAttachment\")\n\t                if Grip and Record.Grip then\n\t                    Grip.CFrame = Record.Grip\n\t                end\n\t            end\n\t        end\n\t\n\t        ApplyModel(v)\n\t    end\n\tend\n\t\n\tlocal function QueueSkins()\n\t    if Queued then return end\n\t\n\t    Queued = true\n\t    task.defer(function()\n\t        Queued = false\n\t        ApplySkins()\n\t    end)\n\tend\n\t\n\tSkinChanger = vape.Categories.Render:CreateModule({\n\t    Name = \"SkinChanger\",\n\t    Function = function(Callback: boolean)\n\t        if Callback then\n\t            SkinChanger:Clean(VapeEvents.InventoryChanged.Event:Connect(QueueSkins))\n\t            SkinChanger:Clean(VapeEvents.InventoryAmountChanged.Event:Connect(QueueSkins))\n\t            SkinChanger:Clean(LocalPlayer.CharacterAdded:Connect(function(Character: Model)\n\t                LastHand = nil\n\t                if Watching then\n\t                    Watching:Disconnect()\n\t                end\n\t                Watching = Character.ChildAdded:Connect(function(Child: Instance)\n\t                    if Child:IsA(\"Accessory\") and Child:WaitForChild(\"Handle\", 3) and SkinChanger.Enabled then\n\t                        ApplyModel(Child)\n\t                    end\n\t                end)\n\t\n\t                task.spawn(function()\n\t                    for _ = 1, 10 do\n\t                        task.wait(0.4)\n\t                        if not SkinChanger.Enabled then return end\n\t                        ApplySkins()\n\t                    end\n\t                end)\n\t            end))\n\t\n\t            if LocalPlayer.Character then\n\t                if Watching then\n\t                    Watching:Disconnect()\n\t                end\n\t                Watching = LocalPlayer.Character.ChildAdded:Connect(function(Child: Instance)\n\t                    if Child:IsA(\"Accessory\") and Child:WaitForChild(\"Handle\", 3) and SkinChanger.Enabled then\n\t                        ApplyModel(Child)\n\t                    end\n\t                end)\n\t            end\n\t        elseif Watching then\n\t            Watching:Disconnect()\n\t            Watching = nil\n\t        end\n\t        ApplySounds()\n\t        ApplySkins()\n\t    end,\n\t    Tooltip = \"Reskins the items and blocks you hold with their sounds, only you can see it\"\n\t})\n\t\n\tfor _, Family: string in Order do\n\t    local List, Seen = {}, {}\n\t    for _, ItemType: string in Groups[Family] do\n\t        for SkinName: string in Skins[ItemType] do\n\t            if not Seen[SkinName] then\n\t                Seen[SkinName] = true\n\t                table.insert(List, SkinName)\n\t            end\n\t        end\n\t    end\n\t\n\t    local Melee: boolean = false\n\t    for _, ItemType: string in Groups[Family] do\n\t        local Meta = bedwars.ItemMeta[ItemType]\n\t        if Meta and Meta.sword then\n\t            Melee = true\n\t            break\n\t        end\n\t    end\n\t\n\t    if Melee then\n\t        for SkinName: string in Extras do\n\t            table.insert(List, SkinName)\n\t        end\n\t    end\n\t\n\t    table.sort(List)\n\t    table.insert(List, 1, \"None\")\n\t    Options[Family] = SkinChanger:CreateDropdown({\n\t        Name = Names[Family],\n\t        List = List,\n\t        Function = function()\n\t            if SkinChanger.Enabled then\n\t                ApplySounds()\n\t                ApplySkins()\n\t            end\n\t        end\n\t    })\n\tend\nend)\n\nRun(function()\n\tlocal StorageESP\n\tlocal List\n\tlocal ShowAmount\n\tlocal Background\n\tlocal Color = {}\n\tlocal Reference = {}\n\tlocal Connections: {[BillboardGui]: {RBXScriptConnection}} = setmetatable({}, {__mode = \"k\"})\n\tlocal Folder: Folder = Instance.new(\"Folder\")\n\tif vape.ThreadFix then\n\t    setthreadidentity(8)\n\tend\n\tFolder.Parent = vape.gui\n\t\n\tlocal function RefreshAdornee(Billboard: BillboardGui)\n\t    local Chest = Billboard.Adornee and Billboard.Adornee:FindFirstChild(\"ChestFolderValue\")\n\t    Chest = Chest and Chest.Value\n\t    if not Chest then\n\t        Billboard.Enabled = false\n\t        return\n\t    end\n\t\n\t    for _, v: RBXScriptConnection in Connections[Billboard] or {} do\n\t        v:Disconnect()\n\t    end\n\t    Connections[Billboard] = {}\n\t    for _, v: Instance in Billboard.Frame:GetChildren() do\n\t        if v:IsA(\"ImageLabel\") then\n\t            v:Destroy()\n\t        end\n\t    end\n\t\n\t    local Amounts: {[string]: number} = {}\n\t    for _, v: Instance in Chest:GetChildren() do\n\t        Amounts[v.Name] = (Amounts[v.Name] or 0) + (v:GetAttribute(\"Amount\") or 0)\n\t        if ShowAmount.Enabled then\n\t            table.insert(Connections[Billboard], v:GetAttributeChangedSignal(\"Amount\"):Connect(function()\n\t                RefreshAdornee(Billboard)\n\t            end))\n\t        end\n\t    end\n\t\n\t    local AlreadyGot: {[string]: boolean} = {}\n\t    Billboard.Enabled = false\n\t    for _, v: Instance in Chest:GetChildren() do\n\t        if AlreadyGot[v.Name] then continue end\n\t        for _, Item: string in List.ListEnabled do\n\t            if v.Name:find(Item, 1, true) then\n\t                AlreadyGot[v.Name] = true\n\t                Billboard.Enabled = true\n\t                local BlockImage: ImageLabel = Instance.new(\"ImageLabel\")\n\t                BlockImage.Size = UDim2.fromOffset(32, 32)\n\t                BlockImage.BackgroundTransparency = 1\n\t                BlockImage.Image = bedwars.getIcon({itemType = v.Name}, true)\n\t                BlockImage.Parent = Billboard.Frame\n\t                if ShowAmount.Enabled and Amounts[v.Name] > 1 then\n\t                    local Amount: TextLabel = Instance.new(\"TextLabel\")\n\t                    Amount.Name = \"Amount\"\n\t                    Amount.Size = UDim2.fromOffset(31, 14)\n\t                    Amount.Position = UDim2.fromOffset(0, 18)\n\t                    Amount.BackgroundTransparency = 1\n\t                    Amount.Text = tostring(Amounts[v.Name])\n\t                    Amount.TextXAlignment = Enum.TextXAlignment.Right\n\t                    Amount.TextSize = 14\n\t                    Amount.TextColor3 = UIPallet.Text\n\t                    Amount.TextStrokeColor3 = Color3.new()\n\t                    Amount.TextStrokeTransparency = 0.4\n\t                    Amount.FontFace = UIPallet.Font\n\t                    Amount.Parent = BlockImage\n\t                end\n\t                break\n\t            end\n\t        end\n\t    end\n\tend\n\t\n\tlocal function Added(Part: Instance)\n\t    local Chest = Part:WaitForChild(\"ChestFolderValue\", 3)\n\t    Chest = Chest and Chest.Value\n\t    if not Chest or not StorageESP.Enabled or Reference[Part] then return end\n\t\n\t    local Billboard: BillboardGui = Instance.new(\"BillboardGui\")\n\t    Billboard.Parent = Folder\n\t    Billboard.Name = \"chest\"\n\t    Billboard.StudsOffsetWorldSpace = Vector3.new(0, 3, 0)\n\t    Billboard.Size = UDim2.fromOffset(36, 36)\n\t    Billboard.AlwaysOnTop = true\n\t    Billboard.ClipsDescendants = false\n\t    Billboard.Adornee = Part\n\t    local Blur: ImageLabel = AddBlur(Billboard)\n\t    Blur.Visible = Background.Enabled\n\t    local Frame: Frame = Instance.new(\"Frame\")\n\t    Frame.Size = UDim2.fromScale(1, 1)\n\t    Frame.BackgroundColor3 = Color3.fromHSV(Color.Hue, Color.Sat, Color.Value)\n\t    Frame.BackgroundTransparency = 1 - (Background.Enabled and Color.Opacity or 0)\n\t    Frame.Parent = Billboard\n\t    local Layout: UIListLayout = Instance.new(\"UIListLayout\")\n\t    Layout.FillDirection = Enum.FillDirection.Horizontal\n\t    Layout.Padding = UDim.new(0, 4)\n\t    Layout.VerticalAlignment = Enum.VerticalAlignment.Center\n\t    Layout.HorizontalAlignment = Enum.HorizontalAlignment.Center\n\t    Layout:GetPropertyChangedSignal(\"AbsoluteContentSize\"):Connect(function()\n\t        Billboard.Size = UDim2.fromOffset(math.max(Layout.AbsoluteContentSize.X + 4, 36), 36)\n\t    end)\n\t    Layout.Parent = Frame\n\t    local Corner: UICorner = Instance.new(\"UICorner\")\n\t    Corner.CornerRadius = UDim.new(0, 4)\n\t    Corner.Parent = Frame\n\t    Reference[Part] = Billboard\n\t\n\t    StorageESP:Clean(Chest.ChildAdded:Connect(function()\n\t        RefreshAdornee(Billboard)\n\t    end))\n\t    StorageESP:Clean(Chest.ChildRemoved:Connect(function()\n\t        RefreshAdornee(Billboard)\n\t    end))\n\t    RefreshAdornee(Billboard)\n\tend\n\t\n\tStorageESP = vape.Categories.Render:CreateModule({\n\t    Name = \"StorageESP\",\n\t    Function = function(Callback: boolean)\n\t        if Callback then\n\t            StorageESP:Clean(CollectionService:GetInstanceAddedSignal(\"chest\"):Connect(function(Part: Instance)\n\t                task.spawn(Added, Part)\n\t            end))\n\t            StorageESP:Clean(CollectionService:GetInstanceRemovedSignal(\"chest\"):Connect(function(Part: Instance)\n\t                if Reference[Part] then\n\t                    Reference[Part]:Destroy()\n\t                    Reference[Part] = nil\n\t                end\n\t            end))\n\t            for _, v: Instance in CollectionService:GetTagged(\"chest\") do\n\t                task.spawn(Added, v)\n\t            end\n\t        else\n\t            for _, v: {RBXScriptConnection} in Connections do\n\t                for _, Connection: RBXScriptConnection in v do\n\t                    Connection:Disconnect()\n\t                end\n\t            end\n\t            table.clear(Connections)\n\t            table.clear(Reference)\n\t            Folder:ClearAllChildren()\n\t        end\n\t    end,\n\t    Tooltip = \"Displays items in chests\"\n\t})\n\t\n\tList = StorageESP:CreateTextList({\n\t    Name = \"Item\",\n\t    Function = function()\n\t        for _, v: BillboardGui in Reference do\n\t            task.spawn(RefreshAdornee, v)\n\t        end\n\t    end\n\t})\n\tShowAmount = StorageESP:CreateToggle({\n\t    Name = \"Show Amount\",\n\t    Function = function()\n\t        for _, v: BillboardGui in Reference do\n\t            task.spawn(RefreshAdornee, v)\n\t        end\n\t    end,\n\t    Tooltip = \"Displays how much of each item the chest holds\"\n\t})\n\tBackground = StorageESP:CreateToggle({\n\t    Name = \"Background\",\n\t    Function = function(Callback: boolean)\n\t        if Color.Object then\n\t            Color.Object.Visible = Callback\n\t        end\n\t        for _, v: BillboardGui in Reference do\n\t            v.Frame.BackgroundTransparency = 1 - (Callback and Color.Opacity or 0)\n\t            v.Blur.Visible = Callback\n\t        end\n\t    end,\n\t    Default = true\n\t})\n\tColor = StorageESP:CreateColorSlider({\n\t    Name = \"Background Color\",\n\t    DefaultValue = 0,\n\t    DefaultOpacity = 0.5,\n\t    Function = function(Hue: number, Sat: number, Val: number, Opacity: number)\n\t        for _, v: BillboardGui in Reference do\n\t            v.Frame.BackgroundColor3 = Color3.fromHSV(Hue, Sat, Val)\n\t            v.Frame.BackgroundTransparency = 1 - (Background.Enabled and Opacity or 0)\n\t        end\n\t    end,\n\t    Darker = true\n\t})\nend)\n\nRun(function()\n\tlocal ShowInventory\n\tlocal TargetInfoOverlay = vape.Categories[\"Target Info\"]\n\tlocal Card: Frame = TargetInfo.Object\n\tlocal Row: Frame?\n\tlocal Tiles: {Frame} = {}\n\tlocal Lifted: {[Frame]: boolean} = {}\n\tlocal TileSize: number = 30\n\tlocal TilePadding: number = 5\n\tlocal Columns: number = 7\n\tlocal Lift: number = 4\n\tlocal Looping: boolean = false\n\t\n\tlocal function CreateRow()\n\t    Row = Instance.new(\"Frame\")\n\t    Row.Name = \"Inventory\"\n\t    Row.BackgroundTransparency = 1\n\t    Row.Position = UDim2.new(0, 0, 1, TilePadding + Lift)\n\t    Row.Size = UDim2.fromScale(1, 0)\n\t    Row.Visible = false\n\t    Row.Parent = Card\n\t    local Grid: UIGridLayout = Instance.new(\"UIGridLayout\")\n\t    Grid.CellPadding = UDim2.fromOffset(TilePadding, TilePadding)\n\t    Grid.CellSize = UDim2.fromOffset(TileSize, TileSize)\n\t    Grid.SortOrder = Enum.SortOrder.LayoutOrder\n\t    Grid.Parent = Row\n\tend\n\t\n\tlocal function CreateTile(Index: number): Frame\n\t    local Cell: Frame = Instance.new(\"Frame\")\n\t    Cell.Name = `Slot{Index}`\n\t    Cell.BackgroundTransparency = 1\n\t    Cell.LayoutOrder = Index\n\t    Cell.Parent = Row\n\t    local Tile: Frame = Instance.new(\"Frame\")\n\t    Tile.Name = \"Tile\"\n\t    Tile.BackgroundColor3 = Color3.fromRGB(29, 36, 46)\n\t    Tile.BorderMode = Enum.BorderMode.Inset\n\t    Tile.BorderSizePixel = 1\n\t    Tile.Size = UDim2.fromScale(1, 1)\n\t    Tile.Parent = Cell\n\t    local Icon: ImageLabel = Instance.new(\"ImageLabel\")\n\t    Icon.Name = \"Icon\"\n\t    Icon.AnchorPoint = Vector2.new(0.5, 0)\n\t    Icon.BackgroundTransparency = 1\n\t    Icon.Position = UDim2.fromScale(0.5, 0.15)\n\t    Icon.Size = UDim2.fromScale(0.8, 0.8)\n\t    Icon.Parent = Tile\n\t    local Amount: TextLabel = Instance.new(\"TextLabel\")\n\t    Amount.Name = \"Amount\"\n\t    Amount.AnchorPoint = Vector2.new(1, 1)\n\t    Amount.BackgroundTransparency = 1\n\t    Amount.FontFace = Font.fromName(\"RobotoMono\", Enum.FontWeight.Bold)\n\t    Amount.Position = UDim2.new(1, -2, 1, 0)\n\t    Amount.Size = UDim2.new(1, -2, 0, 12)\n\t    Amount.Text = \"\"\n\t    Amount.TextColor3 = Color3.new(1, 1, 1)\n\t    Amount.TextSize = 11\n\t    Amount.TextStrokeTransparency = 0.5\n\t    Amount.TextXAlignment = Enum.TextXAlignment.Right\n\t    Amount.ZIndex = 2\n\t    Amount.Parent = Tile\n\t    Tiles[Index] = Cell\n\t\n\t    return Cell\n\tend\n\t\n\tlocal function SetTile(Cell: Frame, Item, Held: boolean)\n\t    local Tile: Frame = Cell.Tile\n\t    Cell.Visible = true\n\t    Tile.Icon.Image = bedwars.getIcon(Item, true)\n\t    Tile.Amount.Text = (Item.amount or 1) > 1 and tostring(Item.amount) or \"\"\n\t    Tile.BackgroundTransparency = Held and 0.2 or 0.4\n\t    Tile.BorderColor3 = Held and Color3.new(1, 1, 1) or Color3.fromRGB(114, 126, 172)\n\t\n\t    if Lifted[Cell] ~= Held then\n\t        Lifted[Cell] = Held\n\t        Tween:Tween(Tile, TweenInfo.new(0.12), {\n\t            Position = UDim2.fromOffset(0, Held and -Lift or 0)\n\t        })\n\t    end\n\tend\n\t\n\tlocal function GetItems(Inventory)\n\t    local Worn: {[Instance]: boolean} = {}\n\t    local Items = {}\n\t\n\t    for _, v: any in Inventory.armor do\n\t        if type(v) == \"table\" and v.tool then\n\t            Worn[v.tool] = true\n\t        end\n\t    end\n\t\n\t    for _, v: any in Inventory.items do\n\t        if v.tool and not Worn[v.tool] then\n\t            table.insert(Items, v)\n\t        end\n\t    end\n\t\n\t    table.sort(Items, function(First, Second): boolean\n\t        local FirstTime: number = First.addedToBackpackTime or 0\n\t        local SecondTime: number = Second.addedToBackpackTime or 0\n\t        if FirstTime ~= SecondTime then\n\t            return FirstTime < SecondTime\n\t        end\n\t\n\t        return First.itemType < Second.itemType\n\t    end)\n\t\n\t    return Items\n\tend\n\t\n\tlocal function Refresh(Target)\n\t    if not Row or not Card.Visible or not TargetInfoOverlay.Object.Visible then\n\t        return\n\t    end\n\t\n\t    local Player: Player? = Target and Target.Player or nil\n\t    local Inventory = Player and bedwars.getInventory and bedwars.getInventory(Player) or nil\n\t    local Items = Inventory and GetItems(Inventory) or {}\n\t    local Hand = Inventory and Inventory.hand or nil\n\t\n\t    for i: number, v: any in Items do\n\t        SetTile(Tiles[i] or CreateTile(i), v, Hand ~= nil and v.tool == Hand.tool)\n\t    end\n\t\n\t    for i: number = #Items + 1, #Tiles do\n\t        Tiles[i].Visible = false\n\t    end\n\t\n\t    local Rows: number = math.ceil(#Items / Columns)\n\t    Row.Size = UDim2.new(1, 0, 0, math.max(Rows * (TileSize + TilePadding) - TilePadding, 0))\n\t    Row.Visible = #Items > 0\n\tend\n\t\n\tlocal function Clear()\n\t    if Row then\n\t        Row:Destroy()\n\t        Row = nil\n\t    end\n\t\n\t    table.clear(Tiles)\n\t    table.clear(Lifted)\n\tend\n\t\n\tShowInventory = TargetInfoOverlay:CreateToggle({\n\t    Name = \"Show Inventory\",\n\t    Function = function(Callback: boolean)\n\t        if not Callback then\n\t            Clear()\n\t            return\n\t        end\n\t\n\t        if not Row then\n\t            CreateRow()\n\t        end\n\t\n\t        if Looping then\n\t            return\n\t        end\n\t        Looping = true\n\t\n\t        task.spawn(function()\n\t            repeat\n\t                Refresh(TargetInfo.LastTarget)\n\t                task.wait(0.1)\n\t            until not ShowInventory.Enabled or vape.Loaded == nil\n\t\n\t            Looping = false\n\t        end)\n\t    end,\n\t    Tooltip = \"Shows the target's inventory under the card in tiles like the BedWars hotbar. The item they are holding is lifted like your selected slot, and the armor they are wearing is left out.\"\n\t})\n\tvape:Clean(TargetInfo.TargetChanged:Connect(function(Target)\n\t    Refresh(Target)\n\tend))\nend)\n\nRun(function()\n\tlocal ComboCounter\n\tlocal ComboComparator\n\tlocal DamageComparator\n\tlocal Combo, Comparator = 0, 0\n\tlocal Dealt, DealtHits, Taken, TakenHits = 0, 0, 0, 0\n\t\n\tComboCounter = TargetInfo:CreateStat({\n\t    Name = \"Combo Counter\",\n\t    Icon = GetVapeAsset(`{vape.Directory}/assets/new/combo_display.png`),\n\t    IconSize = UDim2.fromOffset(14, 12),\n\t    Default = true,\n\t    Tooltip = \"Shows how many hits in a direct row you have landed on, or taken from, the target.\"\n\t})\n\tComboComparator = TargetInfo:CreateStat({\n\t    Name = \"Combo Comparator\",\n\t    Icon = GetVapeAsset(`{vape.Directory}/assets/new/sword_header.png`),\n\t    IconSize = UDim2.fromOffset(12, 12),\n\t    Signed = true,\n\t    Tooltip = \"Measures how many hits you have landed compared to the target.\"\n\t})\n\tDamageComparator = TargetInfo:CreateStat({\n\t    Name = \"Damage Comparator\",\n\t    Default = true,\n\t    Signed = true,\n\t    Tint = true,\n\t    Tooltip = \"Measures the strength of the target compared to yourself, from the damage each of you lands per hit.\"\n\t})\n\tvape:Clean(TargetInfo.TargetChanged:Connect(function()\n\t    Combo, Comparator = 0, 0\n\t    Dealt, DealtHits, Taken, TakenHits = 0, 0, 0, 0\n\tend))\n\tvape:Clean(VapeEvents.EntityDamageEvent.Event:Connect(function(DamageTable)\n\t    local Target = TargetInfo.LastTarget\n\t    if not Target or not Target.Character then return end\n\t\n\t    local Landed: boolean = DamageTable.fromEntity == LocalPlayer.Character and DamageTable.entityInstance == Target.Character\n\t    local Received: boolean = DamageTable.entityInstance == LocalPlayer.Character and DamageTable.fromEntity == Target.Character\n\t    if not Landed and not Received then return end\n\t\n\t    if Landed then\n\t        Combo = Combo >= 0 and Combo + 1 or 0\n\t        Comparator += 1\n\t        Dealt += DamageTable.damage or 0\n\t        DealtHits += 1\n\t    else\n\t        Combo = Combo <= 0 and Combo - 1 or 0\n\t        Comparator -= 1\n\t        Taken += DamageTable.damage or 0\n\t        TakenHits += 1\n\t    end\n\t\n\t    TargetInfo:SetStat(ComboCounter, Combo)\n\t    TargetInfo:SetStat(ComboComparator, Comparator)\n\t    TargetInfo:SetStat(DamageComparator, math.clamp(math.round((DealtHits > 0 and Dealt / DealtHits or 0) - (TakenHits > 0 and Taken / TakenHits or 0)), -9, 9))\n\tend))\nend)\n\nRun(function()\n\tlocal TeamUpgrades\n\tlocal Session = nil\n\tlocal OwnTeam\n\tlocal BedUpgrades\n\tlocal Color\n\tlocal Transparency\n\tlocal Scale\n\tlocal Reference = {}\n\tlocal Folder: Folder = Instance.new(\"Folder\")\n\tif vape.ThreadFix then\n\t    setthreadidentity(8)\n\tend\n\tFolder.Parent = vape.gui\n\t\n\tlocal Numerals: {string} = {\"I\", \"II\", \"III\", \"IV\", \"V\"}\n\t\n\tlocal function GetAnchor(Object: Instance)\n\t    return Object:IsA(\"Model\") and (Object.PrimaryPart or Object:FindFirstChildWhichIsA(\"BasePart\")) or Object\n\tend\n\t\n\tlocal function GetText(Team: string)\n\t    local State = bedwars.Store:getState().Bedwars\n\t    local Upgrades = State.teamUpgrades[Team] or {}\n\t    local Bought: {string} = {}\n\t\n\t    for UpgradeId: string, v: any in bedwars.TeamUpgradeMeta do\n\t        local Tier: number? = Upgrades[UpgradeId]\n\t        if Tier and Tier > 0 then\n\t            table.insert(Bought, `{v.name} {Numerals[Tier] or Tier}`)\n\t        end\n\t    end\n\t\n\t    table.sort(Bought)\n\t\n\t    if BedUpgrades.Enabled then\n\t        local Bed = State.bedTeamUpgrades[Team] or {}\n\t        if Bed.bed_shield then\n\t            table.insert(Bought, \"Bed Shield\")\n\t        end\n\t        if Bed.bed_alarm then\n\t            table.insert(Bought, \"Bed Alarm\")\n\t        end\n\t    end\n\t\n\t    return `Team {Team} | {#Bought > 0 and table.concat(Bought, \", \") or \"No upgrades\"}`\n\tend\n\t\n\tlocal function Added(Object: Instance, Tag: string)\n\t    local Team: string? = Tag:match(\"^(%d+)_TeamOreGenerator\")\n\t    local Anchor: Instance? = Team and GetAnchor(Object)\n\t    if not Anchor then return end\n\t    if not OwnTeam.Enabled and Team == LocalPlayer:GetAttribute(\"Team\") then return end\n\t\n\t    local NameTag: TextLabel = Instance.new(\"TextLabel\")\n\t    NameTag.Name = `Team{Team}`\n\t    NameTag.Text = GetText(Team)\n\t    NameTag.TextSize = 14 * Scale.Value\n\t    NameTag.Font = Enum.Font.Arial\n\t    local Size: Vector2 = GetFontBounds(NameTag.Text, NameTag.TextSize, NameTag.FontFace)\n\t    NameTag.Size = UDim2.fromOffset(Size.X + 8, Size.Y + 7)\n\t    NameTag.AnchorPoint = Vector2.new(0.5, 1)\n\t    NameTag.BackgroundColor3 = Color3.new()\n\t    NameTag.BackgroundTransparency = Transparency.Value\n\t    NameTag.BorderSizePixel = 0\n\t    NameTag.Visible = false\n\t    NameTag.TextColor3 = Color3.fromHSV(Color.Hue, Color.Sat, Color.Value)\n\t    NameTag.Parent = Folder\n\t    Reference[Anchor] = {Label = NameTag, Team = Team}\n\tend\n\t\n\tlocal function Refresh()\n\t    for _, v: {Label: TextLabel, Team: string} in Reference do\n\t        v.Label.Text = GetText(v.Team)\n\t        local Size: Vector2 = GetFontBounds(v.Label.Text, v.Label.TextSize, v.Label.FontFace)\n\t        v.Label.Size = UDim2.fromOffset(Size.X + 8, Size.Y + 7)\n\t    end\n\tend\n\t\n\tTeamUpgrades = vape.Categories.Render:CreateModule({\n\t    Name = \"TeamUpgrades\",\n\t    Function = function(Callback: boolean)\n\t        if Callback then\n\t            local Current = {}\n\t            Session = Current\n\t            for _, Tag: string in CollectionService:GetAllTags() do\n\t                if Tag:match(\"^%d+_TeamOreGenerator$\") then\n\t                    for _, v: Instance in CollectionService:GetTagged(Tag) do\n\t                        Added(v, Tag)\n\t                    end\n\t                    TeamUpgrades:Clean(CollectionService:GetInstanceAddedSignal(Tag):Connect(function(Object: Instance)\n\t                        Added(Object, Tag)\n\t                    end))\n\t                end\n\t            end\n\t\n\t            TeamUpgrades:Clean(RunService.PreRender:Connect(function()\n\t                for Anchor: BasePart, v: {Label: TextLabel, Team: string} in Reference do\n\t                    if not Anchor.Parent then\n\t                        v.Label:Destroy()\n\t                        Reference[Anchor] = nil\n\t                        continue\n\t                    end\n\t\n\t                    local ScreenPos, Visible = Camera:WorldToViewportPoint(Anchor.Position + Vector3.new(0, 4, 0))\n\t                    v.Label.Visible = Visible\n\t                    if not Visible then continue end\n\t                    v.Label.Position = UDim2.fromOffset(ScreenPos.X, ScreenPos.Y)\n\t                end\n\t            end))\n\t\n\t            repeat\n\t                Refresh()\n\t                task.wait(0.5)\n\t            until not TeamUpgrades.Enabled or Session ~= Current\n\t        else\n\t            for Anchor: Instance, v: {Label: TextLabel, Team: string} in Reference do\n\t                v.Label:Destroy()\n\t                Reference[Anchor] = nil\n\t            end\n\t        end\n\t    end,\n\t    Tooltip = \"Puts every teams upgrades over their generator, and whether their bed is shielded or alarmed which the game never shows you anywhere\"\n\t})\n\t\n\tOwnTeam = TeamUpgrades:CreateToggle({\n\t    Name = \"Show own team\",\n\t    Function = function()\n\t        if TeamUpgrades.Enabled then\n\t            TeamUpgrades:Toggle()\n\t            TeamUpgrades:Toggle()\n\t        end\n\t    end\n\t})\n\tBedUpgrades = TeamUpgrades:CreateToggle({\n\t    Name = \"Bed upgrades\",\n\t    Default = true,\n\t    Function = function()\n\t        if TeamUpgrades.Enabled then\n\t            Refresh()\n\t        end\n\t    end,\n\t    Tooltip = \"Bed shield and bed alarm, which no part of the games own UI displays\"\n\t})\n\tColor = TeamUpgrades:CreateColorSlider({\n\t    Name = \"Text Color\",\n\t    Function = function(Hue: number, Sat: number, Val: number)\n\t        for _, v: {Label: TextLabel, Team: string} in Reference do\n\t            v.Label.TextColor3 = Color3.fromHSV(Hue, Sat, Val)\n\t        end\n\t    end,\n\t    DefaultSat = 0,\n\t    DefaultValue = 1\n\t})\n\tTransparency = TeamUpgrades:CreateSlider({\n\t    Name = \"Transparency\",\n\t    Min = 0,\n\t    Max = 1,\n\t    Decimal = 100,\n\t    Default = 0.5,\n\t    Function = function(Value: number)\n\t        for _, v: {Label: TextLabel, Team: string} in Reference do\n\t            v.Label.BackgroundTransparency = Value\n\t        end\n\t    end\n\t})\n\tScale = TeamUpgrades:CreateSlider({\n\t    Name = \"Scale\",\n\t    Min = 0.1,\n\t    Max = 1.5,\n\t    Decimal = 10,\n\t    Default = 1,\n\t    Function = function(Value: number)\n\t        for _, v: {Label: TextLabel, Team: string} in Reference do\n\t            v.Label.TextSize = 14 * Value\n\t            local Size: Vector2 = GetFontBounds(v.Label.Text, v.Label.TextSize, v.Label.FontFace)\n\t            v.Label.Size = UDim2.fromOffset(Size.X + 8, Size.Y + 7)\n\t        end\n\t    end\n\t})\nend)\n\nRun(function()\n\tlocal TrapESP\n\tlocal Traps\n\tlocal Distance\n\tlocal Owner\n\tlocal Transparency\n\tlocal Scale\n\tlocal Color = {}\n\tlocal Reference = {}\n\tlocal Folder: Folder?\n\t\n\tlocal Names: {[string]: string} = {\n\t    [\"glue_trap\"] = \"Gloop\",\n\t    [\"grave_trap\"] = \"Grave\",\n\t    [\"grave_trap_block\"] = \"Grave\",\n\t    [\"invisible_landmine\"] = \"Landmine\",\n\t    [\"lucky_block_trap\"] = \"Lucky Trap\",\n\t    [\"snap_trap\"] = \"Snap Trap\",\n\t    [\"spike_trap\"] = \"Spikes\",\n\t    [\"tesla_trap\"] = \"Tesla\"\n\t}\n\t\n\tlocal function Added(Block: Instance)\n\t    if Reference[Block] or not Block:IsA(\"BasePart\") then return end\n\t\n\t    local Label: string? = Names[Block.Name]\n\t    if not Label or not table.find(Traps.ListEnabled, Label) then return end\n\t\n\t    local NameTag: TextLabel = Instance.new(\"TextLabel\")\n\t    NameTag.Name = Label\n\t    NameTag.Text = Label\n\t    NameTag.TextSize = 14 * Scale.Value\n\t    NameTag.FontFace = UIPallet.Font\n\t    local Size: Vector2 = GetFontBounds(NameTag.Text, NameTag.TextSize, NameTag.FontFace)\n\t    NameTag.Size = UDim2.fromOffset(Size.X + 8, Size.Y + 7)\n\t    NameTag.AnchorPoint = Vector2.new(0.5, 1)\n\t    NameTag.BackgroundColor3 = Color3.new()\n\t    NameTag.BackgroundTransparency = Transparency.Value\n\t    NameTag.BorderSizePixel = 0\n\t    NameTag.Visible = false\n\t    NameTag.TextColor3 = Color3.fromHSV(Color.Hue, Color.Sat, Color.Value)\n\t    NameTag.Parent = Folder\n\t    Reference[Block] = NameTag\n\tend\n\t\n\tlocal function IsMine(Block: Instance)\n\t    local UserId: number? = Block:GetAttribute(\"PlacedByUserId\")\n\t    if not UserId or UserId == 0 then\n\t        return false\n\t    end\n\t    if UserId == LocalPlayer.UserId then\n\t        return true\n\t    end\n\t\n\t    local Placer: Player? = Players:GetPlayerByUserId(UserId)\n\t    return Placer ~= nil and Placer:GetAttribute(\"Team\") == LocalPlayer:GetAttribute(\"Team\")\n\tend\n\t\n\tTrapESP = vape.Categories.Render:CreateModule({\n\t    Name = \"TrapESP\",\n\t    Function = function(Callback: boolean)\n\t        if Callback then\n\t            if not Folder then\n\t                if vape.ThreadFix then\n\t                    setthreadidentity(8)\n\t                end\n\t                Folder = Instance.new(\"Folder\")\n\t                if vape.ThreadFix then\n\t                    setthreadidentity(8)\n\t                end\n\t                Folder.Parent = vape.gui\n\t            end\n\t\n\t            for _, v: Instance in CollectionService:GetTagged(\"block\") do\n\t                Added(v)\n\t            end\n\t\n\t            TrapESP:Clean(CollectionService:GetInstanceAddedSignal(\"block\"):Connect(Added))\n\t            TrapESP:Clean(CollectionService:GetInstanceRemovedSignal(\"block\"):Connect(function(Block: Instance)\n\t                if Reference[Block] then\n\t                    Reference[Block]:Destroy()\n\t                    Reference[Block] = nil\n\t                end\n\t            end))\n\t\n\t            TrapESP:Clean(RunService.PreRender:Connect(function()\n\t                local LocalPosition = Entity.isAlive and Entity.character.RootPart.Position\n\t                for Block: BasePart, NameTag: TextLabel in Reference do\n\t                    if not Block.Parent then\n\t                        NameTag:Destroy()\n\t                        Reference[Block] = nil\n\t                        continue\n\t                    end\n\t\n\t                    if not Owner.Enabled and IsMine(Block) then\n\t                        NameTag.Visible = false\n\t                        continue\n\t                    end\n\t\n\t                    local ScreenPos, Visible = Camera:WorldToViewportPoint(Block.Position + Vector3.new(0, 2, 0))\n\t                    NameTag.Visible = Visible\n\t                    if not Visible then continue end\n\t\n\t                    local Text: string = Distance.Enabled and LocalPosition and `{NameTag.Name} | {((LocalPosition - Block.Position).Magnitude) // 1}m` or NameTag.Name\n\t                    if NameTag.Text ~= Text then\n\t                        NameTag.Text = Text\n\t                        local Size: Vector2 = GetFontBounds(Text, NameTag.TextSize, NameTag.FontFace)\n\t                        NameTag.Size = UDim2.fromOffset(Size.X + 8, Size.Y + 7)\n\t                    end\n\t                    NameTag.Position = UDim2.fromOffset(ScreenPos.X, ScreenPos.Y)\n\t                end\n\t            end))\n\t        else\n\t            for Block: Instance, NameTag: TextLabel in Reference do\n\t                NameTag:Destroy()\n\t                Reference[Block] = nil\n\t            end\n\t        end\n\t    end,\n\t    Tooltip = \"Shows every trap on the map through walls, landmines included, which have no visual at all\"\n\t})\n\t\n\tDistance = TrapESP:CreateToggle({\n\t    Name = \"Distance\",\n\t    Default = true\n\t})\n\tOwner = TrapESP:CreateToggle({\n\t    Name = \"Your traps\",\n\t    Default = true,\n\t    Tooltip = \"Also shows the ones your own team placed\"\n\t})\n\tScale = TrapESP:CreateSlider({\n\t    Name = \"Scale\",\n\t    Min = 0.5,\n\t    Max = 3,\n\t    Default = 1,\n\t    Decimal = 10,\n\t    Function = function(Value: number)\n\t        for _, v: TextLabel in Reference do\n\t            v.TextSize = 14 * Value\n\t            local Size: Vector2 = GetFontBounds(v.Text, v.TextSize, v.FontFace)\n\t            v.Size = UDim2.fromOffset(Size.X + 8, Size.Y + 7)\n\t        end\n\t    end\n\t})\n\tTransparency = TrapESP:CreateSlider({\n\t    Name = \"Transparency\",\n\t    Min = 0,\n\t    Max = 1,\n\t    Default = 0.5,\n\t    Decimal = 100,\n\t    Function = function(Value: number)\n\t        for _, v: TextLabel in Reference do\n\t            v.BackgroundTransparency = Value\n\t        end\n\t    end\n\t})\n\tColor = TrapESP:CreateColorSlider({\n\t    Name = \"Text Color\",\n\t    Function = function(Hue: number, Sat: number, Val: number)\n\t        for _, v: TextLabel in Reference do\n\t            v.TextColor3 = Color3.fromHSV(Hue, Sat, Val)\n\t        end\n\t    end,\n\t    DefaultHue = 0,\n\t    DefaultSat = 0.75,\n\t    Darker = true\n\t})\n\tTraps = TrapESP:CreateTextList({\n\t    Name = \"Traps\",\n\t    Function = function()\n\t        if TrapESP.Enabled then\n\t            TrapESP:Toggle()\n\t            TrapESP:Toggle()\n\t        end\n\t    end,\n\t    Default = {\n\t        \"Gloop\",\n\t        \"Grave\",\n\t        \"Landmine\",\n\t        \"Lucky Trap\",\n\t        \"Snap Trap\",\n\t        \"Spikes\",\n\t        \"Tesla\"\n\t    },\n\t    Darker = true\n\t})\nend)\n\nRun(function()\n\tlocal AntiEffect\n\tlocal Dizzy\n\tlocal Fear\n\tlocal Vignettes\n\tlocal OldVignettes: boolean?\n\t\n\tAntiEffect = vape.Categories.Utility:CreateModule({\n\t    Name = \"AntiEffect\",\n\t    Function = function(Callback: boolean)\n\t        if Callback then\n\t            if Dizzy.Enabled then\n\t                RunService:UnbindFromRenderStep(\"dizzy-status\")\n\t            end\n\t\n\t            if Fear.Enabled then\n\t                RunService:UnbindFromRenderStep(\"werewolf-fear-status\")\n\t            end\n\t\n\t            if Vignettes.Enabled then\n\t                OldVignettes = bedwars.VignetteController.enableOnScreenEffects\n\t                bedwars.VignetteController.enableOnScreenEffects = false\n\t                bedwars.VignetteController:destroyAllVignettes()\n\t            end\n\t\n\t            local Connection = bedwars.SyncEvents.StatusEffectAdded:setPriority(1000):connect(function(Event)\n\t                if Event.entityInstance ~= LocalPlayer.Character then\n\t                    return\n\t                end\n\t\n\t                if Dizzy.Enabled and Event.statusEffect == bedwars.StatusEffectMeta.DIZZY then\n\t                    RunService:UnbindFromRenderStep(\"dizzy-status\")\n\t                end\n\t\n\t                if Fear.Enabled and Event.statusEffect == bedwars.StatusEffectMeta.WEREWOLF_FEAR then\n\t                    RunService:UnbindFromRenderStep(\"werewolf-fear-status\")\n\t                end\n\t            end)\n\t            AntiEffect:Clean(function()\n\t                Connection:Destroy()\n\t            end)\n\t        else\n\t            if OldVignettes ~= nil then\n\t                bedwars.VignetteController.enableOnScreenEffects = OldVignettes\n\t                OldVignettes = nil\n\t            end\n\t        end\n\t    end,\n\t    Tooltip = \"Throws away the parts of a debuff the game plays on your own client\"\n\t})\n\t\n\tDizzy = AntiEffect:CreateToggle({\n\t    Name = \"Dizzy\",\n\t    Default = true,\n\t    Tooltip = \"Stops the dizzy toad swinging your walk direction around, the slow itself is on the server\"\n\t})\n\tFear = AntiEffect:CreateToggle({\n\t    Name = \"Werewolf fear\",\n\t    Default = true,\n\t    Tooltip = \"Stops the werewolf tail walking you away from it\"\n\t})\n\tVignettes = AntiEffect:CreateToggle({\n\t    Name = \"Vignettes\",\n\t    Function = function(Callback: boolean)\n\t        if AntiEffect.Enabled and Callback then\n\t            OldVignettes = bedwars.VignetteController.enableOnScreenEffects\n\t            bedwars.VignetteController.enableOnScreenEffects = false\n\t            bedwars.VignetteController:destroyAllVignettes()\n\t        elseif AntiEffect.Enabled and OldVignettes ~= nil then\n\t            bedwars.VignetteController.enableOnScreenEffects = OldVignettes\n\t            OldVignettes = nil\n\t        end\n\t    end,\n\t    Default = true,\n\t    Tooltip = \"Clears the coloured screen border frozen, decay, soaked and the rest put over your view\"\n\t})\nend)\n\nRun(function()\n\tlocal AntiLasso\n\tlocal Chance\n\tlocal Check\n\tlocal Watching = setmetatable({}, {__mode = \"k\"})\n\t\n\tlocal function Added(Character: Model)\n\t    if Watching[Character] then\n\t        return\n\t    end\n\t\n\t    Watching[Character] = Character.ChildAdded:Connect(function(Child: Instance)\n\t        if Child:IsA(\"Accessory\") and Child:FindFirstChild(\"Rope\") and Random.new(os.clock()):NextNumber(1, 100) < Chance.Value and (not Check.Enabled or Entity.EntityPosition({\n\t            Range = 50,\n\t            Part = \"RootPart\",\n\t            Players = true\n\t        })) then\n\t            Character.PrimaryPart.Anchored = true\n\t            Child.Destroying:Once(function()\n\t                task.wait(0.5)\n\t                Character.PrimaryPart.Anchored = false\n\t            end)\n\t        end\n\t    end)\n\tend\n\t\n\tAntiLasso = vape.Categories.Utility:CreateModule({\n\t    Name = \"AntiLasso\",\n\t    Function = function(Callback: boolean)\n\t        if Callback then\n\t            AntiLasso:Clean(Entity.Events.LocalAdded:Connect(function(Ent)\n\t                task.delay(1, function()\n\t                    Added(Ent.Character)\n\t                end)\n\t            end))\n\t            if Entity.isAlive then\n\t                Added(LocalPlayer.Character)\n\t            end\n\t        end\n\t    end,\n\t    Tooltip = \"Prevents you from getting pulled by lasso projectile.\"\n\t})\n\t\n\tChance = AntiLasso:CreateSlider({\n\t    Name = \"Chance\",\n\t    Min = 0,\n\t    Max = 100,\n\t    Default = 100,\n\t    Suffix = \"%\"\n\t})\n\tCheck = AntiLasso:CreateToggle({Name = \"Only when targeting\"})\nend)\n\nRun(function()\n\tlocal AntiSuffocate\n\tlocal Mode\n\tlocal Height\n\t\n\tlocal Offsets: {Vector3} = {\n\t    Vector3.new(0, 3, 0),\n\t    Vector3.new(3, 0, 0),\n\t    Vector3.new(-3, 0, 0),\n\t    Vector3.new(0, 0, 3),\n\t    Vector3.new(0, 0, -3),\n\t    Vector3.new(0, -3, 0)\n\t}\n\t\n\tlocal function GetEscape(Position: Vector3): Vector3?\n\t    for _, v: Vector3 in Offsets do\n\t        local Target: Vector3 = Position + v\n\t        if not GetPlacedBlock(Target) and not GetPlacedBlock(Target + Vector3.new(0, 3, 0)) then\n\t            return Target\n\t        end\n\t    end\n\t    return nil\n\tend\n\t\n\tAntiSuffocate = vape.Categories.Utility:CreateModule({\n\t    Name = \"AntiSuffocate\",\n\t    Function = function(Callback: boolean)\n\t        if Callback then\n\t            repeat\n\t                if Entity.isAlive and Store.matchState == 1 then\n\t                    local Root: BasePart = Entity.character.RootPart\n\t                    local HeadPosition: Vector3 = Root.Position + Vector3.new(0, Height.Value, 0)\n\t                    if GetPlacedBlock(HeadPosition) then\n\t                        if Mode.Value == \"Break\" then\n\t                            local Block: BasePart? = GetPlacedBlock(HeadPosition)\n\t                            if Block then\n\t                                bedwars.breakBlock(Block, true, true)\n\t                            end\n\t                        else\n\t                            local Escape: Vector3? = GetEscape(RoundPosition(HeadPosition))\n\t                            if Escape then\n\t                                Root.CFrame = CFrame.new(Escape - Vector3.new(0, Height.Value, 0)) * (Root.CFrame - Root.Position)\n\t                                Root.AssemblyLinearVelocity = Vector3.zero\n\t                            end\n\t                        end\n\t                    end\n\t                end\n\t                task.wait(0.1)\n\t            until not AntiSuffocate.Enabled\n\t        end\n\t    end,\n\t    Tooltip = \"Gets you out of a block that someone placed on top of you before it suffocates you\"\n\t})\n\t\n\tMode = AntiSuffocate:CreateDropdown({\n\t    Name = \"Mode\",\n\t    List = {\"Move\", \"Break\"},\n\t    Tooltip = \"Move - shifts you into the nearest open cell\\nBreak - breaks the block you are stuck in\"\n\t})\n\tHeight = AntiSuffocate:CreateSlider({\n\t    Name = \"Check height\",\n\t    Min = 0,\n\t    Max = 4,\n\t    Default = 1.5,\n\t    Decimal = 10,\n\t    Suffix = function(Val: number)\n\t        return Val <= 1 and \"stud\" or \"studs\"\n\t    end,\n\t    Tooltip = \"How far above your root the check looks, 1.5 is head level\"\n\t})\nend)\n\nRun(function()\n\tlocal AutoBalloon\n\t\n\tAutoBalloon = vape.Categories.Utility:CreateModule({\n\t    Name = \"AutoBalloon\",\n\t    Function = function(Callback: boolean)\n\t        if Callback then\n\t            repeat task.wait() until Store.matchState ~= 0 or (not AutoBalloon.Enabled)\n\t            if not AutoBalloon.Enabled then\n\t                return\n\t            end\n\t\n\t            local LowestPoint: number = math.huge\n\t            for _, v: BasePart in Store.blocks do\n\t                local Point: number = (v.Position.Y - (v.Size.Y / 2)) - 50\n\t                if Point < LowestPoint then\n\t                    LowestPoint = Point\n\t                end\n\t            end\n\t\n\t            repeat\n\t                if Entity.isAlive then\n\t                    if Entity.character.RootPart.Position.Y < LowestPoint and (LocalPlayer.Character:GetAttribute(\"InflatedBalloons\") or 0) < 3 then\n\t                        local Balloon = GetItem(\"balloon\")\n\t                        if Balloon then\n\t                            for _ = 1, 3 do\n\t                                bedwars.BalloonController:inflateBalloon()\n\t                            end\n\t                        end\n\t                        task.wait(0.1)\n\t                    end\n\t                end\n\t                task.wait(0.1)\n\t            until not AutoBalloon.Enabled\n\t        end\n\t    end,\n\t    Tooltip = \"Inflates when you fall into the void\"\n\t})\nend)\n\nRun(function()\n\tlocal AutoBlockUp\n\tlocal LimitItem\n\tlocal LastPlace: number = 0\n\tlocal Up: boolean = false\n\t\n\tAutoBlockUp = vape.Categories.Utility:CreateModule({\n\t    Name = \"AutoBlockUp\",\n\t    Function = function(Callback: boolean)\n\t        if Callback then\n\t            AutoBlockUp:Clean(RunService.Heartbeat:Connect(function()\n\t                if Entity.isAlive and Up then\n\t                    local Item: string?\n\t                    if Store.hand.toolType == \"block\" and (Store.hand.amount or 0) > 0 then\n\t                        Item = Store.hand.tool and Store.hand.tool.Name\n\t                    elseif not LimitItem.Enabled then\n\t                        for _, v: any in Store.inventory.inventory.items do\n\t                            local Meta = bedwars.ItemMeta[v.itemType]\n\t                            if Meta and Meta.block and (v.amount or 0) > 0 then\n\t                                Item = v.itemType\n\t                                break\n\t                            end\n\t                        end\n\t                    end\n\t\n\t                    if Item then\n\t                        local Position: Vector3 = RoundPosition(Entity.character.RootPart.Position - Vector3.new(0, Entity.character.HipHeight + 1.5, 0))\n\t                        if tick() >= LastPlace and not GetPlacedBlock(Position) then\n\t                            LastPlace = tick() + 0.15\n\t                            bedwars.placeBlock(Position, Item, false)\n\t                        end\n\t\n\t                        Entity.character.RootPart.AssemblyLinearVelocity = Vector3.new(Entity.character.RootPart.AssemblyLinearVelocity.X, 35, Entity.character.RootPart.AssemblyLinearVelocity.Z)\n\t                    end\n\t                end\n\t            end))\n\t            AutoBlockUp:Clean(UserInputService.InputBegan:Connect(function(Input: InputObject)\n\t                if not UserInputService:GetFocusedTextBox() and (Input.KeyCode == Enum.KeyCode.Space or Input.KeyCode == Enum.KeyCode.ButtonA) then\n\t                    Up = true\n\t                end\n\t            end))\n\t            AutoBlockUp:Clean(UserInputService.InputEnded:Connect(function(Input: InputObject)\n\t                if Input.KeyCode == Enum.KeyCode.Space or Input.KeyCode == Enum.KeyCode.ButtonA then\n\t                    Up = false\n\t                    Entity.character.RootPart.AssemblyLinearVelocity = Vector3.new(Entity.character.RootPart.AssemblyLinearVelocity.X, 0, Entity.character.RootPart.AssemblyLinearVelocity.Z)\n\t                end\n\t            end))\n\t\n\t            local TouchGui = UserInputService.TouchEnabled and LocalPlayer.PlayerGui:FindFirstChild(\"TouchGui\")\n\t            local JumpButton = TouchGui and TouchGui:FindFirstChild(\"JumpButton\", true)\n\t            if JumpButton then\n\t                AutoBlockUp:Clean(JumpButton:GetPropertyChangedSignal(\"ImageRectOffset\"):Connect(function()\n\t                    Up = JumpButton.ImageRectOffset.X == 146\n\t                end))\n\t            end\n\t        end\n\t    end,\n\t    Tooltip = \"Places a block beneath you while holding jump so you can tower up instantly\"\n\t})\n\t\n\tLimitItem = AutoBlockUp:CreateToggle({Name = \"Limit to items\"})\nend)\n\nRun(function()\n\tlocal AutoCollect\n\tlocal Collectables\n\tlocal Range\n\tlocal Delay\n\tlocal Animation\n\t\n\tlocal Request = bedwars.Handler:Get(\"CollectCollectableEntity\")\n\tlocal Cooldowns: {[Instance]: number} = {}\n\t\n\tAutoCollect = vape.Categories.Utility:CreateModule({\n\t    Name = \"AutoCollect\",\n\t    Function = function(Callback: boolean)\n\t        if Callback then\n\t            repeat\n\t                if Entity.isAlive then\n\t                    local LocalPosition: Vector3 = Entity.character.RootPart.Position\n\t                    for _, v: string in Collectables.ListEnabled do\n\t                        for _, Collectable: Instance in CollectionService:GetTagged(v) do\n\t                            local Part = Collectable:IsA(\"Model\") and Collectable.PrimaryPart or Collectable\n\t                            local Id = Collectable:GetAttribute(\"Id\")\n\t                            if Part and Id and tick() > (Cooldowns[Collectable] or 0) and (LocalPosition - Part.Position).Magnitude <= Range.Value then\n\t                                if Animation.Enabled then\n\t                                    bedwars.GameAnimationUtil:playAnimation(LocalPlayer.Character, bedwars.AnimationType.PUNCH)\n\t                                    bedwars.ViewmodelController:playAnimation(bedwars.AnimationType.FP_USE_ITEM)\n\t                                end\n\t\n\t                                Request:Fire(\"SendToServer\", {\n\t                                    id = Id,\n\t                                    collectableName = Collectable.Name\n\t                                })\n\t                                Cooldowns[Collectable] = tick() + 1\n\t                            end\n\t                        end\n\t                    end\n\t                end\n\t                task.wait(Delay.Value)\n\t            until not AutoCollect.Enabled\n\t        else\n\t            table.clear(Cooldowns)\n\t        end\n\t    end,\n\t    Tooltip = \"Picks up every kit collectable near you without walking into it\"\n\t})\n\t\n\tRange = AutoCollect:CreateSlider({\n\t    Name = \"Range\",\n\t    Min = 1,\n\t    Max = 20,\n\t    Default = 11,\n\t    Suffix = function(Val: number)\n\t        return Val <= 1 and \"stud\" or \"studs\"\n\t    end,\n\t    Tooltip = \"The server drops collects past 12 studs\"\n\t})\n\tDelay = AutoCollect:CreateSlider({\n\t    Name = \"Delay\",\n\t    Min = 0.05,\n\t    Max = 1,\n\t    Default = 0.1,\n\t    Decimal = 100,\n\t    Suffix = \"seconds\"\n\t})\n\tAnimation = AutoCollect:CreateToggle({\n\t    Name = \"Animation\",\n\t    Default = true,\n\t    Tooltip = \"Plays the pickup animation\"\n\t})\n\tCollectables = AutoCollect:CreateTextList({\n\t    Name = \"Collectables\",\n\t    Default = {\n\t        \"alchemist_ingedients\",\n\t        \"alchemy_crystal\",\n\t        \"crystalheart_seed\",\n\t        \"forest_environment_plant\",\n\t        \"jailor_soul\",\n\t        \"murder_coin\",\n\t        \"shadow_coin\",\n\t        \"soulvine_seed\",\n\t        \"spirit_gardener_energy\",\n\t        \"spirit_gardener_seeds\",\n\t        \"tearbloom_seed\"\n\t    },\n\t    Darker = true,\n\t    Tooltip = \"Collectable tags to pick up, stars and hidden metal have their own modules\"\n\t})\nend)\n\nRun(function()\n\tlocal AutoCounter\n\tlocal Range\n\tlocal Limit\n\tlocal AutoSwitch = {}\n\t\n\tAutoCounter = vape.Categories.Utility:CreateModule({\n\t    Name = \"AutoCounterTNT\",\n\t    Function = function(Callback: boolean)\n\t        if Callback then\n\t            local TNTs, Placed = {}, {}\n\t            AutoCounter:Clean(workspace.ChildAdded:Connect(function(Child: Instance)\n\t                if Child.Name == \"tnt\" then\n\t                    table.insert(TNTs, Child)\n\t                    Child.Destroying:Once(function()\n\t                        local Index: number? = table.find(TNTs, Child)\n\t                        if Index then\n\t                            table.remove(TNTs, Index)\n\t                        end\n\t                    end)\n\t                end\n\t            end))\n\t            repeat\n\t                for Position: Vector3, Expiry: number in Placed do\n\t                    if Expiry <= tick() then\n\t                        Placed[Position] = nil\n\t                    end\n\t                end\n\t                if Entity.isAlive then\n\t                    local Item: Instance?\n\t                    if Limit.Enabled then\n\t                        Item = Store.hand.tool and Store.hand.tool.Name == \"tnt\" and Store.hand.tool or nil\n\t                    else\n\t                        local Held = GetItem(\"tnt\")\n\t                        Item = Held and Held.tool or nil\n\t                    end\n\t\n\t                    if Item then\n\t                        local LocalPosition: Vector3 = Entity.character.RootPart.Position\n\t                        for _, v: BasePart in TNTs do\n\t                            local RoundedPosition: Vector3 = Vector3.new(math.round(v.Position.X), math.round(v.Position.Y), math.round(v.Position.Z))\n\t                            if v.AssemblyLinearVelocity.Y >= 0 and not Placed[RoundedPosition] and (LocalPosition - v.Position).Magnitude <= Range.Value then\n\t                                if not Limit.Enabled and AutoSwitch.Enabled then\n\t                                    local Hotbar: number? = GetHotbar(Item)\n\t                                    SwitchItem(Item)\n\t                                    if Hotbar then\n\t                                        HotbarSwitch(Hotbar)\n\t                                    end\n\t                                end\n\t                                Placed[RoundedPosition] = tick() + 3\n\t                                task.spawn(bedwars.placeBlock, v.Position, Item.Name)\n\t                                task.wait(0.12)\n\t                            end\n\t                        end\n\t                    end\n\t                end\n\t                task.wait(0.1)\n\t            until not AutoCounter.Enabled\n\t        end\n\t    end,\n\t    Tooltip = \"Automatically places tnt on opponent's tnt\"\n\t})\n\t\n\tAutoCounter:CreateDropdown({\n\t    Name = \"Mode\",\n\t    List = {\"Toggle\", \"On key\"},\n\t    Default = \"Toggle\"\n\t})\n\tRange = AutoCounter:CreateSlider({\n\t    Name = \"Range\",\n\t    Min = 1,\n\t    Max = 60,\n\t    Default = 30\n\t})\n\tLimit = AutoCounter:CreateToggle({\n\t    Name = \"Limit to item\",\n\t    Function = function(Callback: boolean)\n\t        if AutoSwitch.Object then\n\t            AutoSwitch.Object.Visible = not Callback\n\t        end\n\t    end\n\t})\n\tAutoSwitch = AutoCounter:CreateToggle({\n\t    Name = \"Auto Switch\",\n\t    Function = function(Callback: boolean)\n\t        Limit.Object.Visible = not Callback\n\t    end,\n\t    Default = true\n\t})\nend)\n\nRun(function()\n\tlocal AutoHonor\n\tlocal Delay\n\t\n\tlocal Honored = {}\n\tlocal function Honor()\n\t    local PlayerList, Team = Players:GetPlayers(), LocalPlayer:GetAttribute(\"Team\")\n\t    table.sort(PlayerList, function(A: Player, B: Player)\n\t        return A:GetAttribute(\"Team\") == Team and B:GetAttribute(\"Team\") ~= Team\n\t    end)\n\t    for _, v: Player in PlayerList do\n\t        local TeamId = v:GetAttribute(\"Team\")\n\t        if v ~= LocalPlayer and TeamId and not Honored[TeamId] and (LocalPlayer:GetAttribute(TeamId == Team and \"HonorPointsLeftToGiveToAllies\" or \"HonorPointsLeftToGiveToOpponents\") or 0) > 0 then\n\t            Honored[TeamId] = true\n\t            bedwars.HonorController:honorPlayer(v.UserId):await()\n\t            task.wait(Delay.Value)\n\t        end\n\t    end\n\tend\n\t\n\tAutoHonor = vape.Categories.Utility:CreateModule({\n\t    Name = \"AutoHonor\",\n\t    Function = function(Callback: boolean)\n\t        if Callback then\n\t            AutoHonor:Clean(VapeEvents.EntityDeathEvent.Event:Connect(function(DeathTable)\n\t                if DeathTable.finalKill and DeathTable.entityInstance == LocalPlayer.Character and #bedwars.Store:getState().Party.members <= 0 and Store.matchState ~= 2 then\n\t                    Honor()\n\t                end\n\t            end))\n\t            AutoHonor:Clean(VapeEvents.MatchEndEvent.Event:Connect(Honor))\n\t        end\n\t    end,\n\t    Tooltip = \"Automatically honor your teammates\"\n\t})\n\t\n\tDelay = AutoHonor:CreateSlider({\n\t    Name = \"Delay\",\n\t    Min = 0,\n\t    Max = 2,\n\t    Decimal = 100,\n\t    Suffix = \"seconds\",\n\t    Default = 0.1\n\t})\nend)\n\nRun(function()\n\tlocal AutoMiner\n\tlocal Delay\n\tlocal Animation\n\tlocal Range\n\t\n\tlocal Legit: number = GetFunctionRange(bedwars.MinerController.setupMinerPrompts) or 0\n\tlocal Session = nil\n\t\n\tAutoMiner = vape.Categories.Utility:CreateModule({\n\t    Name = \"AutoMiner\",\n\t    Function = function(Callback: boolean)\n\t        if Callback then\n\t            local Petrified = Collection(\"petrified-player\", AutoMiner)\n\t            local Tries: {[Instance]: number} = setmetatable({}, {__mode = \"k\"})\n\t            local LastTry: {[Instance]: number} = setmetatable({}, {__mode = \"k\"})\n\t            local Current = {}\n\t            local Cooldown: number = 0\n\t            Session = Current\n\t\n\t            repeat\n\t                if Entity.isAlive and tick() - Cooldown >= math.max(Delay.Value, 0.25) then\n\t                    local LocalPosition: Vector3 = Entity.character.RootPart.Position\n\t                    local MyTeam = bedwars.Store:getState().Game.myTeam\n\t                    local RetryGap: number = Delay.Value + 1\n\t                    local Best, BestTries, BestDistance = nil, math.huge, math.huge\n\t                    for _, v: Instance in Petrified do\n\t                        local Root: BasePart? = if not v.Parent then nil elseif v:IsA(\"Model\") then v.PrimaryPart elseif v:IsA(\"BasePart\") then v else nil\n\t                        if not Root or not v:GetAttribute(\"PetrifyId\") then\n\t                            continue\n\t                        end\n\t                        if MyTeam and v:GetAttribute(\"Team\") == MyTeam.id then\n\t                            continue\n\t                        end\n\t                        if LastTry[v] and (tick() - LastTry[v]) < RetryGap then\n\t                            continue\n\t                        end\n\t\n\t                        local Distance: number = (LocalPosition - Root.Position).Magnitude\n\t                        local Count: number = Tries[v] or 0\n\t                        if Distance <= Range.Value and (Count < BestTries or (Count == BestTries and Distance < BestDistance)) then\n\t                            Best, BestTries, BestDistance = v, Count, Distance\n\t                        end\n\t                    end\n\t\n\t                    if Best then\n\t                        local Target: Instance = Best\n\t                        local PetrifyId = Target:GetAttribute(\"PetrifyId\")\n\t                        Tries[Target] = BestTries + 1\n\t                        LastTry[Target] = tick()\n\t                        if Animation.Enabled then\n\t                            bedwars.GameAnimationUtil:playAnimation(LocalPlayer.Character, bedwars.AnimationType.MINER_MINE_STONE)\n\t                        end\n\t\n\t                        task.delay(Delay.Value, function()\n\t                            if AutoMiner.Enabled and Target.Parent then\n\t                                bedwars.Handler:Get(\"DestroyPetrifiedPlayer\"):Fire(\"SendToServer\", {\n\t                                    petrifyId = PetrifyId\n\t                                })\n\t                            end\n\t                        end)\n\t                        Cooldown = tick()\n\t                    end\n\t                end\n\t                task.wait(0.1)\n\t            until not AutoMiner.Enabled or Session ~= Current\n\t        end\n\t    end,\n\t    Tooltip = \"Automatically mines the closest enemy petrified player within range\"\n\t})\n\t\n\tRange = AutoMiner:CreateSlider({\n\t    Name = \"Range\",\n\t    Min = 1,\n\t    Max = 30,\n\t    Default = 12,\n\t    Suffix = function(Val: number)\n\t        return Val <= 1 and \"stud\" or \"studs\"\n\t    end\n\t})\n\tAutoMiner:CreateButton({\n\t    Name = \"Sync to legit range\",\n\t    Function = function()\n\t        Range:SetValue(Legit)\n\t    end\n\t})\n\tDelay = AutoMiner:CreateSlider({\n\t    Name = \"Delay\",\n\t    Min = 0,\n\t    Max = 2,\n\t    Default = 0.1,\n\t    Decimal = 10,\n\t    Suffix = \"seconds\"\n\t})\n\tAnimation = AutoMiner:CreateToggle({\n\t    Name = \"Animation\",\n\t    Default = true\n\t})\nend)\n\nRun(function()\n\tlocal AutoPearl\n\tlocal Legit\n\tlocal Back\n\tlocal Check\n\tlocal LandCheck\n\tlocal BackDelay\n\tlocal Limit\n\tlocal ClutchRange\n\tlocal Cooldown\n\tlocal LastThrow: number = 0\n\tlocal Attempted: boolean = false\n\tlocal InFlight\n\t\n\tlocal RayCheck: RaycastParams = RaycastParams.new()\n\tRayCheck.RespectCanCollide = true\n\tRayCheck.FilterType = Enum.RaycastFilterType.Include\n\t\n\tlocal function GetLaunch(From: Vector3, Spot: Vector3): Vector3?\n\t    local Meta = bedwars.ProjectileMeta.telepearl\n\t    local AimPosition: Vector3? = PredictionLib.SolveTrajectory(From, Meta.launchVelocity, Meta.gravitationalAcceleration or 196.2, Spot, Vector3.zero, workspace.Gravity, 0, 0, nil, false, nil, nil, nil, true)\n\t    return AimPosition and CFrame.lookAt(From, AimPosition).LookVector * Meta.launchVelocity or nil\n\tend\n\t\n\tlocal function CanReach(From: Vector3, Spot: Vector3): boolean\n\t    local Meta = bedwars.ProjectileMeta.telepearl\n\t    local Speed: number = Meta.launchVelocity\n\t    local Gravity: number = Meta.gravitationalAcceleration or 196.2\n\t    local Offset: Vector3 = Spot - From\n\t    local Flat: number = Vector2.new(Offset.X, Offset.Z).Magnitude\n\t    return Speed ^ 4 - Gravity * (Gravity * Flat ^ 2 + 2 * Offset.Y * Speed ^ 2) >= 0\n\tend\n\t\n\tlocal function FirePearl(Spot: Vector3, Item): boolean\n\t    if not Entity.isAlive or not GetLaunch(Entity.character.RootPart.Position, Spot) then\n\t        return false\n\t    end\n\t\n\t    local Hotbar, OldHand = GetHotbar(Item.tool), Store.hand\n\t    local PreviousThrow: number = LastThrow\n\t    local ThrowUntil: number = tick() + Cooldown.Value\n\t    LastThrow = ThrowUntil\n\t\n\t    SwitchItem(Item.tool)\n\t    if Legit.Enabled and Hotbar then\n\t        HotbarSwitch(Hotbar)\n\t    end\n\t\n\t    local Position: Vector3 = Entity.character.RootPart.Position\n\t    local Direction: Vector3? = Entity.isAlive and GetLaunch(Position, Spot) or nil\n\t    local Landed: boolean = false\n\t\n\t    if Direction then\n\t        local Meta = bedwars.ProjectileMeta.telepearl\n\t        local Id: string = bedwars.IdUtil.generateId(8)\n\t        local ShotData = bedwars.getShotData(\"telepearl\")\n\t        local Projectile = bedwars.ProjectileController:createLocalProjectile(Meta, \"telepearl\", \"telepearl\", Position, Id, Direction, ShotData)\n\t        InFlight = Projectile\n\t        local Tracked = Projectile\n\t        local Pending: boolean = Projectile == nil\n\t\n\t        bedwars.Handler:Get(\"ProjectileFire\"):Fire(\"CallServerAsync\",\n\t            Item.tool,\n\t            \"telepearl\",\n\t            \"telepearl\",\n\t            Position,\n\t            Position,\n\t            Direction,\n\t            Id,\n\t            ShotData,\n\t            workspace:GetServerTimeNow() - 0.045\n\t        ):andThen(function(Result)\n\t            Pending = false\n\t            if type(Result) == \"table\" and Result.accepted then\n\t                if Projectile == nil and typeof(Result.model) == \"Instance\" then\n\t                    Tracked, InFlight = Result.model, Result.model\n\t                elseif Result.model then\n\t                    Result.model.Parent = ReplicatedStorage\n\t                end\n\t                return\n\t            end\n\t\n\t            if LastThrow == ThrowUntil then\n\t                LastThrow = PreviousThrow\n\t            end\n\t            if InFlight == Projectile then\n\t                InFlight = nil\n\t            end\n\t            Attempted = false\n\t        end)\n\t\n\t        task.spawn(function()\n\t            local Timeout: number = tick() + 10\n\t            repeat\n\t                task.wait()\n\t            until not AutoPearl.Enabled or tick() >= Timeout or (not Pending and (not Tracked or not Tracked.Parent))\n\t            Landed = true\n\t        end)\n\t    else\n\t        if LastThrow == ThrowUntil then\n\t            LastThrow = PreviousThrow\n\t        end\n\t        Landed = true\n\t    end\n\t\n\t    if Back.Enabled and LandCheck.Enabled then\n\t        repeat\n\t            task.wait()\n\t        until Landed or not AutoPearl.Enabled\n\t    end\n\t\n\t    if Back.Enabled and OldHand and OldHand.tool then\n\t        task.wait(BackDelay:GetRandomValue())\n\t        SwitchItem(OldHand.tool)\n\t        if Legit.Enabled and GetHotbar(OldHand.tool) then\n\t            HotbarSwitch(GetHotbar(OldHand.tool))\n\t        end\n\t    end\n\t\n\t    return Direction ~= nil\n\tend\n\t\n\tlocal function FindNearGround(Origin: Vector3, From: Vector3): Vector3?\n\t    for Radius: number = 2, ClutchRange.Value, 3 do\n\t        local Count: number = math.max(8, math.ceil(2 * math.pi * Radius / 6))\n\t        for i: number = 1, Count do\n\t            local Angle: number = 2 * math.pi * i / Count\n\t            local Start: Vector3 = Origin + Vector3.new(math.cos(Angle) * Radius, 3, math.sin(Angle) * Radius)\n\t            local Ray: RaycastResult? = workspace:Raycast(Start, Vector3.new(0, -60, 0), RayCheck)\n\t            if Ray and CanReach(From, Ray.Position) and GetLaunch(From, Ray.Position) then\n\t                return Ray.Position\n\t            end\n\t        end\n\t    end\n\t\n\t    return nil\n\tend\n\t\n\tAutoPearl = vape.Categories.Utility:CreateModule({\n\t    Name = \"AutoPearl\",\n\t    Function = function(Callback: boolean)\n\t        if Callback then\n\t            local Connection = bedwars.SyncEvents.ProjectileLaunched:connect(function(Event)\n\t                if Event.projectileType ~= \"telepearl\" or typeof(Event.projectile) ~= \"Instance\" or not Event.projectile:IsA(\"PVInstance\") or not Entity.isAlive then\n\t                    return\n\t                end\n\t                if Event.shooter == Entity.character.Character then\n\t                    InFlight = Event.projectile\n\t                end\n\t            end)\n\t\n\t            AutoPearl:Clean(function()\n\t                Connection:Destroy()\n\t            end)\n\t\n\t            local LastGround: Vector3?\n\t            repeat\n\t                if Store.map then\n\t                    RayCheck.FilterDescendantsInstances = {Store.map}\n\t                    RayCheck.CollisionGroup = Entity.isAlive and Entity.character.RootPart.CollisionGroup or \"\"\n\t\n\t                    local Item\n\t                    if Entity.isAlive and tick() >= LastThrow and not (Check.Enabled and InFlight and InFlight.Parent) and not (Limit.Enabled and not (Store.hand.tool and Store.hand.tool.Name == \"telepearl\")) then\n\t                        Item = GetItem(\"telepearl\")\n\t                    end\n\t\n\t                    local Root = Entity.isAlive and Entity.character.RootPart\n\t                    if Root and Entity.character.Humanoid.FloorMaterial ~= Enum.Material.Air then\n\t                        LastGround = Root.Position\n\t                    end\n\t\n\t                    if Item and Root and Root.AssemblyLinearVelocity.Y < -100 and not workspace:Raycast(Root.Position, Vector3.new(0, -200, 0), RayCheck) then\n\t                        if not Attempted then\n\t                            Attempted = true\n\t                            local Ground: Vector3? = FindNearGround(Root.Position + Vector3.new(0, 40, 0), Root.Position) or FindNearGround(LastGround and LastGround + Vector3.new(0, 5, 0) or Root.Position, Root.Position)\n\t                            if Ground and not FirePearl(Ground, Item) then\n\t                                Attempted = false\n\t                            end\n\t                        end\n\t                    else\n\t                        Attempted = false\n\t                    end\n\t                end\n\t\n\t                task.wait(0.1)\n\t            until not AutoPearl.Enabled\n\t        else\n\t            InFlight = nil\n\t            Attempted = false\n\t        end\n\t    end,\n\t    Tooltip = \"Throws a pearl onto nearby ground when you fall into the void\"\n\t})\n\t\n\tLegit = AutoPearl:CreateToggle({\n\t    Name = \"Legit Switch\",\n\t    Tooltip = \"Visualizes the switching clientside\",\n\t    Default = true\n\t})\n\tBack = AutoPearl:CreateToggle({\n\t    Name = \"Switch back\",\n\t    Function = function(Callback: boolean)\n\t        if BackDelay then\n\t            BackDelay.Object.Visible = Callback\n\t        end\n\t        if LandCheck then\n\t            LandCheck.Object.Visible = Callback\n\t        end\n\t    end,\n\t    Default = true,\n\t    Tooltip = \"Switches back to the last slot before pearl\"\n\t})\n\tLandCheck = AutoPearl:CreateToggle({\n\t    Name = \"Only after landed\",\n\t    Tooltip = \"Only switches back after your pearl landed\",\n\t    Darker = true\n\t})\n\tCheck = AutoPearl:CreateToggle({\n\t    Name = \"Pearl check\",\n\t    Default = true,\n\t    Tooltip = \"Doesn't throw a pearl while one of yours is still in the air, including ones you threw yourself\"\n\t})\n\tBackDelay = AutoPearl:CreateTwoSlider({\n\t    Name = \"Switch Back Delay\",\n\t    Min = 0,\n\t    Max = 2,\n\t    DefaultMin = 0.1,\n\t    DefaultMax = 0.2,\n\t    Darker = true\n\t})\n\tClutchRange = AutoPearl:CreateSlider({\n\t    Name = \"Clutch range\",\n\t    Min = 10,\n\t    Max = 100,\n\t    Default = 24,\n\t    Suffix = \"studs\",\n\t    Tooltip = \"How far away a block can be for a void save, blocks your pearl cannot reach are skipped\"\n\t})\n\tCooldown = AutoPearl:CreateSlider({\n\t    Name = \"Cooldown\",\n\t    Min = 0,\n\t    Max = 5,\n\t    Default = 1,\n\t    Decimal = 10,\n\t    Suffix = \"seconds\",\n\t    Tooltip = \"Minimum gap between two throws\"\n\t})\n\tLimit = AutoPearl:CreateToggle({\n\t    Name = \"Limit to item\",\n\t    Tooltip = \"Only throws pearl when holding a pearl\"\n\t})\nend)\n\nRun(function()\n\tlocal AutoPearlAggro\n\tlocal Legit\n\tlocal Back\n\tlocal Check\n\tlocal LandCheck\n\tlocal BackDelay\n\tlocal Limit\n\tlocal Distance\n\tlocal MinHealth\n\tlocal Cooldown\n\tlocal LastThrow: number = 0\n\tlocal InFlight\n\t\n\tlocal FollowMinimum: number = 12\n\tlocal LandingTolerance: number = 4\n\tlocal FlightStep: number = 0.05\n\tlocal MaxFlight: number = 4\n\tlocal PearlBox: Vector3 = Vector3.new(3, 1, 3)\n\t\n\tlocal function PredictLanding(Origin: Vector3, Velocity: Vector3, Gravity: number): Vector3?\n\t    local Drop: Vector3 = Vector3.new(0, -Gravity, 0)\n\t    local Last: Vector3 = Origin\n\t    for Step: number = 1, math.round(MaxFlight / FlightStep) do\n\t        local Time: number = Step * FlightStep\n\t        local Position: Vector3 = Origin + Velocity * Time + Drop * (0.5 * Time * Time)\n\t        local Direction: Vector3 = Position - Last\n\t        local Hit: RaycastResult? = workspace:Blockcast(CFrame.new(Last), PearlBox, Direction, Store.airRay)\n\t        if Hit then\n\t            return Last + Direction.Unit * Hit.Distance\n\t        end\n\t        Last = Position\n\t    end\n\t\n\t    return nil\n\tend\n\t\n\tlocal function GetLaunch(From: Vector3, Spot: Vector3): Vector3?\n\t    local Meta = bedwars.ProjectileMeta.telepearl\n\t    local Speed: number = Meta.launchVelocity\n\t    local Gravity: number = Meta.gravitationalAcceleration or 196.2\n\t    local Offset: Vector3 = Spot - From\n\t    local Flat: Vector3 = Offset * Vector3.new(1, 0, 1)\n\t    local Discriminant: number = Speed ^ 4 - Gravity * (Gravity * Flat.Magnitude ^ 2 + 2 * Offset.Y * Speed ^ 2)\n\t    if Flat.Magnitude < 1 or Discriminant < 0 then\n\t        return nil\n\t    end\n\t\n\t    for _, v: number in {-1, 1} do\n\t        local Angle: number = math.atan((Speed ^ 2 + v * math.sqrt(Discriminant)) / (Gravity * Flat.Magnitude))\n\t        local Velocity: Vector3 = Flat.Unit * (math.cos(Angle) * Speed) + Vector3.new(0, math.sin(Angle) * Speed, 0)\n\t        local Landing: Vector3? = PredictLanding(From, Velocity, Gravity)\n\t        if Landing and (Landing - Spot).Magnitude <= LandingTolerance then\n\t            return Velocity\n\t        end\n\t    end\n\t\n\t    return nil\n\tend\n\t\n\tlocal function FirePearl(Spot: Vector3, Item): boolean\n\t    if not Entity.isAlive or not GetLaunch(Entity.character.RootPart.Position, Spot) then\n\t        return false\n\t    end\n\t\n\t    local Hotbar, OldHand = GetHotbar(Item.tool), Store.hand\n\t    local PreviousThrow: number = LastThrow\n\t    local ThrowUntil: number = tick() + Cooldown.Value\n\t    LastThrow = ThrowUntil\n\t\n\t    SwitchItem(Item.tool)\n\t    if Legit.Enabled and Hotbar then\n\t        HotbarSwitch(Hotbar)\n\t    end\n\t\n\t    local Position: Vector3 = Entity.character.RootPart.Position\n\t    local Direction: Vector3? = Entity.isAlive and GetLaunch(Position, Spot) or nil\n\t    local Landed: boolean = false\n\t\n\t    if Direction then\n\t        local Meta = bedwars.ProjectileMeta.telepearl\n\t        local Id: string = bedwars.IdUtil.generateId(8)\n\t        local ShotData = bedwars.getShotData(\"telepearl\")\n\t        local Projectile = bedwars.ProjectileController:createLocalProjectile(Meta, \"telepearl\", \"telepearl\", Position, Id, Direction, ShotData)\n\t        InFlight = Projectile\n\t        local Tracked = Projectile\n\t        local Pending: boolean = Projectile == nil\n\t\n\t        bedwars.Handler:Get(\"ProjectileFire\"):Fire(\"CallServerAsync\",\n\t            Item.tool,\n\t            \"telepearl\",\n\t            \"telepearl\",\n\t            Position,\n\t            Position,\n\t            Direction,\n\t            Id,\n\t            ShotData,\n\t            workspace:GetServerTimeNow() - 0.045\n\t        ):andThen(function(Result)\n\t            Pending = false\n\t            if type(Result) == \"table\" and Result.accepted then\n\t                if Projectile == nil and typeof(Result.model) == \"Instance\" then\n\t                    Tracked, InFlight = Result.model, Result.model\n\t                elseif Result.model then\n\t                    Result.model.Parent = ReplicatedStorage\n\t                end\n\t                return\n\t            end\n\t\n\t            if LastThrow == ThrowUntil then\n\t                LastThrow = PreviousThrow\n\t            end\n\t            if InFlight == Projectile then\n\t                InFlight = nil\n\t            end\n\t        end)\n\t\n\t        task.spawn(function()\n\t            local Timeout: number = tick() + 10\n\t            repeat\n\t                task.wait()\n\t            until not AutoPearlAggro.Enabled or tick() >= Timeout or (not Pending and (not Tracked or not Tracked.Parent))\n\t            Landed = true\n\t        end)\n\t    else\n\t        if LastThrow == ThrowUntil then\n\t            LastThrow = PreviousThrow\n\t        end\n\t        Landed = true\n\t    end\n\t\n\t    if Back.Enabled and LandCheck.Enabled then\n\t        repeat\n\t            task.wait()\n\t        until Landed or not AutoPearlAggro.Enabled\n\t    end\n\t\n\t    if Back.Enabled and OldHand and OldHand.tool then\n\t        task.wait(BackDelay:GetRandomValue())\n\t        SwitchItem(OldHand.tool)\n\t        if Legit.Enabled and GetHotbar(OldHand.tool) then\n\t            HotbarSwitch(GetHotbar(OldHand.tool))\n\t        end\n\t    end\n\t\n\t    return Direction ~= nil\n\tend\n\t\n\tlocal function Follow(Origin: Vector3, Velocity: Vector3)\n\t    if not Entity.isAlive or not Store.airRay then\n\t        return\n\t    end\n\t\n\t    local Meta = bedwars.ProjectileMeta.telepearl\n\t    local Spot: Vector3? = PredictLanding(Origin, Velocity, Meta.gravitationalAcceleration or 196.2)\n\t    if not Spot or not AutoPearlAggro.Enabled or not Entity.isAlive then\n\t        return\n\t    end\n\t\n\t    local Position: Vector3 = Entity.character.RootPart.Position\n\t    local Gap: number = (Spot - Position).Magnitude\n\t    if Gap > Distance.Value or Gap < FollowMinimum or Gap < (Origin - Position).Magnitude then\n\t        return\n\t    end\n\t    if tick() < LastThrow or (Check.Enabled and InFlight and InFlight.Parent) then\n\t        return\n\t    end\n\t    if MinHealth.Value > 0 and Entity.character.Health < MinHealth.Value then\n\t        return\n\t    end\n\t    if Limit.Enabled and not (Store.hand.tool and Store.hand.tool.Name == \"telepearl\") then\n\t        return\n\t    end\n\t\n\t    local Item = GetItem(\"telepearl\")\n\t    if Item then\n\t        FirePearl(Spot, Item)\n\t    end\n\tend\n\t\n\tlocal function HandleLaunch(Event)\n\t    if Event.projectileType ~= \"telepearl\" or not Entity.isAlive then\n\t        return\n\t    end\n\t    if Event.shooter == Entity.character.Character then\n\t        if typeof(Event.projectile) == \"Instance\" and Event.projectile:IsA(\"PVInstance\") then\n\t            InFlight = Event.projectile\n\t        end\n\t        return\n\t    end\n\t    if typeof(Event.origin) ~= \"Vector3\" or typeof(Event.launchVelocity) ~= \"Vector3\" then\n\t        return\n\t    end\n\t\n\t    for _, v: any in Entity.List do\n\t        if v.Character == Event.shooter then\n\t            if v.Targetable then\n\t                task.spawn(Follow, Event.origin, Event.launchVelocity)\n\t            end\n\t            break\n\t        end\n\t    end\n\tend\n\t\n\tAutoPearlAggro = vape.Categories.Utility:CreateModule({\n\t    Name = \"AutoPearlAggro\",\n\t    Function = function(Callback: boolean)\n\t        if Callback then\n\t            local Connection = bedwars.SyncEvents.ProjectileLaunched:connect(HandleLaunch)\n\t\n\t            AutoPearlAggro:Clean(function()\n\t                Connection:Destroy()\n\t            end)\n\t\n\t            if not canDebug then\n\t                bedwars.Client:WaitFor(\"ProjectileLaunchClient\"):andThen(function(Remote)\n\t                    if not Remote or not AutoPearlAggro.Enabled then\n\t                        return\n\t                    end\n\t\n\t                    AutoPearlAggro:Clean(Remote:Connect(function(Data)\n\t                        if type(Data) ~= \"table\" then\n\t                            return\n\t                        end\n\t\n\t                        local Shooter = Data.shooter\n\t                        if typeof(Shooter) == \"Instance\" and Shooter:IsA(\"Player\") then\n\t                            Shooter = Shooter.Character\n\t                        end\n\t                        HandleLaunch({\n\t                            projectileType = Data.projectileType,\n\t                            shooter = Shooter,\n\t                            origin = Data.positionFrom,\n\t                            launchVelocity = Data.initialVelocity\n\t                        })\n\t                    end))\n\t                end)\n\t            end\n\t        else\n\t            InFlight = nil\n\t        end\n\t    end,\n\t    Tooltip = \"Predicts where an enemy pearl will land the moment it is thrown and pearls you to the same spot\\nPearls that fall into the void, land closer to you than the thrower stood, or that your pearl cannot reach are ignored\"\n\t})\n\t\n\tLegit = AutoPearlAggro:CreateToggle({\n\t    Name = \"Legit Switch\",\n\t    Tooltip = \"Visualizes the switching clientside\",\n\t    Default = true\n\t})\n\tBack = AutoPearlAggro:CreateToggle({\n\t    Name = \"Switch back\",\n\t    Function = function(Callback: boolean)\n\t        if BackDelay then\n\t            BackDelay.Object.Visible = Callback\n\t        end\n\t        if LandCheck then\n\t            LandCheck.Object.Visible = Callback\n\t        end\n\t    end,\n\t    Default = true,\n\t    Tooltip = \"Switches back to the last slot before pearl\"\n\t})\n\tLandCheck = AutoPearlAggro:CreateToggle({\n\t    Name = \"Only after landed\",\n\t    Tooltip = \"Only switches back after your pearl landed\",\n\t    Darker = true\n\t})\n\tCheck = AutoPearlAggro:CreateToggle({\n\t    Name = \"Pearl check\",\n\t    Default = true,\n\t    Tooltip = \"Doesn't throw a pearl while one of yours is still in the air, including ones you threw yourself\"\n\t})\n\tBackDelay = AutoPearlAggro:CreateTwoSlider({\n\t    Name = \"Switch Back Delay\",\n\t    Min = 0,\n\t    Max = 2,\n\t    DefaultMin = 0.1,\n\t    DefaultMax = 0.2,\n\t    Darker = true\n\t})\n\tDistance = AutoPearlAggro:CreateSlider({\n\t    Name = \"Distance limit\",\n\t    Min = 10,\n\t    Max = 200,\n\t    Default = 150,\n\t    Suffix = \"studs\",\n\t    Tooltip = \"How far away an enemy pearl can land before it is ignored\"\n\t})\n\tMinHealth = AutoPearlAggro:CreateSlider({\n\t    Name = \"Min health\",\n\t    Min = 0,\n\t    Max = 100,\n\t    Default = 0,\n\t    Tooltip = \"Never follows a pearl below this health, 0 disables the check\"\n\t})\n\tCooldown = AutoPearlAggro:CreateSlider({\n\t    Name = \"Cooldown\",\n\t    Min = 0,\n\t    Max = 5,\n\t    Default = 1,\n\t    Decimal = 10,\n\t    Suffix = \"seconds\",\n\t    Tooltip = \"Minimum gap between two throws\"\n\t})\n\tLimit = AutoPearlAggro:CreateToggle({\n\t    Name = \"Limit to item\",\n\t    Tooltip = \"Only throws pearl when holding a pearl\"\n\t})\nend)\n\nRun(function()\n\tlocal AutoPlay\n\tlocal Delay\n\tlocal Random\n\t\n\tlocal Pending: boolean = false\n\tlocal NextJoin: number = 0\n\t\n\tlocal function JoinQueue()\n\t    if Pending then\n\t        return\n\t    end\n\t\n\t    Pending = true\n\t    task.delay(Delay.Value, function()\n\t        Pending = false\n\t        local State = bedwars.Store:getState()\n\t        if not AutoPlay.Enabled or os.clock() < NextJoin or State.Game.customMatch or State.Party.leader.userId ~= LocalPlayer.UserId or State.Party.queueState ~= 0 then\n\t            return\n\t        end\n\t\n\t        NextJoin = os.clock() + 5\n\t        if Random.Enabled then\n\t            local Modes: {string} = {}\n\t            for QueueType: string, v: any in bedwars.QueueMeta do\n\t                if not v.disabled and not v.voiceChatOnly and not v.rankCategory then\n\t                    table.insert(Modes, QueueType)\n\t                end\n\t            end\n\t            bedwars.QueueController:joinQueue(Modes[math.random(1, #Modes)])\n\t        else\n\t            bedwars.QueueController:joinQueue(Store.queueType)\n\t        end\n\t    end)\n\tend\n\t\n\tAutoPlay = vape.Categories.Utility:CreateModule({\n\t    Name = \"AutoQueue\",\n\t    Function = function(Callback: boolean)\n\t        if Callback then\n\t            AutoPlay:Clean(VapeEvents.EntityDeathEvent.Event:Connect(function(DeathTable)\n\t                if DeathTable.finalKill and DeathTable.entityInstance == LocalPlayer.Character and #bedwars.Store:getState().Party.members <= 0 and Store.matchState ~= 2 then\n\t                    JoinQueue()\n\t                end\n\t            end))\n\t            AutoPlay:Clean(VapeEvents.MatchEndEvent.Event:Connect(JoinQueue))\n\t        end\n\t    end,\n\t    Tooltip = \"Automatically queues after the match ends.\"\n\t})\n\t\n\tDelay = AutoPlay:CreateSlider({\n\t    Name = \"Delay\",\n\t    Min = 0,\n\t    Max = 10,\n\t    Decimal = 10,\n\t    Default = 0,\n\t    Suffix = function(Value: number)\n\t        return Value == 1 and \"second\" or \"seconds\"\n\t    end,\n\t    Tooltip = \"How long to wait after the match ends, or after your final death when you are solo, before queueing\"\n\t})\n\tRandom = AutoPlay:CreateToggle({\n\t    Name = \"Random\",\n\t    Tooltip = \"Chooses a random mode\"\n\t})\nend)\n\nRun(function()\n\tlocal AutoReset\n\tlocal Delay\n\tlocal Pearl\n\tlocal Whisper\n\tlocal Lasso\n\tlocal LowestPoint: number = math.huge\n\t\n\tlocal function GetVoidLine(): number\n\t    if LowestPoint == math.huge then\n\t        for _, v: BasePart in Store.blocks do\n\t            local Point: number = (v.Position.Y - (v.Size.Y / 2)) - 50\n\t            if Point < LowestPoint then\n\t                LowestPoint = Point\n\t            end\n\t        end\n\t    end\n\t    return LowestPoint\n\tend\n\t\n\tlocal function IsLassoed(): boolean\n\t    for _, v: Instance in LocalPlayer.Character and LocalPlayer.Character:GetChildren() or {} do\n\t        if v:IsA(\"Accessory\") and v:FindFirstChild(\"Rope\") then\n\t            return true\n\t        end\n\t    end\n\t    return false\n\tend\n\t\n\tlocal function CanSave(): boolean\n\t    if Pearl.Enabled and GetItem(\"telepearl\") then\n\t        return true\n\t    end\n\t    if Whisper.Enabled and LocalPlayer:GetAttribute(\"IsOwlTarget\") then\n\t        return true\n\t    end\n\t    return Lasso.Enabled and IsLassoed()\n\tend\n\t\n\tAutoReset = vape.Categories.Utility:CreateModule({\n\t    Name = \"AutoReset\",\n\t    Function = function(Callback: boolean)\n\t        if Callback then\n\t            local Falling\n\t            repeat\n\t                if Store.matchState == 1 and Entity.isAlive then\n\t                    local Character = Entity.character\n\t                    local Root: BasePart = Character.RootPart\n\t                    if Falling and Falling ~= Character then\n\t                        Falling = nil\n\t                    end\n\t\n\t                    if not Falling and not CanSave() and Root.Position.Y < GetVoidLine() and Root.AssemblyLinearVelocity.Y < 0 and not workspace:Raycast(Root.Position, Vector3.new(0, -2000, 0), Store.airRay) then\n\t                        Falling = Character\n\t                        task.delay(Delay.Value, function()\n\t                            if AutoReset.Enabled and Entity.isAlive and Entity.character == Character and Root.Parent and not CanSave() and Root.AssemblyLinearVelocity.Y < 0 and not workspace:Raycast(Root.Position, Vector3.new(0, -2000, 0), Store.airRay) then\n\t                                bedwars.Handler:Get(\"ResetCharacter\"):Fire(\"SendToServer\")\n\t                            elseif Falling == Character then\n\t                                Falling = nil\n\t                            end\n\t                        end)\n\t                    end\n\t                else\n\t                    Falling = nil\n\t                end\n\t                task.wait(0.05)\n\t            until not AutoReset.Enabled\n\t        end\n\t    end,\n\t    Tooltip = \"Resets once you fall past the void line so you can respawn sooner, leaving you room to clutch before then\"\n\t})\n\t\n\tDelay = AutoReset:CreateSlider({\n\t    Name = \"Delay\",\n\t    Min = 0,\n\t    Max = 2,\n\t    Default = 0,\n\t    Decimal = 10,\n\t    Suffix = function(Value: number)\n\t        return Value == 1 and \"second\" or \"seconds\"\n\t    end,\n\t    Tooltip = \"How long to wait before resetting. 0 resets instantly\"\n\t})\n\tPearl = AutoReset:CreateToggle({\n\t    Name = \"Pearl check\",\n\t    Default = true,\n\t    Tooltip = \"Never resets while you are carrying a telepearl, so you keep the chance to pearl back\"\n\t})\n\tWhisper = AutoReset:CreateToggle({\n\t    Name = \"Whisper check\",\n\t    Default = true,\n\t    Tooltip = \"Never resets while an owl is assigned to you, so a Whisper can still lift you out\"\n\t})\n\tLasso = AutoReset:CreateToggle({\n\t    Name = \"Lasso check\",\n\t    Default = true,\n\t    Tooltip = \"Never resets while a lasso is attached to you, so the pull can drag you back to safety\"\n\t})\nend)\n\nRun(function()\n\tlocal AutoShoot\n\tlocal Targets\n\tlocal Check\n\tlocal Animation\n\tlocal Projectiles\n\tlocal UseSophia\n\tlocal UseWhim\n\tlocal UseNazar\n\tlocal UseUmeko\n\tlocal UseLasso\n\tlocal FireRate\n\tlocal SwitchDelay\n\t\n\tlocal FireDelays = {}\n\t\n\tlocal function GetShots(): {{any}}\n\t    local Shots: {{any}} = GetProjectiles(Projectiles.ListEnabled, UseSophia.Enabled, UseWhim.Enabled, UseNazar.Enabled, UseUmeko.Enabled)\n\t    local Lasso = UseLasso.Enabled and GetItem(\"lasso\") or nil\n\t    local Source = Lasso and bedwars.ItemMeta.lasso.projectileSource or nil\n\t    if not Source then\n\t        return Shots\n\t    end\n\t\n\t    for _, v: {any} in Shots do\n\t        if v[1].itemType == \"lasso\" then\n\t            return Shots\n\t        end\n\t    end\n\t    table.insert(Shots, {Lasso, \"lasso\", Source.projectileType(\"lasso\"), Source})\n\t    return Shots\n\tend\n\t\n\tlocal function GetEntity()\n\t    local LocalPosition: Vector3 = Entity.character.RootPart.Position\n\t    local Entities = Entity.AllPosition({\n\t        Origin = LocalPosition,\n\t        Part = \"RootPart\",\n\t        Range = 22,\n\t        Players = Targets.Players.Enabled,\n\t        NPCs = Targets.NPCs.Enabled,\n\t        Priority = Targets.Priority.Value,\n\t        Wallcheck = Targets.Walls.Enabled,\n\t        Limit = 10\n\t    })\n\t    if #Entities > 0 then\n\t        for _, v: any in Entities do\n\t            local LocalFacing: Vector3 = Entity.character.RootPart.CFrame.LookVector * Vector3.new(1, 0, 1)\n\t            local Delta: Vector3 = (v.RootPart.Position - LocalPosition) * Vector3.new(1, 0, 1)\n\t            local Angle: number = LocalFacing.Magnitude > 0 and Delta.Magnitude > 0 and math.acos(math.clamp(LocalFacing.Unit:Dot(Delta.Unit), -1, 1)) or 0\n\t            if Angle > (math.rad(120) / 2) then\n\t                continue\n\t            end\n\t            return v\n\t        end\n\t    end\n\t    return nil\n\tend\n\t\n\tAutoShoot = vape.Categories.Utility:CreateModule({\n\t    Name = \"AutoShoot\",\n\t    Function = function(Callback: boolean)\n\t        if Callback then\n\t            repeat\n\t                if Entity.isAlive and Store.hand.toolType == \"sword\" and (tick() - bedwars.SwordController.lastSwing) < 0.2 then\n\t                    local OldTool, OldHotbar = Store.hand.tool, Store.inventory.hotbarSlot\n\t                    for _, v: {any} in GetShots() do\n\t                        local Item, Ammo, Projectile, ItemMeta = unpack(v)\n\t                        if (FireDelays[Item.itemType] or 0) < tick() then\n\t                            local Ent = GetEntity()\n\t                            if not Check.Enabled or Ent then\n\t                                local Hotbar: number? = GetHotbar(Item.tool)\n\t                                SwitchItem(Item.tool)\n\t                                if Hotbar then\n\t                                    HotbarSwitch(Hotbar)\n\t                                end\n\t\n\t                                local Meta = bedwars.ProjectileMeta[Projectile]\n\t                                local ProjectileSpeed, Gravity = Meta.launchVelocity, Meta.gravitationalAcceleration or 196.2\n\t                                local Origin: Vector3 = Entity.character.RootPart.Position\n\t                                local TargetPosition = Ent and PredictionLib.SolveTrajectory(Origin, ProjectileSpeed, Gravity, Ent.RootPart.Position, Ent.RootPart.AssemblyLinearVelocity, workspace.Gravity, Ent.HipHeight, Ent.Jumping and 42.6 or nil, nil, Ent.Humanoid.FloorMaterial == Enum.Material.Air or math.abs(Ent.RootPart.AssemblyLinearVelocity.Y) > 0.01, Ent.RootPart.Position, Ent.RootPart, nil, true) or (not Ent and (Origin + Camera.CFrame.LookVector * 100))\n\t                                if TargetPosition then\n\t                                    local ShootPosition: Vector3 = (CFrame.new(Origin, TargetPosition) * CFrame.new(Vector3.new(-bedwars.BowConstantsTable.RelX, -bedwars.BowConstantsTable.RelY, -bedwars.BowConstantsTable.RelZ))).Position\n\t                                    local Aim: Vector3 = Ent and PredictionLib.SolveTrajectory(ShootPosition, ProjectileSpeed, Gravity, Ent.RootPart.Position, Ent.RootPart.AssemblyLinearVelocity, workspace.Gravity, Ent.HipHeight, Ent.Jumping and 42.6 or nil, nil, Ent.Humanoid.FloorMaterial == Enum.Material.Air or math.abs(Ent.RootPart.AssemblyLinearVelocity.Y) > 0.01, Ent.RootPart.Position, Ent.RootPart, nil, true) or TargetPosition\n\t                                    if Animation.Enabled and canDebug then\n\t                                        bedwars.ProjectileController:launchProjectileWithValues({\n\t                                            initialVelocity = CFrame.lookAt(ShootPosition, Aim).LookVector * ProjectileSpeed,\n\t                                            positionFrom = ShootPosition,\n\t                                            drawDurationSeconds = 1\n\t                                        }, Item.tool, ItemMeta, Ammo, nil, Projectile):await()\n\t                                    else\n\t                                        local Direction, Id = CFrame.lookAt(ShootPosition, Aim).LookVector, bedwars.IdUtil.generateId(8)\n\t                                        bedwars.Handler:Get(\"ProjectileFire\"):Fire(\"CallServerAsync\",\n\t                                            Item.tool,\n\t                                            Ammo,\n\t                                            Projectile,\n\t                                            ShootPosition,\n\t                                            Origin,\n\t                                            Direction * ProjectileSpeed,\n\t                                            Id,\n\t                                            bedwars.getShotData(Item.itemType),\n\t                                            workspace:GetServerTimeNow() - 0.045\n\t                                        ):andThen(function(Result)\n\t                                            if canDebug and type(Result) == \"table\" and Result.accepted and Result.model then\n\t                                                Result.model.Parent = ReplicatedStorage\n\t                                            end\n\t                                        end)\n\t                                        if Ent then\n\t                                            WatchProjectile(Id, ShootPosition, Direction * ProjectileSpeed, Gravity, Ent, Meta.lifetimeSec)\n\t                                        end\n\t                                    end\n\t                                    if Ent then\n\t                                        PredictionLib.trackShot(Ent.RootPart)\n\t                                    end\n\t                                    FireDelays[Item.itemType] = tick() + (ItemMeta.fireDelaySec + FireRate:GetRandomValue())\n\t                                    task.wait(SwitchDelay.Value)\n\t                                end\n\t                            end\n\t                        end\n\t                    end\n\t                    if OldTool then\n\t                        SwitchItem(OldTool)\n\t                    end\n\t                    HotbarSwitch(OldHotbar)\n\t                end\n\t                task.wait(0.1)\n\t            until not AutoShoot.Enabled\n\t        end\n\t    end,\n\t    Tooltip = \"Automatically crossbow macro's\"\n\t})\n\t\n\tTargets = AutoShoot:CreateTargets({Players = true})\n\tCheck = AutoShoot:CreateToggle({\n\t    Name = \"Target check\",\n\t    Function = function(Callback: boolean)\n\t        if Targets.Object then\n\t            Targets.Object.Visible = Callback\n\t        end\n\t    end,\n\t    Default = true\n\t})\n\tAnimation = AutoShoot:CreateToggle({\n\t    Name = \"Animation\",\n\t    Default = true,\n\t    Visible = canDebug,\n\t    Tooltip = \"Plays the shot animation and arrow\"\n\t})\n\tProjectiles = AutoShoot:CreateTextList({\n\t    Name = \"Projectiles\",\n\t    Default = {\"arrow\", \"snowball\"}\n\t})\n\tUseSophia = AutoShoot:CreateToggle({\n\t    Name = \"Use sophia\",\n\t    Tooltip = \"Also shoots sophia's frost staff, swapping it out of mist mode on its own\"\n\t})\n\tUseWhim = AutoShoot:CreateToggle({\n\t    Name = \"Use whim\",\n\t    Tooltip = \"Also casts whim's magic book, follows whatever element you have cycled\"\n\t})\n\tUseNazar = AutoShoot:CreateToggle({\n\t    Name = \"Use nazar\",\n\t    Tooltip = \"Also shoots nazar's life bow, crossbow and headhunter\"\n\t})\n\tUseUmeko = AutoShoot:CreateToggle({\n\t    Name = \"Use umeko\",\n\t    Tooltip = \"Also throws umeko's chakram, waiting for it to come back between throws\"\n\t})\n\tUseLasso = AutoShoot:CreateToggle({\n\t    Name = \"Use Lasso\",\n\t    Tooltip = \"Also throws lassy's lasso, waiting out its cooldown between throws\"\n\t})\n\tFireRate = AutoShoot:CreateTwoSlider({\n\t    Name = \"Fire Rate\",\n\t    Min = 0,\n\t    Max = 1,\n\t    DefaultMin = 0.05,\n\t    DefaultMax = 0.12,\n\t    Decimal = 100\n\t})\n\tSwitchDelay = AutoShoot:CreateSlider({\n\t    Name = \"Switch Delay\",\n\t    Min = 0,\n\t    Max = 1,\n\t    Decimal = 100,\n\t    Suffix = \"seconds\",\n\t    Default = 0.02\n\t})\nend)\n\nRun(function()\n\tlocal AutoToxic\n\tlocal GG\n\tlocal Toggles, Lists, Said, Dead = {}, {}, {}\n\tlocal Presets = {}\n\t\n\tlocal function SendMessage(Name: string, Target: string?, Default: string?)\n\t    local List: {string} = Lists[Name].ListEnabled\n\t    local Message: string? = #List > 0 and List[math.random(1, #List)] or Default\n\t    if not Message then\n\t        return\n\t    end\n\t    if #List > 1 and Message == Said[Name] then\n\t        repeat\n\t            task.wait()\n\t            Message = List[math.random(1, #List)]\n\t        until Message ~= Said[Name]\n\t    end\n\t    Said[Name] = Message\n\t\n\t    Message = Message and Message:gsub(\"<obj>\", Target or \"\") or \"\"\n\t    if TextChatService.ChatVersion == Enum.ChatVersion.TextChatService then\n\t        if TextChatService:CanUserChatAsync(LocalPlayer.UserId) then\n\t            TextChatService.ChatInputBarConfiguration.TargetTextChannel:SendAsync(Message)\n\t        else\n\t            TextChatService.ChatInputBarConfiguration.TargetTextChannel:SendPresetAsync(Presets[Name] or Presets[\"So close\"])\n\t        end\n\t    else\n\t        ReplicatedStorage.DefaultChatSystemChatEvents.SayMessageRequest:FireServer(Message, \"All\")\n\t    end\n\tend\n\t\n\tAutoToxic = vape.Categories.Utility:CreateModule({\n\t    Name = \"AutoToxic\",\n\t    Function = function(Callback: boolean)\n\t        if Callback then\n\t            AutoToxic:Clean(VapeEvents.BedwarsBedBreak.Event:Connect(function(BedTable)\n\t                if Toggles.BedDestroyed.Enabled and BedTable.brokenBedTeam.id == LocalPlayer:GetAttribute(\"Team\") then\n\t                    SendMessage(\"BedDestroyed\", (BedTable.player.DisplayName or BedTable.player.Name), \"how dare you >:( | <obj>\")\n\t                elseif Toggles.Bed.Enabled and BedTable.player.UserId == LocalPlayer.UserId then\n\t                    local Team = bedwars.QueueMeta[Store.queueType].teams[tonumber(BedTable.brokenBedTeam.id)]\n\t                    SendMessage(\"Bed\", Team and Team.displayName:lower() or \"white\", \"nice bed lul | <obj>\")\n\t                end\n\t            end))\n\t            AutoToxic:Clean(VapeEvents.EntityDeathEvent.Event:Connect(function(DeathTable)\n\t                if DeathTable.finalKill then\n\t                    local Killer: Player? = Players:GetPlayerFromCharacter(DeathTable.fromEntity)\n\t                    local Killed: Player? = Players:GetPlayerFromCharacter(DeathTable.entityInstance)\n\t                    if not Killed or not Killer then\n\t                        return\n\t                    end\n\t                    if Killed == LocalPlayer then\n\t                        if (not Dead) and Killer ~= LocalPlayer and Toggles.Death.Enabled then\n\t                            Dead = true\n\t                            SendMessage(\"Death\", (Killer.DisplayName or Killer.Name), \"my gaming chair subscription expired :( | <obj>\")\n\t                        end\n\t                    elseif Killer == LocalPlayer and Toggles.Kill.Enabled then\n\t                        SendMessage(\"Kill\", (Killed.DisplayName or Killed.Name), \"vxp on top | <obj>\")\n\t                    end\n\t                end\n\t            end))\n\t            AutoToxic:Clean(VapeEvents.MatchEndEvent.Event:Connect(function(WinTable)\n\t                if GG.Enabled then\n\t                    if TextChatService.ChatVersion == Enum.ChatVersion.TextChatService then\n\t                        TextChatService.ChatInputBarConfiguration.TargetTextChannel:SendAsync(\"gg\")\n\t                    else\n\t                        ReplicatedStorage.DefaultChatSystemChatEvents.SayMessageRequest:FireServer(\"gg\", \"All\")\n\t                    end\n\t                end\n\t\n\t                local MyTeam = bedwars.Store:getState().Game.myTeam\n\t                if MyTeam and MyTeam.id == WinTable.winningTeamId or LocalPlayer.Neutral then\n\t                    if Toggles.Win.Enabled then\n\t                        SendMessage(\"Win\", nil, \"yall garbage\")\n\t                    end\n\t                end\n\t            end))\n\t        end\n\t    end,\n\t    Tooltip = \"Says a message after a certain action\"\n\t})\n\t\n\tGG = AutoToxic:CreateToggle({\n\t    Name = \"AutoGG\",\n\t    Default = true\n\t})\n\tfor _, v: string in {\"Kill\", \"Death\", \"Bed\", \"BedDestroyed\", \"Win\"} do\n\t    Toggles[v] = AutoToxic:CreateToggle({\n\t        Name = `{v} `,\n\t        Function = function(Callback: boolean)\n\t            if Lists[v] then\n\t                Lists[v].Object.Visible = Callback\n\t            end\n\t        end\n\t    })\n\t    Lists[v] = AutoToxic:CreateTextList({\n\t        Name = v,\n\t        Darker = true,\n\t        Visible = false\n\t    })\n\tend\n\t\n\ttask.spawn(pcall, function()\n\t    for _, Group: any in TextChatService:GetPresetsAsync().categoryGroups do\n\t        for _, Category: any in Group.categories do\n\t            for _, Message: any in Category.messages do\n\t                Presets[Message.value] = Message.presetId\n\t            end\n\t        end\n\t    end\n\tend)\nend)\n\nRun(function()\n\tlocal AutoVoidDrop\n\tlocal OwlCheck\n\tlocal AutoReset\n\t\n\tAutoVoidDrop = vape.Categories.Utility:CreateModule({\n\t    Name = \"AutoVoidDrop\",\n\t    Function = function(Callback: boolean)\n\t        if Callback then\n\t            repeat task.wait() until Store.matchState ~= 0 or (not AutoVoidDrop.Enabled)\n\t            if not AutoVoidDrop.Enabled then\n\t                return\n\t            end\n\t\n\t            local LowestPoint: number = math.huge\n\t            for _, v: BasePart in Store.blocks do\n\t                local Point: number = (v.Position.Y - (v.Size.Y / 2)) - 50\n\t                if Point < LowestPoint then\n\t                    LowestPoint = Point\n\t                end\n\t            end\n\t\n\t            repeat\n\t                if Entity.isAlive then\n\t                    local Root: BasePart = Entity.character.RootPart\n\t                    if Root.Position.Y < LowestPoint and (LocalPlayer.Character:GetAttribute(\"InflatedBalloons\") or 0) <= 0 and not GetItem(\"balloon\") then\n\t                        if not OwlCheck.Enabled or not Root:FindFirstChild(\"OwlLiftForce\") then\n\t                            local Dropped: boolean = false\n\t                            for _, v: string in {\"iron\", \"diamond\", \"emerald\", \"gold\"} do\n\t                                v = GetItem(v)\n\t                                if v then\n\t                                    v = bedwars.Handler:Get(\"DropItem\"):Fire(\"CallServer\", {\n\t                                        item = v.tool,\n\t                                        amount = v.amount\n\t                                    })\n\t\n\t                                    if v then\n\t                                        v:SetAttribute(\"ClientDropTime\", tick() + 100)\n\t                                        Dropped = true\n\t                                    end\n\t                                end\n\t                            end\n\t\n\t                            if Dropped and AutoReset.Enabled then\n\t                                bedwars.Handler:Get(\"ResetCharacter\"):Fire(\"SendToServer\")\n\t                            end\n\t                        end\n\t                    end\n\t                end\n\t\n\t                task.wait(0.1)\n\t            until not AutoVoidDrop.Enabled\n\t        end\n\t    end,\n\t    Tooltip = \"Drops resources when you fall into the void\"\n\t})\n\t\n\tOwlCheck = AutoVoidDrop:CreateToggle({\n\t    Name = \"Owl check\",\n\t    Default = true,\n\t    Tooltip = \"Refuses to drop items if being picked up by an owl\"\n\t})\n\tAutoReset = AutoVoidDrop:CreateToggle({\n\t    Name = \"Auto Reset\",\n\t    Tooltip = \"Resets as soon as your resources are dropped\"\n\t})\nend)\n\nRun(function()\n\tlocal AutoVote\n\tlocal Option\n\tlocal Delay\n\tlocal Notify\n\t\n\tlocal Request = bedwars.Handler:Get(\"CastPregameVote\")\n\tlocal Voted: boolean\n\t\n\tAutoVote = vape.Categories.Utility:CreateModule({\n\t    Name = \"AutoVote\",\n\t    Function = function(Callback: boolean)\n\t        if Callback then\n\t            Voted = false\n\t\n\t            repeat\n\t                if Store.matchState == 0 then\n\t                    if not Voted then\n\t                        Request:Fire(\"SendToServer\", {votingOptionIndex = Option.Value - 1})\n\t                        Voted = true\n\t\n\t                        if Notify.Enabled then\n\t                            SendNotification(\"AutoVote\", `Voted for option {Option.Value}`, 4)\n\t                        end\n\t                    end\n\t                else\n\t                    Voted = false\n\t                end\n\t                task.wait(Delay.Value)\n\t            until not AutoVote.Enabled\n\t        else\n\t            Voted = false\n\t        end\n\t    end,\n\t    Tooltip = \"Casts your map vote the moment the pregame vote opens\"\n\t})\n\t\n\tOption = AutoVote:CreateSlider({\n\t    Name = \"Option\",\n\t    Min = 1,\n\t    Max = 4,\n\t    Default = 1,\n\t    Tooltip = \"Which of the voting options to pick, counting from the left\"\n\t})\n\tDelay = AutoVote:CreateSlider({\n\t    Name = \"Delay\",\n\t    Min = 0.5,\n\t    Max = 10,\n\t    Default = 1,\n\t    Decimal = 10,\n\t    Suffix = \"seconds\"\n\t})\n\tNotify = AutoVote:CreateToggle({\n\t    Name = \"Notify\",\n\t    Default = true,\n\t    Tooltip = \"Tells you when the vote goes in\"\n\t})\nend)\n\nRun(function()\n\tlocal AutoWin\n\tlocal Boost\n\tlocal FlyTime\n\tlocal Health\n\tlocal Recover\n\tlocal StrafeRange\n\tlocal DefendRange\n\tlocal Reserve\n\tlocal BreakBed\n\tlocal CoverBed\n\tlocal AerialFight\n\tlocal LongJump\n\tlocal SkyTravel\n\tlocal Speedrun\n\tlocal Debug\n\tlocal Settings = {}\n\tlocal Agent\n\tlocal Senses\n\tlocal Brain\n\tlocal World\n\tlocal Motion\n\tlocal Routing\n\t\n\tlocal Planar: Vector3 = Vector3.new(1, 0, 1)\n\tlocal Pool, Parked = {}, 0\n\tlocal PlacedMemo, Snapshot = {}, {}\n\tlocal Gait, Leap, Flight, Build = {}, {}, {}, {}\n\tlocal PathModel: Model = Instance.new(\"Model\")\n\tPathModel.Name = \"pathModel\"\n\tPathModel.Parent = workspace.Terrain\n\tvape:Clean(function()\n\t    PathModel:Destroy()\n\tend)\n\t\n\tlocal FallbackPath: Path = cloneref(game:GetService(\"PathfindingService\")):CreatePath({\n\t    AgentRadius = 1,\n\t    AgentHeight = 5,\n\t    AgentCanClimb = true,\n\t    WaypointSpacing = 5,\n\t    Costs = {\n\t        Air = 0,\n\t        Fabric = 0\n\t    }\n\t})\n\t\n\tlocal Tuning = {\n\t    ObserveInterval = 0.25,\n\t    ThinkFloor = 0.2,\n\t    SummaryInterval = 3,\n\t    PositionDecay = 6,\n\t    GearDecay = 45,\n\t    SwitchMargin = 12,\n\t    CommitMargin = 25,\n\t    ProgressBonus = 20,\n\t    ContinueBonus = 5,\n\t    BreakBonus = 30,\n\t    OscillationWindow = 12,\n\t    OscillationDecay = 15,\n\t    FailureWeight = 18,\n\t    FailureLifetime = 60,\n\t    SuccessWeight = 5,\n\t    TimeWeight = 1,\n\t    BlockWeight = 0.8,\n\t    ShortWeight = 15,\n\t    GuessedShort = 0.3,\n\t    VoidWeight = 0.12,\n\t    ThreatWeight = 0.35,\n\t    OpportunityWeight = 0.2,\n\t    BedValue = 100,\n\t    KillValue = 25,\n\t    FinalKillValue = 80,\n\t    EliminationValue = 115,\n\t    VictoryValue = 160,\n\t    DefenderValue = 18,\n\t    IntruderValue = 45,\n\t    WeakValue = 35,\n\t    CorneredValue = 30,\n\t    CorneredTime = 4,\n\t    ContestMargin = 4,\n\t    ContestOdds = 0.3,\n\t 