90, now = 60, invest = 60, armor = 55, soon = 35, cover = 35, upgrade = 30, nice = 12},\n\t    InvestOdds = 0.4,\n\t    SaveUrgency = 55,\n\t    UnarmedFactor = 0.6,\n\t    Phases = {\n\t        OPENING = {bed = 1.15, kill = 0.8, resource = 1.2},\n\t        PRESSURE = {bed = 1.1, kill = 0.9, resource = 1},\n\t        MIDGAME = {bed = 1, kill = 1, resource = 1},\n\t        ENDGAME = {bed = 1.15, kill = 1.2, resource = 0.6},\n\t        FINAL = {bed = 1.2, kill = 1.35, resource = 0.35},\n\t        VICTORY = {bed = 0, kill = 0, resource = 0}\n\t    },\n\t    Sides = {\n\t        {Name = \"east\", Offset = Vector3.new(6, 0, 0)},\n\t        {Name = \"west\", Offset = Vector3.new(-6, 0, 0)},\n\t        {Name = \"south\", Offset = Vector3.new(0, 0, 6)},\n\t        {Name = \"north\", Offset = Vector3.new(0, 0, -6)},\n\t        {Name = \"top\", Offset = Vector3.new(0, 4.5, 0)}\n\t    },\n\t    Swords = {\"wood_sword\", \"stone_sword\", \"iron_sword\", \"diamond_sword\", \"emerald_sword\"},\n\t    Armors = {\"leather_chestplate\", \"iron_chestplate\", \"diamond_chestplate\", \"emerald_chestplate\"},\n\t    TeamUpgrades = {\"TEAM_GENERATOR\", \"ARMOR\", \"DAMAGE\"},\n\t    EconomyWindow = 240,\n\t    BaseRadius = 80,\n\t    ShieldWait = 20,\n\t    Cover = {Vector3.new(1, 0, 0), Vector3.new(-1, 0, 0), Vector3.new(1, 0, 1), Vector3.new(-1, 0, 1), Vector3.new(0, 0, 2), Vector3.new(0, 0, -1), Vector3.new(0, 1, 0), Vector3.new(0, 1, 1)},\n\t    CoverPhase = {OPENING = 2, PRESSURE = 1.6, MIDGAME = 1, ENDGAME = 0.8, FINAL = 0.5, VICTORY = 0},\n\t    CoverValue = 70,\n\t    CoverMinimum = 3,\n\t    CoverRange = 9,\n\t    CoverReach = 16,\n\t    CoverTimeout = 8,\n\t    CoverStall = 1.5,\n\t    CoverBlocks = {\"stone_brick\", \"wood_plank_oak\"},\n\t    ShellValue = 45,\n\t    CoverBatch = 16,\n\t    SnipeRange = 20,\n\t    SnipeMemory = 6,\n\t    HarassMemory = 3,\n\t    HarassRange = 50,\n\t    SightMemory = 12,\n\t    EyeHeight = 1.5,\n\t    SightPoints = {0, 1.5},\n\t    SightMargin = 1,\n\t    AimCone = 0.97,\n\t    ShelterRings = {0, 3, 6, 9, 13, 18},\n\t    ShelterSpacing = 3,\n\t    ShelterStep = 4.5,\n\t    ShelterRange = 18,\n\t    ShelterShift = 4,\n\t    ShelterArrive = 1.5,\n\t    ShelterInterval = 0.5,\n\t    PickupRange = 6,\n\t    PickupMargin = 2,\n\t    PinnedRisk = 0.3,\n\t    BarricadeBlocks = 6,\n\t    SkyHealth = 12,\n\t    BarricadeTime = 2,\n\t    BarricadeCooldown = 6,\n\t    SkyHeight = 22,\n\t    SafeDrop = 21,\n\t    SkyMinimum = 16,\n\t    SkyHold = 1.2,\n\t    SkyRest = 0.3,\n\t    SkyGrace = 0.4,\n\t    SkyWatch = 45,\n\t    SkyClear = 30,\n\t    SkyLand = 20,\n\t    SkyDrop = 60,\n\t    SkyTrigger = 26,\n\t    EnemyReach = 14.4,\n\t    AerialMargin = 2.5,\n\t    AerialTilt = 0.25,\n\t    AerialSteep = 0.08,\n\t    AerialHold = 0.8,\n\t    AerialDrop = 6,\n\t    AerialRest = 0.12,\n\t    SiteGuard = 24,\n\t    SiteRisk = 0.5,\n\t    MenaceRange = 40,\n\t    PursuitRisk = 0.8,\n\t    OutmatchedOdds = 0.5,\n\t    PursuitMemory = 3,\n\t    RespawnDelay = 5,\n\t    RespawnLead = 2.5,\n\t    RespawnGrace = 4,\n\t    RespawnGear = 10,\n\t    RecoveryGear = 150,\n\t    RespawnDanger = 0.6,\n\t    RespawnRadius = 30,\n\t    Blocked = {collision = 40, obstructed = 40, stuck = 40, suffocation = 60},\n\t    ObstacleScan = 4,\n\t    LearnTime = 30,\n\t    ObstacleProbe = Vector3.new(2.6, 2.6, 2.6),\n\t    PassageStep = 1.5,\n\t    EscapeHeight = 30,\n\t    SkyRetry = 0.25,\n\t    AerialScan = 0.1,\n\t    AerialPause = 0.4,\n\t    AerialSlack = 4,\n\t    AerialEntry = 6,\n\t    FocusMargin = 30,\n\t    ChaseFocus = 12,\n\t    DriftRate = 0.4,\n\t    RaidRange = 20,\n\t    RaidValue = 35,\n\t    GearPlan = {{at = 0, item = \"stone_sword\"}, {at = 40, item = \"leather_chestplate\"}, {at = 80, item = \"iron_chestplate\"}, {at = 130, item = \"iron_sword\"}},\n\t    GearMargin = 0.05,\n\t    PlanGrace = 20,\n\t    BehindFactor = 0.75,\n\t    HomeWait = 0.6,\n\t    ArrowFloor = 8,\n\t    ArrowCap = 64,\n\t    ArrowAccuracy = 0.55,\n\t 