resources = {}, armorSlots = {}, samples = {}, ratio = 1}, teams = {}, enemies = {}, teammates = {}, broken = {}, homes = {}, spawns = {}, respawns = {}, rates = table.clone(Tuning.Rates), match = {peakTeams = 0, peakBeds = 0, peakPlayers = 0, contacts = 0, strikes = 0, began = os.clock(), phase = \"OPENING\", elapsed = 0}}\n\t    Motion = {velocity = Vector3.zero, nextPlace = 0, nextBreak = 0, nextAttack = 0, nextClimb = 0, nextLand = 0, controlledAt = -math.huge}\n\t    Routing = {at = -math.huge, retryAt = 0, profiles = {}, shortfalls = {}, flightless = {}, surveys = {}, bought = {}, spent = {}, stock = {}, evaluating = false, detour = Tuning.Detour}\n\t    \n\t    table.clear(Snapshot)\n\tend\n\t\n\tlocal function TravelSpeed()\n\t    return getSpeed() + Boost.Value\n\tend\n\t\n\tlocal function Traversal()\n\t    return {\n\t        Mover = \"Glide\",\n\t        MaxAirTime = FlyTime.Value,\n\t        Rise = 13,\n\t        Instant = true\n\t    }\n\tend\n\t\n\tlocal function Assisted()\n\t    local Killaura = vape.Modules and vape.Modules.Killaura\n\t    return Killaura ~= nil and Killaura.Enabled == true\n\tend\n\t\n\tlocal function Reach()\n\t    local Killaura = vape.Modules and vape.Modules.Killaura\n\t    local Range = Assisted() and Killaura.Options and Killaura.Options[\"Attack range\"]\n\t    if Range then\n\t        return Range.Value\n\t    end\n\t    local Sword = store.tools.sword\n\t    local Meta = Sword and Sword.tool and bedwars.ItemMeta[Sword.tool.Name]\n\t    return Meta and Meta.sword and Meta.sword.attackRange or Tuning.MeleeReach\n\tend\n\t\n\tlocal function Fallback(From: Vector3, To: Vector3)\n\t    if pcall(FallbackPath.ComputeAsync, FallbackPath, From, To) and FallbackPath.Status == Enum.PathStatus.Success then\n\t        local Points: {Vector3} = {}\n\t        for _, v: PathWaypoint in FallbackPath:GetWaypoints() do\n\t            table.insert(Points, v.Position)\n\t        end\n\t        return Points\n\t    end\n\t    return nil\n\tend\n\t\n\tlocal function NewAgent()\n\t    return Navigation.newAgent({\n\t        Config = {\n\t            LowHealth = Health.Value / 100,\n\t            RecoverHealth = math.min(math.max(Recover.Value, Health.Value + 10) / 100, 1),\n\t            BlockReserve = Reserve.Value,\n\t            BedThreatRadius = DefendRange.Value\n\t        },\n\t        Context = {\n\t            Player = LocalPlayer,\n\t            Players = Players,\n\t            Collection = CollectionService,\n\t            Entity = Entity,\n\t            Store = store,\n\t            bedwars = bedwars,\n\t            PathModel = PathModel,\n\t            PlacedBlock = getPlacedBlock,\n\t            Wool = getWool,\n\t            Item = getItem,\n\t            Hotbar = getHotbar,\n\t            CanPlace = canPlace,\n\t            CanSwing = canSwing,\n\t            Projectiles = getProjectiles,\n\t            FireProjectile = fireProjectile,\n\t            BreakEnabled = function()\n\t                return BreakBed.Enabled\n\t            end,\n\t            DebugEnabled = function()\n\t                return Debug.Enabled\n\t            end\n\t        },\n\t        Fallback = Fallback\n\t    })\n\tend\n\t\n\tlocal function HideBlocks()\n\t    for i: number, v: Part in Pool do\n\t        if i > Parked then\n\t            break\n\t        end\n\t        v.CFrame = CFrame.new(9e9, 9e9, 9e9)\n\t    end\n\t    Parked = 0\n\tend\n\t\n\tlocal function ShowBlocks(Plan)\n\t    HideBlocks()\n\t    for _, v: any in Plan and Plan.Waypoints or {} do\n\t        for _, Block: any in v.Blocks or {} do\n\t            if Parked >= 3000 then\n\t                return\n\t            end\n\t            Parked += 1\n\t            local Part: Part? = Pool[Parked]\n\t            if not Part then\n\t                Part = Instance.new(\"Part\")\n\t                Part.Size = Vector3.new(3, 3, 3)\n\t                Part.Material = Enum.Material.Air\n\t                Part.Anchored = true\n\t                Part.Transparency = 0.5\n\t                Part.CanCollide = true\n\t                Part.Color = Color3.fromRGB(140, 140, 140)\n\t                Part.Parent = PathModel\n\t                Pool[Parked] = Part\n\t            end\n\t            Part.Position = Block.Position\n\t        end\n\t    end\n\tend\n\t\n\tlocal function PlanOptions(Channel: string?, Avoid, From: Vector3?)\n\t    local Wool, Amount = getWool()\n\t    return {\n\t        Channel = Channel or \"autowin\",\n\t        Mode = \"Blatant\",\n\t        Avoid = Avoid,\n\t        Costs = if From and Flight.Inside(From) then {Elevation = Tuning.InsideElevation} else nil,\n\t        BlocksBudget = math.max((Wool and Amount or 0) - Reserve.Value, 0),\n\t        Debug = Debug.Enabled,\n\t        Label = true,\n\t        Agent = {\n\t            WalkSpeed = TravelSpeed(),\n\t            MaxDrop = Tuning.SafeDrop\n\t        },\n\t        Traversal = Traversal(),\n\t        Search = {\n\t            MaxSteps = 25000,\n\t            WalkSteps = 8000,\n\t            BridgeWeight = 1.25,\n\t            Fallback = 3,\n\t            Quick = true,\n\t            Smooth = false\n\t        }\n\t    }\n\tend\n\t\n\tlocal function MarkDirty(Reason: string)\n\t    Brain.dirty = Brain.dirty or Reason\n\t    Brain.nextObserve = 0\n\tend\n\t\n\tlocal function Penalty(Key: string?, Now: number)\n\t    if not Key then\n\t        return 0\n\t    end\n\t    local Failed, Succeeded = Agent.Memory.failures[Key], Agent.Memory.successes[Key]\n\t    local Value: number = 0\n\t    if Failed then\n\t        Value += Tuning.FailureWeight * Failed.count * math.max(1 - (Now - Failed.timestamp) / Tuning.FailureLifetime, 0)\n\t    end\n\t    if Succeeded then\n\t        Value -= Tuning.SuccessWeight * math.min(Succeeded.count, 3) * math.max(1 - (Now - Succeeded.timestamp) / Tuning.FailureLifetime, 0)\n\t    end\n\t    return Value\n\tend\n\t\n\tlocal function Suppressed(Key: string, Now: number)\n\t    local Failed = Agent.Memory.failures[Key]\n\t    return Failed ~= nil and Now - Failed.timestamp < math.min(4 * Failed.count, 30)\n\tend\n\t\n\tlocal function RecordFailure(Key: string, Reason: string, Now: number)\n\t    local Root = Entity.isAlive and Entity.character.RootPart\n\t    Agent.Memory:Failure(Key, Reason, Now, Root and Root.Position or nil)\n\t    Brain.failure = `{Key} {Reason}`\n\tend\n\t\n\tlocal function Aversion(Ratio: number)\n\t    local Knee: number = Health.Value / 100\n\t    local Weight: number = math.clamp((Knee + 0.3 - Ratio) / 0.45, 0, 1)\n\t    return 1 + 3 * Weight ^ 1.6\n\tend\n\t\n\tlocal function DeathCost()\n\t    local Cargo: number = 0\n\t    for Resource: string, v: number in Tuning.Cargo do\n\t        Cargo += (World.self.resources[Resource] or 0) * v\n\t    end\n\t    return (World.match.ownBed and Tuning.DeathCost or Tuning.EliminationCost) + Cargo\n\tend\n\t\n\tlocal function RootOf(Record)\n\t    local Root = Record.root\n\t    if Root and Root.Parent then\n\t        return Root\n\t    end\n\t    return nil\n\tend\n\t\n\tlocal function Clear(Position: Vector3, Width: number?)\n\t    local Bottom, Top = Position.Y - Entity.character.HipHeight + Tuning.KneeHeight, Position.Y + Tuning.HeadHeight\n\t    local Size: number = Width or Tuning.BodyWidth\n\t    return #workspace:GetPartBoundsInBox(CFrame.new(Position.X, (Bottom + Top) / 2, Position.Z), Vector3.new(Size, Top - Bottom, Size), Senses.Overlap) == 0\n\tend\n\t\n\tlocal function Passage(From: Vector3, To: Vector3)\n\t    local Offset: Vector3 = To - From\n\t    if Offset.Magnitude < 0.05 then\n\t        return true\n\t    end\n\t    local Steps: number = math.ceil(Offset.Magnitude / Tuning.PassageStep)\n\t    for i: number = 1, Steps do\n\t        if not Clear(From + Offset * (i / Steps), Tuning.HoverWidth) then\n\t            return false\n\t        end\n\t    end\n\t    return true\n\tend\n\t\n\tlocal function Hop(From: Vector3, To: Vector3)\n\t    local Height: number = math.max(From.Y, To.Y)\n\t    local Raised: Vector3 = Vector3.new(From.X, Height, From.Z)\n\t    local Over: Vector3 = Vector3.new(To.X, Height, To.Z)\n\t    return Passage(From, Raised) and Passage(Raised, Over) and Passage(Over, To)\n\tend\n\t\n\tlocal function Headroom(From: Vector3, Limit: number)\n\t    local Rise: number = 0\n\t    while Rise + Tuning.PassageStep <= Limit and Clear(From + Vector3.new(0, Rise + Tuning.PassageStep, 0), Tuning.HoverWidth) do\n\t        Rise += Tuning.PassageStep\n\t    end\n\t    return Rise\n\tend\n\t\n\tlocal function Ascent(From: Vector3)\n\t    for Rise: number = Tuning.PassageStep, Tuning.EscapeHeight, Tuning.PassageStep do\n\t        local Point: Vector3 = From + Vector3.new(0, Rise, 0)\n\t        if Clear(Point, Tuning.HoverWidth) then\n\t            return Point\n\t        end\n\t    end\n\t    return nil\n\tend\n\t\n\tlocal function Touchdown(Stand: Vector3, Ceiling: number)\n\t    local Landing: Vector3? = if Clear(Stand) then Stand else Ascent(Stand)\n\t    return if Landing and Landing.Y <= Ceiling then Landing else nil\n\tend\n\t\n\tlocal function Stride(From: Vector3, Direction: Vector3, Step: number, Lowest: number)\n\t    local Root: BasePart = Entity.character.RootPart\n\t    local HipHeight: number = Entity.character.HipHeight\n\t    local Moved: Vector3 = From + Direction * Step\n\t    local Floor: RaycastResult? = workspace:Raycast(Moved + Vector3.new(0, 3, 0), Vector3.new(0, -70, 0), Senses.Params)\n\t    if not Floor or Floor.Position.Y < Lowest then\n\t        return nil, \"void\"\n\t    end\n\t    if workspace:Blockcast(CFrame.new(From), Vector3.new(Root.Size.X, HipHeight + Root.Size.Y / 2, Root.Size.X), Direction * (Step + 1.5), Senses.Params) then\n\t        return nil\n\t    end\n\t    local Position: Vector3 = Vector3.new(Moved.X, Floor.Position.Y + HipHeight, Moved.Z)\n\t    return Clear(Position) and Position or nil\n\tend\n\t\n\tlocal function Direct(From: Vector3, To: Vector3)\n\t    local Flat: Vector3 = (To - From) * Planar\n\t    local Length: number = Flat.Magnitude\n\t    if Length < 0.1 then\n\t        return true\n\t    end\n\t    local Root: BasePart = Entity.character.RootPart\n\t    local HipHeight: number = Entity.character.HipHeight\n\t    local Lowest: number = math.min(From.Y, To.Y) - HipHeight - Tuning.CoastDrop\n\t    for Step: number = Tuning.DirectSpacing, Length, Tuning.DirectSpacing do\n\t        local Floor: RaycastResult? = workspace:Raycast(From + Flat.Unit * Step + Vector3.new(0, 3, 0), Vector3.new(0, -70, 0), Senses.Params)\n\t        if not Floor or Floor.Position.Y < Lowest then\n\t            return false\n\t        end\n\t    end\n\t    return not workspace:Blockcast(CFrame.new(From), Vector3.new(Root.Size.X, HipHeight + Root.Size.Y / 2, Root.Size.X) - Tuning.CollisionShrink, Flat, Senses.Params)\n\tend\n\t\n\tlocal function LivePosition(Record)\n\t    local Root = RootOf(Record)\n\t    return Root and Root.Position or Record.position\n\tend\n\t\n\tlocal function Attacking(Record, Now: number)\n\t    return Record.hitAt ~= nil and Now - Record.hitAt < Tuning.HitMemory and Record.hitAt > (Record.releasedAt or -math.huge)\n\tend\n\t\n\tlocal function Visible(Record)\n\t    local Origin: Vector3 = World.self.position\n\t    return not workspace:Raycast(Origin, LivePosition(Record) - Origin, Senses.Params)\n\tend\n\t\n\tlocal function Confidence(Record, Now: number)\n\t    return Record.alive and math.exp(-(Now - Record.seenAt) / Tuning.PositionDecay) or 0\n\tend\n\t\n\tlocal function NearestEnemy(Position: Vector3)\n\t    local Best, Found = math.huge, nil\n\t    for _, v: any in World.enemies do\n\t        if v.alive then\n\t            local Distance: number = (LivePosition(v) - Position).Magnitude\n\t            if Distance < Best then\n\t                Best, Found = Distance, v\n\t            end\n\t        end\n\t    end\n\t    for _, v: any in World.respawns do\n\t        local Distance: number = (v.position - Position).Magnitude\n\t        if Distance < Best then\n\t            Best, Found = Distance, v.record\n\t        end\n\t    end\n\t    return Best, Found\n\tend\n\t\n\tlocal function ThreatNear(Position: Vector3, Radius: number, Now: number, Except)\n\t    local Threat, Count = 0, 0\n\t    for _, v: any in World.enemies do\n\t        if v ~= Except and v.alive then\n\t            local Distance: number = (v.position - Position).Magnitude\n\t            if Distance <= Radius then\n\t                Threat += (1 - Distance / Radius) * (v.gearAt and v.sword > 0 and v.sword or Tuning.UnknownDamage) * Confidence(v, Now)\n\t                Count += 1\n\t            end\n\t        end\n\t    end\n\t    for _, v: any in World.respawns do\n\t        local Distance: number = (v.position - Position).Magnitude\n\t        if v.record ~= Except and Distance <= Radius then\n\t            Threat += (1 - Distance / Radius) * (v.record.gearAt and v.record.sword > 0 and v.record.sword or Tuning.UnknownDamage)\n\t            Count += 1\n\t        end\n\t    end\n\t    return Threat, Count\n\tend\n\t\n\tlocal function ThreatPositions(Range: number)\n\t    local List, Origin = {}, World.self.position\n\t    for _, v: any in World.enemies do\n\t        local Position = v.alive and LivePosition(v)\n\t        if Position and (Position - Origin).Magnitude <= Range then\n\t            table.insert(List, Position)\n\t        end\n\t    end\n\t    for _, v: any in World.respawns do\n\t        if (v.position - Origin).Magnitude <= Range then\n\t            table.insert(List, v.position)\n\t        end\n\t    end\n\t    return List\n\tend\n\t\n\tlocal function Sightlines(Now: number)\n\t    local List: {Vector3} = {}\n\t    for _, v: any in World.enemies do\n\t        local Position: Vector3? = v.alive and LivePosition(v)\n\t        if Position and Now - math.max(v.shotAt or -math.huge, v.aimedAt or -math.huge) < Tuning.SightMemory then\n\t            table.insert(List, Position + Vector3.new(0, Tuning.EyeHeight, 0))\n\t        end\n\t    end\n\t    return List\n\tend\n\t\n\tlocal function Exposed(Stand: Vector3, Lines: {Vector3}, Margin: number?)\n\t    for _, Eye: Vector3 in Lines do\n\t        local Flat: Vector3 = (Stand - Eye) * Planar\n\t        local Side: Vector3 = if Flat.Magnitude > 0.1 then Vector3.new(-Flat.Z, 0, Flat.X).Unit else Vector3.zero\n\t        for _, Height: number in Tuning.SightPoints do\n\t            for _, Offset: number in if Margin then {0, -Margin, Margin} else {0} do\n\t                local Point: Vector3 = Stand + Vector3.new(0, Height, 0) + Side * Offset\n\t                if not workspace:Raycast(Eye, Point - Eye, Senses.Params) then\n\t                    return true\n\t                end\n\t            end\n\t        end\n\t    end\n\t    return false\n\tend\n\t\n\tlocal function Shelter(Anchor: Vector3, Radius: number, Lines: {Vector3})\n\t    local HipHeight: number = Entity.character.HipHeight\n\t    local Away: Vector3 = Vector3.zero\n\t    for _, Eye: Vector3 in Lines do\n\t        Away += (Anchor - Eye) * Planar\n\t    end\n\t    local Heading: number = if Away.Magnitude > 0.1 then math.atan2(Away.Z, Away.X) else 0\n\t    for _, Ring: number in Tuning.ShelterRings do\n\t        if Ring > Radius then\n\t            break\n\t        end\n\t        local Count: number = if Ring == 0 then 1 else math.max(math.floor(2 * math.pi * Ring / Tuning.ShelterSpacing), 8)\n\t        for i: number = 0, Count - 1 do\n\t            local Theta: number = Heading + (if i % 2 == 0 then 1 else -1) * math.ceil(i / 2) * 2 * math.pi / Count\n\t            local Point: Vector3 = Anchor + Vector3.new(math.cos(Theta), 0, math.sin(Theta)) * Ring\n\t            local Floor: RaycastResult? = workspace:Raycast(Point + Vector3.new(0, Tuning.ShelterStep, 0), Vector3.new(0, -2 * Tuning.ShelterStep - HipHeight, 0), Senses.Params)\n\t            local Stand: Vector3? = Floor and Vector3.new(Point.X, Floor.Position.Y + HipHeight, Point.Z)\n\t            if Stand and Clear(Stand) and not Senses.Surface(Stand).nearVoid and not Exposed(Stand, Lines, Tuning.SightMargin) then\n\t                return Stand\n\t            end\n\t        end\n\t    end\n\t    return nil\n\tend\n\t\n\tlocal function Pickup()\n\t    local Module = vape.Modules and vape.Modules.PickupRange\n\t    local Range = Module and Module.Enabled and Module.Options and Module.Options.Range\n\t    return (if Range then Range.Value else Tuning.PickupRange) - Tuning.PickupMargin\n\tend\n\t\n\tlocal function Pinned(Position: Vector3, Now: number)\n\t    local Lines: {Vector3} = Sightlines(Now)\n\t    if #Lines == 0 or World.self.blocks >= Tuning.BarricadeBlocks or Shelter(Position, Pickup(), Lines) then\n\t        return 0\n\t    end\n\t    return Tuning.PinnedRisk\n\tend\n\t\n\tlocal function Escape(Now: number)\n\t    local Me = World.self\n\t    local Odds: number = 1\n\t    for _, v: any in World.enemies do\n\t        if v.alive and Attacking(v, Now) then\n\t            local Offset: Vector3 = (Me.position - LivePosition(v)) * Planar\n\t            if Offset.Magnitude <= Reach() + Tuning.ContestMargin then\n\t                local Closing: number = Offset.Magnitude > 0.1 and ((v.velocity or Vector3.zero) * Planar):Dot(Offset.Unit) or 0\n\t                local Pace: number = math.max(Closing, Tuning.PursuitSpeed)\n\t                Odds = math.min(Odds, math.clamp(1 - Pace / math.max(Me.speed, 1), Tuning.EscapeFloor, 1))\n\t            end\n\t        end\n\t    end\n\t    if Odds < 1 and Me.blocks >= 4 then\n\t        Odds = math.max(Odds, Tuning.PillarEscape)\n\t    end\n\t    return Odds\n\tend\n\t\n\tlocal function Faded(Record, Now: number)\n\t    local Fade: number = 0.5 ^ ((Now - (Record.ledgerAt or Now)) / Tuning.LedgerHalfLife)\n\t    return (Record.dealt or 0) * Fade, (Record.taken or 0) * Fade\n\tend\n\t\n\tlocal function Tally(Record, Dealt: boolean, Damage: number?, Now: number)\n\t    local Me = World.self\n\t    Record.dealt, Record.taken = Faded(Record, Now)\n\t    Record.ledgerAt = Now\n\t    if Dealt then\n\t        Record.dealt += 1\n\t    else\n\t        Record.taken += 1\n\t    end\n\t    if not Damage or not Record.gearAt then\n\t        return\n\t    end\n\t    local Predicted: number = if Dealt then math.max(Me.sword, 12) * (1 - (Record.armor or 0)) else (Record.sword > 0 and Record.sword or Tuning.UnknownDamage) * (1 - Me.armor)\n\t    if Predicted > 0 then\n\t        local Field: string = Dealt and \"soak\" or \"harm\"\n\t        Record[Field] = math.clamp((Record[Field] or 1) * (1 - Tuning.LedgerRate) + Damage / Predicted * Tuning.LedgerRate, Tuning.LedgerMin, Tuning.LedgerMax)\n\t    end\n\tend\n\t\n\tlocal function Duel(Record, Damage: number, Armor, Count: number, Support: number, Now: number)\n\t    local Me = World.self\n\t    local Dealt, Taken = Faded(Record, Now)\n\t    local Rate: number = (Dealt + (Assisted() and Tuning.Edge or 1) * Tuning.LedgerPrior) / (Taken + Tuning.LedgerPrior)\n\t    local Kill: number = math.max(math.ceil((Record.health or 100) / (math.max(Me.sword, 12) * (1 - Armor) * (Record.soak or 1))), 1)\n\t    local Survive: number = math.max(math.ceil(Me.health / (Damage * (1 - Me.armor) * (Record.harm or 1) * (1 + Count))), 1)\n\t    local Ratio: number = Survive / (Kill * (1 + Count)) * (1 + 0.6 * Support) * Rate\n\t    if Record.position and Record.position.Y - Me.position.Y > 6 then\n\t        Ratio *= 0.8\n\t    end\n\t    return Ratio ^ 2.2 / (1 + Ratio ^ 2.2), Kill\n\tend\n\t\n\tlocal function Outranged(Record)\n\t    return (Record.far or 0) >= Tuning.FarHits and (Record.reach or 0) > Reach() - 0.5\n\tend\n\t\n\tlocal function CombatEstimate(Record, Location: Vector3, Now: number)\n\t    local Count, Support = 0, 0\n\t    for _, v: any in World.enemies do\n\t        if v ~= Record and v.alive and (v.position - Location).Magnitude <= 20 then\n\t            Count += 1\n\t        end\n\t    end\n\t    for _, v: Vector3 in World.teammates do\n\t        if (v - Location).Magnitude <= 24 then\n\t            Support += 1\n\t        end\n\t    end\n\t\n\t    local Chance, Kill\n\t    if Record.gearAt and Now - Record.gearAt < Tuning.GearDecay then\n\t        Chance, Kill = Duel(Record, Record.sword > 0 and Record.sword or Tuning.UnknownDamage, Record.armor, Count, Support, Now)\n\t    else\n\t        local Low, High\n\t        Low, Kill = Duel(Record, Tuning.WorstDamage, Tuning.WorstArmor, Count, Support, Now)\n\t        High = Duel(Record, Tuning.BestDamage, 0, Count, Support, Now)\n\t        Chance = (Low + High) / 2\n\t    end\n\t    Chance *= Tuning.LossFactor ^ (Record.combatFailures * math.max(1 - (Now - Record.lostAt) / Tuning.LossLifetime, 0))\n\t    if Outranged(Record) then\n\t        local Dealt, Taken = Faded(Record, Now)\n\t        if Taken > Dealt then\n\t            Chance *= Tuning.OutrangedFactor\n\t        end\n\t    end\n\t    if Senses.Surface(Location).nearVoid then\n\t        Chance -= 0.1\n\t    end\n\t    return math.clamp(Chance, 0.02, 0.98), Count, Support, Kill\n\tend\n\t\n\tlocal function SiteRisk(Position: Vector3, Now: number)\n\t    local Risk: number = 0\n\t    for _, v: any in World.enemies do\n\t        local Distance: number = v.alive and v.position and (v.position - Position).Magnitude or math.huge\n\t        if Distance <= Tuning.MenaceRange then\n\t            local Odds: number = CombatEstimate(v, Position, Now)\n\t            if Distance <= Tuning.SiteGuard or Odds < Tuning.ContestOdds then\n\t                Risk = math.max(Risk, (1 - Odds) * Tuning.SiteRisk)\n\t            end\n\t        end\n\t    end\n\t    return Risk\n\tend\n\t\n\tlocal function Pursuit(Now: number)\n\t    local Me = World.self\n\t    local Risk: number = 0\n\t    if World.match.ownBed then\n\t        return Risk\n\t    end\n\t    for _, v: any in World.enemies do\n\t        if v.alive and v.position and not v.protected then\n\t            local Offset: Vector3 = (Me.position - v.position) * Planar\n\t            local Distance: number = Offset.Magnitude\n\t            local Closing: number = Distance > 0.1 and ((v.velocity or Vector3.zero) * Planar):Dot(Offset.Unit) or 0\n\t            local Chasing: boolean = Closing > Tuning.ChargingSpeed or Attacking(v, Now)\n\t            local Range: number = if Now - (v.shotAt or -math.huge) < Tuning.HarassMemory then math.max(Tuning.MenaceRange, Tuning.HarassRange) else Tuning.MenaceRange\n\t            if Now - (v.pursuedAt or -math.huge) < Tuning.PursuitMemory then\n\t                Range = math.max(Range, Tuning.RetreatClear)\n\t            end\n\t            if Distance <= Tuning.SiteGuard or Distance <= Range and (Chasing or Now - (v.pursuedAt or -math.huge) < Tuning.PursuitMemory) then\n\t                local Odds: number = CombatEstimate(v, v.position, Now)\n\t                if Odds < Tuning.OutmatchedOdds then\n\t                    Risk = math.max(Risk, (1 - Odds) * Tuning.PursuitRisk)\n\t                    if Chasing or Distance <= Tuning.SiteGuard then\n\t                        v.pursuedAt = Now\n\t                    end\n\t                end\n\t            end\n\t        end\n\t    end\n\t    return Risk\n\tend\n\t\n\tlocal function Intercept(Record)\n\t    local Root: BasePart = Entity.character.RootPart\n\t    local LiveRoot: BasePart? = RootOf(Record)\n\t    local Position: Vector3 = LiveRoot and LiveRoot.Position or Record.position\n\t    local Velocity: Vector3 = (LiveRoot and LiveRoot.AssemblyLinearVelocity or Record.velocity or Vector3.zero) * Planar\n\t    local Lead: number = math.min((Position - Root.Position).Magnitude / math.max(TravelSpeed(), 1), Tuning.PredictionLimit) * (1 - Record.volatility)\n\t    if Velocity.Magnitude < 3 or Lead <= 0.05 then\n\t        return Position\n\t    end\n\t\n\t    for i: number = 4, 1, -1 do\n\t        local Point: Vector3 = Position + Velocity * (Lead * i / 4)\n\t        if workspace:Raycast(Point + Vector3.new(0, 3, 0), Vector3.new(0, -12, 0), Senses.Params) then\n\t            return Point\n\t        end\n\t    end\n\t    return Position\n\tend\n\t\n\tlocal function Hazards(Now: number, Except)\n\t    local Avoid = {}\n\t    local Config = Agent.Memory.Config\n\t    for Key: number, v: any in Agent.Memory.routes do\n\t        if Now - v.timestamp < Config.AvoidLifetime then\n\t            Avoid[Key] = v.count * (Tuning.Blocked[v.reason] or Config.AvoidPenalty)\n\t        end\n\t    end\n\t    for _, v: any in World.enemies do\n\t        if v ~= Except and v.alive and v.position then\n\t            local Odds: number = CombatEstimate(v, v.position, Now)\n\t            if Odds < 0.6 then\n\t                local Grid: Vector3 = Navigation.WorldToGrid(v.position - Vector3.new(0, 1.5, 0))\n\t                local Weight: number = (0.6 - Odds) * 10\n\t                for X: number = -Tuning.HazardCells, Tuning.HazardCells do\n\t                    for Z: number = -Tuning.HazardCells, Tuning.HazardCells do\n\t                        local Spread: number = math.sqrt(X * X + Z * Z)\n\t                        if Spread <= Tuning.HazardCells then\n\t                            for Y: number = -1, 1 do\n\t                                local Key = Navigation.CellKey(Grid.X + X, Grid.Y + Y, Grid.Z + Z)\n\t                                Avoid[Key] = (Avoid[Key] or 0) + Weight * (1 - Spread / (Tuning.HazardCells + 1))\n\t                            end\n\t                        end\n\t                    end\n\t                end\n\t            end\n\t        end\n\t    end\n\t    return next(Avoid) and Avoid or nil\n\tend\n\t\n\tlocal function Elapsed(Now: number)\n\t    local State = bedwars.Store and bedwars.Store:getState()\n\t    local Started = State and State.Game and State.Game.startTime\n\t    if Started and Started > 0 then\n\t        return math.max(workspace:GetServerTimeNow() - Started, 0)\n\t    end\n\t    return Now - World.match.began\n\tend\n\t\n\tlocal function InferPhase()\n\t    local Me, Match = World.self, World.match\n\t    if Match.enemyTeams == 0 then\n\t        return \"VICTORY\"\n\t    elseif Match.enemyPlayers <= 1 and (Match.beds == 0 or Match.peakPlayers > 1) then\n\t        return \"FINAL\"\n\t    elseif Match.beds == 0 or Match.enemyTeams < Match.peakTeams and Match.enemyTeams <= 2 then\n\t        return \"ENDGAME\"\n\t    elseif Match.developed or Match.beds < Match.peakBeds or next(World.broken) ~= nil or Me.sword > 25 or Me.armor >= 0.3 or Match.elapsed > 420 then\n\t        return \"MIDGAME\"\n\t    elseif Match.elapsed < 45 then\n\t        return \"OPENING\"\n\t    end\n\t    return \"PRESSURE\"\n\tend\n\t\n\tlocal function Remember(Entry, Now: number)\n\t    local Record = World.enemies[Entry.id]\n\t    if not Record then\n\t        Record = {id = Entry.id, player = Entry.player, name = Entry.player.Name, seenAt = 0, volatility = 0, chaseFailures = 0, combatFailures = 0, lostAt = -math.huge, lastInteraction = 0}\n\t        World.enemies[Entry.id] = Record\n\t    end\n\t\n\t    Record.team, Record.present = Entry.team, Now\n\t    if Entry.alive and Record.deathAt and Entry.root == Record.corpse and Now - Record.deathAt < 3 then\n\t        return Record\n\t    end\n\t    if Entry.alive then\n\t        if not Record.alive and Record.respawnAt then\n\t            Record.respawnedAt = Now\n\t            World.spawns[Entry.team] = Entry.position\n\t            if World.broken[Entry.team] then\n\t                Record.huntUntil = Now + Tuning.HuntWindow\n\t            end\n\t        end\n\t        Record.respawnAt = nil\n\t        local Flat: Vector3 = Entry.velocity * Planar\n\t        Record.drift = if Record.drift then Record.drift:Lerp(Flat, Tuning.DriftRate) else Flat\n\t        if Flat.Magnitude > 4 then\n\t            local Turned: boolean = Record.heading ~= nil and Record.heading:Dot(Flat.Unit) < 0.5\n\t            Record.volatility = math.clamp(Record.volatility * 0.85 + (Turned and 0.25 or 0), 0, 0.9)\n\t            Record.heading = Flat.Unit\n\t        else\n\t            Record.volatility *= 0.9\n\t        end\n\t        Record.alive, Record.deathAt, Record.corpse, Record.absent = true, nil, nil, nil\n\t        Record.root, Record.position, Record.velocity, Record.seenAt = Entry.root, Entry.position, Entry.velocity, Now\n\t        Record.health, Record.maxHealth = Entry.health, math.max(Entry.maxHealth, 1)\n\t        Record.protected = Entry.protected\n\t        Record.falling = Entry.velocity.Y < -40 and not workspace:Raycast(Entry.position, Vector3.new(0, -80, 0), Senses.Params)\n\t    else\n\t        if Record.alive then\n\t            Record.absent = Entry.health > 0\n\t        end\n\t        Record.alive, Record.root = false, nil\n\t        Record.deathAt = Record.deathAt or Now\n\t    end\n\t    local Unloaded: boolean = Entry.sword == 0 and (Record.sword or 0) > 0 and (not Entry.alive or Now - (Record.respawnedAt or -math.huge) < Tuning.RespawnGear)\n\t    if Entry.gearKnown and not Unloaded then\n\t        Record.sword, Record.armor, Record.ranged, Record.gearAt = Entry.sword, Entry.armor, Entry.ranged, Now\n\t        Record.emeralds, Record.diamonds = Entry.emeralds or 0, Entry.diamonds or 0\n\t    end\n\t    return Record\n\tend\n\t\n\tlocal function Observe(Now: number)\n\t    local Me, Match = World.self, World.match\n\t    local Character: Model? = LocalPlayer.Character\n\t    Me.position, Me.team = Entity.character.RootPart.Position, tostring(LocalPlayer:GetAttribute(\"Team\"))\n\t    Me.health = Character:GetAttribute(\"Health\") or 0\n\t    Me.maxHealth = math.max(Character:GetAttribute(\"MaxHealth\") or 100, 1)\n\t    Me.ratio = math.clamp(Me.health / Me.maxHealth, 0, 1)\n\t    Me.speed = TravelSpeed()\n\t    local Samples = Me.samples\n\t    table.insert(Samples, {at = Now, health = Me.health})\n\t    while Now - Samples[1].at > Tuning.BurstWindow do\n\t        table.remove(Samples, 1)\n\t    end\n\t    local Peak: number = Me.health\n\t    for _, v: any in Samples do\n\t        Peak = math.max(Peak, v.health)\n\t    end\n\t    if Peak - Me.health >= Tuning.BurstLoss * Me.maxHealth then\n\t        if Now - (Brain.burstAt or -math.huge) > Tuning.BurstMemory then\n\t            MarkDirty(\"Losing health fast\")\n\t        end\n\t        Brain.burstAt = Now\n\t    end\n\t    local Wool, Amount = getWool()\n\t    Me.wool, Me.blocks = Wool, Wool and Amount or 0\n\t    local Sword, Armor = Senses.Gear(store.inventory.inventory)\n\t    Me.sword, Me.armor, Me.armorSlots = Sword, 0, Armor\n\t    for _, v: number in Armor do\n\t        Me.armor += v\n\t    end\n\t    Me.armor = math.clamp(Me.armor, 0, 0.9)\n\t    table.clear(Me.resources)\n\t    for _, v: any in store.inventory.inventory.items do\n\t        Me.resources[v.itemType] = (Me.resources[v.itemType] or 0) + v.amount\n\t    end\n\t\n\t    local Teams = World.teams\n\t    table.clear(Teams)\n\t    table.clear(World.teammates)\n\t    for _, v: any in Senses.Beds() do\n\t        Teams[v.team] = {id = v.team, bed = not World.broken[v.team] and v or nil, members = 0, alive = 0}\n\t        World.homes[v.team] = v.position\n\t    end\n\t\n\t    local Contacts, Strikes, Striking = 0, 0, Reach() + Tuning.ContestMargin\n\t    for _, v: any in Senses.Roster() do\n\t        local Team = Teams[v.team]\n\t        if not Team then\n\t            Team = {id = v.team, members = 0, alive = 0}\n\t            Teams[v.team] = Team\n\t        end\n\t        Team.members += 1\n\t        Team.alive += v.alive and 1 or 0\n\t        if v.enemy then\n\t            local Record = Remember(v, Now)\n\t            local Distance: number = Record.alive and (Record.position - Me.position).Magnitude or math.huge\n\t            if Distance <= Tuning.ContactRange then\n\t                Contacts += 1\n\t            end\n\t            if Distance <= Striking then\n\t                Strikes += 1\n\t            end\n\t        elseif v.alive then\n\t            table.insert(World.teammates, v.position)\n\t        end\n\t    end\n\t    for Id: string, v: any in World.enemies do\n\t        if Now - v.present > 2 then\n\t            World.enemies[Id] = nil\n\t        end\n\t    end\n\t    table.clear(World.respawns)\n\t    for _, v: any in World.enemies do\n\t        local At: number? = v.respawnAt\n\t        local Spawn: Vector3? = At and not v.alive and (World.spawns[v.team] or World.homes[v.team]) or nil\n\t        if Spawn and At - Now <= Tuning.RespawnLead and Now - At <= Tuning.RespawnGrace then\n\t            table.insert(World.respawns, {record = v, position = Spawn, at = At})\n\t        end\n\t    end\n\t    local Root: BasePart = Entity.character.RootPart\n\t    local Head: BasePart? = LocalPlayer.Character:FindFirstChild(\"Head\")\n\t    if Senses.Ground(Root.Position) and Head and #workspace:GetPartBoundsInBox(Head.CFrame, Head.Size, Senses.Overlap) == 0 then\n\t        Me.safe = Root.Position\n\t    end\n\t\n\t    local Own = Teams[Me.team]\n\t    Match.ownBed = Own ~= nil and Own.bed ~= nil\n\t    Match.enemyTeams, Match.enemyPlayers, Match.beds = 0, 0, 0\n\t    for TeamId: string, v: any in Teams do\n\t        if TeamId ~= Me.team and v.members > 0 then\n\t            Match.enemyTeams += 1\n\t            Match.enemyPlayers += v.members\n\t            Match.beds += v.bed and 1 or 0\n\t        end\n\t    end\n\t    Match.peakTeams = math.max(Match.peakTeams, Match.enemyTeams)\n\t    Match.peakBeds = math.max(Match.peakBeds, Match.beds)\n\t    Match.peakPlayers = math.max(Match.peakPlayers, Match.enemyPlayers)\n\t    Match.elapsed = Elapsed(Now)\n\t    Match.phase = InferPhase()\n\t    Match.developed = Match.developed or Match.phase ~= \"OPENING\" and Match.phase ~= \"PRESSURE\"\n\t    if Contacts > Match.contacts then\n\t        MarkDirty(\"Enemy contact\")\n\t    end\n\t    if Strikes > Match.strikes then\n\t        MarkDirty(\"Enemy in striking range\")\n\t    end\n\t    Match.contacts, Match.strikes = Contacts, Strikes\n\t    if Brain.thoughtRatio and Me.ratio < Brain.thoughtRatio - 0.2 then\n\t        MarkDirty(\"Health dropped\")\n\t    end\n\tend\n\t\n\tlocal function Exposure(From: Vector3, To: Vector3, Except, Now: number)\n\t    local Threat, Line = 0, To - From\n\t    local Length: number = Line.Magnitude\n\t    for _, v: any in World.enemies do\n\t        if v ~= Except and v.alive and (v.position - To).Magnitude > 12 then\n\t            local Along: number = Length > 0 and math.clamp((v.position - From):Dot(Line) / (Length * Length), 0, 1) or 0\n\t            local Distance: number = (From + Line * Along - v.position).Magnitude\n\t            if Distance < 18 then\n\t                Threat += (1 - Distance / 18) * (v.gearAt and v.sword > 0 and v.sword or Tuning.UnknownDamage) * Confidence(v, Now)\n\t            end\n\t        end\n\t    end\n\t    return Threat\n\tend\n\t\n\tlocal function EstimateTo(Candidate, Cost: number?, Now: number)\n\t    local Me = World.self\n\t    local Speed: number = math.max(Me.speed, 1)\n\t    local Goal = Brain.goal\n\t    local Key: string = Candidate.approach or Candidate.key\n\t    local Cached = Routing.profiles[Key]\n\t    local Profile, Remembered\n\t    if Goal and Goal.route and Goal.key == Candidate.key and Goal.approach == Candidate.approach then\n\t        Profile = Goal.route\n\t    elseif Cached and Now - Cached.at < Tuning.ProfileLifetime then\n\t        if (Cached.origin - Me.position).Magnitude < 12 then\n\t            Profile = Cached.profile\n\t        else\n\t            Remembered = Cached.profile and Cached.profile.Blocks or 64\n\t        end\n\t    end\n\t\n\t    local Distance: number = (Candidate.position - Me.position).Magnitude\n\t    local Threat: number = Exposure(Me.position, Candidate.position, Candidate.record, Now)\n\t    if SkyTravel.Enabled and ((Candidate.position - Me.position) * Planar).Magnitude >= Tuning.FlightMinimum and not Flight.Barred(Candidate, Now) and Flight.Viable(Candidate, Now) then\n\t        return {distance = Distance, blocks = 0, void = 0, threat = Threat, time = Distance / math.max(TravelSpeed(), 1) + Tuning.FlightOverhead, verified = true}\n\t    end\n\t    if Profile == false then\n\t        return {distance = Distance, blocks = 64, void = Distance, threat = Threat, time = Distance / Speed + 20, verified = true}\n\t    elseif Profile then\n\t        return {distance = Profile.Length, blocks = Profile.Blocks, void = Profile.Void, threat = Threat, time = Profile.Length / Speed + Profile.Blocks * 0.125 + Profile.Gaps * 0.2, verified = true}\n\t    end\n\t\n\t    local Void: number = (Cost or 0) * 3\n\t    local Crossing: number = Speed * FlyTime.Value\n\t    local Blocks: number = math.max(math.ceil((Void - Crossing) / 3), 0)\n\t    local Short = Routing.shortfalls[Candidate.key]\n\t    local Known: boolean = Short ~= nil and Now - Short.at < Tuning.ShortfallLifetime\n\t    if Remembered then\n\t        Blocks, Known = Remembered, true\n\t    end\n\t    if Short and Now - Short.at < Tuning.ShortfallLifetime then\n\t        Blocks = math.max(Blocks, Short.blocks)\n\t    end\n\t    return {distance = Distance, blocks = Blocks, void = Void, threat = Threat, time = Distance * Routing.detour / Speed + Blocks * 0.125, verified = Known}\n\tend\n\t\n\tlocal function Estimate(List, From: number, Now: number)\n\t    local Positions, Owners = {}, {}\n\t    for i: number = From, #List do\n\t        local Candidate = List[i]\n\t        if Candidate.position then\n\t            table.insert(Positions, Candidate.position)\n\t            table.insert(Owners, Candidate)\n\t        end\n\t    end\n\t    local Costs = Navigation.World and #Positions > 0 and Navigation:GetBlockCosts(World.self.position, Positions, {Mode = \"Blatant\"}) or {}\n\t    for i: number, v: any in Owners do\n\t        v.estimate = EstimateTo(v, Costs[i], Now)\n\t    end\n\tend\n\t\n\tlocal function Appraise(Candidate, Now: number)\n\t    local Me = World.self\n\t    local Estimate = Candidate.estimate\n\t    local Fear: number = Aversion(Me.ratio)\n\t    local Blocks: number = Estimate and Estimate.blocks or 0\n\t    local Short: number = math.max(Blocks - math.max(Me.blocks - Reserve.Value, 0), 0)\n\t    local Time: number = (Estimate and Estimate.time or 0) + (Candidate.extra or 0)\n\t    local Risk: number = Candidate.risk or 0\n\t    if Candidate.kind ~= \"RETREAT\" and not Candidate.record then\n\t        Risk = math.max(Risk, Brain.pursuit or 0)\n\t    end\n\t    Candidate.short, Candidate.time = Short, Time\n\t    Candidate.expected = Candidate.value * (Candidate.chance or 1)\n\t    Candidate.cost = Time * Tuning.TimeWeight + Blocks * Tuning.BlockWeight + Short * Tuning.ShortWeight * ((Estimate and Estimate.verified or Candidate.open) and 1 or Tuning.GuessedShort)\n\t        + (Estimate and Estimate.void or 0) * Tuning.VoidWeight * Fear\n\t        + Risk * math.min(DeathCost(), Candidate.stake or math.huge) * Fear\n\t        + ((Candidate.threat or 0) + (Estimate and Estimate.threat or 0)) * Tuning.ThreatWeight * Fear\n\t        + Penalty(Candidate.key, Now) + Penalty(Candidate.approach, Now)\n\t    Candidate.score = Candidate.expected - Candidate.cost\n\t    return Candidate\n\tend\n\t\n\tlocal function Shortage(List, From: number)\n\t    local Needed: number = 0\n\t    for i: number = From, #List do\n\t        local Candidate = List[i]\n\t        if Candidate.short and Candidate.short > 0 and (Candidate.estimate.verified or Candidate.open) and Candidate.score + Candidate.short * Tuning.ShortWeight > 0 then\n\t            Needed = math.max(Needed, math.min(Candidate.estimate.blocks, 64))\n\t        end\n\t    end\n\t    return Needed\n\tend\n\t\n\tlocal function AddBeds(List, Now: number)\n\t    local Me, Match = World.self, World.match\n\t    local Phase = Tuning.Phases[Match.phase]\n\t    for _, Team: any in World.teams do\n\t        local Bed = Team.bed\n\t        local Shield: number = Bed and math.max(Bed.shield - workspace:GetServerTimeNow(), 0) or 0\n\t        if Team.id == Me.team or not Bed or Bed.locked or Team.members == 0 or Shield > Tuning.ShieldWait then\n\t            continue\n\t        end\n\t\n\t        local Value: number = Tuning.BedValue * Phase.bed * (1 + 0.15 * math.max(Team.members - 1, 0)) * (Match.enemyTeams == 1 and 1.2 or 1) * (if Brain.rushing then Tuning.RushBed elseif Brain.unarmed then Tuning.UnarmedFactor elseif Brain.behind then Tuning.BehindFactor else 1)\n\t        local Cover = Senses.Cover(Bed.position)\n\t        local Threat, Count = ThreatNear(Bed.position, DefendRange.Value, Now)\n\t        local Odds, Helping, Guards = 1, 0, 0\n\t        for _, v: any in World.enemies do\n\t            local Grudge: boolean = v.killedAt ~= nil and Now - v.killedAt < Tuning.GrudgeTime\n\t            if v.team == Team.id and (v.alive and v.position and (v.position - Bed.position).Magnitude <= DefendRange.Value or Grudge) then\n\t                Odds = math.min(Odds, (CombatEstimate(v, Bed.position, Now)))\n\t                Guards += Grudge and 1 or 0\n\t            end\n\t        end\n\t        Count = math.max(Count, Guards)\n\t        for _, v: Vector3 in World.teammates do\n\t            if (v - Bed.position).Magnitude <= 12 then\n\t                Helping += 1\n\t            end\n\t        end\n\t\n\t        local Reason: string = `{Cover == 0 and \"exposed\" or `{Cover} cover`} bed, {Count} defender{Count == 1 and \"\" or \"s\"}{Helping > 0 and \", teammate already there\" or \"\"}{Brain.unarmed and \", outsworded\" or \"\"}{Brain.behind and \", outarmored\" or \"\"}`\n\t        for _, Side: {Name: string, Offset: Vector3} in Tuning.Sides do\n\t            local Position: Vector3 = Bed.position + Side.Offset\n\t            table.insert(List, {\n\t                kind = \"DESTROY_BED\",\n\t                key = `bed:{Team.id}`,\n\t                approach = `bed:{Team.id}:{Side.Name}`,\n\t                label = `team {Team.id} bed ({Side.Name})`,\n\t                team = Team.id,\n\t                bed = Bed,\n\t                position = Position,\n\t                value = Value * (Helping > 0 and 0.85 or 1),\n\t                chance = Count > 0 and 0.35 + 0.65 * Odds or 1,\n\t                risk = Count > 0 and (1 - Odds) * 0.7 or 0,\n\t                threat = Threat * 0.5 + (ThreatNear(Position, 18, Now)),\n\t                extra = 1.5 + Cover * 0.7 + Shield,\n\t                reason = Reason\n\t            })\n\t        end\n\t    end\n\tend\n\t\n\tlocal function Contender(Record)\n\t    local Diamond = bedwars.ItemMeta.diamond_sword\n\t    if (Record.sword or 0) >= (Diamond and Diamond.sword.damage or 42) or (Record.armor or 0) >= Tuning.DiamondArmor then\n\t        return false\n\t    end\n\t    for _, Site: any in Senses.Sites().Generators do\n\t        if Site.resource == \"emerald\" and (Site.position - Record.position).Magnitude <= Tuning.DenyRange then\n\t            return true\n\t        end\n\t    end\n\t    return false\n\tend\n\t\n\tlocal function AddKills(List, Now: number)\n\t    local Me, Match = World.self, World.match\n\t    local Phase = Tuning.Phases[Match.phase]\n\t    local Goal, Own = Brain.goal, World.teams[Me.team]\n\t    local Cornering: number = Escape(Now)\n\t    local Focus = Goal and Goal.record\n\t    for _, Record: any in World.enemies do\n\t        if not Record.alive or not Record.position or Record.falling then\n\t            continue\n\t        end\n\t\n\t        local Team = World.teams[Record.team]\n\t        local Bedless: boolean = not (Team and Team.bed)\n\t        local Value: number = Tuning.KillValue\n\t        if Bedless then\n\t            Value = Match.enemyPlayers <= 1 and Tuning.VictoryValue or Team and Team.members <= 1 and Tuning.EliminationValue or Tuning.FinalKillValue\n\t        end\n\t        Value += (1 - math.clamp(Record.health / Record.maxHealth, 0, 1)) * Tuning.WeakValue\n\t        local Loot: number = (Record.emeralds or 0) * Tuning.EmeraldBounty + (Record.diamonds or 0) * Tuning.DiamondBounty\n\t        local Contending: boolean = Contender(Record)\n\t        Value += math.min(Loot, Tuning.BountyLimit) + (Contending and Tuning.DenyValue or 0)\n\t        if Goal and Goal.kind == \"DESTROY_BED\" and Goal.team == Record.team and (Record.position - Goal.bed.part.Position).Magnitude <= DefendRange.Value then\n\t            Value += Tuning.DefenderValue\n\t        end\n\t\n\t        local Kind: string = \"ELIMINATE_PLAYER\"\n\t        local Intrusion: number = Own and Own.bed and (Record.position - Own.bed.position).Magnitude or math.huge\n\t        if Intrusion <= DefendRange.Value and not Brain.rushing then\n\t            Kind = \"DEFEND_BED\"\n\t            Value += Tuning.IntruderValue + (if Intrusion <= Tuning.RaidRange then Tuning.RaidValue else 0)\n\t        end\n\t        local Distance: number = (Record.position - Me.position).Magnitude\n\t        local Cornered: boolean = Now - (Brain.corneredAt or -math.huge) < Tuning.CorneredTime and Distance <= 25\n\t        if Cornered then\n\t            Value += Tuning.CorneredValue\n\t        end\n\t        local Chance, Count, _, Hits = CombatEstimate(Record, Record.position, Now)\n\t        if Brain.retreating and not Cornered and Hits > 1 then\n\t            continue\n\t        end\n\t        Value *= Phase.kill * (Record.protected and 0.4 or 1)\n\t        local Anchored: boolean = not Goal or Goal.kind == \"WAIT\" or Goal.subgoal == \"BREAK\" or Goal.subgoal == \"COLLECT\" or Goal.subgoal == \"BUY\" or Goal.subgoal == \"COVER\" or Goal.kind == \"DESTROY_BED\" and (Goal.bed.position - Me.position).Magnitude <= Tuning.BreakRange\n\t        local Current: boolean = Goal ~= nil and Goal.record == Record\n\t        local Rival: boolean = Focus ~= nil and Focus ~= Record and Focus.alive == true\n\t        local Engaged: boolean = Current and Distance <= Tuning.EngageRange\n\t        local Hitting: boolean = Attacking(Record, Now)\n\t        local Offset: Vector3 = (Record.position - Me.position) * Planar\n\t        local Away: number = Offset.Magnitude > 0.1 and (Record.velocity * Planar):Dot(Offset.Unit) or 0\n\t        local Drift: number = Offset.Magnitude > 0.1 and ((Record.drift or Record.velocity) * Planar):Dot(Offset.Unit) or 0\n\t        local Close: boolean = Distance <= math.min(Reach(), Tuning.Leash - Tuning.ContestMargin) and Now - (Record.releasedAt or -math.huge) > Tuning.ReleaseCooldown\n\t        local Striking: boolean = Hitting and Distance <= Reach() + Tuning.ContestMargin or Close and Visible(Record)\n\t        local Charging: boolean = Close and Away < -Tuning.ChargingSpeed\n\t        local Objective = Goal and (Goal.resume or (Tuning.Resumable[Goal.kind] or Goal.bedless) and Goal)\n\t        local Kiting: boolean = Goal ~= nil and Goal.subgoal == \"BREAK\" and not Goal.close\n\t        local Harassed: boolean = Distance <= Tuning.HarassRange and Now - (Record.shotAt or -math.huge) < Tuning.HarassMemory\n\t        local Contested: boolean = not Brain.retreating and not Record.protected and Chance >= (if Engaged or Harassed then Tuning.HoldOdds else Tuning.ContestOdds) and (Engaged or Harassed or Striking and (Hitting or not Rival and not Kiting and (Anchored or Charging)))\n\t        local Avoidable: number = Hitting and Distance <= Reach() + Tuning.ContestMargin and Cornering or 1\n\t        local Hunted: boolean = not Rival and not Brain.retreating and not Record.protected and Now < (Record.huntUntil or 0) and Chance >= Tuning.ContestOdds\n\t\n\t        local Closing: number = Me.speed - math.max(Drift, 0)\n\t        local CatchTime: number = Distance <= Tuning.EngageRange and 0 or Closing > 1 and math.min(Distance / Closing, 30) or 30\n\t        local Catchable: number = (Distance <= Tuning.EngageRange or Closing > 1 or Current) and 1 or 0.3\n\t        local Evasive: number = if Current or Distance <= Tuning.EngageRange then 1 else Tuning.ChaseDecay ^ (Record.chaseFailures * math.max(1 - (Now - (Record.chaseFailedAt or -math.huge)) / Tuning.ChaseMemory, 0))\n\t        local Reason: string = `win {math.floor(Chance * 100)}%, {Hits} hit{Hits == 1 and \"\" or \"s\"}, {Bedless and \"bedless\" or \"bed alive\"}`\n\t        if Count > 0 then\n\t            Reason ..= `, {Count} nearby`\n\t        end\n\t        if Contending then\n\t            Reason ..= \", contesting emeralds\"\n\t        end\n\t        if Outranged(Record) then\n\t            Reason ..= `, outranges us at {math.floor(Record.reach)} studs`\n\t        end\n\t        if (Record.emeralds or 0) > 0 then\n\t            Reason ..= `, carrying {Record.emeralds} emerald{Record.emeralds == 1 and \"\" or \"s\"}`\n\t        end\n\t        if Contested then\n\t            Reason ..= Hitting and \", hitting us\" or \", in striking range\"\n\t        end\n\t        table.insert(List, {\n\t            kind = Kind,\n\t            key = `kill:{Record.id}`,\n\t            label = Record.name,\n\t            record = Record,\n\t            bedless = Bedless,\n\t            urgent = Cornered or Contested or Hunted,\n\t            cornered = Cornered,\n\t            resume = Contested and Objective or nil,\n\t            position = Intercept(Record),\n\t            value = Value,\n\t            chance = Chance * Catchable * Evasive,\n\t            odds = Chance,\n\t            risk = (1 - Chance) * 0.8 * Avoidable,\n\t            threat = Count * 12,\n\t            extra = math.max(CatchTime - Distance / math.max(Me.speed, 1), 0) + Hits * Settings.CombatRate.Value + 1.5,\n\t            reason = Reason\n\t        })\n\t    end\n\tend\n\t\n\tlocal function AddCamps(List, Now: number)\n\t    local Me, Match = World.self, World.match\n\t    local Phase = Tuning.Phases[Match.phase]\n\t    for _, Record: any in World.enemies do\n\t        local Team = World.teams[Record.team]\n\t        local Spawn: Vector3? = World.spawns[Record.team] or World.homes[Record.team]\n\t        local At: number? = Record.respawnAt\n\t        local Shielded: boolean = Record.alive and Record.protected and Now < (Record.huntUntil or 0)\n\t        if not Spawn or Team and Team.bed or not Shielded and (Record.alive or not At or At - Now > Tuning.CampLead) then\n\t            continue\n\t        end\n\t        local Toward: Vector3 = (Me.position - Spawn) * Planar\n\t        local Stand: Vector3 = Spawn + (Toward.Magnitude > 0.1 and Toward.Unit or Vector3.new(1, 0, 0)) * math.min(Tuning.CampRadius, Toward.Magnitude)\n\t        local Health: number = Record.health\n\t        Record.health = Record.maxHealth or 100\n\t        local Chance: number = CombatEstimate(Record, Spawn, Now)\n\t        Record.health = Health\n\t        table.insert(List, {\n\t            kind = \"CAMP_SPAWN\",\n\t            key = `camp:{Record.id}`,\n\t            label = Record.name,\n\t            camper = Record,\n\t            position = Stand,\n\t            value = (Match.enemyPlayers <= 1 and Tuning.VictoryValue or Team and Team.members <= 1 and Tuning.EliminationValue or Tuning.FinalKillValue) * Phase.kill,\n\t            chance = Chance,\n\t            odds = Chance,\n\t            urgent = Chance >= Tuning.ContestOdds and (Me.position - Spawn).Magnitude <= Tuning.CampReach,\n\t            risk = (1 - Chance) * 0.8,\n\t            extra = At and math.max(At - Now, 0) or 0,\n\t            reason = `waiting for {Record.name} to respawn without a bed, win {math.floor(Chance * 100)}%`\n\t        })\n\t    end\n\tend\n\t\n\tlocal function OuterShell()\n\t    local Taken: {[string]: boolean} = {[\"0,0,0\"] = true, [\"0,0,1\"] = true}\n\t    for _, v: Vector3 in Tuning.Cover do\n\t        Taken[`{v.X},{v.Y},{v.Z}`] = true\n\t    end\n\t    local Cells: {Vector3} = {}\n\t    for _, v: Vector3 in Tuning.Cover do\n\t        for _, Side: Vector3 in {Vector3.new(1, 0, 0), Vector3.new(-1, 0, 0), Vector3.new(0, 0, 1), Vector3.new(0, 0, -1), Vector3.new(0, 1, 0)} do\n\t            local Cell: Vector3 = v + Side\n\t            local Key: string = `{Cell.X},{Cell.Y},{Cell.Z}`\n\t            if not Taken[Key] then\n\t                Taken[Key] = true\n\t                table.insert(Cells, Cell)\n\t            end\n\t        end\n\t    end\n\t    return Cells\n\tend\n\t\n\tlocal Shell: {Vector3} = OuterShell()\n\t\n\tlocal function CoverBlock(Strong: boolean)\n\t    for _, v: string in Tuning.CoverBlocks do\n\t        local Item = getItem(v)\n\t        if Item and (Item.amount or 0) > 0 then\n\t            return v, Item.amount\n\t        end\n\t    end\n\t    if Strong then\n\t        return nil, 0\n\t    end\n\t    local Wool, Amount = getWool()\n\t    return Wool, Wool and Amount or 0\n\tend\n\t\n\tlocal function Uncovered(Bed: BasePart, Cells: {Vector3}?)\n\t    local Open: {Vector3} = {}\n\t    for _, v: Vector3 in Cells or Tuning.Cover do\n\t        local Position: Vector3 = (Bed.CFrame * CFrame.new(v * 3)).Position\n\t        if not getPlacedBlock(Position) then\n\t            table.insert(Open, Position)\n\t        end\n\t    end\n\t    return Open\n\tend\n\t\n\tlocal function AddProtect(List, Now: number)\n\t    local Me, Match = World.self, World.match\n\t    local Own = World.teams[Me.team]\n\t    Brain.coverOpen = 0\n\t    if not CoverBed.Enabled or Brain.rushing or not Own or not Own.bed or not Own.bed.part.Parent then\n\t        return\n\t    end\n\t    local Open = Uncovered(Own.bed.part)\n\t    Brain.coverOpen, Brain.shellOpen = #Open, 0\n\t    if #Open == 0 then\n\t        local Outer = Uncovered(Own.bed.part, Shell)\n\t        local Strong, Amount = CoverBlock(true)\n\t        Brain.shellOpen = #Outer\n\t        if Strong and #Outer >= Tuning.CoverMinimum and not Suppressed(\"reinforce\", Now) then\n\t            table.insert(List, {\n\t                kind = \"PROTECT_BED\",\n\t                key = \"reinforce\",\n\t                label = \"own bed (outer layer)\",\n\t                bed = Own.bed,\n\t                shell = true,\n\t                open = #Outer,\n\t                position = Own.bed.position,\n\t                value = Tuning.ShellValue * (Tuning.CoverPhase[Match.phase] or 1) * math.min(#Outer, Amount) / #Shell,\n\t                chance = 1,\n\t                threat = (ThreatNear(Own.bed.position, 20, Now)),\n\t                extra = #Outer * 0.15,\n\t                reason = `{#Outer} open cells in the outer layer, {Amount} {Strong} carried`\n\t            })\n\t        end\n\t        return\n\t    end\n\t    if #Open < Tuning.CoverMinimum or Suppressed(\"protect\", Now) then\n\t        return\n\t    end\n\t    table.insert(List, {\n\t        kind = \"PROTECT_BED\",\n\t        key = \"protect\",\n\t        label = \"own bed\",\n\t        bed = Own.bed,\n\t        open = #Open,\n\t        position = Own.bed.position,\n\t        value = Tuning.CoverValue * (Tuning.CoverPhase[Match.phase] or 1) * #Open / #Tuning.Cover,\n\t        chance = 1,\n\t        threat = (ThreatNear(Own.bed.position, 20, Now)),\n\t        extra = #Open * 0.15,\n\t        reason = `{#Open} open cells around our bed`\n\t    })\n\tend\n\t\n\tlocal function AddScout(List, Now: number)\n\t    for _, Team: any in World.teams do\n\t        if Team.id == World.self.team or Team.members == 0 or Team.alive > 0 or Team.bed then\n\t            continue\n\t        end\n\t        local Last\n\t        for _, v: any in World.enemies do\n\t            if v.team == Team.id and v.position and (not Last or v.seenAt > Last.seenAt) then\n\t                Last = v\n\t            end\n\t        end\n\t        if Last and not (Last.deathAt and Now - Last.deathAt < 8) then\n\t            table.insert(List, {\n\t                kind = \"SCOUT\",\n\t                key = `scout:{Team.id}`,\n\t                label = `team {Team.id}`,\n\t                position = Last.position,\n\t                value = Tuning.ScoutValue * Tuning.Phases[World.match.phase].kill,\n\t                chance = 1,\n\t                reason = \"Enemy location unknown, checking where they were last seen\"\n\t            })\n\t        end\n\t    end\n\tend\n\t\n\tlocal function Offer(Item: string)\n\t    local ShopItem = bedwars.Shop.getShopItem(Item, LocalPlayer)\n\t    if not ShopItem or ShopItem.disabled or ShopItem.lockedByForge or ShopItem.ignoredByKit and table.find(ShopItem.ignoredByKit, store.equippedKit) then\n\t        return nil\n\t    end\n\t    local Upgrade = ShopItem.require and ShopItem.require.teamUpgrade\n\t    if Upgrade and bedwars.Store then\n\t        local Upgrades = bedwars.Store:getState().Bedwars.teamUpgrades\n\t        if (Upgrades[Upgrade.upgradeId] or -1) < Upgrade.lowestTierIndex then\n\t            return nil\n\t        end\n\t    end\n\t    return {item = Item, currency = ShopItem.currency, price = ShopItem.price, cost = ShopItem.price, amount = ShopItem.amount, tiered = ShopItem.tiered}\n\tend\n\t\n\tlocal function TeamOffer(Item: string)\n\t    local Meta = bedwars.TeamUpgradeMeta and bedwars.TeamUpgradeMeta[Item]\n\t    if not Meta or not bedwars.Store or Meta.disabledInQueue and table.find(Meta.disabledInQueue, store.queueType) then\n\t        return nil\n\t    end\n\t    local Upgrades = bedwars.Store:getState().Bedwars.teamUpgrades[LocalPlayer:GetAttribute(\"Team\")] or {}\n\t    local Index: number = (Upgrades[Item] or 0) + 1\n\t    local Tier = Meta.tiers[Index]\n\t    if not Tier or Tier.availableOnlyInQueue and not table.find(Tier.availableOnlyInQueue, store.queueType) then\n\t        return nil\n\t    end\n\t    return {item = Item, upgrade = true, currency = \"diamond\", price = Tier.cost, cost = Tier.cost, tier = Index}\n\tend\n\t\n\tlocal function NextTier(Chain: {string}, Current: number, Field: string)\n\t    for _, v: string in Chain do\n\t        local Meta = bedwars.ItemMeta[v]\n\t        local Value = Meta and Meta[Field] and (Meta[Field].damage or Meta[Field].damageReductionMultiplier)\n\t        if Value and Value > Current then\n\t            return v\n\t        end\n\t    end\n\t    return nil\n\tend\n\t\n\tlocal function Home()\n\t    local Me = World.self\n\t    local Team = World.teams[Me.team]\n\t    if Team and Team.bed then\n\t        return Team.bed.position\n\t    end\n\t    for _, v: any in Senses.Sites().Generators do\n\t        if v.owner == Me.team then\n\t            return v.position\n\t        end\n\t    end\n\t    return nil\n\tend\n\t\n\tlocal function Worth(Item: string)\n\t    local Meta = bedwars.ItemMeta[Item]\n\t    return Meta and (Meta.sword and Meta.sword.damage or Meta.armor and Meta.armor.damageReductionMultiplier) or 0\n\tend\n\t\n\tlocal function Scheduled(Field: string, Elapsed: number)\n\t    local Best: number = 0\n\t    for _, v: any in Tuning.GearPlan do\n\t        local Meta = bedwars.ItemMeta[v.item]\n\t        if Elapsed >= v.at and Meta and Meta[Field] then\n\t            Best = math.max(Best, Worth(v.item))\n\t        end\n\t    end\n\t    return Best\n\tend\n\t\n\tlocal function Outfit()\n\t    local Me = World.self\n\t    local Sword, Armor = 0, 0\n\t    for _, v: any in World.enemies do\n\t        if v.gearAt then\n\t            Sword, Armor = math.max(Sword, v.sword or 0), math.max(Armor, v.armor or 0)\n\t        end\n\t    end\n\t    local Chest = bedwars.ItemMeta[Tuning.Armors[1]]\n\t    local Plate: number = Chest and Me.armorSlots[Chest.armor.slot] or 0\n\t    local Blade: string? = NextTier(Tuning.Swords, Me.sword, \"sword\")\n\t    local Vest: string? = Chest and NextTier(Tuning.Armors, Plate, \"armor\") or nil\n\t    local Elapsed: number = World.match.elapsed\n\t    local Late: number = Elapsed - Tuning.PlanGrace\n\t    local Outsworded: boolean = Blade ~= nil and (Sword > Me.sword or Scheduled(\"sword\", Late) > Me.sword)\n\t    local Exposed: boolean = Vest ~= nil and (Armor > Me.armor + Tuning.GearMargin or Scheduled(\"armor\", Late) > Plate)\n\t    return {\n\t        blade = Blade,\n\t        vest = Vest,\n\t        sword = Outsworded or Blade ~= nil and Scheduled(\"sword\", Elapsed) > Me.sword,\n\t        armor = Exposed or Vest ~= nil and Scheduled(\"armor\", Elapsed) > Plate,\n\t        outsworded = Outsworded,\n\t        exposed = Exposed\n\t    }\n\tend\n\t\n\tlocal function Archery()\n\t    for _, v: any in store.inventory.inventory.items do\n\t        local Meta = bedwars.ItemMeta[v.itemType]\n\t        local Source = Meta and Meta.projectileSource\n\t        if Source and Source.ammoItemTypes and table.find(Source.ammoItemTypes, \"arrow\") then\n\t            return true\n\t        end\n\t    end\n\t    return false\n\tend\n\t\n\tlocal function Quiver()\n\t    local Meta = bedwars.ProjectileMeta and bedwars.ProjectileMeta.arrow\n\t    local Damage: number = Meta and Meta.combat and Meta.combat.damage or Tuning.ArrowDamage\n\t    local Goal = Brain.goal\n\t    local Focus = Goal and Goal.record\n\t    local Shots: number = 0\n\t    for _, v: any in World.enemies do\n\t        if v == Focus or not Focus and (v.alive or v.respawnAt) then\n\t            local Armor: number = if v.gearAt then v.armor or 0 else Tuning.UnknownArmor\n\t            Shots = math.max(Shots, (v.maxHealth or 100) / math.max(Damage * (1 - Armor), 1) / Tuning.ArrowAccuracy)\n\t        end\n\t    end\n\t    return math.clamp(math.ceil(Shots / 8) * 8, Tuning.ArrowFloor, Tuning.ArrowCap)\n\tend\n\t\n\tlocal function Needs()\n\t    local Me, List = World.self, {}\n\t    local Spare, Required = Me.blocks - Reserve.Value, Brain.blocksNeeded or 0\n\t    local Covering: number = if CoverBed.Enabled and not Brain.rushing then Brain.coverOpen or 0 else 0\n\t    if Covering >= Tuning.CoverMinimum and Spare < Covering then\n\t        local Worth: number = Tuning.CoverValue * (Tuning.CoverPhase[World.match.phase] or 1) * Covering / #Tuning.Cover\n\t        table.insert(List, {item = \"wool_white\", urgency = \"now\", blocks = math.max(Required, Covering) - Spare, worth = Worth})\n\t    elseif Spare < Required then\n\t        table.insert(List, {item = \"wool_white\", urgency = \"now\", blocks = Required - Spare})\n\t    elseif Me.blocks < Reserve.Value then\n\t        table.insert(List, {item = \"wool_white\", urgency = \"nice\", affordable = true})\n\t    end\n\t    local Gear = Brain.gear or {}\n\t    local Outmatched: boolean = Brain.odds ~= nil and Brain.odds < Tuning.InvestOdds\n\t    if Gear.blade then\n\t        local ShopItem = bedwars.Shop.getShopItem(Gear.blade, LocalPlayer)\n\t        local Urgency: string = if Gear.sword then \"parity\" elseif Outmatched or ShopItem and ShopItem.currency == \"emerald\" then \"soon\" else \"nice\"\n\t        table.insert(List, {item = Gear.blade, urgency = Urgency, affordable = Urgency == \"nice\"})\n\t    end\n\t    if Gear.vest then\n\t        local Urgency: string = if Gear.armor then (if Brain.recovering or not World.match.ownBed and Gear.exposed then \"parity\" else \"armor\") elseif Outmatched then \"soon\" else \"nice\"\n\t        table.insert(List, {item = Gear.vest, urgency = Urgency, affordable = Urgency == \"nice\"})\n\t    end\n\t    local Behind: boolean = Gear.sword or Gear.armor or Outmatched\n\t    local Chest = bedwars.ItemMeta[Tuning.Armors[1]]\n\t    local Plate: number = Chest and Me.armorSlots[Chest.armor.slot] or 0\n\t    local Armed: boolean = Worth(\"iron_sword\") > 0 and Me.sword >= Worth(\"iron_sword\") and Worth(\"iron_chestplate\") > 0 and Plate >= Worth(\"iron_chestplate\")\n\t    if Settings.BuyBow.Enabled and Armed then\n\t        if not Archery() then\n\t            table.insert(List, {item = \"wood_bow\", urgency = \"soon\", affordable = true})\n\t        else\n\t            local Arrows = getItem(\"arrow\")\n\t            local Held: number = Arrows and Arrows.amount or 0\n\t            local Wanted: number = Quiver()\n\t            if Held < Wanted then\n\t                local Short: boolean = Held < Tuning.ArrowFloor or Behind and Held < Wanted / 2\n\t                table.insert(List, {item = \"arrow\", urgency = if Short then \"soon\" else \"nice\", affordable = true})\n\t            end\n\t        end\n\t    end\n\t    if Brain.rushing then\n\t        return List\n\t    end\n\t    for _, v: string in Tuning.TeamUpgrades do\n\t        if v == \"TEAM_GENERATOR\" and (Brain.recovering or not World.match.ownBed) and Behind then\n\t            continue\n\t        end\n\t        local Urgency: string = if v == \"ARMOR\" then \"armor\" elseif v == \"TEAM_GENERATOR\" and World.match.elapsed < Tuning.EconomyWindow then \"invest\" else \"upgrade\"\n\t        table.insert(List, {item = v, urgency = Urgency, team = true})\n\t    end\n\t    if CoverBed.Enabled and (Brain.shellOpen or 0) >= Tuning.CoverMinimum and select(2, CoverBlock(true)) < math.min(Brain.shellOpen, Tuning.CoverBatch) then\n\t        table.insert(List, {item = Tuning.CoverBlocks[1], urgency = \"cover\"})\n\t    end\n\t    return List\n\tend\n\t\n\tlocal function AddEconomy(List, Now: number)\n\t    local Me = World.self\n\t    local Phase = Tuning.Phases[World.match.phase]\n\t    local Sites = Senses.Sites()\n\t    local Stock = Senses.Stock(Routing.stock)\n\t    local Base = Home()\n\t    local Invest: number = math.max(Phase.resource, 1 - (Brain.odds or 1))\n\t    local Wanted = Needs()\n\t    local Saving: {[string]: number} = {}\n\t    local Armor: string? = Me.armor == 0 and Me.sword >= Worth(\"stone_sword\") and Brain.gear and Brain.gear.vest or nil\n\t    table.sort(Wanted, function(A, B)\n\t        local Left, Right = Tuning.Utility[A.urgency], Tuning.Utility[B.urgency]\n\t        if Left == Right and Armor then\n\t            return A.item == Armor and B.item ~= Armor\n\t        end\n\t        return Left > Right\n\t    end)\n\t    for _, Need: any in Wanted do\n\t        local Deal = if Need.team then TeamOffer(Need.item) else Offer(Need.item)\n\t        local Meta = bedwars.ItemMeta[Need.item]\n\t        local Unique: boolean = Need.team == true or Meta ~= nil and (Meta.sword or Meta.armor or Meta.projectileSource) ~= nil\n\t        if not Deal or Suppressed(`buy:{Need.item}`, Now) or Unique and Now - (Routing.bought[Need.item] or -math.huge) < Tuning.PurchaseGrace then\n\t            continue\n\t        end\n\t        if Need.blocks and Deal.amount then\n\t            Deal.cost = Deal.price * math.max(math.ceil(Need.blocks / Deal.amount), 1)\n\t        end\n\t\n\t        local Value: number = math.max(Need.worth or 0, Tuning.Utility[Need.urgency] * ((Need.urgency == \"now\" or Need.urgency == \"parity\") and 1 or Need.urgency == \"cover\" and (Tuning.CoverPhase[World.match.phase] or 1) or Invest))\n\t        if Brain.recovering and Need.urgency == \"parity\" then\n\t            Value = math.max(Value, Tuning.RecoveryGear)\n\t        end\n\t        local Have: number = Me.resources[Deal.currency] or 0\n\t        local Spend = Routing.spent[Deal.currency]\n\t        if Spend and Now - Spend.at < Tuning.SpendLag and Have >= Spend.before then\n\t            Have -= Spend.price\n\t        end\n\t        local Reserved: number = if Need.urgency == \"now\" then 0 else Saving[Deal.currency] or 0\n\t        if Tuning.Utility[Need.urgency] >= Tuning.SaveUrgency then\n\t            Saving[Deal.currency] = (Saving[Deal.currency] or 0) + Deal.cost\n\t        end\n\t        Deal.cost += Reserved\n\t        if Have >= Deal.cost then\n\t            for _, Site: any in Deal.upgrade and Sites.Upgrades or Sites.Shops do\n\t                if Site.target.Parent and (not Deal.upgrade or Base and (Site.position - Base).Magnitude <= Tuning.BaseRadius) then\n\t                    table.insert(List, {\n\t                        kind = \"BUY_UPGRADE\",\n\t                        key = `buy:{Need.item}`,\n\t                        approach = `buy:{Need.item}:{Site.id}`,\n\t                        label = Need.item,\n\t                        site = Site,\n\t                        purchase = Deal,\n\t                        position = Site.position,\n\t                        value = Value,\n\t                        chance = 1,\n\t                        threat = (ThreatNear(Site.position, 20, Now)),\n\t                        risk = SiteRisk(Site.position, Now),\n\t                        reason = `{Need.urgency} purchase, {Deal.price} {Deal.currency} on hand`\n\t                    })\n\t                end\n\t            end\n\t        elseif not Need.affordable and (not Brain.rushing or Need.urgency == \"now\") then\n\t            local Missing: number = Deal.cost - Have\n\t            for _, Site: any in Sites.Generators do\n\t                local Owner = Site.owner and World.teams[Site.owner]\n\t                if Site.resource == Deal.currency and Site.target.Parent and (Site.owner == Me.team or not Owner or Owner.members == 0 or not Owner.bed) and not Suppressed(`collect:{Site.id}`, Now) then\n\t                    local Pooled, Rate = 0, 0\n\t                    for _, Other: any in Sites.Generators do\n\t                        if Other.resource == Site.resource and Other.target.Parent and (Other.position - Site.position).Magnitude <= Tuning.ClusterRange then\n\t                            local Cooldown: number? = Other.target:GetAttribute(\"Cooldown\")\n\t                            Pooled += Stock[Other.id] or 0\n\t                            Rate += if Cooldown and Cooldown > 0 then 1 / Cooldown else World.rates[Deal.currency]\n\t                        end\n\t                    end\n\t                    local Ready: number = math.min((Stock[Site.id] or 0) > 0 and Pooled or 0, Missing)\n\t                    table.insert(List, {\n\t                        kind = \"COLLECT_RESOURCE\",\n\t                        key = `collect:{Site.id}`,\n\t                        label = Site.id,\n\t                        site = Site,\n\t                        purchase = Deal,\n\t                        need = Deal.cost,\n\t                        currency = Deal.currency,\n\t                        position = Site.position,\n\t                        value = Value * 0.85,\n\t                        chance = 1,\n\t                        threat = (ThreatNear(Site.position, 20, Now)),\n\t                        risk = math.max(SiteRisk(Site.position, Now), Pinned(Site.position, Now)),\n\t                        extra = (Missing - Ready) / math.max(Rate, World.rates[Deal.currency]) * (if Site.owner == Me.team then Tuning.HomeWait else 1),\n\t                        reason = `{Need.urgency}: {Missing} {Deal.currency} short for {Need.item}, {Ready} waiting there`\n\t                    })\n\t                end\n\t            end\n\t        end\n\t    end\n\tend\n\t\n\tlocal function FarmSpot(Now: number)\n\t    local Me = World.self\n\t    local Lines: {Vector3} = Sightlines(Now)\n\t    local Reach: number = Pickup()\n\t    local Best, Stand, Distance = nil, nil, Tuning.FarmRange\n\t    for _, Site: any in Senses.Sites().Generators do\n\t        local Owner = Site.owner and World.teams[Site.owner]\n\t        if Site.resource == \"iron\" and Site.target.Parent and (Site.owner == Me.team or not Owner or Owner.members == 0 or not Owner.bed) and not Suppressed(`farm:{Site.id}`, Now) then\n\t            local Gap: number = (Site.position - Me.position).Magnitude\n\t            if Gap < Distance and ThreatNear(Site.position, Tuning.CoastClearance * 2, Now) == 0 and SiteRisk(Site.position, Now) == 0 then\n\t                local Spot: Vector3? = Site.position\n\t                if #Lines > 0 then\n\t                    Spot = if ((Me.position - Site.position) * Planar).Magnitude <= Reach and not Exposed(Me.position, Lines) then Me.position else Shelter(Site.position, Reach, Lines)\n\t                end\n\t                if Spot then\n\t                    Best, Stand, Distance = Site, Spot, Gap\n\t                end\n\t            end\n\t        end\n\t    end\n\t    return Best, Stand, #Lines > 0\n\tend\n\t\n\tlocal function Hideout(Now: number)\n\t    local Lines: {Vector3} = Sightlines(Now)\n\t    local Me = World.self\n\t    if #Lines == 0 or not Exposed(Me.position, Lines) then\n\t        return nil\n\t    end\n\t    return Shelter(Me.position, Tuning.ShelterRange, Lines)\n\tend\n\t\n\tlocal function AddRetreat(List, Now: number)\n\t    local Me = World.self\n\t    local Nearest: number = NearestEnemy(Me.position)\n\t    if Nearest > 60 and not Brain.retreating then\n\t        return\n\t    end\n\t\n\t    local Incoming, Danger, Spawning = 0, 0, 0\n\t    for _, v: any in World.enemies do\n\t        if v.alive and (v.position - Me.position).Magnitude <= 20 then\n\t            Incoming += (v.gearAt and v.sword > 0 and v.sword or Tuning.UnknownDamage) * (1 - Me.armor) / Tuning.AttackInterval\n\t            Danger = math.max(Danger, 1 - (CombatEstimate(v, v.position, Now)))\n\t        end\n\t    end\n\t    for _, v: any in World.respawns do\n\t        if (v.position - Me.position).Magnitude <= Tuning.RespawnRadius then\n\t            Incoming += (v.record.gearAt and v.record.sword > 0 and v.record.sword or Tuning.UnknownDamage) * (1 - Me.armor) / Tuning.AttackInterval\n\t            Danger = math.max(Danger, Tuning.RespawnDanger)\n\t            Spawning += 1\n\t        end\n\t    end\n\t    local Fear: number = Aversion(Me.ratio)\n\t    local Exposed: boolean = Spawning > 0 and Me.ratio < math.min(math.max(Recover.Value, Health.Value + 10) / 100, 1)\n\t    local Chased: number = (Brain.pursuit or 0) / Tuning.PursuitRisk\n\t    Danger = math.max(Danger * math.clamp(Incoming * 2.5 / math.max(Me.health, 1), 0, 1) * Escape(Now), Chased)\n\t    local Value: number = Danger * DeathCost() * (Fear - 0.6) * 0.8 + ((Brain.retreating or Exposed) and 35 * Fear or 0)\n\t    if Value <= 0 then\n\t        return\n\t    end\n\t    table.insert(List, {\n\t        kind = \"RETREAT\",\n\t        key = \"retreat\",\n\t        label = \"safety\",\n\t        value = Value,\n\t        chance = 1,\n\t        extra = 4,\n\t        urgent = (Brain.retreating and Nearest <= 60 or Exposed) and Now - (Brain.corneredAt or -math.huge) >= Tuning.CorneredTime,\n\t        reason = Brain.retreating and `health {math.floor(Me.ratio * 100)}%, healing before re-engaging` or Spawning > 0 and `{Spawning} enem{Spawning == 1 and \"y\" or \"ies\"} about to respawn here` or Chased >= Danger and `outmatched enemy closing in, {math.floor(Chased * 100)}% to lose that fight` or `{math.floor(Danger * 100)}% lethal pressure nearby`\n\t    })\n\tend\n\t\n\tlocal function Measure(Goal, Root: BasePart)\n\t    local Subgoal: string = Goal.subgoal\n\t    if Subgoal == \"BREAK\" then\n\t        return Goal.cover or 0\n\t    elseif Subgoal == \"TOWER\" then\n\t        return (Goal.bed.part.Position - Root.Position).Magnitude\n\t    elseif Subgoal == \"COVER\" then\n\t        return Goal.open or 0\n\t    elseif Subgoal == \"FIGHT\" then\n\t        return Goal.record.health or 0\n\t    elseif Subgoal == \"COLLECT\" then\n\t        return -(World.self.resources[Goal.currency] or 0)\n\t    elseif Subgoal == \"HOLD\" or Subgoal == \"BUY\" or Subgoal == \"PERCH\" then\n\t        return 0\n\t    elseif Goal.kind == \"RETREAT\" then\n\t        return -math.min((NearestEnemy(Root.Position)), 60)\n\t    end\n\t    return Goal.position and (Goal.position - Root.Position).Magnitude or 0\n\tend\n\t\n\tlocal function Progress(Goal)\n\t    local Subgoal: string = Goal.subgoal\n\t    if Subgoal == \"BREAK\" or Subgoal == \"TOWER\" or Subgoal == \"FIGHT\" or Subgoal == \"COLLECT\" or Subgoal == \"BUY\" or Subgoal == \"COVER\" then\n\t        return 0.8\n\t    end\n\t    local Initial: number = Goal.initial or 0\n\t    return Initial > 0 and math.clamp(1 - (Goal.best or Initial) / Initial, 0, 1) * 0.7 or 0\n\tend\n\t\n\tlocal function CancelRoute()\n\t    if Routing.request then\n\t        Routing.request.Cancelled = true\n\t        Routing.request = nil\n\t    end\n\t    Routing.retryAt = 0\n\tend\n\t\n\tlocal function Descend()\n\t    local State = Motion.aerial\n\t    Motion.aerial = nil\n\t    if not State or not State.up or not Entity.isAlive then\n\t        return\n\t    end\n\t    local Root: BasePart = Entity.character.RootPart\n\t    local Floor: RaycastResult? = workspace:Raycast(Root.Position, Vector3.new(0, -((State.lift or 0) + Tuning.SkyDrop), 0), Senses.Params)\n\t    local Stand: Vector3? = Floor and Touchdown(Vector3.new(Root.Position.X, Floor.Position.Y + Entity.character.HipHeight, Root.Position.Z), Root.Position.Y)\n\t    if Stand then\n\t        Root.CFrame = CFrame.new(Stand) * Root.CFrame.Rotation\n\t        Root.AssemblyLinearVelocity = Vector3.zero\n\t        Motion.written = Root.Position\n\t    elseif State.stand then\n\t        local Across: Vector3 = Vector3.new(State.stand.X, Root.Position.Y, State.stand.Z)\n\t        local Speed: number = math.max(TravelSpeed(), 1)\n\t        Motion.glide, Motion.leg = {across = Across, final = State.stand, speed = Speed, deadline = os.clock() + (Across - Root.Position).Magnitude / Speed + 1}, nil\n\t    end\n\tend\n\t\n\tlocal function Retarget()\n\t    CancelRoute()\n\t    Descend()\n\t    local Root = Entity.isAlive and Entity.character.RootPart\n\t    if Motion.leg and Root and not Senses.Ground(Root.Position) then\n\t        Motion.commit = Motion.leg\n\t    end\n\t    Motion.leg, Motion.orbit = nil, nil\n\t    Agent:Invalidate(\"Objective changed\")\n\tend\n\t\n\tlocal function Report(Text: string)\n\t    if Debug.Enabled then\n\t        warn(`[catvape] autowin {Text}`)\n\t    end\n\tend\n\t\n\tlocal function Fault(Kind: string, Text: string)\n\t    if Agent and not Agent:Throttle(`fault:{Kind}`, Tuning.ReportInterval) then\n\t        return\n\t    end\n\t    local Goal = Brain and Brain.goal\n\t    local Context: string = Goal and `{Goal.kind} {Goal.label} ({Goal.subgoal})` or \"no goal\"\n\t    warn(`[catvape] autowin {Kind}: {Text} | {Context} | last failure: {Brain and tostring(Brain.failure) or \"none\"}`)\n\tend\n\t\n\tlocal function SetGoal(Candidate, Now: number)\n\t    local Previous = Brain.goal\n\t    local Root: BasePart = Entity.character.RootPart\n\t    if Previous and not Candidate.resume and (Candidate.kind == \"BUY_UPGRADE\" or Candidate.kind == \"COLLECT_RESOURCE\") then\n\t        local Objective = Previous.resume or Previous.kind == \"DESTROY_BED\" and Previous or nil\n\t        if Objective and Objective.kind == \"DESTROY_BED\" then\n\t            Candidate.resume = Objective\n\t        end\n\t    end\n\t    Brain.revision += 1\n\t    Candidate.revision = Brain.revision\n\t    Candidate.createdAt, Candidate.lastProgressAt, Candidate.stage, Candidate.faults = Now, Now, 0, 0\n\t    Candidate.post = Candidate.resume and Root.Position or nil\n\t    Candidate.subgoal = Candidate.kind == \"RETREAT\" and \"PATH\" or Candidate.kind == \"WAIT\" and not Candidate.position and \"HOLD\" or \"APPROACH\"\n\t    Candidate.commitUntil = Now + (Tuning.Commit[Candidate.kind] or 2) * (1 + 0.5 * Brain.oscillation)\n\t    Candidate.initial = Measure(Candidate, Root)\n\t    Candidate.best, Candidate.measured = Candidate.initial, Candidate.subgoal\n\t    Brain.goal = Candidate\n\t    if Candidate.kind == \"WAIT\" then\n\t        Brain.idleAt = Brain.idleAt or Now\n\t    elseif (Candidate.score or 0) > 0 or Candidate.urgent then\n\t        Brain.idleAt = nil\n\t    end\n\t    if Previous then\n\t        Brain.previous = {key = Previous.key, ended = Now}\n\t        if Candidate.kind == \"RETREAT\" and Previous.kind ~= \"RETREAT\" and Previous.kind ~= \"WAIT\" then\n\t            RecordFailure(Previous.key, \"Driven off\", Now)\n\t            if Previous.resume then\n\t                RecordFailure(Previous.resume.key, \"Driven off\", Now)\n\t            end\n\t            if Previous.record and Previous.subgoal == \"FIGHT\" then\n\t                Previous.record.combatFailures += 1\n\t                Previous.record.lostAt = Now\n\t            end\n\t        end\n\t    end\n\t\n\t    local History = Brain.history\n\t    table.insert(History, {key = Candidate.key, at = Now, urgent = Candidate.urgent})\n\t    if #History > 8 then\n\t        table.remove(History, 1)\n\t    end\n\t    local Count: number = #History\n\t    if Count >= 3 and not History[Count].urgent and not History[Count - 1].urgent and History[Count].key == History[Count - 2].key and History[Count - 1].key ~= History[Count].key and Now - History[Count - 2].at < Tuning.OscillationWindow then\n\t        Brain.oscillation = math.min(Brain.oscillation + 1, 3)\n\t        Brain.oscillationAt = Now\n\t    end\n\t\n\t    Retarget()\n\t    local Alternative = Brain.alternative\n\t    Report(`-> {Candidate.kind} {Candidate.label} | score {string.format(\"%.1f\", Candidate.score or 0)} | alt {Alternative and Alternative.kind or \"none\"} {Alternative and Alternative.label or \"\"} = {string.format(\"%.1f\", Alternative and Alternative.score or 0)} | {Candidate.reason}`)\n\tend\n\t\n\tlocal function Valid(Goal)\n\t    if Goal.kind == \"DESTROY_BED\" then\n\t        local Team = World.teams[Goal.team]\n\t        return not World.broken[Goal.team] and Team ~= nil and Team.bed ~= nil and Team.bed.part == Goal.bed.part and Goal.bed.part.Parent ~= nil\n\t    elseif Goal.kind == \"PROTECT_BED\" then\n\t        return CoverBed.Enabled and Goal.bed.part.Parent ~= nil and not World.broken[World.self.team]\n\t    elseif Goal.record then\n\t        local Record = Goal.record\n\t        local Present: boolean = Record.alive or Record.absent == true and os.clock() - (Record.deathAt or 0) < Tuning.MissingGrace\n\t        return Present and World.enemies[Record.id] == Record\n\t    elseif Goal.camper then\n\t        local Record = Goal.camper\n\t        return World.enemies[Record.id] == Record and (not Record.alive and Record.respawnAt ~= nil or Record.alive and Record.protected and os.clock() < (Record.huntUntil or 0))\n\t    elseif Goal.site then\n\t        return Goal.site.target.Parent ~= nil\n\t    end\n\t    return true\n\tend\n\t\n\tlocal function Resume(Objective, Now: number, Reason: string)\n\t    if not Objective or Brain.goal or Brain.retreating or not Entity.isAlive or not Valid(Objective) then\n\t        return\n\t    end\n\t    Brain.revision += 1\n\t    Objective.revision, Objective.subgoal, Objective.measured = Brain.revision, \"APPROACH\", nil\n\t    Objective.lastProgressAt, Objective.stage, Objective.faults, Objective.anchor = Now, 0, 0, nil\n\t    Objective.commitUntil = Now + (Tuning.Commit[Objective.kind] or 2)\n\t    Brain.goal, Brain.idleAt = Objective, nil\n\t    table.insert(Brain.history, {key = Objective.key, at = Now, urgent = true})\n\t    if #Brain.history > 8 then\n\t        table.remove(Brain.history, 1)\n\t    end\n\t    Report(`resumed {Objective.kind} {Objective.label} ({Reason})`)\n\tend\n\t\n\tlocal function Finish(Goal, Now: number, Success: boolean, Reason: string)\n\t    if Brain.goal ~= Goal then\n\t        return\n\t    end\n\t    if Success and Goal.kind ~= \"WAIT\" then\n\t        Agent.Memory:Success(Goal.key, Now)\n\t        if Goal.approach then\n\t            Agent.Memory:Success(Goal.approach, Now)\n\t        end\n\t    end\n\t    Brain.goal, Brain.reason = nil, Reason\n\t    Brain.previous = {key = Goal.key, ended = Now}\n\t    Retarget()\n\t    MarkDirty(Reason)\n\t    Report(`{Success and \"done\" or \"dropped\"} {Goal.kind} {Goal.label} ({Reason})`)\n\t    Resume(Goal.resume, Now, Reason)\n\tend\n\t\n\tlocal function Fail(Goal, Now: number, Reason: string)\n\t    RecordFailure(Goal.key, Reason, Now)\n\t    if Goal.approach then\n\t        RecordFailure(Goal.approach, Reason, Now)\n\t    end\n\t    Finish(Goal, Now, false, Reason)\n\tend\n\t\n\tlocal function Refresh(Goal, Candidate)\n\t    Goal.score, Goal.value, Goal.expected, Goal.cost, Goal.chance, Goal.time = Candidate.score, Candidate.value, Candidate.expected, Candidate.cost, Candidate.chance, Candidate.time\n\t    Goal.reason, Goal.estimate = Candidate.reason, Candidate.estimate\n\t    if Candidate.kind == \"DESTROY_BED\" then\n\t        Goal.bed = Candidate.bed\n\t        if Goal.subgoal == \"APPROACH\" and (Candidate.position - Goal.position).Magnitude > 6 then\n\t            Goal.position, Goal.approach, Goal.label = Candidate.position, Candidate.approach, Candidate.label\n\t        end\n\t    elseif Candidate.kind == \"WAIT\" and Candidate.position and (not Goal.position or Candidate.covered and not Goal.covered or (Candidate.position - Goal.position).Magnitude > Tuning.ShelterShift) then\n\t        Goal.position, Goal.label, Goal.covered, Goal.subgoal, Goal.approach = Candidate.position, Candidate.label, Candidate.covered, \"APPROACH\", Candidate.approach\n\t    end\n\tend\n\t\n\tlocal function Rank(List)\n\t    local Best, Ranked, Goal = {}, {}, Brain.goal\n\t    local Kept: string? = Goal and Goal.approach and not Agent.Memory.failures[Goal.approach] and Goal.approach or nil\n\t    for _, v: any in List do\n\t        local Held = Best[v.key]\n\t        local Locked: boolean = Held ~= nil and Kept ~= nil and Held.approach == Kept\n\t        local Preferred: boolean = Kept ~= nil and v.approach == Kept\n\t        if not Held or not Locked and (Preferred or v.score > Held.score) then\n\t            Best[v.key] = v\n\t        end\n\t    end\n\t    for _, v: any in Best do\n\t        table.insert(Ranked, v)\n\t    end\n\t\n\t    local First, Second = 0, 0\n\t    for _, v: any in Ranked do\n\t        v.rate = math.max(v.score, 0) / (v.time + 5)\n\t        if v.rate > First then\n\t            First, Second = v.rate, First\n\t        elseif v.rate > Second then\n\t            Second = v.rate\n\t        end\n\t    end\n\t\n\t    for _, v: any in Ranked do\n\t        v.score -= Tuning.OpportunityWeight * v.time * (v.rate == First and Second or First)\n\t        if Goal and v.key == Goal.key then\n\t            v.score += Tuning.ContinueBonus + Tuning.ProgressBonus * Progress(Goal) + ((Goal.subgoal == \"BREAK\" or Goal.subgoal == \"TOWER\") and Tuning.BreakBonus or 0)\n\t        end\n\t    end\n\t    table.sort(Ranked, function(A, B)\n\t        if A.score ~= B.score then\n\t            return A.score > B.score\n\t        end\n\t        return A.key < B.key\n\t    end)\n\t    return Ranked\n\tend\n\t\n\tlocal function Evaluate(Candidate, Best, Force: boolean?)\n\t    if Routing.evaluating or not Candidate or not Candidate.position or Candidate.estimate and Candidate.estimate.verified or not Force and Best.score - Candidate.score > Tuning.SwitchMargin * 1.5 then\n\t        return\n\t    end\n\t\n\t    Routing.evaluating = true\n\t    local From, Key = World.self.position, Candidate.approach or Candidate.key\n\t    local Avoid = Hazards(os.clock(), Candidate.record)\n\t    task.spawn(function()\n\t        local Options = PlanOptions(\"autowineval\", Avoid, From)\n\t        Options.Label = false\n\t        local Success, Plan = pcall(Agent.Draft, Agent, From, Candidate.position, Options, nil, Candidate.key)\n\t        Routing.evaluating = false\n\t        if not Success then\n\t            Fault(\"route probe failed\", tostring(Plan))\n\t        end\n\t        local Profile = Success and Plan ~= nil and not Plan.Result.Partial and Plan:Profile(From) or false\n\t        Routing.profiles[Key] = {at = os.clock(), origin = From, profile = Profile}\n\t    end)\n\tend\n\t\n\tlocal function Urgency(Candidate)\n\t    if not Candidate.urgent then\n\t        return 0\n\t    end\n\t    return (Candidate.kind == \"RETREAT\" or Candidate.cornered) and Tuning.Urgency.Survival or Tuning.Urgency.Combat\n\tend\n\t\n\tlocal function Choose(Ranked, Now: number)\n\t    local Viable = {}\n\t    for _, v: any in Ranked do\n\t        if Valid(v) then\n\t            table.insert(Viable, v)\n\t        end\n\t    end\n\t    Ranked = Viable\n\t    local Best, Goal = Ranked[1], Brain.goal\n\t    local Level: number = 0\n\t    for _, v: any in Ranked do\n\t        local Value: number = Urgency(v)\n\t        if Value > Level then\n\t            Best, Level = v, Value\n\t        end\n\t    end\n\t    if Level == Tuning.Urgency.Combat and Best.record and (Best.odds or 1) < Tuning.OutmatchedOdds then\n\t        for _, v: any in Ranked do\n\t            if v.kind == \"RETREAT\" and v.score > 0 and v.score > Best.score + Tuning.SwitchMargin then\n\t                Best = v\n\t                break\n\t            end\n\t        end\n\t    end\n\t    local Held\n\t    local Standing: boolean = Goal ~= nil and Valid(Goal)\n\t    if Standing then\n\t        for _, v: any in Ranked do\n\t            if v.key == Goal.key then\n\t                Held = v\n\t                break\n\t            end\n\t        end\n\t    end\n\t    if Held then\n\t        Goal.missingAt = nil\n\t    elseif Standing and Level == 0 and Goal.record and not Brain.retreating then\n\t        Goal.missingAt = Goal.missingAt or Now\n\t        if Now - Goal.missingAt < Tuning.MissingGrace then\n\t            Brain.candidates = Ranked\n\t            return\n\t        end\n\t    end\n\t    if Held and Held ~= Best and Urgency(Held) >= Level then\n\t        local Focused: number = if not Held.record or Best.record == Held.record then 0 elseif Goal.subgoal == \"FIGHT\" then Tuning.FocusMargin elseif Goal.subgoal == \"CHASE\" then Tuning.ChaseFocus else 0\n\t        local Margin: number = Tuning.SwitchMargin * (1 + 0.75 * Brain.oscillation) + (Now < Goal.commitUntil and Tuning.CommitMargin or 0) + Focused\n\t        local Unproven: boolean = Level == 0 and Best.kind == Held.kind and not Best.record and Best.estimate ~= nil and not Best.estimate.verified and Held.estimate ~= nil and Held.estimate.verified\n\t        if Best.score <= Held.score + Margin then\n\t            Best = Held\n\t        elseif Unproven then\n\t            Evaluate(Best, Held, true)\n\t            Best = Held\n\t        end\n\t    end\n\t    if Urgency(Best) == 0 and Best.record and (Best.odds or 1) < Tuning.ContestOdds and Best.score <= 0 then\n\t        for _, v: any in Ranked do\n\t            if v.kind == \"WAIT\" then\n\t                Best = v\n\t                break\n\t            end\n\t        end\n\t    end\n\t\n\t    Brain.candidates = Ranked\n\t    Brain.alternative = Ranked[1] ~= Best and Ranked[1] or Ranked[2]\n\t    if Goal and Best.key == Goal.key then\n\t        Refresh(Goal, Best)\n\t    elseif Goal and Goal.resume and Best.key == Goal.resume.key then\n\t        Finish(Goal, Now, false, \"The interrupted objective outranks this\")\n\t        if Brain.goal and Brain.goal.key == Best.key then\n\t            Refresh(Brain.goal, Best)\n\t        else\n\t            SetGoal(Best, Now)\n\t        end\n\t    else\n\t        SetGoal(Best, Now)\n\t    end\n\t\n\t    local Probe, Promise = nil, Best.kind == \"WAIT\" and 0 or Best.score + Tuning.SwitchMargin\n\t    for _, v: any in Ranked do\n\t        local Estimate = v.estimate\n\t        if Estimate and not Estimate.verified and v.kind ~= \"BUY_UPGRADE\" then\n\t            local Unguessed: number = v.score + v.short * Tuning.ShortWeight * Tuning.GuessedShort + Estimate.blocks * Tuning.BlockWeight\n\t            if Unguessed > Promise then\n\t                Probe, Promise = v, Unguessed\n\t            end\n\t        end\n\t    end\n\t    if Probe then\n\t        Evaluate(Probe, Best, true)\n\t    else\n\t        Evaluate(Brain.alternative, Best)\n\t    end\n\tend\n\t\n\tlocal function Decide(Now: number)\n\t    local Me = World.self\n\t    local Epoch: number = Brain.epoch\n\t    Brain.thoughtAt, Brain.thoughtRatio, Brain.nextThink, Brain.dirty = Now, Me.ratio, Now + Settings.TargetRate.Value, nil\n\t    Agent.Memory:Expire(Now)\n\t    if Brain.oscillation > 0 and Now - Brain.oscillationAt > Tuning.OscillationDecay then\n\t        Brain.oscillation -= 1\n\t        Brain.oscillationAt = Now\n\t    end\n\t\n\t    local Goal = Brain.goal\n\t    local Plan = Agent:Current()\n\t    if Goal and Plan and Plan.TargetId == Goal.key and not Plan.Expired then\n\t        Goal.route = Plan:Profile(Me.position)\n\t    end\n\t\n\t    local List = {}\n\t    local Gear = Outfit()\n\t    local Blade = if Gear.outsworded then Offer(Gear.blade) else nil\n\t    local Vest = if Gear.exposed then Offer(Gear.vest) else nil\n\t    Brain.gear = Gear\n\t    Brain.unarmed = Blade ~= nil and Blade.currency == \"iron\"\n\t    Brain.behind = Vest ~= nil and Vest.currency == \"iron\"\n\t    Brain.pursuit = Pursuit(Now)\n\t    Brain.recovering = false\n\t    if Gear.sword or Gear.armor then\n\t        for _, v: any in World.enemies do\n\t            if v.alive and Now - math.max(v.killedAt or -math.huge, v.lostAt) < Tuning.LossLifetime then\n\t                Brain.recovering = true\n\t                break\n\t            end\n\t        end\n\t    end\n\t    Brain.rushing = Speedrun.Enabled and not Brain.recovering and World.match.ownBed ~= false and World.match.beds > 0\n\t    AddBeds(List, Now)\n\t    AddKills(List, Now)\n\t    AddCamps(List, Now)\n\t    AddScout(List, Now)\n\t    AddProtect(List, Now)\n\t    Estimate(List, 1, Now)\n\t    if Brain.epoch ~= Epoch then\n\t        return\n\t    end\n\t    for _, v: any in List do\n\t        if v.kind == \"PROTECT_BED\" and not v.shell and v.estimate then\n\t            v.estimate.blocks += v.open\n\t        end\n\t    end\n\t\n\t    local Odds\n\t    for _, v: any in List do\n\t        Appraise(v, Now)\n\t        if v.odds then\n\t            Odds = math.max(Odds or 0, v.odds)\n\t        end\n\t    end\n\t    Brain.odds = Odds\n\t    Brain.blocksNeeded = math.max(Shortage(List, 1), Brain.economyBlocks or 0)\n\t\n\t    local Count: number = #List\n\t    AddEconomy(List, Now)\n\t    AddRetreat(List, Now)\n\t    Estimate(List, Count + 1, Now)\n\t    if Brain.epoch ~= Epoch or not Entity.isAlive then\n\t        return\n\t    end\n\t    local Healthy: boolean = Me.ratio >= math.min(math.max(Recover.Value, Health.Value + 10) / 100, 1)\n\t    local Idle: number = Healthy and Brain.idleAt and math.min((Now - Brain.idleAt) * Tuning.IdleWeight, World.match.phase == \"FINAL\" and Tuning.FinalIdleLimit or Tuning.IdleLimit) or 0\n\t    local Farm, Stand, Covered = nil, nil, false\n\t    if not Brain.retreating then\n\t        Farm, Stand, Covered = FarmSpot(Now)\n\t    end\n\t    local Hidden: Vector3? = if Farm then nil else Hideout(Now)\n\t    table.insert(List, {kind = \"WAIT\", key = \"wait\", approach = if Farm then `farm:{Farm.id}` else nil, label = if Farm then `farming at {Farm.id}` elseif Hidden then \"in cover\" else \"idle\", position = Stand or Hidden, covered = Covered or Hidden ~= nil, value = -Idle, chance = 1, reason = Idle > 0 and `Nothing has positive expected value, idle for {math.floor(Now - Brain.idleAt)}s` or \"Nothing has positive expected value\"})\n\t    for i: number = Count + 1, #List do\n\t        Appraise(List[i], Now)\n\t    end\n\t    Brain.economyBlocks = Shortage(List, Count + 1)\n\t    Choose(Rank(List), Now)\n\tend\n\t\n\tlocal function Think(Now: number)\n\t    if Brain.thinking then\n\t        return\n\t    end\n\t    local Token = {at = Now}\n\t    Brain.thinking = Token\n\t    Brain.nextThink = Now + Settings.TargetRate.Value\n\t    task.spawn(function()\n\t        local Success, Error = xpcall(Decide, debug.traceback, Now)\n\t        if Brain.thinking == Token then\n\t            Brain.thinking = false\n\t        end\n\t        if not Success then\n\t            Brain.failure = tostring(Error)\n\t            Fault(\"decision failed\", tostring(Error))\n\t        end\n\t    end)\n\tend\n\t\n\tlocal function Breakout(Target: Vector3, Now: number)\n\t    local Root: BasePart = Entity.character.RootPart\n\t    local Feet: Vector3 = Navigation.WorldToGrid(Root.Position - Vector3.new(0, Entity.character.HipHeight - 1.5, 0))\n\t    local Flat: Vector3 = (Target - Root.Position) * Planar\n\t    local Best, Score = nil, -math.huge\n\t    for _, v: Vector3 in {Vector3.new(1, 0, 0), Vector3.new(-1, 0, 0), Vector3.new(0, 0, 1), Vector3.new(0, 0, -1)} do\n\t        local Open: boolean = true\n\t        for Y: number = 0, 1 do\n\t            local Grid: Vector3 = Feet + v + Vector3.new(0, Y, 0)\n\t            local Placed = Senses.Block(Grid)\n\t            if Placed or Navigation.World and Navigation.World:Solid(Grid.X, Grid.Y, Grid.Z) then\n\t                Open = false\n\t            end\n\t            if Placed then\n\t                local Value: number = Flat.Magnitude > 0.1 and Flat.Unit:Dot(v) or 0\n\t                if Value > Score then\n\t                    Best, Score = Grid, Value\n\t                end\n\t            end\n\t        end\n\t        if Open then\n\t            return false\n\t        end\n\t    end\n\t    if not Best then\n\t        return false\n\t    end\n\t\n\t    Motion.breaking = {grid = Best, deadline = Now + 3}\n\t    Brain.failure = \"Boxed in, breaking toward the objective\"\n\t    return true\n\tend\n\t\n\tlocal function RouteFault(Goal, Reason: string, Now: number)\n\t    Brain.failure = Reason\n\t    local Plan = Agent:Current()\n\t    if Plan and not Plan.Expired and Plan.TargetId == Goal.key and Plan.Cursor <= #Plan.Waypoints then\n\t        Routing.softFaults = (Routing.softFaults or 0) + 1\n\t        Routing.retryAt = Now + math.min(Routing.softFaults, 4) * Tuning.RouteRetry\n\t        return\n\t    end\n\t    Goal.faults = (Goal.faults or 0) + 1\n\t    Routing.retryAt = Now + math.min(Goal.faults, 4) * Tuning.RouteRetry\n\t    if Entity.isAlive and (Flight.Down(Goal, Now) or Breakout(Goal.position or World.self.position, Now)) then\n\t        return\n\t    end\n\t    if Goal.faults >= Tuning.RouteFaults then\n\t        if Goal.kind == \"RETREAT\" then\n\t            MarkDirty(Reason)\n\t        else\n\t            Fail(Goal, Now, Reason)\n\t        end\n\t    end\n\tend\n\t\n\tlocal function Intercepted(Plan, From: Vector3)\n\t    local Speed, Travelled, Previous = math.max(TravelSpeed(), 1), 0, From\n\t    local Margin: number = math.min(NearestEnemy(From) - 2, Tuning.RetreatClearance)\n\t    for _, v: any in Plan.Waypoints do\n\t        Travelled += (v.Position - Previous).Magnitude\n\t        Previous = v.Position\n\t        local Elapsed: number = Travelled / Speed\n\t        for _, Enemy: any in World.enemies do\n\t            if Enemy.alive then\n\t                local Offset: Vector3 = (From - LivePosition(Enemy)) * Planar\n\t                local Closing: number = Offset.Magnitude > 0.1 and ((Enemy.velocity or Vector3.zero) * Planar):Dot(Offset.Unit) or 0\n\t                local Pace: number = Closing > 4 and math.max(Closing, Tuning.PursuitSpeed) or ((Enemy.velocity or Vector3.zero) * Planar).Magnitude\n\t                if (v.Position - LivePosition(Enemy)).Magnitude - Pace * Elapsed < Margin then\n\t                    return true\n\t                end\n\t            end\n\t        end\n\t    end\n\t    return false\n\tend\n\t\n\tlocal function Skip(Plan, Position: Vector3)\n\t    local Points = Plan.Waypoints\n\t    while Plan.Cursor < #Points do\n\t        local Here, Following = Points[Plan.Cursor], Points[Plan.Cursor + 1]\n\t        local Along: Vector3 = (Following.Position - Here.Position) * Planar\n\t        local Behind: Vector3 = (Here.Position - Position) * Planar\n\t        if Here.Type ~= \"Walk\" or Here.Blocks or Following.Blocks or Following.AirTime or Along.Magnitude < 0.1 or Behind.Magnitude > Tuning.SkipRange or math.abs(Here.Position.Y - Position.Y) > 2 or Behind:Dot(Along) > 0 then\n\t            break\n\t        end\n\t        Plan.Cursor += 1\n\t    end\n\tend\n\t\n\tlocal function Receive(Goal, Plan, Result, Position: Vector3, Now: number)\n\t    local Root = Entity.isAlive and Entity.character.RootPart\n\t    if not Root then\n\t        return\n\t    end\n\t    if not Plan then\n\t        RouteFault(Goal, Result and Result.Reason or \"Navigation is unavailable\", Now)\n\t        return\n\t    end\n\t\n\t    if Plan.Result.Partial and Plan.Kind ~= \"Retreat\" then\n\t        local Ending: Vector3 = Plan.Waypoints[#Plan.Waypoints].Position\n\t        local Gain: number = (Position - Root.Position).Magnitude - (Position - Ending).Magnitude\n\t        if Gain < 12 or Goal.partial and (Goal.partial - Ending).Magnitude < 6 then\n\t            local Spare: number = World.self.blocks - Reserve.Value\n\t            if Spare < 24 then\n\t                Routing.shortfalls[Goal.key] = {blocks = math.max(Spare + 8, Goal.estimate and Goal.estimate.blocks or 0), at = Now}\n\t            end\n\t            RouteFault(Goal, \"Route cannot reach the objective with the blocks available\", Now)\n\t            return\n\t        end\n\t        Goal.partial = Ending\n\t    end\n\t\n\t    if Goal.kind == \"RETREAT\" and Intercepted(Plan, Root.Position) then\n\t        Goal.flee = not Goal.flee\n\t        RouteFault(Goal, \"Retreat route can be cut off by a pursuer\", Now)\n\t        Routing.retryAt = Now\n\t        return\n\t    end\n\t\n\t    local _, Carried = getWool()\n\t    local Pending = Plan:Pending()\n\t    if Pending > (Carried or 0) then\n\t        Routing.shortfalls[Goal.key] = {blocks = Pending, at = Now}\n\t        RouteFault(Goal, `Route needs {Pending} blocks, carrying {Carried or 0}`, Now)\n\t        return\n\t    end\n\t\n\t    local Airborne: boolean = Motion.leg ~= nil and not Senses.Ground(Root.Position)\n\t    local Current, Adopted = Agent:Adopt(Plan, {position = Root.Position, velocity = Motion.velocity, airborne = Airborne}, Now)\n\t    if Adopted then\n\t        if Airborne then\n\t            Motion.commit = Motion.leg\n\t        else\n\t            Skip(Current, Root.Position)\n\t        end\n\t        Motion.leg = nil\n\t        table.clear(PlacedMemo)\n\t        Senses.Clear()\n\t        ShowBlocks(Current)\n\t        if Debug.Enabled and Plan.Result.Decisions and Agent:Throttle(\"decisions\") then\n\t            for _, v: any in Plan.Result.Decisions do\n\t                warn(`[catvape] autowin {v.Summary}`)\n\t            end\n\t        end\n\t    end\n\t    Routing.softFaults = 0\n\t    Goal.route = Current:Profile(Root.Position)\n\t    Routing.profiles[Goal.approach or Goal.key] = {at = Now, origin = Root.Position, profile = Goal.route}\n\t    local Straight: number = (Position - Root.Position).Magnitude\n\t    if Straight > Tuning.DetourSample and not Goal.route.Partial then\n\t        Routing.detour = math.clamp(Routing.detour * 0.7 + Goal.route.Length / Straight * 0.3, Tuning.Detour, Tuning.DetourLimit)\n\t    end\n\tend\n\t\n\tlocal function RequestRoute(Goal, Position: Vector3?, Threats: {Vector3}?, Now: number)\n\t    CancelRoute()\n\t    local Request = {Cancelled = false}\n\t    local From: Vector3 = Entity.character.RootPart.Position\n\t    local Avoid = Hazards(Now, Goal.record)\n\t    Routing.request, Routing.at, Routing.replace = Request, Now, nil\n\t    task.spawn(function()\n\t        local Began: number = os.clock()\n\t        local Success, Plan, Result = pcall(Agent.Draft, Agent, From, Position, PlanOptions(\"autowin\", Avoid, From), Threats, Goal.key, Request)\n\t        if Routing.request ~= Request then\n\t            return\n\t        end\n\t        Routing.request, Routing.took = nil, os.clock() - Began\n\t        if Brain.goal ~= Goal then\n\t            return\n\t        end\n\t        if not Success then\n\t            Fault(\"route failed\", tostring(Plan))\n\t            RouteFault(Goal, tostring(Plan), os.clock())\n\t            return\n\t        end\n\t        Receive(Goal, Plan, Result, Position or World.self.position, os.clock())\n\t    end)\n\tend\n\t\n\tlocal function Dodge(Speed: number, Delta: number, Velocity: Vector3)\n\t    local Root: BasePart = Entity.character.RootPart\n\t    local Projectile = Senses.Projectile(Root.Position, Velocity)\n\t    local Side = Projectile and Vector3.new(-Projectile.velocity.Z, 0, Projectile.velocity.X)\n\t    if not Side or Side.Magnitude < 0.1 then\n\t        return false\n\t    end\n\t\n\t    local Direction, Floor\n\t    for _, v: Vector3 in {Side.Unit, -Side.Unit} do\n\t        local Hit: RaycastResult? = workspace:Raycast(Root.Position + v * Speed * Delta + Vector3.new(0, 3, 0), Vector3.new(0, -70, 0), Senses.Params)\n\t        if Hit and Hit.Position.Y >= Root.Position.Y - Entity.character.HipHeight - 4 and not workspace:Blockcast(CFrame.new(Root.Position), Vector3.new(Root.Size.X, Entity.character.HipHeight + (Root.Size.Y / 2), Root.Size.X), v * (Speed * Delta + 1.5), Senses.Params) and (not Direction or not Senses.Projectile(Root.Position + v * Speed * Delta, v * Speed)) then\n\t            Direction, Floor = v, Hit\n\t        end\n\t    end\n\t\n\t    if not Direction then\n\t        return false\n\t    end\n\t\n\t    local Position: Vector3 = Root.Position + Direction * Speed * Delta\n\t    Position = Vector3.new(Position.X, Floor.Position.Y + Entity.character.HipHeight, Position.Z)\n\t    if not Clear(Position) then\n\t        return false\n\t    end\n\t    Root.CFrame = CFrame.new(Position) * Root.CFrame.Rotation\n\t    Root.AssemblyLinearVelocity = Vector3.zero\n\t    return true\n\tend\n\t\n\tlocal function Hold(Now: number, DeltaTime: number)\n\t    if Motion.leg and not Senses.Ground(Entity.character.RootPart.Position) then\n\t        Motion.commit = Motion.leg\n\t    end\n\t    Motion.leg, Motion.orbit = nil, nil\n\t    if not Motion.commit then\n\t        Dodge(TravelSpeed(), DeltaTime, Vector3.zero)\n\t    end\n\tend\n\t\n\tlocal function Coast(Toward: Vector3?, Now: number, DeltaTime: number, Guard)\n\t    local Root: BasePart = Entity.character.RootPart\n\t    local Flat: Vector3 = Toward and (Toward - Root.Position) * Planar or Vector3.zero\n\t    if Flat.Magnitude < 1 or Motion.commit or not Senses.Ground(Root.Position) then\n\t        Hold(Now, DeltaTime)\n\t        return false\n\t    end\n\t\n\t    local Step: number = math.min(TravelSpeed() * DeltaTime, Flat.Magnitude)\n\t    local Lowest: number = Root.Position.Y - Entity.character.HipHeight - Tuning.CoastDrop\n\t    local Heading: Vector3 = Flat.Unit\n\t    local Side: number = Motion.coastSide or 1\n\t    local Locked: boolean = Now < (Motion.coastUntil or 0)\n\t    local Edge: boolean = false\n\t    for _, Angle: number in Tuning.CoastAngles do\n\t        if Locked and Angle < 0 or Edge and math.abs(Angle) > 45 then\n\t            continue\n\t        end\n\t        local Theta: number = math.rad(Angle * Side)\n\t        local Direction: Vector3 = Vector3.new(Heading.X * math.cos(Theta) - Heading.Z * math.sin(Theta), 0, Heading.X * math.sin(Theta) + Heading.Z * math.cos(Theta))\n\t        local Position, Blocked = Stride(Root.Position, Direction, Step, Lowest)\n\t        Edge = Edge or Angle == 0 and Blocked == \"void\"\n\t        if Position and not (Guard and ThreatNear(Position, Tuning.CoastClearance, Now, Guard.record) > 0) then\n\t            if Angle ~= 0 then\n\t                Motion.coastSide, Motion.coastUntil = Side * math.sign(Angle), Now + Tuning.CoastLock\n\t            end\n\t            Motion.leg, Motion.orbit = nil, nil\n\t            Root.CFrame = CFrame.lookAlong(Position, Direction)\n\t            Root.AssemblyLinearVelocity = Vector3.zero\n\t            Motion.written, Motion.velocity, Motion.controlledAt = Root.Position, Direction * TravelSpeed(), Now\n\t            return true\n\t        end\n\t    end\n\t    Hold(Now, DeltaTime)\n\t    return false\n\tend\n\t\n\tlocal function Glide(Across: Vector3, Final: Vector3?, Speed: number, Now: number)\n\t    local Root: BasePart = Entity.character.RootPart\n\t    Motion.glide = {across = Across, final = Final, speed = math.max(Speed, 1), deadline = Now + (Across - Root.Position).Magnitude / math.max(Speed, 1) + 1}\n\t    Motion.leg = nil\n\tend\n\t\n\tlocal function StepGlide(Now: number, DeltaTime: number)\n\t    local Maneuver = Motion.glide\n\t    local Root: BasePart = Entity.character.RootPart\n\t    local Offset: Vector3 = Maneuver.across - Root.Position\n\t    if Offset.Magnitude < 1 or Now > Maneuver.deadline then\n\t        local Final: Vector3? = Maneuver.final and ((Root.Position - Maneuver.across) * Planar).Magnitude < 2 and Touchdown(Maneuver.final, Root.Position.Y) or nil\n\t        if Final then\n\t            Root.CFrame = CFrame.new(Final)\n\t        end\n\t        Root.AssemblyLinearVelocity = Vector3.zero\n\t        Motion.glide, Motion.written = nil, Root.Position\n\t        return\n\t    end\n\t    local Position: Vector3 = Root.Position + Offset.Unit * math.min(Maneuver.speed * DeltaTime, Offset.Magnitude)\n\t    if not Clear(Position, Tuning.HoverWidth) then\n\t        Motion.glide = nil\n\t        return\n\t    end\n\t    Root.CFrame = CFrame.new(Position)\n\t    Root.AssemblyLinearVelocity = Vector3.zero\n\t    Motion.written, Motion.controlledAt = Root.Position, Now\n\tend\n\t\n\tlocal function Land(Now: number)\n\t    if Now < Motion.nextLand then\n\t        return false\n\t    end\n\t    local Root: BasePart = Entity.character.RootPart\n\t    local HipHeight: number = Entity.character.HipHeight\n\t    local From: Vector3 = Root.Position\n\t    local Best = Senses.Landing(Root, HipHeight, function(Top: Vector3)\n\t        local Goal: Vector3 = Vector3.new(Top.X, Top.Y + HipHeight + 0.5, Top.Z)\n\t        local Raised: Vector3 = Vector3.new(From.X, math.max(From.Y, Goal.Y), From.Z)\n\t        return Clear(Raised, Tuning.HoverWidth) and Hop(From, Goal)\n\t    end)\n\t    if not Best then\n\t        Motion.nextLand = Now + 0.25\n\t        return false\n\t    end\n\t\n\t    local Goal: Vector3 = Vector3.new(Best.X, Best.Y + HipHeight + 0.5, Best.Z)\n\t    local Height: number = math.max(Root.Position.Y, Goal.Y)\n\t    Root.CFrame = CFrame.new(Root.Position.X, Height, Root.Position.Z)\n\t    Root.AssemblyLinearVelocity = Vector3.zero\n\t    Glide(Vector3.new(Goal.X, Height, Goal.Z), Goal, TravelSpeed(), Now)\n\t    Agent:Invalidate(\"Recovered onto nearby ground\")\n\t    return true\n\tend\n\t\n\tlocal function Perch(Now: number)\n\t    if Now < Motion.nextClimb then\n\t        return nil\n\t    end\n\t    local Root: BasePart = Entity.character.RootPart\n\t    local HipHeight: number = Entity.character.HipHeight\n\t    local From: Vector3 = Root.Position\n\t    local Best = Senses.Perch(Root, HipHeight, Entity.AllPosition({\n\t        Range = 60,\n\t        Part = \"RootPart\",\n\t        Players = true\n\t    }), function(Top: Vector3)\n\t        return Hop(From, Vector3.new(Top.X, Top.Y + HipHeight + 0.5, Top.Z))\n\t    end)\n\t    if not Best then\n\t        Motion.nextClimb = Now + 0.5\n\t        return nil\n\t    end\n\t\n\t    local Goal: Vector3 = Vector3.new(Best.X, Best.Y + HipHeight + 0.5, Best.Z)\n\t    local Climb: number = Goal.Y - Root.Position.Y\n\t    Root.CFrame = CFrame.new(Root.Position.X, Goal.Y, Root.Position.Z)\n\t    Root.AssemblyLinearVelocity = Vector3.zero\n\t    Glide(Goal, nil, getSpeed(), Now)\n\t    Agent:Invalidate(\"Climbed away from a fight\")\n\t    Report(`climbing {math.floor(Climb)} studs to break contact`)\n\t    return Goal\n\tend\n\t\n\tlocal function Rise(Now: number)\n\t    Motion.nextLand = 0\n\t    if Land(Now) then\n\t        return true\n\t    end\n\t    Motion.nextClimb = 0\n\t    return Perch(Now) ~= nil\n\tend\n\t\n\tfunction Leap.Kit()\n\t    local Module = vape.Modules and vape.Modules.LongJump\n\t    return Module and not Module.Enabled and Module.Launch or nil\n\tend\n\t\n\tfunction Leap.Stop()\n\t    local State = Motion and Motion.leap\n\t    if not State then\n\t        return\n\t    end\n\t    Motion.leap, Motion.nextLeap = nil, os.clock() + Tuning.LeapInterval\n\t    for _, v: RBXScriptConnection in State.connections do\n\t        v:Disconnect()\n\t    end\n\tend\n\t\n\tfunction Leap.Range(Kit, Name: string)\n\t    local Speed, Duration = Kit.Scaled(Name)\n\t    if not Speed then\n\t        return Tuning.RecoilRange\n\t    end\n\t    return Speed * math.min(Duration - Kit.Coast, FlyTime.Value) * Tuning.LeapMargin\n\tend\n\t\n\tfunction Leap.Launcher(Kit)\n\t    local Best, Range = nil, 0\n\t    for Name: string, Method: (...any) -> ...any in Kit.Methods do\n\t        local Item = getItem(Name, nil, true)\n\t        local Recoil: boolean = Kit.Scaled(Name) == nil\n\t        if (Item or store.equippedKit == Name) and (not Recoil or World.self.health >= Tuning.LeapHealth) and Kit.Ready(Name, Item) then\n\t            local Reach: number = Leap.Range(Kit, Name)\n\t            if Reach > Range then\n\t                Best, Range = {name = Name, item = Item, method = Method, recoil = Recoil}, Reach\n\t            end\n\t        end\n\t    end\n\t    return Best, Range\n\tend\n\t\n\tfunction Leap.Sweep(From: Vector3, To: Vector3)\n\t    local Bottom: number = Tuning.KneeHeight - Entity.character.HipHeight\n\t    local Size: Vector3 = Vector3.new(Tuning.HoverWidth, Tuning.HeadHeight - Bottom, Tuning.HoverWidth)\n\t    local Lift: Vector3 = Vector3.new(0, (Bottom + Tuning.HeadHeight) / 2, 0)\n\t    return workspace:Blockcast(CFrame.new(From + Lift), Size, To - From, Senses.Params) == nil\n\tend\n\t\n\tfunction Leap.Spot(Plan, Range: number)\n\t    local Root: BasePart = Entity.character.RootPart\n\t    local HipHeight: number = Entity.character.HipHeight\n\t    local Checked: number = 0\n\t    for i: number = #Plan.Waypoints, Plan.Cursor, -1 do\n\t        local Waypoint = Plan.Waypoints[i]\n\t        local Distance: number = ((Waypoint.Center - Root.Position) * Planar).Magnitude\n\t        if Distance >= Tuning.LeapMinimum and Distance <= Range and not Waypoint.Blocks and Waypoint.Type ~= \"Wait\" then\n\t            Checked += 1\n\t            if Checked > Tuning.LeapChecks then\n\t                return nil\n\t            end\n\t\n\t            local Floor: RaycastResult? = workspace:Raycast(Waypoint.Center + Vector3.new(0, 3, 0), Vector3.new(0, -9, 0), Senses.Params)\n\t            if Floor then\n\t                local Stand: Vector3 = Vector3.new(Waypoint.Center.X, Floor.Position.Y + HipHeight, Waypoint.Center.Z)\n\t                local Cruise: number = math.max(Root.Position.Y, Stand.Y) + Tuning.LeapLift\n\t                local Raised: Vector3 = Vector3.new(Root.Position.X, Cruise, Root.Position.Z)\n\t                local Over: Vector3 = Vector3.new(Stand.X, Cruise, Stand.Z)\n\t                local Landing: Vector3? = if Cruise - Stand.Y <= Tuning.SafeDrop then Touchdown(Stand, Cruise) else nil\n\t                if Landing and Passage(Root.Position, Raised) and Clear(Over, Tuning.HoverWidth) and Leap.Sweep(Raised, Over) then\n\t                    return i, Landing, Cruise\n\t                end\n\t            end\n\t        end\n\t    end\n\t    return nil\n\tend\n\t\n\tfunction Leap.Propel(State, Speed: number, Duration: number)\n\t    local Kit = Leap.Kit()\n\t    if Motion.leap ~= State or State.phase ~= \"arming\" or not Kit or not Entity.isAlive then\n\t        return\n\t    end\n\t    local Root: BasePart = Entity.character.RootPart\n\t    local Point: Vector3 = Vector3.new(Root.Position.X, State.cruise, Root.Position.Z)\n\t    local Over: Vector3 = Vector3.new(State.landing.X, State.cruise, State.landing.Z)\n\t    local Window: number = math.min(Duration - Kit.Coast, FlyTime.Value)\n\t    if Speed * Window < (Over - Point).Magnitude or not Passage(Root.Position, Point) then\n\t        Leap.Stop()\n\t        Report(`long jump boost of {math.floor(Speed)} studs/s cannot reach the landing, walking instead`)\n\t        return\n\t    end\n\t    State.phase, State.speed, State.point, State.over, State.flightEnd = \"flying\", Speed, Point, Over, os.clock() + Window\n\tend\n\t\n\tfunction Leap.Recoil(DamageTable)\n\t    local State, Kit = Motion.leap, Leap.Kit()\n\t    if not State or not State.recoil or not Kit then\n\t        return false\n\t    end\n\t    local Speed, Duration = Kit.Knockback(DamageTable)\n\t    if not Speed then\n\t        return false\n\t    end\n\t    Leap.Propel(State, Speed, Duration)\n\t    return true\n\tend\n\t\n\tfunction Leap.Try(Goal, Plan, Now: number)\n\t    if not LongJump.Enabled or Motion.leap or Now < (Motion.nextLeap or 0) then\n\t        return false\n\t    end\n\t    Motion.nextLeap = Now + Tuning.LeapInterval\n\t    local Kit = Leap.Kit()\n\t    local Root: BasePart = Entity.character.RootPart\n\t    if not Kit or not Senses.Ground(Root.Position) then\n\t        return false\n\t    end\n\t    local Choice, Range = Leap.Launcher(Kit)\n\t    if not Choice then\n\t        return false\n\t    end\n\t    local Index, Landing, Cruise = Leap.Spot(Plan, Range)\n\t    if not Index then\n\t        return false\n\t    end\n\t\n\t    local Heading: Vector3 = ((Landing - Root.Position) * Planar).Unit\n\t    local State = {\n\t        goal = Goal,\n\t        name = Choice.name,\n\t        recoil = Choice.recoil,\n\t        phase = \"arming\",\n\t        heading = Heading,\n\t        anchor = Root.Position,\n\t        landing = Landing,\n\t        cruise = Cruise,\n\t        plan = Plan,\n\t        index = Index,\n\t        deadline = Now + (Choice.recoil and Tuning.LeapFuse or Tuning.LeapArm),\n\t        connections = {}\n\t    }\n\t    Motion.leg, Motion.orbit, Motion.leap = nil, nil, State\n\t    Root.CFrame = CFrame.lookAlong(Root.Position, Heading)\n\t    Root.AssemblyLinearVelocity = Vector3.zero\n\t    Motion.written, Motion.controlledAt = Root.Position, Now\n\t\n\t    task.spawn(Choice.method, Choice.item, Root.Position, Heading, {\n\t        Active = function(): boolean\n\t            return Motion.leap == State\n\t        end,\n\t        Propel = function(_, Speed: number, Duration: number)\n\t            Leap.Propel(State, Speed, Duration)\n\t        end,\n\t        Anchor = function(Position: Vector3)\n\t            State.anchor = Position\n\t        end,\n\t        Clean = function(Connection: RBXScriptConnection)\n\t            table.insert(State.connections, Connection)\n\t        end\n\t    })\n\t    Report(`long jumping {math.floor(((Landing - Root.Position) * Planar).Magnitude)} studs with {Choice.name}`)\n\t    return true\n\tend\n\t\n\tfunction Leap.Step(Now: number, DeltaTime: number)\n\t    local State = Motion.leap\n\t    local Root: BasePart = Entity.character.RootPart\n\t    if State.phase == \"arming\" then\n\t        if Now > State.deadline or Brain.goal ~= State.goal then\n\t            Leap.Stop()\n\t            Report(`long jump with {State.name} did not launch`)\n\t            return\n\t        end\n\t        Root.CFrame = CFrame.lookAlong(State.anchor, State.heading)\n\t        Root.AssemblyLinearVelocity = Vector3.zero\n\t        Motion.written, Motion.controlledAt = Root.Position, Now\n\t        return\n\t    end\n\t\n\t    local Offset: Vector3 = State.over - State.point\n\t    local Next: Vector3 = if Offset.Magnitude > State.speed * DeltaTime then State.point + Offset.Unit * State.speed * DeltaTime else State.over\n\t    local Snapped: boolean = Motion.written ~= nil and (Root.Position - Motion.written).Magnitude > Tuning.LeapSnap\n\t    if Snapped or Now > State.flightEnd + Tuning.LeapGrace or not Clear(Next, Tuning.HoverWidth) then\n\t        Leap.Stop()\n\t        Agent:Invalidate(if Snapped then \"Position corrected by the server during a long jump\" else \"Long jump cut short\")\n\t        Motion.nextLand = 0\n\t        Land(Now)\n\t        return\n\t    end\n\t    State.point = Next\n\t    Root.CFrame = CFrame.lookAlong(Next, State.heading)\n\t    Root.AssemblyLinearVelocity = Vector3.zero\n\t    Motion.written, Motion.controlledAt = Root.Position, Now\n\t    if Next ~= State.over then\n\t        return\n\t    end\n\t\n\t    Leap.Stop()\n\t    local Landing: Vector3? = Touchdown(State.landing, State.cruise)\n\t    if not Landing then\n\t        Agent:Invalidate(\"Long jump landing is blocked\")\n\t        Motion.nextLand = 0\n\t        Land(Now)\n\t        return\n\t    end\n\t    Root.CFrame = CFrame.lookAlong(Landing, State.heading)\n\t    Root.AssemblyLinearVelocity = Vector3.zero\n\t    Motion.written = Root.Position\n\t    if Agent:IsCurrent(State.plan) then\n\t        State.plan.Cursor = State.index + 1\n\t    end\n\t    Report(`long jump with {State.name} landed`)\n\t    Build.Landed(Now)\n\tend\n\t\n\tfunction Flight.Stop()\n\t    local State = Motion and Motion.flight\n\t    if not State then\n\t        return\n\t    end\n\t    Motion.flight, Motion.nextFlight = nil, os.clock() + Tuning.FlightInterval\n\t    if Entity.isAlive then\n\t        local Root: BasePart = Entity.character.RootPart\n\t        Root.AssemblyLinearVelocity = Vector3.new(0, math.max(Root.AssemblyLinearVelocity.Y, -Tuning.FlightSettle), 0)\n\t    end\n\tend\n\t\n\tfunction Flight.Claim(Active: boolean)\n\t    if Active and not vape.MovementOwner then\n\t        vape.MovementOwner = \"AutoWin\"\n\t    elseif not Active and vape.MovementOwner == \"AutoWin\" then\n\t        vape.MovementOwner = nil\n\t    end\n\tend\n\t\n\tfunction Flight.Floor(Point: Vector3, Top: number, Depth: number)\n\t    return workspace:Raycast(Vector3.new(Point.X, Top, Point.Z), Vector3.new(0, -Depth, 0), Senses.Params)\n\tend\n\t\n\tfunction Flight.Inside(Position: Vector3)\n\t    local Walls: number = 0\n\t    for i: number = 0, 7 do\n\t        local Theta: number = i * math.pi / 4\n\t        if workspace:Raycast(Position, Vector3.new(math.cos(Theta), 0, math.sin(Theta)) * Tuning.InsideRange, Senses.Params) then\n\t            Walls += 1\n\t        end\n\t    end\n\t    return Walls >= Tuning.InsideWalls\n\tend\n\t\n\tfunction Flight.Survey(From: Vector3, To: Vector3, Sample: number)\n\t    local Flat: Vector3 = (To - From) * Planar\n\t    local Top: number = math.max(From.Y, To.Y) + Tuning.FlightScan\n\t    local Depth: number = Top - math.min(From.Y, To.Y) + Tuning.FlightScan\n\t    local Highest, Span, Longest = -math.huge, 0, 0\n\t    local Tops: {number | boolean} = {}\n\t    for Distance: number = 0, Flat.Magnitude, Sample do\n\t        local Hit: RaycastResult? = Flight.Floor(From + Flat.Unit * Distance, Top, Depth)\n\t        table.insert(Tops, if Hit then Hit.Position.Y else false)\n\t        if Hit then\n\t            Highest, Span = math.max(Highest, Hit.Position.Y), 0\n\t        else\n\t            Span += Sample\n\t            Longest = math.max(Longest, Span)\n\t        end\n\t    end\n\t    return Tops, Highest, Longest, Flight.Floor(To, Top, Depth)\n\tend\n\t\n\tfunction Flight.Gap(Tops: {number | boolean}, Sample: number, Clearance: number?)\n\t    local Window: number = math.floor(Tuning.FlightLookahead / Sample)\n\t    local Lift: number = Clearance or Tuning.FlightClearance\n\t    local Level, Peak = nil, -math.huge\n\t    local Run, Longest, Worst, Last = 0, 0, 0, 1\n\t    for i: number = 1, #Tops do\n\t        local Ahead: number = -math.huge\n\t        for j: number = i, math.min(i + Window, #Tops) do\n\t            local Other = Tops[j]\n\t            if Other then\n\t                Ahead = math.max(Ahead, Other)\n\t            end\n\t        end\n\t        if Ahead > -math.huge then\n\t            Level = Ahead\n\t        end\n\t        Peak = math.max(Peak, Level or -math.huge)\n\t        local Top = Tops[i]\n\t        if i == 1 or Top and Peak + Lift - Top <= Tuning.SafeDrop then\n\t            Run, Worst, Last, Peak = 0, Longest, i, Level or -math.huge\n\t        else\n\t            Run += Sample\n\t            Longest = math.max(Longest, Run)\n\t        end\n\t    end\n\t    return Worst, Last\n\tend\n\t\n\tfunction Flight.Span()\n\t    return (Tuning.FlightAir - Tuning.FlightRest) * math.max(TravelSpeed(), 1)\n\tend\n\t\n\tfunction Flight.Viable(Candidate, Now: number)\n\t    local From: Vector3 = World.self.position\n\t    local Cached = Routing.surveys[Candidate.key]\n\t    if Cached and Now - Cached.at < Tuning.SurveyLifetime and (Cached.from - From).Magnitude < Tuning.SurveyShift and (Cached.to - Candidate.position).Magnitude < Tuning.SurveyShift then\n\t        return Cached.viable\n\t    end\n\t    local Tops, _, _, Ground = Flight.Survey(From, Candidate.position, Tuning.SurveySample)\n\t    local Viable: boolean = Ground ~= nil and Ground.Position.Y + Entity.character.HipHeight - Candidate.position.Y <= Tuning.SafeDrop + Tuning.PerchMargin and (Flight.Gap(Tops, Tuning.SurveySample)) <= Flight.Span()\n\t    Routing.surveys[Candidate.key] = {at = Now, from = From, to = Candidate.position, viable = Viable}\n\t    return Viable\n\tend\n\t\n\tfunction Flight.Grounded(Goal, Now: number)\n\t    local State = {at = Now, distance = ((Goal.position - Entity.character.RootPart.Position) * Planar).Magnitude}\n\t    Routing.flightless[Goal.key] = State\n\t    if Goal.approach then\n\t        Routing.flightless[Goal.approach] = State\n\t    end\n\tend\n\t\n\tfunction Flight.Barred(Candidate, Now: number)\n\t    for _, Key: string? in {Candidate.key, Candidate.approach} do\n\t        local State = Key and Routing.flightless[Key]\n\t        if State and Now - State.at <= Tuning.FlightMemory and State.distance - ((Candidate.position - Entity.character.RootPart.Position) * Planar).Magnitude < Tuning.FlightMinimum / 2 then\n\t            return true\n\t        end\n\t    end\n\t    return false\n\tend\n\t\n\tfunction Flight.Line(From: Vector3, To: Vector3, Clearance: number?, Limit: number?)\n\t    local HipHeight: number = Entity.character.HipHeight\n\t    local Flat: Vector3 = (To - From) * Planar\n\t    if Flat.Magnitude < 1 then\n\t        return nil\n\t    end\n\t    local Tops, Highest, Longest, Ground = Flight.Survey(From, To, Tuning.FlightSample)\n\t    local Gap, Last = Flight.Gap(Tops, Tuning.FlightSample, Clearance)\n\t    if not Ground or Ground.Position.Y + HipHeight - To.Y > Tuning.SafeDrop + Tuning.PerchMargin or Gap > (Limit or Flight.Span()) then\n\t        return nil\n\t    end\n\t    local Floor: number = Ground.Position.Y\n\t    if Last < #Tops and not Limit then\n\t        local Length: number = (Last - 1) * Tuning.FlightSample\n\t        local Perch = Tops[Last]\n\t        if Length < Tuning.FlightMinimum / 2 or not Perch or Perch - Floor > Tuning.SafeDrop + Tuning.PerchMargin then\n\t            return nil\n\t        end\n\t        To, Floor, Highest = From + Flat.Unit * Length, Perch, -math.huge\n\t        for i: number = #Tops, Last + 1, -1 do\n\t            table.remove(Tops, i)\n\t        end\n\t        for _, Top in Tops do\n\t            if Top then\n\t                Highest = math.max(Highest, Top)\n\t            end\n\t        end\n\t    end\n\t\n\t    local Stand: Vector3 = Vector3.new(To.X, Floor + HipHeight, To.Z)\n\t    local Cruise: number = math.max(Highest + HipHeight + (Clearance or Tuning.FlightClearance), From.Y, Stand.Y)\n\t    for _ = 0, Tuning.FlightRaises do\n\t        local Raised: Vector3 = Vector3.new(From.X, Cruise, From.Z)\n\t        local Over: Vector3 = Vector3.new(Stand.X, Cruise, Stand.Z)\n\t        local Landing: Vector3? = Touchdown(Stand, Cruise)\n\t        if Landing and Passage(From, Raised) and Leap.Sweep(Raised, Over) and Passage(Over, Landing) then\n\t            return {cruise = Cruise, landing = Landing, span = Longest, tops = Tops, origin = From, heading = Flat.Unit}\n\t        end\n\t        Cruise += Tuning.FlightRaise\n\t    end\n\t    return nil\n\tend\n\t\n\tfunction Flight.Adopt(State, Line)\n\t    State.cruise, State.landing, State.tops, State.origin, State.heading = Line.cruise, Line.landing, Line.tops, Line.origin, Line.heading\n\t    return State\n\tend\n\t\n\tfunction Flight.Level(State, Position: Vector3)\n\t    local Along: number = ((Position - State.origin) * Planar):Dot(State.heading)\n\t    local First: number = math.clamp(math.floor(Along / Tuning.FlightSample) + 1, 1, #State.tops)\n\t    local Last: number = math.clamp(math.floor((Along + Tuning.FlightLookahead) / Tuning.FlightSample) + 1, 1, #State.tops)\n\t    local Highest: number? = nil\n\t    for i: number = First, Last do\n\t        local Top = State.tops[i]\n\t        if Top then\n\t            Highest = math.max(Highest or -math.huge, Top)\n\t        end\n\t    end\n\t    if Highest then\n\t        State.level = Highest + Entity.character.HipHeight + (State.clearance or Tuning.FlightClearance)\n\t    end\n\t    return State.level\n\tend\n\t\n\tfunction Flight.Exposure(State, Position: Vector3)\n\t    local Tops = State.tops\n\t    if #Tops == 0 then\n\t        return 0\n\t    end\n\t    local Along: number = ((Position - State.origin) * Planar):Dot(State.heading)\n\t    local Window: number = math.floor(Tuning.FlightLookahead / Tuning.FlightSample)\n\t    local Lift: number = State.clearance or Tuning.FlightClearance\n\t    local Peak: number = State.apex - Entity.character.HipHeight - Lift\n\t    local Run: number = 0\n\t    for i: number = math.max(math.floor(Along / Tuning.FlightSample) + 2, 1), #Tops do\n\t        local Top = Tops[i]\n\t        local Highest: number = Peak\n\t        for j: number = i, math.min(i + Window, #Tops) do\n\t            local Other = Tops[j]\n\t            if Other then\n\t                Highest = math.max(Highest, Other)\n\t            end\n\t        end\n\t        if Top and Highest + Lift - Top <= Tuning.SafeDrop then\n\t            break\n\t        end\n\t        Run += Tuning.FlightSample\n\t    end\n\t    return Run\n\tend\n\t\n\tfunction Flight.Launch(Goal, Line, Now: number, Extra)\n\t    local Root: BasePart = Entity.character.RootPart\n\t    local Distance: number = ((Line.landing - Root.Position) * Planar).Magnitude\n\t    Motion.leg, Motion.commit, Motion.orbit, Motion.glide = nil, nil, nil, nil\n\t    local State = Flight.Adopt({\n\t        goal = Goal,\n\t        target = Line.landing,\n\t        phase = \"cruise\",\n\t        grounded = Now,\n\t        apex = Root.Position.Y,\n\t        last = Root.Position,\n\t        lineAt = Now,\n\t        level = Root.Position.Y,\n\t        label = Goal and Goal.label or \"safe ground\",\n\t        deadline = Now + Distance / math.max(TravelSpeed(), 1) * 1.5 + Tuning.FlightSlack\n\t    }, Line)\n\t    for Key: string, v: any in Extra or {} do\n\t        State[Key] = v\n\t    end\n\t    Motion.flight, Motion.controlledAt = State, Now\n\t    return State\n\tend\n\t\n\tfunction Flight.Try(Goal, Position: Vector3, Now: number)\n\t    if not SkyTravel.Enabled or Motion.flight or Motion.leap or Now < (Motion.nextFlight or 0) or Flight.Barred(Goal, Now) then\n\t        return false\n\t    end\n\t    local Root: BasePart = Entity.character.RootPart\n\t    if not Senses.Ground(Root.Position) then\n\t        return false\n\t    end\n\t    local Distance: number = ((Position - Root.Position) * Planar).Magnitude\n\t    if Distance < Tuning.FlightMinimum then\n\t        return false\n\t    end\n\t    Motion.nextFlight = Now + Tuning.FlightInterval\n\t    if Flight.Inside(Root.Position) then\n\t        return false\n\t    end\n\t    local Line = Flight.Line(Root.Position, Position)\n\t    if not Line then\n\t        Flight.Grounded(Goal, Now)\n\t        return false\n\t    end\n\t\n\t    Routing.flightless[Goal.key] = nil\n\t    if Goal.approach then\n\t        Routing.flightless[Goal.approach] = nil\n\t    end\n\t    CancelRoute()\n\t    Flight.Launch(Goal, Line, Now, {target = Position, phase = \"ground\", height = Root.Position.Y, resume = Now + Tuning.FlightRest})\n\t    Report(`flying {math.floor(Distance)} studs to {Goal.label}, cruising {math.floor(Line.cruise - Root.Position.Y)} studs up`)\n\t    return true\n\tend\n\t\n\tfunction Flight.Ground(Origin: Vector3, Toward: Vector3?, Below: number?, Range: number, Rise: number)\n\t    local HipHeight: number = Entity.character.HipHeight\n\t    for Radius: number = Tuning.GroundStep, Range, Tuning.GroundStep do\n\t        local Best, Score = nil, math.huge\n\t        local Count: number = math.max(math.floor(2 * math.pi * Radius / Tuning.GroundStep), 8)\n\t        for i: number = 0, Count - 1 do\n\t            local Theta: number = 2 * math.pi * i / Count\n\t            local Point: Vector3 = Origin + Vector3.new(math.cos(Theta), 0, math.sin(Theta)) * Radius\n\t            local Floor: RaycastResult? = Flight.Floor(Point, Origin.Y + Rise, Rise + Tuning.SkyDrop + Tuning.FlightScan)\n\t            if Floor and Floor.Normal.Y > 0.65 and (not Below or Floor.Position.Y <= Below) then\n\t                local Stand: Vector3 = Vector3.new(Point.X, Floor.Position.Y + HipHeight, Point.Z)\n\t                local Distance: number = if Toward then ((Toward - Stand) * Planar).Magnitude else 0\n\t                if Distance < Score and Clear(Stand) and not Senses.Surface(Stand).nearVoid then\n\t                    Best, Score = Stand, Distance\n\t                end\n\t            end\n\t        end\n\t        if Best then\n\t            return Best\n\t        end\n\t    end\n\t    return nil\n\tend\n\t\n\tfunction Flight.Down(Goal, Now: number)\n\t    if Motion.flight or Motion.leap or Now < (Motion.nextDescent or 0) then\n\t        return false\n\t    end\n\t    Motion.nextDescent = Now + Tuning.RescueInterval\n\t    local Root: BasePart = Entity.character.RootPart\n\t    local Feet: number = Root.Position.Y - Entity.character.HipHeight\n\t    if not Senses.Ground(Root.Position) or not Goal.position or Goal.position.Y >= Feet then\n\t        return false\n\t    end\n\t    local Stand: Vector3? = Flight.Ground(Root.Position, Goal.position, Feet - Tuning.SafeDrop, Tuning.DescendRange, Tuning.PassageStep)\n\t    local Line = Stand and Flight.Line(Root.Position, Stand, Tuning.DescendClearance, Tuning.FlightVoidSpan)\n\t    if not Line then\n\t        return false\n\t    end\n\t\n\t    CancelRoute()\n\t    Flight.Launch(Goal, Line, Now, {fixed = true, clearance = Tuning.DescendClearance})\n\t    Report(`no route down, flying {math.floor(Root.Position.Y - Line.landing.Y)} studs down toward {Goal.label}`)\n\t    return true\n\tend\n\t\n\tfunction Flight.Rescue(Now: number)\n\t    if Motion.flight or Now < (Motion.nextRescue or 0) then\n\t        return false\n\t    end\n\t    Motion.nextRescue = Now + Tuning.RescueInterval\n\t    local Root: BasePart = Entity.character.RootPart\n\t    if workspace:Raycast(Root.Position, Vector3.new(0, -Tuning.SkyDrop, 0), Senses.Params) then\n\t        return false\n\t    end\n\t    local Safe: Vector3? = World.self.safe\n\t    local Stand: Vector3? = if Safe and ((Safe - Root.Position) * Planar).Magnitude <= Tuning.FlightVoidSpan then Safe else Flight.Ground(Root.Position, nil, nil, Tuning.FlightVoidSpan, Tuning.EscapeHeight)\n\t    local Line = Stand and Flight.Line(Root.Position, Stand, Tuning.DescendClearance, Tuning.FlightVoidSpan)\n\t    if not Line then\n\t        return false\n\t    end\n\t\n\t    CancelRoute()\n\t    Flight.Launch(Brain.goal, Line, Now, {fixed = true, rescue = true, clearance = Tuning.DescendClearance, label = \"safe ground\"})\n\t    Agent:Invalidate(\"Flying back to safe ground\")\n\t    Report(`stranded over the void, flying {math.floor(((Line.landing - Root.Position) * Planar).Magnitude)} studs back to safe ground`)\n\t    return true\n\tend\n\t\n\tfunction Flight.Abort(Now: number, Reason: string)\n\t    Flight.Stop()\n\t    Agent:Invalidate(Reason)\n\t    Report(`flight stopped: {Reason}`)\n\t    Motion.nextLand = 0\n\t    Land(Now)\n\tend\n\t\n\tfunction Flight.Touch(State, Now: number)\n\t    local Root: BasePart = Entity.character.RootPart\n\t    local HipHeight: number = Entity.character.HipHeight\n\t    local Floor: RaycastResult? = workspace:Raycast(Root.Position, Vector3.new(0, -(Tuning.SafeDrop + HipHeight), 0), Senses.Params)\n\t    local Stand: Vector3? = Floor and Touchdown(Vector3.new(Root.Position.X, Floor.Position.Y + HipHeight, Root.Position.Z), Root.Position.Y)\n\t    if not Stand or math.max(Root.Position.Y, State.apex or Root.Position.Y) - Stand.Y > Tuning.SafeDrop then\n\t        return false\n\t    end\n\t    State.phase, State.height, State.resume = \"touch\", Root.Position.Y, Now + Tuning.FlightTouch\n\t    Root.CFrame = CFrame.new(Stand) * Root.CFrame.Rotation\n\t    Root.AssemblyLinearVelocity = Vector3.zero\n\t    Motion.written = Root.Position\n\t    return true\n\tend\n\t\n\tfunction Flight.Landed(State, Now: number)\n\t    local Root: BasePart = Entity.character.RootPart\n\t    if State.goal and ((State.target - State.landing) * Planar).Magnitude > Tuning.FlightArrive then\n\t        Flight.Grounded(State.goal, Now)\n\t    end\n\t    Flight.Stop()\n\t    Root.AssemblyLinearVelocity = Vector3.zero\n\t    Agent:Invalidate(\"Landed after flying\")\n\t    Report(`flight landed at {State.label}`)\n\t    Build.Landed(Now)\n\tend\n\t\n\tfunction Flight.Step(Now: number, DeltaTime: number)\n\t    local State = Motion.flight\n\t    local Root: BasePart = Entity.character.RootPart\n\t    local Position: Vector3 = Root.Position\n\t    Motion.controlledAt = Now\n\t    if State.phase == \"touch\" or State.phase == \"ground\" then\n\t        if State.phase == \"ground\" and not Senses.Ground(Position) then\n\t            Flight.Abort(Now, \"Lost support before takeoff\")\n\t            return\n\t        end\n\t        Root.AssemblyLinearVelocity = Vector3.zero\n\t        if Now < State.resume then\n\t            return\n\t        end\n\t        local Back: Vector3 = Vector3.new(Position.X, State.height, Position.Z)\n\t        if Passage(Position, Back) then\n\t            Root.CFrame = CFrame.new(Back) * Root.CFrame.Rotation\n\t        end\n\t        State.phase, State.grounded, State.last, State.apex = \"cruise\", Now, Root.Position, Root.Position.Y\n\t        return\n\t    end\n\t\n\t    State.apex = math.max(State.apex or Position.Y, Position.Y)\n\t    if ((Position - State.last) * Planar).Magnitude > TravelSpeed() * DeltaTime + Tuning.FlightSnap then\n\t        Flight.Abort(Now, \"Position corrected by the server during a flight\")\n\t        return\n\t    elseif Now > State.deadline then\n\t        Flight.Abort(Now, \"Flight took too long\")\n\t        return\n\t    elseif not State.rescue and Now - State.grounded > Tuning.FlightAir and ((State.landing - Position) * Planar).Magnitude > Tuning.FlightArrive and not Senses.Ground(Position) then\n\t        Flight.Abort(Now, \"Flight ran out of air time without a safe touchdown\")\n\t        return\n\t    end\n\t\n\t    if not State.fixed then\n\t        local Goal = Brain.goal\n\t        local Target: Vector3? = Goal and Goal.position\n\t        if not Target then\n\t            Flight.Abort(Now, \"Flight lost its objective\")\n\t            return\n\t        end\n\t        if Goal.record and ((Target - Position) * Planar).Magnitude <= Reach() then\n\t            Flight.Stop()\n\t            return\n\t        end\n\t        if Goal ~= State.goal or (Target - State.target).Magnitude > Tuning.FlightDrift and Now - State.lineAt >= Tuning.FlightRetarget then\n\t            State.goal, State.lineAt, State.label = Goal, Now, Goal.label\n\t            local Line = Flight.Line(Position, Target)\n\t            if Line then\n\t                State.target = Target\n\t                Flight.Adopt(State, Line)\n\t                State.deadline = math.max(State.deadline, Now + ((Target - Position) * Planar).Magnitude / math.max(TravelSpeed(), 1) * 1.5 + Tuning.FlightSlack)\n\t            elseif (Target - State.target).Magnitude > Tuning.FlightMinimum then\n\t                Flight.Abort(Now, \"Flight objective moved out of reach\")\n\t                return\n\t            end\n\t        end\n\t    end\n\t\n\t    local Landing: Vector3 = State.landing\n\t    local Flat: Vector3 = (Landing - Position) * Planar\n\t    local Over: boolean = Flat.Magnitude <= Tuning.FlightArrive\n\t    if Senses.Ground(Position) then\n\t        State.grounded = Now\n\t        if Over and math.abs(Position.Y - Landing.Y) <= 3 then\n\t            Flight.Landed(State, Now)\n\t            return\n\t        end\n\t    end\n\t    local Speed: number = TravelSpeed()\n\t    local Ahead: Vector3 = Position + State.heading * (Tuning.FlightSample + Speed * DeltaTime)\n\t    local Aloft: number = Now - State.grounded\n\t    if not Over and Aloft > Tuning.FlightRest and (Aloft > Tuning.FlightHold or Aloft + Flight.Exposure(State, Ahead) / math.max(Speed, 1) > Tuning.FlightAir - Tuning.FlightRest) and Flight.Touch(State, Now) then\n\t        return\n\t    end\n\t\n\t    local Horizontal: Vector3 = if Over then Flat * math.min(Tuning.FlightSpring, 1 / math.max(DeltaTime, 0.001)) else Flat.Unit * Speed\n\t    local Vertical: number = math.clamp(((if Over then Landing.Y else Flight.Level(State, Position)) - Position.Y) * Tuning.FlightSpring, -Tuning.FlightDescent, Tuning.FlightLaunch)\n\t    if Over and Position.Y - Landing.Y < Tuning.FlightClearance then\n\t        Vertical = math.max(Vertical, -Tuning.FlightSettle)\n\t    end\n\t    if State.blocked and (Position - State.blockedPosition).Magnitude >= Tuning.StuckDistance then\n\t        State.blocked, State.blockedPosition = nil, nil\n\t    end\n\t    if not Clear(Position + (Horizontal + Vector3.new(0, Vertical, 0)) * DeltaTime, Tuning.HoverWidth) then\n\t        Horizontal, Vertical = Vector3.zero, if Over then 0 else math.max(Vertical, Tuning.FlightSettle)\n\t        local Rising: boolean = Vertical > 0 and Position.Y < State.cruise + Tuning.FlightRaise and Clear(Position + Vector3.new(0, Vertical * DeltaTime, 0), Tuning.HoverWidth)\n\t        if not Rising then\n\t            Vertical = 0\n\t        end\n\t        State.blocked, State.blockedPosition = State.blocked or Now, State.blockedPosition or Position\n\t    end\n\t    if State.blocked and Now - State.blocked > 1 then\n\t        if State.goal then\n\t            Flight.Grounded(State.goal, Now)\n\t        end\n\t        Flight.Abort(Now, \"Flight path is blocked\")\n\t        return\n\t    end\n\t    if Horizontal.Magnitude > 0.01 then\n\t        Root.CFrame += Horizontal * DeltaTime\n\t    end\n\t    Root.AssemblyLinearVelocity = Vector3.new(0, Vertical, 0)\n\t    State.last, Motion.velocity = Root.Position, Horizontal\n\tend\n\t\n\tlocal function Pillar(Now: number, Levels: number, Reason: string?)\n\t    local _, Amount = getWool()\n\t    if Motion.pillar or not Amount or Amount < 2 then\n\t        return false\n\t    end\n\t    local Root: BasePart = Entity.character.RootPart\n\t    if not Build.Allowed(Navigation.WorldToGrid(Root.Position - Vector3.new(0, Entity.character.HipHeight - 1.5, 0))) then\n\t        return false\n\t    end\n\t    local Room: number = math.min(math.floor(Headroom(Root.Position, Levels * 3) / 3), Levels, Amount)\n\t    if Room < 2 then\n\t        return false\n\t    end\n\t\n\t    Motion.pillar = {remaining = Room, deadline = Now + Room + 2}\n\t    Motion.leg, Motion.orbit, Motion.raisedAt = nil, nil, Now\n\t    Agent:Invalidate(\"Pillaring up\")\n\t    Report(Reason or `pillaring {Room} blocks up to break contact`)\n\t    return true\n\tend\n\t\n\tlocal function StepPillar(Now: number)\n\t    local State = Motion.pillar\n\t    local Root: BasePart = Entity.character.RootPart\n\t    if State.grid then\n\t        if Senses.Block(State.grid) then\n\t            State.grid = nil\n\t        elseif Now - State.placed > Tuning.PillarConfirm then\n\t            Motion.pillar = nil\n\t            Brain.failure = \"Pillar block was not confirmed\"\n\t            return\n\t        end\n\t    end\n\t    if State.hold then\n\t        Root.CFrame = CFrame.new(State.hold) * Root.CFrame.Rotation\n\t        Root.AssemblyLinearVelocity = Vector3.zero\n\t        Motion.written, Motion.controlledAt = Root.Position, Now\n\t    end\n\t    if State.grid then\n\t        return\n\t    end\n\t    if State.remaining <= 0 or Now > State.deadline then\n\t        Motion.pillar = nil\n\t        return\n\t    end\n\t\n\t    local Wool = getWool()\n\t    if not Wool then\n\t        Motion.pillar = nil\n\t        return\n\t    end\n\t    if workspace:GetServerTimeNow() < Motion.nextPlace then\n\t        return\n\t    end\n\t    local Feet: Vector3 = Navigation.WorldToGrid(Root.Position - Vector3.new(0, Entity.character.HipHeight - 1.5, 0))\n\t    if not Build.Allowed(Feet) then\n\t        Motion.pillar = nil\n\t        Brain.failure = \"Pillar placement is not allowed here\"\n\t        return\n\t    end\n\t    if not Passage(Root.Position, Root.Position + Vector3.new(0, 3, 0)) then\n\t        Motion.pillar = nil\n\t        Brain.failure = \"Pillar blocked above\"\n\t        return\n\t    end\n\t    State.hold = Root.Position + Vector3.new(0, 3, 0)\n\t    Root.CFrame = CFrame.new(State.hold) * Root.CFrame.Rotation\n\t    Root.AssemblyLinearVelocity = Vector3.zero\n\t    State.grid, State.placed, State.remaining = Feet, Now, State.remaining - 1\n\t    Motion.nextPlace = workspace:GetServerTimeNow() + 1 / (bedwars.SharedConstants.BLOCK_PLACE_CPS or 12)\n\t    Motion.written, Motion.controlledAt = Root.Position, Now\n\t    task.spawn(bedwars.placeBlock, Feet * 3, Wool, false)\n\tend\n\t\n\tlocal function Sniped(Now: number)\n\t    for _, v: any in World.enemies do\n\t        if v.alive and Now - (v.shotAt or -math.huge) < Tuning.SnipeMemory then\n\t            return true\n\t        end\n\t    end\n\t    return false\n\tend\n\t\n\tlocal function Aimed(Event)\n\t    local Shooter: Player? = Event.shooter and Players:GetPlayerFromCharacter(Event.shooter)\n\t    local Record = Shooter and World.enemies[tostring(Shooter.UserId)]\n\t    if not Record or not Entity.isAlive or typeof(Event.origin) ~= \"Vector3\" or typeof(Event.launchVelocity) ~= \"Vector3\" then\n\t        return\n\t    end\n\t    local Offset: Vector3 = (Entity.character.RootPart.Position - Event.origin) * Planar\n\t    local Heading: Vector3 = Event.launchVelocity * Planar\n\t    if Offset.Magnitude > Tuning.SnipeRange and Heading.Magnitude > 1 and Heading.Unit:Dot(Offset.Unit) >= Tuning.AimCone then\n\t        Record.aimedAt = os.clock()\n\t    end\n\tend\n\t\n\tlocal function Skyward(Now: number)\n\t    if World.self.health < Tuning.SkyHealth or Sniped(Now) or Now < (Motion.nextSky or 0) then\n\t        return false\n\t    end\n\t    local Root: BasePart = Entity.character.RootPart\n\t    local Height: number = Headroom(Root.Position, Tuning.SkyHeight)\n\t    if Height < Tuning.SkyMinimum then\n\t        Motion.nextSky = Now + Tuning.SkyRetry\n\t        return false\n\t    end\n\t    local Hover: Vector3 = Root.Position + Vector3.new(0, Height, 0)\n\t    Motion.leg, Motion.orbit, Motion.commit = nil, nil, nil\n\t    Motion.sky = {hover = Hover, lift = Height, deadline = Now + Tuning.SkyHold, resting = false}\n\t    Root.CFrame = CFrame.new(Hover) * Root.CFrame.Rotation\n\t    Root.AssemblyLinearVelocity = Vector3.zero\n\t    Motion.written, Motion.controlledAt = Root.Position, Now\n\t    Agent:Invalidate(\"Escaped upward\")\n\t    Report(`escaping {math.floor(Height)} studs straight up`)\n\t    return true\n\tend\n\t\n\tlocal function StepSky(Now: number, DeltaTime: number)\n\t    local State = Motion.sky\n\t    local Root: BasePart = Entity.character.RootPart\n\t    local HipHeight: number = Entity.character.HipHeight\n\t    local Threats = ThreatPositions(Tuning.SkyWatch)\n\t    if State.resting then\n\t        Motion.controlledAt = Now\n\t        if Now < State.deadline then\n\t            return\n\t        end\n\t        local Chased: boolean = false\n\t        for _, v: Vector3 in Threats do\n\t            Chased = Chased or ((v - Root.Position) * Planar).Magnitude <= Tuning.SkyClear\n\t        end\n\t        if not Chased or not Skyward(Now) then\n\t            Motion.sky = nil\n\t            Agent:Invalidate(\"Landed after escaping upward\")\n\t        end\n\t        return\n\t    end\n\t\n\t    local Clearance: number = Tuning.SkyLand\n\t    for _, v: any in World.enemies do\n\t        if v.alive and (LivePosition(v) - Root.Position).Magnitude <= Tuning.SkyWatch then\n\t            Clearance = math.max(Clearance, (v.reach or 0) + Tuning.ContestMargin)\n\t        end\n\t    end\n\t    local function Crowded(Point: Vector3)\n\t        for _, v: Vector3 in Threats do\n\t            if ((v - Point) * Planar).Magnitude <= Clearance then\n\t                return true\n\t            end\n\t        end\n\t        return false\n\t    end\n\t\n\t    local Sum, Count = Vector3.zero, 0\n\t    for _, v: Vector3 in Threats do\n\t        Sum += v\n\t        Count += 1\n\t    end\n\t    local Away: Vector3 = Count > 0 and (State.hover - Sum / Count) * Planar or Vector3.zero\n\t    if Away.Magnitude > 0.1 then\n\t        local Heading: Vector3 = Away.Unit\n\t        for _, Angle: number in Tuning.CoastAngles do\n\t            local Theta: number = math.rad(Angle * (State.side or 1))\n\t            local Direction: Vector3 = Vector3.new(Heading.X * math.cos(Theta) - Heading.Z * math.sin(Theta), 0, Heading.X * math.sin(Theta) + Heading.Z * math.cos(Theta))\n\t            local Next: Vector3 = State.hover + Direction * TravelSpeed() * DeltaTime\n\t            local Below: RaycastResult? = workspace:Raycast(Next, Vector3.new(0, -(State.lift + Tuning.SkyDrop), 0), Senses.Params)\n\t            if Below and Next.Y - Below.Position.Y - HipHeight <= State.lift + Tuning.PassageStep and Clear(Next, Tuning.HoverWidth) then\n\t                if Angle ~= 0 then\n\t                    State.side = (State.side or 1) * math.sign(Angle)\n\t                end\n\t                State.hover = Next\n\t                break\n\t            end\n\t        end\n\t    end\n\t    Root.CFrame = CFrame.new(State.hover) * Root.CFrame.Rotation\n\t    Root.AssemblyLinearVelocity = Vector3.zero\n\t    Motion.written, Motion.controlledAt = Root.Position, Now\n\t\n\t    local Forced: boolean = Now >= State.deadline + Tuning.SkyGrace\n\t    if Now >= State.deadline and (Forced or not Crowded(State.hover)) then\n\t        local Floor: RaycastResult? = workspace:Raycast(State.hover, Vector3.new(0, -(State.lift + Tuning.SkyDrop), 0), Senses.Params)\n\t        local Stand: Vector3? = Floor and Touchdown(Vector3.new(State.hover.X, Floor.Position.Y + HipHeight, State.hover.Z), State.hover.Y)\n\t        if Stand then\n\t            Root.CFrame = CFrame.new(Stand) * Root.CFrame.Rotation\n\t            Root.AssemblyLinearVelocity = Vector3.zero\n\t            Motion.written = Root.Position\n\t            State.resting, State.deadline = true, Now + Tuning.SkyRest\n\t            if Crowded(Root.Position) and Pillar(Now, Tuning.PillarHeight) then\n\t                Motion.sky = nil\n\t            end\n\t        elseif Forced then\n\t            Motion.sky = nil\n\t            Land(Now)\n\t        end\n\t    end\n\tend\n\t\n\tfunction Build.Allowed(Grid: Vector3)\n\t    if LocalPlayer:GetAttribute(\"DenyBlockPlace\") then\n\t        return false\n\t    end\n\t    local Map = bedwars.MapController\n\t    if not Map then\n\t        return true\n\t    end\n\t    local Checked, Denied = pcall(Map.isInDenyRegion, Map, Grid)\n\t    if Checked and Denied then\n\t        return false\n\t    end\n\t    Checked, Denied = pcall(Map.isOutOfBounds, Map, Grid)\n\t    return not (Checked and Denied)\n\tend\n\t\n\tfunction Build.Wall(Stand: Vector3, Shooter: Vector3)\n\t    local Flat: Vector3 = (Shooter - Stand) * Planar\n\t    if Flat.Magnitude < 1 then\n\t        return nil\n\t    end\n\t    local Feet: Vector3 = Navigation.WorldToGrid(Stand - Vector3.new(0, Entity.character.HipHeight - 1.5, 0))\n\t    local Forward: Vector3 = math.abs(Flat.X) > math.abs(Flat.Z) and Vector3.new(math.sign(Flat.X), 0, 0) or Vector3.new(0, 0, math.sign(Flat.Z))\n\t    local Side: Vector3 = Vector3.new(Forward.Z, 0, Forward.X)\n\t    local Height: number = if Shooter.Y - Stand.Y > Tuning.WallRaise then 3 else 2\n\t    local Cells: {Vector3} = {}\n\t    for Y: number = 0, Height - 1 do\n\t        for Offset: number = -1, 1 do\n\t            table.insert(Cells, Feet + Forward + Side * Offset + Vector3.new(0, Y, 0))\n\t        end\n\t    end\n\t    return Cells\n\tend\n\t\n\tfunction Build.Open(Cells: {Vector3})\n\t    for _, Grid: Vector3 in Cells do\n\t        if not Senses.Block(Grid) and not (Navigation.World and Navigation.World:Solid(Grid.X, Grid.Y, Grid.Z)) and not Build.Allowed(Grid) then\n\t            return false\n\t        end\n\t    end\n\t    return true\n\tend\n\t\n\tfunction Build.Spot(Origin: Vector3, Shooter: Vector3)\n\t    local HipHeight: number = Entity.character.HipHeight\n\t    for _, Ring: number in Tuning.WallRings do\n\t        local Count: number = math.max(math.floor(2 * math.pi * Ring / Tuning.ShelterSpacing), 8)\n\t        for i: number = 0, Count - 1 do\n\t            local Theta: number = 2 * math.pi * i / Count\n\t            local Point: Vector3 = Origin + Vector3.new(math.cos(Theta), 0, math.sin(Theta)) * Ring\n\t            local Floor: RaycastResult? = workspace:Raycast(Point + Vector3.new(0, Tuning.ShelterStep, 0), Vector3.new(0, -2 * Tuning.ShelterStep - HipHeight, 0), Senses.Params)\n\t            local Stand: Vector3? = Floor and Vector3.new(Point.X, Floor.Position.Y + HipHeight, Point.Z)\n\t            local Cells = Stand and Build.Wall(Stand, Shooter)\n\t            if Cells and Clear(Stand) and not Senses.Surface(Stand).nearVoid and Build.Open(Cells) and Direct(Origin, Stand) then\n\t                return Stand, Cells\n\t            end\n\t        end\n\t    end\n\t    return nil\n\tend\n\t\n\tfunction Build.Barricade(Shooter: Vector3, Now: number)\n\t    if Motion.barricade or Now < (Motion.barricadeAt or 0) or not getWool() then\n\t        return false\n\t    end\n\t    local Root: BasePart = Entity.character.RootPart\n\t    if not Senses.Ground(Root.Position) then\n\t        return false\n\t    end\n\t    local Stand: Vector3? = Root.Position\n\t    local Cells = Build.Wall(Root.Position, Shooter)\n\t    if not Cells then\n\t        return false\n\t    end\n\t    local Moved: boolean = not Build.Open(Cells)\n\t    if Moved then\n\t        Stand, Cells = Build.Spot(Root.Position, Shooter)\n\t        if not Stand then\n\t            Motion.barricadeAt = Now + Tuning.BarricadeCooldown\n\t            Report(\"the map does not allow a wall against the archer anywhere close\")\n\t            return false\n\t        end\n\t    end\n\t\n\t    local Travel: number = ((Stand - Root.Position) * Planar).Magnitude\n\t    Motion.barricade = {cells = Cells, next = 1, stand = if Moved then Stand else nil, deadline = Now + Tuning.BarricadeTime + Travel / math.max(TravelSpeed(), 1)}\n\t    Motion.barricadeAt = Now + Tuning.BarricadeCooldown\n\t    Report(`walling off an archer {math.floor(((Shooter - Stand) * Planar).Magnitude)} studs away, {#Cells // 3} blocks high{if Moved then `, {math.floor(Travel)} studs over where the map allows building` else \"\"}`)\n\t    return true\n\tend\n\t\n\tfunction Build.Walk(Now: number, DeltaTime: number)\n\t    local State = Motion.barricade\n\t    local Root: BasePart = Entity.character.RootPart\n\t    if Now > State.deadline then\n\t        Motion.barricade = nil\n\t    elseif ((State.stand - Root.Position) * Planar).Magnitude <= Tuning.WallArrive then\n\t        State.stand = nil\n\t        Hold(Now, DeltaTime)\n\t    elseif not Coast(State.stand, Now, DeltaTime) then\n\t        Motion.barricade = nil\n\t    end\n\tend\n\t\n\tfunction Build.StepBarricade(Now: number)\n\t    local State = Motion.barricade\n\t    if Now > State.deadline or State.next > #State.cells then\n\t        Motion.barricade = nil\n\t        return\n\t    end\n\t    if State.stand or workspace:GetServerTimeNow() < Motion.nextPlace then\n\t        return\n\t    end\n\t    local Wool = getWool()\n\t    if not Wool then\n\t        Motion.barricade = nil\n\t        return\n\t    end\n\t    while State.next <= #State.cells do\n\t        local Grid: Vector3 = State.cells[State.next]\n\t        State.next += 1\n\t        if not Senses.Block(Grid) and not (Navigation.World and Navigation.World:Solid(Grid.X, Grid.Y, Grid.Z)) then\n\t            Motion.nextPlace = workspace:GetServerTimeNow() + 1 / (bedwars.SharedConstants.BLOCK_PLACE_CPS or 12)\n\t            task.spawn(bedwars.placeBlock, Grid * 3, Wool, false)\n\t            return\n\t        end\n\t    end\n\tend\n\t\n\tfunction Build.Screen(Now: number)\n\t    if Motion.barricade or Now < (Motion.screenAt or 0) then\n\t        return false\n\t    end\n\t    Motion.screenAt = Now + Tuning.ShelterInterval\n\t    local Root: BasePart = Entity.character.RootPart\n\t    for _, Eye: Vector3 in Sightlines(Now) do\n\t        if Exposed(Root.Position, {Eye}) then\n\t            return Build.Barricade(Eye, Now)\n\t        end\n\t    end\n\t    return false\n\tend\n\t\n\tfunction Build.Archers(Now: number, Range: number)\n\t    local Origin: Vector3 = Entity.character.RootPart.Position\n\t    local Lines: {Vector3} = Sightlines(Now)\n\t    for _, v: any in World.enemies do\n\t        local Position: Vector3? = v.alive and v.ranged and LivePosition(v)\n\t        if Position and (Position - Origin).Magnitude <= Range then\n\t            local Inventory = store.inventories[v.player]\n\t            local Held = Inventory and Inventory.hand and Inventory.hand.tool\n\t            local Meta = Held and bedwars.ItemMeta[Held.Name]\n\t            if not Meta or not Meta.sword then\n\t                table.insert(Lines, Position + Vector3.new(0, Tuning.EyeHeight, 0))\n\t            end\n\t        end\n\t    end\n\t    return Lines\n\tend\n\t\n\tfunction Build.Nearest(Lines: {Vector3})\n\t    local Root: BasePart = Entity.character.RootPart\n\t    local Best, Nearest = nil, math.huge\n\t    for _, Eye: Vector3 in Lines do\n\t        local Distance: number = (Eye - Root.Position).Magnitude\n\t        if Distance < Nearest and Exposed(Root.Position, {Eye}) then\n\t            Best, Nearest = Eye, Distance\n\t        end\n\t    end\n\t    return Best\n\tend\n\t\n\tfunction Build.Landed(Now: number)\n\t    if not Entity.isAlive or Motion.barricade then\n\t        return\n\t    end\n\t    local Best: Vector3? = Build.Nearest(Build.Archers(Now, Tuning.WallWatch))\n\t    if Best then\n\t        Motion.barricadeAt = nil\n\t        Build.Barricade(Best, Now)\n\t    end\n\tend\n\t\n\tfunction Build.Hide(Goal, Archers: {Vector3}, Now: number, DeltaTime: number)\n\t    local Root: BasePart = Entity.character.RootPart\n\t    if Now >= (Goal.shelterAt or 0) then\n\t        Goal.shelterAt = Now + Tuning.ShelterInterval\n\t        Goal.cover = if Exposed(Root.Position, Archers) then Shelter(Root.Position, Tuning.ShelterRange, Archers) else nil\n\t    end\n\t    if Goal.cover and ((Goal.cover - Root.Position) * Planar).Magnitude > Tuning.ShelterArrive and Coast(Goal.cover, Now, DeltaTime) then\n\t        Goal.haven = Root.Position\n\t        return true\n\t    end\n\t    local Eye: Vector3? = Build.Nearest(Archers)\n\t    if Eye and not Motion.barricade and not Build.Barricade(Eye, Now) then\n\t        return false\n\t    end\n\t    Hold(Now, DeltaTime)\n\t    return true\n\tend\n\t\n\tfunction Build.Needed(Bed: Vector3, From: Vector3)\n\t    local Rise: number = Bed.Y - From.Y\n\t    return Rise > 0 and (Bed - From).Magnitude > Tuning.StanceReach and Tuning.StanceReach ^ 2 - Rise ^ 2 < Tuning.TowerGap ^ 2\n\tend\n\t\n\tfunction Build.Height(Bed: Vector3, Stand: Vector3)\n\t    local Across: number = ((Bed - Stand) * Planar).Magnitude\n\t    local Height: number = Bed.Y - math.sqrt(math.max(Tuning.TowerReach ^ 2 - Across ^ 2, 0))\n\t    return math.max(math.ceil((Height - Stand.Y) / 3), 0)\n\tend\n\t\n\tfunction Build.Column(Bed: Vector3, From: Vector3)\n\t    local HipHeight: number = Entity.character.HipHeight\n\t    local Center: Vector3 = Navigation.WorldToGrid(Bed)\n\t    local Best, Score = nil, math.huge\n\t    for X: number = -Tuning.TowerRing, Tuning.TowerRing do\n\t        for Z: number = -Tuning.TowerRing, Tuning.TowerRing do\n\t            if X == 0 and Z == 0 then\n\t                continue\n\t            end\n\t            local Point: Vector3 = (Center + Vector3.new(X, 0, Z)) * 3\n\t            local Floor: RaycastResult? = Flight.Floor(Point, Bed.Y + 3, Bed.Y + 3 - From.Y + Tuning.SafeDrop)\n\t            if not Floor or Floor.Normal.Y < 0.65 then\n\t                continue\n\t            end\n\t            local Stand: Vector3 = Vector3.new(Point.X, Floor.Position.Y + HipHeight, Point.Z)\n\t            local Needed: number = Build.Height(Bed, Stand)\n\t            local Feet: Vector3 = Navigation.WorldToGrid(Stand - Vector3.new(0, HipHeight - 1.5, 0))\n\t            local Usable: boolean = Clear(Stand) and Headroom(Stand, Needed * 3) >= Needed * 3\n\t            for i: number = 0, Needed - 1 do\n\t                Usable = Usable and Build.Allowed(Feet + Vector3.new(0, i, 0))\n\t            end\n\t            local Cost: number = Needed * 3 + ((Stand - From) * Planar).Magnitude * 0.25\n\t            if Usable and Cost < Score then\n\t                Best, Score = {stand = Stand, needed = Needed}, Cost\n\t            end\n\t        end\n\t    end\n\t    return Best\n\tend\n\t\n\tfunction Build.Tower(Goal, Now: number, DeltaTime: number)\n\t    local Root: BasePart = Entity.character.RootPart\n\t    local Bed: Vector3 = Goal.bed.part.Position\n\t    if (Bed - Root.Position).Magnitude <= Tuning.TowerReach + 1 then\n\t        Goal.subgoal, Goal.towered, Goal.breakAt, Goal.tower = \"BREAK\", true, Now, nil\n\t        Hold(Now, DeltaTime)\n\t        return\n\t    end\n\t    local Tower = Goal.tower\n\t    if not Tower then\n\t        Tower = Build.Column(Bed, Root.Position)\n\t        if not Tower then\n\t            Fail(Goal, Now, \"No room to build a bed tower\")\n\t            return\n\t        end\n\t        Tower.deadline = Now + Tuning.BreakStall\n\t        Goal.tower = Tower\n\t        Report(`bed is out of reach from the ground, building a {Tower.needed} block tower next to it`)\n\t    end\n\t    if Now > Tower.deadline then\n\t        Fail(Goal, Now, \"Bed tower took too long\")\n\t        return\n\t    end\n\t\n\t    local Offset: Vector3 = Tower.stand - Root.Position\n\t    if (Offset * Planar).Magnitude > 1 then\n\t        if Offset.Y > Tuning.PassageStep and (Offset * Planar).Magnitude <= Tuning.TowerGap and Hop(Root.Position, Tower.stand) then\n\t            Root.CFrame = CFrame.new(Tower.stand) * Root.CFrame.Rotation\n\t            Root.AssemblyLinearVelocity = Vector3.zero\n\t            Motion.written, Motion.controlledAt = Root.Position, Now\n\t        else\n\t            Coast(Tower.stand, Now, DeltaTime)\n\t        end\n\t        return\n\t    end\n\t\n\t    local Needed: number = Build.Height(Bed, Root.Position)\n\t    Goal.towers = (Goal.towers or 0) + 1\n\t    if Needed == 0 then\n\t        Goal.subgoal, Goal.towered, Goal.breakAt, Goal.tower = \"BREAK\", true, Now, nil\n\t    elseif Goal.towers > Tuning.TowerRetries or not Pillar(Now, math.max(Needed, 2), `building a {Needed} block bed tower`) then\n\t        Fail(Goal, Now, if getWool() then \"Bed tower could not be built\" else \"Out of blocks for the bed tower\")\n\t    end\n\tend\n\t\n\tlocal function Suffocating(Now: number)\n\t    local Root: BasePart = Entity.character.RootPart\n\t    local HipHeight: number = Entity.character.HipHeight\n\t    local Feet: Vector3 = Navigation.WorldToGrid(Root.Position - Vector3.new(0, HipHeight - 1.5, 0))\n\t    for Y: number = 0, 1 do\n\t        local Cell: Vector3 = Feet + Vector3.new(0, Y, 0)\n\t        Agent.Memory:Route(Cell, \"suffocation\", Now)\n\t        Agent.Memory:Route(Cell, \"suffocation\", Now)\n\t        if Navigation.World then\n\t            Navigation.World:Invalidate(Cell.X, Cell.Y, Cell.Z)\n\t        end\n\t    end\n\t    Agent:Invalidate(\"Suffocating inside geometry\")\n\t    Brain.failure = \"Suffocating inside geometry\"\n\t    Motion.leg, Motion.commit, Motion.orbit, Motion.sky, Motion.glide, Motion.aerial = nil, nil, nil, nil, nil, nil\n\t    Leap.Stop()\n\t    Flight.Stop()\n\t\n\t    local Exit: Vector3? = Ascent(Root.Position)\n\t    if Exit then\n\t        local Lift: number = Exit.Y - Root.Position.Y\n\t        Root.CFrame = CFrame.new(Exit) * Root.CFrame.Rotation\n\t        Root.AssemblyLinearVelocity = Vector3.zero\n\t        Motion.written, Motion.controlledAt = Exit, Now\n\t        Report(`suffocating, rising {math.floor(Lift + 0.5)} studs to open air`)\n\t    elseif not Rise(Now) then\n\t        Pillar(Now, 2)\n\t    end\n\t\n\t    local Goal = Brain.goal\n\t    if Goal then\n\t        RouteFault(Goal, \"Suffocating inside geometry\", Now)\n\t    end\n\tend\n\t\n\tlocal function Clutch()\n\t    local Root: BasePart = Entity.character.RootPart\n\t    local Wool, Amount = getWool()\n\t    if not Navigation.World or workspace:GetServerTimeNow() < Motion.nextPlace then\n\t        return false\n\t    end\n\t\n\t    local Result = Navigation:FindClutch({\n\t        Position = Root.Position, \n\t        Velocity = \n\t        Root.AssemblyLinearVelocity, \n\t        Grounded = false\n\t    }, {\n\t        Channel = \"autowinclutch\",\n\t        Mode = \"Blatant\",\n\t        BlocksAvailable = Amount,\n\t        Clutch = {Void = true}\n\t    })\n\t    if Result.Success and Result.BridgePath[1] then\n\t        Motion.nextPlace = workspace:GetServerTimeNow() + 1 / (bedwars.SharedConstants.BLOCK_PLACE_CPS or 12)\n\t        task.spawn(bedwars.placeBlock, Result.BridgePath[1].Position, Wool, false)\n\t        return true\n\t    end\n\t    return false\n\tend\n\t\n\tlocal function Scaffold(Position: Vector3, Plan, Index: number, Now: number)\n\t    local Block = Plan:NextBlock(Index)\n\t    return Block and (Position - Block.Position).Magnitude <= 18 and (PlacedMemo[tostring(Block.Position)] or 0) <= Now and Block.Position or nil\n\tend\n\t\n\tlocal function BeginLeg(Plan, Index: number, Now: number)\n\t    local Root: BasePart = Entity.character.RootPart\n\t    local HipHeight: number = Entity.character.HipHeight\n\t    local Waypoint = Plan.Waypoints[Index]\n\t    if Waypoint.Blocks and not getWool() then\n\t        return nil, \"Out of blocks for the planned bridge\"\n\t    end\n\t    if Waypoint.Gap and not Navigation:EvaluateGap(math.max(Waypoint.Gap, ((Waypoint.Center - Root.Position) * Planar).Magnitude - 4.5), Waypoint.Rise * 3, {Speed = TravelSpeed(), Traversal = Traversal()}).Crossable then\n\t        return nil, \"Gap is no longer crossable at this speed\"\n\t    end\n\t\n\t    local Ground: RaycastResult? = workspace:Raycast(Waypoint.Center + Vector3.new(0, 3, 0), Vector3.new(0, -9, 0), Senses.Params)\n\t    local Destination: Vector3 = Ground and Vector3.new(Waypoint.Center.X, Ground.Position.Y + HipHeight, Waypoint.Center.Z) or Waypoint.Blocks and Waypoint.Center + Vector3.new(0, HipHeight - 1.5, 0) or Waypoint.Center + Vector3.new(0, 3, 0)\n\t    if not Ground and #workspace:GetPartBoundsInBox(CFrame.new(Waypoint.Center + Vector3.new(0, 1.5, 0)), Vector3.new(1, 2, 1), Senses.Overlap) > 0 then\n\t        Destination += Vector3.new(0, 3, 0)\n\t    end\n\t    if Destination.Y > Root.Position.Y and Passage(Root.Position, Vector3.new(Root.Position.X, Destination.Y, Root.Position.Z)) then\n\t        Root.CFrame = CFrame.new(Root.Position.X, Destination.Y, Root.Position.Z)\n\t    end\n\t    local Heading: Vector3 = (Destination - Root.Position) * Planar\n\t    local Climb: Vector3? = if Destination.Y - Root.Position.Y > Tuning.PassageStep and Heading.Magnitude > 0.1 then Heading.Unit else nil\n\t\n\t    local Drop: boolean = Root.Position.Y - Destination.Y > (Waypoint.Type == \"Jump\" and 0.1 or 4) and not workspace:Raycast(Vector3.new(Destination.X, Root.Position.Y, Destination.Z), Vector3.new(0, Destination.Y - Root.Position.Y, 0), Senses.Params)\n\t    local Leg = {\n\t        plan = Plan,\n\t        index = Index,\n\t        grid = Waypoint.Grid,\n\t        point = Root.Position,\n\t        destination = Destination,\n\t        target = Drop and Vector3.new(Destination.X, Root.Position.Y, Destination.Z) or Destination,\n\t        drop = Drop,\n\t        ground = Ground ~= nil,\n\t        bridging = Waypoint.Blocks ~= nil,\n\t        climb = Climb,\n\t        deadline = Now + (Root.Position - Destination).Magnitude / math.max(TravelSpeed(), 1) + 3\n\t    }\n\t    Motion.leg, Motion.written = Leg, Root.Position\n\t\n\t    return Leg\n\tend\n\t\n\tlocal function MarkObstacle(Cell: Vector3, Along: Vector3, Now: number)\n\t    local Across: Vector3 = Vector3.new(-Along.Z, 0, Along.X)\n\t    local Step: Vector3 = math.abs(Across.X) > math.abs(Across.Z) and Vector3.new(math.sign(Across.X), 0, 0) or Vector3.new(0, 0, math.sign(Across.Z))\n\t    \n\t    for Offset: number = -Tuning.ObstacleScan, Tuning.ObstacleScan do\n\t        local Grid: Vector3 = Cell + Step * Offset\n\t        for Y: number = 0, 1 do\n\t            if #workspace:GetPartBoundsInBox(CFrame.new((Grid + Vector3.new(0, Y, 0)) * 3), Tuning.ObstacleProbe, Senses.Overlap) > 0 then\n\t                Agent.Memory:Route(Grid, \"collision\", Now)\n\t                if Navigation.World and Navigation.World.Learn then\n\t                    Navigation.World:Learn(Grid.X, Grid.Y + Y, Grid.Z, Tuning.LearnTime)\n\t                end\n\t                break\n\t            end\n\t        end\n\t    end\n\tend\n\t\n\tlocal function StepLeg(Leg, Now: number, DeltaTime: number)\n\t    local Root: BasePart = Entity.character.RootPart\n\t    if Motion.written and (Root.Position - Motion.written).Magnitude > 10 then\n\t        if Leg.grid then\n\t            Agent.Memory:Route(Leg.grid, \"lagback\", Now)\n\t        end\n\t        Agent:Invalidate(\"Position corrected by the server\")\n\t        Motion.written = nil\n\t        return \"blocked\", \"Position corrected by the server\"\n\t    end\n\t\n\t    local Speed: number = TravelSpeed()\n\t    if Leg.bridging then\n\t        local PlaceRate: number = bedwars.SharedConstants.BLOCK_PLACE_CPS or 12\n\t        Speed = math.min(Speed, PlaceRate * 3)\n\t        if workspace:GetServerTimeNow() >= Motion.nextPlace then\n\t            local Wool = getWool()\n\t            local Block = Wool and Scaffold(Root.Position, Leg.plan, Leg.index, Now)\n\t            if Block then\n\t                Motion.nextPlace = workspace:GetServerTimeNow() + 1 / PlaceRate\n\t                PlacedMemo[tostring(Block)] = Now + 1\n\t                task.spawn(bedwars.placeBlock, Block, Wool, false)\n\t            end\n\t        end\n\t    end\n\t\n\t    local Box: Vector3 = Vector3.new(Root.Size.X, Entity.character.HipHeight + Root.Size.Y / 2, Root.Size.X)\n\t    if Senses.Obstructed(Root.Position, Leg.target, Box) then\n\t        if Leg.grid then\n\t            Agent.Memory:Route(Leg.grid, \"obstructed\", Now)\n\t        end\n\t        Agent:Invalidate(\"Enemy block across the route\")\n\t        return \"blocked\", \"Enemy block across the route\"\n\t    end\n\t    \n\t    local Across: Vector3 = (Leg.target - Leg.point) * Planar\n\t    local Ahead = Leg.ground and Across.Magnitude > 0.05 and Across.Unit * math.min(TravelSpeed() * DeltaTime + Tuning.CollisionLookahead, Across.Magnitude)\n\t    local Contact = Ahead and workspace:Blockcast(CFrame.new(Root.Position), Box - Tuning.CollisionShrink, Ahead, Senses.Params)\n\t    if Contact then\n\t        local Cell: Vector3 = Navigation.WorldToGrid(Root.Position + Across.Unit * 3 - Vector3.new(0, Entity.character.HipHeight - 1.5, 0))\n\t        Cell = Vector3.new(Cell.X, Leg.grid and Leg.grid.Y or Cell.Y, Cell.Z)\n\t        for i: number, v: Vector3 in {Cell, Leg.grid} do\n\t            Agent.Memory:Route(v, i == 1 and \"collision\" or \"detour\", Now)\n\t            if Navigation.World then\n\t                Navigation.World:Invalidate(v.X, v.Y, v.Z)\n\t                Navigation.World:Invalidate(v.X, v.Y + 1, v.Z)\n\t            end\n\t        end\n\t        MarkObstacle(Cell, Across.Unit, Now)\n\t        local Hit: Instance = Contact.Instance\n\t        local Reason: string = `Collided with {Hit.Parent and Hit.Parent.Name or \"?\"}.{Hit.Name}, which the route did not expect`\n\t        Agent:Invalidate(Reason)\n\t        return \"blocked\", Reason\n\t    end\n\t\n\t    local Offset: Vector3 = Leg.target - Leg.point\n\t    local Distance: number = Offset.Magnitude\n\t    local Direction: Vector3 = Distance > 0 and Offset / Distance or Vector3.zero\n\t    local Step: number = math.min(Speed * DeltaTime, Distance)\n\t    if Leg.bridging and not Leg.plan:Placed(Leg.plan.Waypoints[Leg.index]) and not Senses.Ground(Leg.point + Direction * Step) then\n\t        Leg.waiting = Leg.waiting or Now\n\t        Leg.deadline = math.max(Leg.deadline, Now + 1)\n\t        if Now - Leg.waiting > Tuning.PlacementTimeout then\n\t            if Leg.grid then\n\t                Agent.Memory:Route(Leg.grid, \"placement\", Now)\n\t            end\n\t            Agent:Invalidate(\"Block placement was not confirmed\")\n\t            return \"blocked\", \"Block placement was not confirmed\"\n\t        end\n\t        Step = 0\n\t    else\n\t        Leg.waiting = nil\n\t    end\n\t    Leg.point += Direction * Step\n\t    local Flat: Vector3 = Direction * Planar\n\t    local Velocity: Vector3 = Direction * Speed\n\t    if Leg.ground and not Leg.bridging and not Clear(Leg.point) and Clear(Root.Position) then\n\t        Leg.point = Root.Position\n\t        local Cell: Vector3 = Navigation.WorldToGrid(Root.Position + (Across.Magnitude > 0.05 and Across.Unit * 3 or Vector3.zero) - Vector3.new(0, Entity.character.HipHeight - 1.5, 0))\n\t        Agent.Memory:Route(Vector3.new(Cell.X, Leg.grid and Leg.grid.Y or Cell.Y, Cell.Z), \"collision\", Now)\n\t        if Across.Magnitude > 0.05 then\n\t            MarkObstacle(Vector3.new(Cell.X, Leg.grid and Leg.grid.Y or Cell.Y, Cell.Z), Across.Unit, Now)\n\t        end\n\t        Agent:Invalidate(\"Next step would enter solid geometry\")\n\t        return \"blocked\", \"Next step would enter solid geometry\"\n\t    end\n\t    if not Leg.ground and not Leg.bridging and not Clear(Leg.point, Tuning.HoverWidth) and Clear(Root.Position, Tuning.HoverWidth) then\n\t        Leg.point = Root.Position\n\t        if Leg.grid then\n\t            Agent.Memory:Route(Leg.grid, \"collision\", Now)\n\t        end\n\t        Agent:Invalidate(\"Air leg would enter solid geometry\")\n\t        return \"blocked\", \"Air leg would enter solid geometry\"\n\t    end\n\t\n\t    local Lifted = Senses.Projectile(Leg.point, Velocity) and not Senses.Projectile(Leg.point + Vector3.new(0, 8, 0), Velocity) and Passage(Leg.point, Leg.point + Vector3.new(0, 8, 0))\n\t    local Position: Vector3 = Lifted and Leg.point + Vector3.new(0, 8, 0) or Leg.point\n\t    Root.CFrame = Flat.Magnitude > 0.1 and CFrame.lookAlong(Position, Flat) or CFrame.new(Position) * Root.CFrame.Rotation\n\t    Root.AssemblyLinearVelocity = Leg.ground and Vector3.zero or Vector3.new(0, 2.5, 0)\n\t    Motion.written, Motion.velocity, Motion.controlledAt = Root.Position, Velocity, Now\n\t\n\t    if (Leg.target - Leg.point).Magnitude < 0.05 or Now > Leg.deadline then\n\t        local Landing: Vector3? = Leg.drop and Touchdown(Leg.destination, Root.Position.Y) or nil\n\t        if Landing then\n\t            Root.CFrame = CFrame.new(Landing)\n\t            Root.AssemblyLinearVelocity = Vector3.zero\n\t            Motion.written = Root.Position\n\t        end\n\t        return \"arrived\"\n\t    end\n\t    return \"moving\"\n\tend\n\t\n\tlocal function Travel(Plan, Now: number, DeltaTime: number)\n\t    if Plan.Cursor > #Plan.Waypoints then\n\t        Motion.leg = nil\n\t        return \"end\"\n\t    end\n\t\n\t    local Leg = Motion.leg\n\t    if not Leg or Leg.plan ~= Plan or Leg.index ~= Plan.Cursor then\n\t        local Reason\n\t        Leg, Reason = BeginLeg(Plan, Plan.Cursor, Now)\n\t        if not Leg then\n\t            Agent:Invalidate(Reason)\n\t            return \"blocked\", Reason\n\t        end\n\t    end\n\t\n\t    local Status, Reason = StepLeg(Leg, Now, DeltaTime)\n\t    if Status == \"arrived\" then\n\t        Motion.leg = nil\n\t        if Agent:IsCurrent(Plan) then\n\t            Plan.Cursor = Leg.index + 1\n\t        end\n\t        return \"moving\"\n\t    elseif Status == \"blocked\" then\n\t        Motion.leg = nil\n\t    end\n\t    \n\t    return Status, Reason\n\tend\n\t\n\tlocal function Near(Position: Vector3, Radius: number, Vertical: number?)\n\t    local Offset: Vector3 = Position - Entity.character.RootPart.Position\n\t    return (Offset * Planar).Magnitude <= Radius and math.abs(Offset.Y) <= (Vertical or 6)\n\tend\n\t\n\tlocal function Supported(Plan)\n\t    for i: number = Plan.Cursor, math.min(Plan.Cursor + 2, #Plan.Waypoints) do\n\t        local Waypoint = Plan.Waypoints[i]\n\t        if Waypoint.Ground and not Waypoint.Blocks and not workspace:Raycast(Waypoint.Center + Vector3.new(0, 3, 0), Vector3.new(0, -9, 0), Senses.Params) then\n\t            return false\n\t        end\n\t    end\n\t    return true\n\tend\n\t\n\tlocal function Approach(Goal, Position: Vector3, Radius: number, Now: number, DeltaTime: number, Vertical: number?)\n\t    if Near(Position, Radius, Vertical) then\n\t        Motion.leg = nil\n\t        return \"arrived\"\n\t    end\n\t    if Flight.Try(Goal, Position, Now) then\n\t        return \"moving\"\n\t    end\n\t\n\t    local Root: BasePart = Entity.character.RootPart\n\t    local Plan = Agent:Current()\n\t    local Owned = Plan ~= nil and not Plan.Expired and Plan.TargetId == Goal.key\n\t    if Owned and Plan.Cursor > #Plan.Waypoints then\n\t        Motion.leg = nil\n\t        return \"end\"\n\t    end\n\t    if Owned and not Motion.leg and Plan:Stale() then\n\t        if Supported(Plan) then\n\t            Routing.replace = Routing.replace or \"Route support changed\"\n\t        else\n\t            Agent:Invalidate(\"Route support changed\")\n\t            Owned = false\n\t        end\n\t    end\n\t    if not Owned then\n\t        if not Routing.request and Now >= Routing.retryAt then\n\t            RequestRoute(Goal, Position, nil, Now)\n\t        end\n\t        Coast(Position, Now, DeltaTime, Goal)\n\t        return \"routing\"\n\t    end\n\t\n\t    local Settle: number = math.max(0.5, (Routing.took or 0) * Tuning.ReplanFactor)\n\t    local Drifted: boolean = Now - Routing.at >= Settle and Plan.Target ~= nil and (Position - Plan.Target).Magnitude > math.clamp((Position - Root.Position).Magnitude * 0.25, 6, 30)\n\t    if not Routing.request and Now >= Routing.retryAt and (Routing.replace or Drifted) then\n\t        RequestRoute(Goal, Position, nil, Now)\n\t    end\n\t    if Motion.commit or not Agent:IsCurrent(Plan) or Plan.Expired then\n\t        return \"routing\"\n\t    end\n\t    if Leap.Try(Goal, Plan, Now) then\n\t        return \"moving\"\n\t    end\n\t\n\t    local Status, Reason = Travel(Plan, Now, DeltaTime)\n\t    if Status == \"blocked\" then\n\t        RouteFault(Goal, Reason or \"Route blocked\", Now)\n\t    end\n\t\n\t    return Status\n\tend\n\t\n\tlocal function ShortEnd(Goal, Now: number)\n\t    Agent:Invalidate(\"Route ended short of the objective\")\n\t    RouteFault(Goal, \"Route ends short of the objective\", Now)\n\tend\n\t\n\tlocal function Strike(Record, Distance: number, Now: number)\n\t    if Assisted() or Now < Motion.nextAttack or not Record.root or Distance > Reach() then\n\t        return\n\t    end\n\t    \n\t    Motion.nextAttack = Now + Settings.CombatRate.Value\n\t    Senses.Attack({target = Record.root, player = Record.player, owner = Record.team})\n\tend\n\t\n\tlocal function OrbitRadius(Goal)\n\t    local Limit: number = math.max(math.min(StrafeRange.Value, Reach() - Tuning.StrikeMargin), Tuning.MinOrbit)\n\t    Goal.radius = math.min(Goal.radius or Limit, Limit)\n\t\n\t    return Goal.radius\n\tend\n\t\n\tlocal function Orbit(Record, Target: BasePart, Now: number, DeltaTime: number, Range: number)\n\t    local Root: BasePart = Entity.character.RootPart\n\t    local HipHeight: number = Entity.character.HipHeight\n\t    local State = Motion.orbit\n\t    if not State or State.record ~= Record then\n\t        State = {record = Record, spin = 1, flipAt = Now + Tuning.StrafeFlip, last = Root.Position}\n\t        Motion.orbit = State\n\t    end\n\t    Motion.leg = nil\n\t    Motion.controlledAt = Now\n\t\n\t    local Delta: number = math.max(DeltaTime, 1 / 240)\n\t    local LocalPosition, TargetPosition = Root.Position, Target.Position\n\t    local Velocity: Vector3 = (LocalPosition - State.last) / Delta\n\t    State.last = LocalPosition\n\t    if Dodge(TravelSpeed(), Delta, Velocity * Planar) then\n\t        State.last = Root.Position\n\t        return\n\t    end\n\t\n\t    local Speed: number = TravelSpeed() * Delta\n\t    local Moving: Vector3 = Target.AssemblyLinearVelocity * Planar\n\t    local Toward: Vector3 = (TargetPosition - LocalPosition) * Planar\n\t    local Away: number = Toward.Magnitude > 0.1 and Moving:Dot(Toward.Unit) or 0\n\t    local Running: boolean = Away > Tuning.RunningSpeed\n\t    local Charging: boolean = Away < -Tuning.ChargingSpeed\n\t    local Lead: number = Running and Toward.Magnitude > Range + 3 and math.min(Toward.Magnitude / math.max(TravelSpeed(), 1), Tuning.OrbitLead) * (1 - Record.volatility) or 0\n\t    local Center: Vector3 = Vector3.new(TargetPosition.X, LocalPosition.Y, TargetPosition.Z) + Moving * Lead\n\t    local Offset: Vector3 = (LocalPosition - Center) * Planar\n\t    local Outward: Vector3 = Offset.Magnitude > 0.1 and Offset.Unit or Toward.Magnitude > 0.1 and -Toward.Unit or Vector3.new(1, 0, 0)\n\t    local Slack: number = (Running and math.max(Range - 3, Tuning.MinOrbit) or Range) - Offset.Magnitude\n\t    local Lowest: number = math.min(TargetPosition.Y - HipHeight - 9, LocalPosition.Y - HipHeight - Tuning.CoastDrop)\n\t    if State.free and Now >= State.flipAt and math.abs(Slack) < 2 then\n\t        State.spin, State.flipAt = -State.spin, Now + Tuning.StrafeFlip + (Now * 7.3) % 1 * Tuning.StrafeJitter\n\t    end\n\t\n\t    local Radial: number = math.clamp(Slack - Away * Delta, -Speed, Speed)\n\t    local Side: number = math.sqrt(math.max(Speed * Speed - Radial * Radial, 0))\n\t    if Charging then\n\t        Radial, Side = math.clamp(Slack, -1, 1) * Speed * 0.6, Speed * 0.8\n\t    end\n\t    local Tangent: Vector3 = Vector3.new(-Outward.Z, 0, Outward.X)\n\t    local Position: Vector3? = nil\n\t    State.free = false\n\t    local Inward: boolean = Offset.Magnitude > Tuning.MinOrbit\n\t    for i: number = 1, 8 do\n\t        local Spin: number = if i % 2 == 1 then State.spin else -State.spin\n\t        local Step: Vector3 = if i <= 2 then Outward * Radial + Tangent * (Side * Spin) elseif i <= 4 then Tangent * (Speed * Spin) elseif i == 5 then Outward * Radial elseif not Inward then Vector3.zero elseif i <= 7 then (Tangent * (0.8 * Spin) - Outward * 0.6) * Speed else -Outward * Speed\n\t        \n\t        if Step.Magnitude > 0.01 then\n\t            Position = Stride(LocalPosition, Step.Unit, Step.Magnitude, Lowest)\n\t            if Position then\n\t                State.free = i == 1\n\t                if Spin ~= State.spin then\n\t                    State.spin, State.flipAt = Spin, Now + Tuning.StrafeFlip\n\t                end\n\t                break\n\t            end\n\t        end\n\t    end\n\t\n\t    local Footing: RaycastResult? = workspace:Raycast(LocalPosition, Vector3.new(0, -70, 0), Senses.Params)\n\t    if Footing and Footing.Position.Y < Lowest then\n\t        Footing = nil\n\t    end\n\t\n\t    local Recovery: Vector3 = TargetPosition - LocalPosition\n\t    if not Footing and Recovery.Magnitude > 0.1 then\n\t        local Moved: Vector3 = LocalPosition + (Recovery.Unit * math.min(Speed, Recovery.Magnitude))\n\t        if Clear(Moved) then\n\t            Root.CFrame = (TargetPosition - Moved).Magnitude > 0.1 and CFrame.lookAt(Moved, TargetPosition) or CFrame.new(Moved) * Root.CFrame.Rotation\n\t        end\n\t    elseif Position then\n\t        Root.CFrame = ((TargetPosition - Position) * Planar).Magnitude > 0.1 and CFrame.lookAt(Position, Vector3.new(TargetPosition.X, Position.Y, TargetPosition.Z)) or CFrame.new(Position) * Root.CFrame.Rotation\n\t    elseif Footing then\n\t        local Standing: Vector3 = Vector3.new(LocalPosition.X, Footing.Position.Y + HipHeight, LocalPosition.Z)\n\t        Root.CFrame = Toward.Magnitude > 0.1 and CFrame.lookAt(Standing, Vector3.new(TargetPosition.X, Standing.Y, TargetPosition.Z)) or CFrame.new(Standing) * Root.CFrame.Rotation\n\t    end\n\t\n\t    Root.AssemblyLinearVelocity = Vector3.zero\n\t    Motion.written = Root.Position\n\tend\n\t\n\tlocal function EnemyReach(Record)\n\t    local Inventory = store.inventories[Record.player]\n\t    local Held = Inventory and Inventory.hand and Inventory.hand.tool\n\t    local Meta = Held and bedwars.ItemMeta[Held.Name]\n\t    return Meta and Meta.sword and Meta.sword.attackRange or store.swordDistance or Tuning.EnemyReach\n\tend\n\t\n\tlocal function AerialSpot(Target: BasePart, Distance: number, First: number)\n\t    local HipHeight: number = Entity.character.HipHeight\n\t    local Center: Vector3 = Target.Position\n\t    local Look: Vector3 = Target.CFrame.LookVector * Planar\n\t    Look = Look.Magnitude > 0.01 and Look.Unit or Vector3.new(0, 0, 1)\n\t\n\t    local Side: Vector3 = Vector3.new(Look.Z, 0, -Look.X)\n\t    local Tilts: {Vector3} = {-Look * Tuning.AerialTilt, Side * Tuning.AerialTilt, -Side * Tuning.AerialTilt, Look * Tuning.AerialTilt, -Look * Tuning.AerialSteep, Side * Tuning.AerialSteep}\n\t    local Rejected: {string} = {}\n\t    for i: number = 0, #Tilts - 1 do\n\t        local Index: number = (First + i - 1) % #Tilts + 1\n\t        local Direction: Vector3 = (Vector3.new(0, 1, 0) + Tilts[Index]).Unit\n\t        local Ceiling: RaycastResult? = workspace:Raycast(Center, Direction * Distance, Senses.Params)\n\t        local Point: Vector3 = Center + Direction * (Ceiling and math.max((Ceiling.Position - Center).Magnitude - 2, 0) or Distance)\n\t        local Ground: RaycastResult? = workspace:Raycast(Point, Vector3.new(0, -(Distance + 12), 0), Senses.Params)\n\t        local Reason: string\n\t        if (Point - Center).Magnitude < Tuning.MinOrbit then\n\t            Reason = \"ceiling\"\n\t        elseif not Clear(Point, Tuning.HoverWidth) then\n\t            Reason = \"blocked\"\n\t        elseif not Ground then\n\t            Reason = \"void\"\n\t        elseif Ground.Position.Y < Center.Y - HipHeight - Tuning.AerialDrop then\n\t            Reason = \"drop\"\n\t        elseif Senses.Surface(Ground.Position + Vector3.new(0, HipHeight, 0)).nearVoid then\n\t            Reason = \"edge\"\n\t        elseif not Passage(Point, Vector3.new(Point.X, Ground.Position.Y + HipHeight, Point.Z)) then\n\t            Reason = \"column\"\n\t        else\n\t            return Point - Center, Index, nil\n\t        end\n\t\n\t        table.insert(Rejected, Reason)\n\t    end\n\t    \n\t    return nil, nil, table.concat(Rejected, \",\")\n\tend\n\t\n\tlocal function Aerial(Record, Target: BasePart, Now: number, DeltaTime: number)\n\t    local Root: BasePart = Entity.character.RootPart\n\t    local HipHeight: number = Entity.character.HipHeight\n\t    local Center: Vector3 = Target.Position\n\t    local State = Motion.aerial\n\t    local Fresh: boolean = not State or State.record ~= Record\n\t    if Fresh or Now >= State.scanAt then\n\t        local Offset, Index, Rejected = AerialSpot(Target, math.clamp(EnemyReach(Record) + Tuning.AerialMargin, Tuning.MinOrbit, Reach() - 1), if Fresh then 1 else State.tilt)\n\t        if not Offset then\n\t            Motion.aerialFail = `no hover spot ({Rejected})`\n\t            return false\n\t        end\n\t        if Fresh then\n\t            State = {record = Record, up = true, since = Now, at = Root.Position, lift = 0}\n\t            Motion.aerial = State\n\t        end\n\t        State.offset, State.tilt, State.scanAt = Offset, Index, Now + Tuning.AerialScan\n\t    end\n\t    if State.up and Now - State.since >= Tuning.AerialHold then\n\t        State.up, State.since = false, Now\n\t    elseif not State.up and Now - State.since >= Tuning.AerialRest then\n\t        State.up, State.since = true, Now\n\t    end\n\t\n\t    local Spot: Vector3 = Center + State.offset\n\t    local Shift: Vector3 = (Spot - State.at) * Planar\n\t    local Limit: number = TravelSpeed() * math.max(DeltaTime, 1 / 240)\n\t    local Hover: Vector3 = if Shift.Magnitude > Limit then Vector3.new(State.at.X, Spot.Y, State.at.Z) + Shift.Unit * Limit else Spot\n\t    local Below: RaycastResult? = workspace:Raycast(Hover, Vector3.new(0, -(Hover.Y - Center.Y + HipHeight + Tuning.SkyDrop), 0), Senses.Params)\n\t    if not Below then\n\t        Motion.aerialFail = \"void below the hover path\"\n\t        return false\n\t    end\n\t    local Stand: Vector3 = Vector3.new(Hover.X, Below.Position.Y + HipHeight, Hover.Z)\n\t    if Hover.Y - Stand.Y > Tuning.SafeDrop then\n\t        Motion.aerialFail = \"unsafe drop below the hover path\"\n\t        return false\n\t    end\n\t    local Exposed: boolean = ((Center - Hover) * Planar).Magnitude <= EnemyReach(Record) + Tuning.AerialMargin\n\t    local Rising: boolean = State.up and (Exposed or ((Spot - Hover) * Planar).Magnitude <= Tuning.AerialEntry)\n\t    local Goal: Vector3 = if Rising then Hover else Stand\n\t    if not Passage(Root.Position, Goal) then\n\t        Motion.aerialFail = if Rising then \"blocked on the way up\" elseif State.up then \"blocked approaching on the ground\" else \"blocked on the way down\"\n\t        return false\n\t    end\n\t    State.at, State.stand, State.lift = Goal, Stand, Hover.Y - Below.Position.Y\n\t    Root.CFrame = CFrame.lookAt(Goal, Center)\n\t    Root.AssemblyLinearVelocity = Vector3.zero\n\t    Motion.leg, Motion.orbit = nil, nil\n\t    Motion.written, Motion.controlledAt = Root.Position, Now\n\t    \n\t    return true\n\tend\n\t\n\tlocal function Demolish(Goal, Now: number)\n\t    local Bed: BasePart = Goal.bed.part\n\t    if not BreakBed.Enabled or (Bed.Position - Entity.character.RootPart.Position).Magnitude > Tuning.BreakRange then\n\t        return false\n\t    end\n\t    if Now >= Motion.nextBreak and (Bed:GetAttribute(\"BedShieldEndTime\") or 0) <= workspace:GetServerTimeNow() then\n\t        Motion.nextBreak = Now + Settings.BedRate.Value\n\t        task.spawn(bedwars.breakBlock, Bed, true, true, nil, true)\n\t    end\n\t    return true\n\tend\n\t\n\tlocal function Engage(Goal, Now: number, DeltaTime: number)\n\t    local Record = Goal.record\n\t    local Target: BasePart? = RootOf(Record)\n\t    if not Target then\n\t        Hold(Now, DeltaTime)\n\t        return\n\t    end\n\t\n\t    local Root: BasePart = Entity.character.RootPart\n\t    local Distance: number = (Target.Position - Root.Position).Magnitude\n\t    local Fighting: boolean = Goal.subgoal == \"FIGHT\"\n\t    local Radius: number = OrbitRadius(Goal)\n\t    local Aloft: boolean = Motion.aerial ~= nil and Motion.aerial.record == Record\n\t    local Open: boolean = if Aloft then Goal.sight ~= false else Goal.direct ~= false or Distance <= Radius + (Fighting and 6 or 3) and Goal.sight ~= false\n\t    if Fighting and (not Open or Distance > (if Aloft then Reach() + Tuning.AerialSlack else Radius + 8)) then\n\t        Goal.gapAt = Goal.gapAt or Now\n\t        if not Open and Now - Goal.gapAt > Tuning.GapDwell or Now - Goal.gapAt > Tuning.GapStall then\n\t            Goal.routed, Goal.gapAt = true, nil\n\t        end\n\t    else\n\t        Goal.gapAt = nil\n\t    end\n\t    if Goal.routed and Open and Distance <= Tuning.EngageRange then\n\t        Goal.routed = nil\n\t    end\n\t\n\t    local Objective = Goal.resume\n\t    local Swinging: boolean = bedwars.SwordController ~= nil and workspace:GetServerTimeNow() - bedwars.SwordController.lastAttack < Tuning.SwordLock\n\t    if Objective and Objective.kind == \"DESTROY_BED\" and Assisted() and Swinging and Valid(Objective) then\n\t        Demolish(Objective, Now)\n\t    end\n\t\n\t    if not Goal.routed and (Fighting and Distance <= Tuning.DisengageRange or not Fighting and Open and Distance <= Tuning.EngageRange) then\n\t        if not Fighting then\n\t            Goal.subgoal, Goal.startRatio = \"FIGHT\", World.self.ratio\n\t            CancelRoute()\n\t            if Motion.leg and not Senses.Ground(Root.Position) then\n\t                Motion.commit, Motion.leg = Motion.leg, nil\n\t                Strike(Record, Distance, Now)\n\t                return\n\t            end\n\t        end\n\t        local Lifted: boolean = false\n\t        if AerialFight.Enabled and not Record.protected and Now >= (Motion.aerialPause or 0) then\n\t            Lifted = Aerial(Record, Target, Now, DeltaTime)\n\t            if not Lifted then\n\t                Motion.aerialPause = Now + Tuning.AerialPause\n\t            end\n\t        end\n\t        if not Lifted then\n\t            Descend()\n\t            if not Motion.glide then\n\t                Orbit(Record, Target, Now, DeltaTime, Radius)\n\t            end\n\t        end\n\t        Strike(Record, Distance, Now)\n\t        return\n\t    end\n\t\n\t    Descend()\n\t    if Motion.glide then\n\t        return\n\t    end\n\t    if Goal.subgoal ~= \"CHASE\" then\n\t        Goal.subgoal, Goal.chaseAt, Goal.closest, Goal.closestAt, Goal.startDistance = \"CHASE\", Now, Distance, Now, Distance\n\t        Motion.orbit = nil\n\t    end\n\t    local Status: string = Approach(Goal, Goal.position or Target.Position, 3, Now, DeltaTime)\n\t    Strike(Record, Distance, Now)\n\t    if Status == \"end\" then\n\t        local Plan = Agent:Current()\n\t        if Plan and Plan.Target and (Plan.Target - Target.Position).Magnitude < 6 then\n\t            ShortEnd(Goal, Now)\n\t        else\n\t            Agent:Invalidate(\"Target moved past the end of the route\")\n\t        end\n\t    end\n\tend\n\t\n\tlocal function StancePoint(Bed: Vector3, From: Vector3, Threats: {Vector3})\n\t    local HipHeight: number = Entity.character.HipHeight\n\t    local function Safety(Point: Vector3)\n\t        local Nearest: number = Tuning.StanceWatch\n\t        for _, v: Vector3 in Threats do\n\t            Nearest = math.min(Nearest, ((v - Point) * Planar).Magnitude)\n\t        end\n\t        return Nearest\n\t    end\n\t\n\t    local Options = {}\n\t    for _, Radius: number in Tuning.StanceRings do\n\t        for Angle: number = 0, 330, 30 do\n\t            local Theta: number = math.rad(Angle)\n\t            local Point: Vector3 = Bed + Vector3.new(math.cos(Theta) * Radius, 0, math.sin(Theta) * Radius)\n\t            table.insert(Options, {point = Point, score = Safety(Point) - ((Point - From) * Planar).Magnitude * Tuning.StanceTravel})\n\t        end\n\t    end\n\t    table.sort(Options, function(A, B)\n\t        return A.score > B.score\n\t    end)\n\t\n\t    local function Passage(To: Vector3)\n\t        local Line: Vector3 = (To - From) * Planar\n\t        local Length: number = Line.Magnitude\n\t        local Nearest: number = math.huge\n\t        for _, v: Vector3 in Threats do\n\t            local Offset: Vector3 = (v - From) * Planar\n\t            local Along: number = Length > 0.1 and math.clamp(Offset:Dot(Line) / (Length * Length), 0, 1) or 0\n\t            Nearest = math.min(Nearest, (Offset - Line * Along).Magnitude)\n\t        end\n\t        return Nearest\n\t    end\n\t\n\t    local Standing: number = Safety(From)\n\t    local Margin: number = math.min(Standing, Tuning.StanceClear) * 0.9\n\t    local Checked: number = 0\n\t    for _, v: any in Options do\n\t        if Checked >= Tuning.StanceChecks or v.score <= Standing + Tuning.StanceGain then\n\t            break\n\t        end\n\t        if Passage(v.point) >= Margin then\n\t            Checked += 1\n\t            local Floor: RaycastResult? = workspace:Raycast(v.point + Vector3.new(0, 10, 0), Vector3.new(0, -24, 0), Senses.Params)\n\t            if Floor and Floor.Normal.Y > 0.65 then\n\t                local Stand: Vector3 = Vector3.new(v.point.X, Floor.Position.Y + HipHeight, v.point.Z)\n\t                if (Stand - Bed).Magnitude <= Tuning.StanceReach and not Senses.Surface(Stand).nearVoid and Clear(Stand) and Direct(From, Stand) then\n\t                    return Stand\n\t                end\n\t            end\n\t        end\n\t    end\n\t    return nil\n\tend\n\t\n\tlocal function Stance(Goal, Now: number, DeltaTime: number)\n\t    local Root: BasePart = Entity.character.RootPart\n\t    local Threats = ThreatPositions(Tuning.StanceWatch)\n\t    if #Threats == 0 then\n\t        local Bed: Vector3 = Goal.bed.part.Position\n\t        Goal.stance = nil\n\t        if not (((Bed - Root.Position) * Planar).Magnitude > Tuning.StanceReach and Coast(Bed, Now, DeltaTime)) then\n\t            Hold(Now, DeltaTime)\n\t        end\n\t        return\n\t    end\n\t    if Now >= (Goal.stanceAt or 0) then\n\t        Goal.stanceAt = Now + Tuning.StanceInterval\n\t        Goal.stance = StancePoint(Goal.bed.part.Position, Root.Position, Threats) or Goal.stance\n\t    end\n\t    if Goal.stance and ((Goal.stance - Root.Position) * Planar).Magnitude > 1.5 then\n\t        if not Coast(Goal.stance, Now, DeltaTime) then\n\t            Goal.stance, Goal.stanceAt = nil, 0\n\t        end\n\t    else\n\t        Hold(Now, DeltaTime)\n\t    end\n\tend\n\t\n\tlocal function AttackBed(Goal, Now: number, DeltaTime: number)\n\t    local Bed: BasePart = Goal.bed.part\n\t    local Root: BasePart = Entity.character.RootPart\n\t    local BedDistance: number = (Bed.Position - Root.Position).Magnitude\n\t    if Goal.subgoal == \"APPROACH\" then\n\t        local Status: string = Approach(Goal, Goal.position, 3, Now, DeltaTime)\n\t        local Ranged: boolean = not Goal.close and BreakBed.Enabled and BedDistance <= Tuning.BreakRange and not Motion.commit and Senses.Ground(Root.Position) and not Senses.Surface(Root.Position).nearVoid\n\t        if Status == \"arrived\" or BedDistance <= Tuning.BreakReach or Ranged or Status == \"end\" and BedDistance <= Tuning.BreakRange then\n\t            Goal.subgoal, Goal.breakAt = \"BREAK\", Now\n\t            Motion.leg = nil\n\t        elseif Status == \"end\" then\n\t            ShortEnd(Goal, Now)\n\t            return\n\t        end\n\t    elseif Goal.subgoal == \"TOWER\" then\n\t        Build.Tower(Goal, Now, DeltaTime)\n\t    elseif BedDistance > Tuning.BreakRange then\n\t        Goal.subgoal, Goal.towered = \"APPROACH\", nil\n\t    elseif Goal.towered and BedDistance <= Tuning.StanceReach then\n\t        Hold(Now, DeltaTime)\n\t    elseif Settings.BedTower.Enabled and BreakBed.Enabled and Senses.Ground(Root.Position) and Build.Needed(Bed.Position, Root.Position) then\n\t        Goal.subgoal, Goal.tower, Goal.towered = \"TOWER\", nil, nil\n\t    elseif not Goal.close and BedDistance > Tuning.BreakReach and (Bed:GetAttribute(\"BedShieldEndTime\") or 0) <= workspace:GetServerTimeNow() and Now - math.max(Goal.breakAt or Now, Goal.lastProgressAt) > Tuning.StanceStall then\n\t        Goal.subgoal, Goal.close, Goal.stance = \"APPROACH\", true, nil\n\t        Report(`bed is not breaking from {math.floor(BedDistance)} studs, moving in`)\n\t    else\n\t        Stance(Goal, Now, DeltaTime)\n\t    end\n\t\n\t    if BedDistance <= Tuning.BreakRange and not Demolish(Goal, Now) and Goal.subgoal == \"BREAK\" and Now - Goal.breakAt > Tuning.BreakStall then\n\t        Finish(Goal, Now, true, \"Held the bed for another breaker\")\n\t    end\n\tend\n\t\n\tlocal function Collect(Goal, Now: number, DeltaTime: number)\n\t    local Item = getItem(Goal.currency)\n\t    local Amount: number = Item and Item.amount or 0\n\t    local function Learn()\n\t        local Gained: number = Amount - (Goal.startAmount or Amount)\n\t        local Spent: number = Now - (Goal.collectAt or Now)\n\t        if Gained > 0 and Spent > 1 then\n\t            World.rates[Goal.currency] = World.rates[Goal.currency] * 0.5 + Gained / Spent * 0.5\n\t        end\n\t    end\n\t\n\t    if Amount >= Goal.need then\n\t        Learn()\n\t        Finish(Goal, Now, true, `Collected {Goal.need} {Goal.currency}`)\n\t        return\n\t    end\n\t    if Goal.subgoal == \"APPROACH\" then\n\t        local Status: string = Approach(Goal, Goal.site.position, 3, Now, DeltaTime)\n\t        if Status == \"arrived\" then\n\t            Goal.subgoal, Goal.collectAt, Goal.startAmount = \"COLLECT\", Now, Amount\n\t        elseif Status == \"end\" then\n\t            ShortEnd(Goal, Now)\n\t        end\n\t        return\n\t    end\n\t    if not Near(Goal.site.position, 12) then\n\t        Goal.subgoal = \"APPROACH\"\n\t        return\n\t    end\n\t    if Now >= (Goal.shelterAt or 0) then\n\t        Goal.shelterAt = Now + Tuning.ShelterInterval\n\t        local Lines: {Vector3} = Sightlines(Now)\n\t        Goal.stand = if #Lines > 0 and Exposed(Entity.character.RootPart.Position, Lines) then Shelter(Goal.site.position, Pickup(), Lines) else nil\n\t    end\n\t    if Goal.stand then\n\t        Coast(Goal.stand, Now, DeltaTime)\n\t    else\n\t        Hold(Now, DeltaTime)\n\t        Build.Screen(Now)\n\t    end\n\t    if Now >= (Goal.stockAt or 0) then\n\t        Goal.stockAt = Now + 0.5\n\t        local Stock = Senses.Stock(Routing.stock)\n\t        if (Stock[Goal.site.id] or 0) == 0 then\n\t            for _, Other: any in Senses.Sites().Generators do\n\t                if Other ~= Goal.site and Other.resource == Goal.site.resource and (Stock[Other.id] or 0) > 0 and (Other.position - Goal.site.position).Magnitude <= Tuning.ClusterRange then\n\t                    Learn()\n\t                    Finish(Goal, Now, true, `Moving on to {Other.id}`)\n\t                    return\n\t                end\n\t            end\n\t        end\n\t    end\n\t    if Now - Goal.collectAt > Tuning.CollectWait then\n\t        Learn()\n\t        Finish(Goal, Now, false, \"Generator wait expired\")\n\t    end\n\tend\n\t\n\tlocal function Buy(Goal, Now: number, DeltaTime: number)\n\t    if Goal.subgoal == \"APPROACH\" then\n\t        local Status: string = Approach(Goal, Goal.site.position, 3, Now, DeltaTime, 3.5)\n\t        if Status == \"arrived\" then\n\t            Goal.subgoal = \"BUY\"\n\t        elseif Status == \"end\" then\n\t            ShortEnd(Goal, Now)\n\t        end\n\t        return\n\t    end\n\t\n\t    Hold(Now, DeltaTime)\n\t    local Pending = Goal.pending\n\t    if not Pending then\n\t        Pending = {started = Now, before = World.self.resources[Goal.purchase.currency] or 0}\n\t        Goal.pending = Pending\n\t        local Deal = Goal.purchase\n\t        Senses.Buy({target = Goal.site.target, position = Goal.site.position, shopId = Goal.site.shopId}, Deal, function(Success: boolean)\n\t            Pending.done, Pending.success = true, Success\n\t            if Success then\n\t                Routing.bought[Deal.item] = os.clock()\n\t                Routing.spent[Deal.currency] = {at = os.clock(), price = Deal.price, before = Pending.before}\n\t            end\n\t            if Success and not Deal.upgrade then\n\t                bedwars.AudioManager:playAudio(bedwars.SoundList.BEDWARS_PURCHASE_ITEM)\n\t                bedwars.Store:dispatch({\n\t                    type = \"BedwarsAddItemPurchased\",\n\t                    itemType = Deal.item\n\t                })\n\t                if Deal.tiered and bedwars.BedwarsShopController then\n\t                    bedwars.BedwarsShopController.alreadyPurchasedMap[Deal.item] = true\n\t                end\n\t            end\n\t        end)\n\t    elseif Pending.done then\n\t        if Pending.success then\n\t            Finish(Goal, Now, true, `Bought {Goal.purchase.item}`)\n\t        elseif (World.self.resources[Goal.purchase.currency] or 0) < Goal.purchase.price then\n\t            Finish(Goal, Now, false, \"The resources were spent before the purchase went through\")\n\t        else\n\t            Fail(Goal, Now, \"Shop rejected the purchase\")\n\t        end\n\t    elseif Now - Pending.started > Tuning.PurchaseTimeout then\n\t        Fail(Goal, Now, \"Purchase was not acknowledged\")\n\t    end\n\tend\n\t\n\tlocal function Protect(Goal, Now: number, DeltaTime: number)\n\t    if Goal.subgoal == \"APPROACH\" then\n\t        local Status: string = Approach(Goal, Goal.position, Tuning.CoverRange, Now, DeltaTime)\n\t        if Status == \"arrived\" or Status == \"end\" and Near(Goal.position, Tuning.CoverReach) then\n\t            Goal.subgoal, Goal.coverAt, Goal.placedAt = \"COVER\", Now, Now\n\t            Motion.leg = nil\n\t        elseif Status == \"end\" then\n\t            ShortEnd(Goal, Now)\n\t        end\n\t        return\n\t    end\n\t\n\t    local Root: BasePart = Entity.character.RootPart\n\t    local Open = Uncovered(Goal.bed.part, Goal.shell and Shell or Tuning.Cover)\n\t    Goal.open = #Open\n\t    if #Open == 0 then\n\t        Finish(Goal, Now, true, \"Covered our bed\")\n\t        return\n\t    end\n\t    if Now - Goal.coverAt > Tuning.CoverTimeout then\n\t        Fail(Goal, Now, \"Bed cover could not be placed\")\n\t        return\n\t    end\n\t    local Block = CoverBlock(Goal.shell == true)\n\t    if not Block then\n\t        Finish(Goal, Now, false, \"Out of blocks for the bed cover\")\n\t        return\n\t    end\n\t\n\t    local Target: Vector3? = nil\n\t    for _, v: Vector3 in Open do\n\t        local Offset: Vector3 = v - Root.Position\n\t        if ((Offset * Planar).Magnitude > 2.5 or math.abs(Offset.Y) > 4) and Offset.Magnitude <= Tuning.CoverReach and (PlacedMemo[tostring(v)] or 0) <= Now then\n\t            Target = v\n\t            break\n\t        end\n\t    end\n\t    if not Target then\n\t        if Now - Goal.placedAt > Tuning.CoverStall then\n\t            Coast(Goal.position, Now, DeltaTime)\n\t        else\n\t            Hold(Now, DeltaTime)\n\t        end\n\t        return\n\t    end\n\t    Hold(Now, DeltaTime)\n\t    if workspace:GetServerTimeNow() < Motion.nextPlace then\n\t        return\n\t    end\n\t    Goal.placedAt = Now\n\t    Motion.nextPlace = workspace:GetServerTimeNow() + 1 / (bedwars.SharedConstants.BLOCK_PLACE_CPS or 12)\n\t    PlacedMemo[tostring(Target)] = Now + 1\n\t    task.spawn(bedwars.placeBlock, Target, Block, false)\n\tend\n\t\n\tfunction Flight.Refuge(Now: number)\n\t    local Me = World.self\n\t    local Threats: {Vector3} = ThreatPositions(math.huge)\n\t    local Options: {Vector3} = {}\n\t    local Base: Vector3? = Home()\n\t    if Base then\n\t        table.insert(Options, Base)\n\t    end\n\t    for _, Site: any in Senses.Sites().Generators do\n\t        local Owner = Site.owner and World.teams[Site.owner]\n\t        if Site.target.Parent and (Site.owner == Me.team or not Owner or Owner.members == 0) then\n\t            table.insert(Options, Site.position)\n\t        end\n\t    end\n\t    local Best, Nearest = nil, math.huge\n\t    for _, Option: Vector3 in Options do\n\t        local Distance: number = ((Option - Me.position) * Planar).Magnitude\n\t        local Safe: boolean = Distance >= Tuning.FlightMinimum and Distance < Nearest\n\t        for _, v: Vector3 in Threats do\n\t            Safe = Safe and (v - Option).Magnitude > Tuning.RefugeClear\n\t        end\n\t        if Safe and Flight.Viable({key = \"retreat\", position = Option}, Now) then\n\t            Best, Nearest = Option, Distance\n\t        end\n\t    end\n\t    return Best\n\tend\n\t\n\tlocal function FleePoint()\n\t    local Root: BasePart = Entity.character.RootPart\n\t    local Sum, Count = Vector3.zero, 0\n\t    for _, v: Vector3 in ThreatPositions(60) do\n\t        Sum += v\n\t        Count += 1\n\t    end\n\t    if Count == 0 then\n\t        return nil\n\t    end\n\t    local Away: Vector3 = (Root.Position - Sum / Count) * Planar\n\t    Away = Away.Magnitude > 0.1 and Away.Unit or Root.CFrame.LookVector * Planar\n\t    for _, Distance: number in {36, 24, 12} do\n\t        for _, Angle: number in {0, 45, -45, 90, -90, 135, -135, 180} do\n\t            local Theta: number = math.rad(Angle)\n\t            local Point: Vector3 = Root.Position + Vector3.new(Away.X * math.cos(Theta) - Away.Z * math.sin(Theta), 0, Away.X * math.sin(Theta) + Away.Z * math.cos(Theta)) * Distance\n\t            local Ground: RaycastResult? = workspace:Raycast(Point + Vector3.new(0, 3, 0), Vector3.new(0, -12, 0), Senses.Params)\n\t            if Ground then\n\t                return Vector3.new(Point.X, Ground.Position.Y + Entity.character.HipHeight, Point.Z)\n\t            end\n\t        end\n\t    end\n\t    return nil\n\tend\n\t\n\tlocal function Withdraw(Goal, Now: number, DeltaTime: number)\n\t    local Root: BasePart = Entity.character.RootPart\n\t    local Nearest, Enemy = NearestEnemy(Root.Position)\n\t    local Healed: boolean = World.self.ratio >= math.min(math.max(Recover.Value, Health.Value + 10) / 100, 1)\n\t    if not Brain.retreating and Nearest > (if Healed then 40 else Tuning.RetreatClear) and (Brain.pursuit or 0) == 0 and not Sniped(Now) then\n\t        Finish(Goal, Now, true, \"Out of danger\")\n\t        return\n\t    end\n\t    if Goal.subgoal == \"PERCH\" or Goal.subgoal == \"PILLAR\" or Goal.subgoal == \"SKY\" then\n\t        if Motion.glide or Motion.pillar or Motion.sky then\n\t            return\n\t        end\n\t        Goal.subgoal, Goal.haven, Goal.raised = \"HOLD\", Root.Position, Goal.subgoal == \"PILLAR\" or Now - (Motion.raisedAt or -math.huge) < Tuning.PillarConfirm + Tuning.PillarHeight\n\t    end\n\t    local Archers: {Vector3} = Build.Archers(Now, Tuning.ArcherRange)\n\t    if Goal.subgoal == \"PATH\" and #Archers > 0 and Nearest > math.max(Tuning.SkyClear, (Enemy and Enemy.reach or 0) + Tuning.ContestMargin) then\n\t        Build.Screen(Now)\n\t    end\n\t    local Pending: boolean = Enemy ~= nil and not Enemy.alive\n\t    if Nearest <= 60 and (Pending or Nearest > Tuning.SkyTrigger and Goal.subgoal ~= \"HOLD\") and not Healed and SkyTravel.Enabled and #Archers == 0 then\n\t        if not Goal.position and Now >= (Goal.refugeAt or 0) then\n\t            Goal.refugeAt = Now + Tuning.RefugeInterval\n\t            Goal.position = Flight.Refuge(Now)\n\t            if Goal.position then\n\t                Report(`evacuating {math.floor((Goal.position - Root.Position).Magnitude)} studs to heal`)\n\t            end\n\t        end\n\t        if Goal.position then\n\t            Goal.subgoal = \"EVACUATE\"\n\t            local Status: string = Approach(Goal, Goal.position, 6, Now, DeltaTime)\n\t            if Status == \"arrived\" or Status == \"end\" then\n\t                Goal.subgoal, Goal.haven, Goal.position = \"HOLD\", Root.Position, nil\n\t            end\n\t            return\n\t        end\n\t    end\n\t    if Nearest > 60 or Goal.subgoal == \"HOLD\" and Goal.haven and (Root.Position - Goal.haven).Magnitude < 6 and Nearest > (Goal.raised and Tuning.PillarSafe or Tuning.ContactRange) then\n\t        Goal.subgoal = \"HOLD\"\n\t        if #Archers > 0 then\n\t            if Build.Hide(Goal, Archers, Now, DeltaTime) then\n\t                return\n\t            end\n\t        else\n\t            Hold(Now, DeltaTime)\n\t            return\n\t        end\n\t    end\n\t    if Nearest <= Tuning.SkyTrigger and #Archers == 0 then\n\t        local Spot: Vector3? = Nearest <= 18 and Perch(Now)\n\t        if Spot then\n\t            Goal.subgoal, Goal.haven = \"PERCH\", Spot\n\t            return\n\t        end\n\t        if Skyward(Now) then\n\t            Goal.subgoal = \"SKY\"\n\t            return\n\t        end\n\t        if Nearest <= 18 and not World.match.ownBed and Pillar(Now, Tuning.PillarHeight) then\n\t            Goal.subgoal = \"PILLAR\"\n\t            return\n\t        end\n\t    end\n\t\n\t    Goal.subgoal = \"PATH\"\n\t    local Plan = Agent:Current()\n\t    if not Plan or Plan.Expired or Plan.TargetId ~= Goal.key or Plan.Cursor > #Plan.Waypoints then\n\t        if not Routing.request and Now >= Routing.retryAt and Now - Routing.at >= 0.5 then\n\t            local Flee = Goal.flee and FleePoint()\n\t            if Flee then\n\t                RequestRoute(Goal, Flee, nil, Now)\n\t            elseif Goal.flee and Nearest <= 25 and Pillar(Now, Tuning.PillarHeight) then\n\t                Goal.subgoal = \"PILLAR\"\n\t                return\n\t            else\n\t                if Goal.flee and Nearest <= 25 then\n\t                    Brain.corneredAt = Now\n\t                    MarkDirty(\"Cornered with no safe escape\")\n\t                end\n\t                RequestRoute(Goal, nil, ThreatPositions(80), Now)\n\t            end\n\t        end\n\t        if not Goal.escapeAt or Now - Goal.escapeAt > Tuning.ObserveInterval then\n\t            Goal.escape, Goal.escapeAt = FleePoint(), Now\n\t        end\n\t        Coast(Goal.escape, Now, DeltaTime)\n\t        return\n\t    end\n\t    if Plan.Kind == \"Retreat\" and Plan.Target and (Plan.Target - Root.Position).Magnitude < 6 and Nearest <= 25 then\n\t        if Pillar(Now, Tuning.PillarHeight) then\n\t            Goal.subgoal = \"PILLAR\"\n\t            return\n\t        end\n\t        Brain.corneredAt = Now\n\t        MarkDirty(\"Cornered with no safe escape\")\n\t    end\n\t    Goal.haven = Plan.Target\n\t    Travel(Plan, Now, DeltaTime)\n\tend\n\t\n\tlocal function Scout(Goal, Now: number, DeltaTime: number)\n\t    local Status: string = Approach(Goal, Goal.position, 6, Now, DeltaTime)\n\t    if Status == \"arrived\" then\n\t        Finish(Goal, Now, true, \"Reached the last known position\")\n\t    elseif Status == \"end\" then\n\t        ShortEnd(Goal, Now)\n\t    end\n\tend\n\t\n\tlocal function Idle(Goal, Now: number, DeltaTime: number)\n\t    if Goal.subgoal == \"APPROACH\" then\n\t        local Status: string = Approach(Goal, Goal.position, if Goal.covered then Tuning.ShelterArrive else 3, Now, DeltaTime)\n\t        if Status == \"arrived\" or Status == \"end\" then\n\t            Goal.subgoal, Goal.createdAt = \"HOLD\", Now\n\t        end\n\t        return\n\t    end\n\t    local Mob = Brain.mobHit\n\t    if Mob and Now - Mob.at < Tuning.MobMemory then\n\t        local Root: BasePart = Entity.character.RootPart\n\t        local Away: Vector3 = (Root.Position - Mob.position) * Planar\n\t        Coast(Root.Position + (Away.Magnitude > 0.1 and Away.Unit or Root.CFrame.LookVector * Planar) * Tuning.MobClearance, Now, DeltaTime)\n\t    elseif Goal.covered and Goal.position then\n\t        Coast(Goal.position, Now, DeltaTime)\n\t        Build.Screen(Now)\n\t    else\n\t        Hold(Now, DeltaTime)\n\t        Build.Screen(Now)\n\t    end\n\t    if Now - Goal.createdAt >= Tuning.WaitLimit then\n\t        Finish(Goal, Now, true, \"Wait elapsed\")\n\t    end\n\tend\n\t\n\tlocal function Camp(Goal, Now: number, DeltaTime: number)\n\t    if Goal.subgoal == \"APPROACH\" then\n\t        local Status: string = Approach(Goal, Goal.position, 4, Now, DeltaTime)\n\t        if Status == \"arrived\" or Status == \"end\" then\n\t            Goal.subgoal = \"HOLD\"\n\t        end\n\t        return\n\t    end\n\t    Hold(Now, DeltaTime)\n\t    local Record = Goal.camper\n\t    if Record.alive and not Record.protected then\n\t        Finish(Goal, Now, true, `{Record.name} respawned`)\n\t    elseif not Record.alive and Now > (Record.respawnAt or Now) + Tuning.CampPatience then\n\t        Finish(Goal, Now, false, \"The respawn did not show up\")\n\t    end\n\tend\n\t\n\tlocal Handlers = {\n\t    DESTROY_BED = AttackBed,\n\t    ELIMINATE_PLAYER = Engage,\n\t    DEFEND_BED = Engage,\n\t    PROTECT_BED = Protect,\n\t    COLLECT_RESOURCE = Collect,\n\t    BUY_UPGRADE = Buy,\n\t    RETREAT = Withdraw,\n\t    SCOUT = Scout,\n\t    WAIT = Idle,\n\t    CAMP_SPAWN = Camp\n\t}\n\t\n\tlocal function Finishing(Now: number)\n\t    local Me = World.self\n\t    local Goal = Brain.goal\n\t    local Stood = if Brain.stand and Now - Brain.stoodAt < Tuning.DuelDelay then Brain.stand else nil\n\t    local Record = Goal and Goal.subgoal == \"FIGHT\" and Goal.record or Stood\n\t    if not Record then\n\t        local Nearest: number = Reach()\n\t        for _, v: any in World.enemies do\n\t            local Distance: number = if v.alive and v.position then (LivePosition(v) - Me.position).Magnitude else math.huge\n\t            if Distance <= Nearest then\n\t                Record, Nearest = v, Distance\n\t            end\n\t        end\n\t    end\n\t    local Root: BasePart? = Record and Record.alive and not Record.protected and RootOf(Record)\n\t    if not Root or (Root.Position - Me.position).Magnitude > (if Stood == Record then Tuning.EngageRange else Reach()) or #World.respawns > 0 then\n\t        return false\n\t    end\n\t    local Body: Instance? = Root.Parent\n\t    Record.health = Body and Body:GetAttribute(\"Health\") or Record.health\n\t    local _, Count, _, Kill = CombatEstimate(Record, Record.position, Now)\n\t    if Count > 0 then\n\t        return false\n\t    end\n\t    local Health: number = LocalPlayer.Character and LocalPlayer.Character:GetAttribute(\"Health\") or Me.health\n\t    local Damage: number = (Record.gearAt and Record.sword > 0 and Record.sword or Tuning.UnknownDamage) * (1 - Me.armor)\n\t    if Kill <= Tuning.FinishHits and math.ceil(Health / Damage) > Kill then\n\t        return true\n\t    end\n\t    local Dealt, Taken = Faded(Record, Now)\n\t    local Pace: number = math.clamp((Dealt + (if Assisted() then Tuning.DuelEdge else 1) * Tuning.LedgerPrior) / (Taken + Tuning.LedgerPrior), 0.5, 2.5)\n\t    local Lead: number = (if World.match.ownBed == false then Tuning.DuelLead else -Tuning.DuelLead) - (if Stood == Record then Tuning.DuelSlack else 0)\n\t    if math.ceil(Health / (Damage * (Record.harm or 1))) * Pace - Kill < Lead then\n\t        return false\n\t    end\n\t    Brain.stand, Brain.stoodAt = Record, Now\n\t    return true\n\tend\n\t\n\tlocal function Gate(Now: number)\n\t    local Me = World.self\n\t    local RecoverRatio: number = math.min(math.max(Recover.Value, Health.Value + 10) / 100, 1)\n\t    local Shot: number = if Now - (Brain.shotAt or -math.huge) < Tuning.SnipeMemory then Tuning.ShotSurvival else 0\n\t    local Burst: number = if Now - (Brain.burstAt or -math.huge) < Tuning.BurstMemory then Tuning.BurstSurvival else 0\n\t    local Knee: number = math.min(Health.Value / 100 + math.max(Shot, Burst), RecoverRatio - 0.05)\n\t    if World.match.ownBed == false then\n\t        Knee = math.max(Knee, RecoverRatio - 0.05)\n\t    end\n\t    local Nearest: number = NearestEnemy(Me.position)\n\t    local WasRetreating: boolean = Brain.retreating\n\t    if not WasRetreating and Me.ratio <= Knee and Nearest <= 60 and not Finishing(Now) then\n\t        Brain.retreating, Brain.retreatAt = true, Now\n\t    elseif WasRetreating and (Me.ratio >= RecoverRatio or Nearest > 60 and Now - Brain.retreatAt > Tuning.RetreatLimit or Now - Brain.retreatAt > Tuning.DuelDelay and Escape(Now) < 1 and Finishing(Now)) then\n\t        Brain.retreating = false\n\t    end\n\t    if WasRetreating ~= Brain.retreating then\n\t        MarkDirty(Brain.retreating and \"Health at or below the retreat threshold\" or \"Recovered\")\n\t    end\n\tend\n\t\n\tlocal function Unstick(Goal, Now: number)\n\t    local Root: BasePart = Entity.character.RootPart\n\t    Goal.stage += 1\n\t    Goal.anchorAt = Now\n\t    local Toward: Vector3 = Goal.position or Root.Position\n\t    Brain.failure = `stalled, recovery stage {Goal.stage}`\n\t    if Goal.stage == 1 then\n\t        Agent:Invalidate(\"Stalled, replanning\")\n\t    elseif Goal.stage == 2 then\n\t        local Flat: Vector3 = (Toward - Root.Position) * Planar\n\t        local Ahead: Vector3 = Root.Position + (Flat.Magnitude > 0.1 and Flat.Unit * 3 or Vector3.zero) - Vector3.new(0, Entity.character.HipHeight - 1.5, 0)\n\t        Agent.Memory:Route(Navigation.WorldToGrid(Ahead), \"stuck\", Now)\n\t        Agent:Invalidate(\"Stalled again, avoiding the cell ahead\")\n\t    elseif Goal.stage == 3 then\n\t        if not Breakout(Toward, Now) then\n\t            Agent:Invalidate(\"Stalled with nothing to break\")\n\t        end\n\t    elseif Goal.stage == 4 then\n\t        if not Rise(Now) and not Pillar(Now, 2) then\n\t            Agent:Invalidate(\"Stalled with no vertical escape\")\n\t        end\n\t    else\n\t        Fail(Goal, Now, \"Stalled through every recovery stage\")\n\t        return\n\t    end\n\t    Motion.leg = nil\n\tend\n\t\n\tlocal function Monitor(Now: number)\n\t    Gate(Now)\n\t    local Goal = Brain.goal\n\t    if not Goal then\n\t        return\n\t    end\n\t    if not Valid(Goal) then\n\t        Finish(Goal, Now, false, \"Objective no longer exists\")\n\t        return\n\t    end\n\t\n\t    local Root: BasePart = Entity.character.RootPart\n\t    if Goal.kind == \"DESTROY_BED\" then\n\t        Goal.cover = Senses.Cover(Goal.bed.part.Position)\n\t    end\n\t    if not Goal.anchor or (Root.Position - Goal.anchor).Magnitude > Tuning.StuckDistance then\n\t        Goal.anchor, Goal.anchorAt = Root.Position, Now\n\t    end\n\t    if Goal.subgoal ~= Goal.measured then\n\t        Goal.measured, Goal.best, Goal.lastProgressAt = Goal.subgoal, Measure(Goal, Root), Now\n\t    else\n\t        local Value: number = Measure(Goal, Root)\n\t        if Value < Goal.best - Tuning.ProgressStep then\n\t            Goal.best, Goal.lastProgressAt, Goal.faults, Goal.stage = Value, Now, 0, 0\n\t        end\n\t    end\n\t\n\t    if Goal.kind == \"DESTROY_BED\" then\n\t        if Goal.subgoal == \"BREAK\" and Now - Goal.lastProgressAt > Tuning.BreakStall then\n\t            Fail(Goal, Now, \"Bed is not breaking\")\n\t            return\n\t        end\n\t    elseif Goal.record then\n\t        local Record = Goal.record\n\t        local Distance: number = (LivePosition(Record) - Root.Position).Magnitude\n\t        local Aloft: boolean = Motion.aerial ~= nil and Motion.aerial.record == Record\n\t        Goal.position = Intercept(Record)\n\t        Goal.direct = if Distance <= Tuning.DisengageRange and not Aloft then Direct(Root.Position, LivePosition(Record)) else nil\n\t        Goal.sight = if Goal.direct == false or Aloft then Visible(Record) else nil\n\t        local Post: Vector3? = Goal.post\n\t        local Hitting: boolean = Attacking(Record, Now)\n\t        local Pressing: boolean = Hitting and Distance <= Reach() + Tuning.ContestMargin\n\t        if Post and not Pressing and (((Root.Position - Post) * Planar).Magnitude > Tuning.Leash or not Hitting and (Distance > Tuning.EngageRange or ((LivePosition(Record) - Post) * Planar).Magnitude > Tuning.Leash)) then\n\t            Record.releasedAt = Now\n\t            Finish(Goal, Now, false, \"Threat left combat range\")\n\t            return\n\t        end\n\t        if Goal.subgoal == \"CHASE\" then\n\t            if Distance < Goal.closest - 3 then\n\t                Goal.closest, Goal.closestAt = Distance, Now\n\t            end\n\t            if Record.falling then\n\t                Finish(Goal, Now, false, \"Target is falling into the void\")\n\t                return\n\t            end\n\t            local Patience: number = Tuning.ChaseStall + math.min(Goal.startDistance / math.max(World.self.speed, 1), Tuning.ChasePatience)\n\t            if Now - Goal.closestAt > Patience or Now - Goal.chaseAt > Tuning.ChaseTimeout + Patience - Tuning.ChaseStall and Distance > Goal.startDistance * 0.6 then\n\t                Record.chaseFailures, Record.chaseFailedAt = Record.chaseFailures + 1, Now\n\t                Fail(Goal, Now, \"Chase is not closing the distance\")\n\t                return\n\t            end\n\t        elseif Goal.subgoal == \"FIGHT\" then\n\t            local Chance: number = CombatEstimate(Record, Record.position, Now)\n\t            Goal.chance = Chance\n\t            if Chance >= 0.5 then\n\t                Goal.commitUntil = math.max(Goal.commitUntil, Now + 1)\n\t            elseif Chance < 0.3 and World.self.ratio < (Goal.startRatio or 1) - 0.25 then\n\t                MarkDirty(\"Fight turning against us\")\n\t            end\n\t            if not Aloft and Now - Goal.lastProgressAt > Tuning.TightenTime and Now - (Goal.tightenedAt or 0) > Tuning.TightenTime and Goal.radius and Goal.radius > Tuning.MinOrbit then\n\t                Goal.radius = math.max(Goal.radius - Tuning.TightenStep, Tuning.MinOrbit)\n\t                Goal.tightenedAt = Now\n\t                Report(`no damage landing, tightening orbit to {Goal.radius} studs`)\n\t            end\n\t            if Now - Goal.lastProgressAt > Tuning.FightStall then\n\t                Record.combatFailures += 1\n\t                Record.lostAt = Now\n\t                Fail(Goal, Now, \"Fight made no progress\")\n\t                return\n\t            end\n\t        end\n\t    end\n\t\n\t    local Moving: boolean = Goal.subgoal == \"APPROACH\" or Goal.subgoal == \"CHASE\" or Goal.subgoal == \"PATH\" and Goal.best > -50\n\t    if Moving and not Routing.request and not Motion.glide and not Motion.breaking and not Motion.leap and not Motion.flight and Now - Goal.anchorAt > Tuning.StuckTime then\n\t        Unstick(Goal, Now)\n\t    elseif Now - Goal.lastProgressAt > (Tuning.Timeouts[Goal.kind] or 20) then\n\t        Fail(Goal, Now, \"Watchdog, no progress\")\n\t    end\n\tend\n\t\n\tlocal function Emergency(Now: number, DeltaTime: number)\n\t    local Root: BasePart = Entity.character.RootPart\n\t    if Motion.flight then\n\t        Flight.Step(Now, DeltaTime)\n\t        return true\n\t    end\n\t    if Motion.leap then\n\t        Leap.Step(Now, DeltaTime)\n\t        return true\n\t    end\n\t    if Motion.sky then\n\t        StepSky(Now, DeltaTime)\n\t        return true\n\t    end\n\t    if Motion.glide then\n\t        StepGlide(Now, DeltaTime)\n\t        return true\n\t    end\n\t    if Motion.pillar then\n\t        StepPillar(Now)\n\t        return true\n\t    end\n\t    if Motion.barricade and Motion.barricade.stand then\n\t        Build.Walk(Now, DeltaTime)\n\t        return true\n\t    end\n\t    if Motion.breaking then\n\t        local Breaking = Motion.breaking\n\t        if not Senses.Block(Breaking.grid) or Now > Breaking.deadline then\n\t            Motion.breaking = nil\n\t            Agent:Invalidate(\"Obstruction handled\")\n\t        elseif Now >= Motion.nextBreak then\n\t            Motion.nextBreak = Now + Tuning.AttackInterval\n\t            Senses.Break(Breaking.grid)\n\t        end\n\t        return true\n\t    end\n\t    if Motion.commit then\n\t        if StepLeg(Motion.commit, Now, DeltaTime) ~= \"moving\" then\n\t            Motion.commit = nil\n\t            if not Senses.Ground(Root.Position) then\n\t                Motion.nextLand = 0\n\t                Land(Now)\n\t            end\n\t            local Plan = Agent:Current()\n\t            if Plan and not Plan.Expired then\n\t                Plan:Resume(Root.Position, Motion.velocity, true)\n\t            end\n\t        end\n\t        return true\n\t    end\n\t\n\t    local Airborne, Falling = Senses.Drop(Root, Entity.character.Humanoid)\n\t    local Stranded: boolean = not Airborne and not Senses.Ground(Root.Position) and (Entity.character.Humanoid.FloorMaterial ~= Enum.Material.Air or not workspace:Raycast(Root.Position, Vector3.new(0, -Tuning.SkyDrop, 0), Senses.Params))\n\t    if Falling and getWool() and Clutch() then\n\t        return true\n\t    elseif (Airborne or Stranded) and Now - Motion.controlledAt > 0.1 then\n\t        return Land(Now) or Flight.Rescue(Now)\n\t    end\n\t    return false\n\tend\n\t\n\tlocal function Describe(Now: number)\n\t    local Goal, Me, Plan = Brain.goal, World.self, Agent:Current()\n\t    local Alternative = Brain.alternative\n\t    Snapshot.Goal = Goal and Goal.kind or \"NONE\"\n\t    Snapshot.Target = Goal and Goal.label or nil\n\t    Snapshot.Action = Goal and Goal.subgoal or nil\n\t    Snapshot.Score = Goal and Goal.score or 0\n\t    Snapshot.Alternative = Alternative and `{Alternative.kind} {Alternative.label} = {string.format(\"%.1f\", Alternative.score or 0)}` or nil\n\t    Snapshot.Suspended = Goal and Goal.resume and `{Goal.resume.kind} {Goal.resume.label}` or nil\n\t    Snapshot.Health = math.floor((Me.ratio or 0) * 100)\n\t    Snapshot.Threat = Me.position and (ThreatNear(Me.position, Tuning.ContactRange, Now)) or 0\n\t    Snapshot.RouteCost = Plan and Plan.Cost or 0\n\t    Snapshot.BuildCost = Plan and Plan:Pending() or 0\n\t    Snapshot.Progress = Goal and math.floor(Progress(Goal) * 100) or 0\n\t    Snapshot.PlanRevision = Agent.PlanRevision\n\t    Snapshot.GoalRevision = Brain.revision\n\t    Snapshot.Phase = World.match.phase\n\t    Snapshot.Oscillation = Brain.oscillation\n\t    Snapshot.Retreating = Brain.retreating\n\t    Snapshot.LastFailure = Brain.failure\n\t    Snapshot.Reason = Goal and Goal.reason or Brain.reason\n\t    return Snapshot\n\tend\n\t\n\tlocal function Summarize(Now: number)\n\t    if Now < Brain.nextSummary then\n\t        return\n\t    end\n\t    Brain.nextSummary = Now + Tuning.SummaryInterval\n\t    local State = Describe(Now)\n\t    if Debug.Enabled then\n\t        warn(string.format(\"[catvape] autowin goal=%s target=%s action=%s score=%.1f alt=%s health=%d%% threat=%.0f route=%.1f blocks=%d progress=%d%% revision=%d/%d phase=%s failure=%s reason=%s\",\n\t            State.Goal, tostring(State.Target), tostring(State.Action), State.Score, tostring(State.Alternative), State.Health, State.Threat, State.RouteCost, State.BuildCost,\n\t            State.Progress, State.PlanRevision, State.GoalRevision, State.Phase, tostring(State.LastFailure), tostring(State.Reason)))\n\t    end\n\tend\n\t\n\tlocal function Watch(Now: number)\n\t    local Thinking = Brain.thinking\n\t    if type(Thinking) == \"table\" and Now - Thinking.at > Tuning.ThinkStuck then\n\t        Brain.thinking, Brain.epoch = false, Brain.epoch + 1\n\t        Fault(\"decision stalled\", `no decision for {math.floor(Now - Thinking.at)}s, restarting it`)\n\t    end\n\t    if Routing.request and Now - Routing.at > Tuning.RouteStuck then\n\t        CancelRoute()\n\t        Fault(\"route stalled\", `route request open for {math.floor(Now - Routing.at)}s, cancelled it`)\n\t    end\n\t\n\t    local Root: BasePart = Entity.character.RootPart\n\t    if not Brain.still or (Root.Position - Brain.still).Magnitude > Tuning.StuckDistance then\n\t        Brain.still, Brain.stillAt = Root.Position, Now\n\t        return\n\t    end\n\t    if Now - Brain.stillAt < Tuning.StallTime then\n\t        return\n\t    end\n\t    Brain.stillAt = Now\n\t    local Goal = Brain.goal\n\t    if Goal and (Goal.kind == \"RETREAT\" or Goal.kind == \"WAIT\" and Goal.position or Goal.subgoal == \"BREAK\" or Goal.subgoal == \"COLLECT\" or Goal.subgoal == \"BUY\" or Goal.subgoal == \"COVER\") then\n\t        return\n\t    end\n\t    local Plan = Agent:Current()\n\t    local Options: {string} = {}\n\t    for i: number = 1, math.min(#Brain.candidates, 3) do\n\t        local v = Brain.candidates[i]\n\t        table.insert(Options, `{v.kind} {v.label} {string.format(\"%.1f\", v.score or 0)}`)\n\t    end\n\t    local Flags: {string} = {}\n\t    for _, v: string in {\"leg\", \"commit\", \"glide\", \"pillar\", \"breaking\", \"orbit\", \"sky\", \"leap\", \"flight\"} do\n\t        if Motion[v] then\n\t            table.insert(Flags, v)\n\t        end\n\t    end\n\t    local Route: string = Plan and `{Plan.Cursor}/{#Plan.Waypoints}{Plan.Expired and \" expired\" or \"\"}{Goal and Plan.TargetId ~= Goal.key and \" other\" or \"\"}` or \"none\"\n\t    Fault(\"stalled\", `no movement for {Tuning.StallTime}s | route {Route} | request {Routing.request and \"open\" or \"none\"} | thinking {Brain.thinking and \"yes\" or \"no\"} | motion {#Flags > 0 and table.concat(Flags, \",\") or \"none\"} | top {table.concat(Options, \"; \")}`)\n\tend\n\t\n\tfunction Gait.Stop()\n\t    if Gait.walk and Gait.walk.IsPlaying then\n\t        Gait.walk:Stop(Tuning.GaitFade)\n\t        Gait.run:Stop(Tuning.GaitFade)\n\t    end\n\tend\n\t\n\tfunction Gait.Release()\n\t    Gait.Stop()\n\t    local Walk, Run = Gait.walk, Gait.run\n\t    if Walk and Run then\n\t        task.delay(Tuning.GaitFade, function()\n\t            Walk:Destroy()\n\t            Run:Destroy()\n\t        end)\n\t    end\n\t    Gait.humanoid, Gait.walk, Gait.run, Gait.dampening, Gait.last, Gait.speed = nil, nil, nil, nil, nil, nil\n\tend\n\t\n\tfunction Gait.Load(Humanoid: Humanoid)\n\t    local Animator: Animator? = Humanoid:FindFirstChildOfClass(\"Animator\")\n\t    local Animate: Instance? = Humanoid.Parent and Humanoid.Parent:FindFirstChild(\"Animate\")\n\t    local Walk: Instance? = Animate and Animate:FindFirstChild(\"walk\")\n\t    local Run: Instance? = Animate and Animate:FindFirstChild(\"run\")\n\t    local WalkAnimation: Animation? = Walk and Walk:FindFirstChildOfClass(\"Animation\")\n\t    local RunAnimation: Animation? = Run and Run:FindFirstChildOfClass(\"Animation\")\n\t    if not Animator or not WalkAnimation or not RunAnimation then\n\t        return\n\t    end\n\t\n\t    local WalkLoaded, WalkTrack = pcall(Animator.LoadAnimation, Animator, WalkAnimation)\n\t    local RunLoaded, RunTrack = pcall(Animator.LoadAnimation, Animator, RunAnimation)\n\t    if not WalkLoaded or not RunLoaded then\n\t        return\n\t    end\n\t\n\t    Gait.Release()\n\t    WalkTrack.Priority, RunTrack.Priority = Enum.AnimationPriority.Movement, Enum.AnimationPriority.Movement\n\t    Gait.humanoid, Gait.walk, Gait.run, Gait.speed = Humanoid, WalkTrack, RunTrack, 0\n\t    Gait.dampening = Animate:FindFirstChild(\"ScaleDampeningPercent\")\n\tend\n\t\n\tfunction Gait.Blend(Speed: number, Humanoid: Humanoid)\n\t    local Dampening: NumberValue? = Gait.dampening\n\t    local Height: number = if not Humanoid.AutomaticScalingEnabled then 1 elseif Dampening then 1 + (Humanoid.HipHeight - 2) * Dampening.Value / 2 else Humanoid.HipHeight / 2\n\t    local Pace: number = Speed / 16 * 1.25 / Height\n\t    if Pace <= 0.5 then\n\t        return 1, 0.0001, Pace / 0.5, Pace\n\t    elseif Pace < 1 then\n\t        local Mix: number = (Pace - 0.5) / 0.5\n\t        return 1 - Mix, Mix, 1, 1\n\t    end\n\t    return 0.0001, 1, Pace / 0.5, Pace\n\tend\n\t\n\tfunction Gait.Step(DeltaTime: number)\n\t    local Humanoid: Humanoid? = Entity.isAlive and Entity.character.Humanoid or nil\n\t    if not Humanoid or not Brain.active then\n\t        Gait.Stop()\n\t        Gait.last, Gait.speed = nil, 0\n\t        return\n\t    end\n\t    if Gait.humanoid ~= Humanoid then\n\t        Gait.Load(Humanoid)\n\t        if Gait.humanoid ~= Humanoid then\n\t            return\n\t        end\n\t    end\n\t\n\t    local Root: BasePart = Entity.character.RootPart\n\t    local Measured: number = Gait.last and ((Root.Position - Gait.last) * Planar).Magnitude / math.max(DeltaTime, 1 / 240) or 0\n\t    Gait.last = Root.Position\n\t    if Measured <= TravelSpeed() * 2 then\n\t        Gait.speed += (Measured - Gait.speed) * math.min(DeltaTime * Tuning.GaitResponse, 1)\n\t    end\n\t\n\t    if Gait.speed <= Tuning.GaitThreshold or not Senses.Ground(Root.Position) then\n\t        Gait.Stop()\n\t        return\n\t    end\n\t\n\t    local WalkWeight, RunWeight, WalkSpeed, RunSpeed = Gait.Blend(Gait.speed, Humanoid)\n\t    if Gait.walk.IsPlaying then\n\t        Gait.walk:AdjustWeight(WalkWeight)\n\t        Gait.run:AdjustWeight(RunWeight)\n\t        Gait.walk:AdjustSpeed(WalkSpeed)\n\t        Gait.run:AdjustSpeed(RunSpeed)\n\t    else\n\t        Gait.walk:Play(Tuning.GaitFade, WalkWeight, WalkSpeed)\n\t        Gait.run:Play(Tuning.GaitFade, RunWeight, RunSpeed)\n\t    end\n\tend\n\t\n\tlocal function Step(Now: number, DeltaTime: number)\n\t    local Character: Model? = LocalPlayer.Character\n\t    local Root = Entity.isAlive and Entity.character.RootPart\n\t    local Alive: boolean = if Root and Character then (Character:GetAttribute(\"Health\") or 0) > 0 else false\n\t    local Owned: boolean = Root and isnetworkowner(Root) or false\n\t    if Alive and not Owned and store.matchState == 1 and Brain.active then\n\t        if not Motion.foreign then\n\t            Motion.foreign = Now\n\t            Fault(\"server control\", \"the server is moving the character, holding the objective until control returns\")\n\t        end\n\t        return\n\t    end\n\t    if Motion.foreign and Alive and Owned then\n\t        Motion.foreign = nil\n\t        Motion.leg, Motion.commit, Motion.orbit, Motion.written, Motion.sky, Motion.aerial = nil, nil, nil, nil, nil, nil\n\t        Leap.Stop()\n\t        Flight.Stop()\n\t        local Plan = Agent:Current()\n\t        if Plan and not Plan.Expired then\n\t            Plan:Resume(Root.Position, Root.AssemblyLinearVelocity, not Senses.Ground(Root.Position))\n\t        end\n\t    end\n\t    if store.matchState == 0 or store.matchState == 2 or not Alive or not Owned then\n\t        if Brain.active then\n\t            Brain.active, Motion.foreign = false, nil\n\t            local Goal = Brain.goal\n\t            if Goal and not Alive then\n\t                Fail(Goal, Now, \"Died during the objective\")\n\t            elseif Goal then\n\t                Brain.goal = nil\n\t                Report(`paused {Goal.kind} {Goal.label}`)\n\t            end\n\t            Brain.epoch += 1\n\t            CancelRoute()\n\t            Motion.leg, Motion.commit, Motion.glide, Motion.orbit, Motion.breaking, Motion.pillar, Motion.sky, Motion.barricade, Motion.aerial = nil, nil, nil, nil, nil, nil, nil, nil, nil\n\t            Leap.Stop()\n\t            Flight.Stop()\n\t            Flight.Claim(false)\n\t            AutoWin.Climb = nil\n\t        end\n\t        return\n\t    end\n\t    if not Brain.active then\n\t        Brain.active = true\n\t        Brain.epoch += 1\n\t        Motion.written = nil\n\t        MarkDirty(\"Resumed control\")\n\t    end\n\t\n\t    Senses.Filter()\n\t    if Now >= Brain.nextObserve then\n\t        Brain.nextObserve = Now + Tuning.ObserveInterval\n\t        local Tracked, Problem = xpcall(Observe, debug.traceback, Now)\n\t        if Tracked then\n\t            Tracked, Problem = xpcall(Monitor, debug.traceback, Now)\n\t        end\n\t        if not Tracked then\n\t            Fault(\"tracking failed\", tostring(Problem))\n\t        end\n\t        Tracked, Problem = xpcall(Watch, debug.traceback, Now)\n\t        if not Tracked then\n\t            Fault(\"watchdog failed\", tostring(Problem))\n\t        end\n\t    end\n\t    if not Brain.thinking and (Brain.dirty and Now - Brain.thoughtAt >= Tuning.ThinkFloor or Now >= Brain.nextThink) then\n\t        Think(Now)\n\t    end\n\t    if not Emergency(Now, DeltaTime) then\n\t        local Goal = Brain.goal\n\t        if Goal then\n\t            Handlers[Goal.kind](Goal, Now, DeltaTime)\n\t        else\n\t            Hold(Now, DeltaTime)\n\t        end\n\t    end\n\t    if Motion.barricade then\n\t        Build.StepBarricade(Now)\n\t    end\n\t    AutoWin.Climb = if Motion.leg then Motion.leg.climb else nil\n\t    Flight.Claim(Motion.flight ~= nil or Motion.leap ~= nil or Motion.glide ~= nil or Motion.sky ~= nil or Motion.pillar ~= nil or Motion.aerial ~= nil and Motion.aerial.up == true)\n\t    Summarize(Now)\n\tend\n\t\n\tAutoWin = vape.Categories.Utility:CreateModule({\n\t    Name = \"AutoWin\",\n\t    Tags = {\"Experimental\"},\n\t    Function = function(Callback: boolean)\n\t        if Callback then\n\t            Reset()\n\t            Agent = NewAgent()\n\t            Senses = Agent.Interface\n\t            AutoWin.Brain, AutoWin.Agent, AutoWin.World, AutoWin.Snapshot, AutoWin.Motion = Brain, Agent, World, Snapshot, Motion\n\t\n\t            local Launched = bedwars.SyncEvents.ProjectileLaunched:connect(function(Event)\n\t                Senses.Track(Event)\n\t                Aimed(Event)\n\t            end)\n\t            AutoWin:Clean(function()\n\t                Launched:Destroy()\n\t            end)\n\t            AutoWin:Clean(vapeEvents.PlaceBlockEvent.Event:Connect(function(BlockTable)\n\t                if BlockTable.player ~= LocalPlayer then\n\t                    Senses.Obstacle(BlockTable.blockRef.blockPosition * 3)\n\t                end\n\t            end))\n\t            AutoWin:Clean(vapeEvents.BedwarsBedBreak.Event:Connect(function(BedTable)\n\t                local Now: number = os.clock()\n\t                local Team = type(BedTable) == \"table\" and BedTable.brokenBedTeam and tostring(BedTable.brokenBedTeam.id)\n\t                if Team then\n\t                    World.broken[Team] = Now\n\t                end\n\t                Senses.Mark(\"beds\")\n\t                local Goal = Brain.goal\n\t                if Goal and Goal.kind == \"DESTROY_BED\" and (Team == Goal.team or not Goal.bed.part.Parent) then\n\t                    Finish(Goal, Now, true, \"Bed destroyed\")\n\t                end\n\t                MarkDirty(\"Bed destroyed\")\n\t            end))\n\t            AutoWin:Clean(vapeEvents.EntityDeathEvent.Event:Connect(function(DeathTable)\n\t                local Now: number = os.clock()\n\t                if DeathTable.entityInstance == LocalPlayer.Character then\n\t                    local Killer: Player? = DeathTable.fromEntity and Players:GetPlayerFromCharacter(DeathTable.fromEntity)\n\t                    local Culprit = Killer and World.enemies[tostring(Killer.UserId)]\n\t                    if Culprit then\n\t                        Culprit.killedAt = Now\n\t                    end\n\t                    if Brain.goal then\n\t                        Fail(Brain.goal, Now, \"Died during the objective\")\n\t                    end\n\t                    if World.self.position then\n\t                        Agent.Memory:Route(Navigation.WorldToGrid(World.self.position - Vector3.new(0, 1.5, 0)), \"death\", Now)\n\t                    end\n\t                    Brain.epoch += 1\n\t                    return\n\t                end\n\t\n\t                local Killed: Player? = DeathTable.entityInstance and Players:GetPlayerFromCharacter(DeathTable.entityInstance)\n\t                local Record = Killed and World.enemies[tostring(Killed.UserId)]\n\t                if not Record then\n\t                    return\n\t                end\n\t                Record.alive, Record.corpse, Record.root, Record.deathAt, Record.lastInteraction, Record.absent = false, Record.root, nil, Now, Now, false\n\t                Record.respawnAt = not DeathTable.finalKill and Now + (tonumber(DeathTable.respawnDuration) or Tuning.RespawnDelay) or nil\n\t                local Goal = Brain.goal\n\t                if Goal and Goal.record == Record then\n\t                    Finish(Goal, Now, true, DeathTable.fromEntity == LocalPlayer.Character and \"Killed the target\" or \"Target died\")\n\t                end\n\t                MarkDirty(\"Enemy died\")\n\t            end))\n\t            AutoWin:Clean(vapeEvents.EntityDamageEvent.Event:Connect(function(DamageTable)\n\t                local Now: number = os.clock()\n\t                local Melee: boolean = bedwars.DamageType == nil or DamageTable.damageType == bedwars.DamageType.SWORD\n\t                if DamageTable.fromEntity == LocalPlayer.Character and DamageTable.entityInstance ~= LocalPlayer.Character then\n\t                    local Victim: Player? = DamageTable.entityInstance and Players:GetPlayerFromCharacter(DamageTable.entityInstance)\n\t                    local Target = Victim and World.enemies[tostring(Victim.UserId)]\n\t                    if Target and Melee then\n\t                        Tally(Target, true, tonumber(DamageTable.damage), Now)\n\t                    end\n\t                    return\n\t                end\n\t                if DamageTable.entityInstance ~= LocalPlayer.Character or not Entity.isAlive or not Brain.active then\n\t                    return\n\t                end\n\t                if Leap.Recoil(DamageTable) then\n\t                    return\n\t                end\n\t                if bedwars.DamageType and DamageTable.damageType == bedwars.DamageType.SUFFOCATE then\n\t                    if Now >= (Motion.suffocatedAt or 0) then\n\t                        Motion.suffocatedAt = Now + 0.5\n\t                        Suffocating(Now)\n\t                    end\n\t                    return\n\t                end\n\t\n\t                local Source: Instance? = DamageTable.fromEntity\n\t                local Attacker: Player? = Source and Players:GetPlayerFromCharacter(Source)\n\t                local Record = Attacker and World.enemies[tostring(Attacker.UserId)]\n\t                if Record then\n\t                    local Fresh: boolean = not Attacking(Record, Now)\n\t                    local Harm: number = Record.harm or 1\n\t                    Record.hitAt = Now\n\t                    if Melee then\n\t                        local Where: Vector3? = LivePosition(Record)\n\t                        local Gap: number = Where and (Where - Entity.character.RootPart.Position).Magnitude or math.huge\n\t                        Tally(Record, false, tonumber(DamageTable.damage), Now)\n\t                        if Gap <= Tuning.ReachCap then\n\t                            Record.reach = math.max(Record.reach or 0, Gap)\n\t                            Record.far = (Record.far or 0) + (Gap > Tuning.LongReach and 1 or 0)\n\t                        end\n\t                    end\n\t                    if Fresh then\n\t                        MarkDirty(\"Under attack\")\n\t                    elseif (Record.harm or 1) > Harm * 1.25 then\n\t                        MarkDirty(\"Hits harder than its gear\")\n\t                    end\n\t                    if bedwars.DamageType and DamageTable.damageType == bedwars.DamageType.PROJECTILE then\n\t                        Brain.shotAt = Now\n\t                    end\n\t                    local Shooter: Vector3? = LivePosition(Record)\n\t                    if Shooter and not Melee and (Shooter - Entity.character.RootPart.Position).Magnitude > Tuning.SnipeRange then\n\t                        local Goal = Brain.goal\n\t                        local Subgoal: string? = Goal and Goal.subgoal\n\t                        Record.shotAt = Now\n\t                        local Projectile: boolean = bedwars.DamageType ~= nil and DamageTable.damageType == bedwars.DamageType.PROJECTILE\n\t                        if Projectile and (not Goal or Goal.kind == \"WAIT\" or Subgoal == \"HOLD\" or Subgoal == \"COLLECT\" or Subgoal == \"BUY\" or Subgoal == \"BREAK\" or Subgoal == \"COVER\") then\n\t                            Build.Barricade(Shooter + Vector3.new(0, Tuning.EyeHeight, 0), Now)\n\t                        end\n\t                    end\n\t                elseif Source and not Attacker and (Source:IsA(\"Model\") or Source:IsA(\"BasePart\")) then\n\t                    Brain.mobHit = {at = Now, position = Source:IsA(\"Model\") and Source:GetPivot().Position or Source.Position}\n\t                end\n\t            end))\n\t            AutoWin:Clean(vapeEvents.GrapplingHookFunctions.Event:Connect(function(DataTable)\n\t                local State, Kit = Motion.leap, Leap.Kit()\n\t                if State and Kit then\n\t                    local Speed, Duration = Kit.Transit(DataTable)\n\t                    if Speed then\n\t                        Leap.Propel(State, Speed, Duration)\n\t                    end\n\t                end\n\t            end))\n\t            AutoWin:Clean(vapeEvents.InventoryAmountChanged.Event:Connect(function()\n\t                local Goal = Brain.goal\n\t                local Leg = Motion.leg or Motion.commit\n\t                if (not Goal or Goal.kind ~= \"COLLECT_RESOURCE\" and Goal.subgoal ~= \"COVER\") and not (Leg and Leg.bridging) and not Motion.pillar then\n\t                    MarkDirty(\"Inventory changed\")\n\t                end\n\t            end))\n\t            if Entity.Events then\n\t                AutoWin:Clean(Entity.Events.LocalAdded:Connect(function()\n\t                    MarkDirty(\"Respawned\")\n\t                end))\n\t            end\n\t\n\t            while AutoWin.Enabled do\n\t                local DeltaTime: number = task.wait()\n\t                if not AutoWin.Enabled then\n\t                    break\n\t                end\n\t                local Now: number = os.clock()\n\t                local Success, Error = xpcall(Step, debug.traceback, Now, DeltaTime)\n\t                if not Success then\n\t                    Fault(\"step failed\", tostring(Error))\n\t                    Brain.errors = if Now - (Brain.erroredAt or -math.huge) < Tuning.ErrorWindow then (Brain.errors or 0) + 1 else 1\n\t                    Brain.erroredAt = Now\n\t                    if Brain.errors >= 2 then\n\t                        Motion.leg, Motion.commit, Motion.glide, Motion.orbit, Motion.breaking, Motion.pillar, Motion.sky, Motion.barricade, Motion.aerial = nil, nil, nil, nil, nil, nil, nil, nil, nil\n\t                        Leap.Stop()\n\t                        Flight.Stop()\n\t                        Flight.Claim(false)\n\t                        AutoWin.Climb = nil\n\t                        pcall(Agent.Invalidate, Agent, \"Recovering from an error\")\n\t                    end\n\t                    if Brain.errors >= Tuning.ErrorBurst and Brain.goal then\n\t                        Brain.errors = 0\n\t                        pcall(Fail, Brain.goal, Now, \"Kept erroring, dropped it to recover\")\n\t                    end\n\t                end\n\t                Success, Error = xpcall(Gait.Step, debug.traceback, DeltaTime)\n\t                if not Success then\n\t                    Fault(\"walk animation failed\", tostring(Error))\n\t                end\n\t            end\n\t        else\n\t            Gait.Release()\n\t            Leap.Stop()\n\t            Flight.Stop()\n\t            Flight.Claim(false)\n\t            if Agent then\n\t                Agent:Destroy()\n\t            end\n\t            if Routing then\n\t                CancelRoute()\n\t            end\n\t            HideBlocks()\n\t            table.clear(PlacedMemo)\n\t            if Brain then\n\t                Brain.goal, Brain.epoch = nil, Brain.epoch + 1\n\t            end\n\t            AutoWin.Brain, AutoWin.Agent, AutoWin.World, AutoWin.Motion, AutoWin.Climb = nil, nil, nil, nil, nil\n\t        end\n\t    end,\n\t    Tooltip = \"Plays the match for you. It keeps weighing beds, kills, resources, upgrades and retreat against each other and commits to the best one as the match changes\"\n\t})\n\t\n\tBoost = AutoWin:CreateSlider({\n\t    Name = \"Move boost\",\n\t    Min = 2,\n\t    Max = 40,\n\t    Default = 2,\n\t    Suffix = function(Val: number)\n\t        return Val == 1 and \"stud\" or \"studs\"\n\t    end,\n\t    Tooltip = \"Added on top of your walk speed while it travels, anything much above 2 gets flagged by the anticheat\"\n\t})\n\tFlyTime = AutoWin:CreateSlider({\n\t    Name = \"Fly time\",\n\t    Min = 0,\n\t    Max = 2,\n\t    Default = 1.75,\n\t    Decimal = 100,\n\t    Suffix = function(Val: number)\n\t        return Val == 1 and \"second\" or \"seconds\"\n\t    end,\n\t    Tooltip = \"Longest it flies over a gap without placing blocks, it only bridges gaps it cannot cross in this time at its current speed, past 2 seconds gets flagged\"\n\t})\n\tHealth = AutoWin:CreateSlider({\n\t    Name = \"Health\",\n\t    Min = 1,\n\t    Max = 100,\n\t    Default = 40,\n\t    Suffix = \"%\",\n\t    Tooltip = \"Health where survival takes over. Below it, it retreats from nearby enemies by climbing onto something tall or pathing to the safest ground. Survival also takes over up to 15% sooner for a few seconds after an arrow hits you or after losing more than a third of your health within 1.5 seconds. Above it, lower health still makes risky fights and void routes steadily less attractive\"\n\t})\n\tRecover = AutoWin:CreateSlider({\n\t    Name = \"Recover health\",\n\t    Min = 1,\n\t    Max = 100,\n\t    Default = 70,\n\t    Suffix = \"%\",\n\t    Tooltip = \"Once retreating, it only goes back to its objectives after healing to this health percentage, always at least 10% above Health. Without a bed, it starts recovering five percentage points below this value when enemies are nearby, unless it can safely finish the current fight\"\n\t})\n\tStrafeRange = AutoWin:CreateSlider({\n\t    Name = \"Strafe range\",\n\t    Min = 1,\n\t    Max = 30,\n\t    Default = 18,\n\t    Suffix = function(Val: number)\n\t        return Val == 1 and \"stud\" or \"studs\"\n\t    end,\n\t    Tooltip = \"Distance kept while circling an opponent\"\n\t})\n\tDefendRange = AutoWin:CreateSlider({\n\t    Name = \"Defend range\",\n\t    Min = 0,\n\t    Max = 100,\n\t    Default = 40,\n\t    Suffix = function(Val: number)\n\t        return Val == 1 and \"stud\" or \"studs\"\n\t    end,\n\t    Tooltip = \"Enemies this close to a bed count as its defenders when it weighs attacking that bed, and enemies this close to your own bed are treated as intruders worth stopping\"\n\t})\n\tReserve = AutoWin:CreateSlider({\n\t    Name = \"Block reserve\",\n\t    Min = 0,\n\t    Max = 32,\n\t    Default = 8,\n\t    Tooltip = \"Blocks kept aside for clutching instead of being spent on the route\"\n\t})\n\tSettings.TargetRate = AutoWin:CreateSlider({\n\t    Name = \"Target Recheck Rate\",\n\t    Min = 0.5,\n\t    Max = 5,\n\t    Default = 1.5,\n\t    Decimal = 10,\n\t    Suffix = function(Val: number)\n\t        return Val == 1 and \"second\" or \"seconds\"\n\t    end,\n\t    Tooltip = \"Seconds between full rechecks of every bed, player, purchase and retreat option. Big events like being hit or a bed breaking still trigger a recheck right away\"\n\t})\n\tSettings.CombatRate = AutoWin:CreateSlider({\n\t    Name = \"Combat Update Rate\",\n\t    Min = 0.1,\n\t    Max = 1,\n\t    Default = 0.4,\n\t    Decimal = 100,\n\t    Suffix = function(Val: number)\n\t        return Val == 1 and \"second\" or \"seconds\"\n\t    end,\n\t    Tooltip = \"Seconds between its own sword swings, which is also how long it expects each hit of a fight to take. Only swings itself while Killaura is off, Killaura sets its own speed\"\n\t})\n\tSettings.BedRate = AutoWin:CreateSlider({\n\t    Name = \"Bed Update Rate\",\n\t    Min = 0.05,\n\t    Max = 1,\n\t    Default = 0.1,\n\t    Decimal = 100,\n\t    Suffix = function(Val: number)\n\t        return Val == 1 and \"second\" or \"seconds\"\n\t    end,\n\t    Tooltip = \"Seconds between bed break hits while it is in range. The server only accepts one about every 0.3 seconds, so faster just makes sure none are missed\"\n\t})\n\tBreakBed = AutoWin:CreateToggle({\n\t    Name = \"Break bed\",\n\t    Default = true,\n\t    Tooltip = \"Break the bed once it reaches it instead of only standing next to it\"\n\t})\n\tSettings.BedTower = AutoWin:CreateToggle({\n\t    Name = \"Bed Tower\",\n\t    Default = true,\n\t    Tooltip = \"When the bed it is going for sits too high to break from the ground, it builds a pillar right next to it until the bed is within reach, standing on any blocks already stacked there first so it only places what is missing. It never builds one for a bed it is not attacking or one it can reach by walking\"\n\t})\n\tCoverBed = AutoWin:CreateToggle({\n\t    Name = \"Cover bed\",\n\t    Default = true,\n\t    Tooltip = \"Wall off your own bed with wool while it is still standing, most urgently early in the match, and patch the cover when enemies break into it\"\n\t})\n\tAerialFight = AutoWin:CreateToggle({\n\t    Name = \"Aerial fight\",\n\t    Default = true,\n\t    Tooltip = \"Fights from above and behind the target, just outside its sword reach but inside yours, dropping to the ground for a split second every second so the anticheat does not flag the air time\"\n\t})\n\tLongJump = AutoWin:CreateToggle({\n\t    Name = \"Long jump\",\n\t    Default = true,\n\t    Tooltip = \"Uses a LongJump kit or item (dao dash, jade hammer, void axe, cat pounce, cannon, grapple, fireball, TNT) to fly straight to the farthest point on its route it can reach at LongJump's speed. It only launches when the flight path is clear, the drop at the end is safe and the flight fits in Fly time, uses fireballs and TNT only above 60 health, and never while the LongJump module itself is on\"\n\t})\n\tSkyTravel = AutoWin:CreateToggle({\n\t    Name = \"Sky travel\",\n\t    Default = true,\n\t    Tooltip = \"Flies in a straight line to anything 45+ studs away instead of walking and bridging, the way HighJump and Fly do by hand. It cruises at walk speed 8 studs above the ground ahead and touches down for a quarter second at least every 1.4 seconds, earlier when a stretch it cannot touch down on is coming, because the server takes control after about 2.4 seconds in the air. It never touches down more than 21 studs below its highest point since the last touchdown, since that is where the server starts dealing fall damage. It skips a flight whose stretch without a safe touchdown is too long to cross in that time, which rules out most long void gaps, lands early at the edge of a drop that would hurt and walks the rest, and walks out of a building through its doorway before taking off\"\n\t})\n\tSpeedrun = AutoWin:CreateToggle({\n\t    Name = \"Speedrun\",\n\t    Default = true,\n\t    Tooltip = \"Plays for the fastest win: rushes the nearest bed from the first second even with a wood sword, never covers or walks home to defend its own bed, skips team upgrades, and never farms a generator for gear, it only shops once kills or pickups have already paid for the item. Once every enemy bed is gone it plays the final kills normally again, farming gear, covering and defending its own bed\"\n\t})\n\tSettings.BuyBow = AutoWin:CreateToggle({\n\t    Name = \"Buy Bow & Arrows\",\n\t    Default = true,\n\t    Tooltip = \"Once it owns an iron sword and iron armor, it buys a bow and then enough arrows for the toughest enemy with iron it already has, such as iron picked up from kills, and only when that iron is not saved for more important gear. Off, it never buys them\"\n\t})\n\tDebug = AutoWin:CreateToggle({\n\t    Name = \"Debug\",\n\t    Tooltip = \"Warn on every goal change with its score, the best alternative and the reason, and print a goal, route and progress summary every 3 seconds. AutoWin.Snapshot holds the live decision state\"\n\t})\nend)\n\nRun(function()\n\tlocal Clutch\n\tlocal OnVoid\n\tlocal FallDamage\n\tlocal Accuracy = {}\n\tlocal Allowance\n\tlocal BlockFall\n\tlocal Blocks\n\tlocal Speed\n\tlocal SilentAim\n\tlocal ResetAngle\n\tlocal ReturnSlot\n\tlocal MoveDelay\n\tlocal FailDelay\n\tlocal Staircase\n\tlocal LimitBlocks\n\tlocal MaxBlocks\n\tlocal Blacklist\n\tlocal HeldOnly\n\tlocal Whitelist\n\tlocal Label: TextLabel?\n\tlocal Placed, LastPlace, LastDanger, Falling = 0, 0, 0, false\n\tlocal CatchCell, CatchUntil, CatchSeen, CatchTries = nil, 0, false, 0\n\tlocal Impulse, ImpulseUntil = Vector3.zero, 0\n\tlocal GroundY: number?\n\tlocal MaxDrop: number = 512\n\tlocal ReachCells: number = 3\n\tlocal CatchStuds: number = 14\n\tlocal BridgeStuds: number = 14\n\tlocal CatchTime: number = 0.4\n\tlocal CatchLimit: number = 2\n\t\n\tlocal function GetClutchBlock()\n\t    if store.hand.toolType == \"block\" and (#Whitelist.ListEnabled == 0 or Blacklist.Enabled ~= (table.find(Whitelist.ListEnabled, store.hand.tool.Name) and true or false)) then\n\t        return store.hand.tool.Name, store.hand.amount, nil\n\t    end\n\t\n\t    if not HeldOnly.Enabled then\n\t        for _, v: any in store.inventory.inventory.items do\n\t            local Meta = bedwars.ItemMeta[v.itemType]\n\t            if Meta and Meta.block and (#Whitelist.ListEnabled == 0 or Blacklist.Enabled ~= (table.find(Whitelist.ListEnabled, v.itemType) and true or false)) then\n\t                return v.itemType, v.amount, v\n\t            end\n\t        end\n\t    end\n\t    return nil, 0, nil\n\tend\n\t\n\tlocal function IsDangerous(Position: Vector3): boolean\n\t    if not (OnVoid.Enabled or BlockFall.Enabled) then\n\t        return false\n\t    end\n\t\n\t    local Ray: RaycastResult? = Entity.Raycast(Position, Vector3.new(0, -MaxDrop, 0), store.airRay)\n\t    local Drop: number? = Ray and Position.Y - Ray.Position.Y or nil\n\t    if not Drop then\n\t        return OnVoid.Enabled\n\t    end\n\t    return BlockFall.Enabled and (Drop / 3) > Blocks.Value\n\tend\n\t\n\tlocal function GetBridge(State): Vector3?\n\t    local Feet: Vector3 = State.Position - Vector3.new(0, Entity.character.HipHeight + 1.5, 0)\n\t    local Level: number = GroundY or roundPos(Feet).Y\n\t    if Feet.Y < Level - 1.5 then\n\t        return nil\n\t    end\n\t\n\t    local Placement = Navigation:SolveVoid(State, {Channel = \"clutch\", Reach = BridgeStuds})\n\t    if Placement and IsDangerous(Placement.Position) then\n\t        return Placement.Position\n\t    end\n\t\n\t    local Under: Vector3 = Vector3.new(math.round(Feet.X / 3) * 3, Level, math.round(Feet.Z / 3) * 3)\n\t    local MoveDirection: Vector3 = Entity.character.Humanoid.MoveDirection\n\t    local Columns: {Vector3} = {Under}\n\t\n\t    if MoveDirection.Magnitude > 0 then\n\t        table.insert(Columns, roundPos(Under + MoveDirection * 3))\n\t        if Staircase.Enabled then\n\t            table.insert(Columns, roundPos(Under + MoveDirection * 3 + Vector3.new(0, 3, 0)))\n\t        end\n\t    end\n\t\n\t    for _, v: Vector3 in Columns do\n\t        for Depth: number = 0, ReachCells do\n\t            local Position: Vector3 = v - Vector3.new(0, Depth * 3, 0)\n\t            if getPlacedBlock(Position) then\n\t                break\n\t            end\n\t            if IsDangerous(Position) and Navigation:SolvePlacement(State, Navigation.WorldToGrid(Position), {Channel = \"clutch\", Reach = BridgeStuds}).Valid then\n\t                return Position\n\t            end\n\t        end\n\t    end\n\t    return nil\n\tend\n\t\n\tlocal function GetPlacement()\n\t    local Root: BasePart = Entity.character.RootPart\n\t    local State = {\n\t        Position = Root.Position,\n\t        Velocity = tick() < ImpulseUntil and Root.AssemblyLinearVelocity + Impulse or Root.AssemblyLinearVelocity,\n\t        Grounded = Entity.character.Humanoid.FloorMaterial ~= Enum.Material.Air\n\t    }\n\t\n\t    if State.Grounded and Entity.character.Humanoid.MoveDirection == Vector3.zero and (State.Velocity * Vector3.new(1, 0, 1)).Magnitude < 0.5 then\n\t        return nil, false\n\t    end\n\t\n\t    if not State.Grounded and CatchTries < CatchLimit and (FallDamage.Enabled or BlockFall.Enabled or OnVoid.Enabled) then\n\t        local Result = Navigation:FindClutch(State, {\n\t            Channel = \"clutch\",\n\t            Reach = CatchStuds,\n\t            BlocksAvailable = LimitBlocks.Enabled and math.max(MaxBlocks.Value - Placed, 0) or nil,\n\t            DamageAllowance = FallDamage.Enabled and math.min(Allowance.Value, math.max(Entity.character.Health - 1, 0)) or 1000,\n\t            Agent = {SafeMargin = Accuracy.Value / 100},\n\t            Clutch = {\n\t                MaxFall = BlockFall.Enabled and Blocks.Value * 3 or math.huge,\n\t                Void = OnVoid.Enabled\n\t            }\n\t        })\n\t\n\t        if Result.Success then\n\t            return Result.BridgePath[1].Position, true\n\t        elseif Result.Reason == \"Safe\" then\n\t            return nil, false\n\t        end\n\t    end\n\t\n\t    return GetBridge(State), false\n\tend\n\t\n\tClutch = vape.Categories.Utility:CreateModule({\n\t    Name = \"Clutch\",\n\t    Function = function(Callback: boolean)\n\t        if Label then\n\t            if vape.ThreadFix then\n\t                setthreadidentity(8)\n\t            end\n\t\n\t            Label.Visible = Callback\n\t        end\n\t\n\t        if Callback then\n\t            local LastSlot: number?\n\t\n\t            Clutch:Clean(vapeEvents.EntityDamageEvent.Event:Connect(function(DamageTable)\n\t                if DamageTable.entityInstance ~= LocalPlayer.Character or not Entity.isAlive or not DamageTable.fromPosition then\n\t                    return\n\t                end\n\t                local Multiplier = DamageTable.knockbackMultiplier\n\t                if Multiplier and Multiplier.disabled then\n\t                    return\n\t                end\n\t\n\t                local Direction: Vector3 = bedwars.KnockbackUtil.getDirection(Entity.character.RootPart.Position, DamageTable.fromPosition)\n\t                if Direction.Magnitude > 0 then\n\t                    Impulse = bedwars.KnockbackUtil.calculateKnockbackVelocity(Direction, 1, Multiplier)\n\t                    ImpulseUntil = tick() + 0.2\n\t                end\n\t            end))\n\t\n\t            ;(function()\n\t                local Warned: number = 0\n\t\n\t                repeat\n\t                    if vape.ThreadFix then\n\t                        setthreadidentity(8)\n\t                    end\n\t\n\t                    local Success, ErrorMessage = pcall(function()\n\t                        if not Entity.isAlive then\n\t                            CatchCell, CatchSeen, CatchTries, Falling = nil, false, 0, false\n\t                            return\n\t                        end\n\t\n\t                        local Grounded: boolean = Entity.character.Humanoid.FloorMaterial ~= Enum.Material.Air\n\t                        if Grounded then\n\t                            GroundY = roundPos((Entity.character.RootPart.Position - Vector3.new(0, Entity.character.HipHeight + 1.5, 0))).Y\n\t                            Placed, CatchTries = 0, 0\n\t                        end\n\t\n\t                        if CatchCell then\n\t                            local Feet: Vector3 = (Entity.character.RootPart.Position - Vector3.new(0, Entity.character.HipHeight + 1.5, 0))\n\t                            local AimVelocity: Vector3 = tick() < ImpulseUntil and Entity.character.RootPart.AssemblyLinearVelocity + Impulse or Entity.character.RootPart.AssemblyLinearVelocity\n\t                            local AimElapsed: number = ((AimVelocity.Y + math.sqrt((AimVelocity.Y * AimVelocity.Y) + (2 * workspace.Gravity * math.max((Feet.Y - (CatchCell.Y + 1.5)), 0)))) / workspace.Gravity)\n\t                            local Aimed: Vector3 = Vector3.new(math.round((Feet.X + (AimVelocity.X * AimElapsed)) / 3) * 3, CatchCell.Y, math.round((Feet.Z + (AimVelocity.Z * AimElapsed)) / 3) * 3)\n\t                            if Grounded or Feet.Y < CatchCell.Y or (Aimed - CatchCell).Magnitude > 3 then\n\t                                CatchCell, CatchSeen = nil, false\n\t                            elseif getPlacedBlock(CatchCell) then\n\t                                CatchSeen = true\n\t                            elseif CatchSeen or tick() > CatchUntil then\n\t                                CatchCell, CatchSeen = nil, false\n\t                            end\n\t                        end\n\t\n\t                        local Position, Catching\n\t                        if not CatchCell then\n\t                            Position, Catching = GetPlacement()\n\t                        end\n\t\n\t                        if Position or Label then\n\t                            local ItemType, Amount, Item = GetClutchBlock()\n\t                            if Label then\n\t                                if vape.ThreadFix then\n\t                                    setthreadidentity(8)\n\t                                end\n\t\n\t                                Label.Text = `{Amount} <font color=\"rgb(170, 170, 170)\">(Clutch)</font>`\n\t                                Label.TextColor3 = Color3.fromHSV((Amount / 128) / 2.8, 0.86, 1)\n\t                            end\n\t\n\t                            if Position and ItemType and (not LimitBlocks.Enabled or Placed < MaxBlocks.Value) then\n\t                                if not Falling then\n\t                                    Falling = true\n\t                                    LastSlot = store.inventory.hotbarSlot\n\t                                    task.wait(((MoveDelay.ValueMin + math.random() * (MoveDelay.ValueMax - MoveDelay.ValueMin)) / 60))\n\t                                    if vape.ThreadFix then\n\t                                        setthreadidentity(8)\n\t                                    end\n\t\n\t                                    Position = nil\n\t                                    if Entity.isAlive then\n\t                                        Position, Catching = GetPlacement()\n\t                                    end\n\t                                end\n\t\n\t                                local Now: number = workspace:GetServerTimeNow()\n\t                                local Interval: number = 1 / bedwars.SharedConstants.BLOCK_PLACE_CPS\n\t                                if Position and Now >= LastPlace then\n\t                                    local Slot = Item and getHotbar(Item.tool)\n\t                                    if Slot then\n\t                                        task.spawn(hotbarSwitch, Slot)\n\t                                    end\n\t                                    LastPlace = Now + math.max(1 / Speed.Value, Interval)\n\t                                    local Restore: CFrame?\n\t                                    if not SilentAim.Enabled then\n\t                                        Restore = Camera.CFrame\n\t                                        if vape.ThreadFix then\n\t                                            setthreadidentity(8)\n\t                                        end\n\t                                        Camera.CFrame = CFrame.lookAt(Restore.Position, Position)\n\t                                    end\n\t\n\t                                    local Success = bedwars.placeBlock(Position, ItemType)\n\t                                    if Restore then\n\t                                        task.delay(((ResetAngle.ValueMin + math.random() * (ResetAngle.ValueMax - ResetAngle.ValueMin)) / 60), function()\n\t                                            if vape.ThreadFix then\n\t                                                setthreadidentity(8)\n\t                                            end\n\t\n\t                                            Camera.CFrame = CFrame.lookAt(Camera.CFrame.Position, Camera.CFrame.Position + Restore.LookVector)\n\t                                        end)\n\t                                    end\n\t\n\t                                    if Success then\n\t                                        Placed += 1\n\t                                        if Catching then\n\t                                            CatchCell, CatchSeen = Position, false\n\t                                            CatchTries += 1\n\t                                            CatchUntil = tick() + CatchTime + math.clamp(store.ping.total or 0, 0, 0.3)\n\t                                        end\n\t                                    else\n\t                                        LastPlace = Now + math.max(FailDelay.Value / 1000, Interval)\n\t                                    end\n\t                                end\n\t                            end\n\t                        end\n\t\n\t                        if Position then\n\t                            LastDanger = tick()\n\t                        elseif Falling and (tick() - LastDanger) > 0.5 then\n\t                            Falling = false\n\t                            Placed = 0\n\t                            if ReturnSlot.Enabled and LastSlot then\n\t                                hotbarSwitch(LastSlot)\n\t                            end\n\t                            LastSlot = nil\n\t                        end\n\t                    end)\n\t\n\t                    if not Success and tick() > Warned then\n\t                        Warned = tick() + 5\n\t                        warn(`[catvape] clutch step failed: {ErrorMessage}`)\n\t                    end\n\t\n\t                    task.wait()\n\t                until not Clutch.Enabled\n\t            end)()\n\t        else\n\t            Falling, Placed, CatchCell, CatchSeen, CatchTries, ImpulseUntil, GroundY = false, 0, nil, false, 0, 0, nil\n\t        end\n\t    end,\n\t    Tooltip = \"Saves yourself from falling\"\n\t})\n\t\n\tOnVoid = Clutch:CreateToggle({\n\t    Name = \"On void\",\n\t    Tooltip = \"Clutches when there is nothing at all beneath you\"\n\t})\n\tFallDamage = Clutch:CreateToggle({\n\t    Name = \"On fall damage\",\n\t    Function = function(Callback: boolean)\n\t        if Accuracy.Object then\n\t            Accuracy.Object.Visible = Callback\n\t        end\n\t    end,\n\t    Default = true,\n\t    Tooltip = \"Catches you as far down as it can while still landing you without damage\"\n\t})\n\tAccuracy = Clutch:CreateSlider({\n\t    Name = \"Accuracy\",\n\t    Min = 50,\n\t    Max = 100,\n\t    Default = 100,\n\t    Darker = true,\n\t    Suffix = \"%\",\n\t    Tooltip = \"How close to the real limit it cuts it, lower catches you higher up with room to spare\"\n\t})\n\tAllowance = Clutch:CreateSlider({\n\t    Name = \"Damage allowance\",\n\t    Min = 0,\n\t    Max = 100,\n\t    Default = 0,\n\t    Suffix = \"hp\",\n\t    Tooltip = \"Fall damage you are willing to eat, so it can catch you even lower\"\n\t})\n\tBlockFall = Clutch:CreateToggle({\n\t    Name = \"On more than x blocks\",\n\t    Default = true\n\t})\n\tBlocks = Clutch:CreateSlider({\n\t    Name = \"Blocks\",\n\t    Min = 1,\n\t    Max = 30,\n\t    Default = 3,\n\t    Suffix = function(Val: number)\n\t        return Val <= 1 and \"block\" or \"blocks\"\n\t    end\n\t})\n\tSpeed = Clutch:CreateSlider({\n\t    Name = \"Speed\",\n\t    Min = 1,\n\t    Max = 40,\n\t    Default = 20,\n\t    Suffix = \"bps\",\n\t    Tooltip = \"Blocks placed per second\"\n\t})\n\tSilentAim = Clutch:CreateToggle({\n\t    Name = \"Silent aim\",\n\t    Default = true,\n\t    Tooltip = \"Places without turning your camera to the block\"\n\t})\n\tResetAngle = Clutch:CreateTwoSlider({\n\t    Name = \"Reset angle delay\",\n\t    Min = 0,\n\t    Max = 20,\n\t    DefaultMin = 3,\n\t    DefaultMax = 6,\n\t    Tooltip = \"Ticks before your camera goes back to where it was\"\n\t})\n\tReturnSlot = Clutch:CreateToggle({\n\t    Name = \"Return to last slot\",\n\t    Tooltip = \"Swaps back to whatever you were holding once you land\"\n\t})\n\tMoveDelay = Clutch:CreateTwoSlider({\n\t    Name = \"Clutch move delay\",\n\t    Min = 0,\n\t    Max = 20,\n\t    DefaultMin = 2,\n\t    DefaultMax = 5,\n\t    Tooltip = \"Ticks of reaction time before the first block goes down\"\n\t})\n\tFailDelay = Clutch:CreateSlider({\n\t    Name = \"Fail delay\",\n\t    Min = 0,\n\t    Max = 1000,\n\t    Default = 0,\n\t    Suffix = \"ms\"\n\t})\n\tStaircase = Clutch:CreateToggle({\n\t    Name = \"Allow staircase up\",\n\t    Tooltip = \"Also places ahead and above you so you can climb back up\"\n\t})\n\tClutch:CreateToggle({\n\t    Name = \"Show block count\",\n\t    Function = function(Callback: boolean)\n\t        if Callback then\n\t            Label = Instance.new(\"TextLabel\")\n\t            Label.Size = UDim2.fromOffset(100, 20)\n\t            Label.Position = UDim2.new(0.5, 6, 0.5, 80)\n\t            Label.BackgroundTransparency = 1\n\t            Label.AnchorPoint = Vector2.new(0.5, 0)\n\t            Label.Text = \"0\"\n\t            Label.TextColor3 = Color3.new(0, 1, 0)\n\t            Label.TextSize = 18\n\t            Label.RichText = true\n\t            Label.Font = Enum.Font.Arial\n\t            Label.Visible = Clutch.Enabled\n\t            if vape.ThreadFix then\n\t                setthreadidentity(8)\n\t            end\n\t            Label.Parent = vape.gui\n\t        else\n\t            Label:Destroy()\n\t            Label = nil\n\t        end\n\t    end\n\t})\n\tLimitBlocks = Clutch:CreateToggle({\n\t    Name = \"Limit blocks\",\n\t    Default = true,\n\t    Tooltip = \"Caps how many blocks one clutch is allowed to spend\"\n\t})\n\tMaxBlocks = Clutch:CreateSlider({\n\t    Name = \"Max blocks\",\n\t    Min = 1,\n\t    Max = 32,\n\t    Default = 5\n\t})\n\tBlacklist = Clutch:CreateToggle({\n\t    Name = \"Blacklist\",\n\t    Tooltip = \"Treats the list as blocks to avoid instead of blocks to use\"\n\t})\n\tHeldOnly = Clutch:CreateToggle({\n\t    Name = \"Held whitelist\",\n\t    Tooltip = \"Only clutches with the block already in your hand, never swaps for one\"\n\t})\n\tWhitelist = Clutch:CreateTextList({\n\t    Name = \"Whitelist\",\n\t    Tooltip = \"Block types the clutch is allowed to use\"\n\t})\n\t\nend)\n\nRun(function()\n\tlocal DeviceSpoofer\n\tlocal Device\n\tlocal OldDevice, Old\n\t\n\tDeviceSpoofer = vape.Categories.Utility:CreateModule({\n\t    Name = \"DeviceSpoofer\",\n\t    Function = function(Callback: boolean)\n\t        if Callback then\n\t            OldDevice, Old = bedwars.UserInputController:getUserInputType(), bedwars.UserInputController.getUserInputType\n\t            bedwars.UserInputController.getUserInputType = function()\n\t                return Device.Value:upper()\n\t            end\n\t            bedwars.Handler:Get(\"SendUserInputType\"):Fire(\"SendToServer\", {userInputType = Device.Value:upper()})\n\t        else\n\t            bedwars.UserInputController.getUserInputType = Old\n\t            bedwars.Handler:Get(\"SendUserInputType\"):Fire(\"SendToServer\", {userInputType = OldDevice})\n\t            Old = nil\n\t        end\n\t    end,\n\t    Tooltip = \"Spoofs the device you show up as to the server\",\n\t    ExtraText = function()\n\t        return Device.Value\n\t    end\n\t})\n\t\n\tDevice = DeviceSpoofer:CreateDropdown({\n\t    Name = \"Device\",\n\t    List = {\"Mobile\", \"PC\", \"Gamepad\"},\n\t    Function = function(Val: string)\n\t        if DeviceSpoofer.Enabled then\n\t            bedwars.Handler:Get(\"SendUserInputType\"):Fire(\"SendToServer\", {userInputType = Val:upper()})\n\t        end\n\t    end\n\t})\nend)\n\nRun(function()\n\tlocal KnockbackDelay\n\tlocal Chance\n\tlocal AirDelay\n\tlocal GroundDelay\n\tlocal TargetCheck\n\t\n\tlocal Old, RandomGenerator\n\tlocal function Apply(Type: string, Environment, ...)\n\t    local Root, Mass, Direction, Knockback = ...\n\t    Knockback = Knockback and table.clone(Knockback) or {}\n\t    Knockback[Type] = Environment[Type] and Knockback[Type] or 0\n\t    return Old(Root, Mass, Direction, Knockback, select(5, ...))\n\tend\n\t\n\tKnockbackDelay = vape.Categories.Utility:CreateModule({\n\t    Name = \"KnockbackDelay\",\n\t    Function = function(Callback: boolean)\n\t        if Callback then\n\t            Old, RandomGenerator = bedwars.KnockbackUtil.applyKnockback, Random.new()\n\t            bedwars.KnockbackUtil.applyKnockback = function(...)\n\t                if RandomGenerator:NextNumber(0, 100) > Chance.Value then\n\t                    return Old(...)\n\t                end\n\t\n\t                local Root, Mass, Direction, Knockback = ...\n\t                if not TargetCheck.Enabled or Entity.EntityPosition({\n\t                    Range = 50,\n\t                    Part = \"RootPart\",\n\t                    Players = true,\n\t                }) then\n\t                    local Environment = {}\n\t                    task.delay(AirDelay:GetRandomValue() / 1000, Apply, \"horizontal\", Environment, Root, Mass, Direction, Knockback, select(5, ...))\n\t                    task.delay(GroundDelay:GetRandomValue() / 1000, Apply, \"vertical\", Environment, Root, Mass, Direction, Knockback, select(5, ...))\n\t                    return\n\t                end\n\t                return Old(...)\n\t            end\n\t        else\n\t            bedwars.KnockbackUtil.applyKnockback = Old or bedwars.KnockbackUtil.applyKnockback\n\t        end\n\t    end,\n\t    Tooltip = \"Delays incoming knockback packets\"\n\t})\n\t\n\tChance = KnockbackDelay:CreateSlider({\n\t    Name = \"Chance\",\n\t    Min = 1,\n\t    Max = 100,\n\t    Suffix = \"%\",\n\t    Default = 40\n\t})\n\tAirDelay = KnockbackDelay:CreateTwoSlider({\n\t    Name = \"Air delay\",\n\t    Min = 0,\n\t    Max = 500,\n\t    DefaultMin = 50,\n\t    DefaultMax = 200\n\t})\n\tGroundDelay = KnockbackDelay:CreateTwoSlider({\n\t    Name = \"Ground delay\",\n\t    Min = 0,\n\t    Max = 500,\n\t    DefaultMin = 50,\n\t    DefaultMax = 200\n\t})\n\tTargetCheck = KnockbackDelay:CreateToggle({Name = \"Target check\"})\nend)\n\nRun(function()\n\tlocal LeaveParty; LeaveParty = vape.Categories.Utility:CreateModule({\n\t    Name = \"LeaveParty\",\n\t    Function = function(Callback: boolean)\n\t        if Callback then\n\t            bedwars.PartyController:leaveParty()\n\t            LeaveParty:Toggle()\n\t        end\n\t    end\n\t})\nend)\n\nRun(function()\n\tlocal MatchDodge\n\tlocal RankOnly\n\tlocal AutoUndodge\n\tlocal UndodgeMode\n\tlocal Blacklist\n\tlocal Ping\n\tlocal Timeout\n\tlocal RankVeto\n\tlocal VetoAt\n\tlocal TeamCheck\n\tlocal Requeue\n\tlocal MaxWait\n\tlocal Advanced\n\tlocal RankAdvantage\n\tlocal DeviceCheck\n\tlocal Device\n\tlocal LowRank\n\tlocal LowRankAt\n\tlocal Guaranteed\n\tlocal Tiers: {string} = {\"Bronze\", \"Silver\", \"Gold\", \"Platinum\", \"Diamond\", \"Emerald\", \"Nightmare\"}\n\t\n\tlocal Ranks = {}\n\tlocal Status: string = \"Next match\"\n\tlocal Requeued: boolean = false\n\tlocal RequeueTries: number = 0\n\tlocal RequeueRetry: number = 0\n\t\n\tlocal function GetRank(Player: Player): number?\n\t    local Rank = Ranks[Player]\n\t    if not Rank then\n\t        Rank = {retry = 0}\n\t        Ranks[Player] = Rank\n\t    end\n\t    if not Rank.pending and not Rank.value and os.clock() >= Rank.retry then\n\t        Rank.pending = true\n\t        task.spawn(function()\n\t            local Success, Response = pcall(store.rank[Player].async)\n\t            if Ranks[Player] == Rank then\n\t                Rank.pending = false\n\t                Rank.retry = os.clock() + 5\n\t                if Success and type(Response) == \"number\" and bedwars.RankMeta[Response] then\n\t                    Rank.value = Response\n\t                end\n\t            end\n\t        end)\n\t    end\n\t    return Rank.value\n\tend\n\t\n\tlocal function GetRoster(Data)\n\t    local State = bedwars.Store:getState().Game\n\t    local Teams, Assigned = {}, {}\n\t    local Leader = type(Data) == \"table\" and Data.match and Data.match.teamLeaderUserId\n\t    for _, v: any in State.teams or {} do\n\t        for MemberIndex: any, Member: any in v.members or {} do\n\t            Assigned[tonumber(Member.userId or MemberIndex)] = tostring(v.id)\n\t        end\n\t    end\n\t    local Team = LocalPlayer:GetAttribute(\"Team\") or (State.myTeam and State.myTeam.id) or Assigned[LocalPlayer.UserId] or Assigned[Leader]\n\t    if not Team then\n\t        return nil\n\t    end\n\t    Team = tostring(Team)\n\t\n\t    local Result = {allies = {LocalPlayer}, opponents = {}, alliesLoaded = 1, opponentsLoaded = 0, pending = false}\n\t    for _, v: Player in Players:GetPlayers() do\n\t        Teams[v.UserId] = true\n\t        if v == LocalPlayer or v:GetAttribute(\"Spectator\") then\n\t            continue\n\t        end\n\t        local OtherTeam = v:GetAttribute(\"Team\") or Assigned[v.UserId]\n\t        if OtherTeam then\n\t            OtherTeam = tostring(OtherTeam)\n\t            local Friendly: boolean = OtherTeam == Team\n\t            table.insert(Friendly and Result.allies or Result.opponents, v)\n\t            if v:GetAttribute(\"PlayerConnected\") then\n\t                if Friendly then\n\t                    Result.alliesLoaded += 1\n\t                else\n\t                    Result.opponentsLoaded += 1\n\t                end\n\t            else\n\t                Result.pending = true\n\t            end\n\t        else\n\t            Result.pending = true\n\t        end\n\t    end\n\t    for UserId: number in Assigned do\n\t        if UserId ~= LocalPlayer.UserId and not Teams[UserId] then\n\t            Result.pending = true\n\t        end\n\t    end\n\t    return Result\n\tend\n\t\n\tlocal function RequeueMatch(): string?\n\t    local State = bedwars.Store:getState()\n\t    if Requeued or State.Party.queueState ~= 0 then\n\t        Requeued = true\n\t        return \"Requeued\"\n\t    end\n\t\n\t    local Data = TeleportService:GetLocalPlayerTeleportData()\n\t    if (type(Data) == \"table\" and Data.customMatch) or State.Game.customMatch or State.Party.leader.userId ~= LocalPlayer.UserId then\n\t        return nil\n\t    end\n\t\n\t    local Match = type(Data) == \"table\" and Data.match\n\t    local QueueType: string? = Match and Match.queueType or store.queueType\n\t    local Meta = QueueType and bedwars.QueueMeta[QueueType]\n\t    if not Meta or Meta.disabled then\n\t        return nil\n\t    end\n\t\n\t    if os.clock() >= RequeueRetry then\n\t        if RequeueTries >= 3 then\n\t            return \"Requeue failed\"\n\t        end\n\t        RequeueTries += 1\n\t        RequeueRetry = os.clock() + 5\n\t        pcall(bedwars.QueueController.joinQueue, bedwars.QueueController, QueueType)\n\t    end\n\t    return \"Requeueing\"\n\tend\n\t\n\tMatchDodge = vape.Categories.Utility:CreateModule({\n\t    Name = \"AutoMatchDodge\",\n\t    Function = function(Callback: boolean)\n\t        writefile(`{vape.Directory}/profiles/matchdodge.txt`, tostring(Callback))\n\t        getgenv().matchDodgeActive = Callback\n\t        if Callback then\n\t            store.readyHold.Claimed = true\n\t            MatchDodge:Clean(coroutine.running())\n\t            local Start: number?\n\t            repeat\n\t                if not getgenv().dodged and not store.readyHold.Held then\n\t                    Start = nil\n\t                    Status = LocalPlayer:GetAttribute(\"PlayerConnected\") and \"Loaded\" or \"Next match\"\n\t                else\n\t                    Start = Start or store.readyHold.Started or os.clock()\n\t                    local Data = TeleportService:GetLocalPlayerTeleportData()\n\t                    local Match = type(Data) == \"table\" and (Data.match or Data.customMatch)\n\t                    local Queue = bedwars.QueueMeta[Match and Match.queueType or store.queueType]\n\t                    if getgenv().regionLockActive and not getgenv().regionLockAllowed then\n\t                        Status = \"Waiting for RegionLock\"\n\t                    elseif RankOnly.Enabled and Queue and not Queue.rankCategory then\n\t                        if getgenv().dodged and not store.readyHold.Remote then\n\t                            bedwars.Handler:Get(\"PlayerConnect\"):Fire(\"SendToServer\", Data)\n\t                        end\n\t                        store.readyHold.Release()\n\t                        getgenv().dodged = false\n\t                        Status = \"Loaded\"\n\t                    elseif AutoUndodge.Enabled then\n\t                        local Roster = GetRoster(Data)\n\t                        local Expired = MaxWait.Value > 0 and os.clock() - Start >= MaxWait.Value\n\t                        local Ready = Expired or (UndodgeMode.Value == \"Latency\" and math.max(store.ping.incoming or 0, store.ping.total or 0) * 1000 >= Ping.Value) or (UndodgeMode.Value == \"Rank\" and Roster and #Roster.opponents > 0 and not Roster.pending)\n\t                        local Veto: string?\n\t                        local Five = Queue and Queue.teams and #Queue.teams == 2 and Queue.teams[1].maxPlayers == 5 and Queue.teams[2].maxPlayers == 5\n\t                        if TeamCheck.Enabled or (Advanced.Enabled and Guaranteed.Enabled) then\n\t                            if not Queue then\n\t                                Veto = \"Waiting for queue\"\n\t                            elseif not Five and Advanced.Enabled and Guaranteed.Enabled then\n\t                                Veto = \"Requires a 5v5 queue\"\n\t                            elseif Five and (not Roster or Roster.pending or #Roster.opponents == 0) then\n\t                                Veto = \"Waiting for teams\"\n\t                            elseif Five and TeamCheck.Enabled and Roster.alliesLoaded < Roster.opponentsLoaded then\n\t                                Veto = \"4v5 Check\"\n\t                            elseif Five and Advanced.Enabled and Guaranteed.Enabled and (store.matchState ~= 1 or Roster.alliesLoaded ~= 5 or Roster.opponentsLoaded ~= 4) then\n\t                                Veto = \"Waiting for 5v4\"\n\t                            end\n\t                        end\n\t\n\t                        local Ranked = RankVeto.Enabled or (UndodgeMode.Value == \"Rank\" and #Blacklist.ListEnabled > 0) or (Advanced.Enabled and (RankAdvantage.Enabled or LowRank.Enabled))\n\t                        if Ranked or (Advanced.Enabled and DeviceCheck.Enabled) then\n\t                            if not Roster or #Roster.opponents == 0 or Roster.pending then\n\t                                Veto = Veto or \"Waiting for teams\"\n\t                            else\n\t                                local EnemyRank, OwnRank = 0, 0\n\t                                for _, v: Player in Roster.opponents do\n\t                                    if Ranked then\n\t                                        local Rank: number? = GetRank(v)\n\t                                        if Rank == nil then\n\t                                            Veto = Veto or \"Waiting for ranks\"\n\t                                        else\n\t                                            local Tier: string = bedwars.RankMeta[Rank].tier\n\t                                            local Index: number?\n\t                                            for TierIndex: number, TierName: string in Tiers do\n\t                                                if TierName:lower() == Tier then\n\t                                                    Index = TierIndex\n\t                                                    break\n\t                                                end\n\t                                            end\n\t                                            EnemyRank += Rank\n\t                                            if not Index then\n\t                                                Veto = Veto or \"Unknown rank\"\n\t                                            elseif RankVeto.Enabled and Index >= table.find(Tiers, VetoAt.Value) then\n\t                                                Veto = Veto or \"Rank Veto\"\n\t                                            elseif UndodgeMode.Value == \"Rank\" and table.find(Blacklist.ListEnabled, Tier) then\n\t                                                Veto = Veto or \"Rank Blacklist\"\n\t                                            elseif Advanced.Enabled and LowRank.Enabled and Index > table.find(Tiers, LowRankAt.Value) then\n\t                                                Veto = Veto or \"Low Rank\"\n\t                                            end\n\t                                        end\n\t                                    end\n\t                                    if Advanced.Enabled and DeviceCheck.Enabled then\n\t                                        local PlayerDevice = v:GetAttribute(\"UserInputType\")\n\t                                        local Allowed: boolean = PlayerDevice == Device.Value:upper() or (Device.Value == \"Mobile / Gamepad\" and (PlayerDevice == \"MOBILE\" or PlayerDevice == \"GAMEPAD\"))\n\t                                        if not Allowed then\n\t                                            Veto = Veto or (PlayerDevice and \"Device Check\" or \"Waiting for devices\")\n\t                                        end\n\t                                    end\n\t                                end\n\t                                if Advanced.Enabled and RankAdvantage.Enabled then\n\t                                    for _, v: Player in Roster.allies do\n\t                                        local Rank: number? = GetRank(v)\n\t                                        if Rank == nil then\n\t                                            Veto = Veto or \"Waiting for ranks\"\n\t                                        else\n\t                                            OwnRank += Rank\n\t                                        end\n\t                                    end\n\t                                    if OwnRank / #Roster.allies <= EnemyRank / #Roster.opponents then\n\t                                        Veto = Veto or \"Rank Advantage\"\n\t                                    end\n\t                                end\n\t                            end\n\t                        end\n\t\n\t                        Status = Veto or (UndodgeMode.Value == \"Latency\" and \"Waiting for ping\" or \"Waiting for opponents\")\n\t                        if Requeued then\n\t                            Status = \"Requeued\"\n\t                        elseif Ready and not Veto then\n\t                            if getgenv().dodged and not store.readyHold.Remote then\n\t                                bedwars.Handler:Get(\"PlayerConnect\"):Fire(\"SendToServer\", Data)\n\t                            end\n\t                            store.readyHold.Release()\n\t                            getgenv().dodged = false\n\t                            Status = \"Loaded\"\n\t                        elseif Requeue.Enabled and Veto and (Expired or not Veto:find(\"^Waiting\")) then\n\t                            local RequeueStatus: string? = RequeueMatch()\n\t                            Status = RequeueStatus and `{RequeueStatus} ({Veto})` or Veto\n\t                        end\n\t                    else\n\t                        Status = \"Waiting for Load\"\n\t                    end\n\t                end\n\t                task.wait(0.5)\n\t            until not MatchDodge.Enabled\n\t        else\n\t            if not getgenv().regionLockActive or getgenv().regionLockAllowed then\n\t                if getgenv().dodged and not store.readyHold.Remote then\n\t                    bedwars.Handler:Get(\"PlayerConnect\"):Fire(\"SendToServer\", TeleportService:GetLocalPlayerTeleportData())\n\t                end\n\t                store.readyHold.Release()\n\t                getgenv().dodged = false\n\t            end\n\t            Status = \"Loaded\"\n\t            store.readyHold.Claimed = getgenv().regionLockActive\n\t            table.clear(Ranks)\n\t        end\n\t    end,\n\t    Tooltip = \"Waits before loading a match until your chosen checks pass\",\n\t    ExtraText = function()\n\t        return Status\n\t    end\n\t})\n\t\n\tMatchDodge:CreateButton({\n\t    Name = \"Load\",\n\t    Function = function()\n\t        if Requeued and store.readyHold.Held then\n\t            pcall(bedwars.QueueController.leaveQueue, bedwars.QueueController)\n\t        end\n\t        if getgenv().dodged and not store.readyHold.Remote then\n\t            bedwars.Handler:Get(\"PlayerConnect\"):Fire(\"SendToServer\", TeleportService:GetLocalPlayerTeleportData())\n\t        end\n\t        store.readyHold.Release()\n\t        getgenv().dodged = false\n\t        Status = \"Loaded\"\n\t    end,\n\t    Tooltip = \"Loads this match now, ignoring the automatic checks, and leaves the queue Requeue joined\"\n\t})\n\tRankOnly = MatchDodge:CreateToggle({\n\t    Name = \"Rank only\",\n\t    Tooltip = \"Loads straight away when the match is not ranked\"\n\t})\n\tAutoUndodge = MatchDodge:CreateToggle({\n\t    Name = \"Auto Undodge\",\n\t    Function = function(Callback: boolean)\n\t        if UndodgeMode then\n\t            UndodgeMode.Object.Visible = Callback\n\t        end\n\t        if Blacklist then\n\t            Blacklist.Object.Visible = Callback and UndodgeMode.Value == \"Rank\"\n\t        end\n\t        if Ping then\n\t            Ping.Object.Visible = Callback and UndodgeMode.Value == \"Latency\"\n\t        end\n\t    end,\n\t    Tooltip = \"Automatically loads when the selected checks pass\"\n\t})\n\tUndodgeMode = MatchDodge:CreateDropdown({\n\t    Name = \"Mode\",\n\t    List = {\"Rank\", \"Latency\"},\n\t    Function = function(Value: string)\n\t        if Blacklist then\n\t            Blacklist.Object.Visible = AutoUndodge.Enabled and Value == \"Rank\"\n\t        end\n\t        if Ping then\n\t            Ping.Object.Visible = AutoUndodge.Enabled and Value == \"Latency\"\n\t        end\n\t    end,\n\t    Darker = true,\n\t    Visible = false,\n\t    Tooltip = \"Rank waits for opponents to load, Latency waits for your ping to reach the threshold\"\n\t})\n\tBlacklist = MatchDodge:CreateTextList({\n\t    Name = \"Rank Blacklist\",\n\t    Placeholder = \"bronze / silver / gold / platinum / diamond / emerald / nightmare\",\n\t    Darker = true,\n\t    Visible = false,\n\t    Function = function()\n\t        for i: number, v: string in Blacklist.List do\n\t            Blacklist.List[i] = v:lower()\n\t        end\n\t        for i: number, v: string in Blacklist.ListEnabled do\n\t            Blacklist.ListEnabled[i] = v:lower()\n\t        end\n\t    end\n\t})\n\tPing = MatchDodge:CreateSlider({\n\t    Name = \"Ping\",\n\t    Min = 50,\n\t    Max = 1000,\n\t    Default = 200,\n\t    Darker = true,\n\t    Visible = false,\n\t    Suffix = \"ms\",\n\t    Tooltip = \"How high your ping has to be before loading\"\n\t})\n\tRankVeto = MatchDodge:CreateToggle({\n\t    Name = \"Rank Veto\",\n\t    Function = function(Callback: boolean)\n\t        if VetoAt then\n\t            VetoAt.Object.Visible = Callback\n\t        end\n\t    end,\n\t    Tooltip = \"Keeps dodging opponents at or above the selected rank, even after Max Wait\"\n\t})\n\tVetoAt = MatchDodge:CreateDropdown({\n\t    Name = \"Veto At\",\n\t    List = Tiers,\n\t    Default = \"Diamond\",\n\t    Darker = true,\n\t    Visible = false,\n\t    Tooltip = \"The lowest enemy rank that blocks automatic loading\"\n\t})\n\tTeamCheck = MatchDodge:CreateToggle({\n\t    Name = \"4v5 Check\",\n\t    Tooltip = \"In 5v5 queues, waits if fewer teammates than opponents are loaded, counting you\"\n\t})\n\tRequeue = MatchDodge:CreateToggle({\n\t    Name = \"Requeue\",\n\t    Tooltip = \"Needs Auto Undodge. When a check rejects the match, or still blocks it after Max Wait, queues the same mode again from the loading screen (party leader only, up to 3 tries). Once requeued, this match only loads if you press Load\"\n\t})\n\tMaxWait = MatchDodge:CreateSlider({\n\t    Name = \"Max Wait\",\n\t    Min = 0,\n\t    Max = 120,\n\t    Function = function(Value: number)\n\t        if Timeout then\n\t            Timeout.Value = Value\n\t        end\n\t    end,\n\t    Default = 20,\n\t    Suffix = function(Val: number)\n\t        return Val == 1 and \"second\" or \"seconds\"\n\t    end,\n\t    Tooltip = \"Skips the mode wait after this long. Rank vetoes, blacklist, team and Advanced checks still apply. 0 waits forever\"\n\t})\n\tTimeout = MatchDodge:CreateSlider({\n\t    Name = \"Timeout\",\n\t    Min = 0,\n\t    Max = 120,\n\t    Function = function(Value: number)\n\t        MaxWait:SetValue(Value)\n\t    end,\n\t    Default = 20,\n\t    Visible = false\n\t})\n\tAdvanced = MatchDodge:CreateToggle({\n\t    Name = \"Advanced\",\n\t    Function = function(Callback: boolean)\n\t        for _, v: any in {RankAdvantage, DeviceCheck, LowRank, Guaranteed} do\n\t            v.Object.Visible = Callback\n\t        end\n\t        if Device then\n\t            Device.Object.Visible = Callback and DeviceCheck.Enabled\n\t        end\n\t        if LowRankAt then\n\t            LowRankAt.Object.Visible = Callback and LowRank.Enabled\n\t        end\n\t    end,\n\t    Tooltip = \"Enables extra conditions for automatic loading\"\n\t})\n\tRankAdvantage = MatchDodge:CreateToggle({\n\t    Name = \"Rank Advantage\",\n\t    Darker = true,\n\t    Visible = false,\n\t    Tooltip = \"Requires your team, including you, to have a higher average rank division\"\n\t})\n\tDeviceCheck = MatchDodge:CreateToggle({\n\t    Name = \"Device Check\",\n\t    Function = function(Callback: boolean)\n\t        if Device then\n\t            Device.Object.Visible = Advanced.Enabled and Callback\n\t        end\n\t    end,\n\t    Darker = true,\n\t    Visible = false,\n\t    Tooltip = \"Requires every opponent to use one of the selected devices\"\n\t})\n\tDevice = MatchDodge:CreateDropdown({\n\t    Name = \"Device\",\n\t    List = {\"Mobile / Gamepad\", \"Mobile\", \"Gamepad\", \"PC\"},\n\t    Darker = true,\n\t    Visible = false\n\t})\n\tLowRank = MatchDodge:CreateToggle({\n\t    Name = \"Low Rank\",\n\t    Function = function(Callback: boolean)\n\t        if LowRankAt then\n\t            LowRankAt.Object.Visible = Advanced.Enabled and Callback\n\t        end\n\t    end,\n\t    Darker = true,\n\t    Visible = false,\n\t    Tooltip = \"Requires every opponent to be at or below the selected rank\"\n\t})\n\tLowRankAt = MatchDodge:CreateDropdown({\n\t    Name = \"Low Rank At\",\n\t    List = Tiers,\n\t    Default = \"Gold\",\n\t    Darker = true,\n\t    Visible = false\n\t})\n\tGuaranteed = MatchDodge:CreateToggle({\n\t    Name = \"Guaranteed 5v4\",\n\t    Darker = true,\n\t    Visible = false,\n\t    Tooltip = \"Waits for the match to start with 5 on your side and 4 opponents, with nobody still loading. Later reconnects can change the teams\"\n\t})\n\ttask.spawn(function()\n\t    repeat task.wait() until vape.Loaded or vape.Loaded == nil\n\t    local Last = isfile(`{vape.Directory}/profiles/matchdodge.json`) and readfile(`{vape.Directory}/profiles/matchdodge.json`)\n\t    if vape.Loaded and Last then\n\t        local Success, Response = pcall(HttpService.JSONDecode, HttpService, Last)\n\t        if Success and type(Response) == \"table\" then\n\t            if Response.Options and Response.Options[\"Max Wait\"] then\n\t                Response.Options.Timeout = Response.Options[\"Max Wait\"]\n\t            end\n\t            MatchDodge:Load(Response)\n\t        end\n\t    end\n\t\n\t    repeat\n\t        if vape.Loaded then\n\t            local Data = {}\n\t            MatchDodge:Save(Data)\n\t            Data.AutoMatchDodge.Favorited = nil\n\t            local Encoded: string = HttpService:JSONEncode(Data.AutoMatchDodge)\n\t            if Encoded ~= Last then\n\t                Last = Encoded\n\t                writefile(`{vape.Directory}/profiles/matchdodge.json`, Encoded)\n\t            end\n\t        end\n\t        task.wait(1)\n\t    until vape.Loaded == nil\n\tend)\nend)\n\nRun(function()\n\tlocal MatchHistory\n\t\n\tMatchHistory = vape.Categories.Utility:CreateModule({\n\t    Name = \"ViewMatchHistory\",\n\t    Function = function(Callback: boolean)\n\t        if Callback then\n\t            bedwars.Flamework.resolveDependency(\"@easy-games/game-core:client/controllers/app-controller@AppController\"):openApp({\n\t                appId = \"MatchHistoryApp\",\n\t                app = bedwars.ModerationApp\n\t            }, {\n\t                player = LocalPlayer,\n\t                matchHistory = {}\n\t            })\n\t            MatchHistory:Toggle()\n\t        end\n\t    end\n\t})\nend)\n\nRun(function()\n\tlocal MissileTP\n\t\n\tMissileTP = vape.Categories.Utility:CreateModule({\n\t    Name = \"MissileTP\",\n\t    Function = function(Callback: boolean)\n\t        if Callback then\n\t            MissileTP:Toggle()\n\t            local Target = Entity.EntityMouse({\n\t                Range = 1000,\n\t                Players = true,\n\t                Part = \"RootPart\"\n\t            })\n\t\n\t            if GetItem(\"guided_missile\") and Target then\n\t                local Projectile = bedwars.RuntimeLib.await(bedwars.GuidedProjectileController.fireGuidedProjectile:CallServerAsync(\"guided_missile\"))\n\t                if Projectile then\n\t                    local ProjectileModel: Model = Projectile.model\n\t                    if not ProjectileModel.PrimaryPart then\n\t                        ProjectileModel:GetPropertyChangedSignal(\"PrimaryPart\"):Wait()\n\t                    end\n\t\n\t                    local BodyForce: BodyForce = Instance.new(\"BodyForce\")\n\t                    BodyForce.Force = Vector3.new(0, ProjectileModel.PrimaryPart.AssemblyMass * workspace.Gravity, 0)\n\t                    BodyForce.Name = \"AntiGravity\"\n\t                    BodyForce.Parent = ProjectileModel.PrimaryPart\n\t\n\t                    repeat\n\t                        Projectile.model:SetPrimaryPartCFrame(CFrame.lookAlong(Target.RootPart.CFrame.p, Camera.CFrame.LookVector))\n\t                        task.wait(0.1)\n\t                    until not Projectile.model or not Projectile.model.Parent\n\t                else\n\t                    SendNotification(\"MissileTP\", \"Missile on cooldown.\", 3)\n\t                end\n\t            end\n\t        end\n\t    end,\n\t    Tooltip = \"Spawns and teleports a missile to a player\\nnear your mouse.\"\n\t})\nend)\n\nRun(function()\n\tlocal NickHider\n\tlocal Replacement\n\tlocal ChatTags\n\tlocal Level\n\tlocal HideOthers\n\tlocal Kit\n\tlocal Hidden = setmetatable({}, {__mode = \"k\"})\n\tlocal Swapped = setmetatable({}, {__mode = \"k\"})\n\tlocal Watched = setmetatable({}, {__mode = \"k\"})\n\tlocal Patterns: {string} = {}\n\tlocal Plain: {string} = {}\n\tlocal Shortest: number = math.huge\n\tlocal TextClasses: {[string]: boolean} = {TextLabel = true, TextButton = true, TextBox = true}\n\tlocal Fake: string = \"hidden\"\n\tlocal Writing: Instance?\n\tlocal OldUsername, OldDisplayName, OldClanTag, OldLevel\n\t\n\tlocal Refreshing: boolean = false\n\t\n\tlocal function QueueRefresh()\n\t    if Refreshing or not NickHider or not NickHider.Enabled then\n\t        return\n\t    end\n\t    Refreshing = true\n\t\n\t    task.delay(0.35, function()\n\t        Refreshing = false\n\t        if NickHider.Enabled then\n\t            NickHider:Toggle()\n\t            NickHider:Toggle()\n\t        end\n\t    end)\n\tend\n\t\n\tlocal function ShouldHidePlayer(Player: Player?)\n\t    return Player and (Player.UserId == LocalPlayer.UserId or HideOthers.Enabled)\n\tend\n\t\n\tlocal function AddPlayerNames(Player: Player)\n\t    for _, v: string in {Player.Name, Player.DisplayName} do\n\t        if v ~= \"\" then\n\t            local LowerName: string = v:lower()\n\t            if not table.find(Plain, LowerName) then\n\t                table.insert(Plain, LowerName)\n\t                Shortest = math.min(Shortest, #LowerName)\n\t            end\n\t        end\n\t        for _, Variant: string in {v, v:lower(), v:upper()} do\n\t            local Pattern: string = (Variant:gsub(\"%W\", \"%%%0\"))\n\t            if Variant ~= \"\" and not table.find(Patterns, Pattern) then\n\t                table.insert(Patterns, Pattern)\n\t            end\n\t        end\n\t    end\n\tend\n\t\n\tlocal function ReplaceText(Object: Instance)\n\t    if Writing == Object then\n\t        return\n\t    end\n\t\n\t    local Text: string = Object.Text\n\t    if type(Text) ~= \"string\" or #Text < Shortest then\n\t        return\n\t    end\n\t\n\t    local Hit: boolean = false\n\t    for _, v: string in Plain do\n\t        if Text:find(v, 1, true) then\n\t            Hit = true\n\t            break\n\t        end\n\t    end\n\t    if not Hit then\n\t        local LowerText: string = Text:lower()\n\t        for _, v: string in Plain do\n\t            if LowerText:find(v, 1, true) then\n\t                Hit = true\n\t                break\n\t            end\n\t        end\n\t    end\n\t    if not Hit then\n\t        return\n\t    end\n\t\n\t    local NewText: string = Text\n\t    for _, v: string in Patterns do\n\t        if NewText:find(v) then\n\t            NewText = NewText:gsub(v, Fake)\n\t        end\n\t    end\n\t    if NewText == Text then\n\t        return\n\t    end\n\t\n\t    Swapped[Object] = Text\n\t    Object:SetAttribute(\"NickHiderOriginalText\", Text)\n\t    Writing = Object\n\t    Object.Text = NewText\n\t    Writing = nil\n\t\n\t    if not Watched[Object] then\n\t        Watched[Object] = Object:GetPropertyChangedSignal(\"Text\"):Connect(function()\n\t            ReplaceText(Object)\n\t        end)\n\t    end\n\tend\n\t\n\tlocal function HideObject(Object: Instance)\n\t    if TextClasses[Object.ClassName] then\n\t        ReplaceText(Object)\n\t    end\n\tend\n\t\n\tlocal function HideKit(Object: Instance)\n\t    if not Kit.Enabled or Object.Name ~= \"PlayerKitFrame\" or Hidden[Object] ~= nil then\n\t        return\n\t    end\n\t\n\t    task.defer(function()\n\t        local Label = Object.Parent and Object.Parent:FindFirstChild(\"PlayerName\", true)\n\t        if not NickHider.Enabled or not Kit.Enabled or not Label or not Label.Text:find(Fake, 1, true) then\n\t            return\n\t        end\n\t\n\t        Hidden[Object] = Object.Visible\n\t        Object.Visible = false\n\t    end)\n\tend\n\t\n\tlocal function Watch(Root: Instance?)\n\t    if not Root then\n\t        return\n\t    end\n\t\n\t    if vape.ThreadFix then\n\t        setthreadidentity(8)\n\t    end\n\t    NickHider:Clean(Root.DescendantAdded:Connect(function(Object: Instance)\n\t        if NickHider.Enabled then\n\t            HideObject(Object)\n\t            HideKit(Object)\n\t        end\n\t    end))\n\t\n\t    local Clock: number = os.clock()\n\t    for _, v: Instance in Root:GetDescendants() do\n\t        HideObject(v)\n\t        HideKit(v)\n\t\n\t        if os.clock() - Clock > 0.002 then\n\t            task.wait()\n\t            if not NickHider.Enabled then\n\t                return\n\t            end\n\t            Clock = os.clock()\n\t\n\t            if vape.ThreadFix then\n\t                setthreadidentity(8)\n\t            end\n\t        end\n\t    end\n\tend\n\t\n\tNickHider = vape.Categories.Utility:CreateModule({\n\t    Name = \"NickHider\",\n\t    ConfigName = \"NameHider\",\n\t    Function = function(Callback: boolean)\n\t        if Callback then\n\t            table.clear(Patterns)\n\t            table.clear(Plain)\n\t            Shortest = math.huge\n\t            for _, Player: Player in Players:GetPlayers() do\n\t                if Player == LocalPlayer or HideOthers.Enabled then\n\t                    AddPlayerNames(Player)\n\t                end\n\t            end\n\t\n\t            Fake = Replacement.Value ~= \"\" and Replacement.Value or \"hidden\"\n\t            for _, v: string in Patterns do\n\t                if Fake:find(v) then\n\t                    Fake = \"hidden\"\n\t                    break\n\t                end\n\t            end\n\t\n\t            local GamePlayer = bedwars.GamePlayerUtil and bedwars.GamePlayerUtil.getGamePlayer(LocalPlayer)\n\t            GamePlayer = GamePlayer and getmetatable(GamePlayer)\n\t            GamePlayer = GamePlayer and GamePlayer.__index\n\t            if GamePlayer and not OldUsername then\n\t                OldUsername, OldDisplayName = GamePlayer.getUsername, GamePlayer.getDisplayName\n\t                OldClanTag, OldLevel = GamePlayer.getClanTag, GamePlayer.getLevel\n\t                GamePlayer.getUsername = function(self, ...)\n\t                    local Player: Player? = self:getPlayer()\n\t                    return ShouldHidePlayer(Player) and Fake or OldUsername(self, ...)\n\t                end\n\t                GamePlayer.getDisplayName = function(self, ...)\n\t                    local Player: Player? = self:getPlayer()\n\t                    return ShouldHidePlayer(Player) and Fake or OldDisplayName(self, ...)\n\t                end\n\t                GamePlayer.getClanTag = function(self, ...)\n\t                    local Player: Player? = self:getPlayer()\n\t                    return (Player and Player.UserId == LocalPlayer.UserId) and ChatTags.Enabled and \"\" or OldClanTag(self, ...)\n\t                end\n\t                GamePlayer.getLevel = function(self, ...)\n\t                    local Player: Player? = self:getPlayer()\n\t                    if Player and (HideOthers.Enabled or (Player.UserId == LocalPlayer.UserId and Level.Enabled)) then\n\t                        return -1\n\t                    end\n\t                    return OldLevel(self, ...)\n\t                end\n\t            end\n\t\n\t            for _, v: Instance in {LocalPlayer:FindFirstChildOfClass(\"PlayerGui\"), CoreGui, gethui and gethui() or nil, LocalPlayer.Character} do\n\t                Watch(v)\n\t            end\n\t\n\t            NickHider:Clean(LocalPlayer.CharacterAdded:Connect(function(Character: Model)\n\t                if NickHider.Enabled then\n\t                    Watch(Character)\n\t                end\n\t            end))\n\t            NickHider:Clean(Players.PlayerAdded:Connect(function()\n\t                if HideOthers.Enabled then\n\t                    QueueRefresh()\n\t                end\n\t            end))\n\t            NickHider:Clean(Players.PlayerRemoving:Connect(function()\n\t                if HideOthers.Enabled then\n\t                    QueueRefresh()\n\t                end\n\t            end))\n\t        else\n\t            local GamePlayer = bedwars.GamePlayerUtil and bedwars.GamePlayerUtil.getGamePlayer(LocalPlayer)\n\t            GamePlayer = GamePlayer and getmetatable(GamePlayer)\n\t            GamePlayer = GamePlayer and GamePlayer.__index\n\t            if OldUsername and GamePlayer then\n\t                GamePlayer.getUsername, GamePlayer.getDisplayName = OldUsername, OldDisplayName\n\t                GamePlayer.getClanTag, GamePlayer.getLevel = OldClanTag, OldLevel\n\t                OldUsername, OldDisplayName, OldClanTag, OldLevel = nil, nil, nil, nil\n\t            end\n\t            if vape.ThreadFix then\n\t                setthreadidentity(8)\n\t            end\n\t\n\t            for _, v: RBXScriptConnection in Watched do\n\t                v:Disconnect()\n\t            end\n\t            table.clear(Watched)\n\t\n\t            for Object: GuiObject, Visible: boolean in Hidden do\n\t                if Object.Parent then\n\t                    Object.Visible = Visible\n\t                end\n\t            end\n\t            table.clear(Hidden)\n\t\n\t            for Object: Instance, OriginalText: string in Swapped do\n\t                if Object.Parent then\n\t                    Writing = Object\n\t                    Object.Text = OriginalText\n\t                    Object:SetAttribute(\"NickHiderOriginalText\", nil)\n\t                end\n\t            end\n\t            Writing = nil\n\t            table.clear(Swapped)\n\t        end\n\t    end,\n\t    Tooltip = \"Replaces your username and display name everywhere it shows up on your screen\",\n\t    ExtraText = function()\n\t        return Replacement.Value ~= \"\" and Replacement.Value or \"hidden\"\n\t    end\n\t})\n\t\n\tReplacement = NickHider:CreateTextBox({\n\t    Name = \"Name\",\n\t    Function = QueueRefresh,\n\t    Default = \"hidden\"\n\t})\n\tHideOthers = NickHider:CreateToggle({\n\t    Name = \"Hide others\",\n\t    Function = QueueRefresh,\n\t    Tooltip = \"Hides every player's username and level\"\n\t})\n\tChatTags = NickHider:CreateToggle({\n\t    Name = \"Hide chat tags\",\n\t    Tooltip = \"Hides your clan tag wherever it renders\"\n\t})\n\tLevel = NickHider:CreateToggle({\n\t    Name = \"Hide level\",\n\t    Function = QueueRefresh,\n\t    Tooltip = \"Hides your level wherever it renders\"\n\t})\n\tKit = NickHider:CreateToggle({\n\t    Name = \"Hide kit\",\n\t    Function = QueueRefresh,\n\t    Tooltip = \"Hides your kit icon in the tab list\"\n\t})\nend)\n\nRun(function()\n\tlocal PhaseMine\n\t\n\tlocal Ignored = setmetatable({}, {__mode = \"k\"})\n\tlocal Watching = setmetatable({}, {__mode = \"k\"})\n\t\n\tlocal function SetIgnored(Part: Instance)\n\t    if Part:IsA(\"BasePart\") and not Ignored[Part] then\n\t        Ignored[Part] = true\n\t        bedwars.QueryUtil:setQueryIgnored(Part, true)\n\t    end\n\tend\n\t\n\tlocal function Added(Character: Model)\n\t    for _, v: BasePart in Character:QueryDescendants(\"BasePart\") do\n\t        SetIgnored(v)\n\t    end\n\t\n\t    if not Watching[Character] then\n\t        Watching[Character] = Character.ChildAdded:Connect(SetIgnored)\n\t    end\n\tend\n\t\n\tPhaseMine = vape.Categories.Utility:CreateModule({\n\t    Name = \"PhaseMine\",\n\t    Function = function(Callback: boolean)\n\t        if Callback then\n\t            PhaseMine:Clean(Entity.Events.EntityAdded:Connect(function(Ent)\n\t                if Ent.Player then\n\t                    task.delay(1, Added, Ent.Character)\n\t                end\n\t            end))\n\t\n\t            for _, v: any in Entity.List do\n\t                if v.Player and v.Player ~= LocalPlayer and v.Character then\n\t                    Added(v.Character)\n\t                end\n\t            end\n\t        else\n\t            for _, v: RBXScriptConnection in Watching do\n\t                v:Disconnect()\n\t            end\n\t            table.clear(Watching)\n\t\n\t            for Part: BasePart in Ignored do\n\t                if Part.Parent then\n\t                    bedwars.QueryUtil:setQueryIgnored(Part, false)\n\t                end\n\t            end\n\t            table.clear(Ignored)\n\t        end\n\t    end,\n\t    Tooltip = \"Allows you to mine through opponents\"\n\t})\nend)\n\nRun(function()\n\tlocal PickupRange\n\tlocal Range\n\tlocal Network\n\tlocal Lower\n\tlocal Picked = setmetatable({}, {__mode = \"k\"})\n\t\n\tPickupRange = vape.Categories.Utility:CreateModule({\n\t    Name = \"PickupRange\",\n\t    Function = function(Callback: boolean)\n\t        if Callback then\n\t            local Items = Collection(\"ItemDrop\", PickupRange)\n\t            repeat\n\t                if Entity.isAlive then\n\t                    local LocalPosition: Vector3 = Entity.character.RootPart.Position\n\t                    for _, v: BasePart in Items do\n\t                        if tick() - (v:GetAttribute(\"ClientDropTime\") or 0) < 2 or Picked[v] then\n\t                            continue\n\t                        end\n\t                        if Network.Enabled and isnetworkowner(v) and Entity.character.Humanoid.Health > 0 then\n\t                            v.CFrame = CFrame.new(LocalPosition - Vector3.new(0, 3, 0))\n\t                        end\n\t\n\t                        if (LocalPosition - v.Position).Magnitude <= Range.Value then\n\t                            if Lower.Enabled and (LocalPosition.Y - v.Position.Y) < (Entity.character.HipHeight - 1) then\n\t                                continue\n\t                            end\n\t                            Picked[v] = true\n\t                            task.spawn(function()\n\t                                bedwars.Handler:Get(\"PickupItemDrop\"):Fire(\"CallServerAsync\", {\n\t                                    itemDrop = v\n\t                                }):andThen(function(Success)\n\t                                    Picked[v] = nil\n\t                                    if Success and bedwars.SoundList then\n\t                                        bedwars.AudioManager:playAudio(bedwars.SoundList.PICKUP_ITEM_DROP)\n\t                                        local Sound = bedwars.ItemMeta[v.Name].pickUpOverlaySound\n\t                                        if Sound then\n\t                                            bedwars.AudioManager:playAudio(Sound, {\n\t                                                position = v.Position,\n\t                                                volumeMultiplier = 0.9\n\t                                            })\n\t                                        end\n\t                                    end\n\t                                end)\n\t                            end)\n\t                        end\n\t                    end\n\t                end\n\t                task.wait(0.1)\n\t            until not PickupRange.Enabled\n\t        end\n\t    end,\n\t    Tooltip = \"Picks up items from a farther distance\"\n\t})\n\t\n\tRange = PickupRange:CreateSlider({\n\t    Name = \"Range\",\n\t    Min = 1,\n\t    Max = 10,\n\t    Default = 10,\n\t    Suffix = function(Val: number)\n\t        return Val == 1 and \"stud\" or \"studs\"\n\t    end\n\t})\n\tNetwork = PickupRange:CreateToggle({\n\t    Name = \"Network TP\",\n\t    Default = true\n\t})\n\tLower = PickupRange:CreateToggle({Name = \"Feet Check\"})\nend)\n\nRun(function()\n\tlocal RegionLock\n\tlocal Regions\n\tlocal Timeout\n\tlocal Requeue\n\t\n\tlocal Status: string = \"Next match\"\n\tlocal ServerRegion: string?\n\tlocal Warned: boolean = false\n\tlocal Requeued: boolean = false\n\tlocal RequeueTries: number = 0\n\tlocal RequeueRetry: number = 0\n\tlocal Aliases: {[string]: string} = {\n\t    AU = \"SEA\",\n\t    AUS = \"SEA\",\n\t    AUSTRALIA = \"SEA\",\n\t    NZ = \"SEA\",\n\t    OCE = \"SEA\",\n\t    OCEANIA = \"SEA\",\n\t    AS = \"SEA\",\n\t    ASIA = \"SEA\",\n\t    SG = \"SEA\",\n\t    SGP = \"SEA\",\n\t    US = \"NA\",\n\t    USA = \"NA\",\n\t    AMERICA = \"NA\",\n\t    EUROPE = \"EU\",\n\t    GB = \"EU\",\n\t    UK = \"EU\"\n\t}\n\t\n\tlocal function Canonical(Value: string): string\n\t    Value = tostring(Value):gsub(\"%s+\", \"\"):upper()\n\t    if Value:match(\"^SG%-%d+$\") then\n\t        return \"SEA\"\n\t    end\n\t    return Aliases[Value] or Value\n\tend\n\t\n\tlocal function GetRegion(): string?\n\t    local Display: Instance? = LocalPlayer.PlayerGui:FindFirstChild(\"ServerRegionDisplay\")\n\t    local Label: TextLabel? = Display and Display:FindFirstChild(\"ServerRegionText\")\n\t    local Region: string? = Label and Label.Text:gsub(\"<[^>]+>\", \"\"):match(\"REGION:%s*(%S+)\") or nil\n\t    if not Region then\n\t        local State = bedwars.Store:getState().Game\n\t        Region = type(State) == \"table\" and type(State.serverRegion) == \"string\" and State.serverRegion ~= \"\" and State.serverRegion or nil\n\t    end\n\t    if Region then\n\t        ServerRegion = Region\n\t    end\n\t    return ServerRegion\n\tend\n\t\n\tlocal function IsRegionAllowed(): boolean\n\t    if #Regions.ListEnabled == 0 then\n\t        return true\n\t    end\n\t\n\t    local Region = GetRegion()\n\t    if not Region then\n\t        return false\n\t    end\n\t\n\t    Region = Canonical(Region)\n\t    for _, v: string in Regions.ListEnabled do\n\t        v = Canonical(v)\n\t        if v ~= \"\" and Region:sub(1, #v) == v then\n\t            return true\n\t        end\n\t    end\n\t    return false\n\tend\n\t\n\tlocal function RequeueMatch(): string?\n\t    local State = bedwars.Store:getState()\n\t    if Requeued or State.Party.queueState ~= 0 then\n\t        Requeued = true\n\t        return \"Requeued\"\n\t    end\n\t\n\t    local Data = TeleportService:GetLocalPlayerTeleportData()\n\t    if (type(Data) == \"table\" and Data.customMatch) or State.Game.customMatch or State.Party.leader.userId ~= LocalPlayer.UserId then\n\t        return nil\n\t    end\n\t\n\t    local Match = type(Data) == \"table\" and Data.match\n\t    local QueueType: string? = Match and Match.queueType or Store.queueType\n\t    local Meta = QueueType and bedwars.QueueMeta[QueueType]\n\t    if not Meta or Meta.disabled then\n\t        return nil\n\t    end\n\t\n\t    if os.clock() >= RequeueRetry then\n\t        if RequeueTries >= 3 then\n\t            return \"Requeue failed\"\n\t        end\n\t        RequeueTries += 1\n\t        RequeueRetry = os.clock() + 5\n\t        pcall(bedwars.QueueController.joinQueue, bedwars.QueueController, QueueType)\n\t    end\n\t    return \"Requeueing\"\n\tend\n\t\n\tlocal function Release()\n\t    if not getgenv().matchDodgeActive then\n\t        if getgenv().dodged and not Store.readyHold.Remote then\n\t            bedwars.Handler:Get(\"PlayerConnect\"):Fire(\"SendToServer\", TeleportService:GetLocalPlayerTeleportData())\n\t        end\n\t        Store.readyHold.Release()\n\t        getgenv().dodged = false\n\t    end\n\tend\n\t\n\tRegionLock = vape.Categories.Utility:CreateModule({\n\t    Name = \"RegionLock\",\n\t    Function = function(Callback: boolean)\n\t        writefile(`{vape.Directory}/profiles/regionlock.txt`, tostring(Callback))\n\t        getgenv().regionLockActive = Callback\n\t        getgenv().regionLockAllowed = not Callback\n\t        if Callback then\n\t            Store.readyHold.Claimed = true\n\t            RegionLock:Clean(coroutine.running())\n\t            Warned = false\n\t            repeat\n\t                if not getgenv().dodged and not Store.readyHold.Held then\n\t                    Status = LocalPlayer:GetAttribute(\"PlayerConnected\") and \"Loaded\" or \"Next match\"\n\t                else\n\t                    local Started: number = Store.readyHold.Started or os.clock()\n\t                    getgenv().regionLockAllowed = IsRegionAllowed()\n\t                    if getgenv().regionLockAllowed then\n\t                        Status = ServerRegion or \"Any region\"\n\t                        Release()\n\t                    elseif ServerRegion then\n\t                        local RequeueStatus: string? = Requeue.Enabled and RequeueMatch() or nil\n\t                        Status = `{RequeueStatus or \"Wrong region\"} ({ServerRegion})`\n\t                    elseif Timeout.Value > 0 and (os.clock() - Started) >= Timeout.Value then\n\t                        if not Warned then\n\t                            Warned = true\n\t                            SendNotification(\"RegionLock\", \"Could not read this server region, loading anyway\", 8, \"warning\")\n\t                        end\n\t                        getgenv().regionLockAllowed = true\n\t                        Status = \"Unknown region\"\n\t                        Release()\n\t                    else\n\t                        Status = \"Finding region\"\n\t                    end\n\t                end\n\t                task.wait(0.5)\n\t            until not RegionLock.Enabled\n\t        else\n\t            Release()\n\t            Status = \"Loaded\"\n\t            Store.readyHold.Claimed = getgenv().matchDodgeActive\n\t        end\n\t    end,\n\t    Tooltip = \"Stays out of matches that are not hosted in one of your selected server regions. BedWars only hosts NA, EU and SEA, and picks yours from your account country, so this can only reject the odd cross-region server, not move you to another region\",\n\t    ExtraText = function()\n\t        return Status\n\t    end\n\t})\n\t\n\tRegions = RegionLock:CreateTextList({\n\t    Name = \"Regions\",\n\t    Placeholder = \"NA / EU / SEA\",\n\t    Default = {\"NA\", \"EU\", \"SEA\"},\n\t    Function = function()\n\t        if not Regions then\n\t            return\n\t        end\n\t        for i: number, v: string in Regions.List do\n\t            Regions.List[i] = v:gsub(\"%s+\", \"\"):upper()\n\t        end\n\t        for i: number, v: string in Regions.ListEnabled do\n\t            Regions.ListEnabled[i] = v:gsub(\"%s+\", \"\"):upper()\n\t        end\n\t    end,\n\t    Tooltip = \"Turn off the regions you do not want. AUS, OCE, AU, NZ and SG data-center codes such as SG-03 count as SEA; US counts as NA. Leaving every region on accepts anything\"\n\t})\n\tTimeout = RegionLock:CreateSlider({\n\t    Name = \"Timeout\",\n\t    Min = 0,\n\t    Max = 120,\n\t    Default = 20,\n\t    Suffix = function(Value: number)\n\t        return Value == 1 and \"second\" or \"seconds\"\n\t    end,\n\t    Tooltip = \"Loads anyway when the server never reports a region. 0 waits forever\"\n\t})\n\tRequeue = RegionLock:CreateToggle({\n\t    Name = \"Requeue\",\n\t    Tooltip = \"When the region is wrong, queues the same mode again from the loading screen (party leader only, up to 3 tries) and keeps you there until the new match is found\"\n\t})\n\t\n\ttask.spawn(function()\n\t    repeat task.wait() until vape.Loaded or vape.Loaded == nil\n\t    local Last = isfile(`{vape.Directory}/profiles/regionlock.json`) and readfile(`{vape.Directory}/profiles/regionlock.json`)\n\t    if vape.Loaded and Last then\n\t        local Success, Response = pcall(HttpService.JSONDecode, HttpService, Last)\n\t        if Success and type(Response) == \"table\" then\n\t            RegionLock:Load(Response)\n\t        end\n\t    end\n\t\n\t    repeat\n\t        if vape.Loaded then\n\t            local Data = {}\n\t            RegionLock:Save(Data)\n\t            Data.RegionLock.Favorited = nil\n\t            local Encoded: string = HttpService:JSONEncode(Data.RegionLock)\n\t            if Encoded ~= Last then\n\t                Last = Encoded\n\t                writefile(`{vape.Directory}/profiles/regionlock.json`, Encoded)\n\t            end\n\t        end\n\t        task.wait(1)\n\t    until vape.Loaded == nil\n\tend)\nend)\n\nRun(function()\n\tlocal ReplayMod\n\tlocal Rate\n\tlocal AutoSave\n\tlocal Replays\n\tlocal Speed\n\tlocal FreeCam\n\tlocal CameraSpeed\n\tlocal Avatars\n\tlocal Animations\n\tlocal Entities\n\tlocal InfoUI\n\tlocal UpdateMode\n\tlocal GameHealthBar\n\tlocal Armor\n\tlocal DamageEffects\n\tlocal Sounds\n\tlocal SoundVolume\n\t\n\tlocal ReplayFolder: string = `{vape.Directory}/replays`\n\tlocal SampleSize: number = 13\n\tlocal LegacySize: number = 8\n\tlocal AnimationSize: number = 4\n\tlocal SoundSize: number = 7\n\tlocal DamageSize: number = 3\n\tlocal DropSize: number = 8\n\tlocal ItemLookup = {}\n\tlocal LoadoutLookup = {}\n\tlocal ArmorLookup = {}\n\tlocal AnimationLookup = {}\n\tlocal DamageLookup = {}\n\tlocal NpcNames = setmetatable({}, {__mode = \"k\"})\n\tlocal NpcModels = setmetatable({}, {__mode = \"k\"})\n\tlocal NpcSearches = setmetatable({}, {__mode = \"k\"})\n\tlocal NpcCount: number = 0\n\tlocal DropIds = setmetatable({}, {__mode = \"k\"})\n\tlocal DropLive = {}\n\tlocal DropCount: number = 0\n\tlocal SoundLookup = {}\n\tlocal AnimationWatchers = {}\n\tlocal BlockSize: number = 6\n\tlocal MapSize: number = 10\n\tlocal HotbarSize: number = 20\n\tlocal ReplayVisuals = vape.Libraries.replayvisuals\n\tlocal FeedLive = setmetatable({}, {__mode = \"k\"})\n\tlocal PropSize: number = 14\n\tlocal ReplayOffset: Vector3 = Vector3.new(0, 1500, 0)\n\tlocal Recording, Playback, FreeCamState, Timeline, Accumulator = nil, nil, nil, nil, 0\n\tlocal OldPlaySound, MuteSounds = nil, false\n\t\n\tif not isfolder(`{vape.Directory}/replays`) then\n\t    makefolder(`{vape.Directory}/replays`)\n\tend\n\t\n\tlocal DefaultAnimations = {\n\t    Idle = \"rbxassetid://507766666\",\n\t    Walk = \"rbxassetid://507777826\",\n\t    Run = \"rbxassetid://507767714\",\n\t    Fall = \"rbxassetid://507767968\"\n\t}\n\t\n\tlocal BodySlots = {\n\t    Head = 1,\n\t    UpperTorso = 2,\n\t    LowerTorso = 2,\n\t    LeftUpperArm = 3,\n\t    LeftLowerArm = 3,\n\t    LeftHand = 3,\n\t    RightUpperArm = 4,\n\t    RightLowerArm = 4,\n\t    RightHand = 4,\n\t    LeftUpperLeg = 5,\n\t    LeftLowerLeg = 5,\n\t    LeftFoot = 5,\n\t    RightUpperLeg = 6,\n\t    RightLowerLeg = 6,\n\t    RightFoot = 6\n\t}\n\t\n\tlocal BodyFields: {string} = {\"HeadColor3\", \"TorsoColor3\", \"LeftArmColor3\", \"RightArmColor3\", \"LeftLegColor3\", \"RightLegColor3\"}\n\t\n\tlocal BlockTints = {\n\t    {\"white\", Color3.fromRGB(236, 236, 236)},\n\t    {\"black\", Color3.fromRGB(38, 38, 42)},\n\t    {\"grey\", Color3.fromRGB(130, 130, 134)},\n\t    {\"gray\", Color3.fromRGB(130, 130, 134)},\n\t    {\"red\", Color3.fromRGB(196, 62, 56)},\n\t    {\"orange\", Color3.fromRGB(226, 132, 48)},\n\t    {\"yellow\", Color3.fromRGB(226, 202, 62)},\n\t    {\"lime\", Color3.fromRGB(140, 210, 70)},\n\t    {\"green\", Color3.fromRGB(84, 158, 74)},\n\t    {\"cyan\", Color3.fromRGB(78, 190, 196)},\n\t    {\"blue\", Color3.fromRGB(66, 112, 196)},\n\t    {\"purple\", Color3.fromRGB(134, 78, 186)},\n\t    {\"magenta\", Color3.fromRGB(196, 84, 168)},\n\t    {\"pink\", Color3.fromRGB(226, 148, 186)},\n\t    {\"brown\", Color3.fromRGB(122, 84, 56)},\n\t    {\"wood\", Color3.fromRGB(158, 116, 74)},\n\t    {\"plank\", Color3.fromRGB(168, 128, 82)},\n\t    {\"sand\", Color3.fromRGB(214, 198, 146)},\n\t    {\"stone\", Color3.fromRGB(126, 126, 130)},\n\t    {\"marble\", Color3.fromRGB(214, 212, 206)},\n\t    {\"obsidian\", Color3.fromRGB(52, 44, 68)},\n\t    {\"ice\", Color3.fromRGB(170, 210, 232)},\n\t    {\"glass\", Color3.fromRGB(198, 222, 232)},\n\t    {\"grass\", Color3.fromRGB(96, 158, 72)},\n\t    {\"dirt\", Color3.fromRGB(122, 92, 62)},\n\t    {\"gold\", Color3.fromRGB(226, 186, 68)},\n\t    {\"iron\", Color3.fromRGB(186, 186, 190)},\n\t    {\"emerald\", Color3.fromRGB(72, 196, 118)},\n\t    {\"diamond\", Color3.fromRGB(110, 214, 220)}\n\t}\n\t\n\tlocal function GetMatchStart()\n\t    local State = bedwars.Store:getState().Game\n\t    local StartTime: number = State and State.startTime or 0\n\t    return StartTime > 0 and StartTime or 0\n\tend\n\t\n\tlocal function GetMatchId(StartTime: number)\n\t    local JobId: string = tostring(game.JobId):gsub(\"%-\", \"\"):sub(1, 8)\n\t    return `{JobId} {os.date(\"%Y-%m-%d %H-%M\", StartTime > 0 and StartTime or os.time())}`\n\tend\n\t\n\tlocal function GetReplayDate(FileName: string)\n\t    local Written: string? = FileName:match(\"(%d%d%d%d%-%d%d%-%d%d %d%d%-%d%d)\")\n\t    if Written then\n\t        return Written\n\t    end\n\t\n\t    local Legacy: number? = tonumber(FileName:match(\"_(%d+)%-\"))\n\t    return Legacy and os.date(\"%Y-%m-%d %H-%M\", Legacy) or \"\"\n\tend\n\t\n\tlocal function GetPaletteIndex(Palette, Lookup, Value)\n\t    local Index: number? = Lookup[Value]\n\t    if not Index then\n\t        table.insert(Palette, Value)\n\t        Index = #Palette\n\t        Lookup[Value] = Index\n\t    end\n\t    return Index\n\tend\n\t\n\tlocal function GetLoadoutIndex(Player: Player?)\n\t    local Inventory = Player == LocalPlayer and store.inventory.inventory or (store.inventories[Player] or {})\n\t    local List = {}\n\t\n\t    for _, v: any in (Inventory.items or {}) do\n\t        if v.itemType then\n\t            table.insert(List, {v.itemType, v.amount or 1})\n\t        end\n\t    end\n\t    table.sort(List, function(A, B)\n\t        return A[1] < B[1]\n\t    end)\n\t\n\t    local Parts: {string} = {}\n\t    for _, v: any in List do\n\t        table.insert(Parts, `{v[1]}:{v[2]}`)\n\t    end\n\t\n\t    local Signature: string = table.concat(Parts, \",\")\n\t    local Index: number? = LoadoutLookup[Signature]\n\t    if not Index then\n\t        local Encoded = {}\n\t        for _, v: any in List do\n\t            table.insert(Encoded, GetPaletteIndex(Recording.Items, ItemLookup, v[1]))\n\t            table.insert(Encoded, v[2])\n\t        end\n\t        table.insert(Recording.Loadouts, Encoded)\n\t        Index = #Recording.Loadouts\n\t        LoadoutLookup[Signature] = Index\n\t    end\n\t\n\t    return Index\n\tend\n\t\n\tlocal function GetNpcVisual(Character: Model, Root: BasePart)\n\t    local Cached = NpcModels[Character]\n\t    if Cached and Cached.Parent and (Cached:GetPivot().Position - Root.Position).Magnitude <= 3 then\n\t        return Cached\n\t    end\n\t\n\t    local Now: number = os.clock()\n\t    if (NpcSearches[Character] or 0) > Now then\n\t        return nil\n\t    end\n\t    NpcSearches[Character] = Now + 1\n\t\n\t    local Closest, Distance = nil, 3\n\t    for _, v: Model in workspace:GetChildren() do\n\t        if v ~= Character and v:IsA(\"Model\") and v:FindFirstChildWhichIsA(\"AnimationController\") then\n\t            local Gap: number = (v:GetPivot().Position - Root.Position).Magnitude\n\t            if Gap < Distance then\n\t                Closest, Distance = v, Gap\n\t            end\n\t        end\n\t    end\n\t\n\t    NpcModels[Character] = Closest\n\t    return Closest\n\tend\n\t\n\tlocal function ClearWatchers()\n\t    for _, v: {Animator: Animator, Connection: RBXScriptConnection} in AnimationWatchers do\n\t        v.Connection:Disconnect()\n\t    end\n\t    table.clear(AnimationWatchers)\n\tend\n\t\n\tlocal function RecordAnimation(Track, Action: number, AnimationId: string, AnimationSpeed: number)\n\t    if not Recording then\n\t        return\n\t    end\n\t\n\t    table.insert(Track.Anims, (math.floor((os.clock() - Recording.Start) * 1000 + 0.5) / 1000))\n\t    table.insert(Track.Anims, Action)\n\t    table.insert(Track.Anims, GetPaletteIndex(Recording.AnimIds, AnimationLookup, AnimationId))\n\t    table.insert(Track.Anims, (math.floor(AnimationSpeed * 100 + 0.5) / 100))\n\tend\n\t\n\tlocal function RecordDrop(Action: number, Id: number, ItemType: string?, DropCFrame: CFrame?)\n\t    local Stream = Recording.Drops\n\t    table.insert(Stream, (math.floor((os.clock() - Recording.Start) * 1000 + 0.5) / 1000))\n\t    table.insert(Stream, Action)\n\t    table.insert(Stream, Id)\n\t    table.insert(Stream, ItemType and GetPaletteIndex(Recording.Items, ItemLookup, ItemType) or 1)\n\t    table.insert(Stream, DropCFrame and (math.floor(DropCFrame.X * 100 + 0.5) / 100) or 0)\n\t    table.insert(Stream, DropCFrame and (math.floor(DropCFrame.Y * 100 + 0.5) / 100) or 0)\n\t    table.insert(Stream, DropCFrame and (math.floor(DropCFrame.Z * 100 + 0.5) / 100) or 0)\n\t    table.insert(Stream, DropCFrame and (math.floor(math.deg(select(2, DropCFrame:ToEulerAnglesYXZ())) * 100 + 0.5) / 100) or 0)\n\tend\n\t\n\tlocal function RecordDrops()\n\t    local Drops: Instance? = workspace:FindFirstChild(\"ItemDrops\")\n\t    if not Drops then\n\t        return\n\t    end\n\t\n\t    local Seen = {}\n\t    for _, v: BasePart in Drops:GetChildren() do\n\t        if v:IsA(\"BasePart\") then\n\t            local Id: number? = DropIds[v]\n\t            if not Id then\n\t                DropCount += 1\n\t                Id = DropCount\n\t                DropIds[v] = Id\n\t            end\n\t            Seen[Id] = true\n\t\n\t            local DropCFrame: CFrame = v.CFrame\n\t            local LastPosition: Vector3? = DropLive[Id]\n\t            if not LastPosition or (LastPosition - DropCFrame.Position).Magnitude > 0.2 then\n\t                DropLive[Id] = DropCFrame.Position\n\t                RecordDrop(1, Id, v.Name, DropCFrame)\n\t            end\n\t        end\n\t    end\n\t\n\t    for Id: number in DropLive do\n\t        if not Seen[Id] then\n\t            DropLive[Id] = nil\n\t            RecordDrop(0, Id)\n\t        end\n\t    end\n\tend\n\t\n\tlocal function RecordFeed(Now: number)\n\t    local Gui: ScreenGui? = LocalPlayer.PlayerGui:FindFirstChild(\"KillFeedGui\")\n\t    local Container: Instance? = Gui and Gui:FindFirstChild(\"KillFeedContainer\")\n\t    if not Container then return end\n\t    for _, v: Instance in Container:GetChildren() do\n\t        if not v:IsA(\"GuiObject\") then continue end\n\t        local Entry = FeedLive[v]\n\t        if not Entry then\n\t            Entry = {Time = Now, Duration = 5, Gui = ReplayVisuals.Capture(v)}\n\t            FeedLive[v] = Entry\n\t            table.insert(Recording.GameFeed, Entry)\n\t        elseif not Entry.Ready and Now - Entry.Time >= 0.15 then\n\t            Entry.Gui = ReplayVisuals.Capture(v)\n\t            Entry.Ready = true\n\t        end\n\t    end\n\t    for Object: Instance, Entry: any in FeedLive do\n\t        if Object.Parent ~= Container then\n\t            Entry.Duration = math.max(Now - Entry.Time, 0.1)\n\t            FeedLive[Object] = nil\n\t        end\n\t    end\n\tend\n\t\n\tlocal function Sample()\n\t    local Now: number = (math.floor((os.clock() - Recording.Start) * 1000 + 0.5) / 1000)\n\t\n\t    if Recording.StartTime == 0 then\n\t        local StartTime: number = GetMatchStart()\n\t        if StartTime > 0 then\n\t            Recording.StartTime = StartTime\n\t            Recording.MatchId = GetMatchId(StartTime)\n\t        end\n\t    end\n\t\n\t    local function Record(Ent)\n\t        if not Ent.RootPart or not Ent.Character then\n\t            return\n\t        end\n\t\n\t        local Player: Player? = Ent.Player\n\t        if not Player and not Entities.Enabled then\n\t            return\n\t        end\n\t\n\t        local Name: string? = Player and Player.Name or NpcNames[Ent.Character]\n\t        if not Name then\n\t            NpcCount += 1\n\t            Name = `{Ent.Character.Name} #{NpcCount}`\n\t            NpcNames[Ent.Character] = Name\n\t        end\n\t\n\t        local Visual: Model? = not Player and GetNpcVisual(Ent.Character, Ent.RootPart) or nil\n\t        local Track = Recording.Tracks[Name]\n\t        if not Track then\n\t            local TeamColor: Color3 = Entity.getEntityColor(Ent) or Color3.new(1, 1, 1)\n\t            local ModelName\n\t            if Player == nil then\n\t                local Assets: Instance? = ReplicatedStorage:FindFirstChild(\"Assets\")\n\t                local Misc = Assets and Assets:FindFirstChild(\"Misc\")\n\t                if Misc then\n\t                    if Visual and Misc:FindFirstChild(Visual.Name) then\n\t                        ModelName = Visual.Name\n\t                    else\n\t                        local Stripped: string = (Ent.Character.Name:gsub(\" \", \"\"))\n\t                        ModelName = Misc:FindFirstChild(Stripped) and Stripped or nil\n\t                    end\n\t                end\n\t            end\n\t\n\t            local Colors: BodyColors? = Ent.Character:FindFirstChildWhichIsA(\"BodyColors\")\n\t            local RigColors\n\t            if Colors then\n\t                RigColors = {}\n\t                for _, v: string in BodyFields do\n\t                    local Value: Color3 = Colors[v]\n\t                    table.insert(RigColors, {math.floor(Value.R * 255), math.floor(Value.G * 255), math.floor(Value.B * 255)})\n\t                end\n\t            end\n\t\n\t            Track = {\n\t                UserId = Player and Player.UserId or 0,\n\t                NPC = Player == nil or nil,\n\t                Model = ModelName,\n\t                Color = {math.floor(TeamColor.R * 255), math.floor(TeamColor.G * 255), math.floor(TeamColor.B * 255)},\n\t                MaxHealth = (math.floor((Ent.MaxHealth or 100) * 10 + 0.5) / 10),\n\t                Rig = RigColors,\n\t                Data = {},\n\t                Anims = {}\n\t            }\n\t            Recording.Tracks[Name] = Track\n\t        end\n\t\n\t        local Rig: Model = Visual or Ent.Character\n\t        local Controller = Rig and (Rig:FindFirstChildWhichIsA(\"Humanoid\") or Rig:FindFirstChildWhichIsA(\"AnimationController\"))\n\t        local Animator = Controller and Controller:FindFirstChildWhichIsA(\"Animator\")\n\t        local Watcher = AnimationWatchers[Ent.Character]\n\t        if Animator and not (Watcher and Watcher.Animator == Animator) then\n\t            if Watcher then\n\t                Watcher.Connection:Disconnect()\n\t            end\n\t\n\t            AnimationWatchers[Ent.Character] = {\n\t                Animator = Animator,\n\t                Connection = Animator.AnimationPlayed:Connect(function(Playing: AnimationTrack)\n\t                    local AnimationId: string = Recording and Animations.Enabled and Playing.Animation and Playing.Animation.AnimationId or \"\"\n\t                    if AnimationId == \"\" then\n\t                        return\n\t                    end\n\t\n\t                    RecordAnimation(Track, 1, AnimationId, Playing.Speed)\n\t                    Playing.Stopped:Once(function()\n\t                        RecordAnimation(Track, 0, AnimationId, Playing.Speed)\n\t                    end)\n\t                end)\n\t            }\n\t        end\n\t\n\t        local Stream = Track.Data\n\t        if #Stream >= SampleSize and Stream[#Stream - (SampleSize - 1)] == Now then\n\t            return\n\t        end\n\t\n\t        local Held = Player == LocalPlayer and store.inventory.inventory.hand or (Player and store.inventories[Player] or {}).hand\n\t        Held = Held and (Held.itemType or Held.tool and Held.tool.Name) or \"\"\n\t\n\t        local RootCFrame: CFrame = Ent.RootPart.CFrame\n\t        local Pitch, Yaw = (Visual and Visual:GetPivot() or RootCFrame):ToEulerAnglesYXZ()\n\t        local Velocity: Vector3 = Ent.RootPart.AssemblyLinearVelocity\n\t        table.insert(Stream, Now)\n\t        table.insert(Stream, (math.floor(RootCFrame.X * 100 + 0.5) / 100))\n\t        table.insert(Stream, (math.floor(RootCFrame.Y * 100 + 0.5) / 100))\n\t        table.insert(Stream, (math.floor(RootCFrame.Z * 100 + 0.5) / 100))\n\t        table.insert(Stream, (math.floor(math.deg(Yaw) * 100 + 0.5) / 100))\n\t        table.insert(Stream, (math.floor(math.deg(Pitch) * 100 + 0.5) / 100))\n\t        table.insert(Stream, (math.floor(Velocity.X * 100 + 0.5) / 100))\n\t        table.insert(Stream, (math.floor(Velocity.Y * 100 + 0.5) / 100))\n\t        table.insert(Stream, (math.floor(Velocity.Z * 100 + 0.5) / 100))\n\t        table.insert(Stream, (math.floor(Ent.Health * 10 + 0.5) / 10))\n\t        table.insert(Stream, GetPaletteIndex(Recording.Items, ItemLookup, Held))\n\t        table.insert(Stream, GetLoadoutIndex(Player))\n\t        local ArmorSet = {}\n\t        for Slot: number = 0, 2 do\n\t            local Holder: ObjectValue? = Ent.Character:FindFirstChild(`ArmorInvItem_{Slot}`)\n\t            local Worn = Holder and Holder.Value\n\t            table.insert(ArmorSet, GetPaletteIndex(Recording.Items, ItemLookup, (Worn and Worn.Name or \"\")))\n\t        end\n\t\n\t        local Signature: string = table.concat(ArmorSet, \",\")\n\t        if not ArmorLookup[Signature] then\n\t            table.insert(Recording.Armors, ArmorSet)\n\t            ArmorLookup[Signature] = #Recording.Armors\n\t        end\n\t        table.insert(Stream, ArmorLookup[Signature])\n\t\n\t        local Inventory = Player == LocalPlayer and store.inventory or store.inventories[Player]\n\t        local Hotbar = Inventory and Inventory.hotbar\n\t        if not Hotbar then\n\t            return\n\t        end\n\t\n\t        Track.Hotbar = Track.Hotbar or {}\n\t        local Slots = Track.Hotbar\n\t        local Changed: boolean = #Slots < HotbarSize\n\t        local Row = {}\n\t        for i: number = 1, 9 do\n\t            local Item = Hotbar[i] and Hotbar[i].item\n\t            table.insert(Row, Item and GetPaletteIndex(Recording.Items, ItemLookup, Item.itemType) or 0)\n\t            table.insert(Row, Item and (math.floor((Item.amount or 1) * 10 + 0.5) / 10) or 0)\n\t            if not Changed and (Slots[#Slots - (HotbarSize - 1) + (i * 2) - 1] ~= Row[i * 2 - 1] or Slots[#Slots - (HotbarSize - 1) + (i * 2)] ~= Row[i * 2]) then\n\t                Changed = true\n\t            end\n\t        end\n\t\n\t        table.insert(Row, Inventory.hotbarSlot or -1)\n\t        if not Changed and Slots[#Slots] ~= Row[#Row] then Changed = true end\n\t        if Changed then\n\t            table.insert(Slots, Now)\n\t            for _, v: number in Row do\n\t                table.insert(Slots, v)\n\t            end\n\t        end\n\t    end\n\t\n\t    if Entity.isAlive then\n\t        Record(Entity.character)\n\t    end\n\t\n\t    for _, v: any in Entity.List do\n\t        Record(v)\n\t    end\n\t    RecordDrops()\n\t    RecordFeed(Now)\n\t\n\t    if Recording.Beds then\n\t        for _, v: Instance in CollectionService:GetTagged(\"bed\") do\n\t            local Entry = Recording.Beds[tostring(v:GetAttribute(\"Id\") or v:GetAttribute(\"id\") or v.Name)]\n\t            if Entry and Entry.Data[#Entry.Data - 3] ~= Now then\n\t                table.insert(Entry.Data, Now)\n\t                local BlockPosition = v:GetAttribute(\"BlockPosition\")\n\t                if not BlockPosition and v:IsA(\"BasePart\") then\n\t                    local Success, Resolved = pcall(bedwars.BlockController.getBlockPosition, bedwars.BlockController, v.Position)\n\t                    BlockPosition = Success and Resolved or nil\n\t                end\n\t\n\t                local Health\n\t                if BlockPosition then\n\t                    local Success, Data = pcall(function()\n\t                        return bedwars.BlockController:getStore():getBlockData(BlockPosition)\n\t                    end)\n\t                    Health = Success and Data and (Data:GetAttribute(\"1\") or Data:GetAttribute(\"Health\")) or nil\n\t                end\n\t\n\t                table.insert(Entry.Data, (math.floor((Health or v:GetAttribute(\"Health\") or 0) * 10 + 0.5) / 10))\n\t                table.insert(Entry.Data, (math.floor((v:GetAttribute(\"MaxHealth\") or 1) * 10 + 0.5) / 10))\n\t                table.insert(Entry.Data, (math.floor((v:GetAttribute(\"BedPlatingAmount\") or 0) * 10 + 0.5) / 10))\n\t            end\n\t        end\n\t    end\n\tend\n\t\n\tlocal function StartRecording()\n\t    local StartTime: number = GetMatchStart()\n\t\n\t    Recording = {\n\t        Version = 3,\n\t        HotbarStride = HotbarSize,\n\t        HUD = ReplayVisuals.Capture(LocalPlayer.PlayerGui:FindFirstChild(\"hotbar\")),\n\t        FeedLayout = ReplayVisuals.Capture(LocalPlayer.PlayerGui:FindFirstChild(\"KillFeedGui\") and LocalPlayer.PlayerGui.KillFeedGui:FindFirstChild(\"KillFeedContainer\")),\n\t        GameFeed = {},\n\t        Stride = SampleSize,\n\t        MatchId = GetMatchId(StartTime),\n\t        StartTime = StartTime,\n\t        JobId = game.JobId,\n\t        Map = store.map and store.map.Name or \"Unknown\",\n\t        Queue = store.queueType,\n\t        Date = os.time(),\n\t        Rate = Rate.Value,\n\t        Items = {\"\"},\n\t        AnimIds = {},\n\t        SoundIds = {},\n\t        DamageTypes = {},\n\t        Tracks = {},\n\t        Blocks = {},\n\t        Drops = {},\n\t        Loadouts = {},\n\t        Armors = {},\n\t        Events = {},\n\t        SoundStream = {},\n\t        Start = os.clock()\n\t    }\n\t    ClearWatchers()\n\t    table.clear(ItemLookup)\n\t    table.clear(LoadoutLookup)\n\t    table.clear(ArmorLookup)\n\t    table.clear(AnimationLookup)\n\t    table.clear(DamageLookup)\n\t    table.clear(SoundLookup)\n\t    table.clear(DropLive)\n\t    table.clear(FeedLive)\n\t    ItemLookup[\"\"] = 1\n\tend\n\t\n\tlocal function SnapshotMap()\n\t    local MapRoot: Instance? = workspace:FindFirstChild(\"Map\")\n\t    local Worlds = MapRoot and MapRoot:FindFirstChild(\"Worlds\")\n\t    local World = Worlds and Worlds:GetChildren()[1]\n\t    local Blocks = World and World:FindFirstChild(\"Blocks\")\n\t    if not Blocks then\n\t        return\n\t    end\n\t\n\t    local Palette, Lookup, Stream = {}, {}, {}\n\t\n\t    local function AddBlock(Block: BasePart)\n\t        local Variant: string = \"\"\n\t        pcall(function()\n\t            Variant = Block.MaterialVariant\n\t        end)\n\t\n\t        local Appearance = ReplayVisuals.CaptureAppearance(Block)\n\t        local Key: string = `{HttpService:JSONEncode(Appearance)}|{Block.Name}|{Block.BrickColor.Number}|{Block.Material.Name}|{Variant}|{Block.Transparency}|{Block.ClassName}`\n\t        local Index: number = Lookup[Key]\n\t        if not Index then\n\t            table.insert(Palette, {Block.Name, math.floor(Block.Color.R * 255), math.floor(Block.Color.G * 255), math.floor(Block.Color.B * 255), Block.Material.Name, Variant, (math.floor(Block.Transparency * 100 + 0.5) / 100), Block.ClassName, Appearance})\n\t            Index = #Palette\n\t            Lookup[Key] = Index\n\t        end\n\t\n\t        table.insert(Stream, (math.floor(Block.Position.X * 10 + 0.5) / 10))\n\t        table.insert(Stream, (math.floor(Block.Position.Y * 10 + 0.5) / 10))\n\t        table.insert(Stream, (math.floor(Block.Position.Z * 10 + 0.5) / 10))\n\t        table.insert(Stream, (math.floor(Block.Size.X * 1000 + 0.5) / 1000))\n\t        table.insert(Stream, (math.floor(Block.Size.Y * 1000 + 0.5) / 1000))\n\t        table.insert(Stream, (math.floor(Block.Size.Z * 1000 + 0.5) / 1000))\n\t        table.insert(Stream, Index)\n\t        local X, Y, Z = Block.CFrame:ToEulerAnglesYXZ()\n\t        table.insert(Stream, X)\n\t        table.insert(Stream, Y)\n\t        table.insert(Stream, Z)\n\t    end\n\t\n\t    for _, v: BasePart in Blocks:GetChildren() do\n\t        if v:IsA(\"BasePart\") then\n\t            AddBlock(v)\n\t            for _, v: BasePart in v:GetChildren() do\n\t                if v:IsA(\"BasePart\") and v.Transparency < 1 then\n\t                    AddBlock(v)\n\t                end\n\t            end\n\t        end\n\t    end\n\t\n\t    local Props = {}\n\t    for _, v: string in {\"chest\", \"team-crate\"} do\n\t        for _, v: Instance in CollectionService:GetTagged(v) do\n\t            local Pivot: CFrame = v:IsA(\"BasePart\") and v.CFrame or v:GetPivot()\n\t            table.insert(Props, 1)\n\t            table.insert(Props, GetPaletteIndex(Recording.Items, ItemLookup, v.Name))\n\t            for _, Component: number in {Pivot:GetComponents()} do\n\t                table.insert(Props, (math.floor(Component * 10 + 0.5) / 10))\n\t            end\n\t        end\n\t    end\n\t\n\t    Recording.Beds = {}\n\t    for _, v: Instance in CollectionService:GetTagged(\"bed\") do\n\t        local Id: string = tostring(v:GetAttribute(\"Id\") or v:GetAttribute(\"id\") or v.Name)\n\t        local Pivot: CFrame = v:IsA(\"BasePart\") and v.CFrame or v:GetPivot()\n\t        local Components = {}\n\t        for _, v: number in {Pivot:GetComponents()} do\n\t            table.insert(Components, (math.floor(v * 10 + 0.5) / 10))\n\t        end\n\t\n\t        local Colors = {}\n\t        if v:IsA(\"BasePart\") then\n\t            Colors.Root = {math.floor((v.Color).R * 255), math.floor((v.Color).G * 255), math.floor((v.Color).B * 255)}\n\t        end\n\t        for _, v: BasePart in v:GetDescendants() do\n\t            if v:IsA(\"BasePart\") then\n\t                Colors[v.Name] = {math.floor((v.Color).R * 255), math.floor((v.Color).G * 255), math.floor((v.Color).B * 255)}\n\t            end\n\t        end\n\t\n\t        local TeamId = v:GetAttribute(\"TeamId\") or tonumber(Id:match(\"^(%d+)\"))\n\t        local TeamName: string = \"\"\n\t        for _, v: any in (bedwars.Store:getState().Game.teams or {}) do\n\t            if type(v) == \"table\" and tostring(v.id) == tostring(TeamId) then\n\t                TeamName = tostring(v.name)\n\t            end\n\t        end\n\t\n\t        Recording.Beds[Id] = {Name = v.Name, Team = TeamName, Colors = Colors, CFrame = Components, Data = {}}\n\t    end\n\t\n\t    Recording.World = Stream\n\t    Recording.Props = Props\n\t    Recording.Palette = Palette\n\t    Recording.MapStride = MapSize\n\t    if Recording.Map == \"Unknown\" then\n\t        Recording.Map = World.Name\n\t    end\n\tend\n\t\n\tlocal function DescribeEntity(Value)\n\t    if typeof(Value) == \"Instance\" then\n\t        return Value.Name\n\t    end\n\t    if typeof(Value) == \"string\" then\n\t        return Value\n\t    end\n\t    if type(Value) == \"table\" then\n\t        return tostring(Value.Name or Value.name or Value.displayName or \"\")\n\t    end\n\t    return \"\"\n\tend\n\t\n\tlocal function RecordEvent(Text: string)\n\t    if not Recording or Text == \"\" then\n\t        return\n\t    end\n\t\n\t    table.insert(Recording.Events, (math.floor((os.clock() - Recording.Start) * 1000 + 0.5) / 1000))\n\t    table.insert(Recording.Events, Text)\n\tend\n\t\n\tlocal function RecordBlock(Action: number, BlockPosition, BlockType: string?)\n\t    if not Recording or typeof(BlockPosition) ~= \"Vector3\" then\n\t        return\n\t    end\n\t\n\t    local Stream = Recording.Blocks\n\t    table.insert(Stream, (math.floor((os.clock() - Recording.Start) * 1000 + 0.5) / 1000))\n\t    table.insert(Stream, Action)\n\t    table.insert(Stream, BlockPosition.X)\n\t    table.insert(Stream, BlockPosition.Y)\n\t    table.insert(Stream, BlockPosition.Z)\n\t    table.insert(Stream, GetPaletteIndex(Recording.Items, ItemLookup, (BlockType or \"\")))\n\tend\n\t\n\tlocal function SaveRecording()\n\t    if not Recording or not next(Recording.Tracks) then\n\t        return nil\n\t    end\n\t\n\t    local Mode: string? = tostring(Recording.Map):match(\"^([^_]+)_\")\n\t    local FileName: string = `{Mode and `{Mode}_` or \"\"}{Recording.MatchId}.json`\n\t    local Success: boolean = pcall(function()\n\t        writefile(`{ReplayFolder}/{FileName}`, HttpService:JSONEncode(Recording))\n\t    end)\n\t\n\t    return Success and FileName or nil\n\tend\n\t\n\tlocal function RefreshList()\n\t    local List = {}\n\t\n\t    for _, v: string in listfiles(ReplayFolder) do\n\t        local FileName: string? = v:match(\"([^/\\\\]+)$\")\n\t        if FileName and FileName:sub(-5) == \".json\" then\n\t            table.insert(List, FileName)\n\t        end\n\t    end\n\t\n\t    table.sort(List, function(A: string, B: string)\n\t        local DateA, DateB = GetReplayDate(A), GetReplayDate(B)\n\t        if DateA ~= DateB then\n\t            return DateA > DateB\n\t        end\n\t        return A > B\n\t    end)\n\t    if #List == 0 then\n\t        table.insert(List, \"None\")\n\t    end\n\t\n\t    Replays:Change(List)\n\t    return List\n\tend\n\t\n\tlocal BarLooks = {\n\t    Health = {\n\t        Icon = \"BED_HEALTH_ICON\",\n\t        Tint = Color3.fromRGB(53, 238, 49),\n\t        Gradient = ColorSequence.new(Color3.fromRGB(33, 161, 45), Color3.fromRGB(53, 238, 49))\n\t    },\n\t    Plating = {\n\t        Icon = \"BED_PLATING_ICON\",\n\t        Tint = Color3.fromRGB(88, 213, 253),\n\t        Gradient = ColorSequence.new(Color3.fromRGB(59, 125, 196), Color3.fromRGB(88, 213, 253))\n\t    }\n\t}\n\t\n\tlocal function BuildGameBar(Parent: Instance, Look, Size: UDim2, Position: UDim2)\n\t    local Container: Frame = Instance.new(\"Frame\")\n\t    Container.Name = \"BarContainer\"\n\t    Container.Size = Size\n\t    Container.Position = Position\n\t    Container.BackgroundTransparency = 1\n\t    Container.Parent = Parent\n\t\n\t    local Wrapper: Frame = Instance.new(\"Frame\")\n\t    Wrapper.Name = \"BarWrapper\"\n\t    Wrapper.Size = UDim2.fromScale(0.88, 1)\n\t    Wrapper.AnchorPoint = Vector2.new(0, 0.5)\n\t    Wrapper.Position = UDim2.fromScale(0, 0.5)\n\t    Wrapper.BackgroundTransparency = 1\n\t    Wrapper.Parent = Container\n\t\n\t    local BarContainer: Frame = Instance.new(\"Frame\")\n\t    BarContainer.Name = \"ProgressBarContainer\"\n\t    BarContainer.Size = UDim2.fromScale(1, 0.8)\n\t    BarContainer.AnchorPoint = Vector2.new(0, 0.5)\n\t    BarContainer.Position = UDim2.fromScale(0, 0.5)\n\t    BarContainer.BackgroundTransparency = 1\n\t    BarContainer.Parent = Wrapper\n\t\n\t    local Background: Frame = Instance.new(\"Frame\")\n\t    Background.Name = \"ProgressBarBackground\"\n\t    Background.Size = UDim2.fromScale(1, 1)\n\t    Background.BackgroundColor3 = Color3.new()\n\t    Background.BorderSizePixel = 0\n\t    Background.Parent = BarContainer\n\t\n\t    local BackCorner: UICorner = Instance.new(\"UICorner\")\n\t    BackCorner.CornerRadius = UDim.new(0.1)\n\t    BackCorner.Parent = Background\n\t\n\t    local Fill: Frame = Instance.new(\"Frame\")\n\t    Fill.Name = \"ProgressBar\"\n\t    Fill.Size = UDim2.fromScale(1, 1)\n\t    Fill.AnchorPoint = Vector2.new(0, 0.5)\n\t    Fill.Position = UDim2.fromScale(0, 0.5)\n\t    Fill.BackgroundColor3 = Color3.new(1, 1, 1)\n\t    Fill.BorderSizePixel = 0\n\t    Fill.Parent = Background\n\t\n\t    local FillCorner: UICorner = Instance.new(\"UICorner\")\n\t    FillCorner.CornerRadius = UDim.new(0.1)\n\t    FillCorner.Parent = Fill\n\t\n\t    local Gradient: UIGradient = Instance.new(\"UIGradient\")\n\t    Gradient.Color = Look.Gradient\n\t    Gradient.Parent = Fill\n\t\n\t    local Inner: Frame = Instance.new(\"Frame\")\n\t    Inner.Name = \"BarHighlight\"\n\t    Inner.Size = UDim2.new(1, -2, 1, -4)\n\t    Inner.AnchorPoint = Vector2.new(0, 0.5)\n\t    Inner.Position = UDim2.fromScale(0, 0.5)\n\t    Inner.BackgroundTransparency = 1\n\t    Inner.ZIndex = 4\n\t    Inner.Parent = Fill\n\t\n\t    local InnerCorner: UICorner = Instance.new(\"UICorner\")\n\t    InnerCorner.CornerRadius = UDim.new(0.1)\n\t    InnerCorner.Parent = Inner\n\t\n\t    local Stroke: UIStroke = Instance.new(\"UIStroke\")\n\t    Stroke.Transparency = 0.55\n\t    Stroke.Thickness = 2\n\t    Stroke.Color = Color3.new(1, 1, 1)\n\t    Stroke.Parent = Inner\n\t\n\t    local Icon: ImageLabel = Instance.new(\"ImageLabel\")\n\t    Icon.Name = \"BarIcon\"\n\t    Icon.Size = UDim2.fromScale(1, 1)\n\t    Icon.SizeConstraint = Enum.SizeConstraint.RelativeYY\n\t    Icon.AnchorPoint = Vector2.new(0.5, 0.5)\n\t    Icon.Position = UDim2.fromScale(0, 0.5)\n\t    Icon.BackgroundTransparency = 1\n\t    Icon.Image = bedwars.ImageList[Look.Icon] or \"\"\n\t    Icon.ImageColor3 = Look.Tint\n\t    Icon.ZIndex = 6\n\t    Icon.Parent = Container\n\t\n\t    return Fill\n\tend\n\t\n\tlocal function BuildRig(Name: string, TeamColor: Color3)\n\t    local Model: Model = Instance.new(\"Model\")\n\t    Model.Name = `Replay_{Name}`\n\t\n\t    local Body: Part = Instance.new(\"Part\")\n\t    Body.Name = \"Body\"\n\t    Body.Size = Vector3.new(2, 5, 1)\n\t    Body.Anchored = true\n\t    Body.CanCollide = false\n\t    Body.CanQuery = false\n\t    Body.Material = Enum.Material.SmoothPlastic\n\t    Body.Color = TeamColor\n\t    Body.TopSurface = Enum.SurfaceType.Smooth\n\t    Body.BottomSurface = Enum.SurfaceType.Smooth\n\t    Body.Parent = Model\n\t\n\t    local Billboard: BillboardGui = Instance.new(\"BillboardGui\")\n\t    Billboard.Size = UDim2.fromOffset(200, 66)\n\t    Billboard.StudsOffset = Vector3.new(0, 3.9, 0)\n\t    Billboard.AlwaysOnTop = true\n\t    Billboard.Parent = Body\n\t\n\t    local Frame: Frame = Instance.new(\"Frame\")\n\t    Frame.Size = UDim2.fromScale(1, 1)\n\t    Frame.BackgroundColor3 = UIPallet.Main\n\t    Frame.BackgroundTransparency = 0.1\n\t    Frame.BorderSizePixel = 0\n\t    Frame.Parent = Billboard\n\t\n\t    local Corner: UICorner = Instance.new(\"UICorner\")\n\t    Corner.CornerRadius = UDim.new(0, 5)\n\t    Corner.Parent = Frame\n\t\n\t    local Stroke: UIStroke = Instance.new(\"UIStroke\")\n\t    Stroke.Color = Color.Light(UIPallet.Main, 0.034)\n\t    Stroke.Parent = Frame\n\t\n\t    local NameLabel: TextLabel = Instance.new(\"TextLabel\")\n\t    NameLabel.Size = UDim2.new(0.48, 0, 0, 14)\n\t    NameLabel.Position = UDim2.fromOffset(7, 4)\n\t    NameLabel.BackgroundTransparency = 1\n\t    NameLabel.TextColor3 = UIPallet.Text\n\t    NameLabel.TextSize = 12\n\t    NameLabel.FontFace = UIPallet.Font\n\t    NameLabel.TextXAlignment = Enum.TextXAlignment.Left\n\t    NameLabel.TextTruncate = Enum.TextTruncate.AtEnd\n\t    NameLabel.Text = Name\n\t    NameLabel.Parent = Frame\n\t\n\t    local HealthBack: Frame = Instance.new(\"Frame\")\n\t    HealthBack.Size = UDim2.new(1, -156, 0, 10)\n\t    HealthBack.Position = UDim2.fromOffset(104, 7)\n\t    HealthBack.BackgroundColor3 = Color.Dark(UIPallet.Main, 0.02)\n\t    HealthBack.BorderSizePixel = 0\n\t    HealthBack.Parent = Frame\n\t\n\t    local HealthCorner: UICorner = Instance.new(\"UICorner\")\n\t    HealthCorner.CornerRadius = UDim.new(1, 0)\n\t    HealthCorner.Parent = HealthBack\n\t\n\t    local HealthStroke: UIStroke = Instance.new(\"UIStroke\")\n\t    HealthStroke.Color = Color.Light(UIPallet.Main, 0.04)\n\t    HealthStroke.Parent = HealthBack\n\t\n\t    local HealthPadding: UIPadding = Instance.new(\"UIPadding\")\n\t    HealthPadding.PaddingTop = UDim.new(0, 2)\n\t    HealthPadding.PaddingBottom = UDim.new(0, 2)\n\t    HealthPadding.PaddingLeft = UDim.new(0, 2)\n\t    HealthPadding.PaddingRight = UDim.new(0, 2)\n\t    HealthPadding.Parent = HealthBack\n\t\n\t    local HealthFill: Frame = Instance.new(\"Frame\")\n\t    HealthFill.Size = UDim2.fromScale(1, 1)\n\t    HealthFill.BackgroundColor3 = Color3.fromRGB(126, 211, 90)\n\t    HealthFill.BorderSizePixel = 0\n\t    HealthFill.Parent = HealthBack\n\t\n\t    local FillCorner: UICorner = Instance.new(\"UICorner\")\n\t    FillCorner.CornerRadius = UDim.new(1, 0)\n\t    FillCorner.Parent = HealthFill\n\t\n\t    local HealthText: TextLabel = Instance.new(\"TextLabel\")\n\t    HealthText.Size = UDim2.fromOffset(30, 12)\n\t    HealthText.AnchorPoint = Vector2.new(1, 0)\n\t    HealthText.Position = UDim2.new(1, -8, 0, 6)\n\t    HealthText.BackgroundTransparency = 1\n\t    HealthText.TextColor3 = Color.Dark(UIPallet.Text, 0.1)\n\t    HealthText.TextSize = 11\n\t    HealthText.FontFace = UIPallet.Font\n\t    HealthText.TextXAlignment = Enum.TextXAlignment.Right\n\t    HealthText.Text = \"100\"\n\t    HealthText.Parent = Frame\n\t\n\t    local Icons: Frame = Instance.new(\"Frame\")\n\t    Icons.Size = UDim2.new(1, -14, 0, 24)\n\t    Icons.Position = UDim2.fromOffset(7, 21)\n\t    Icons.BackgroundTransparency = 1\n\t    Icons.Parent = Frame\n\t\n\t    local Layout: UIListLayout = Instance.new(\"UIListLayout\")\n\t    Layout.FillDirection = Enum.FillDirection.Horizontal\n\t    Layout.SortOrder = Enum.SortOrder.LayoutOrder\n\t    Layout.Padding = UDim.new(0, 3)\n\t    Layout.Parent = Icons\n\t\n\t    local HeldLabel: TextLabel = Instance.new(\"TextLabel\")\n\t    HeldLabel.Size = UDim2.new(1, -14, 0, 13)\n\t    HeldLabel.Position = UDim2.fromOffset(7, 48)\n\t    HeldLabel.BackgroundTransparency = 1\n\t    HeldLabel.TextColor3 = Color.Dark(UIPallet.Text, 0.16)\n\t    HeldLabel.TextSize = 11\n\t    HeldLabel.FontFace = UIPallet.Font\n\t    HeldLabel.TextXAlignment = Enum.TextXAlignment.Left\n\t    HeldLabel.Text = \"\"\n\t    HeldLabel.Parent = Frame\n\t\n\t    Model.Parent = workspace\n\t    Billboard.Enabled = InfoUI.Enabled\n\t\n\t    if GameHealthBar.Enabled then\n\t        HealthBack.Visible = false\n\t        HealthFill = BuildGameBar(Frame, BarLooks.Health, HealthBack.Size, HealthBack.Position)\n\t    end\n\t\n\t    return {\n\t        Model = Model,\n\t        Body = Body,\n\t        Info = Billboard,\n\t        NameLabel = NameLabel,\n\t        HealthFill = HealthFill,\n\t        HealthText = HealthText,\n\t        Icons = Icons,\n\t        HeldLabel = HeldLabel,\n\t        IconPool = {},\n\t        Playing = {},\n\t        AnimSpeeds = {},\n\t        ArmorPieces = {}\n\t    }\n\tend\n\t\n\tlocal function UpdateIcons(Rig, Loadout, Items)\n\t    if Rig.LoadoutId == Loadout then\n\t        return\n\t    end\n\t    Rig.LoadoutId = Loadout\n\t\n\t    for _, v: {Frame: Frame} in Rig.IconPool do\n\t        v.Frame:Destroy()\n\t    end\n\t    table.clear(Rig.IconPool)\n\t    if type(Loadout) ~= \"table\" then\n\t        return\n\t    end\n\t\n\t    local ArmorItems, Tools, Projectiles = {}, {}, {}\n\t    for i: number = 1, #Loadout - 1, 2 do\n\t        local ItemType: string? = Items[Loadout[i]]\n\t        local Meta = ItemType and bedwars.ItemMeta[ItemType] or nil\n\t        if Meta and Meta.image then\n\t            local Entry = {Type = ItemType, Amount = Loadout[i + 1], Image = Meta.image}\n\t            if Meta.armor then\n\t                table.insert(ArmorItems, Entry)\n\t            elseif Meta.sword or Meta.breakBlock then\n\t                table.insert(Tools, Entry)\n\t            elseif Meta.projectileSource or Entry.Amount > 1 then\n\t                table.insert(Projectiles, Entry)\n\t            end\n\t        end\n\t    end\n\t\n\t    local Order: number = 0\n\t    for _, v: {{Type: string, Amount: number, Image: string}} in {ArmorItems, Tools, Projectiles} do\n\t        for _, v: {Type: string, Amount: number, Image: string} in v do\n\t            if Order >= 7 then\n\t                break\n\t            end\n\t            Order += 1\n\t\n\t            local Holder: Frame = Instance.new(\"Frame\")\n\t            Holder.Size = UDim2.fromOffset(24, 24)\n\t            Holder.BackgroundColor3 = Color.Dark(UIPallet.Main, 0.02)\n\t            Holder.BorderSizePixel = 0\n\t            Holder.LayoutOrder = Order\n\t            Holder.Parent = Rig.Icons\n\t\n\t            local SlotCorner: UICorner = Instance.new(\"UICorner\")\n\t            SlotCorner.CornerRadius = UDim.new(0, 4)\n\t            SlotCorner.Parent = Holder\n\t\n\t            local SlotStroke: UIStroke = Instance.new(\"UIStroke\")\n\t            SlotStroke.Color = Color.Light(UIPallet.Main, 0.04)\n\t            SlotStroke.Parent = Holder\n\t\n\t            local Image: ImageLabel = Instance.new(\"ImageLabel\")\n\t            Image.Size = UDim2.fromOffset(18, 18)\n\t            Image.Position = UDim2.fromOffset(3, 3)\n\t            Image.BackgroundTransparency = 1\n\t            Image.Image = v.Image\n\t            Image.Parent = Holder\n\t\n\t            if v.Amount > 1 then\n\t                local CountLabel: TextLabel = Instance.new(\"TextLabel\")\n\t                CountLabel.Size = UDim2.fromOffset(22, 10)\n\t                CountLabel.Position = UDim2.fromOffset(0, 13)\n\t                CountLabel.BackgroundTransparency = 1\n\t                CountLabel.TextColor3 = UIPallet.Text\n\t                CountLabel.TextStrokeTransparency = 0.4\n\t                CountLabel.TextSize = 10\n\t                CountLabel.FontFace = UIPallet.Font\n\t                CountLabel.TextXAlignment = Enum.TextXAlignment.Right\n\t                CountLabel.Text = tostring(v.Amount)\n\t                CountLabel.Parent = Holder\n\t            end\n\t\n\t            table.insert(Rig.IconPool, {Frame = Holder})\n\t        end\n\t    end\n\tend\n\t\n\tlocal BlockLooks = {}\n\t\n\tlocal function GetBlockLook(BlockName: string)\n\t    local Cached = BlockLooks[BlockName]\n\t    if Cached ~= nil then\n\t        return Cached\n\t    end\n\t\n\t    local Items = ReplicatedStorage:FindFirstChild(\"Items\")\n\t    local Item = Items and Items:FindFirstChild(BlockName)\n\t    local Handle = Item and Item:FindFirstChild(\"Handle\")\n\t    if Handle and Handle:IsA(\"BasePart\") then\n\t        Cached = {Color = Handle.Color, Material = Handle.Material, Textures = {}}\n\t        for _, v: Texture in Handle:GetChildren() do\n\t            if v:IsA(\"Texture\") then\n\t                table.insert(Cached.Textures, v)\n\t            end\n\t        end\n\t    else\n\t        Cached = false\n\t    end\n\t\n\t    BlockLooks[BlockName] = Cached\n\t    return Cached\n\tend\n\t\n\tlocal Materials = {}\n\tfor _, v: EnumItem in Enum.Material:GetEnumItems() do\n\t    Materials[v.Name] = v\n\tend\n\t\n\tlocal Shapes = {CornerWedgePart = true, WedgePart = true, TrussPart = true}\n\t\n\tlocal function ApplyBlockLook(Part: BasePart, BlockName: string, Fallback: Color3, Material: string?, Variant: string?, Transparency: number?, Appearance)\n\t    if Materials[Material] then\n\t        Part.Color = Fallback\n\t        Part.Material = Materials[Material]\n\t        Part.MaterialVariant = Variant or \"\"\n\t        Part.Transparency = Transparency or 0\n\t        if Appearance then\n\t            ReplayVisuals.ApplyAppearance(Part, Appearance)\n\t        else\n\t            local Look = GetBlockLook(BlockName)\n\t            for _, v: Texture in Look and Look.Textures or {} do v:Clone().Parent = Part end\n\t        end\n\t        return\n\t    end\n\t\n\t    local Look = GetBlockLook(BlockName)\n\t    if not Look then\n\t        local Tint: Color3 = Fallback\n\t        for _, v: any in BlockTints do\n\t            if tostring(BlockName):lower():find(v[1], 1, true) then\n\t                Tint = v[2]\n\t                break\n\t            end\n\t        end\n\t\n\t        Part.Color = Tint\n\t        Part.Material = Enum.Material.SmoothPlastic\n\t        return\n\t    end\n\t\n\t    Part.Color = Look.Color\n\t    Part.Material = Look.Material\n\t    for _, v: Texture in Look.Textures do\n\t        v:Clone().Parent = Part\n\t    end\n\tend\n\t\n\tlocal function BuildMap(Data)\n\t    local Stream, Palette = Data.World, Data.Palette\n\t    if type(Stream) ~= \"table\" or type(Palette) ~= \"table\" then\n\t        return nil, 0\n\t    end\n\t\n\t    local Folder: Folder = Instance.new(\"Folder\")\n\t    Folder.Name = \"ReplayWorld\"\n\t    Folder.Parent = workspace\n\t    Playback.World = Folder\n\t\n\t    local Looks = {}\n\t    for _, v: any in Palette do\n\t        if not Looks[v[1]] then\n\t            Looks[v[1]] = v\n\t        end\n\t    end\n\t    Data.Looks = Looks\n\t\n\t    local Built: number = 0\n\t    local Low, High = Vector3.new(9e9, 9e9, 9e9), Vector3.new(-9e9, -9e9, -9e9)\n\t\n\t    local Stride: number = Data.MapStride or 7\n\t    for i: number = 1, #Stream - (Stride - 1), Stride do\n\t        local Entry = Palette[Stream[i + 6]]\n\t        if Entry then\n\t            local Part: BasePart = Instance.new(Shapes[Entry[8]] and Entry[8] or \"Part\")\n\t            Part.Name = tostring(Entry[1])\n\t            Part.Anchored = true\n\t            Part.CanCollide = false\n\t            Part.CanQuery = false\n\t            Part.Size = Vector3.new(Stream[i + 3], Stream[i + 4], Stream[i + 5])\n\t            local Rotation: number = Stride > 7 and Stream[i + 7] or 0\n\t            local Angles: CFrame = Stride >= 10 and CFrame.fromEulerAnglesYXZ(Stream[i + 7], Stream[i + 8], Stream[i + 9]) or CFrame.fromEulerAnglesYXZ(math.rad(math.floor(Rotation / 16) * 90), math.rad(math.floor(Rotation / 4) % 4 * 90), math.rad(Rotation % 4 * 90))\n\t            Part.CFrame = CFrame.new(Vector3.new(Stream[i], Stream[i + 1], Stream[i + 2]) + ReplayOffset) * Angles\n\t            Part.TopSurface = Enum.SurfaceType.Smooth\n\t            Part.BottomSurface = Enum.SurfaceType.Smooth\n\t            ApplyBlockLook(Part, Entry[1], Color3.fromRGB(Entry[2], Entry[3], Entry[4]), Entry[5], Entry[6], Entry[7], Entry[9])\n\t            Part.Parent = Folder\n\t            Built += 1\n\t            Low = Low:Min(Part.Position)\n\t            High = High:Max(Part.Position)\n\t        end\n\t\n\t        if Built % 250 == 0 then\n\t            task.wait()\n\t            if not Playback then\n\t                Folder:Destroy()\n\t                return nil, 0\n\t            end\n\t        end\n\t    end\n\t\n\t    local Props = Data.Props\n\t    local AssetBlocks = ReplicatedStorage:FindFirstChild(\"Assets\")\n\t    AssetBlocks = AssetBlocks and AssetBlocks:FindFirstChild(\"Blocks\")\n\t\n\t    if type(Props) == \"table\" then\n\t        for i: number = 1, #Props - (PropSize - 1), PropSize do\n\t            local Kind: number = Props[i]\n\t            local PropName: string = Data.Items[Props[i + 1]] or \"\"\n\t            local PropCFrame: CFrame = CFrame.new(Props[i + 2], Props[i + 3], Props[i + 4], Props[i + 5], Props[i + 6], Props[i + 7], Props[i + 8], Props[i + 9], Props[i + 10], Props[i + 11], Props[i + 12], Props[i + 13]) + ReplayOffset\n\t\n\t            local Template = Kind == 1 and AssetBlocks and AssetBlocks:FindFirstChild(PropName) or nil\n\t            if Template then\n\t                local Clone = Template:Clone()\n\t                for _, v: Instance in Clone:GetDescendants() do\n\t                    if v:IsA(\"BasePart\") then\n\t                        v.Anchored = true\n\t                        v.CanCollide = false\n\t                        v.CanQuery = false\n\t                    elseif v:IsA(\"BaseScript\") then\n\t                        v:Destroy()\n\t                    end\n\t                end\n\t                Clone.Parent = Folder\n\t                Clone:PivotTo(PropCFrame)\n\t            else\n\t                local Part: Part = Instance.new(\"Part\")\n\t                Part.Name = PropName\n\t                Part.Anchored = true\n\t                Part.CanCollide = false\n\t                Part.CanQuery = false\n\t                Part.Size = Kind == 2 and Vector3.new(1, 1, 1) or Vector3.new(3, 3, 3)\n\t                Part.CFrame = PropCFrame\n\t                ApplyBlockLook(Part, PropName, Color3.fromRGB(200, 200, 200))\n\t                Part.Parent = Folder\n\t            end\n\t            Built += 1\n\t        end\n\t    end\n\t\n\t    if Built == 0 then\n\t        return Folder, 0\n\t    end\n\t    return Folder, Built, (Low + High) * 0.5, (High - Low).Magnitude\n\tend\n\t\n\tlocal function SetHeldItem(Rig, ItemType: string)\n\t    if Rig.HeldName == ItemType then\n\t        return\n\t    end\n\t    Rig.HeldName = ItemType\n\t\n\t    if Rig.Held then\n\t        Rig.Held:Destroy()\n\t        Rig.Held = nil\n\t    end\n\t    if ItemType == \"\" then\n\t        return\n\t    end\n\t\n\t    local Items = ReplicatedStorage:FindFirstChild(\"Items\")\n\t    local Template = Items and Items:FindFirstChild(ItemType)\n\t    local Handle = Template and Template:FindFirstChild(\"Handle\")\n\t    if not Handle then\n\t        return\n\t    end\n\t\n\t    local Clone = Handle:Clone()\n\t    Clone.Name = \"HeldItem\"\n\t    Clone.CanCollide = false\n\t    Clone.CanQuery = false\n\t    Clone.Massless = true\n\t    for _, v: Instance in Clone:GetChildren() do\n\t        if v:IsA(\"TouchTransmitter\") or v:IsA(\"BaseScript\") then\n\t            v:Destroy()\n\t        end\n\t    end\n\t\n\t    local Avatar = Rig.Avatar\n\t    local Hand = Avatar and (Avatar:FindFirstChild(\"RightHand\") or Avatar:FindFirstChild(\"Right Arm\"))\n\t    if Hand then\n\t        local HandGrip = Hand:FindFirstChild(\"RightGripAttachment\")\n\t        local HandleGrip = Clone:FindFirstChild(\"RightGripAttachment\")\n\t\n\t        Clone.Anchored = false\n\t        local Weld: Weld = Instance.new(\"Weld\")\n\t        Weld.Part0 = Hand\n\t        Weld.Part1 = Clone\n\t        Weld.C0 = HandGrip and HandGrip.CFrame or CFrame.new(0, -0.15, 0)\n\t        Weld.C1 = HandleGrip and HandleGrip.CFrame or CFrame.new()\n\t        Weld.Parent = Clone\n\t        Clone.Parent = Avatar\n\t    else\n\t        Clone.Anchored = true\n\t        local Longest: number = math.max(Clone.Size.X, Clone.Size.Y, Clone.Size.Z)\n\t        Rig.HeldOffset = CFrame.new(1.4, -0.4, -(Longest * 0.25)) * CFrame.Angles(math.rad(-100), 0, math.rad(10))\n\t        Clone.Parent = Rig.Model\n\t    end\n\t\n\t    Rig.Held = Clone\n\tend\n\t\n\tlocal function GetRigTemplate(Name: string)\n\t    local Owner: Player? = Players:FindFirstChild(Name)\n\t    local Source = Owner and Owner.Character\n\t    local Exact: boolean = (Source and Source:FindFirstChild(\"UpperTorso\") and Source:FindFirstChild(\"HumanoidRootPart\") and true or false)\n\t    if not Exact then\n\t        Source = (LocalPlayer.Character and LocalPlayer.Character:FindFirstChild(\"UpperTorso\") and LocalPlayer.Character:FindFirstChild(\"HumanoidRootPart\") and true or false) and LocalPlayer.Character or nil\n\t        if not Source then\n\t            for _, v: Player in Players:GetPlayers() do\n\t                if (v.Character and v.Character:FindFirstChild(\"UpperTorso\") and v.Character:FindFirstChild(\"HumanoidRootPart\") and true or false) then\n\t                    Source = v.Character\n\t                    break\n\t                end\n\t            end\n\t        end\n\t    end\n\t    if not Source then\n\t        return nil, false\n\t    end\n\t\n\t    local Archivable: boolean = Source.Archivable\n\t    Source.Archivable = true\n\t    local Clone = Source:Clone()\n\t    Source.Archivable = Archivable\n\t    local Template = Clone\n\t    if not Template then\n\t        return nil, false\n\t    end\n\t\n\t    for _, v: Instance in Template:GetDescendants() do\n\t        if v:IsA(\"Tool\") or v:IsA(\"ObjectValue\") or v:IsA(\"BillboardGui\") or v:IsA(\"ParticleEmitter\") or v:IsA(\"Highlight\") or v:IsA(\"ForceField\") or (v:IsA(\"Accessory\") and bedwars.ItemMeta[v.Name]) or (not Exact and (v:IsA(\"Accessory\") or v.Name == \"3DClothing\")) then\n\t            v:Destroy()\n\t        end\n\t    end\n\t\n\t    if not Exact then\n\t        for _, v: BasePart in Template:GetDescendants() do\n\t            if v:IsA(\"BasePart\") and v.Name ~= \"HumanoidRootPart\" then\n\t                v.Transparency = 0\n\t                v.LocalTransparencyModifier = 0\n\t            end\n\t        end\n\t    end\n\t\n\t    return Template, Exact\n\tend\n\t\n\t\n\tlocal function LoadNpcModel(Rig, ModelName: string)\n\t    local Assets = ReplicatedStorage:FindFirstChild(\"Assets\")\n\t    local Misc = Assets and Assets:FindFirstChild(\"Misc\")\n\t    local Template = Misc and Misc:FindFirstChild(ModelName)\n\t    if not Rig or not Rig.Model or not Template then\n\t        return\n\t    end\n\t\n\t    local Model = Template:Clone()\n\t    local Primary = Model:FindFirstChild(\"RootPart\") or Model.PrimaryPart or Model:FindFirstChildWhichIsA(\"BasePart\")\n\t    if not Primary then\n\t        Model:Destroy()\n\t        return\n\t    end\n\t\n\t    for _, v: BaseScript in Model:GetDescendants() do\n\t        if v:IsA(\"BaseScript\") then\n\t            v:Destroy()\n\t        end\n\t    end\n\t\n\t    local Jointed = {}\n\t    for _, v: Motor6D in Model:GetDescendants() do\n\t        if v:IsA(\"Motor6D\") and v.Part1 then\n\t            Jointed[v.Part1] = true\n\t        end\n\t    end\n\t\n\t    for _, v: BasePart in Model:GetDescendants() do\n\t        if v:IsA(\"BasePart\") then\n\t            v.CanCollide = false\n\t            v.CanQuery = false\n\t            v.Massless = true\n\t            v.Anchored = v == Primary\n\t            if v ~= Primary and not Jointed[v] then\n\t                local Weld: WeldConstraint = Instance.new(\"WeldConstraint\")\n\t                Weld.Part0 = Primary\n\t                Weld.Part1 = v\n\t                Weld.Parent = Primary\n\t            end\n\t        end\n\t    end\n\t\n\t    local Controller = Model:FindFirstChildWhichIsA(\"Humanoid\") or Model:FindFirstChildWhichIsA(\"AnimationController\")\n\t    if not Controller then\n\t        Controller = Instance.new(\"AnimationController\")\n\t        Controller.Parent = Model\n\t    end\n\t\n\t    local Animator = Controller:FindFirstChildWhichIsA(\"Animator\")\n\t    if not Animator then\n\t        Animator = Instance.new(\"Animator\")\n\t        Animator.Parent = Controller\n\t    end\n\t    Rig.Animator = Animator\n\t    Rig.Anims = Rig.Anims or {}\n\t\n\t    Model.PrimaryPart = Primary\n\t    Model.Name = \"Avatar\"\n\t    Model.Parent = Rig.Model\n\t    Rig.Avatar = Model\n\tend\n\t\n\tlocal function LoadAvatar(Rig, Name: string, UserId: number?, Colors, IsNpc: boolean?)\n\t    if not Rig then\n\t        return\n\t    end\n\t\n\t    task.spawn(function()\n\t        local Model, Exact = nil, false\n\t        if Colors then\n\t            Model, Exact = GetRigTemplate(Name)\n\t        end\n\t\n\t        if Model then\n\t            if not Exact then\n\t                local BodyColors: BodyColors? = Model:FindFirstChildWhichIsA(\"BodyColors\")\n\t                for PartName: string, v: number in BodySlots do\n\t                    local Part: BasePart? = Model:FindFirstChild(PartName)\n\t                    local Entry = Colors[v]\n\t                    if Part and Entry then\n\t                        Part.Color = Color3.fromRGB(Entry[1], Entry[2], Entry[3])\n\t                        if BodyColors then\n\t                            BodyColors[BodyFields[v]] = Part.Color\n\t                        end\n\t                    end\n\t                end\n\t            end\n\t        else\n\t            if IsNpc then\n\t                return\n\t            end\n\t\n\t            if not UserId or UserId <= 0 then\n\t                local Existing: Player? = Players:FindFirstChild(Name)\n\t                if Existing then\n\t                    UserId = Existing.UserId\n\t                else\n\t                    local Success, Resolved = pcall(function()\n\t                        return Players:GetUserIdFromNameAsync(Name)\n\t                    end)\n\t                    UserId = Success and Resolved or nil\n\t                end\n\t            end\n\t            if not UserId or not Playback then\n\t                return\n\t            end\n\t\n\t            local Success, Created = pcall(function()\n\t                return Players:CreateHumanoidModelFromUserId(UserId)\n\t            end)\n\t            if not Success or not Created then\n\t                return\n\t            end\n\t            Model = Created\n\t        end\n\t\n\t        if not Playback or not Rig.Model then\n\t            Model:Destroy()\n\t            return\n\t        end\n\t\n\t        local Root: BasePart? = Model:FindFirstChild(\"HumanoidRootPart\")\n\t        for _, v: Instance in Model:GetDescendants() do\n\t            if v:IsA(\"BasePart\") then\n\t                v.CanCollide = false\n\t                v.CanQuery = false\n\t                v.Massless = true\n\t            elseif v:IsA(\"BaseScript\") then\n\t                v:Destroy()\n\t            end\n\t        end\n\t\n\t        Model.PrimaryPart = Root or Model.PrimaryPart\n\t        Model.Name = \"Avatar\"\n\t        Model.Parent = Rig.Model\n\t\n\t        for _, v: AnimationConstraint in Model:GetDescendants() do\n\t            if v:IsA(\"AnimationConstraint\") and v.Attachment0 and v.Attachment1 then\n\t                local Motor: Motor6D = Instance.new(\"Motor6D\")\n\t                Motor.Name = v.Name\n\t                Motor.Part0 = v.Attachment0.Parent\n\t                Motor.Part1 = v.Attachment1.Parent\n\t                Motor.C0 = v.Attachment0.CFrame\n\t                Motor.C1 = v.Attachment1.CFrame\n\t                Motor.Parent = v.Attachment1.Parent\n\t                v:Destroy()\n\t            end\n\t        end\n\t\n\t        for _, v: RigidConstraint in Model:GetDescendants() do\n\t            if v:IsA(\"RigidConstraint\") and v:FindFirstAncestorWhichIsA(\"Accessory\") and v.Attachment0 and v.Attachment1 then\n\t                local Weld: Weld = Instance.new(\"Weld\")\n\t                Weld.Name = \"AccessoryWeld\"\n\t                Weld.Part0 = v.Attachment1.Parent\n\t                Weld.Part1 = v.Attachment0.Parent\n\t                Weld.C0 = v.Attachment1.CFrame\n\t                Weld.C1 = v.Attachment0.CFrame\n\t                Weld.Parent = v.Attachment0.Parent\n\t            end\n\t        end\n\t\n\t        for _, v: Instance in Model:GetDescendants() do\n\t            if v:IsA(\"BallSocketConstraint\") or v:IsA(\"RigidConstraint\") then\n\t                v:Destroy()\n\t            end\n\t        end\n\t\n\t        local Humanoid: Humanoid? = Model:FindFirstChildWhichIsA(\"Humanoid\")\n\t        if Humanoid then\n\t            Humanoid.DisplayName = \"\"\n\t            Humanoid.HealthDisplayType = Enum.HumanoidHealthDisplayType.AlwaysOff\n\t\n\t            for _, v: EnumItem in {Enum.HumanoidStateType.FallingDown, Enum.HumanoidStateType.Ragdoll, Enum.HumanoidStateType.Physics} do\n\t                pcall(Humanoid.SetStateEnabled, Humanoid, v, false)\n\t            end\n\t\n\t            local Animator = Humanoid:FindFirstChildWhichIsA(\"Animator\")\n\t            if not Animator then\n\t                Animator = Instance.new(\"Animator\")\n\t                Animator.Parent = Humanoid\n\t            end\n\t            Rig.Animator = Animator\n\t\n\t            Rig.Anims = {}\n\t            for State: string, v: string in DefaultAnimations do\n\t                local Animation: Animation = Instance.new(\"Animation\")\n\t                Animation.AnimationId = v\n\t                local Loaded, Track = pcall(Animator.LoadAnimation, Animator, Animation)\n\t                if Loaded and Track then\n\t                    Track.Looped = true\n\t                    Track.Priority = Enum.AnimationPriority.Core\n\t                    Rig.Anims[State] = Track\n\t                end\n\t            end\n\t        end\n\t\n\t        if Root then\n\t            Root.Anchored = true\n\t        end\n\t\n\t        local Neck = Model:FindFirstChild(\"Neck\", true)\n\t        if Neck and Neck:IsA(\"Motor6D\") then\n\t            Rig.Neck = Neck\n\t            Rig.NeckBase = Neck.C0\n\t        end\n\t\n\t        Rig.Avatar = Model\n\t        Rig.Body.Transparency = 1\n\t\n\t        if Rig.Held then\n\t            Rig.Held:Destroy()\n\t            Rig.Held = nil\n\t        end\n\t        Rig.HeldName = nil\n\t        Rig.ArmorId = nil\n\t    end)\n\tend\n\t\n\tlocal function FormatTime(Seconds: number)\n\t    Seconds = math.max(math.floor(Seconds), 0)\n\t    return string.format(\"%d:%02d\", Seconds // 60, Seconds % 60)\n\tend\n\t\n\tlocal function UpdateTimeline()\n\t    if not Timeline or not Playback then\n\t        return\n\t    end\n\t\n\t    local Duration: number = math.max(Playback.Duration, 0.01)\n\t    Timeline.Fill.Size = UDim2.fromScale(math.clamp(Playback.Clock / Duration, 0, 1), 1)\n\t    Timeline.Knob.Position = UDim2.new(math.clamp(Playback.Clock / Duration, 0, 1), 0, 0.5, 0)\n\t    Timeline.Time.Text = `{FormatTime(Playback.Clock)} / {FormatTime(Duration)}`\n\t    Timeline.PlayLabel.Text = Playback.Paused and \"▶\" or \"❚❚\"\n\tend\n\t\n\tlocal function MakeButton(Parent: Instance, Text: string, Width: number, Order: number)\n\t    local Button: TextButton = Instance.new(\"TextButton\")\n\t    Button.Size = UDim2.fromOffset(Width, 28)\n\t    Button.LayoutOrder = Order\n\t    Button.BackgroundColor3 = Color.Dark(UIPallet.Main, 0.02)\n\t    Button.BorderSizePixel = 0\n\t    Button.AutoButtonColor = false\n\t    Button.Text = Text\n\t    Button.TextColor3 = Color.Dark(UIPallet.Text, 0.1)\n\t    Button.TextSize = 12\n\t    Button.FontFace = UIPallet.Font\n\t    Button.Parent = Parent\n\t\n\t    local Corner: UICorner = Instance.new(\"UICorner\")\n\t    Corner.CornerRadius = UDim.new(0, 4)\n\t    Corner.Parent = Button\n\t\n\t    local Stroke: UIStroke = Instance.new(\"UIStroke\")\n\t    Stroke.Color = Color.Light(UIPallet.Main, 0.04)\n\t    Stroke.Parent = Button\n\t\n\t    Button.MouseEnter:Connect(function()\n\t        Tween:Tween(Button, UIPallet.Tween, {BackgroundColor3 = Color.Light(UIPallet.Main, 0.034)})\n\t    end)\n\t    Button.MouseLeave:Connect(function()\n\t        Tween:Tween(Button, UIPallet.Tween, {BackgroundColor3 = Color.Dark(UIPallet.Main, 0.02)})\n\t    end)\n\t    return Button\n\tend\n\t\n\tlocal function DestroyTimeline()\n\t    if not Timeline then\n\t        return\n\t    end\n\t    Timeline.Gui:Destroy()\n\t    Timeline = nil\n\tend\n\t\n\tlocal HotbarTemplate\n\tlocal HiddenGuis = setmetatable({}, {__mode = \"k\"})\n\tlocal GuiWatcher\n\t\n\tlocal function HideGameGuis(Hide: boolean)\n\t    if not Hide then\n\t        if GuiWatcher then\n\t            GuiWatcher:Disconnect()\n\t            GuiWatcher = nil\n\t        end\n\t        for Gui: ScreenGui, v: boolean in HiddenGuis do\n\t            if Gui.Parent then\n\t                Gui.Enabled = v\n\t            end\n\t        end\n\t        table.clear(HiddenGuis)\n\t        return\n\t    end\n\t\n\t    local function Conceal(Gui: Instance)\n\t        if not Gui:IsA(\"ScreenGui\") or Gui == vape.gui or Gui.Name == \"ReplayTimeline\" or Gui.Name == \"ReplayHotbar\" or HiddenGuis[Gui] ~= nil then\n\t            return\n\t        end\n\t\n\t        HiddenGuis[Gui] = Gui.Enabled\n\t        Gui.Enabled = false\n\t    end\n\t\n\t    for _, v: Instance in LocalPlayer.PlayerGui:GetChildren() do\n\t        Conceal(v)\n\t    end\n\t    GuiWatcher = LocalPlayer.PlayerGui.ChildAdded:Connect(Conceal)\n\tend\n\t\n\tlocal function BuildTimeline()\n\t    DestroyTimeline()\n\t\n\t    local Gui: ScreenGui = Instance.new(\"ScreenGui\")\n\t    Gui.Name = \"ReplayTimeline\"\n\t    Gui.ResetOnSpawn = false\n\t    Gui.IgnoreGuiInset = true\n\t    Gui.ZIndexBehavior = Enum.ZIndexBehavior.Sibling\n\t    Gui.DisplayOrder = 50\n\t    Gui.Parent = LocalPlayer.PlayerGui\n\t\n\t    local Panel: Frame = Instance.new(\"Frame\")\n\t    Panel.Size = UDim2.fromOffset(540, 94)\n\t    Panel.Position = UDim2.new(0.5, -270, 1, -240)\n\t    Panel.BackgroundColor3 = UIPallet.Main\n\t    Panel.BorderSizePixel = 0\n\t    Panel.Parent = Gui\n\t\n\t    local PanelCorner: UICorner = Instance.new(\"UICorner\")\n\t    PanelCorner.CornerRadius = UDim.new(0, 5)\n\t    PanelCorner.Parent = Panel\n\t\n\t    local PanelStroke: UIStroke = Instance.new(\"UIStroke\")\n\t    PanelStroke.Color = Color.Light(UIPallet.Main, 0.034)\n\t    PanelStroke.Parent = Panel\n\t\n\t    local Title: TextLabel = Instance.new(\"TextLabel\")\n\t    Title.Size = UDim2.new(1, -10, 0, 20)\n\t    Title.Position = UDim2.fromOffset(10, 4)\n\t    Title.BackgroundTransparency = 1\n\t    Title.TextColor3 = UIPallet.Text\n\t    Title.TextSize = 13\n\t    Title.FontFace = UIPallet.Font\n\t    Title.TextXAlignment = Enum.TextXAlignment.Left\n\t    Title.Text = \"Replay\"\n\t    Title.Parent = Panel\n\t\n\t    local Divider: Frame = Instance.new(\"Frame\")\n\t    Divider.Size = UDim2.new(1, 0, 0, 1)\n\t    Divider.Position = UDim2.fromOffset(0, 26)\n\t    Divider.BackgroundColor3 = Color.Light(UIPallet.Main, 0.04)\n\t    Divider.BorderSizePixel = 0\n\t    Divider.Parent = Panel\n\t\n\t    local Bar: TextButton = Instance.new(\"TextButton\")\n\t    Bar.Size = UDim2.new(1, -24, 0, 8)\n\t    Bar.Position = UDim2.fromOffset(12, 36)\n\t    Bar.BackgroundColor3 = Color.Dark(UIPallet.Main, 0.02)\n\t    Bar.BorderSizePixel = 0\n\t    Bar.Text = \"\"\n\t    Bar.AutoButtonColor = false\n\t    Bar.Parent = Panel\n\t\n\t    local BarCorner: UICorner = Instance.new(\"UICorner\")\n\t    BarCorner.CornerRadius = UDim.new(1, 0)\n\t    BarCorner.Parent = Bar\n\t\n\t    local BarStroke: UIStroke = Instance.new(\"UIStroke\")\n\t    BarStroke.Color = Color.Light(UIPallet.Main, 0.04)\n\t    BarStroke.Parent = Bar\n\t\n\t    local Fill: Frame = Instance.new(\"Frame\")\n\t    Fill.Size = UDim2.fromScale(0, 1)\n\t    Fill.BackgroundColor3 = Color3.fromRGB(126, 211, 90)\n\t    Fill.BorderSizePixel = 0\n\t    Fill.Parent = Bar\n\t\n\t    local FillCorner: UICorner = Instance.new(\"UICorner\")\n\t    FillCorner.CornerRadius = UDim.new(1, 0)\n\t    FillCorner.Parent = Fill\n\t\n\t    local Knob: Frame = Instance.new(\"Frame\")\n\t    Knob.Size = UDim2.fromOffset(12, 12)\n\t    Knob.AnchorPoint = Vector2.new(0.5, 0.5)\n\t    Knob.Position = UDim2.fromScale(0, 0.5)\n\t    Knob.BackgroundColor3 = UIPallet.Text\n\t    Knob.BorderSizePixel = 0\n\t    Knob.Parent = Bar\n\t\n\t    local KnobCorner: UICorner = Instance.new(\"UICorner\")\n\t    KnobCorner.CornerRadius = UDim.new(1, 0)\n\t    KnobCorner.Parent = Knob\n\t\n\t    local Row: Frame = Instance.new(\"Frame\")\n\t    Row.Size = UDim2.new(1, -24, 0, 30)\n\t    Row.Position = UDim2.fromOffset(12, 54)\n\t    Row.BackgroundTransparency = 1\n\t    Row.Parent = Panel\n\t\n\t    local RowLayout: UIListLayout = Instance.new(\"UIListLayout\")\n\t    RowLayout.FillDirection = Enum.FillDirection.Horizontal\n\t    RowLayout.VerticalAlignment = Enum.VerticalAlignment.Center\n\t    RowLayout.SortOrder = Enum.SortOrder.LayoutOrder\n\t    RowLayout.Padding = UDim.new(0, 6)\n\t    RowLayout.Parent = Row\n\t\n\t    local BackButton: TextButton = MakeButton(Row, \"\\u{00AB} 10s\", 62, 1)\n\t    local PlayButton: TextButton = MakeButton(Row, \"❚❚\", 44, 2)\n\t    local ForwardButton: TextButton = MakeButton(Row, \"10s \\u{00BB}\", 62, 3)\n\t\n\t    local PreviousButton: TextButton = MakeButton(Row, \"\\u{25C0}\", 28, 5)\n\t    local SpectateLabel: TextLabel = Instance.new(\"TextLabel\")\n\t    SpectateLabel.Size = UDim2.fromOffset(130, 28)\n\t    SpectateLabel.LayoutOrder = 6\n\t    SpectateLabel.BackgroundTransparency = 1\n\t    SpectateLabel.TextColor3 = UIPallet.Text\n\t    SpectateLabel.TextSize = 12\n\t    SpectateLabel.FontFace = UIPallet.Font\n\t    SpectateLabel.TextTruncate = Enum.TextTruncate.AtEnd\n\t    SpectateLabel.Text = \"Free camera\"\n\t    SpectateLabel.Parent = Row\n\t    local NextButton: TextButton = MakeButton(Row, \"\\u{25B6}\", 28, 7)\n\t\n\t    local TimeLabel: TextLabel = Instance.new(\"TextLabel\")\n\t    TimeLabel.Size = UDim2.fromOffset(110, 28)\n\t    TimeLabel.LayoutOrder = 4\n\t    TimeLabel.BackgroundTransparency = 1\n\t    TimeLabel.TextColor3 = Color.Dark(UIPallet.Text, 0.1)\n\t    TimeLabel.TextSize = 12\n\t    TimeLabel.FontFace = UIPallet.Font\n\t    TimeLabel.TextXAlignment = Enum.TextXAlignment.Left\n\t    TimeLabel.Text = \"0:00 / 0:00\"\n\t    TimeLabel.Parent = Row\n\t\n\t    local Feed: Frame = Instance.new(\"Frame\")\n\t    Feed.Name = \"KillFeed\"\n\t    Feed.Size = UDim2.fromOffset(280, 150)\n\t    Feed.Position = UDim2.fromOffset(16, 110)\n\t    Feed.BackgroundTransparency = 1\n\t    Feed.Parent = Gui\n\t\n\t    local FeedLayout: UIListLayout = Instance.new(\"UIListLayout\")\n\t    FeedLayout.SortOrder = Enum.SortOrder.LayoutOrder\n\t    FeedLayout.HorizontalAlignment = Enum.HorizontalAlignment.Left\n\t    FeedLayout.Padding = UDim.new(0, 2)\n\t    FeedLayout.Parent = Feed\n\t\n\t    if Playback.Data.FeedLayout then\n\t        local Native = ReplayVisuals.Restore(Playback.Data.FeedLayout, Gui)\n\t        if Native then\n\t            Feed:Destroy()\n\t            Feed = Native\n\t            for _, v: Instance in Feed:GetChildren() do if v:IsA(\"GuiObject\") then v:Destroy() end end\n\t        end\n\t    end\n\t    Timeline = {Gui = Gui, Fill = Fill, Knob = Knob, Time = TimeLabel, PlayLabel = PlayButton, Spectate = SpectateLabel, Feed = Feed}\n\t\n\t    local function CycleSpectate(Step: number)\n\t        if not Playback then\n\t            return\n\t        end\n\t\n\t        local Names: {string} = {}\n\t        for Name: string in Playback.Rigs do\n\t            table.insert(Names, Name)\n\t        end\n\t        table.sort(Names)\n\t        table.insert(Names, 1, \"\")\n\t\n\t        local Index: number = table.find(Names, Playback.Spectate or \"\") or 1\n\t        Index += Step\n\t        if Index > #Names then\n\t            Index = 1\n\t        elseif Index < 1 then\n\t            Index = #Names\n\t        end\n\t\n\t        Playback.Spectate = Names[Index] ~= \"\" and Names[Index] or nil\n\t        SpectateLabel.Text = Playback.Spectate or \"Free camera\"\n\t    end\n\t\n\t    PreviousButton.MouseButton1Click:Connect(function()\n\t        CycleSpectate(-1)\n\t    end)\n\t    NextButton.MouseButton1Click:Connect(function()\n\t        CycleSpectate(1)\n\t    end)\n\t\n\t    Bar.MouseButton1Down:Connect(function()\n\t        local MouseLocation: Vector2 = UserInputService:GetMouseLocation()\n\t        if Playback then\n\t            Playback.Clock = math.clamp((MouseLocation.X - Bar.AbsolutePosition.X) / math.max(Bar.AbsoluteSize.X, 1), 0, 1) * Playback.Duration\n\t            UpdateTimeline()\n\t        end\n\t    end)\n\t    BackButton.MouseButton1Click:Connect(function()\n\t        if Playback then\n\t            Playback.Clock = math.max(Playback.Clock - 10, 0)\n\t            UpdateTimeline()\n\t        end\n\t    end)\n\t    ForwardButton.MouseButton1Click:Connect(function()\n\t        if Playback then\n\t            Playback.Clock = math.min(Playback.Clock + 10, Playback.Duration)\n\t            UpdateTimeline()\n\t        end\n\t    end)\n\t    PlayButton.MouseButton1Click:Connect(function()\n\t        if Playback then\n\t            Playback.Paused = not Playback.Paused\n\t            UpdateTimeline()\n\t        end\n\t    end)\n\tend\n\t\n\tlocal function StopFreecam()\n\t    if not FreeCamState then\n\t        return\n\t    end\n\t\n\t    for _, v: RBXScriptConnection in FreeCamState.Connections do\n\t        v:Disconnect()\n\t    end\n\t    if FreeCamState.Controls then\n\t        FreeCamState.Controls:Enable()\n\t    end\n\t    Camera.CameraType = FreeCamState.OldType\n\t    Camera.CameraSubject = FreeCamState.OldSubject\n\t    UserInputService.MouseBehavior = FreeCamState.OldBehavior\n\t    FreeCamState = nil\n\tend\n\t\n\tlocal function StartFreecam()\n\t    StopFreecam()\n\t\n\t    local Pitch, Yaw = Camera.CFrame:ToEulerAnglesYXZ()\n\t    FreeCamState = {\n\t        Position = Camera.CFrame.Position,\n\t        Pitch = Pitch,\n\t        Yaw = Yaw,\n\t        Keys = {},\n\t        Connections = {},\n\t        Controls = Playback and Playback.Controls,\n\t        OldType = Camera.CameraType,\n\t        OldSubject = Camera.CameraSubject,\n\t        OldBehavior = UserInputService.MouseBehavior\n\t    }\n\t\n\t    if FreeCamState.Controls then\n\t        FreeCamState.Controls:Disable()\n\t    end\n\t    Camera.CameraType = Enum.CameraType.Scriptable\n\t\n\t    table.insert(FreeCamState.Connections, UserInputService.InputBegan:Connect(function(Input: InputObject, Typing: boolean)\n\t        if Typing then\n\t            return\n\t        end\n\t        FreeCamState.Keys[Input.KeyCode] = true\n\t        if Input.UserInputType == Enum.UserInputType.MouseButton2 then\n\t            FreeCamState.Looking = true\n\t            UserInputService.MouseBehavior = Enum.MouseBehavior.LockCurrentPosition\n\t        end\n\t    end))\n\t    table.insert(FreeCamState.Connections, UserInputService.InputEnded:Connect(function(Input: InputObject)\n\t        FreeCamState.Keys[Input.KeyCode] = nil\n\t        if Input.UserInputType == Enum.UserInputType.MouseButton2 then\n\t            FreeCamState.Looking = false\n\t            UserInputService.MouseBehavior = Enum.MouseBehavior.Default\n\t        end\n\t    end))\n\t    table.insert(FreeCamState.Connections, UserInputService.InputChanged:Connect(function(Input: InputObject)\n\t        if FreeCamState.Looking and Input.UserInputType == Enum.UserInputType.MouseMovement then\n\t            FreeCamState.Yaw -= Input.Delta.X * 0.005\n\t            FreeCamState.Pitch = math.clamp(FreeCamState.Pitch - Input.Delta.Y * 0.005, -1.4, 1.4)\n\t        end\n\t    end))\n\t\n\t    table.insert(FreeCamState.Connections, RunService.RenderStepped:Connect(function(Delta: number)\n\t        local Spectated = Playback and Playback.Spectate and Playback.Rigs[Playback.Spectate]\n\t        if Spectated and Spectated.Body.Parent then\n\t            local Target: Vector3 = Spectated.Body.Position + Vector3.new(0, 1.5, 0)\n\t            local Rotation: CFrame = CFrame.Angles(0, FreeCamState.Yaw, 0) * CFrame.Angles(FreeCamState.Pitch, 0, 0)\n\t            Camera.CFrame = CFrame.new(Target) * Rotation * CFrame.new(0, 0, 12)\n\t            FreeCamState.Position = Camera.CFrame.Position\n\t            return\n\t        end\n\t\n\t        local Rotation: CFrame = CFrame.Angles(0, FreeCamState.Yaw, 0) * CFrame.Angles(FreeCamState.Pitch, 0, 0)\n\t        local Move: Vector3 = Vector3.zero\n\t        local Keys = FreeCamState.Keys\n\t        if Keys[Enum.KeyCode.W] then\n\t            Move += Vector3.new(0, 0, -1)\n\t        end\n\t        if Keys[Enum.KeyCode.S] then\n\t            Move += Vector3.new(0, 0, 1)\n\t        end\n\t        if Keys[Enum.KeyCode.A] then\n\t            Move += Vector3.new(-1, 0, 0)\n\t        end\n\t        if Keys[Enum.KeyCode.D] then\n\t            Move += Vector3.new(1, 0, 0)\n\t        end\n\t        if Keys[Enum.KeyCode.E] then\n\t            Move += Vector3.new(0, 1, 0)\n\t        end\n\t        if Keys[Enum.KeyCode.Q] then\n\t            Move += Vector3.new(0, -1, 0)\n\t        end\n\t\n\t        if Move.Magnitude > 0 then\n\t            local Boost: number = Keys[Enum.KeyCode.LeftShift] and 3 or 1\n\t            FreeCamState.Position += (Rotation * CFrame.new(Move.Unit * CameraSpeed.Value * Boost * Delta)).Position - Rotation.Position\n\t        end\n\t\n\t        Camera.CFrame = CFrame.new(FreeCamState.Position) * Rotation\n\t    end))\n\tend\n\t\n\tlocal function BuildBeds(Data, Folder)\n\t    local Built = {}\n\t    local AssetBlocks = ReplicatedStorage:FindFirstChild(\"Assets\")\n\t    AssetBlocks = AssetBlocks and AssetBlocks:FindFirstChild(\"Blocks\")\n\t    if type(Data.Beds) ~= \"table\" then\n\t        return Built\n\t    end\n\t\n\t    for BedId: string, Bed: any in Data.Beds do\n\t        local Components = Bed.CFrame or {}\n\t        if #Components >= 12 then\n\t            local BedCFrame: CFrame = CFrame.new(Components[1], Components[2], Components[3], Components[4], Components[5], Components[6], Components[7], Components[8], Components[9], Components[10], Components[11], Components[12]) + ReplayOffset\n\t            local Template = AssetBlocks and AssetBlocks:FindFirstChild(Bed.Name or \"bed\")\n\t            local Colors = Bed.Colors or {}\n\t            local Model\n\t\n\t            if Template then\n\t                Model = Template:Clone()\n\t                for _, v: Instance in Model:GetDescendants() do\n\t                    if v:IsA(\"BasePart\") then\n\t                        v.Anchored = true\n\t                        v.CanCollide = false\n\t                        v.CanQuery = false\n\t                        local Tint = Colors[v.Name]\n\t                        if Tint then\n\t                            v.Color = Color3.fromRGB(Tint[1], Tint[2], Tint[3])\n\t                        end\n\t                    elseif v:IsA(\"BaseScript\") then\n\t                        v:Destroy()\n\t                    end\n\t                end\n\t                Model.Parent = Folder\n\t                Model:PivotTo(BedCFrame)\n\t            end\n\t\n\t            local Anchor: Part = Instance.new(\"Part\")\n\t            Anchor.Name = \"BedAnchor\"\n\t            Anchor.Size = Vector3.new(1, 1, 1)\n\t            Anchor.Transparency = 1\n\t            Anchor.Anchored = true\n\t            Anchor.CanCollide = false\n\t            Anchor.CanQuery = false\n\t            Anchor.CFrame = BedCFrame\n\t            Anchor.Parent = Folder\n\t\n\t            local Meta = bedwars.ItemMeta[Bed.Name or \"bed\"]\n\t            local Title: string = Meta and Meta.displayName or \"Bed\"\n\t            if Bed.Team and Bed.Team ~= \"\" then\n\t                Title = `{Bed.Team} Bed`\n\t            end\n\t\n\t            local Stream = Bed.Data or {}\n\t            local Fill, Shield\n\t            if GameHealthBar.Enabled then\n\t                local Plated: boolean = (Stream[4] or 0) > 0\n\t                local Billboard: BillboardGui = Instance.new(\"BillboardGui\")\n\t                Billboard.Name = \"BedHealth\"\n\t                Billboard.Size = UDim2.fromScale(8, 2)\n\t                Billboard.MaxDistance = 150\n\t                Billboard.LightInfluence = 0\n\t                Billboard.Adornee = Anchor\n\t                Billboard.Parent = Anchor\n\t\n\t                local Root: Frame = Instance.new(\"Frame\")\n\t                Root.Size = UDim2.fromScale(1, 1)\n\t                Root.BackgroundTransparency = 1\n\t                Root.Parent = Billboard\n\t\n\t                Fill = BuildGameBar(Root, BarLooks.Health, UDim2.fromScale(1, 0.4), UDim2.fromScale(0, 0.4))\n\t                Shield = Plated and BuildGameBar(Root, BarLooks.Plating, UDim2.fromScale(1, 0.4), UDim2.fromScale(0, 0)) or nil\n\t            end\n\t\n\t            local CustomFill = Fill\n\t            if not CustomFill then\n\t                local Billboard: BillboardGui = Instance.new(\"BillboardGui\")\n\t                Billboard.Size = UDim2.fromOffset(249, 102)\n\t                Billboard.StudsOffset = Vector3.new(0, 2.5, 0)\n\t                Billboard.MaxDistance = 120\n\t                Billboard.AlwaysOnTop = true\n\t                Billboard.Parent = Anchor\n\t                local Back: Frame = Instance.new(\"Frame\")\n\t                Back.Size = UDim2.fromOffset(160, 50)\n\t                Back.Position = UDim2.fromOffset(44, 32)\n\t                Back.BackgroundColor3 = Color3.new()\n\t                Back.BackgroundTransparency = 0.5\n\t                Back.BorderSizePixel = 0\n\t                Back.Parent = Billboard\n\t                local BackCorner: UICorner = Instance.new(\"UICorner\")\n\t                BackCorner.CornerRadius = UDim.new(0, 5)\n\t                BackCorner.Parent = Back\n\t                local Blur: ImageLabel = Instance.new(\"ImageLabel\")\n\t                Blur.Size = UDim2.new(1, 89, 1, 52)\n\t                Blur.Position = UDim2.fromOffset(-48, -31)\n\t                Blur.BackgroundTransparency = 1\n\t                Blur.Image = GetVapeAsset(`{vape.Directory}/assets/new/blur.png`)\n\t                Blur.ScaleType = Enum.ScaleType.Slice\n\t                Blur.SliceCenter = Rect.new(52, 31, 261, 502)\n\t                Blur.Parent = Back\n\t                local Shadow: TextLabel = Instance.new(\"TextLabel\")\n\t                Shadow.Size = UDim2.fromOffset(145, 14)\n\t                Shadow.Position = UDim2.fromOffset(13, 12)\n\t                Shadow.BackgroundTransparency = 1\n\t                Shadow.Text = Title\n\t                Shadow.TextXAlignment = Enum.TextXAlignment.Left\n\t                Shadow.TextYAlignment = Enum.TextYAlignment.Top\n\t                Shadow.TextColor3 = Color3.new()\n\t                Shadow.TextScaled = true\n\t                Shadow.Font = Enum.Font.Arial\n\t                Shadow.ZIndex = 2\n\t                Shadow.Parent = Back\n\t                local TitleLabel: TextLabel = Shadow:Clone()\n\t                TitleLabel.Position = UDim2.fromOffset(12, 11)\n\t                TitleLabel.TextColor3 = Color.Dark(UIPallet.Text, 0.16)\n\t                TitleLabel.ZIndex = 3\n\t                TitleLabel.Parent = Back\n\t                local Track: Frame = Instance.new(\"Frame\")\n\t                Track.Size = UDim2.fromOffset(138, 4)\n\t                Track.Position = UDim2.fromOffset(12, 32)\n\t                Track.BackgroundColor3 = UIPallet.Main\n\t                Track.BorderSizePixel = 0\n\t                Track.Parent = Back\n\t                local TrackCorner: UICorner = Instance.new(\"UICorner\")\n\t                TrackCorner.CornerRadius = UDim.new(1, 0)\n\t                TrackCorner.Parent = Track\n\t                local Fill: Frame = Instance.new(\"Frame\")\n\t                Fill.Size = UDim2.fromScale(1, 1)\n\t                Fill.BackgroundColor3 = Color3.fromHSV(0.4, 0.89, 0.75)\n\t                Fill.BorderSizePixel = 0\n\t                Fill.Parent = Track\n\t                local FillCorner: UICorner = Instance.new(\"UICorner\")\n\t                FillCorner.CornerRadius = UDim.new(1, 0)\n\t                FillCorner.Parent = Fill\n\t                CustomFill = Fill\n\t            end\n\t\n\t            Built[BedId] = {\n\t                Model = Model,\n\t                Anchor = Anchor,\n\t                Fill = CustomFill,\n\t                Shield = Shield,\n\t                Tint = Fill == nil,\n\t                Data = Stream,\n\t                Cursor = 1,\n\t                PlateMax = Stream[4] or 0,\n\t                HealthMax = math.max(Stream[3] or 1, 1),\n\t                Last = Stream[#Stream - 3] or 0\n\t            }\n\t        end\n\t    end\n\t\n\t    return Built\n\tend\n\t\n\tlocal function UpdateFeed(Elapsed: number)\n\t    local Feed = Timeline and Timeline.Feed\n\t    local Stream = Playback.Events\n\t    local Native = Playback.Data.GameFeed\n\t    if Feed and type(Native) == \"table\" and #Native > 0 then\n\t        Playback.FeedRows = Playback.FeedRows or {}\n\t        for i: number, Entry: any in Native do\n\t            local Visible: boolean = Elapsed >= Entry.Time and Elapsed < Entry.Time + (Entry.Duration or 5)\n\t            local Row = Playback.FeedRows[i]\n\t            if Visible and not Row then\n\t                Row = ReplayVisuals.Restore(Entry.Gui, Feed)\n\t                if Row then Row.LayoutOrder = i end\n\t                Playback.FeedRows[i] = Row\n\t            elseif not Visible and Row then\n\t                Row:Destroy()\n\t                Playback.FeedRows[i] = nil\n\t            end\n\t        end\n\t        return\n\t    end\n\t    if not Feed or type(Stream) ~= \"table\" then\n\t        return\n\t    end\n\t\n\t    local Cursor: number = Playback.EventCursor or 1\n\t    if Elapsed < (Playback.FeedTime or 0) then\n\t        for _, v: TextLabel in Feed:GetChildren() do\n\t            if v:IsA(\"TextLabel\") then\n\t                v:Destroy()\n\t            end\n\t        end\n\t        Cursor = 1\n\t    end\n\t    Playback.FeedTime = Elapsed\n\t\n\t    while (Cursor + 1) <= #Stream and Stream[Cursor] <= Elapsed do\n\t        local Label: TextLabel = Instance.new(\"TextLabel\")\n\t        Label.Size = UDim2.new(1, 0, 0, 16)\n\t        Label.BackgroundTransparency = 1\n\t        Label.TextColor3 = UIPallet.Text\n\t        Label.TextStrokeTransparency = 0.5\n\t        Label.TextSize = 12\n\t        Label.FontFace = UIPallet.Font\n\t        Label.TextXAlignment = Enum.TextXAlignment.Left\n\t        Label.LayoutOrder = Cursor\n\t        Label.Text = tostring(Stream[Cursor + 1])\n\t        Label.Parent = Feed\n\t\n\t        local Children: {Instance} = Feed:GetChildren()\n\t        if #Children > 7 then\n\t            for _, v: TextLabel in Children do\n\t                if v:IsA(\"TextLabel\") and v.LayoutOrder < Cursor - 6 then\n\t                    v:Destroy()\n\t                end\n\t            end\n\t        end\n\t        Cursor += 2\n\t    end\n\t    Playback.EventCursor = Cursor\n\tend\n\t\n\tlocal function PlayReplaySound(SoundId, Position: Vector3?, Volume: number)\n\t    if not SoundId then\n\t        return\n\t    end\n\t\n\t    MuteSounds = true\n\t    pcall(function()\n\t        bedwars.AudioManager:playAudio(SoundId, {position = Position, volumeMultiplier = Volume * SoundVolume.Value})\n\t    end)\n\t    MuteSounds = false\n\tend\n\t\n\tlocal function UpdateBeds(Elapsed: number)\n\t    local Rewound: boolean = Elapsed < (Playback.BedTime or 0)\n\t    Playback.BedTime = Elapsed\n\t\n\t    for _, v: any in Playback.Beds do\n\t        local Stream = v.Data\n\t        if #Stream >= 4 then\n\t            local Cursor: number = v.Cursor\n\t            if Elapsed < Stream[Cursor] then\n\t                Cursor = 1\n\t            end\n\t            while (Cursor + 4) <= #Stream and Stream[Cursor + 4] <= Elapsed do\n\t                Cursor += 4\n\t            end\n\t            v.Cursor = Cursor\n\t\n\t            local Health, Plating = Stream[Cursor + 1], Stream[Cursor + 3]\n\t            local Alive: boolean = Health > 0 and Elapsed <= (v.Last + 0.5)\n\t            if v.Alive ~= Alive then\n\t                if v.Alive and not Alive and Health <= 0 and not Rewound and Sounds.Enabled then\n\t                    PlayReplaySound(bedwars.SoundList.BED_BREAK, v.Anchor.Position, 1)\n\t                end\n\t                v.Alive = Alive\n\t            end\n\t\n\t            if v.Tint then\n\t                local Percent: number = v.PlateMax > 0 and math.clamp(Plating / v.PlateMax, 0, 1) or math.clamp(Health / v.HealthMax, 0, 1)\n\t                v.Fill.Size = UDim2.fromScale(Percent, 1)\n\t                v.Fill.BackgroundColor3 = Color3.fromHSV(math.clamp(Percent / 2.5, 0, 1), 0.89, 0.75)\n\t            else\n\t                v.Fill.Size = UDim2.fromScale(math.clamp(Health / v.HealthMax, 0, 1), 1)\n\t                if v.Shield then\n\t                    v.Shield.Size = UDim2.fromScale(math.clamp(Plating / v.PlateMax, 0, 1), 1)\n\t                end\n\t            end\n\t            v.Anchor.Parent = Alive and Playback.World or nil\n\t            if v.Model then\n\t                v.Model.Parent = Alive and Playback.World or nil\n\t            end\n\t        end\n\t    end\n\tend\n\t\n\tlocal function StopPlayback()\n\t    if not Playback then\n\t        return\n\t    end\n\t\n\t    for _, v: any in Playback.Rigs do\n\t        for _, v: Accessory in v.ArmorPieces do\n\t            v:Destroy()\n\t        end\n\t        v.Model:Destroy()\n\t    end\n\t    for _, v: Part in Playback.Blocks do\n\t        v:Destroy()\n\t    end\n\t    if Playback.World then\n\t        Playback.World:Destroy()\n\t    end\n\t    Playback = nil\n\t    DestroyTimeline()\n\t\n\t    local Gui: ScreenGui? = LocalPlayer.PlayerGui:FindFirstChild(\"ReplayHotbar\")\n\t    if Gui then Gui:Destroy() end\n\t    if HotbarTemplate then\n\t        HotbarTemplate:Destroy()\n\t        HotbarTemplate = nil\n\t    end\n\t\n\t    HideGameGuis(false)\n\t    StopFreecam()\n\tend\n\t\n\tlocal function UpdateBlocks(Elapsed: number)\n\t    local Stream = Playback.BlockStream\n\t    local Blocks = Playback.Blocks\n\t\n\t    if Elapsed < (Playback.BlockTime or 0) then\n\t        for Key: string, v: Part in Blocks do\n\t            v:Destroy()\n\t            Blocks[Key] = nil\n\t        end\n\t        Playback.BlockCursor = 1\n\t    end\n\t    Playback.BlockTime = Elapsed\n\t\n\t    local Cursor: number = Playback.BlockCursor\n\t    while (Cursor + BlockSize - 1) <= #Stream and Stream[Cursor] <= Elapsed do\n\t        local Action: number = Stream[Cursor + 1]\n\t        local Position: Vector3 = Vector3.new(Stream[Cursor + 2], Stream[Cursor + 3], Stream[Cursor + 4]) * 3\n\t        local Key: string = `{Position.X}_{Position.Y}_{Position.Z}`\n\t\n\t        if Action == 1 then\n\t            if not Blocks[Key] then\n\t                local BlockType: string = Playback.Data.Items[Stream[Cursor + 5]] or \"\"\n\t                local Block: Part = Instance.new(\"Part\")\n\t                Block.Name = BlockType ~= \"\" and BlockType or \"ReplayBlock\"\n\t                Block.Size = Vector3.new(3, 3, 3)\n\t                Block.Anchored = true\n\t                Block.CanCollide = false\n\t                Block.CanQuery = false\n\t                Block.TopSurface = Enum.SurfaceType.Smooth\n\t                Block.BottomSurface = Enum.SurfaceType.Smooth\n\t                Block.Position = Position + ReplayOffset\n\t                local Look = Playback.Data.Looks and Playback.Data.Looks[BlockType]\n\t                ApplyBlockLook(Block, BlockType, Look and Color3.fromRGB(Look[2], Look[3], Look[4]) or Color3.fromRGB(235, 235, 235), Look and Look[5], Look and Look[6], Look and Look[7], Look and Look[9])\n\t                Block.Parent = Playback.World or workspace\n\t                Blocks[Key] = Block\n\t            end\n\t        elseif Blocks[Key] then\n\t            Blocks[Key]:Destroy()\n\t            Blocks[Key] = nil\n\t        end\n\t\n\t        Cursor += BlockSize\n\t    end\n\t    Playback.BlockCursor = Cursor\n\tend\n\t\n\tlocal function BuildDrop(ItemType: string)\n\t    local Items = ReplicatedStorage:FindFirstChild(\"Items\")\n\t    local Template = Items and Items:FindFirstChild(ItemType)\n\t    local Handle = Template and Template:FindFirstChild(\"Handle\")\n\t    local Drop\n\t\n\t    if Handle and Handle:IsA(\"BasePart\") then\n\t        Drop = Handle:Clone()\n\t        for _, v: Instance in Drop:GetDescendants() do\n\t            if v:IsA(\"TouchTransmitter\") or v:IsA(\"BaseScript\") then\n\t                v:Destroy()\n\t            elseif v:IsA(\"BasePart\") then\n\t                v.Anchored = false\n\t                v.CanCollide = false\n\t                v.CanQuery = false\n\t                v.Massless = true\n\t            end\n\t        end\n\t    else\n\t        Drop = Instance.new(\"Part\")\n\t        Drop.Size = Vector3.new(1, 1, 1)\n\t        ApplyBlockLook(Drop, ItemType, Color3.fromRGB(200, 200, 200))\n\t    end\n\t\n\t    Drop.Name = ItemType ~= \"\" and ItemType or \"ReplayDrop\"\n\t    Drop.Anchored = true\n\t    Drop.CanCollide = false\n\t    Drop.CanQuery = false\n\t    Drop.Massless = true\n\t    Drop.Parent = Playback.World or workspace\n\t    return Drop\n\tend\n\t\n\tlocal function UpdateDrops(Elapsed: number)\n\t    local Stream = Playback.DropStream\n\t    local Drops = Playback.Drops\n\t    if #Stream < DropSize then\n\t        return\n\t    end\n\t\n\t    if Elapsed < (Playback.DropTime or 0) then\n\t        for Id: number, v: BasePart in Drops do\n\t            v:Destroy()\n\t            Drops[Id] = nil\n\t        end\n\t        Playback.DropCursor = 1\n\t    end\n\t    Playback.DropTime = Elapsed\n\t\n\t    local Cursor: number = Playback.DropCursor\n\t    while (Cursor + DropSize - 1) <= #Stream and Stream[Cursor] <= Elapsed do\n\t        local Id: number = Stream[Cursor + 2]\n\t\n\t        if Stream[Cursor + 1] == 1 then\n\t            local Drop = Drops[Id] or BuildDrop(Playback.Data.Items[Stream[Cursor + 3]] or \"\")\n\t            Drop.CFrame = CFrame.new(Vector3.new(Stream[Cursor + 4], Stream[Cursor + 5], Stream[Cursor + 6]) + ReplayOffset) * CFrame.Angles(0, math.rad(Stream[Cursor + 7]), 0)\n\t            Drops[Id] = Drop\n\t        elseif Drops[Id] then\n\t            Drops[Id]:Destroy()\n\t            Drops[Id] = nil\n\t        end\n\t\n\t        Cursor += DropSize\n\t    end\n\t    Playback.DropCursor = Cursor\n\tend\n\t\n\tlocal function SetArmor(Rig, ArmorSet)\n\t    if Rig.ArmorId == ArmorSet then\n\t        return\n\t    end\n\t    Rig.ArmorId = ArmorSet\n\t\n\t    for _, v: Accessory in Rig.ArmorPieces do\n\t        v:Destroy()\n\t    end\n\t    table.clear(Rig.ArmorPieces)\n\t\n\t    local Avatar = Rig.Avatar\n\t    if not Avatar or not Armor.Enabled or type(ArmorSet) ~= \"table\" then\n\t        return\n\t    end\n\t\n\t    local Existing = {}\n\t    for _, v: Accessory in Avatar:GetChildren() do\n\t        if v:IsA(\"Accessory\") then\n\t            Existing[v] = true\n\t        end\n\t    end\n\t\n\t    local Items = ReplicatedStorage:FindFirstChild(\"Items\")\n\t    for _, ItemIndex: number in ArmorSet do\n\t        local ItemType: string = Playback.Data.Items[ItemIndex] or \"\"\n\t        local Template = ItemType ~= \"\" and Items and Items:FindFirstChild(ItemType) or nil\n\t        if Template then\n\t            local Clone = Template:Clone()\n\t            for _, v: Instance in Clone:GetDescendants() do\n\t                if v:IsA(\"BasePart\") then\n\t                    v.CanCollide = false\n\t                    v.CanQuery = false\n\t                    v.Massless = true\n\t                elseif v:IsA(\"BaseScript\") then\n\t                    v:Destroy()\n\t                end\n\t            end\n\t\n\t            Clone.Parent = Avatar\n\t            pcall(function()\n\t                bedwars.WeldTable:weldAccessory(Avatar, Clone)\n\t                bedwars.WeldTable:weldCharacterAccessories(Avatar, Clone)\n\t            end)\n\t        end\n\t    end\n\t\n\t    for _, v: Accessory in Avatar:GetChildren() do\n\t        if v:IsA(\"Accessory\") and not Existing[v] then\n\t            table.insert(Rig.ArmorPieces, v)\n\t        end\n\t    end\n\tend\n\t\n\tlocal function Hermite(P0: number, V0: number, P1: number, V1: number, Alpha: number, Span: number)\n\t    local AlphaSquared: number = Alpha * Alpha\n\t    local AlphaCubed: number = AlphaSquared * Alpha\n\t    return ((2 * AlphaCubed) - (3 * AlphaSquared) + 1) * P0 + (AlphaCubed - (2 * AlphaSquared) + Alpha) * Span * V0 + ((3 * AlphaSquared) - (2 * AlphaCubed)) * P1 + (AlphaCubed - AlphaSquared) * Span * V1\n\tend\n\t\n\tlocal function UpdateSounds(Elapsed: number)\n\t    local Stream = Playback.SoundStream\n\t    if not Sounds.Enabled or #Stream < SoundSize then\n\t        return\n\t    end\n\t\n\t    if Elapsed < (Playback.SoundTime or 0) then\n\t        Playback.SoundCursor = 1\n\t    end\n\t    Playback.SoundTime = Elapsed\n\t\n\t    local Cursor: number = Playback.SoundCursor\n\t    while (Cursor + SoundSize - 1) <= #Stream and Stream[Cursor] <= Elapsed do\n\t        local SoundId = Playback.Data.SoundIds[Stream[Cursor + 1]]\n\t        if SoundId and SoundId ~= bedwars.SoundList.BED_BREAK and Elapsed - Stream[Cursor] < 0.35 then\n\t            local Position: Vector3? = Stream[Cursor + 6] == 1 and Vector3.new(Stream[Cursor + 2], Stream[Cursor + 3], Stream[Cursor + 4]) + ReplayOffset or nil\n\t            PlayReplaySound(SoundId, Position, Stream[Cursor + 5])\n\t        end\n\t        Cursor += SoundSize\n\t    end\n\t    Playback.SoundCursor = Cursor\n\tend\n\t\n\tlocal function UpdateAnimations(Rig, Track, Elapsed: number)\n\t    local Stream = Track.Anims\n\t\n\t    if Elapsed < (Rig.AnimTime or 0) then\n\t        for _, v: AnimationTrack | boolean in Rig.Playing do\n\t            if v then\n\t                v:Stop(0.1)\n\t            end\n\t        end\n\t        Rig.AnimCursor = 1\n\t    end\n\t    Rig.AnimTime = Elapsed\n\t\n\t    local Cursor: number = Rig.AnimCursor or 1\n\t    while (Cursor + AnimationSize - 1) <= #Stream and Stream[Cursor] <= Elapsed do\n\t        local AnimationId: string? = Playback.Data.AnimIds[Stream[Cursor + 2]]\n\t        local Playing = AnimationId and Rig.Playing[AnimationId]\n\t        if AnimationId and Playing == nil then\n\t            local Animation: Animation = Instance.new(\"Animation\")\n\t            Animation.AnimationId = AnimationId\n\t            local Loaded, Created = pcall(Rig.Animator.LoadAnimation, Rig.Animator, Animation)\n\t            Playing = Loaded and Created or false\n\t            Rig.Playing[AnimationId] = Playing\n\t        end\n\t\n\t        if Playing then\n\t            if Stream[Cursor + 1] == 1 then\n\t                Rig.AnimSpeeds[AnimationId] = Stream[Cursor + 3]\n\t                Rig.AnimScale = nil\n\t                Playing:Play(0.1)\n\t            else\n\t                Playing:Stop(0.1)\n\t            end\n\t        end\n\t        Cursor += AnimationSize\n\t    end\n\t    Rig.AnimCursor = Cursor\n\t\n\t    local Scale: number = Playback.Paused and 0 or Speed.Value\n\t    if Rig.AnimScale ~= Scale then\n\t        Rig.AnimScale = Scale\n\t        for AnimationId: string, v: AnimationTrack | boolean in Rig.Playing do\n\t            if v then\n\t                v:AdjustSpeed((Rig.AnimSpeeds[AnimationId] or 1) * Scale)\n\t            end\n\t        end\n\t    end\n\tend\n\t\n\tlocal function UpdateHits(Rig, Track, Elapsed: number, RigCFrame: CFrame)\n\t    local Stream = Track.Hits\n\t\n\t    if Elapsed < (Rig.HitTime or 0) then\n\t        if Rig.Highlight then\n\t            Rig.Highlight.Enabled = false\n\t        end\n\t        Rig.HitFlash = nil\n\t        Rig.HitCursor = 1\n\t    end\n\t    Rig.HitTime = Elapsed\n\t\n\t    local Cursor: number = Rig.HitCursor or 1\n\t    while (Cursor + DamageSize - 1) <= #Stream and Stream[Cursor] <= Elapsed do\n\t        if Elapsed - Stream[Cursor] < 0.35 then\n\t            if not Rig.Highlight then\n\t                Rig.Highlight = Instance.new(\"Highlight\")\n\t                Rig.Highlight.Name = \"_DamageHighlight_\"\n\t                Rig.Highlight.FillColor = Color3.fromRGB(255, 0, 0)\n\t                Rig.Highlight.FillTransparency = 0.4\n\t                Rig.Highlight.OutlineTransparency = 1\n\t                Rig.Highlight.DepthMode = Enum.HighlightDepthMode.Occluded\n\t                Rig.Highlight.Parent = Rig.Model\n\t            end\n\t\n\t            Rig.Highlight.Enabled = true\n\t            Rig.HitFlash = Elapsed + 0.2\n\t            bedwars.DamageIndicatorController:spawnDamageIndicator(RigCFrame.Position + Vector3.new(0, 2.5, 0), Stream[Cursor + 1], {\n\t                damageType = Playback.Data.DamageTypes[Stream[Cursor + 2]],\n\t                infiniteRange = true\n\t            })\n\t        end\n\t        Cursor += DamageSize\n\t    end\n\t    Rig.HitCursor = Cursor\n\t\n\t    if Rig.HitFlash and Elapsed >= Rig.HitFlash then\n\t        Rig.HitFlash = nil\n\t        Rig.Highlight.Enabled = false\n\t    end\n\tend\n\t\n\tlocal function UpdateHotbarGui(Elapsed: number)\n\t    local Gui: ScreenGui? = Playback.HotbarGui\n\t    if not Gui then\n\t        return\n\t    end\n\t\n\t    local Track = Playback.Spectate and Playback.Data.Tracks[Playback.Spectate]\n\t    if not Track then\n\t        Gui.Enabled = false\n\t        return\n\t    end\n\t    Gui.Enabled = true\n\t\n\t    local Root = Gui:FindFirstChild(\"1\")\n\t    local Items = Root and Root:FindFirstChild(\"ItemsHotbar\")\n\t    local Slots = Track.Hotbar\n\t    local SlotStride: number = Playback.Data.HotbarStride or 19\n\t    if Items and not HotbarTemplate then\n\t        for _, v: Instance in Items:GetChildren() do\n\t            local Frame = v:FindFirstChild(\"1\") and v[\"1\"]:FindFirstChild(\"3\")\n\t            if Frame and Frame:FindFirstChild(\"1\") and Frame:FindFirstChild(\"2\") and not Frame:GetAttribute(\"ReplayClone\") then\n\t                HotbarTemplate = Frame:Clone()\n\t                break\n\t            end\n\t        end\n\t    end\n\t\n\t    if Items and type(Slots) == \"table\" and #Slots >= SlotStride and Slots[1] <= Elapsed then\n\t        local Cursor: number = 1\n\t        for i: number = 1, #Slots - (SlotStride - 1), SlotStride do\n\t            if Slots[i] > Elapsed then\n\t                break\n\t            end\n\t            Cursor = i\n\t        end\n\t\n\t        for i: number = 1, 9 do\n\t            local Slot = Items:FindFirstChild(tostring(i))\n\t            local Button = Slot and Slot:FindFirstChild(\"1\")\n\t            if Button then\n\t                local ItemType: string = Playback.Data.Items[Slots[Cursor + (i * 2) - 1]] or \"\"\n\t                local Amount: number = Slots[Cursor + (i * 2)] or 0\n\t                local Selected: boolean = SlotStride >= 20 and Slots[Cursor + 19] == i - 1 or SlotStride < 20 and ItemType ~= \"\" and ItemType == Playback.SpectateItem\n\t                Button.BackgroundColor3 = Selected and Color3.fromRGB(255, 255, 255) or Color3.fromRGB(114, 127, 172)\n\t                local Frame = Button:FindFirstChild(\"3\")\n\t                if ItemType == \"\" then\n\t                    if Frame then\n\t                        Frame.Visible = false\n\t                    end\n\t                else\n\t                    if not Frame and HotbarTemplate then\n\t                        Frame = HotbarTemplate:Clone()\n\t                        Frame:SetAttribute(\"ReplayClone\", true)\n\t                        Frame.Parent = Button\n\t                    end\n\t\n\t                    if Frame then\n\t                        Frame.Visible = true\n\t                        local Icon = Frame:FindFirstChild(\"1\")\n\t                        if Icon then\n\t                            Icon.Image = bedwars.getIcon({itemType = ItemType}, true)\n\t                        end\n\t\n\t                        local CountLabel = Frame:FindFirstChild(\"2\")\n\t                        if CountLabel then\n\t                            CountLabel.Text = tostring(Amount)\n\t                            CountLabel.Visible = Amount > 1\n\t                        end\n\t                    end\n\t                end\n\t            end\n\t        end\n\t    end\n\t\n\t    if Items then Items.Visible = type(Slots) == \"table\" and #Slots >= SlotStride and Slots[1] <= Elapsed end\n\t    local Container = Root and Root:FindFirstChild(\"HotbarHealthbarContainer\")\n\t    local Health: number = Playback.SpectateHealth or 0\n\t    local Label = Container and Container:FindFirstChild(\"1\")\n\t    if Label then\n\t        Label.Text = `{math.floor(Health)} `\n\t    end\n\t\n\t    local Wrapper = Container and Container:FindFirstChild(\"HealthbarProgressWrapper\")\n\t    local Bar = Wrapper and Wrapper:FindFirstChild(\"1\")\n\t    if Bar then\n\t        Bar.Size = UDim2.fromScale(math.clamp(Health / (Playback.SpectateMaxHealth or 100), 0, 1), Bar.Size.Y.Scale)\n\t    end\n\tend\n\t\n\tlocal function UpdatePlayback(Elapsed: number)\n\t    local Data = Playback.Data\n\t    local Stride: number = Playback.Stride\n\t    local Legacy: boolean = Stride == LegacySize\n\t    local Finished: boolean = true\n\t\n\t    UpdateBlocks(Elapsed)\n\t    UpdateDrops(Elapsed)\n\t    if Playback.Beds then\n\t        UpdateBeds(Elapsed)\n\t    end\n\t    UpdateFeed(Elapsed)\n\t    UpdateSounds(Elapsed)\n\t\n\t    for Name: string, v: any in Data.Tracks do\n\t        local Rig = Playback.Rigs[Name]\n\t        local Stream = v.Data\n\t        local Cursor: number = v.Cursor\n\t        if Elapsed < Stream[Cursor] then\n\t            Cursor = 1\n\t        end\n\t        while (Cursor + Stride) <= #Stream and Stream[Cursor + Stride] <= Elapsed do\n\t            Cursor += Stride\n\t        end\n\t        v.Cursor = Cursor\n\t\n\t        local NextCursor: number = Cursor + Stride\n\t        while (NextCursor + Stride - 1) <= #Stream and Stream[NextCursor] <= Stream[Cursor] do\n\t            NextCursor += Stride\n\t        end\n\t        local HasNext: boolean = (NextCursor + Stride - 1) <= #Stream\n\t        local Health: number = Stream[Cursor + (Legacy and 5 or 9)]\n\t        local InRange: boolean = Elapsed >= Stream[1] and Elapsed <= v.Last and Health > 0\n\t\n\t        if HasNext then\n\t            Finished = false\n\t        end\n\t\n\t        if Rig.Visible ~= InRange then\n\t            Rig.Visible = InRange\n\t            Rig.Model.Parent = InRange and workspace or nil\n\t        end\n\t\n\t        if InRange then\n\t            local X, Y, Z = Stream[Cursor + 1], Stream[Cursor + 2], Stream[Cursor + 3]\n\t            local Yaw: number = Stream[Cursor + 4]\n\t            local Pitch: number = Legacy and 0 or Stream[Cursor + 5]\n\t            local FlatSpeed, RiseSpeed = 0, 0\n\t\n\t            local Interpolate: boolean = HasNext and Vector3.new(Stream[NextCursor + 1] - X, Stream[NextCursor + 2] - Y, Stream[NextCursor + 3] - Z).Magnitude <= 40\n\t            if Interpolate then\n\t                local From: number = Stream[Cursor]\n\t                local Span: number = Stream[NextCursor] - From\n\t                local Alpha: number = Span > 0 and math.clamp((Elapsed - From) / Span, 0, 1) or 0\n\t                local NextX, NextY, NextZ = Stream[NextCursor + 1], Stream[NextCursor + 2], Stream[NextCursor + 3]\n\t\n\t                if Legacy then\n\t                    if Span > 0 then\n\t                        FlatSpeed = Vector3.new(NextX - X, 0, NextZ - Z).Magnitude / Span\n\t                        RiseSpeed = (NextY - Y) / Span\n\t                    end\n\t\n\t                    local Previous: number = Cursor - Stride\n\t                    local After: number = NextCursor + Stride\n\t                    local PreviousX: number = Previous >= 1 and Stream[Previous + 1] or (X - (NextX - X))\n\t                    local PreviousY: number = Previous >= 1 and Stream[Previous + 2] or (Y - (NextY - Y))\n\t                    local PreviousZ: number = Previous >= 1 and Stream[Previous + 3] or (Z - (NextZ - Z))\n\t                    local AfterX: number = (After + Stride - 1) <= #Stream and Stream[After + 1] or (NextX + (NextX - X))\n\t                    local AfterY: number = (After + Stride - 1) <= #Stream and Stream[After + 2] or (NextY + (NextY - Y))\n\t                    local AfterZ: number = (After + Stride - 1) <= #Stream and Stream[After + 3] or (NextZ + (NextZ - Z))\n\t                    local AlphaSquared: number = Alpha * Alpha\n\t                    local AlphaCubed: number = AlphaSquared * Alpha\n\t                    local function Spline(P0: number, P1: number, P2: number, P3: number)\n\t                        return 0.5 * ((2 * P1) + (-P0 + P2) * Alpha + (2 * P0 - 5 * P1 + 4 * P2 - P3) * AlphaSquared + (-P0 + 3 * P1 - 3 * P2 + P3) * AlphaCubed)\n\t                    end\n\t\n\t                    X = Spline(PreviousX, X, NextX, AfterX)\n\t                    Y = Spline(PreviousY, Y, NextY, AfterY)\n\t                    Z = Spline(PreviousZ, Z, NextZ, AfterZ)\n\t                else\n\t                    local VelocityX, VelocityY, VelocityZ = Stream[Cursor + 6], Stream[Cursor + 7], Stream[Cursor + 8]\n\t                    local NextVelocityX, NextVelocityY, NextVelocityZ = Stream[NextCursor + 6], Stream[NextCursor + 7], Stream[NextCursor + 8]\n\t                    X = Hermite(X, VelocityX, NextX, NextVelocityX, Alpha, Span)\n\t                    Y = Hermite(Y, VelocityY, NextY, NextVelocityY, Alpha, Span)\n\t                    Z = Hermite(Z, VelocityZ, NextZ, NextVelocityZ, Alpha, Span)\n\t                    FlatSpeed = Vector3.new(VelocityX + (NextVelocityX - VelocityX) * Alpha, 0, VelocityZ + (NextVelocityZ - VelocityZ) * Alpha).Magnitude\n\t                    RiseSpeed = VelocityY + (NextVelocityY - VelocityY) * Alpha\n\t                    Pitch += ((((Stream[NextCursor + 5] - Pitch) + 180) % 360) - 180) * Alpha\n\t                end\n\t\n\t                Yaw += ((((Stream[NextCursor + 4] - Yaw) + 180) % 360) - 180) * Alpha\n\t            end\n\t\n\t            local RigCFrame: CFrame = CFrame.new(Vector3.new(X, Y, Z) + ReplayOffset) * CFrame.Angles(0, math.rad(Yaw), 0)\n\t            Rig.Body.CFrame = RigCFrame * CFrame.new(0, -0.5, 0)\n\t            Rig.Body.Transparency = Rig.Avatar and 1 or 0\n\t\n\t            if Rig.Avatar and Rig.Avatar.PrimaryPart then\n\t                Rig.Avatar.PrimaryPart.CFrame = RigCFrame\n\t\n\t                if Rig.Neck then\n\t                    Rig.Neck.C0 = Rig.NeckBase * CFrame.Angles(math.rad(Pitch), 0, 0)\n\t                end\n\t\n\t                if Animations.Enabled and Rig.Animator and #(v.Anims or {}) >= AnimationSize then\n\t                    UpdateAnimations(Rig, v, Elapsed)\n\t                elseif Rig.Anims then\n\t                    local State: string = \"Idle\"\n\t                    if RiseSpeed < -24 then\n\t                        State = \"Fall\"\n\t                    elseif FlatSpeed > 19 then\n\t                        State = \"Run\"\n\t                    elseif FlatSpeed > 1 then\n\t                        State = \"Walk\"\n\t                    end\n\t\n\t                    if Rig.AnimState ~= State then\n\t                        local Previous = Rig.AnimState and Rig.Anims[Rig.AnimState]\n\t                        if Previous then\n\t                            Previous:Stop(0.15)\n\t                        end\n\t                        if Rig.Anims[State] then\n\t                            Rig.Anims[State]:Play(0.15)\n\t                        end\n\t                        Rig.AnimState = State\n\t                    end\n\t                end\n\t\n\t                if not Legacy then\n\t                    SetArmor(Rig, (Data.Armors or {})[Stream[Cursor + 12]])\n\t                end\n\t            end\n\t\n\t            if DamageEffects.Enabled and #(v.Hits or {}) >= DamageSize then\n\t                UpdateHits(Rig, v, Elapsed, RigCFrame)\n\t            end\n\t\n\t            local ItemType: string = Data.Items[Stream[Cursor + (Legacy and 6 or 10)]] or \"\"\n\t            SetHeldItem(Rig, ItemType)\n\t            if Rig.Held and Rig.Held.Anchored then\n\t                Rig.Held.CFrame = RigCFrame * Rig.HeldOffset\n\t            end\n\t\n\t            local MaxHealth: number = v.MaxHealth or Data.MaxHealth or 100\n\t            Rig.HealthFill.Size = UDim2.fromScale(math.clamp(Health / MaxHealth, 0, 1), 1)\n\t            Rig.HealthText.Text = tostring(math.floor(Health))\n\t            if Name == Playback.Spectate then\n\t                Playback.SpectateHealth, Playback.SpectateMaxHealth, Playback.SpectateItem = Health, MaxHealth, ItemType\n\t            end\n\t            Rig.HeldLabel.Text = ItemType\n\t            UpdateIcons(Rig, (Data.Loadouts or {})[Stream[Cursor + (Legacy and 7 or 11)]], Data.Items)\n\t        end\n\t    end\n\t\n\t    UpdateHotbarGui(Elapsed)\n\t    return Finished\n\tend\n\t\n\tlocal function StartPlayback()\n\t    StopPlayback()\n\t\n\t    local FileName: string = Replays.Value\n\t    local FilePath: string = `{ReplayFolder}/{FileName}`\n\t    if FileName == \"None\" or not isfile(FilePath) then\n\t        notif(\"ReplayMod\", \"No replay selected\", 5, \"alert\")\n\t        return\n\t    end\n\t\n\t    local Success, Data = pcall(function()\n\t        return HttpService:JSONDecode(readfile(FilePath))\n\t    end)\n\t    if not Success or type(Data) ~= \"table\" or type(Data.Tracks) ~= \"table\" then\n\t        notif(\"ReplayMod\", \"That replay is corrupted\", 5, \"alert\")\n\t        return\n\t    end\n\t\n\t    local Stride: number = Data.Stride or LegacySize\n\t    local Rigs = {}\n\t    local Count, Duration = 0, 0\n\t    for Name: string, v: any in Data.Tracks do\n\t        v.Cursor = 1\n\t        v.Last = v.Data[#v.Data - (Stride - 1)] or 0\n\t        Duration = math.max(Duration, v.Last)\n\t        local TeamColor = v.Color or {255, 255, 255}\n\t        local Rig = BuildRig(Name, Color3.fromRGB(TeamColor[1], TeamColor[2], TeamColor[3]))\n\t        Rig.Visible = true\n\t        Rigs[Name] = Rig\n\t        Count += 1\n\t    end\n\t\n\t    local BlockStream = Data.Blocks or {}\n\t    if #BlockStream >= BlockSize then\n\t        Duration = math.max(Duration, BlockStream[#BlockStream - (BlockSize - 1)])\n\t    end\n\t\n\t    Data.DamageTypes = Data.DamageTypes or {}\n\t\n\t    local Success, Controls = pcall(function()\n\t        return require(LocalPlayer.PlayerScripts:WaitForChild(\"PlayerModule\", 5)):GetControls()\n\t    end)\n\t    Controls = Success and Controls or nil\n\t\n\t    Playback = {\n\t        Data = Data,\n\t        Stride = Stride,\n\t        Rigs = Rigs,\n\t        Blocks = {},\n\t        BlockStream = BlockStream,\n\t        BlockCursor = 1,\n\t        Drops = {},\n\t        DropStream = Data.Drops or {},\n\t        DropCursor = 1,\n\t        SoundStream = Data.SoundStream or {},\n\t        SoundCursor = 1,\n\t        Clock = 0,\n\t        Duration = Duration,\n\t        Controls = Controls\n\t    }\n\t\n\t    local World, Built, Center, Span = BuildMap(Data)\n\t    if not Playback then\n\t        return\n\t    end\n\t    Playback.World = World\n\t    Playback.Beds = BuildBeds(Data, World)\n\t    Playback.Events = Data.Events or {}\n\t\n\t    if FreeCam.Enabled then\n\t        StartFreecam()\n\t        if Center then\n\t            FreeCamState.Position = Center + Vector3.new(0, Span * 0.35, Span * 0.6)\n\t            FreeCamState.Pitch = -0.5\n\t            FreeCamState.Yaw = 0\n\t        end\n\t    end\n\t\n\t    if Rigs[LocalPlayer.Name] then\n\t        Playback.Spectate = LocalPlayer.Name\n\t    end\n\t\n\t    if Avatars.Enabled then\n\t        for Name: string, v: any in Data.Tracks do\n\t            if v.Model then\n\t                LoadNpcModel(Rigs[Name], v.Model)\n\t            else\n\t                LoadAvatar(Rigs[Name], Name, v.UserId, v.Rig, v.NPC)\n\t            end\n\t        end\n\t    end\n\t\n\t    BuildTimeline()\n\t    local Hotbar: ScreenGui? = Data.HUD and ReplayVisuals.Restore(Data.HUD) or LocalPlayer.PlayerGui:FindFirstChild(\"hotbar\") and LocalPlayer.PlayerGui.hotbar:Clone()\n\t    if Hotbar then\n\t        Hotbar.Name = \"ReplayHotbar\"\n\t        Hotbar.ResetOnSpawn = false\n\t        Hotbar.DisplayOrder = 49\n\t        for _, v: Instance in Hotbar:GetDescendants() do if v:IsA(\"BaseScript\") then v:Destroy() end end\n\t        Hotbar.Parent = LocalPlayer.PlayerGui\n\t        Playback.HotbarGui = Hotbar\n\t    end\n\t    HideGameGuis(true)\n\t    if Timeline then\n\t        Timeline.Spectate.Text = Playback.Spectate or \"Free camera\"\n\t    end\n\t    UpdateTimeline()\n\t    notif(\"ReplayMod\", `Playing {FileName} ({Count} players, {Built} blocks, {math.floor(Duration)}s)`, 8)\n\tend\n\t\n\tlocal function SeekPlayback(Percent: number)\n\t    if not Playback then\n\t        return\n\t    end\n\t    Playback.Clock = (Playback.Duration or 0) * (Percent / 100)\n\tend\n\t\n\tReplayMod = vape.Categories.Utility:CreateModule({\n\t    Name = \"ReplayMod\",\n\t    Function = function(Callback: boolean)\n\t        if Callback then\n\t            StartRecording()\n\t            Accumulator = 0\n\t            local LastState = store.matchState\n\t\n\t            OldPlaySound = OldPlaySound or bedwars.AudioManager.playAudio\n\t            bedwars.AudioManager.playAudio = function(self, SoundId, Config, ...)\n\t                if Recording and not MuteSounds and Sounds.Enabled and typeof(SoundId) == \"string\" then\n\t                    local Settings = type(Config) == \"table\" and Config or {}\n\t                    local Position: Vector3? = typeof(Settings.position) == \"Vector3\" and Settings.position or nil\n\t                    local Stream = Recording.SoundStream\n\t                    table.insert(Stream, (math.floor((os.clock() - Recording.Start) * 1000 + 0.5) / 1000))\n\t                    table.insert(Stream, GetPaletteIndex(Recording.SoundIds, SoundLookup, SoundId))\n\t                    table.insert(Stream, Position and (math.floor(Position.X * 100 + 0.5) / 100) or 0)\n\t                    table.insert(Stream, Position and (math.floor(Position.Y * 100 + 0.5) / 100) or 0)\n\t                    table.insert(Stream, Position and (math.floor(Position.Z * 100 + 0.5) / 100) or 0)\n\t                    table.insert(Stream, (math.floor((Settings.volumeMultiplier or 1) * 100 + 0.5) / 100))\n\t                    table.insert(Stream, Position and 1 or 0)\n\t                end\n\t                return OldPlaySound(self, SoundId, Config, ...)\n\t            end\n\t\n\t            ReplayMod:Clean(RunService.PostSimulation:Connect(function(Delta: number)\n\t                if not ReplayMod.Enabled or not Rate.Value then return end\n\t                if store.matchState ~= LastState then\n\t                    if store.matchState == 1 then\n\t                        StartRecording()\n\t                        Accumulator = 0\n\t                    end\n\t                    LastState = store.matchState\n\t                end\n\t\n\t                if Recording then\n\t                    if not Recording.World then\n\t                        SnapshotMap()\n\t                    end\n\t\n\t                    local Interval: number = 1 / Rate.Value\n\t                    Accumulator += Delta\n\t                    if Accumulator >= Interval then\n\t                        Accumulator %= Interval\n\t                        Sample()\n\t                    end\n\t                end\n\t\n\t            end))\n\t\n\t            local function Step(Delta: number)\n\t                if Playback and ReplayMod.Enabled and Speed.Value then\n\t                    if not Playback.Paused then\n\t                        Playback.Clock = math.clamp(Playback.Clock + Delta * Speed.Value, 0, Playback.Duration)\n\t                    end\n\t                    if UpdatePlayback(Playback.Clock) and not Playback.Paused then\n\t                        Playback.Paused = true\n\t                    end\n\t                    UpdateTimeline()\n\t                end\n\t            end\n\t\n\t            for _, v: string in {\"PreRender\", \"Heartbeat\", \"RenderStepped\", \"PreSimulation\"} do\n\t                ReplayMod:Clean(RunService[v]:Connect(function(Delta: number)\n\t                    if UpdateMode.Value == v then\n\t                        Step(Delta)\n\t                    end\n\t                end))\n\t            end\n\t\n\t            ReplayMod:Clean(vapeEvents.PlaceBlockEvent.Event:Connect(function(BlockTable)\n\t                local Position = BlockTable.blockRef and BlockTable.blockRef.blockPosition\n\t                local Block = Position and getPlacedBlock(Position * 3) or nil\n\t                RecordBlock(1, Position, Block and Block.Name or \"\")\n\t            end))\n\t\n\t            ReplayMod:Clean(vapeEvents.BreakBlockEvent.Event:Connect(function(BlockTable)\n\t                local Position = BlockTable.blockRef and BlockTable.blockRef.blockPosition\n\t                RecordBlock(0, Position, \"\")\n\t            end))\n\t\n\t            ReplayMod:Clean(vapeEvents.EntityDamageEvent.Event:Connect(function(DamageTable)\n\t                if type(DamageTable) ~= \"table\" then\n\t                    return\n\t                end\n\t\n\t                if not Recording or not DamageEffects.Enabled or DamageTable.disableDamageHighlight then\n\t                    return\n\t                end\n\t\n\t                local Character = DamageTable.entityInstance\n\t                if typeof(Character) ~= \"Instance\" then\n\t                    return\n\t                end\n\t\n\t                local Player: Player? = Players:GetPlayerFromCharacter(Character)\n\t                local Track = Recording.Tracks[Player and Player.Name or NpcNames[Character] or \"\"]\n\t                if not Track then\n\t                    return\n\t                end\n\t\n\t                Track.Hits = Track.Hits or {}\n\t                table.insert(Track.Hits, (math.floor((os.clock() - Recording.Start) * 1000 + 0.5) / 1000))\n\t                table.insert(Track.Hits, (math.floor((DamageTable.damage or 0) * 10 + 0.5) / 10))\n\t                table.insert(Track.Hits, GetPaletteIndex(Recording.DamageTypes, DamageLookup, tostring(DamageTable.damageType or \"\")))\n\t            end))\n\t\n\t            ReplayMod:Clean(vapeEvents.EntityDeathEvent.Event:Connect(function(DeathTable)\n\t                if type(DeathTable) ~= \"table\" then\n\t                    return\n\t                end\n\t\n\t                local Victim: string = DescribeEntity(DeathTable.entityInstance or DeathTable.entity)\n\t                local Killer: string = DescribeEntity(DeathTable.killerEntity or DeathTable.fromEntity or DeathTable.killer)\n\t                if Victim == \"\" then\n\t                    return\n\t                end\n\t\n\t                RecordEvent(Killer ~= \"\" and `{Killer} killed {Victim}` or `{Victim} died`)\n\t            end))\n\t\n\t            ReplayMod:Clean(vapeEvents.BedwarsBedBreak.Event:Connect(function(BedTable)\n\t                local Breaker: string = type(BedTable) == \"table\" and DescribeEntity(BedTable.player) or \"\"\n\t                RecordEvent(Breaker ~= \"\" and `{Breaker} broke a bed` or \"A bed was broken\")\n\t            end))\n\t\n\t            ReplayMod:Clean(vapeEvents.MatchEndEvent.Event:Connect(function()\n\t                if AutoSave.Enabled then\n\t                    local FileName: string = SaveRecording()\n\t                    if FileName then\n\t                        notif(\"ReplayMod\", `Saved {FileName}`, 8)\n\t                        RefreshList()\n\t                    end\n\t                    StartRecording()\n\t                end\n\t            end))\n\t        else\n\t            if OldPlaySound then\n\t                bedwars.AudioManager.playAudio = OldPlaySound\n\t                OldPlaySound = nil\n\t            end\n\t            ClearWatchers()\n\t            StopPlayback()\n\t            Recording = nil\n\t        end\n\t    end,\n\t    Tooltip = \"Records everyone's movement, animations, sounds, armor and held items, then replays the match back\"\n\t})\n\t\n\tRate = ReplayMod:CreateSlider({\n\t    Name = \"Sample rate\",\n\t    Min = 5,\n\t    Max = 60,\n\t    Default = 30,\n\t    Suffix = \"hz\",\n\t    Tooltip = \"Samples per second, higher is smoother but makes bigger files\"\n\t})\n\tAutoSave = ReplayMod:CreateToggle({\n\t    Name = \"Save on match end\",\n\t    Default = true\n\t})\n\tReplayMod:CreateButton({\n\t    Name = \"Save replay now\",\n\t    Function = function()\n\t        local FileName: string = SaveRecording()\n\t        if FileName then\n\t            notif(\"ReplayMod\", `Saved {FileName}`, 8)\n\t            RefreshList()\n\t        else\n\t            notif(\"ReplayMod\", \"Nothing recorded yet\", 5, \"alert\")\n\t        end\n\t    end\n\t})\n\tReplays = ReplayMod:CreateDropdown({\n\t    Name = \"Replay\",\n\t    List = {\"None\"}\n\t})\n\tSpeed = ReplayMod:CreateSlider({\n\t    Name = \"Playback speed\",\n\t    Min = 0.25,\n\t    Max = 4,\n\t    Decimal = 100,\n\t    Default = 1,\n\t    Suffix = \"x\"\n\t})\n\tAvatars = ReplayMod:CreateToggle({\n\t    Name = \"Load avatars\",\n\t    Default = true,\n\t    Tooltip = \"Rebuilds everyone as their blocky bedwars character, turn off for faster playback\"\n\t})\n\tInfoUI = ReplayMod:CreateToggle({\n\t    Name = \"Information UI\",\n\t    Function = function(Callback: boolean)\n\t        if not Playback then\n\t            return\n\t        end\n\t\n\t        for _, v: any in Playback.Rigs do\n\t            if v.Info then\n\t                v.Info.Enabled = Callback\n\t            end\n\t        end\n\t    end,\n\t    Tooltip = \"Shows the name, health bar and inventory above each entity\",\n\t    Default = true\n\t})\n\tGameHealthBar = ReplayMod:CreateToggle({\n\t    Name = \"Game health bar\",\n\t    Default = true,\n\t    Tooltip = \"Uses bedwars own health bar instead of the custom one\"\n\t})\n\tUpdateMode = ReplayMod:CreateDropdown({\n\t    Name = \"Update mode\",\n\t    List = {\"PreRender\", \"Heartbeat\", \"RenderStepped\", \"PreSimulation\"},\n\t    Tooltip = \"Which loop drives playback movement\"\n\t})\n\tEntities = ReplayMod:CreateToggle({\n\t    Name = \"Record entities\",\n\t    Default = true,\n\t    Tooltip = \"Also records NPCs and mobs, not just players\"\n\t})\n\tAnimations = ReplayMod:CreateToggle({\n\t    Name = \"Animations\",\n\t    Default = true,\n\t    Darker = true,\n\t    Tooltip = \"Records every animation the game plays on a player and replays it on their avatar\"\n\t})\n\tArmor = ReplayMod:CreateToggle({\n\t    Name = \"Armor\",\n\t    Default = true,\n\t    Darker = true,\n\t    Tooltip = \"Puts the armor everyone was wearing back onto their avatar\"\n\t})\n\tDamageEffects = ReplayMod:CreateToggle({\n\t    Name = \"Damage effects\",\n\t    Default = true,\n\t    Darker = true,\n\t    Tooltip = \"Records every hit and replays the red damage flash and damage numbers\"\n\t})\n\tSounds = ReplayMod:CreateToggle({\n\t    Name = \"Sounds\",\n\t    Function = function(Callback: boolean)\n\t        if SoundVolume then\n\t            SoundVolume.Object.Visible = Callback\n\t        end\n\t    end,\n\t    Tooltip = \"Records every positioned game sound and plays it back in the replay\",\n\t    Default = true\n\t})\n\tSoundVolume = ReplayMod:CreateSlider({\n\t    Name = \"Sound volume\",\n\t    Min = 0,\n\t    Max = 2,\n\t    Default = 1,\n\t    Decimal = 100,\n\t    Darker = true,\n\t    Suffix = \"x\"\n\t})\n\tFreeCam = ReplayMod:CreateToggle({\n\t    Name = \"Free camera\",\n\t    Function = function(Callback: boolean)\n\t        if not Callback then\n\t            StopFreecam()\n\t        elseif Playback then\n\t            StartFreecam()\n\t        end\n\t    end,\n\t    Tooltip = \"Unlocks your camera during playback, WASD to fly, Q and E for down and up, shift to go faster\",\n\t    Default = true\n\t})\n\tCameraSpeed = ReplayMod:CreateSlider({\n\t    Name = \"Camera speed\",\n\t    Min = 10,\n\t    Max = 250,\n\t    Default = 60,\n\t    Darker = true,\n\t    Suffix = \"studs\"\n\t})\n\tReplayMod:CreateSlider({\n\t    Name = \"Seek\",\n\t    Min = 0,\n\t    Max = 100,\n\t    Suffix = \"%\",\n\t    Function = SeekPlayback,\n\t    Tooltip = \"Jumps to a point in the replay while it is playing\",\n\t    Default = 0\n\t})\n\tReplayMod:CreateButton({\n\t    Name = \"Play replay\",\n\t    Function = StartPlayback\n\t})\n\tReplayMod:CreateButton({\n\t    Name = \"Stop playback\",\n\t    Function = StopPlayback\n\t})\n\tReplayMod:CreateButton({\n\t    Name = \"Refresh list\",\n\t    Function = function()\n\t        local List: {string} = RefreshList()\n\t        notif(\"ReplayMod\", `Found {List[1] == \"None\" and 0 or #List} replays`, 5)\n\t    end\n\t})\n\tReplayMod:CreateButton({\n\t    Name = \"Delete replay\",\n\t    Function = function()\n\t        local FileName: string = Replays.Value\n\t        local FilePath: string = `{ReplayFolder}/{FileName}`\n\t        if FileName ~= \"None\" and isfile(FilePath) then\n\t            delfile(FilePath)\n\t            notif(\"ReplayMod\", `Deleted {FileName}`, 5)\n\t            RefreshList()\n\t        end\n\t    end\n\t})\n\ttask.spawn(RefreshList)\nend)\n\nRun(function()\n\tlocal Scaffold\n\tlocal Expand\n\tlocal Tower\n\tlocal Downwards\n\tlocal Diagonal\n\tlocal LimitItem\n\tlocal Mouse\n\tlocal FillColor\n\tlocal OutlineColor\n\tlocal Adjacent, LastPosition, Label, VisualBlock = {}, Vector3.zero\n\tlocal VisualTween, VisualPosition\n\tlocal VisualSpeed: number = 0.1\n\t\n\tfor X: number = -3, 3, 3 do\n\t    for Y: number = -3, 3, 3 do\n\t        for Z: number = -3, 3, 3 do\n\t            local Offset: Vector3 = Vector3.new(X, Y, Z)\n\t            if Offset ~= Vector3.zero then\n\t                table.insert(Adjacent, Offset)\n\t            end\n\t        end\n\t    end\n\tend\n\t\n\tlocal function NearCorner(BlockPosition: Vector3, Position: Vector3): Vector3\n\t    local StartPosition: Vector3 = BlockPosition - Vector3.new(3, 3, 3)\n\t    local EndPosition: Vector3 = BlockPosition + Vector3.new(3, 3, 3)\n\t    local Check: Vector3 = BlockPosition + (Position - BlockPosition).Unit * 100\n\t    return Vector3.new(math.clamp(Check.X, StartPosition.X, EndPosition.X), math.clamp(Check.Y, StartPosition.Y, EndPosition.Y), math.clamp(Check.Z, StartPosition.Z, EndPosition.Z))\n\tend\n\tgetgenv().nearCorner = NearCorner\n\t\n\tlocal function BlockProximity(Position: Vector3): Vector3?\n\t    local Magnitude, Closest = 60\n\t    local Blocks = GetBlocksInPoints(bedwars.BlockController:getBlockPosition(Position - Vector3.new(21, 21, 21)), bedwars.BlockController:getBlockPosition(Position + Vector3.new(21, 21, 21)))\n\t    for _, v: Vector3 in Blocks do\n\t        local BlockPosition: Vector3 = NearCorner(v, Position)\n\t        local NewMagnitude: number = (Position - BlockPosition).Magnitude\n\t        if NewMagnitude < Magnitude then\n\t            Magnitude, Closest = NewMagnitude, BlockPosition\n\t        end\n\t    end\n\t    table.clear(Blocks)\n\t    return Closest\n\tend\n\tgetgenv().blockProximity = BlockProximity\n\t\n\tlocal function CheckAdjacent(Position: Vector3): boolean\n\t    for _, v: Vector3 in Adjacent do\n\t        if GetPlacedBlock(Position + v) then\n\t            return true\n\t        end\n\t    end\n\t    return false\n\tend\n\tgetgenv().checkAdjacent = CheckAdjacent\n\t\n\tlocal function GetScaffoldBlock()\n\t    if Store.hand.toolType == \"block\" then\n\t        return Store.hand.tool.Name, Store.hand.amount\n\t    elseif (not LimitItem.Enabled) then\n\t        local Wool, Amount = GetWool()\n\t        if Wool then\n\t            return Wool, Amount\n\t        else\n\t            for _, v: any in Store.inventory.inventory.items do\n\t                if bedwars.ItemMeta[v.itemType].block then\n\t                    return v.itemType, v.amount\n\t                end\n\t            end\n\t        end\n\t    end\n\t\n\t    return nil, 0\n\tend\n\t\n\tScaffold = vape.Categories.Utility:CreateModule({\n\t    Name = \"Scaffold\",\n\t    Function = function(Callback: boolean)\n\t        if Label then\n\t            if vape.ThreadFix then\n\t                setthreadidentity(8)\n\t            end\n\t\n\t            Label.Visible = Callback\n\t        end\n\t\n\t        if Callback then\n\t            repeat\n\t                if vape.ThreadFix then\n\t                    setthreadidentity(8)\n\t                end\n\t\n\t                if Entity.isAlive and not vape.MovementOwner then\n\t                    local Wool, Amount = GetScaffoldBlock()\n\t\n\t                    if Mouse.Enabled then\n\t                        if not UserInputService:IsMouseButtonPressed(0) then\n\t                            Wool = nil\n\t                        end\n\t                    end\n\t\n\t                    if Label then\n\t                        Amount = Amount or 0\n\t                        if vape.ThreadFix then\n\t                            setthreadidentity(8)\n\t                        end\n\t\n\t                        Label.Text = `{Amount} <font color=\"rgb(170, 170, 170)\">(Scaffold)</font>`\n\t                        Label.TextColor3 = Color3.fromHSV((Amount / 128) / 2.8, 0.86, 1)\n\t                    end\n\t\n\t                    if Wool then\n\t                        local Root: BasePart = Entity.character.RootPart\n\t                        if Tower.Enabled and UserInputService:IsKeyDown(Enum.KeyCode.Space) and (not UserInputService:GetFocusedTextBox()) then\n\t                            Root.AssemblyLinearVelocity = Vector3.new(Root.AssemblyLinearVelocity.X, 38, Root.AssemblyLinearVelocity.Z)\n\t                        end\n\t\n\t                        for Step: number = Expand.Value, 1, -1 do\n\t                            local CurrentPosition: Vector3 = RoundPosition(Root.Position - Vector3.new(0, Entity.character.HipHeight + (Downwards.Enabled and UserInputService:IsKeyDown(Enum.KeyCode.LeftShift) and 4.5 or 1.5), 0) + Entity.character.Humanoid.MoveDirection * (Step * 3))\n\t                            if Diagonal.Enabled then\n\t                                if math.abs(math.round(math.deg(math.atan2(-Entity.character.Humanoid.MoveDirection.X, -Entity.character.Humanoid.MoveDirection.Z)) / 45) * 45) % 90 == 45 then\n\t                                    local Delta: Vector3 = (LastPosition - CurrentPosition)\n\t                                    if ((Delta.X == 0 and Delta.Z ~= 0) or (Delta.X ~= 0 and Delta.Z == 0)) and ((LastPosition - Root.Position) * Vector3.new(1, 0, 1)).Magnitude < 2.5 then\n\t                                        CurrentPosition = LastPosition\n\t                                    end\n\t                                end\n\t                            end\n\t\n\t                            if VisualBlock and CurrentPosition then\n\t                                local VisualTarget: Vector3 = bedwars.BlockController:getBlockPosition(CurrentPosition) * 3\n\t                                if VisualPosition ~= VisualTarget then\n\t                                    if vape.ThreadFix then\n\t                                        setthreadidentity(8)\n\t                                    end\n\t\n\t                                    if VisualTween then\n\t                                        VisualTween:Cancel()\n\t                                        VisualTween = nil\n\t                                    end\n\t\n\t                                    if VisualBlock.Parent == Camera then\n\t                                        VisualTween = TweenService:Create(VisualBlock, TweenInfo.new(VisualSpeed, Enum.EasingStyle.Quad, Enum.EasingDirection.Out), {CFrame = CFrame.new(VisualTarget)})\n\t                                        VisualTween:Play()\n\t                                    else\n\t                                        VisualBlock.CFrame = CFrame.new(VisualTarget)\n\t                                        VisualBlock.Parent = Camera\n\t                                    end\n\t                                    VisualPosition = VisualTarget\n\t                                end\n\t                            end\n\t\n\t                            local Block, BlockPosition = GetPlacedBlock(CurrentPosition)\n\t                            if not Block then\n\t                                BlockPosition = CheckAdjacent(BlockPosition * 3) and BlockPosition * 3 or BlockProximity(CurrentPosition)\n\t                                if BlockPosition then\n\t                                    task.delay(0, bedwars.placeBlock, BlockPosition, Wool, false)\n\t                                end\n\t                            end\n\t                            LastPosition = CurrentPosition\n\t                        end\n\t                    end\n\t                end\n\t                task.wait(0.03)\n\t            until not Scaffold.Enabled\n\t            if VisualTween then\n\t                VisualTween:Cancel()\n\t                VisualTween = nil\n\t            end\n\t            if VisualBlock then\n\t                if vape.ThreadFix then\n\t                    setthreadidentity(8)\n\t                end\n\t\n\t                VisualBlock.Parent = nil\n\t            end\n\t            VisualPosition = nil\n\t        end\n\t    end,\n\t    Tooltip = \"Helps you make bridges/scaffold walk.\"\n\t})\n\t\n\tExpand = Scaffold:CreateSlider({\n\t    Name = \"Expand\",\n\t    Min = 1,\n\t    Max = 6\n\t})\n\tTower = Scaffold:CreateToggle({\n\t    Name = \"Tower\",\n\t    Default = true\n\t})\n\tDownwards = Scaffold:CreateToggle({\n\t    Name = \"Downwards\",\n\t    Default = true\n\t})\n\tDiagonal = Scaffold:CreateToggle({\n\t    Name = \"Diagonal\",\n\t    Default = true\n\t})\n\tLimitItem = Scaffold:CreateToggle({Name = \"Limit to items\"})\n\tMouse = Scaffold:CreateToggle({Name = \"Require mouse down\"})\n\tScaffold:CreateToggle({\n\t    Name = \"Visual\",\n\t    Function = function(Callback: boolean)\n\t        if vape.ThreadFix then\n\t            setthreadidentity(8)\n\t        end\n\t\n\t        FillColor.Object.Visible = Callback\n\t        OutlineColor.Object.Visible = Callback\n\t        if Callback then\n\t            if vape.ThreadFix then\n\t                setthreadidentity(8)\n\t            end\n\t\n\t            VisualBlock = Instance.new(\"Part\")\n\t            VisualBlock.Size = Vector3.new(3, 3, 3)\n\t            VisualBlock.Anchored = true\n\t            VisualBlock.CanCollide = false\n\t            VisualBlock.CanQuery = false\n\t            VisualBlock.CanTouch = false\n\t            VisualBlock.CastShadow = false\n\t            VisualBlock.Transparency = 1\n\t            if vape.ThreadFix then\n\t                setthreadidentity(8)\n\t            end\n\t\n\t            local Selection: SelectionBox = Instance.new(\"SelectionBox\")\n\t            Selection.Adornee = VisualBlock\n\t            Selection.LineThickness = 0.04\n\t            Selection.Color3 = Color3.fromHSV(OutlineColor.Hue, OutlineColor.Sat, OutlineColor.Value)\n\t            Selection.Transparency = 1 - OutlineColor.Opacity\n\t            Selection.SurfaceColor3 = Color3.fromHSV(FillColor.Hue, FillColor.Sat, FillColor.Value)\n\t            Selection.SurfaceTransparency = 1 - FillColor.Opacity\n\t            if vape.ThreadFix then\n\t                setthreadidentity(8)\n\t            end\n\t\n\t            Selection.Parent = VisualBlock\n\t            bedwars.QueryUtil:setQueryIgnored(VisualBlock, true)\n\t        else\n\t            if VisualTween then\n\t                VisualTween:Cancel()\n\t                VisualTween = nil\n\t            end\n\t            if VisualBlock then\n\t                if vape.ThreadFix then\n\t                    setthreadidentity(8)\n\t                end\n\t\n\t                VisualBlock.Parent = nil\n\t            end\n\t            VisualPosition = nil\n\t            if vape.ThreadFix then\n\t                setthreadidentity(8)\n\t            end\n\t\n\t            VisualBlock:Destroy()\n\t            VisualBlock = nil\n\t        end\n\t    end,\n\t    Tooltip = \"Renders an overlay on the block about to be placed\"\n\t})\n\tFillColor = Scaffold:CreateColorSlider({\n\t    Name = \"Fill Color\",\n\t    DefaultSat = 0,\n\t    DefaultOpacity = 0.4,\n\t    Darker = true,\n\t    Visible = false,\n\t    Function = function(Hue: number, Sat: number, Val: number, Opacity: number)\n\t        if VisualBlock then\n\t            if vape.ThreadFix then\n\t                setthreadidentity(8)\n\t            end\n\t\n\t            VisualBlock.SelectionBox.SurfaceColor3 = Color3.fromHSV(Hue, Sat, Val)\n\t            VisualBlock.SelectionBox.SurfaceTransparency = 1 - Opacity\n\t        end\n\t    end\n\t})\n\tOutlineColor = Scaffold:CreateColorSlider({\n\t    Name = \"Outline Color\",\n\t    DefaultValue = 0,\n\t    Darker = true,\n\t    Visible = false,\n\t    Function = function(Hue: number, Sat: number, Val: number, Opacity: number)\n\t        if VisualBlock then\n\t            if vape.ThreadFix then\n\t                setthreadidentity(8)\n\t            end\n\t\n\t            VisualBlock.SelectionBox.Color3 = Color3.fromHSV(Hue, Sat, Val)\n\t            VisualBlock.SelectionBox.Transparency = 1 - Opacity\n\t        end\n\t    end\n\t})\n\tScaffold:CreateToggle({\n\t    Name = \"Block Count\",\n\t    Function = function(Callback: boolean)\n\t        if Callback then\n\t            if vape.ThreadFix then\n\t                setthreadidentity(8)\n\t            end\n\t\n\t            Label = Instance.new(\"TextLabel\")\n\t            Label.Size = UDim2.fromOffset(100, 20)\n\t            Label.Position = UDim2.new(0.5, 6, 0.5, 60)\n\t            Label.BackgroundTransparency = 1\n\t            Label.AnchorPoint = Vector2.new(0.5, 0)\n\t            Label.Text = \"0\"\n\t            Label.TextColor3 = Color3.new(0, 1, 0)\n\t            Label.TextSize = 18\n\t            Label.RichText = true\n\t            Label.Font = Enum.Font.Arial\n\t            Label.Visible = Scaffold.Enabled\n\t            if vape.ThreadFix then\n\t                setthreadidentity(8)\n\t            end\n\t            Label.Parent = vape.gui\n\t        else\n\t            if vape.ThreadFix then\n\t                setthreadidentity(8)\n\t            end\n\t\n\t            Label:Destroy()\n\t            Label = nil\n\t        end\n\t    end\n\t})\n\t\nend)\n\nRun(function()\n\tlocal SetEmote\n\tlocal Emote\n\tlocal Track: AnimationTrack?\n\t\n\tlocal List, EmoteTypes = {}, {}\n\tfor EmoteType: any, v: any in bedwars.EmoteMeta do\n\t    if EmoteType ~= bedwars.EmoteType.NONE and v.name and not EmoteTypes[v.name] then\n\t        EmoteTypes[v.name] = EmoteType\n\t        table.insert(List, v.name)\n\t    end\n\tend\n\ttable.sort(List)\n\t\n\tlocal function CancelEmote()\n\t    if Entity.isAlive then\n\t        if Track then\n\t            Track:Stop()\n\t            Track:Destroy()\n\t            Track = nil\n\t        end\n\t        if LocalPlayer.Character:GetAttribute(\"PlayingEmote\") then\n\t            LocalPlayer.Character:SetAttribute(\"PlayingEmote\", nil)\n\t        end\n\t    end\n\tend\n\t\n\tSetEmote = vape.Categories.Utility:CreateModule({\n\t    Name = \"SetEmote\",\n\t    Function = function(Callback: boolean)\n\t        if Callback then\n\t            SetEmote:Toggle()\n\t            if Entity.isAlive then\n\t                local EmoteType = EmoteTypes[Emote.Value]\n\t                local Meta = bedwars.EmoteMeta[EmoteType]\n\t                if Meta then\n\t                    LocalPlayer.Character:SetAttribute(\"PlayingEmote\", EmoteType)\n\t                    local PlayBeginSounds = bedwars.EmoteController.createEmoteBeginAudioPlayers or bedwars.EmoteController.playEmoteBeginSounds\n\t                    if PlayBeginSounds then\n\t                        PlayBeginSounds(bedwars.EmoteController, EmoteType, LocalPlayer)\n\t                    end\n\t                    local Animation = Meta.animation\n\t                    if not Animation and Meta.emoteDisplayType then\n\t                        local Display = bedwars.EmoteDisplayMeta[Meta.emoteDisplayType]\n\t                        Animation = Display and Display.animation\n\t                    end\n\t                    if Animation and not noAutoPlayAnimation then\n\t                        Track = LocalPlayer.Character.Humanoid:LoadAnimation(bedwars.GameAnimationUtil:getAnimation(Animation.type))\n\t                        Track.Looped = Animation.looped or false\n\t                        Track:Play(nil, nil, Animation.speed or 1)\n\t                    end\n\t                    if not Meta.animation then\n\t                        local Gui: BillboardGui = Instance.new(\"BillboardGui\")\n\t                        Gui.Size = UDim2.fromScale(6, 2.5)\n\t                        Gui.StudsOffset = Vector3.new(0, 2, 0)\n\t                        Gui.AlwaysOnTop = true\n\t                        Gui.Adornee = LocalPlayer.Character.Head\n\t\n\t                        local Image: ImageLabel = Instance.new(\"ImageLabel\")\n\t                        Image.AnchorPoint = Vector2.new(0.5, 1)\n\t                        Image.Position = UDim2.fromScale(0.5, 1)\n\t                        Image.Size = UDim2.fromScale(0, 0)\n\t                        Image.Image = Meta.image\n\t                        Image.BackgroundTransparency = 1\n\t                        Image.ImageTransparency = 1\n\t                        Image.ScaleType = Enum.ScaleType.Fit\n\t                        Image.Parent = Gui\n\t\n\t                        Gui.Parent = LocalPlayer.Character.Head\n\t                        TweenService:Create(Image, TweenInfo.new(0.4, Enum.EasingStyle.Exponential, Enum.EasingDirection.Out), {\n\t                            Position = UDim2.fromScale(0.5, 0.5),\n\t                            Size = UDim2.fromScale(1, 1),\n\t                            ImageTransparency = 0\n\t                        }):Play()\n\t                    end\n\t                    if Meta.allowMovement then\n\t                        task.delay(6, CancelEmote)\n\t                    else\n\t                        LocalPlayer.Character.Humanoid:GetPropertyChangedSignal(\"MoveDirection\"):Once(CancelEmote)\n\t                    end\n\t                end\n\t            end\n\t        end\n\t    end,\n\t    Tooltip = \"Plays the selected emote on your character, other players can see it too\"\n\t})\n\t\n\tEmote = SetEmote:CreateDropdown({\n\t    Name = \"Emote\",\n\t    List = List,\n\t    Default = \"nightmare\"\n\t})\nend)\n\nRun(function()\n\tlocal ShopQuickBuy\n\tlocal HoldDelay\n\tlocal CPS\n\t\n\tlocal Holding: boolean = false\n\tlocal ClickThread: thread?\n\t\n\tlocal function GetShopId()\n\t    if not Entity.isAlive then\n\t        return nil\n\t    end\n\t    local LocalPosition: Vector3 = Entity.character.RootPart.Position\n\t    local Id\n\t    for _, v: any in Store.shop do\n\t        if v.Shop and (v.RootPart.Position - LocalPosition).Magnitude <= 20 then\n\t            Id = v.Id\n\t        end\n\t    end\n\t    return Id\n\tend\n\t\n\tlocal function GetHoveredItem(): string?\n\t    local MousePosition: Vector2 = (UserInputService:GetMouseLocation() - GuiService:GetGuiInset())\n\t    for _, v: GuiObject in LocalPlayer.PlayerGui:GetGuiObjectsAtPosition(MousePosition.X, MousePosition.Y) do\n\t        local Object: Instance? = v\n\t        while Object and Object ~= LocalPlayer.PlayerGui do\n\t            local ItemType: string? = Object.Name:match(\"^(.+)_ShopItemCard$\")\n\t            if ItemType then\n\t                return ItemType\n\t            end\n\t            Object = Object.Parent\n\t        end\n\t    end\n\tend\n\t\n\tlocal function StartClicking(ItemType: string)\n\t    if ClickThread then\n\t        task.cancel(ClickThread)\n\t    end\n\t    ClickThread = task.spawn(function()\n\t        repeat\n\t            local ShopId = bedwars.AppController:isAppOpen(\"BedwarsItemShopApp\") and Store.shopLoaded and GetShopId()\n\t            if ShopId and bedwars.BedwarsShopController.alreadyPurchasedMap[ItemType] == nil then\n\t                local Item = bedwars.Shop.getShopItem(ItemType, LocalPlayer, {shopId = ShopId})\n\t                local Currency = Item and GetItem(Item.currency)\n\t                local Buyable = Item and not (Item.ignoredByKit and table.find(Item.ignoredByKit, Store.equippedKit or \"\")) and not Item.lockedByForge and not Item.disabled and (Currency and Currency.amount or 0) >= Item.price\n\t                if Buyable and Item.require and Item.require.teamUpgrade and (bedwars.Store:getState().Bedwars.teamUpgrades[Item.require.teamUpgrade.upgradeId] or -1) < Item.require.teamUpgrade.lowestTierIndex then\n\t                    Buyable = false\n\t                end\n\t\n\t                if Buyable then\n\t                    bedwars.Handler:Get(\"BedwarsPurchaseItem\"):Fire(\"CallServerAsync\", {\n\t                        shopItem = Item,\n\t                        shopId = ShopId\n\t                    }):andThen(function(Success)\n\t                        if not Success then\n\t                            return\n\t                        end\n\t                        bedwars.AudioManager:playAudio(bedwars.SoundList.BEDWARS_PURCHASE_ITEM)\n\t                        bedwars.Store:dispatch({\n\t                            type = \"BedwarsAddItemPurchased\",\n\t                            itemType = ItemType\n\t                        })\n\t                        if Item.tiered then\n\t                            bedwars.BedwarsShopController.alreadyPurchasedMap[ItemType] = true\n\t                        end\n\t                    end)\n\t                end\n\t            end\n\t            task.wait(1 / CPS.Value)\n\t        until not Holding\n\t        ClickThread = nil\n\t    end)\n\tend\n\t\n\tShopQuickBuy = vape.Categories.Utility:CreateModule({\n\t    Name = \"ShopClicker\",\n\t    Function = function(Callback: boolean)\n\t        if Callback then\n\t            ShopQuickBuy:Clean(UserInputService.InputBegan:Connect(function(Input: InputObject)\n\t                if Input.UserInputType ~= Enum.UserInputType.MouseButton1 then\n\t                    return\n\t                end\n\t                if not bedwars.AppController:isAppOpen(\"BedwarsItemShopApp\") then\n\t                    return\n\t                end\n\t\n\t                local ItemType: string? = GetHoveredItem()\n\t                if not ItemType then\n\t                    return\n\t                end\n\t\n\t                Holding = true\n\t                task.delay(HoldDelay.Value, function()\n\t                    if Holding and GetHoveredItem() == ItemType then\n\t                        StartClicking(ItemType)\n\t                    end\n\t                end)\n\t            end))\n\t\n\t            ShopQuickBuy:Clean(UserInputService.InputEnded:Connect(function(Input: InputObject)\n\t                if Input.UserInputType == Enum.UserInputType.MouseButton1 then\n\t                    Holding = false\n\t                end\n\t            end))\n\t        else\n\t            Holding = false\n\t            if ClickThread then\n\t                task.cancel(ClickThread)\n\t                ClickThread = nil\n\t            end\n\t        end\n\t    end,\n\t    Tooltip = \"Hold on a shop item to rapidly buy it.\"\n\t})\n\t\n\tHoldDelay = ShopQuickBuy:CreateSlider({\n\t    Name = \"Hold Delay\",\n\t    Min = 0,\n\t    Max = 1,\n\t    Default = 0.15,\n\t    Decimal = 20,\n\t    Suffix = \"seconds\"\n\t})\n\tCPS = ShopQuickBuy:CreateSlider({\n\t    Name = \"CPS\",\n\t    Min = 1,\n\t    Max = 20,\n\t    Default = 20,\n\t    Darker = true\n\t})\nend)\n\nRun(function()\n\tlocal StaffDetector\n\tlocal Mode\n\tlocal Clans\n\tlocal Profile\n\tlocal Users\n\tlocal BlacklistedClans: {string} = {\"gg\", \"gg2\", \"DV\", \"DV2\"}\n\tlocal BlacklistedUserIds: {number} = {1502104539, 3826146717, 4531785383, 1049767300, 4926350670, 653085195, 184655415, 2752307430, 5087196317, 5744061325, 1536265275}\n\tlocal Joined, Rejoins, JoinTimes = {}, {}, {}\n\tlocal Watchers: {[Player]: RBXScriptConnection} = {}\n\tlocal Counts: {[string]: number} = {Spectate = 0, Mod = 0, Impossible = 0}\n\tlocal FlagColors: {[string]: string} = {Spectate = \"rgb(236,129,43)\", Mod = \"rgb(250,50,56)\", Impossible = \"rgb(180,90,250)\"}\n\tlocal Entries = {}\n\tlocal Window, InfoLabel, Expanded\n\t\n\tlocal function RefreshViewer()\n\t    if not Window then\n\t        return\n\t    end\n\t\n\t    local ShowList = Expanded and #Entries > 0\n\t    local Lines: {string} = {\"<b>StaffDetector</b>\", '<font size=\"4\"> </font>'}\n\t    for _, v: string in {\"Spectate\", \"Mod\", \"Impossible\"} do\n\t        table.insert(Lines, `<font color=\"{FlagColors[v]}\">{v}: {Counts[v]}</font>`)\n\t    end\n\t\n\t    if ShowList then\n\t        table.insert(Lines, '<font size=\"4\"> </font>')\n\t        for i: number, v: {Name: string, Reason: string, Category: string} in Entries do\n\t            if i > 8 then\n\t                break\n\t            end\n\t            table.insert(Lines, `{v.Name} <font color=\"{FlagColors[v.Category]}\">{v.Reason}</font>`)\n\t        end\n\t    end\n\t\n\t    InfoLabel.Text = table.concat(Lines, \"\\n\")\n\t    local Bounds: Vector2 = GetFontBounds(RemoveTags(InfoLabel.Text), InfoLabel.TextSize, InfoLabel.FontFace)\n\t    local TitleBounds: Vector2 = GetFontBounds(\"StaffDetector\", InfoLabel.TextSize, Font.new(InfoLabel.FontFace.Family, Enum.FontWeight.Bold))\n\t    Window.Size = UDim2.fromOffset(math.max(Bounds.X, TitleBounds.X) + 16, Bounds.Y + (ShowList and -8 or 4))\n\tend\n\t\n\tlocal function StaffFunction(Player: Player, CheckType: string)\n\t    if not vape.Loaded then\n\t        repeat task.wait() until vape.Loaded\n\t    end\n\t\n\t    SendNotification(\"StaffDetector\", `Staff Detected ({CheckType}): {Player.Name} ({Player.UserId})`, 60, \"alert\")\n\t    Whitelist.customtags[Player.Name] = {{text = \"GAME STAFF\", color = Color3.new(1, 0, 0)}}\n\t    local Category: string = CheckType == \"impossible_join\" and \"Impossible\" or CheckType == \"spectator\" and \"Spectate\" or \"Mod\"\n\t    Counts[Category] += 1\n\t    table.insert(Entries, 1, {Name = Player.Name, Reason = CheckType, Category = Category})\n\t    RefreshViewer()\n\t\n\t    if Mode.Value == \"Uninject\" then\n\t        task.spawn(function()\n\t            vape:Uninject()\n\t        end)\n\t        game:GetService(\"StarterGui\"):SetCore(\"SendNotification\", {\n\t            Title = \"StaffDetector\",\n\t            Text = `Staff Detected ({CheckType})\\n{Player.Name} ({Player.UserId})`,\n\t            Duration = 60,\n\t        })\n\t    elseif Mode.Value == \"Requeue\" then\n\t        bedwars.QueueController:joinQueue(Store.queueType)\n\t    elseif Mode.Value == \"Profile\" then\n\t        vape.Save = function() end\n\t        if vape.Profile ~= Profile.Value then\n\t            vape:Load(true, Profile.Value)\n\t        end\n\t    elseif Mode.Value == \"AutoConfig\" then\n\t        local SafeModules: {string} = {\"AutoClicker\", \"Reach\", \"Sprint\", \"HitFix\", \"StaffDetector\"}\n\t        vape.Save = function() end\n\t        for ModuleName: string, v: any in vape.Modules do\n\t            if not (table.find(SafeModules, ModuleName) or v.Category == \"Render\") then\n\t                if v.Enabled then\n\t                    v:Toggle()\n\t                end\n\t                v:SetBind(\"\")\n\t            end\n\t        end\n\t    end\n\tend\n\t\n\tlocal function NoteSpectator(Player: Player, Reason: string)\n\t    SendNotification(\"StaffDetector\", `Spectator {Player.Name} joined {Reason}`, 20, \"warning\")\n\t    Counts.Spectate += 1\n\t    table.insert(Entries, 1, {Name = Player.Name, Reason = \"spectator\", Category = \"Spectate\"})\n\t    RefreshViewer()\n\tend\n\t\n\tlocal function CheckJoin(Player: Player, Connection: RBXScriptConnection)\n\t    if Player:GetAttribute(\"Team\") or not Player:GetAttribute(\"Spectator\") or Store.matchState ~= 1 or bedwars.Store:getState().Game.customMatch or (tick() - (JoinTimes[Player.UserId] or 0)) > 20 then\n\t        return\n\t    end\n\t\n\t    Connection:Disconnect()\n\t    task.wait(5)\n\t    if (not StaffDetector.Enabled) or Player.Parent ~= Players or Player:GetAttribute(\"Team\") or not Player:GetAttribute(\"Spectator\") then\n\t        return\n\t    end\n\t\n\t    if Rejoins[Player.UserId] then\n\t        NoteSpectator(Player, \"back after leaving\")\n\t        return\n\t    end\n\t\n\t    if Player.FollowUserId ~= 0 and Joined[Player.FollowUserId] then\n\t        NoteSpectator(Player, `following {Joined[Player.FollowUserId]}`)\n\t        return\n\t    end\n\t\n\t    local Success, Pages = pcall(Players.GetFriendsAsync, Players, Player.UserId)\n\t    if not Success then\n\t        return\n\t    end\n\t\n\t    local Friend, Finished = nil, Pages.IsFinished\n\t    for _ = 1, 6 do\n\t        for _, v: any in Pages:GetCurrentPage() do\n\t            if Joined[v.Id] then\n\t                Friend = Joined[v.Id]\n\t                break\n\t            end\n\t        end\n\t        if Friend or Finished then\n\t            break\n\t        end\n\t        if not pcall(Pages.AdvanceToNextPageAsync, Pages) then\n\t            return\n\t        end\n\t        Finished = Pages.IsFinished\n\t    end\n\t\n\t    if Friend then\n\t        NoteSpectator(Player, `from {Friend}`)\n\t    elseif Finished then\n\t        StaffFunction(Player, \"impossible_join\")\n\t        return true\n\t    end\n\tend\n\t\n\tlocal function Added(Player: Player)\n\t    if Joined[Player.UserId] then\n\t        Rejoins[Player.UserId] = true\n\t    end\n\t    Joined[Player.UserId] = Player.Name\n\t    local Teleported = Player:GetAttribute(\"LastTeleported\")\n\t    JoinTimes[Player.UserId] = Teleported and (tick() - math.min(workspace:GetServerTimeNow() - Teleported, 60)) or tick()\n\t    if Player == LocalPlayer then\n\t        return\n\t    end\n\t\n\t    if table.find(BlacklistedUserIds, Player.UserId) or table.find(Users.ListEnabled, tostring(Player.UserId)) then\n\t        StaffFunction(Player, \"blacklisted_user\")\n\t    else\n\t        local Success, Response = pcall(function()\n\t            return Player:GetRankInGroup(5774246)\n\t        end)\n\t        if not Success then\n\t            SendNotification(\"StaffDetector\", Response, 30, \"alert\")\n\t        end\n\t\n\t        if (Success and Response or 0) >= 100 then\n\t            StaffFunction(Player, \"staff_role\")\n\t        else\n\t            local Connection: RBXScriptConnection\n\t            Connection = Player:GetAttributeChangedSignal(\"Spectator\"):Connect(function()\n\t                CheckJoin(Player, Connection)\n\t            end)\n\t            Watchers[Player] = Connection\n\t            StaffDetector:Clean(Connection)\n\t            if CheckJoin(Player, Connection) then\n\t                return\n\t            end\n\t\n\t            if not Player:GetAttribute(\"ClanTag\") then\n\t                Player:GetAttributeChangedSignal(\"ClanTag\"):Wait()\n\t            end\n\t\n\t            if table.find(BlacklistedClans, Player:GetAttribute(\"ClanTag\")) and vape.Loaded and Clans.Enabled then\n\t                Connection:Disconnect()\n\t                StaffFunction(Player, `blacklisted_clan_{Player:GetAttribute(\"ClanTag\"):lower()}`)\n\t            end\n\t        end\n\t    end\n\tend\n\t\n\tStaffDetector = vape.Categories.Utility:CreateModule({\n\t    Name = \"StaffDetector\",\n\t    Function = function(Callback: boolean)\n\t        if Callback then\n\t            StaffDetector:Clean(Players.PlayerAdded:Connect(Added))\n\t            StaffDetector:Clean(Players.PlayerRemoving:Connect(function(Player: Player)\n\t                local Connection: RBXScriptConnection? = Watchers[Player]\n\t                if Connection then\n\t                    Connection:Disconnect()\n\t                    Watchers[Player] = nil\n\t                end\n\t            end))\n\t            for _, v: Player in Players:GetPlayers() do\n\t                task.spawn(Added, v)\n\t            end\n\t        else\n\t            table.clear(Joined)\n\t            table.clear(Rejoins)\n\t            table.clear(JoinTimes)\n\t            table.clear(Watchers)\n\t        end\n\t    end,\n\t    Tooltip = \"Detects people with a staff rank ingame\"\n\t})\n\t\n\tMode = StaffDetector:CreateDropdown({\n\t    Name = \"Mode\",\n\t    List = {\"Uninject\", \"Profile\", \"Requeue\", \"AutoConfig\", \"Notify\"},\n\t    Function = function(Val: string)\n\t        if Profile.Object then\n\t            Profile.Object.Visible = Val == \"Profile\"\n\t        end\n\t    end\n\t})\n\tClans = StaffDetector:CreateToggle({\n\t    Name = \"Blacklist clans\",\n\t    Default = true\n\t})\n\tProfile = StaffDetector:CreateTextBox({\n\t    Name = \"Profile\",\n\t    Default = \"default\",\n\t    Darker = true,\n\t    Visible = false\n\t})\n\tUsers = StaffDetector:CreateTextList({\n\t    Name = \"Users\",\n\t    Placeholder = \"player (userid)\"\n\t})\n\tStaffDetector:CreateToggle({\n\t    Name = \"Viewer\",\n\t    Function = function(Callback: boolean)\n\t        if Callback and not Window then\n\t            Window = Instance.new(\"TextButton\")\n\t            Window.Name = \"StaffDetectorViewer\"\n\t            Window.Position = UDim2.fromOffset(12, 120)\n\t            Window.BackgroundColor3 = Color3.new()\n\t            Window.BackgroundTransparency = 0.5\n\t            Window.Text = \"\"\n\t            Window.AutoButtonColor = false\n\t            if vape.ThreadFix then\n\t                setthreadidentity(8)\n\t            end\n\t            Window.Parent = vape.gui.ScaledGui\n\t            AddBlur(Window)\n\t            local Corner: UICorner = Instance.new(\"UICorner\")\n\t            Corner.CornerRadius = UDim.new(0, 5)\n\t            Corner.Parent = Window\n\t\n\t            InfoLabel = Instance.new(\"TextLabel\")\n\t            InfoLabel.Size = UDim2.new(1, -16, 1, -16)\n\t            InfoLabel.Position = UDim2.fromOffset(8, 8)\n\t            InfoLabel.BackgroundTransparency = 1\n\t            InfoLabel.TextXAlignment = Enum.TextXAlignment.Left\n\t            InfoLabel.TextYAlignment = Enum.TextYAlignment.Top\n\t            InfoLabel.TextSize = 16\n\t            InfoLabel.TextColor3 = Color3.new(1, 1, 1)\n\t            InfoLabel.TextStrokeColor3 = Color3.new()\n\t            InfoLabel.TextStrokeTransparency = 0.8\n\t            InfoLabel.Font = Enum.Font.Arial\n\t            InfoLabel.RichText = true\n\t            InfoLabel.Parent = Window\n\t            StaffDetector:AddHUD(Window)\n\t\n\t            local PressPosition: UDim2? = nil\n\t            Window.MouseButton1Down:Connect(function()\n\t                PressPosition = Window.Position\n\t            end)\n\t\n\t            Window.MouseButton1Click:Connect(function()\n\t                if PressPosition == Window.Position then\n\t                    Expanded = not Expanded\n\t                    RefreshViewer()\n\t                end\n\t            end)\n\t        end\n\t\n\t        if Window then\n\t            Window.Visible = Callback\n\t            RefreshViewer()\n\t        end\n\t    end,\n\t    Tooltip = \"Shows a panel with detection counts, click it to list who tripped them and drag it while the GUI is open to move it\"\n\t})\n\ttask.spawn(function()\n\t    repeat task.wait(1) until vape.Loaded or vape.Loaded == nil\n\t    if vape.Loaded and StaffDetector.Toggle and not StaffDetector.Enabled then\n\t        StaffDetector:Toggle()\n\t    end\n\tend)\nend)\n\nRun(function()\n\tTrapDisabler = vape.Categories.Utility:CreateModule({\n\t    Name = \"TrapDisabler\",\n\t    Tooltip = \"Drops the reports the game makes you send when you walk into a trap\"\n\t})\n\t\n\tTrapSnap = TrapDisabler:CreateToggle({\n\t    Name = \"Snap traps\",\n\t    Default = true,\n\t    Tooltip = \"Stops trapper snap traps from marking you\"\n\t})\n\tTrapMine = TrapDisabler:CreateToggle({\n\t    Name = \"Landmines\",\n\t    Default = true,\n\t    Tooltip = \"Stops invisible landmines from detonating on you\"\n\t})\n\tTrapTeleport = TrapDisabler:CreateToggle({\n\t    Name = \"Teleport blocks\",\n\t    Tooltip = \"Stops teleport blocks from moving you\"\n\t})\n\tTrapPortal = TrapDisabler:CreateToggle({\n\t    Name = \"Void portals\",\n\t    Tooltip = \"Stops void portals from moving you, this also blocks your own\"\n\t})\nend)\n\nRun(function()\n\tlocal AntiAFK\n\t\n\tAntiAFK = vape.Categories.World:CreateModule({\n\t    Name = \"Anti-AFK\",\n\t    Function = function(Callback: boolean)\n\t        if Callback then\n\t            if not canDebug then\n\t                local VirtualUser: VirtualUser = game:GetService(\"VirtualUser\")\n\t                AntiAFK:Clean(LocalPlayer.Idled:Connect(function()\n\t                    VirtualUser:CaptureController()\n\t                    VirtualUser:ClickButton2(Vector2.zero)\n\t                end))\n\t                AntiAFK:Clean(task.spawn(function()\n\t                    repeat\n\t                        bedwars.Handler:Get(\"AfkInfo\"):Fire(\"SendToServer\", {afk = false})\n\t                        task.wait(30)\n\t                    until not AntiAFK.Enabled\n\t                end))\n\t                return\n\t            end\n\t\n\t            for _, v: any in getconnections(LocalPlayer.Idled) do\n\t                v:Disconnect()\n\t            end\n\t\n\t            for _, v: any in getconnections(RunService.Heartbeat) do\n\t                if type(v.Function) == \"function\" and table.find(debug.getconstants(v.Function), \"AfkInfo\") then\n\t                    v:Disconnect()\n\t                end\n\t            end\n\t\n\t            bedwars.Handler:Get(\"AfkInfo\"):Fire(\"SendToServer\", {\n\t                afk = false\n\t            })\n\t        end\n\t    end,\n\t    Tooltip = \"Lets you stay ingame without getting kicked\"\n\t})\nend)\n\nRun(function()\n\tlocal AutoTool\n\tlocal Mode\n\tlocal Delay = {}\n\tlocal SwitchBack\n\tlocal BreakEvent\n\tlocal Looking, Deadline, Previous, Switching = nil, 0, nil, false\n\t\n\tlocal function IsMining(): boolean\n\t    local Mining = Store.breakTool\n\t    return Mining ~= nil and Mining.expires > tick() and not (Mining.session and Mining.session.Cancelled)\n\tend\n\t\n\tlocal function GetToolSlot(Block)\n\t    if IsMining() or not Block or Block:GetAttribute(\"NoBreak\") or Block:GetAttribute(`Team{LocalPlayer:GetAttribute(\"Team\") or 0}NoBreak`) then\n\t        return\n\t    end\n\t\n\t    local Meta = bedwars.ItemMeta[Block.Name]\n\t    local Tool = Meta and Meta.block and Store.tools[Meta.block.breakType]\n\t    if not Tool or (Store.hand and Store.hand.tool == Tool.tool) then\n\t        return\n\t    end\n\t\n\t    for i: number, v: any in Store.inventory.hotbar do\n\t        if v.item and v.item.itemType == Tool.itemType then\n\t            return i - 1\n\t        end\n\t    end\n\t    return\n\tend\n\t\n\tlocal function GetTargetBlock(): Instance?\n\t    if not canDebug then\n\t        return vape.Libraries.cheatengine.BlockTarget.GetBlock()\n\t    end\n\t\n\t    local Placer = Store.blockPlacer or (bedwars.BlockPlacementController and bedwars.BlockPlacementController.blockPlacer)\n\t    local Selector = Placer and Placer.clientManager and Placer.clientManager:getBlockSelector()\n\t    local Info = Selector and Selector:getMouseInfo(1, {ray = not UserInputService.KeyboardEnabled and Camera:ScreenPointToRay(Camera.ViewportSize.X / 2, Camera.ViewportSize.Y / 2 - GuiService:GetGuiInset().Y) or nil})\n\t    return Info and Info.target and Info.target.blockInstance or nil\n\tend\n\t\n\tlocal function SwitchTo(Slot: number)\n\t    if Switching then\n\t        return\n\t    end\n\t\n\t    Switching = true\n\t    task.spawn(function()\n\t        if not IsMining() then\n\t            HotbarSwitch(Slot)\n\t        end\n\t        Switching = false\n\t    end)\n\tend\n\t\n\tAutoTool = vape.Categories.World:CreateModule({\n\t    Name = \"AutoTool\",\n\t    Function = function(Callback: boolean)\n\t        if Callback then\n\t            Looking, Deadline, Previous, Switching = nil, 0, nil, false\n\t\n\t            local Event: BindableEvent = Instance.new(\"BindableEvent\")\n\t            BreakEvent = Event\n\t            AutoTool:Clean(Event)\n\t            AutoTool:Clean(Event.Event:Connect(function()\n\t                ContextActionService:CallFunction(\"block-break\", Enum.UserInputState.Begin, newproxy(true))\n\t            end))\n\t\n\t            AutoTool:Clean(RunService.Heartbeat:Connect(function()\n\t                if not Entity.isAlive or IsMining() then\n\t                    return\n\t                end\n\t                if Mode.Value ~= \"Look\" and (canDebug or not UserInputService:IsMouseButtonPressed(Enum.UserInputType.MouseButton1)) then\n\t                    Looking = nil\n\t                    return\n\t                end\n\t\n\t                local HeldMeta = Store.hand.tool and bedwars.ItemMeta[Store.hand.tool.Name]\n\t                if not (HeldMeta and HeldMeta.breakBlock) then\n\t                    Looking, Previous = nil, nil\n\t                    return\n\t                end\n\t\n\t                local Block = GetTargetBlock()\n\t                if not Block then\n\t                    Looking = nil\n\t                    if Mode.Value == \"Look\" and SwitchBack.Enabled and Previous then\n\t                        SwitchTo(Previous)\n\t                        Previous = nil\n\t                    end\n\t                    return\n\t                end\n\t\n\t                if Block ~= Looking then\n\t                    Looking, Deadline = Block, tick() + (Mode.Value == \"Look\" and Delay:GetRandomValue() or 0)\n\t                    return\n\t                end\n\t                if tick() < Deadline then\n\t                    return\n\t                end\n\t\n\t                local Slot = GetToolSlot(Block)\n\t                if Slot then\n\t                    Previous = Previous or (Store.hand.tool and GetHotbar(Store.hand.tool) or nil)\n\t                    SwitchTo(Slot)\n\t                end\n\t            end))\n\t\n\t            bedwars.BlockBreakCallbacks.AutoTool = function(self, Maid, MouseRay, ...)\n\t                if Mode.Value == \"Break\" then\n\t                    local Info = self.clientManager:getBlockSelector():getMouseInfo(1, {ray = MouseRay})\n\t                    local Slot = GetToolSlot(Info and Info.target and Info.target.blockInstance or nil)\n\t                    if Slot then\n\t                        task.spawn(function()\n\t                            if not AutoTool.Enabled or BreakEvent ~= Event or IsMining() then return end\n\t                            if HotbarSwitch(Slot) and AutoTool.Enabled and BreakEvent == Event and UserInputService:IsMouseButtonPressed(0) then\n\t                                Event:Fire()\n\t                            end\n\t                        end)\n\t                    end\n\t                end\n\t            end\n\t        else\n\t            Looking, Previous = nil, nil\n\t            bedwars.BlockBreakCallbacks.AutoTool = nil\n\t            BreakEvent = nil\n\t        end\n\t    end,\n\t    Tooltip = \"Automatically selects the correct tool\"\n\t})\n\t\n\tMode = AutoTool:CreateDropdown({\n\t    Name = \"Mode\",\n\t    List = {\"Look\", \"Break\"},\n\t    Function = function(Val: string)\n\t        if Delay.Object then\n\t            Delay.Object.Visible = Val == \"Look\"\n\t            SwitchBack.Object.Visible = Val == \"Look\"\n\t        end\n\t    end,\n\t    Default = \"Break\",\n\t    Tooltip = \"Look swaps while you are still aiming at the block, Break swaps on the first hit like it used to\"\n\t})\n\tDelay = AutoTool:CreateTwoSlider({\n\t    Name = \"Delay\",\n\t    Min = 0,\n\t    Max = 1,\n\t    Decimal = 100,\n\t    DefaultMin = 0.06,\n\t    DefaultMax = 0.16,\n\t    Darker = true,\n\t    Suffix = \"seconds\",\n\t    Tooltip = \"How long you have to be looking at the block before it swaps\"\n\t})\n\tSwitchBack = AutoTool:CreateToggle({\n\t    Name = \"Switch back\",\n\t    Darker = true,\n\t    Tooltip = \"Puts the item you were holding back once you look away\"\n\t})\nend)\n\nRun(function()\n\tlocal BedAssist\n\tlocal AimMode\n\tlocal Speed\n\tlocal Range\n\tlocal Angle\n\tlocal Shake\n\tlocal Mode\n\tlocal Limit\n\tlocal AutoMine\n\tlocal MineBed\n\tlocal Started, NextSearch = 0, 0\n\tlocal Target, TargetBed, TargetPosition\n\tlocal OldHit, HitBlock, Session, Pending\n\tlocal Generator: Random = Random.new()\n\tlocal Sides: {Vector3} = {Vector3.xAxis, -Vector3.xAxis, Vector3.yAxis, -Vector3.yAxis, Vector3.zAxis, -Vector3.zAxis}\n\tlocal Points: {Vector3} = {Vector3.zero, Vector3.xAxis * 1.35, -Vector3.xAxis * 1.35, Vector3.yAxis * 1.35, -Vector3.yAxis * 1.35, Vector3.zAxis * 1.35, -Vector3.zAxis * 1.35}\n\tlocal RayParams: RaycastParams = RaycastParams.new()\n\tRayParams.FilterType = Enum.RaycastFilterType.Exclude\n\t\n\tlocal function GetAim(Block, Position: Vector3, Direction: Vector3)\n\t    for _, v: Vector3 in Points do\n\t        if Block.Name == \"bed\" and (v == Vector3.zero or GetPlacedBlock(Position + v.Unit * 3)) then\n\t            continue\n\t        end\n\t        local Aim: Vector3 = Position + v\n\t        local Offset: Vector3 = Aim - Camera.CFrame.Position\n\t        if Offset.Magnitude > 0.001 and Offset.Unit:Dot(Direction) >= math.cos(math.rad(Angle.Value)) then\n\t            local Hit: RaycastResult? = bedwars.QueryUtil:raycast(Camera.CFrame.Position, Offset.Unit * (Offset.Magnitude + 3), RayParams)\n\t            if Hit and (Hit.Instance == Block or Hit.Instance:IsDescendantOf(Block)) then\n\t                if Block.Name == \"bed\" then\n\t                    local Handler = bedwars.BlockController:getHandlerRegistry():getHandler(\"bed\")\n\t                    local Closest, Distance = nil, math.huge\n\t                    for _, Cell: Vector3 in Handler:getContainedPositions(Block) do\n\t                        local Magnitude: number = (Cell * 3 - (Hit.Position - Hit.Normal * 0.1)).Magnitude\n\t                        if Magnitude < Distance then\n\t                            Closest, Distance = Cell * 3, Magnitude\n\t                        end\n\t                    end\n\t                    if Closest ~= Position then\n\t                        continue\n\t                    end\n\t                end\n\t                return Hit.Position\n\t            end\n\t        end\n\t    end\n\t    return nil\n\tend\n\t\n\tlocal function GetBestPosition(Bed: BasePart, Direction: Vector3)\n\t    local Handler = bedwars.BlockController:getHandlerRegistry():getHandler(Bed.Name)\n\t    local Positions = Handler and Handler:getContainedPositions(Bed) or {bedwars.BlockController:getBlockPosition(Bed.Position)}\n\t    local Queue, Distances, Depths, Visited = {}, {}, {}, {}\n\t    local LocalPosition: Vector3 = Entity.character.RootPart.Position\n\t    local BlockStore = bedwars.BlockController:getStore()\n\t    local Cost, Depth, Distance, Magnitude = math.huge, math.huge, math.huge, math.huge\n\t    local Block, Position\n\t    for _, v: Vector3 in Positions do\n\t        if BlockStore:getBlockAt(v) == Bed then\n\t            Distances[v], Depths[v] = 0, 0\n\t            table.insert(Queue, {position = v, cost = 0, depth = 0})\n\t        end\n\t    end\n\t\n\t    for _ = 1, 512 do\n\t        local BestIndex, Node\n\t        for i: number, v: {position: Vector3, cost: number, depth: number} in Queue do\n\t            if not Node or v.cost < Node.cost or v.cost == Node.cost and v.depth < Node.depth then\n\t                BestIndex, Node = i, v\n\t            end\n\t        end\n\t        if not Node or Node.cost > Cost then\n\t            break\n\t        end\n\t        table.remove(Queue, BestIndex)\n\t        if Visited[Node.position] then\n\t            continue\n\t        end\n\t        Visited[Node.position] = true\n\t        local Current = BlockStore:getBlockAt(Node.position)\n\t        local WorldPosition: Vector3 = Node.position * 3\n\t        local NodeMagnitude: number = (LocalPosition - WorldPosition).Magnitude\n\t        local NodeDistance: number = math.huge\n\t        for _, v: Vector3 in Positions do\n\t            NodeDistance = math.min(NodeDistance, (Node.position - v).Magnitude)\n\t        end\n\t        if Current and NodeMagnitude <= math.min(Range.Value, bedwars.BlockBreaker:getRange()) then\n\t            local Point = GetAim(Current, WorldPosition, Direction)\n\t            if Point and (Node.cost < Cost or Node.depth < Depth or Node.depth == Depth and (NodeDistance < Distance or NodeDistance == Distance and ((Current == Target and Block ~= Target) or (Current == Target) == (Block == Target) and NodeMagnitude < Magnitude))) then\n\t                Block, Position = Current, WorldPosition\n\t                Cost, Depth, Distance, Magnitude = Node.cost, Node.depth, NodeDistance, NodeMagnitude\n\t            end\n\t        end\n\t\n\t        for _, v: Vector3 in Sides do\n\t            local NextPosition: Vector3 = Node.position + v\n\t            if Visited[NextPosition] or (NextPosition * 3 - Bed.Position).Magnitude > 18 then\n\t                continue\n\t            end\n\t            local NextBlock = BlockStore:getBlockAt(NextPosition)\n\t            local Meta = NextBlock and bedwars.ItemMeta[NextBlock.Name]\n\t            if not Meta or not Meta.block or NextBlock:GetAttribute(\"NoBreak\") or NextBlock:GetAttribute(`Team{LocalPlayer:GetAttribute(\"Team\") or -1}NoBreak`) or not bedwars.BlockController:isBlockBreakable({blockPosition = NextPosition}, LocalPlayer) then\n\t                continue\n\t            end\n\t            local Data = BlockStore:getBlockData(NextPosition)\n\t            local Health = Data and Data:GetAttribute(bedwars.BlockBreaker.blockHealthbar:getHealthKey(NextBlock)) or NextBlock:GetAttribute(\"Health\") or Meta.block.health\n\t            local Damage = bedwars.BlockController:calculateBlockDamage(LocalPlayer, {blockPosition = NextPosition})\n\t            if Damage <= 0 then\n\t                continue\n\t            end\n\t            local Hits: number = Node.cost + math.max(math.ceil((Health or 10) / Damage), 1)\n\t            local Steps: number = Node.depth + 1\n\t            if Hits < (Distances[NextPosition] or math.huge) or Hits == Distances[NextPosition] and Steps < Depths[NextPosition] then\n\t                Distances[NextPosition], Depths[NextPosition] = Hits, Steps\n\t                table.insert(Queue, {position = NextPosition, cost = Hits, depth = Steps})\n\t            end\n\t        end\n\t    end\n\t    return Block, Position, Cost, Depth, Magnitude\n\tend\n\t\n\tBedAssist = vape.Categories.World:CreateModule({\n\t    Name = \"BedAssist\",\n\t    Function = function(Callback: boolean)\n\t        if Callback then\n\t            local Current = {}\n\t            Session, Pending = Current, nil\n\t            local Beds = Collection(\"bed\", BedAssist)\n\t            local Maid = getmetatable(bedwars.BlockBreaker.maid).new()\n\t            BedAssist:Clean(function()\n\t                Maid:DoCleaning()\n\t            end)\n\t            OldHit = bedwars.BlockBreaker.hitBlock\n\t            HitBlock = function(self, Cleanup, MouseRay, ...)\n\t                local Info = self.clientManager:getBlockSelector():getMouseInfo(1, {ray = MouseRay, range = math.min(Range.Value, self:getRange())})\n\t                local Selected = Info and Info.target\n\t                if Session ~= Current or not MineBed.Enabled or not Selected or Selected.blockInstance.Name ~= \"bed\" then\n\t                    return OldHit(self, Cleanup, MouseRay, ...)\n\t                end\n\t                if Pending and tick() - Pending.sent < math.max(1, LocalPlayer:GetNetworkPing() * 4 + 0.5) or not Entity.isAlive or Store.matchState ~= 1 or LocalPlayer:GetAttribute(\"DenyBlockBreak\") or tick() - self.lastHitTime < self:getCooldown() or not bedwars.BlockController:isBlockBreakable(Selected.blockRef, LocalPlayer) then\n\t                    return\n\t                end\n\t                local Block = Selected.blockInstance\n\t                if Block:GetAttribute(`Team{LocalPlayer:GetAttribute(\"Team\") or -1}NoBreak`) or (Block:GetAttribute(\"BedShieldEndTime\") or 0) > workspace:GetServerTimeNow() then\n\t                    return\n\t                end\n\t                local Data = bedwars.BlockController:getStore():getBlockData(Selected.blockRef.blockPosition)\n\t                local HealthKey: string = self.blockHealthbar:getHealthKey(Block)\n\t                local Before: number = Data and Data:GetAttribute(HealthKey) or Block:GetAttribute(\"Health\")\n\t                local Request = {sent = tick()}\n\t                Pending = Request\n\t                self.lastHitTime = tick()\n\t                Store.lastHit = self.lastHitTime\n\t                for _, Function: (...any) -> () in bedwars.BlockBreakCallbacks do\n\t                    Function(self, Cleanup, MouseRay, ...)\n\t                end\n\t                local Animation = bedwars.AnimationUtil:playAnimation(LocalPlayer, bedwars.BlockController:getAnimationController():getAssetId(1))\n\t                if Animation then\n\t                    Cleanup:GiveTask(function()\n\t                        Animation:Stop()\n\t                        Animation:Destroy()\n\t                    end)\n\t                end\n\t                self.onBreak:Fire()\n\t                bedwars.ClientDamageBlock:Get(\"DamageBlock\"):CallServerAsync({\n\t                    blockRef = Selected.blockRef,\n\t                    hitPosition = Selected.hitPosition,\n\t                    hitNormal = Selected.hitNormal\n\t                }):andThen(function(Result)\n\t                    if Session ~= Current then return end\n\t                    if Result == \"destroyed\" then\n\t                        self.blockHealthbar:destroy()\n\t                        self.breakTextureHandler:removeTexture(Selected.blockRef)\n\t                        if bedwars.BlockController:getStore():getBlockAt(Selected.blockRef.blockPosition) == Block then\n\t                            bedwars.BlockController:destroyBlock(Selected.blockRef)\n\t                        end\n\t                        self.breakEffect:playBreak(Block.Name, Selected.blockRef.blockPosition, LocalPlayer)\n\t                    elseif Result == \"damaged\" then\n\t                        local After: number = Data and Data:GetAttribute(HealthKey) or Block:GetAttribute(\"Health\")\n\t                        self:updateHealthbar(Selected.blockRef, Before, Block:GetAttribute(\"MaxHealth\"), math.max(Before - After, 0), Block)\n\t                        self.breakEffect:playHit(Block.Name, Selected.blockRef.blockPosition, LocalPlayer)\n\t                    end\n\t                    NextSearch = 0\n\t                end):catch(function()\n\t                    if Session == Current then NextSearch = 0 end\n\t                end):finally(function()\n\t                    if Pending == Request then Pending = nil end\n\t                end)\n\t                return nil\n\t            end\n\t            bedwars.BlockBreaker.hitBlock = HitBlock\n\t\n\t            BedAssist:Clean(RunService.PostSimulation:Connect(function(DeltaTime: number)\n\t                local HeldMeta = Store.hand.tool and bedwars.ItemMeta[Store.hand.tool.Name]\n\t                if not Entity.isAlive or Store.matchState ~= 1 or LocalPlayer:GetAttribute(\"Spectator\") or LocalPlayer:GetAttribute(\"DenyBlockBreak\") or UserInputService:GetFocusedTextBox() or GuiService.MenuIsOpen or bedwars.AppController:isLayerOpen(bedwars.UILayers.MAIN) or Limit.Enabled and not (HeldMeta and HeldMeta.breakBlock) then\n\t                    Target, TargetBed, TargetPosition, NextSearch = nil, nil, nil, 0\n\t                    return\n\t                end\n\t\n\t                local MouseLocation: Vector2 = UserInputService.MouseEnabled and UserInputService:GetMouseLocation() or Camera.ViewportSize / 2\n\t                local MouseRay: Ray = Camera:ViewportPointToRay(MouseLocation.X, MouseLocation.Y)\n\t                RayParams.FilterDescendantsInstances = {LocalPlayer.Character, Camera}\n\t                if tick() >= NextSearch or Target and not Target.Parent then\n\t                    local Block, Bed, Position\n\t                    local Cost, Depth, Distance = math.huge, math.huge, math.huge\n\t                    for _, v: BasePart in Beds do\n\t                        if not v.Parent or v:GetAttribute(`Team{LocalPlayer:GetAttribute(\"Team\") or -1}NoBreak`) or (v:GetAttribute(\"BedShieldEndTime\") or 0) > workspace:GetServerTimeNow() or (v.Position - Entity.character.RootPart.Position).Magnitude > Range.Value + 3 or not bedwars.BlockController:isBlockBreakable({blockPosition = bedwars.BlockController:getBlockPosition(v.Position)}, LocalPlayer) then\n\t                            continue\n\t                        end\n\t                        local BedBlock, BedPosition, BedCost, BedDepth, BedMagnitude = GetBestPosition(v, MouseRay.Direction)\n\t                        if BedBlock and (BedCost < Cost or BedCost == Cost and (BedDepth < Depth or BedDepth == Depth and BedMagnitude < Distance)) then\n\t                            Block, Bed, Position, Cost, Depth, Distance = BedBlock, v, BedPosition, BedCost, BedDepth, BedMagnitude\n\t                        end\n\t                    end\n\t                    if Block ~= Target then\n\t                        Started = tick()\n\t                    end\n\t                    Target, TargetBed, TargetPosition, NextSearch = Block, Bed, Position, tick() + 0.15\n\t                end\n\t\n\t                if not Target or not Target.Parent or not TargetBed.Parent or TargetBed:GetAttribute(`Team{LocalPlayer:GetAttribute(\"Team\") or -1}NoBreak`) or (TargetBed:GetAttribute(\"BedShieldEndTime\") or 0) > workspace:GetServerTimeNow() or Target == TargetBed and not MineBed.Enabled or (Entity.character.RootPart.Position - TargetPosition).Magnitude > math.min(Range.Value, bedwars.BlockBreaker:getRange()) then\n\t                    return\n\t                end\n\t                local AimPosition = GetAim(Target, TargetPosition, MouseRay.Direction)\n\t                if not AimPosition then\n\t                    return\n\t                end\n\t                local AimSpeed: number = Speed.Value\n\t                if AimMode.Value == \"Adaptive\" then\n\t                    local Progress: number = math.clamp((tick() - Started) * AimSpeed * 0.5, 0, 1)\n\t                    AimSpeed *= Progress < 0.5 and 4 * Progress ^ 3 or 1 - (-2 * Progress + 2) ^ 3 / 2\n\t                end\n\t                local Alpha: number = 1 - math.exp(-AimSpeed * DeltaTime)\n\t                local Aim: Vector3 = AimPosition + Vector3.new(Generator:NextNumber(-1, 1), Generator:NextNumber(-1, 1), Generator:NextNumber(-1, 1)) * Shake.Value * 0.005\n\t                if Mode.Value == \"Mouse\" then\n\t                    local Screen, Visible = Camera:WorldToViewportPoint(Aim)\n\t                    if Visible then\n\t                        local Delta: Vector2 = (Vector2.new(Screen.X, Screen.Y) - MouseLocation) * Alpha\n\t                        mousemoverel(Delta.X, Delta.Y)\n\t                    end\n\t                else\n\t                    local Direction: Vector3 = (Aim - MouseRay.Origin).Unit\n\t                    local Axis: Vector3 = MouseRay.Direction:Cross(Direction)\n\t                    if Axis.Magnitude > 0.0001 then\n\t                        local Rotation: CFrame = CFrame.fromAxisAngle(Axis.Unit, math.acos(math.clamp(MouseRay.Direction:Dot(Direction), -1, 1)) * Alpha)\n\t                        Camera.CFrame = CFrame.new(Camera.CFrame.Position) * Rotation * Camera.CFrame.Rotation\n\t                    end\n\t                end\n\t\n\t                if AutoMine.Enabled and not UserInputService:IsMouseButtonPressed(Enum.UserInputType.MouseButton1) and tick() - bedwars.BlockBreaker.lastHitTime >= bedwars.BlockBreaker:getCooldown() then\n\t                    MouseRay = Camera:ViewportPointToRay(MouseLocation.X, MouseLocation.Y)\n\t                    local Info = bedwars.BlockBreaker.clientManager:getBlockSelector():getMouseInfo(1, {ray = MouseRay, range = math.min(Range.Value, bedwars.BlockBreaker:getRange())})\n\t                    if Info and Info.target and Info.target.blockInstance == Target then\n\t                        Maid:DoCleaning()\n\t                        bedwars.BlockBreaker:hitBlock(Maid, MouseRay)\n\t                    end\n\t                end\n\t            end))\n\t        else\n\t            if bedwars.BlockBreaker.hitBlock == HitBlock then\n\t                bedwars.BlockBreaker.hitBlock = OldHit\n\t            end\n\t            Session, Pending = nil, nil\n\t            Target, TargetBed, TargetPosition, NextSearch = nil, nil, nil, 0\n\t        end\n\t    end,\n\t    Tooltip = \"Smoothly aims and mines the weakest visible route into an enemy bed using normal reach and mining speed\"\n\t})\n\t\n\tAimMode = BedAssist:CreateDropdown({\n\t    Name = \"Mode\",\n\t    List = {\"Simple\", \"Adaptive\"},\n\t    Default = \"Simple\"\n\t})\n\tlocal AimModes: {string} = {\"Camera\"}\n\tif UserInputService.MouseEnabled and mousemoverel then\n\t    table.insert(AimModes, \"Mouse\")\n\tend\n\tMode = BedAssist:CreateDropdown({\n\t    Name = \"Aim mode\",\n\t    List = AimModes,\n\t    Default = \"Camera\"\n\t})\n\tSpeed = BedAssist:CreateSlider({\n\t    Name = \"Aim speed\",\n\t    Min = 1,\n\t    Max = 20,\n\t    Default = 7\n\t})\n\tRange = BedAssist:CreateSlider({\n\t    Name = \"Range\",\n\t    Min = 1,\n\t    Max = 30,\n\t    Default = 18,\n\t    Suffix = function(Val: number)\n\t        return Val <= 1 and \"stud\" or \"studs\"\n\t    end,\n\t    Tooltip = \"Never exceeds the game's normal mining reach\"\n\t})\n\tAngle = BedAssist:CreateSlider({\n\t    Name = \"View angle\",\n\t    Min = 5,\n\t    Max = 180,\n\t    Default = 60,\n\t    Suffix = \"degrees\",\n\t    Tooltip = \"Maximum angle away from your crosshair, 180 allows every direction\"\n\t})\n\tShake = BedAssist:CreateSlider({\n\t    Name = \"Shake\",\n\t    Min = 0,\n\t    Max = 100,\n\t    Default = 3\n\t})\n\tLimit = BedAssist:CreateToggle({Name = \"Limit to item\", Default = true})\n\tAutoMine = BedAssist:CreateToggle({\n\t    Name = \"Auto mine\",\n\t    Default = true,\n\t    Tooltip = \"Mines only when your crosshair reaches the chosen block; disable for aim assistance only\"\n\t})\n\tMineBed = BedAssist:CreateToggle({\n\t    Name = \"Mine bed\",\n\t    Default = true,\n\t    Tooltip = \"Mines the bed as soon as it is visible; disable to stop once the defense is open\"\n\t})\nend)\n\nRun(function()\n\tlocal BedPatcher\n\tlocal Mode\n\tlocal Whitelist\n\tlocal PlaceRange\n\tlocal Radius\n\tlocal Wool\n\tlocal Switch\n\tlocal NoAnimation\n\tlocal Limit\n\tlocal Layout, Adjacent = {}, {}\n\tlocal PlaceAnimation = bedwars.BlockController:getAnimationController():getAssetId(0)\n\tlocal Placing, Old = false\n\t\n\tfor _, v: EnumItem in Enum.NormalId:GetEnumItems() do\n\t    table.insert(Adjacent, Vector3.FromNormalId(v) * 3)\n\tend\n\t\n\tlocal function GetBedNear()\n\t    local LocalPosition: Vector3 = Entity.isAlive and Entity.character.RootPart.Position or Vector3.zero\n\t    for _, v: BasePart in CollectionService:GetTagged(\"bed\") do\n\t        if (LocalPosition - v.Position).Magnitude < (PlaceRange.Value + Radius.Value) and v:GetAttribute(`Team{LocalPlayer:GetAttribute(\"Team\") or -1}NoBreak`) then\n\t            return v\n\t        end\n\t    end\n\t    return nil\n\tend\n\t\n\tlocal function GetBlock(ItemType: string?)\n\t    if Limit.Enabled then\n\t        local Hand = Store.hand.toolType == \"block\" and Store.hand.tool\n\t        if Hand and (not Wool.Enabled or Hand.Name:find(\"wool\")) and table.find(Whitelist.ListEnabled, Hand.Name:find(\"wool\") and \"wool\" or Hand.Name) then\n\t            return Hand.Name, Hand\n\t        end\n\t        return nil\n\t    end\n\t\n\t    local Best, Health\n\t    for _, v: any in Store.inventory.inventory.items do\n\t        local Block = bedwars.ItemMeta[v.itemType].block\n\t        if not Block or (Wool.Enabled and not v.itemType:find(\"wool\")) then\n\t            continue\n\t        end\n\t        if not table.find(Whitelist.ListEnabled, v.itemType:find(\"wool\") and \"wool\" or v.itemType) then\n\t            continue\n\t        end\n\t        if v.itemType == ItemType then\n\t            return v.itemType, v.tool\n\t        end\n\t        if not Health or (Block.health or 0) > Health then\n\t            Best, Health = v, Block.health or 0\n\t        end\n\t    end\n\t    return Best and Best.itemType or nil, Best and Best.tool or nil\n\tend\n\t\n\tlocal function ScanBed(Bed: BasePart)\n\t    table.clear(Layout)\n\t    for _, v: BasePart in Store.blocks do\n\t        if not v:HasTag(\"bed\") and (v.Position - Bed.Position).Magnitude <= Radius.Value then\n\t            Layout[v.Position] = v.Name\n\t        end\n\t    end\n\t\n\t    local Holes = {}\n\t    for Position: Vector3, v: string in Layout do\n\t        for _, Offset: Vector3 in Adjacent do\n\t            local Cell: Vector3 = Position + Offset\n\t            if Layout[Cell] or Holes[Cell] or GetPlacedBlock(Cell) then\n\t                continue\n\t            end\n\t\n\t            local Walls: number = 0\n\t            for _, Side: Vector3 in Adjacent do\n\t                if Layout[Cell + Side] then\n\t                    Walls += 1\n\t                end\n\t            end\n\t\n\t            if Walls >= 4 then\n\t                Holes[Cell] = v\n\t            end\n\t        end\n\t    end\n\t\n\t    for Position: Vector3, v: string in Holes do\n\t        Layout[Position] = v\n\t    end\n\tend\n\t\n\tBedPatcher = vape.Categories.World:CreateModule({\n\t    Name = \"BedPatcher\",\n\t    Function = function(Callback: boolean)\n\t        if Callback then\n\t            local Bed\n\t            Old = bedwars.AnimationUtil.playAnimation\n\t            bedwars.AnimationUtil.playAnimation = function(self, Player, AssetId, Config)\n\t                if Placing and NoAnimation.Enabled and AssetId == PlaceAnimation then\n\t                    return\n\t                end\n\t                return Old(self, Player, AssetId, Config)\n\t            end\n\t\n\t            BedPatcher:Clean(CollectionService:GetInstanceAddedSignal(\"block\"):Connect(function(Block)\n\t                if Bed and not Block:HasTag(\"bed\") and (Block.Position - Bed.Position).Magnitude <= Radius.Value then\n\t                    Layout[Block.Position] = Block.Name\n\t                end\n\t            end))\n\t\n\t            BedPatcher:Clean(VapeEvents.BreakBlockEvent.Event:Connect(function(BlockTable)\n\t                local Player = BlockTable.player\n\t                if Player and (Player == LocalPlayer or Player:GetAttribute(\"Team\") == LocalPlayer:GetAttribute(\"Team\")) then\n\t                    Layout[BlockTable.blockRef.blockPosition * 3] = nil\n\t                end\n\t            end))\n\t\n\t            repeat\n\t                local Found = GetBedNear()\n\t                if Found ~= Bed then\n\t                    Bed = Found\n\t                    if Bed then\n\t                        ScanBed(Bed)\n\t                    else\n\t                        table.clear(Layout)\n\t                    end\n\t                end\n\t\n\t                if Bed and Entity.isAlive then\n\t                    local LocalPosition: Vector3 = Entity.character.RootPart.Position\n\t                    local Holes = {}\n\t\n\t                    for Position: Vector3, v: string in Layout do\n\t                        if (LocalPosition - Position).Magnitude <= PlaceRange.Value and not GetPlacedBlock(Position) then\n\t                            table.insert(Holes, {Position, v})\n\t                        end\n\t                    end\n\t\n\t                    table.sort(Holes, function(A, B): boolean\n\t                        return (A[1] - Bed.Position).Magnitude < (B[1] - Bed.Position).Magnitude\n\t                    end)\n\t\n\t                    for _, v: {any} in Holes do\n\t                        local Position, ItemType = unpack(v)\n\t                        if GetPlacedBlock(Position) then\n\t                            continue\n\t                        end\n\t\n\t                        local Item, Tool = GetBlock(ItemType)\n\t                        if not Item then\n\t                            break\n\t                        end\n\t\n\t                        if Switch.Enabled and GetHotbar(Tool) and HotbarSwitch(GetHotbar(Tool)) then\n\t                            task.wait()\n\t                        end\n\t\n\t                        Placing = true\n\t                        bedwars.placeBlock(Position, Item)\n\t                        Placing = false\n\t                        task.wait(1 / bedwars.SharedConstants.BLOCK_PLACE_CPS)\n\t                    end\n\t                elseif not Bed and Mode.Value == \"On Key\" then\n\t                    SendNotification(\"BedPatcher\", \"Unable to locate bed\", 5)\n\t                    BedPatcher:Toggle()\n\t                    break\n\t                end\n\t\n\t                task.wait(0.5)\n\t                if Mode.Value == \"On Key\" then\n\t                    BedPatcher:Toggle()\n\t                    break\n\t                end\n\t            until not BedPatcher.Enabled\n\t        else\n\t            bedwars.AnimationUtil.playAnimation = Old\n\t            Placing = false\n\t        end\n\t    end,\n\t    Tooltip = \"Puts back the blocks an enemy broke out of your bed defense.\"\n\t})\n\t\n\tMode = BedPatcher:CreateDropdown({\n\t    Name = \"Mode\",\n\t    List = {\"Toggle\", \"On Key\"},\n\t    Default = \"Toggle\"\n\t})\n\tWhitelist = BedPatcher:CreateTextList({\n\t    Name = \"Whitelist\",\n\t    Default = {\"wool\", \"obsidian\"}\n\t})\n\tPlaceRange = BedPatcher:CreateSlider({\n\t    Name = \"Place Range\",\n\t    Min = 1,\n\t    Max = 60,\n\t    Default = 15\n\t})\n\tRadius = BedPatcher:CreateSlider({\n\t    Name = \"Defense Radius\",\n\t    Min = 3,\n\t    Max = 30,\n\t    Default = 15,\n\t    Suffix = function(Val: number)\n\t        return Val == 1 and \"stud\" or \"studs\"\n\t    end,\n\t    Tooltip = \"How far out from the bed still counts as your defense\"\n\t})\n\tWool = BedPatcher:CreateToggle({Name = \"Wool only\", Tooltip = \"Only uses wools to patch.\"})\n\tSwitch = BedPatcher:CreateToggle({Name = \"Auto Switch\"})\n\tNoAnimation = BedPatcher:CreateToggle({\n\t    Name = \"No Animation\",\n\t    Tooltip = \"Hides the arm swing every patched block would otherwise play\"\n\t})\n\tLimit = BedPatcher:CreateToggle({Name = \"Limit to item\"})\nend)\n\nRun(function()\n\tlocal BedPlates\n\tlocal Background\n\tlocal Color\n\tlocal LayerCounter\n\tlocal LayerColor\n\tlocal Reference = {}\n\tlocal Shown: {[BillboardGui]: string} = setmetatable({}, {__mode = \"k\"})\n\tlocal Folder: Folder = Instance.new(\"Folder\")\n\tif vape.ThreadFix then\n\t    setthreadidentity(8)\n\tend\n\tFolder.Parent = vape.gui\n\t\n\tlocal function GetBlockLayerHealth(Block: string): number\n\t    local Meta = bedwars.ItemMeta[Block]\n\t    return Meta and Meta.block and Meta.block.health or 0\n\tend\n\t\n\tlocal function ScanSide(self, Start: Vector3, Layers)\n\t    for _, v: Vector3 in Sides do\n\t        local Found = {}\n\t        for Depth: number = 1, 15 do\n\t            local Block = GetPlacedBlock(Start + (v * Depth))\n\t            if not Block or Block == self or Block.Name == \"bed\" then\n\t                break\n\t            end\n\t            if not Block:GetAttribute(\"NoBreak\") then\n\t                Found[Block.Name] = (Found[Block.Name] or 0) + 1\n\t            end\n\t        end\n\t\n\t        for Name: string, Count: number in Found do\n\t            Layers[Name] = math.max(Layers[Name] or 0, Count)\n\t        end\n\t    end\n\tend\n\t\n\tlocal function RefreshAdornee(Billboard: BillboardGui)\n\t    local Start: Vector3 = Billboard.Adornee.Position\n\t    local Layers = {}\n\t    local AlreadyGot = {}\n\t    ScanSide(Billboard.Adornee, Start, Layers)\n\t    ScanSide(Billboard.Adornee, Start + Vector3.new(0, 0, 3), Layers)\n\t    for Name: string, Count: number in Layers do\n\t        table.insert(AlreadyGot, {Name, Count})\n\t    end\n\t    table.sort(AlreadyGot, function(A, B): boolean\n\t        local HealthA, HealthB = GetBlockLayerHealth(A[1]), GetBlockLayerHealth(B[1])\n\t        return HealthA == HealthB and A[1] < B[1] or HealthA > HealthB\n\t    end)\n\t    Billboard.Enabled = #AlreadyGot > 0\n\t\n\t    local Key: {string} = {tostring(not LayerCounter or LayerCounter.Enabled)}\n\t    for _, v: {any} in AlreadyGot do\n\t        table.insert(Key, `{v[1]}:{v[2]}`)\n\t    end\n\t    local LayerKey: string = table.concat(Key, \",\")\n\t    if Shown[Billboard] == LayerKey then return end\n\t    Shown[Billboard] = LayerKey\n\t\n\t    for _, v: Instance in Billboard.Frame:GetChildren() do\n\t        if v:IsA(\"ImageLabel\") and v.Name ~= \"Blur\" then\n\t            v:Destroy()\n\t        end\n\t    end\n\t\n\t    for _, v: {any} in AlreadyGot do\n\t        local Block, Amount = v[1], v[2]\n\t        local BlockImage: ImageLabel = Instance.new(\"ImageLabel\")\n\t        BlockImage.Size = UDim2.fromOffset(32, 32)\n\t        BlockImage.BackgroundTransparency = 1\n\t        BlockImage.Image = bedwars.getIcon({itemType = Block}, true)\n\t        BlockImage.Parent = Billboard.Frame\n\t        if Amount > 1 and (not LayerCounter or LayerCounter.Enabled) then\n\t            local AmountText: TextLabel = Instance.new(\"TextLabel\")\n\t            AmountText.Name = \"Amount\"\n\t            AmountText.Size = UDim2.fromScale(1, 1)\n\t            AmountText.BackgroundTransparency = 1\n\t            AmountText.Text = tostring(Amount)\n\t            AmountText.TextColor3 = (LayerColor and Color3.fromHSV(LayerColor.Hue, LayerColor.Sat, LayerColor.Value) or Color3.new(1, 1, 1))\n\t            AmountText.TextSize = 16\n\t            AmountText.TextStrokeTransparency = 0.3\n\t            AmountText.Font = Enum.Font.Arial\n\t            AmountText.Parent = BlockImage\n\t        end\n\t    end\n\tend\n\t\n\tlocal function Added(Bed: BasePart)\n\t    if Reference[Bed] then return end\n\t\n\t    local Billboard: BillboardGui = Instance.new(\"BillboardGui\")\n\t    Billboard.Parent = Folder\n\t    Billboard.Name = \"bed\"\n\t    Billboard.StudsOffsetWorldSpace = Vector3.new(0, 3, 0)\n\t    Billboard.Size = UDim2.fromOffset(36, 36)\n\t    Billboard.AlwaysOnTop = true\n\t    Billboard.ClipsDescendants = false\n\t    Billboard.Adornee = Bed\n\t    local Blur: ImageLabel = AddBlur(Billboard)\n\t    Blur.Visible = Background.Enabled\n\t    local Frame: Frame = Instance.new(\"Frame\")\n\t    Frame.Size = UDim2.fromScale(1, 1)\n\t    Frame.BackgroundColor3 = Color3.fromHSV(Color.Hue, Color.Sat, Color.Value)\n\t    Frame.BackgroundTransparency = 1 - (Background.Enabled and Color.Opacity or 0)\n\t    Frame.Parent = Billboard\n\t    local Layout: UIListLayout = Instance.new(\"UIListLayout\")\n\t    Layout.FillDirection = Enum.FillDirection.Horizontal\n\t    Layout.Padding = UDim.new(0, 4)\n\t    Layout.VerticalAlignment = Enum.VerticalAlignment.Center\n\t    Layout.HorizontalAlignment = Enum.HorizontalAlignment.Center\n\t    Layout:GetPropertyChangedSignal(\"AbsoluteContentSize\"):Connect(function()\n\t        Billboard.Size = UDim2.fromOffset(math.max(Layout.AbsoluteContentSize.X + 4, 36), 36)\n\t    end)\n\t    Layout.Parent = Frame\n\t    local Corner: UICorner = Instance.new(\"UICorner\")\n\t    Corner.CornerRadius = UDim.new(0, 4)\n\t    Corner.Parent = Frame\n\t    Reference[Bed] = Billboard\n\t    RefreshAdornee(Billboard)\n\tend\n\t\n\tlocal function RefreshNear(Data)\n\t    Data = Data.blockRef.blockPosition * 3\n\t    for Bed: BasePart, v: BillboardGui in Reference do\n\t        if (Data - Bed.Position).Magnitude <= 30 then\n\t            RefreshAdornee(v)\n\t        end\n\t    end\n\tend\n\t\n\tBedPlates = vape.Categories.World:CreateModule({\n\t    Name = \"BedPlates\",\n\t    Function = function(Callback: boolean)\n\t        if Callback then\n\t            for _, v: BasePart in CollectionService:GetTagged(\"bed\") do\n\t                task.spawn(Added, v)\n\t            end\n\t            BedPlates:Clean(VapeEvents.PlaceBlockEvent.Event:Connect(RefreshNear))\n\t            BedPlates:Clean(VapeEvents.BreakBlockEvent.Event:Connect(RefreshNear))\n\t            BedPlates:Clean(CollectionService:GetInstanceAddedSignal(\"bed\"):Connect(Added))\n\t            BedPlates:Clean(CollectionService:GetInstanceRemovedSignal(\"bed\"):Connect(function(Bed: Instance)\n\t                if Reference[Bed] then\n\t                    Reference[Bed]:Destroy()\n\t                    Reference[Bed] = nil\n\t                end\n\t            end))\n\t        else\n\t            table.clear(Reference)\n\t            Folder:ClearAllChildren()\n\t        end\n\t    end,\n\t    Tooltip = \"Displays blocks over the bed\"\n\t})\n\t\n\tBackground = BedPlates:CreateToggle({\n\t    Name = \"Background\",\n\t    Function = function(Callback: boolean)\n\t        if Color and Color.Object then\n\t            Color.Object.Visible = Callback\n\t        end\n\t        for _, v: BillboardGui in Reference do\n\t            v.Frame.BackgroundTransparency = 1 - (Callback and Color.Opacity or 0)\n\t            v.Blur.Visible = Callback\n\t        end\n\t    end,\n\t    Default = true\n\t})\n\tColor = BedPlates:CreateColorSlider({\n\t    Name = \"Background Color\",\n\t    DefaultValue = 0,\n\t    DefaultOpacity = 0.5,\n\t    Function = function(Hue: number, Sat: number, Val: number, Opacity: number)\n\t        for _, v: BillboardGui in Reference do\n\t            v.Frame.BackgroundColor3 = Color3.fromHSV(Hue, Sat, Val)\n\t            v.Frame.BackgroundTransparency = 1 - (Background.Enabled and Opacity or 0)\n\t        end\n\t    end,\n\t    Darker = true\n\t})\n\tLayerCounter = BedPlates:CreateToggle({\n\t    Name = \"Layer Counter\",\n\t    Function = function(Callback: boolean)\n\t        if LayerColor and LayerColor.Object then\n\t            LayerColor.Object.Visible = Callback\n\t        end\n\t        for _, v: BillboardGui in Reference do\n\t            RefreshAdornee(v)\n\t        end\n\t    end,\n\t    Default = true\n\t})\n\tLayerColor = BedPlates:CreateColorSlider({\n\t    Name = \"Counter Text Color\",\n\t    Function = function()\n\t        local TextColor: Color3 = (LayerColor and Color3.fromHSV(LayerColor.Hue, LayerColor.Sat, LayerColor.Value) or Color3.new(1, 1, 1))\n\t        for _, Billboard: BillboardGui in Reference do\n\t            for _, v: Instance in Billboard.Frame:GetDescendants() do\n\t                if v:IsA(\"TextLabel\") and v.Name == \"Amount\" then\n\t                    v.TextColor3 = TextColor\n\t                end\n\t            end\n\t        end\n\t    end,\n\t    DefaultSat = 0,\n\t    DefaultValue = 1\n\t})\nend)\n\nRun(function()\n\tlocal BedProtector\n\tlocal PlaceRange\n\tlocal Layers\n\tlocal Blacklist\n\tlocal Wool\n\tlocal Mode\n\tlocal Smart\n\tlocal Switch\n\t\n\tlocal function GetBlocks()\n\t    local Blocks = {}\n\t    for _, v: any in Store.inventory.inventory.items do\n\t        local Block = bedwars.ItemMeta[v.itemType].block\n\t        if Block and (Wool.Enabled and v.itemType:find(\"wool\") or not Wool.Enabled and not table.find(Blacklist.ListEnabled, v.itemType:find(\"wool\") and \"wool\" or v.itemType)) then\n\t            table.insert(Blocks, {Type = v.itemType, Health = Block.health, Tool = v.tool, Amount = v.amount or math.huge})\n\t        end\n\t    end\n\t    if #Blocks > 1 then\n\t        table.sort(Blocks, function(A, B): boolean\n\t            return A.Health > B.Health\n\t        end)\n\t    end\n\t    return Blocks\n\tend\n\t\n\tlocal function GetLayerBlock(Blocks, Layer: number)\n\t    local Count: number = #Blocks\n\t    for i: number = 0, Count - 1 do\n\t        local Block = Blocks[(math.min(Layer, Count) + i - 1) % Count + 1]\n\t        if Block.Amount > 0 then\n\t            return Block\n\t        end\n\t    end\n\t    return nil\n\tend\n\t\n\tlocal function GetPyramid(Size: number, Grid: number): {Vector3}\n\t    local Positions: {Vector3} = {}\n\t    for Height: number = Size, 0, -1 do\n\t        for Width: number = Height, 0, -1 do\n\t            table.insert(Positions, Vector3.new(Width, (Size - Height), ((Height + 1) - Width)) * Grid)\n\t            table.insert(Positions, Vector3.new(Width * -1, (Size - Height), ((Height + 1) - Width)) * Grid)\n\t            table.insert(Positions, Vector3.new(Width, (Size - Height), (Height - Width) * -1) * Grid)\n\t            table.insert(Positions, Vector3.new(Width * -1, (Size - Height), (Height - Width) * -1) * Grid)\n\t        end\n\t    end\n\t    return Positions\n\tend\n\t\n\tlocal function GetPyramidRange(Size: number): number\n\t    local Far: number = 0\n\t    for _, v: Vector3 in GetPyramid(Size, 3) do\n\t        Far = math.max(Far, v.Magnitude)\n\t    end\n\t    return Far\n\tend\n\t\n\tlocal function GetBedNear()\n\t    local LocalPosition: Vector3 = Entity.isAlive and Entity.character.RootPart.Position or Vector3.zero\n\t    local Range: number = PlaceRange.Value + GetPyramidRange(Layers.Value)\n\t    for _, v: BasePart in CollectionService:GetTagged(\"bed\") do\n\t        if (LocalPosition - v.Position).Magnitude < Range and v:GetAttribute(`Team{LocalPlayer:GetAttribute(\"Team\") or -1}NoBreak`) then\n\t            return v\n\t        end\n\t    end\n\t    return nil\n\tend\n\t\n\tlocal function PlaceLayer(Bed: BasePart, Blocks, Layer: number): boolean\n\t    local PlaceDelay: number = 1 / math.min(bedwars.DefaultPlaceCPS or math.huge, bedwars.SharedConstants.BLOCK_PLACE_CPS)\n\t    for _, Offset: Vector3 in GetPyramid(Layer, 3) do\n\t        if not BedProtector.Enabled or not Entity.isAlive then\n\t            return false\n\t        end\n\t        local Position: Vector3 = (Bed.CFrame * CFrame.new(Offset)).Position\n\t        if GetPlacedBlock(Position) then\n\t            continue\n\t        end\n\t        if (Entity.character.RootPart.Position - Position).Magnitude > PlaceRange.Value then\n\t            continue\n\t        end\n\t        local Block = GetLayerBlock(Blocks, Layer)\n\t        if not Block then\n\t            return false\n\t        end\n\t\n\t        repeat\n\t            task.wait()\n\t        until not BedProtector.Enabled or not Entity.isAlive or (workspace:GetServerTimeNow() - bedwars.BlockCpsController.lastPlaceTimestamp) >= PlaceDelay\n\t        if not BedProtector.Enabled or not Entity.isAlive then\n\t            return false\n\t        end\n\t\n\t        if Switch.Enabled and HotbarSwitch(GetHotbar(Block.Tool)) then\n\t            task.wait()\n\t        end\n\t        task.spawn(bedwars.placeBlock, Position, Block.Type, false)\n\t        if GetPlacedBlock(Position) then\n\t            Block.Amount -= 1\n\t        end\n\t    end\n\t    return true\n\tend\n\t\n\tBedProtector = vape.Categories.World:CreateModule({\n\t    Name = \"BedProtector\",\n\t    Function = function(Callback: boolean)\n\t        if Callback then\n\t            repeat\n\t                local Bed = GetBedNear()\n\t                if Bed then\n\t                    local Blocks = GetBlocks()\n\t                    local PreviousSlot: number? = Switch.Enabled and Store.hand and Store.hand.tool and GetHotbar(Store.hand.tool) or nil\n\t\n\t                    for Layer: number = 1, Layers.Value do\n\t                        if #Blocks == 0 or not PlaceLayer(Bed, Blocks, Layer) then\n\t                            break\n\t                        end\n\t                    end\n\t\n\t                    if PreviousSlot and HotbarSwitch(PreviousSlot) then\n\t                        task.wait()\n\t                    end\n\t                else\n\t                    if Mode.Value == \"On Key\" then\n\t                        SendNotification(\"BedProtector\", \"Unable to locate bed\", 5)\n\t                        BedProtector:Toggle()\n\t                        break\n\t                    end\n\t                end\n\t                task.wait(0.5)\n\t                if Mode.Value == \"On Key\" then\n\t                    BedProtector:Toggle()\n\t                    break\n\t                end\n\t            until not BedProtector.Enabled\n\t        end\n\t    end,\n\t    Tooltip = \"Automatically places strong blocks around the bed.\"\n\t})\n\t\n\tMode = BedProtector:CreateDropdown({\n\t    Name = \"Mode\",\n\t    List = {\"Toggle\", \"On Key\"},\n\t    Function = function(Val: string)\n\t        if Smart then\n\t            Smart.Object.Visible = Val == \"Toggle\"\n\t        end\n\t    end,\n\t    Default = \"Toggle\"\n\t})\n\tBlacklist = BedProtector:CreateTextList({\n\t    Name = \"Blacklist\",\n\t    Default = {\"siege_tnt\", \"tnt\"}\n\t})\n\tPlaceRange = BedProtector:CreateSlider({\n\t    Name = \"Place Range\",\n\t    Min = 1,\n\t    Max = 30,\n\t    Default = 15\n\t})\n\tLayers = BedProtector:CreateSlider({\n\t    Name = \"Layers\",\n\t    Min = 1,\n\t    Max = 6,\n\t    Default = 2,\n\t    Tooltip = \"How many layers go around your bed. Your strongest block goes closest to it, and your weakest one is reused when you have fewer block types than layers\"\n\t})\n\tWool = BedProtector:CreateToggle({Name = \"Wool only\", Tooltip = \"Only uses wools to bed defend.\"})\n\tSwitch = BedProtector:CreateToggle({Name = \"Auto Switch\"})\n\tSmart = BedProtector:CreateToggle({Name = \"Smart\", Default = true})\nend)\n\nRun(function()\n\tlocal BlockIn\n\tlocal Mode\n\tlocal PlacementMode\n\tlocal PlacementSpeed\n\tlocal Center\n\tlocal Priority\n\tlocal Return\n\tlocal Switch\n\tlocal Wool\n\tlocal Blacklist\n\tlocal CenterOrigin: Vector3?\n\tlocal LastPlace: number = 0\n\t\n\tlocal Scan: number = 30\n\tlocal Directions: {Vector3} = {\n\t    Vector3.new(1, 0, 0),\n\t    Vector3.new(-1, 0, 0),\n\t    Vector3.new(0, 0, 1),\n\t    Vector3.new(0, 0, -1)\n\t}\n\tlocal Priorities = {\n\t    [\"Lowest cost\"] = function(A, B): boolean\n\t        return A.Health < B.Health\n\t    end,\n\t    [\"Hardest\"] = function(A, B): boolean\n\t        return A.Health > B.Health\n\t    end\n\t}\n\t\n\tlocal function GetOrigin(): Vector3\n\t    local Position: Vector3 = Entity.character.RootPart.Position\n\t    local Hit: RaycastResult? = Entity.Raycast(Position, Vector3.new(0, -Scan, 0), Store.airRay)\n\t    return RoundPosition(Hit and Vector3.new(Position.X, Hit.Position.Y + 1.5, Position.Z) or Position)\n\tend\n\t\n\tlocal function GetBedNear()\n\t    local LocalPosition: Vector3 = Entity.character.RootPart.Position\n\t    for _, v: BasePart in CollectionService:GetTagged(\"bed\") do\n\t        if (LocalPosition - v.Position).Magnitude >= 14 or v:GetAttribute(`Team{LocalPlayer:GetAttribute(\"Team\") or -1}NoBreak`) then\n\t            continue\n\t        end\n\t\n\t        local Handler = bedwars.BlockController:getHandlerRegistry():getHandler(v.Name)\n\t        local Cells = Handler and Handler:getContainedPositions(v) or {v.Position / 3}\n\t        local Occupied = {}\n\t        for _, Cell: Vector3 in Cells do\n\t            Occupied[Cell * 3] = true\n\t        end\n\t\n\t        local Defended: boolean = true\n\t        for _, Cell: Vector3 in Cells do\n\t            for i: number = 1, #Sides do\n\t                local Position: Vector3 = (Cell * 3) + Sides[i]\n\t                if not Occupied[Position] and not GetPlacedBlock(Position) then\n\t                    Defended = false\n\t                    break\n\t                end\n\t            end\n\t            if not Defended then\n\t                break\n\t            end\n\t        end\n\t\n\t        if Defended then\n\t            return v\n\t        end\n\t    end\n\t    return nil\n\tend\n\t\n\tlocal function GetBlocks()\n\t    local Blocks = {}\n\t    for _, v: any in Store.inventory.inventory.items do\n\t        local Block = bedwars.ItemMeta[v.itemType].block\n\t        if Block and (Wool.Enabled and v.itemType:find(\"wool\") or not Wool.Enabled and not table.find(Blacklist.ListEnabled, v.itemType:find(\"wool\") and \"wool\" or v.itemType)) then\n\t            local Slot: number? = GetHotbar(v.tool)\n\t            if Slot or not Switch.Enabled then\n\t                table.insert(Blocks, {Type = v.itemType, Health = Block.health, Slot = Slot, Amount = v.amount or math.huge})\n\t            end\n\t        end\n\t    end\n\t    if #Blocks > 1 then\n\t        table.sort(Blocks, Priorities[Priority.Value])\n\t    end\n\t    return Blocks\n\tend\n\t\n\tlocal function GetEnclosure(Origin: Vector3, Grounded: boolean): {Vector3}\n\t    local Enemy = Entity.EntityPosition({\n\t        Range = 60,\n\t        Part = \"RootPart\",\n\t        Players = true\n\t    })\n\t    local Facing: Vector3 = Enemy and Enemy.RootPart.Position - Origin or Vector3.zero\n\t    local Order: {Vector3} = table.clone(Directions)\n\t    table.sort(Order, function(A: Vector3, B: Vector3): boolean\n\t        return A:Dot(Facing) > B:Dot(Facing)\n\t    end)\n\t\n\t    local Cells: {Vector3} = {}\n\t    if Grounded and not Entity.Raycast(Origin, Vector3.new(0, -3, 0), Store.airRay) then\n\t        table.insert(Cells, Vector3.new(0, -3, 0))\n\t    end\n\t    for _, Height: number in {0, 3} do\n\t        for _, Direction: Vector3 in Order do\n\t            table.insert(Cells, Vector3.new(Direction.X * 3, Height, Direction.Z * 3))\n\t        end\n\t    end\n\t    if Grounded then\n\t        table.insert(Cells, Vector3.new(Order[1].X * 3, 6, Order[1].Z * 3))\n\t        table.insert(Cells, Vector3.new(0, 6, 0))\n\t    end\n\t    return Cells\n\tend\n\t\n\tlocal function HoldCenter()\n\t    if not CenterOrigin or PlacementMode.Value ~= \"Blatant\" or not Center.Enabled or vape.MovementOwner or not Entity.isAlive then\n\t        return\n\t    end\n\t\n\t    local Root: BasePart = Entity.character.RootPart\n\t    if isnetworkowner(Root) then\n\t        Root.CFrame = CFrame.new(CenterOrigin.X, Root.Position.Y, CenterOrigin.Z) * Root.CFrame.Rotation\n\t        Root.AssemblyLinearVelocity = Vector3.new(0, Root.AssemblyLinearVelocity.Y, 0)\n\t    end\n\tend\n\t\n\tlocal function GetPlaceDelay(): number\n\t    local CPS: number = math.min(bedwars.DefaultPlaceCPS or math.huge, bedwars.SharedConstants.BLOCK_PLACE_CPS)\n\t    if PlacementMode.Value == \"Legit\" then\n\t        CPS = math.min(CPS, PlacementSpeed.Value)\n\t    end\n\t    return 1 / math.max(CPS, 1)\n\tend\n\t\n\tlocal function PlacePattern(Origin: Vector3, Cells: {Vector3}, Blocks, Limit: number)\n\t    local Hotbar = Store.hand.tool and GetHotbar(Store.hand.tool) or nil\n\t    local Placed: number = 0\n\t\n\t    for _, Offset: Vector3 in Cells do\n\t        if Placed >= Limit or not BlockIn.Enabled or not Entity.isAlive then\n\t            break\n\t        end\n\t        local Position: Vector3 = Origin + Offset\n\t        if GetPlacedBlock(Position) then\n\t            continue\n\t        end\n\t        while Blocks[1] and Blocks[1].Amount <= 0 do\n\t            table.remove(Blocks, 1)\n\t        end\n\t        local Block = Blocks[1]\n\t        if not Block then\n\t            break\n\t        end\n\t\n\t        if PlacementMode.Value == \"Blatant\" and Center.Enabled then\n\t            CenterOrigin = Origin\n\t        end\n\t        repeat\n\t            task.wait()\n\t        until not BlockIn.Enabled or not Entity.isAlive or (workspace:GetServerTimeNow() - math.max(LastPlace, bedwars.BlockCpsController.lastPlaceTimestamp)) >= GetPlaceDelay()\n\t        if not BlockIn.Enabled or not Entity.isAlive then\n\t            break\n\t        end\n\t        if PlacementMode.Value == \"Legit\" then\n\t            local OffsetPosition: Vector3 = (Entity.character.RootPart.Position - Origin) * Vector3.new(1, 0, 1)\n\t            if math.max(math.abs(OffsetPosition.X), math.abs(OffsetPosition.Z)) > 1.5 then\n\t                break\n\t            end\n\t        end\n\t\n\t        if Switch.Enabled then\n\t            HotbarSwitch(Block.Slot)\n\t        end\n\t        LastPlace = workspace:GetServerTimeNow()\n\t        task.spawn(bedwars.placeBlock, Position, Block.Type)\n\t        if GetPlacedBlock(Position) then\n\t            Block.Amount -= 1\n\t            Placed += 1\n\t        end\n\t    end\n\t    if Return.Enabled and Switch.Enabled and Hotbar then\n\t        HotbarSwitch(Hotbar)\n\t    end\n\tend\n\t\n\tBlockIn = vape.Categories.World:CreateModule({\n\t    Name = \"Block-In\",\n\t    Function = function(Callback: boolean)\n\t        if Callback then\n\t            LastPlace = 0\n\t            BlockIn:Clean(RunService.PreSimulation:Connect(HoldCenter))\n\t            BlockIn:Clean(function()\n\t                CenterOrigin = nil\n\t            end)\n\t\n\t            repeat\n\t                if Entity.isAlive and (Mode.Value == \"On bind\" or GetBedNear()) then\n\t                    local Blocks = GetBlocks()\n\t                    local Early: boolean = false\n\t                    repeat\n\t                        task.wait()\n\t                        if Entity.isAlive and not Early then\n\t                            local Origin: Vector3 = GetOrigin()\n\t                            local Drop: number = Entity.character.RootPart.Position.Y - Origin.Y\n\t                            Early = Drop >= 6 and Drop <= 24\n\t                            if Early then\n\t                                PlacePattern(Origin, GetEnclosure(Origin, false), Blocks, PlacementMode.Value == \"Blatant\" and Center.Enabled and math.huge or 3)\n\t                            end\n\t                        end\n\t                    until not BlockIn.Enabled or not Entity.isAlive or Entity.character.Humanoid.FloorMaterial ~= Enum.Material.Air\n\t\n\t                    if Entity.isAlive then\n\t                        local Origin: Vector3 = GetOrigin()\n\t                        PlacePattern(Origin, GetEnclosure(Origin, true), Blocks, math.huge)\n\t                    end\n\t                    CenterOrigin = nil\n\t                end\n\t\n\t                if Mode.Value == \"On bind\" then\n\t                    if BlockIn.Enabled then BlockIn:Toggle() end\n\t                    break\n\t                end\n\t                task.wait(0.5)\n\t            until not BlockIn.Enabled\n\t        end\n\t    end,\n\t    Tooltip = \"Automatically blocks you in by building walls around you\"\n\t})\n\t\n\tMode = BlockIn:CreateDropdown({\n\t    Name = \"Mode\",\n\t    List = {\"On bind\", \"When near\"},\n\t    Default = \"On bind\",\n\t    Tooltip = \"On bind blocks you in once per keypress, When near keeps you blocked in while you are on an enemy bed\"\n\t})\n\tPlacementMode = BlockIn:CreateDropdown({\n\t    Name = \"Placement mode\",\n\t    List = {\"Legit\", \"Blatant\"},\n\t    Default = \"Legit\",\n\t    Function = function(Val: string)\n\t        if PlacementSpeed then PlacementSpeed.Object.Visible = Val == \"Legit\" end\n\t        if Center then Center.Object.Visible = Val == \"Blatant\" end\n\t    end,\n\t    Tooltip = \"Legit uses your placement speed and lets you move freely, Blatant builds at the normal limit with optional centering\"\n\t})\n\tPlacementSpeed = BlockIn:CreateSlider({\n\t    Name = \"Placement speed\",\n\t    Min = 1,\n\t    Max = math.max(bedwars.DefaultPlaceCPS or bedwars.SharedConstants.BLOCK_PLACE_CPS, 1),\n\t    Default = 4,\n\t    Visible = true,\n\t    Suffix = \"blocks/s\",\n\t    Tooltip = \"Blocks placed per second in Legit mode\"\n\t})\n\tCenter = BlockIn:CreateToggle({\n\t    Name = \"Center\",\n\t    Default = true,\n\t    Visible = false,\n\t    Tooltip = \"Holds you in the middle of your block while it builds, so no side gets skipped\"\n\t})\n\tPriority = BlockIn:CreateDropdown({\n\t    Name = \"Block priority\",\n\t    List = {\"Lowest cost\", \"Hardest\"},\n\t    Default = \"Lowest cost\"\n\t})\n\tSwitch = BlockIn:CreateToggle({Name = \"Switch\", Default = true})\n\tReturn = BlockIn:CreateToggle({Name = \"Return to last slot\", Default = true})\n\tWool = BlockIn:CreateToggle({Name = \"Wool only\"})\n\tBlacklist = BlockIn:CreateTextList({\n\t    Name = \"Blacklist\",\n\t    Default = {\"cannon\", \"siege_tnt\", \"tnt\"}\n\t})\nend)\n\nRun(function()\n\tlocal ChestSteal\n\tlocal Session = nil\n\tlocal Range\n\tlocal Open\n\tlocal Skywars\n\tlocal Legit\n\tlocal Visualize\n\tlocal FillColor\n\tlocal OutlineColor\n\tlocal Animate\n\tlocal Speed\n\tlocal Delays = {}\n\tlocal Boxes = {}\n\tlocal Tweens = {}\n\tlocal BoxTargets = {}\n\t\n\tlocal function UpdateBoxes(Targets)\n\t    for i: number, Box: Part in Boxes do\n\t        local Chest = Targets and Targets[i]\n\t        if Chest ~= BoxTargets[i] then\n\t            if Tweens[i] then\n\t                Tweens[i]:Cancel()\n\t                Tweens[i] = nil\n\t            end\n\t\n\t            if not Chest then\n\t                Box.Parent = nil\n\t            elseif Animate.Enabled and Box.Parent == Camera then\n\t                Tweens[i] = TweenService:Create(Box, TweenInfo.new(Speed.Value, Enum.EasingStyle.Quad, Enum.EasingDirection.Out), {CFrame = Chest.CFrame})\n\t                Tweens[i]:Play()\n\t            else\n\t                Box.CFrame = Chest.CFrame\n\t                Box.Parent = Camera\n\t            end\n\t            BoxTargets[i] = Chest\n\t        end\n\t\n\t        if Chest then\n\t            Box.SelectionBox.Color3 = Color3.fromHSV(OutlineColor.Hue, OutlineColor.Sat, OutlineColor.Value)\n\t            Box.SelectionBox.Transparency = 1 - OutlineColor.Opacity\n\t            Box.SelectionBox.SurfaceColor3 = Color3.fromHSV(FillColor.Hue, FillColor.Sat, FillColor.Value)\n\t            Box.SelectionBox.SurfaceTransparency = 1 - FillColor.Opacity\n\t        end\n\t    end\n\tend\n\t\n\tlocal function LootChest(Chest)\n\t    Chest = Chest and Chest.Value or nil\n\t    \n\t    local ChestItems = Chest and Chest:GetChildren() or {}\n\t    if #ChestItems > 1 and (Delays[Chest] or 0) < tick() then\n\t        Delays[Chest] = tick() + 0.2\n\t        local Observed = LocalPlayer.Character and LocalPlayer.Character:FindFirstChild(\"ObservedChestFolder\")\n\t        Observed = Observed and Observed.Value or nil\n\t        bedwars.Client:GetNamespace(\"Inventory\"):Get(\"SetObservedChest\"):SendToServer(Chest)\n\t\n\t        for _, v: Instance in ChestItems do\n\t            if v:IsA(\"Accessory\") then\n\t                task.spawn(function()\n\t                    pcall(function()\n\t                        bedwars.Client:GetNamespace(\"Inventory\"):Get(\"ChestGetItem\"):CallServer(Chest, v)\n\t                    end)\n\t                end)\n\t                if Legit.Enabled then\n\t                    task.wait(0.2)\n\t                end\n\t            end\n\t        end\n\t\n\t        bedwars.Client:GetNamespace(\"Inventory\"):Get(\"SetObservedChest\"):SendToServer(Observed)\n\t    end\n\tend\n\t\n\tChestSteal = vape.Categories.World:CreateModule({\n\t    Name = \"ChestSteal\",\n\t    Function = function(Callback: boolean)\n\t        if Callback then\n\t            local Current = {}\n\t            Session = Current\n\t            local Chests = Collection(\"chest\", ChestSteal)\n\t            repeat\n\t                task.wait()\n\t            until Store.queueType ~= \"bedwars_test\"\n\t            if Session ~= Current then\n\t                return\n\t            end\n\t            local function GetChestPart(Folder: Instance)\n\t                for _, v: BasePart in Chests do\n\t                    local FolderValue: ObjectValue? = v:FindFirstChild(\"ChestFolderValue\")\n\t                    if FolderValue and FolderValue.Value == Folder then\n\t                        return v\n\t                    end\n\t                end\n\t                return nil\n\t            end\n\t\n\t            if (not Skywars.Enabled) or Store.queueType:find(\"skywars\") then\n\t                repeat\n\t                    local Targets = {}\n\t                    if Entity.isAlive and Store.matchState ~= 2 then\n\t                        if Open.Enabled then\n\t                            if bedwars.AppController:isAppOpen(\"ChestApp\") then\n\t                                local Observed = LocalPlayer.Character:FindFirstChild(\"ObservedChestFolder\")\n\t                                LootChest(Observed)\n\t                                Targets[1] = Observed and Observed.Value and GetChestPart(Observed.Value) or nil\n\t                            end\n\t                        else\n\t                            local LocalPosition: Vector3 = Entity.character.RootPart.Position\n\t                            local Closest: number = math.huge\n\t                            for _, v: BasePart in Chests do\n\t                                local Magnitude: number = (LocalPosition - v.Position).Magnitude\n\t                                if Magnitude <= Range.Value then\n\t                                    LootChest(v:FindFirstChild(\"ChestFolderValue\"))\n\t                                    if Magnitude < Closest then\n\t                                        Closest, Targets[1] = Magnitude, v\n\t                                    end\n\t                                end\n\t                            end\n\t                        end\n\t                    end\n\t\n\t                    UpdateBoxes(Targets)\n\t                    task.wait(0.1)\n\t                until not ChestSteal.Enabled or Session ~= Current\n\t            end\n\t        else\n\t            UpdateBoxes(nil)\n\t        end\n\t    end,\n\t    Tooltip = \"Grabs items from near chests.\"\n\t})\n\t\n\tRange = ChestSteal:CreateSlider({\n\t    Name = \"Range\",\n\t    Min = 0,\n\t    Max = 18,\n\t    Default = 18,\n\t    Suffix = function(Val: number)\n\t        return Val == 1 and \"stud\" or \"studs\"\n\t    end\n\t})\n\tVisualize = ChestSteal:CreateToggle({\n\t    Name = \"Visualize\",\n\t    Function = function(Callback: boolean)\n\t        FillColor.Object.Visible = Callback\n\t        OutlineColor.Object.Visible = Callback\n\t        Animate.Object.Visible = Callback\n\t        Speed.Object.Visible = Callback\n\t        if Callback then\n\t            local Part: Part = Instance.new(\"Part\")\n\t            Part.Size = Vector3.new(3, 3, 3)\n\t            Part.Anchored = true\n\t            Part.CanCollide = false\n\t            Part.CanQuery = false\n\t            Part.CanTouch = false\n\t            Part.CastShadow = false\n\t            Part.Transparency = 1\n\t            local Selection: SelectionBox = Instance.new(\"SelectionBox\")\n\t            Selection.Adornee = Part\n\t            Selection.LineThickness = 0.04\n\t            Selection.Parent = Part\n\t            bedwars.QueryUtil:setQueryIgnored(Part, true)\n\t            Boxes[1] = Part\n\t        else\n\t            UpdateBoxes(nil)\n\t            for _, v: Part in Boxes do\n\t                v:Destroy()\n\t            end\n\t            table.clear(Boxes)\n\t            table.clear(Tweens)\n\t            table.clear(BoxTargets)\n\t        end\n\t    end,\n\t    Tooltip = \"Draws a box around the closest chest being looted\"\n\t})\n\tFillColor = ChestSteal:CreateColorSlider({\n\t    Name = \"Fill Color\",\n\t    DefaultSat = 0,\n\t    DefaultOpacity = 0.25,\n\t    Darker = true,\n\t    Visible = false\n\t})\n\tOutlineColor = ChestSteal:CreateColorSlider({\n\t    Name = \"Outline Color\",\n\t    DefaultSat = 0,\n\t    Darker = true,\n\t    Visible = false\n\t})\n\tAnimate = ChestSteal:CreateToggle({\n\t    Name = \"Animate\",\n\t    Default = true,\n\t    Darker = true,\n\t    Visible = false,\n\t    Tooltip = \"Glides the box onto the next chest instead of snapping to it\"\n\t})\n\tSpeed = ChestSteal:CreateSlider({\n\t    Name = \"Animation time\",\n\t    Min = 0.01,\n\t    Max = 0.5,\n\t    Default = 0.08,\n\t    Decimal = 100,\n\t    Suffix = \"s\",\n\t    Darker = true,\n\t    Visible = false\n\t})\n\tOpen = ChestSteal:CreateToggle({Name = \"GUI Check\"})\n\tLegit = ChestSteal:CreateToggle(({Name = \"Legit mode\"}))\n\tSkywars = ChestSteal:CreateToggle({\n\t    Name = \"Only Skywars\",\n\t    Function = function()\n\t        if ChestSteal.Enabled then\n\t            ChestSteal:Toggle()\n\t            ChestSteal:Toggle()\n\t        end\n\t    end,\n\t    Default = true\n\t})\nend)\n\nRun(function()\n\tlocal FastPlace\n\tlocal CPS\n\t\n\tbedwars.DefaultPlaceCPS = bedwars.SharedConstants.BLOCK_PLACE_CPS\n\t\n\tFastPlace = vape.Categories.World:CreateModule({\n\t    Name = \"FastPlace\",\n\t    Function = function(Callback: boolean)\n\t        bedwars.SharedConstants.BLOCK_PLACE_CPS = Callback and CPS.Value or bedwars.DefaultPlaceCPS\n\t    end,\n\t    Tooltip = \"Changes the block place delay. Block-In and BedProtector keep the normal speed so none of their blocks get dropped\"\n\t})\n\t\n\tCPS = FastPlace:CreateSlider({\n\t    Name = \"Cps\",\n\t    Min = 1,\n\t    Max = 100,\n\t    Function = function(Val: number)\n\t        if FastPlace.Enabled then\n\t            bedwars.SharedConstants.BLOCK_PLACE_CPS = Val\n\t        end\n\t    end,\n\t    Default = 13\n\t})\n\tFastPlace:CreateButton({\n\t    Name = \"Reset to bedwars cps\",\n\t    Function = function()\n\t        CPS:SetValue(bedwars.DefaultPlaceCPS)\n\t    end\n\t})\nend)\n\nRun(function()\n\tlocal Nuker\n\tlocal Mode\n\tlocal ClosestBreak\n\tlocal Range\n\tlocal BreakSpeed\n\tlocal UpdateRate\n\tlocal Custom\n\tlocal Bed\n\tlocal Tesla\n\tlocal Hive\n\tlocal LuckyBlock\n\tlocal IronOre\n\tlocal Effect\n\tlocal CustomHealth = {}\n\tlocal Animation = {}\n\tlocal SelfBreak\n\tlocal LimitItem\n\tlocal Wallcheck\n\tlocal ViewAngle\n\tlocal AutoTool\n\tlocal PlayerCheck\n\tlocal CustomList, Parts = {}, {}\n\tlocal Mouse: Mouse = cloneref(LocalPlayer:GetMouse())\n\tlocal MouseParams: RaycastParams = RaycastParams.new()\n\tMouseParams.FilterType = Enum.RaycastFilterType.Exclude\n\tlocal MouseOrigin, MouseDirection, MouseHit = Vector3.zero, Vector3.zero, nil\n\tlocal PlayerParams: RaycastParams = RaycastParams.new()\n\tPlayerParams.FilterType = Enum.RaycastFilterType.Include\n\tlocal Session = nil\n\tlocal ActiveBlock: BasePart?\n\tlocal NextBreak: number = 0\n\tlocal PathShown: boolean = false\n\tlocal HealthbarProgress\n\tlocal HealthbarCleanup: (() -> ())?\n\t\n\tlocal function ClearHealthbar()\n\t    local Cleanup: (() -> ())? = HealthbarCleanup\n\t    HealthbarCleanup = nil\n\t    if Cleanup then\n\t        Cleanup()\n\t    end\n\tend\n\t\n\tlocal function CustomHealthbar(self, BlockRef, Health: number, MaxHealth: number, ChangeHealth: number, Block)\n\t    xpcall(function()\n\t        if Block:GetAttribute(\"NoHealthbar\") then\n\t            return\n\t        end\n\t        if not self.healthbarPart or not self.healthbarBlockRef or self.healthbarBlockRef.blockPosition ~= BlockRef.blockPosition then\n\t            if self.healthbarPart then\n\t                bedwars.QueryUtil:setQueryIgnored(self.healthbarPart, true)\n\t            end\n\t            ClearHealthbar()\n\t            self.healthbarBlockRef = BlockRef\n\t            local Roact = bedwars.Roact\n\t            local Create = Roact.createElement\n\t            local Meta = bedwars.ItemMeta[Block.Name]\n\t            local DisplayName: string = Meta and Meta.displayName or Block.Name\n\t            HealthbarProgress = HealthbarProgress or Roact.createRef()\n\t            local Percent: number = math.clamp(Health / MaxHealth, 0, 1)\n\t            local CleanCheck: boolean = true\n\t            local Part: Part = Instance.new(\"Part\")\n\t            Part.Size = Vector3.one\n\t            Part.CFrame = CFrame.new(bedwars.BlockController:getWorldPosition(BlockRef.blockPosition))\n\t            Part.Transparency = 1\n\t            Part.Anchored = true\n\t            Part.CanCollide = false\n\t            Part.Parent = workspace\n\t            bedwars.QueryUtil:setQueryIgnored(Part, true)\n\t            self.healthbarPart = Part\n\t\n\t            local Mounted = Roact.mount(Create(\"BillboardGui\", {\n\t                Size = UDim2.fromOffset(249, 102),\n\t                StudsOffset = Vector3.new(0, 2.5, 0),\n\t                Adornee = Part,\n\t                MaxDistance = 40,\n\t                AlwaysOnTop = true\n\t            }, {\n\t                Create(\"Frame\", {\n\t                    Size = UDim2.fromOffset(160, 50),\n\t                    Position = UDim2.fromOffset(44, 32),\n\t                    BackgroundColor3 = Color3.new(),\n\t                    BackgroundTransparency = 0.5\n\t                }, {\n\t                    Create(\"UICorner\", {CornerRadius = UDim.new(0, 5)}),\n\t                    Create(\"ImageLabel\", {\n\t                        Size = UDim2.new(1, 89, 1, 52),\n\t                        Position = UDim2.fromOffset(-48, -31),\n\t                        BackgroundTransparency = 1,\n\t                        Image = GetVapeAsset(`{vape.Directory}/assets/new/blur.png`),\n\t                        ScaleType = Enum.ScaleType.Slice,\n\t                        SliceCenter = Rect.new(52, 31, 261, 502)\n\t                    }),\n\t                    Create(\"TextLabel\", {\n\t                        Size = UDim2.fromOffset(145, 14),\n\t                        Position = UDim2.fromOffset(13, 12),\n\t                        BackgroundTransparency = 1,\n\t                        Text = DisplayName,\n\t                        TextXAlignment = Enum.TextXAlignment.Left,\n\t                        TextYAlignment = Enum.TextYAlignment.Top,\n\t                        TextColor3 = Color3.new(),\n\t                        TextScaled = true,\n\t                        Font = Enum.Font.Arial\n\t                    }),\n\t                    Create(\"TextLabel\", {\n\t                        Size = UDim2.fromOffset(145, 14),\n\t                        Position = UDim2.fromOffset(12, 11),\n\t                        BackgroundTransparency = 1,\n\t                        Text = DisplayName,\n\t                        TextXAlignment = Enum.TextXAlignment.Left,\n\t                        TextYAlignment = Enum.TextYAlignment.Top,\n\t                        TextColor3 = Color.Dark(UIPallet.Text, 0.16),\n\t                        TextScaled = true,\n\t                        Font = Enum.Font.Arial\n\t                    }),\n\t                    Create(\"Frame\", {\n\t                        Size = UDim2.fromOffset(138, 4),\n\t                        Position = UDim2.fromOffset(12, 32),\n\t                        BackgroundColor3 = UIPallet.Main\n\t                    }, {\n\t                        Create(\"UICorner\", {CornerRadius = UDim.new(1, 0)}),\n\t                        Create(\"Frame\", {\n\t                            [Roact.Ref] = HealthbarProgress,\n\t                            Size = UDim2.fromScale(Percent, 1),\n\t                            BackgroundColor3 = Color3.fromHSV(math.clamp(Percent / 2.5, 0, 1), 0.89, 0.75)\n\t                        }, {Create(\"UICorner\", {CornerRadius = UDim.new(1, 0)})})\n\t                    })\n\t                })\n\t            }), Part)\n\t\n\t            HealthbarCleanup = function()\n\t                CleanCheck = false\n\t                self.healthbarBlockRef = nil\n\t                Roact.unmount(Mounted)\n\t                if self.healthbarPart then\n\t                    self.healthbarPart:Destroy()\n\t                end\n\t                self.healthbarPart = nil\n\t            end\n\t\n\t            bedwars.RuntimeLib.Promise.delay(5):andThen(function()\n\t                if CleanCheck then\n\t                    ClearHealthbar()\n\t                end\n\t            end)\n\t        end\n\t\n\t        local Progress: Frame? = HealthbarProgress and HealthbarProgress:getValue()\n\t        if not Progress then\n\t            return\n\t        end\n\t\n\t        local NewPercent: number = math.clamp((Health - ChangeHealth) / MaxHealth, 0, 1)\n\t        TweenService:Create(Progress, TweenInfo.new(0.3), {\n\t            Size = UDim2.fromScale(NewPercent, 1), BackgroundColor3 = Color3.fromHSV(math.clamp(NewPercent / 2.5, 0, 1), 0.89, 0.75)\n\t        }):Play()\n\t    end, function(...)\n\t        if shared.VapeDeveloper then\n\t            warn(...)\n\t        end\n\t    end)\n\tend\n\t\n\tlocal function GetContainedPositions(Block)\n\t    local Handler = bedwars.BlockController:getHandlerRegistry():getHandler(Block.Name)\n\t    return Handler and Handler:getContainedPositions(Block) or {bedwars.BlockController:getBlockPosition(Block.Position)}\n\tend\n\t\n\tlocal function GetBlockDistance(Block, LocalPosition: Vector3): number\n\t    local Closest: number = math.huge\n\t    for _, Position: Vector3 in GetContainedPositions(Block) do\n\t        if bedwars.BlockController:isBlockBreakable({blockPosition = Position}, LocalPlayer) then\n\t            Closest = math.min(Closest, (Position * 3 - LocalPosition).Magnitude)\n\t        end\n\t    end\n\t    return Closest\n\tend\n\t\n\tlocal function AttemptBreak(List, LocalPosition: Vector3, Route: boolean?, TeamCheck: boolean?)\n\t    if not List then\n\t        return\n\t    end\n\t\n\t    local Block, Closest = nil, math.huge\n\t    for _, v: BasePart in List do\n\t        local Distance: number = GetBlockDistance(v, LocalPosition)\n\t        if Distance >= Range.Value then\n\t            continue\n\t        end\n\t        if not SelfBreak.Enabled and v:GetAttribute(\"PlacedByUserId\") == LocalPlayer.UserId then\n\t            continue\n\t        end\n\t        if TeamCheck then\n\t            local Placer: Player? = Players:GetPlayerByUserId(v:GetAttribute(\"PlacedByUserId\") or 0)\n\t            if Placer and Placer:GetAttribute(\"Team\") == LocalPlayer:GetAttribute(\"Team\") then\n\t                continue\n\t            end\n\t        end\n\t        if v ~= ActiveBlock and Wallcheck.Enabled and not ClosestBreak.Enabled and ViewAngle.Value < 180 then\n\t            local Offset: Vector3 = v.Position - Camera.CFrame.Position\n\t            if Offset.Magnitude > 0 and math.deg(math.acos(math.clamp(Offset.Unit:Dot(Camera.CFrame.LookVector), -1, 1))) > ViewAngle.Value then\n\t                continue\n\t            end\n\t        end\n\t        if (v:GetAttribute(\"BedShieldEndTime\") or 0) > workspace:GetServerTimeNow() then\n\t            continue\n\t        end\n\t        if LimitItem.Enabled and not (Store.hand.tool and bedwars.ItemMeta[Store.hand.tool.Name] and bedwars.ItemMeta[Store.hand.tool.Name].breakBlock) then\n\t            continue\n\t        end\n\t        if PlayerCheck.Enabled and workspace:Raycast(Entity.character.Head.Position, v.Position - Entity.character.Head.Position, PlayerParams) then\n\t            continue\n\t        end\n\t\n\t        if v == ActiveBlock then\n\t            Block = v\n\t            break\n\t        end\n\t        if not ClosestBreak.Enabled or v == MouseHit then\n\t            if Distance < Closest then\n\t                Block, Closest = v, Distance\n\t            end\n\t            continue\n\t        end\n\t\n\t        local Offset: Vector3 = v.Position - MouseOrigin\n\t        local Along: number = Offset:Dot(MouseDirection)\n\t        local Spread: number = Along > 0 and (Offset - MouseDirection * Along).Magnitude or Offset.Magnitude\n\t        if Spread < Closest then\n\t            Block, Closest = v, Spread\n\t        end\n\t    end\n\t\n\t    if not Block then\n\t        return false\n\t    end\n\t\n\t    ActiveBlock = Block\n\t    if tick() < NextBreak then return true end\n\t    local BreakPosition, BreakPath, EndPosition, Requested = bedwars.breakBlock(Block, Effect.Enabled, Animation.Value ~= \"No Animation\" and Animation.Value or nil, CustomHealth.Enabled and CustomHealthbar or nil, AutoTool.Enabled, Wallcheck.Enabled, ClosestBreak.Enabled and BreakMethods.Distance or BreakMethods[Mode.Value], not Route, true, Session)\n\t    if Requested then NextBreak = tick() + BreakSpeed.Value end\n\t    local CurrentNode = BreakPosition\n\t    if CurrentNode or PathShown then\n\t        PathShown = CurrentNode ~= nil\n\t        for _, v: Part in Parts do\n\t            v.Position = CurrentNode or Vector3.zero\n\t            if CurrentNode then\n\t                v.BoxHandleAdornment.Color3 = CurrentNode == EndPosition and Color3.new(1, 0.2, 0.2) or CurrentNode == BreakPosition and Color3.new(0.2, 0.2, 1) or Color3.new(0.2, 1, 0.2)\n\t            end\n\t            CurrentNode = BreakPath and BreakPath[CurrentNode]\n\t        end\n\t    end\n\t\n\t    return BreakPosition ~= nil\n\tend\n\t\n\tNuker = vape.Categories.World:CreateModule({\n\t    Name = \"Nuker\",\n\t    ConfigName = \"Breaker\",\n\t    Function = function(Callback: boolean)\n\t        if Callback then\n\t            local Current = {}\n\t            Session = Current\n\t            ActiveBlock, NextBreak = nil, 0\n\t            for _ = 1, 30 do\n\t                local Part: Part = Instance.new(\"Part\")\n\t                Part.Anchored = true\n\t                Part.CanQuery = false\n\t                Part.CanCollide = false\n\t                Part.Transparency = 1\n\t                Part.Parent = Camera\n\t                local Highlight: BoxHandleAdornment = Instance.new(\"BoxHandleAdornment\")\n\t                Highlight.Size = Vector3.one\n\t                Highlight.AlwaysOnTop = true\n\t                Highlight.ZIndex = 1\n\t                Highlight.Transparency = 0.5\n\t                Highlight.Adornee = Part\n\t                Highlight.Parent = Part\n\t                table.insert(Parts, Part)\n\t            end\n\t\n\t            local Beds = Collection(\"bed\", Nuker)\n\t            local Teslas = Collection(\"tesla-trap\", Nuker)\n\t            local Hives = Collection(\"beehive\", Nuker)\n\t            local LuckyBlocks = Collection(\"LuckyBlock\", Nuker)\n\t            local IronOres = Collection(\"iron_ore_mesh_block\", Nuker)\n\t            CustomList = Collection(\"block\", Nuker, function(List, Object: Instance)\n\t                if table.find(Custom.ListEnabled, Object.Name) then\n\t                    table.insert(List, Object)\n\t                end\n\t            end)\n\t\n\t            repeat\n\t                task.wait(1 / UpdateRate.Value)\n\t                if not Nuker.Enabled or Session ~= Current then\n\t                    break\n\t                end\n\t                if Entity.isAlive then\n\t                    local LocalPosition: Vector3 = Entity.character.RootPart.Position\n\t\n\t                    if ClosestBreak.Enabled then\n\t                        local Ignore: {Instance} = {LocalPlayer.Character, Camera}\n\t                        for _, v: any in Entity.List do\n\t                            if v.Character then\n\t                                table.insert(Ignore, v.Character)\n\t                            end\n\t                        end\n\t                        MouseParams.FilterDescendantsInstances = Ignore\n\t                        MouseOrigin, MouseDirection = Mouse.UnitRay.Origin, Mouse.UnitRay.Direction\n\t                        local Result: RaycastResult? = workspace:Raycast(MouseOrigin, MouseDirection * 999, MouseParams)\n\t                        MouseHit = Result and Result.Instance or nil\n\t                    end\n\t                    if PlayerCheck.Enabled then\n\t                        local Characters: {Model} = {}\n\t                        for _, v: any in Entity.List do\n\t                            if v.Player and v.Character then\n\t                                table.insert(Characters, v.Character)\n\t                            end\n\t                        end\n\t                        PlayerParams.FilterDescendantsInstances = Characters\n\t                    end\n\t\n\t                    if AttemptBreak(Bed.Enabled and Beds, LocalPosition, true) then\n\t                        continue\n\t                    end\n\t                    if AttemptBreak(Hive.Enabled and Hives, LocalPosition, nil, true) then\n\t                        continue\n\t                    end\n\t                    if AttemptBreak(Tesla.Enabled and Teslas, LocalPosition, nil, true) then\n\t                        continue\n\t                    end\n\t                    if AttemptBreak(IronOre.Enabled and IronOres, LocalPosition) then\n\t                        continue\n\t                    end\n\t                    if AttemptBreak(LuckyBlock.Enabled and LuckyBlocks, LocalPosition) then\n\t                        continue\n\t                    end\n\t                    if AttemptBreak(CustomList, LocalPosition) then\n\t                        continue\n\t                    end\n\t\n\t                    ActiveBlock = nil\n\t                    if PathShown then\n\t                        PathShown = false\n\t                        for _, v: Part in Parts do\n\t                            v.Position = Vector3.zero\n\t                        end\n\t                    end\n\t                end\n\t            until not Nuker.Enabled or Session ~= Current\n\t        else\n\t            if Session then Session.Cancelled = true end\n\t            if Store.breakTool and Store.breakTool.session == Session then\n\t                Store.breakTool = nil\n\t            end\n\t            ActiveBlock = nil\n\t            ClearHealthbar()\n\t            for _, v: Part in Parts do\n\t                v:ClearAllChildren()\n\t                v:Destroy()\n\t            end\n\t            table.clear(Parts)\n\t            PathShown = false\n\t        end\n\t    end,\n\t    Tooltip = \"Break blocks around you automatically\"\n\t})\n\t\n\tMode = Nuker:CreateDropdown({\n\t    Name = \"Break mode\",\n\t    List = {\"Health\", \"Distance\"},\n\t    Default = \"Health\"\n\t})\n\tClosestBreak = Nuker:CreateToggle({\n\t    Name = \"Closest break\",\n\t    Function = function(Callback: boolean)\n\t        Mode.Object.Visible = not Callback\n\t    end,\n\t    Tooltip = \"Ignores the break mode and always takes the block nearest your crosshair, seeing straight through players\"\n\t})\n\tRange = Nuker:CreateSlider({\n\t    Name = \"Break range\",\n\t    Min = 1,\n\t    Max = 30,\n\t    Default = 30,\n\t    Suffix = function(Val: number)\n\t        return Val == 1 and \"stud\" or \"studs\"\n\t    end\n\t})\n\tBreakSpeed = Nuker:CreateSlider({\n\t    Name = \"Break speed\",\n\t    Min = 0,\n\t    Max = 0.3,\n\t    Default = 0.25,\n\t    Decimal = 100,\n\t    Suffix = \"seconds\"\n\t})\n\tUpdateRate = Nuker:CreateSlider({\n\t    Name = \"Update rate\",\n\t    Min = 1,\n\t    Max = 120,\n\t    Default = 60,\n\t    Suffix = \"hz\"\n\t})\n\tCustom = Nuker:CreateTextList({\n\t    Name = \"Custom\",\n\t    Function = function()\n\t        if not CustomList then\n\t            return\n\t        end\n\t        table.clear(CustomList)\n\t        for _, v: BasePart in Store.blocks do\n\t            if table.find(Custom.ListEnabled, v.Name) then\n\t                table.insert(CustomList, v)\n\t            end\n\t        end\n\t    end\n\t})\n\tBed = Nuker:CreateToggle({\n\t    Name = \"Break Bed\",\n\t    Default = true\n\t})\n\tTesla = Nuker:CreateToggle({\n\t    Name = \"Break Tesla\",\n\t    Default = true\n\t})\n\tHive = Nuker:CreateToggle({\n\t    Name = \"Break Hive\",\n\t    Default = true\n\t})\n\tLuckyBlock = Nuker:CreateToggle({\n\t    Name = \"Break Lucky Block\",\n\t    Default = true\n\t})\n\tIronOre = Nuker:CreateToggle({\n\t    Name = \"Break Iron Ore\",\n\t    Default = true\n\t})\n\tEffect = Nuker:CreateToggle({\n\t    Name = \"Show Healthbar & Effects\",\n\t    Function = function(Callback: boolean)\n\t        if CustomHealth.Object then\n\t            CustomHealth.Object.Visible = Callback\n\t        end\n\t    end,\n\t    Default = true\n\t})\n\tCustomHealth = Nuker:CreateToggle({\n\t    Name = \"Custom Healthbar\",\n\t    Default = true,\n\t    Darker = true\n\t})\n\tAnimation = Nuker:CreateDropdown({\n\t    Name = \"Animation Mode\",\n\t    List = {\"No Animation\", \"Minimal\", \"Full\"},\n\t    Tooltip = \"Minimal plays the tiny stub you get while macroing, Full plays the whole swing\"\n\t})\n\tSelfBreak = Nuker:CreateToggle({Name = \"Self Break\"})\n\tWallcheck = Nuker:CreateToggle({\n\t    Name = \"Legit mode\",\n\t    Function = function(Callback: boolean)\n\t        if ViewAngle then\n\t            ViewAngle.Object.Visible = Callback\n\t        end\n\t    end,\n\t    Default = true,\n\t    Tooltip = \"Checks for blocks inside the bed instead of directly targetting bed,\\nand only breaks what you are actually looking at\"\n\t})\n\tViewAngle = Nuker:CreateSlider({\n\t    Name = \"View angle\",\n\t    Min = 5,\n\t    Max = 180,\n\t    Default = 60,\n\t    Suffix = \"degrees\",\n\t    Darker = true,\n\t    Tooltip = \"How far off your crosshair a block can sit in legit mode, 180 breaks anything in range\"\n\t})\n\tAutoTool = Nuker:CreateToggle({\n\t    Name = \"Auto Tool\",\n\t    Tooltip = \"Visualises tool switching on ur client\"\n\t})\n\tLimitItem = Nuker:CreateToggle({\n\t    Name = \"Limit to items\",\n\t    Tooltip = \"Only breaks when tools are held\"\n\t})\n\tPlayerCheck = Nuker:CreateToggle({\n\t    Name = \"Player check\",\n\t    Tooltip = \"Skips a block while a player stands between you and it, so you dont mine through them\"\n\t})\nend)\n\nRun(function()\n\tlocal ArmorSwitch\n\tlocal Mode\n\tlocal Targets\n\tlocal Range\n\t\n\tArmorSwitch = vape.Categories.Inventory:CreateModule({\n\t    Name = \"ArmorSwitch\",\n\t    Function = function(Callback: boolean)\n\t        if Callback then\n\t            if Mode.Value == \"Toggle\" then\n\t                repeat\n\t                    local State: boolean = Entity.EntityPosition({\n\t                        Part = \"RootPart\",\n\t                        Range = Range.Value,\n\t                        Players = Targets.Players.Enabled,\n\t                        NPCs = Targets.NPCs.Enabled,\n\t                        Priority = Targets.Priority.Value,\n\t                        Wallcheck = Targets.Walls.Enabled\n\t                    }) and true or false\n\t\n\t                    for Slot: number = 0, 2 do\n\t                        if (Store.inventory.inventory.armor[Slot + 1] ~= \"empty\") ~= State and ArmorSwitch.Enabled then\n\t                            bedwars.Store:dispatch({\n\t                                type = \"InventorySetArmorItem\",\n\t                                item = Store.inventory.inventory.armor[Slot + 1] == \"empty\" and State and GetBestArmor(Slot) or nil,\n\t                                armorSlot = Slot\n\t                            })\n\t                            VapeEvents.InventoryChanged.Event:Wait()\n\t                        end\n\t                    end\n\t                    task.wait(0.1)\n\t                until not ArmorSwitch.Enabled\n\t            else\n\t                ArmorSwitch:Toggle()\n\t                for Slot: number = 0, 2 do\n\t                    bedwars.Store:dispatch({\n\t                        type = \"InventorySetArmorItem\",\n\t                        item = Store.inventory.inventory.armor[Slot + 1] == \"empty\" and GetBestArmor(Slot) or nil,\n\t                        armorSlot = Slot\n\t                    })\n\t                    VapeEvents.InventoryChanged.Event:Wait()\n\t                end\n\t            end\n\t        end\n\t    end,\n\t    Tooltip = \"Puts on / takes off armor when toggled for baiting.\"\n\t})\n\t\n\tMode = ArmorSwitch:CreateDropdown({\n\t    Name = \"Mode\",\n\t    List = {\"Toggle\", \"On Key\"}\n\t})\n\tTargets = ArmorSwitch:CreateTargets({\n\t    Players = true,\n\t    NPCs = true\n\t})\n\tRange = ArmorSwitch:CreateSlider({\n\t    Name = \"Range\",\n\t    Min = 1,\n\t    Max = 30,\n\t    Default = 30,\n\t    Suffix = function(Val: number)\n\t        return Val == 1 and \"stud\" or \"studs\"\n\t    end\n\t})\nend)\n\nRun(function()\n\tlocal AutoBank\n\tlocal Whitelist\n\tlocal Spectators\n\tlocal Display\n\tlocal UI\n\tlocal Mode\n\tlocal Nearby\n\tlocal Radius\n\tlocal BankBind\n\tlocal OnDeath\n\tlocal DeathItems\n\tlocal DeathWhitelist\n\tlocal Resources: {string} = {\"emerald\", \"diamond\", \"iron\", \"gold\"}\n\tlocal ManualHold: boolean = false\n\tlocal Returning: boolean = false\n\tlocal Dying: boolean = false\n\tlocal DeathCharacter: Model?\n\tlocal Damage, DamagedAt, PreviousHealth = 0, 0, 100\n\tlocal DeathUntil, FallingSince, GroundRefresh = 0, 0, 0\n\tlocal VoidParams: RaycastParams = RaycastParams.new()\n\tVoidParams.FilterType = Enum.RaycastFilterType.Include\n\tVoidParams.RespectCanCollide = true\n\tlocal Session = nil\n\tlocal Banked: {[BasePart]: CFrame} = {}\n\tlocal Dropping, FailedAt = {}, {}\n\tlocal Holds: {[string]: number} = {}\n\tlocal Items: {[string]: {Amount: number, Object: TextLabel}} = {}\n\tlocal DisplayAmounts: {[string]: number} = {}\n\tlocal Claimed: {[BasePart]: boolean} = setmetatable({}, {__mode = \"k\"})\n\tlocal Requests: {[BasePart]: number} = setmetatable({}, {__mode = \"k\"})\n\tlocal HideRandom: Random = Random.new()\n\tlocal Hidden: CFrame = CFrame.new(HideRandom:NextNumber(-1e6, 1e6), 1e5, HideRandom:NextNumber(-1e6, 1e6))\n\tlocal Slot: number = 0\n\t\n\tlocal function IsNearShop(): boolean\n\t    if not Entity.isAlive then\n\t        return false\n\t    end\n\t\n\t    local LocalPosition: Vector3 = Entity.character.RootPart.Position\n\t    for _, v: any in store.shop do\n\t        local Shopkeeper: PVInstance? = v.RootPart\n\t        if not (Shopkeeper and Shopkeeper.Parent) then\n\t            continue\n\t        end\n\t\n\t        local ShopPosition: Vector3 = Shopkeeper:IsA(\"BasePart\") and Shopkeeper.Position or Shopkeeper:GetPivot().Position\n\t        if (ShopPosition - LocalPosition).Magnitude <= 30 and (v.Upgrades or v.Shop) and not Entity.EntityPosition({\n\t            Origin = ShopPosition,\n\t            Range = 40,\n\t            Part = \"RootPart\",\n\t            Players = true\n\t        }) then\n\t            return true\n\t        end\n\t    end\n\t    return false\n\tend\n\t\n\tlocal function IsShopping(): boolean\n\t    return bedwars.AppController:isAppOpen(\"BedwarsItemShopApp\") or bedwars.AppController:isAppOpen(\"TeamUpgradeApp\") or false\n\tend\n\t\n\tlocal function GetSpectator(): Player?\n\t    local Team = LocalPlayer:GetAttribute(\"Team\")\n\t    for _, v: Player in Players:GetPlayers() do\n\t        if v == LocalPlayer or not (v:GetAttribute(\"Spectator\") or (v.Team and v.Team.Name == \"Spectators\")) then\n\t            continue\n\t        end\n\t        if not Team or v:GetAttribute(\"Team\") ~= Team then\n\t            return v\n\t        end\n\t    end\n\t    return nil\n\tend\n\t\n\tlocal function GetListName(ItemName: string): string\n\t    return ItemName:find(\"wool_\") and \"wool\" or ItemName\n\tend\n\t\n\tlocal function GetAmount(Part: BasePart): number\n\t    return Part:GetAttribute(\"Amount\") or 1\n\tend\n\t\n\tlocal function GetHeld(ItemType: string): number\n\t    local Item = getItem(ItemType)\n\t    return Item and Item.amount or 0\n\tend\n\t\n\tlocal function GetBanked(ItemType: string)\n\t    local Stacks, Total = {}, 0\n\t    for Part: BasePart in Banked do\n\t        if Part.Name == ItemType and Part.Parent == workspace.ItemDrops then\n\t            table.insert(Stacks, Part)\n\t            Total += GetAmount(Part)\n\t        end\n\t    end\n\t    return Stacks, Total\n\tend\n\t\n\tlocal function SortStacks(Stacks: {BasePart})\n\t    table.sort(Stacks, function(A: BasePart, B: BasePart): boolean\n\t        return GetAmount(A) > GetAmount(B)\n\t    end)\n\tend\n\t\n\tlocal function Bank(Part: Instance)\n\t    if not Part:IsA(\"BasePart\") or Banked[Part] then\n\t        return\n\t    end\n\t\n\t    Slot = (Slot + 1) % 64\n\t    Banked[Part] = Hidden + Vector3.new(Slot * 1200, 0, 0)\n\t    local Visibility: {[BasePart]: number} = {}\n\t    local function Hide(Object: Instance)\n\t        if Object:IsA(\"BasePart\") and Visibility[Object] == nil then\n\t            Visibility[Object] = Object.LocalTransparencyModifier\n\t            Object.LocalTransparencyModifier = 1\n\t        end\n\t    end\n\t\n\t    Hide(Part)\n\t    for _, v: Instance in Part:GetDescendants() do Hide(v) end\n\t    local Connection: RBXScriptConnection = Part.DescendantAdded:Connect(Hide)\n\t    Part.AssemblyLinearVelocity = Vector3.zero\n\t    Part.CFrame = Banked[Part]\n\t    Part.AncestryChanged:Once(function()\n\t        Banked[Part] = nil\n\t        Connection:Disconnect()\n\t        for Object: BasePart, Transparency: number in Visibility do\n\t            Object.LocalTransparencyModifier = Transparency\n\t        end\n\t    end)\n\tend\n\t\n\tlocal function Return(Part: BasePart)\n\t    if not Entity.isAlive or Dying then\n\t        return\n\t    end\n\t\n\t    Part.AssemblyLinearVelocity = Vector3.zero\n\t    Part.CFrame = Entity.character.Head.CFrame\n\t    if (Requests[Part] or 0) > tick() then\n\t        return\n\t    end\n\t\n\t    Requests[Part] = tick() + 1\n\t    task.spawn(function()\n\t        bedwars.Handler:Get(\"PickupItemDrop\"):Fire(\"CallServerAsync\", {\n\t            itemDrop = Part\n\t        }):andThen(function(Success)\n\t            Requests[Part] = nil\n\t            if Success then\n\t                Banked[Part] = nil\n\t            end\n\t        end)\n\t    end)\n\tend\n\t\n\tlocal function IsClear(): boolean\n\t    local Team: any = LocalPlayer:GetAttribute(\"Team\")\n\t    for _, v: Player in Players:GetPlayers() do\n\t        local Character: Model? = v.Character\n\t        local Root: BasePart? = Character and Character.PrimaryPart\n\t        if v == LocalPlayer or v:GetAttribute(\"Spectator\") or not Root or (Character:GetAttribute(\"Health\") or 0) <= 0 then\n\t            continue\n\t        end\n\t        local Teammate: boolean = Team ~= nil and v:GetAttribute(\"Team\") == Team\n\t        if (Nearby.Value == \"Everyone\" or Nearby.Value == \"Teammates\" and Teammate or Nearby.Value == \"Enemies\" and not Teammate) and (Root.Position - Entity.character.RootPart.Position).Magnitude <= Radius.Value * 3 then\n\t            return false\n\t        end\n\t    end\n\t    return true\n\tend\n\t\n\tlocal function IsDying(): boolean\n\t    if not OnDeath.Enabled or not Entity.isAlive then\n\t        FallingSince, DeathUntil = 0, 0\n\t        return false\n\t    end\n\t\n\t    local Health: number = LocalPlayer.Character:GetAttribute(\"Health\") or Entity.character.Health\n\t    if DeathCharacter ~= LocalPlayer.Character then\n\t        DeathCharacter = LocalPlayer.Character\n\t        PreviousHealth = Health\n\t        Damage, DamagedAt, FallingSince, DeathUntil = 0, 0, 0, 0\n\t    end\n\t    if Health < PreviousHealth then\n\t        Damage, DamagedAt = PreviousHealth - Health, tick()\n\t    end\n\t    PreviousHealth = Health\n\t    local Horizon: number = math.max(LocalPlayer:GetNetworkPing() * 2, store.ping.total or 0) + 0.2\n\t    if Health > 0 and tick() - DamagedAt < 1 and Health <= Damage * math.max(1, math.ceil(Horizon / 0.3)) and Entity.EntityPosition({Range = 25, Part = \"RootPart\", Players = true, NPCs = true}) then\n\t        DeathUntil = tick() + math.max(Horizon, 1)\n\t    end\n\t\n\t    local Velocity: Vector3 = Entity.character.RootPart.AssemblyLinearVelocity\n\t    if Velocity.Y < -20 and Entity.character.Humanoid.FloorMaterial == Enum.Material.Air and (LocalPlayer.Character:GetAttribute(\"InflatedBalloons\") or 0) <= 0 and not Entity.character.RootPart:FindFirstChild(\"OwlLiftForce\") then\n\t        if tick() >= GroundRefresh then\n\t            GroundRefresh = tick() + 2\n\t            VoidParams.FilterDescendantsInstances = store.map and {store.map} or store.blocks\n\t        end\n\t        local Position: Vector3 = Entity.character.RootPart.Position\n\t        local Distance: number = math.clamp(Position.Y - workspace.FallenPartsDestroyHeight, 512, 15000)\n\t        local Direction: Vector3 = Vector3.new(0, -Distance, 0)\n\t        local Ahead: Vector3 = Position + Velocity * Vector3.new(1, 0, 1) * Horizon\n\t        if not workspace:Raycast(Position, Direction, VoidParams) and not workspace:Raycast(Ahead, Direction, VoidParams) then\n\t            if FallingSince == 0 then FallingSince = tick() end\n\t            if tick() - FallingSince >= 0.12 then\n\t                DeathUntil = tick() + math.max(Horizon, 0.5)\n\t            end\n\t        else\n\t            FallingSince = 0\n\t        end\n\t    else\n\t        FallingSince = 0\n\t    end\n\t    return Health <= 0 or tick() < DeathUntil\n\tend\n\t\n\tlocal function DropItems(List: {string}, Current, Emergency: boolean?)\n\t    for _, v: any in store.inventory.inventory.items do\n\t        local ItemName: string? = v.tool and v.tool.Name or nil\n\t        if not ItemName or Dropping[ItemName] or not table.find(List, GetListName(ItemName)) or tick() - (FailedAt[ItemName] or 0) < (Emergency and 0.1 or 0.5) or not Emergency and (Holds[ItemName] or 0) > tick() then\n\t            continue\n\t        end\n\t        Dropping[ItemName] = true\n\t        task.spawn(function()\n\t            if not AutoBank.Enabled or Session ~= Current or not Entity.isAlive then\n\t                Dropping[ItemName] = nil\n\t                return\n\t            end\n\t            local Success, Part = pcall(function()\n\t                return bedwars.Handler:Get(\"DropItem\"):Fire(\"CallServer\", {item = v.tool, amount = v.amount})\n\t            end)\n\t            Dropping[ItemName] = nil\n\t            if Success and Part and Part:IsA(\"BasePart\") and Part.Parent then\n\t                Bank(Part)\n\t                if not AutoBank.Enabled and Entity.isAlive then Return(Part) end\n\t            elseif AutoBank.Enabled and Session == Current then\n\t                FailedAt[ItemName] = tick()\n\t            end\n\t        end)\n\t    end\n\tend\n\t\n\tlocal function CanHandBack(Currency: string, Price: number): boolean\n\t    local Held: number = GetHeld(Currency)\n\t    if Held >= Price then\n\t        return false\n\t    end\n\t\n\t    local _, Total = GetBanked(Currency)\n\t    return Held + Total >= Price\n\tend\n\t\n\tlocal function Cover(Currency: string, Price: number)\n\t    local Pulled: {BasePart} = {}\n\t    Holds[Currency] = tick() + 6\n\t\n\t    pcall(function()\n\t        local Stacks: {BasePart} = GetBanked(Currency)\n\t        SortStacks(Stacks)\n\t\n\t        local Needed: number = Price - GetHeld(Currency)\n\t        for _, v: BasePart in Stacks do\n\t            if Needed <= 0 then\n\t                break\n\t            end\n\t            Needed -= GetAmount(v)\n\t            Claimed[v] = true\n\t            table.insert(Pulled, v)\n\t        end\n\t\n\t        local Deadline: number = tick() + 3\n\t        repeat\n\t            for _, v: BasePart in Pulled do\n\t                if Banked[v] then\n\t                    Return(v)\n\t                end\n\t            end\n\t            task.wait()\n\t        until GetHeld(Currency) >= Price or tick() > Deadline or Dying or not (AutoBank.Enabled and Entity.isAlive)\n\t    end)\n\t\n\t    for _, v: BasePart in Pulled do\n\t        Claimed[v] = nil\n\t    end\n\t    Holds[Currency] = tick() + 3\n\tend\n\t\n\tlocal function HookPurchases()\n\t    local Remote = bedwars.Handler:Get(\"BedwarsPurchaseItem\").Remote\n\t    local Class = typeof(Remote) == \"table\" and getmetatable(Remote) or nil\n\t    local Promise = bedwars.RuntimeLib and bedwars.RuntimeLib.Promise\n\t    if typeof(Class) ~= \"table\" or typeof(rawget(Class, \"CallServerAsync\")) ~= \"function\" or typeof(Promise) ~= \"table\" or not Promise.new then\n\t        return\n\t    end\n\t\n\t    local OldCall = Class.CallServerAsync\n\t    local function Purchase(self, ...)\n\t        local Request: any = ...\n\t        local ShopItem: any = AutoBank.Enabled and self.name == \"BedwarsPurchaseItem\" and typeof(Request) == \"table\" and Request.shopItem or nil\n\t        if typeof(ShopItem) ~= \"table\" or typeof(ShopItem.currency) ~= \"string\" or typeof(ShopItem.price) ~= \"number\" then\n\t            return OldCall(self, ...)\n\t        end\n\t\n\t        Holds[ShopItem.currency] = tick() + 3\n\t        local Success, Needed = pcall(CanHandBack, ShopItem.currency, ShopItem.price)\n\t        if not (Success and Needed) then\n\t            return OldCall(self, ...)\n\t        end\n\t\n\t        local Arguments: {n: number} = table.pack(...)\n\t        return Promise.new(function(Resolve: (...any) -> ())\n\t            Cover(ShopItem.currency, ShopItem.price)\n\t            Resolve(OldCall(self, table.unpack(Arguments, 1, Arguments.n)))\n\t        end)\n\t    end\n\t\n\t    Class.CallServerAsync = Purchase\n\t    AutoBank:Clean(function()\n\t        if Class.CallServerAsync == Purchase then\n\t            Class.CallServerAsync = OldCall\n\t        end\n\t    end)\n\tend\n\t\n\tlocal function HookShopMenu()\n\t    local Controller = bedwars.BedwarsShopController\n\t    local OldStatus = Controller and Controller.getDisabledStatus\n\t    if typeof(OldStatus) ~= \"function\" then\n\t        return\n\t    end\n\t\n\t    local Previous = rawget(Controller, \"getDisabledStatus\")\n\t    local function Status(self, ShopItem: any, ...)\n\t        local Disabled: any = OldStatus(self, ShopItem, ...)\n\t        if typeof(Disabled) == \"table\" and Disabled.reason == \"Not Enough\" and typeof(ShopItem) == \"table\" and typeof(ShopItem.currency) == \"string\" and typeof(ShopItem.price) == \"number\" then\n\t            local Success, Covered = pcall(CanHandBack, ShopItem.currency, ShopItem.price)\n\t            if Success and Covered then\n\t                return nil\n\t            end\n\t        end\n\t        return Disabled\n\t    end\n\t\n\t    Controller.getDisabledStatus = Status\n\t    AutoBank:Clean(function()\n\t        if rawget(Controller, \"getDisabledStatus\") == Status then\n\t            Controller.getDisabledStatus = Previous\n\t        end\n\t    end)\n\tend\n\t\n\tlocal function Added(ItemType: string)\n\t    local Item: ImageLabel = Instance.new(\"ImageLabel\")\n\t    Item.Image = bedwars.getIcon({itemType = ItemType == \"wool\" and \"wool_white\" or ItemType}, true)\n\t    Item.Size = UDim2.fromOffset(32, 32)\n\t    Item.Name = ItemType\n\t    Item.BackgroundTransparency = 1\n\t    Item.LayoutOrder = #UI:GetChildren()\n\t    Item.Parent = UI\n\t    local ItemText: TextLabel = Instance.new(\"TextLabel\")\n\t    ItemText.Name = \"Amount\"\n\t    ItemText.Size = UDim2.fromScale(1, 1)\n\t    ItemText.BackgroundTransparency = 1\n\t    ItemText.Text = \"\"\n\t    ItemText.TextColor3 = Color3.new(1, 1, 1)\n\t    ItemText.TextSize = 16\n\t    ItemText.TextStrokeTransparency = 0.3\n\t    ItemText.Font = Enum.Font.Arial\n\t    ItemText.Parent = Item\n\t    Items[ItemType] = {Amount = -1, Object = ItemText}\n\tend\n\t\n\tlocal function RefreshItems()\n\t    if not UI then\n\t        return\n\t    end\n\t\n\t    for _, v: Instance in UI:GetChildren() do\n\t        if v:IsA(\"ImageLabel\") then\n\t            v:Destroy()\n\t        end\n\t    end\n\t    table.clear(Items)\n\t    local List: {string} = table.clone(Whitelist.ListEnabled)\n\t    if OnDeath and OnDeath.Enabled and DeathItems then\n\t        local DeathList: {string} = DeathItems.Value == \"Resources\" and Resources or DeathItems.Value == \"Whitelist\" and Whitelist.ListEnabled or DeathWhitelist.ListEnabled\n\t        for _, v: string in DeathList do table.insert(List, v) end\n\t    end\n\t    for _, v: string in List do\n\t        if not Items[v] then Added(v) end\n\t    end\n\tend\n\t\n\tlocal function UpdateDisplay()\n\t    local Hotbar = LocalPlayer.PlayerGui:FindFirstChild(\"hotbar\")\n\t    local HotbarFrame: Instance? = Hotbar and Hotbar:FindFirstChild(\"1\")\n\t    Hotbar = HotbarFrame and HotbarFrame:FindFirstChild(\"HotbarHealthbarContainer\")\n\t    if Hotbar then\n\t        UI.Position = UDim2.new(0.5, 0, 0, (Hotbar.AbsolutePosition.Y + GuiService:GetGuiInset().Y) - 60)\n\t    end\n\t\n\t    local Amounts: {[string]: number} = DisplayAmounts\n\t    table.clear(Amounts)\n\t    for Part: BasePart in Banked do\n\t        local ListName: string = GetListName(Part.Name)\n\t        Amounts[ListName] = (Amounts[ListName] or 0) + GetAmount(Part)\n\t    end\n\t    for ItemType: string, v: {Amount: number, Object: TextLabel} in Items do\n\t        local Amount: number = Amounts[ItemType] or 0\n\t        if v.Amount ~= Amount then\n\t            v.Amount = Amount\n\t            v.Object.Text = tostring(Amount)\n\t        end\n\t    end\n\tend\n\t\n\tAutoBank = vape.Categories.Inventory:CreateModule({\n\t    Name = \"AutoBank\",\n\t    Function = function(Callback: boolean)\n\t        if Callback then\n\t            local Current = {}\n\t            Session = Current\n\t            ManualHold, Returning, Dying = false, false, false\n\t            PreviousHealth = LocalPlayer.Character and LocalPlayer.Character:GetAttribute(\"Health\") or 100\n\t            DeathCharacter = LocalPlayer.Character\n\t            Damage, DamagedAt, GroundRefresh, FallingSince, DeathUntil = 0, 0, 0, 0, 0\n\t\n\t            UI = Instance.new(\"Frame\")\n\t            UI.Size = UDim2.new(1, 0, 0, 32)\n\t            UI.AnchorPoint = Vector2.new(0.5, 0)\n\t            UI.Position = UDim2.new(0.5, 0, 0, -240)\n\t            UI.BackgroundTransparency = 1\n\t            UI.Visible = Display.Enabled\n\t            if vape.ThreadFix then\n\t                setthreadidentity(8)\n\t            end\n\t            UI.Parent = vape.gui\n\t            AutoBank:Clean(UI)\n\t            local Sort: UIListLayout = Instance.new(\"UIListLayout\")\n\t            Sort.FillDirection = Enum.FillDirection.Horizontal\n\t            Sort.HorizontalAlignment = Enum.HorizontalAlignment.Center\n\t            Sort.SortOrder = Enum.SortOrder.LayoutOrder\n\t            Sort.Parent = UI\n\t            RefreshItems()\n\t\n\t            HookPurchases()\n\t            HookShopMenu()\n\t\n\t            local Drops: Instance = workspace.ItemDrops\n\t            AutoBank:Clean(RunService.PreSimulation:Connect(function()\n\t                Dying = IsDying()\n\t                if Dying then\n\t                    Returning = false\n\t                    if not (Spectators.Enabled and GetSpectator()) then\n\t                        local DeathList: {string} = DeathItems.Value == \"Resources\" and Resources or DeathItems.Value == \"Whitelist\" and Whitelist.ListEnabled or DeathWhitelist.ListEnabled\n\t                        DropItems(DeathList, Current, true)\n\t                    end\n\t                end\n\t                local Head: BasePart? = Entity.isAlive and Entity.character.Head or nil\n\t                for Part: BasePart, Spot: CFrame in Banked do\n\t                    if Part.Parent == Drops then\n\t                        Part.Transparency = 1\n\t                        Part.AssemblyLinearVelocity = Vector3.zero\n\t                        Part.CFrame = Head and not Dying and (Returning or Claimed[Part]) and Head.CFrame or Spot\n\t                    else\n\t                        Banked[Part] = nil\n\t                    end\n\t                end\n\t            end))\n\t\n\t            repeat\n\t                if Display.Enabled then\n\t                    UpdateDisplay()\n\t                end\n\t\n\t                local Spectator: Player? = Spectators.Enabled and GetSpectator() or nil\n\t                local NearShop: boolean = IsNearShop()\n\t                if not NearShop then ManualHold = false end\n\t                local Allowed: boolean = Mode.Value ~= \"Clear area\" or Entity.isAlive and IsClear()\n\t                if Entity.isAlive and (Dying or Spectator) then\n\t                    Returning = false\n\t                elseif Entity.isAlive and (ManualHold or not NearShop) then\n\t                    Returning = false\n\t                    if Mode.Value ~= \"Manual\" and Allowed and not IsShopping() then\n\t                        DropItems(Whitelist.ListEnabled, Current)\n\t                    end\n\t                elseif Entity.isAlive and Allowed then\n\t                    Returning = true\n\t                    local Stacks: {BasePart} = {}\n\t                    for Part: BasePart in Banked do\n\t                        table.insert(Stacks, Part)\n\t                    end\n\t                    SortStacks(Stacks)\n\t                    for _, v: BasePart in Stacks do\n\t                        Return(v)\n\t                    end\n\t                else\n\t                    Returning = false\n\t                end\n\t                task.wait(OnDeath.Enabled and 0.05 or 0.1)\n\t            until not AutoBank.Enabled or Session ~= Current\n\t        else\n\t            Dying = false\n\t            UI = nil\n\t            table.clear(Items)\n\t            repeat\n\t                if Entity.isAlive then\n\t                    for Part: BasePart in Banked do\n\t                        Return(Part)\n\t                    end\n\t                end\n\t                task.wait()\n\t            until AutoBank.Enabled or not next(Banked)\n\t        end\n\t    end,\n\t    Tooltip = \"Stores resources somewhere safe and gives them back near your shop\\nBuying while they are banked hands back just what the purchase needs, largest stacks first\\nClear area waits for your chosen players before automatic deposits or withdrawals; Bank now banks once when pressed\\nOn death protects items early during a void fall or predicted lethal follow-up; its item list is separate\\nNothing new gets banked while the shop menu is open\"\n\t})\n\t\n\tWhitelist = AutoBank:CreateTextList({\n\t    Name = \"Whitelist\",\n\t    Function = RefreshItems,\n\t    Default = {\"emerald\", \"diamond\", \"iron\"},\n\t    Tooltip = \"Items that get banked, wool covers every wool color\"\n\t})\n\tSpectators = AutoBank:CreateToggle({\n\t    Name = \"Spectator check\",\n\t    Tooltip = \"Pauses automatic deposits and withdrawals while an enemy or unteamed player is spectating\"\n\t})\n\tDisplay = AutoBank:CreateToggle({\n\t    Name = \"Display resources\",\n\t    Function = function(Callback: boolean)\n\t        if UI then\n\t            UI.Visible = Callback\n\t        end\n\t    end,\n\t    Default = true\n\t})\n\tMode = AutoBank:CreateDropdown({\n\t    Name = \"Bank mode\",\n\t    List = {\"Always\", \"Clear area\", \"Manual\"},\n\t    Default = \"Clear area\",\n\t    Tooltip = \"Always and Bank now can show a brief item drop; On death prioritizes saving your items\",\n\t    Function = function(Value: string)\n\t        if Nearby then Nearby.Object.Visible = Value == \"Clear area\" end\n\t        if Radius then Radius.Object.Visible = Value == \"Clear area\" end\n\t    end\n\t})\n\tNearby = AutoBank:CreateDropdown({\n\t    Name = \"Nearby players\",\n\t    List = {\"Everyone\", \"Enemies\", \"Teammates\"},\n\t    Default = \"Everyone\",\n\t    Visible = true,\n\t    Darker = true\n\t})\n\tRadius = AutoBank:CreateSlider({\n\t    Name = \"Clear radius\",\n\t    Min = 1,\n\t    Max = 50,\n\t    Default = 35,\n\t    Suffix = \"blocks\",\n\t    Visible = true,\n\t    Darker = true\n\t})\n\tBankBind = AutoBank:CreateBind({\n\t    Name = \"Bank now\",\n\t    Tooltip = \"Banks your whitelist once while enabled; near a shop, keeps it banked until you leave and return or make a purchase\"\n\t})\n\tvape:Clean(BankBind.Triggered:Connect(function(IsDown: boolean)\n\t    if IsDown and AutoBank.Enabled and Entity.isAlive and not IsShopping() and not (Spectators.Enabled and GetSpectator()) then\n\t        if #Whitelist.ListEnabled == 0 then\n\t            notif(\"AutoBank\", \"Select items in Whitelist before using Bank now\", 5, \"alert\")\n\t            return\n\t        end\n\t        ManualHold, Returning = IsNearShop(), false\n\t        DropItems(Whitelist.ListEnabled, Session, true)\n\t    end\n\tend))\n\tOnDeath = AutoBank:CreateToggle({\n\t    Name = \"On death\",\n\t    Function = function(Callback: boolean)\n\t        if DeathItems then DeathItems.Object.Visible = Callback end\n\t        if DeathWhitelist then DeathWhitelist.Object.Visible = Callback and DeathItems.Value == \"Custom\" end\n\t        RefreshItems()\n\t    end,\n\t    Tooltip = \"Banks the death item list before a predicted lethal hit or void fall, allowing time for your ping; spectator check still applies\"\n\t})\n\tDeathItems = AutoBank:CreateDropdown({\n\t    Name = \"Death items\",\n\t    List = {\"Resources\", \"Whitelist\", \"Custom\"},\n\t    Default = \"Resources\",\n\t    Function = function(Value: string)\n\t        if DeathWhitelist then DeathWhitelist.Object.Visible = OnDeath.Enabled and Value == \"Custom\" end\n\t        RefreshItems()\n\t    end,\n\t    Visible = false,\n\t    Darker = true,\n\t    Tooltip = \"Items to protect on predicted death; wool includes every color\"\n\t})\n\tDeathWhitelist = AutoBank:CreateTextList({\n\t    Name = \"Death whitelist\",\n\t    Default = {\"emerald\", \"diamond\", \"iron\", \"gold\"},\n\t    Function = RefreshItems,\n\t    Visible = false,\n\t    Darker = true,\n\t    Tooltip = \"Choose each item to protect when Death items is Custom; wool includes every color\"\n\t})\nend)\n\nRun(function()\n\tlocal AutoBuy\n\tlocal Session = nil\n\tlocal Sword\n\tlocal Armor\n\tlocal Upgrades\n\tlocal BedwarsCheck\n\tlocal GUI\n\tlocal SmartCheck\n\tlocal Custom = {}\n\tlocal CustomPost = {}\n\tlocal UpgradeToggles = {}\n\tlocal Functions, ShopId = {}\n\tlocal Callbacks = {Custom, Functions, CustomPost}\n\tlocal NPCTick: number = tick()\n\t\n\tlocal Swords: {string} = {\n\t    \"wood_sword\",\n\t    \"stone_sword\",\n\t    \"iron_sword\",\n\t    \"diamond_sword\",\n\t    \"emerald_sword\"\n\t}\n\t\n\tlocal Daos: {string} = {\n\t    \"wood_dao\",\n\t    \"stone_dao\",\n\t    \"iron_dao\",\n\t    \"diamond_dao\",\n\t    \"emerald_dao\"\n\t}\n\t\n\tlocal KitSwords: {[string]: string} = {\n\t    ice_queen = \"ice_sword\",\n\t    ember = \"infernal_saber\",\n\t    lumen = \"light_sword\"\n\t}\n\t\n\tlocal BedwarsQueues: {string} = {\n\t    \"combined_kit_to4\",\n\t    \"overpowered\",\n\t    \"hyper_gen_to4\",\n\t    \"all_random_kit_to4\",\n\t    \"all_same_kit_to4\"\n\t}\n\t\n\tlocal Armors: {string} = {\n\t    \"none\",\n\t    \"leather_chestplate\",\n\t    \"iron_chestplate\",\n\t    \"diamond_chestplate\",\n\t    \"emerald_chestplate\"\n\t}\n\t\n\tlocal Axes: {string} = {\n\t    \"none\",\n\t    \"wood_axe\",\n\t    \"stone_axe\",\n\t    \"iron_axe\",\n\t    \"diamond_axe\"\n\t}\n\t\n\tlocal Pickaxes: {string} = {\n\t    \"none\",\n\t    \"wood_pickaxe\",\n\t    \"stone_pickaxe\",\n\t    \"iron_pickaxe\",\n\t    \"diamond_pickaxe\"\n\t}\n\t\n\tlocal function HasKit(Kits: {string}?): boolean\n\t    if not Kits then\n\t        return false\n\t    end\n\t    for _, v: string in Store.equippedKits or {} do\n\t        if table.find(Kits, v) then\n\t            return true\n\t        end\n\t    end\n\t    return false\n\tend\n\t\n\tlocal function IsHidden(Item): boolean\n\t    if Item.requiresKit and #Item.requiresKit > 0 and not HasKit(Item.requiresKit) then\n\t        return true\n\t    end\n\t    if Item.ignoreAttribute and Item.ignoreAttribute ~= \"\" and LocalPlayer:GetAttribute(Item.ignoreAttribute) then\n\t        return true\n\t    end\n\t    if Item.requireAttribute and Item.requireAttribute ~= \"\" and not LocalPlayer:GetAttribute(Item.requireAttribute) then\n\t        return true\n\t    end\n\t    return HasKit(Item.ignoredByKit)\n\tend\n\t\n\tlocal function GetSwords(): {string}\n\t    if HasKit({\"dasher\"}) then\n\t        return Daos\n\t    end\n\t\n\t    for _, v: string in Store.equippedKits or {} do\n\t        if KitSwords[v] then\n\t            local List: {string} = table.clone(Swords)\n\t            List[5] = KitSwords[v]\n\t            return List\n\t        end\n\t    end\n\t\n\t    return Swords\n\tend\n\t\n\tlocal function GetShopNPC()\n\t    local Shop, ItemShop, UpgradeShop, NewId = nil, false, false, nil\n\t    if Entity.isAlive then\n\t        local LocalPosition: Vector3 = Entity.character.RootPart.Position\n\t        for _, v: any in Store.shop do\n\t            if (v.RootPart.Position - LocalPosition).Magnitude <= 20 then\n\t                Shop = v.Upgrades or v.Shop or nil\n\t                UpgradeShop = UpgradeShop or v.Upgrades\n\t                ItemShop = ItemShop or v.Shop\n\t                NewId = v.Shop and v.Id or NewId\n\t            end\n\t        end\n\t    end\n\t    return Shop, ItemShop, UpgradeShop, NewId\n\tend\n\t\n\tlocal function CanBuy(Item, CurrencyTable, Amount: number?): boolean\n\t    Amount = Amount or 1\n\t    if not CurrencyTable[Item.currency] then\n\t        local Currency = GetItem(Item.currency)\n\t        CurrencyTable[Item.currency] = Currency and Currency.amount or 0\n\t    end\n\t    if IsHidden(Item) then\n\t        return false\n\t    end\n\t    if Item.lockedByForge or Item.disabled then\n\t        return false\n\t    end\n\t    if Item.require and Item.require.teamUpgrade then\n\t        if (bedwars.Store:getState().Bedwars.teamUpgrades[Item.require.teamUpgrade.upgradeId] or -1) < Item.require.teamUpgrade.lowestTierIndex then\n\t            return false\n\t        end\n\t    end\n\t    return CurrencyTable[Item.currency] >= (Item.price * Amount)\n\tend\n\t\n\tlocal function BuyItem(Item, CurrencyTable)\n\t    if not ShopId then\n\t        return\n\t    end\n\t    bedwars.Handler:Get(\"BedwarsPurchaseItem\"):Fire(\"CallServerAsync\", {\n\t        shopItem = Item,\n\t        shopId = ShopId\n\t    }):andThen(function(Success)\n\t        if Success then\n\t            local Meta = bedwars.ItemMeta[Item.itemType]\n\t            SendNotification(\"AutoBuy\", `Bought {Meta and Meta.displayName or Item.itemType}`, 3)\n\t            bedwars.AudioManager:playAudio(bedwars.SoundList.BEDWARS_PURCHASE_ITEM)\n\t            bedwars.Store:dispatch({\n\t                type = \"BedwarsAddItemPurchased\",\n\t                itemType = Item.itemType\n\t            })\n\t            if Item.tiered and not Item.nextTier then\n\t                bedwars.BedwarsShopController.alreadyPurchasedMap[Item.itemType] = true\n\t            end\n\t        end\n\t    end)\n\t    CurrencyTable[Item.currency] -= Item.price\n\tend\n\t\n\tlocal function BuyTool(Tool, Tools: {string}, CurrencyTable): boolean\n\t    local Bought, Buyable = false\n\t    Tool = Tool and table.find(Tools, Tool.itemType) and table.find(Tools, Tool.itemType) + 1 or math.huge\n\t\n\t    for i: number = Tool, #Tools do\n\t        local ShopItem = bedwars.Shop.getShopItem(Tools[i], LocalPlayer)\n\t        if not ShopItem or IsHidden(ShopItem) then\n\t            continue\n\t        end\n\t\n\t        if CanBuy(ShopItem, CurrencyTable) then\n\t            local Meta = bedwars.ItemMeta[Tools[i]]\n\t            if SmartCheck.Enabled and Meta and Meta.breakBlock and i > 2 then\n\t                if Armor.Enabled then\n\t                    local CurrentArmor = Store.inventory.inventory.armor[2]\n\t                    CurrentArmor = CurrentArmor and CurrentArmor ~= \"empty\" and CurrentArmor.itemType or \"none\"\n\t                    if (table.find(Armors, CurrentArmor) or 3) < 3 then\n\t                        break\n\t                    end\n\t                end\n\t                if Sword.Enabled then\n\t                    if Store.tools.sword and (table.find(GetSwords(), Store.tools.sword.itemType) or 2) < 2 then\n\t                        break\n\t                    end\n\t                end\n\t            end\n\t            Bought = true\n\t            Buyable = ShopItem\n\t        end\n\t        if ShopItem.nextTier then\n\t            break\n\t        end\n\t    end\n\t\n\t    if Buyable then\n\t        BuyItem(Buyable, CurrencyTable)\n\t    end\n\t\n\t    return Bought\n\tend\n\t\n\tAutoBuy = vape.Categories.Inventory:CreateModule({\n\t    Name = \"AutoBuy\",\n\t    Function = function(Callback: boolean)\n\t        if Callback then\n\t            local Current = {}\n\t            Session = Current\n\t            repeat\n\t                task.wait()\n\t            until Store.queueType ~= \"bedwars_test\"\n\t            if Session ~= Current then\n\t                return\n\t            end\n\t            if BedwarsCheck.Enabled and not (Store.queueType:find(\"bedwars\") or table.find(BedwarsQueues, Store.queueType)) then\n\t                return\n\t            end\n\t\n\t            local LastUpgradeShop\n\t            AutoBuy:Clean(VapeEvents.InventoryAmountChanged.Event:Connect(function()\n\t                if (NPCTick - tick()) > 1 then\n\t                    NPCTick = tick()\n\t                end\n\t            end))\n\t\n\t            repeat\n\t                local NPC, ItemShop, UpgradeShop, NewId = GetShopNPC()\n\t                ShopId = NewId\n\t                local MenuOpen: boolean = bedwars.AppController:isAppOpen(\"BedwarsItemShopApp\") or bedwars.AppController:isAppOpen(\"TeamUpgradeApp\")\n\t                if (GUI.Enabled and not MenuOpen) or (not GUI.Enabled and MenuOpen) then\n\t                    NPC = nil\n\t                end\n\t\n\t                if NPC and LastUpgradeShop ~= UpgradeShop then\n\t                    if (NPCTick - tick()) > 1 then\n\t                        NPCTick = tick()\n\t                    end\n\t                    LastUpgradeShop = UpgradeShop\n\t                end\n\t\n\t                if NPC and NPCTick <= tick() and Store.matchState ~= 2 and Store.shopLoaded and not (vape.Modules.AutoWin or {}).Enabled then\n\t                    local CurrencyTable = {}\n\t                    local WaitCheck\n\t                    for _, v: {(...any) -> ...any} in Callbacks do\n\t                        for _, BuyFunction: (...any) -> ...any in v do\n\t                            local Success, Bought = pcall(BuyFunction, CurrencyTable, ItemShop, UpgradeShop)\n\t                            if Success and Bought then\n\t                                WaitCheck = true\n\t                            end\n\t                        end\n\t                    end\n\t                    NPCTick = tick() + (WaitCheck and 0.4 or math.huge)\n\t                end\n\t\n\t                task.wait(0.1)\n\t            until not AutoBuy.Enabled or Session ~= Current\n\t        else\n\t            NPCTick = tick()\n\t        end\n\t    end,\n\t    Tooltip = \"Automatically buys items when you go near the shop\"\n\t})\n\t\n\tSword = AutoBuy:CreateToggle({\n\t    Name = \"Buy Sword\",\n\t    Function = function(Callback: boolean)\n\t        NPCTick = tick()\n\t        Functions[2] = Callback and function(CurrencyTable, Shop)\n\t            if not Shop then\n\t                return\n\t            end\n\t\n\t            return BuyTool(Store.tools.sword, GetSwords(), CurrencyTable)\n\t        end or nil\n\t    end\n\t})\n\tArmor = AutoBuy:CreateToggle({\n\t    Name = \"Buy Armor\",\n\t    Function = function(Callback: boolean)\n\t        NPCTick = tick()\n\t        Functions[1] = Callback and function(CurrencyTable, Shop)\n\t            if not Shop then\n\t                return\n\t            end\n\t            local CurrentArmor = Store.inventory.inventory.armor[2] ~= \"empty\" and Store.inventory.inventory.armor[2] or GetBestArmor(1)\n\t            CurrentArmor = CurrentArmor and CurrentArmor.itemType or \"none\"\n\t            return BuyTool({itemType = CurrentArmor}, Armors, CurrencyTable)\n\t        end or nil\n\t    end,\n\t    Default = true\n\t})\n\tAutoBuy:CreateToggle({\n\t    Name = \"Buy Axe\",\n\t    Function = function(Callback: boolean)\n\t        NPCTick = tick()\n\t        Functions[3] = Callback and function(CurrencyTable, Shop)\n\t            if not Shop then\n\t                return\n\t            end\n\t            return BuyTool(Store.tools.wood or {itemType = \"none\"}, Axes, CurrencyTable)\n\t        end or nil\n\t    end\n\t})\n\tAutoBuy:CreateToggle({\n\t    Name = \"Buy Pickaxe\",\n\t    Function = function(Callback: boolean)\n\t        NPCTick = tick()\n\t        Functions[4] = Callback and function(CurrencyTable, Shop)\n\t            if not Shop then\n\t                return\n\t            end\n\t            return BuyTool(Store.tools.stone, Pickaxes, CurrencyTable)\n\t        end or nil\n\t    end\n\t})\n\tUpgrades = AutoBuy:CreateToggle({\n\t    Name = \"Buy Upgrades\",\n\t    Function = function(Callback: boolean)\n\t        for _, v: any in UpgradeToggles do\n\t            v.Object.Visible = Callback\n\t        end\n\t    end,\n\t    Default = true\n\t})\n\tlocal Count: number = 0\n\tfor UpgradeId: string, v: any in bedwars.TeamUpgradeMeta do\n\t    local ToggleCount: number = Count\n\t    table.insert(UpgradeToggles, AutoBuy:CreateToggle({\n\t        Name = `Buy {v.name == \"Armor\" and \"Protection\" or v.name}`,\n\t        Function = function(Callback: boolean)\n\t            NPCTick = tick()\n\t            Functions[5 + ToggleCount + (v.name == \"Armor\" and 20 or 0)] = Callback and function(CurrencyTable, Shop, UpgradeShop)\n\t                if not UpgradeShop or not Upgrades.Enabled then\n\t                    return\n\t                end\n\t                if v.disabledInQueue and table.find(v.disabledInQueue, Store.queueType) then\n\t                    return\n\t                end\n\t\n\t                local CurrentUpgrades = bedwars.Store:getState().Bedwars.teamUpgrades[LocalPlayer:GetAttribute(\"Team\")] or {}\n\t                local Bought: boolean = false\n\t                for TierIndex: number = (CurrentUpgrades[UpgradeId] or 0) + 1, #v.tiers do\n\t                    local Tier = v.tiers[TierIndex]\n\t                    if Tier.availableOnlyInQueue and not table.find(Tier.availableOnlyInQueue, Store.queueType) then\n\t                        continue\n\t                    end\n\t                    if not CanBuy({currency = \"diamond\", price = Tier.cost}, CurrencyTable) then\n\t                        break\n\t                    end\n\t\n\t                    bedwars.Handler:Get(\"RequestPurchaseTeamUpgrade\"):Fire(\"CallServerAsync\", UpgradeId):andThen(function(Success)\n\t                        if Success then\n\t                            SendNotification(\"AutoBuy\", `Bought {v.name == \"Armor\" and \"Protection\" or v.name} {TierIndex}`, 3)\n\t                        end\n\t                    end)\n\t                    CurrencyTable.diamond -= Tier.cost\n\t                    Bought = true\n\t                end\n\t\n\t                return Bought\n\t            end or nil\n\t        end,\n\t        Darker = true,\n\t        Default = (UpgradeId == \"ARMOR\" or UpgradeId == \"DAMAGE\")\n\t    }))\n\t    Count += 1\n\tend\n\tBedwarsCheck = AutoBuy:CreateToggle({\n\t    Name = \"Only Bedwars\",\n\t    Function = function()\n\t        if AutoBuy.Enabled then\n\t            AutoBuy:Toggle()\n\t            AutoBuy:Toggle()\n\t        end\n\t    end,\n\t    Default = true,\n\t    Tooltip = \"Only buys in BedWars modes, including Kit Fusion and Hyper Kits\"\n\t})\n\tGUI = AutoBuy:CreateToggle({\n\t    Name = \"GUI check\",\n\t    Tooltip = \"On: only buys while the shop menu is open. Off: pauses while the shop menu is open so it never fights your own purchases\"\n\t})\n\tSmartCheck = AutoBuy:CreateToggle({\n\t    Name = \"Smart check\",\n\t    Default = true,\n\t    Tooltip = \"Buys iron armor before iron axe\"\n\t})\n\tAutoBuy:CreateTextList({\n\t    Name = \"Item\",\n\t    Placeholder = \"priority/item/amount/after\",\n\t    Function = function(List: {string})\n\t        table.clear(Custom)\n\t        table.clear(CustomPost)\n\t        for _, v: string in List do\n\t            local Fields: {string} = v:split(\"/\")\n\t            local Priority: number? = tonumber(Fields[1])\n\t            if Priority then\n\t                (Fields[4] and CustomPost or Custom)[Priority] = function(CurrencyTable, Shop)\n\t                    if not Shop then\n\t                        return\n\t                    end\n\t\n\t                    local Item = bedwars.Shop.getShopItem(Fields[2], LocalPlayer)\n\t                    local Amount: number? = tonumber(Fields[3])\n\t                    if Item and Amount then\n\t                        local Held = GetItem(Fields[2] == \"wool_white\" and bedwars.Shop.getTeamWoolById(LocalPlayer:GetAttribute(\"Team\")) or Fields[2])\n\t                        Held = (Held and Amount - Held.amount or Amount) // math.max(Item.amount, 1)\n\t                        if Held > 0 and CanBuy(Item, CurrencyTable, Held) then\n\t                            for _ = 1, Held do\n\t                                BuyItem(Item, CurrencyTable)\n\t                            end\n\t                            return true\n\t                        end\n\t                    end\n\t                end\n\t            end\n\t        end\n\t    end\n\t})\nend)\n\nRun(function()\n\tlocal AutoChestSplit\n\tlocal Items\n\tlocal Range\n\tlocal Minimum\n\tlocal EnemyOnly\n\tlocal Delay\n\tlocal NextDeposit: number = 0\n\t\n\tlocal function GetChest(LocalPosition: Vector3): BasePart?\n\t    for _, v: Instance in CollectionService:GetTagged(\"personal-chest\") do\n\t        local Part: BasePart? = not v:IsA(\"Model\") and v or (v.PrimaryPart or v:FindFirstChildWhichIsA(\"BasePart\", true))\n\t        if Part and (Part.Position - LocalPosition).Magnitude <= Range.Value then\n\t            return Part\n\t        end\n\t    end\n\t    return nil\n\tend\n\t\n\tlocal function InEnemyBase(LocalPosition: Vector3): boolean\n\t    local Team = LocalPlayer:GetAttribute(\"Team\")\n\t    local Closest, Distance = nil, math.huge\n\t\n\t    for _, v: Instance in CollectionService:GetTagged(\"team-crate\") do\n\t        local Part: BasePart? = not v:IsA(\"Model\") and v or (v.PrimaryPart or v:FindFirstChildWhichIsA(\"BasePart\", true))\n\t        local PartDistance: number = Part and (Part.Position - LocalPosition).Magnitude or math.huge\n\t        if PartDistance < Distance then\n\t            Closest, Distance = v, PartDistance\n\t        end\n\t    end\n\t    return Closest ~= nil and Closest:GetAttribute(\"Team\") ~= Team\n\tend\n\t\n\tlocal function DepositSplit()\n\t    local Inventory: Instance? = ReplicatedStorage:FindFirstChild(\"Inventories\")\n\t    Inventory = Inventory and Inventory:FindFirstChild(`{LocalPlayer.Name}_personal`) or nil\n\t    if not Inventory then\n\t        return\n\t    end\n\t\n\t    for _, v: string in Items.ListEnabled do\n\t        local Item = getItem(v)\n\t        if Item and (Item.amount or 1) >= Minimum.Value then\n\t            task.spawn(function()\n\t                bedwars.Client:GetNamespace(\"Inventory\"):Get(\"ChestGiveItem\"):CallServer(Inventory, Item.tool)\n\t            end)\n\t        end\n\t    end\n\tend\n\t\n\tAutoChestSplit = vape.Categories.Inventory:CreateModule({\n\t    Name = \"AutoChestSplit\",\n\t    Function = function(Callback: boolean)\n\t        if Callback then\n\t            NextDeposit = 0\n\t\n\t            repeat\n\t                task.wait()\n\t            until store.matchState ~= 0 or (not AutoChestSplit.Enabled)\n\t            if not AutoChestSplit.Enabled then\n\t                return\n\t            end\n\t\n\t            repeat\n\t                if Entity.isAlive and tick() >= NextDeposit and #Items.ListEnabled > 0 then\n\t                    local LocalPosition: Vector3 = Entity.character.RootPart.Position\n\t                    if GetChest(LocalPosition) and (not EnemyOnly.Enabled or InEnemyBase(LocalPosition)) then\n\t                        NextDeposit = tick() + Delay.Value\n\t                        DepositSplit()\n\t                    end\n\t                end\n\t                task.wait(0.1)\n\t            until not AutoChestSplit.Enabled\n\t        end\n\t    end,\n\t    Tooltip = \"Banks the split in your personal chest the moment you are stood at one\"\n\t})\n\t\n\tItems = AutoChestSplit:CreateTextList({\n\t    Name = \"Items\",\n\t    Default = {\"diamond\", \"emerald\"},\n\t    Tooltip = \"What counts as the split\"\n\t})\n\tRange = AutoChestSplit:CreateSlider({\n\t    Name = \"Range\",\n\t    Min = 1,\n\t    Max = 18,\n\t    Default = 18,\n\t    Suffix = function(Val: number)\n\t        return Val <= 1 and \"stud\" or \"studs\"\n\t    end,\n\t    Tooltip = \"How close to the chest you have to be, the game itself stops at 18\"\n\t})\n\tMinimum = AutoChestSplit:CreateSlider({\n\t    Name = \"Minimum\",\n\t    Min = 1,\n\t    Max = 64,\n\t    Default = 1,\n\t    Tooltip = \"Leaves the stack alone until you are holding this many\"\n\t})\n\tEnemyOnly = AutoChestSplit:CreateToggle({\n\t    Name = \"Enemy base only\",\n\t    Default = true,\n\t    Tooltip = \"Only banks at a chest that is closer to their generator than yours\"\n\t})\n\tDelay = AutoChestSplit:CreateSlider({\n\t    Name = \"Delay\",\n\t    Min = 0,\n\t    Max = 5,\n\t    Decimal = 10,\n\t    Default = 0.5,\n\t    Suffix = \"seconds\"\n\t})\nend)\n\nRun(function()\n\tlocal AutoConsume\n\tlocal Health\n\tlocal SpeedPotion\n\tlocal Apple\n\tlocal ShieldPotion\n\t\n\tlocal function ConsumeCheck(Attribute: string?)\n\t    if Entity.isAlive then\n\t        if SpeedPotion.Enabled and (not Attribute or Attribute == \"StatusEffect_speed\") then\n\t            local SpeedPotionItem = GetItem(\"speed_potion\")\n\t            if SpeedPotionItem and (not LocalPlayer.Character:GetAttribute(\"StatusEffect_speed\")) then\n\t                for _ = 1, 4 do\n\t                    if bedwars.Handler:Get(\"ConsumeItem\"):Fire(\"CallServer\", {item = SpeedPotionItem.tool}) then\n\t                        break\n\t                    end\n\t                end\n\t            end\n\t        end\n\t\n\t        if Apple.Enabled and (not Attribute or Attribute:find(\"Health\")) then\n\t            if (LocalPlayer.Character:GetAttribute(\"Health\") / LocalPlayer.Character:GetAttribute(\"MaxHealth\")) <= (Health.Value / 100) then\n\t                local AppleItem = GetItem(\"orange\") or (not LocalPlayer.Character:GetAttribute(\"StatusEffect_golden_apple\") and GetItem(\"golden_apple\")) or GetItem(\"apple\")\n\t                if AppleItem then\n\t                    bedwars.Handler:Get(\"ConsumeItem\"):Fire(\"CallServerAsync\", {\n\t                        item = AppleItem.tool\n\t                    })\n\t                end\n\t            end\n\t        end\n\t\n\t        if ShieldPotion.Enabled and (not Attribute or Attribute:find(\"Shield\")) then\n\t            if (LocalPlayer.Character:GetAttribute(\"Shield_POTION\") or 0) == 0 then\n\t                local ShieldItem = GetItem(\"big_shield\") or GetItem(\"mini_shield\")\n\t                if ShieldItem then\n\t                    bedwars.Handler:Get(\"ConsumeItem\"):Fire(\"CallServerAsync\", {\n\t                        item = ShieldItem.tool\n\t                    })\n\t                end\n\t            end\n\t        end\n\t    end\n\tend\n\t\n\tAutoConsume = vape.Categories.Inventory:CreateModule({\n\t    Name = \"AutoConsume\",\n\t    Function = function(Callback: boolean)\n\t        if Callback then\n\t            AutoConsume:Clean(VapeEvents.InventoryAmountChanged.Event:Connect(ConsumeCheck))\n\t            AutoConsume:Clean(VapeEvents.AttributeChanged.Event:Connect(function(Attribute: string)\n\t                if Attribute:find(\"Shield\") or Attribute:find(\"Health\") or Attribute == \"StatusEffect_speed\" then\n\t                    ConsumeCheck(Attribute)\n\t                end\n\t            end))\n\t            ConsumeCheck()\n\t        end\n\t    end,\n\t    Tooltip = \"Automatically heals for you when health or shield is under threshold.\"\n\t})\n\t\n\tHealth = AutoConsume:CreateSlider({\n\t    Name = \"Health Percent\",\n\t    Min = 1,\n\t    Max = 99,\n\t    Default = 70,\n\t    Suffix = \"%\"\n\t})\n\tSpeedPotion = AutoConsume:CreateToggle({\n\t    Name = \"Speed Potions\",\n\t    Default = true\n\t})\n\tApple = AutoConsume:CreateToggle({\n\t    Name = \"Apple\",\n\t    Default = true\n\t})\n\tShieldPotion = AutoConsume:CreateToggle({\n\t    Name = \"Shield Potions\",\n\t    Default = true\n\t})\nend)\n\nRun(function()\n\tlocal AutoFish\n\tlocal Show\n\tlocal Blacklist\n\tlocal Minigame\n\tlocal MinigameMode = {}\n\tlocal CompleteDelay = {}\n\tlocal Reaction = {}\n\tlocal Clicks = {}\n\tlocal Cast\n\tlocal CastDelay = {}\n\tlocal GUI\n\tlocal Rejects: {Vector3} = {}\n\t\n\tlocal Old\n\t\n\tlocal function IsMenuOpen(): boolean\n\t    return GUI.Enabled and bedwars.AppController:isLayerOpen(bedwars.UILayers.MAIN)\n\tend\n\t\n\tlocal function GetBobber(): Instance?\n\t    for _, v: Instance in workspace:GetChildren() do\n\t        if v.Name == \"fisherman_bobber\" and v:GetAttribute(\"ProjectileShooter\") == LocalPlayer.UserId then\n\t            return v\n\t        end\n\t    end\n\t    return nil\n\tend\n\t\n\tlocal function GetCastSpot(): Vector3?\n\t    local LocalPosition: Vector3 = Entity.character.RootPart.Position\n\t    local OpenSpot: Vector3?\n\t\n\t    for Distance: number = 5, 17, 3 do\n\t        for Angle: number = 0, 330, 30 do\n\t            local Spot: Vector3 = LocalPosition + (CFrame.Angles(0, math.rad(Angle), 0).LookVector * Distance)\n\t            local RayResult = Entity.Raycast(Spot + Vector3.new(0, 8, 0), Vector3.new(0, -26, 0), Store.airRay)\n\t            local CheckPosition: Vector3 = RayResult and RayResult.Position or Spot\n\t            local Rejected: boolean = false\n\t            for _, v: Vector3 in Rejects do\n\t                if (v - CheckPosition).Magnitude < 4 then\n\t                    Rejected = true\n\t                    break\n\t                end\n\t            end\n\t\n\t            if not RayResult then\n\t                if not OpenSpot and not Rejected then\n\t                    OpenSpot = Spot\n\t                end\n\t            elseif RayResult.Material == Enum.Material.Water and not Rejected then\n\t                return RayResult.Position\n\t            end\n\t        end\n\t    end\n\t    return OpenSpot\n\tend\n\t\n\tlocal function PlayMinigame()\n\t    local FishermanUtil = bedwars.FishermanUtil\n\t    local Marker, Zone\n\t    local Deadline: number = tick() + 3\n\t    repeat\n\t        for _, v: Instance in LocalPlayer.PlayerGui:GetDescendants() do\n\t            if v.Name == \"Marker\" and v.Parent and v.Parent.Name == \"Minigame\" then\n\t                local FoundZone: Instance? = v.Parent:FindFirstChild(\"FishZone\")\n\t                if FoundZone then\n\t                    Marker, Zone = v, FoundZone\n\t                    break\n\t                end\n\t            end\n\t        end\n\t        if not Marker then\n\t            task.wait()\n\t        end\n\t    until Marker or tick() > Deadline\n\t    if not Marker then\n\t        return\n\t    end\n\t\n\t    local Speed, AimOffset = FishermanUtil.startingMarkerIncrementSpeed, 0\n\t    repeat\n\t        if not Marker.Parent or not Zone.Parent then\n\t            return\n\t        end\n\t\n\t        if IsMenuOpen() then\n\t            TweenService:Create(Marker, TweenInfo.new(FishermanUtil.totalDecaySpeedSec * (Marker.Position.X.Scale + Marker.Size.X.Scale), Enum.EasingStyle.Linear), {\n\t                Position = UDim2.new(0, 2, 0.5, 0)\n\t            }):Play()\n\t            Speed = FishermanUtil.startingMarkerIncrementSpeed\n\t            repeat\n\t                task.wait(0.1)\n\t            until not IsMenuOpen() or not Marker.Parent or not AutoFish.Enabled or not Minigame.Enabled\n\t            continue\n\t        end\n\t\n\t        local Width: number = Marker.AbsoluteSize.X\n\t        local Center: number = Marker.AbsolutePosition.X + (Width / 2)\n\t        local Delta: number = ((Zone.AbsolutePosition.X + (Zone.AbsoluteSize.X / 2) + AimOffset) - Center) / math.max(Width, 1)\n\t        if Delta > 0.2 then\n\t            TweenService:Create(Marker, TweenInfo.new(math.max(Speed, FishermanUtil.holdMinimumMarkerIncrementSpeed), Enum.EasingStyle.Linear), {\n\t                Position = UDim2.new(math.min(Marker.Position.X.Scale + FishermanUtil.markerIncrementAmount, 1 - Marker.Size.X.Scale), 0, 0.5, 0)\n\t            }):Play()\n\t            Speed -= 0.01\n\t            task.wait(0.05)\n\t        elseif Delta < -0.2 then\n\t            TweenService:Create(Marker, TweenInfo.new(FishermanUtil.totalDecaySpeedSec * (Marker.Position.X.Scale + Marker.Size.X.Scale), Enum.EasingStyle.Linear), {\n\t                Position = UDim2.new(0, 2, 0.5, 0)\n\t            }):Play()\n\t            Speed = FishermanUtil.startingMarkerIncrementSpeed\n\t            AimOffset = (math.random() - 0.5) * Width * 0.1\n\t            task.wait(Reaction:GetRandomValue())\n\t        else\n\t            local Period: number = 1 / Clicks:GetRandomValue()\n\t            TweenService:Create(Marker, TweenInfo.new(math.max(FishermanUtil.startingMarkerIncrementSpeed, FishermanUtil.holdMinimumMarkerIncrementSpeed), Enum.EasingStyle.Linear), {\n\t                Position = UDim2.new(math.min(Marker.Position.X.Scale + FishermanUtil.markerIncrementAmount, 1 - Marker.Size.X.Scale), 0, 0.5, 0)\n\t            }):Play()\n\t            task.wait(Period * (0.35 + (math.random() * 0.25)))\n\t            TweenService:Create(Marker, TweenInfo.new(FishermanUtil.totalDecaySpeedSec * (Marker.Position.X.Scale + Marker.Size.X.Scale), Enum.EasingStyle.Linear), {\n\t                Position = UDim2.new(0, 2, 0.5, 0)\n\t            }):Play()\n\t            Speed = FishermanUtil.startingMarkerIncrementSpeed\n\t            AimOffset = (math.random() - 0.5) * Width * 0.1\n\t            task.wait(Period * (0.35 + (math.random() * 0.25)))\n\t        end\n\t    until not AutoFish.Enabled or not Minigame.Enabled\n\tend\n\t\n\tAutoFish = vape.Categories.Inventory:CreateModule({\n\t    Name = \"AutoFish\",\n\t    Function = function(Callback: boolean)\n\t        if Callback then\n\t            Old = bedwars.FishingMinigameController.startMinigame\n\t            bedwars.FishingMinigameController.startMinigame = function(...)\n\t                if Minigame.Enabled and MinigameMode.Value == \"Instant\" then\n\t                    local Deadline: number = tick() + bedwars.FishermanUtil.minigameDuration\n\t                    while IsMenuOpen() and tick() < Deadline do\n\t                        task.wait(0.1)\n\t                    end\n\t                    task.wait(CompleteDelay:GetRandomValue())\n\t                    return select(3, ...)({win = true})\n\t                end\n\t\n\t                local Call = (Old or bedwars.FishingMinigameController.startMinigame)(...)\n\t                if Minigame.Enabled then\n\t                    task.spawn(PlayMinigame)\n\t                end\n\t                return Call\n\t            end\n\t\n\t            AutoFish:Clean(bedwars.Handler:Get(\"FishFound\").Remote:Connect(function(Data)\n\t                local Reroll: boolean = #Blacklist.ListEnabled > 0\n\t                for _, v: any in Data.dropData.drops do\n\t                    local Amount: number = tonumber(v.amount) or 0\n\t                    if Show.Enabled then\n\t                        local ItemDisplay: string = bedwars.ItemMeta[v.itemType] and bedwars.ItemMeta[v.itemType].displayName or v.itemType\n\t                        SendNotification(\"AutoFish\", `You can get {Amount} {ItemDisplay:lower()}{Amount >= 2 and \"s\" or \"\"} on ur next fish`, 20, \"info\")\n\t                    end\n\t                    if not table.find(Blacklist.ListEnabled, v.itemType) then\n\t                        Reroll = false\n\t                    end\n\t                end\n\t\n\t                if Reroll and Entity.isAlive then\n\t                    LocalPlayer.Character.Humanoid.Jump = true\n\t                end\n\t            end))\n\t            repeat\n\t                if Entity.isAlive and Cast.Enabled and (Store.hand.tool and Store.hand.tool.Name == \"fishing_rod\") and not GetBobber() and not IsMenuOpen() then\n\t                    local Spot: Vector3? = GetCastSpot()\n\t                    if not Spot and #Rejects > 0 then\n\t                        table.clear(Rejects)\n\t                        Spot = GetCastSpot()\n\t                    end\n\t\n\t                    if Spot then\n\t                        task.wait(CastDelay:GetRandomValue())\n\t                        if AutoFish.Enabled and not IsMenuOpen() then\n\t                            local Item = bedwars.FishingRodController:getHandItem()\n\t                            if Item and not bedwars.FishingRodController.projectileHandler and bedwars.FishingRodController:canLaunch() then\n\t                                bedwars.FishingRodController:beginHolding(Item, nil, bedwars.FishingRodController.aimingMaid, false)\n\t                                task.wait()\n\t                                local Handler = bedwars.FishingRodController.projectileHandler\n\t                                if Handler then\n\t                                    local ProjectileMeta = bedwars.ProjectileMeta.fisherman_bobber\n\t                                    local Origin: Vector3 = (bedwars.ProjectileController:getLaunchPosition(Item.tool) or Entity.character.RootPart.Position) + Handler.fromPositionOffset\n\t                                    Handler.targetPoint = PredictionLib.SolveTrajectory(Origin, ProjectileMeta.launchVelocity, ProjectileMeta.gravitationalAcceleration, Spot, Vector3.zero, workspace.Gravity, 0, 0) or Spot\n\t                                end\n\t                                bedwars.FishingRodController:releaseChargeInput(bedwars.FishingRodController.aimingMaid, function()\n\t                                    return true\n\t                                end, nil)\n\t                            end\n\t\n\t                            task.wait(2.5)\n\t                            local Bobber: Instance? = GetBobber()\n\t                            if not Bobber or not Bobber:GetAttribute(\"WaitingForFish\") then\n\t                                table.insert(Rejects, Spot)\n\t                            end\n\t                        end\n\t                    end\n\t                end\n\t                task.wait(0.1)\n\t            until not AutoFish.Enabled\n\t        else\n\t            table.clear(Rejects)\n\t            if Old then\n\t                bedwars.FishingMinigameController.startMinigame = Old\n\t                Old = nil\n\t            end\n\t        end\n\t    end,\n\t    Tooltip = \"Automatically fishes with fishing rod\"\n\t})\n\t\n\tBlacklist = AutoFish:CreateTextList({\n\t    Name = \"Blacklisted loot\",\n\t    Default = {\"iron\"},\n\t    Tooltip = \"Jumps to cancel the catch when every item the fish drops is blacklisted\"\n\t})\n\tShow = AutoFish:CreateToggle({\n\t    Name = \"Show loot drops\",\n\t    Tooltip = \"Notifies ur next lootdrops\"\n\t})\n\tMinigame = AutoFish:CreateToggle({\n\t    Name = \"Auto Minigame\",\n\t    Function = function(Callback: boolean)\n\t        if MinigameMode.Object then\n\t            MinigameMode.Object.Visible = Callback\n\t            CompleteDelay.Object.Visible = Callback and MinigameMode.Value == \"Instant\"\n\t            Reaction.Object.Visible = Callback and MinigameMode.Value == \"Legit\"\n\t            Clicks.Object.Visible = Callback and MinigameMode.Value == \"Legit\"\n\t        end\n\t    end,\n\t    Default = true,\n\t    Tooltip = \"Automatically completes the minigame\"\n\t})\n\tMinigameMode = AutoFish:CreateDropdown({\n\t    Name = \"Minigame mode\",\n\t    List = {\"Instant\", \"Legit\"},\n\t    Darker = true,\n\t    Function = function(Val: string)\n\t        if CompleteDelay.Object then\n\t            CompleteDelay.Object.Visible = Minigame.Enabled and Val == \"Instant\"\n\t            Reaction.Object.Visible = Minigame.Enabled and Val == \"Legit\"\n\t            Clicks.Object.Visible = Minigame.Enabled and Val == \"Legit\"\n\t        end\n\t    end,\n\t    Tooltip = \"Instant wins the moment the minigame opens, Legit plays the bar out itself\"\n\t})\n\tCompleteDelay = AutoFish:CreateTwoSlider({\n\t    Name = \"Complete delay\",\n\t    Min = 0,\n\t    Max = 25,\n\t    Decimal = 5,\n\t    DefaultMin = 0.1,\n\t    DefaultMax = 0.9,\n\t    Darker = true\n\t})\n\tReaction = AutoFish:CreateTwoSlider({\n\t    Name = \"Reaction\",\n\t    Min = 0,\n\t    Max = 1,\n\t    Decimal = 100,\n\t    DefaultMin = 0.06,\n\t    DefaultMax = 0.19,\n\t    Darker = true,\n\t    Visible = false,\n\t    Tooltip = \"How long it takes to notice the fish moved away before it lets go\"\n\t})\n\tClicks = AutoFish:CreateTwoSlider({\n\t    Name = \"Clicks\",\n\t    Min = 3,\n\t    Max = 20,\n\t    DefaultMin = 8,\n\t    DefaultMax = 13,\n\t    Darker = true,\n\t    Visible = false,\n\t    Suffix = \"cps\",\n\t    Tooltip = \"How fast it taps to hover the bar on the fish\"\n\t})\n\tCast = AutoFish:CreateToggle({\n\t    Name = \"Auto Cast\",\n\t    Function = function(Callback: boolean)\n\t        if CastDelay.Object then\n\t            CastDelay.Object.Visible = Callback\n\t        end\n\t    end,\n\t    Tooltip = \"Finds a spot to fish at and casts there, ignoring where ur camera looks\"\n\t})\n\tCastDelay = AutoFish:CreateTwoSlider({\n\t    Name = \"Cast delay\",\n\t    Min = 0,\n\t    Max = 5,\n\t    Decimal = 5,\n\t    DefaultMin = 0.3,\n\t    DefaultMax = 1.2,\n\t    Darker = true,\n\t    Visible = false\n\t})\n\tGUI = AutoFish:CreateToggle({\n\t    Name = \"GUI Check\",\n\t    Tooltip = \"Waits while a game menu like the shop or ur inventory is open before casting or playing the minigame\"\n\t})\nend)\n\nRun(function()\n\tlocal AutoHotbar\n\tlocal Mode\n\tlocal Clear\n\tlocal List\n\tlocal Active\n\t\n\tlocal function CreateWindow(self): Frame\n\t    local SelectedSlot: number = 1\n\t    local Window: Frame = Instance.new(\"Frame\")\n\t    Window.Name = \"HotbarGUI\"\n\t    Window.Size = UDim2.fromOffset(660, 465)\n\t    Window.Position = UDim2.fromScale(0.5, 0.5)\n\t    Window.BackgroundColor3 = UIPallet.Main\n\t    Window.AnchorPoint = Vector2.new(0.5, 0.5)\n\t    Window.Visible = false\n\t    if vape.ThreadFix then\n\t        setthreadidentity(8)\n\t    end\n\t    Window.Parent = vape.gui.ScaledGui\n\t    local Title: TextLabel = Instance.new(\"TextLabel\")\n\t    Title.Name = \"Title\"\n\t    Title.Size = UDim2.new(1, -10, 0, 20)\n\t    Title.Position = UDim2.fromOffset(math.abs(Title.Size.X.Offset), 12)\n\t    Title.BackgroundTransparency = 1\n\t    Title.Text = \"AutoHotbar\"\n\t    Title.TextXAlignment = Enum.TextXAlignment.Left\n\t    Title.TextColor3 = UIPallet.Text\n\t    Title.TextSize = 13\n\t    Title.FontFace = UIPallet.Font\n\t    Title.Parent = Window\n\t    local Divider: Frame = Instance.new(\"Frame\")\n\t    Divider.Name = \"Divider\"\n\t    Divider.Size = UDim2.new(1, 0, 0, 1)\n\t    Divider.Position = UDim2.fromOffset(0, 40)\n\t    Divider.BackgroundColor3 = Color.Light(UIPallet.Main, 0.04)\n\t    Divider.BorderSizePixel = 0\n\t    Divider.Parent = Window\n\t    AddBlur(Window)\n\t    local Modal: TextButton = Instance.new(\"TextButton\")\n\t    Modal.Text = \"\"\n\t    Modal.BackgroundTransparency = 1\n\t    Modal.Modal = true\n\t    Modal.Parent = Window\n\t    local Corner: UICorner = Instance.new(\"UICorner\")\n\t    Corner.CornerRadius = UDim.new(0, 5)\n\t    Corner.Parent = Window\n\t    local Close: ImageButton = Instance.new(\"ImageButton\")\n\t    Close.Name = \"Close\"\n\t    Close.Size = UDim2.fromOffset(24, 24)\n\t    Close.Position = UDim2.new(1, -35, 0, 9)\n\t    Close.BackgroundColor3 = Color3.new(1, 1, 1)\n\t    Close.BackgroundTransparency = 1\n\t    Close.Image = GetVapeAsset(`{vape.Directory}/assets/new/close.png`)\n\t    Close.ImageColor3 = Color.Light(UIPallet.Text, 0.2)\n\t    Close.ImageTransparency = 0.5\n\t    Close.AutoButtonColor = false\n\t    Close.Parent = Window\n\t    Close.MouseEnter:Connect(function()\n\t        Close.ImageTransparency = 0.3\n\t        Tween:Tween(Close, TweenInfo.new(0.2), {\n\t            BackgroundTransparency = 0.6\n\t        })\n\t    end)\n\t    Close.MouseLeave:Connect(function()\n\t        Close.ImageTransparency = 0.5\n\t        Tween:Tween(Close, TweenInfo.new(0.2), {\n\t            BackgroundTransparency = 1\n\t        })\n\t    end)\n\t    Close.MouseButton1Click:Connect(function()\n\t        Window.Visible = false\n\t        vape.gui.ScaledGui.ClickGui.Visible = true\n\t    end)\n\t    local CloseCorner: UICorner = Instance.new(\"UICorner\")\n\t    CloseCorner.CornerRadius = UDim.new(1, 0)\n\t    CloseCorner.Parent = Close\n\t    local BigSlot: Frame = Instance.new(\"Frame\")\n\t    BigSlot.Size = UDim2.fromOffset(110, 111)\n\t    BigSlot.Position = UDim2.fromOffset(11, 71)\n\t    BigSlot.BackgroundColor3 = Color.Dark(UIPallet.Main, 0.02)\n\t    BigSlot.Parent = Window\n\t    local BigSlotCorner: UICorner = Instance.new(\"UICorner\")\n\t    BigSlotCorner.CornerRadius = UDim.new(0, 4)\n\t    BigSlotCorner.Parent = BigSlot\n\t    local BigSlotStroke: UIStroke = Instance.new(\"UIStroke\")\n\t    BigSlotStroke.Color = Color.Light(UIPallet.Main, 0.034)\n\t    BigSlotStroke.ApplyStrokeMode = Enum.ApplyStrokeMode.Border\n\t    BigSlotStroke.Parent = BigSlot\n\t    local SlotNumber: TextLabel = Instance.new(\"TextLabel\")\n\t    SlotNumber.Size = UDim2.fromOffset(80, 20)\n\t    SlotNumber.Position = UDim2.fromOffset(25, 200)\n\t    SlotNumber.BackgroundTransparency = 1\n\t    SlotNumber.Text = \"SLOT 1\"\n\t    SlotNumber.TextColor3 = Color.Dark(UIPallet.Text, 0.1)\n\t    SlotNumber.TextSize = 12\n\t    SlotNumber.FontFace = UIPallet.Font\n\t    SlotNumber.Parent = Window\n\t    for Slot: number = 1, 9 do\n\t        local SlotBackground: TextButton = Instance.new(\"TextButton\")\n\t        SlotBackground.Name = `Slot{Slot}`\n\t        SlotBackground.Size = UDim2.fromOffset(51, 52)\n\t        SlotBackground.Position = UDim2.fromOffset(89 + (Slot * 55), 382)\n\t        SlotBackground.BackgroundColor3 = Color.Dark(UIPallet.Main, 0.02)\n\t        SlotBackground.Text = \"\"\n\t        SlotBackground.AutoButtonColor = false\n\t        SlotBackground.Parent = Window\n\t        local SlotImage: ImageLabel = Instance.new(\"ImageLabel\")\n\t        SlotImage.Size = UDim2.fromOffset(32, 32)\n\t        SlotImage.Position = UDim2.new(0.5, -16, 0.5, -16)\n\t        SlotImage.BackgroundTransparency = 1\n\t        SlotImage.Image = \"\"\n\t        SlotImage.Parent = SlotBackground\n\t        local SlotCorner: UICorner = Instance.new(\"UICorner\")\n\t        SlotCorner.CornerRadius = UDim.new(0, 4)\n\t        SlotCorner.Parent = SlotBackground\n\t        local SlotStroke: UIStroke = Instance.new(\"UIStroke\")\n\t        SlotStroke.Color = Color.Light(UIPallet.Main, 0.04)\n\t        SlotStroke.Thickness = 2\n\t        SlotStroke.ApplyStrokeMode = Enum.ApplyStrokeMode.Border\n\t        SlotStroke.Enabled = Slot == SelectedSlot\n\t        SlotStroke.Parent = SlotBackground\n\t        SlotBackground.MouseEnter:Connect(function()\n\t            SlotBackground.BackgroundColor3 = Color.Light(UIPallet.Main, 0.034)\n\t        end)\n\t        SlotBackground.MouseLeave:Connect(function()\n\t            SlotBackground.BackgroundColor3 = Color.Dark(UIPallet.Main, 0.02)\n\t        end)\n\t        SlotBackground.MouseButton1Click:Connect(function()\n\t            Window[`Slot{SelectedSlot}`].UIStroke.Enabled = false\n\t            SelectedSlot = Slot\n\t            SlotStroke.Enabled = true\n\t            SlotNumber.Text = `SLOT {SelectedSlot}`\n\t        end)\n\t        SlotBackground.MouseButton2Click:Connect(function()\n\t            local SelectedHotbar = self.Hotbars[self.Selected]\n\t            if SelectedHotbar then\n\t                Window[`Slot{Slot}`].ImageLabel.Image = \"\"\n\t                SelectedHotbar.Hotbar[tostring(Slot)] = nil\n\t                SelectedHotbar.Object[`Slot{Slot}`].Image = \"\"\n\t            end\n\t        end)\n\t    end\n\t    local SearchBackground: Frame = Instance.new(\"Frame\")\n\t    SearchBackground.Size = UDim2.fromOffset(496, 31)\n\t    SearchBackground.Position = UDim2.fromOffset(142, 80)\n\t    SearchBackground.BackgroundColor3 = Color.Light(UIPallet.Main, 0.034)\n\t    SearchBackground.Parent = Window\n\t    local Search: TextBox = Instance.new(\"TextBox\")\n\t    Search.Size = UDim2.new(1, -10, 0, 31)\n\t    Search.Position = UDim2.fromOffset(10, 0)\n\t    Search.BackgroundTransparency = 1\n\t    Search.Text = \"\"\n\t    Search.PlaceholderText = \"\"\n\t    Search.TextXAlignment = Enum.TextXAlignment.Left\n\t    Search.TextColor3 = UIPallet.Text\n\t    Search.TextSize = 12\n\t    Search.FontFace = UIPallet.Font\n\t    Search.ClearTextOnFocus = false\n\t    Search.Parent = SearchBackground\n\t    local SearchCorner: UICorner = Instance.new(\"UICorner\")\n\t    SearchCorner.CornerRadius = UDim.new(0, 4)\n\t    SearchCorner.Parent = SearchBackground\n\t    local SearchIcon: ImageLabel = Instance.new(\"ImageLabel\")\n\t    SearchIcon.Size = UDim2.fromOffset(14, 14)\n\t    SearchIcon.Position = UDim2.new(1, -26, 0, 8)\n\t    SearchIcon.BackgroundTransparency = 1\n\t    SearchIcon.Image = GetVapeAsset(`{vape.Directory}/assets/new/search.png`)\n\t    SearchIcon.ImageColor3 = Color.Light(UIPallet.Main, 0.37)\n\t    SearchIcon.Parent = SearchBackground\n\t    local Children: ScrollingFrame = Instance.new(\"ScrollingFrame\")\n\t    Children.Name = \"Children\"\n\t    Children.Size = UDim2.fromOffset(500, 240)\n\t    Children.Position = UDim2.fromOffset(144, 122)\n\t    Children.BackgroundTransparency = 1\n\t    Children.BorderSizePixel = 0\n\t    Children.ScrollBarThickness = 2\n\t    Children.ScrollBarImageTransparency = 0.75\n\t    Children.CanvasSize = UDim2.new()\n\t    Children.Parent = Window\n\t    local WindowList: UIGridLayout = Instance.new(\"UIGridLayout\")\n\t    WindowList.SortOrder = Enum.SortOrder.LayoutOrder\n\t    WindowList.FillDirectionMaxCells = 9\n\t    WindowList.CellSize = UDim2.fromOffset(51, 52)\n\t    WindowList.CellPadding = UDim2.fromOffset(4, 3)\n\t    WindowList.Parent = Children\n\t    WindowList:GetPropertyChangedSignal(\"AbsoluteContentSize\"):Connect(function()\n\t        if vape.ThreadFix then\n\t            setthreadidentity(8)\n\t        end\n\t        Children.CanvasSize = UDim2.fromOffset(0, WindowList.AbsoluteContentSize.Y / vape.guiscale.Scale)\n\t    end)\n\t    table.insert(vape.Windows, Window)\n\t\n\t    local function CreateItem(ItemId: string, Image: string)\n\t        local SlotBackground: TextButton = Instance.new(\"TextButton\")\n\t        SlotBackground.BackgroundColor3 = Color.Light(UIPallet.Main, 0.02)\n\t        SlotBackground.Text = \"\"\n\t        SlotBackground.AutoButtonColor = false\n\t        SlotBackground.Parent = Children\n\t        local SlotImage: ImageLabel = Instance.new(\"ImageLabel\")\n\t        SlotImage.Size = UDim2.fromOffset(32, 32)\n\t        SlotImage.Position = UDim2.new(0.5, -16, 0.5, -16)\n\t        SlotImage.BackgroundTransparency = 1\n\t        SlotImage.Image = Image\n\t        SlotImage.Parent = SlotBackground\n\t        local SlotCorner: UICorner = Instance.new(\"UICorner\")\n\t        SlotCorner.CornerRadius = UDim.new(0, 4)\n\t        SlotCorner.Parent = SlotBackground\n\t        SlotBackground.MouseEnter:Connect(function()\n\t            SlotBackground.BackgroundColor3 = Color.Light(UIPallet.Main, 0.04)\n\t        end)\n\t        SlotBackground.MouseLeave:Connect(function()\n\t            SlotBackground.BackgroundColor3 = Color.Light(UIPallet.Main, 0.02)\n\t        end)\n\t        SlotBackground.MouseButton1Click:Connect(function()\n\t            local SelectedHotbar = self.Hotbars[self.Selected]\n\t            if SelectedHotbar then\n\t                Window[`Slot{SelectedSlot}`].ImageLabel.Image = Image\n\t                SelectedHotbar.Hotbar[tostring(SelectedSlot)] = ItemId\n\t                SelectedHotbar.Object[`Slot{SelectedSlot}`].Image = Image\n\t            end\n\t        end)\n\t    end\n\t\n\t    local function IndexSearch(Text: string)\n\t        for _, v: Instance in Children:GetChildren() do\n\t            if v:IsA(\"TextButton\") then\n\t                v:ClearAllChildren()\n\t                v:Destroy()\n\t            end\n\t        end\n\t\n\t        if Text == \"\" then\n\t            for _, v: string in {\"diamond_sword\", \"diamond_pickaxe\", \"diamond_axe\", \"shears\", \"wood_bow\", \"wool_white\", \"fireball\", \"apple\", \"iron\", \"gold\", \"diamond\", \"emerald\"} do\n\t                CreateItem(v, bedwars.ItemMeta[v].image)\n\t            end\n\t            return\n\t        end\n\t\n\t        for ItemId: string, v: any in bedwars.ItemMeta do\n\t            if Text:lower() == ItemId:lower():sub(1, Text:len()) then\n\t                if not v.image then\n\t                    continue\n\t                end\n\t                CreateItem(ItemId, v.image)\n\t            end\n\t        end\n\t    end\n\t\n\t    Search:GetPropertyChangedSignal(\"Text\"):Connect(function()\n\t        IndexSearch(Search.Text)\n\t    end)\n\t    IndexSearch(\"\")\n\t\n\t    return Window\n\tend\n\t\n\tvape.Components.HotbarList = function(OptionSettings, Children, Api)\n\t    if vape.ThreadFix then\n\t        setthreadidentity(8)\n\t    end\n\t    local OptionApi = {\n\t        Type = \"HotbarList\",\n\t        Hotbars = {},\n\t        Selected = 1\n\t    }\n\t    local HotbarList: TextButton = Instance.new(\"TextButton\")\n\t    HotbarList.Name = \"HotbarList\"\n\t    HotbarList.Size = UDim2.fromOffset(220, 40)\n\t    HotbarList.BackgroundColor3 = OptionSettings.Darker and (Children.BackgroundColor3 == Color.Dark(UIPallet.Main, 0.02) and Color.Dark(UIPallet.Main, 0.04) or Color.Dark(UIPallet.Main, 0.02)) or Children.BackgroundColor3\n\t    HotbarList.Text = \"\"\n\t    HotbarList.BorderSizePixel = 0\n\t    HotbarList.AutoButtonColor = false\n\t    HotbarList.Parent = Children\n\t    local TextBackground: Frame = Instance.new(\"Frame\")\n\t    TextBackground.Name = \"BKG\"\n\t    TextBackground.Size = UDim2.new(1, -20, 0, 31)\n\t    TextBackground.Position = UDim2.fromOffset(10, 4)\n\t    TextBackground.BackgroundColor3 = Color.Light(UIPallet.Main, 0.034)\n\t    TextBackground.Parent = HotbarList\n\t    local TextBackgroundCorner: UICorner = Instance.new(\"UICorner\")\n\t    TextBackgroundCorner.CornerRadius = UDim.new(0, 4)\n\t    TextBackgroundCorner.Parent = TextBackground\n\t    local AddButton: TextButton = Instance.new(\"TextButton\")\n\t    AddButton.Name = \"HotbarList\"\n\t    AddButton.Size = UDim2.new(1, -2, 1, -2)\n\t    AddButton.Position = UDim2.fromOffset(1, 1)\n\t    AddButton.BackgroundColor3 = UIPallet.Main\n\t    AddButton.Text = \"\"\n\t    AddButton.AutoButtonColor = false\n\t    AddButton.Parent = TextBackground\n\t    AddButton.MouseEnter:Connect(function()\n\t        Tween:Tween(TextBackground, TweenInfo.new(0.2), {\n\t            BackgroundColor3 = Color.Light(UIPallet.Main, 0.14)\n\t        })\n\t    end)\n\t    AddButton.MouseLeave:Connect(function()\n\t        Tween:Tween(TextBackground, TweenInfo.new(0.2), {\n\t            BackgroundColor3 = Color.Light(UIPallet.Main, 0.034)\n\t        })\n\t    end)\n\t    local AddButtonCorner: UICorner = Instance.new(\"UICorner\")\n\t    AddButtonCorner.CornerRadius = UDim.new(0, 4)\n\t    AddButtonCorner.Parent = AddButton\n\t    local AddButtonIcon: ImageLabel = Instance.new(\"ImageLabel\")\n\t    AddButtonIcon.Size = UDim2.fromOffset(12, 12)\n\t    AddButtonIcon.Position = UDim2.fromScale(0.5, 0.5)\n\t    AddButtonIcon.AnchorPoint = Vector2.new(0.5, 0.5)\n\t    AddButtonIcon.BackgroundTransparency = 1\n\t    AddButtonIcon.Image = GetVapeAsset(`{vape.Directory}/assets/new/add.png`)\n\t    AddButtonIcon.ImageColor3 = Color3.fromHSV(0.46, 0.96, 0.52)\n\t    AddButtonIcon.Parent = AddButton\n\t    local ChildrenList: Frame = Instance.new(\"Frame\")\n\t    ChildrenList.Size = UDim2.new(1, 0, 1, -40)\n\t    ChildrenList.Position = UDim2.fromOffset(0, 40)\n\t    ChildrenList.BackgroundTransparency = 1\n\t    ChildrenList.Parent = HotbarList\n\t    local WindowList: UIListLayout = Instance.new(\"UIListLayout\")\n\t    WindowList.SortOrder = Enum.SortOrder.LayoutOrder\n\t    WindowList.HorizontalAlignment = Enum.HorizontalAlignment.Center\n\t    WindowList.Padding = UDim.new(0, 3)\n\t    WindowList.Parent = ChildrenList\n\t    WindowList:GetPropertyChangedSignal(\"AbsoluteContentSize\"):Connect(function()\n\t        if vape.ThreadFix then\n\t            setthreadidentity(8)\n\t        end\n\t        HotbarList.Size = UDim2.fromOffset(220, math.min(43 + WindowList.AbsoluteContentSize.Y / vape.guiscale.Scale, 603))\n\t    end)\n\t    AddButton.MouseButton1Click:Connect(function()\n\t        OptionApi:AddHotbar()\n\t    end)\n\t    OptionApi.Window = CreateWindow(OptionApi)\n\t\n\t    function OptionApi:Save(SaveTable)\n\t        local Hotbars = {}\n\t        for _, v: {Hotbar: {[string]: any}, Object: TextButton} in self.Hotbars do\n\t            table.insert(Hotbars, v.Hotbar)\n\t        end\n\t        SaveTable.HotbarList = {\n\t            Selected = self.Selected,\n\t            Hotbars = Hotbars\n\t        }\n\t    end\n\t\n\t    function OptionApi:Load(SaveTable)\n\t        for _, v: {Hotbar: {[string]: any}, Object: TextButton} in self.Hotbars do\n\t            v.Object:ClearAllChildren()\n\t            v.Object:Destroy()\n\t            table.clear(v.Hotbar)\n\t        end\n\t        table.clear(self.Hotbars)\n\t        for _, v: any in SaveTable.Hotbars do\n\t            self:AddHotbar(v)\n\t        end\n\t        self.Selected = SaveTable.Selected or 1\n\t    end\n\t\n\t    function OptionApi:AddHotbar(Data)\n\t        local HotbarData = {Hotbar = Data or {}}\n\t        table.insert(self.Hotbars, HotbarData)\n\t        local Hotbar: TextButton = Instance.new(\"TextButton\")\n\t        Hotbar.Size = UDim2.fromOffset(200, 27)\n\t        Hotbar.BackgroundColor3 = table.find(self.Hotbars, HotbarData) == self.Selected and Color.Light(UIPallet.Main, 0.034) or UIPallet.Main\n\t        Hotbar.Text = \"\"\n\t        Hotbar.AutoButtonColor = false\n\t        Hotbar.Parent = ChildrenList\n\t        HotbarData.Object = Hotbar\n\t        local HotbarCorner: UICorner = Instance.new(\"UICorner\")\n\t        HotbarCorner.CornerRadius = UDim.new(0, 4)\n\t        HotbarCorner.Parent = Hotbar\n\t        for Slot: number = 1, 9 do\n\t            local SlotImage: ImageLabel = Instance.new(\"ImageLabel\")\n\t            SlotImage.Name = `Slot{Slot}`\n\t            SlotImage.Size = UDim2.fromOffset(17, 18)\n\t            SlotImage.Position = UDim2.fromOffset(-7 + (Slot * 18), 5)\n\t            SlotImage.BackgroundColor3 = Color.Dark(UIPallet.Main, 0.02)\n\t            SlotImage.Image = HotbarData.Hotbar[tostring(Slot)] and bedwars.getIcon({itemType = HotbarData.Hotbar[tostring(Slot)]}, true) or \"\"\n\t            SlotImage.BorderSizePixel = 0\n\t            SlotImage.Parent = Hotbar\n\t        end\n\t        Hotbar.MouseButton1Click:Connect(function()\n\t            local Index: number? = table.find(OptionApi.Hotbars, HotbarData)\n\t            if Index == OptionApi.Selected then\n\t                vape.gui.ScaledGui.ClickGui.Visible = false\n\t                OptionApi.Window.Visible = true\n\t                for Slot: number = 1, 9 do\n\t                    OptionApi.Window[`Slot{Slot}`].ImageLabel.Image = HotbarData.Hotbar[tostring(Slot)] and bedwars.getIcon({itemType = HotbarData.Hotbar[tostring(Slot)]}, true) or \"\"\n\t                end\n\t            else\n\t                if OptionApi.Hotbars[OptionApi.Selected] then\n\t                    OptionApi.Hotbars[OptionApi.Selected].Object.BackgroundColor3 = UIPallet.Main\n\t                end\n\t                Hotbar.BackgroundColor3 = Color.Light(UIPallet.Main, 0.034)\n\t                OptionApi.Selected = Index\n\t            end\n\t        end)\n\t        local Close: ImageButton = Instance.new(\"ImageButton\")\n\t        Close.Name = \"Close\"\n\t        Close.Size = UDim2.fromOffset(16, 16)\n\t        Close.Position = UDim2.new(1, -23, 0, 6)\n\t        Close.BackgroundColor3 = Color3.new(1, 1, 1)\n\t        Close.BackgroundTransparency = 1\n\t        Close.Image = GetVapeAsset(`{vape.Directory}/assets/new/closemini.png`)\n\t        Close.ImageColor3 = Color.Light(UIPallet.Text, 0.2)\n\t        Close.ImageTransparency = 0.5\n\t        Close.AutoButtonColor = false\n\t        Close.Parent = Hotbar\n\t        local CloseCorner: UICorner = Instance.new(\"UICorner\")\n\t        CloseCorner.CornerRadius = UDim.new(1, 0)\n\t        CloseCorner.Parent = Close\n\t        Close.MouseEnter:Connect(function()\n\t            Close.ImageTransparency = 0.3\n\t            Tween:Tween(Close, TweenInfo.new(0.2), {\n\t                BackgroundTransparency = 0.6\n\t            })\n\t        end)\n\t        Close.MouseLeave:Connect(function()\n\t            Close.ImageTransparency = 0.5\n\t            Tween:Tween(Close, TweenInfo.new(0.2), {\n\t                BackgroundTransparency = 1\n\t            })\n\t        end)\n\t        Close.MouseButton1Click:Connect(function()\n\t            local Index: number? = table.find(self.Hotbars, HotbarData)\n\t            local SelectedHotbar = self.Hotbars[self.Selected]\n\t            local RemovedHotbar = self.Hotbars[Index]\n\t            if SelectedHotbar and RemovedHotbar then\n\t                RemovedHotbar.Object:ClearAllChildren()\n\t                RemovedHotbar.Object:Destroy()\n\t                table.remove(self.Hotbars, Index)\n\t                self.Selected = table.find(self.Hotbars, SelectedHotbar) or 1\n\t            end\n\t        end)\n\t    end\n\t\n\t    Api.Options.HotbarList = OptionApi\n\t\n\t    return OptionApi\n\tend\n\t\n\tlocal function Sort()\n\t    local Wanted: {[string]: string} = {}\n\t    for Slot: string, v: string in List.Hotbars[List.Selected] and List.Hotbars[List.Selected].Hotbar or {} do\n\t        Wanted[Slot] = v\n\t        if v == \"diamond_sword\" then\n\t            local Sword = Store.tools.sword\n\t            Wanted[Slot] = Sword and Sword.itemType or \"wood_sword\"\n\t        elseif v == \"diamond_pickaxe\" then\n\t            local Pickaxe = Store.tools.stone\n\t            Wanted[Slot] = Pickaxe and Pickaxe.itemType or \"wood_pickaxe\"\n\t        elseif v == \"diamond_axe\" then\n\t            local Axe = Store.tools.wood\n\t            Wanted[Slot] = Axe and Axe.itemType or \"wood_axe\"\n\t        elseif v == \"wood_bow\" then\n\t            local Bow = GetBow()\n\t            Wanted[Slot] = Bow and Bow.itemType or \"wood_bow\"\n\t        elseif v == \"wool_white\" then\n\t            local SortedItems = table.clone(Store.inventory.inventory.items)\n\t            table.sort(SortedItems, function(A, B)\n\t                return A.amount < B.amount\n\t            end)\n\t            for _, Item: any in SortedItems do\n\t                local Meta = bedwars.ItemMeta[Item.itemType]\n\t                local Block = Meta and Meta.block\n\t                if Block and not Block.seeThrough then\n\t                    Wanted[Slot] = Item.itemType\n\t                    break\n\t                end\n\t            end\n\t        end\n\t    end\n\t\n\t    for _, v: any in Store.inventory.inventory.items do\n\t        local Slot\n\t        for SlotKey: string, ItemType: string in Wanted do\n\t            if v.itemType == ItemType then\n\t                Slot = tonumber(SlotKey)\n\t                break\n\t            end\n\t        end\n\t\n\t        if Slot then\n\t            local OldItem = Store.inventory.hotbar[Slot]\n\t            if OldItem.item and OldItem.item.itemType == v.itemType then\n\t                continue\n\t            end\n\t            if OldItem.item then\n\t                bedwars.Store:dispatch({\n\t                    type = \"InventoryRemoveFromHotbar\",\n\t                    slot = Slot - 1\n\t                })\n\t                VapeEvents.InventoryChanged.Event:Wait()\n\t            end\n\t\n\t            local NewSlot\n\t            for i: number, HotbarSlot: any in Store.inventory.hotbar do\n\t                if HotbarSlot.item and HotbarSlot.item.itemType == v.itemType then\n\t                    NewSlot = i - 1\n\t                    break\n\t                end\n\t            end\n\t\n\t            if NewSlot then\n\t                bedwars.Store:dispatch({\n\t                    type = \"InventoryRemoveFromHotbar\",\n\t                    slot = NewSlot\n\t                })\n\t                VapeEvents.InventoryChanged.Event:Wait()\n\t                if OldItem.item then\n\t                    local Swap\n\t                    for _, Item: any in Store.inventory.inventory.items do\n\t                        if Item.itemType == OldItem.item.itemType then\n\t                            Swap = Item\n\t                            break\n\t                        end\n\t                    end\n\t                    bedwars.Store:dispatch({\n\t                        type = \"InventoryAddToHotbar\",\n\t                        item = Swap,\n\t                        slot = NewSlot\n\t                    })\n\t                    VapeEvents.InventoryChanged.Event:Wait()\n\t                end\n\t            end\n\t\n\t            local Held\n\t            for _, Item: any in Store.inventory.inventory.items do\n\t                if Item.itemType == v.itemType then\n\t                    Held = Item\n\t                    break\n\t                end\n\t            end\n\t            bedwars.Store:dispatch({\n\t                type = \"InventoryAddToHotbar\",\n\t                item = Held,\n\t                slot = Slot - 1\n\t            })\n\t            VapeEvents.InventoryChanged.Event:Wait()\n\t        elseif Clear.Enabled then\n\t            local NewSlot\n\t            for i: number, HotbarSlot: any in Store.inventory.hotbar do\n\t                if HotbarSlot.item and HotbarSlot.item.itemType == v.itemType then\n\t                    NewSlot = i - 1\n\t                    break\n\t                end\n\t            end\n\t\n\t            if NewSlot then\n\t                bedwars.Store:dispatch({\n\t                    type = \"InventoryRemoveFromHotbar\",\n\t                    slot = NewSlot\n\t                })\n\t                VapeEvents.InventoryChanged.Event:Wait()\n\t            end\n\t        end\n\t    end\n\tend\n\t\n\tlocal function SortCallback()\n\t    if Active then\n\t        return\n\t    end\n\t\n\t    Active = true\n\t    local Success, Error = pcall(Sort)\n\t    Active = false\n\t\n\t    if not Success and shared.VapeDeveloper then\n\t        warn(`[catvape] AutoHotbar failed to sort: {Error}`)\n\t    end\n\tend\n\t\n\tAutoHotbar = vape.Categories.Inventory:CreateModule({\n\t    Name = \"AutoHotbar\",\n\t    Function = function(Callback: boolean)\n\t        if Callback then\n\t            task.spawn(SortCallback)\n\t            if Mode.Value == \"On Key\" then\n\t                AutoHotbar:Toggle()\n\t                return\n\t            end\n\t\n\t            AutoHotbar:Clean(VapeEvents.InventoryAmountChanged.Event:Connect(SortCallback))\n\t        end\n\t    end,\n\t    Tooltip = \"Automatically arranges hotbar to your liking.\"\n\t})\n\t\n\tMode = AutoHotbar:CreateDropdown({\n\t    Name = \"Activation\",\n\t    List = {\"Toggle\", \"On Key\"},\n\t    Function = function()\n\t        if AutoHotbar.Enabled then\n\t            AutoHotbar:Toggle()\n\t            AutoHotbar:Toggle()\n\t        end\n\t    end\n\t})\n\tClear = AutoHotbar:CreateToggle({Name = \"Clear Hotbar\"})\n\tList = AutoHotbar:CreateHotbarList({})\nend)\n\nRun(function()\n\tlocal AutoSteal\n\tlocal Range\n\tlocal Delay\n\tlocal GUI\n\tlocal Stash = {}\n\t\n\tlocal function StealCrate(Crate: Instance)\n\t    local FolderValue: Instance? = Crate:FindFirstChild(\"ChestFolderValue\")\n\t    local Folder = FolderValue and FolderValue.Value or nil\n\t    if not Folder then\n\t        return\n\t    end\n\t\n\t    local Items: {Instance} = {}\n\t    for _, v: Instance in Folder:GetChildren() do\n\t        if v:IsA(\"Accessory\") then\n\t            table.insert(Items, v)\n\t        end\n\t    end\n\t    if #Items == 0 then\n\t        return\n\t    end\n\t\n\t    local Observed = LocalPlayer.Character and LocalPlayer.Character:FindFirstChild(\"ObservedChestFolder\")\n\t    Observed = Observed and Observed.Value or nil\n\t    bedwars.Client:GetNamespace(\"Inventory\"):Get(\"SetObservedChest\"):SendToServer(Folder)\n\t\n\t    for _, v: Instance in Items do\n\t        local ItemType: string = v.Name\n\t        task.spawn(function()\n\t            local Success, Result = pcall(function()\n\t                return bedwars.Client:GetNamespace(\"Inventory\"):Get(\"ChestGetItem\"):CallServer(Folder, v)\n\t            end)\n\t\n\t            if Success and Result then\n\t                table.insert(Stash, {Type = ItemType, Expire = tick() + 5})\n\t            end\n\t        end)\n\t    end\n\t\n\t    bedwars.Client:GetNamespace(\"Inventory\"):Get(\"SetObservedChest\"):SendToServer(Observed)\n\tend\n\t\n\tlocal function DepositStash()\n\t    local Inventory: Instance? = ReplicatedStorage:FindFirstChild(\"Inventories\")\n\t    Inventory = Inventory and Inventory:FindFirstChild(`{LocalPlayer.Name}_personal`) or nil\n\t    if not Inventory then\n\t        return\n\t    end\n\t\n\t    local Pending = table.clone(Stash)\n\t    table.clear(Stash)\n\t\n\t    for _, v: {Type: string, Expire: number} in Pending do\n\t        local Item = GetItem(v.Type)\n\t        if Item then\n\t            task.spawn(function()\n\t                local Success, Result = pcall(function()\n\t                    return bedwars.Client:GetNamespace(\"Inventory\"):Get(\"ChestGiveItem\"):CallServer(Inventory, Item.tool)\n\t                end)\n\t\n\t                if not (Success and Result) and tick() < v.Expire then\n\t                    table.insert(Stash, v)\n\t                end\n\t            end)\n\t        elseif tick() < v.Expire then\n\t            table.insert(Stash, v)\n\t        end\n\t    end\n\tend\n\t\n\tAutoSteal = vape.Categories.Inventory:CreateModule({\n\t    Name = \"AutoSteal\",\n\t    Function = function(Callback: boolean)\n\t        if Callback then\n\t            repeat\n\t                task.wait()\n\t            until Store.matchState ~= 0 or (not AutoSteal.Enabled)\n\t            if not AutoSteal.Enabled then\n\t                return\n\t            end\n\t\n\t            local Crates = Collection(\"team-crate\", AutoSteal)\n\t            local Chests = Collection(\"personal-chest\", AutoSteal)\n\t            local NextSteal: number = 0\n\t\n\t            repeat\n\t                if Entity.isAlive and tick() > NextSteal and (not GUI.Enabled or bedwars.AppController:isAppOpen(\"ChestApp\")) then\n\t                    NextSteal = tick() + Delay.Value\n\t                    local LocalPosition: Vector3 = Entity.character.RootPart.Position\n\t                    local Team = LocalPlayer:GetAttribute(\"Team\")\n\t\n\t                    for _, v: BasePart in Crates do\n\t                        if v:GetAttribute(\"Team\") ~= Team and (LocalPosition - v.Position).Magnitude <= Range.Value then\n\t                            StealCrate(v)\n\t                        end\n\t                    end\n\t\n\t                    if #Stash > 0 then\n\t                        for _, v: BasePart in Chests do\n\t                            if (LocalPosition - v.Position).Magnitude <= Range.Value then\n\t                                DepositStash()\n\t                                break\n\t                            end\n\t                        end\n\t                    end\n\t                end\n\t                task.wait(0.1)\n\t            until not AutoSteal.Enabled\n\t        end\n\t\n\t        table.clear(Stash)\n\t    end,\n\t    Tooltip = \"Automatically steals loot from the enemy team's crate and banks it in your personal chest\"\n\t})\n\t\n\tRange = AutoSteal:CreateSlider({\n\t    Name = \"Range\",\n\t    Min = 1,\n\t    Max = 18,\n\t    Default = 18,\n\t    Suffix = function(Val: number)\n\t        return Val == 1 and \"stud\" or \"studs\"\n\t    end\n\t})\n\tDelay = AutoSteal:CreateSlider({\n\t    Name = \"Delay\",\n\t    Min = 0,\n\t    Max = 1,\n\t    Decimal = 100,\n\t    Suffix = \"seconds\",\n\t    Default = 0\n\t})\n\tGUI = AutoSteal:CreateToggle({Name = \"GUI Check\"})\nend)\n\nRun(function()\n\tlocal AutoUse\n\tlocal Items\n\tlocal Combat\n\tlocal Delay\n\t\n\tAutoUse = vape.Categories.Inventory:CreateModule({\n\t    Name = \"AutoUse\",\n\t    Function = function(Callback: boolean)\n\t        if Callback then\n\t            repeat\n\t                if Entity.isAlive and Store.matchState == 1 and not IsCasting() and (not Combat.Enabled or (workspace:GetServerTimeNow() - (LocalPlayer.Character:GetAttribute(\"LastDamageTakenTime\") or 0)) < 6) then\n\t                    for _, v: string in Items.ListEnabled do\n\t                        local Item = GetItem(v)\n\t                        local ItemMeta = Item and bedwars.ItemMeta[v]\n\t                        local Consumable = ItemMeta and ItemMeta.consumable\n\t                        if Consumable then\n\t                            local Effect: string = Consumable.statusEffect and Consumable.statusEffect.statusEffectType or ({v:gsub(\"_potion\", \"\")})[1]\n\t                            if not LocalPlayer.Character:GetAttribute(`StatusEffect_{Effect}`) then\n\t                                bedwars.Handler:Get(\"ConsumeItem\"):Fire(\"CallServerAsync\", {item = Item.tool})\n\t                                task.wait(Consumable.consumeTime or 1)\n\t                                break\n\t                            end\n\t                        end\n\t                    end\n\t                end\n\t                task.wait(Delay.Value)\n\t            until not AutoUse.Enabled\n\t        end\n\t    end,\n\t    Tooltip = \"Drinks and eats the buff items you list as soon as their effect runs out\"\n\t})\n\t\n\tItems = AutoUse:CreateTextList({\n\t    Name = \"Items\",\n\t    Default = {\"fury_potion\", \"crit_star\", \"vitality_star\", \"pie\"},\n\t    Tooltip = \"Item ids, anything the game lets you consume\\nfury_potion, jump_potion, serpents_touch_potion, crit_star, vitality_star, snow_cone, pie, watermelon, can_of_beans, sparkling_apple_juice\"\n\t})\n\tCombat = AutoUse:CreateToggle({\n\t    Name = \"In combat only\",\n\t    Tooltip = \"Saves them until something has hit you in the last 6 seconds\"\n\t})\n\tDelay = AutoUse:CreateSlider({\n\t    Name = \"Delay\",\n\t    Min = 0.1,\n\t    Max = 5,\n\t    Default = 0.5,\n\t    Decimal = 10,\n\t    Suffix = \"seconds\"\n\t})\nend)\n\nRun(function()\n\tlocal Value\n\tlocal OldClickHold, OldShowProgress\n\t\n\tlocal FastConsume = vape.Categories.Inventory:CreateModule({\n\t    Name = \"FastConsume\",\n\t    Function = function(Callback: boolean)\n\t        if Callback then\n\t            OldClickHold = bedwars.ClickHold.startClick\n\t            OldShowProgress = bedwars.ClickHold.showProgress\n\t            bedwars.ClickHold.startClick = function(self)\n\t                self.startedClickTime = tick()\n\t                local Handle = self:showProgress()\n\t                local ClickTime: number = self.startedClickTime\n\t                bedwars.RuntimeLib.Promise.defer(function()\n\t                    task.wait(self.durationSeconds * (Value.Value / 40))\n\t                    if Handle == self.handle and ClickTime == self.startedClickTime and self.closeOnComplete then\n\t                        self:hideProgress()\n\t                        if self.onComplete then\n\t                            self.onComplete()\n\t                        end\n\t                        if self.onPartialComplete then\n\t                            self.onPartialComplete(1)\n\t                        end\n\t                        self.startedClickTime = -1\n\t                    end\n\t                end)\n\t            end\n\t\n\t            bedwars.ClickHold.showProgress = function(self)\n\t                local Roact = debug.getupvalue(OldShowProgress, 1)\n\t                local Countdown = Roact.mount(Roact.createElement(\"ScreenGui\", {}, {Roact.createElement(\"Frame\", {\n\t                    [Roact.Ref] = self.wrapperRef,\n\t                    Size = UDim2.new(),\n\t                    Position = UDim2.fromScale(0.5, 0.55),\n\t                    AnchorPoint = Vector2.new(0.5, 0),\n\t                    BackgroundColor3 = Color3.fromRGB(0, 0, 0),\n\t                    BackgroundTransparency = 0.8\n\t                }, {Roact.createElement(\"Frame\", {\n\t                    [Roact.Ref] = self.progressRef,\n\t                    Size = UDim2.fromScale(0, 1),\n\t                    BackgroundColor3 = Color3.new(1, 1, 1),\n\t                    BackgroundTransparency = 0.5\n\t                })})}), LocalPlayer:FindFirstChild(\"PlayerGui\"))\n\t\n\t                self.handle = Countdown\n\t                local SizeTween: Tween = TweenService:Create(self.wrapperRef:getValue(), TweenInfo.new(0.1), {\n\t                    Size = UDim2.fromScale(0.11, 0.005)\n\t                })\n\t                local CountdownTween: Tween = TweenService:Create(self.progressRef:getValue(), TweenInfo.new(self.durationSeconds * (Value.Value / 100), Enum.EasingStyle.Linear), {\n\t                    Size = UDim2.fromScale(1, 1)\n\t                })\n\t\n\t                SizeTween:Play()\n\t                CountdownTween:Play()\n\t                table.insert(self.tweens, CountdownTween)\n\t                table.insert(self.tweens, SizeTween)\n\t\n\t                return Countdown\n\t            end\n\t        else\n\t            bedwars.ClickHold.startClick = OldClickHold\n\t            bedwars.ClickHold.showProgress = OldShowProgress\n\t        end\n\t    end,\n\t    Tooltip = \"Use/Consume items quicker.\"\n\t})\n\t\n\tValue = FastConsume:CreateSlider({\n\t    Name = \"Multiplier\",\n\t    Min = 0,\n\t    Max = 100\n\t})\nend)\n\nRun(function()\n\tlocal FastDrop\n\t\n\tFastDrop = vape.Categories.Inventory:CreateModule({\n\t    Name = \"FastDrop\",\n\t    Function = function(Callback: boolean)\n\t        if Callback then\n\t            repeat\n\t                if Entity.isAlive and (not Store.inventory.opened) and (UserInputService:IsKeyDown(Enum.KeyCode.H) or UserInputService:IsKeyDown(Enum.KeyCode.Backspace)) and UserInputService:GetFocusedTextBox() == nil then\n\t                    task.spawn(bedwars.ItemDropController.dropItemInHand)\n\t                    task.wait()\n\t                else\n\t                    task.wait(0.1)\n\t                end\n\t            until not FastDrop.Enabled\n\t        end\n\t    end,\n\t    Tooltip = \"Drops items fast when you hold Q\"\n\t})\nend)\n\nRun(function()\n\tlocal AutoAbaddon\n\tlocal Delay\n\tlocal Limit\n\tlocal Range\n\tlocal NextPlace: number = 0\n\t\n\tAutoAbaddon = vape.Categories.Kits:CreateModule({\n\t    Name = \"AutoAbaddon\",\n\t    Function = function(Callback: boolean)\n\t        if Callback then\n\t            NextPlace = 0\n\t\n\t            repeat\n\t                if Entity.isAlive and Store.equippedKit == \"scarab\" and tick() >= NextPlace and bedwars.AbilityController:canUseAbility(\"place_scarab_hive\", {disableBlockedAbilityAlert = true}) then\n\t                    local Origin: Vector3 = Entity.character.RootPart.Position\n\t                    local Hives: number = 0\n\t\n\t                    for _, v: Instance in CollectionService:GetTagged(\"scarab_spawner\") do\n\t                        local Part = v:IsA(\"Model\") and v.PrimaryPart or v\n\t                        if Part and Part:GetAttribute(\"PlacedByUserId\") == LocalPlayer.UserId and (Part.Position - Origin).Magnitude <= Range.Value then\n\t                            Hives += 1\n\t                        end\n\t                    end\n\t\n\t                    if Hives < Limit.Value then\n\t                        NextPlace = tick() + Delay.Value\n\t                        bedwars.AbilityController:useAbility(\"place_scarab_hive\")\n\t                    end\n\t                end\n\t                task.wait(0.1)\n\t            until not AutoAbaddon.Enabled\n\t        end\n\t    end,\n\t    Tooltip = \"Keeps scarab hives up around you without spamming the ability\"\n\t})\n\t\n\tLimit = AutoAbaddon:CreateSlider({\n\t    Name = \"Hives\",\n\t    Min = 1,\n\t    Max = 10,\n\t    Default = 3,\n\t    Tooltip = \"Stops once this many of your hives are already standing nearby\"\n\t})\n\tRange = AutoAbaddon:CreateSlider({\n\t    Name = \"Range\",\n\t    Min = 5,\n\t    Max = 100,\n\t    Default = 40,\n\t    Suffix = function(Val: number)\n\t        return Val <= 1 and \"stud\" or \"studs\"\n\t    end,\n\t    Tooltip = \"How far out hives still count toward the limit\"\n\t})\n\tDelay = AutoAbaddon:CreateSlider({\n\t    Name = \"Delay\",\n\t    Min = 0.1,\n\t    Max = 5,\n\t    Default = 1.5,\n\t    Decimal = 100,\n\t    Suffix = function(Val: number)\n\t        return Val <= 1 and \"sec\" or \"secs\"\n\t    end\n\t})\nend)\n\nRun(function()\n\tlocal AutoAdetunde\n\tlocal GUI\n\tlocal Last\n\t\n\tlocal Upgrades: {string} = {}\n\tfor Upgrade: string in bedwars.AdetundeUpgradeMeta do\n\t    table.insert(Upgrades, Upgrade)\n\tend\n\ttable.sort(Upgrades)\n\t\n\tlocal function GetBuyOrder(Tiers: {[string]: number}): {string}\n\t    local LastUpgrade: string? = Last.Value ~= \"None\" and Last.Value or nil\n\t    local Order, Waiting = {}, false\n\t    for _, v: string in Upgrades do\n\t        if Tiers[v] == nil or v == LastUpgrade then\n\t            continue\n\t        end\n\t        table.insert(Order, v)\n\t        if AutoAdetunde.Options[`Buy {v}`].Enabled and bedwars.AdetundeUpgradeMeta[v].tiers[Tiers[v] + 1] then\n\t            Waiting = true\n\t        end\n\t    end\n\t    if LastUpgrade and Tiers[LastUpgrade] and not Waiting then\n\t        table.insert(Order, LastUpgrade)\n\t    end\n\t    return Order\n\tend\n\t\n\tAutoAdetunde = vape.Categories.Kits:CreateModule({\n\t    Name = \"AutoAdetunde\",\n\t    Function = function(Callback: boolean)\n\t        if Callback then\n\t            repeat\n\t                if not GUI.Enabled or bedwars.AppController:isAppOpen(\"FrostyHammerApp\") then\n\t                    local Tiers: {[string]: number} = bedwars.AdetundeUtil.getUpgradesFromHammer(LocalPlayer) or {}\n\t                    for _, Upgrade: string in GetBuyOrder(Tiers) do\n\t                        local Crystal = GetItem(\"frost_crystal\")\n\t                        if not Crystal then\n\t                            break\n\t                        end\n\t\n\t                        local NextUpgrade = AutoAdetunde.Options[`Buy {Upgrade}`].Enabled and bedwars.AdetundeUpgradeMeta[Upgrade].tiers[Tiers[Upgrade] + 1]\n\t                        if NextUpgrade and Crystal.amount >= NextUpgrade.price then\n\t                            bedwars.Handler:Get(\"UpgradeFrostyHammer\"):Fire(\"CallServer\", Upgrade)\n\t                            task.wait(0.1)\n\t                        end\n\t                    end\n\t                end\n\t                task.wait(0.5)\n\t            until not AutoAdetunde.Enabled\n\t        end\n\t    end,\n\t    Tooltip = \"Automatically upgrades ur frosty hammer\"\n\t})\n\t\n\tfor _, v: string in Upgrades do\n\t    AutoAdetunde:CreateToggle({\n\t        Name = `Buy {v}`,\n\t        Default = true\n\t    })\n\tend\n\t\n\tlocal LastList: {string} = {\"None\"}\n\tfor _, v: string in Upgrades do\n\t    table.insert(LastList, v)\n\tend\n\tLast = AutoAdetunde:CreateDropdown({\n\t    Name = \"Last upgrade\",\n\t    List = LastList,\n\t    Default = \"None\",\n\t    Tooltip = \"Saves this upgrade for last, so your crystals go into the others until they are maxed\"\n\t})\n\t\n\tGUI = AutoAdetunde:CreateToggle({\n\t    Name = \"GUI Check\",\n\t    Tooltip = \"Only upgrades while the frosty hammer menu is open\"\n\t})\nend)\n\nRun(function()\n\tlocal AutoAgni\n\tlocal VoidSave\n\tlocal Escape\n\tlocal Targets\n\tlocal Health\n\tlocal Range\n\tlocal NextBoost: number = 0\n\t\n\tAutoAgni = vape.Categories.Kits:CreateModule({\n\t    Name = \"AutoAgni\",\n\t    Function = function(Callback: boolean)\n\t        if Callback then\n\t            NextBoost = 0\n\t\n\t            repeat\n\t                if Entity.isAlive and Store.equippedKit == \"agni\" and tick() >= NextBoost and bedwars.AbilityController:canUseAbility(\"rocket_detonate\", {disableBlockedAbilityAlert = true}) then\n\t                    local Root: BasePart = Entity.character.RootPart\n\t                    local Humanoid: Humanoid = Entity.character.Humanoid\n\t                    local Boost: boolean = false\n\t\n\t                    if VoidSave.Enabled and Root.AssemblyLinearVelocity.Y <= -20 and not workspace:Raycast(Root.Position, Vector3.new(0, -2000, 0), Store.airRay) then\n\t                        Boost = true\n\t                    end\n\t\n\t                    if not Boost and Escape.Enabled and Humanoid.Health <= (Humanoid.MaxHealth * (Health.Value / 100)) then\n\t                        Boost = #Entity.AllPosition({\n\t                            Range = Range.Value,\n\t                            Part = \"RootPart\",\n\t                            Players = Targets.Players.Enabled,\n\t                            NPCs = Targets.NPCs.Enabled\n\t                        }) > 0\n\t                    end\n\t\n\t                    if Boost then\n\t                        NextBoost = tick() + 1\n\t                        bedwars.AbilityController:useAbility(\"rocket_detonate\")\n\t                    end\n\t                end\n\t                task.wait(0.05)\n\t            until not AutoAgni.Enabled\n\t        end\n\t    end,\n\t    Tooltip = \"Spends Rocket Boost on saving you from the void and on getting out of fights you are losing\"\n\t})\n\t\n\tVoidSave = AutoAgni:CreateToggle({\n\t    Name = \"Void save\",\n\t    Default = true,\n\t    Tooltip = \"Boosts the moment you drop off the map with nothing below you\"\n\t})\n\tEscape = AutoAgni:CreateToggle({\n\t    Name = \"Escape\",\n\t    Default = true,\n\t    Function = function(Callback: boolean)\n\t        if Range then\n\t            Health.Object.Visible = Callback\n\t            Range.Object.Visible = Callback\n\t            Targets.Object.Visible = Callback\n\t        end\n\t    end,\n\t    Tooltip = \"Boosts away once you are low and somebody is on you\"\n\t})\n\tTargets = AutoAgni:CreateTargets({\n\t    Players = true,\n\t    NPCs = true\n\t})\n\tHealth = AutoAgni:CreateSlider({\n\t    Name = \"Health\",\n\t    Min = 1,\n\t    Max = 100,\n\t    Default = 35,\n\t    Suffix = \"%\"\n\t})\n\tRange = AutoAgni:CreateSlider({\n\t    Name = \"Range\",\n\t    Min = 1,\n\t    Max = 60,\n\t    Default = 20,\n\t    Suffix = function(Val: number)\n\t        return Val <= 1 and \"stud\" or \"studs\"\n\t    end\n\t})\nend)\n\nRun(function()\n\tlocal AutoArachne\n\tlocal Targets\n\tlocal Range\n\tlocal Amount\n\t\n\tAutoArachne = vape.Categories.Kits:CreateModule({\n\t    Name = \"AutoArachne\",\n\t    Function = function(Callback: boolean)\n\t        if Callback then\n\t            repeat\n\t                if Entity.isAlive and Store.equippedKit == \"spider_queen\" and bedwars.AbilityController:canUseAbility(\"spider_queen_summon_spiders\", {disableBlockedAbilityAlert = true}) then\n\t                    local Found: number = #Entity.AllPosition({\n\t                        Range = Range.Value,\n\t                        Part = \"RootPart\",\n\t                        Players = Targets.Players.Enabled,\n\t                        NPCs = Targets.NPCs.Enabled,\n\t                        Wallcheck = Targets.Walls.Enabled\n\t                    })\n\t\n\t                    if Found >= Amount.Value then\n\t                        bedwars.AbilityController:useAbility(\"spider_queen_summon_spiders\")\n\t                    end\n\t                end\n\t                task.wait(0.1)\n\t            until not AutoArachne.Enabled\n\t        end\n\t    end,\n\t    Tooltip = \"Automatically summons spiders once an enemy is nearby\"\n\t})\n\t\n\tTargets = AutoArachne:CreateTargets({\n\t    Players = true,\n\t    NPCs = true\n\t})\n\tRange = AutoArachne:CreateSlider({\n\t    Name = \"Range\",\n\t    Min = 1,\n\t    Max = 60,\n\t    Default = 30,\n\t    Suffix = function(Val: number)\n\t        return Val <= 1 and \"stud\" or \"studs\"\n\t    end\n\t})\n\tAmount = AutoArachne:CreateSlider({\n\t    Name = \"Targets\",\n\t    Min = 1,\n\t    Max = 8,\n\t    Default = 1,\n\t    Tooltip = \"Enemies in range before summoning\"\n\t})\nend)\n\nRun(function()\n\tlocal AutoBee\n\tlocal Collect\n\tlocal CollectRange\n\tlocal CollectDelay\n\tlocal Switch\n\tlocal LimitCollect\n\tlocal Deposit\n\tlocal DepositRange\n\tlocal DepositDelay\n\t\n\tAutoBee = vape.Categories.Kits:CreateModule({\n\t    Name = \"AutoBeekeeper\",\n\t    Function = function(Callback: boolean)\n\t        if Callback then\n\t            local Hives: {BasePart} = Collection(\"beehive\", AutoBee)\n\t\n\t            repeat\n\t                if Entity.isAlive then\n\t                    local LocalPosition: Vector3 = Entity.character.RootPart.Position\n\t\n\t                    if Collect.Enabled and (not LimitCollect.Enabled or Store.hand.tool and Store.hand.tool.Name == \"bee_net\") then\n\t                        for _, v: Model in CollectionService:GetTagged(\"bee\") do\n\t                            local Root = v.PrimaryPart or v:FindFirstChild(\"Root\")\n\t                            if Root and (LocalPosition - Root.Position).Magnitude <= CollectRange.Value then\n\t                                local Net = Switch.Enabled and GetItem(\"bee_net\")\n\t                                if Net then\n\t                                    SwitchItem(Net.tool)\n\t                                end\n\t                                bedwars.Handler:Get(\"PickUpBee\"):Fire(\"SendToServer\", {\n\t                                    beeId = v:GetAttribute(\"BeeId\")\n\t                                })\n\t\n\t                                if CollectDelay.Value > 0 then\n\t                                    task.wait(CollectDelay.Value)\n\t                                end\n\t                            end\n\t                        end\n\t                    end\n\t\n\t                    if Deposit.Enabled and GetItem(\"bee\") then\n\t                        for _, v: BasePart in Hives do\n\t                            if not GetItem(\"bee\") then\n\t                                break\n\t                            end\n\t\n\t                            local Prompt: ProximityPrompt? = v:FindFirstChildWhichIsA(\"ProximityPrompt\")\n\t                            if Prompt and (v:GetAttribute(\"Level\") or 0) < 10 and v:GetAttribute(\"PlacedByUserId\") == LocalPlayer.UserId and (LocalPosition - v.Position).Magnitude <= DepositRange.Value then\n\t                                task.spawn(fireproximityprompt, Prompt)\n\t\n\t                                if DepositDelay.Value > 0 then\n\t                                    task.wait(DepositDelay.Value)\n\t                                end\n\t                            end\n\t                        end\n\t                    end\n\t                end\n\t                task.wait(0.1)\n\t            until not AutoBee.Enabled\n\t        end\n\t    end,\n\t    Tooltip = \"Automatically deposit bees, and collects nearby bees\"\n\t})\n\t\n\tCollect = AutoBee:CreateToggle({\n\t    Name = \"Collect bees\",\n\t    Function = function(Callback: boolean)\n\t        if CollectRange then\n\t            CollectRange.Object.Visible = Callback\n\t            CollectDelay.Object.Visible = Callback\n\t            Switch.Object.Visible = Callback\n\t            LimitCollect.Object.Visible = Callback\n\t        end\n\t    end,\n\t    Default = true\n\t})\n\tCollectRange = AutoBee:CreateSlider({\n\t    Name = \"Collect Range\",\n\t    Min = 1,\n\t    Max = 22,\n\t    Default = 20,\n\t    Darker = true,\n\t    Suffix = function(Val: number)\n\t        return Val <= 1 and \"stud\" or \"studs\"\n\t    end\n\t})\n\tCollectDelay = AutoBee:CreateSlider({\n\t    Name = \"Collect delay\",\n\t    Min = 0,\n\t    Max = 2,\n\t    Default = 0.1,\n\t    Decimal = 100,\n\t    Darker = true\n\t})\n\tSwitch = AutoBee:CreateToggle({\n\t    Name = \"Auto Switch\",\n\t    Default = true,\n\t    Darker = true,\n\t    Tooltip = \"Puts the bee net in your hand before catching, the server ignores the catch without it\"\n\t})\n\tLimitCollect = AutoBee:CreateToggle({\n\t    Name = \"Limit to item\",\n\t    Darker = true\n\t})\n\tDeposit = AutoBee:CreateToggle({\n\t    Name = \"Deposit bees\",\n\t    Function = function(Callback: boolean)\n\t        if DepositRange then\n\t            DepositRange.Object.Visible = Callback\n\t            DepositDelay.Object.Visible = Callback\n\t        end\n\t    end,\n\t    Tooltip = \"Automatically puts the bees into a beehive\"\n\t})\n\tDepositRange = AutoBee:CreateSlider({\n\t    Name = \"Deposit Range\",\n\t    Min = 1,\n\t    Max = 14,\n\t    Default = 14,\n\t    Darker = true,\n\t    Visible = false,\n\t    Suffix = function(Val: number)\n\t        return Val <= 1 and \"stud\" or \"studs\"\n\t    end\n\t})\n\tDepositDelay = AutoBee:CreateSlider({\n\t    Name = \"Deposit Delay\",\n\t    Min = 0,\n\t    Max = 2,\n\t    Default = 0.1,\n\t    Decimal = 100,\n\t    Darker = true,\n\t    Visible = false\n\t})\nend)\n\nRun(function()\n\tlocal AutoBountyHunter\n\tlocal Track\n\tlocal Reroll\n\tlocal RerollRange\n\tlocal Delay\n\t\n\tlocal TrackCooldown, RerollCooldown = 0, 0\n\tlocal TrackAbilities: {string} = {\"bounty_hunter_4\", \"bounty_hunter_3\", \"bounty_hunter_2\", \"bounty_hunter_1\"}\n\t\n\tlocal function GetTrackAbility(): string\n\t    local EnabledAbilities = bedwars.AbilityController.enabledAbilities\n\t    for _, v: string in TrackAbilities do\n\t        if EnabledAbilities and EnabledAbilities[v] then\n\t            return v\n\t        end\n\t    end\n\t\n\t    local Level: number = bedwars.BountyHunterUtil and bedwars.BountyHunterUtil.getBountyHunterLevel(LocalPlayer) or 0\n\t    return `bounty_hunter_{math.clamp(Level + 1, 1, 4)}`\n\tend\n\t\n\tlocal function UseAbility(Ability: string): boolean\n\t    if not bedwars.AbilityController:canUseAbility(Ability, {disableBlockedAbilityAlert = true}) then\n\t        return false\n\t    end\n\t    bedwars.AbilityController:useAbility(Ability)\n\t    return true\n\tend\n\t\n\tAutoBountyHunter = vape.Categories.Kits:CreateModule({\n\t    Name = \"AutoBountyHunter\",\n\t    Function = function(Callback: boolean)\n\t        if Callback then\n\t            TrackCooldown, RerollCooldown = 0, 0\n\t\n\t            repeat\n\t                if Entity.isAlive and Store.equippedKit == \"bounty_hunter\" then\n\t                    local Kit = bedwars.Store:getState().Kit\n\t                    local Target = Kit and Kit.bountyHunterTarget\n\t                    local Ent = Target and Entity.getEntity(Target)\n\t\n\t                    if Track.Enabled and Target and tick() >= TrackCooldown and UseAbility(GetTrackAbility()) then\n\t                        TrackCooldown = tick() + Delay.Value\n\t                    end\n\t\n\t                    if Reroll.Enabled and tick() >= RerollCooldown then\n\t                        local Distance: number = Ent and Ent.RootPart and (Ent.RootPart.Position - Entity.character.RootPart.Position).Magnitude or math.huge\n\t                        if Distance > RerollRange.Value and UseAbility(\"bounty_hunter_reroll\") then\n\t                            RerollCooldown = tick() + 1\n\t                        end\n\t                    end\n\t                end\n\t                task.wait(0.1)\n\t            until not AutoBountyHunter.Enabled\n\t        end\n\t    end,\n\t    Tooltip = \"Keeps the bounty tracker up on your target and rerolls bounties you cannot reach\"\n\t})\n\t\n\tTrack = AutoBountyHunter:CreateToggle({\n\t    Name = \"Auto track\",\n\t    Default = true,\n\t    Tooltip = \"Uses the tracking ability whenever it comes off cooldown, the marker lasts 15 seconds\"\n\t})\n\tDelay = AutoBountyHunter:CreateSlider({\n\t    Name = \"Delay\",\n\t    Min = 0,\n\t    Max = 5,\n\t    Default = 0.5,\n\t    Decimal = 10,\n\t    Suffix = \"seconds\"\n\t})\n\tReroll = AutoBountyHunter:CreateToggle({\n\t    Name = \"Auto reroll\",\n\t    Tooltip = \"Rerolls the bounty when your target is dead, gone or further away than the range below\"\n\t})\n\tRerollRange = AutoBountyHunter:CreateSlider({\n\t    Name = \"Reroll range\",\n\t    Min = 10,\n\t    Max = 500,\n\t    Default = 250,\n\t    Darker = true,\n\t    Suffix = function(Val: number)\n\t        return Val <= 1 and \"stud\" or \"studs\"\n\t    end\n\t})\nend)\n\nRun(function()\n\tlocal AutoBuilder\n\tlocal Animation\n\tlocal Blacklist\n\tlocal BedCheck\n\tlocal Limit\n\tlocal BlockNames: {[BasePart]: string} = setmetatable({}, {__mode = \"k\"})\n\t\n\tlocal function GetBed(Position: Vector3): BasePart?\n\t    local Bed, LastMagnitude = nil, math.huge\n\t    local NoBreak: string = `Team{LocalPlayer:GetAttribute(\"Team\") or -1}NoBreak`\n\t    for _, v: BasePart in CollectionService:GetTagged(\"bed\") do\n\t        local Magnitude: number = (Position - v.Position).Magnitude\n\t        if Magnitude < LastMagnitude and v:GetAttribute(NoBreak) then\n\t            Bed, LastMagnitude = v, Magnitude\n\t        end\n\t    end\n\t    return Bed\n\tend\n\t\n\tAutoBuilder = vape.Categories.Kits:CreateModule({\n\t    Name = \"AutoBuilder\",\n\t    Function = function(Callback: boolean)\n\t        if Callback then\n\t            repeat\n\t                task.wait()\n\t            until Store.matchState ~= 0 and Store.equippedKit == \"builder\" or not AutoBuilder.Enabled\n\t            if not AutoBuilder.Enabled then\n\t                return\n\t            end\n\t\n\t            local Blocks: {BasePart} = Collection(\"block\", AutoBuilder, function(List: {BasePart}, Block: BasePart)\n\t                task.delay(0, function()\n\t                    if not Block:GetAttribute(\"NoBreak\") and Block:GetAttribute(\"PlacedByUserId\") then\n\t                        BlockNames[Block] = Block.Name:find(\"wool_\") and \"wool\" or Block.Name\n\t                        table.insert(List, Block)\n\t                    end\n\t                end)\n\t            end)\n\t\n\t            repeat\n\t                if Entity.isAlive and (not Limit.Enabled and GetItem(\"hammer\") or Limit.Enabled and Store.hand.tool and Store.hand.tool.Name == \"hammer\") then\n\t                    local Bed: BasePart? = BedCheck.Enabled and GetBed(Entity.character.RootPart.Position) or nil\n\t\n\t                    for _, v: BasePart in Blocks do\n\t                        if table.find(Blacklist.ListEnabled, BlockNames[v]) then\n\t                            continue\n\t                        end\n\t\n\t                        if not BedCheck.Enabled or Bed and (Bed.Position - v.Position).Magnitude <= 30 then\n\t                            if not v:FindFirstChild(\"BuilderFortify\") then\n\t                                bedwars.Handler:Get(\"FortifyBlock\"):Fire(\"SendToServer\", bedwars.BlockController:getBlockPosition(v.Position))\n\t\n\t                                if Animation.Enabled then\n\t                                    bedwars.GameAnimationUtil:playAnimation(LocalPlayer, bedwars.GameAnimationUtil:getAssetId(bedwars.AnimationType.BUILDER_HAMMER_HIT), {\n\t                                        fadeInTime = 0.02\n\t                                    })\n\t                                    bedwars.AudioManager:playAudio(bedwars.SoundList.FORTIFY_BLOCK, {\n\t                                        position = Entity.character.RootPart.Position\n\t                                    })\n\t                                end\n\t                            end\n\t                        end\n\t                    end\n\t                end\n\t                task.wait(0.1)\n\t            until not AutoBuilder.Enabled\n\t        end\n\t    end,\n\t    Tooltip = \"Automatically fortifies your blocks with the builder hammer\"\n\t})\n\t\n\tBedCheck = AutoBuilder:CreateToggle({\n\t    Name = \"Bed Check\",\n\t    Tooltip = \"Checks if the block is near your bed\"\n\t})\n\tAnimation = AutoBuilder:CreateToggle({\n\t    Name = \"Animation\",\n\t    Default = true,\n\t    Tooltip = \"Plays builder visuals (sfx and anim)\"\n\t})\n\tLimit = AutoBuilder:CreateToggle({\n\t    Name = \"Limit to items\",\n\t    Default = true\n\t})\n\tBlacklist = AutoBuilder:CreateTextList({\n\t    Name = \"Blacklists\",\n\t    Placeholder = \"block\",\n\t    Default = {\"cannon\", \"wool\"}\n\t})\nend)\n\nRun(function()\n\tlocal AutoCaitlyn\n\tlocal Mode\n\tlocal TargetMode\n\tlocal Range\n\tlocal MinHP\n\tlocal TargetPriorities\n\tlocal DropContract\n\tlocal ActiveSession\n\t\n\tlocal Success, BloodAssassinUtil = pcall(function()\n\t    return require(ReplicatedStorage.TS.games.bedwars.kit.kits[\"blood-assassin\"][\"blood-assassin-util\"]).BloodAssassinUtil\n\tend)\n\tlocal AbandonTime: number = Success and BloodAssassinUtil.ABANDON_TIME_SEC or 60\n\t\n\tlocal function GetValidTargets(WallCheck: boolean)\n\t    local Targets = {}\n\t    for _, v: any in Entity.AllPosition({\n\t        Part = \"RootPart\",\n\t        Players = true,\n\t        Range = Range.Value,\n\t        Wallcheck = WallCheck\n\t    }) do\n\t        if not (v.Player.Team and v.Player.Team.Name == \"Spectators\") then\n\t            Targets[v.Player] = v\n\t            Targets[v.Character] = v\n\t        end\n\t    end\n\t    return Targets\n\tend\n\t\n\tlocal function GetScore(Session, Contract, Targets)\n\t    local Ent = Targets[Contract.target]\n\t    if not Ent then\n\t        return nil\n\t    end\n\t\n\t    local Health: number = Ent.Humanoid.Health\n\t    local Distance: number = (Entity.character.RootPart.Position - Ent.RootPart.Position).Magnitude\n\t    local Score: number = 30 + ((tonumber(Contract.rewardValue) or 0) * 35)\n\t    Score += (1 - math.clamp(Health / math.max(Ent.Humanoid.MaxHealth, 1), 0, 1)) * 35\n\t    Score += math.max(1 - (Distance / Range.Value), 0) * 20\n\t\n\t    if Health <= MinHP.Value then\n\t        Score += 20\n\t    end\n\t    if (Session.threats[Ent.Player] or 0) > tick() then\n\t        Score += 30\n\t    end\n\t    if Ent.Character:GetAttribute(\"BleedSource\") == LocalPlayer.UserId then\n\t        Score += 25\n\t    end\n\t    local Success, Team = pcall(bedwars.TeamController.getPlayerTeam, bedwars.TeamController, Ent.Player)\n\t    local TeamId = Success and Team and Team.id or Ent.Player:GetAttribute(\"Team\")\n\t    local Bed = true\n\t    if TeamId ~= nil then\n\t        local Cached = Session.beds[TeamId]\n\t        if Cached and Cached[2] > tick() then\n\t            Bed = Cached[1]\n\t        else\n\t            Success, Team = pcall(bedwars.BedwarsController.getTeamBed, bedwars.BedwarsController, TeamId)\n\t            Bed = not Success or Team and Team.Parent\n\t            Session.beds[TeamId] = {Bed, tick() + 1}\n\t        end\n\t    end\n\t\n\t    if not Bed then\n\t        Score += 20\n\t    end\n\t\n\t    local Reward = Contract.rewardExplanation\n\t    if type(Reward) == \"table\" then\n\t        Score += (Reward.assassin and 10 or 0) + (Reward.kitClass and 8 or 0) + (Reward.gear and 6 or 0)\n\t    end\n\t    return Score, Ent\n\tend\n\t\n\tlocal function GetPriorityContract(Session, Contracts)\n\t    local Bounty: boolean = false\n\t    for _, v: any in Contracts do\n\t        if v.rewardValue or v.rewardUpgrade then\n\t            Bounty = true\n\t            break\n\t        end\n\t    end\n\t    if not Bounty then\n\t        return nil, false\n\t    end\n\t\n\t    local Targets = GetValidTargets(true)\n\t    local Current, CurrentScore\n\t    if Session.priorityId then\n\t        for _, v: any in Contracts do\n\t            if v.id == Session.priorityId then\n\t                Current, CurrentScore = v, GetScore(Session, v, Targets)\n\t                break\n\t            end\n\t        end\n\t    end\n\t\n\t    local Best, BestScore\n\t    for _, v: any in Contracts do\n\t        local Score: number? = GetScore(Session, v, Targets)\n\t        if Score and (not BestScore or Score > BestScore) then\n\t            Best, BestScore = v, Score\n\t        end\n\t    end\n\t\n\t    if Current and CurrentScore and Best ~= Current and BestScore < CurrentScore + 15 then\n\t        Best = Current\n\t    end\n\t\n\t    Session.priorityId = Best and Best.id or nil\n\t    return Best, true\n\tend\n\t\n\tlocal function GetNormalContract(Session, Contracts)\n\t    local Offered: {[string]: any} = {}\n\t    for _, v: any in Contracts do\n\t        if v.target then\n\t            Offered[v.target.Name] = v\n\t        end\n\t    end\n\t\n\t    for _, v: any in Entity.AllPosition({\n\t        Part = \"RootPart\",\n\t        Players = true,\n\t        Range = Range.Value,\n\t        Sort = SortMethods[TargetMode.Value]\n\t    }) do\n\t        local Contract = Offered[v.Player.Name]\n\t        if Contract and (Session.hits[v.Character] or 0) > tick() and not (v.Player.Team and v.Player.Team.Name == \"Spectators\") then\n\t            if Mode.Value ~= \"On Low\" or v.Humanoid.Health < MinHP.Value then\n\t                return Contract\n\t            end\n\t        end\n\t    end\n\t    return nil\n\tend\n\t\n\tlocal function CanDrop(Contract): boolean\n\t    local Activation: number? = tonumber(Contract.activationTime)\n\t    if not Activation or (workspace:GetServerTimeNow() - Activation) < AbandonTime then\n\t        return false\n\t    end\n\t\n\t    local Ent = Contract.target and Entity.getEntity(Contract.target)\n\t    if not Ent or Ent.Health <= 0 then\n\t        return true\n\t    end\n\t    return (Ent.RootPart.Position - Entity.character.RootPart.Position).Magnitude > Range.Value\n\tend\n\t\n\tlocal function UpdateCaitlyn(Session)\n\t    if not Entity.isAlive or Store.matchState ~= 1 or Store.equippedKit ~= \"blood_assassin\" then\n\t        table.clear(Session.hits)\n\t        Session.pendingId = nil\n\t        Session.priorityId = nil\n\t        return\n\t    end\n\t\n\t    local Kit = bedwars.Store:getState().Kit\n\t    local Active = Kit and Kit.activeContract\n\t    if not Kit or Active then\n\t        Session.pendingId = nil\n\t        Session.priorityId = Active and Active.id or nil\n\t        if Active and DropContract.Enabled and Session.dropUntil <= tick() and CanDrop(Active) then\n\t            bedwars.Handler:Get(\"BloodAssassinSelectContract\"):Fire(\"SendToServer\", {\n\t                contractId = nil\n\t            })\n\t            Session.dropUntil = tick() + 5\n\t        end\n\t        return\n\t    end\n\t\n\t    if Session.pendingId and Session.pendingUntil > tick() then\n\t        return\n\t    end\n\t    Session.pendingId = nil\n\t\n\t    local Contracts = Kit.availableContracts\n\t    if not Contracts or #Contracts == 0 then\n\t        return\n\t    end\n\t\n\t    local Contract\n\t    if TargetPriorities.Enabled then\n\t        local Available\n\t        Contract, Available = GetPriorityContract(Session, Contracts)\n\t        if not Available then\n\t            Contract = GetNormalContract(Session, Contracts)\n\t        end\n\t    else\n\t        Session.priorityId = nil\n\t        Contract = GetNormalContract(Session, Contracts)\n\t    end\n\t    if Contract and not (Session.pendingId == Contract.id and Session.pendingUntil > tick()) then\n\t        bedwars.Handler:Get(\"BloodAssassinSelectContract\"):Fire(\"SendToServer\", {\n\t            contractId = Contract.id\n\t        })\n\t        Session.pendingId = Contract.id\n\t        Session.pendingUntil = tick() + 1\n\t    end\n\tend\n\t\n\tAutoCaitlyn = vape.Categories.Kits:CreateModule({\n\t    Name = \"AutoCaitlyn\",\n\t    Function = function(Callback: boolean)\n\t        if Callback then\n\t            local Session = {\n\t                beds = {},\n\t                dropUntil = 0,\n\t                hits = setmetatable({}, {__mode = \"k\"}),\n\t                nextUpdate = 0,\n\t                pendingUntil = 0,\n\t                threats = {}\n\t            }\n\t            ActiveSession = Session\n\t\n\t            AutoCaitlyn:Clean(VapeEvents.EntityDamageEvent.Event:Connect(function(DamageTable)\n\t                if ActiveSession ~= Session then\n\t                    return\n\t                end\n\t\n\t                local Source = (typeof(DamageTable.fromEntity) == \"Instance\" and Entity.getEntity(DamageTable.fromEntity) or nil)\n\t                if DamageTable.entityInstance == LocalPlayer.Character and Source and Source.Player then\n\t                    Session.threats[Source.Player] = tick() + 3\n\t                elseif DamageTable.fromEntity == LocalPlayer.Character or DamageTable.fromEntity == LocalPlayer then\n\t                    local Victim = (typeof(DamageTable.entityInstance) == \"Instance\" and Entity.getEntity(DamageTable.entityInstance) or nil)\n\t                    if Victim and Victim.Character then\n\t                        Session.hits[Victim.Character] = tick() + 1\n\t                    end\n\t                end\n\t            end))\n\t\n\t            AutoCaitlyn:Clean(VapeEvents.BedwarsBedBreak.Event:Connect(function()\n\t                table.clear(Session.beds)\n\t            end))\n\t\n\t            AutoCaitlyn:Clean(Entity.Events.LocalAdded:Connect(function()\n\t                table.clear(Session.hits)\n\t                Session.pendingId = nil\n\t            end))\n\t\n\t            AutoCaitlyn:Clean(Entity.Events.LocalRemoved:Connect(function()\n\t                table.clear(Session.hits)\n\t                Session.pendingId = nil\n\t                Session.priorityId = nil\n\t            end))\n\t\n\t            repeat\n\t                if tick() >= Session.nextUpdate then\n\t                    Session.nextUpdate = tick() + 0.2\n\t                    UpdateCaitlyn(Session)\n\t                end\n\t                task.wait(0.05)\n\t            until not AutoCaitlyn.Enabled or ActiveSession ~= Session\n\t\n\t            if ActiveSession == Session then\n\t                ActiveSession = nil\n\t            end\n\t        else\n\t            ActiveSession = nil\n\t        end\n\t    end,\n\t    Tooltip = \"Automatically assigns a player's contract when a specific action happens\"\n\t})\n\t\n\tMode = AutoCaitlyn:CreateDropdown({\n\t    Name = \"Contract mode\",\n\t    List = {\"On Hit\", \"On Low\"},\n\t    Function = function(Val: string)\n\t        if MinHP then\n\t            MinHP.Object.Visible = Val == \"On Low\"\n\t        end\n\t    end,\n\t    Default = \"On Low\",\n\t    Tooltip = \"On Hit - Contracts them whenever u start hitting them\\nOn Low - When they're low\"\n\t})\n\tMinHP = AutoCaitlyn:CreateSlider({\n\t    Name = \"Minimum Health\",\n\t    Tooltip = \"How low they have to be before contracting\",\n\t    Min = 1,\n\t    Max = 100,\n\t    Default = 30,\n\t    Darker = true,\n\t    Visible = false\n\t})\n\tlocal Methods: {string} = {\"Damage\", \"Distance\"}\n\tfor _, v: string in SortList do\n\t    if not table.find(Methods, v) then\n\t        table.insert(Methods, v)\n\t    end\n\tend\n\tTargetMode = AutoCaitlyn:CreateDropdown({\n\t    Name = \"Target Mode\",\n\t    List = Methods,\n\t    Default = \"Distance\",\n\t    Tooltip = \"Who gets ur contract when more than one player u hit has one up, sorted the same way as Killaura's Target Mode\"\n\t})\n\tRange = AutoCaitlyn:CreateSlider({\n\t    Name = \"Range\",\n\t    Min = 1,\n\t    Max = 50,\n\t    Default = 50,\n\t    Suffix = function(Val: number)\n\t        return Val <= 1 and \"stud\" or \"studs\"\n\t    end\n\t})\n\tTargetPriorities = AutoCaitlyn:CreateToggle({\n\t    Name = \"Target Priorities\",\n\t    Function = function()\n\t        if ActiveSession then\n\t            ActiveSession.priorityId = nil\n\t        end\n\t    end,\n\t    Tooltip = \"Right away takes the contract with the best reward and easiest kill in range, instead of waiting for Contract mode and Target Mode\"\n\t})\n\tDropContract = AutoCaitlyn:CreateToggle({\n\t    Name = \"Drop Contract\",\n\t    Tooltip = \"Drops ur contract once 60 seconds have passed since taking it (the soonest the game allows) so u can take a new one. It is kept while the target is alive within Range, and dropped when they die\"\n\t})\nend)\n\nRun(function()\n\tlocal AutoCard\n\tlocal Range\n\tlocal Delay\n\tlocal NextThrow: number = 0\n\t\n\tAutoCard = vape.Categories.Kits:CreateModule({\n\t    Name = \"AutoCard\",\n\t    Function = function(Callback: boolean)\n\t        if Callback then\n\t            NextThrow = 0\n\t\n\t            repeat\n\t                if Entity.isAlive and Store.equippedKit == \"card\" and tick() >= NextThrow and bedwars.AbilityController:canUseAbility(\"CARD_THROW\", {disableBlockedAbilityAlert = true}) then\n\t                    local Target = Entity.EntityPosition({\n\t                        Origin = Entity.character.RootPart.Position,\n\t                        Range = Range.Value,\n\t                        Part = \"RootPart\",\n\t                        Players = true,\n\t                        Wallcheck = true\n\t                    })\n\t\n\t                    if Target then\n\t                        NextThrow = tick() + Delay.Value\n\t                        bedwars.AbilityController:useAbility(\"CARD_THROW\")\n\t                    end\n\t                end\n\t                task.wait(0.1)\n\t            until not AutoCard.Enabled\n\t        end\n\t    end,\n\t    Tooltip = \"Automatically throws Fortuna cards at whoever is near you\"\n\t})\n\t\n\tRange = AutoCard:CreateSlider({\n\t    Name = \"Range\",\n\t    Min = 1,\n\t    Max = 100,\n\t    Default = 60,\n\t    Suffix = function(Val: number)\n\t        return Val <= 1 and \"stud\" or \"studs\"\n\t    end\n\t})\n\tDelay = AutoCard:CreateSlider({\n\t    Name = \"Delay\",\n\t    Min = 0.1,\n\t    Max = 3,\n\t    Default = 0.4,\n\t    Decimal = 10,\n\t    Suffix = function(Val: number)\n\t        return Val <= 1 and \"sec\" or \"secs\"\n\t    end\n\t})\nend)\n\nRun(function()\n\tlocal AutoCogsworth\n\tlocal Targets\n\tlocal Collect\n\tlocal Steal\n\tlocal Range\n\tlocal Delay\n\tlocal Overclock\n\tlocal OverclockRange\n\tlocal NextCollect: number = 0\n\tlocal NextOverclock: number = 0\n\t\n\tlocal function GetBots()\n\t    local Controller = bedwars.GatherBotBasicController\n\t    return Controller and Controller.gatherBotMap or {}\n\tend\n\t\n\tAutoCogsworth = vape.Categories.Kits:CreateModule({\n\t    Name = \"AutoCogsworth\",\n\t    Function = function(Callback: boolean)\n\t        if Callback then\n\t            NextCollect = 0\n\t            NextOverclock = 0\n\t\n\t            repeat\n\t                if Entity.isAlive then\n\t                    local Origin: Vector3 = Entity.character.RootPart.Position\n\t\n\t                    if Collect.Enabled and tick() >= NextCollect then\n\t                        for Bot: Model in GetBots() do\n\t                            if not Bot.Parent then\n\t                                continue\n\t                            end\n\t                            local Owner = Bot:GetAttribute(\"PlacedByUserId\")\n\t                            if not Steal.Enabled and Owner ~= LocalPlayer.UserId then\n\t                                continue\n\t                            end\n\t                            if (Bot:GetAttribute(\"HeldItemAmount\") or 0) <= 0 then\n\t                                continue\n\t                            end\n\t                            if (Bot:GetPivot().Position - Origin).Magnitude > Range.Value then\n\t                                continue\n\t                            end\n\t\n\t                            bedwars.Handler:Get(\"GatherBotCollectItems\"):Fire(\"SendToServer\", {\n\t                                gatherBot = Bot\n\t                            })\n\t                            NextCollect = tick() + Delay.Value\n\t                            break\n\t                        end\n\t                    end\n\t\n\t                    if Overclock.Enabled and Store.equippedKit == \"steam_engineer\" and tick() >= NextOverclock and bedwars.AbilityController:canUseAbility(\"STEAM_ENGINEER_OVERCLOCK\", {disableBlockedAbilityAlert = true}) then\n\t                        local Found: boolean = #Entity.AllPosition({\n\t                            Range = OverclockRange.Value,\n\t                            Part = \"RootPart\",\n\t                            Players = Targets.Players.Enabled,\n\t                            NPCs = Targets.NPCs.Enabled\n\t                        }) > 0\n\t\n\t                        if Found then\n\t                            NextOverclock = tick() + 1\n\t                            bedwars.AbilityController:useAbility(\"STEAM_ENGINEER_OVERCLOCK\")\n\t                        end\n\t                    end\n\t                end\n\t                task.wait(0.1)\n\t            until not AutoCogsworth.Enabled\n\t        end\n\t    end,\n\t    Tooltip = \"Empties gather bots from across the map and overclocks when a fight starts\"\n\t})\n\t\n\tTargets = AutoCogsworth:CreateTargets({\n\t    Players = true,\n\t    NPCs = true\n\t})\n\tCollect = AutoCogsworth:CreateToggle({\n\t    Name = \"Collect bots\",\n\t    Default = true,\n\t    Tooltip = \"The games own collect prompt stops at 10 studs, the server never checks it\"\n\t})\n\tSteal = AutoCogsworth:CreateToggle({\n\t    Name = \"Steal enemy bots\",\n\t    Tooltip = \"Also empties gather bots that somebody else placed\"\n\t})\n\tRange = AutoCogsworth:CreateSlider({\n\t    Name = \"Range\",\n\t    Min = 5,\n\t    Max = 500,\n\t    Default = 250,\n\t    Suffix = function(Val: number)\n\t        return Val <= 1 and \"stud\" or \"studs\"\n\t    end\n\t})\n\tDelay = AutoCogsworth:CreateSlider({\n\t    Name = \"Delay\",\n\t    Min = 0.1,\n\t    Max = 3,\n\t    Default = 0.3,\n\t    Decimal = 100,\n\t    Suffix = function(Val: number)\n\t        return Val <= 1 and \"sec\" or \"secs\"\n\t    end\n\t})\n\tOverclock = AutoCogsworth:CreateToggle({\n\t    Name = \"Overclock\",\n\t    Default = true,\n\t    Function = function(Callback: boolean)\n\t        if OverclockRange then\n\t            OverclockRange.Object.Visible = Callback\n\t        end\n\t    end\n\t})\n\tOverclockRange = AutoCogsworth:CreateSlider({\n\t    Name = \"Overclock range\",\n\t    Min = 1,\n\t    Max = 60,\n\t    Default = 25,\n\t    Suffix = function(Val: number)\n\t        return Val <= 1 and \"stud\" or \"studs\"\n\t    end\n\t})\nend)\n\nRun(function()\n\tlocal AutoConqueror\n\tlocal Targets\n\tlocal Banner\n\tlocal Mode\n\tlocal Range = {}\n\tlocal Cooldown\n\tlocal Switch\n\tlocal SwitchDelay = {}\n\tlocal NextPlace: number = 0\n\tlocal Placing: boolean = false\n\t\n\tlocal Banners: {[string]: string} = {\n\t    Fire = \"damage_banner\",\n\t    Defense = \"defense_banner\",\n\t    Heal = \"heal_banner\"\n\t}\n\t\n\tlocal function PlaceBanner()\n\t    if Placing or tick() < NextPlace or not Entity.isAlive then\n\t        return\n\t    end\n\t\n\t    local ItemType: string = Banners[Banner.Value]\n\t    local Item = getItem(Banners[Banner.Value])\n\t    local Item = Item and (Item.amount or 1) > 0 and Item or nil\n\t    if not Item then\n\t        return\n\t    end\n\t\n\t    local LocalPosition: Vector3 = Entity.character.RootPart.Position\n\t    for _, v: Instance in CollectionService:GetTagged(\"flag-kit\") do\n\t        if v:IsA(\"BasePart\") and v.Name == ItemType and (v.Position - LocalPosition).Magnitude <= bedwars.ConquerorBalance.CONQUEROR_FLAG_RADIUS / 2 then\n\t            return\n\t        end\n\t    end\n\t\n\t    local Character = Entity.character\n\t    local Base: Vector3 = roundPos(Character.RootPart.Position - Vector3.new(0, Character.HipHeight + 1.5, 0))\n\t    local Spot: Vector3?\n\t    for _, v: Vector3 in {Vector3.new(3, 3, 0), Vector3.new(-3, 3, 0), Vector3.new(0, 3, 3), Vector3.new(0, 3, -3), Vector3.new(0, 3, 0)} do\n\t        local Position: Vector3 = Base + v\n\t        if not getPlacedBlock(Position) and getPlacedBlock(Position - Vector3.new(0, 3, 0)) then\n\t            Spot = Position\n\t            break\n\t        end\n\t    end\n\t    if not Spot then\n\t        return\n\t    end\n\t\n\t    Placing = true\n\t    NextPlace = tick() + Cooldown.Value\n\t    local Hotbar = Switch.Enabled and store.hand.tool and getHotbar(store.hand.tool) or nil\n\t\n\t    if not Switch.Enabled or hotbarSwitch(getHotbar(Item.tool)) then\n\t        if Switch.Enabled then\n\t            task.wait(SwitchDelay.Value)\n\t        end\n\t\n\t        bedwars.placeBlock(Spot, ItemType)\n\t\n\t        if Hotbar then\n\t            task.wait(SwitchDelay.Value)\n\t            hotbarSwitch(Hotbar)\n\t        end\n\t    end\n\t    Placing = false\n\tend\n\t\n\tAutoConqueror = vape.Categories.Kits:CreateModule({\n\t    Name = \"AutoConqueror\",\n\t    Function = function(Callback: boolean)\n\t        if Callback then\n\t            NextPlace = 0\n\t            Placing = false\n\t\n\t            AutoConqueror:Clean(vapeEvents.EntityDamageEvent.Event:Connect(function(DamageTable)\n\t                if Mode.Value ~= \"On attack\" or DamageTable.damageType ~= 0 or store.equippedKit ~= \"vesta\" then\n\t                    return\n\t                end\n\t\n\t                local Character: Model? = LocalPlayer.Character\n\t                if (DamageTable.fromEntity and DamageTable.fromEntity.Name == LocalPlayer.Name) or (Character and DamageTable.entityInstance == Character) then\n\t                    task.spawn(PlaceBanner)\n\t                end\n\t            end))\n\t\n\t            repeat\n\t                if Mode.Value == \"On near\" and Entity.isAlive and store.equippedKit == \"vesta\" and Entity.EntityPosition({\n\t                    Range = Range.Value,\n\t                    Part = \"RootPart\",\n\t                    Players = Targets.Players.Enabled,\n\t                    NPCs = Targets.NPCs.Enabled,\n\t                    Priority = Targets.Priority.Value,\n\t                    Wallcheck = Targets.Walls.Enabled or nil\n\t                }) then\n\t                    PlaceBanner()\n\t                end\n\t                task.wait(0.1)\n\t            until not AutoConqueror.Enabled\n\t        else\n\t            Placing = false\n\t        end\n\t    end,\n\t    Tooltip = \"Drops a Conqueror banner beside you when a fight starts\"\n\t})\n\t\n\tTargets = AutoConqueror:CreateTargets({\n\t    Players = true,\n\t    NPCs = false\n\t})\n\tBanner = AutoConqueror:CreateDropdown({\n\t    Name = \"Banner\",\n\t    List = {\"Fire\", \"Defense\", \"Heal\"},\n\t    Tooltip = \"Which banner to put down, Fire gives the damage buff\"\n\t})\n\tMode = AutoConqueror:CreateDropdown({\n\t    Name = \"Place on\",\n\t    List = {\"On attack\", \"On near\"},\n\t    Function = function(Val: string)\n\t        if Range.Object then\n\t            Range.Object.Visible = Val == \"On near\"\n\t        end\n\t    end,\n\t    Tooltip = \"On attack waits until you trade hits, On near drops it as soon as someone walks up\"\n\t})\n\tRange = AutoConqueror:CreateSlider({\n\t    Name = \"Range\",\n\t    Min = 5,\n\t    Max = 100,\n\t    Default = 30,\n\t    Darker = true,\n\t    Visible = false,\n\t    Suffix = function(Val: number)\n\t        return Val <= 1 and \"stud\" or \"studs\"\n\t    end,\n\t    Tooltip = \"How close an enemy has to be for On near\"\n\t})\n\tCooldown = AutoConqueror:CreateSlider({\n\t    Name = \"Cooldown\",\n\t    Min = 1,\n\t    Max = 60,\n\t    Default = 30,\n\t    Suffix = \"seconds\",\n\t    Tooltip = \"Time before it puts another one down, a banner lasts 30 seconds\"\n\t})\n\tSwitch = AutoConqueror:CreateToggle({\n\t    Name = \"Legit switch\",\n\t    Function = function(Callback: boolean)\n\t        if SwitchDelay.Object then\n\t            SwitchDelay.Object.Visible = Callback\n\t        end\n\t    end,\n\t    Tooltip = \"Holds the banner through the hotbar and puts your item back after\"\n\t})\n\tSwitchDelay = AutoConqueror:CreateSlider({\n\t    Name = \"Switch delay\",\n\t    Min = 0,\n\t    Max = 1,\n\t    Decimal = 100,\n\t    Default = 0.08,\n\t    Darker = true,\n\t    Visible = false,\n\t    Suffix = \"seconds\"\n\t})\nend)\n\nRun(function()\n\tlocal AutoCrocowolf\n\tlocal Range\n\tlocal Targets\n\t\n\tAutoCrocowolf = vape.Categories.Kits:CreateModule({\n\t    Name = \"AutoCrocowolf\",\n\t    Function = function(Callback: boolean)\n\t        if Callback then\n\t            repeat\n\t                if Entity.isAlive and Store.equippedKit == \"beast\" and bedwars.AbilityController:canUseAbility(\"beast_form\", {disableBlockedAbilityAlert = true}) then\n\t                    local Origin: Vector3 = Entity.character.RootPart.Position\n\t                    local Found: number = 0\n\t                    for _, v: any in Entity.List do\n\t                        if v.Targetable and (v.RootPart.Position - Origin).Magnitude <= Range.Value then\n\t                            Found += 1\n\t                        end\n\t                    end\n\t\n\t                    if Found >= Targets.Value then\n\t                        bedwars.AbilityController:useAbility(\"beast_form\")\n\t                    end\n\t                end\n\t                task.wait(0.1)\n\t            until not AutoCrocowolf.Enabled\n\t        end\n\t    end,\n\t    Tooltip = \"Automatically goes into beast form once enough enemies are around you\"\n\t})\n\t\n\tRange = AutoCrocowolf:CreateSlider({\n\t    Name = \"Range\",\n\t    Min = 1,\n\t    Max = 60,\n\t    Default = 30,\n\t    Suffix = function(Val: number)\n\t        return Val <= 1 and \"stud\" or \"studs\"\n\t    end\n\t})\n\tTargets = AutoCrocowolf:CreateSlider({\n\t    Name = \"Targets\",\n\t    Min = 1,\n\t    Max = 8,\n\t    Default = 1,\n\t    Tooltip = \"Enemies in range before transforming\"\n\t})\nend)\n\nRun(function()\n\tlocal AutoCyber\n\tlocal Mode\n\tlocal Whitelist\n\tlocal Visual\n\tlocal Steal\n\tlocal Target\n\tlocal Limit\n\t\n\tlocal TeamCache, CacheExpire = nil, 0\n\tlocal function GetTeamGenerator()\n\t    if CacheExpire > tick() and TeamCache and TeamCache.Parent then\n\t        return TeamCache\n\t    end\n\t    TeamCache, CacheExpire = CollectionService:GetTagged(`{LocalPlayer:GetAttribute(\"Team\")}_TeamOreGenerator`)[1], tick() + 5\n\t    return TeamCache\n\tend\n\tlocal DroneCache = nil\n\tlocal Watching = setmetatable({}, {__mode = \"k\"})\n\tlocal function GetDrone()\n\t    if Limit.Enabled and (not Store.hand.tool or Store.hand.tool.Name ~= \"drone\") then\n\t        return nil\n\t    end\n\t    if DroneCache and DroneCache.Parent then\n\t        return DroneCache\n\t    end\n\t    for _, v: Model in CollectionService:GetTagged(\"Drone\") do\n\t        if v:GetAttribute(\"PlayerUserId\") == LocalPlayer.UserId then\n\t            local function Changed()\n\t                if v:GetAttribute(\"HeldItem\") then\n\t                    repeat\n\t                        bedwars.Handler:Get(\"DropDroneItem\"):Fire(\"SendToServer\", {\n\t                            direction = Vector3.new(1000, 10, 0),\n\t                            position = v.PrimaryPart.Position\n\t                        })\n\t                        task.wait(0.1)\n\t                    until not v:GetAttribute(\"HeldItem\") or not AutoCyber.Enabled\n\t                end\n\t            end\n\t            if not Watching[v] then\n\t                Watching[v] = {\n\t                    v:GetAttributeChangedSignal(\"HeldItem\"):Connect(Changed),\n\t                    v:GetAttributeChangedSignal(\"HeldItemAmount\"):Connect(Changed)\n\t                }\n\t            end\n\t            DroneCache = v\n\t            return v\n\t        end\n\t    end\n\t    if GetItem(\"drone\") and bedwars.Handler:Get(\"FireGuidedProjectile\"):Fire(\"CallServer\", \"drone\") then\n\t        task.wait(0.1)\n\t        return GetDrone()\n\t    end\n\t    return nil\n\tend\n\tlocal Blacklist: {[BasePart]: number} = {}\n\tlocal function GetItemDrop(Drone: Model): BasePart?\n\t    local Generator = GetTeamGenerator()\n\t    Generator = Generator and Generator.PrimaryPart.Position or Vector3.zero\n\t    local Children: {BasePart} = workspace.ItemDrops:GetChildren()\n\t    local Position: Vector3 = Drone.PrimaryPart.Position\n\t    local Distances: {[BasePart]: number} = {}\n\t\n\t    local function GetDistance(Part: BasePart): number\n\t        local Distance: number? = Distances[Part]\n\t        if not Distance then\n\t            Distance = (Position - Part.Position).Magnitude\n\t            Distances[Part] = Distance\n\t        end\n\t        return Distance\n\t    end\n\t\n\t    table.sort(Children, function(A: BasePart, B: BasePart)\n\t        return GetDistance(A) < GetDistance(B)\n\t    end)\n\t    for _, v: BasePart in Children do\n\t        if tick() > (Blacklist[v] or 0) and table.find(Whitelist.ListEnabled, v.Name) and v.Position.Y > 0 and math.abs(v.AssemblyLinearVelocity.Y) <= 0 and (not Steal.Enabled or (v.Position - Generator).Magnitude > 20) and (not Target.Enabled or not Entity.EntityPosition({\n\t            Origin = Position,\n\t            Range = 60,\n\t            Part = \"RootPart\",\n\t            Players = true\n\t        })) then\n\t            return v\n\t        end\n\t    end\n\t    return nil\n\tend\n\tAutoCyber = vape.Categories.Kits:CreateModule({\n\t    Name = \"AutoCyber\",\n\t    Function = function(Callback: boolean)\n\t        if Callback then\n\t            AutoCyber:Clean(workspace.ItemDrops.ChildAdded:Connect(function(ItemDrop: BasePart)\n\t                task.wait()\n\t                if ItemDrop.AssemblyLinearVelocity.X > 100 then\n\t                    Blacklist[ItemDrop] = tick() + 5\n\t                    local Amount = ItemDrop:GetAttribute(\"Amount\")\n\t                    local LastParent: Instance? = ItemDrop.Parent\n\t                    if Mode.Value == \"Player\" then\n\t                        SendNotification(\"AutoCyber\", `Collecting {Amount} {ItemDrop.Name}`, 4, \"info\")\n\t                        repeat\n\t                            ItemDrop.AssemblyLinearVelocity = Vector3.zero\n\t                            ItemDrop.CFrame = Entity.character.RootPart.CFrame - Vector3.new(0, 4, 0)\n\t                            task.spawn(function()\n\t                                bedwars.Handler:Get(\"PickupItemDrop\"):Fire(\"CallServerAsync\", {\n\t                                    itemDrop = ItemDrop\n\t                                }):andThen(function(Success: boolean)\n\t                                    if Success and bedwars.SoundList then\n\t                                        bedwars.AudioManager:playAudio(bedwars.SoundList.PICKUP_ITEM_DROP)\n\t                                        local Sound = bedwars.ItemMeta[ItemDrop.Name].pickUpOverlaySound\n\t                                        if Sound then\n\t                                            bedwars.AudioManager:playAudio(Sound, {\n\t                                                position = ItemDrop.Position,\n\t                                                volumeMultiplier = 0.9\n\t                                            })\n\t                                        end\n\t                                    end\n\t                                end)\n\t                            end)\n\t                            task.wait(0.02)\n\t                        until not ItemDrop or ItemDrop.Parent ~= LastParent\n\t\n\t                        SendNotification(\"AutoCyber\", `Collected {Amount} {ItemDrop.Name}{Amount > 1 and \"s\" or \"\"}`, 4, \"info\")\n\t                    else\n\t                        local Start: number = tick()\n\t                        local Generator = GetTeamGenerator()\n\t                        if Generator then\n\t                            repeat\n\t                                ItemDrop.AssemblyLinearVelocity = Vector3.zero\n\t                                ItemDrop.CFrame = Generator.PrimaryPart.CFrame\n\t                                task.wait()\n\t                            until (tick() - Start) >= 1 or not ItemDrop or ItemDrop.Parent ~= LastParent\n\t                            SendNotification(\"AutoCyber\", `Dropped {Amount} {ItemDrop.Name}`, 8, \"info\")\n\t                        else\n\t                            SendNotification(\"AutoCyber\", \"Generator not found\", 20, \"alert\")\n\t                        end\n\t                    end\n\t                end\n\t            end))\n\t\n\t            repeat\n\t                local Drone: Model? = GetDrone()\n\t                if Drone then\n\t                    local ItemDrop: BasePart? = GetItemDrop(Drone)\n\t                    if ItemDrop then\n\t                        task.wait(0.3)\n\t                        local Highlight: Highlight?\n\t                        if Visual.Enabled then\n\t                            Highlight = Instance.new(\"Highlight\")\n\t                            Highlight.FillColor = Color3.new(1, 1, 1)\n\t                            Highlight.FillTransparency = 0\n\t                            Highlight.OutlineTransparency = 0.5\n\t                            Highlight.OutlineColor = Color3.new()\n\t                            Highlight.Parent = ItemDrop\n\t                        end\n\t                        Drone.PrimaryPart.AssemblyLinearVelocity = Vector3.zero\n\t                        Drone.PrimaryPart.CFrame = CFrame.new(Drone.PrimaryPart.CFrame.X, 10000, Drone.PrimaryPart.CFrame.Z)\n\t                        local Magnitude, LastMagnitude = 0, 9e9\n\t                        local Position: Vector3 = ItemDrop.Position\n\t                        repeat\n\t                            if Drone and Drone.Parent then\n\t                                Position = ItemDrop.Position\n\t                                local Multiplier = Drone:GetAttribute(\"SpeedBoost\")\n\t                                Multiplier = Multiplier == 0 or Multiplier == \"\" or not Multiplier and true or false\n\t                                Drone.PrimaryPart.CanCollide = false\n\t                                Drone.PrimaryPart.AssemblyAngularVelocity = Vector3.zero\n\t                                Drone.PrimaryPart.AssemblyLinearVelocity = CFrame.lookAt(Drone.PrimaryPart.Position * Vector3.new(1, 0, 1), Position * Vector3.new(1, 0, 1)).LookVector * 30\n\t                                Magnitude = ((Drone.PrimaryPart.Position * Vector3.new(1, 0, 1)) - (Position * Vector3.new(1, 0, 1))).Magnitude\n\t                                if (LastMagnitude - Magnitude) >= 25 then\n\t                                    LastMagnitude = Magnitude\n\t                                    SendNotification(\"AutoCyber\", `Drone is {math.floor(Magnitude)} studs away from {ItemDrop.Name}.`, 1, \"info\")\n\t                                end\n\t                            else\n\t                                break\n\t                            end\n\t                            task.wait()\n\t                        until not ItemDrop or ItemDrop.Parent ~= workspace.ItemDrops or not AutoCyber.Enabled or Magnitude <= 2\n\t                        if not AutoCyber.Enabled then\n\t                            if Highlight and Highlight.Parent then\n\t                                Highlight:Destroy()\n\t                            end\n\t                            break\n\t                        end\n\t\n\t                        if Magnitude <= 5 then\n\t                            local Start: number = tick()\n\t                            if Visual.Enabled then\n\t                                SendNotification(\"AutoCyber\", `Attempting to collect {ItemDrop.Name}`, 4, \"info\")\n\t                            end\n\t                            repeat\n\t                                if Drone and Drone.Parent then\n\t                                    Drone.PrimaryPart.AssemblyLinearVelocity = Vector3.zero\n\t                                    Drone.PrimaryPart.AssemblyAngularVelocity = Vector3.new(0, -30, 0)\n\t                                    Drone.PrimaryPart.CFrame = CFrame.new(Position - Vector3.new(0, Drone.Hitbox.Size.Y, 0))\n\t                                end\n\t                                task.wait(0.02)\n\t                            until (tick() - Start) >= 1.25\n\t                        elseif Visual.Enabled then\n\t                            SendNotification(\"AutoCyber\", `Too far away to collect {ItemDrop.Name} ({Magnitude} studs).`, 8, \"info\")\n\t                        end\n\t                        if Highlight and Highlight.Parent then\n\t                            Highlight:Destroy()\n\t                        end\n\t                    else\n\t                        Drone.PrimaryPart.CFrame = CFrame.new(Drone.PrimaryPart.CFrame.X, 10000, Drone.PrimaryPart.CFrame.Z)\n\t                        Drone.PrimaryPart.AssemblyLinearVelocity = Vector3.zero\n\t                        for _, v: string in Whitelist.ListEnabled do\n\t                            local Item: string = v\n\t                            local Children: {Model} = CollectionService:GetTagged(`{Item}_OreGenerator`)\n\t                            local Position: Vector3 = Drone.PrimaryPart.Position\n\t                            table.sort(Children, function(A: Model, B: Model)\n\t                                return (Position - A.PrimaryPart.Position).Magnitude < (Position - B.PrimaryPart.Position).Magnitude\n\t                            end)\n\t                            local Generator: BasePart? = Children[1] and Children[1].PrimaryPart or nil\n\t                            if Generator then\n\t                                local Magnitude: number = 0\n\t                                repeat\n\t                                    if Drone and Drone.Parent then\n\t                                        if GetItemDrop(Drone) then\n\t                                            break\n\t                                        end\n\t                                        Drone.PrimaryPart.CanCollide = false\n\t                                        Drone.PrimaryPart.AssemblyAngularVelocity = Vector3.zero\n\t                                        Drone.PrimaryPart.AssemblyLinearVelocity = CFrame.lookAt(Drone.PrimaryPart.Position * Vector3.new(1, 0, 1), Generator.Position * Vector3.new(1, 0, 1)).LookVector * 30\n\t                                        Magnitude = ((Drone.PrimaryPart.Position * Vector3.new(1, 0, 1)) - (Generator.Position * Vector3.new(1, 0, 1))).Magnitude\n\t                                    else\n\t                                        break\n\t                                    end\n\t                                    task.wait()\n\t                                until not AutoCyber.Enabled or Magnitude <= 5\n\t                            end\n\t                        end\n\t                    end\n\t                end\n\t                task.wait()\n\t            until not AutoCyber.Enabled\n\t        else\n\t            local Drone: Model? = GetDrone()\n\t            if Drone then\n\t                Drone.PrimaryPart.CFrame = CFrame.new(Drone.PrimaryPart.CFrame.X, 500, Drone.PrimaryPart.CFrame.Z)\n\t            end\n\t        end\n\t    end,\n\t    Tooltip = \"Allows you to steal other's opponent resources via drone.\"\n\t})\n\t\n\tMode = AutoCyber:CreateDropdown({\n\t    Name = \"Drop mode\",\n\t    List = {\"Player\", \"Generator\"},\n\t    Default = \"Player\",\n\t    Tooltip = \"Where cyber items gets dropped to.\"\n\t})\n\tWhitelist = AutoCyber:CreateTextList({\n\t    Name = \"Whitelist\",\n\t    Default = {\"emerald\", \"diamond\"}\n\t})\n\tVisual = AutoCyber:CreateToggle({\n\t    Name = \"Visualize\",\n\t    Default = true,\n\t    Tooltip = \"Shows what item the drone is targeting and updates\\non where how far the drone is to the item.\"\n\t})\n\tSteal = AutoCyber:CreateToggle({\n\t    Name = \"Steal split\",\n\t    Default = true,\n\t    Tooltip = \"Steals other opponent team's generator split.\"\n\t})\n\tTarget = AutoCyber:CreateToggle({Name = \"Target check\"})\n\tLimit = AutoCyber:CreateToggle({Name = \"Limit to item\"})\nend)\n\nRun(function()\n\tlocal AutoDavey\n\tlocal Switch\n\tlocal Break\n\tlocal Jump\n\tlocal LimitItem\n\t\n\tlocal Old, OldAim\n\t\n\tlocal function CanBreak(): boolean\n\t    if not LimitItem.Enabled then\n\t        return true\n\t    end\n\t    local ItemMeta = Store.hand.tool and bedwars.ItemMeta[Store.hand.tool.Name]\n\t    return ItemMeta ~= nil and ItemMeta.breakBlock ~= nil\n\tend\n\t\n\tlocal function BreakCannon(Block: BasePart, KeepLast: boolean?)\n\t    local Deadline: number = tick() + 0.6 + (Store.ping.total or 0)\n\t    local Hits: number = KeepLast and math.max(math.ceil(GetBlockHits(Block, Block.Position)) - 1, 0) or math.huge\n\t\n\t    repeat\n\t        if not AutoDavey.Enabled or not Entity.isAlive or not CanBreak() or Hits <= 0 then\n\t            return\n\t        end\n\t        if (Block.Position - Entity.character.RootPart.Position).Magnitude > 30 then\n\t            return\n\t        end\n\t        bedwars.breakBlock(Block, true, true, nil, Switch.Enabled)\n\t        Hits -= 1\n\t        task.wait(0.1)\n\t    until not Block.Parent or tick() > Deadline\n\tend\n\t\n\tAutoDavey = vape.Categories.Kits:CreateModule({\n\t    Name = \"AutoDavey\",\n\t    Function = function(Callback: boolean)\n\t        if Callback then\n\t            OldAim = bedwars.CannonController.startAiming\n\t            bedwars.CannonController.startAiming = function(self, Block, ...)\n\t                local Call = OldAim(self, Block, ...)\n\t\n\t                if Break.Enabled and Block and Block.Parent and Entity.isAlive and CanBreak() and GetBlockHits(Block, Block.Position) > 1 then\n\t                    task.spawn(BreakCannon, Block, true)\n\t                end\n\t\n\t                return Call\n\t            end\n\t\n\t            Old = bedwars.CannonHandController.launchSelf\n\t            bedwars.CannonHandController.launchSelf = function(self, Block, ...)\n\t                if Break.Enabled and Block and Block.Parent and Entity.isAlive and (Block.Position - Entity.character.RootPart.Position).Magnitude <= 30 and CanBreak() then\n\t                    pcall(BreakCannon, Block, true)\n\t                    task.spawn(BreakCannon, Block)\n\t                end\n\t\n\t                local Call = Old(self, Block, ...)\n\t\n\t                if Jump.Enabled and Entity.isAlive then\n\t                    Entity.character.Humanoid:ChangeState(Enum.HumanoidStateType.Jumping)\n\t                end\n\t                return Call\n\t            end\n\t        else\n\t            bedwars.CannonHandController.launchSelf = Old\n\t            bedwars.CannonController.startAiming = OldAim\n\t        end\n\t    end,\n\t    Tooltip = \"Automatically breaks cannon/jump on launch\"\n\t})\n\t\n\tJump = AutoDavey:CreateToggle({Name = \"Jump on impact\"})\n\t\n\tBreak = AutoDavey:CreateToggle({Name = \"Break on impact\", Default = true})\n\t\n\tSwitch = AutoDavey:CreateToggle({Name = \"Legit switch\"})\n\t\n\tLimitItem = AutoDavey:CreateToggle({\n\t    Name = \"Limit to items\",\n\t    Tooltip = \"Only breaks when tools are held\"\n\t})\nend)\n\nRun(function()\n\tlocal AutoDragonSword\n\tlocal Range\n\tlocal Targets\n\t\n\tAutoDragonSword = vape.Categories.Kits:CreateModule({\n\t    Name = \"AutoDragonSword\",\n\t    Function = function(Callback: boolean)\n\t        if Callback then\n\t            repeat\n\t                if Entity.isAlive and Store.equippedKit == \"dragon_sword\" and bedwars.AbilityController:canUseAbility(\"dragon_sword_ult\", {disableBlockedAbilityAlert = true}) then\n\t                    local Origin: Vector3 = Entity.character.RootPart.Position\n\t                    local Found: number = 0\n\t                    for _, v: any in Entity.List do\n\t                        if v.Targetable and (v.RootPart.Position - Origin).Magnitude <= Range.Value then\n\t                            Found += 1\n\t                        end\n\t                    end\n\t\n\t                    if Found >= Targets.Value then\n\t                        bedwars.AbilityController:useAbility(\"dragon_sword_ult\")\n\t                    end\n\t                end\n\t                task.wait(0.1)\n\t            until not AutoDragonSword.Enabled\n\t        end\n\t    end,\n\t    Tooltip = \"Automatically uses Lian ultimate once enough enemies are around you\"\n\t})\n\t\n\tRange = AutoDragonSword:CreateSlider({\n\t    Name = \"Range\",\n\t    Min = 1,\n\t    Max = 60,\n\t    Default = 25,\n\t    Suffix = function(Val: number)\n\t        return Val <= 1 and \"stud\" or \"studs\"\n\t    end\n\t})\n\tTargets = AutoDragonSword:CreateSlider({\n\t    Name = \"Targets\",\n\t    Min = 1,\n\t    Max = 8,\n\t    Default = 1,\n\t    Tooltip = \"Enemies in range before using the ultimate\"\n\t})\nend)\n\nRun(function()\n\tlocal AutoDrill\n\tlocal AutoCollect\n\tlocal Notify\n\tlocal AutoAttack\n\tlocal Legit\n\tlocal Range\n\tlocal AttackDelay\n\tlocal CollectDelay\n\tlocal Targets\n\tlocal Sort\n\tlocal CurrentDrill\n\tlocal AttackDebounce: {[Model]: number} = {}\n\tlocal CollectDebounce: {[Model]: number} = {}\n\t\n\tlocal function AddDrill(Drills: {Model}, Added: {[Model]: boolean}, Drill)\n\t    if typeof(Drill) ~= \"Instance\" or Added[Drill] or Drill:GetAttribute(\"PlacedByUserId\") ~= LocalPlayer.UserId then\n\t        return\n\t    end\n\t    if (Drill and (Drill.PrimaryPart or Drill:FindFirstChild(\"RootPart\") or Drill:FindFirstChildWhichIsA(\"BasePart\"))) then\n\t        Added[Drill] = true\n\t        table.insert(Drills, Drill)\n\t    end\n\tend\n\t\n\tlocal function GetDrills(Tagged: {Model}): {Model}\n\t    local Drills, Added = {}, {}\n\t    for _, v: Model in Tagged do\n\t        AddDrill(Drills, Added, v)\n\t    end\n\t\n\t    for _, v: Model in (bedwars.DrillTabletController and bedwars.DrillTabletController.drillList or {}) do\n\t        AddDrill(Drills, Added, v)\n\t    end\n\t\n\t    return Drills\n\tend\n\t\n\tlocal function UpdateAttackControls()\n\t    if Legit then\n\t        local Enabled: boolean = AutoAttack.Enabled\n\t        Legit.Object.Visible = Enabled\n\t        Range.Object.Visible = Enabled and not Legit.Enabled\n\t        AttackDelay.Object.Visible = Enabled\n\t        Targets.Object.Visible = Enabled\n\t        Sort.Object.Visible = Enabled\n\t    end\n\tend\n\t\n\tAutoDrill = vape.Categories.Kits:CreateModule({\n\t    Name = \"AutoDrill\",\n\t    Function = function(Callback: boolean)\n\t        if Callback then\n\t            local Tagged: {Model} = Collection(\"Drill\", AutoDrill)\n\t            repeat\n\t                task.wait()\n\t            until Store.matchState ~= 0 and Store.equippedKit == \"drill\" or not AutoDrill.Enabled\n\t\n\t            repeat\n\t                if Entity.isAlive and Store.equippedKit == \"drill\" then\n\t                    local Now: number = tick()\n\t                    for _, v: Model in GetDrills(Tagged) do\n\t                        local Part = (v and (v.PrimaryPart or v:FindFirstChild(\"RootPart\") or v:FindFirstChildWhichIsA(\"BasePart\")))\n\t                        if not Part then\n\t                            continue\n\t                        end\n\t\n\t                        if AutoCollect.Enabled and ((v:GetAttribute(\"diamond\") or 0) + (v:GetAttribute(\"emerald\") or 0)) > 0 and Now > (CollectDebounce[v] or 0) then\n\t                            bedwars.Handler:Get(\"ExtractFromDrill\"):Fire(\"SendToServer\", {drill = v})\n\t                            CollectDebounce[v] = Now + CollectDelay.Value\n\t\n\t                            if Notify.Enabled then\n\t                                SendNotification(\"Auto Drill\", \"Collected drill resources\", 4, \"info\")\n\t                            end\n\t                        end\n\t\n\t                        if AutoAttack.Enabled and Now > (AttackDebounce[v] or 0) then\n\t                            local Target = Entity.EntityPosition({\n\t                                Origin = Part.Position,\n\t                                Range = Legit.Enabled and 10 or Range.Value,\n\t                                Part = \"RootPart\",\n\t                                Players = Targets.Players.Enabled,\n\t                                NPCs = Targets.NPCs.Enabled,\n\t                                Priority = Targets.Priority.Value,\n\t                                Sort = SortMethods[Sort.Value]\n\t                            })\n\t\n\t                            local Using: boolean = CurrentDrill == v\n\t                            if Target and not Using and bedwars.Handler:Get(\"PlayerUseDrillController\"):Fire(\"CallServer\", {drill = v}) ~= false then\n\t                                CurrentDrill = v\n\t                                Using = true\n\t                            end\n\t\n\t                            if Target and Using then\n\t                                TargetInfo.Targets[Target] = tick() + 1\n\t                                bedwars.Handler:Get(\"DrillAttack\"):Fire(\"SendToServer\", {targetPosition = Target.RootPart.Position})\n\t                                AttackDebounce[v] = Now + AttackDelay.Value\n\t                            end\n\t                        end\n\t                    end\n\t                end\n\t                task.wait(0.1)\n\t            until not AutoDrill.Enabled\n\t        else\n\t            CurrentDrill = nil\n\t            table.clear(AttackDebounce)\n\t            table.clear(CollectDebounce)\n\t        end\n\t    end,\n\t    Tooltip = \"Automatically collects resources and attacks with placed drills.\"\n\t})\n\t\n\tAutoCollect = AutoDrill:CreateToggle({\n\t    Name = \"Auto collect\",\n\t    Function = function(Callback: boolean)\n\t        if Notify then\n\t            Notify.Object.Visible = Callback\n\t            CollectDelay.Object.Visible = Callback\n\t        end\n\t    end,\n\t    Default = true\n\t})\n\tNotify = AutoDrill:CreateToggle({\n\t    Name = \"Notify on collect\",\n\t    Darker = true\n\t})\n\tAutoAttack = AutoDrill:CreateToggle({\n\t    Name = \"Auto attack\",\n\t    Function = UpdateAttackControls,\n\t    Default = true\n\t})\n\tRange = AutoDrill:CreateSlider({\n\t    Name = \"Range\",\n\t    Min = 1,\n\t    Max = 10,\n\t    Default = 10,\n\t    Suffix = function(Val: number)\n\t        return Val == 1 and \"stud\" or \"studs\"\n\t    end\n\t})\n\tLegit = AutoDrill:CreateToggle({\n\t    Name = \"Legit Range\",\n\t    Function = UpdateAttackControls,\n\t    Default = true\n\t})\n\tAttackDelay = AutoDrill:CreateSlider({\n\t    Name = \"Attack delay\",\n\t    Min = 0.1,\n\t    Max = 1,\n\t    Default = 0.3,\n\t    Decimal = 100,\n\t    Suffix = function(Val: number)\n\t        return Val == 1 and \"sec\" or \"secs\"\n\t    end\n\t})\n\tCollectDelay = AutoDrill:CreateSlider({\n\t    Name = \"Collect delay\",\n\t    Min = 0.1,\n\t    Max = 3,\n\t    Default = 0.5,\n\t    Decimal = 10,\n\t    Suffix = function(Val: number)\n\t        return Val == 1 and \"sec\" or \"secs\"\n\t    end\n\t})\n\tTargets = AutoDrill:CreateTargets({\n\t    Players = true,\n\t    NPCs = false\n\t})\n\tlocal Methods: {string} = {\"Distance\", \"Health\", \"Damage\"}\n\tfor Method: string in SortMethods do\n\t    if not table.find(Methods, Method) then\n\t        table.insert(Methods, Method)\n\t    end\n\tend\n\tSort = AutoDrill:CreateDropdown({\n\t    Name = \"Sort\",\n\t    List = Methods,\n\t    Default = \"Distance\"\n\t})\n\tUpdateAttackControls()\nend)\n\nRun(function()\n\tlocal AutoElder\n\tlocal Streamer\n\tlocal Range\n\tlocal Animation\n\tlocal Delay\n\t\n\tlocal Legit: number = GetFunctionRange(bedwars.EldertreeController.createTreeOrbInteraction) or 10\n\tlocal Cooldowns: {[Instance]: number} = {}\n\t\n\tAutoElder = vape.Categories.Kits:CreateModule({\n\t    Name = \"AutoElder\",\n\t    Function = function(Callback: boolean)\n\t        if Callback then\n\t            AutoElder:Clean(ProximityPromptService.PromptShown:Connect(function(Prompt: ProximityPrompt)\n\t                if Streamer.Enabled and Prompt.Name == \"treeOrb\" then\n\t                    task.delay(0.1, Prompt.InputHoldBegin, Prompt)\n\t                end\n\t            end))\n\t\n\t            repeat\n\t                if not Streamer.Enabled and Entity.isAlive then\n\t                    local LocalPosition: Vector3 = Entity.character.RootPart.Position\n\t                    for _, v: PVInstance in CollectionService:GetTagged(\"treeOrb\") do\n\t                        local OrbPosition: Vector3? = v.Parent and v:GetPivot().Position\n\t                        if OrbPosition and tick() > (Cooldowns[v] or 0) and (LocalPosition - OrbPosition).Magnitude <= Range.Value then\n\t                            if Delay.Value > 0 then\n\t                                task.wait(Delay.Value)\n\t                            end\n\t\n\t                            if v.Parent and (Entity.character.RootPart.Position - v:GetPivot().Position).Magnitude <= Range.Value then\n\t                                if Animation.Enabled then\n\t                                    bedwars.GameAnimationUtil:playAnimation(LocalPlayer.Character, bedwars.AnimationType.PUNCH)\n\t                                    bedwars.ViewmodelController:playAnimation(bedwars.AnimationType.FP_USE_ITEM)\n\t                                    bedwars.AudioManager:playAudio(bedwars.SoundList.CROP_HARVEST)\n\t                                end\n\t\n\t                                if bedwars.Handler:Get(\"ConsumeTreeOrb\"):Fire(\"CallServer\", {treeOrbSecret = v:GetAttribute(\"TreeOrbSecret\")}) then\n\t                                    v:Destroy()\n\t                                end\n\t                                Cooldowns[v] = tick() + 1\n\t                            end\n\t                        end\n\t                    end\n\t                end\n\t                task.wait(0.1)\n\t            until not AutoElder.Enabled\n\t        else\n\t            table.clear(Cooldowns)\n\t        end\n\t    end,\n\t    Tooltip = \"Automatically collects tree orbs\"\n\t})\n\t\n\tStreamer = AutoElder:CreateToggle({\n\t    Name = \"Streamer mode\",\n\t    Function = function(Callback: boolean)\n\t        if Delay then\n\t            Delay.Object.Visible = not Callback\n\t            Range.Object.Visible = not Callback\n\t            Animation.Object.Visible = not Callback\n\t        end\n\t    end,\n\t    Tooltip = \"Useful for when ur screensharing\"\n\t})\n\tAnimation = AutoElder:CreateToggle({\n\t    Name = \"Animation\",\n\t    Default = true,\n\t    Tooltip = \"Plays the collect animation\"\n\t})\n\tRange = AutoElder:CreateSlider({\n\t    Name = \"Range\",\n\t    Min = 1,\n\t    Max = 20,\n\t    Default = 12,\n\t    Suffix = function(Val: number)\n\t        return Val > 1 and \"studs\" or \"stud\"\n\t    end\n\t})\n\tAutoElder:CreateButton({\n\t    Name = \"Sync to legit range\",\n\t    Function = function()\n\t        Range:SetValue(Legit)\n\t    end\n\t})\n\tDelay = AutoElder:CreateSlider({\n\t    Name = \"Delay\",\n\t    Min = 0,\n\t    Max = 1,\n\t    Default = 0.2,\n\t    Decimal = 100,\n\t    Suffix = function(Val: number)\n\t        return Val > 1 and \"secs\" or \"sec\"\n\t    end\n\t})\nend)\n\nRun(function()\n\tlocal AutoEldric\n\tlocal Targets\n\tlocal Range\n\tlocal Priority\n\tlocal Allies\n\tlocal Health\n\tlocal Linked\n\t\n\tlocal Link = bedwars.Handler:Get(\"WarlockLinkTarget\")\n\t\n\tlocal function GetHurtAlly(Origin: Vector3)\n\t    local Best, BestHealth\n\t    for _, v: any in Entity.List do\n\t        if not v.Targetable and v.Player and v ~= Entity.character and (v.RootPart.Position - Origin).Magnitude <= Range.Value then\n\t            local Ratio: number = v.Health / v.MaxHealth\n\t            if Ratio <= (Health.Value / 100) and (not BestHealth or Ratio < BestHealth) then\n\t                Best, BestHealth = v, Ratio\n\t            end\n\t        end\n\t    end\n\t    return Best\n\tend\n\t\n\tAutoEldric = vape.Categories.Kits:CreateModule({\n\t    Name = \"AutoEldric\",\n\t    Function = function(Callback: boolean)\n\t        if Callback then\n\t            Linked = nil\n\t\n\t            repeat\n\t                if Entity.isAlive and Store.equippedKit == \"warlock\" and Store.hand.tool and Store.hand.tool.Name == \"warlock_staff\" then\n\t                    local Origin: Vector3 = Entity.character.RootPart.Position\n\t                    local Target\n\t\n\t                    if Priority.Value == \"Teammates\" and Allies.Enabled then\n\t                        Target = GetHurtAlly(Origin)\n\t                    end\n\t\n\t                    if not Target then\n\t                        Target = Entity.EntityPosition({\n\t                            Origin = Origin,\n\t                            Range = Range.Value,\n\t                            Part = \"RootPart\",\n\t                            Players = Targets.Players.Enabled,\n\t                            NPCs = Targets.NPCs.Enabled,\n\t                            Priority = Targets.Priority.Value,\n\t                            Wallcheck = Targets.Walls.Enabled\n\t                        })\n\t                    end\n\t\n\t                    if not Target and Allies.Enabled then\n\t                        Target = GetHurtAlly(Origin)\n\t                    end\n\t\n\t                    if Target and Target.Character ~= Linked then\n\t                        if bedwars.AbilityController:canUseAbility(\"WARLOCK_LINK\", {disableBlockedAbilityAlert = true}) then\n\t                            bedwars.AbilityController:useAbility(\"WARLOCK_LINK\")\n\t                            task.wait(Store.ping.total or 0.1)\n\t                        end\n\t\n\t                        if AutoEldric.Enabled and Target.Character and Target.Character.Parent then\n\t                            Linked = Target.Character\n\t                            Link:Fire(\"CallServer\", {target = Target.Character})\n\t                        end\n\t                    elseif not Target then\n\t                        Linked = nil\n\t                    end\n\t                end\n\t                task.wait(0.1)\n\t            until not AutoEldric.Enabled\n\t        end\n\t    end,\n\t    Tooltip = \"Automatically links the warlock staff to enemies or hurt teammates\"\n\t})\n\t\n\tTargets = AutoEldric:CreateTargets({\n\t    Players = true,\n\t    Walls = true\n\t})\n\tRange = AutoEldric:CreateSlider({\n\t    Name = \"Range\",\n\t    Min = 1,\n\t    Max = 60,\n\t    Default = 24,\n\t    Suffix = function(Val: number)\n\t        return Val <= 1 and \"stud\" or \"studs\"\n\t    end\n\t})\n\tAutoEldric:CreateButton({\n\t    Name = \"Sync to legit range\",\n\t    Function = function()\n\t        Range:SetValue(bedwars.WarlockBalance and bedwars.WarlockBalance.SELECTOR_RANGE or 24)\n\t    end\n\t})\n\tPriority = AutoEldric:CreateDropdown({\n\t    Name = \"Priority\",\n\t    List = {\"Enemies\", \"Teammates\"},\n\t    Tooltip = \"Which side the staff links first when both are in range\"\n\t})\n\tAllies = AutoEldric:CreateToggle({\n\t    Name = \"Heal teammates\",\n\t    Default = true,\n\t    Tooltip = \"Links a hurt teammate when no enemy is in range\"\n\t})\n\tHealth = AutoEldric:CreateSlider({\n\t    Name = \"Ally health\",\n\t    Min = 1,\n\t    Max = 100,\n\t    Default = 70,\n\t    Darker = true,\n\t    Suffix = function()\n\t        return \"%\"\n\t    end\n\t})\nend)\n\nRun(function()\n\tlocal AutoElektra\n\tlocal Targets\n\tlocal Range\n\tlocal Face\n\tlocal NextDash: number = 0\n\t\n\tAutoElektra = vape.Categories.Kits:CreateModule({\n\t    Name = \"AutoElektra\",\n\t    Function = function(Callback: boolean)\n\t        if Callback then\n\t            NextDash = 0\n\t\n\t            repeat\n\t                if Entity.isAlive and Store.equippedKit == \"elektra\" and tick() >= NextDash and bedwars.AbilityController:canUseAbility(\"ELECTRIC_DASH\", {disableBlockedAbilityAlert = true}) then\n\t                    local Target = Entity.EntityPosition({\n\t                        Range = Range.Value,\n\t                        Part = \"RootPart\",\n\t                        Players = Targets.Players.Enabled,\n\t                        NPCs = Targets.NPCs.Enabled,\n\t                        Priority = Targets.Priority.Value,\n\t                        Wallcheck = Targets.Walls.Enabled,\n\t                        Sort = SortMethods.Distance\n\t                    })\n\t\n\t                    if Target then\n\t                        if Face.Enabled then\n\t                            local Root: BasePart = Entity.character.RootPart\n\t                            Root.CFrame = CFrame.lookAlong(Root.Position, (Target.RootPart.Position - Root.Position) * Vector3.new(1, 0, 1))\n\t                        end\n\t\n\t                        NextDash = tick() + 0.5\n\t                        bedwars.AbilityController:useAbility(\"ELECTRIC_DASH\")\n\t                    end\n\t                end\n\t                task.wait(0.1)\n\t            until not AutoElektra.Enabled\n\t        end\n\t    end,\n\t    Tooltip = \"Spends your dash charges on whoever walks into range\"\n\t})\n\t\n\tTargets = AutoElektra:CreateTargets({\n\t    Players = true,\n\t    NPCs = true,\n\t    Walls = true\n\t})\n\tRange = AutoElektra:CreateSlider({\n\t    Name 