\",\n\t    Min = 0,\n\t    Max = 1,\n\t    Default = 0.1,\n\t    Decimal = 100\n\t})\n\tRange = AutoEmber:CreateSlider({\n\t    Name = \"Range\",\n\t    Min = 1,\n\t    Max = 22,\n\t    Default = 22,\n\t    Suffix = function(Val: number)\n\t        return Val <= 1 and \"stud\" or \"studs\"\n\t    end\n\t})\n\tLimit = AutoEmber:CreateToggle({Name = \"Limit to item\"})\nend)\n\nRun(function()\n\tlocal AutoEquipKit\n\tlocal Kit\n\t\n\tlocal Kits, List = {}, {}\n\t\n\tfor KitType: string, v: any in bedwars.BedwarsKitMeta do\n\t    if v.name ~= \"None\" then\n\t        table.insert(List, v.name)\n\t    end\n\t    Kits[v.name] = KitType\n\tend\n\ttable.sort(List)\n\ttable.insert(List, 1, \"None\")\n\t\n\tAutoEquipKit = vape.Categories.Kits:CreateModule({\n\t    Name = \"AutoEquipKit\",\n\t    Function = function(Callback: boolean)\n\t        if Callback then\n\t            local Last: number?\n\t\n\t            repeat\n\t                if Store.matchState == 2 and Last == 1 and Kit.Value ~= \"None\" then\n\t                    bedwars.Handler:Get(\"BedwarsActivateKit\"):Fire(\"CallServer\", {kit = Kits[Kit.Value]})\n\t                    SendNotification(\"AutoEquipKit\", `Equipped {Kit.Value} for the next round.`, 10, \"info\")\n\t                end\n\t\n\t                Last = Store.matchState\n\t                task.wait(0.5)\n\t            until not AutoEquipKit.Enabled\n\t        end\n\t    end,\n\t    Tooltip = \"Equips a kit automatically when a round ends\"\n\t})\n\t\n\tKit = AutoEquipKit:CreateDropdown({\n\t    Name = \"Equip kit\",\n\t    List = List,\n\t    Default = \"None\"\n\t})\nend)\n\nRun(function()\n\tlocal AutoEvelynn\n\tlocal Range\n\tlocal Delay\n\tlocal EnemyCheck\n\t\n\tlocal Legit: number = GetFunctionRange(bedwars.SpiritAssassinController.onKitLocalActivated) or 120\n\t\n\tAutoEvelynn = vape.Categories.Kits:CreateModule({\n\t    Name = \"AutoEvelynn\",\n\t    Function = function(Callback: boolean)\n\t        if Callback then\n\t            local Spirits: {PVInstance} = Collection(\"EvelynnSoul\", AutoEvelynn)\n\t            local Cooldown: number = 0\n\t\n\t            repeat\n\t                if Entity.isAlive and Store.equippedKit == \"spirit_assassin\" and (Delay.Value <= 0 or tick() - Cooldown >= Delay.Value) and not bedwars.StatusEffectUtil:isActive(LocalPlayer.Character, \"grounded\") and not bedwars.StatusEffectUtil:isActive(LocalPlayer.Character, \"frosted\") then\n\t                    local LocalPosition: Vector3 = Entity.character.RootPart.Position\n\t                    for _, v: PVInstance in Spirits do\n\t                        local Position: Vector3 = v:GetPivot().Position\n\t                        if (LocalPosition - Position).Magnitude <= Range.Value and (not EnemyCheck.Enabled or Entity.EntityPosition({Origin = Position, Range = 18, Part = \"RootPart\", Players = true, NPCs = true})) then\n\t                            bedwars.Handler:Get(\"UseSpirit\"):Fire(\"CallServer\", {\n\t                                secret = v:GetAttribute(\"SpiritSecret\")\n\t                            })\n\t                            Cooldown = tick()\n\t                            break\n\t                        end\n\t                    end\n\t                end\n\t                task.wait(0.1)\n\t            until not AutoEvelynn.Enabled\n\t        end\n\t    end,\n\t    Tooltip = \"Eats nearby spirits so you teleport onto whoever you damaged\"\n\t})\n\t\n\tRange = AutoEvelynn:CreateSlider({\n\t    Name = \"Range\",\n\t    Min = 1,\n\t    Max = 120,\n\t    Default = 60,\n\t    Suffix = function(Val: number)\n\t        return Val <= 1 and \"stud\" or \"studs\"\n\t    end\n\t})\n\tAutoEvelynn:CreateButton({\n\t    Name = \"Sync to legit range\",\n\t    Function = function()\n\t        Range:SetValue(Legit)\n\t    end\n\t})\n\tDelay = AutoEvelynn:CreateSlider({\n\t    Name = \"Delay\",\n\t    Min = 0,\n\t    Max = 2,\n\t    Default = 0.1,\n\t    Decimal = 10,\n\t    Suffix = \"seconds\"\n\t})\n\tEnemyCheck = AutoEvelynn:CreateToggle({\n\t    Name = \"Enemy check\",\n\t    Tooltip = \"Only eats a spirit while somebody is still standing next to it\"\n\t})\nend)\n\nRun(function()\n\tlocal AutoFarmer\n\tlocal Harvest\n\tlocal Collect\n\tlocal Range\n\tlocal Delay\n\tlocal NextAction: number = 0\n\t\n\tlocal Drops: {[string]: boolean} = {\n\t    carrot = true,\n\t    carrot_seeds = true,\n\t    melon = true,\n\t    melon_seeds = true,\n\t    watermelon = true,\n\t    pumpkin = true,\n\t    pumpkin_block = true,\n\t    pumpkin_seeds = true\n\t}\n\t\n\tlocal function HarvestCrop(Origin: Vector3): boolean\n\t    for _, v: Instance in CollectionService:GetTagged(\"HarvestableCrop\") do\n\t        local Owner: number = v:GetAttribute(\"PlacedByUserId\") or 0\n\t        local Player = Owner ~= 0 and Players:GetPlayerByUserId(Owner)\n\t        if v:IsA(\"BasePart\") and (v.Position - Origin).Magnitude <= Range.Value and (not Player or Player:GetAttribute(\"Team\") == LocalPlayer:GetAttribute(\"Team\")) then\n\t            bedwars.Handler:Get(\"CropHarvest\"):Fire(\"CallServer\", {\n\t                position = bedwars.BlockController:getBlockPosition(v.Position)\n\t            })\n\t            return true\n\t        end\n\t    end\n\t    return false\n\tend\n\t\n\tlocal function CollectDrop(Origin: Vector3): boolean\n\t    for _, v: BasePart in CollectionService:GetTagged(\"ItemDrop\") do\n\t        if Drops[v.Name] and (v:GetAttribute(\"PickupReadyTime\") or math.huge) < workspace:GetServerTimeNow() and (v.Position - Origin).Magnitude <= Range.Value then\n\t            bedwars.Handler:Get(\"PickupItemDrop\"):Fire(\"CallServerAsync\", {itemDrop = v})\n\t            return true\n\t        end\n\t    end\n\t    return false\n\tend\n\t\n\tAutoFarmer = vape.Categories.Kits:CreateModule({\n\t    Name = \"AutoFarmer\",\n\t    Function = function(Callback: boolean)\n\t        if Callback then\n\t            NextAction = 0\n\t\n\t            repeat\n\t                if Entity.isAlive and Store.equippedKit == \"farmer_cletus\" and tick() >= NextAction then\n\t                    local Origin: Vector3 = Entity.character.RootPart.Position\n\t                    if (Harvest.Enabled and HarvestCrop(Origin)) or (Collect.Enabled and CollectDrop(Origin)) then\n\t                        NextAction = tick() + Delay.Value\n\t                    end\n\t                end\n\t                task.wait(0.1)\n\t            until not AutoFarmer.Enabled\n\t        end\n\t    end,\n\t    Tooltip = \"Harvests your ripe crops and picks up what they drop\"\n\t})\n\t\n\tHarvest = AutoFarmer:CreateToggle({\n\t    Name = \"Harvest crops\",\n\t    Default = true,\n\t    Tooltip = \"Reaps anything ripe, the same call the Harvest prompt makes\"\n\t})\n\tCollect = AutoFarmer:CreateToggle({\n\t    Name = \"Collect drops\",\n\t    Default = true,\n\t    Tooltip = \"Picks up the crops and seeds lying on the ground\"\n\t})\n\tRange = AutoFarmer:CreateSlider({\n\t    Name = \"Range\",\n\t    Min = 1,\n\t    Max = 60,\n\t    Default = 25,\n\t    Suffix = function(Val: number)\n\t        return Val <= 1 and \"stud\" or \"studs\"\n\t    end,\n\t    Tooltip = \"The games own harvest prompt stops at 6 studs, so the server may refuse anything much further out\"\n\t})\n\tAutoFarmer:CreateButton({\n\t    Name = \"Sync to legit range\",\n\t    Function = function()\n\t        Range:SetValue(6)\n\t    end\n\t})\n\tDelay = AutoFarmer:CreateSlider({\n\t    Name = \"Delay\",\n\t    Min = 0.05,\n\t    Max = 3,\n\t    Default = 0.15,\n\t    Decimal = 100,\n\t    Suffix = function(Val: number)\n\t        return Val <= 1 and \"sec\" or \"secs\"\n\t    end\n\t})\nend)\n\nRun(function()\n\tlocal AutoFlora\n\tlocal Mode\n\tlocal Height\n\tlocal Speed\n\tlocal NextGlide: number = 0\n\t\n\tAutoFlora = vape.Categories.Kits:CreateModule({\n\t    Name = \"AutoFlora\",\n\t    Function = function(Callback: boolean)\n\t        if Callback then\n\t            NextGlide = 0\n\t\n\t            repeat\n\t                if Entity.isAlive and Store.equippedKit == \"queen_bee\" and tick() >= NextGlide and bedwars.AbilityController:canUseAbility(\"QUEEN_BEE_GLIDE\", {disableBlockedAbilityAlert = true}) then\n\t                    local Root: BasePart = Entity.character.RootPart\n\t\n\t                    if Root.AssemblyLinearVelocity.Y <= -Speed.Value then\n\t                        local Drop: number = Mode.Value == \"Void\" and 2000 or Height.Value\n\t                        local Ground: RaycastResult? = workspace:Raycast(Root.Position, Vector3.new(0, -Drop, 0), Store.airRay)\n\t\n\t                        if not Ground then\n\t                            NextGlide = tick() + 1\n\t                            bedwars.AbilityController:useAbility(\"QUEEN_BEE_GLIDE\")\n\t                        end\n\t                    end\n\t                end\n\t                task.wait(0.05)\n\t            until not AutoFlora.Enabled\n\t        end\n\t    end,\n\t    Tooltip = \"Opens the glide the moment you drop with nothing under you\"\n\t})\n\t\n\tMode = AutoFlora:CreateDropdown({\n\t    Name = \"Mode\",\n\t    List = {\"Void\", \"Any Drop\"},\n\t    Default = \"Void\",\n\t    Function = function(Val: string)\n\t        if Height then\n\t            Height.Object.Visible = Val == \"Any Drop\"\n\t        end\n\t    end,\n\t    Tooltip = \"Void - only when there is no floor at all under you\\nAny Drop - also for long falls onto the map\"\n\t})\n\tHeight = AutoFlora:CreateSlider({\n\t    Name = \"Ground check\",\n\t    Min = 5,\n\t    Max = 200,\n\t    Default = 40,\n\t    Visible = false,\n\t    Suffix = function(Val: number)\n\t        return Val <= 1 and \"stud\" or \"studs\"\n\t    end\n\t})\n\tSpeed = AutoFlora:CreateSlider({\n\t    Name = \"Fall speed\",\n\t    Min = 1,\n\t    Max = 100,\n\t    Default = 20,\n\t    Tooltip = \"How fast you have to be dropping before it glides\"\n\t})\nend)\n\nRun(function()\n\tlocal AutoFreiya\n\tlocal Range\n\tlocal Stacks\n\tlocal 