                 local BreakType = ItemMeta and ItemMeta.block and ItemMeta.block.breakType\n\t                                    local Tool = BreakType and Store.tools[BreakType] or Store.tools.sword\n\t                                    local Slot = Tool and GetHotbar(Tool.tool)\n\t                                    if Slot then\n\t                                        HotbarSwitch(Slot)\n\t                                    elseif Tool then\n\t                                        SwitchItem(Tool.tool)\n\t                                    end\n\t                                end\n\t                                bedwars.breakBlock(Block, false, nil, nil, Switch.Enabled)\n\t                            end\n\t                        end)\n\t                    end\n\t\n\t                    if Jump.Enabled and Entity.isAlive then\n\t                        Entity.character.Humanoid:ChangeState(Enum.HumanoidStateType.Jumping)\n\t                    end\n\t                end\n\t                return Call\n\t            end\n\t        else\n\t            bedwars.LaunchPadController.attemptLaunch = Old\n\t        end\n\t    end,\n\t    Tooltip = \"Automatically handles Gingerbread Man launch pads.\"\n\t})\n\t\n\tPlace = AutoGingerbread:CreateToggle({\n\t    Name = \"Place pads\",\n\t    Function = function(Callback: boolean)\n\t        if PlaceDelay then\n\t            PlaceDelay.Object.Visible = Callback\n\t        end\n\t    end,\n\t    Tooltip = \"Drops a bounce pad into the cell below you whenever it is empty, so a jump lands you straight back onto one\",\n\t    Default = true\n\t})\n\tPlaceDelay = AutoGingerbread:CreateSlider({\n\t    Name = \"Place delay\",\n\t    Min = 0,\n\t    Max = 1,\n\t    Default = 0,\n\t    Decimal = 100,\n\t    Darker = true,\n\t    Suffix = function(Val: number)\n\t        return Val == 1 and \"sec\" or \"secs\"\n\t    end\n\t})\n\tBreak = AutoGingerbread:CreateToggle({\n\t    Name = \"Break launch pad\",\n\t    Function = function(Callback: boolean)\n\t        if Range then\n\t            Range.Object.Visible = Callback\n\t            Delay.Object.Visible = Callback\n\t            Switch.Object.Visible = Callback\n\t            OwnOnly.Object.Visible = Callback\n\t        end\n\t    end,\n\t    Default = true\n\t})\n\tJump = AutoGingerbread:CreateToggle({Name = \"Jump after launch\"})\n\t\n\tSwitch = AutoGingerbread:CreateToggle({\n\t    Name = \"Legit switch\",\n\t    Darker = true\n\t})\n\tOwnOnly = AutoGingerbread:CreateToggle({\n\t    Name = \"Own pads only\",\n\t    Default = true,\n\t    Darker = true\n\t})\n\tSuccessfulOnly = AutoGingerbread:CreateToggle({\n\t    Name = \"Successful launch only\",\n\t    Default = true\n\t})\n\tRange = AutoGingerbread:CreateSlider({\n\t    Name = \"Range\",\n\t    Min = 1,\n\t    Max = 30,\n\t    Default = 30,\n\t    Darker = true,\n\t    Suffix = function(Val: number)\n\t        return Val <= 1 and \"stud\" or \"studs\"\n\t    end\n\t})\n\tDelay = AutoGingerbread:CreateSlider({\n\t    Name = \"Break delay\",\n\t    Min = 0,\n\t    Max = 1,\n\t    Default = 0.05,\n\t    Decimal = 100,\n\t    Darker = true,\n\t    Suffix = function(Val: number)\n\t        return Val == 1 and \"sec\" or \"secs\"\n\t    end\n\t})\nend)\n\nRun(function()\n\tlocal AutoGrim\n\tlocal Range\n\tlocal Health\n\tlocal Delay\n\t\n\tlocal Legit: number = GetFunctionRange(bedwars.GrimReaperController.registerSoulInteractions) or 0\n\t\n\tAutoGrim = vape.Categories.Kits:CreateModule({\n\t    Name = \"AutoGrim\",\n\t    Function = function(Callback: boolean)\n\t        if Callback then\n\t            local Souls: {Model} = Collection(\"GrimSoul\", AutoGrim)\n\t            local Cooldown: number = 0\n\t\n\t            repeat\n\t                if Entity.isAlive and LocalPlayer.Character:GetAttribute(\"Health\") <= (LocalPlayer.Character:GetAttribute(\"MaxHealth\") * (Health.Value / 100)) and not LocalPlayer.Character:GetAttribute(\"GrimReaperChannel\") and (Delay.Value <= 0 or tick() - Cooldown >= Delay.Value) then\n\t                    local LocalPosition: Vector3 = Entity.character.RootPart.Position\n\t                    for _, v: Model in Souls do\n\t                        if (LocalPosition - v:GetPivot().Position).Magnitude <= Range.Value then\n\t                            bedwars.Handler:Get(\"ConsumeGrimReaperSoul\"):Fire(\"CallServer\", {\n\t                                secret = v:GetAttribute(\"GrimReaperSoulSecret\")\n\t                            })\n\t                            Cooldown = tick()\n\t                            break\n\t                        end\n\t                    end\n\t                end\n\t                task.wait(0.1)\n\t            until not AutoGrim.Enabled\n\t        end\n\t    end,\n\t    Tooltip = \"Automatically consumes nearby souls when your health drops low\"\n\t})\n\t\n\tRange = AutoGrim:CreateSlider({\n\t    Name = \"Range\",\n\t    Min = 1,\n\t    Max = 120,\n\t    Default = 12,\n\t    Suffix = function(Val: number)\n\t        return Val <= 1 and \"stud\" or \"studs\"\n\t    end\n\t})\n\tAutoGrim:CreateButton({\n\t    Name = \"Sync to legit range\",\n\t    Function = function()\n\t        Range:SetValue(Legit)\n\t    end\n\t})\n\tHealth = AutoGrim:CreateSlider({\n\t    Name = \"Health\",\n\t    Min = 1,\n\t    Max = 100,\n\t    Default = 25,\n\t    Suffix = function()\n\t        return \"%\"\n\t    end,\n\t    Tooltip = \"Only eats a soul once your health drops to this share of your maximum\"\n\t})\n\tDelay = AutoGrim:CreateSlider({\n\t    Name = \"Delay\",\n\t    Min = 0,\n\t    Max = 2,\n\t    Default = 0.1,\n\t    Decimal = 10,\n\t    Suffix = \"seconds\"\n\t})\nend)\n\nRun(function()\n\tlocal AutoGrove\n\tlocal Delay\n\tlocal NextWater: number = 0\n\t\n\tAutoGrove = vape.Categories.Kits:CreateModule({\n\t    Name = \"AutoGrove\",\n\t    Function = function(Callback: boolean)\n\t        if Callback then\n\t            NextWater = 0\n\t\n\t            repeat\n\t                if Entity.isAlive and Store.equippedKit == \"spirit_gardener\" and tick() >= NextWater and bedwars.AbilityController:canUseAbility(\"spirit_gardener_water\", {disableBlockedAbilityAlert = true}) then\n\t                    NextWater = tick() + Delay.Value\n\t                    bedwars.AbilityController:useAbility(\"spirit_gardener_water\")\n\t                end\n\t                task.wait(0.1)\n\t            until not AutoGrove.Enabled\n\t        end\n\t    end,\n\t    Tooltip = \"Automatically feeds spirit energy to your flowers so they never wither\"\n\t})\n\t\n\tDelay = AutoGrove:CreateSlider({\n\t    Name = \"Delay\",\n\t    Min = 0.5,\n\t    Max = 20,\n\t    Default = 3,\n\t    Decimal = 10,\n\t    Suffix = function(Val: number)\n\t        return Val <= 1 and \"sec\" or \"secs\"\n\t    end\n\t})\nend)\n\nRun(function()\n\tlocal AutoHannah\n\tlocal Targets\n\tlocal Sort\n\tlocal Range\n\tlocal AuraTarget\n\tlocal Attempted = setmetatable({}, {__mode = \"k\"})\n\t\n\tAutoHannah = vape.Categories.Kits:CreateModule({\n\t    Name = \"AutoHannah\",\n\t    Function = function(Callback: boolean)\n\t        if Callback then\n\t            repeat\n\t                if Entity.isAlive and Store.equippedKit == \"hannah\" and not bedwars.StatusEffectUtil:isActive(LocalPlayer.Character, \"grounded\") and not bedwars.StatusEffectUtil:isActive(LocalPlayer.Character, \"frosted\") then\n\t                    local Threshold: number = bedwars.BalanceFile.HANNAH_BASE_EXECUTE_THRESHOLD + (bedwars.BalanceFile.HANNAH_MAX_COMBO * bedwars.BalanceFile.HANNAH_COMBO_EXECUTE_BOOST)\n\t\n\t                    for _, v: any in Entity.AllPosition({\n\t                        Origin = Entity.character.RootPart.Position,\n\t                        Range = Range.Value,\n\t                        Part = \"RootPart\",\n\t                        Players = Targets.Players.Enabled,\n\t                        NPCs = Targets.NPCs.Enabled,\n\t                        Priority = Targets.Priority.Value,\n\t                        Sort = SortMethods[Sort.Value]\n\t                    }) do\n\t                        if v.Character:HasTag(\"HannahExecuteInteraction\") and v.Health <= v.MaxHealth * Threshold and (not AuraTarget.Enabled or (TargetInfo.Targets[v] or 0) > tick()) and (not Attempted[v.Character] or tick() - Attempted[v.Character] >= 0.3) then\n\t                            Attempted[v.Character] = tick()\n\t\n\t                            if bedwars.Handler:Get(\"HannahPromptTrigger\"):Fire(\"CallServer\", {\n\t                                user = LocalPlayer,\n\t                                victimEntity = v.Character\n\t                            }) then\n\t                                local Billboard: Instance? = v.Character:FindFirstChild(\"Hannah Execution Icon\")\n\t                                if Billboard then\n\t                                    Billboard:Destroy()\n\t                                end\n\t                            end\n\t\n\t                            break\n\t                        end\n\t                    end\n\t                end\n\t                task.wait(0.1)\n\t            until not AutoHannah.Enabled\n\t            table.clear(Attempted)\n\t        end\n\t    end,\n\t    Tooltip = \"Automatically executes low health players with Hannah.\"\n\t})\n\t\n\tTargets = AutoHannah:CreateTargets({Players = true})\n\tlocal Methods: {string} = {\"Health\", \"Distance\"}\n\tfor _, v: string in SortList do\n\t    if not table.find(Methods, v) then\n\t        table.insert(Methods, v)\n\t    end\n\tend\n\tSort = AutoHannah:CreateDropdown({\n\t    Name = \"Target mode\",\n\t    List = Methods,\n\t    Default = \"Health\"\n\t})\n\tRange = AutoHannah:CreateSlider({\n\t    Name = \"Range\",\n\t    Min = 1,\n\t    Max = 30,\n\t    Default = 30,\n\t    Suffix = function(Val: number)\n\t        return Val <= 1 and \"stud\" or \"studs\"\n\t    end\n\t})\n\tAuraTarget = AutoHannah:CreateToggle({\n\t    Name = \"Only killaura target\",\n\t    Tooltip = \"Only executes targets that are being attacked by killaura\"\n\t})\nend)\n\nRun(function()\n\tlocal AutoHephaestus\n\tlocal Summon\n\tlocal LastRepair, LastSummon = 0, 0\n\t\n\tAutoHephaestus = vape.Categories.Kits:CreateModule({\n\t    Name = \"AutoHephaestus\",\n\t    Function = function(Callback: boolean)\n\t        if Callback then\n\t            AutoHephaestus:Clean(RunService.Heartbeat:Connect(function()\n\t                if Store.equippedKit ~= \"tinker\" then\n\t                    return\n\t                end\n\t\n\t                if bedwars.TinkerKitController.mounted then\n\t                    if tick() >= LastRepair and bedwars.AbilityController:canUseAbility(\"tinker_self_repair\", {disableBlockedAbilityAlert = true}) and (workspace:GetServerTimeNow() - bedwars.SwordController.lastAttack) > 1 then\n\t                        LastRepair = tick() + 0.5\n\t                        bedwars.AbilityController:useAbility(\"tinker_self_repair\")\n\t                    end\n\t                elseif Summon.Enabled and tick() >= LastSummon and bedwars.AbilityController:canUseAbility(\"tinker_summon\", {disableBlockedAbilityAlert = true}) then\n\t                    LastSummon = tick() + 1\n\t                    bedwars.AbilityController:useAbility(\"tinker_summon\")\n\t                end\n\t            end))\n\t        end\n\t    end,\n\t    Tooltip = \"Automatically repairs your Tinker machine whenever the self repair ability is available\"\n\t})\n\t\n\tSummon = AutoHephaestus:CreateToggle({\n\t    Name = \"Summon tinker\",\n\t    Tooltip = \"Calls the machine back whenever you are not mounted on it\"\n\t})\nend)\n\nRun(function()\n\tlocal AutoJade\n\tlocal Height\n\tlocal FallSpeed\n\tlocal Switch\n\tlocal SwitchDelay = {}\n\tlocal LimitItem\n\tlocal NextSlam: number = 0\n\t\n\tlocal function Slam(Hammer)\n\t    if store.hand.tool ~= Hammer.tool then\n\t        if Switch.Enabled then\n\t            hotbarSwitch(getHotbar(Hammer.tool))\n\t        else\n\t            switchItem(Hammer.tool, 0)\n\t        end\n\t        task.wait(SwitchDelay.Value)\n\t    end\n\t\n\t    if AutoJade.Enabled and Entity.isAlive and bedwars.AbilityController:canUseAbility(\"jade_hammer_jump\", {disableBlockedAbilityAlert = true}) then\n\t        bedwars.JadeHammerController:useJadeHammer()\n\t    end\n\tend\n\t\n\tAutoJade = vape.Categories.Kits:CreateModule({\n\t    Name = \"AutoJade\",\n\t    Function = function(Callback: boolean)\n\t        if Callback then\n\t            NextSlam = 0\n\t\n\t            AutoJade:Clean(RunService.Heartbeat:Connect(function()\n\t                if not Entity.isAlive or store.equippedKit ~= \"jade\" or tick() < NextSlam or not bedwars.JadeHammerController then\n\t                    return\n\t                end\n\t\n\t                local Root: BasePart = Entity.character.RootPart\n\t                if Root.AssemblyLinearVelocity.Y > -FallSpeed.Value then\n\t                    return\n\t                end\n\t                if not bedwars.AbilityController:canUseAbility(\"jade_hammer_jump\", {disableBlockedAbilityAlert = true}) then\n\t                    return\n\t                end\n\t                if not Entity.Raycast(Root.Position, Vector3.new(0, -Height.Value, 0), store.airRay) then\n\t                    return\n\t                end\n\t\n\t                local Hammer\n\t                if store.hand.tool and bedwars.JadeBalance.isJadeHammer(store.hand.tool.Name) then\n\t                    Hammer = store.hand\n\t                elseif not LimitItem.Enabled then\n\t                    for _, v: any in store.inventory.inventory.items do\n\t                        if bedwars.JadeBalance.isJadeHammer(v.itemType) then\n\t                            Hammer = v\n\t                            break\n\t                        end\n\t                    end\n\t                end\n\t                if not Hammer then\n\t                    return\n\t                end\n\t\n\t                NextSlam = tick() + bedwars.JadeBalance.HAMMER_COOLDOWN\n\t                task.spawn(Slam, Hammer)\n\t            end))\n\t        end\n\t    end,\n\t    Tooltip = \"Slams the Jade hammer down right before you land\"\n\t})\n\t\n\tHeight = AutoJade:CreateSlider({\n\t    Name = \"Height\",\n\t    Min = 3,\n\t    Max = 60,\n\t    Default = 15,\n\t    Suffix = function(Val: number)\n\t        return Val <= 1 and \"stud\" or \"studs\"\n\t    end,\n\t    Tooltip = \"Slams once the ground is this close beneath you\"\n\t})\n\tFallSpeed = AutoJade:CreateSlider({\n\t    Name = \"Fall speed\",\n\t    Min = 0,\n\t    Max = 100,\n\t    Default = 10,\n\t    Tooltip = \"Only slams once you are dropping this fast\"\n\t})\n\tSwitch = AutoJade:CreateToggle({\n\t    Name = \"Legit switch\",\n\t    Function = function(Callback: boolean)\n\t        if SwitchDelay.Object then\n\t            SwitchDelay.Object.Visible = Callback\n\t        end\n\t    end,\n\t    Tooltip = \"Takes the hammer out through the hotbar instead of silently\"\n\t})\n\tSwitchDelay = AutoJade:CreateSlider({\n\t    Name = \"Switch delay\",\n\t    Min = 0,\n\t    Max = 1,\n\t    Decimal = 100,\n\t    Default = 0.05,\n\t    Darker = true,\n\t    Visible = false,\n\t    Suffix = \"seconds\"\n\t})\n\tLimitItem = AutoJade:CreateToggle({\n\t    Name = \"Limit to items\",\n\t    Tooltip = \"Only slams while the hammer is already held\"\n\t})\nend)\n\nRun(function()\n\tlocal AutoKaida\n\tlocal Targets\n\tlocal Sort\n\tlocal SwingRange\n\tlocal AttackRange\n\tlocal Spell\n\tlocal SpellMode\n\tlocal SpellCharge\n\tlocal SpellRange\n\tlocal Swing\n\tlocal Limit\n\tlocal Mouse\n\tlocal GUI\n\t\n\tlocal Casting: number = 0\n\t\n\tlocal function GetClaw()\n\t    if Limit.Enabled then\n\t        return Store.hand.tool and bedwars.IsItemClaw(Store.hand.tool.Name) and Store.hand or nil\n\t    end\n\t\n\t    for _, v: any in Store.inventory.inventory.items do\n\t        if bedwars.IsItemClaw(v.itemType) then\n\t            return v\n\t        end\n\t    end\n\t    return nil\n\tend\n\t\n\tlocal function CastSpell()\n\t    local LocalPosition: Vector3 = Entity.character.RootPart.Position\n\t    local Range: number = math.min(SpellRange.Value, bedwars.SummonerKitBalance.SPELL_CAST_RANGE)\n\t    local Target: Vector3?\n\t    if SpellMode.Value == \"Camera\" then\n\t        local Point: Vector3? = bedwars.AbilityIndicatorUtil:calculateBlockTargetPoint(Camera.CFrame.Position, Camera.CFrame.LookVector, 300, nil, {allowArenaBarrierTarget = false})\n\t        Target = Point and (Point - LocalPosition).Magnitude <= Range and Point or nil\n\t    else\n\t        local Ent = Entity.EntityPosition({\n\t            Range = Range,\n\t            Wallcheck = Targets.Walls.Enabled or nil,\n\t            Part = \"RootPart\",\n\t            Players = Targets.Players.Enabled,\n\t            NPCs = Targets.NPCs.Enabled,\n\t            Priority = Targets.Priority.Value,\n\t            Sort = SortMethods[Sort.Value]\n\t        })\n\t        if Ent then\n\t            local Point: Vector3? = bedwars.AbilityIndicatorUtil:calculateBlockTargetPoint(Ent.RootPart.Position + Vector3.new(0, 3, 0), Vector3.new(0, -1, 0), 30, nil, {allowArenaBarrierTarget = false})\n\t            Target = Point and (Point - LocalPosition).Magnitude <= Range and Point or Ent.RootPart.Position\n\t        end\n\t    end\n\t    if not Target or not bedwars.AbilityController:canUseAbility(\"summoner_start_charging\", {disableBlockedAbilityAlert = true}) then\n\t        return\n\t    end\n\t\n\t    Casting = tick() + 6\n\t    bedwars.AbilityController:useAbility(\"summoner_start_charging\", nil, {targetPosition = Target})\n\t\n\t    local Level: number = bedwars.SummonerUtil.summoner_getPlayerSpellLevel(LocalPlayer) or 1\n\t    local Charge: number = math.max(bedwars.SummonerUtil.summoner_getTotalCastTimeRequired(Level) * (SpellCharge.Value / 100), bedwars.SummonerKitBalance.SPELL_MINIMUM_CAST_TIME)\n\t    local Deadline: number = tick() + Charge\n\t    repeat\n\t        task.wait()\n\t    until tick() >= Deadline or not AutoKaida.Enabled or not Entity.isAlive or not bedwars.SummonerKitController:isPlayerCastingSpell(LocalPlayer)\n\t\n\t    if AutoKaida.Enabled and Entity.isAlive and bedwars.SummonerKitController:isPlayerCastingSpell(LocalPlayer) then\n\t        bedwars.AbilityController:useAbility(\"summoner_finish_charging\")\n\t    end\n\t    Casting = 0\n\tend\n\t\n\tAutoKaida = vape.Categories.Kits:CreateModule({\n\t    Name = \"AutoKaida\",\n\t    Function = function(Callback: boolean)\n\t        if Callback then\n\t            repeat\n\t                if Entity.isAlive and Store.equippedKit == \"summoner\" then\n\t                    if Spell.Enabled and tick() > Casting and not bedwars.SummonerKitController:isPlayerCastingSpell(LocalPlayer) then\n\t                        task.spawn(CastSpell)\n\t                    end\n\t\n\t                    local Claw = (not Mouse.Enabled or UserInputService:IsMouseButtonPressed(0)) and (not GUI.Enabled or not bedwars.AppController:isLayerOpen(bedwars.UILayers.MAIN)) and GetClaw()\n\t                    local Ent = Claw and (workspace:GetServerTimeNow() - bedwars.SummonerClawHandController.lastAttackTime) > bedwars.SummonerKitBalance.CLAW_COOLDOWN and (Swing.Enabled or not bedwars.SummonerKitController:isPlayerCastingSpell(LocalPlayer)) and Entity.EntityPosition({\n\t                        Range = SwingRange.Value,\n\t                        Wallcheck = Targets.Walls.Enabled or nil,\n\t                        Part = \"RootPart\",\n\t                        Players = Targets.Players.Enabled,\n\t                        NPCs = Targets.NPCs.Enabled,\n\t                        Priority = Targets.Priority.Value,\n\t                        Sort = SortMethods[Sort.Value]\n\t                    })\n\t\n\t                    if Ent then\n\t                        local SelfPosition: Vector3 = Entity.character.RootPart.Position\n\t                        local Delta: Vector3 = Ent.RootPart.Position - SelfPosition\n\t                        local Direction: Vector3 = CFrame.lookAt(SelfPosition, Ent.RootPart.Position).LookVector\n\t                        TargetInfo.Targets[Ent] = tick() + 1\n\t                        SwitchItem(Claw.tool, 0)\n\t                        if Delta.Magnitude <= AttackRange.Value then\n\t                            bedwars.Handler:Get(\"SummonerClawAttackRequest\"):Fire(nil, {\n\t                                position = SelfPosition + Direction * math.max(Delta.Magnitude - 16.399, 0),\n\t                                direction = Direction,\n\t                                clientTime = workspace:GetServerTimeNow()\n\t                            })\n\t                        end\n\t                        bedwars.SummonerClawHandController.lastAttackTime = workspace:GetServerTimeNow()\n\t                        bedwars.SummonerClawController:clawAttack(LocalPlayer, SelfPosition, Direction, Claw.tool.Name)\n\t                    end\n\t                end\n\t\n\t                task.wait(0.1)\n\t            until not AutoKaida.Enabled\n\t        else\n\t            Casting = 0\n\t        end\n\t    end,\n\t    Tooltip = \"Automatically attacks with the Kaida claw and casts her summon circle\"\n\t})\n\t\n\tTargets = AutoKaida:CreateTargets({Players = true})\n\tlocal Methods: {string} = {\"Distance\", \"Damage\"}\n\tfor _, v: string in SortList do\n\t    if not table.find(Methods, v) then\n\t        table.insert(Methods, v)\n\t    end\n\tend\n\tSort = AutoKaida:CreateDropdown({\n\t    Name = \"Target mode\",\n\t    List = Methods\n\t})\n\tSwingRange = AutoKaida:CreateSlider({\n\t    Name = \"Swing Range\",\n\t    Min = 1,\n\t    Max = 32,\n\t    Default = 32,\n\t    Suffix = function(Val: number)\n\t        return Val <= 1 and \"stud\" or \"studs\"\n\t    end\n\t})\n\tAttackRange = AutoKaida:CreateSlider({\n\t    Name = \"Attack Range\",\n\t    Min = 1,\n\t    Max = 32,\n\t    Default = 32,\n\t    Suffix = function(Val: number)\n\t        return Val <= 1 and \"stud\" or \"studs\"\n\t    end\n\t})\n\tSpell = AutoKaida:CreateToggle({\n\t    Name = \"Auto summon\",\n\t    Function = function(Callback: boolean)\n\t        if SpellMode then\n\t            SpellMode.Object.Visible = Callback\n\t            SpellCharge.Object.Visible = Callback\n\t            SpellRange.Object.Visible = Callback\n\t        end\n\t    end,\n\t    Tooltip = \"Charges and drops the summon circle on its own\"\n\t})\n\tSpellMode = AutoKaida:CreateDropdown({\n\t    Name = \"Summon at\",\n\t    List = {\"Target\", \"Camera\"},\n\t    Darker = true,\n\t    Visible = false,\n\t    Tooltip = \"Target drops the circle on the closest enemy, Camera drops it where you are looking\"\n\t})\n\tSpellCharge = AutoKaida:CreateSlider({\n\t    Name = \"Charge\",\n\t    Min = 1,\n\t    Max = 100,\n\t    Default = 100,\n\t    Darker = true,\n\t    Visible = false,\n\t    Suffix = \"%\",\n\t    Tooltip = \"How far to charge before releasing, 100% is the full radius for your spell level\"\n\t})\n\tSpellRange = AutoKaida:CreateSlider({\n\t    Name = \"Summon Range\",\n\t    Min = 1,\n\t    Max = 120,\n\t    Default = math.floor(bedwars.SummonerKitBalance.SPELL_CAST_RANGE),\n\t    Darker = true,\n\t    Visible = false,\n\t    Suffix = function(Val: number)\n\t        return Val <= 1 and \"stud\" or \"studs\"\n\t    end,\n\t    Tooltip = \"Capped at the range the game allows, which KitExtender can raise\"\n\t})\n\tSwing = AutoKaida:CreateToggle({\n\t    Name = \"Swing during ability\",\n\t    Default = true,\n\t    Tooltip = \"Continue claw attacks while the ability is charging\"\n\t})\n\tLimit = AutoKaida:CreateToggle({\n\t    Name = \"Limit to items\",\n\t    Tooltip = \"Only attacks while the claw is held\"\n\t})\n\tMouse = AutoKaida:CreateToggle({Name = \"Require mouse down\"})\n\tGUI = AutoKaida:CreateToggle({Name = \"GUI check\"})\nend)\n\nRun(function()\n\tlocal AutoKaliyah\n\tlocal Range\n\tlocal Stacks\n\tlocal Delay\n\tlocal NoSlow\n\t\n\tlocal Legit: number = GetFunctionRange(bedwars.DragonSlayerController.hasEligiblePunchTarget) or 14.4\n\tlocal Modifier, Old\n\tlocal NoSlowUntil: number = 0\n\t\n\tlocal function Punch()\n\t    if NoSlow.Enabled then\n\t        if not Old then\n\t            Modifier = bedwars.SprintController:getMovementStatusModifier()\n\t            Old = Modifier.addModifier\n\t            Modifier.addModifier = function(self, Data)\n\t                if NoSlow.Enabled and tick() < NoSlowUntil and Data and Data.moveSpeedMultiplier == 0 then\n\t                    Data.moveSpeedMultiplier = 1\n\t                end\n\t                return Old(self, Data)\n\t            end\n\t\n\t            AutoKaliyah:Clean(function()\n\t                Modifier.addModifier = Old\n\t                Modifier, Old = nil, nil\n\t                NoSlowUntil = 0\n\t            end)\n\t        end\n\t        NoSlowUntil = math.max(NoSlowUntil, tick() + Delay.Value + 0.1)\n\t    end\n\t\n\t    task.wait(Delay.Value)\n\t    bedwars.AbilityController:useAbility(\"dragon_slayer_punch\")\n\tend\n\t\n\tAutoKaliyah = vape.Categories.Kits:CreateModule({\n\t    Name = \"AutoKaliyah\",\n\t    Function = function(Callback: boolean)\n\t        if Callback then\n\t            repeat\n\t                if Entity.isAlive and Store.equippedKit == \"dragon_slayer\" and bedwars.AbilityController:canUseAbility(\"dragon_slayer_punch\", {disableBlockedAbilityAlert = true}) then\n\t                    local LocalPosition: Vector3 = Entity.character.RootPart.Position\n\t                    for Target: Model, Emblem: any in bedwars.DragonSlayerController.dragonEmblems do\n\t                        if Emblem.stackCount >= Stacks.Value and Target.PrimaryPart and (Target.PrimaryPart.Position - LocalPosition).Magnitude <= Range.Value then\n\t                            Punch()\n\t                            break\n\t                        end\n\t                    end\n\t                end\n\t                task.wait(0.1)\n\t            until not AutoKaliyah.Enabled\n\t        end\n\t    end,\n\t    Tooltip = 'Automatically uses the \"punch\" ability from kaliyah'\n\t})\n\t\n\tNoSlow = AutoKaliyah:CreateToggle({\n\t    Name = \"No Slow\",\n\t    Default = true,\n\t    Tooltip = 'Prevents you from being slowed down after using the \"Punch\" ability'\n\t})\n\tRange = AutoKaliyah:CreateSlider({\n\t    Name = \"Range\",\n\t    Min = 1,\n\t    Max = 20,\n\t    Default = 18,\n\t    Suffix = function(Val: number)\n\t        return Val <= 1 and \"stud\" or \"studs\"\n\t    end\n\t})\n\tAutoKaliyah:CreateButton({\n\t    Name = \"Sync to legit range\",\n\t    Function = function()\n\t        Range:SetValue(Legit)\n\t    end\n\t})\n\tStacks = AutoKaliyah:CreateSlider({\n\t    Name = \"Stacks\",\n\t    Min = 1,\n\t    Max = 3,\n\t    Default = 1,\n\t    Suffix = function(Val: number)\n\t        return Val <= 1 and \"stack\" or \"stacks\"\n\t    end,\n\t    Tooltip = \"How many emblems a target needs before the punch fires, 3 stacks deals 25 damage against a wall instead of 10\"\n\t})\n\tDelay = AutoKaliyah:CreateSlider({\n\t    Name = \"Delay\",\n\t    Min = 0,\n\t    Max = 1,\n\t    Default = 0.1,\n\t    Decimal = 100\n\t})\nend)\n\nRun(function()\n\tlocal AutoKit\n\tlocal Legit\n\tlocal Toggles = {}\n\tlocal Running = {}\n\t\n\tlocal function NewSession()\n\t    local Session = {Tasks = {}}\n\t\n\t    function Session:Clean(Task: any)\n\t        table.insert(self.Tasks, type(Task) == \"function\" and {Disconnect = Task} or Task)\n\t    end\n\t\n\t    function Session:Stop()\n\t        if self.Thread and coroutine.status(self.Thread) ~= \"dead\" then\n\t            task.cancel(self.Thread)\n\t        end\n\t        for _, v: any in self.Tasks do\n\t            v:Disconnect()\n\t        end\n\t        table.clear(self.Tasks)\n\t    end\n\t\n\t    return Session\n\tend\n\t\n\tlocal function KitCollection(Id, Callback: (Instance) -> (), Range: number, Specific: boolean, Session)\n\t    local Objects = type(Id) == \"table\" and Id or Collection(Id, Session)\n\t    repeat\n\t        if Entity.isAlive then\n\t            local LocalPosition: Vector3 = Entity.character.RootPart.Position\n\t            for _, v: Instance in Objects do\n\t                if (vape.Modules.InfiniteFly or {}).Enabled or not AutoKit.Enabled then\n\t                    break\n\t                end\n\t                local Part = not v:IsA(\"Model\") and v or (v.PrimaryPart or v:FindFirstChildWhichIsA(\"BasePart\", true))\n\t                if Part and (Part.Position - LocalPosition).Magnitude <= (not Legit.Enabled and Specific and math.huge or Range) then\n\t                    Callback(v)\n\t                end\n\t            end\n\t        end\n\t        task.wait(0.1)\n\t    until not AutoKit.Enabled\n\tend\n\t\n\tlocal AutoKitFunctions = {\n\t    battery = function()\n\t        repeat\n\t            if Entity.isAlive then\n\t                local LocalPosition: Vector3 = Entity.character.RootPart.Position\n\t                for BatteryId: any, v: any in bedwars.BatteryEffectsController.liveBatteries do\n\t                    if (v.position - LocalPosition).Magnitude <= 10 then\n\t                        local BatteryInfo = bedwars.BatteryEffectsController:getBatteryInfo(BatteryId)\n\t                        if not BatteryInfo or BatteryInfo.activateTime >= workspace:GetServerTimeNow() or BatteryInfo.consumeTime + 0.1 >= workspace:GetServerTimeNow() then\n\t                            continue\n\t                        end\n\t                        BatteryInfo.consumeTime = workspace:GetServerTimeNow()\n\t                        bedwars.Handler:Get(\"ConsumeBattery\"):Fire(\"SendToServer\", {batteryId = BatteryId})\n\t                    end\n\t                end\n\t            end\n\t            task.wait(0.1)\n\t        until not AutoKit.Enabled\n\t    end,\n\t    beekeeper = function(Session)\n\t        KitCollection(\"bee\", function(Bee: Instance)\n\t            bedwars.Handler:Get(\"PickUpBee\"):Fire(\"SendToServer\", {beeId = Bee:GetAttribute(\"BeeId\")})\n\t        end, 18, false, Session)\n\t    end,\n\t    bigman = function(Session)\n\t        KitCollection(\"treeOrb\", function(Orb: Instance)\n\t            if bedwars.Handler:Get(\"ConsumeTreeOrb\"):Fire(\"CallServer\", {treeOrbSecret = Orb:GetAttribute(\"TreeOrbSecret\")}) then\n\t                Orb:Destroy()\n\t            end\n\t        end, 12, false, Session)\n\t    end,\n\t    block_kicker = function(Session)\n\t        local Old = bedwars.BlockKickerKitController.getKickBlockProjectileOriginPosition\n\t        bedwars.BlockKickerKitController.getKickBlockProjectileOriginPosition = function(...)\n\t            local Origin, Direction = select(2, ...)\n\t            local Ent = Entity.EntityMouse({\n\t                Part = \"RootPart\",\n\t                Range = 1000,\n\t                Origin = Origin,\n\t                Players = true,\n\t                Wallcheck = true\n\t            })\n\t\n\t            if Ent then\n\t                local AimPosition: Vector3? = PredictionLib.SolveTrajectory(Origin, 100, 20, Ent.RootPart.Position, Ent.RootPart.AssemblyLinearVelocity, workspace.Gravity, Ent.HipHeight, Ent.Jumping and 42.6 or nil)\n\t                if AimPosition then\n\t                    for i: number, v: any in debug.getstack(2) do\n\t                        if v == Direction then\n\t                            debug.setstack(2, i, CFrame.lookAt(Origin, AimPosition).LookVector)\n\t                        end\n\t                    end\n\t                end\n\t            end\n\t\n\t            return Old(...)\n\t        end\n\t\n\t        Session:Clean(function()\n\t            bedwars.BlockKickerKitController.getKickBlockProjectileOriginPosition = Old\n\t        end)\n\t    end,\n\t    cat = function(Session)\n\t        local Old = bedwars.CatController.leap\n\t        bedwars.CatController.leap = function(...)\n\t            VapeEvents.CatPounce:Fire()\n\t            return Old(...)\n\t        end\n\t\n\t        Session:Clean(function()\n\t            bedwars.CatController.leap = Old\n\t        end)\n\t    end,\n\t    davey = function(Session)\n\t        local Old = bedwars.CannonHandController.launchSelf\n\t        bedwars.CannonHandController.launchSelf = function(...)\n\t            local Results = {Old(...)}\n\t            local self, Block = ...\n\t            if Block:GetAttribute(\"PlacedByUserId\") == LocalPlayer.UserId and (Block.Position - Entity.character.RootPart.Position).Magnitude < 30 then\n\t                task.spawn(bedwars.breakBlock, Block, false)\n\t            end\n\t\n\t            return unpack(Results)\n\t        end\n\t\n\t        Session:Clean(function()\n\t            bedwars.CannonHandController.launchSelf = Old\n\t        end)\n\t    end,\n\t    dragon_slayer = function()\n\t        repeat\n\t            if Entity.isAlive and not (vape.Modules.InfiniteFly or {}).Enabled and bedwars.DragonSlayerController:hasEligiblePunchTarget() and bedwars.AbilityController:canUseAbility(\"dragon_slayer_punch\", {disableBlockedAbilityAlert = true}) then\n\t                bedwars.AbilityController:useAbility(\"dragon_slayer_punch\")\n\t            end\n\t            task.wait(0.1)\n\t        until not AutoKit.Enabled\n\t    end,\n\t    farmer_cletus = function(Session)\n\t        KitCollection(\"HarvestableCrop\", function(Crop: BasePart)\n\t            if bedwars.Handler:Get(\"CropHarvest\"):Fire(\"CallServer\", {position = bedwars.BlockController:getBlockPosition(Crop.Position)}) then\n\t                bedwars.GameAnimationUtil:playAnimation(LocalPlayer.Character, bedwars.AnimationType.PUNCH)\n\t                bedwars.AudioManager:playAudio(bedwars.SoundList.CROP_HARVEST)\n\t            end\n\t        end, 10, false, Session)\n\t    end,\n\t    fisherman = function(Session)\n\t        local Old = bedwars.FishingMinigameController.startMinigame\n\t        bedwars.FishingMinigameController.startMinigame = function(_, _, Result)\n\t            Result({win = true})\n\t        end\n\t\n\t        Session:Clean(function()\n\t            bedwars.FishingMinigameController.startMinigame = Old\n\t        end)\n\t    end,\n\t    gingerbread_man = function(Session)\n\t        local Old = bedwars.LaunchPadController.attemptLaunch\n\t        bedwars.LaunchPadController.attemptLaunch = function(...)\n\t            local Results = {Old(...)}\n\t            local self, Block = ...\n\t            if (workspace:GetServerTimeNow() - self.lastLaunch) < 0.4 then\n\t                if Block:GetAttribute(\"PlacedByUserId\") == LocalPlayer.UserId and (Block.Position - Entity.character.RootPart.Position).Magnitude < 30 then\n\t                    task.spawn(bedwars.breakBlock, Block, false)\n\t                end\n\t            end\n\t\n\t            return unpack(Results)\n\t        end\n\t\n\t        Session:Clean(function()\n\t            bedwars.LaunchPadController.attemptLaunch = Old\n\t        end)\n\t    end,\n\t    hannah = function(Session)\n\t        KitCollection(\"HannahExecuteInteraction\", function(Victim: Instance)\n\t            local Billboard = bedwars.Handler:Get(\"HannahPromptTrigger\"):Fire(\"CallServer\", {\n\t                user = LocalPlayer,\n\t                victimEntity = Victim\n\t            }) and Victim:FindFirstChild(\"Hannah Execution Icon\")\n\t\n\t            if Billboard then\n\t                Billboard:Destroy()\n\t            end\n\t        end, 30, true, Session)\n\t    end,\n\t    jailor = function(Session)\n\t        KitCollection(\"jailor_soul\", function(Soul: Instance)\n\t            bedwars.JailorController:collectEntity(LocalPlayer, Soul, \"JailorSoul\")\n\t        end, 20, false, Session)\n\t    end,\n\t    grim_reaper = function(Session)\n\t        KitCollection(bedwars.GrimReaperController.soulsByPosition, function(Soul: Instance)\n\t            if Entity.isAlive and LocalPlayer.Character:GetAttribute(\"Health\") <= (LocalPlayer.Character:GetAttribute(\"MaxHealth\") / 4) and (not LocalPlayer.Character:GetAttribute(\"GrimReaperChannel\")) then\n\t                bedwars.Handler:Get(\"ConsumeGrimReaperSoul\"):Fire(\"CallServer\", {\n\t                    secret = Soul:GetAttribute(\"GrimReaperSoulSecret\")\n\t                })\n\t            end\n\t        end, 120, false, Session)\n\t    end,\n\t    melody = function()\n\t        local NextHeal: number = 0\n\t        local Played: boolean = false\n\t        repeat\n\t            local Magnitude, Health, Ent = 30, math.huge\n\t            if Entity.isAlive then\n\t                local LocalPosition: Vector3 = Entity.character.RootPart.Position\n\t                for _, v: any in Entity.List do\n\t                    if v.Player and v.Player:GetAttribute(\"Team\") == LocalPlayer:GetAttribute(\"Team\") then\n\t                        local NewMagnitude: number = (LocalPosition - v.RootPart.Position).Magnitude\n\t                        if NewMagnitude <= Magnitude and v.Health < Health and v.Health < v.MaxHealth then\n\t                            Magnitude, Health, Ent = NewMagnitude, v.Health, v\n\t                        end\n\t                    end\n\t                end\n\t            end\n\t\n\t            if Ent and tick() >= NextHeal and GetItem(\"guitar\") then\n\t                NextHeal = tick() + bedwars.MelodyKitBalance.HEAL_COOLDOWN\n\t                Played = true\n\t                bedwars.Handler:Get(\"PlayGuitar\"):Fire(\"SendToServer\", {\n\t                    healTarget = Ent.Character\n\t                })\n\t            end\n\t\n\t            task.wait(0.1)\n\t        until not AutoKit.Enabled\n\t\n\t        if Played then\n\t            bedwars.Handler:Get(\"StopPlayingGuitar\"):Fire(\"SendToServer\")\n\t        end\n\t    end,\n\t    metal_detector = function(Session)\n\t        KitCollection(\"hidden-metal\", function(Metal: Instance)\n\t            bedwars.Handler:Get(\"CollectCollectableEntity\"):Fire(\"SendToServer\", {\n\t                id = Metal:GetAttribute(\"Id\")\n\t            })\n\t        end, 20, false, Session)\n\t    end,\n\t    miner = function(Session)\n\t        KitCollection(\"petrified-player\", function(Petrified: Instance)\n\t            bedwars.Handler:Get(\"DestroyPetrifiedPlayer\"):Fire(\"SendToServer\", {\n\t                petrifyId = Petrified:GetAttribute(\"PetrifyId\")\n\t            })\n\t        end, 6, true, Session)\n\t    end,\n\t    pinata = function(Session)\n\t        KitCollection(`{LocalPlayer.Name}:pinata`, function(Pinata: Instance)\n\t            if GetItem(\"candy\") then\n\t                bedwars.Handler:Get(\"DepositCoins\"):Fire(\"CallServer\", Pinata)\n\t            end\n\t        end, 6, true, Session)\n\t    end,\n\t    spirit_assassin = function(Session)\n\t        KitCollection(\"EvelynnSoul\", function(Spirit: Instance)\n\t            bedwars.SpiritAssassinController:useSpirit(LocalPlayer, Spirit)\n\t        end, 120, true, Session)\n\t    end,\n\t    star_collector = function(Session)\n\t        KitCollection(\"stars\", function(Star: Instance)\n\t            bedwars.StarCollectorController:collectEntity(LocalPlayer, Star, Star.Name)\n\t        end, 20, false, Session)\n\t    end,\n\t    summoner = function()\n\t        repeat\n\t            local Ent = Entity.EntityPosition({\n\t                Range = 31,\n\t                Part = \"RootPart\",\n\t                Players = true,\n\t                Sort = SortMethods.Health\n\t            })\n\t\n\t            if Ent and (not Legit.Enabled or (LocalPlayer.Character:GetAttribute(\"Health\") or 0) > 0) then\n\t                local LocalPosition: Vector3 = Entity.character.RootPart.Position\n\t                local ShootDirection: Vector3 = CFrame.lookAt(LocalPosition, Ent.RootPart.Position).LookVector\n\t                LocalPosition += ShootDirection * math.max((LocalPosition - Ent.RootPart.Position).Magnitude - 16, 0)\n\t\n\t                bedwars.Handler:Get(\"SummonerClawAttackRequest\"):Fire(\"SendToServer\", {\n\t                    position = LocalPosition,\n\t                    direction = ShootDirection,\n\t                    clientTime = workspace:GetServerTimeNow()\n\t                })\n\t            end\n\t\n\t            task.wait(0.1)\n\t        until not AutoKit.Enabled\n\t    end,\n\t    void_dragon = function(Session)\n\t        local OldFlap = bedwars.VoidDragonController.flapWings\n\t        local Flapped: boolean?\n\t\n\t        bedwars.VoidDragonController.flapWings = function(self)\n\t            if not Flapped and bedwars.Handler:Get(\"DragonFlap\"):Fire(\"CallServer\", {player = LocalPlayer}) ~= false then\n\t                local Modifier = bedwars.SprintController:getMovementStatusModifier():addModifier({\n\t                    blockSprint = true,\n\t                    constantSpeedMultiplier = 2\n\t                })\n\t                self.SpeedMaid:GiveTask(Modifier)\n\t                self.SpeedMaid:GiveTask(function()\n\t                    Flapped = false\n\t                end)\n\t                Flapped = true\n\t            end\n\t        end\n\t\n\t        Session:Clean(function()\n\t            bedwars.VoidDragonController.flapWings = OldFlap\n\t        end)\n\t\n\t        repeat\n\t            if bedwars.VoidDragonController.inDragonForm then\n\t                local Ent = Entity.EntityPosition({\n\t                    Range = 30,\n\t                    Part = \"RootPart\",\n\t                    Players = true\n\t                })\n\t\n\t                if Ent then\n\t                    bedwars.Handler:Get(\"DragonBreath\"):Fire(\"SendToServer\", {\n\t                        player = LocalPlayer,\n\t                        targetPoint = Ent.RootPart.Position\n\t                    })\n\t                end\n\t            end\n\t            task.wait(0.1)\n\t        until not AutoKit.Enabled\n\t    end,\n\t    warlock = function()\n\t        local LastTarget\n\t        repeat\n\t            if Store.hand.tool and Store.hand.tool.Name == \"warlock_staff\" then\n\t                local Ent = Entity.EntityPosition({\n\t                    Range = 30,\n\t                    Part = \"RootPart\",\n\t                    Players = true,\n\t                    NPCs = true\n\t                })\n\t\n\t                if Ent and Ent.Character ~= LastTarget then\n\t                    if not bedwars.Handler:Get(\"WarlockLinkTarget\"):Fire(\"CallServer\", {\n\t                        target = Ent.Character\n\t                    }) then\n\t                        Ent = nil\n\t                    end\n\t                end\n\t\n\t                LastTarget = Ent and Ent.Character\n\t            else\n\t                LastTarget = nil\n\t            end\n\t\n\t            task.wait(0.1)\n\t        until not AutoKit.Enabled\n\t    end,\n\t    wizard = function()\n\t        repeat\n\t            local Ability = LocalPlayer:GetAttribute(\"WizardAbility\")\n\t            if Ability and bedwars.AbilityController:canUseAbility(Ability, {disableBlockedAbilityAlert = true}) then\n\t                local Ent = Entity.EntityPosition({\n\t                    Range = 50,\n\t                    Part = \"RootPart\",\n\t                    Players = true,\n\t                    Sort = SortMethods.Health\n\t                })\n\t\n\t                if Ent then\n\t                    bedwars.AbilityController:useAbility(Ability, newproxy(true), {target = Ent.RootPart.Position})\n\t                end\n\t            end\n\t\n\t            task.wait(0.1)\n\t        until not AutoKit.Enabled\n\t    end\n\t}\n\t\n\tlocal function StopKits()\n\t    for Kit: string, Session: any in Running do\n\t        Running[Kit] = nil\n\t        Session:Stop()\n\t    end\n\tend\n\t\n\tlocal function SyncKits()\n\t    local Kits: {string} = Store.equippedKits or {}\n\t    for Kit: string, Session: any in Running do\n\t        if not table.find(Kits, Kit) or not Toggles[Kit].Enabled then\n\t            Running[Kit] = nil\n\t            Session:Stop()\n\t        end\n\t    end\n\t\n\t    for _, v: string in Kits do\n\t        if AutoKitFunctions[v] and Toggles[v].Enabled and not Running[v] then\n\t            local Session = NewSession()\n\t            Running[v] = Session\n\t            Session.Thread = task.spawn(AutoKitFunctions[v], Session)\n\t        end\n\t    end\n\tend\n\t\n\tAutoKit = vape.Categories.Kits:CreateModule({\n\t    Name = \"AutoKit\",\n\t    Function = function(Callback: boolean)\n\t        if Callback then\n\t            AutoKit:Clean(StopKits)\n\t            repeat\n\t                if Store.matchState ~= 0 then\n\t                    SyncKits()\n\t                end\n\t                task.wait(0.5)\n\t            until not AutoKit.Enabled\n\t        end\n\t    end,\n\t    Tooltip = \"Automatically uses kit abilities for every kit you have, including both kits in Kit Fusion.\"\n\t})\n\t\n\tLegit = AutoKit:CreateToggle({Name = \"Legit Range\"})\n\tlocal function KitName(Kit: string): string\n\t    local Meta = bedwars.BedwarsKitMeta[Kit]\n\t    return Meta and Meta.name or Kit\n\tend\n\t\n\tlocal SortTable: {string} = {}\n\tfor Kit: string in AutoKitFunctions do\n\t    table.insert(SortTable, Kit)\n\tend\n\ttable.sort(SortTable, function(A: string, B: string)\n\t    return KitName(A) < KitName(B)\n\tend)\n\tfor _, v: string in SortTable do\n\t    Toggles[v] = AutoKit:CreateToggle({\n\t        Name = KitName(v),\n\t        Default = true\n\t    })\n\tend\nend)\n\nRun(function()\n\tlocal AutoKrystal\n\t\n\tlocal function GetBed(): BasePart?\n\t    local LocalPosition: Vector3 = Entity.isAlive and Entity.character.RootPart.Position or Vector3.zero\n\t    for _, v: BasePart in CollectionService:GetTagged(\"bed\") do\n\t        if (LocalPosition - v.Position).Magnitude <= 22 and not v:GetAttribute(`Team{LocalPlayer:GetAttribute(\"Team\") or -1}NoBreak`) then\n\t            return v\n\t        end\n\t    end\n\t    return\n\tend\n\t\n\tAutoKrystal = vape.Categories.Kits:CreateModule({\n\t    Name = \"AutoKrystal\",\n\t    Function = function(Callback: boolean)\n\t        if Callback then\n\t            repeat\n\t                local Bed = Entity.isAlive and Store.equippedKit == \"glacial_skater\" and bedwars.AbilityController:canUseAbility(\"skating_freeze\", {disableBlockedAbilityAlert = true}) and GetBed()\n\t                if Bed then\n\t                    for _, v: BasePart in Store.blocks do\n\t                        if (Bed.Position - v.Position).Magnitude <= 20 and v:GetAttribute(\"PlacedByUserId\") then\n\t                            bedwars.AbilityController:useAbility(\"skating_freeze\")\n\t                            break\n\t                        end\n\t                    end\n\t                end\n\t                task.wait(0.1)\n\t            until not AutoKrystal.Enabled\n\t        end\n\t    end,\n\t    Tooltip = \"Automatically uses freeze ability when near\\nopponent's bed defense.\"\n\t})\nend)\n\nRun(function()\n\tlocal AutoLani\n\tlocal Delay\n\tlocal UseEnemy\n\tlocal Enemy\n\tlocal Player\n\t\n\tlocal Request = bedwars.Handler:Get(\"PaladinAbilityRequest\")\n\t\n\tAutoLani = vape.Categories.Kits:CreateModule({\n\t    Name = \"AutoLani\",\n\t    Function = function(Callback: boolean)\n\t        if Callback then\n\t            local OldStart\n\t\n\t            repeat\n\t                local Start = LocalPlayer:GetAttribute(\"PaladinStartTime\")\n\t                if OldStart and OldStart ~= Start then\n\t                    local Target = UseEnemy.Enabled and Players:FindFirstChild(Enemy.Value) or not UseEnemy.Enabled and Players:FindFirstChild(Player.Value) or nil\n\t                    if Target then\n\t                        task.delay(Delay.Value, function()\n\t                            Request:Fire(\"SendToServer\", {target = Target})\n\t                        end)\n\t                    end\n\t                end\n\t                OldStart = Start\n\t                task.wait(0.1)\n\t            until not AutoLani.Enabled\n\t        end\n\t    end,\n\t    Tooltip = 'Automatically uses the \"scepter of light\" ability'\n\t})\n\t\n\tlocal Friends, Enemies = {\"None\"}, {\"None\"}\n\t\n\tlocal function AddConnection(TargetPlayer: Player, Connected: boolean?)\n\t    local Friendly: boolean = TargetPlayer:GetAttribute(\"Team\") == LocalPlayer:GetAttribute(\"Team\")\n\t\n\t    if not Connected then\n\t        vape:Clean(TargetPlayer:GetAttributeChangedSignal(\"Team\"):Connect(function()\n\t            AddConnection(TargetPlayer, true)\n\t        end))\n\t    end\n\t\n\t    if Friendly and not table.find(Friends, TargetPlayer.Name) then\n\t        table.insert(Friends, TargetPlayer.Name)\n\t        Player:Change(Friends)\n\t    elseif not Friendly and TargetPlayer.Team and TargetPlayer.Team.Name ~= \"Spectators\" and not table.find(Enemies, TargetPlayer.Name) then\n\t        table.insert(Enemies, TargetPlayer.Name)\n\t        Enemy:Change(Enemies)\n\t    end\n\tend\n\t\n\tPlayer = AutoLani:CreateDropdown({\n\t    Name = \"Selected Player\",\n\t    List = {},\n\t    Tooltip = \"Player to use the ability on\"\n\t})\n\tEnemy = AutoLani:CreateDropdown({\n\t    Name = \"Selected Enemy\",\n\t    List = {},\n\t    Visible = false,\n\t    Tooltip = \"Target to use the ability on\"\n\t})\n\tUseEnemy = AutoLani:CreateToggle({\n\t    Name = \"Use enemy\",\n\t    Function = function(Callback: boolean)\n\t        Enemy.Object.Visible = Callback\n\t        Player.Object.Visible = not Callback\n\t    end,\n\t    Tooltip = \"Uses the ability on other people instead of your teammates\"\n\t})\n\tDelay = AutoLani:CreateSlider({\n\t    Name = \"Delay\",\n\t    Min = 1,\n\t    Max = 20,\n\t    Default = 5,\n\t    Decimal = 10,\n\t    Suffix = function(Val: number)\n\t        return Val <= 1 and \"sec\" or \"secs\"\n\t    end,\n\t    Tooltip = \"Delay between triggers\"\n\t})\n\tfor _, v: Player in Players:GetPlayers() do\n\t    AddConnection(v)\n\tend\n\tvape:Clean(Players.PlayerAdded:Connect(AddConnection))\nend)\n\nRun(function()\n\tlocal AutoLasso\n\tlocal Targets\n\tlocal Range\n\tlocal FireRate\n\tlocal SwitchDelay\n\tlocal NextFire: number = 0\n\tlocal Session = nil\n\t\n\tlocal function ThrowLasso()\n\t    local Item = GetItem(\"lasso\")\n\t    local Source = Item and bedwars.ItemMeta.lasso.projectileSource or nil\n\t    local Target = Source and GetFacingEntity({\n\t        Part = \"RootPart\",\n\t        Range = Range.Value,\n\t        Players = Targets.Players.Enabled,\n\t        NPCs = Targets.NPCs.Enabled,\n\t        Priority = Targets.Priority.Value,\n\t        Wallcheck = Targets.Walls.Enabled,\n\t        Limit = 10\n\t    }) or nil\n\t    if not Target then\n\t        return\n\t    end\n\t\n\t    NextFire = tick() + 0.5\n\t    local Current = Session\n\t    local Previous: Tool? = Store.hand.tool\n\t    local Hotbar: number? = GetHotbar(Item.tool)\n\t    if Hotbar then\n\t        bedwars.Store:dispatch({type = \"InventorySelectHotbarSlot\", slot = Hotbar})\n\t    else\n\t        SwitchItem(Item.tool)\n\t    end\n\t    task.wait(math.max(LocalPlayer:GetNetworkPing() * 2, Store.ping.total or 0, 0.05))\n\t    if AutoLasso.Enabled and Session == Current and Entity.isAlive and Target.RootPart.Parent and Store.hand.tool == Item.tool then\n\t        if FireProjectile(Item, \"lasso\", Source.projectileType(\"lasso\"), Target) then\n\t            NextFire = tick() + Source.fireDelaySec + FireRate:GetRandomValue()\n\t            task.wait(SwitchDelay.Value)\n\t        end\n\t    end\n\t    if Previous and Previous.Parent and Session == Current and (not Store.hand.tool or Store.hand.tool == Item.tool) then\n\t        local PreviousSlot: number? = GetHotbar(Previous)\n\t        if PreviousSlot then bedwars.Store:dispatch({type = \"InventorySelectHotbarSlot\", slot = PreviousSlot}) else SwitchItem(Previous) end\n\t    end\n\tend\n\t\n\tAutoLasso = vape.Categories.Kits:CreateModule({\n\t    Name = \"AutoLasso\",\n\t    Function = function(Callback: boolean)\n\t        if Callback then\n\t            local Current = {}\n\t            Session = Current\n\t            NextFire = 0\n\t\n\t            repeat\n\t                local Meleeing: boolean = (tick() - bedwars.SwordController.lastSwing) < 0.3 or Store.attacking or (workspace:GetServerTimeNow() - bedwars.SwordController.lastAttack) < 0.3\n\t                if Entity.isAlive and (Store.equippedKit == \"cowgirl\" or table.find(Store.equippedKits or {}, \"cowgirl\")) and (Store.hand.toolType == \"sword\" or Store.hand.tool and Store.hand.tool.Name == \"lasso\") and Meleeing and tick() >= NextFire then\n\t                    ThrowLasso()\n\t                end\n\t                task.wait(0.1)\n\t            until not AutoLasso.Enabled or Session ~= Current\n\t        end\n\t    end,\n\t    Tooltip = \"Automatically throws Lassy's lasso at whoever you're meleeing\"\n\t})\n\t\n\tTargets = AutoLasso:CreateTargets({\n\t    Players = true,\n\t    NPCs = false\n\t})\n\tRange = AutoLasso:CreateSlider({\n\t    Name = \"Range\",\n\t    Min = 1,\n\t    Max = 60,\n\t    Default = 22,\n\t    Suffix = function(Val: number)\n\t        return Val <= 1 and \"stud\" or \"studs\"\n\t    end\n\t})\n\tFireRate = AutoLasso:CreateTwoSlider({\n\t    Name = \"Fire Rate\",\n\t    Min = 0,\n\t    Max = 1,\n\t    DefaultMin = 0.05,\n\t    DefaultMax = 0.12,\n\t    Decimal = 100\n\t})\n\tSwitchDelay = AutoLasso:CreateSlider({\n\t    Name = \"Switch Delay\",\n\t    Min = 0,\n\t    Max = 1,\n\t    Decimal = 100,\n\t    Suffix = \"seconds\",\n\t    Default = 0.02\n\t})\nend)\n\nRun(function()\n\tlocal AutoLumen\n\tlocal Targets\n\tlocal Range\n\tlocal FullCharge\n\tlocal Delay\n\t\n\tlocal Balance = bedwars.LumenBalance or {MIN_CHARGE_TIME = 0.65, MAX_CHARGE_TIME = 1.25}\n\tlocal Sword: string = \"light_sword\"\n\tlocal Cooldown: number = 0\n\t\n\tlocal function ChargedSwing()\n\t    local ChargeController = bedwars.SwordChargeController\n\t    if ChargeController:getChargeState() ~= bedwars.ChargeState.Idle then\n\t        return\n\t    end\n\t\n\t    ChargeController:startCharging(Sword)\n\t    local Started: number = ChargeController:getChargeStartTime()\n\t    if Started == 0 then\n\t        return\n\t    end\n\t\n\t    local ItemMeta = bedwars.ItemMeta[Sword]\n\t    local Charged = ItemMeta and ItemMeta.sword and ItemMeta.sword.chargedAttack\n\t    local TargetTime: number = (FullCharge.Enabled and (Charged and Charged.maxChargeTimeSec or Balance.MAX_CHARGE_TIME) or (Charged and Charged.minChargeTimeSec or Balance.MIN_CHARGE_TIME)) + 0.05\n\t    repeat\n\t        task.wait()\n\t    until not AutoLumen.Enabled or not Entity.isAlive or (tick() - Started) >= TargetTime\n\t\n\t    local ChargeTime: number = tick() - Started\n\t    ChargeController:stopCharging(Sword)\n\t    if not AutoLumen.Enabled or not Entity.isAlive then\n\t        return\n\t    end\n\t\n\t    local Tool = Store.hand.tool\n\t    if not Tool or Tool.Name ~= Sword then\n\t        return\n\t    end\n\t\n\t    local Charged = bedwars.ItemMeta[Sword].sword.chargedAttack\n\t    if not (Charged.skipSwingDamage and ChargeTime > (Charged.minChargeTimeSec or Balance.MIN_CHARGE_TIME)) then\n\t        bedwars.SwordController:swingSwordAtMouse(ChargeTime)\n\t    end\n\t\n\t    bedwars.SyncEvents.SwordChargedSwing:fire(LocalPlayer, Tool, {chargeTime = ChargeTime})\n\t    Cooldown = tick() + Delay.Value\n\tend\n\t\n\tAutoLumen = vape.Categories.Kits:CreateModule({\n\t    Name = \"AutoLumen\",\n\t    Function = function(Callback: boolean)\n\t        if Callback then\n\t            Cooldown = 0\n\t\n\t            repeat\n\t                if Entity.isAlive and Store.equippedKit == \"lumen\" and Store.hand.tool and Store.hand.tool.Name == Sword and tick() >= Cooldown then\n\t                    local Target = Entity.EntityMouse({\n\t                        Origin = Entity.character.RootPart.Position,\n\t                        Range = Range.Value,\n\t                        Part = \"RootPart\",\n\t                        Players = Targets.Players.Enabled,\n\t                        NPCs = Targets.NPCs.Enabled,\n\t                        Priority = Targets.Priority.Value,\n\t                        Wallcheck = Targets.Walls.Enabled\n\t                    })\n\t\n\t                    if Target then\n\t                        ChargedSwing()\n\t                    end\n\t                end\n\t                task.wait(0.1)\n\t            until not AutoLumen.Enabled\n\t        end\n\t    end,\n\t    Tooltip = \"Charges the sword of light and releases a wave whenever an enemy is in front of you, Killaura skips this sword because it has a charged attack\"\n\t})\n\t\n\tTargets = AutoLumen:CreateTargets({\n\t    Players = true,\n\t    Walls = true\n\t})\n\tRange = AutoLumen:CreateSlider({\n\t    Name = \"Range\",\n\t    Min = 1,\n\t    Max = 120,\n\t    Default = 60,\n\t    Suffix = function(Val: number)\n\t        return Val <= 1 and \"stud\" or \"studs\"\n\t    end\n\t})\n\tFullCharge = AutoLumen:CreateToggle({\n\t    Name = \"Full charge\",\n\t    Default = true,\n\t    Tooltip = \"Holds the swing to the maximum charge, an upgraded lumen only fires the multi beam at full charge\"\n\t})\n\tDelay = AutoLumen:CreateSlider({\n\t    Name = \"Delay\",\n\t    Min = 0,\n\t    Max = 2,\n\t    Default = 0.1,\n\t    Decimal = 100,\n\t    Suffix = \"seconds\"\n\t})\nend)\n\nRun(function()\n\tlocal AutoMarina\n\tlocal Range\n\t\n\tAutoMarina = vape.Categories.Kits:CreateModule({\n\t    Name = \"AutoMarina\",\n\t    Function = function(Callback: boolean)\n\t        if Callback then\n\t            local Jellies: {Model} = Collection(\"jellyfish\", AutoMarina, function(List: {Model}, Jelly: Model)\n\t                task.delay(0, function()\n\t                    if Jelly:GetAttribute(\"PlacedByUserId\") == LocalPlayer.UserId then\n\t                        table.insert(List, Jelly)\n\t                    end\n\t                end)\n\t            end)\n\t\n\t            repeat\n\t                if Entity.isAlive and bedwars.AbilityController:canUseAbility(\"electrify_jellyfish\", {disableBlockedAbilityAlert = true}) then\n\t                    for _, v: Model in Jellies do\n\t                        if v.PrimaryPart and Entity.EntityPosition({\n\t                            Origin = v.PrimaryPart.Position,\n\t                            Range = Range.Value,\n\t                            Part = \"RootPart\",\n\t                            Players = true\n\t                        }) then\n\t                            bedwars.AbilityController:useAbility(\"electrify_jellyfish\")\n\t                            break\n\t                        end\n\t                    end\n\t                end\n\t                task.wait(0.1)\n\t            until not AutoMarina.Enabled\n\t        end\n\t    end,\n\t    Tooltip = 'Automatically uses \"electrify\" ability when enemies are near jellies.'\n\t})\n\t\n\tRange = AutoMarina:CreateSlider({\n\t    Name = \"Range\",\n\t    Min = 1,\n\t    Max = 65,\n\t    Default = 50,\n\t    Suffix = function(Val: number)\n\t        return Val <= 1 and \"stud\" or \"studs\"\n\t    end\n\t})\nend)\n\nRun(function()\n\tlocal AutoMarrow\n\tlocal Mode\n\tlocal Targets\n\tlocal Range\n\tlocal Health\n\t\n\tAutoMarrow = vape.Categories.Kits:CreateModule({\n\t    Name = \"AutoMarrow\",\n\t    Function = function(Callback: boolean)\n\t        if Callback then\n\t            repeat\n\t                if Entity.isAlive and Store.equippedKit == \"skeleton\" and bedwars.AbilityController:canUseAbility(\"skeleton_ability\", {disableBlockedAbilityAlert = true}) then\n\t                    local Humanoid: Humanoid = Entity.character.Humanoid\n\t                    local Low: boolean = Humanoid.Health <= (Humanoid.MaxHealth * (Health.Value / 100))\n\t                    local Near: boolean = #Entity.AllPosition({\n\t                        Range = Range.Value,\n\t                        Part = \"RootPart\",\n\t                        Players = Targets.Players.Enabled,\n\t                        NPCs = Targets.NPCs.Enabled,\n\t                        Wallcheck = Targets.Walls.Enabled\n\t                    }) > 0\n\t\n\t                    if (Mode.Value == \"Low Health\" and Low) or (Mode.Value == \"Enemy Near\" and Near) or (Mode.Value == \"Both\" and (Low or Near)) then\n\t                        bedwars.AbilityController:useAbility(\"skeleton_ability\")\n\t                    end\n\t                end\n\t                task.wait(0.1)\n\t            until not AutoMarrow.Enabled\n\t        end\n\t    end,\n\t    Tooltip = \"Automatically drops Toxic Escape clouds when you are in trouble\"\n\t})\n\t\n\tMode = AutoMarrow:CreateDropdown({\n\t    Name = \"Mode\",\n\t    List = {\"Both\", \"Low Health\", \"Enemy Near\"},\n\t    Default = \"Both\"\n\t})\n\tTargets = AutoMarrow:CreateTargets({\n\t    Players = true,\n\t    NPCs = true\n\t})\n\tRange = AutoMarrow:CreateSlider({\n\t    Name = \"Range\",\n\t    Min = 1,\n\t    Max = 40,\n\t    Default = 12,\n\t    Suffix = function(Val: number)\n\t        return Val <= 1 and \"stud\" or \"studs\"\n\t    end\n\t})\n\tHealth = AutoMarrow:CreateSlider({\n\t    Name = \"Health\",\n\t    Min = 1,\n\t    Max = 100,\n\t    Default = 45,\n\t    Suffix = \"%\",\n\t    Tooltip = \"Drops the clouds once you fall under this\"\n\t})\nend)\n\nRun(function()\n\tlocal AutoMartin\n\tlocal Targets\n\tlocal Range\n\tlocal Delay\n\t\n\tlocal Cooldown: number = 0\n\t\n\tAutoMartin = vape.Categories.Kits:CreateModule({\n\t    Name = \"AutoMartin\",\n\t    Function = function(Callback: boolean)\n\t        if Callback then\n\t            Cooldown = 0\n\t\n\t            repeat\n\t                if tick() >= Cooldown and Entity.EntityPosition({\n\t                    Range = Range.Value,\n\t                    Part = \"RootPart\",\n\t                    Wallcheck = Targets.Walls.Enabled,\n\t                    Players = Targets.Players.Enabled,\n\t                    NPCs = Targets.NPCs.Enabled,\n\t                    Priority = Targets.Priority.Value,\n\t                    Sort = SortMethods.Distance\n\t                }) and bedwars.AbilityController:canUseAbility(\"cactus_fire\", {disableBlockedAbilityAlert = true}) then\n\t                    Cooldown = tick() + Delay.Value\n\t                    bedwars.AbilityController:useAbility(\"cactus_fire\")\n\t                end\n\t                task.wait(0.1)\n\t            until not AutoMartin.Enabled\n\t        end\n\t    end,\n\t    Tooltip = 'Automatically uses \"Wild growth\" ability when within range.'\n\t})\n\t\n\tTargets = AutoMartin:CreateTargets({\n\t    Players = true,\n\t    Walls = true\n\t})\n\tRange = AutoMartin:CreateSlider({\n\t    Name = \"Range\",\n\t    Min = 1,\n\t    Max = 22,\n\t    Default = 22,\n\t    Suffix = function(Val: number)\n\t        return Val == 1 and \"stud\" or \"studs\"\n\t    end\n\t})\n\tDelay = AutoMartin:CreateSlider({\n\t    Name = \"Delay\",\n\t    Min = 0,\n\t    Max = 2,\n\t    Default = 0,\n\t    Decimal = 100,\n\t    Suffix = \"seconds\"\n\t})\nend)\n\nRun(function()\n\tlocal AutoMelody\n\tlocal Range\n\tlocal SelfHeal\n\tlocal TeammateHeal\n\tlocal UseHotbar\n\tlocal SwitchBack\n\tlocal NextHeal: number = 0\n\t\n\tAutoMelody = vape.Categories.Kits:CreateModule({\n\t    Name = \"AutoMelody\",\n\t    Function = function(Callback: boolean)\n\t        if Callback then\n\t            NextHeal = 0\n\t\n\t            repeat\n\t                local Health, Target = math.huge, nil\n\t                if Entity.isAlive and tick() >= NextHeal then\n\t                    local LocalPosition: Vector3 = Entity.character.RootPart.Position\n\t\n\t                    if SelfHeal.Enabled and Entity.character.Health < Entity.character.MaxHealth then\n\t                        Health, Target = Entity.character.Health, Entity.character\n\t                    end\n\t\n\t                    if TeammateHeal.Enabled then\n\t                        for _, v: any in Entity.List do\n\t                            if v.Player and v.Player:GetAttribute(\"Team\") == LocalPlayer:GetAttribute(\"Team\") and v.Health > 0 and v.Health < v.MaxHealth and v.Health < Health and (LocalPosition - v.RootPart.Position).Magnitude <= Range.Value then\n\t                                Health, Target = v.Health, v\n\t                            end\n\t                        end\n\t                    end\n\t                end\n\t\n\t                local Guitar = Target and GetItem(\"guitar\")\n\t                if Guitar then\n\t                    local PreviousSlot, PreviousTool = Store.inventory.hotbarSlot, Store.hand.tool\n\t\n\t                    if UseHotbar.Enabled then\n\t                        local Slot = GetHotbar(Guitar.tool)\n\t                        if Slot then\n\t                            HotbarSwitch(Slot)\n\t                        end\n\t                    end\n\t\n\t                    NextHeal = tick() + bedwars.MelodyKitBalance.HEAL_COOLDOWN\n\t                    bedwars.Handler:Get(\"PlayGuitar\"):Fire(\"SendToServer\", {\n\t                        healTarget = Target.Character\n\t                    })\n\t\n\t                    if UseHotbar.Enabled and SwitchBack.Enabled then\n\t                        if PreviousSlot and PreviousSlot ~= Store.inventory.hotbarSlot then\n\t                            HotbarSwitch(PreviousSlot)\n\t                        elseif PreviousTool then\n\t                            SwitchItem(PreviousTool)\n\t                        end\n\t                    end\n\t                end\n\t                task.wait(0.1)\n\t            until not AutoMelody.Enabled\n\t            bedwars.Handler:Get(\"StopPlayingGuitar\"):Fire(\"SendToServer\")\n\t        end\n\t    end,\n\t    Tooltip = \"Automatically uses the guitar to heal ur teammates/urself\"\n\t})\n\t\n\tSelfHeal = AutoMelody:CreateToggle({\n\t    Name = \"Self Heal\",\n\t    Default = true\n\t})\n\tTeammateHeal = AutoMelody:CreateToggle({\n\t    Name = \"Teammate Heal\",\n\t    Default = true\n\t})\n\tRange = AutoMelody:CreateSlider({\n\t    Name = \"Range\",\n\t    Min = 1,\n\t    Max = 51,\n\t    Default = 51,\n\t    Suffix = function(Val: number)\n\t        return Val <= 1 and \"stud\" or \"studs\"\n\t    end,\n\t    Tooltip = \"The guitar reaches 51 studs, which is what this defaults to\"\n\t})\n\tUseHotbar = AutoMelody:CreateToggle({\n\t    Name = \"Use hotbar\",\n\t    Function = function(Callback: boolean)\n\t        if SwitchBack then\n\t            SwitchBack.Object.Visible = Callback\n\t        end\n\t    end,\n\t    Tooltip = \"Visibly swaps onto the guitar slot before healing instead of playing it silently\"\n\t})\n\tSwitchBack = AutoMelody:CreateToggle({\n\t    Name = \"Switch back\",\n\t    Default = true,\n\t    Darker = true,\n\t    Visible = false,\n\t    Tooltip = \"Returns to whatever you were holding after the heal\"\n\t})\nend)\n\nRun(function()\n\tlocal AutoMetal\n\tlocal Limit\n\tlocal StreamerMode\n\tlocal Duration\n\tlocal Range\n\tlocal Animation\n\t\n\tlocal Legit: number = GetFunctionRange(bedwars.HiddenMetalController.onKitLocalActivated) or 0\n\tlocal Cooldowns: {[Instance]: number} = {}\n\t\n\tAutoMetal = vape.Categories.Kits:CreateModule({\n\t    Name = \"AutoMetal\",\n\t    Function = function(Callback: boolean)\n\t        if Callback then\n\t            AutoMetal:Clean(ProximityPromptService.PromptShown:Connect(function(Prompt: ProximityPrompt)\n\t                if StreamerMode.Enabled and Prompt.Name == \"hidden-metal-prompt\" and (not Limit.Enabled or Store.hand.tool and Store.hand.tool.Name == \"metal_detector\") then\n\t                    task.wait(0.1)\n\t                    Prompt:InputHoldBegin()\n\t                end\n\t            end))\n\t\n\t            repeat\n\t                if not StreamerMode.Enabled and Entity.isAlive then\n\t                    local LocalPosition: Vector3 = Entity.character.RootPart.Position\n\t                    for _, v: Instance in CollectionService:GetTagged(\"hidden-metal\") do\n\t                        if tick() > (Cooldowns[v] or 0) and (LocalPosition - v.Part.Position).Magnitude <= Range.Value and (not Limit.Enabled or Store.hand.tool and Store.hand.tool.Name == \"metal_detector\") then\n\t                            if Duration.Value > 0 then\n\t                                task.wait(Duration.Value)\n\t                            end\n\t\n\t                            if (LocalPosition - v.Part.Position).Magnitude <= Range.Value then\n\t                                if Animation.Enabled then\n\t                                    bedwars.GameAnimationUtil:playAnimation(LocalPlayer.Character, bedwars.AnimationType.SHOVEL_DIG)\n\t                                    bedwars.AudioManager:playAudio(bedwars.SoundList.SNAP_TRAP_CONSUME_MARK)\n\t                                end\n\t\n\t                                bedwars.Handler:Get(\"CollectCollectableEntity\"):Fire(\"SendToServer\", {\n\t                                    id = v:GetAttribute(\"Id\")\n\t                                })\n\t                                Cooldowns[v] = tick() + 1\n\t                            end\n\t                        end\n\t                    end\n\t                end\n\t                task.wait(0.1)\n\t            until not AutoMetal.Enabled\n\t        else\n\t            table.clear(Cooldowns)\n\t        end\n\t    end,\n\t    Tooltip = \"Automatically uses the metal kit\"\n\t})\n\t\n\tLimit = AutoMetal:CreateToggle({Name = \"Limit to item\"})\n\t\n\tStreamerMode = AutoMetal:CreateToggle({\n\t    Name = \"Streamer mode\",\n\t    Function = function(Callback: boolean)\n\t        if Duration then\n\t            Duration.Object.Visible = not Callback\n\t            Range.Object.Visible = not Callback\n\t            Animation.Object.Visible = not Callback\n\t        end\n\t    end,\n\t    Tooltip = \"Actually does the metal prompt thing for you\"\n\t})\n\tAnimation = AutoMetal:CreateToggle({\n\t    Name = \"Animation\",\n\t    Default = true,\n\t    Tooltip = \"Plays the metal collect animation\"\n\t})\n\tRange = AutoMetal:CreateSlider({\n\t    Name = \"Range\",\n\t    Min = 1,\n\t    Max = 20,\n\t    Default = Legit,\n\t    Suffix = function(Val: number)\n\t        return Val > 1 and \"studs\" or \"stud\"\n\t    end\n\t})\n\tAutoMetal:CreateButton({\n\t    Name = \"Sync to legit range\",\n\t    Function = function()\n\t        Range:SetValue(Legit)\n\t    end\n\t})\n\tDuration = AutoMetal:CreateSlider({\n\t    Name = \"Delay\",\n\t    Min = 0,\n\t    Max = 1,\n\t    Default = 0.2,\n\t    Decimal = 5,\n\t    Suffix = function(Val: number)\n\t        return Val > 1 and \"secs\" or \"sec\"\n\t    end\n\t})\nend)\n\nRun(function()\n\tlocal AutoMushroom\n\tlocal Ingredient\n\tlocal Delay\n\tlocal NextAdd: number = 0\n\t\n\tlocal Ingredients: {[string]: string} = {\n\t    Mushrooms = \"alchemist_add_mushrooms\",\n\t    Flowers = \"alchemist_add_flower\",\n\t    Thorns = \"alchemist_add_thorns\"\n\t}\n\t\n\tAutoMushroom = vape.Categories.Kits:CreateModule({\n\t    Name = \"AutoMushroom\",\n\t    Function = function(Callback: boolean)\n\t        if Callback then\n\t            NextAdd = 0\n\t\n\t            repeat\n\t                local Ability: string = Ingredients[Ingredient.Value]\n\t                if Entity.isAlive and Store.equippedKit == \"alchemist\" and tick() >= NextAdd and bedwars.AbilityController:canUseAbility(Ability, {disableBlockedAbilityAlert = true}) then\n\t                    NextAdd = tick() + Delay.Value\n\t                    bedwars.AbilityController:useAbility(Ability)\n\t                end\n\t                task.wait(0.1)\n\t            until not AutoMushroom.Enabled\n\t        end\n\t    end,\n\t    Tooltip = \"Automatically tops the alchemist flask up with an ingredient\"\n\t})\n\t\n\tIngredient = AutoMushroom:CreateDropdown({\n\t    Name = \"Ingredient\",\n\t    List = {\"Mushrooms\", \"Flowers\", \"Thorns\"}\n\t})\n\tDelay = AutoMushroom:CreateSlider({\n\t    Name = \"Delay\",\n\t    Min = 0.1,\n\t    Max = 5,\n\t    Default = 0.5,\n\t    Decimal = 10,\n\t    Suffix = function(Val: number)\n\t        return Val <= 1 and \"sec\" or \"secs\"\n\t    end\n\t})\nend)\n\nRun(function()\n\tlocal AutoNahila\n\tlocal Health\n\tlocal Range\n\tlocal Allies\n\t\n\tAutoNahila = vape.Categories.Kits:CreateModule({\n\t    Name = \"AutoNahila\",\n\t    Function = function(Callback: boolean)\n\t        if Callback then\n\t            repeat\n\t                if Entity.isAlive and Store.equippedKit == \"oasis\" and bedwars.AbilityController:canUseAbility(\"oasis_heal_veil\", {disableBlockedAbilityAlert = true}) then\n\t                    local Character = Entity.character\n\t                    local Hurt: boolean = (Character.Health / Character.MaxHealth) <= (Health.Value / 100)\n\t                    if not Hurt and Allies.Enabled then\n\t                        local Origin: Vector3 = Character.RootPart.Position\n\t                        for _, v: any in Entity.List do\n\t                            if not v.Targetable and v.Player and v ~= Character and (v.RootPart.Position - Origin).Magnitude <= Range.Value and (v.Health / v.MaxHealth) <= (Health.Value / 100) then\n\t                                Hurt = true\n\t                                break\n\t                            end\n\t                        end\n\t                    end\n\t\n\t                    if Hurt then\n\t                        bedwars.AbilityController:useAbility(\"oasis_heal_veil\")\n\t                    end\n\t                end\n\t                task.wait(0.1)\n\t            until not AutoNahila.Enabled\n\t        end\n\t    end,\n\t    Tooltip = \"Automatically drops the heal veil when you or a teammate is hurt\"\n\t})\n\t\n\tHealth = AutoNahila:CreateSlider({\n\t    Name = \"Health\",\n\t    Min = 1,\n\t    Max = 100,\n\t    Default = 60,\n\t    Suffix = function()\n\t        return \"%\"\n\t    end,\n\t    Tooltip = \"Heals at or below this much health\"\n\t})\n\tAllies = AutoNahila:CreateToggle({\n\t    Name = \"Heal teammates\",\n\t    Default = true\n\t})\n\tRange = AutoNahila:CreateSlider({\n\t    Name = \"Ally range\",\n\t    Min = 1,\n\t    Max = 60,\n\t    Default = 25,\n\t    Suffix = function(Val: number)\n\t        return Val <= 1 and \"stud\" or \"studs\"\n\t    end\n\t})\nend)\n\nRun(function()\n\tlocal AutoNazar\n\tlocal Consume\n\tlocal Health\n\tlocal Force\n\tlocal Empower\n\tlocal Range\n\tlocal Empowered: boolean = false\n\t\n\tAutoNazar = vape.Categories.Kits:CreateModule({\n\t    Name = \"AutoNazar\",\n\t    Function = function(Callback: boolean)\n\t        if Callback then\n\t            Empowered = false\n\t            AutoNazar:Clean(LocalPlayer.CharacterAdded:Connect(function()\n\t                Empowered = false\n\t            end))\n\t\n\t            repeat\n\t                if Entity.isAlive and Store.equippedKit == \"nazar\" then\n\t                    local Character = Entity.character\n\t                    local LifeForce: number = LocalPlayer:GetAttribute(\"LifeForce\") or 0\n\t                    if Consume.Enabled and LifeForce >= Force.Value and (Character.Health / Character.MaxHealth) <= (Health.Value / 100) and bedwars.AbilityController:canUseAbility(\"consume_life_foce\", {disableBlockedAbilityAlert = true}) then\n\t                        bedwars.AbilityController:useAbility(\"consume_life_foce\")\n\t                    end\n\t\n\t                    if Empower.Enabled then\n\t                        local Wanted: boolean = Entity.EntityPosition({\n\t                            Origin = Character.RootPart.Position,\n\t                            Range = Range.Value,\n\t                            Part = \"RootPart\",\n\t                            Players = true\n\t                        }) and true or false\n\t                        if Wanted ~= Empowered then\n\t                            local Ability: string = Wanted and \"enable_life_force_attack\" or \"disable_life_force_attack\"\n\t                            if bedwars.AbilityController:canUseAbility(Ability, {disableBlockedAbilityAlert = true}) then\n\t                                bedwars.AbilityController:useAbility(Ability)\n\t                                Empowered = Wanted\n\t                            end\n\t                        end\n\t                    end\n\t                end\n\t                task.wait(0.1)\n\t            until not AutoNazar.Enabled\n\t        end\n\t    end,\n\t    Tooltip = \"Automatically spends life force to heal and empowers attacks near enemies\"\n\t})\n\t\n\tHealth = AutoNazar:CreateSlider({\n\t    Name = \"Health\",\n\t    Min = 1,\n\t    Max = 100,\n\t    Default = 70,\n\t    Suffix = function()\n\t        return \"%\"\n\t    end,\n\t    Tooltip = \"Consumes once your health drops below this\"\n\t})\n\tForce = AutoNazar:CreateSlider({\n\t    Name = \"Life force\",\n\t    Min = 1,\n\t    Max = 150,\n\t    Default = 35,\n\t    Tooltip = \"Life force you need stored before consuming\"\n\t})\n\tRange = AutoNazar:CreateSlider({\n\t    Name = \"Range\",\n\t    Min = 1,\n\t    Max = 60,\n\t    Default = 25,\n\t    Suffix = function(Val: number)\n\t        return Val <= 1 and \"stud\" or \"studs\"\n\t    end\n\t})\n\tConsume = AutoNazar:CreateToggle({\n\t    Name = \"Consume life force\",\n\t    Function = function(Callback: boolean)\n\t        Health.Object.Visible = Callback\n\t        Force.Object.Visible = Callback\n\t    end,\n\t    Tooltip = \"Converts stored life force into health when hurt\",\n\t    Default = true\n\t})\n\tEmpower = AutoNazar:CreateToggle({\n\t    Name = \"Empower attacks\",\n\t    Function = function(Callback: boolean)\n\t        Range.Object.Visible = Callback\n\t    end,\n\t    Tooltip = \"Enables empowered attacks while an enemy is close and disables them after\",\n\t    Default = true\n\t})\nend)\n\nRun(function()\n\tlocal AutoNoelle\n\tlocal Notify\n\tlocal FrostySlime\n\tlocal HealSlime\n\tlocal StickySlime\n\tlocal VoidSlime\n\tlocal Limit\n\t\n\tlocal function GetSlimes()\n\t    local Slimes = {}\n\t    local Folder: Instance? = workspace:FindFirstChild(\"SlimeModelFolder\")\n\t    for _, v: Instance in Folder and Folder:GetChildren() or {} do\n\t        local Data = v:FindFirstChild(\"SlimeData\")\n\t        Data = Data and Data.Value\n\t\n\t        if Data and Data.Tamer.Value == LocalPlayer.UserId then\n\t            table.insert(Slimes, {\n\t                Data = Data,\n\t                RootPart = v,\n\t                Name = v.Name:gsub(`_{LocalPlayer.Name}`, \"\"):gsub(\"Slime\", \" Slime\")\n\t            })\n\t        end\n\t    end\n\t    return Slimes\n\tend\n\t\n\tlocal function GetPlayer(Name: string)\n\t    for _, v: Player in Players:GetPlayers() do\n\t        if `{v.DisplayName} ({v.Name})` == Name then\n\t            return v\n\t        end\n\t    end\n\t    return\n\tend\n\t\n\tAutoNoelle = vape.Categories.Kits:CreateModule({\n\t    Name = \"AutoNoelle\",\n\t    Function = function(Callback: boolean)\n\t        if Callback then\n\t            repeat\n\t                if Entity.isAlive and (not Limit.Enabled or Store.hand.tool and Store.hand.tool.Name == \"slime_tamer_flute\") then\n\t                    for _, v: any in GetSlimes() do\n\t                        local Dropdown = AutoNoelle.Options[`{v.Name} Target`]\n\t                        local TargetPlayer: Player? = Dropdown and GetPlayer(Dropdown.Value)\n\t                        if TargetPlayer and v.Data.Following.Value ~= TargetPlayer.UserId then\n\t                            bedwars.Handler:Get(\"RequestMoveSlime\"):Fire(\"CallServerAsync\", {\n\t                                slimeId = v.Data:GetAttribute(\"Id\"),\n\t                                targetPlayerUserId = TargetPlayer.UserId\n\t                            }):andThen(function(Success: boolean)\n\t                                if Success then\n\t                                    v.Data.Following.Value = TargetPlayer.UserId\n\t\n\t                                    if Notify.Enabled then\n\t                                        SendNotification(\"AutoNoelle\", `Directed {v.Name} to {TargetPlayer.DisplayName} ({TargetPlayer.Name})`, 5, \"info\")\n\t                                    end\n\t                                end\n\t                            end)\n\t                        end\n\t                    end\n\t                end\n\t                task.wait(0.5)\n\t            until not AutoNoelle.Enabled\n\t        end\n\t    end,\n\t    Tooltip = \"Automatically directs the slimes to the selected player's\"\n\t})\n\t\n\tlocal Friends: {string} = {\"None\"}\n\t\n\tlocal function AddConnection(TargetPlayer: Player, Connected: boolean?)\n\t    if not Connected then\n\t        vape:Clean(TargetPlayer:GetAttributeChangedSignal(\"Team\"):Connect(function()\n\t            AddConnection(TargetPlayer, true)\n\t        end))\n\t    end\n\t\n\t    local Name: string = `{TargetPlayer.DisplayName} ({TargetPlayer.Name})`\n\t    if TargetPlayer:GetAttribute(\"Team\") == LocalPlayer:GetAttribute(\"Team\") and not table.find(Friends, Name) then\n\t        table.insert(Friends, Name)\n\t        FrostySlime:Change(Friends)\n\t        HealSlime:Change(Friends)\n\t        StickySlime:Change(Friends)\n\t        VoidSlime:Change(Friends)\n\t    end\n\tend\n\t\n\tNotify = AutoNoelle:CreateToggle({Name = \"Notify on direct\"})\n\t\n\tLimit = AutoNoelle:CreateToggle({Name = \"Limit to item\"})\n\t\n\tFrostySlime = AutoNoelle:CreateDropdown({\n\t    Name = \"Frosty Slime Target\",\n\t    List = {},\n\t    Tooltip = \"Player to direct frost slimes to\"\n\t})\n\tHealSlime = AutoNoelle:CreateDropdown({\n\t    Name = \"Heal Slime Target\",\n\t    List = {},\n\t    Tooltip = \"Player to direct heal slimes to\"\n\t})\n\tStickySlime = 