t    Function = function(Callback: boolean)\n\t        if Callback then\n\t            Aura = \"\"\n\t            AutoSilas:Clean(bedwars.Handler:Get(\"UpdateRebellionAura\").Remote:Connect(function(Data)\n\t                if Data.player == LocalPlayer then\n\t                    Aura = Data.newAura\n\t                end\n\t            end))\n\t\n\t            repeat\n\t                if Entity.isAlive and Store.equippedKit == \"rebellion_leader\" then\n\t                    local Origin: Vector3 = Entity.character.RootPart.Position\n\t                    local Enemy = Entity.EntityPosition({\n\t                        Origin = Origin,\n\t                        Range = Range.Value,\n\t                        Part = \"RootPart\",\n\t                        Players = true\n\t                    })\n\t\n\t                    if PressAttack.Enabled and Enemy and bedwars.AbilityController:canUseAbility(\"rebellion_shield\", {disableBlockedAbilityAlert = true}) then\n\t                        bedwars.AbilityController:useAbility(\"rebellion_shield\")\n\t                    end\n\t\n\t                    if SwapAura.Enabled then\n\t                        local Wanted: string? = Enemy and \"damage\" or GetHurtAlly(Origin) and \"healing\" or nil\n\t                        if Wanted and Aura ~= \"\" and Aura ~= Wanted and bedwars.AbilityController:canUseAbility(\"rebellion_aura_swap\", {disableBlockedAbilityAlert = true}) then\n\t                            bedwars.AbilityController:useAbility(\"rebellion_aura_swap\")\n\t                        end\n\t                    end\n\t                end\n\t                task.wait(0.1)\n\t            until not AutoSilas.Enabled\n\t        end\n\t    end,\n\t    Tooltip = \"Automatically swaps your aura and rallies your team\"\n\t})\n\t\n\tRange = AutoSilas:CreateSlider({\n\t    Name = \"Range\",\n\t    Min = 1,\n\t    Max = 60,\n\t    Default = 30,\n\t    Suffix = function(Val: number)\n\t        return Val <= 1 and \"stud\" or \"studs\"\n\t    end\n\t})\n\tSwapAura = AutoSilas:CreateToggle({\n\t    Name = \"Swap aura\",\n\t    Default = true,\n\t    Tooltip = \"Uses the damage aura near enemies and the healing aura near hurt allies\"\n\t})\n\tPressAttack = AutoSilas:CreateToggle({\n\t    Name = \"Press the attack\",\n\t    Default = true,\n\t    Tooltip = \"Uses the shield ability when an enemy gets close\"\n\t})\nend)\n\nRun(function()\n\tlocal AutoSkoll\n\tlocal Targets\n\tlocal Sort\n\tlocal Range\n\tlocal Aim\n\tlocal Detonate\n\tlocal DetonateMode = {}\n\tlocal Health = {}\n\tlocal Marked: {[Instance]: number} = {}\n\t\n\tlocal Old\n\t\n\tlocal function GetTarget()\n\t    return Entity.EntityPosition({\n\t        Range = Range.Value,\n\t        Part = \"RootPart\",\n\t        Players = Targets.Players.Enabled,\n\t        NPCs = Targets.NPCs.Enabled,\n\t        Priority = Targets.Priority.Value,\n\t        Wallcheck = Targets.Walls.Enabled or nil,\n\t        Sort = sortmethods[Sort.Value]\n\t    })\n\tend\n\t\n\tlocal function ShouldDetonate()\n\t    if not Detonate.Enabled then\n\t        return false\n\t    end\n\t\n\t    local TargetHealth, Expiry\n\t    for Target: Instance, v: number in Marked do\n\t        if Target.Parent and tick() < v then\n\t            local Humanoid: Humanoid? = Target:FindFirstChildWhichIsA(\"Humanoid\")\n\t            if Humanoid and Humanoid.MaxHealth > 0 then\n\t                TargetHealth, Expiry = (Humanoid.Health + getShieldAttribute(Target)) / Humanoid.MaxHealth * 100, v\n\t                break\n\t            end\n\t        end\n\t    end\n\t    if DetonateMode.Value == \"Instantly\" then\n\t        return true\n\t    elseif not TargetHealth then\n\t        return false\n\t    elseif DetonateMode.Value == \"Low health\" then\n\t        return TargetHealth <= Health.Value\n\t    end\n\t    return tick() >= Expiry - 1\n\tend\n\t\n\tAutoSkoll = vape.Categories.Kits:CreateModule({\n\t    Name = \"AutoSkoll\",\n\t    Function = function(Callback: boolean)\n\t        if Callback then\n\t            table.clear(Marked)\n\t\n\t            Old = bedwars.VoidHunterKitController.onAbilityUsed\n\t            bedwars.VoidHunterKitController.onAbilityUsed = function(self, Character, Data, ...)\n\t                if Aim.Enabled and Data and Data.ability == \"void_hunter_mark\" and Character == LocalPlayer.Character and Character.PrimaryPart then\n\t                    local Target = GetTarget()\n\t                    if Target then\n\t                        local Origin: Vector3 = Character.PrimaryPart.Position\n\t                        local Delta: Vector3 = Target.RootPart.Position - Origin\n\t                        if Delta.Magnitude > 0 then\n\t                            bedwars.Handler:Get(\"VoidHunter_MarkAbilityRequest\"):Fire(\"SendToServer\", {\n\t                                originPosition = Origin,\n\t                                direction = Delta.Unit\n\t                            })\n\t                            return\n\t                        end\n\t                    end\n\t                end\n\t                return Old(self, Character, Data, ...)\n\t            end\n\t\n\t            AutoSkoll:Clean(bedwars.Handler:Get(\"VoidHunter_TargetMarked\").Remote:Connect(function(Data)\n\t                if Data.userPlayer == LocalPlayer and Data.targetEntityInstance then\n\t                    Marked[Data.targetEntityInstance] = tick() + bedwars.VoidHunterBalance.MARK_DURATION\n\t                end\n\t            end))\n\t\n\t            AutoSkoll:Clean(bedwars.Handler:Get(\"VoidHunter_TargetMarkRemoved\").Remote:Connect(function(Data)\n\t                if Data.userPlayer == LocalPlayer and Data.targetEntityInstance then\n\t                    Marked[Data.targetEntityInstance] = nil\n\t                end\n\t            end))\n\t\n\t            repeat\n\t                if Entity.isAlive and store.equippedKit == \"void_hunter\" then\n\t                    if ShouldDetonate() and bedwars.AbilityController:canUseAbility(\"void_hunter_detonate\", {disableBlockedAbilityAlert = true}) then\n\t                        bedwars.AbilityController:useAbility(\"void_hunter_detonate\")\n\t                        table.clear(Marked)\n\t                    elseif GetTarget() and bedwars.AbilityController:canUseAbility(\"void_hunter_mark\", {disableBlockedAbilityAlert = true}) then\n\t                        bedwars.AbilityController:useAbility(\"void_hunter_mark\")\n\t                    end\n\t                end\n\t                task.wait(0.1)\n\t            until not AutoSkoll.Enabled\n\t        else\n\t            table.clear(Marked)\n\t            if Old then\n\t                bedwars.VoidHunterKitController.onAbilityUsed = Old\n\t                Old = nil\n\t            end\n\t        end\n\t    end,\n\t    Tooltip = \"Sends Fenrir at whoever is near you and sets the mark off\"\n\t})\n\t\n\tTargets = AutoSkoll:CreateTargets({\n\t    Players = true,\n\t    NPCs = false\n\t})\n\tlocal Methods: {string} = {\"Distance\", \"Health\"}\n\tfor _, v: string in sortlist do\n\t    if not table.find(Methods, v) then\n\t        table.insert(Methods, v)\n\t    end\n\tend\n\tSort = AutoSkoll:CreateDropdown({\n\t    Name = \"Target mode\",\n\t    List = Methods\n\t})\n\tRange = AutoSkoll:CreateSlider({\n\t    Name = \"Range\",\n\t    Min = 1,\n\t    Max = 100,\n\t    Default = 50,\n\t    Suffix = function(Val: number)\n\t        return Val <= 1 and \"stud\" or \"studs\"\n\t    end,\n\t    Tooltip = \"Fenrir travels 39 studs a second and lives 3 seconds\"\n\t})\n\tAim = AutoSkoll:CreateToggle({\n\t    Name = \"Aim wolf\",\n\t    Default = true,\n\t    Tooltip = \"Throws Fenrir straight at your target instead of wherever your camera points\"\n\t})\n\tDetonate = AutoSkoll:CreateToggle({\n\t    Name = \"Auto detonate\",\n\t    Function = function(Callback: boolean)\n\t        if DetonateMode.Object then\n\t            DetonateMode.Object.Visible = Callback\n\t            Health.Object.Visible = Callback and DetonateMode.Value == \"Low health\"\n\t        end\n\t    end,\n\t    Default = true,\n\t    Tooltip = \"Sets the mark off, which costs you the damage buff on them\"\n\t})\n\tDetonateMode = AutoSkoll:CreateDropdown({\n\t    Name = \"Detonate at\",\n\t    List = {\"Low health\", \"Instantly\", \"Before it expires\"},\n\t    Darker = true,\n\t    Visible = false,\n\t    Function = function(Val: string)\n\t        if Health.Object then\n\t            Health.Object.Visible = Detonate.Enabled and Val == \"Low health\"\n\t        end\n\t    end,\n\t    Tooltip = \"Low health finishes them off, Before it expires keeps the buff until the mark runs out\"\n\t})\n\tHealth = AutoSkoll:CreateSlider({\n\t    Name = \"Health\",\n\t    Min = 1,\n\t    Max = 100,\n\t    Default = 30,\n\t    Darker = true,\n\t    Visible = false,\n\t    Suffix = \"%\",\n\t    Tooltip = \"Blows the mark for 20 damage once they drop under this\"\n\t})\nend)\n\nRun(function()\n\tlocal AutoSmoke\n\tlocal Range\n\tlocal Health\n\tlocal Delay\n\tlocal NextBomb: number = 0\n\t\n\tAutoSmoke = vape.Categories.Kits:CreateModule({\n\t    Name = \"AutoSmoke\",\n\t    Function = function(Callback: boolean)\n\t        if Callback then\n\t            NextBomb = 0\n\t\n\t            repeat\n\t                local Bomb = Entity.isAlive and Store.equippedKit == \"smoke\" and tick() >= NextBomb and GetItem(\"smoke_bomb\") or nil\n\t                if Bomb and Entity.character.Health <= (Entity.character.MaxHealth * (Health.Value / 100)) then\n\t                    local Target = Entity.EntityPosition({\n\t                        Origin = Entity.character.RootPart.Position,\n\t                        Range = Range.Value,\n\t                        Part = \"RootPart\",\n\t                        Players = true\n\t                    })\n\t\n\t                    if Target then\n\t                        NextBomb = tick() + Delay.Value\n\t                        bedwars.Handler:Get(\"ConsumeItem\"):Fire(\"CallServer\", {item = Bomb.tool})\n\t                    end\n\t                end\n\t                task.wait(0.1)\n\t            until not AutoSmoke.Enabled\n\t        end\n\t    end,\n\t    Tooltip = \"Automatically pops a smoke bomb when you are low with enemies nearby\"\n\t})\n\t\n\tRange = AutoSmoke:CreateSlider({\n\t    Name = \"Range\",\n\t    Min = 1,\n\t    Max = 60,\n\t    Default = 25,\n\t    Suffix = function(Val: number)\n\t        return Val <= 1 and \"stud\" or \"studs\"\n\t    end\n\t})\n\tHealth = AutoSmoke:CreateSlider({\n\t    Name = \"Health\",\n\t    Min = 1,\n\t    Max = 100,\n\t    Default = 50,\n\t    Suffix = function()\n\t        return \"%\"\n\t    end,\n\t    Tooltip = \"Pops the bomb at or below this much health\"\n\t})\n\tDelay = AutoSmoke:CreateSlider({\n\t    Name = \"Delay\",\n\t    Min = 0.5,\n\t    Max = 15,\n\t    Default = 5,\n\t    Decimal = 10,\n\t    Suffix = function(Val: number)\n\t        return Val <= 1 and \"sec\" or \"secs\"\n\t    end\n\t})\nend)\n\nRun(function()\n\tlocal AutoSophia\n\tlocal Targets\n\tlocal Range\n\tlocal FireRate\n\tlocal SwitchDelay\n\tlocal NextFire: number = 0\n\tlocal NextSwap: number = 0\n\t\n\tlocal Staffs: {string} = {\"frost_staff_3\", \"frost_staff_2\", \"frost_staff_1\"}\n\t\n\tlocal function ShootStaff()\n\t    local Item, ItemType\n\t    for _, v: string in Staffs do\n\t        Item = GetItem(v)\n\t        if Item then\n\t            ItemType = v\n\t            break\n\t        end\n\t    end\n\t    local Source = Item and bedwars.ItemMeta[ItemType].projectileSource or nil\n\t    local Target = Source and GetFacingEntity({\n\t        Part = \"RootPart\",\n\t        Range = Range.Value,\n\t        Players = Targets.Players.Enabled,\n\t        NPCs = Targets.NPCs.Enabled,\n\t        Priority = Targets.Priority.Value,\n\t        Wallcheck = Targets.Walls.Enabled,\n\t        Limit = 10\n\t    }) or nil\n\t    if not Target then\n\t        return\n\t    end\n\t\n\t    local Ready: boolean = bedwars.FrostyGunController.projectileMode == bedwars.FrostyGunMode.PROJECTILE\n\t    local Swapping: boolean = not Ready and tick() >= NextSwap and bedwars.AbilityController:canUseAbility(\"frosty_gun_swap\", {disableBlockedAbilityAlert = true})\n\t    if not Ready and not Swapping then\n\t        return\n\t    end\n\t\n\t    local Hotbar = Store.hand.tool and GetHotbar(Store.hand.tool) or nil\n\t    if HotbarSwitch(GetHotbar(Item.tool)) then\n\t        task.wait(Store.ping.total or 0)\n\t        if Ready then\n\t            if FireProjectile(Item, ItemType, Source.projectileType(ItemType), Target) then\n\t                NextFire = tick() + Source.fireDelaySec + FireRate:GetRandomValue()\n\t                task.wait(SwitchDelay.Value)\n\t            end\n\t        else\n\t            NextSwap = tick() + 1\n\t            bedwars.AbilityController:useAbility(\"frosty_gun_swap\")\n\t            task.wait(SwitchDelay.Value)\n\t        end\n\t        HotbarSwitch(Hotbar)\n\t    end\n\tend\n\t\n\tAutoSophia = vape.Categories.Kits:CreateModule({\n\t    Name = \"AutoSophia\",\n\t    Function = function(Callback: boolean)\n\t        if Callback then\n\t            NextFire, NextSwap = 0, 0\n\t\n\t            repeat\n\t                if Entity.isAlive and Store.equippedKit == \"winter_lady\" and Store.hand.toolType == \"sword\" and (tick() - bedwars.SwordController.lastSwing) < 0.2 and tick() >= NextFire then\n\t                    ShootStaff()\n\t                end\n\t                task.wait(0.1)\n\t            until not AutoSophia.Enabled\n\t        end\n\t    end,\n\t    Tooltip = \"Automatically shoots Sophia's frost staff at whoever you're meleeing, swapping it out of mist mode when needed\"\n\t})\n\t\n\tTargets = AutoSophia:CreateTargets({\n\t    Players = true,\n\t    NPCs = false\n\t})\n\tRange = AutoSophia:CreateSlider({\n\t    Name = \"Range\",\n\t    Min = 1,\n\t    Max = 60,\n\t    Default = 22,\n\t    Suffix = function(Val: number)\n\t        return Val <= 1 and \"stud\" or \"studs\"\n\t    end\n\t})\n\tFireRate = AutoSophia:CreateTwoSlider({\n\t    Name = \"Fire Rate\",\n\t    Min = 0,\n\t    Max = 1,\n\t    DefaultMin = 0.05,\n\t    DefaultMax = 0.12,\n\t    Decimal = 100\n\t})\n\tSwitchDelay = AutoSophia:CreateSlider({\n\t    Name = \"Switch Delay\",\n\t    Min = 0,\n\t    Max = 1,\n\t    Decimal = 100,\n\t    Suffix = \"seconds\",\n\t    Default = 0.02\n\t})\nend)\n\nRun(function()\n\tlocal AutoStar\n\tlocal Streamer\n\tlocal Range\n\tlocal Animation\n\tlocal Delay\n\t\n\tlocal Cooldowns: {[Instance]: number} = {}\n\t\n\tAutoStar = vape.Categories.Kits:CreateModule({\n\t    Name = \"AutoStarCollector\",\n\t    Function = function(Callback: boolean)\n\t        if Callback then\n\t            AutoStar:Clean(ProximityPromptService.PromptShown:Connect(function(Prompt: ProximityPrompt)\n\t                if Streamer.Enabled and Prompt.Name == \"stars_ProximityPrompt\" then\n\t                    task.wait(0.1)\n\t                    Prompt:InputHoldBegin()\n\t                end\n\t            end))\n\t\n\t            repeat\n\t                if not Streamer.Enabled and Entity.isAlive then\n\t                    local LocalPosition: Vector3 = Entity.character.RootPart.Position\n\t                    for _, v: Model in CollectionService:GetTagged(\"stars\") do\n\t                        if tick() > (Cooldowns[v] or 0) and v.PrimaryPart and (LocalPosition - v.PrimaryPart.Position).Magnitude <= Range.Value then\n\t                            if Delay.Value > 0 then\n\t                                task.wait(Delay.Value)\n\t                            end\n\t\n\t                            if (LocalPosition - v.PrimaryPart.Position).Magnitude <= Range.Value then\n\t                                if Animation.Enabled then\n\t                                    bedwars.GameAnimationUtil:playAnimation(LocalPlayer.Character, bedwars.AnimationType.PUNCH)\n\t                                    bedwars.ViewmodelController:playAnimation(bedwars.AnimationType.FP_USE_ITEM)\n\t                                end\n\t\n\t                                bedwars.StarCollectorController:collectEntity(LocalPlayer, v, v.Name)\n\t                                Cooldowns[v] = tick() + 1\n\t                            end\n\t                        end\n\t                    end\n\t                end\n\t                task.wait(0.1)\n\t            until not AutoStar.Enabled\n\t        else\n\t            table.clear(Cooldowns)\n\t        end\n\t    end,\n\t    Tooltip = \"Automatically collects stars\"\n\t})\n\t\n\tStreamer = AutoStar:CreateToggle({\n\t    Name = \"Streamer mode\",\n\t    Function = function(Callback: boolean)\n\t        if Delay then\n\t            Delay.Object.Visible = not Callback\n\t            Range.Object.Visible = not Callback\n\t            Animation.Object.Visible = not Callback\n\t        end\n\t    end,\n\t    Tooltip = \"Useful for when ur screensharing\"\n\t})\n\tAnimation = AutoStar:CreateToggle({\n\t    Name = \"Animation\",\n\t    Default = true,\n\t    Tooltip = \"Plays the collect animation\"\n\t})\n\tRange = AutoStar:CreateSlider({\n\t    Name = \"Range\",\n\t    Min = 1,\n\t    Max = 20,\n\t    Default = 12,\n\t    Suffix = function(Val: number)\n\t        return Val > 1 and \"studs\" or \"stud\"\n\t    end\n\t})\n\tDelay = AutoStar:CreateSlider({\n\t    Name = \"Delay\",\n\t    Min = 0,\n\t    Max = 1,\n\t    Default = 0.2,\n\t    Decimal = 100,\n\t    Suffix = function(Val: number)\n\t        return Val > 1 and \"secs\" or \"sec\"\n\t    end\n\t})\nend)\n\nRun(function()\n\tlocal AutoTaliyah\n\tlocal Emerald\n\tlocal Diamond\n\tlocal Iron\n\tlocal Amount\n\t\n\tlocal function GetShopId()\n\t    if Entity.isAlive then\n\t        local LocalPosition: Vector3 = Entity.character.RootPart.Position\n\t        for _, v: any in Store.shop do\n\t            if v.Shop and (v.RootPart.Position - LocalPosition).Magnitude <= 20 then\n\t                return v.Id\n\t            end\n\t        end\n\t    end\n\t    return\n\tend\n\t\n\tAutoTaliyah = vape.Categories.Kits:CreateModule({\n\t    Name = \"AutoTaliyah\",\n\t    Function = function(Callback: boolean)\n\t        if Callback then\n\t            local Item\n\t            local NextSell: number = 0\n\t\n\t            repeat\n\t                Item = Item or bedwars.Shop.getShopItem(\"chicken_shop_item\", LocalPlayer)\n\t                local Id = Item and NextSell < os.clock() and GetShopId()\n\t                if Id then\n\t                    local ChickenData = bedwars.TaliyahUtil:getPrice()\n\t                    if (ChickenData.currency == \"emerald\" and Emerald.Enabled or ChickenData.currency == \"iron\" and Iron.Enabled or ChickenData.currency == \"diamond\" and Diamond.Enabled) and ChickenData.price >= Amount.Value then\n\t                        NextSell = os.clock() + 0.5\n\t                        bedwars.Handler:Get(\"BedwarsPurchaseItem\"):Fire(\"CallServerAsync\", {\n\t                            shopItem = Item,\n\t                            shopId = Id\n\t                        }):andThen(function(Success: boolean)\n\t                            if Success then\n\t                                bedwars.AudioManager:playAudio(bedwars.SoundList.BEDWARS_PURCHASE_ITEM)\n\t                                bedwars.Store:dispatch({\n\t                                    type = \"BedwarsAddItemPurchased\",\n\t                                    itemType = Item.itemType\n\t                                })\n\t                                if Item.tiered then\n\t                                    bedwars.BedwarsShopController.alreadyPurchasedMap[Item.itemType] = true\n\t                                end\n\t                            end\n\t                        end)\n\t                    end\n\t                end\n\t                task.wait(0.1)\n\t            until not AutoTaliyah.Enabled\n\t        end\n\t    end,\n\t    Tooltip = \"Automatically buy chickens when it sells for emerald\"\n\t})\n\t\n\tIron = AutoTaliyah:CreateToggle({\n\t    Name = \"Iron\",\n\t    Default = true,\n\t    Tooltip = \"Sells ur chicken when the currency is iron\"\n\t})\n\tEmerald = AutoTaliyah:CreateToggle({\n\t    Name = \"Emerald\",\n\t    Default = true,\n\t    Tooltip = \"Sells ur chicken when the currency is emerald\"\n\t})\n\tDiamond = AutoTaliyah:CreateToggle({\n\t    Name = \"Diamond\",\n\t    Default = true,\n\t    Tooltip = \"Sells ur chicken when the currency is diamond\"\n\t})\n\tAmount = AutoTaliyah:CreateSlider({\n\t    Name = \"Amount\",\n\t    Min = 1,\n\t    Max = 1000,\n\t    Default = 2,\n\t    Tooltip = \"Only sells if the currency is selling for the selected amount\"\n\t})\nend)\n\nRun(function()\n\tlocal AutoTrap\n\tlocal Mode\n\tlocal Targets\n\tlocal TrapType\n\tlocal Traps\n\tlocal Target\n\tlocal Radius\n\tlocal Range\n\tlocal Amount\n\tlocal PlaceRange\n\tlocal Delay\n\tlocal IgnoreWalls\n\tlocal Switch\n\tlocal Notify\n\tlocal Detonate\n\t\n\tlocal TrapperFolder: Folder = ReplicatedStorage.TS.games.bedwars.kit.kits.trapper\n\tlocal Constants = require(TrapperFolder[\"trapper-constants\"])\n\tlocal TrapperUtil = require(TrapperFolder[\"trapper-util\"])\n\tlocal TrapState = require(TrapperFolder[\"snap-trap-state\"]).SnapTrapState\n\tlocal Balance = Constants.TrapperBalance\n\tlocal TrapNames: {[string]: string} = {Snap = \"snap_trap\", Venom = \"venom_trap\", Explosive = \"explosive_trap\"}\n\tlocal Placed: {[Vector3]: number} = {}\n\tlocal NextThrow: number = 0\n\tlocal NextSwitch: number = 0\n\tlocal NextDetonate: number = 0\n\tlocal BedCount: number = 0\n\tlocal Session: number = 0\n\tlocal RayFilter: {Instance} = {}\n\tlocal SightParams: RaycastParams = RaycastParams.new()\n\tSightParams.FilterType = Enum.RaycastFilterType.Exclude\n\t\n\tlocal function UpdateFilter()\n\t    local Filter: {Instance} = {Camera, Entity.character.Character}\n\t    for _, v: any in Entity.List do\n\t        table.insert(Filter, v.Character)\n\t    end\n\t    for _, v: Instance in CollectionService:GetTagged(\"DontBlockAbilityRaycast\") do\n\t        table.insert(Filter, v)\n\t    end\n\t    RayFilter = Filter\n\tend\n\t\n\tlocal function Raycast(Origin: Vector3, Direction: Vector3): RaycastResult?\n\t    SightParams.FilterDescendantsInstances = RayFilter\n\t    return bedwars.QueryUtil:raycast(Origin, Direction, SightParams)\n\tend\n\t\n\tlocal function HasStock(Item: string): boolean\n\t    local Meta = Constants.TrapperTrapMeta[Item]\n\t    return Meta ~= nil and bedwars.TrapperController:canUseAbilities() and TrapperUtil.getTrapCount(LocalPlayer, Item) > 0 and TrapperUtil.getPlacedTrapCount(LocalPlayer, Item) < Meta.maxPlaced\n\tend\n\t\n\tlocal function GetTrap(EnemyMode: boolean): string?\n\t    local Wanted: string? = TrapNames[TrapType.Value]\n\t    if Wanted then\n\t        return HasStock(Wanted) and Wanted or nil\n\t    end\n\t\n\t    if EnemyMode then\n\t        local Selected: string = TrapperUtil.getSelectedTrap(LocalPlayer)\n\t        if HasStock(Selected) then\n\t            return Selected\n\t        end\n\t        for _, v: string in Constants.TrapperTraps do\n\t            if HasStock(v) then\n\t                return v\n\t            end\n\t        end\n\t    else\n\t        for _, v: string in Traps.ListEnabled do\n\t            if TrapperUtil.isTrapperTrap(v) and HasStock(v) or not TrapperUtil.isTrapperTrap(v) and GetItem(v) then\n\t                return v\n\t            end\n\t        end\n\t    end\n\t    return nil\n\tend\n\t\n\tlocal function GetGround(Position: Vector3): Vector3?\n\t    local Hit: RaycastResult? = Raycast(Position + Vector3.new(0, 3, 0), Vector3.new(0, -24, 0))\n\t    if Hit and Hit.Normal.Y > 0.99 then\n\t        return RoundPosition(Hit.Position + Vector3.new(0, 0.15, 0))\n\t    end\n\t    return nil\n\tend\n\t\n\tlocal function IsValid(Position: Vector3, Item: string): boolean\n\t    if tick() < (Placed[Position] or 0) or GetPlacedBlock(Position) then\n\t        return false\n\t    end\n\t\n\t    local Origin: Vector3 = Entity.character.RootPart.Position + Vector3.new(0, 1, 0)\n\t    if (Position - Origin).Magnitude > math.min(PlaceRange.Value, Balance.ThrowRange) then\n\t        return false\n\t    end\n\t\n\t    if TrapperUtil.isTrapperTrap(Item) then\n\t        return TrapperUtil.canThrowTrap(Origin, Position, Raycast, Vector3.yAxis)\n\t    end\n\t    return GetPlacedBlock(Position - Vector3.new(0, 3, 0)) ~= nil and CanPlace()\n\tend\n\t\n\tlocal function PlaceTrap(Position: Vector3, Item: string): boolean\n\t    if not IsValid(Position, Item) then\n\t        return false\n\t    end\n\t\n\t    if TrapperUtil.isTrapperTrap(Item) then\n\t        if not HasStock(Item) or bedwars.TrapperController.currentAim then\n\t            return false\n\t        end\n\t\n\t        if TrapperUtil.getSelectedTrap(LocalPlayer) ~= Item then\n\t            if tick() >= NextSwitch and bedwars.AbilityController:canUseAbility(\"trapper_switch\", {disableBlockedAbilityAlert = true}) then\n\t                NextSwitch = tick() + math.max(Balance.SwitchCooldown, 0.25)\n\t                bedwars.AbilityController:useAbility(\"trapper_switch\", nil, {trapType = Item})\n\t            end\n\t            return false\n\t        end\n\t\n\t        local Controller = bedwars.TrapperController\n\t        local Aim = {\n\t            character = LocalPlayer.Character,\n\t            trapType = Item,\n\t            source = \"binding\",\n\t            released = true,\n\t            payload = {trapType = Item, target = Position, normal = Vector3.yAxis}\n\t        }\n\t        Controller.currentAim = Aim\n\t        local Success, Fired = pcall(function(): boolean\n\t            if not bedwars.AbilityController:canUseAbility(\"trapper_throw\", {disableBlockedAbilityAlert = true}) then\n\t                return false\n\t            end\n\t            bedwars.AbilityController:useAbility(\"trapper_throw\", nil, Aim.payload)\n\t            return true\n\t        end)\n\t        if Controller.currentAim == Aim then\n\t            Controller:cancelAim()\n\t        end\n\t        if not Success then\n\t            error(Fired)\n\t        end\n\t        if not Fired then\n\t            return false\n\t        end\n\t    else\n\t        local Previous: number? = Switch.Enabled and Store.hand.tool and GetHotbar(Store.hand.tool) or nil\n\t        bedwars.placeBlock(Position, Item)\n\t        if Previous then\n\t            HotbarSwitch(Previous)\n\t        end\n\t    end\n\t\n\t    Placed[Position] = tick() + 2\n\t    if Notify.Enabled then\n\t        SendNotification(\"AutoTrap\", `Placed {Item}`, 3)\n\t    end\n\t    return true\n\tend\n\t\n\tlocal function GetBed(): BasePart?\n\t    local Own: string = `Team{LocalPlayer:GetAttribute(\"Team\") or -1}NoBreak`\n\t    local Closest, ClosestDistance = nil, Range.Value\n\t    for _, v: BasePart in CollectionService:GetTagged(\"bed\") do\n\t        local Mine: boolean = v:GetAttribute(Own) and true or false\n\t        if Mine ~= (Target.Value == \"Your bed\") then\n\t            continue\n\t        end\n\t\n\t        local Distance: number = (Entity.character.RootPart.Position - v.Position).Magnitude\n\t        if Distance < ClosestDistance then\n\t            Closest, ClosestDistance = v, Distance\n\t        end\n\t    end\n\t    return Closest\n\tend\n\t\n\tlocal function TrapBed(Item: string): boolean\n\t    local Bed: BasePart? = GetBed()\n\t    if not Bed then\n\t        return false\n\t    end\n\t\n\t    local Step: number = Radius.Value * 3\n\t    for X: number = -Step, Step, 3 do\n\t        for Z: number = -Step, Step, 3 do\n\t            if math.abs(X) ~= Step and math.abs(Z) ~= Step then\n\t                continue\n\t            end\n\t\n\t            local Position: Vector3? = GetGround(Bed.Position + Vector3.new(X, 0, Z))\n\t            if Position and PlaceTrap(Position, Item) then\n\t                return true\n\t            end\n\t        end\n\t    end\n\t    return false\n\tend\n\t\n\tlocal function GetEnemies(): {any}\n\t    return Entity.AllPosition({\n\t        Range = Detonate.Enabled and TrapperUtil.getArmedTrapCount(LocalPlayer, \"explosive_trap\") > 0 and math.huge or PlaceRange.Value + 15,\n\t        Part = \"RootPart\",\n\t        Players = Targets.Players.Enabled,\n\t        NPCs = Targets.NPCs.Enabled,\n\t        Wallcheck = (IgnoreWalls.Enabled or Targets.Walls.Enabled) and true or nil,\n\t        Sort = SortMethods.Distance\n\t    })\n\tend\n\t\n\tlocal function TrapEnemies(Item: string, Enemies: {any}): boolean\n\t    local Origin: Vector3 = Entity.character.RootPart.Position + Vector3.new(0, 1, 0)\n\t    for _, v: any in Enemies do\n\t        local Position: Vector3 = v.RootPart.Position\n\t        local Velocity: Vector3 = v.RootPart.AssemblyLinearVelocity * Vector3.new(1, 0, 1)\n\t        local Duration: number = TrapperUtil.trapThrowDuration(Origin, Position) + Balance.SettleTime + Constants.TrapperTrapMeta[Item].setupTime + (Store.ping.total or 0)\n\t        local Lead: Vector3 = Velocity * Duration\n\t        if Lead.Magnitude > 18 then\n\t            Lead = Lead.Unit * 18\n\t        end\n\t\n\t        for _, Factor: number in {1, 0.5, 0} do\n\t            local Ground: Vector3? = GetGround(Position + Lead * Factor - Vector3.new(0, v.HipHeight - 1.5, 0))\n\t            if Ground and PlaceTrap(Ground, Item) then\n\t                return true\n\t            end\n\t        end\n\t    end\n\t    return false\n\tend\n\t\n\tlocal function DetonateTraps(PlacedTraps: {BasePart}, Enemies: {any})\n\t    if not Detonate.Enabled or tick() < NextDetonate or TrapperUtil.getArmedTrapCount(LocalPlayer, \"explosive_trap\") == 0 or not bedwars.TrapperController:canUseAbilities() or not bedwars.AbilityController:canUseAbility(\"trapper_detonate\", {disableBlockedAbilityAlert = true}) then\n\t        return\n\t    end\n\t\n\t    for _, v: BasePart in PlacedTraps do\n\t        if v.Name ~= \"explosive_trap\" or v:GetAttribute(\"PlacedByUserId\") ~= LocalPlayer.UserId or v:GetAttribute(\"SnapTrapState\") ~= TrapState.ACTIVE then\n\t            continue\n\t        end\n\t\n\t        local Normal: Vector3 = v:GetAttribute(\"TrapperSurfaceNormal\") or Vector3.yAxis\n\t        local Center: Vector3 = TrapperUtil.trapSurfacePosition(v.Position, Normal)\n\t        for _, Ent: any in Enemies do\n\t            local Predicted: Vector3 = Ent.RootPart.Position + Ent.RootPart.AssemblyLinearVelocity * Balance.ExplosionDelay\n\t            if (Ent.RootPart.Position - Center).Magnitude <= Balance.ExplosionRadius and (Predicted - Center).Magnitude <= Balance.ExplosionRadius then\n\t                NextDetonate = tick() + math.max(Balance.DetonateCooldown, Balance.ExplosionDelay)\n\t                bedwars.AbilityController:useAbility(\"trapper_detonate\")\n\t                return\n\t            end\n\t        end\n\t    end\n\tend\n\t\n\tAutoTrap = vape.Categories.Kits:CreateModule({\n\t    Name = \"AutoTrap\",\n\t    Function = function(Callback: boolean)\n\t        Session += 1\n\t        if Callback then\n\t            local CurrentSession: number = Session\n\t            table.clear(Placed)\n\t            NextThrow, NextSwitch, NextDetonate, BedCount = 0, 0, 0, 0\n\t            local PlacedTraps: {BasePart} = Collection(\"trapper_trap\", AutoTrap)\n\t\n\t            repeat\n\t                if Entity.isAlive then\n\t                    local Enemies: {any} = GetEnemies()\n\t                    DetonateTraps(PlacedTraps, Enemies)\n\t                    if tick() >= NextThrow then\n\t                        local EnemyMode: boolean = Mode.Value == \"Enemies\"\n\t                        local Item: string? = GetTrap(EnemyMode)\n\t                        if Item then\n\t                            UpdateFilter()\n\t                            local Success: boolean = EnemyMode and TrapEnemies(Item, Enemies) or not EnemyMode and TrapBed(Item)\n\t                            if Success then\n\t                                BedCount = EnemyMode and 0 or BedCount + 1\n\t                                local Pause: boolean = EnemyMode or BedCount >= Amount.Value\n\t                                NextThrow = tick() + math.max(Balance.ThrowCooldown, Pause and Delay.Value or 0)\n\t                                if Pause then\n\t                                    BedCount = 0\n\t                                end\n\t                            end\n\t                        end\n\t                    end\n\t                end\n\t\n\t                for Position: Vector3, Expiry: number in Placed do\n\t                    if tick() >= Expiry then\n\t                        Placed[Position] = nil\n\t                    end\n\t                end\n\t                task.wait(0.1)\n\t            until not AutoTrap.Enabled or CurrentSession ~= Session\n\t        end\n\t    end,\n\t    Tooltip = \"Throws the reworked Trapper traps at enemies or around a bed and detonates armed explosives\"\n\t})\n\t\n\tMode = AutoTrap:CreateDropdown({\n\t    Name = \"Mode\",\n\t    List = {\"Bed ring\", \"Enemies\"},\n\t    Function = function(Val: string)\n\t        if Traps then\n\t            local EnemyMode: boolean = Val == \"Enemies\"\n\t            Target.Object.Visible = not EnemyMode\n\t            Radius.Object.Visible = not EnemyMode\n\t            Range.Object.Visible = not EnemyMode\n\t            Amount.Object.Visible = not EnemyMode\n\t            Traps.Object.Visible = not EnemyMode\n\t            IgnoreWalls.Object.Visible = EnemyMode\n\t        end\n\t        BedCount = 0\n\t    end,\n\t    Tooltip = \"Bed ring surrounds a bed; Enemies throws ahead of nearby targets using the trap's travel and arming time\"\n\t})\n\tTargets = AutoTrap:CreateTargets({Players = true})\n\tTrapType = AutoTrap:CreateDropdown({\n\t    Name = \"Trap type\",\n\t    List = {\"Auto\", \"Snap\", \"Venom\", \"Explosive\"},\n\t    Tooltip = \"Auto uses your selected stocked trap against enemies and the Traps list around beds\"\n\t})\n\tTarget = AutoTrap:CreateDropdown({\n\t    Name = \"Target\",\n\t    List = {\"Your bed\", \"Enemy bed\"}\n\t})\n\tRadius = AutoTrap:CreateSlider({\n\t    Name = \"Radius\",\n\t    Min = 1,\n\t    Max = 5,\n\t    Default = 2,\n\t    Suffix = \"blocks\"\n\t})\n\tRange = AutoTrap:CreateSlider({\n\t    Name = \"Range\",\n\t    Min = 4,\n\t    Max = 60,\n\t    Default = 20,\n\t    Suffix = \"studs\",\n\t    Tooltip = \"How close the bed has to be before placing\"\n\t})\n\tAmount = AutoTrap:CreateSlider({\n\t    Name = \"Amount\",\n\t    Min = 1,\n\t    Max = 8,\n\t    Default = 3,\n\t    Suffix = \"traps\",\n\t    Tooltip = \"Traps to throw per bed ring pass\"\n\t})\n\tPlaceRange = AutoTrap:CreateSlider({\n\t    Name = \"Place Range\",\n\t    Min = 1,\n\t    Max = 45,\n\t    Default = 30,\n\t    Suffix = \"studs\",\n\t    Tooltip = \"Maximum throw distance, capped at the game's throw range\"\n\t})\n\tDelay = AutoTrap:CreateSlider({\n\t    Name = \"Delay\",\n\t    Min = 0.35,\n\t    Max = 10,\n\t    Default = 0.5,\n\t    Decimal = 100,\n\t    Suffix = \"seconds\",\n\t    Tooltip = \"Wait between enemy throws or bed ring passes, respecting the game's cooldown\"\n\t})\n\tIgnoreWalls = AutoTrap:CreateToggle({\n\t    Name = \"Ignore behind walls\",\n\t    Visible = false,\n\t    Tooltip = \"Skips enemies you cannot see; throw paths are always checked\"\n\t})\n\tDetonate = AutoTrap:CreateToggle({\n\t    Name = \"Auto detonate\",\n\t    Default = true,\n\t    Tooltip = \"Detonates all your armed explosives when an enemy is inside a blast and is predicted to remain there\"\n\t})\n\tSwitch = AutoTrap:CreateToggle({\n\t    Name = \"Switch back\",\n\t    Default = true,\n\t    Tooltip = \"Restores your hotbar slot after placing an inventory trap; Trapper throws do not change your held item\"\n\t})\n\tNotify = AutoTrap:CreateToggle({Name = \"Notify\"})\n\tTraps = AutoTrap:CreateTextList({\n\t    Name = \"Traps\",\n\t    Default = {\"snap_trap\", \"venom_trap\", \"explosive_trap\", \"invisible_landmine\", \"spike_trap\", \"tesla_trap\", \"grave_trap\", \"lucky_block_trap\"},\n\t    Darker = true,\n\t    Placeholder = \"item\",\n\t    Tooltip = \"Bed ring trap priority; Trapper traps use your kit stock and other traps use your inventory\"\n\t})\nend)\n\nRun(function()\n\tlocal AutoTriton\n\tlocal Legit\n\tlocal Back\n\tlocal BackDelay\n\tlocal Limit\n\tlocal FallSpeed\n\tlocal Search\n\tlocal NextFire: number = 0\n\t\n\tlocal RayCheck: RaycastParams = RaycastParams.new()\n\tRayCheck.RespectCanCollide = true\n\tRayCheck.FilterType = Enum.RaycastFilterType.Include\n\t\n\tlocal function GetNearGround(Origin: Vector3)\n\t    for Step: number = 1, Search.Value do\n\t        for _, v: Vector3 in {Vector3.xAxis, Vector3.zAxis, -Vector3.xAxis, -Vector3.zAxis} do\n\t            local RayResult: RaycastResult? = workspace:Raycast((Origin + Vector3.new(0, 3, 0)) + (v * Step), Vector3.new(0, -80, 0), RayCheck)\n\t            if RayResult then\n\t                return RayResult.Position\n\t            end\n\t        end\n\t    end\n\t    return nil\n\tend\n\t\n\tlocal function FireHarpoon(Item, Spot: Vector3)\n\t    local Meta = bedwars.ProjectileMeta.harpoon_projectile\n\t    local Source = bedwars.ItemMeta[Item.itemType].projectileSource\n\t    local Origin: Vector3 = Entity.character.RootPart.Position\n\t    local Speed, Gravity = Meta.launchVelocity, Meta.gravitationalAcceleration or 196.2\n\t    local ShootPosition: Vector3 = (CFrame.new(Origin, Spot) * CFrame.new(Vector3.new(-bedwars.BowConstantsTable.RelX, -bedwars.BowConstantsTable.RelY, -bedwars.BowConstantsTable.RelZ))).Position\n\t    local AimPoint: Vector3? = PredictionLib.SolveTrajectory(ShootPosition, Speed, Gravity, Spot, Vector3.zero, workspace.Gravity, 0, nil, nil, false, Spot)\n\t    if not AimPoint then\n\t        return false\n\t    end\n\t\n\t    local Hotbar, Previous = GetHotbar(Item.tool), Store.hand.tool\n\t    SwitchItem(Item.tool)\n\t    if Legit.Enabled and Hotbar then\n\t        HotbarSwitch(Hotbar)\n\t    end\n\t\n\t    NextFire = tick() + (Source and Source.fireDelaySec or 8)\n\t    bedwars.Handler:Get(\"ProjectileFire\"):Fire(\"CallServerAsync\",\n\t        Item.tool,\n\t        nil,\n\t        Source and Source.projectileType(Item.itemType) or \"harpoon_projectile\",\n\t        ShootPosition,\n\t        Origin,\n\t        CFrame.lookAt(ShootPosition, AimPoint).LookVector * Speed,\n\t        bedwars.IdUtil.generateId(8),\n\t        bedwars.getShotData(Item.itemType),\n\t        workspace:GetServerTimeNow() - 0.045\n\t    ):andThen(function(Result)\n\t        if type(Result) == \"table\" and Result.accepted and Result.model then\n\t            Result.model.Parent = ReplicatedStorage\n\t        end\n\t    end)\n\t\n\t    if Back.Enabled and Previous then\n\t        task.wait(BackDelay:GetRandomValue())\n\t        SwitchItem(Previous)\n\t        if Legit.Enabled and GetHotbar(Previous) then\n\t            HotbarSwitch(GetHotbar(Previous))\n\t        end\n\t    end\n\t    return true\n\tend\n\t\n\tAutoTriton = vape.Categories.Kits:CreateModule({\n\t    Name = \"AutoTriton\",\n\t    Function = function(Callback: boolean)\n\t        if Callback then\n\t            NextFire = 0\n\t            local LastGround: Vector3?\n\t\n\t            repeat\n\t                if Entity.isAlive and tick() >= NextFire and (not Limit.Enabled or Store.hand.tool and Store.hand.tool.Name == \"harpoon\") then\n\t                    local Root: BasePart = Entity.character.RootPart\n\t                    local Harpoon = GetItem(\"harpoon\")\n\t                    RayCheck.FilterDescendantsInstances = {Store.map}\n\t                    RayCheck.CollisionGroup = Root.CollisionGroup\n\t\n\t                    if Entity.character.Humanoid.FloorMaterial ~= Enum.Material.Air then\n\t                        LastGround = Root.Position\n\t                    end\n\t\n\t                    if Harpoon and Root.AssemblyLinearVelocity.Y < -FallSpeed.Value and not workspace:Raycast(Root.Position, Vector3.new(0, -200, 0), RayCheck) then\n\t                        local Spot: Vector3? = GetNearGround(Root.Position + Vector3.new(0, 40, 0)) or LastGround and GetNearGround(LastGround + Vector3.new(0, 5, 0))\n\t                        if Spot then\n\t                            FireHarpoon(Harpoon, Spot)\n\t                        end\n\t                    end\n\t                end\n\t                task.wait(0.1)\n\t            until not AutoTriton.Enabled\n\t        end\n\t    end,\n\t    Tooltip = \"Automatically throws the trident onto nearby ground when you are falling into the void\"\n\t})\n\t\n\tFallSpeed = AutoTriton:CreateSlider({\n\t    Name = \"Fall speed\",\n\t    Min = 10,\n\t    Max = 200,\n\t    Default = 60,\n\t    Suffix = \"studs a second\",\n\t    Tooltip = \"How fast you have to be falling before it throws\"\n\t})\n\tSearch = AutoTriton:CreateSlider({\n\t    Name = \"Search range\",\n\t    Min = 4,\n\t    Max = 60,\n\t    Default = 40,\n\t    Suffix = function(Val: number)\n\t        return Val <= 1 and \"stud\" or \"studs\"\n\t    end,\n\t    Tooltip = \"How far out it looks for ground to land on\"\n\t})\n\tLegit = AutoTriton:CreateToggle({\n\t    Name = \"Legit Switch\",\n\t    Default = true,\n\t    Tooltip = \"Visualizes the switching clientside\"\n\t})\n\tBack = AutoTriton:CreateToggle({\n\t    Name = \"Switch back\",\n\t    Function = function(Callback: boolean)\n\t        if BackDelay then\n\t            BackDelay.Object.Visible = Callback\n\t        end\n\t    end,\n\t    Default = true,\n\t    Tooltip = \"Switches back to the last slot after throwing\"\n\t})\n\tBackDelay = AutoTriton:CreateTwoSlider({\n\t    Name = \"Switch Back Delay\",\n\t    Min = 0,\n\t    Max = 2,\n\t    DefaultMin = 0.1,\n\t    DefaultMax = 0.2,\n\t    Darker = true\n\t})\n\tLimit = AutoTriton:CreateToggle({\n\t    Name = \"Limit to item\",\n\t    Tooltip = \"Only throws when you are already holding the trident\"\n\t})\nend)\n\nRun(function()\n\tlocal AutoTrixie\n\tlocal Targets\n\tlocal Warp\n\tlocal WarpRange\n\tlocal Rewind\n\tlocal Health\n\tlocal NextAbility: number = 0\n\t\n\tAutoTrixie = vape.Categories.Kits:CreateModule({\n\t    Name = \"AutoTrixie\",\n\t    Function = function(Callback: boolean)\n\t        if Callback then\n\t            NextAbility = 0\n\t\n\t            repeat\n\t                if Entity.isAlive and Store.equippedKit == \"void_walker\" and tick() >= NextAbility then\n\t                    local Humanoid: Humanoid = Entity.character.Humanoid\n\t\n\t                    if Rewind.Enabled and Humanoid.Health <= (Humanoid.MaxHealth * (Health.Value / 100)) and bedwars.AbilityController:canUseAbility(\"void_walker_rewind\", {disableBlockedAbilityAlert = true}) then\n\t                        NextAbility = tick() + 1\n\t                        bedwars.AbilityController:useAbility(\"void_walker_rewind\")\n\t                    elseif Warp.Enabled and bedwars.AbilityController:canUseAbility(\"void_walker_warp\", {disableBlockedAbilityAlert = true}) then\n\t                        local Target = Entity.EntityPosition({\n\t                            Range = WarpRange.Value,\n\t                            Part = \"RootPart\",\n\t                            Players = Targets.Players.Enabled,\n\t                            NPCs = Targets.NPCs.Enabled,\n\t                            Wallcheck = Targets.Walls.Enabled,\n\t                            Sort = SortMethods.Distance\n\t                        })\n\t\n\t                        if Target then\n\t                            local Root: BasePart = Entity.character.RootPart\n\t                            Root.CFrame = CFrame.lookAlong(Root.Position, (Target.RootPart.Position - Root.Position) * Vector3.new(1, 0, 1))\n\t                            NextAbility = tick() + 1\n\t                            bedwars.AbilityController:useAbility(\"void_walker_warp\")\n\t                        end\n\t                    end\n\t                end\n\t                task.wait(0.1)\n\t            until not AutoTrixie.Enabled\n\t        end\n\t    end,\n\t    Tooltip = \"Warps you onto whoever you are chasing and rifts you back out when it goes wrong\"\n\t})\n\t\n\tTargets = AutoTrixie:CreateTargets({\n\t    Players = true,\n\t    NPCs = true,\n\t    Walls = true\n\t})\n\tWarp = AutoTrixie:CreateToggle({\n\t    Name = \"Warp to target\",\n\t    Default = true,\n\t    Function = function(Callback: boolean)\n\t        if WarpRange then\n\t            WarpRange.Object.Visible = Callback\n\t        end\n\t    end,\n\t    Tooltip = \"Turns you at the closest enemy before warping so the portal lands on them\"\n\t})\n\tWarpRange = AutoTrixie:CreateSlider({\n\t    Name = \"Warp range\",\n\t    Min = 5,\n\t    Max = 80,\n\t    Default = 40,\n\t    Suffix = function(Val: number)\n\t        return Val <= 1 and \"stud\" or \"studs\"\n\t    end\n\t})\n\tRewind = AutoTrixie:CreateToggle({\n\t    Name = \"Rewind on low health\",\n\t    Default = true,\n\t    Function = function(Callback: boolean)\n\t        if Health then\n\t            Health.Object.Visible = Callback\n\t        end\n\t    end\n\t})\n\tHealth = AutoTrixie:CreateSlider({\n\t    Name = \"Health\",\n\t    Min = 1,\n\t    Max = 100,\n\t    Default = 40,\n\t    Suffix = \"%\"\n\t})\nend)\n\nRun(function()\n\tlocal AutoUma\n\tlocal Range\n\tlocal Limit\n\tlocal Animation\n\tlocal AutoSummon\n\tlocal HealSpirit\n\tlocal AttackSpirit\n\tlocal TargetItemDrops\n\tlocal Diamond\n\tlocal Emerald\n\t\n\tlocal function GetAttackData()\n\t    if Limit.Enabled then\n\t        local Tool: Tool? = (Store.hand.tool and Store.hand.tool.Name == \"spirit_staff\") and Store.hand.tool or nil\n\t        return Tool, Tool and GetHotbar(Tool) or nil\n\t    end\n\t    for i: number, v: any in Store.inventory.inventory.items do\n\t        if v.itemType == \"spirit_staff\" and v.tool then\n\t            SwitchItem(v.tool, 0)\n\t            return v.tool, i\n\t        end\n\t    end\n\t    return\n\tend\n\t\n\tlocal RayCheck: RaycastParams = RaycastParams.new()\n\tRayCheck.FilterType = Enum.RaycastFilterType.Include\n\t\n\tlocal function FireSpirit(Staff, SpiritType: string, Drop: BasePart)\n\t    local Meta = bedwars.ProjectileMeta[SpiritType]\n\t    if not Meta then\n\t        return false\n\t    end\n\t\n\t    local LocalPosition: Vector3 = Entity.character.RootPart.Position\n\t    local ShootPosition: Vector3 = LocalPosition + Vector3.new(0, 2, 0)\n\t    RayCheck.FilterDescendantsInstances = Store.map and {Store.map} or {}\n\t\n\t    local AimPoint: Vector3? = PredictionLib.SolveTrajectory(ShootPosition, Meta.launchVelocity, Meta.gravitationalAcceleration or 196.2, Drop.Position, Vector3.zero, workspace.Gravity, 0, 0, RayCheck)\n\t    if not AimPoint then\n\t        return false\n\t    end\n\t\n\t    bedwars.Handler:Get(\"ProjectileFire\"):Fire(\"CallServerAsync\",\n\t        Staff,\n\t        nil,\n\t        SpiritType,\n\t        ShootPosition,\n\t        LocalPosition,\n\t        CFrame.lookAt(ShootPosition, AimPoint).LookVector * Meta.launchVelocity,\n\t        bedwars.IdUtil.generateId(8),\n\t        bedwars.getShotData(Staff.Name),\n\t        workspace:GetServerTimeNow() - 0.045\n\t    )\n\t\n\t    return true\n\tend\n\t\n\tlocal function GetDrops(LocalPosition: Vector3, ItemDrops: {BasePart})\n\t    local Drop, LastMagnitude = nil, Range.Value + 1\n\t    for _, v: BasePart in ItemDrops do\n\t        if v.Name == \"emerald\" and Emerald.Enabled or v.Name == \"diamond\" and Diamond.Enabled then\n\t            local Magnitude: number = (LocalPosition - v.Position).Magnitude\n\t            if Magnitude <= LastMagnitude and not Entity.Wallcheck(LocalPosition, v.Position, {Camera, LocalPlayer.Character, v}) then\n\t                Drop, LastMagnitude = v, Magnitude\n\t            end\n\t        end\n\t    end\n\t    return Drop\n\tend\n\t\n\tAutoUma = vape.Categories.Kits:CreateModule({\n\t    Name = \"AutoUma\",\n\t    Function = function(Callback: boolean)\n\t        if Callback then\n\t            local Items: {BasePart} = Collection(\"ItemDrop\", AutoUma)\n\t            repeat\n\t                local Staff = GetAttackData()\n\t                if Staff then\n\t                    if TargetItemDrops.Enabled then\n\t                        local AttackSpirits: number = (LocalPlayer:GetAttribute(\"ReadySummonedAttackSpirits\") or 0)\n\t                        local HealSpirits: number = (LocalPlayer:GetAttribute(\"ReadySummonedHealSpirits\") or 0)\n\t\n\t                        if AutoSummon.Enabled then\n\t                            if AttackSpirit.Enabled and AttackSpirits < 1 and GetItem(\"summon_stone\") then\n\t                                bedwars.AbilityController:useAbility(\"summon_attack_spirit\")\n\t                            end\n\t\n\t                            if HealSpirit.Enabled and HealSpirits < 1 and GetItem(\"summon_stone\") then\n\t                                bedwars.AbilityController:useAbility(\"summon_heal_spirit\")\n\t                            end\n\t                        end\n\t\n\t                        if (HealSpirits + AttackSpirits) > 0 then\n\t                            local LocalPosition: Vector3 = Entity.character.RootPart.Position\n\t                            local Drop: BasePart? = GetDrops(LocalPosition, Items)\n\t                            if Drop and FireSpirit(Staff, AttackSpirits > 0 and \"attack_spirit\" or \"heal_spirit\", Drop) then\n\t                                if Animation.Enabled then\n\t                                    bedwars.GameAnimationUtil:playAnimation(LocalPlayer.Character, bedwars.AnimationType.WIZARD_BALL_CAST)\n\t                                    bedwars.AudioManager:playAudio(bedwars.SoundList.SPIRIT_SUMMONER_CHANGE_AFFINITY, {})\n\t                                end\n\t\n\t                                task.wait(1.5)\n\t                            end\n\t                        end\n\t                    end\n\t                end\n\t                task.wait(0.1)\n\t            until not AutoUma.Enabled\n\t        end\n\t    end,\n\t    Tooltip = \"Automatically throw spirits at item drops and opponents.\"\n\t})\n\t\n\tRange = AutoUma:CreateSlider({\n\t    Name = \"Range\",\n\t    Min = 1,\n\t    Max = 80,\n\t    Default = 50,\n\t    Decimal = 5,\n\t    Suffix = function(Val: number)\n\t        return Val >= 2 and \"studs\" or \"stud\"\n\t    end\n\t})\n\tAnimation = AutoUma:CreateToggle({\n\t    Name = \"Animation\",\n\t    Default = true\n\t})\n\tLimit = AutoUma:CreateToggle({\n\t    Name = \"Limit to item\",\n\t    Default = true\n\t})\n\tAutoSummon = AutoUma:CreateToggle({\n\t    Name = \"Auto Summon\",\n\t    Function = function(Callback: boolean)\n\t        if AttackSpirit then\n\t            AttackSpirit.Object.Visible = Callback\n\t            HealSpirit.Object.Visible = Callback\n\t        end\n\t    end,\n\t    Tooltip = \"Automattically summons spirit for you\"\n\t})\n\tHealSpirit = AutoUma:CreateToggle({\n\t    Name = \"Use heal spirit\",\n\t    Default = true,\n\t    Visible = false,\n\t    Darker = true\n\t})\n\tAttackSpirit = AutoUma:CreateToggle({\n\t    Name = \"Use attack spirit\",\n\t    Default = true,\n\t    Visible = false,\n\t    Darker = true\n\t})\n\tTargetItemDrops = AutoUma:CreateToggle({\n\t    Name = \"Target item drops\",\n\t    Function = function(Callback: boolean)\n\t        if Emerald then\n\t            Emerald.Object.Visible = Callback\n\t            Diamond.Object.Visible = Callback\n\t        end\n\t    end,\n\t    Default = true\n\t})\n\tEmerald = AutoUma:CreateToggle({\n\t    Name = \"Emerald\",\n\t    Darker = true,\n\t    Default = true\n\t})\n\tDiamond = AutoUma:CreateToggle({\n\t    Name = \"Diamond\",\n\t    Darker = true,\n\t    Default = true\n\t})\nend)\n\nRun(function()\n\tlocal Old, Overcharge\n\t\n\tvape.Categories.Kits:CreateModule({\n\t    Name = \"AutoVanessa\",\n\t    Function = function(Callback: boolean)\n\t        if Callback then\n\t            Old = bedwars.TripleShotProjectileController.getChargeTime\n\t            Overcharge = bedwars.TripleShotProjectileController.overchargeStartTime\n\t            bedwars.TripleShotProjectileController.getChargeTime = function()\n\t                return 0\n\t            end\n\t            bedwars.TripleShotProjectileController.overchargeStartTime = tick()\n\t        else\n\t            bedwars.TripleShotProjectileController.getChargeTime = Old\n\t            bedwars.TripleShotProjectileController.overchargeStartTime = Overcharge\n\t        end\n\t    end,\n\t    Tooltip = \"Fully charges your bow instantly and enables triple shot as Vanessa\"\n\t})\nend)\n\nRun(function()\n\tlocal AutoVoidKnight\n\tlocal Iron\n\tlocal Emeralds\n\tlocal Keep\n\tlocal Ascend\n\tlocal Range\n\t\n\tlocal function Feed(ItemType: string, Ability: string)\n\t    local Item = GetItem(ItemType)\n\t    if Item and Item.amount > Keep.Value and bedwars.AbilityController:canUseAbility(Ability, {disableBlockedAbilityAlert = true}) then\n\t        bedwars.AbilityController:useAbility(Ability)\n\t    end\n\tend\n\t\n\tAutoVoidKnight = vape.Categories.Kits:CreateModule({\n\t    Name = \"AutoVoidKnight\",\n\t    Function = function(Callback: boolean)\n\t        if Callback then\n\t            repeat\n\t                if Entity.isAlive and Store.equippedKit == \"void_knight\" then\n\t                    if Iron.Enabled then\n\t                        Feed(\"iron\", \"void_knight_consume_iron\")\n\t                    end\n\t\n\t                    if Emeralds.Enabled then\n\t                        Feed(\"emerald\", \"void_knight_consume_emerald\")\n\t                    end\n\t\n\t                    if Ascend.Enabled and bedwars.AbilityController:canUseAbility(\"void_knight_ascend\", {disableBlockedAbilityAlert = true}) then\n\t                        local Near = Entity.EntityPosition({\n\t                            Origin = Entity.character.RootPart.Position,\n\t                            Range = Range.Value,\n\t                            Part = \"RootPart\",\n\t                            Players = true\n\t                        })\n\t                        if Near then\n\t                            bedwars.AbilityController:useAbility(\"void_knight_ascend\")\n\t                        end\n\t                    end\n\t                end\n\t                task.wait(0.2)\n\t            until not AutoVoidKnight.Enabled\n\t        end\n\t    end,\n\t    Tooltip = \"Automatically feeds your resources into the void and ascends in fights\"\n\t})\n\t\n\tKeep = AutoVoidKnight:CreateSlider({\n\t    Name = \"Keep\",\n\t    Min = 0,\n\t    Max = 64,\n\t    Default = 0,\n\t    Tooltip = \"Resources left untouched in your inventory\"\n\t})\n\tRange = AutoVoidKnight:CreateSlider({\n\t    Name = \"Range\",\n\t    Min = 1,\n\t    Max = 60,\n\t    Default = 30,\n\t    Suffix = function(Val: number)\n\t        return Val <= 1 and \"stud\" or \"studs\"\n\t    end\n\t})\n\tIron = AutoVoidKnight:CreateToggle({\n\t    Name = \"Iron\",\n\t    Default = true\n\t})\n\tEmeralds = AutoVoidKnight:CreateToggle({\n\t    Name = \"Emeralds\",\n\t    Default = true\n\t})\n\tAscend = AutoVoidKnight:CreateToggle({\n\t    Name = \"Ascend\",\n\t    Default = true,\n\t    Tooltip = \"Uses void ascension when an enemy is close\"\n\t})\nend)\n\nRun(function()\n\tlocal AutoVoidRegent\n\tlocal Height\n\tlocal FallSpeed\n\tlocal Switch\n\tlocal SwitchDelay = {}\n\tlocal LimitItem\n\tlocal NextSlam: number = 0\n\t\n\tlocal function Slam(Axe)\n\t    if store.hand.tool ~= Axe.tool then\n\t        if Switch.Enabled then\n\t            hotbarSwitch(getHotbar(Axe.tool))\n\t        else\n\t            switchItem(Axe.tool, 0)\n\t        end\n\t        task.wait(SwitchDelay.Value)\n\t    end\n\t\n\t    if AutoVoidRegent.Enabled and Entity.isAlive and bedwars.AbilityController:canUseAbility(\"void_axe_jump\", {disableBlockedAbilityAlert = true}) then\n\t        bedwars.VoidAxeController:useVoidAxe()\n\t    end\n\tend\n\t\n\tAutoVoidRegent = vape.Categories.Kits:CreateModule({\n\t    Name = \"AutoVoidRegent\",\n\t    Function = function(Callback: boolean)\n\t        if Callback then\n\t            NextSlam = 0\n\t\n\t            AutoVoidRegent:Clean(RunService.Heartbeat:Connect(function()\n\t                if not Entity.isAlive or store.equippedKit ~= \"regent\" or tick() < NextSlam or not bedwars.VoidAxeController then\n\t                    return\n\t                end\n\t\n\t                local Root: BasePart = Entity.character.RootPart\n\t                if Root.AssemblyLinearVelocity.Y > -FallSpeed.Value then\n\t                    return\n\t                end\n\t                if not bedwars.AbilityController:canUseAbility(\"void_axe_jump\", {disableBlockedAbilityAlert = true}) then\n\t                    return\n\t                end\n\t                if not Entity.Raycast(Root.Position, Vector3.new(0, -Height.Value, 0), store.airRay) then\n\t                    return\n\t                end\n\t\n\t                local Axe\n\t                if store.hand.tool and store.hand.tool.Name == \"void_axe\" then\n\t                    Axe = store.hand\n\t                elseif not LimitItem.Enabled then\n\t                    Axe = getItem(\"void_axe\")\n\t                end\n\t                if not Axe then\n\t                    return\n\t                end\n\t\n\t                NextSlam = tick() + bedwars.VoidRegentBalance.AXE_COOLDOWN\n\t                task.spawn(Slam, Axe)\n\t            end))\n\t        end\n\t    end,\n\t    Tooltip = \"Slams the void axe down right before you land\"\n\t})\n\t\n\tHeight = AutoVoidRegent:CreateSlider({\n\t    Name = \"Height\",\n\t    Min = 3,\n\t    Max = 60,\n\t    Default = 15,\n\t    Suffix = function(Val: number)\n\t        return Val <= 1 and \"stud\" or \"studs\"\n\t    end,\n\t    Tooltip = \"Slams once the ground is this close beneath you\"\n\t})\n\tFallSpeed = AutoVoidRegent:CreateSlider({\n\t    Name = \"Fall speed\",\n\t    Min = 0,\n\t    Max = 100,\n\t    Default = 10,\n\t    Tooltip = \"Only slams once you are dropping this fast\"\n\t})\n\tSwitch = AutoVoidRegent:CreateToggle({\n\t    Name = \"Legit switch\",\n\t    Function = function(Callback: boolean)\n\t        if SwitchDelay.Object then\n\t            SwitchDelay.Object.Visible = Callback\n\t        end\n\t    end,\n\t    Tooltip = \"Takes the axe out through the hotbar instead of silently\"\n\t})\n\tSwitchDelay = AutoVoidRegent:CreateSlider({\n\t    Name = \"Switch delay\",\n\t    Min = 0,\n\t    Max = 1,\n\t    Decimal = 100,\n\t    Default = 0.05,\n\t    Darker = true,\n\t    Visible = false,\n\t    Suffix = \"seconds\"\n\t})\n\tLimitItem = AutoVoidRegent:CreateToggle({\n\t    Name = \"Limit to items\",\n\t    Tooltip = \"Only slams while the axe is already held\"\n\t})\nend)\n\nRun(function()\n\tlocal AutoWarden\n\tlocal Range\n\t\n\tlocal Collected = setmetatable({}, {__mode = \"k\"})\n\t\n\tAutoWarden = vape.Categories.Kits:CreateModule({\n\t    Name = \"AutoWarden\",\n\t    Function = function(Callback: boolean)\n\t        if Callback then\n\t            table.clear(Collected)\n\t\n\t            repeat\n\t                if Entity.isAlive and Store.equippedKit == \"jailor\" then\n\t                    local Origin: Vector3 = Entity.character.RootPart.Position\n\t                    for _, v: Model in CollectionService:GetTagged(\"jailor_soul\") do\n\t                        if not Collected[v] and v.PrimaryPart and (v.PrimaryPart.Position - Origin).Magnitude <= Range.Value then\n\t                            Collected[v] = true\n\t                            bedwars.JailorController:collectEntity(LocalPlayer, v, v.Name)\n\t                        end\n\t                    end\n\t                end\n\t                task.wait(0.1)\n\t            until not AutoWarden.Enabled\n\t        end\n\t    end,\n\t    Tooltip = \"Automatically imprisons the souls dropped by enemies you kill\"\n\t})\n\t\n\tRange = AutoWarden:CreateSlider({\n\t    Name = \"Range\",\n\t    Min = 1,\n\t    Max = 60,\n\t    Default = 25,\n\t    Suffix = function(Val: number)\n\t        return Val <= 1 and \"stud\" or \"studs\"\n\t    end\n\t})\nend)\n\nRun(function()\n\tlocal AutoWarrior\n\tlocal Targets\n\tlocal Range\n\tlocal Amount\n\t\n\tAutoWarrior = vape.Categories.Kits:CreateModule({\n\t    Name = \"AutoWarrior\",\n\t    Function = function(Callback: boolean)\n\t        if Callback then\n\t            repeat\n\t                if Entity.isAlive and Store.equippedKit == \"warrior\" and bedwars.AbilityController:canUseAbility(\"warrior_strike\", {disableBlockedAbilityAlert = true}) then\n\t                    local Found: number = #Entity.AllPosition({\n\t                        Range = Range.Value,\n\t                        Part = \"RootPart\",\n\t                        Players = Targets.Players.Enabled,\n\t                        NPCs = Targets.NPCs.Enabled,\n\t                        Wallcheck = Targets.Walls.Enabled\n\t                    })\n\t\n\t                    if Found >= Amount.Value then\n\t                        bedwars.AbilityController:useAbility(\"warrior_strike\")\n\t                    end\n\t                end\n\t                task.wait(0.1)\n\t            until not AutoWarrior.Enabled\n\t        end\n\t    end,\n\t    Tooltip = \"Automatically uses Warriors Strike once enough enemies are next to you\"\n\t})\n\t\n\tTargets = AutoWarrior:CreateTargets({\n\t    Players = true,\n\t    NPCs = true,\n\t    Walls = true\n\t})\n\tRange = AutoWarrior:CreateSlider({\n\t    Name = \"Range\",\n\t    Min = 1,\n\t    Max = 40,\n\t    Default = 14,\n\t    Suffix = function(Val: number)\n\t        return Val <= 1 and \"stud\" or \"studs\"\n\t    end\n\t})\n\tAmount = AutoWarrior:CreateSlider({\n\t    Name = \"Targets\",\n\t    Min = 1,\n\t    Max = 8,\n\t    Default = 1,\n\t    Tooltip = \"Enemies in range before striking\"\n\t})\nend)\n\nRun(function()\n\tlocal AutoWhim\n\tlocal Targets\n\tlocal Range\n\tlocal FireRate\n\tlocal SwitchDelay\n\tlocal NextFire: number = 0\n\t\n\tlocal function CastSpell()\n\t    local Item = GetItem(\"mage_spellbook\")\n\t    local Util = bedwars.MageKitUtil\n\t    local Element: string? = bedwars.BalanceFile.MAGE_ELEMENT_CYCLE[(LocalPlayer:GetAttribute(\"MageElementIndex\") or 0) + 1]\n\t    if not Element or table.find(Util.getUnlockedMageElements(LocalPlayer), Element) == nil then\n\t        Element = \"BASE\"\n\t    end\n\t\n\t    local Meta = Util.MageElementMeta[Element]\n\t    local Source = Item and Meta and Meta.projectileSource or nil\n\t    local Target = Source and GetFacingEntity({\n\t        Part = \"RootPart\",\n\t        Range = Range.Value,\n\t        Players = Targets.Players.Enabled,\n\t        NPCs = Targets.NPCs.Enabled,\n\t        Priority = Targets.Priority.Value,\n\t        Wallcheck = Targets.Walls.Enabled,\n\t        Limit = 10\n\t    }) or nil\n\t    if not Target then\n\t        return\n\t    end\n\t\n\t    local Hotbar = Store.hand.tool and GetHotbar(Store.hand.tool) or nil\n\t    if HotbarSwitch(GetHotbar(Item.tool)) then\n\t        task.wait(Store.ping.total or 0)\n\t        if FireProjectile(Item, \"mage_spellbook\", Source.projectileType(\"mage_spellbook\"), Target) then\n\t            NextFire = tick() + Source.fireDelaySec + FireRate:GetRandomValue()\n\t            task.wait(SwitchDelay.Value)\n\t        end\n\t        HotbarSwitch(Hotbar)\n\t    end\n\tend\n\t\n\tAutoWhim = vape.Categories.Kits:CreateModule({\n\t    Name = \"AutoWhim\",\n\t    Function = function(Callback: boolean)\n\t        if Callback then\n\t            NextFire = 0\n\t\n\t            repeat\n\t                if Entity.isAlive and Store.equippedKit == \"mage\" and Store.hand.toolType == \"sword\" and (tick() - bedwars.SwordController.lastSwing) < 0.2 and tick() >= NextFire then\n\t                    CastSpell()\n\t                end\n\t                task.wait(0.1)\n\t            until not AutoWhim.Enabled\n\t        end\n\t    end,\n\t    Tooltip = \"Automatically casts Whim's magic book at whoever you're meleeing\"\n\t})\n\t\n\tTargets = AutoWhim:CreateTargets({\n\t    Players = true,\n\t    NPCs = false\n\t})\n\tRange = AutoWhim:CreateSlider({\n\t    Name = \"Range\",\n\t    Min = 1,\n\t    Max = 60,\n\t    Default = 22,\n\t    Suffix = function(Val: number)\n\t        return Val <= 1 and \"stud\" or \"studs\"\n\t    end\n\t})\n\tFireRate = AutoWhim:CreateTwoSlider({\n\t    Name = \"Fire Rate\",\n\t    Min = 0,\n\t    Max = 1,\n\t    DefaultMin = 0.05,\n\t    DefaultMax = 0.12,\n\t    Decimal = 100\n\t})\n\tSwitchDelay = AutoWhim:CreateSlider({\n\t    Name = \"Switch Delay\",\n\t    Min = 0,\n\t    Max = 1,\n\t    Decimal = 100,\n\t    Suffix = \"seconds\",\n\t    Default = 0.02\n\t})\nend)\n\nRun(function()\n\tlocal AutoWhimElement\n\tlocal Range\n\tlocal Delay\n\tlocal Notify\n\tlocal Attempts: {[string]: number} = {}\n\t\n\tlocal function LearnTome(Tome: Instance)\n\t    local Secret = Tome:GetAttribute(\"TomeSecret\")\n\t    if not Secret or (Attempts[Secret] or 0) > tick() then\n\t        return\n\t    end\n\t\n\t    Attempts[Secret] = tick() + 3\n\t    local Result = bedwars.Handler:Get(\"LearnElementTome\"):Fire(\"CallServer\", {secret = Secret})\n\t    if typeof(Result) ~= \"table\" or not Result.element then\n\t        return\n\t    end\n\t\n\t    local Element = Result.element\n\t    pcall(function()\n\t        bedwars.MageController:destroyTomeGuidingBeam()\n\t        bedwars.MageController:playLearnTomeEffect(LocalPlayer, Tome, Element)\n\t    end)\n\t\n\t    task.delay(bedwars.BalanceFile.LEARN_TOME_DURATION or 2, function()\n\t        pcall(function()\n\t            bedwars.MageController:fadeOutTome(Tome)\n\t            if LocalPlayer.Character then\n\t                bedwars.MageKitUtil.changeMageKitAppearance(LocalPlayer, LocalPlayer.Character, Element)\n\t            end\n\t        end)\n\t    end)\n\t    if Notify.Enabled then\n\t        notif(\"AutoWhimElement\", `Learned the {Result.element} element`, 5, \"info\")\n\t    end\n\tend\n\t\n\tAutoWhimElement = vape.Categories.Kits:CreateModule({\n\t    Name = \"AutoWhimElement\",\n\t    Function = function(Callback: boolean)\n\t        if Callback then\n\t            table.clear(Attempts)\n\t\n\t            repeat\n\t                if Entity.isAlive and store.equippedKit == \"mage\" then\n\t                    local LocalPosition: Vector3 = Entity.character.RootPart.Position\n\t\n\t                    for _, v: Instance in CollectionService:GetTagged(\"ElementTome\") do\n\t                        local Part = v.Parent and (not v:IsA(\"Model\") and v or (v.PrimaryPart or v:FindFirstChildWhichIsA(\"BasePart\", true)))\n\t                        if Part and (Part.Position - LocalPosition).Magnitude <= Range.Value then\n\t                            LearnTome(v)\n\t                        end\n\t                    end\n\t                end\n\t                task.wait(Delay.Value)\n\t            until not AutoWhimElement.Enabled\n\t        else\n\t            table.clear(Attempts)\n\t        end\n\t    end,\n\t    Tooltip = \"Reads every Tome of the Elements it can reach so Whim unlocks its spells\"\n\t})\n\t\n\tRange = AutoWhimElement:CreateSlider({\n\t    Name = \"Range\",\n\t    Min = 1,\n\t    Max = 500,\n\t    Default = 10,\n\t    Suffix = function(Val: number)\n\t        return Val <= 1 and \"stud\" or \"studs\"\n\t    end,\n\t    Tooltip = \"The prompt the game gives you stops at 10 studs\"\n\t})\n\tDelay = AutoWhimElement:CreateSlider({\n\t    Name = \"Delay\",\n\t    Min = 0.1,\n\t    Max = 5,\n\t    Decimal = 10,\n\t    Default = 0.5,\n\t    Suffix = \"seconds\",\n\t    Tooltip = \"How often it looks for a tome\"\n\t})\n\tNotify = AutoWhimElement:CreateToggle({\n\t    Name = \"Notify\",\n\t    Default = true,\n\t    Tooltip = \"Tells you which element you picked up\"\n\t})\nend)\n\nRun(function()\n\tlocal AutoWhisper\n\tlocal Heal\n\tlocal Threshold\n\tlocal Fly\n\tlocal Owl\n\tlocal Target\n\tlocal FOVCheck\n\tlocal FOV\n\tlocal RangeCircle\n\tlocal CircleColor\n\tlocal CircleTransparency\n\tlocal CircleThickness\n\tlocal CircleFilled\n\tlocal CircleObject\n\t\n\tlocal Teammates: {string} = {\"None\"}\n\tlocal Old\n\tlocal MapBottom: number = math.huge\n\tlocal FallDepth: number = 12\n\tlocal FootingCharacter, FootingY = nil, -math.huge\n\t\n\tlocal Success, OwlBalance = pcall(function()\n\t    return require(ReplicatedStorage.TS.balance[\"owl-balance-file\"]).OwlBalance\n\tend)\n\tlocal AttachRange: number = Success and OwlBalance.OWL_ATTACH_MAX_RANGE or 60\n\t\n\tlocal function GetMouseOrigin()\n\t    return UserInputService.TouchEnabled and Camera.ViewportSize / 2 or UserInputService:GetMouseLocation()\n\tend\n\t\n\tlocal function GetOwlTarget(): Player?\n\t    local Picked: Player? = Players:FindFirstChild(Target.Value)\n\t    if not FOVCheck.Enabled then\n\t        return Picked\n\t    end\n\t\n\t    if not Entity.isAlive then\n\t        return nil\n\t    end\n\t\n\t    local Origin: Vector2 = GetMouseOrigin()\n\t    local Best, BestDistance = nil, FOV.Value\n\t    for _, v: Player in (Picked and {Picked} or Players:GetPlayers()) do\n\t        local Character: Model? = v.Character\n\t        local Root: BasePart? = Character and Character:FindFirstChild(\"HumanoidRootPart\")\n\t        if v == LocalPlayer or not Root or v:GetAttribute(\"Team\") ~= LocalPlayer:GetAttribute(\"Team\") or v:GetAttribute(\"IsOwlTarget\") then\n\t            continue\n\t        end\n\t\n\t        if (Root.Position - Entity.character.RootPart.Position).Magnitude > AttachRange then\n\t            continue\n\t        end\n\t\n\t        local Position, Visible = Camera:WorldToViewportPoint(Root.Position)\n\t        local Distance: number = (Vector2.new(Position.X, Position.Y) - Origin).Magnitude\n\t        if Visible and Distance <= BestDistance then\n\t            Best, BestDistance = v, Distance\n\t        end\n\t    end\n\t\n\t    return Best\n\tend\n\t\n\tlocal function RefreshOptions()\n\t    local ShowFOV: boolean = Owl.Enabled and FOVCheck.Enabled\n\t    local ShowCircle: boolean = ShowFOV and RangeCircle.Enabled\n\t\n\t    Target.Object.Visible = Owl.Enabled\n\t    FOVCheck.Object.Visible = Owl.Enabled\n\t    FOV.Object.Visible = ShowFOV\n\t    RangeCircle.Object.Visible = ShowFOV\n\t    CircleColor.Object.Visible = ShowCircle\n\t    CircleTransparency.Object.Visible = ShowCircle\n\t    CircleThickness.Object.Visible = ShowCircle\n\t    CircleFilled.Object.Visible = ShowCircle\n\t\n\t    if CircleObject then\n\t        CircleObject.Visible = AutoWhisper.Enabled and ShowFOV\n\t    end\n\tend\n\t\n\tlocal function GetAttachedCharacter(): Model?\n\t    local Attached: Instance? = bedwars.OwlAbilityController.target\n\t    if Attached and Attached:IsA(\"Player\") then\n\t        return Attached.Character\n\t    end\n\t    return Attached :: Model?\n\tend\n\t\n\tlocal function GetMapBottom(): number\n\t    if MapBottom == math.huge then\n\t        for _, v: BasePart in Store.blocks do\n\t            MapBottom = math.min(MapBottom, v.Position.Y - (v.Size.Y / 2))\n\t        end\n\t    end\n\t    return MapBottom == math.huge and -math.huge or MapBottom\n\tend\n\t\n\tlocal function CanUse(Ability: string): boolean\n\t    return bedwars.AbilityController:getEnabledAbility(Ability) ~= nil and bedwars.AbilityController:canUseAbility(Ability, {disableBlockedAbilityAlert = true})\n\tend\n\t\n\tlocal function AddConnection(TargetPlayer: Player, Connected: boolean?)\n\t    if not Connected then\n\t        vape:Clean(TargetPlayer:GetAttributeChangedSignal(\"Team\"):Connect(function()\n\t            AddConnection(TargetPlayer, true)\n\t        end))\n\t    end\n\t\n\t    if TargetPlayer ~= LocalPlayer and TargetPlayer:GetAttribute(\"Team\") == LocalPlayer:GetAttribute(\"Team\") and not table.find(Teammates, TargetPlayer.Name) then\n\t        table.insert(Teammates, TargetPlayer.Name)\n\t        Target:Change(Teammates)\n\t    end\n\tend\n\t\n\tAutoWhisper = vape.Categories.Kits:CreateModule({\n\t    Name = \"AutoWhisper\",\n\t    Function = function(Callback: boolean)\n\t        if CircleObject then\n\t            CircleObject.Visible = Callback and Owl.Enabled and FOVCheck.Enabled\n\t        end\n\t\n\t        if Callback then\n\t            AutoWhisper:Clean(RunService.RenderStepped:Connect(function()\n\t                if CircleObject then\n\t                    CircleObject.Position = GetMouseOrigin()\n\t                end\n\t            end))\n\t\n\t            Old = bedwars.OwlKitController.onAbilityUsed\n\t            bedwars.OwlKitController.onAbilityUsed = function(self, Character, Data, ...)\n\t                if Owl.Enabled and Data and Data.ability == \"SUMMON_OWL\" and Character == LocalPlayer.Character then\n\t                    local TargetPlayer: Player? = GetOwlTarget()\n\t                    if TargetPlayer and TargetPlayer ~= LocalPlayer then\n\t                        bedwars.Handler:Get(\"SummonOwl\"):Fire(\"CallServer\", TargetPlayer)\n\t                        return\n\t                    end\n\t                end\n\t                return Old(self, Character, Data, ...)\n\t            end\n\t\n\t            repeat\n\t                task.wait()\n\t            until Store.matchState ~= 0 or not AutoWhisper.Enabled\n\t            if not AutoWhisper.Enabled then\n\t                return\n\t            end\n\t\n\t            repeat\n\t                if Owl.Enabled and not bedwars.OwlAbilityController.target and GetOwlTarget() and bedwars.AbilityController:canUseAbility(\"SUMMON_OWL\", {disableBlockedAbilityAlert = true}) then\n\t                    bedwars.AbilityController:useAbility(\"SUMMON_OWL\")\n\t                end\n\t\n\t                local Character: Model? = GetAttachedCharacter()\n\t                if Character then\n\t                    local Root: BasePart? = Character.PrimaryPart\n\t                    if Root then\n\t                        if FootingCharacter ~= Character then\n\t                            FootingCharacter, FootingY = Character, GetMapBottom() + FallDepth\n\t                        end\n\t                        if math.abs(Root.AssemblyLinearVelocity.Y) < 2 then\n\t                            FootingY = Root.Position.Y\n\t                        end\n\t\n\t                        if Fly.Enabled and Root.Position.Y < FootingY - FallDepth and CanUse(\"OWL_LIFT\") then\n\t                            bedwars.AbilityController:useAbility(\"OWL_LIFT\")\n\t                        end\n\t                    end\n\t\n\t                    local Health: number? = Character:GetAttribute(\"Health\")\n\t                    local MaxHealth: number? = Character:GetAttribute(\"MaxHealth\")\n\t                    if Heal.Enabled and (Threshold.Value >= 100 or Health and MaxHealth and MaxHealth > 0 and Health / MaxHealth <= Threshold.Value / 100) and CanUse(\"OWL_HEAL\") then\n\t                        bedwars.AbilityController:useAbility(\"OWL_HEAL\")\n\t                    end\n\t                end\n\t                task.wait(0.1)\n\t            until not AutoWhisper.Enabled\n\t        elseif Old then\n\t            bedwars.OwlKitController.onAbilityUsed = Old\n\t            Old = nil\n\t        end\n\t    end,\n\t    Tooltip = \"Automatically uses whisper abilities\"\n\t})\n\t\n\tHeal = AutoWhisper:CreateToggle({\n\t    Name = \"Heal\",\n\t    Function = function(Callback: boolean)\n\t        if Threshold then\n\t            Threshold.Object.Visible = Callback\n\t        end\n\t    end,\n\t    Default = true\n\t})\n\tThreshold = AutoWhisper:CreateSlider({\n\t    Name = \"Health\",\n\t    Min = 1,\n\t    Max = 100,\n\t    Default = 99,\n\t    Darker = true,\n\t    Suffix = \"%\"\n\t})\n\tFly = AutoWhisper:CreateToggle({\n\t    Name = \"Fly\",\n\t    Default = true,\n\t    Tooltip = \"Lifts the player your owl is on once they fall well below where they last stood over the void, so it never fires on normal jumps or while bridging\"\n\t})\n\tOwl = AutoWhisper:CreateToggle({\n\t    Name = \"Auto owl\",\n\t    Function = RefreshOptions,\n\t    Tooltip = \"Sends the owl to the teammate you pick as soon as the ability is up\"\n\t})\n\tTarget = AutoWhisper:CreateDropdown({\n\t    Name = \"Teammate\",\n\t    List = Teammates,\n\t    Darker = true,\n\t    Visible = false,\n\t    Tooltip = \"Who the owl gets summoned onto\"\n\t})\n\tFOVCheck = AutoWhisper:CreateToggle({\n\t    Name = \"FOV check\",\n\t    Function = RefreshOptions,\n\t    Darker = true,\n\t    Visible = false,\n\t    Tooltip = \"Only sends the owl to a teammate inside the FOV around your mouse, within owl range and without an owl already\\nWith Teammate on None it picks whoever is closest to your mouse\"\n\t})\n\tFOV = AutoWhisper:CreateSlider({\n\t    Name = \"FOV\",\n\t    Min = 1,\n\t    Max = 1000,\n\t    Function = function(Val: number)\n\t        if CircleObject then\n\t            CircleObject.Radius = Val\n\t        end\n\t    end,\n\t    Darker = true,\n\t    Default = 150,\n\t    Visible = false\n\t})\n\tRangeCircle = AutoWhisper:CreateToggle({\n\t    Name = \"Range Circle\",\n\t    Function = function(Callback: boolean)\n\t        if Callback then\n\t            CircleObject = Drawing.new(\"Circle\")\n\t            CircleObject.Filled = CircleFilled.Enabled\n\t            CircleObject.Color = Color3.fromHSV(CircleColor.Hue, CircleColor.Sat, CircleColor.Value)\n\t            CircleObject.Position = GetMouseOrigin()\n\t            CircleObject.Radius = FOV.Value\n\t            CircleObject.NumSides = 100\n\t            CircleObject.Thickness = CircleThickness.Value\n\t            CircleObject.Transparency = 1 - CircleTransparency.Value\n\t        else\n\t            pcall(function()\n\t                CircleObject.Visible = false\n\t                CircleObject:Remove()\n\t            end)\n\t            CircleObject = nil\n\t        end\n\t        RefreshOptions()\n\t    end,\n\t    Darker = true,\n\t    Visible = false\n\t})\n\tCircleColor = AutoWhisper:CreateColorSlider({\n\t    Name = \"Circle Color\",\n\t    Function = function(Hue: number, Sat: number, Val: number)\n\t        if CircleObject then\n\t            CircleObject.Color = Color3.fromHSV(Hue, Sat, Val)\n\t        end\n\t    end,\n\t    Darker = true,\n\t    Visible = false\n\t})\n\tCircleTransparency = AutoWhisper:CreateSlider({\n\t    Name = \"Transparency\",\n\t    Min = 0,\n\t    Max = 1,\n\t    Decimal = 10,\n\t    Function = function(Val: number)\n\t        if CircleObject then\n\t            CircleObject.Transparency = 1 - Val\n\t        end\n\t    end,\n\t    Darker = true,\n\t    Default = 0.5,\n\t    Visible = false\n\t})\n\tCircleThickness = AutoWhisper:CreateSlider({\n\t    Name = \"Thickness\",\n\t    Min = 1,\n\t    Max = 10,\n\t    Decimal = 10,\n\t    Function = function(Val: number)\n\t        if CircleObject then\n\t            CircleObject.Thickness = Val\n\t        end\n\t    end,\n\t    Darker = true,\n\t    Default = 1,\n\t    Visible = false,\n\t    Tooltip = \"How wide the circle's outline is, has no effect while Circle Filled is on\"\n\t})\n\tCircleFilled = AutoWhisper:CreateToggle({\n\t    Name = \"Circle Filled\",\n\t    Function = function(Callback: boolean)\n\t        if CircleObject then\n\t            CircleObject.Filled = Callback\n\t        end\n\t    end,\n\t    Darker = true,\n\t    Visible = false\n\t})\n\t\n\tfor _, v: Player in Players:GetPlayers() do\n\t    AddConnection(v)\n\tend\n\tvape:Clean(Players.PlayerAdded:Connect(AddConnection))\nend)\n\nRun(function()\n\tlocal AutoXurot\n\tlocal Range\n\tlocal Delay\n\tlocal DragonForm: boolean = false\n\tlocal NextBreath: number = 0\n\t\n\tlocal Breath = bedwars.Handler:Get(\"DragonBreath\")\n\t\n\tlocal function IsLocal(Data)\n\t    if type(Data) ~= \"table\" then\n\t        return true\n\t    end\n\t    return Data.player == nil or Data.player == LocalPlayer\n\tend\n\t\n\tAutoXurot = vape.Categories.Kits:CreateModule({\n\t    Name = \"AutoXurot\",\n\t    Function = function(Callback: boolean)\n\t        if Callback then\n\t            DragonForm, NextBreath = false, 0\n\t\n\t            local Action = bedwars.Handler:Get(\"VoidDragonAction\")\n\t            if Action.Remote then\n\t                AutoXurot:Clean(Action.Remote:Connect(function(Data)\n\t                    if IsLocal(Data) then\n\t                        if Data.action == \"transform\" then\n\t                            DragonForm = true\n\t                        elseif Data.action == \"dragon_deactive\" then\n\t                            DragonForm = false\n\t                        end\n\t                    end\n\t                end))\n\t            end\n\t\n\t            local Deactivate = bedwars.Handler:Get(\"VoidDragonDeactive\")\n\t            if Deactivate.Remote then\n\t                AutoXurot:Clean(Deactivate.Remote:Connect(function(Data)\n\t                    if IsLocal(Data) then\n\t                        DragonForm = false\n\t                    end\n\t                end))\n\t            end\n\t\n\t            AutoXurot:Clean(LocalPlayer.CharacterAdded:Connect(function()\n\t                DragonForm = false\n\t            end))\n\t\n\t            repeat\n\t                if DragonForm and Entity.isAlive and Store.equippedKit == \"void_dragon\" and tick() >= NextBreath then\n\t                    local Target = Entity.EntityPosition({\n\t                        Origin = Entity.character.RootPart.Position,\n\t                        Range = Range.Value,\n\t                        Part = \"RootPart\",\n\t                        Players = true,\n\t                        Wallcheck = true\n\t                    })\n\t\n\t                    if Target then\n\t                        NextBreath = tick() + Delay.Value\n\t                        Breath:Fire(\"SendToServer\", {player = LocalPlayer, targetPoint = Target.RootPart.Position})\n\t                    end\n\t                end\n\t                task.wait(0.05)\n\t            until not AutoXurot.Enabled\n\t        end\n\t    end,\n\t    Tooltip = \"Automatically breathes on enemies while you are in dragon form\"\n\t})\n\t\n\tRange = AutoXurot:CreateSlider({\n\t    Name = \"Range\",\n\t    Min = 1,\n\t    Max = 200,\n\t    Default = 120,\n\t    Suffix = function(Val: number)\n\t        return Val <= 1 and \"stud\" or \"studs\"\n\t    end\n\t})\n\tDelay = AutoXurot:CreateSlider({\n\t    Name = \"Delay\",\n\t    Min = 0.1,\n\t    Max = 3,\n\t    Default = 0.5,\n\t    Decimal = 10,\n\t    Suffix = function(Val: number)\n\t        return Val <= 1 and \"sec\" or \"secs\"\n\t    end\n\t})\nend)\n\nRun(function()\n\tlocal AutoYeti\n\tlocal Range\n\tlocal Targets\n\t\n\tAutoYeti = vape.Categories.Kits:CreateModule({\n\t    Name = \"AutoYeti\",\n\t    Function = function(Callback: boolean)\n\t        if Callback then\n\t            repeat\n\t                if Entity.isAlive and Store.equippedKit == \"yeti\" and bedwars.AbilityController:canUseAbility(\"yeti_glacial_roar\", {disableBlockedAbilityAlert = true}) then\n\t                    local Origin: Vector3 = Entity.character.RootPart.Position\n\t                    local Found: number = 0\n\t                    for _, v: any in Entity.List do\n\t                        if v.Targetable and (v.RootPart.Position - Origin).Magnitude <= Range.Value then\n\t                            Found += 1\n\t                        end\n\t                    end\n\t\n\t                    if Found >= Targets.Value then\n\t                        bedwars.AbilityController:useAbility(\"yeti_glacial_roar\")\n\t                    end\n\t                end\n\t                task.wait(0.1)\n\t            until not AutoYeti.Enabled\n\t        end\n\t    end,\n\t    Tooltip = \"Automatically roars once enough enemies are around you\"\n\t})\n\t\n\tRange = AutoYeti:CreateSlider({\n\t    Name = \"Range\",\n\t    Min = 1,\n\t    Max = 60,\n\t    Default = 30,\n\t    Suffix = function(Val: number)\n\t        return Val <= 1 and \"stud\" or \"studs\"\n\t    end\n\t})\n\tTargets = AutoYeti:CreateSlider({\n\t    Name = \"Targets\",\n\t    Min = 1,\n\t    Max = 8,\n\t    Default = 1,\n\t    Tooltip = \"Enemies in range before roaring\"\n\t})\nend)\n\nRun(function()\n\tlocal AutoZeno\n\tlocal Targets\n\tlocal TargetMode\n\tlocal Limit\n\tlocal AFKCheck\n\tlocal AutoShockWave\n\tlocal ShockwaveRange\n\tlocal UseStrike\n\tlocal UseStorm\n\tlocal Range\n\tlocal Delay\n\t\n\tlocal function GetAttackData()\n\t    if Limit.Enabled then\n\t        local Tool: Tool? = Store.hand.tool\n\t        local ItemType: string? = Tool and Tool.Name\n\t        if ItemType and bedwars.WizardUtil:isWizardStaff(ItemType) then\n\t            return Tool, ItemType\n\t        end\n\t        return nil\n\t    end\n\t\n\t    for _, v: any in Store.inventory.inventory.items do\n\t        if bedwars.WizardUtil:isWizardStaff(v.itemType) and v.tool then\n\t            SwitchItem(v.tool, 0)\n\t            return v.tool, v.itemType\n\t        end\n\t    end\n\t\n\t    return nil\n\tend\n\t\n\tAutoZeno = vape.Categories.Kits:CreateModule({\n\t    Name = \"AutoZeno\",\n\t    Function = function(Callback: boolean)\n\t        if Callback then\n\t            local Attempts: {[string]: number} = {}\n\t            repeat\n\t                if Entity.isAlive and not (AFKCheck.Enabled and IsAfk()) then\n\t                    local Staff, ItemType = GetAttackData()\n\t                    if Staff and ItemType then\n\t                        local LocalPosition: Vector3 = Entity.character.RootPart.Position\n\t                        local CastRange: number = math.min(Range.Value, bedwars.WizardUtil:getCastRange(ItemType))\n\t                        local Shockwave: boolean = AutoShockWave.Enabled and bedwars.WizardUtil:hasAbility(ItemType, \"SHOCKWAVE\")\n\t                        local Ent = Entity.EntityPosition({\n\t                            Origin = LocalPosition,\n\t                            Range = math.max(CastRange, Shockwave and ShockwaveRange.Value or 0),\n\t                            Part = \"RootPart\",\n\t                            Players = Targets.Players.Enabled,\n\t                            NPCs = Targets.NPCs.Enabled,\n\t                            Priority = Targets.Priority.Value,\n\t                            Sort = SortMethods[TargetMode.Value]\n\t                        })\n\t\n\t                        if Ent then\n\t                            local Distance: number = (LocalPosition - Ent.RootPart.Position).Magnitude\n\t                            local TargetPosition: Vector3 = Ent.RootPart.Position + ((Ent.Humanoid.MoveDirection or Vector3.zero) * (1 + LocalPlayer:GetNetworkPing()))\n\t                            local Abilities = {\n\t                                {\"LIGHTNING_STORM\", UseStorm.Enabled and Distance <= CastRange},\n\t                                {\"SHOCKWAVE\", Shockwave and Distance <= ShockwaveRange.Value},\n\t                                {\"LIGHTNING_STRIKE\", UseStrike.Enabled and Distance <= CastRange}\n\t                            }\n\t\n\t                            for _, v: any in Abilities do\n\t                                if not v[2] or (Attempts[v[1]] or 0) > tick() then\n\t                                    continue\n\t                                end\n\t                                if not bedwars.WizardUtil:hasAbility(ItemType, v[1]) then\n\t                                    continue\n\t                                end\n\t\n\t                                local Controller = bedwars.WizardStaffController\n\t                                if not Controller then\n\t                                    continue\n\t                                end\n\t\n\t                                local Success, Allowed = pcall(Controller.canCastAbility, Controller, v[1])\n\t                                if not Success or not Allowed then\n\t                                    continue\n\t                                end\n\t                                Success, Allowed = pcall(bedwars.AbilityController.canUseAbility, bedwars.AbilityController, v[1], {disableBlockedAbilityAlert = true})\n\t                                if not Success or not Allowed then\n\t                                    continue\n\t                                end\n\t\n\t                                Attempts[v[1]] = tick() + math.max(Delay.Value, 0.25)\n\t                                if pcall(bedwars.AbilityController.useAbility, bedwars.AbilityController, v[1], newproxy(true), {target = v[1] == \"SHOCKWAVE\" and Vector3.zero or TargetPosition}) then\n\t                                    task.wait(Delay.Value)\n\t                                    break\n\t                                end\n\t                            end\n\t                        end\n\t                    end\n\t                end\n\t                task.wait(0.1)\n\t            until not AutoZeno.Enabled\n\t        end\n\t    end,\n\t    Tooltip = \"Automatically uses zeno's staff.\"\n\t})\n\t\n\tTargets = AutoZeno:CreateTargets({\n\t    Players = true,\n\t    NPCs = false\n\t})\n\tlocal Methods: {string} = {\"Damage\", \"Distance\"}\n\tfor _, v: string in SortList do\n\t    if not table.find(Methods, v) then\n\t        table.insert(Methods, v)\n\t    end\n\tend\n\tTargetMode = AutoZeno:CreateDropdown({\n\t    Name = \"Target Mode\",\n\t    List = Methods,\n\t    Default = \"Distance\"\n\t})\n\tLimit = AutoZeno:CreateToggle({\n\t    Name = \"Limit to item\",\n\t    Default = true\n\t})\n\tAFKCheck = AutoZeno:CreateToggle({\n\t    Name = \"AFK check\",\n\t    Tooltip = \"Stops casting once you have not touched your mouse or keyboard for 30 seconds\"\n\t})\n\tUseStrike = AutoZeno:CreateToggle({\n\t    Name = \"Use Lightning Strike\",\n\t    Default = true\n\t})\n\tUseStorm = AutoZeno:CreateToggle({Name = \"Use Lightning Storm\"})\n\tAutoShockWave = AutoZeno:CreateToggle({\n\t    Name = \"Auto Shockwave\",\n\t    Function = function(Callback: boolean)\n\t        if ShockwaveRange then\n\t            ShockwaveRange.Object.Visible = Callback\n\t        end\n\t    end,\n\t    Tooltip = \"Automatically uses the shockwave ability when a target is near\"\n\t})\n\tShockwaveRange = AutoZeno:CreateSlider({\n\t    Name = \"Shockwave Range\",\n\t    Min = 1,\n\t    Max = 12,\n\t    Decimal = 5,\n\t    Default = 12,\n\t    Darker = true,\n\t    Visible = false,\n\t    Suffix = function(Val: number)\n\t        return Val > 1 and \"studs\" or \"stud\"\n\t    end\n\t})\n\tRange = AutoZeno:CreateSlider({\n\t    Name = \"Range\",\n\t    Min = 1,\n\t    Max = 60,\n\t    Decimal = 5,\n\t    Default = 35,\n\t    Suffix = function(Val: number)\n\t        return Val > 1 and \"studs\" or \"stud\"\n\t    end\n\t})\n\tDelay = AutoZeno:CreateSlider({\n\t    Name = \"Delay\",\n\t    Min = 0,\n\t    Max = 10,\n\t    Decimal = 5,\n\t    Default = 0.5,\n\t    Suffix = function(Val: number)\n\t        return Val > 1 and \"secs\" or \"sec\"\n\t    end\n\t})\nend)\n\nRun(function()\n\tlocal AutoZephyr\n\tlocal Lead\n\t\n\tlocal TeleportLimits: {[string]: number} = {\n\t    Fly = 2,\n\t    InfiniteJump = 1.7\n\t}\n\t\n\tlocal function GetPullIn(): number?\n\t    local TPDown = vape.Modules.TPDown\n\t    if TPDown and TPDown.Enabled then\n\t        return TPDown.PullIn\n\t    end\n\t\n\t    local AirTime: number = tick() - (Entity.character.AirTime or tick())\n\t    for Name: string, Limit: number in TeleportLimits do\n\t        local Module = vape.Modules[Name]\n\t        local Option = Module and Module.Options[\"TP Down\"]\n\t        if Module and Module.Enabled and Option and Option.Enabled then\n\t            return Limit - AirTime\n\t        end\n\t    end\n\t    return nil\n\tend\n\t\n\tAutoZephyr = vape.Categories.Kits:CreateModule({\n\t    Name = \"AutoZephyr\",\n\t    Function = function(Callback: boolean)\n\t        if Callback then\n\t            local Humanoid: Humanoid? = nil\n\t            local StateConnection: RBXScriptConnection? = nil\n\t            local Used: number = 0\n\t            local NextJump: number = 0\n\t\n\t            AutoZephyr:Clean(function()\n\t                if StateConnection then\n\t                    StateConnection:Disconnect()\n\t                    StateConnection = nil\n\t                end\n\t            end)\n\t\n\t            AutoZephyr:Clean(RunService.PreSimulation:Connect(function()\n\t                if not Entity.isAlive or vape.MovementOwner then\n\t                    return\n\t                end\n\t\n\t                if Entity.character.Humanoid ~= Humanoid then\n\t                    if StateConnection then\n\t                        StateConnection:Disconnect()\n\t                    end\n\t                    Humanoid = Entity.character.Humanoid\n\t                    Used = 0\n\t                    StateConnection = Entity.character.Humanoid.StateChanged:Connect(function(Old: Enum.HumanoidStateType, New: Enum.HumanoidStateType)\n\t                        if New == Enum.HumanoidStateType.Landed then\n\t                            Used = 0\n\t                        elseif Old == Enum.HumanoidStateType.Freefall and New == Enum.HumanoidStateType.Jumping then\n\t                            Used += 1\n\t                        end\n\t                    end)\n\t                end\n\t\n\t                if Entity.character.Humanoid.FloorMaterial ~= Enum.Material.Air or NextJump > tick() then\n\t                    return\n\t                end\n\t\n\t                local Controller = bedwars.JumpHeightController\n\t                local Allowed: number = Controller and Controller.allowedAirJumps or 0\n\t                local PullIn: number? = GetPullIn()\n\t                if Used < Allowed and PullIn and PullIn <= Lead.Value then\n\t                    NextJump = tick() + 0.25\n\t                    bedwars.Handler:Get(\"NotifyAirJump\"):Fire()\n\t                    Entity.character.Humanoid:ChangeState(Enum.HumanoidStateType.Jumping)\n\t                    Entity.character.AirTime = tick()\n\t                end\n\t            end))\n\t        end\n\t    end,\n\t    Tooltip = \"Uses a Zephyr air jump right before TPDown, or the TP Down option of Fly or InfiniteJump, would pull you down, so you stay up instead. Needs Zephyr's air jumps (5 orbs)\"\n\t})\n\t\n\tLead = AutoZephyr:CreateSlider({\n\t    Name = \"Lead\",\n\t    Min = 0.05,\n\t    Max = 0.5,\n\t    Default = 0.15,\n\t    Decimal = 100,\n\t    Suffix = function(Val: number)\n\t        return Val == 1 and \"second\" or \"seconds\"\n\t    end,\n\t    Tooltip = \"How long before the pull down it jumps\"\n\t})\nend)\n\nRun(function()\n\tlocal AutoZola\n\tlocal Mode\n\tlocal Range\n\tlocal Links: {[Instance]: number} = {}\n\tlocal NextLink: number = 0\n\t\n\tlocal function IsLinked(Character: Model)\n\t    local Expiry: number? = Links[Character]\n\t    if Expiry and Expiry > tick() then\n\t        return true\n\t    end\n\t    Links[Character] = nil\n\t    return false\n\tend\n\t\n\tlocal function AttemptLink(Character: Model?)\n\t    if not Character or tick() < NextLink or IsLinked(Character) then\n\t        return\n\t    end\n\t    local Count: number = 0\n\t    for LinkedCharacter: Instance in Links do\n\t        if IsLinked(LinkedCharacter) then\n\t            Count += 1\n\t        end\n\t    end\n\t    if Count >= bedwars.SoulBrokerConstants.MAX_SOUL_LINKS then\n\t        return\n\t    end\n\t\n\t    Links[Character] = tick() + 1\n\t    NextLink = tick() + 1\n\t    bedwars.Handler:Get(\"AttemptSoulLink\"):Fire(\"CallServerAsync\", Character)\n\tend\n\t\n\tAutoZola = vape.Categories.Kits:CreateModule({\n\t    Name = \"AutoZola\",\n\t    Function = function(Callback: boolean)\n\t        if Callback then\n\t            AutoZola:Clean(bedwars.Handler:Get(\"SoulLinkFormed\").Remote:Connect(function(LinkTable)\n\t                if LinkTable.broker == LocalPlayer and not LinkTable.guard then\n\t                    Links[LinkTable.target] = tick() + bedwars.SoulBrokerConstants.SOUL_LINK_DURATION\n\t                end\n\t            end))\n\t\n\t            AutoZola:Clean(bedwars.Handler:Get(\"SoulLinkRemoved\").Remote:Connect(function(LinkTable)\n\t                if LinkTable.broker == LocalPlayer and not LinkTable.guard then\n\t                    Links[LinkTable.target] = nil\n\t                end\n\t            end))\n\t\n\t            AutoZola:Clean(VapeEvents.EntityDamageEvent.Event:Connect(function(DamageTable)\n\t                if Mode.Value ~= \"On Hit\" or DamageTable.fromEntity ~= LocalPlayer.Character then\n\t                    return\n\t                end\n\t                if not Entity.isAlive or Store.equippedKit ~= \"soul_broker\" then\n\t                    return\n\t                end\n\t\n\t                local Target = Entity.getEntity(DamageTable.entityInstance)\n\t                if Target and Target.Player and Target.Targetable and (Entity.character.RootPart.Position - Target.RootPart.Position).Magnitude <= Range.Value then\n\t                    AttemptLink(Target.Character)\n\t                end\n\t            end))\n\t\n\t            repeat\n\t                if Mode.Value == \"On See\" and tick() >= NextLink and Entity.isAlive and Store.equippedKit == \"soul_broker\" then\n\t                    for _, v: any in Entity.AllPosition({\n\t                        Range = Range.Value,\n\t                        Part = \"RootPart\",\n\t                        Players = true,\n\t                        Wallcheck = true\n\t                    }) do\n\t                        if not IsLinked(v.Character) then\n\t                            AttemptLink(v.Character)\n\t                            break\n\t                        end\n\t                    end\n\t                end\n\t                task.wait(0.1)\n\t            until not AutoZola.Enabled\n\t        end\n\t    end,\n\t    Tooltip = \"Automatically soul links enemies\"\n\t})\n\t\n\tMode = AutoZola:CreateDropdown({\n\t    Name = \"Mode\",\n\t    List = {\"On See\", \"On Hit\"},\n\t    Tooltip = \"On See - Links enemies as soon as you can see them\\nOn Hit - Links enemies whenever you hit them\",\n\t    Default = \"On See\"\n\t})\n\tRange = AutoZola:CreateSlider({\n\t    Name = \"Range\",\n\t    Min = 1,\n\t    Max = 50,\n\t    Default = 30,\n\t    Suffix = function(Val: number)\n\t        return Val <= 1 and \"stud\" or \"studs\"\n\t    end\n\t})\nend)\n\nRun(function()\n\tlocal CryptAura\n\tlocal Range\n\tlocal Delay\n\tlocal NextClaim: number = 0\n\t\n\tlocal Claimed = setmetatable({}, {__mode = \"k\"})\n\t\n\tlocal Activate = bedwars.Handler:Get(\"ActivateGravestone\")\n\t\n\tCryptAura = vape.Categories.Kits:CreateModule({\n\t    Name = \"CryptAura\",\n\t    Function = function(Callback: boolean)\n\t        if Callback then\n\t            NextClaim = 0\n\t            table.clear(Claimed)\n\t\n\t            repeat\n\t                if Entity.isAlive and Store.equippedKit == \"necromancer\" and tick() >= NextClaim then\n\t                    local Origin: Vector3 = Entity.character.RootPart.Position\n\t                    for _, v: Instance in CollectionService:GetTagged(\"Gravestone\") do\n\t                        if not Claimed[v] and v:GetAttribute(\"GravestoneSecret\") and (v:GetPivot().Position - Origin).Magnitude <= Range.Value then\n\t                            Claimed[v] = true\n\t                            NextClaim = tick() + Delay.Value\n\t                            Activate:Fire(\"CallServer\", {\n\t                                secret = v:GetAttribute(\"GravestoneSecret\"),\n\t                                position = v:GetAttribute(\"GravestonePosition\"),\n\t                                skeletonData = {\n\t                                    associatedPlayerUserId = v:GetAttribute(\"GravestonePlayerUserId\"),\n\t                                    armorType = v:GetAttribute(\"ArmorType\"),\n\t                                    weaponType = v:GetAttribute(\"SwordType\"),\n\t                                    bowType = v:GetAttribute(\"BowType\")\n\t                                }\n\t                            })\n\t                            break\n\t                        end\n\t                    end\n\t                end\n\t                task.wait(0.1)\n\t            until not CryptAura.Enabled\n\t        end\n\t    end,\n\t    Tooltip = \"Automatically claims the gravestones enemies drop into your undead army\"\n\t})\n\t\n\tRange = CryptAura:CreateSlider({\n\t    Name = \"Range\",\n\t    Min = 1,\n\t    Max = 40,\n\t    Default = 12,\n\t    Suffix = function(Val: number)\n\t        return Val <= 1 and \"stud\" or \"studs\"\n\t    end\n\t})\n\tDelay = CryptAura:CreateSlider({\n\t    Name = \"Delay\",\n\t    Min = 0.1,\n\t    Max = 3,\n\t    Default = 0.3,\n\t    Decimal = 10,\n\t    Suffix = function(Val: number)\n\t        return Val <= 1 and \"sec\" or \"secs\"\n\t    end\n\t})\nend)\n\nRun(function()\n\tlocal DaveyAim\n\tlocal Mode\n\tlocal Position\n\tlocal Range\n\tlocal PlaceCannon\n\tlocal Switch\n\tlocal LaunchCannon\n\tlocal ShowTarget\n\tlocal OldDaveyAim\n\t\n\tlocal RayCheck: RaycastParams = RaycastParams.new()\n\tRayCheck.RespectCanCollide = true\n\tlocal SoftSteps: number = 14\n\tlocal FallSafeSpeed: number = 99\n\tlocal FallDamageScale: number = 0.884\n\t\n\tlocal function CastBlock(Origin: Vector3, Direction: Vector3, Ignored: {Instance}): RaycastResult?\n\t    local Filter: {Instance} = table.clone(Ignored)\n\t    local First: RaycastResult?\n\t    local Found: RaycastResult?\n\t\n\t    for _ = 1, 8 do\n\t        RayCheck.FilterDescendantsInstances = Filter\n\t        local Result: RaycastResult? = workspace:Raycast(Origin, Direction, RayCheck)\n\t        if not Result then\n\t            break\n\t        end\n\t\n\t        First = First or Result\n\t        if CollectionService:HasTag(Result.Instance, \"block\") then\n\t            Found = Result\n\t            break\n\t        end\n\t\n\t        table.insert(Filter, Result.Instance)\n\t    end\n\t\n\t    RayCheck.FilterDescendantsInstances = Ignored\n\t\n\t    return Found or First\n\tend\n\t\n\tlocal function PlaceCannonBlock()\n\t    local Item = GetItem(\"cannon\")\n\t    if not Item then\n\t        SendNotification(\"DaveyAim\", \"No cannon in your inventory.\", 5, \"warning\")\n\t        return nil\n\t    end\n\t\n\t    local Root: BasePart = Entity.character.RootPart\n\t    local Feet: Vector3 = RoundPosition(Root.Position - Vector3.new(0, Entity.character.HipHeight + 1.5, 0))\n\t    for Drop: number = 0, 3 do\n\t        local Support: Vector3 = Feet - Vector3.yAxis * (3 * Drop)\n\t        if GetPlacedBlock(Support) then\n\t            Feet = Support\n\t            break\n\t        end\n\t    end\n\t    local Spot, Closest = nil, math.huge\n\t\n\t    for X: number = -3, 3 do\n\t        for Z: number = -3, 3 do\n\t            for Y: number = 0, 1 do\n\t                local Cell: Vector3 = Feet + Vector3.new(X * 3, Y * 3, Z * 3)\n\t                local Distance: number = (Root.Position - Cell).Magnitude\n\t                if Distance > Range.Value or Distance >= Closest or Cell == Feet or Cell == Feet + Vector3.yAxis * 3 then\n\t                    continue\n\t                end\n\t                if GetPlacedBlock(Cell) or GetPlacedBlock(Cell + Vector3.yAxis * 3) or not GetPlacedBlock(Cell - Vector3.yAxis * 3) then\n\t                    continue\n\t                end\n\t                Spot, Closest = Cell, Distance\n\t            end\n\t        end\n\t    end\n\t\n\t    local PlacePosition: Vector3? = Spot\n\t    if not PlacePosition then\n\t        SendNotification(\"DaveyAim\", \"Nowhere to put a cannon.\", 5, \"warning\")\n\t        return nil\n\t    end\n\t\n\t    if Switch.Enabled then\n\t        SwitchItem(Item.tool)\n\t        local Hotbar = GetHotbar(Item.tool)\n\t        if Hotbar then\n\t            HotbarSwitch(Hotbar)\n\t        end\n\t    end\n\t\n\t    bedwars.placeBlock(PlacePosition, \"cannon\")\n\t\n\t    local Timeout: number = tick() + 1 + Store.ping.total\n\t    repeat\n\t        task.wait(0.05)\n\t        for _, v: BasePart in CollectionService:GetTagged(\"cannon\") do\n\t            if (v.Position - PlacePosition).Magnitude < 1.5 then\n\t                return v\n\t            end\n\t        end\n\t    until tick() > Timeout\n\t\n\t    return nil\n\tend\n\t\n\tlocal function GetApex(Delta: Vector3, Time: number)\n\t    local Rise: number = ((Delta + Vector3.new(0, workspace.Gravity * Time * Time * 0.5, 0)) / Time).Y\n\t    return Rise > 0 and (Rise * Rise) / (2 * workspace.Gravity) or 0\n\tend\n\t\n\tlocal function FindLaunchSpeed(Func, Depth: number?)\n\t    local Success, Constants = pcall(debug.getconstants, Func)\n\t    if not Success then\n\t        return\n\t    end\n\t\n\t    local Speed, Matched\n\t    for _, v: any in Constants do\n\t        if v == \"LaunchSelfFromCannon\" then\n\t            Matched = true\n\t        elseif type(v) == \"number\" and v > 0 then\n\t            Speed = Speed or v\n\t        end\n\t    end\n\t    if Matched and Speed then\n\t        return Speed\n\t    end\n\t    if (Depth or 0) >= 3 then\n\t        return\n\t    end\n\t\n\t    local Found, Upvalues = pcall(debug.getupvalues, Func)\n\t    if not Found then\n\t        return\n\t    end\n\t\n\t    for _, v: any in Upvalues do\n\t        if type(v) == \"function\" then\n\t            local Result: number? = FindLaunchSpeed(v, (Depth or 0) + 1)\n\t            if Result then\n\t                return Result\n\t            end\n\t        end\n\t    end\n\tend\n\t\n\tlocal function SolveTime(Delta: Vector3, Velocity: Vector3, Speed: number, Fast: number, Slow: number)\n\t    for _ = 1, 60 do\n\t        local Middle: number = (Fast + Slow) / 2\n\t        if ((Delta + Vector3.new(0, workspace.Gravity * Middle * Middle * 0.5, 0)) / Middle - Velocity).Magnitude > Speed then\n\t            Fast = Middle\n\t        else\n\t            Slow = Middle\n\t        end\n\t    end\n\t\n\t    return (Fast + Slow) / 2\n\tend\n\t\n\tlocal function GetLaunchTime(Origin: Vector3, Delta: Vector3, Velocity: Vector3, Speed: number)\n\t    local Low, Up = 0.0001, 20\n\t\n\t    for _ = 1, 50 do\n\t        local First, Second = Low + (Up - Low) / 3, Up - (Up - Low) / 3\n\t        if ((Delta + Vector3.new(0, workspace.Gravity * First * First * 0.5, 0)) / First - Velocity).Magnitude < ((Delta + Vector3.new(0, workspace.Gravity * Second * Second * 0.5, 0)) / Second - Velocity).Magnitude then\n\t            Up = Second\n\t        else\n\t            Low = First\n\t        end\n\t    end\n\t\n\t    local Middle: number = (Low + Up) / 2\n\t    if ((Delta + Vector3.new(0, workspace.Gravity * Middle * Middle * 0.5, 0)) / Middle - Velocity).Magnitude > Speed then\n\t        return\n\t    end\n\t\n\t    local FastTime: number = SolveTime(Delta, Velocity, Speed, 0.0001, Middle)\n\t    local SlowTime: number = SolveTime(Delta, Velocity, Speed, 20, Middle)\n\t    local Candidates: {number} = {FastTime, SlowTime}\n\t    for Step: number = 1, SoftSteps do\n\t        table.insert(Candidates, FastTime + (SlowTime - FastTime) * Step / (SoftSteps + 1))\n\t    end\n\t    if OldDaveyAim.Enabled then\n\t        for Step: number = -24, 24 do\n\t            local FlightTime: number = Middle * (1 + Step * 0.05)\n\t            if FlightTime > 0.05 and ((Delta + Vector3.new(0, workspace.Gravity * FlightTime * FlightTime * 0.5, 0)) / FlightTime - Velocity).Magnitude <= Speed then\n\t                table.insert(Candidates, FlightTime)\n\t            end\n\t        end\n\t    end\n\t    table.sort(Candidates, function(A: number, B: number)\n\t        local ApexA, ApexB = GetApex(Delta, A), GetApex(Delta, B)\n\t        if ApexA ~= ApexB then\n\t            return ApexA < ApexB\n\t        end\n\t\n\t        return A < B\n\t    end)\n\t\n\t    for _, v: number in Candidates do\n\t        local Arc: Vector3 = (Delta + Vector3.new(0, workspace.Gravity * v * v * 0.5, 0)) / v\n\t        if Entity.character.Humanoid.FloorMaterial ~= Enum.Material.Air and Arc.Y <= 0 then\n\t            continue\n\t        end\n\t        local Previous: Vector3 = Origin\n\t        local Lower: Vector3 = Vector3.yAxis * math.max(Entity.character.HipHeight - 2, 0)\n\t        local Blocked: boolean = false\n\t        local Steps: number = math.clamp(math.ceil(math.max(v * 60, (Arc.Magnitude * v + workspace.Gravity * v * v * 0.5) / 6)), 12, 240)\n\t        for Step: number = 1, Steps do\n\t            local Elapsed: number = v * Step / Steps\n\t            local Point: Vector3 = Origin + Arc * Elapsed - Vector3.new(0, workspace.Gravity * Elapsed * Elapsed * 0.5, 0)\n\t            local Hit: RaycastResult? = workspace:Spherecast(Previous, 2, Point - Previous, RayCheck) or workspace:Spherecast(Previous - Lower, 2, Point - Previous, RayCheck)\n\t            local Landing: boolean = Hit ~= nil and Step == Steps and Hit.Normal.Y > 0.7 and ((Hit.Position - Origin - Delta) * Vector3.new(1, 0, 1)).Magnitude <= 2.5\n\t            if Hit and not Landing then\n\t                Blocked = true\n\t                break\n\t            end\n\t            Previous = Point\n\t        end\n\t\n\t        if not Blocked then\n\t            return v\n\t        end\n\t    end\n\t\n\t    return nil\n\tend\n\t\n\tlocal function TrackFlight(Cannon: BasePart, Direction: Vector3, Speed: number, Time: number, Target: Vector3, Visual: Part?, Manual: boolean?)\n\t    local Root: BasePart = Entity.character.RootPart\n\t    local Humanoid: Humanoid = Entity.character.Humanoid\n\t    local Velocity: Vector3 = Root.AssemblyLinearVelocity\n\t    local Controller = bedwars.CannonHandController\n\t    local Flight = {Root = Root}\n\t    local Active: boolean = false\n\t    local Cancelled: boolean = false\n\t    local LaunchStart: number = 0\n\t    local FlightOrigin: Vector3 = Root.Position\n\t    local FlightVelocity: Vector3 = (Target - FlightOrigin + Vector3.yAxis * workspace.Gravity * Time * Time * 0.5) / Time\n\t    local AutoRotate: boolean = Humanoid.AutoRotate\n\t    local Legacy: boolean = OldDaveyAim.Enabled\n\t    local Deadline: number = tick() + (Manual and 30 or 2) + Store.ping.total\n\t    local Old = Controller.launchSelf\n\t    local Launch\n\t\n\t    local function Restore()\n\t        if Controller.launchSelf == Launch then\n\t            Controller.launchSelf = Old\n\t        end\n\t    end\n\t\n\t    Launch = function(self, Block: BasePart, ...)\n\t        if Block ~= Cannon or Cancelled then\n\t            return Old(self, Block, ...)\n\t        end\n\t\n\t        Active = true\n\t        Velocity = Root.AssemblyLinearVelocity\n\t        FlightOrigin = Root.Position\n\t        FlightVelocity = (Target - FlightOrigin + Vector3.yAxis * workspace.Gravity * Time * Time * 0.5) / Time\n\t        Store.cannonFlight = Flight\n\t        Deadline = tick() + 2 + Store.ping.total\n\t        local Call = Old(self, Block, ...)\n\t        LaunchStart = tick()\n\t        Restore()\n\t        return Call\n\t    end\n\t    Controller.launchSelf = Launch\n\t\n\t    task.spawn(function()\n\t        local Launched: boolean = false\n\t        local Airborne: boolean = false\n\t        local Elapsed: number = 0\n\t\n\t        repeat\n\t            local Delta: number = RunService.PreSimulation:Wait()\n\t            if Cancelled or not Entity.isAlive or Entity.character.RootPart ~= Root or (Active and Store.cannonFlight ~= Flight) then\n\t                break\n\t            end\n\t\n\t            if Active and not Launched and (Root.AssemblyLinearVelocity - Velocity):Dot(Direction) > Speed * 0.5 then\n\t                Launched = true\n\t                Deadline = LaunchStart + Time + 3\n\t                Humanoid.AutoRotate = false\n\t                Humanoid:ChangeState(Enum.HumanoidStateType.Freefall)\n\t                Root.AssemblyAngularVelocity = Vector3.zero\n\t\n\t                if not Legacy then\n\t                    local Needed: Vector3 = (Target - Root.Position + Vector3.yAxis * workspace.Gravity * Time * Time * 0.5) / Time\n\t                    local Current: Vector3 = Root.AssemblyLinearVelocity\n\t                    if (Needed - Current).Magnitude > 2 and Needed.Magnitude <= math.max(Current.Magnitude, Speed) + 1 then\n\t                        Root.AssemblyLinearVelocity = Needed\n\t                    end\n\t                end\n\t            end\n\t            if Launched then\n\t                local Grounded: boolean = Humanoid.FloorMaterial ~= Enum.Material.Air or (Root.AssemblyLinearVelocity.Y <= 0 and workspace:Raycast(Root.Position, Vector3.yAxis * -(Entity.character.HipHeight + 0.05), RayCheck) ~= nil)\n\t                if not Grounded then\n\t                    Airborne = true\n\t                elseif Airborne or tick() - LaunchStart > 0.2 then\n\t                    break\n\t                end\n\t                Elapsed += Delta\n\t                if Legacy then\n\t                    if Elapsed < Time then\n\t                        local IdealPosition: Vector3 = FlightOrigin + FlightVelocity * Elapsed - Vector3.yAxis * workspace.Gravity * Elapsed * Elapsed * 0.5\n\t                        local IdealVelocity: Vector3 = FlightVelocity - Vector3.yAxis * workspace.Gravity * Elapsed\n\t                        local Ceiling: number = math.sqrt(Speed * Speed + 2 * workspace.Gravity * math.max(FlightOrigin.Y - Root.Position.Y, 0))\n\t                        local Corrected: Vector3 = IdealVelocity + (IdealPosition - Root.Position) * 6\n\t                        local StepVelocity: Vector3 = Corrected.Magnitude > Ceiling and Corrected.Unit * Ceiling or Corrected\n\t                        if workspace:Spherecast(Root.Position, 2, StepVelocity * Delta, RayCheck) then\n\t                            break\n\t                        end\n\t                        Root.AssemblyLinearVelocity = StepVelocity\n\t                    else\n\t                        Root.AssemblyLinearVelocity = Vector3.new(0, Root.AssemblyLinearVelocity.Y, 0)\n\t                        if Elapsed >= Time + 0.5 then\n\t                            break\n\t                        end\n\t                    end\n\t                elseif Elapsed >= Time then\n\t                    break\n\t                end\n\t            end\n\t            if Visual then\n\t                Visual.Tag.TextLabel.Text = `Landing ({math.floor((Target - Root.Position).Magnitude)} studs)`\n\t            end\n\t        until tick() > Deadline\n\t\n\t        Cancelled = true\n\t        Restore()\n\t        if Store.cannonFlight == Flight then\n\t            Store.cannonFlight = nil\n\t        end\n\t        if Launched and Humanoid.Parent and not Humanoid.AutoRotate then\n\t            Humanoid.AutoRotate = AutoRotate\n\t        end\n\t        if Legacy and Launched and Entity.isAlive and Entity.character.RootPart == Root then\n\t            Root.AssemblyLinearVelocity = Vector3.new(0, math.min(Root.AssemblyLinearVelocity.Y, 0), 0)\n\t        end\n\t        if Visual then\n\t            Visual:Destroy()\n\t        end\n\t    end)\n\t\n\t    return function()\n\t        Cancelled = true\n\t        Restore()\n\t    end\n\tend\n\t\n\tDaveyAim = vape.Categories.Kits:CreateModule({\n\t    Name = \"DaveyAim\",\n\t    Function = function(Callback: boolean)\n\t        if Callback then\n\t            DaveyAim:Toggle()\n\t            if not Entity.isAlive or Store.cannonFlight then\n\t                return\n\t            end\n\t\n\t            local Cannons: {BasePart} = {}\n\t            local CannonOrigin: Vector3 = Entity.character.RootPart.Position\n\t            for _, v: BasePart in Store.blocks do\n\t                if v.Name == \"cannon\" and (CannonOrigin - v.Position).Magnitude <= Range.Value then\n\t                    table.insert(Cannons, v)\n\t                end\n\t            end\n\t            if #Cannons > 1 then\n\t                table.sort(Cannons, function(A: BasePart, B: BasePart)\n\t                    return (CannonOrigin - A.Position).Magnitude < (CannonOrigin - B.Position).Magnitude\n\t                end)\n\t            end\n\t\n\t            local Cannon = Cannons[1] or (PlaceCannon.Enabled and PlaceCannonBlock())\n\t            if not Cannon then\n\t                if not PlaceCannon.Enabled then\n\t                    SendNotification(\"DaveyAim\", \"No cannon in range.\", 5, \"warning\")\n\t                end\n\t                return\n\t            end\n\t\n\t            local CameraAim: boolean = Position.Value == \"Camera\" or UserInputService.TouchEnabled\n\t            local AimRay: Ray = CameraAim and Ray.new(Camera.CFrame.Position, Camera.CFrame.LookVector) or cloneref(LocalPlayer:GetMouse()).UnitRay\n\t            local RayResult: RaycastResult? = CastBlock(AimRay.Origin, AimRay.Direction * 10000, {LocalPlayer.Character, Camera, Cannon})\n\t            if not RayResult then\n\t                SendNotification(\"DaveyAim\", \"No block found where you are aiming.\", 5, \"warning\")\n\t                return\n\t            end\n\t\n\t            local LocalPosition: Vector3 = Entity.character.RootPart.Position\n\t            local TargetPosition: Vector3 = RayResult.Position + Vector3.new(0, Entity.character.HipHeight, 0)\n\t            local Velocity: Vector3 = Entity.character.RootPart.AssemblyLinearVelocity\n\t            local Boost = vape.Libraries.cheatengine and vape.Libraries.cheatengine.CannonBoost\n\t            local CannonSpeed: number = (FindLaunchSpeed(bedwars.CannonHandController.launchSelf) or not canDebug and Boost and Boost.GetSpeed and Boost.GetSpeed() or 200)\n\t            local MaxRange: number = (CannonSpeed * CannonSpeed) / workspace.Gravity\n\t            if (TargetPosition - LocalPosition).Magnitude > MaxRange then\n\t                SendNotification(\"DaveyAim\", `Too far away ({math.floor((TargetPosition - LocalPosition).Magnitude)} studs away, {math.floor(MaxRange)} max).`, 5, \"warning\")\n\t                return\n\t            end\n\t\n\t            local Time: number? = GetLaunchTime(LocalPosition, TargetPosition - LocalPosition, Velocity, CannonSpeed)\n\t            if not Time then\n\t                SendNotification(\"DaveyAim\", \"No clear cannon arc to that position.\", 5, \"warning\")\n\t                return\n\t            end\n\t\n\t            local LandingSpeed: number = math.max(workspace.Gravity * Time - (((TargetPosition - LocalPosition) + Vector3.new(0, workspace.Gravity * Time * Time * 0.5, 0)) / Time).Y, 0)\n\t            local FallDamage: number = math.max(LandingSpeed - FallSafeSpeed, 0) * FallDamageScale\n\t            local NoFall = vape.Modules.NoFall\n\t            if FallDamage >= Entity.character.Humanoid.Health - 3 and not (NoFall and NoFall.Enabled) then\n\t                SendNotification(\"DaveyAim\", `That landing would deal about {math.floor(FallDamage)} damage ({math.floor(LandingSpeed)} studs/s down), pick a lower or closer spot.`, 5, \"warning\")\n\t                return\n\t            end\n\t\n\t            local LaunchDirection: Vector3 = (((TargetPosition - LocalPosition) + Vector3.new(0, workspace.Gravity * Time * Time * 0.5, 0)) / Time - Velocity).Unit\n\t            local Visual: Part?\n\t            if ShowTarget.Enabled then\n\t                local BlockPosition: Vector3 = RoundPosition(RayResult.Position - RayResult.Normal * 1.5)\n\t                Visual = Instance.new(\"Part\")\n\t                Visual.Size = Vector3.new(3, 3, 3)\n\t                Visual.CFrame = CFrame.new(BlockPosition)\n\t                Visual.Anchored = true\n\t                Visual.CanCollide = false\n\t                Visual.CanQuery = false\n\t                Visual.CanTouch = false\n\t                Visual.CastShadow = false\n\t                Visual.Transparency = 1\n\t                local Selection: SelectionBox = Instance.new(\"SelectionBox\")\n\t                Selection.Adornee = Visual\n\t                Selection.LineThickness = 0.04\n\t                Selection.Color3 = Color3.new(1, 1, 1)\n\t                Selection.SurfaceColor3 = Color3.new(1, 1, 1)\n\t                Selection.SurfaceTransparency = 0.75\n\t                Selection.Parent = Visual\n\t                local TagSize: Vector2 = GetFontBounds(\"Landing (000 studs)\", 14, UIPallet.Font)\n\t                local Billboard: BillboardGui = Instance.new(\"BillboardGui\")\n\t                Billboard.Name = \"Tag\"\n\t                Billboard.Size = UDim2.fromOffset(TagSize.X + 8, TagSize.Y + 7)\n\t                Billboard.StudsOffsetWorldSpace = (TargetPosition - BlockPosition) + Vector3.new(0, 2, 0)\n\t                Billboard.AlwaysOnTop = true\n\t                Billboard.Parent = Visual\n\t                local Tag: TextLabel = Instance.new(\"TextLabel\")\n\t                Tag.Size = Billboard.Size\n\t                Tag.BackgroundColor3 = Color3.new()\n\t                Tag.BackgroundTransparency = 0.5\n\t                Tag.BorderSizePixel = 0\n\t                Tag.RichText = true\n\t                Tag.FontFace = UIPallet.Font\n\t                Tag.TextSize = 14\n\t                Tag.TextColor3 = Color3.new(1, 1, 1)\n\t                Tag.Parent = Billboard\n\t                bedwars.QueryUtil:setQueryIgnored(Visual, true)\n\t                Visual.Parent = Camera\n\t            end\n\t            if Visual then\n\t                Visual.Tag.TextLabel.Text = `Landing ({math.floor((TargetPosition - LocalPosition).Magnitude)} studs)`\n\t            end\n\t\n\t            if Mode.Value == \"Legit\" then\n\t                local AimDirection: Vector3 = LaunchDirection\n\t                local StartLook: Vector3 = Camera.CFrame.LookVector\n\t                local Angle: number = math.deg(math.acos(math.clamp(StartLook:Dot(AimDirection), -1, 1)))\n\t                local Duration: number = math.clamp(Angle / 300, 0.15, 0.8)\n\t                local Elapsed, Alpha = 0, 0\n\t\n\t                repeat\n\t                    Elapsed += RunService.PostSimulation:Wait()\n\t                    Alpha = math.clamp(Elapsed / Duration, 0, 1)\n\t                    local Eased: number = Alpha < 0.5 and (2 * Alpha * Alpha) or (1 - ((-2 * Alpha + 2) ^ 2) / 2)\n\t                    local Look: Vector3 = StartLook:Lerp(AimDirection, Eased)\n\t                    if Look.Magnitude > 0.001 then\n\t                        local CameraPosition: Vector3 = Camera.CFrame.Position\n\t                        Camera.CFrame = CFrame.lookAt(CameraPosition, CameraPosition + Look.Unit)\n\t                    end\n\t                until Alpha >= 1 or not Entity.isAlive\n\t                if not Entity.isAlive then\n\t                    if Visual then\n\t                        Visual:Destroy()\n\t                    end\n\t                    return\n\t                end\n\t                bedwars.CannonController:startAiming(Cannon)\n\t                task.wait(Cannon.AimPrompt.HoldDuration)\n\t\n\t                local Ready: number = tick() + 1\n\t                repeat\n\t                    RunService.PostSimulation:Wait()\n\t                until Cannon.StopAimingPrompt.Enabled or tick() > Ready or not Cannon.Parent\n\t\n\t                bedwars.CannonController:stopAiming()\n\t            end\n\t            task.wait((Cannon.StopAimingPrompt.HoldDuration + (0.2 + Store.ping.total)) + RunService.PostSimulation:Wait())\n\t\n\t            if Mode.Value == \"Legit\" then\n\t                local Success, Aiming = pcall(function()\n\t                    return bedwars.CannonController:isAiming()\n\t                end)\n\t                if Success and Aiming then\n\t                    pcall(function()\n\t                        bedwars.CannonController:stopAiming()\n\t                    end)\n\t                end\n\t            end\n\t\n\t            local BlockPosition: Vector3 = bedwars.BlockController:getBlockPosition(Cannon.Position)\n\t            local Aimed: boolean?\n\t            local Timeout: number = tick() + 1\n\t            repeat\n\t                bedwars.Handler:Get(\"AimCannon\"):Fire(\"SendToServer\", {\n\t                    cannonBlockPos = BlockPosition,\n\t                    lookVector = LaunchDirection\n\t                })\n\t                task.wait(0.15)\n\t                local Look = Cannon:GetAttribute(\"LookVector\")\n\t                Aimed = Look and (Look - LaunchDirection).Magnitude < 0.0001\n\t            until Aimed or tick() > Timeout or not Cannon.Parent\n\t\n\t            if not Aimed then\n\t                SendNotification(\"DaveyAim\", \"Cannon refused the aim.\", 5, \"warning\")\n\t                if Visual then\n\t                    Visual:Destroy()\n\t                end\n\t                return\n\t            end\n\t\n\t            if not Entity.isAlive or not Cannon.Parent then\n\t                if Visual then\n\t                    Visual:Destroy()\n\t                end\n\t                return\n\t            end\n\t\n\t            if LaunchCannon.Enabled then\n\t                TrackFlight(Cannon, LaunchDirection, CannonSpeed, Time, TargetPosition, Visual)\n\t                bedwars.CannonHandController:launchSelf(Cannon)\n\t            else\n\t                local Launched, StillAimed = false, true\n\t                local Cancel = TrackFlight(Cannon, LaunchDirection, CannonSpeed, Time, TargetPosition, Visual, true)\n\t                local Connection: RBXScriptConnection = Cannon.LaunchSelfPrompt.Triggered:Connect(function(PromptPlayer: Player)\n\t                    if PromptPlayer == LocalPlayer and not Launched and Entity.isAlive then\n\t                        Launched = true\n\t                    end\n\t                end)\n\t                local LaunchDeadline: number = tick() + 30\n\t\n\t                repeat\n\t                    RunService.PostSimulation:Wait()\n\t                    local Look = Cannon.Parent and Cannon:GetAttribute(\"LookVector\")\n\t                    StillAimed = typeof(Look) ~= \"Vector3\" or (Look - LaunchDirection).Magnitude < 0.0001\n\t                until Launched or not StillAimed or tick() > LaunchDeadline or not Entity.isAlive or not Cannon.Parent\n\t\n\t                Connection:Disconnect()\n\t                if not Launched then\n\t                    Cancel()\n\t                    if not StillAimed then\n\t                        SendNotification(\"DaveyAim\", \"Cannon was re-aimed before you launched.\", 5, \"warning\")\n\t                    end\n\t                    if Visual then\n\t                        Visual:Destroy()\n\t                    end\n\t                    return\n\t                end\n\t            end\n\t        end\n\t    end,\n\t    Tooltip = \"Aims a nearby cannon at your cursor and launches you onto it\"\n\t})\n\t\n\tMode = DaveyAim:CreateDropdown({\n\t    Name = \"Aim Mode\",\n\t    List = {\"Blatant\", \"Legit\"},\n\t    Default = \"Blatant\"\n\t})\n\tPosition = DaveyAim:CreateDropdown({\n\t    Name = \"Position Mode\",\n\t    List = {\"Mouse\", \"Camera\"},\n\t    Default = \"Mouse\"\n\t})\n\tRange = DaveyAim:CreateSlider({\n\t    Name = \"Search Range\",\n\t    Min = 1,\n\t    Max = 18,\n\t    Default = 10,\n\t    Suffix = function(Val: number)\n\t        return Val <= 1 and \"stud\" or \"studs\"\n\t    end\n\t})\n\tPlaceCannon = DaveyAim:CreateToggle({\n\t    Name = \"Place Cannon\",\n\t    Function = function(Callback: boolean)\n\t        if Switch then\n\t            Switch.Object.Visible = Callback\n\t        end\n\t    end,\n\t    Tooltip = \"Puts a cannon down on the nearest free block when there is none in range\",\n\t    Default = true\n\t})\n\tSwitch = DaveyAim:CreateToggle({\n\t    Name = \"Auto Switch\",\n\t    Default = true,\n\t    Darker = true,\n\t    Tooltip = \"Holds the cannon before placing it\"\n\t})\n\tLaunchCannon = DaveyAim:CreateToggle({\n\t    Name = \"Launch Cannon\",\n\t    Default = true,\n\t    Tooltip = \"Launches you normally, turn this off to aim and launch yourself\"\n\t})\n\tShowTarget = DaveyAim:CreateToggle({\n\t    Name = \"Show Target\",\n\t    Default = true,\n\t    Tooltip = \"Highlights the block you are landing on until you land\"\n\t})\n\tOldDaveyAim = DaveyAim:CreateToggle({\n\t    Name = \"Old DaveyAim\",\n\t    Tooltip = \"Uses the previous flight correction and stops horizontal movement at the landing point\"\n\t})\nend)\n\nRun(function()\n\tlocal EquipKit\n\tlocal Kit\n\t\n\tlocal KitIds: {[string]: string} = {}\n\t\n\tEquipKit = vape.Categories.Kits:CreateModule({\n\t    Name = \"EquipKit\",\n\t    Function = function(Callback: boolean)\n\t        if Callback then\n\t            EquipKit:Toggle()\n\t            SendNotification(\"EquipKit\", `{bedwars.Handler:Get(\"BedwarsActivateKit\"):Fire(\"CallServer\", {kit = KitIds[Kit.Value]}) and \"Successfully equipped\" or \"Failed to equip\"} {Kit.Value}.`, 10, \"info\")\n\t        end\n\t    end\n\t})\n\t\n\tlocal KitNames: {string} = {}\n\tfor KitId: string, v: any in bedwars.BedwarsKitMeta do\n\t    table.insert(KitNames, v.name)\n\t    KitIds[v.name] = KitId\n\tend\n\ttable.sort(KitNames)\n\tKit = EquipKit:CreateDropdown({\n\t    Name = \"Equip kit\",\n\t    List = KitNames,\n\t    Default = \"None\"\n\t})\nend)\n\nRun(function()\n\tlocal FalconAura\n\tlocal Range\n\tlocal Delay\n\tlocal Recall\n\tlocal NextSend: number = 0\n\t\n\tFalconAura = vape.Categories.Kits:CreateModule({\n\t    Name = \"FalconAura\",\n\t    Function = function(Callback: boolean)\n\t        if Callback then\n\t            NextSend = 0\n\t\n\t            repeat\n\t                if Entity.isAlive and Store.equippedKit == \"falconer\" and tick() >= NextSend then\n\t                    local Target = Entity.EntityPosition({\n\t                        Origin = Entity.character.RootPart.Position,\n\t                        Range = Range.Value,\n\t                        Part = \"RootPart\",\n\t                        Players = true,\n\t                        Wallcheck = true\n\t                    })\n\t\n\t                    if Target and bedwars.AbilityController:canUseAbility(\"SEND_FALCON\", {disableBlockedAbilityAlert = true}) then\n\t                        NextSend = tick() + Delay.Value\n\t                        bedwars.AbilityController:useAbility(\"SEND_FALCON\")\n\t                    elseif not Target and Recall.Enabled and bedwars.AbilityController:canUseAbility(\"RECALL_FALCON\", {disableBlockedAbilityAlert = true}) then\n\t                        bedwars.AbilityController:useAbility(\"RECALL_FALCON\")\n\t                    end\n\t                end\n\t                task.wait(0.1)\n\t            until not FalconAura.Enabled\n\t        end\n\t    end,\n\t    Tooltip = \"Automatically sends Bekzat falcon at whoever is near you\"\n\t})\n\t\n\tRange = FalconAura:CreateSlider({\n\t    Name = \"Range\",\n\t    Min = 1,\n\t    Max = 150,\n\t    Default = 80,\n\t    Suffix = function(Val: number)\n\t        return Val <= 1 and \"stud\" or \"studs\"\n\t    end\n\t})\n\tDelay = FalconAura:CreateSlider({\n\t    Name = \"Delay\",\n\t    Min = 0.1,\n\t    Max = 5,\n\t    Default = 1,\n\t    Decimal = 10,\n\t    Suffix = function(Val: number)\n\t        return Val <= 1 and \"sec\" or \"secs\"\n\t    end\n\t})\n\tRecall = FalconAura:CreateToggle({\n\t    Name = \"Recall when clear\",\n\t    Default = true,\n\t    Tooltip = \"Calls the falcon back once nobody is in range\"\n\t})\nend)\n\nRun(function()\n\tlocal Old\n\t\n\tvape.Categories.Kits:CreateModule({\n\t    Name = \"InfiniteKrystal\",\n\t    Function = function(Callback: boolean)\n\t        if Callback then\n\t            Old = bedwars.GlacialSkaterController.updateMomentum\n\t            bedwars.GlacialSkaterController.updateMomentum = function(self, ...)\n\t                self.momentum = 1000\n\t                self.lastMomentumReport = workspace:GetServerTimeNow()\n\t                return Old(self, ...)\n\t            end\n\t        else\n\t            bedwars.GlacialSkaterController.updateMomentum = Old\n\t        end\n\t    end,\n\t    Tooltip = \"Gives you max momentum forever\"\n\t})\nend)\n\nRun(function()\n\tlocal KitExtender\n\tlocal Kaida\n\tlocal KaidaRange\n\tlocal OldMethods = {}\n\tlocal SummonRange: number?\n\t\n\tlocal Boosts = {\n\t    {\n\t        Name = \"Jade Hammer\",\n\t        Kit = \"jade\",\n\t        Controller = \"JadeHammerController\",\n\t        Method = \"useJadeHammer\",\n\t        Tooltip = \"Extends how far the Jade Hammer jump launches you\",\n\t        Hook = function(Entry, Old)\n\t            return function(self)\n\t                local Jumped: boolean = bedwars.AbilityController:canUseAbility(\"jade_hammer_jump\", {disableBlockedAbilityAlert = true})\n\t                local Call = Old(self)\n\t\n\t                if Entry.Toggle.Enabled and Jumped and Store.equippedKit == \"jade\" and Entity.isAlive then\n\t                    local Root: BasePart = Entity.character.RootPart\n\t                    Root:ApplyImpulse(Vector3.new(0, Root.AssemblyMass * (Entry.Multiplier.Value - 1) * 20.5, 0))\n\t                end\n\t                return Call\n\t            end\n\t        end\n\t    },\n\t    {\n\t        Name = \"Void Regent Dash\",\n\t        Kit = \"regent\",\n\t        Controller = \"VoidAxeController\",\n\t        Method = \"useVoidAxe\",\n\t        Tooltip = \"Extends how far the Void Regent axe dash launches you\",\n\t        Hook = function(Entry, Old)\n\t            return function(self)\n\t                local Dashed: boolean = bedwars.AbilityController:canUseAbility(\"void_axe_jump\", {disableBlockedAbilityAlert = true})\n\t                local Call = Old(self)\n\t\n\t                if Entry.Toggle.Enabled and Dashed and Store.equippedKit == \"regent\" and Entity.isAlive then\n\t                    local Root: BasePart = Entity.character.RootPart\n\t                    Root:ApplyImpulse(Root.CFrame.LookVector * Vector3.new(1, 0, 1) * Root.AssemblyMass * (Entry.Multiplier.Value - 1) * 70)\n\t                end\n\t                return Call\n\t            end\n\t        end\n\t    },\n\t    {\n\t        Name = \"Yamini Pounce\",\n\t        Kit = \"cat\",\n\t        Controller = \"CatController\",\n\t        Method = \"leap\",\n\t        Tooltip = \"Extends how far the Yamini pounce launches you\",\n\t        Hook = function(Entry, Old)\n\t            return function(self, Character: Model?, Direction: Vector3?)\n\t                local Call = Old(self, Character, Direction)\n\t                local Horizontal: Vector3 = Direction and Direction * Vector3.new(1, 0, 1) or Vector3.zero\n\t                local Root: BasePart? = Character and Character:FindFirstChild(\"HumanoidRootPart\")\n\t                if Entry.Toggle.Enabled and Store.equippedKit == \"cat\" and Root and Horizontal.Magnitude > 0 then\n\t                    Root:ApplyImpulse(Horizontal.Unit * Root.AssemblyMass * (Entry.Multiplier.Value - 1) * 70)\n\t                end\n\t                return Call\n\t            end\n\t        end\n\t    },\n\t    {\n\t        Name = \"Yamini Wall Kick\",\n\t        Kit = \"cat\",\n\t        Controller = \"CatController\",\n\t        Method = \"dismountWall\",\n\t        Tooltip = \"Extends how high dropping off a climbed wall throws you\",\n\t        Hook = function(Entry, Old)\n\t            return function(self, ...)\n\t                local Call = Old(self, ...)\n\t\n\t                if Entry.Toggle.Enabled and Store.equippedKit == \"cat\" and Entity.isAlive then\n\t                    local Root: BasePart = Entity.character.RootPart\n\t                    Root:ApplyImpulse(Vector3.new(0, Root.AssemblyMass * (Entry.Multiplier.Value - 1) * 25, 0))\n\t                end\n\t                return Call\n\t            end\n\t        end\n\t    },\n\t    {\n\t        Name = \"Yuzi Dash\",\n\t        Kit = \"dasher\",\n\t        Controller = \"DaoController\",\n\t        Method = \"dashForward\",\n\t        Tooltip = \"Extends how far the yuzi dash launches you\",\n\t        Hook = function(Entry, Old)\n\t            return function(self, Direction: Vector3?)\n\t                local Call = Old(self, Direction)\n\t                local Horizontal: Vector3 = Direction and Direction * Vector3.new(1, 0, 1) or Vector3.zero\n\t                if Entry.Toggle.Enabled and Store.equippedKit == \"dasher\" and Entity.isAlive and Horizontal.Magnitude > 0 then\n\t                    local Root: BasePart = Entity.character.RootPart\n\t                    Root:ApplyImpulse(Horizontal.Unit * Root.AssemblyMass * (Entry.Multiplier.Value - 1) * 70)\n\t                end\n\t                return Call\n\t            end\n\t        end\n\t    },\n\t    {\n\t        Name = \"Xurot Wing Flap\",\n\t        Kit = \"void_dragon\",\n\t        Controller = \"VoidDragonController\",\n\t        Method = \"flapWings\",\n\t        Tooltip = \"Extends how high each wing flap throws you\",\n\t        Hook = function(Entry, Old)\n\t            return function(self, ...)\n\t                local Call = Old(self, ...)\n\t\n\t                if Entry.Toggle.Enabled and Store.equippedKit == \"void_dragon\" and Entity.isAlive then\n\t                    local Root: BasePart = Entity.character.RootPart\n\t                    Root:ApplyImpulse(Vector3.new(0, Root.AssemblyMass * (Entry.Multiplier.Value - 1) * 40, 0))\n\t                end\n\t                return Call\n\t            end\n\t        end\n\t    }\n\t}\n\t\n\tKitExtender = vape.Categories.Kits:CreateModule({\n\t    Name = \"KitExtender\",\n\t    Function = function(Callback: boolean)\n\t        if Callback then\n\t            for i: number, v: any in Boosts do\n\t                local Controller = bedwars[v.Controller]\n\t                if Controller and Controller[v.Method] then\n\t                    OldMethods[i] = Controller[v.Method]\n\t                    Controller[v.Method] = v.Hook(v, OldMethods[i])\n\t                end\n\t            end\n\t\n\t            if Kaida.Enabled then\n\t                local Success, Balance = pcall(function()\n\t                    return require(ReplicatedStorage.TS.games.bedwars.kit.kits.summoner[\"summoner-kit-balance\"]).SummonerKitBalance\n\t                end)\n\t                if Success and Balance then\n\t                    SummonRange = SummonRange or Balance.SPELL_CAST_RANGE\n\t                    Balance.SPELL_CAST_RANGE = math.max(KaidaRange.Value, SummonRange)\n\t                end\n\t            end\n\t        else\n\t            for i: number, v: any in Boosts do\n\t                local Controller = bedwars[v.Controller]\n\t                if Controller and OldMethods[i] then\n\t                    Controller[v.Method] = OldMethods[i]\n\t                end\n\t            end\n\t            table.clear(OldMethods)\n\t\n\t            if SummonRange then\n\t                local Success, Balance = pcall(function()\n\t                    return require(ReplicatedStorage.TS.games.bedwars.kit.kits.summoner[\"summoner-kit-balance\"]).SummonerKitBalance\n\t                end)\n\t                if Success and Balance then\n\t                    Balance.SPELL_CAST_RANGE = SummonRange\n\t                end\n\t                SummonRange = nil\n\t            end\n\t        end\n\t    end,\n\t    Tooltip = \"Pushes kit movement abilities further than the game intends\"\n\t})\n\t\n\tfor _, v: any in Boosts do\n\t    v.Toggle = KitExtender:CreateToggle({\n\t        Name = v.Name,\n\t        Function = function(Callback: boolean)\n\t            if v.Multiplier and v.Multiplier.Object then\n\t                v.Multiplier.Object.Visible = Callback\n\t            end\n\t        end,\n\t        Tooltip = v.Tooltip\n\t    })\n\t    v.Multiplier = KitExtender:CreateSlider({\n\t        Name = `{v.Name} multiplier`,\n\t        Min = 1,\n\t        Max = 5,\n\t        Decimal = 10,\n\t        Default = 2,\n\t        Darker = true,\n\t        Visible = false,\n\t        Suffix = \"x\"\n\t    })\n\tend\n\tKaida = KitExtender:CreateToggle({\n\t    Name = \"Kaida Summon Range\",\n\t    Function = function(Callback: boolean)\n\t        if KaidaRange and KaidaRange.Object then\n\t            KaidaRange.Object.Visible = Callback\n\t        end\n\t        if KitExtender.Enabled then\n\t            KitExtender:Toggle()\n\t            KitExtender:Toggle()\n\t        end\n\t    end,\n\t    Tooltip = \"Lifts the cap the game puts on where the summon circle can land\"\n\t})\n\tKaidaRange = KitExtender:CreateSlider({\n\t    Name = \"Kaida summon range\",\n\t    Min = 45,\n\t    Max = 120,\n\t    Function = function(Val: number)\n\t        if not KitExtender.Enabled or not SummonRange then\n\t            return\n\t        end\n\t        local Success, Balance = pcall(function()\n\t            return require(ReplicatedStorage.TS.games.bedwars.kit.kits.summoner[\"summoner-kit-balance\"]).SummonerKitBalance\n\t        end)\n\t        if Success and Balance then\n\t            Balance.SPELL_CAST_RANGE = math.max(Val, SummonRange)\n\t        end\n\t    end,\n\t    Default = 75,\n\t    Darker = true,\n\t    Visible = false,\n\t    Suffix = function(Val: number)\n\t        return Val == 1 and \"stud\" or \"studs\"\n\t    end\n\t})\nend)\n\nRun(function()\n\tlocal KitSpy\n\tlocal Viewer\n\tlocal Notifications\n\tlocal Teammates\n\tlocal Self\n\tlocal Range\n\tlocal Window\n\tlocal Delay\n\tlocal Items\n\tlocal Extras\n\tlocal Toggles = {}\n\t\n\tlocal ExtraLabels: {[string]: string} = {\n\t    [\"alchemist_ingedients\"] = \"ingredient\",\n\t    [\"alchemy_crystal\"] = \"crystal\",\n\t    [\"crystalheart_seed\"] = \"crystalheart seed\",\n\t    [\"forest_environment_plant\"] = \"plant\",\n\t    [\"ghost\"] = \"ghost\",\n\t    [\"murder_coin\"] = \"coin\",\n\t    [\"shadow_coin\"] = \"shadow coin\",\n\t    [\"soulvine_seed\"] = \"soulvine seed\",\n\t    [\"spirit_gardener_energy\"] = \"energy\",\n\t    [\"spirit_gardener_seeds\"] = \"seed\",\n\t    [\"tearbloom_seed\"] = \"tearbloom seed\"\n\t}\n\t\n\tlocal Totals: {[Player]: {[string]: number}} = {}\n\tlocal Panel, InfoLabel\n\tlocal Expanded: boolean = false\n\tlocal DigAnimation = bedwars.GameAnimationUtil:getAssetId(bedwars.AnimationType.SHOVEL_DIG)\n\tlocal Animators = setmetatable({}, {__mode = \"k\"})\n\t\n\tlocal function PlayerName(TargetPlayer: Player?)\n\t    return TargetPlayer and (TargetPlayer.DisplayName or TargetPlayer.Name) or \"someone\"\n\tend\n\t\n\tlocal function Ignored(TargetPlayer: Player)\n\t    if TargetPlayer == LocalPlayer then\n\t        return Self.Enabled\n\t    end\n\t    return Teammates.Enabled and TargetPlayer.Team == LocalPlayer.Team\n\tend\n\t\n\tlocal function AmountText(Amount: number, Label: string)\n\t    return `{Amount} {Label}{Amount == 1 and \"\" or \"s\"}`\n\tend\n\t\n\tlocal function RefreshViewer()\n\t    if not Panel then\n\t        return\n\t    end\n\t\n\t    local List = {}\n\t    for TargetPlayer: Player, Kinds: {[string]: number} in Totals do\n\t        local Total, Text = 0, {}\n\t        for Label: string, Amount: number in Kinds do\n\t            Total += Amount\n\t            table.insert(Text, AmountText(Amount, Label))\n\t        end\n\t        table.sort(Text)\n\t        table.insert(List, {Name = PlayerName(TargetPlayer), Total = Total, Text = table.concat(Text, \", \")})\n\t    end\n\t    table.sort(List, function(A, B)\n\t        return A.Total > B.Total\n\t    end)\n\t\n\t    local Lines: {string} = {\"<b>KitSpy</b>\"}\n\t    if #List == 0 then\n\t        table.insert(Lines, \"Nothing spotted yet\")\n\t    else\n\t        for i: number, v: any in List do\n\t            if not Expanded and i > 5 then\n\t                table.insert(Lines, `+{#List - 5} more`)\n\t                break\n\t            end\n\t            table.insert(Lines, `{v.Name}: {v.Text}`)\n\t        end\n\t    end\n\t\n\t    InfoLabel.Text = table.concat(Lines, \"\\n\")\n\t    local Size: Vector2 = GetFontBounds(removeTags(InfoLabel.Text), InfoLabel.TextSize, InfoLabel.FontFace)\n\t    local TitleSize: Vector2 = GetFontBounds(\"KitSpy\", InfoLabel.TextSize, Font.new(InfoLabel.FontFace.Family, Enum.FontWeight.Bold))\n\t    Panel.Size = UDim2.fromOffset(math.max(Size.X, TitleSize.X) + 16, Size.Y + 16)\n\t    Panel.Visible = Viewer.Enabled\n\tend\n\t\n\tlocal function AddTotal(TargetPlayer: Player, Label: string, Amount: number)\n\t    local Kinds: {[string]: number} = Totals[TargetPlayer] or {}\n\t    Kinds[Label] = (Kinds[Label] or 0) + Amount\n\t    Totals[TargetPlayer] = Kinds\n\t    RefreshViewer()\n\t    return Kinds[Label]\n\tend\n\t\n\tlocal function CreateViewer()\n\t    if Panel then\n\t        return\n\t    end\n\t\n\t    Panel = Instance.new(\"TextButton\")\n\t    Panel.Name = \"KitSpyViewer\"\n\t    Panel.Position = UDim2.fromOffset(12, 260)\n\t    Panel.BackgroundColor3 = Color3.new()\n\t    Panel.BackgroundTransparency = 0.5\n\t    Panel.Text = \"\"\n\t    Panel.AutoButtonColor = false\n\t    Panel.Visible = false\n\t    if vape.ThreadFix then\n\t        setthreadidentity(8)\n\t    end\n\t    Panel.Parent = vape.gui.ScaledGui\n\t    addBlur(Panel)\n\t\n\t    local Corner: UICorner = Instance.new(\"UICorner\")\n\t    Corner.CornerRadius = UDim.new(0, 5)\n\t    Corner.Parent = Panel\n\t\n\t    InfoLabel = Instance.new(\"TextLabel\")\n\t    InfoLabel.Size = UDim2.new(1, -16, 1, -16)\n\t    InfoLabel.Position = UDim2.fromOffset(8, 8)\n\t    InfoLabel.BackgroundTransparency = 1\n\t    InfoLabel.TextXAlignment = Enum.TextXAlignment.Left\n\t    InfoLabel.TextYAlignment = Enum.TextYAlignment.Top\n\t    InfoLabel.TextSize = 16\n\t    InfoLabel.TextColor3 = Color3.new(1, 1, 1)\n\t    InfoLabel.TextStrokeColor3 = Color3.new()\n\t    InfoLabel.TextStrokeTransparency = 0.8\n\t    InfoLabel.Font = Enum.Font.Arial\n\t    InfoLabel.RichText = true\n\t    InfoLabel.Parent = Panel\n\t\n\t    Panel.MouseButton1Click:Connect(function()\n\t        Expanded = not Expanded\n\t        RefreshViewer()\n\t    end)\n\tend\n\t\n\tlocal function InventoryCount(TargetPlayer: Player, ItemType: string)\n\t    local Total: number = 0\n\t    for _, v: any in (store.inventories[TargetPlayer] or {items = {}}).items do\n\t        if v.itemType == ItemType then\n\t            Total += (v.amount or 1)\n\t        end\n\t    end\n\t    return Total\n\tend\n\t\n\tlocal function RecentItems(TargetPlayer: Player, Filtered: boolean)\n\t    local Now, Found = workspace:GetServerTimeNow(), {}\n\t    for _, v: any in (store.inventories[TargetPlayer] or {items = {}}).items do\n\t        if (Now - (v.addedToBackpackTime or 0)) > Window.Value then\n\t            continue\n\t        end\n\t        if Filtered and #Items.ListEnabled > 0 and not table.find(Items.ListEnabled, v.itemType) then\n\t            continue\n\t        end\n\t        local Meta = bedwars.ItemMeta[v.itemType]\n\t        table.insert(Found, `{(v.amount or 1) > 1 and `{v.amount}x ` or \"\"}{Meta and Meta.displayName or v.itemType}`)\n\t    end\n\t    return Found\n\tend\n\t\n\tlocal function Report(TargetPlayer: Player, Verb: string, Filtered: boolean)\n\t    local Found: {string} = RecentItems(TargetPlayer, Filtered)\n\t    if #Found == 0 then\n\t        return\n\t    end\n\t\n\t    notif(\"KitSpy\", `{PlayerName(TargetPlayer)} {Verb} {table.concat(Found, \", \")}`, 8, \"info\")\n\tend\n\t\n\tlocal function NearestPlayer(Position: Vector3)\n\t    local Closest, Distance = nil, Range.Value\n\t    for _, v: any in Entity.List do\n\t        if not v.Player or Ignored(v.Player) then\n\t            continue\n\t        end\n\t\n\t        local Magnitude: number = (v.RootPart.Position - Position).Magnitude\n\t        if Magnitude <= Distance then\n\t            Closest, Distance = v.Player, Magnitude\n\t        end\n\t    end\n\t    return Closest\n\tend\n\t\n\tlocal function Credit(TargetPlayer: Player, Label: string, Amount: number)\n\t    local Total: number = AddTotal(TargetPlayer, Label, Amount)\n\t    if Notifications.Enabled then\n\t        notif(\"KitSpy\", `{PlayerName(TargetPlayer)} picked up {AmountText(Amount, Label)} ({Total} total)`, 5, \"info\")\n\t    end\n\tend\n\t\n\tlocal function TrackCollectable(Tags, Label: string, ItemType: string?, LabelMap: {[string]: string}?)\n\t    local Positions, Pending, Counts = {}, {}, {}\n\t\n\t    local function ObjectAdded(Objects: {Instance}, Object: Instance)\n\t        table.insert(Objects, Object)\n\t\n\t        local Part = Object:IsA(\"Model\") and (Object.PrimaryPart or Object:FindFirstChildWhichIsA(\"BasePart\", true)) or Object\n\t        if Part then\n\t            Positions[Object] = Part.Position\n\t        end\n\t    end\n\t\n\t    local function ObjectRemoved(Objects: {Instance}, Object: Instance, Tag: string)\n\t        local Index: number? = table.find(Objects, Object)\n\t        if Index then\n\t            table.remove(Objects, Index)\n\t        end\n\t\n\t        local Position: Vector3? = Positions[Object]\n\t        Positions[Object] = nil\n\t        if not Position then\n\t            return\n\t        end\n\t\n\t        if not ItemType then\n\t            local TargetPlayer: Player? = NearestPlayer(Position)\n\t            if TargetPlayer then\n\t                Credit(TargetPlayer, LabelMap and LabelMap[Tag] or Label, 1)\n\t            end\n\t            return\n\t        end\n\t\n\t        table.insert(Pending, {Position = Position, Time = tick()})\n\t    end\n\t\n\t    local Objects: {Instance} = collection(Tags, KitSpy, ObjectAdded, ObjectRemoved)\n\t\n\t    if ItemType then\n\t        for _, v: any in Entity.List do\n\t            if v.Player then\n\t                Counts[v.Player] = InventoryCount(v.Player, ItemType)\n\t            end\n\t        end\n\t    end\n\t\n\t    repeat\n\t        local Now: number = tick()\n\t\n\t        for _, v: Instance in Objects do\n\t            local Part = v:IsA(\"Model\") and (v.PrimaryPart or v:FindFirstChildWhichIsA(\"BasePart\", true)) or v\n\t            if Part then\n\t                Positions[v] = Part.Position\n\t            end\n\t        end\n\t\n\t        for i: number = #Pending, 1, -1 do\n\t            if (Now - Pending[i].Time) > Window.Value then\n\t                table.remove(Pending, i)\n\t            end\n\t        end\n\t\n\t        if ItemType then\n\t            for _, v: any in Entity.List do\n\t                local TargetPlayer: Player? = v.Player\n\t                if not TargetPlayer or Ignored(TargetPlayer) then\n\t                    continue\n\t                end\n\t\n\t                local Amount: number = InventoryCount(TargetPlayer, ItemType)\n\t                local Previous: number? = Counts[TargetPlayer]\n\t                Counts[TargetPlayer] = Amount\n\t\n\t                if not Previous or Amount <= Previous or not v.RootPart then\n\t                    continue\n\t                end\n\t\n\t                for i: number = #Pending, 1, -1 do\n\t                    if (v.RootPart.Position - Pending[i].Position).Magnitude > Range.Value then\n\t                        continue\n\t                    end\n\t\n\t                    table.remove(Pending, i)\n\t                    Credit(TargetPlayer, Label, Amount - Previous)\n\t                    break\n\t                end\n\t            end\n\t        end\n\t\n\t        task.wait(0.2)\n\t    until not KitSpy.Enabled\n\tend\n\t\n\tlocal function TrackDigging()\n\t    local function EntityAdded(Ent)\n\t        if not Ent.Player or Ignored(Ent.Player) then\n\t            return\n\t        end\n\t\n\t        local Animator: Animator? = Ent.Humanoid:FindFirstChildOfClass(\"Animator\")\n\t        if not Animator or Animators[Animator] then\n\t            return\n\t        end\n\t        Animators[Animator] = Animator.AnimationPlayed:Connect(function(Track: AnimationTrack)\n\t            if Track.Animation.AnimationId ~= DigAnimation then\n\t                return\n\t            end\n\t\n\t            task.delay(Delay.Value, Report, Ent.Player, \"dug up\", true)\n\t        end)\n\t    end\n\t\n\t    KitSpy:Clean(Entity.Events.EntityAdded:Connect(EntityAdded))\n\t    KitSpy:Clean(function()\n\t        for _, v: RBXScriptConnection in Animators do\n\t            v:Disconnect()\n\t        end\n\t        table.clear(Animators)\n\t    end)\n\t\n\t    for _, v: any in Entity.List do\n\t        EntityAdded(v)\n\t    end\n\tend\n\t\n\tlocal function TrackBounties()\n\t    local Hunters: {[Player]: Player} = {}\n\t\n\t    KitSpy:Clean(function()\n\t        table.clear(Hunters)\n\t    end)\n\t\n\t    KitSpy:Clean(bedwars.Handler:Get(\"BountyHunterTargetChanged\").Remote:Connect(function(Data)\n\t        local Hunter = typeof(Data) == \"table\" and Data.hunter\n\t        if typeof(Hunter) ~= \"Instance\" or not Hunter:IsA(\"Player\") then\n\t            return\n\t        end\n\t\n\t        local Target: Player? = Data.newTargetUserId ~= 0 and Players:GetPlayerByUserId(Data.newTargetUserId) or nil\n\t        Hunters[Hunter] = Target\n\t\n\t        if Target and Notifications.Enabled and not Ignored(Hunter) then\n\t            notif(\"KitSpy\", `{PlayerName(Hunter)} is now hunting {PlayerName(Target)}`, 12, \"info\")\n\t        end\n\t    end))\n\t\n\t    KitSpy:Clean(vapeEvents.EntityDeathEvent.Event:Connect(function(DeathTable)\n\t        local Victim: Player? = Players:GetPlayerFromCharacter(DeathTable.entityInstance)\n\t        local Killer: Player? = Players:GetPlayerFromCharacter(DeathTable.fromEntity)\n\t        if not Victim or not Killer or Hunters[Killer] ~= Victim then\n\t            return\n\t        end\n\t\n\t        Hunters[Killer] = nil\n\t        if Ignored(Killer) then\n\t            return\n\t        end\n\t\n\t        AddTotal(Killer, \"bounty\", 1)\n\t        notif(\"KitSpy\", `{PlayerName(Killer)} claimed their bounty on {PlayerName(Victim)}`, 20, \"alert\")\n\t        task.delay(Delay.Value, Report, Killer, \"looted\", false)\n\t    end))\n\t\n\t    KitSpy:Clean(Players.PlayerRemoving:Connect(function(TargetPlayer: Player)\n\t        Hunters[TargetPlayer] = nil\n\t        for Hunter: Player, v: Player in Hunters do\n\t            if v == TargetPlayer then\n\t                Hunters[Hunter] = nil\n\t            end\n\t        end\n\t    end))\n\tend\n\t\n\tlocal function TrackFishing()\n\t    KitSpy:Clean(bedwars.Handler:Get(\"FishCaught\").Remote:Connect(function(Data)\n\t        local TargetPlayer = typeof(Data) == \"table\" and Data.catchingPlayer\n\t        if not TargetPlayer or not Data.dropData or not Data.dropData.drops or Ignored(TargetPlayer) then\n\t            return\n\t        end\n\t\n\t        local Text: {string} = {}\n\t        for _, v: any in Data.dropData.drops do\n\t            local Meta = bedwars.ItemMeta[v.itemType]\n\t            table.insert(Text, AmountText(v.amount, (Meta and Meta.displayName or v.itemType):lower()))\n\t        end\n\t\n\t        if #Text == 0 then\n\t            return\n\t        end\n\t\n\t        AddTotal(TargetPlayer, \"catch\", 1)\n\t        if Notifications.Enabled then\n\t            notif(\"KitSpy\", `{PlayerName(TargetPlayer)} caught {table.concat(Text, \", \")}`, 20, \"info\")\n\t        end\n\t    end))\n\tend\n\t\n\tlocal KitSpyFunctions = {\n\t    beekeeper = function()\n\t        TrackCollectable(\"bee\", \"bee\", \"bee\")\n\t    end,\n\t    bigman = function()\n\t        TrackCollectable(\"treeOrb\", \"tree orb\")\n\t    end,\n\t    bounty_hunter = TrackBounties,\n\t    farmer_cletus = function()\n\t        TrackCollectable(\"HarvestableCrop\", \"crop\")\n\t    end,\n\t    fisherman = TrackFishing,\n\t    jailor = function()\n\t        TrackCollectable(\"jailor_soul\", \"soul\")\n\t    end,\n\t    metal_detector = function()\n\t        TrackCollectable(\"hidden-metal\", \"metal\")\n\t        TrackDigging()\n\t    end,\n\t    spirit_assassin = function()\n\t        TrackCollectable(\"EvelynnSoul\", \"spirit\")\n\t    end,\n\t    star_collector = function()\n\t        TrackCollectable(\"stars\", \"star\")\n\t    end\n\t}\n\t\n\tKitSpy = vape.Categories.Kits:CreateModule({\n\t    Name = \"KitSpy\",\n\t    Function = function(Callback: boolean)\n\t        if Callback then\n\t            CreateViewer()\n\t            RefreshViewer()\n\t\n\t            for Kit: string, v: (...any) -> ...any in KitSpyFunctions do\n\t                if Toggles[Kit].Enabled then\n\t                    task.spawn(v)\n\t                end\n\t            end\n\t\n\t            if #Extras.ListEnabled > 0 then\n\t                task.spawn(TrackCollectable, Extras.ListEnabled, \"collectable\", nil, ExtraLabels)\n\t            end\n\t        elseif Panel then\n\t            Panel.Visible = false\n\t        end\n\t    end,\n\t    Tooltip = \"Reports what other players are doing with their kit, from bee pickups to bounty claims\"\n\t})\n\t\n\tViewer = KitSpy:CreateToggle({\n\t    Name = \"Viewer\",\n\t    Function = function()\n\t        RefreshViewer()\n\t    end,\n\t    Tooltip = \"Shows a panel with everything each player has picked up, click it to expand\",\n\t    Default = true\n\t})\n\tNotifications = KitSpy:CreateToggle({\n\t    Name = \"Notifications\",\n\t    Default = true,\n\t    Tooltip = \"Sends a notification every time someone is caught using their kit\"\n\t})\n\tTeammates = KitSpy:CreateToggle({\n\t    Name = \"Ignore teammates\",\n\t    Default = true\n\t})\n\tSelf = KitSpy:CreateToggle({\n\t    Name = \"Ignore yourself\",\n\t    Default = true\n\t})\n\tRange = KitSpy:CreateSlider({\n\t    Name = \"Range\",\n\t    Min = 1,\n\t    Max = 40,\n\t    Default = 25,\n\t    Suffix = function(Val: number)\n\t        return Val <= 1 and \"stud\" or \"studs\"\n\t    end,\n\t    Tooltip = \"How close a player must be to the pickup to be blamed for taking it\"\n\t})\n\tWindow = KitSpy:CreateSlider({\n\t    Name = \"Window\",\n\t    Min = 1,\n\t    Max = 10,\n\t    Default = 3,\n\t    Suffix = function(Val: number)\n\t        return Val > 1 and \"secs\" or \"sec\"\n\t    end,\n\t    Tooltip = \"How recently something must have happened to still count as that pickup\"\n\t})\n\tDelay = KitSpy:CreateSlider({\n\t    Name = \"Delay\",\n\t    Min = 0,\n\t    Max = 2,\n\t    Default = 0.5,\n\t    Decimal = 100,\n\t    Suffix = function(Val: number)\n\t        return Val == 1 and \"sec\" or \"secs\"\n\t    end,\n\t    Tooltip = \"Wait before reading their inventory after a dig or a bounty kill\"\n\t})\n\tItems = KitSpy:CreateTextList({\n\t    Name = \"Items\",\n\t    Placeholder = \"item type (iron_ingot)\",\n\t    Darker = true,\n\t    Tooltip = \"Only report these item types when someone digs, leave it empty to report everything\"\n\t})\n\tExtras = KitSpy:CreateTextList({\n\t    Name = \"Collectables\",\n\t    Default = {\n\t        \"alchemist_ingedients\",\n\t        \"alchemy_crystal\",\n\t        \"crystalheart_seed\",\n\t        \"ghost\",\n\t        \"murder_coin\",\n\t        \"shadow_coin\",\n\t        \"soulvine_seed\",\n\t        \"spirit_gardener_energy\",\n\t        \"spirit_gardener_seeds\",\n\t        \"tearbloom_seed\"\n\t    },\n\t    Darker = true,\n\t    Tooltip = \"Extra collectable tags to watch, reported by whoever was closest when they vanished\"\n\t})\n\tKitSpy:CreateButton({\n\t    Name = \"Reset totals\",\n\t    Function = function()\n\t        table.clear(Totals)\n\t        RefreshViewer()\n\t    end\n\t})\n\t\n\tlocal function KitName(Kit: string)\n\t    local Meta = bedwars.BedwarsKitMeta[Kit]\n\t    return Meta and Meta.name or Kit\n\tend\n\t\n\tlocal SortedKits: {string} = {}\n\tfor Kit: string in KitSpyFunctions do\n\t    table.insert(SortedKits, Kit)\n\tend\n\ttable.sort(SortedKits, function(A: string, B: string)\n\t    return KitName(A) < KitName(B)\n\tend)\n\tfor _, v: string in SortedKits do\n\t    Toggles[v] = KitSpy:CreateToggle({\n\t        Name = KitName(v),\n\t        Default = true\n\t    })\n\tend\nend)\n\nRun(function()\n\tlocal AutoPickpocket\n\tlocal Targets\n\tlocal Range\n\tlocal Hidden\n\t\n\tlocal Legit: number = GetFunctionRange(bedwars.MimicController.onKitLocalActivated) or 25\n\tlocal MimicPickPocket = bedwars.Handler:Get(\"MimicBlockPickPocketPlayer\")\n\tlocal Sounds = {bedwars.SoundList.MIMIC_PICKPOCKET_1, bedwars.SoundList.MIMIC_PICKPOCKET_2, bedwars.SoundList.MIMIC_PICKPOCKET_3}\n\tlocal RandomGenerator: Random = Random.new()\n\tlocal Attempted = setmetatable({}, {__mode = \"k\"})\n\tlocal Ready, Warned = false, 0\n\t\n\tAutoPickpocket = vape.Categories.Kits:CreateModule({\n\t    Name = \"AutoPickpocket\",\n\t    Function = function(Callback: boolean)\n\t        if Callback then\n\t            Ready = false\n\t            AutoPickpocket:Clean(bedwars.Client:Get(\"MimicBlockPickPocketReady\"):Connect(function(Event)\n\t                if Event.player == LocalPlayer then\n\t                    Ready = Event.ready and true or false\n\t                end\n\t            end))\n\t\n\t            repeat\n\t                local Success, Error = pcall(function()\n\t                    if not Entity.isAlive or Store.equippedKit ~= \"mimic\" then\n\t                        return\n\t                    end\n\t                    local LocalPosition: Vector3 = Entity.character.RootPart.Position\n\t                    local NearbyTargets = Entity.AllPosition({\n\t                        Range = Range.Value,\n\t                        Origin = LocalPosition,\n\t                        Wallcheck = Targets.Walls.Enabled or nil,\n\t                        Part = \"RootPart\",\n\t                        Players = true,\n\t                        Sort = SortMethods.Distance\n\t                    })\n\t\n\t                    for _, v: any in NearbyTargets do\n\t                        if not Ready then\n\t                            break\n\t                        end\n\t                        if not v.Character:HasTag(\"MimicBLockPickPocketPlayer\") then\n\t                            continue\n\t                        end\n\t                        if Attempted[v.Character] and tick() - Attempted[v.Character] < 0.5 then\n\t                            continue\n\t                        end\n\t                        Attempted[v.Character] = tick()\n\t                        Ready = false\n\t\n\t                        if MimicPickPocket:Fire(\"CallServer\", v.Player) then\n\t                            bedwars.AudioManager:playAudio(Sounds[RandomGenerator:NextInteger(1, #Sounds)], {\n\t                                playbackSpeedMultiplier = 1.27,\n\t                                position = LocalPosition\n\t                            })\n\t                        end\n\t                        break\n\t                    end\n\t\n\t                    if #NearbyTargets <= 0 and Hidden.Enabled and bedwars.AbilityController:canUseAbility(\"MIMIC_BLOCK_HIDDEN\", {disableBlockedAbilityAlert = true}) then\n\t                        bedwars.AbilityController:useAbility(\"MIMIC_BLOCK_HIDDEN\")\n\t                    end\n\t                end)\n\t\n\t                if not Success and tick() - Warned > 5 then\n\t                    Warned = tick()\n\t                    warn(`[catvape] AutoPickpocket: {Error}`)\n\t                end\n\t                task.wait(0.1)\n\t            until not AutoPickpocket.Enabled\n\t            table.clear(Attempted)\n\t        end\n\t    end,\n\t    Tooltip = \"Automatically pickpockets with milo kit.\"\n\t})\n\t\n\tTargets = AutoPickpocket:CreateTargets({Players = true, Walls = true})\n\t\n\tRange = AutoPickpocket:CreateSlider({\n\t    Name = \"Range\",\n\t    Min = 1,\n\t    Max = 30,\n\t    Default = Legit,\n\t    Suffix = function(Val: number)\n\t        return Val <= 1 and \"stud\" or \"studs\"\n\t    end\n\t})\n\tAutoPickpocket:CreateButton({\n\t    Name = \"Sync to legit range\",\n\t    Function = function()\n\t        Range:SetValue(Legit)\n\t    end\n\t})\n\tHidden = AutoPickpocket:CreateToggle({\n\t    Name = \"Hide when clear\",\n\t    Tooltip = \"Goes back into the block once nobody is in range\"\n\t})\nend)\n\nRun(function()\n\tlocal RavenTP\n\t\n\tRavenTP = vape.Categories.Kits:CreateModule({\n\t    Name = \"RavenTP\",\n\t    Function = function(Callback: boolean)\n\t        if Callback then\n\t            RavenTP:Toggle()\n\t            local Target = Entity.EntityMouse({\n\t                Range = 1000,\n\t                Players = true,\n\t                Part = \"RootPart\"\n\t            })\n\t\n\t            if GetItem(\"raven\") and Target then\n\t                bedwars.Handler:Get(\"SpawnRaven\"):Fire(\"CallServerAsync\"):andThen(function(Projectile: Model?)\n\t                    if Projectile then\n\t                        local BodyForce: BodyForce = Instance.new(\"BodyForce\")\n\t                        BodyForce.Force = Vector3.new(0, Projectile.PrimaryPart.AssemblyMass * workspace.Gravity, 0)\n\t                        BodyForce.Parent = Projectile.PrimaryPart\n\t\n\t                        if Target then\n\t                            task.spawn(function()\n\t                                for _ = 1, 20 do\n\t                                    if Target.RootPart and Projectile then\n\t                                        Projectile:SetPrimaryPartCFrame(CFrame.lookAlong(Target.RootPart.Position, Camera.CFrame.LookVector))\n\t                                    end\n\t                                    task.wait(0.05)\n\t                                end\n\t                            end)\n\t                            task.wait(0.3)\n\t                            bedwars.RavenController:detonateRaven()\n\t                        end\n\t                    end\n\t                end)\n\t            end\n\t        end\n\t    end,\n\t    Tooltip = \"Spawns and teleports a raven to a player\\nnear your mouse.\"\n\t})\nend)\n\nRun(function()\n\tlocal VoidRegentAutoClutch\n\tlocal Range\n\tlocal Depth\n\tlocal FallSpeed\n\tlocal FaceGround\n\tlocal LastClutch: number = 0\n\t\n\tVoidRegentAutoClutch = vape.Categories.Kits:CreateModule({\n\t    Name = \"VoidRegentAutoClutch\",\n\t    Function = function(Callback: boolean)\n\t        if Callback then\n\t            VoidRegentAutoClutch:Clean(RunService.Heartbeat:Connect(function()\n\t                if Entity.isAlive and Store.equippedKit == \"regent\" and Store.airRay and tick() >= LastClutch and bedwars.VoidAxeController then\n\t                    local Root: BasePart = Entity.character.RootPart\n\t                    if Root.AssemblyLinearVelocity.Y < -FallSpeed.Value and not Entity.Raycast(Root.Position, Vector3.new(0, -Depth.Value, 0), Store.airRay) and bedwars.AbilityController:canUseAbility(\"void_axe_jump\", {disableBlockedAbilityAlert = true}) then\n\t                        local Ground: Vector3? = GetNearGround(Range.Value / 3)\n\t                        local Delta: Vector3? = Ground and (Ground - Root.Position) * Vector3.new(1, 0, 1)\n\t                        if Delta and Delta.Magnitude > 0 then\n\t                            LastClutch = tick() + 0.5\n\t                            if FaceGround.Enabled then\n\t                                Root.CFrame = CFrame.lookAt(Root.Position, Root.Position + Delta.Unit)\n\t                            end\n\t                            bedwars.VoidAxeController:useVoidAxe()\n\t                        end\n\t                    end\n\t                end\n\t            end))\n\t        end\n\t    end,\n\t    Tooltip = \"Dashes the void axe back towards solid ground when you fall off the map\"\n\t})\n\t\n\tRange = VoidRegentAutoClutch:CreateSlider({\n\t    Name = \"Range\",\n\t    Min = 10,\n\t    Max = 60,\n\t    Default = 45,\n\t    Suffix = function(Val: number)\n\t        return Val <= 1 and \"stud\" or \"studs\"\n\t    end,\n\t    Tooltip = \"How far to look for ground to dash back to\"\n\t})\n\tDepth = VoidRegentAutoClutch:CreateSlider({\n\t    Name = \"Depth\",\n\t    Min = 10,\n\t    Max = 150,\n\t    Default = 60,\n\t    Suffix = function(Val: number)\n\t        return Val <= 1 and \"stud\" or \"studs\"\n\t    end,\n\t    Tooltip = \"Nothing beneath you within this counts as the void\"\n\t})\n\tFallSpeed = VoidRegentAutoClutch:CreateSlider({\n\t    Name = \"Fall speed\",\n\t    Min = 0,\n\t    Max = 100,\n\t    Default = 10,\n\t    Tooltip = \"Only clutches once you are dropping this fast\"\n\t})\n\tFaceGround = VoidRegentAutoClutch:CreateToggle({\n\t    Name = \"Face ground\",\n\t    Default = true,\n\t    Tooltip = \"Turns you towards the ground first, the dash always goes where you face\"\n\t})\nend)\n\nRun(function()\n\tlocal VulcanAssist\n\tlocal Targets\n\tlocal Range\n\tlocal Sort\n\t\n\tVulcanAssist = vape.Categories.Kits:CreateModule({\n\t    Name = \"VulcanAssist\",\n\t    Function = function(Callback: boolean)\n\t        if Callback then\n\t            repeat\n\t                local Turret = Entity.isAlive and bedwars.Store:getState().Game.selectedTurret\n\t                if Turret then\n\t                    local Origin: Vector3 = Turret.Rotate.Position\n\t                    local Ent = Entity.EntityMouse({\n\t                        Range = Range.Value,\n\t                        Origin = Origin,\n\t                        Wallcheck = Targets.Walls.Enabled or nil,\n\t                        Part = \"RootPart\",\n\t                        Players = Targets.Players.Enabled,\n\t                        NPCs = Targets.NPCs.Enabled,\n\t                        Priority = Targets.Priority.Value,\n\t                        Sort = SortMethods[Sort.Value]\n\t                    })\n\t                    local AimPosition: Vector3? = Ent and PredictionLib.SolveTrajectory(Origin, 320, 10, Ent.RootPart.Position, Ent.RootPart.AssemblyLinearVelocity, workspace.Gravity, Ent.HipHeight, nil, Store.airRay, Ent.Humanoid.FloorMaterial == Enum.Material.Air or math.abs(Ent.RootPart.AssemblyLinearVelocity.Y) > 0.01, Ent.RootPart.Position, Ent.RootPart)\n\t                    if AimPosition then\n\t                        local Delta: Vector3 = AimPosition - Origin\n\t                        bedwars.TurretCameraController.angleX = math.atan2(-Delta.X, -Delta.Z)\n\t                        bedwars.TurretCameraController.angleY = math.clamp(math.atan2(Delta.Y, math.sqrt(Delta.X ^ 2 + Delta.Z ^ 2)), -0.8, 0.8)\n\t                    end\n\t                end\n\t                task.wait(0.1)\n\t            until not VulcanAssist.Enabled\n\t        end\n\t    end,\n\t    Tooltip = \"Automatically aims turret camera toward opponents\"\n\t})\n\t\n\tTargets = VulcanAssist:CreateTargets({Walls = true, Players = true})\n\t\n\tlocal Methods: {string} = {\"Distance\", \"Damage\"}\n\tfor _, v: string in SortList do\n\t    if not table.find(Methods, v) then\n\t        table.insert(Methods, v)\n\t    end\n\tend\n\t\n\tSort = VulcanAssist:CreateDropdown({\n\t    Name = \"Target mode\",\n\t    List = Methods,\n\t    Default = Methods[1]\n\t})\n\tRange = VulcanAssist:CreateSlider({\n\t    Name = \"Range\",\n\t    Min = 1,\n\t    Max = 1000,\n\t    Default = 500\n\t})\nend)\n\nRun(function()\n\tlocal BedAlarm\n\tlocal Highlight\n\tlocal Pearls\n\tlocal Range\n\tlocal Volume\n\tlocal PearlTypes: {string} = {\"telepearl\", \"boba_pearl\", \"teleport_hat\"}\n\tlocal RayCheck: RaycastParams = RaycastParams.new()\n\tRayCheck.RespectCanCollide = true\n\t\n\tBedAlarm = vape.Legit:CreateModule({\n\t    Name = \"BedAlarm\",\n\t    Category = \"Game\",\n\t    Icon = GetVapeAsset(`{vape.Directory}/assets/new/legit_bedalarm.png`),\n\t    Function = function(Callback: boolean)\n\t        if Callback then\n\t            local Highlighted: {[Model]: boolean} = setmetatable({}, {__mode = \"k\"})\n\t            local Alerted: number = 0\n\t\n\t            local ProjectileLaunched = bedwars.SyncEvents.ProjectileLaunched:connect(function(Event)\n\t                if not Pearls.Enabled or not table.find(PearlTypes, Event.projectileType) or typeof(Event.origin) ~= \"Vector3\" or typeof(Event.launchVelocity) ~= \"Vector3\" then\n\t                    return\n\t                end\n\t                local Ent = Entity.getEntity(Event.shooter)\n\t                local Bed: BasePart?\n\t                if Ent and Ent.Targetable and Entity.isAlive then\n\t                    for _, v: BasePart in CollectionService:GetTagged(\"bed\") do\n\t                        if tonumber(v:GetAttribute(\"TeamId\")) == tonumber(LocalPlayer:GetAttribute(\"Team\")) then\n\t                            Bed = v\n\t                            break\n\t                        end\n\t                    end\n\t                end\n\t                if not Bed or os.clock() < Alerted then\n\t                    return\n\t                end\n\t\n\t                local ProjectileMeta = bedwars.ProjectileMeta[Event.projectileType]\n\t                local Drop: Vector3 = Vector3.new(0, -(ProjectileMeta and ProjectileMeta.gravitationalAcceleration or 196.2), 0)\n\t                local IgnoreList: {Instance} = {Event.shooter}\n\t                for _, v: any in Entity.List do\n\t                    table.insert(IgnoreList, v.Character)\n\t                end\n\t\n\t                RayCheck.FilterDescendantsInstances = IgnoreList\n\t                local Landing: Vector3 = Event.origin\n\t                for Step: number = 1, 100 do\n\t                    local FlightTime: number = Step * 0.05\n\t                    local Point: Vector3 = Event.origin + Event.launchVelocity * FlightTime + Drop * (0.5 * FlightTime * FlightTime)\n\t                    local Hit: RaycastResult? = Entity.Raycast(Landing, Point - Landing, RayCheck)\n\t                    if Hit then\n\t                        Landing = Hit.Position\n\t                        break\n\t                    end\n\t                    Landing = Point\n\t                end\n\t\n\t                if (Landing - Bed.Position).Magnitude > Range.Value then\n\t                    return\n\t                end\n\t\n\t                Alerted = os.clock() + 3.05\n\t                if Highlight.Enabled and Ent.Player and not Highlighted[Ent.Character] then\n\t                    Highlighted[Ent.Character] = true\n\t                    bedwars.BedAlarmController:addIntruderPlayerHighlight(Ent.Player)\n\t                end\n\t\n\t                bedwars.NotificationController:sendInfoNotification({message = \"[Bed Alarm]: An intruder pearled to your bed!\"})\n\t                local Near: boolean = (Entity.character.RootPart.Position - Bed.Position).Magnitude < 30\n\t                bedwars.AudioManager:playAudio(Near and bedwars.SoundList.BED_ALARM or bedwars.SoundList.BED_ALARM_TRIGGERED_FAR, {volumeMultiplier = Volume.Value, position = Near and Bed.Position or nil, rollOffMaxDistance = 100})\n\t            end)\n\t            BedAlarm:Clean(function()\n\t                ProjectileLaunched:Destroy()\n\t            end)\n\t\n\t            ;(function()\n\t                repeat\n\t                    local Bed: BasePart?\n\t                    if Entity.isAlive then\n\t                        for _, v: BasePart in CollectionService:GetTagged(\"bed\") do\n\t                            if tonumber(v:GetAttribute(\"TeamId\")) == tonumber(LocalPlayer:GetAttribute(\"Team\")) then\n\t                                Bed = v\n\t                                break\n\t                            end\n\t                        end\n\t                    end\n\t\n\t                    local Intruders = Bed and Entity.AllPosition({\n\t                        Origin = Bed.Position,\n\t                        Range = Range.Value,\n\t                        Part = \"RootPart\",\n\t                        Players = true\n\t                    })\n\t\n\t                    if Intruders and Intruders[1] and os.clock() > Alerted then\n\t                        Alerted = os.clock() + 3.05\n\t\n\t                        if Highlight.Enabled then\n\t                            for _, v: any in Intruders do\n\t                                if v.Player and not Highlighted[v.Character] then\n\t                                    Highlighted[v.Character] = true\n\t                                    bedwars.BedAlarmController:addIntruderPlayerHighlight(v.Player)\n\t                                end\n\t                            end\n\t                        end\n\t\n\t                        bedwars.NotificationController:sendInfoNotification({message = \"[Bed Alarm]: An intruder is near your bed!\"})\n\t                        local Near: boolean = (Entity.character.RootPart.Position - Bed.Position).Magnitude < 30\n\t                        bedwars.AudioManager:playAudio(Near and bedwars.SoundList.BED_ALARM or bedwars.SoundList.BED_ALARM_TRIGGERED_FAR, {volumeMultiplier = Volume.Value, position = Near and Bed.Position or nil, rollOffMaxDistance = 100})\n\t                    end\n\t\n\t                    task.wait(0.1)\n\t                until not BedAlarm.Enabled\n\t            end)()\n\t        end\n\t    end,\n\t    Tooltip = \"Notifies when an enemy is near your bed\"\n\t})\n\t\n\tHighlight = BedAlarm:CreateToggle({\n\t    Name = \"Highlight intruders\",\n\t    Default = true,\n\t    Tooltip = \"Outlines the intruders through walls\\n(just like bedwars own bed alarm)\"\n\t})\n\tPearls = BedAlarm:CreateToggle({\n\t    Name = \"Pearl detection\",\n\t    Default = true,\n\t    Tooltip = \"Also alarms the moment an enemy throws a pearl that lands at your bed\"\n\t})\n\tRange = BedAlarm:CreateSlider({\n\t    Name = \"Range\",\n\t    Min = 1,\n\t    Max = 100,\n\t    Default = 70,\n\t    Suffix = function(Val: number)\n\t        return Val == 1 and \"stud\" or \"studs\"\n\t    end\n\t})\n\tVolume = BedAlarm:CreateSlider({\n\t    Name = \"Volume multiplier\",\n\t    Min = 0.1,\n\t    Max = 2,\n\t    Default = 1.4,\n\t    Decimal = 100\n\t})\nend)\n\nRun(function()\n\tlocal BedBreakEffect\n\tlocal List\n\tlocal NameToId: {[string]: any} = {}\n\t\n\tBedBreakEffect = vape.Legit:CreateModule({\n\t    Name = \"Bed Break Effect\",\n\t    Category = \"Game\",\n\t    Icon = GetVapeAsset(`{vape.Directory}/assets/new/legit_bedbreakeffect.png`),\n\t    Function = function(Callback: boolean)\n\t        if Callback then\n\t            BedBreakEffect:Clean(VapeEvents.BedwarsBedBreak.Event:Connect(function(Data)\n\t                firesignal(bedwars.Handler:Get(\"BedBreakEffectTriggered\").Remote.instance.OnClientEvent, {\n\t                    player = Data.player,\n\t                    cframe = CFrame.new(Data.bedBlockPosition * 3),\n\t                    effectType = NameToId[List.Value],\n\t                    teamId = Data.brokenBedTeam.id,\n\t                    centerBedPosition = Data.bedBlockPosition * 3\n\t                })\n\t            end))\n\t        end\n\t    end,\n\t    Tooltip = \"Custom bed break effects\"\n\t})\n\t\n\tlocal BreakEffectName: {string} = {}\n\tfor EffectId: string, v: any in bedwars.BedBreakEffectMeta do\n\t    table.insert(BreakEffectName, v.name)\n\t    NameToId[v.name] = EffectId\n\tend\n\ttable.sort(BreakEffectName)\n\tList = BedBreakEffect:CreateDropdown({\n\t    Name = \"Effect\",\n\t    List = BreakEffectName\n\t})\nend)\n\nRun(function()\n\tlocal Old: (...any) -> ...any\n\t\n\tvape.Legit:CreateModule({\n\t    Name = \"Clean Kit\",\n\t    Category = \"Game\",\n\t    Icon = GetVapeAsset(`{vape.Directory}/assets/new/legit_cleankit.png`),\n\t    Function = function(Callback: boolean)\n\t        if Callback then\n\t            Old = bedwars.WindWalkerController.spawnOrb\n\t            bedwars.WindWalkerController.spawnOrb = function() end\n\t            local ZephyrEffect = LocalPlayer.PlayerGui:FindFirstChild(\"WindWalkerEffect\", true)\n\t            if ZephyrEffect then\n\t                ZephyrEffect.Visible = false\n\t            end\n