  Settings.blowUpSize = Size.Value\n\t            Settings.blowUpDuration = 0\n\t            Settings.baseColor = Color3.fromHSV(Color.Hue, Color.Sat, Color.Value)\n\t            Settings.blowUpCompleteDuration = 0\n\t            Settings.anchoredDuration = Anchor.Value\n\t        else\n\t            for Key: string, v: any in OldValues do\n\t                Settings[Key] = v\n\t            end\n\t            debug.setconstant(bedwars.DamageIndicator, DumpConstant(\"Enum.Font\"), OldFont)\n\t        end\n\t    end,\n\t    Tooltip = \"Customize the damage indicator\"\n\t})\n\t\n\tlocal FontItems: {string} = {\"GothamBlack\"}\n\tfor _, v: EnumItem in Enum.Font:GetEnumItems() do\n\t    if v.Name ~= \"GothamBlack\" then\n\t        table.insert(FontItems, v.Name)\n\t    end\n\tend\n\tFontOption = DamageIndicator:CreateDropdown({\n\t    Name = \"Font\",\n\t    List = FontItems,\n\t    Function = function(Val: string)\n\t        if DamageIndicator.Enabled then\n\t            debug.setconstant(bedwars.DamageIndicator, DumpConstant(\"Enum.Font\"), Enum.Font[Val])\n\t        end\n\t    end\n\t})\n\tColor = DamageIndicator:CreateColorSlider({\n\t    Name = \"Color\",\n\t    DefaultHue = 0,\n\t    Function = function(Hue: number, Sat: number, Val: number)\n\t        if DamageIndicator.Enabled then\n\t            Settings.baseColor = Color3.fromHSV(Hue, Sat, Val)\n\t        end\n\t    end\n\t})\n\tSize = DamageIndicator:CreateSlider({\n\t    Name = \"Size\",\n\t    Min = 1,\n\t    Max = 32,\n\t    Function = function(Val: number)\n\t        if DamageIndicator.Enabled then\n\t            Settings.textSize = Val\n\t            Settings.blowUpSize = Val\n\t        end\n\t    end,\n\t    Default = 32\n\t})\n\tAnchor = DamageIndicator:CreateSlider({\n\t    Name = \"Anchor\",\n\t    Min = 0,\n\t    Max = 1,\n\t    Decimal = 10,\n\t    Function = function(Val: number)\n\t        if DamageIndicator.Enabled then\n\t            Settings.anchoredDuration = Val\n\t        end\n\t    end\n\t