r({\n\t    Name = \"FOV\",\n\t    Min = 30,\n\t    Max = 120\n\t})\nend)\n\nRun(function()\n\tlocal Cap: number? = getfpscap and getfpscap() or nil\n\t\n\tvape.Legit:CreateModule({\n\t    Name = \"FPSUnlocker\",\n\t    Category = \"Game\",\n\t    Icon = GetVapeAsset(`{vape.Directory}/assets/new/legit_fpsunlocker.png`),\n\t    Function = function(Callback: boolean)\n\t        if Cap then\n\t            setfpscap(Callback and 9999 or Cap)\n\t        elseif Callback then\n\t            setfpscap(9999)\n\t            SendNotification(\"FPSUnlocker\", \"You have to restart ur game inorder to disable this.\", 8, \"info\")\n\t        end\n\t    end\n\t})\nend)\n\nRun(function()\n\tlocal HitColor\n\tlocal Color\n\tlocal Done: {Highlight} = {}\n\t\n\tHitColor = vape.Legit:CreateModule({\n\t    Name = \"Hit Color\",\n\t    Category = \"Game\",\n\t    Icon = GetVapeAsset(`{vape.Directory}/assets/new/legit_hitcolor.png`),\n\t    Function = function(Callback: boolean)\n\t        if Callback then\n\t            repeat\n\t                for _, v: any in Entity.List do\n\t                    local Highlight: Highlight? = v.Character and v.Character:FindFirstChild(\"_DamageHighlight_\")\n\t                    if Highlight then\n\t                        if not table.find(Done, Highlight) then\n\t                            table.insert(Done, Highlight)\n\t                        end\n\t                        Highlight.FillColor = Color3.fromHSV(Color.Hue, Color.Sat, Color.Value)\n\t                        Highlight.FillTransparency = Color.Opacity\n\t                    end\n\t                end\n\t                task.wait(0.1)\n\t            until not HitColor.Enabled\n\t        else\n\t            for _, v: Highlight in Done do\n\t                v.FillColor = Color3.new(1, 0, 0)\n\t                v.FillTransparency = 0.4\n\t            end\n\t            table.clear(Done)\n\t        end\n\t    end,\n\t    Tooltip = \"Customize the hit highlight options\"\n\t})\n\t\n\tColor =