tbar[\"1\"].BackgroundColor3 = Color3.fromHSV(Hue, Sat, Val)\n\t            end\n\t        end\n\t    end\n\t})\n\tHotbarColor = Interface:CreateColorSlider({\n\t    Name = \"Hotbar Color\",\n\t    DefaultOpacity = 0.8,\n\t    Function = function(Hue: number, Sat: number, Val: number, Opacity: number)\n\t        if not canDebug then\n\t            Refresh()\n\t            return\n\t        end\n\t        local InventoryRender = OldInventoryRender or HotbarOpenInventory.render\n\t        local Tile = FindComponent(\"HotbarTile\")\n\t        local AppRender = Tile and Tile.render\n\t        local MainColor: number = tonumber(Color3.fromHSV(Hue, Sat, Val):ToHex(), 16)\n\t        local BorderColor: number = tonumber(Color3.fromHSV(Hue, Sat, math.clamp(Val > 0.5 and Val - 0.2 or Val + 0.2, 0, 1)):ToHex(), 16)\n\t        local Fill: number = 1 - Opacity\n\t        local Hover: number = math.clamp(1.2 - Opacity, 0, 1)\n\t\n\t        local AppMain, AppBorder, AppFill, AppHover\n\t        if AppRender then\n\t            AppMain = Resolve(AppRender, \"Main\", 1909806)\n\t            AppBorder = Resolve(AppRender, \"Border\", 7503788)\n\t            AppFill = Resolve(AppRender, \"Fill\", 0.2, 1909806)\n\t            AppHover = Resolve(AppRender, \"Hover\", 0.4, 1909806)\n\t        end\n\t        local InventoryMain = Resolve(InventoryRender, \"Main\", 1909806)\n\t        local InventoryBorder = Resolve(InventoryRender, \"Border\", 7503788)\n\t        local InventoryHover = Resolve(InventoryRender, \"Hover\", 0.4)\n\t\n\t        ModifyConstant(AppRender, AppMain, MainColor)\n\t        ModifyConstant(AppRender, AppBorder, BorderColor)\n\t        ModifyConstant(AppRender, AppFill, Fill)\n\t        ModifyConstant(AppRender, AppHover, Hover)\n\t        ModifyConstant(InventoryRender, InventoryMain, MainColor)\n\t        ModifyConstant(InventoryRender, InventoryHover, Hover)\n\t        ModifyConstant(InventoryRender, InventoryBorder, BorderColor)\n\t    end\n\t})\nend)\n\nRun(funct