r(Parts[3]) or 0)\n\t        SongBPM = 60 / (tonumber(Parts[2]) or 50)\n\t        SongObject:Play()\n\t    end\n\tend\n\t\n\tSongBeats = vape.Legit:CreateModule({\n\t    Name = \"Song Beats\",\n\t    Category = \"Game\",\n\t    Icon = GetVapeAsset(`{vape.Directory}/assets/new/legit_songbeats.png`),\n\t    Function = function(Callback: boolean)\n\t        if Callback then\n\t            local Current = {}\n\t            Session = Current\n\t            SongObject = Instance.new(\"Sound\")\n\t            SongObject.Volume = Volume.Value / 100\n\t            SongObject.Parent = workspace\n\t            repeat\n\t                if not SongObject.Playing then\n\t                    ChooseSong()\n\t                end\n\t                if BeatTick < tick() and SongBeats.Enabled and FOV.Enabled then\n\t                    BeatTick = tick() + SongBPM\n\t                    OldFOV = math.min(bedwars.FovController:getFOV() * (bedwars.SprintController.sprinting and 1.1 or 1), 120)\n\t                    Camera.FieldOfView = OldFOV - FOVValue.Value\n\t                    SongTween = TweenService:Create(Camera, TweenInfo.new(math.min(SongBPM, 0.2), Enum.EasingStyle.Linear), {FieldOfView = OldFOV})\n\t                    SongTween:Play()\n\t                end\n\t                task.wait()\n\t            until not SongBeats.Enabled or Session ~= Current\n\t        else\n\t            if SongObject then\n\t                SongObject:Destroy()\n\t            end\n\t            if SongTween then\n\t                SongTween:Cancel()\n\t            end\n\t            if OldFOV then\n\t                Camera.FieldOfView = OldFOV\n\t            end\n\t            table.clear(AlreadyPicked)\n\t        end\n\t    end,\n\t    Tooltip = \"Built in mp3 player\"\n\t})\n\t\n\tList = SongBeats:CreateTextList({\n\t    Name = \"Songs\",\n\t    Placeholder = \"filepath/bpm/start\"\n\t})\n\tFOV = SongBeats:CreateToggle({\n\t    Name = \"Beat FOV\",\n\t    Function = function(Callback: boolean)\n\t        if FOVValue.Object then\n\t            FOVValue.Object.Visible = Callback\n\t        end\n\t        if SongBeats.Enabled then\n\t            SongBeats:Toggle()\n\t            SongBeats:Toggle()\n\t        end\n\t    end,\n\t    Default = true\n\t})\n\tFOVValue = SongBeats:CreateSlider({\n\t    Name = \"Adjustment\",\n\t    Min = 1,\n\t    Max = 30,\n\t    Default = 5,\n\t    Darker = true\n\t})\n\tVolume = SongBeats:CreateSlider({\n\t    Name = \"Volume\",\n\t    Function = function(Val: number)\n\t        if SongObject then\n\t            SongObject.Volume = Val / 100\n\t        end\n\t    end,\n\t    Min = 1,\n\t    Max = 100,\n\t    Default = 100,\n\t    Suffix = \"%\"\n\t})\nend)\n\nRun(function()\n\tlocal SoundChanger\n\tlocal List\n\tlocal SoundList: {[string]: string} = {}\n\tlocal Old: (...any) -> ...any\n\t\n\tSoundChanger = vape.Legit:CreateModule({\n\t    Name = \"SoundChanger\",\n\t    Category = \"Game\",\n\t    Icon = GetVapeAsset(`{vape.Directory}/assets/new/legit_soundchanger.png`),\n\t    Function = function(Callback: boolean)\n\t        if Callback then\n\t            Old = bedwars.AudioManager.playAudio\n\t            bedwars.AudioManager.playAudio = function(self, SoundId, ...)\n\t                if SoundList[SoundId] then\n\t                    SoundId = SoundList[SoundId]\n\t                end\n\t\n\t                return Old(self, SoundId, ...)\n\t            end\n\t        else\n\t            bedwars.AudioManager.playAudio = Old\n\t        end\n\t    end,\n\t    Tooltip = \"Change ingame sounds to custom ones.\"\n\t})\n\t\n\tList = SoundChanger:CreateTextList({\n\t    Name = \"Sounds\",\n\t    Placeholder = \"(DAMAGE_1/ben.mp3)\",\n\t    Function = function()\n\t        table.clear(SoundList)\n\t        for _, v: string in List.ListEnabled do\n\t            local Parts: {string} = v:split(\"/\")\n\t            local SoundId: string? = bedwars.SoundList[Parts[1]]\n\t            if SoundId and #Parts > 1 then\n\t                SoundList[SoundId] = Parts[2]:find(\"rbxasset\") and Parts[2] or isfile(Parts[2]) and AssetFunction(Parts[2]) or \"\"\n\t            end\n\t        end\n\t    end\n\t})\nend)\n\nRun(function()\n\tlocal UICleanup\n\tlocal OpenInventory\n\tlocal KillFeed\n\tlocal OldTabList\n\tlocal ResizeHealth\n\tlocal NoNumbers\n\tlocal OriginalPlayerList: boolean?\n\tlocal HotbarApp = canDebug and GetRoactRender(require(LocalPlayer.PlayerScripts.TS.controllers.global.hotbar.ui[\"hotbar-app\"]).HotbarApp.render)\n\tlocal HotbarOpenInventory = canDebug and require(LocalPlayer.PlayerScripts.TS.controllers.global.hotbar.ui[\"hotbar-open-inventory\"]).HotbarOpenInventory\n\tlocal OldConstants, NewConstants = {}, {}\n\tlocal Indices: {[any]: {[string]: number}} = {}\n\tlocal OldKillFeed\n\tlocal GuiOverrides = CreateGuiOverrides()\n\t\n\tlocal function Added(Object: Instance)\n\t    if not UICleanup.Enabled then\n\t        return\n\t    end\n\t    if Object:IsA(\"ScreenGui\") and Object.Name == \"KillFeedGui\" and KillFeed.Enabled then\n\t        GuiOverrides.Apply(Object, {Enabled = false})\n\t    elseif Object:IsA(\"GuiObject\") and Object:FindFirstAncestor(\"hotbar\") then\n\t        if Object.Name == \"HotbarHealthbarContainer\" and ResizeHealth.Enabled then\n\t            GuiOverrides.Apply(Object, {Size = UDim2.new(1, 0, Object.Size.Y.Scale, Object.Size.Y.Offset)})\n\t        elseif Object.Parent.Name == \"ItemsHotbar\" and Object.Name == \"10\" and OpenInventory.Enabled then\n\t            GuiOverrides.Apply(Object, {Visible = false})\n\t        elseif Object:IsA(\"TextLabel\") and Object.Parent:IsA(\"ImageButton\") and Object:FindFirstAncestor(\"ItemsHotbar\") and NoNumbers.Enabled then\n\t            GuiOverrides.Apply(Object, {Visible = false})\n\t        end\n\t    end\n\tend\n\t\n\tlocal function Refresh()\n\t    GuiOverrides.Restore()\n\t    if UICleanup.Enabled then\n\t        for _, v: Instance in LocalPlayer.PlayerGui:GetDescendants() do\n\t            Added(v)\n\t        end\n\t    end\n\tend\n\t\n\tvape:Clean(function()\n\t    for _, v: {[number]: any} in NewConstants do\n\t        table.clear(v)\n\t    end\n\t    for _, v: {[number]: any} in OldConstants do\n\t        table.clear(v)\n\t    end\n\t    table.clear(NewConstants)\n\t    table.clear(OldConstants)\n\t    table.clear(Indices)\n\tend)\n\t\n\tlocal function FindComponent(Name: string)\n\t    if not HotbarApp then\n\t        return nil\n\t    end\n\t    for Index: number = 1, 64 do\n\t        local Success, Value = pcall(debug.getupvalue, HotbarApp, Index)\n\t        if not Success then\n\t            break\n\t        end\n\t        if type(Value) == \"table\" and rawget(Value, \"__componentName\") == Name then\n\t            return Value\n\t        end\n\t    end\n\t    return nil\n\tend\n\t\n\tlocal function Resolve(Function, Key: string, Value: any, After: any?): number?\n\t    if typeof(Function) ~= \"function\" then\n\t        return nil\n\t    end\n\t    local Known: {[string]: number}? = Indices[Function]\n\t    if Known and Known[Key] then\n\t        return Known[Key]\n\t    end\n\t    local Index: number? = getgenv().findConstant(Function, Value, After)\n\t    if Index then\n\t        Indices[Function] = Known or {}\n\t        Indices[Function][Key] = Index\n\t    end\n\t    return Index\n\tend\n\t\n\tlocal function ModifyConstant(Function, Index: number?, Value)\n\t    if not Function or not Index then\n\t        return\n\t    end\n\t    local Saved: {[number]: any}? = OldConstants[Function]\n\t    local Original: any = Saved and Saved[Index]\n\t    if Original == nil then\n\t        if Value == nil then\n\t            return\n\t        end\n\t        local Valid: boolean\n\t        Valid, Original = pcall(debug.getconstant, Function, Index)\n\t        if not Valid or typeof(Original) ~= typeof(Value) then\n\t            return\n\t        end\n\t    end\n\t\n\t    OldConstants[Function] = Saved or {}\n\t    NewConstants[Function] = NewConstants[Function] or {}\n\t    OldConstants[Function][Index] = Original\n\t    NewConstants[Function][Index] = Value\n\t    if UICleanup.Enabled then\n\t        if Value then\n\t            debug.setconstant(Function, Index, Value)\n\t        else\n\t            debug.setconstant(Function, Index, Original)\n\t            OldConstants[Function][Index] = nil\n\t        end\n\t    end\n\tend\n\t\n\tUICleanup = vape.Legit:CreateModule({\n\t    Name = \"UI Cleanup\",\n\t    Category = \"Game\",\n\t    Icon = GetVapeAsset(`{vape.Directory}/assets/new/legit_uicleanup.png`),\n\t    Function = function(Callback: boolean)\n\t        if not canDebug then\n\t            if Callback then\n\t                OriginalPlayerList = StarterGui:GetCoreGuiEnabled(Enum.CoreGuiType.PlayerList)\n\t                UICleanup:Clean(GuiOverrides.Restore)\n\t                UICleanup:Clean(LocalPlayer.PlayerGui.DescendantAdded:Connect(Added))\n\t                StarterGui:SetCoreGuiEnabled(Enum.CoreGuiType.PlayerList, OldTabList.Enabled)\n\t            elseif OriginalPlayerList ~= nil then\n\t                StarterGui:SetCoreGuiEnabled(Enum.CoreGuiType.PlayerList, OriginalPlayerList)\n\t                OriginalPlayerList = nil\n\t            end\n\t            Refresh()\n\t            return\n\t        end\n\t\n\t        for Function: (...any) -> ...any, Constants: {[number]: any} in (Callback and NewConstants or OldConstants) do\n\t            for i: number, Value: any in Constants do\n\t                debug.setconstant(Function, i, Value)\n\t            end\n\t        end\n\t        if Callback then\n\t            if OpenInventory.Enabled then\n\t                OldInventoryRender = HotbarOpenInventory.render\n\t                HotbarOpenInventory.render = function()\n\t                    return bedwars.Roact.createElement(\"TextButton\", {Visible = false}, {})\n\t                end\n\t            end\n\t\n\t            if KillFeed.Enabled then\n\t                OldKillFeed = bedwars.KillFeedController.addToKillFeed\n\t                bedwars.KillFeedController.addToKillFeed = function() end\n\t            end\n\t\n\t            if OldTabList.Enabled then\n\t                StarterGui:SetCoreGuiEnabled(Enum.CoreGuiType.PlayerList, true)\n\t            end\n\t        else\n\t            if OldInventoryRender then\n\t                HotbarOpenInventory.render = OldInventoryRender\n\t                OldInventoryRender = nil\n\t            end\n\t\n\t            if KillFeed.Enabled then\n\t                bedwars.KillFeedController.addToKillFeed = OldKillFeed\n\t                OldKillFeed = nil\n\t            end\n\t\n\t            if OldTabList.Enabled then\n\t                StarterGui:SetCoreGuiEnabled(Enum.CoreGuiType.PlayerList, false)\n\t            end\n\t        end\n\t    end,\n\t    Tooltip = \"Cleans up the UI for kits & main\"\n\t})\n\t\n\tResizeHealth = UICleanup:CreateToggle({\n\t    Name = \"Resize Health\",\n\t    Function = function(Callback: boolean)\n\t        if not canDebug then\n\t            Refresh()\n\t            return\n\t        end\n\t        local Healthbar = FindComponent(\"HotbarHealthbar\")\n\t        local Tile = FindComponent(\"HotbarTile\")\n\t        ModifyConstant(HotbarApp, Resolve(HotbarApp, \"Width\", 0.6), Callback and 1 or nil)\n\t        ModifyConstant(Healthbar and Healthbar.render, Healthbar and Resolve(Healthbar.render, \"Width\", 0.85), Callback and 1 or nil)\n\t        ModifyConstant(Tile and Tile.tweenPosition, Tile and Resolve(Tile.tweenPosition, \"Lift\", -0.075), Callback and 0 or nil)\n\t    end,\n\t    Default = true\n\t})\n\tNoNumbers = UICleanup:CreateToggle({\n\t    Name = \"No Hotbar Numbers\",\n\t    Function = function(Callback: boolean)\n\t        if not canDebug then\n\t            Refresh()\n\t            return\n\t        end\n\t        local Tile = FindComponent(\"HotbarTile\")\n\t        local InventoryRender = OldInventoryRender or HotbarOpenInventory.render\n\t        ModifyConstant(Tile and Tile.render, Tile and Resolve(Tile.render, \"Number\", 0.23, \"Keybind\"), Callback and 0 or nil)\n\t        ModifyConstant(InventoryRender, Resolve(InventoryRender, \"Number\", 0.23), Callback and 0 or nil)\n\t    end,\n\t    Default = true\n\t})\n\tOpenInventory = UICleanup:CreateToggle({\n\t    Name = \"No Inventory Button\",\n\t    Function = function(Callback: boolean)\n\t        if not canDebug then\n\t            Refresh()\n\t            return\n\t        end\n\t        if UICleanup.Enabled then\n\t            if Callback then\n\t                OldInventoryRender = HotbarOpenInventory.render\n\t                HotbarOpenInventory.render = function()\n\t                    return bedwars.Roact.createElement(\"TextButton\", {Visible = false}, {})\n\t                end\n\t            else\n\t                HotbarOpenInventory.render = OldInventoryRender\n\t                OldInventoryRender = nil\n\t            end\n\t        end\n\t    end,\n\t    Default = true\n\t})\n\tKillFeed = UICleanup:CreateToggle({\n\t    Name = \"No Kill Feed\",\n\t    Function = function(Callback: boolean)\n\t        if not canDebug then\n\t            Refresh()\n\t            return\n\t        end\n\t        if UICleanup.Enabled then\n\t            if Callback then\n\t                OldKillFeed = bedwars.KillFeedController.addToKillFeed\n\t                bedwars.KillFeedController.addToKillFeed = function() end\n\t            else\n\t                bedwars.KillFeedController.addToKillFeed = OldKillFeed\n\t                OldKillFeed = nil\n\t            end\n\t        end\n\t    end,\n\t    Default = true\n\t})\n\tOldTabList = UICleanup:CreateToggle({\n\t    Name = \"Old Player List\",\n\t    Function = function(Callback: boolean)\n\t        if UICleanup.Enabled then\n\t            StarterGui:SetCoreGuiEnabled(Enum.CoreGuiType.PlayerList, Callback)\n\t        end\n\t    end,\n\t    Default = true\n\t})\n\tUICleanup:CreateToggle({\n\t    Name = \"Fix Queue Card\",\n\t    Function = function(Callback: boolean)\n\t        if not canDebug then\n\t            return\n\t        end\n\t        ModifyConstant(bedwars.QueueCard.render, Resolve(bedwars.QueueCard.render, \"Card\", 0.01), Callback and 0.1 or nil)\n\t    end,\n\t    Visible = canDebug,\n\t    Default = true\n\t})\nend)\n\nRun(function()\n\tlocal Viewmodel\n\tlocal Depth\n\tlocal Horizontal\n\tlocal Vertical\n\tlocal Size\n\tlocal NoBob\n\tlocal Visuals\n\tlocal FillColor\n\tlocal OutlineColor\n\tlocal Rotations = {}\n\tlocal Highlights: {Highlight} = {}\n\tlocal Old, OldC1\n\tlocal RootJoint, RootC0, RootOffset\n\tlocal Rig: Model?\n\t\n\tlocal function HighlightAccessory(Accessory: Accessory)\n\t    local Handle: BasePart? = Accessory:FindFirstChild(\"Handle\")\n\t    if Handle then\n\t        local Highlight: Highlight = Instance.new(\"Highlight\")\n\t        Highlight.Name = \"ViewmodelVisuals\"\n\t        Highlight.FillColor = Color3.fromHSV(FillColor.Hue, FillColor.Sat, FillColor.Value)\n\t        Highlight.FillTransparency = FillColor.Opacity\n\t        Highlight.OutlineColor = Color3.fromHSV(OutlineColor.Hue, OutlineColor.Sat, OutlineColor.Value)\n\t        Highlight.OutlineTransparency = OutlineColor.Opacity\n\t        Highlight.Parent = Handle\n\t        table.insert(Highlights, Highlight)\n\t    end\n\tend\n\t\n\tlocal function StartViewmodel()\n\t    local ViewmodelRig: Model?\n\t    repeat\n\t        ViewmodelRig = Camera:FindFirstChild(\"Viewmodel\")\n\t        if ViewmodelRig or not Viewmodel.Enabled then\n\t            break\n\t        end\n\t        task.wait(0.1)\n\t    until false\n\t    if not ViewmodelRig or not Viewmodel.Enabled or Rig == ViewmodelRig then\n\t        return\n\t    end\n\t\n\t    Rig = ViewmodelRig\n\t    ViewmodelRig:ScaleTo(1)\n\t    OldC1 = ViewmodelRig.RightHand.RightWrist.C1\n\t    ViewmodelRig.RightHand.RightWrist.C1 = OldC1 * CFrame.Angles(math.rad(Rotations[1].Value), math.rad(Rotations[2].Value), math.rad(Rotations[3].Value))\n\t    local LowerTorso: BasePart? = ViewmodelRig:FindFirstChild(\"LowerTorso\")\n\t    local Accessory: Accessory? = ViewmodelRig:FindFirstChildWhichIsA(\"Accessory\")\n\t    local Reference = Accessory and Accessory:FindFirstChild(\"Handle\") or ViewmodelRig:FindFirstChild(\"RightHand\")\n\t    RootJoint = LowerTorso and LowerTorso:FindFirstChildWhichIsA(\"Motor6D\")\n\t    RootC0 = RootJoint and RootJoint.C0\n\t    RootOffset = Reference and ViewmodelRig.HumanoidRootPart.CFrame:PointToObjectSpace(Reference.Position)\n\t    ViewmodelRig:ScaleTo(Size.Value)\n\t    if RootJoint and RootC0 and RootOffset then\n\t        RootJoint.C0 = (RootC0 - RootC0.Position) + (RootC0.Position * Size.Value) + (RootOffset * (1 - Size.Value))\n\t    end\n\t\n\t    Viewmodel:Clean(ViewmodelRig.ChildAdded:Connect(function(Child: Instance)\n\t        if Child:IsA(\"Accessory\") and Size.Value ~= 1 then\n\t            if Store.matchState == 0 then\n\t                repeat\n\t                    task.wait()\n\t                until Store.matchState ~= 0\n\t                task.wait(0.5)\n\t            end\n\t            bedwars.scaleTool(Child, Size.Value)\n\t        end\n\t    end))\n\t    bedwars.InventoryViewmodelController:handleStore(bedwars.Store:getState())\n\tend\n\t\n\tlocal function StartVisuals()\n\t    local ViewmodelRig: Model?\n\t    repeat\n\t        ViewmodelRig = Camera:FindFirstChild(\"Viewmodel\")\n\t        if ViewmodelRig or not Viewmodel.Enabled then\n\t            break\n\t        end\n\t        task.wait(0.1)\n\t    until false\n\t    if not ViewmodelRig or not Viewmodel.Enabled then\n\t        return\n\t    end\n\t\n\t    for _, v: Instance in ViewmodelRig:GetChildren() do\n\t        if v:IsA(\"Accessory\") then\n\t            HighlightAccessory(v)\n\t        end\n\t    end\n\t\n\t    Viewmodel:Clean(ViewmodelRig.ChildAdded:Connect(function(Child: Instance)\n\t        for i: number = #Highlights, 1, -1 do\n\t            if not Highlights[i].Parent then\n\t                table.remove(Highlights, i)\n\t            end\n\t        end\n\t        if Child:IsA(\"Accessory\") then\n\t            HighlightAccessory(Child)\n\t        end\n\t    end))\n\tend\n\t\n\tViewmodel = vape.Legit:CreateModule({\n\t    Name = \"Viewmodel\",\n\t    Category = \"Game\",\n\t    Icon = GetVapeAsset(`{vape.Directory}/assets/new/legit_viewmodel.png`),\n\t    Function = function(Callback: boolean)\n\t        local ViewmodelRig: Model? = Camera:FindFirstChild(\"Viewmodel\")\n\t        if Callback then\n\t            Old = bedwars.ViewmodelController.playAnimation\n\t            if NoBob.Enabled then\n\t                bedwars.ViewmodelController.playAnimation = function(self, AnimationType, ...)\n\t                    if bedwars.AnimationType and AnimationType == bedwars.AnimationType.FP_WALK then\n\t                        return\n\t                    end\n\t                    return Old(self, AnimationType, ...)\n\t                end\n\t            end\n\t\n\t            Viewmodel:Clean(function()\n\t                for _, v: Highlight in Highlights do\n\t                    v:Destroy()\n\t                end\n\t            end)\n\t            Viewmodel:Clean(Camera.ChildAdded:Connect(function(Child: Instance)\n\t                if Child.Name == \"Viewmodel\" then\n\t                    StartViewmodel()\n\t\n\t                    if Visuals.Enabled then\n\t                        StartVisuals()\n\t                    end\n\t                end\n\t            end))\n\t            LocalPlayer.PlayerScripts.TS.controllers.global.viewmodel[\"viewmodel-controller\"]:SetAttribute(\"ConstantManager_DEPTH_OFFSET\", -Depth.Value)\n\t            LocalPlayer.PlayerScripts.TS.controllers.global.viewmodel[\"viewmodel-controller\"]:SetAttribute(\"ConstantManager_HORIZONTAL_OFFSET\", Horizontal.Value)\n\t            LocalPlayer.PlayerScripts.TS.controllers.global.viewmodel[\"viewmodel-controller\"]:SetAttribute(\"ConstantManager_VERTICAL_OFFSET\", Vertical.Value)\n\t\n\t            StartViewmodel()\n\t\n\t            if Visuals.Enabled then\n\t                StartVisuals()\n\t            end\n\t        else\n\t            bedwars.ViewmodelController.playAnimation = Old\n\t            if ViewmodelRig and OldC1 then\n\t                ViewmodelRig:ScaleTo(1)\n\t                ViewmodelRig.RightHand.RightWrist.C1 = OldC1\n\t\n\t                if RootJoint and RootC0 then\n\t                    RootJoint.C0 = RootC0\n\t                end\n\t            end\n\t\n\t            OldC1 = nil\n\t            Rig = nil\n\t            RootJoint = nil\n\t\n\t            bedwars.InventoryViewmodelController:handleStore(bedwars.Store:getState())\n\t            LocalPlayer.PlayerScripts.TS.controllers.global.viewmodel[\"viewmodel-controller\"]:SetAttribute(\"ConstantManager_DEPTH_OFFSET\", 0)\n\t            LocalPlayer.PlayerScripts.TS.controllers.global.viewmodel[\"viewmodel-controller\"]:SetAttribute(\"ConstantManager_HORIZONTAL_OFFSET\", 0)\n\t            LocalPlayer.PlayerScripts.TS.controllers.global.viewmodel[\"viewmodel-controller\"]:SetAttribute(\"ConstantManager_VERTICAL_OFFSET\", 0)\n\t            table.clear(Highlights)\n\t        end\n\t    end,\n\t    Tooltip = \"Changes the viewmodel animations and visuals\"\n\t})\n\t\n\tDepth = Viewmodel:CreateSlider({\n\t    Name = \"Depth\",\n\t    Min = 0,\n\t    Max = 2,\n\t    Decimal = 10,\n\t    Function = function(Val: number)\n\t        if Viewmodel.Enabled then\n\t            LocalPlayer.PlayerScripts.TS.controllers.global.viewmodel[\"viewmodel-controller\"]:SetAttribute(\"ConstantManager_DEPTH_OFFSET\", -Val)\n\t        end\n\t    end,\n\t    Default = 0.8\n\t})\n\tHorizontal = Viewmodel:CreateSlider({\n\t    Name = \"Horizontal\",\n\t    Min = 0,\n\t    Max = 2,\n\t    Decimal = 10,\n\t    Function = function(Val: number)\n\t        if Viewmodel.Enabled then\n\t            LocalPlayer.PlayerScripts.TS.controllers.global.viewmodel[\"viewmodel-controller\"]:SetAttribute(\"ConstantManager_HORIZONTAL_OFFSET\", Val)\n\t        end\n\t    end,\n\t    Default = 0.8\n\t})\n\tVertical = Viewmodel:CreateSlider({\n\t    Name = \"Vertical\",\n\t    Min = -0.2,\n\t    Max = 2,\n\t    Decimal = 10,\n\t    Function = function(Val: number)\n\t        if Viewmodel.Enabled then\n\t            LocalPlayer.PlayerScripts.TS.controllers.global.viewmodel[\"viewmodel-controller\"]:SetAttribute(\"ConstantManager_VERTICAL_OFFSET\", Val)\n\t        end\n\t    end,\n\t    Default = -0.2\n\t})\n\tSize = Viewmodel:CreateSlider({\n\t    Name = \"Size\",\n\t    Min = 0.1,\n\t    Max = 2,\n\t    Decimal = 10,\n\t    Function = function(Val: number)\n\t        if Viewmodel.Enabled and Camera:FindFirstChild(\"Viewmodel\") then\n\t            Camera.Viewmodel:ScaleTo(Val)\n\t            if RootJoint and RootC0 and RootOffset then\n\t                RootJoint.C0 = (RootC0 - RootC0.Position) + (RootC0.Position * Val) + (RootOffset * (1 - Val))\n\t            end\n\t        end\n\t    end,\n\t    Default = 1\n\t})\n\tfor _, v: string in {\"Rotation X\", \"Rotation Y\", \"Rotation Z\"} do\n\t    table.insert(Rotations, Viewmodel:CreateSlider({\n\t        Name = v,\n\t        Min = 0,\n\t        Max = 360,\n\t        Function = function(Val: number)\n\t            if Viewmodel.Enabled and OldC1 and Camera:FindFirstChild(\"Viewmodel\") then\n\t                Camera.Viewmodel.RightHand.RightWrist.C1 = (OldC1 + OldC1.Position * (Size.Value - 1)) * CFrame.Angles(math.rad(Rotations[1].Value), math.rad(Rotations[2].Value), math.rad(Rotations[3].Value))\n\t            end\n\t        end\n\t    }))\n\tend\n\tNoBob = Viewmodel:CreateToggle({\n\t    Name = \"No Bobbing\",\n\t    Function = function()\n\t        if Viewmodel.Enabled then\n\t            Viewmodel:Toggle()\n\t            Viewmodel:Toggle()\n\t        end\n\t    end,\n\t    Default = true\n\t})\n\tVisuals = Viewmodel:CreateToggle({\n\t    Name = \"Visuals\",\n\t    Function = function(Callback: boolean)\n\t        FillColor.Object.Visible = Callback\n\t        OutlineColor.Object.Visible = Callback\n\t        if Viewmodel.Enabled then\n\t            Viewmodel:Toggle()\n\t            Viewmodel:Toggle()\n\t        end\n\t    end,\n\t    Tooltip = \"Highlights the item held in your viewmodel\"\n\t})\n\tFillColor = Viewmodel:CreateColorSlider({\n\t    Name = \"Fill Color\",\n\t    DefaultSat = 0,\n\t    DefaultOpacity = 0.5,\n\t    Darker = true,\n\t    Visible = false,\n\t    Function = function(Hue: number, Sat: number, Val: number, Opacity: number)\n\t        for _, v: Highlight in Highlights do\n\t            v.FillColor = Color3.fromHSV(Hue, Sat, Val)\n\t            v.FillTransparency = Opacity\n\t        end\n\t    end\n\t})\n\tOutlineColor = Viewmodel:CreateColorSlider({\n\t    Name = \"Outline Color\",\n\t    DefaultValue = 0,\n\t    DefaultOpacity = 0,\n\t    Darker = true,\n\t    Visible = false,\n\t    Function = function(Hue: number, Sat: number, Val: number, Opacity: number)\n\t        for _, v: Highlight in Highlights do\n\t            v.OutlineColor = Color3.fromHSV(Hue, Sat, Val)\n\t            v.OutlineTransparency = Opacity\n\t        end\n\t    end\n\t})\nend)\n\nRun(function()\n\tlocal WinEffect\n\tlocal List\n\tlocal NameToId: {[string]: any} = {}\n\t\n\tWinEffect = vape.Legit:CreateModule({\n\t    Name = \"WinEffect\",\n\t    Category = \"Game\",\n\t    Icon = GetVapeAsset(`{vape.Directory}/assets/new/legit_wineffect.png`),\n\t    Function = function(Callback: boolean)\n\t        if Callback then\n\t            if not canDebug then\n\t                SendNotification(\"WinEffect\", \"This executor cannot trigger the game's win effect callbacks\", 5)\n\t                WinEffect:Toggle()\n\t                return\n\t            end\n\t            WinEffect:Clean(VapeEvents.MatchEndEvent.Event:Connect(function()\n\t                for _, v: any in getconnections(bedwars.Handler:Get(\"WinEffectTriggered\").Remote.instance.OnClientEvent) do\n\t                    if v.Function then\n\t                        v.Function({\n\t                            winEffectType = NameToId[List.Value],\n\t                            winningPlayer = LocalPlayer\n\t                        })\n\t                    end\n\t                end\n\t            end))\n\t        end\n\t    end,\n\t    Tooltip = \"Allows you to select any clientside win effect\"\n\t})\n\t\n\tlocal WinEffectName: {string} = {}\n\tfor EffectId: string, v: any in bedwars.WinEffectMeta do\n\t    table.insert(WinEffectName, v.name)\n\t    NameToId[v.name] = EffectId\n\tend\n\ttable.sort(WinEffectName)\n\tList = WinEffect:CreateDropdown({\n\t    Name = \"Effects\",\n\t    List = WinEffectName\n\t})\nend)\n\nRun(function()\n\tlocal Zoom\n\tlocal Level\n\tlocal Speed\n\tlocal Sensitivity\n\t\n\tlocal OldSetFOV, OldGetFOV, OldSensitivity\n\tlocal Current, Target = 0, 0\n\tlocal OriginalFOV: number?\n\t\n\tlocal function GetBaseFOV(): number\n\t    local FOV = vape.Legit.Modules.FOV\n\t    return FOV and FOV.Enabled and FOV.Options.FOV.Value or bedwars.Store:getState().Settings.fov or OriginalFOV or Camera.FieldOfView\n\tend\n\t\n\tZoom = vape.Legit:CreateModule({\n\t    Name = \"Zoom\",\n\t    Category = \"Game\",\n\t    Icon = GetVapeAsset(`{vape.Directory}/assets/new/legit_fov.png`),\n\t    Function = function(Callback: boolean)\n\t        if not canDebug then\n\t            if Callback then\n\t                OriginalFOV = Camera.FieldOfView\n\t                Current = GetBaseFOV()\n\t                if Sensitivity.Enabled then\n\t                    OldSensitivity = UserInputService.MouseDeltaSensitivity\n\t                    UserInputService.MouseDeltaSensitivity = OldSensitivity / Level.Value\n\t                end\n\t\n\t                Zoom:Clean(RunService.PreRender:Connect(function(Delta: number)\n\t                    Target = GetBaseFOV() / Level.Value\n\t                    Current += (Target - Current) * math.clamp(Speed.Value * Delta, 0, 1)\n\t                    Camera.FieldOfView = Current\n\t                end))\n\t            else\n\t                Camera.FieldOfView = GetBaseFOV()\n\t                OriginalFOV = nil\n\t                if OldSensitivity then\n\t                    UserInputService.MouseDeltaSensitivity = OldSensitivity\n\t                    OldSensitivity = nil\n\t                end\n\t            end\n\t            return\n\t        end\n\t\n\t        if Callback then\n\t            local Base: number = bedwars.FovController:getFOV()\n\t            Current, Target = Base, Base / Level.Value\n\t\n\t            OldSetFOV = bedwars.FovController.setFOV\n\t            OldGetFOV = bedwars.FovController.getFOV\n\t            bedwars.FovController.setFOV = function(self, Value: number?)\n\t                Base = Value or Base\n\t                Target = Base / Level.Value\n\t                return OldSetFOV(self, Current)\n\t            end\n\t            bedwars.FovController.getFOV = function()\n\t                return Current\n\t            end\n\t\n\t            if Sensitivity.Enabled then\n\t                OldSensitivity = UserInputService.MouseDeltaSensitivity\n\t                UserInputService.MouseDeltaSensitivity = OldSensitivity / Level.Value\n\t            end\n\t\n\t            Zoom:Clean(RunService.PreRender:Connect(function(Delta: number)\n\t                Target = Base / Level.Value\n\t                Current = Current + (Target - Current) * math.clamp(Speed.Value * Delta, 0, 1)\n\t                OldSetFOV(bedwars.FovController, Current)\n\t            end))\n\t        else\n\t            bedwars.FovController.setFOV = OldSetFOV\n\t            bedwars.FovController.getFOV = OldGetFOV\n\t\n\t            if OldSensitivity then\n\t                UserInputService.MouseDeltaSensitivity = OldSensitivity\n\t                OldSensitivity = nil\n\t            end\n\t\n\t            if OldSetFOV then\n\t                bedwars.FovController:setFOV(bedwars.Store:getState().Settings.fov)\n\t            end\n\t        end\n\t    end,\n\t    Tooltip = \"Zooms your view in while it is on, bind it to a key and hold it like a scope\"\n\t})\n\t\n\tLevel = Zoom:CreateSlider({\n\t    Name = \"Level\",\n\t    Min = 1.1,\n\t    Max = 6,\n\t    Default = 3,\n\t    Decimal = 10,\n\t    Suffix = \"x\"\n\t})\n\tSpeed = Zoom:CreateSlider({\n\t    Name = \"Speed\",\n\t    Min = 1,\n\t    Max = 30,\n\t    Default = 12,\n\t    Tooltip = \"How fast the zoom eases in and out, higher is snappier\"\n\t})\n\tSensitivity = Zoom:CreateToggle({\n\t    Name = \"Sensitivity\",\n\t    Default = true,\n\t    Tooltip = \"Slows your mouse by the same amount you zoomed in\"\n\t})\nend)"},{"path":"src/games/77790193039862.lua","name":"77790193039862.lua","size":37130,"sha":"5765e69496b2274fe0453f3979e7dd001e93cabd","encoding":"utf8","content":"local Run = function(Func: () -> ())\n    Func()\nend\nlocal cloneref = cloneref or function(Reference: Instance)\n    return Reference\nend\n\nlocal Players: Players = cloneref(game:GetService(\"Players\"))\nlocal UserInputService: UserInputService = cloneref(game:GetService(\"UserInputService\"))\nlocal ReplicatedStorage: ReplicatedStorage = cloneref(game:GetService(\"ReplicatedStorage\"))\nlocal ReplicatedFirst: ReplicatedFirst = cloneref(game:GetService(\"ReplicatedFirst\"))\nlocal CollectionService: CollectionService = cloneref(game:GetService(\"CollectionService\"))\nlocal RunService: RunService = cloneref(game:GetService(\"RunService\"))\nlocal CoreGui: CoreGui = cloneref(game:GetService(\"CoreGui\"))\n\nlocal Camera: Camera = workspace.CurrentCamera\nlocal LocalPlayer: Player = Players.LocalPlayer\nlocal vape = shared.vape\nlocal Entity = vape.Libraries.entity\nlocal TargetInfo = vape.Libraries.targetinfo\nlocal Arena = {}\n\nlocal OldHit\nlocal Spider = {Enabled = false}\nlocal Phase = {Enabled = false}\n\nlocal function CalculateMoveVector()\n    local MoveVector: Vector3 = Arena.MoveController:GetMoveVector()\n    local Cos, Sin\n    local _, _, _, R00, R01, R02, _, _, R12, _, _, R22 = Camera.CFrame:GetComponents()\n    if R12 < 1 and R12 > -1 then\n        Cos = R22\n        Sin = R02\n    else\n        Cos = R00\n        Sin = -R01 * math.sign(R12)\n    end\n    MoveVector = Vector3.new((Cos * MoveVector.X + Sin * MoveVector.Z), 0, (Cos * MoveVector.Z - Sin * MoveVector.X)) / math.sqrt(Cos * Cos + Sin * Sin)\n    return MoveVector.Unit == MoveVector.Unit and MoveVector.Unit or Vector3.zero\nend\n\nlocal function SendNotification(...)\n    return vape:CreateNotification(...)\nend\n\nRun(function()\n    local CharacterScript = LocalPlayer.PlayerScripts.CharacterController\n    local Environment = getsenv(CharacterScript)\n    if not (Environment and Environment.startHit) then\n        repeat\n            Environment = getsenv(CharacterScript)\n            task.wait()\n        until Environment and Environment.startHit or vape.Loaded == nil\n\n        if vape.Loaded == nil then\n            return\n        end\n    end\n\n    Arena = {\n        Client = getsenv(CharacterScript),\n        PlayerState = require(CharacterScript.PlayerState),\n        Inventory = require(CharacterScript.Inventory),\n        MoveController = require(LocalPlayer.PlayerScripts.PlayerModule):GetControls(),\n        SwingFunction = debug.getupvalue(getsenv(CharacterScript).startHit, 1)\n    }\n\n    for _, v: any in getconnections(RunService.Heartbeat) do\n        if v.Function and islclosure(v.Function) and debug.getconstants(v.Function)[1] == 0.05 then\n            Arena.TickFunction = debug.getupvalue(v.Function, 3)\n        end\n    end\n\n    for _, v: any in getconnections(ReplicatedStorage.Remotes.LoadLocalCharacter.OnClientEvent) do\n        if v.Function then\n            Arena.MoveFunction = debug.getupvalue(v.Function, 9)\n        end\n    end\n\n    vape:Clean(function()\n        table.clear(Arena)\n    end)\nend)\n\nRun(function()\n    local function WaitForChildOfType(Object: Instance, Name: string, Timeout: number, Property)\n        local CheckTick: number = tick() + Timeout\n        local Returned\n        repeat\n            Returned = Property and Object[Name] or Object:FindFirstChildOfClass(Name)\n            if Returned or CheckTick < tick() then\n                break\n            end\n            task.wait()\n        until false\n        return Returned\n    end\n\n    Entity.getUpdateConnections = function(Ent)\n        return {\n            Ent.Player.HealthValue:GetPropertyChangedSignal(\"Value\")\n        }\n    end\n\n    Entity.addEntity = function(Character, Player, TeamFunction)\n        if not Character then\n            return\n        end\n\n        if Player == LocalPlayer then\n            local Humanoid = {GetState = function() end, Health = 100}\n            local RootPart = Camera.CameraSubject\n\n            local Target = {\n                Connections = {},\n                Character = Character,\n                Health = 100,\n                Head = RootPart,\n                Humanoid = Humanoid,\n                HumanoidRootPart = RootPart,\n                HipHeight = 5,\n                MaxHealth = 100,\n                NPC = Player == nil,\n                Player = Player,\n                RootPart = RootPart,\n                TeamCheck = TeamFunction\n            }\n\n            Entity.character = Target\n            Entity.isAlive = true\n            Entity.Events.LocalAdded:Fire(Target)\n            return\n        end\n\n        Entity.EntityThreads[Character] = task.spawn(function()\n            local Humanoid = WaitForChildOfType(Character, \"Humanoid\", 10)\n            local RootPart = Character:WaitForChild(\"Torso\", 10)\n            local Head = Character:WaitForChild(\"Head\", 10) or RootPart\n            local HealthValue = Player:WaitForChild(\"HealthValue\", 10)\n\n            if Humanoid and RootPart then\n                local Target = {\n                    Connections = {},\n                    Character = Character,\n                    Health = Player.HealthValue.Value,\n                    Head = Head,\n                    Humanoid = Humanoid,\n                    HumanoidRootPart = RootPart,\n                    Hitbox = Character.PlayerHitbox,\n                    HipHeight = 3,\n                    MaxHealth = 100,\n                    NPC = Player == nil,\n                    Player = Player,\n                    RootPart = RootPart,\n                    TeamCheck = TeamFunction\n                }\n\n                Target.Targetable = Entity.targetCheck(Target)\n                for _, v: RBXScriptSignal in Entity.getUpdateConnections(Target) do\n                    table.insert(Target.Connections, v:Connect(function()\n                        Target.Health = Player.HealthValue.Value\n                        Entity.Events.EntityUpdated:Fire(Target)\n                    end))\n                end\n\n                table.insert(Entity.List, Target)\n                Entity.Events.EntityAdded:Fire(Target)\n            end\n\n            Entity.EntityThreads[Character] = nil\n        end)\n    end\n\n    Entity.addPlayer = function(Player) end\n\n    local OldStart = Entity.start\n    Entity.start = function()\n        OldStart()\n        if Entity.Running then\n            table.insert(Entity.Connections, Camera:GetPropertyChangedSignal(\"CameraSubject\"):Connect(function()\n                if Camera.CameraSubject then\n                    Entity.addEntity(true, LocalPlayer)\n                end\n            end))\n\n            if Camera.CameraSubject then\n                Entity.addEntity(true, LocalPlayer)\n            end\n\n            table.insert(Entity.Connections, workspace.OtherCharacters.ChildAdded:Connect(function(Character: Instance)\n                local Player = Players:FindFirstChild(Character.Name:sub(1, #Character.Name - 14))\n                if Player then\n                    Entity.refreshEntity(Character, Player)\n                end\n            end))\n\n            for _, Character: Instance in workspace.OtherCharacters:GetChildren() do\n                local Player = Players:FindFirstChild(Character.Name:sub(1, #Character.Name - 14))\n                if Player then\n                    Entity.refreshEntity(Character, Player)\n                end\n            end\n        end\n    end\n\n    Entity.start()\nend)\n\nfor _, v: string in {\"AimAssist\", \"Reach\", \"SilentAim\", \"AntiFall\", \"Desync\", \"Invisible\", \"Jesus\", \"MouseTP\", \"Phase\", \"SpinBot\", \"Swim\", \"TargetStrafe\", \"AnimationPlayer\", \"AntiRagdoll\", \"ChatSpammer\", \"Disabler\", \"StateSpoofer\", \"Freecam\", \"Gravity\", \"Parkour\", \"SafeWalk\", \"MurderMystery\"} do\n    vape:Remove(v)\nend\n\nRun(function()\n\tlocal AutoClicker\n\tlocal CPS\n\tlocal Thread\n\t\n\tlocal function AutoClick()\n\t    if Thread then\n\t        task.cancel(Thread)\n\t    end\n\t\n\t    Thread = task.delay(1 / CPS.GetRandomValue(), function()\n\t        repeat\n\t            task.spawn(Arena.Client.startHit)\n\t            task.wait(1 / CPS.GetRandomValue())\n\t        until not AutoClicker.Enabled\n\t    end)\n\tend\n\t\n\tAutoClicker = vape.Categories.Combat:CreateModule({\n\t    Name = \"AutoClicker\",\n\t    Function = function(Callback: boolean)\n\t        if Callback then\n\t            AutoClicker:Clean(UserInputService.InputBegan:Connect(function(Input: InputObject)\n\t                if Input.UserInputType == Enum.UserInputType.MouseButton1 then\n\t                    AutoClick()\n\t                end\n\t            end))\n\t\n\t            AutoClicker:Clean(UserInputService.InputEnded:Connect(function(Input: InputObject)\n\t                if Input.UserInputType == Enum.UserInputType.MouseButton1 and Thread then\n\t                    task.cancel(Thread)\n\t                    Thread = nil\n\t                end\n\t            end))\n\t        else\n\t            if Thread then\n\t                task.cancel(Thread)\n\t                Thread = nil\n\t            end\n\t        end\n\t    end,\n\t    Tooltip = \"Hold attack button to automatically click\"\n\t})\n\tCPS = AutoClicker:CreateTwoSlider({\n\t    Name = \"CPS\",\n\t    Min = 1,\n\t    Max = 9,\n\t    DefaultMin = 7,\n\t    DefaultMax = 7\n\t})\nend)\n\nRun(function()\n\tlocal Reach\n\tlocal Value\n\tlocal Old\n\t\n\tReach = vape.Categories.Combat:CreateModule({\n\t    Name = \"Reach\",\n\t    Function = function(Callback: boolean)\n\t        if Callback then\n\t            Old = debug.getupvalue(OldHit or Arena.Client.startHit, 4)\n\t            debug.setupvalue(OldHit or Arena.Client.startHit, 4, Old + Value.Value)\n\t        else\n\t            if Old then\n\t                debug.setupvalue(OldHit or Arena.Client.startHit, 4, Old)\n\t                Old = nil\n\t            end\n\t        end\n\t    end,\n\t    Tooltip = \"Extends attack reach\"\n\t})\n\tValue = Reach:CreateSlider({\n\t    Name = \"Range\",\n\t    Min = 0,\n\t    Max = 6,\n\t    Default = 6,\n\t    Decimal = 10,\n\t    Function = function(Val: number)\n\t        if Reach.Enabled then\n\t            debug.setupvalue(OldHit or Arena.Client.startHit, 4, Old + Val)\n\t        end\n\t    end,\n\t    Suffix = function(Val: number)\n\t        return Val == 1 and \"stud\" or \"studs\"\n\t    end\n\t})\nend)\n\nRun(function()\n\tlocal Sprint\n\t\n\tSprint = vape.Categories.Combat:CreateModule({\n\t    Name = \"Sprint\",\n\t    Function = function(Callback: boolean)\n\t        if Callback then\n\t            repeat\n\t                Arena.PlayerState.Preferences.AutoSprint = true\n\t                task.wait(0.016)\n\t            until not Sprint.Enabled\n\t        end\n\t    end,\n\t    Tooltip = \"Sets your sprinting to true.\"\n\t})\nend)\n\nRun(function()\n\tlocal Velocity\n\tlocal Horizontal\n\tlocal Vertical\n\tlocal Chance\n\tlocal Targeting\n\tlocal Connection\n\tlocal Generator, Old = Random.new()\n\t\n\tlocal function VelocityFunction(...)\n\t    if Generator:NextNumber(0, 100) > Chance.Value then\n\t 