t        end\n\t\n\t        if not Slot.Shown then\n\t            Slot.Shown = true\n\t            Slot.Object.Visible = true\n\t        end\n\t\n\t        if Slot.Major ~= Major then\n\t            Slot.Major = Major\n\t            Slot.Bar.Position = Major and MajorPosition or MinorPosition\n\t            Slot.Bar.Size = Major and MajorSize or MinorSize\n\t            Slot.Bar.BackgroundTransparency = Major and 0.6 or 0.624\n\t        end\n\t\n\t        local LabelShown: boolean = Major or Normalized % 15 == 0\n\t        if Slot.LabelShown ~= LabelShown then\n\t            Slot.LabelShown = LabelShown\n\t            Slot.Label.Visible = LabelShown\n\t        end\n\t\n\t        if LabelShown and (Slot.Value ~= Normalized or Plain ~= Last.plain) then\n\t            Slot.Value = Normalized\n\t            Slot.Label.Text = Major and Cardinals[Normalized] or tostring(math.floor(Normalized))\n\t            Slot.Label.FontFace = (Major or Plain) and UIPallet.FontBold or UIPallet.Font\n\t            Slot.Label.TextColor3 = Plain and PlateColor or (Major and WhiteColor or MutedColor)\n\t        end\n\t    end\n\t\n\t    Last.plain = Plain\n\t\n\t    for SlotIndex: number, v: any in Slots do\n\t        if SlotIndex > Index and v.Shown then\n\t            v.Shown = false\n\t            v.Object.Visible = false\n\t        end\n\t    end\n\tend\n\t\n\tCompass = vape.Legit:CreateModule({\n\t    Name = \"Compass\",\n\t    Category = \"HUD\",\n\t    Icon = GetVapeAsset(`{vape.Directory}/assets/new/legit_compass.png`),\n\t    Function = function(Callback: boolean)\n\t        if Callback then\n\t            Compass:Clean(RunService.RenderStepped:Connect(Update))\n\t        end\n\t    end,\n\t    Size = UDim2.fromOffset(616, 60),\n\t    Tooltip = \"Shows a compass indicating your direction\"\n\t})\n\t\n\tBackground = Compass:CreateToggle({\n\t    Name = \"Render background\",\n\t    Function = function(Callback: boolean)\n\t        if BackgroundColor then\n\t            Holder.BackgroundTransparency = Callback and 1 - BackgroundColor.Opacity or 1\n\t            BackgroundColor.Object.Visible = Callback\n\t        end\n\t    end,\n\t    Default = true\n\t})\n\tBackgroundColor = Compass:CreateColorSlider({\n\t    Name = \"Background Color\",\n\t    DefaultHue = 0.8333,\n\t    DefaultSat = 0.0385,\n\t    DefaultValue = 0.102,\n\t    DefaultOpacity = 0.4,\n\t    Function = function(Hue: number, Sat: number, Val: number, Opacity: number)\n\t        if Holder then\n\t            Holder.BackgroundColor3 = Color3.fromHSV(Hue, Sat, Val)\n\t            Holder.BackgroundTransparency = Background.Enabled and 1 - Opacity or 1\n\t        end\n\t    end,\n\t    Darker = true\n\t})\n\tHolder = Compass.Children\n\tHolder.BackgroundColor3 = Color3.fromRGB(26, 25, 26)\n\tHolder.BackgroundTransparency = 0.6\n\tlocal HolderCorner: UICorner = Instance.new(\"UICorner\")\n\tHolderCorner.CornerRadius = UDim.new(0, 4)\n\tHolderCorner.Parent = Holder\n\tStrip = Instance.new(\"Frame\")\n\tStrip.BackgroundTransparency = 1\n\tStrip.ClipsDescendants = true\n\tStrip.Name = \"Strip\"\n\tStrip.Position = UDim2.fromOffset(0, -20)\n\tStrip.Size = UDim2.fromOffset(616, 80)\n\tStrip.Parent = Holder\n\tHeadingLabel = Instance.new(\"TextLabel\")\n\tHeadingLabel.AnchorPoint = Vector2.new(0.5, 0)\n\tHeadingLabel.BackgroundTransparency = 1\n\tHeadingLabel.FontFace = UIPallet.FontBold\n\tHeadingLabel.Position = UDim2.fromOffset(StripCentre, 0)\n\tHeadingLabel.Size = UDim2.fromOffset(200, 16)\n\tHeadingLabel.TextColor3 = PlateColor\n\tHeadingLabel.TextSize = 12\n\tHeadingLabel.Parent = Strip\n\tlocal Arrow: ImageLabel = Instance.new(\"ImageLabel\")\n\tArrow.AnchorPoint = Vector2.new(0.5, 0)\n\tArrow.BackgroundTransparency = 1\n\tArrow.Image = GetVapeAsset(`{vape.Directory}/assets/new/compassarrow.png`)\n\tArrow.Position = UDim2.fromOffset(StripCentre, 15)\n\tArrow.Size = UDim2.fromOffset(19, 32)\n\tArrow.Parent = Strip\n\tfor i: number = 1, 29 do\n\t    local Slot: Frame = Instance.new(\"Frame\")\n\t    Slot.BackgroundTransparency = 1\n\t    Slot.Size = UDim2.new()\n\t    Slot.Visible = false\n\t    Slot.Parent = Strip\n\t    local Bar: Frame = Instance.new(\"Frame\")\n\t    Bar.AnchorPoint = Vector2.new(0.5, 0)\n\t    Bar.BackgroundColor3 = WhiteColor\n\t    Bar.BorderSizePixel = 0\n\t    Bar.Position = MajorPosition\n\t    Bar.Size = MajorSize\n\t    Bar.Parent = Slot\n\t    local Label: TextLabel = Instance.new(\"TextLabel\")\n\t    Label.AnchorPoint = Vector2.new(0.5, 0)\n\t    Label.BackgroundTransparency = 1\n\t    Label.FontFace = UIPallet.FontBold\n\t    Label.Position = UDim2.fromOffset(0, 43)\n\t    Label.Size = UDim2.fromOffset(60, 20)\n\t    Label.TextColor3 = WhiteColor\n\t    Label.TextSize = 11\n\t    Label.Parent = Slot\n\t    Slots[i] = {Object = Slot, Bar = Bar, Label = Label}\n\tend\nend)\n\nRun(function()\n\tlocal Coords\n\tlocal DisplayType\n\tlocal Background\n\tlocal BackgroundColor\n\tlocal HorizontalAxes = {}\n\tlocal VerticalAxes = {}\n\tlocal CoordText: {string} = {}\n\tlocal Positives: {[number]: boolean} = {}\n\tlocal Last = {}\n\tlocal PositiveColor: Color3 = Color3.fromRGB(5, 134, 105)\n\tlocal NegativeColor: Color3 = Color3.fromRGB(250, 50, 56)\n\tlocal TriangleArrow: string = GetVapeAsset(`{vape.Directory}/assets/new/triangle.png`)\n\tlocal DigitWidth: number = GetFontBounds(\"0\", 19, UIPallet.Font).X\n\tlocal Holder, Horizontal, Vertical\n\tlocal HorizontalMaterial, VerticalMaterial\n\t\n\tlocal function AddLabel(Parent: Instance, TextSize: number, TextColor: Color3): TextLabel\n\t    local Label: TextLabel = Instance.new(\"TextLabel\")\n\t    Label.BackgroundTransparency = 1\n\t    Label.FontFace = UIPallet.Font\n\t    Label.Size = UDim2.fromOffset(200, 20)\n\t    Label.TextColor3 = TextColor\n\t    Label.TextSize = TextSize\n\t    Label.TextXAlignment = Enum.TextXAlignment.Left\n\t    Label.Parent = Parent\n\t\n\t    return Label\n\tend\n\t\n\tlocal function AddArrow(Parent: Instance)\n\t    local Box: Frame = Instance.new(\"Frame\")\n\t    Box.BackgroundColor3 = Color3.fromRGB(26, 25, 26)\n\t    Box.BackgroundTransparency = 0.431\n\t    Box.Size = UDim2.fromOffset(16, 16)\n\t    Box.Parent = Parent\n\t    local Corner: UICorner = Instance.new(\"UICorner\")\n\t    Corner.CornerRadius = UDim.new(0, 3)\n\t    Corner.Parent = Box\n\t    local Triangle: ImageLabel = Instance.new(\"ImageLabel\")\n\t    Triangle.BackgroundTransparency = 1\n\t    Triangle.Image = TriangleArrow\n\t    Triangle.Size = UDim2.fromOffset(8, 4)\n\t    Triangle.Parent = Box\n\t\n\t    return Box, Triangle\n\tend\n\t\n\tlocal function AddDivider(Parent: Instance, Size: UDim2): Frame\n\t    local Divider: Frame = Instance.new(\"Frame\")\n\t    Divider.BackgroundColor3 = Color3.new(1, 1, 1)\n\t    Divider.BackgroundTransparency = 0.8\n\t    Divider.BorderSizePixel = 0\n\t    Divider.Size = Size\n\t    Divider.Parent = Parent\n\t\n\t    return Divider\n\tend\n\t\n\tlocal function Update()\n\t    if vape.ThreadFix then\n\t        setthreadidentity(8)\n\t    end\n\t\n\t    if not Entity.isAlive then\n\t        return\n\t    end\n\t\n\t    local Position: Vector3 = Entity.character.RootPart.Position\n\t    local Look: Vector3 = Camera.CFrame.LookVector\n\t    local Material: string = Entity.character.Humanoid.FloorMaterial.Name\n\t    local X, Y, Z = math.round(Position.X), math.round(Position.Y), math.round(Position.Z)\n\t    local PositiveX, PositiveZ = Look.X > 0, Look.Z > 0\n\t    if Last.x == X and Last.y == Y and Last.z == Z and Last.positivex == PositiveX and Last.positivez == PositiveZ and Last.material == Material and Last.display == DisplayType.Value then\n\t        return\n\t    end\n\t\n\t    Last.x, Last.y, Last.z, Last.positivex, Last.positivez, Last.material, Last.display = X, Y, Z, PositiveX, PositiveZ, Material, DisplayType.Value\n\t    CoordText[1] = tostring(X)\n\t    CoordText[2] = tostring(Y)\n\t    CoordText[3] = tostring(Z)\n\t    Positives[1] = PositiveX\n\t    Positives[3] = PositiveZ\n\t\n\t    if DisplayType.Value == \"Vertical\" then\n\t        for i: number, v: any in VerticalAxes do\n\t            v.Value.Text = CoordText[i]\n\t\n\t            if v.Triangle then\n\t                v.Triangle.ImageColor3 = Positives[i] and PositiveColor or NegativeColor\n\t                v.Triangle.Position = UDim2.fromOffset(4, Positives[i] and 5 or 6)\n\t                v.Triangle.Rotation = Positives[i] and 180 or 0\n\t            end\n\t        end\n\t\n\t        VerticalMaterial.Text = Material\n\t        return\n\t    end\n\t\n\t    local Offset: number = 20\n\t\n\t    for i: number, v: any in HorizontalAxes do\n\t        v.Label.Position = UDim2.fromOffset(Offset, 16)\n\t        Offset += v.Width + 5\n\t        v.Value.Text = CoordText[i]\n\t        v.Value.Position = UDim2.fromOffset(Offset, 13)\n\t        Offset += math.max(44, 10 + DigitWidth * #CoordText[i])\n\t\n\t        if v.Triangle then\n\t            v.Arrow.Position = UDim2.fromOffset(Offset - 8, 18)\n\t            v.Triangle.ImageColor3 = Positives[i] and PositiveColor or NegativeColor\n\t            v.Triangle.Position = UDim2.fromOffset(4, Positives[i] and 5 or 6)\n\t            v.Triangle.Rotation = Positives[i] and 180 or 0\n\t        end\n\t\n\t        if v.Divider then\n\t            Offset += v.Triangle and 20 or 0\n\t            v.Divider.Position = UDim2.fromOffset(Offset - 1, 18)\n\t            Offset += 20\n\t        end\n\t    end\n\t\n\t    HorizontalMaterial.Text = Material\n\t    Holder.Size = UDim2.fromOffset(Offset + 24, 70)\n\tend\n\t\n\tCoords = vape.Legit:CreateModule({\n\t    Name = \"Coords\",\n\t    Category = \"HUD\",\n\t    Icon = GetVapeAsset(`{vape.Directory}/assets/new/legit_coords.png`),\n\t    Function = function(Callback: boolean)\n\t        if Callback then\n\t            Coords:Clean(RunService.RenderStepped:Connect(Update))\n\t        end\n\t    end,\n\t    Size = UDim2.fromOffset(280, 70),\n\t    Tooltip = \"Shows your current XYZ coordinates\"\n\t})\n\t\n\tDisplayType = Coords:CreateDropdown({\n\t    Name = \"Display Type\",\n\t    List = {\"Horizontal\", \"Vertical\"},\n\t    Function = function(Value: string)\n\t        if Holder then\n\t            Horizontal.Visible = Value == \"Horizontal\"\n\t            Vertical.Visible = Value == \"Vertical\"\n\t            Holder.Size = UDim2.fromOffset(Value == \"Vertical\" and 140 or 280, Value == \"Vertical\" and 180 or 70)\n\t        end\n\t    end\n\t})\n\tBackground = Coords:CreateToggle({\n\t    Name = \"Render background\",\n\t    Function = function(Callback: boolean)\n\t        if BackgroundColor then\n\t            Holder.BackgroundTransparency = Callback and 1 - BackgroundColor.Opacity or 1\n\t            BackgroundColor.Object.Visible = Callback\n\t        end\n\t    end,\n\t    Default = true\n\t})\n\tBackgroundColor = Coords:CreateColorSlider({\n\t    Name = \"Background Color\",\n\t    DefaultHue = 0.8333,\n\t    DefaultSat = 0.0385,\n\t    DefaultValue = 0.102,\n\t    DefaultOpacity = 0.4,\n\t    Function = function(Hue: number, Sat: number, Val: number, Opacity: number)\n\t        if Holder then\n\t            Holder.BackgroundColor3 = Color3.fromHSV(Hue, Sat, Val)\n\t            Holder.BackgroundTransparency = Background.Enabled and 1 - Opacity or 1\n\t        end\n\t    end,\n\t    Darker = true\n\t})\n\tHolder = Coords.Children\n\tHolder.BackgroundColor3 = Color3.fromRGB(26, 25, 26)\n\tHolder.BackgroundTransparency = 0.6\n\tlocal HolderCorner: UICorner = Instance.new(\"UICorner\")\n\tHolderCorner.CornerRadius = UDim.new(0, 4)\n\tHolderCorner.Parent = Holder\n\tHorizontal = Instance.new(\"Frame\")\n\tHorizontal.BackgroundTransparency = 1\n\tHorizontal.Name = \"Horizontal\"\n\tHorizontal.Size = UDim2.fromScale(1, 1)\n\tHorizontal.Parent = Holder\n\tVertical = Instance.new(\"Frame\")\n\tVertical.BackgroundTransparency = 1\n\tVertical.Name = \"Vertical\"\n\tVertical.Size = UDim2.fromScale(1, 1)\n\tVertical.Visible = false\n\tVertical.Parent = Holder\n\tfor i: number, Axis: string in {\"X\", \"Y\", \"Z\"} do\n\t    local Entry = {Width = GetFontBounds(Axis, 12, UIPallet.Font).X}\n\t    Entry.Label = AddLabel(Horizontal, 12, Color3.new(1, 1, 1))\n\t    Entry.Label.Text = Axis\n\t    Entry.Value = AddLabel(Horizontal, 19, Color3.new(1, 1, 1))\n\t\n\t    if Axis ~= \"Y\" then\n\t        Entry.Arrow, Entry.Triangle = AddArrow(Horizontal)\n\t    end\n\t\n\t    if Axis ~= \"Z\" then\n\t        Entry.Divider = AddDivider(Horizontal, UDim2.fromOffset(2, 16))\n\t    end\n\t\n\t    HorizontalAxes[i] = Entry\n\tend\n\tfor i: number, Axis: string in {\"X\", \"Y\", \"Z\"} do\n\t    local Entry = {}\n\t    Entry.Label = AddLabel(Vertical, 11, Color3.new(1, 1, 1))\n\t    Entry.Label.Text = Axis\n\t    Entry.Label.Position = UDim2.fromOffset(16, 16 + (i - 1) * 45)\n\t    Entry.Value = AddLabel(Vertical, 17, Color3.new(1, 1, 1))\n\t    Entry.Value.Position = UDim2.fromOffset(21 + GetFontBounds(Axis, 11, UIPallet.Font).X, 13 + (i - 1) * 45)\n\t\n\t    if Axis ~= \"Y\" then\n\t        Entry.Arrow, Entry.Triangle = AddArrow(Vertical)\n\t        Entry.Arrow.Position = UDim2.fromOffset(108, Axis == \"X\" and 18 or 105)\n\t    end\n\t\n\t    VerticalAxes[i] = Entry\n\tend\n\tfor i: number = 1, 3 do\n\t    local Divider: Frame = AddDivider(Vertical, UDim2.fromOffset(110, 2))\n\t    Divider.Position = UDim2.fromOffset(16, 2 + i * 45)\n\tend\n\tlocal HorizontalLabel: TextLabel = AddLabel(Horizontal, 12, Color3.new(1, 1, 1))\n\tHorizontalLabel.Text = \"MATERIAL:\"\n\tHorizontalLabel.Position = UDim2.fromOffset(20, 41)\n\tHorizontalMaterial = AddLabel(Horizontal, 12, Color3.fromRGB(255, 160, 84))\n\tHorizontalMaterial.Position = UDim2.fromOffset(20 + GetFontBounds(\"MATERIAL: \", 12, UIPallet.Font).X, 41)\n\tlocal VerticalLabel: TextLabel = AddLabel(Vertical, 11, Color3.new(1, 1, 1))\n\tVerticalLabel.Text = \"MATERIAL:\"\n\tVerticalLabel.Position = UDim2.fromOffset(16, 146)\n\tVerticalMaterial = AddLabel(Vertical, 11, Color3.fromRGB(255, 160, 84))\n\tVerticalMaterial.Position = UDim2.fromOffset(24 + GetFontBounds(\"MATERIAL:\", 11, UIPallet.Font).X, 146)\nend)\n\nRun(function()\n\tlocal Disguise\n\tlocal Mode\n\tlocal IDBox\n\tlocal Generation: number = 0\n\tlocal Disguised: Model?\n\tlocal AppliedKey: string?\n\tlocal HeadMesh: {Head: MeshPart, Copy: MeshPart}?\n\tlocal EmoteRecord: {[string]: any}?\n\tlocal Connections: {RBXScriptConnection} = {}\n\tlocal Cloned: {[Instance]: boolean} = {}\n\tlocal Stashed: {[Instance]: Instance} = {}\n\tlocal Colors: {[BasePart]: Color3} = {}\n\tlocal Animations: {[Animation]: string} = {}\n\tlocal UserIds: {[string]: number} = {}\n\tlocal Descriptions: {[number]: HumanoidDescription} = {}\n\tlocal Appearance: {string} = {\"Accoutrement\", \"Clothing\", \"ShirtGraphic\", \"BodyColors\"}\n\tlocal Inherited: {string} = {\"HeightScale\", \"WidthScale\", \"DepthScale\", \"HeadScale\", \"BodyTypeScale\", \"ProportionScale\", \"Torso\", \"LeftArm\", \"RightArm\", \"LeftLeg\", \"RightLeg\"}\n\tlocal ApplyMethods: {string} = {\"ApplyDescriptionResetAsync\", \"ApplyDescriptionReset\", \"ApplyDescriptionAsync\", \"ApplyDescription\"}\n\t\n\tlocal function IsAppearance(Object: Instance): boolean\n\t    if Object:GetAttribute(\"InvItem\") ~= nil or Object:GetAttribute(\"ArmorSlot\") ~= nil or Object:GetAttribute(\"IsBackpack\") ~= nil then\n\t        return false\n\t    end\n\t\n\t    for _, ClassName: string in Appearance do\n\t        if Object:IsA(ClassName) then\n\t            return true\n\t        end\n\t    end\n\t\n\t    return false\n\tend\n\t\n\tlocal function Hide(Object: Instance)\n\t    local Parent: Instance? = Object.Parent\n\t    if Cloned[Object] or not Parent then\n\t        return\n\t    end\n\t\n\t    Stashed[Object] = Parent\n\t    task.defer(function()\n\t        if Stashed[Object] ~= Parent then\n\t            return\n\t        end\n\t\n\t        if Object.Parent == Parent then\n\t            Object.Parent = nil\n\t        else\n\t            Stashed[Object] = nil\n\t        end\n\t    end)\n\tend\n\t\n\tlocal function CopyMesh(Target: MeshPart, Source: MeshPart): boolean\n\t    return pcall(function()\n\t        Target:ApplyMesh(Source)\n\t    end) or pcall(function()\n\t        Target.MeshId = Source.MeshId\n\t    end)\n\tend\n\t\n\tlocal function Reset(Revert: boolean)\n\t    Generation += 1\n\t    Disguised = nil\n\t    AppliedKey = nil\n\t\n\t    for _, v: RBXScriptConnection in Connections do\n\t        v:Disconnect()\n\t    end\n\t    table.clear(Connections)\n\t\n\t    if Revert then\n\t        for Object: Instance in Cloned do\n\t            Object:Destroy()\n\t        end\n\t\n\t        for Object: Instance, Parent: Instance in Stashed do\n\t            pcall(function()\n\t                Object.Parent = Parent\n\t            end)\n\t        end\n\t\n\t        for Part: BasePart, Color: Color3 in Colors do\n\t            Part.Color = Color\n\t        end\n\t\n\t        if HeadMesh then\n\t            CopyMesh(HeadMesh.Head, HeadMesh.Copy)\n\t        end\n\t\n\t        if EmoteRecord then\n\t            pcall(function()\n\t                EmoteRecord.Description.JumpAnimation = EmoteRecord.JumpAnimation\n\t                EmoteRecord.Description:SetEmotes(EmoteRecord.Emotes)\n\t                EmoteRecord.Description:SetEquippedEmotes(EmoteRecord.Equipped)\n\t            end)\n\t        end\n\t\n\t        for Target: Animation, AnimationId: string in Animations do\n\t            Target.AnimationId = AnimationId\n\t        end\n\t    end\n\t\n\t    if HeadMesh then\n\t        HeadMesh.Copy:Destroy()\n\t    end\n\t\n\t    HeadMesh = nil\n\t    EmoteRecord = nil\n\t    table.clear(Cloned)\n\t    table.clear(Stashed)\n\t    table.clear(Colors)\n\t    table.clear(Animations)\n\tend\n\t\n\tlocal function ResolveUserId(Text: string): number?\n\t    local Name: string = (Text:gsub(\"[%s@]\", \"\"))\n\t    if Name == \"\" then\n\t        return 239702688\n\t    end\n\t\n\t    if Name:match(\"^%d+$\") then\n\t        return tonumber(Name)\n\t    end\n\t\n\t    local Key: string = Name:lower()\n\t    if not UserIds[Key] then\n\t        local Success, UserId = pcall(function()\n\t            return Players:GetUserIdFromNameAsync(Name)\n\t        end)\n\t\n\t        if Success and UserId then\n\t            UserIds[Key] = UserId\n\t        end\n\t    end\n\t\n\t    return UserIds[Key]\n\tend\n\t\n\tlocal function GetDescription(UserId: number): HumanoidDescription?\n\t    if not Descriptions[UserId] then\n\t        for i: number = 1, 3 do\n\t            local Success, Description = pcall(function()\n\t                return Players:GetHumanoidDescriptionFromUserId(UserId)\n\t            end)\n\t\n\t            if Success and Description then\n\t                Descriptions[UserId] = Description\n\t                break\n\t            end\n\t\n\t            if i < 3 then\n\t                task.wait(1)\n\t            end\n\t        end\n\t    end\n\t\n\t    return Descriptions[UserId] and Descriptions[UserId]:Clone()\n\tend\n\t\n\tlocal function ApplyDescription(Target: Humanoid, Description: HumanoidDescription): boolean\n\t    local Result: boolean?\n\t    task.spawn(function()\n\t        for _, Method: string in ApplyMethods do\n\t            if pcall(function()\n\t                Target[Method](Target, Description)\n\t            end) then\n\t                Result = true\n\t                return\n\t            end\n\t        end\n\t\n\t        Result = false\n\t    end)\n\t\n\t    local Deadline: number = tick() + 10\n\t    while Result == nil and tick() < Deadline do\n\t        task.wait(0.1)\n\t    end\n\t\n\t    return Result == true\n\tend\n\t\n\tlocal function DisguiseCharacter(Ent, Current: number)\n\t    local UserId: number? = ResolveUserId(IDBox.Value)\n\t    if Current ~= Generation then\n\t        return\n\t    end\n\t\n\t    if not UserId then\n\t        SendNotification(\"Disguise\", `Could not find the user {IDBox.Value}`, 5, \"warning\")\n\t        return\n\t    end\n\t\n\t    local Deadline: number = tick() + 5\n\t    while not LocalPlayer:HasAppearanceLoaded() and tick() < Deadline do\n\t        task.wait(0.1)\n\t    end\n\t\n\t    local Description: HumanoidDescription? = GetDescription(UserId)\n\t    local Character: Model = Ent.Character\n\t    if Current ~= Generation or not Character.Parent then\n\t        if Description then\n\t            Description:Destroy()\n\t        end\n\t\n\t        return\n\t    end\n\t\n\t    if not Description then\n\t        SendNotification(\"Disguise\", `Could not load the avatar of user {UserId}`, 5, \"warning\")\n\t        return\n\t    end\n\t\n\t    local Original: HumanoidDescription? = Ent.Humanoid:FindFirstChildOfClass(\"HumanoidDescription\")\n\t    if Original then\n\t        for _, Property: string in Inherited do\n\t            Description[Property] = Original[Property]\n\t        end\n\t    end\n\t\n\t    local Archivable: boolean = Character.Archivable\n\t    Character.Archivable = true\n\t    local Clone: Model = Character:Clone()\n\t    Character.Archivable = Archivable\n\t\n\t    local Objects: {Instance} = Clone:GetDescendants()\n\t    table.insert(Objects, Clone)\n\t    for _, v: Instance in Objects do\n\t        for _, Tag: string in v:GetTags() do\n\t            v:RemoveTag(Tag)\n\t        end\n\t\n\t        if v:IsA(\"LuaSourceContainer\") then\n\t            v:Destroy()\n\t        elseif v:IsA(\"BasePart\") and v.Parent == Clone then\n\t            v.CanCollide = false\n\t            v.CanQuery = false\n\t            v.CanTouch = false\n\t            v.Anchored = v.Name == \"HumanoidRootPart\"\n\t        end\n\t    end\n\t\n\t    local CloneHumanoid: Humanoid? = Clone:FindFirstChildOfClass(\"Humanoid\")\n\t    if CloneHumanoid then\n\t        CloneHumanoid.DisplayDistanceType = Enum.HumanoidDisplayDistanceType.None\n\t    end\n\t\n\t    Clone.Name = \"DisguiseRig\"\n\t    Clone:PivotTo(Clone:GetPivot() + Vector3.new(0, 1000, 0))\n\t    Clone.Parent = workspace\n\t\n\t    local Applied: boolean = CloneHumanoid ~= nil and ApplyDescription(CloneHumanoid, Description)\n\t    if not Applied and Current == Generation then\n\t        SendNotification(\"Disguise\", `Could not apply the avatar of user {UserId}`, 5, \"warning\")\n\t    end\n\t\n\t    if not Applied or Current ~= Generation or not Character.Parent then\n\t        Clone:Destroy()\n\t        Description:Destroy()\n\t        return\n\t    end\n\t\n\t    table.insert(Connections, Character.ChildAdded:Connect(function(Child: Instance)\n\t        if IsAppearance(Child) then\n\t            Hide(Child)\n\t        end\n\t    end))\n\t\n\t    for _, Child: Instance in Character:GetChildren() do\n\t        if IsAppearance(Child) then\n\t            Hide(Child)\n\t        elseif Child:IsA(\"BasePart\") and Child.Name ~= \"HumanoidRootPart\" then\n\t            Colors[Child] = Child.Color\n\t        end\n\t    end\n\t\n\t    for _, Child: Instance in Clone:GetChildren() do\n\t        if not IsAppearance(Child) then\n\t            continue\n\t        end\n\t\n\t        for _, v: Instance in Child:GetDescendants() do\n\t            if v:IsA(\"Weld\") and v.Part1 and v.Part1.Parent == Clone then\n\t                v.Part1 = Character:FindFirstChild(v.Part1.Name)\n\t            elseif v:IsA(\"RigidConstraint\") and v.Attachment1 and v.Attachment1.Parent and v.Attachment1.Parent.Parent == Clone then\n\t                local Part: Instance? = Character:FindFirstChild(v.Attachment1.Parent.Name)\n\t                v.Attachment1 = Part and Part:FindFirstChild(v.Attachment1.Name)\n\t            end\n\t        end\n\t\n\t        Cloned[Child] = true\n\t        Child.Parent = Character\n\t    end\n\t\n\t    local Head: BasePart = Ent.Head\n\t    local CloneHead: Instance? = Clone:FindFirstChild(\"Head\")\n\t    local Face: Instance? = Head:FindFirstChild(\"face\")\n\t    local CloneFace: Instance? = CloneHead and CloneHead:FindFirstChild(\"face\")\n\t\n\t    table.insert(Connections, Head.ChildAdded:Connect(function(Child: Instance)\n\t        if Child:IsA(\"Decal\") and Child.Name == \"face\" then\n\t            Hide(Child)\n\t        end\n\t    end))\n\t\n\t    if Face then\n\t        Hide(Face)\n\t    end\n\t\n\t    if CloneFace then\n\t        Cloned[CloneFace] = true\n\t        CloneFace.Parent = Head\n\t    end\n\t\n\t    if CloneHead and CloneHead:IsA(\"MeshPart\") and Head:IsA(\"MeshPart\") and not Head:FindFirstChild(\"FaceControls\") then\n\t        local Copy: MeshPart? = Head:Clone()\n\t        if Copy and CopyMesh(Head, CloneHead) then\n\t            Copy:ClearAllChildren()\n\t            HeadMesh = {Head = Head, Copy = Copy}\n\t\n\t            for _, v: Instance in Head:GetChildren() do\n\t                if v:IsA(\"SurfaceAppearance\") then\n\t                    Hide(v)\n\t                end\n\t            end\n\t\n\t            for _, v: Instance in CloneHead:GetChildren() do\n\t                if v:IsA(\"SurfaceAppearance\") then\n\t                    Cloned[v] = true\n\t                    v.Parent = Head\n\t                end\n\t            end\n\t        elseif Copy then\n\t            Copy:Destroy()\n\t        end\n\t    end\n\t\n\t    if Original then\n\t        pcall(function()\n\t            EmoteRecord = {\n\t                Description = Original,\n\t                Emotes = Original:GetEmotes(),\n\t                Equipped = Original:GetEquippedEmotes(),\n\t                JumpAnimation = Original.JumpAnimation\n\t            }\n\t\n\t            Original.JumpAnimation = Description.JumpAnimation\n\t            Original:SetEmotes(Description:GetEmotes())\n\t            Original:SetEquippedEmotes(Description:GetEquippedEmotes())\n\t        end)\n\t    end\n\t\n\t    Clone:Destroy()\n\t    Description:Destroy()\n\tend\n\t\n\tlocal function DisguiseAnimation(Ent, Current: number)\n\t    local BundleId: number? = IDBox.Value == \"\" and 43 or tonumber(IDBox.Value)\n\t    if not BundleId then\n\t        SendNotification(\"Disguise\", \"Animation mode takes an animation pack bundle ID\", 5, \"warning\")\n\t        return\n\t    end\n\t\n\t    local Success, Data = pcall(function()\n\t        return MarketplaceService:GetProductInfo(BundleId, Enum.InfoType.Bundle)\n\t    end)\n\t\n\t    local Animate: Instance? = Ent.Character:FindFirstChild(\"Animate\")\n\t    if Current ~= Generation then\n\t        return\n\t    end\n\t\n\t    if not Success or type(Data) ~= \"table\" then\n\t        SendNotification(\"Disguise\", `Could not load bundle {BundleId}`, 5, \"warning\")\n\t        return\n\t    end\n\t\n\t    if Data.BundleType ~= \"AvatarAnimations\" then\n\t        SendNotification(\"Disguise\", \"that's not an animation pack\", 5, \"warning\")\n\t        return\n\t    end\n\t\n\t    if not Animate then\n\t        SendNotification(\"Disguise\", \"Your character has no Animate script to change\", 5, \"warning\")\n\t        return\n\t    end\n\t\n\t    for _, Item: any in Data.Items do\n\t        local Words: {string} = Item.Name:split(\" \")\n\t        local Folder: Instance? = Animate:FindFirstChild(Words[#Words]:lower())\n\t        local Target: Animation? = Folder and Folder:FindFirstChildWhichIsA(\"Animation\")\n\t        if not Target then\n\t            continue\n\t        end\n\t\n\t        local Loaded, Objects = pcall(function()\n\t            return game:GetObjects(`rbxassetid://{Item.Id}`)\n\t        end)\n\t\n\t        local Source: Animation? = Loaded and Objects[1] and Objects[1]:FindFirstChildWhichIsA(\"Animation\", true)\n\t        if Current ~= Generation then\n\t            return\n\t        end\n\t\n\t        if Source then\n\t            Animations[Target] = Animations[Target] or Target.AnimationId\n\t            Target.AnimationId = Source.AnimationId\n\t        end\n\t    end\n\tend\n\t\n\tlocal function LocalAdded(Ent)\n\t    if vape.ThreadFix then\n\t        setthreadidentity(8)\n\t    end\n\t\n\t    local Key: string = `{Mode.Value}:{IDBox.Value}`\n\t    if Ent.Character == Disguised and Key == AppliedKey then\n\t        return\n\t    end\n\t\n\t    Reset(Ent.Character == Disguised)\n\t    Disguised = Ent.Character\n\t    AppliedKey = Key\n\t\n\t    if Mode.Value == \"Character\" then\n\t        DisguiseCharacter(Ent, Generation)\n\t    else\n\t        DisguiseAnimation(Ent, Generation)\n\t    end\n\tend\n\t\n\tDisguise = vape.Legit:CreateModule({\n\t    Name = \"Disguise\",\n\t    Category = \"Game\",\n\t    Icon = GetVapeAsset(`{vape.Directory}/assets/new/legit_disguise.png`),\n\t    Function = function(Callback: boolean)\n\t        if vape.ThreadFix then\n\t            setthreadidentity(8)\n\t        end\n\t\n\t        if Callback then\n\t            Disguise:Clean(Entity.Events.LocalAdded:Connect(LocalAdded))\n\t            if Entity.isAlive then\n\t                task.spawn(LocalAdded, Entity.character)\n\t            end\n\t        else\n\t            Reset(true)\n\t        end\n\t    end,\n\t    Tooltip = \"Makes your character look like another player (user ID or username) or swaps your animations for an animation pack (bundle ID). Press enter in the box to apply a new one, your own look comes back when turned off\"\n\t})\n\t\n\tMode = Disguise:CreateDropdown({\n\t    Name = \"Mode\",\n\t    List = {\"Character\", \"Animation\"},\n\t    Function = function()\n\t        if Disguise.Enabled then\n\t            Disguise:Toggle()\n\t            Disguise:Toggle()\n\t        end\n\t    end\n\t})\n\tIDBox = Disguise:CreateTextBox({\n\t    Name = \"Disguise\",\n\t    Placeholder = \"User ID, username or bundle ID\",\n\t    Function = function(Enter: boolean)\n\t        if Enter and Disguise.Enabled then\n\t            Disguise:Toggle()\n\t            Disguise:Toggle()\n\t        end\n\t    end\n\t})\nend)\n\nRun(function()\n\tlocal FFlag\n\tlocal Flags\n\tlocal List\n\tlocal Prefixes: {string} = {\"DFFlag\", \"DFInt\", \"DFLog\", \"DFString\", \"SFFlag\", \"FFlag\", \"FInt\", \"FLog\", \"FString\"}\n\tlocal Marker: string = \"CVFF1:\"\n\t\n\tlocal function UnpackFlags(Text: string): string\n\t    local Size, Body = Text:match(`^{Marker}(%d+):(.+)$`)\n\t    if not Size then\n\t        return Text\n\t    end\n\t\n\t    local Success, Plain = pcall(function()\n\t        return lz4decompress(base64decode(Body), tonumber(Size))\n\t    end)\n\t    return Success and Plain or Text\n\tend\n\t\n\tlocal function Apply()\n\t    if not FFlag.Enabled then\n\t        return\n\t    end\n\t\n\t    local Applied: number = 0\n\t    for _, v: string in List.ListEnabled do\n\t        local Name, Value = v:match(\"^%s*(.-)%s*=%s*(.-)%s*$\")\n\t        for _, Prefix: string in Prefixes do\n\t            if Name and Name:sub(1, #Prefix) == Prefix then\n\t                Name = Name:sub(#Prefix + 1)\n\t                break\n\t            end\n\t        end\n\t\n\t        if Name and Name ~= \"\" and Value ~= \"\" and pcall(setfflag, Name, Value) then\n\t            Applied += 1\n\t        end\n\t    end\n\t\n\t    if Applied > 0 then\n\t        SendNotification(\"Vape\", `Applied {Applied} fflag{Applied == 1 and \"\" or \"s\"}, join a new game for them to take effect`, 12, \"info\")\n\t    end\n\tend\n\t\n\tlocal function Ingest(Text: string, Source: string)\n\t    Text = UnpackFlags(Text)\n\t    local Success, Json = pcall(function()\n\t        return HttpService:JSONDecode(Text)\n\t    end)\n\t\n\t    if not Success or typeof(Json) ~= \"table\" then\n\t        SendNotification(\"Vape\", `{Source} is not valid fflag json`, 12, \"warning\")\n\t        return\n\t    end\n\t\n\t    local AddedCount, DroppedCount = 0, 0\n\t    for Key: any, v: any in Json do\n\t        local Entry: string?\n\t        for _, Prefix: string in Prefixes do\n\t            if typeof(Key) == \"string\" and #Key > #Prefix and Key:sub(1, #Prefix) == Prefix and (typeof(v) == \"string\" or typeof(v) == \"number\" or typeof(v) == \"boolean\") then\n\t                Entry = `{Key}={tostring(v)}`\n\t                break\n\t            end\n\t        end\n\t\n\t        if Entry and not table.find(List.List, Entry) then\n\t            table.insert(List.List, Entry)\n\t            table.insert(List.ListEnabled, Entry)\n\t            AddedCount += 1\n\t        elseif not Entry then\n\t            DroppedCount += 1\n\t        end\n\t    end\n\t\n\t    List:ChangeValue()\n\t    SendNotification(\"Vape\", `Took {AddedCount} fflag{AddedCount == 1 and \"\" or \"s\"} from {Source}{DroppedCount > 0 and `, dropped {DroppedCount} it did not recognise` or \"\"}`, 12, AddedCount > 0 and \"info\" or \"warning\")\n\tend\n\t\n\tFFlag = vape.Legit:CreateModule({\n\t    Name = \"FFlagEditor\",\n\t    Category = \"Game\",\n\t    Icon = GetVapeAsset(`{vape.Directory}/assets/new/legit_fflageditor.png`),\n\t    Function = function(Callback: boolean)\n\t        if Callback then\n\t            Apply()\n\t        else\n\t            SendNotification(\"Vape\", \"Inorder to disable fflags you have applied, You need to restart roblox\", 20, \"info\")\n\t        end\n\t    end\n\t})\n\t\n\tList = FFlag:CreateTextList({\n\t    Name = \"Flags\",\n\t    Function = Apply,\n\t    Tooltip = \"One flag per entry as Name=Value, click a flag to leave it out without deleting it\\nSaved with your profile, so it travels with an exported config\"\n\t})\n\tFlags = FFlag:CreateTextBox({\n\t    Name = \"FFlags\",\n\t    Placeholder = \"json format only\",\n\t    Function = function(Enter: boolean)\n\t        if Enter and Flags.Value ~= \"\" then\n\t            Ingest(Flags.Value, \"the box\")\n\t            Flags:SetValue(\"\")\n\t        end\n\t    end\n\t})\n\tFFlag:CreateButton({\n\t    Name = \"Import from file\",\n\t    Function = function()\n\t        if not isfile(`{vape.Directory}/fflags.json`) then\n\t            SendNotification(\"Vape\", `No {vape.Directory}/fflags.json to read`, 12, \"warning\")\n\t            return\n\t        end\n\t\n\t        Ingest(readfile(`{vape.Directory}/fflags.json`), `{vape.Directory}/fflags.json`)\n\t    end\n\t})\n\tFFlag:CreateButton({\n\t    Name = \"Export to file\",\n\t    Function = function()\n\t        local Json: {[string]: string} = {}\n\t        for _, v: string in List.ListEnabled do\n\t            local Name, Value = v:match(\"^%s*(.-)%s*=%s*(.-)%s*$\")\n\t            if Name and Name ~= \"\" then\n\t                Json[Name] = Value\n\t            end\n\t        end\n\t\n\t        local Plain: string = HttpService:JSONEncode(Json)\n\t        local Success, Blob = pcall(function()\n\t            return `{Marker}{#Plain}:{base64encode(lz4compress(Plain))}`\n\t        end)\n\t\n\t        local Copied, Packed = Plain, false\n\t        if Success and UnpackFlags(Blob) == Plain then\n\t            Copied, Packed = Blob, true\n\t        end\n\t        writefile(`{vape.Directory}/fflags.json`, Plain)\n\t\n\t        if setclipboard then\n\t            setclipboard(Copied)\n\t        end\n\t\n\t        SendNotification(\"Vape\", Packed and `Wrote {vape.Directory}/fflags.json and copied {#Copied} characters to your clipboard, {math.floor(#Copied / #Plain * 100)}% of the raw json` or `Wrote {vape.Directory}/fflags.json and copied the raw json, packing it did not read back so it was left alone`, 12, Packed and \"info\" or \"warning\")\n\t    end\n\t})\n\tFFlag:CreateButton({\n\t    Name = \"Reset\",\n\t    Function = function()\n\t        table.clear(List.List)\n\t        table.clear(List.ListEnabled)\n\t        List:ChangeValue()\n\t        SendNotification(\"Vape\", \"Cleared the list, restart roblox to drop the flags already applied\", 20, \"info\")\n\t    end\n\t})\nend)\n\nRun(function()\n\tlocal FOV\n\tlocal Value\n\tlocal OldFOV: number\n\t\n\tFOV = vape.Legit:CreateModule({\n\t    Name = \"FOV\",\n\t    Category = \"Game\",\n\t    Icon = GetVapeAsset(`{vape.Directory}/assets/new/legit_fov.png`),\n\t    Function = function(Callback: boolean)\n\t        if Callback then\n\t            OldFOV = Camera.FieldOfView\n\t            repeat\n\t                Camera.FieldOfView = Value.Value\n\t                task.wait()\n\t            until not FOV.Enabled\n\t        else\n\t            Camera.FieldOfView = OldFOV\n\t        end\n\t    end,\n\t    Tooltip = \"Adjusts camera vision\"\n\t})\n\t\n\tValue = FOV:CreateSlider({\n\t    Name = \"FOV\",\n\t    Min = 30,\n\t    Max = 120\n\t})\nend)\n\nRun(function()\n\tlocal FPS\n\tlocal Label: TextLabel\n\t\n\tFPS = vape.Legit:CreateModule({\n\t    Name = \"FPS\",\n\t    Category = \"HUD\",\n\t    Icon = GetVapeAsset(`{vape.Directory}/assets/new/legit_fps.png`),\n\t    Function = function(Callback: boolean)\n\t        if Callback then\n\t            local Frames: {number} = {}\n\t            local StartClock: number = os.clock()\n\t            local UpdateTick: number = tick()\n\t\n\t            FPS:Clean(RunService.Heartbeat:Connect(function()\n\t                local UpdateClock: number = os.clock()\n\t                table.insert(Frames, UpdateClock)\n\t\n\t                if UpdateTick < tick() then\n\t                    UpdateTick = tick() + 1\n\t\n\t                    local Expired: number = 0\n\t                    while Frames[Expired + 1] and Frames[Expired + 1] < UpdateClock - 1 do\n\t                        Expired += 1\n\t                    end\n\t\n\t                    if Expired > 0 then\n\t                        local Count: number = #Frames\n\t                        table.move(Frames, Expired + 1, Count, 1)\n\t                        for i: number = Count - Expired + 1, Count do\n\t                            Frames[i] = nil\n\t                        end\n\t                    end\n\t\n\t                    Label.Text = `{math.floor(os.clock() - StartClock >= 1 and #Frames or #Frames / (os.clock() - StartClock))} FPS`\n\t                end\n\t            end))\n\t        end\n\t    end,\n\t    Size = UDim2.fromOffset(100, 41),\n\t    Tooltip = \"Shows the current framerate\"\n\t})\n\t\n\tFPS:CreateFont({\n\t    Name = \"Font\",\n\t    Blacklist = \"Gotham\",\n\t    Function = function(Val: Font)\n\t        Label.FontFace = Val\n\t    end\n\t})\n\tFPS:CreateColorSlider({\n\t    Name = \"Color\",\n\t    DefaultValue = 0,\n\t    DefaultOpacity = 0.5,\n\t    Function = function(Hue: number, Sat: number, Val: number, Opacity: number)\n\t        Label.BackgroundColor3 = Color3.fromHSV(Hue, Sat, Val)\n\t        Label.BackgroundTransparency = 1 - Opacity\n\t    end\n\t})\n\tLabel = Instance.new(\"TextLabel\")\n\tLabel.Size = UDim2.fromScale(1, 1)\n\tLabel.BackgroundTransparency = 0.5\n\tLabel.TextSize = 15\n\tLabel.FontFace = UIPallet.Font\n\tLabel.Text = \"inf FPS\"\n\tLabel.TextColor3 = Color3.new(1, 1, 1)\n\tLabel.BackgroundColor3 = Color3.new()\n\tLabel.Parent = FPS.Children\n\tlocal Corner: UICorner = Instance.new(\"UICorner\")\n\tCorner.CornerRadius = UDim.new(0, 4)\n\tCorner.Parent = Label\nend)\n\nRun(function()\n\tlocal Keystrokes\n\tlocal KeyStyle\n\tlocal MouseStyle\n\tlocal ShowSpacebar\n\tlocal ShowCpsOnly\n\tlocal Keys = {}\n\tlocal LeftClicks: {number} = {}\n\tlocal RightClicks: {number} = {}\n\tlocal ArrowIcons: {[string]: string} = {\n\t    W = GetVapeAsset(`{vape.Directory}/assets/new/key_up.png`),\n\t    A = GetVapeAsset(`{vape.Directory}/assets/new/key_left.png`),\n\t    S = GetVapeAsset(`{vape.Directory}/assets/new/key_down.png`),\n\t    D = GetVapeAsset(`{vape.Directory}/assets/new/key_right.png`)\n\t}\n\tlocal Keybinds: {[Enum.KeyCode]: string} = {\n\t    [Enum.KeyCode.W] = \"W\",\n\t    [Enum.KeyCode.A] = \"A\",\n\t    [Enum.KeyCode.S] = \"S\",\n\t    [Enum.KeyCode.D] = \"D\",\n\t    [Enum.KeyCode.Space] = \"Space\"\n\t}\n\tlocal ReleasedBackground: Color3 = Color3.fromRGB(20, 20, 20)\n\tlocal PressedText: Color3 = Color3.fromRGB(20, 20, 20)\n\tlocal KeyTween: TweenInfo = TweenInfo.new(0.05, Enum.EasingStyle.Linear)\n\tlocal Holder, MouseIcons, CpsHolder, CpsBackground, CpsDivider, CpsLeft, CpsRight, CpsLabel\n\tlocal LeftMouseIcon, RightMouseIcon, MiddleMouseIcon\n\tlocal ShownLeft, ShownRight\n\t\n\tlocal function AddLabel(Parent: Instance, Name: string, Text: string): TextLabel\n\t    local Label: TextLabel = Instance.new(\"TextLabel\")\n\t    Label.BackgroundTransparency = 1\n\t    Label.FontFace = UIPallet.FontDisplay\n\t    Label.Name = Name\n\t    Label.Size = UDim2.fromOffset(200, 22)\n\t    Label.Text = Text\n\t    Label.TextColor3 = Color3.fromRGB(209, 209, 209)\n\t    Label.TextSize = 16 * UIPallet.DisplayScale\n\t    Label.Parent = Parent\n\t\n\t    return Label\n\tend\n\t\n\tlocal function PlaceCps(Label: TextLabel, X: number, CenterY: number, Alignment: Enum.TextXAlignment)\n\t    Label.Position = UDim2.fromOffset(Alignment == Enum.TextXAlignment.Right and X - 200 or X, CenterY - 11)\n\t    Label.TextXAlignment = Alignment\n\tend\n\t\n\tlocal function PlaceKey(Entry, X: number, Y: number, Width: number, Height: number)\n\t    Entry.Object.Position = UDim2.fromOffset(X, Y - 1)\n\t    Entry.Object.Size = UDim2.fromOffset(Width, Height + 1)\n\t    Entry.Label.Position = UDim2.fromOffset((Width / 2) - 100, 5.75)\n\t    Entry.Icon.Position = UDim2.fromOffset((Width / 2) - 4.4, 6)\n\tend\n\t\n\tlocal function PressKey(Entry, Pressed: boolean)\n\t    if Entry.Pressed == Pressed then\n\t        return\n\t    end\n\t\n\t    Entry.Pressed = Pressed\n\t    Entry.Shadow.Enabled = Pressed\n\t\n\t    Tween:Tween(Entry.Object, KeyTween, {\n\t        BackgroundColor3 = Pressed and Color3.new(1, 1, 1) or ReleasedBackground,\n\t        BackgroundTransparency = Pressed and 0 or 0.294\n\t    })\n\t\n\t    Tween:Tween(Entry.Bar, KeyTween, {\n\t        BackgroundColor3 = Pressed and PressedText or Color3.new(1, 1, 1)\n\t    })\n\t\n\t    Tween:Tween(Entry.Icon, KeyTween, {\n\t        ImageColor3 = Pressed and PressedText or Color3.new(1, 1, 1)\n\t    })\n\t\n\t    Tween:Tween(Entry.Label, KeyTween, {\n\t        TextColor3 = Pressed and PressedText or Color3.new(1, 1, 1)\n\t    })\n\t\n\t    if Entry.Mouse then\n\t        Tween:Tween(Entry.Mouse, KeyTween, {\n\t            ImageColor3 = Pressed and Color3.new(1, 1, 1) or ReleasedBackground,\n\t            ImageTransparency = Pressed and 0 or 0.294\n\t        })\n\t    end\n\tend\n\t\n\tlocal function CountClicks(Clicks: {number}): number\n\t    local Now: number = tick()\n\t    while Clicks[1] and Clicks[1] < Now do\n\t        table.remove(Clicks, 1)\n\t    end\n\t\n\t    return #Clicks\n\tend\n\t\n\tlocal function RefreshLayout()\n\t    if not Holder then\n\t        return\n\t    end\n\t\n\t    local IconStyle: boolean = MouseStyle.Value == \"Icon\"\n\t    local ArrowStyle: boolean = KeyStyle.Value == \"Arrow\"\n\t    local Spacebar: boolean = ShowSpacebar.Enabled\n\t\n\t    for KeyName: string, v: any in Keys do\n\t        v.Object.Visible = not ShowCpsOnly.Enabled and (KeyName ~= \"Space\" or Spacebar) and not (IconStyle and (KeyName == \"LMB\" or KeyName == \"RMB\"))\n\t        v.Label.Visible = not ArrowStyle or KeyName == \"LMB\" or KeyName == \"RMB\" or KeyName == \"Space\"\n\t        v.Icon.Visible = ArrowStyle and ArrowIcons[KeyName] ~= nil\n\t        v.Icon.Image = ArrowIcons[KeyName] or \"\"\n\t    end\n\t\n\t    MouseIcons.Visible = IconStyle and not ShowCpsOnly.Enabled\n\t    CpsDivider.Visible = not ShowCpsOnly.Enabled\n\t    CpsLabel.Visible = ShowCpsOnly.Enabled\n\t    CpsRight.Visible = not ShowCpsOnly.Enabled\n\t\n\t    if ShowCpsOnly.Enabled then\n\t        Holder.Size = UDim2.fromOffset(150, 40)\n\t        CpsHolder.Position = UDim2.fromOffset(0, 0)\n\t        CpsHolder.Size = UDim2.fromOffset(110, 20)\n\t        CpsBackground.Position = UDim2.fromOffset(0, 0)\n\t        CpsBackground.Size = UDim2.fromOffset(39 + GetFontBounds(\"CPS\", 16 * UIPallet.DisplayScale, UIPallet.FontDisplay).X, 24)\n\t        PlaceCps(CpsLeft, 22, 14, Enum.TextXAlignment.Right)\n\t        PlaceCps(CpsLabel, 25, 14, Enum.TextXAlignment.Left)\n\t\n\t        return\n\t    end\n\t\n\t    local KeysY: number = IconStyle and 8 or 4\n\t    local MouseX: number = IconStyle and 122 or 0\n\t    local MouseY: number = (IconStyle and KeysY - 12 or KeysY + 80) + (Spacebar and 28 or 0)\n\t    local CpsWidth: number = IconStyle and 80 or 110\n\t    Holder.Size = UDim2.fromOffset(108 + (IconStyle and 96 or 0), (IconStyle and 80 or 144) + (Spacebar and 28 or 0))\n\t    PlaceKey(Keys.W, 38, KeysY - 4, 34, 34)\n\t    PlaceKey(Keys.A, 0, KeysY + 38, 34, 34)\n\t    PlaceKey(Keys.S, 38, KeysY + 38, 34, 34)\n\t    PlaceKey(Keys.D, 76, KeysY + 38, 34, 34)\n\t    PlaceKey(Keys.Space, 0, KeysY + 79, 110.5, 22)\n\t    PlaceKey(Keys.LMB, MouseX, MouseY, 52.7, 32)\n\t    PlaceKey(Keys.RMB, MouseX + 56.7, MouseY, 52.7, 32)\n\t    MouseIcons.Position = UDim2.fromOffset(MouseX - 4, MouseY)\n\t    CpsHolder.Position = UDim2.fromOffset(MouseX, MouseY + (IconStyle and 44 or 34))\n\t    CpsHolder.Size = UDim2.fromOffset(CpsWidth, 20)\n\t    CpsBackground.Position = UDim2.fromOffset(0, 4)\n\t    CpsBackground.Size = UDim2.fromOffset(CpsWidth, 24)\n\t    CpsDivider.Position = UDim2.fromOffset(CpsWidth / 2, 8)\n\t    PlaceCps(CpsLeft, 10, 16, Enum.TextXAlignment.Left)\n\t    PlaceCps(CpsRight, CpsWidth - 10, 16, Enum.TextXAlignment.Right)\n\tend\n\t\n\tlocal function Update()\n\t    if vape.ThreadFix then\n\t        setthreadidentity(8)\n\t    end\n\t\n\t    local LeftCount: number = CountClicks(LeftClicks)\n\t    if LeftCount ~= ShownLeft then\n\t        ShownLeft = LeftCount\n\t        CpsLeft.Text = tostring(LeftCount)\n\t    end\n\t\n\t    local RightCount: number = CountClicks(RightClicks)\n\t    if RightCount ~= ShownRight then\n\t        ShownRight = RightCount\n\t        CpsRight.Text = tostring(RightCount)\n\t    end\n\tend\n\t\n\tlocal function InputChanged(Input: InputObject, Pressed: boolean)\n\t    if vape.ThreadFix then\n\t        setthreadidentity(8)\n\t    end\n\t\n\t    local Name: string? = Keybinds[Input.KeyCode]\n\t    if Input.UserInputType == Enum.UserInputType.MouseButton1 then\n\t        Name = \"LMB\"\n\t\n\t        if Pressed then\n\t            table.insert(LeftClicks, tick() + 1)\n\t        end\n\t    elseif Input.UserInputType == Enum.UserInputType.MouseButton2 then\n\t        Name = \"RMB\"\n\t\n\t        if Pressed then\n\t            table.insert(RightClicks, tick() + 1)\n\t        end\n\t    end\n\t\n\t    if Name and Keys[Name] then\n\t        PressKey(Keys[Name], Pressed)\n\t    end\n\tend\n\t\n\tKeystrokes = vape.Legit:CreateModule({\n\t    Name = \"Keystrokes\",\n\t    Category = \"HUD\",\n\t    Icon = GetVapeAsset(`{vape.Directory}/assets/new/legit_keystrokes.png`),\n\t    Function = function(Callback: boolean)\n\t        if Callback then\n\t            Keystrokes:Clean(UserInputService.InputBegan:Connect(function(Input: InputObject)\n\t                InputChanged(Input, true)\n\t            end))\n\t\n\t            Keystrokes:Clean(UserInputService.InputEnded:Connect(function(Input: InputObject)\n\t                InputChanged(Input, false)\n\t            end))\n\t\n\t            Keystrokes:Clean(RunService.RenderStepped:Connect(Update))\n\t        else\n\t            for _, v: any in Keys do\n\t                PressKey(v, false)\n\t            end\n\t        end\n\t    end,\n\t    Size = UDim2.fromOffset(108, 172),\n\t    Tooltip = \"Shows when your movement keys or mouse buttons are pressed, as well as mouse clicks per second\"\n\t})\n\t\n\tKeyStyle = Keystrokes:CreateDropdown({\n\t    Name = \"Key Style\",\n\t    List = {\"Keyboard\", \"Arrow\"},\n\t    Function = function()\n\t        RefreshLayout()\n\t    end\n\t})\n\tMouseStyle = Keystrokes:CreateDropdown({\n\t    Name = \"Mouse Style\",\n\t    List = {\"Button\", \"Icon\"},\n\t    Function = function()\n\t        RefreshLayout()\n\t    end\n\t})\n\tShowSpacebar = Keystrokes:CreateToggle({\n\t    Name = \"Show Spacebar\",\n\t    Function = function()\n\t        RefreshLayout()\n\t    end,\n\t    Default = true\n\t})\n\tShowCpsOnly = Keystrokes:CreateToggle({\n\t    Name = \"Show CPS Only\",\n\t    Function = function()\n\t        RefreshLayout()\n\t    end\n\t})\n\tHolder = Keystrokes.Children\n\tfor _, v: string in {\"W\", \"A\", \"S\", \"D\", \"Space\", \"LMB\", \"RMB\"} do\n\t    local Name: string = v\n\t    local Key: Frame = Instance.new(\"Frame\")\n\t    Key.BackgroundColor3 = ReleasedBackground\n\t    Key.BackgroundTransparency = 0.294\n\t    Key.BorderSizePixel = 0\n\t    Key.Name = Name\n\t    Key.Parent = Holder\n\t    local Corner: UICorner = Instance.new(\"UICorner\")\n\t    Corner.CornerRadius = UDim.new(0, 5)\n\t    Corner.Parent = Key\n\t    local Shadow: UIShadow = Instance.new(\"UIShadow\")\n\t    Shadow.BlurRadius = UDim.new(0, 6)\n\t    Shadow.Color = Color3.new()\n\t    Shadow.Enabled = false\n\t    Shadow.Offset = UDim2.new()\n\t    Shadow.Spread = UDim2.new()\n\t    Shadow.Transparency = 0.404\n\t    Shadow.Parent = Key\n\t    local Label: TextLabel = Instance.new(\"TextLabel\")\n\t    Label.BackgroundTransparency = 1\n\t    Label.FontFace = UIPallet.FontBold\n\t    Label.Name = \"Label\"\n\t    Label.Size = UDim2.fromOffset(200, 20)\n\t    Label.Text = Name == \"Space\" and \"\" or Name\n\t    Label.TextColor3 = Color3.new(1, 1, 1)\n\t    Label.TextSize = 14\n\t    Label.Parent = Key\n\t    local Icon: ImageLabel = Instance.new(\"ImageLabel\")\n\t    Icon.BackgroundTransparency = 1\n\t    Icon.Name = \"Icon\"\n\t    Icon.Size = UDim2.fromOffset(8.8, 8.8)\n\t    Icon.Visible = false\n\t    Icon.Parent = Key\n\t    local Bar: Frame = Instance.new(\"Frame\")\n\t    Bar.AnchorPoint = Vector2.new(0.5, 0)\n\t    Bar.BackgroundColor3 = Color3.new(1, 1, 1)\n\t    Bar.BorderSizePixel = 0\n\t    Bar.Name = \"Bar\"\n\t    Bar.Position = UDim2.new(0.5, 0, 0, 4)\n\t    Bar.Size = UDim2.fromOffset(60, 3)\n\t    Bar.Visible = Name == \"Space\"\n\t    Bar.Parent = Key\n\t    Keys[Name] = {Object = Key, Label = Label, Icon = Icon, Bar = Bar, Shadow = Shadow, Pressed = false}\n\tend\n\tMouseIcons = Instance.new(\"Frame\")\n\tMouseIcons.BackgroundTransparency = 1\n\tMouseIcons.Name = \"MouseIcons\"\n\tMouseIcons.Size = UDim2.fromOffset(96, 48)\n\tMouseIcons.Visible = false\n\tMouseIcons.Parent = Holder\n\tLeftMouseIcon = Instance.new(\"ImageLabel\")\n\tLeftMouseIcon.BackgroundTransparency = 1\n\tLeftMouseIcon.Image = GetVapeAsset(`{vape.Directory}/assets/new/key_lmb.png`)\n\tLeftMouseIcon.ImageColor3 = ReleasedBackground\n\tLeftMouseIcon.Name = \"LMB\"\n\tLeftMouseIcon.Size = UDim2.fromOffset(50.2, 48)\n\tLeftMouseIcon.Parent = MouseIcons\n\tRightMouseIcon = LeftMouseIcon:Clone()\n\tRightMouseIcon.Image = GetVapeAsset(`{vape.Directory}/assets/new/key_rmb.png`)\n\tRightMouseIcon.Name = \"RMB\"\n\tRightMouseIcon.Position = UDim2.fromOffset(40, 0)\n\tRightMouseIcon.Parent = MouseIcons\n\tMiddleMouseIcon = Instance.new(\"ImageLabel\")\n\tMiddleMouseIcon.BackgroundTransparency = 1\n\tMiddleMouseIcon.Image = GetVapeAsset(`{vape.Directory}/assets/new/key_mmb.png`)\n\tMiddleMouseIcon.ImageColor3 = Color3.fromRGB(225, 225, 225)\n\tMiddleMouseIcon.Name = \"MMB\"\n\tMiddleMouseIcon.Position = UDim2.fromOffset(43, 14)\n\tMiddleMouseIcon.Size = UDim2.fromOffset(3.9, 13.8)\n\tMiddleMouseIcon.Parent = MouseIcons\n\tCpsHolder = Instance.new(\"Frame\")\n\tCpsHolder.BackgroundTransparency = 1\n\tCpsHolder.Name = \"CPS\"\n\tCpsHolder.Size = UDim2.fromOffset(110, 20)\n\tCpsHolder.Parent = Holder\n\tCpsBackground = Instance.new(\"Frame\")\n\tCpsBackground.BackgroundColor3 = ReleasedBackground\n\tCpsBackground.BackgroundTransparency = 0.294\n\tCpsBackground.BorderSizePixel = 0\n\tCpsBackground.Name = \"Background\"\n\tCpsBackground.ZIndex = 0\n\tCpsBackground.Parent = CpsHolder\n\tlocal CpsCorner: UICorner = Instance.new(\"UICorner\")\n\tCpsCorner.CornerRadius = UDim.new(0, 5)\n\tCpsCorner.Parent = CpsBackground\n\tCpsDivider = Instance.new(\"Frame\")\n\tCpsDivider.BackgroundColor3 = Color3.fromRGB(209, 209, 209)\n\tCpsDivider.BorderSizePixel = 0\n\tCpsDivider.Name = \"Divider\"\n\tCpsDivider.Size = UDim2.fromOffset(2, 18)\n\tCpsDivider.Parent = CpsHolder\n\tCpsLeft = AddLabel(CpsHolder, \"Left\", \"0\")\n\tCpsRight = AddLabel(CpsHolder, \"Right\", \"0\")\n\tCpsLabel = AddLabel(CpsHolder, \"Label\", \"CPS\")\n\tCpsLabel.Visible = false\n\tKeys.LMB.Mouse = LeftMouseIcon\n\tKeys.RMB.Mouse = RightMouseIcon\n\tRefreshLayout()\nend)\n\nRun(function()\n\tlocal Memory\n\tlocal Label: TextLabel\n\t\n\tMemory = vape.Legit:CreateModule({\n\t    Name = \"Memory\",\n\t    Category = \"HUD\",\n\t    Icon = GetVapeAsset(`{vape.Directory}/assets/new/legit_memory.png`),\n\t    Function = function(Callback: boolean)\n\t        if Callback then\n\t            repeat\n\t                Label.Text = `{math.floor(tonumber(Stats.PerformanceStats.Memory:GetValue()))} MB`\n\t                task.wait(1)\n\t            until not Memory.Enabled\n\t        end\n\t    end,\n\t    Size = UDim2.fromOffset(100, 41),\n\t    Tooltip = \"A label showing the memory currently used by roblox\"\n\t})\n\t\n\tMemory:CreateFont({\n\t    Name = \"Font\",\n\t    Blacklist = \"Gotham\",\n\t    Function = function(Val: Font)\n\t        Label.FontFace = Val\n\t    end\n\t})\n\tMemory:CreateColorSlider({\n\t    Name = \"Color\",\n\t    DefaultValue = 0,\n\t    DefaultOpacity = 0.5,\n\t    Function = function(Hue: number, Sat: number, Val: number, Opacity: number)\n\t        Label.BackgroundColor3 = Color3.fromHSV(Hue, Sat, Val)\n\t        Label.BackgroundTransparency = 1 - Opacity\n\t    end\n\t})\n\tLabel = Instance.new(\"TextLabel\")\n\tLabel.Size = UDim2.new(0, 100, 0, 41)\n\tLabel.BackgroundTransparency = 0.5\n\tLabel.TextSize = 15\n\tLabel.FontFace = UIPallet.Font\n\tLabel.Text = \"0 MB\"\n\tLabel.TextColor3 = Color3.new(1, 1, 1)\n\tLabel.BackgroundColor3 = Color3.new()\n\tLabel.Parent = Memory.Children\n\tlocal Corner: UICorner = Instance.new(\"UICorner\")\n\tCorner.CornerRadius = UDim.new(0, 4)\n\tCorner.Parent = Label\nend)\n\nRun(function()\n\tlocal Ping\n\tlocal Label: TextLabel\n\t\n\tPing = vape.Legit:CreateModule({\n\t    Name = \"Ping\",\n\t    Category = \"HUD\",\n\t    Icon = GetVapeAsset(`{vape.Directory}/assets/new/legit_ping.png`),\n\t    Function = function(Callback: boolean)\n\t        if Callback then\n\t            repeat\n\t                Label.Text = `{math.floor(tonumber(Stats.PerformanceStats.Ping:GetValue()))} ms`\n\t                task.wait(1)\n\t            until not Ping.Enabled\n\t        end\n\t    end,\n\t    Size = UDim2.fromOffset(100, 41),\n\t    Tooltip = \"Shows the current connection speed to the roblox server\"\n\t})\n\t\n\tPing:CreateFont({\n\t    Name = \"Font\",\n\t    Blacklist = \"Gotham\",\n\t    Function = function(Val: Font)\n\t        Label.FontFace = Val\n\t    end\n\t})\n\tPing:CreateColorSlider({\n\t    Name = \"Color\",\n\t    DefaultValue = 0,\n\t    DefaultOpacity = 0.5,\n\t    Function = function(Hue: number, Sat: number, Val: number, Opacity: number)\n\t        Label.BackgroundColor3 = Color3.fromHSV(Hue, Sat, Val)\n\t        Label.BackgroundTransparency = 1 - Opacity\n\t    end\n\t})\n\tLabel = Instance.new(\"TextLabel\")\n\tLabel.Size = UDim2.new(0, 100, 0, 41)\n\tLabel.BackgroundTransparency = 0.5\n\tLabel.TextSize = 15\n\tLabel.FontFace = UIPallet.Font\n\tLabel.Text = \"0 ms\"\n\tLabel.TextColor3 = Color3.new(1, 1, 1)\n\tLabel.BackgroundColor3 = Color3.new()\n\tLabel.Parent = Ping.Children\n\tlocal Corner: UICorner = Instance.new(\"UICorner\")\n\tCorner.CornerRadius = UDim.new(0, 4)\n\tCorner.Parent = Label\nend)\n\nRun(function()\n\tlocal SongBeats\n\tlocal List\n\tlocal FOV\n\tlocal FOVValue = {}\n\tlocal Volume\n\tlocal AlreadyPicked: {string} = {}\n\tlocal BeatTick: number = os.clock()\n\tlocal OldFOV, SongObject, SongBPM, SongTween\n\t\n\tlocal function ChooseSong()\n\t    local Songs: {string} = List.ListEnabled\n\t    if #AlreadyPicked >= #Songs then\n\t        table.clear(AlreadyPicked)\n\t    end\n\t\n\t    if #Songs <= 0 then\n\t        SendNotification(\"SongBeats\", \"no songs\", 10)\n\t        SongBeats:Toggle()\n\t        return\n\t    end\n\t\n\t    local ChosenSong: string = Songs[math.random(1, #Songs)]\n\t    if #Songs > 1 and table.find(AlreadyPicked, ChosenSong) then\n\t        repeat\n\t            task.wait()\n\t            ChosenSong = Songs[math.random(1, #Songs)]\n\t        until not table.find(AlreadyPicked, ChosenSong) or not SongBeats.Enabled\n\t    end\n\t    if not SongBeats.Enabled then\n\t        return\n\t    end\n\t\n\t    table.insert(AlreadyPicked, ChosenSong)\n\t    local Split: {string} = ChosenSong:split(\"/\")\n\t    if not isfile(Split[1]) then\n\t        SendNotification(\"SongBeats\", `Missing song ({Split[1]})`, 10)\n\t        SongBeats:Toggle()\n\t        return\n\t    end\n\t\n\t    SongObject.SoundId = AssetFunction(Split[1])\n\t    repeat\n\t        task.wait()\n\t    until SongObject.IsLoaded or not SongBeats.Enabled\n\t\n\t    if SongBeats.Enabled then\n\t        BeatTick = os.clock() + (tonumber(Split[3]) or 0)\n\t        SongBPM = 60 / (tonumber(Split[2]) or 50)\n\t        SongObject:Play()\n\t    end\n\tend\n\t\n\tSongBeats = vape.Legit:CreateModule({\n\t    Name = \"Song Beats\",\n\t    Category = \"Game\",\n\t    Icon = GetVapeAsset(`{vape.Directory}/assets/new/legit_songbeats.png`),\n\t    Function = function(Callback: boolean)\n\t        if Callback then\n\t            SongObject = Instance.new(\"Sound\")\n\t            SongObject.Volume = Volume.Value / 100\n\t            SongObject.Parent = workspace\n\t            SongBeats:Clean(SongObject)\n\t            OldFOV = Camera.FieldOfView\n\t\n\t            repeat\n\t                if not SongObject.Playing then\n\t                    ChooseSong()\n\t                end\n\t\n\t                if BeatTick < os.clock() and SongBeats.Enabled and FOV.Enabled then\n\t                    BeatTick = os.clock() + SongBPM\n\t                    if SongTween then\n\t                        SongTween:Cancel()\n\t                    end\n\t\n\t                    Camera.FieldOfView = OldFOV - FOVValue.Value\n\t                    SongTween = TweenService:Create(Camera, TweenInfo.new(math.min(SongBPM, 0.2), Enum.EasingStyle.Linear), {\n\t                        FieldOfView = OldFOV\n\t                    })\n\t\n\t                    SongTween:Play()\n\t                end\n\t\n\t                task.wait()\n\t            until not SongBeats.Enabled\n\t        else\n\t            if SongTween then\n\t                SongTween:Cancel()\n\t            end\n\t\n\t            if OldFOV then\n\t                Camera.FieldOfView = OldFOV\n\t            end\n\t\n\t            table.clear(AlreadyPicked)\n\t        end\n\t    end,\n\t    Tooltip = \"Built in mp3 player\"\n\t})\n\t\n\tList = SongBeats:CreateTextList({\n\t    Name = \"Songs\",\n\t    Placeholder = \"filepath/bpm/start\"\n\t})\n\tFOV = SongBeats:CreateToggle({\n\t    Name = \"Beat FOV\",\n\t    Function = function(Callback: boolean)\n\t        if FOVValue.Object then\n\t            FOVValue.Object.Visible = Callback\n\t        end\n\t\n\t        if SongBeats.Enabled then\n\t            SongBeats:Toggle()\n\t            SongBeats:Toggle()\n\t        end\n\t    end,\n\t    Default = true\n\t})\n\tFOVValue = SongBeats:CreateSlider({\n\t    Name = \"Adjustment\",\n\t    Min = 1,\n\t    Max = 30,\n\t    Default = 5,\n\t    Darker = true\n\t})\n\tVolume = SongBeats:CreateSlider({\n\t    Name = \"Volume\",\n\t    Function = function(Val: number)\n\t        if SongObject then\n\t            SongObject.Volume = Val / 100\n\t        end\n\t    end,\n\t    Min = 1,\n\t    Max = 100,\n\t    Default = 100,\n\t    Suffix = \"%\"\n\t})\nend)\n\nRun(function()\n\tlocal Speedmeter\n\tlocal Label: TextLabel\n\t\n\tSpeedmeter = vape.Legit:CreateModule({\n\t    Name = \"Speedmeter\",\n\t    Category = \"HUD\",\n\t    Icon = GetVapeAsset(`{vape.Directory}/assets/new/legit_speedmeter.png`),\n\t    Function = function(Callback: boolean)\n\t        if Callback then\n\t            repeat\n\t                local LastPosition: Vector3 = Entity.isAlive and Entity.character.HumanoidRootPart.Position * Vector3.new(1, 0, 1) or Vector3.zero\n\t                local Delta: number = task.wait(0.2)\n\t                local NewPosition: Vector3 = Entity.isAlive and Entity.character.HumanoidRootPart.Position * Vector3.new(1, 0, 1) or Vector3.zero\n\t                Label.Text = `{math.round(((LastPosition - NewPosition) / Delta).Magnitude)} sps`\n\t            until not Speedmeter.Enabled\n\t        end\n\t    end,\n\t    Size = UDim2.fromOffset(100, 41),\n\t    Tooltip = \"A label showing the average velocity in studs\"\n\t})\n\t\n\tSpeedmeter:CreateFont({\n\t    Name = \"Font\",\n\t    Blacklist = \"Gotham\",\n\t    Function = function(Val: Font)\n\t        Label.FontFace = Val\n\t    end\n\t})\n\tSpeedmeter:CreateColorSlider({\n\t    Name = \"Color\",\n\t    DefaultValue = 0,\n\t    DefaultOpacity = 0.5,\n\t    Function = function(Hue: number, Sat: number, Val: number, Opacity: number)\n\t        Label.BackgroundColor3 = Color3.fromHSV(Hue, Sat, Val)\n\t        Label.BackgroundTransparency = 1 - Opacity\n\t    end\n\t})\n\tLabel = Instance.new(\"TextLabel\")\n\tLabel.Size = UDim2.fromScale(1, 1)\n\tLabel.BackgroundTransparency = 0.5\n\tLabel.TextSize = 15\n\tLabel.FontFace = UIPallet.Font\n\tLabel.Text = \"0 sps\"\n\tLabel.TextColor3 = Color3.new(1, 1, 1)\n\tLabel.BackgroundColor3 = Color3.new()\n\tLabel.Parent = Speedmeter.Children\n\tlocal Corner: UICorner = Instance.new(\"UICorner\")\n\tCorner.CornerRadius = UDim.new(0, 4)\n\tCorner.Parent = Label\nend)\n\nRun(function()\n\tlocal TimeChanger\n\tlocal Value\n\tlocal Old: string?\n\t\n\tTimeChanger = vape.Legit:CreateModule({\n\t    Name = \"Time Changer\",\n\t    Category = \"Game\",\n\t    Icon = GetVapeAsset(`{vape.Directory}/assets/new/legit_timechanger.png`),\n\t    Function = function(Callback: boolean)\n\t        if Callback then\n\t            Old = Lighting.TimeOfDay\n\t            repeat\n\t                Lighting.TimeOfDay = `{Value.Value}:00:00`\n\t                task.wait()\n\t            until not TimeChanger.Enabled\n\t        else\n\t            Lighting.TimeOfDay = Old\n\t            Old = nil\n\t        end\n\t    end,\n\t    Tooltip = \"Change the time of the current world\"\n\t})\n\t\n\tValue = TimeChanger:CreateSlider({\n\t    Name = \"Time\",\n\t    Min = 0,\n\t    Max = 24,\n\t    Function = function(Val: number)\n\t        if TimeChanger.Enabled then\n\t            Lighting.TimeOfDay = `{Val}:00:00`\n\t        end\n\t    end,\n\t    Default = 12\n\t})\nend)"},{"path":"src/guis/new.lua","name":"new.lua","size":551263,"sha":"133b168bbae8b5893fa6f45aa57436baee5123cf","encoding":"utf8","content":"local License = ... or {}\nlocal vape = {\n    ActiveBinds = {},\n    Categories = {},\n    Directory = shared.VapeDeveloper and \"catprivate\" or \"catsix\",\n    FavoriteCount = 0,\n    GUIColor = {\n        Hue = 0.46,\n        Sat = 0.96,\n        Value = 0.52\n    },\n    HeldKeybinds = {},\n    Loaded = false,\n    Libraries = {},\n    Modules = {},\n    Place = game.PlaceId,\n    Profile = \"default\",\n    RainbowSliders = {},\n    Settings = {},\n    SettingToggleNotifications = {},\n    ThreadFix = setthreadidentity and true or false,\n    ToggleNotifications = {},\n    Version = \"4.22\",\n    Windows = {}\n}\n\nlocal Run = function(Callback: () -> ())\n    Callback()\nend\nlocal cloneref = cloneref or function(Reference: Instance)\n    return Reference\nend\nlocal TweenService = cloneref(game:GetService(\"TweenService\"))\nlocal UserInputService = cloneref(game:GetService(\"UserInputService\"))\nlocal TextService = cloneref(game:GetService(\"TextService\"))\nlocal GuiService = cloneref(game:GetService(\"GuiService\"))\nlocal RunService = cloneref(game:GetService(\"RunService\"))\nlocal HttpService = cloneref(game:GetService(\"HttpService\"))\nlocal Lighting = cloneref(game:GetService(\"Lighting\"))\n\nlocal FontSize: GetTextBoundsParams = Instance.new(\"GetTextBoundsParams\")\nFontSize.Width = math.huge\nlocal NotificationCache = {}\nlocal NotificationList = {}\nlocal Notifications\nlocal GetVapeAsset\nlocal VapeColors\nlocal Components\nlocal CreateSignal\nlocal ClickGUI\nlocal ScaledGUI\nlocal BlurEffect\nlocal BlurFocus\nlocal BlurTween\nlocal TopBarContainer: Instance?\nlocal TopBarStats: Instance?\nlocal TopBarHidden: boolean = false\nlocal TopBarButtons: {[GuiObject]: boolean} = {}\nlocal GlassConnection\nlocal GlassShown: boolean = true\nlocal GlassParts = {}\nlocal ToolBlur\nlocal Tooltip\nlocal TextGUI\nlocal Scale = {Scale = 1}\nlocal BlurInfo: TweenInfo = TweenInfo.new(0.3, Enum.EasingStyle.Quad, Enum.EasingDirection.Out)\nlocal GUI\nlocal SortQueued: boolean = false\nlocal BuildClock: number = os.clock()\nlocal BuildBudget: number = 0.03\n\nlocal function YieldBuild(Budget: number?)\n    if os.clock() - BuildClock > (Budget or BuildBudget) then\n        BuildBudget = math.clamp(task.wait(), 0.03, 0.07)\n        BuildClock = os.clock()\n    end\nend\n\nvape.YieldBuild = YieldBuild\n\nlocal StagedWindows: {{Object: GuiObject?, Parent: Instance?, Build: (() -> ())?}} = {}\nlocal WindowsMounted: boolean = false\n\nlocal function StageWindow(Object: GuiObject, Parent: Instance)\n    if WindowsMounted then\n        Object.Parent = Parent\n    else\n        table.insert(StagedWindows, {Object = Object, Parent = Parent})\n    end\nend\n\nlocal function StageBuild(Callback: () -> ())\n    if WindowsMounted then\n        Callback()\n    else\n        table.insert(StagedWindows, {Build = Callback})\n    end\nend\n\nlocal function MountWindows(Budget: number?)\n    local Started: number = os.clock()\n\n    while StagedWindows[1] do\n        local Entry = table.remove(StagedWindows, 1)\n        if Entry.Build then\n            local Success, Error = pcall(Entry.Build)\n            if not Success then\n                warn(`[catvape] failed to build a staged window: {Error}`)\n            end\n        else\n            pcall(function()\n                Entry.Object.Parent = Entry.Parent\n            end)\n        end\n\n        if Budget and os.clock() - Started > Budget then\n            task.wait()\n            Started = os.clock()\n        end\n    end\n\n    WindowsMounted = true\nend\n\nlocal isfile = isfile or function(FilePath: string)\n    local Success, Data = pcall(function()\n        return readfile(FilePath)\n    end)\n\n    return Success and Data ~= nil and Data ~= \"\"\nend\n\nlocal function LoadJSON(FilePath: string)\n    local Success, Data = pcall(function()\n        return HttpService:JSONDecode(readfile(FilePath))\n    end)\n\n    return Success and type(Data) == \"table\" and Data or nil\nend\n\nlocal function WriteJSON(FilePath: string, Data)\n    local Success, Encoded = pcall(HttpService.JSONEncode, HttpService, Data)\n    if not Success then\n        return false, Encoded\n    end\n\n    return pcall(writefile, FilePath, Encoded)\nend\n\nlocal NotificationsOff = isfile(`{vape.Directory}/profiles/notifications.txt`) and readfile(`{vape.Directory}/profiles/notifications.txt`) == \"false\"\nlocal LoadFailures: number = 0\nlocal DeferredLoads: number = 0\nlocal LoadGeneration: number = 0\nlocal LoadCalled: boolean = false\nlocal CanSave: boolean = true\nlocal NeedsSave: boolean = false\nlocal function AttemptLoad(Object, Data, Name: string)\n    local Success, Error = pcall(Object.Load, Object, Data)\n    if not Success then\n        LoadFailures += 1\n        warn(`[catvape] failed to load {Name}: {Error}`)\n    end\nend\n\nlocal function FinishLoad()\n    if not LoadCalled or DeferredLoads > 0 or vape.Loaded == nil then\n        return\n    end\n\n    vape.Loaded = CanSave\n\n    if SortQueued then\n        vape:SortCategories(true)\n    end\n\n    if vape.Downloader then\n        vape.Downloader:Destroy()\n        vape.Downloader = nil\n    end\n\n    if NeedsSave then\n        NeedsSave = false\n        vape:Save()\n    end\n\n    if not WindowsMounted then\n        task.spawn(function()\n            if vape.ThreadFix then\n                setthreadidentity(8)\n            end\n\n            task.wait()\n            MountWindows(0.004)\n        end)\n    end\nend\n\nlocal FeatureTags\nlocal function GetFeatureTag(Name: string)\n    if not FeatureTags then\n        FeatureTags = {}\n\n        if not isfile(`{vape.Directory}/features.json`) then\n            pcall(function()\n                writefile(`{vape.Directory}/features.json`, game:HttpGet(\"https://api.catvape.dev/download/src/features.json\", true))\n            end)\n        end\n\n        local Features = LoadJSON(`{vape.Directory}/features.json`)\n        for Tag: string, v: string in {updated = \"updated\", new = \"added\"} do\n            local List = Features and Features[v]\n\n            if type(List) == \"table\" then\n                for _, Feature: any in List do\n                    if type(Feature) == \"string\" then\n                        FeatureTags[Feature] = Tag\n                    end\n                end\n            end\n        end\n    end\n\n    return FeatureTags[Name]\nend\n\nlocal Color = {}\nlocal UIPallet = {}\ndo\n    function Color.Dark(Color: Color3, Amount: number)\n        local Hue, Sat, Val = Color:ToHSV()\n        return Color3.fromHSV(Hue, Sat, math.clamp(select(3, UIPallet.Main:ToHSV()) > 0.5 and Val + Amount or Val - Amount, 0, 1))\n    end\n\n    function Color.Light(Color: Color3, Amount: number)\n        local Hue, Sat, Val = Color:ToHSV()\n        return Color3.fromHSV(Hue, Sat, math.clamp(select(3, UIPallet.Main:ToHSV()) > 0.5 and Val - Amount or Val + Amount, 0, 1))\n    end\n\n    function vape:Color(Hue: number)\n        local Sat: number = 0.74 + (0.26 * math.min(Hue / 0.045, 1))\n\n        if Hue > 0.577 then\n            Sat = 1 - (0.48 * math.min((Hue - 0.577) / 0.088, 1))\n        end\n\n        if Hue > 0.674 then\n            Sat = 0.52 + (0.48 * math.min((Hue - 0.674) / 0.149, 1))\n        end\n\n        if Hue > 0.869 then\n            Sat = 1 - (0.26 * math.min((Hue - 0.869) / 0.131, 1))\n        end\n\n        return Hue, Sat, 1\n    end\n\n    function vape:TextColor(Hue: number, Sat: number, Val: number)\n        if Val >= 0.7 and (Sat < 0.6 or Hue > 0.04 and Hue < 0.56) then\n            return Color3.new(0.19, 0.19, 0.19)\n        end\n\n        return Color3.new(1, 1, 1)\n    end\nend\n\nlocal function DeferredOption(Kind: string, Props, Children: Instance?, API, Order: number?, Constructor: ((...any) -> any)?)\n    if Kind ~= \"Toggle\" and Kind ~= \"Slider\" and Kind ~= \"Dropdown\" and Kind ~= \"TextList\" and Kind ~= \"ColorSlider\" and Kind ~= \"Targets\" and Kind ~= \"TwoSlider\" and Kind ~= \"TextBox\" and (Kind ~= \"Bind\" or not Props.Module) then\n        if not Constructor then\n            return\n        end\n\n        local Before: number = #Children:GetChildren()\n        local Result = Constructor(Props, Children, API)\n        for i: number, Child: Instance in Children:GetChildren() do\n            if i > Before and Child:IsA(\"GuiObject\") then\n                Child.LayoutOrder = Order or 0\n            end\n        end\n\n        return Result\n    end\n\n    local Component = {Type = Kind, Index = 0}\n    local Mounted\n    local Callbacks = {}\n    local BindColor: Color3?\n    local Optional = {Bind = true, Name = true, Suffix = true, Mobile = true, Binding = true}\n    Props.Function = Props.Function or function() end\n\n    if Kind ~= \"Bind\" then\n        for _ in API.Options do\n            Component.Index += 1\n        end\n    end\n\n    function Component:Color() end\n\n    function Component:OnMount(Callback: () -> ())\n        table.insert(Callbacks, Callback)\n    end\n\n    local function Mount()\n        if Mounted then return Mounted end\n\n        local Data = {}\n        Component:Save(Data)\n        local Settings = table.clone(Props)\n        Settings.Function = function() end\n        local Bind = rawget(Component, \"Bind\")\n        local Triggered = rawget(Component, \"Triggered\")\n        local Index: number = Component.Index\n        local Minimum = rawget(Component, \"Min\")\n        local Maximum = rawget(Component, \"Max\")\n        local Before: number = Children and #Children:GetChildren() or 0\n        Mounted = Components[Kind](Settings, Children, API)\n        if Order and Children then\n            for i: number, Child: Instance in Children:GetChildren() do\n                if i > Before and Child:IsA(\"GuiObject\") then\n                    Child.LayoutOrder = Order\n                end\n            end\n        end\n        Mounted.Index = Index\n\n        if Minimum then Mounted.Min = Minimum end\n        if Maximum then Mounted.Max = Maximum end\n        if Triggered then Mounted.Triggered = Triggered end\n        Mounted:Load(Data[Kind == \"Targets\" and \"Targets\" or Props.Name or \"Bind\"])\n        Settings.Function = Props.Function\n        if BindColor then Mounted:SetColor(BindColor) end\n\n        if Kind == \"ColorSlider\" then\n            local Rainbow: number? = table.find(vape.RainbowSliders, Component)\n            if Rainbow then table.remove(vape.RainbowSliders, Rainbow) end\n        end\n\n        if Kind == \"Bind\" then\n            local Active: number? = table.find(vape.ActiveBinds, Component)\n            if Active then table.remove(vape.ActiveBinds, Active) end\n            if Props.Position then Mounted.Object.Position = Props.Position end\n            API.Bind = Component\n        else\n            Mounted.Bind = Bind\n            API.Options[Props.Name or Kind] = Component\n        end\n\n        table.clear(Component)\n        setmetatable(Component, {\n            __index = function(_, Key: string)\n                if Key == \"Mount\" then return Mount end\n                if Key == \"OnMount\" then return function(_, Callback) Callback() end end\n                return Mounted[Key]\n            end,\n            __newindex = function(_, Key: string, Value)\n                Mounted[Key] = Value\n            end\n        })\n\n        if Kind ~= \"Bind\" and Mounted.Color then\n            Mounted:Color(vape.GUIColor.Hue, vape.GUIColor.Sat, vape.GUIColor.Value, vape.GUIColor.Rainbow and vape.RainbowMode.Value ~= \"Retro\")\n        end\n        for _, Callback: () -> () in Callbacks do Callback() end\n        table.clear(Callbacks)\n\n        return Mounted\n    end\n\n    if Kind == \"Toggle\" then\n        Component.Default = Props.Default and true or false\n        Component.Enabled = false\n        Component.Name = Props.Name\n\n        function Component:Toggle()\n            self.Enabled = not self.Enabled\n            vape:QueueSave()\n            Props.Function(self.Enabled)\n        end\n\n        function Component:Load(Data)\n            if self.Enabled ~= (Data.Enabled or false) then self:Toggle() end\n            if self.Bind and Data.Bind then self.Bind:Load(Data.Bind) end\n        end\n\n        function Component:Save(Data)\n            Data[Props.Name] = {Enabled = self.Enabled}\n            if self.Bind then self.Bind:Save(Data[Props.Name]) end\n        end\n    elseif Kind == \"Slider\" then\n        Component.Decimal = Props.Decimal or 1\n        Component.Default = Props.Default or Props.Min\n        Component.Max = Props.Max\n        Component.Min = Props.Min\n        Component.Suffix = Props.Suffix\n        Component.Value = Props.Default or Props.Min\n\n        function Component:SetValue(Value: number, Position: number?, WasReleased: boolean?)\n            if type(Value) ~= \"number\" or Value ~= Value or Value == math.huge or Value == -math.huge then return end\n            if self.Value ~= Value or WasReleased then\n                self.Value = Value\n                vape:QueueSave()\n                Props.Function(Value, WasReleased)\n            end\n        end\n\n        function Component:Load(Data)\n            local Value = Data.Value == Data.Max and Data.Max ~= self.Max and self.Max or Data.Value\n            if type(Value) == \"number\" then Value = math.clamp(Value, self.Min, self.Max) end\n            if self.Value ~= Value then self:SetValue(Value, nil, true) end\n        end\n\n        function Component:Save(Data)\n            Data[Props.Name] = {Value = self.Value, Max = self.Max}\n        end\n    elseif Kind == \"Dropdown\" then\n        Component.Default = Props.Default or Props.List[1] or \"None\"\n        Component.Index = 0\n        Component.List = Props.List\n        Component.Value = Props.List[1] or \"None\"\n\n        function Component:SetValue(Value, IsClick: boolean?)\n            self.Value = table.find(Props.List, Value) and Value or Props.List[1] or \"None\"\n            vape:QueueSave()\n            Props.Function(self.Value, IsClick)\n        end\n\n        function Component:Change(List: {string}?)\n            Props.List = List or {}\n            if not table.find(Props.List, self.Value) then self:SetValue(self.Value) end\n        end\n\n        function Component:Load(Data)\n            if Data.Value and self.Value ~= Data.Value then self:SetValue(Data.Value) end\n        end\n\n        function Component:Save(Data)\n            Data[Props.Name] = {Value = self.Value}\n        end\n    elseif Kind == \"TextList\" then\n        Component.Default = Props.Default and table.clone(Props.Default) or {}\n        Component.List = Props.Default and table.clone(Props.Default) or {}\n        Component.ListEnabled = Props.Default and table.clone(Props.Default) or {}\n        Component.Icon = Props.Icon\n        Optional.Icon = true\n\n        function Component:ChangeValue(Value: string?)\n            if Value then\n                local Index: number? = table.find(self.List, Value)\n                if Index then\n                    table.remove(self.List, Index)\n                    local Enabled: number? = table.find(self.ListEnabled, Value)\n                    if Enabled then table.remove(self.ListEnabled, Enabled) end\n                else\n                    table.insert(self.List, Value)\n                    table.insert(self.ListEnabled, Value)\n                end\n            end\n            vape:QueueSave()\n            Props.Function(self.List)\n        end\n\n        function Component:Load(Data)\n            self.List = Data.List or {}\n            self.ListEnabled = Data.ListEnabled or {}\n            self:ChangeValue()\n        end\n\n        function Component:Save(Data)\n            Data[Props.Name] = {List = self.List, ListEnabled = self.ListEnabled}\n        end\n    elseif Kind == \"ColorSlider\" then\n        Component.Hue = Props.DefaultHue or 0.44\n        Component.Sat = Props.DefaultSat or 1\n        Component.Value = Props.DefaultValue or 1\n        Component.Opacity = Props.DefaultOpacity or 1\n        Component.Rainbow = false\n        Component.Index = 0\n\n        function Component:Toggle()\n            self.Rainbow = not self.Rainbow\n            if self.Rainbow then\n                table.insert(vape.RainbowSliders, self)\n            else\n                local Index: number? = table.find(vape.RainbowSliders, self)\n                if Index then table.remove(vape.RainbowSliders, Index) end\n            end\n            vape:QueueSave()\n        end\n\n        function Component:SetValue(Hue: number?, Sat: number?, Value: number?, Opacity: number?)\n            self.Hue = Hue or self.Hue\n            self.Sat = Sat or self.Sat\n            self.Value = Value or self.Value\n            self.Opacity = Opacity or self.Opacity\n            if not self.Rainbow then vape:QueueSave() end\n            Props.Function(self.Hue, self.Sat, self.Value, self.Opacity)\n        end\n\n        function Component:Load(Data)\n            local Hue, Sat, Value, Opacity = Data.Hue or self.Hue, Data.Sat or self.Sat, Data.Value or self.Value, Data.Opacity or self.Opacity\n            if (Data.Rainbow or false) ~= self.Rainbow then self:Toggle() end\n            if self.Hue ~= Hue or self.Sat ~= Sat or self.Value ~= Value or self.Opacity ~= Opacity then self:SetValue(Hue, Sat, Value, Opacity) end\n        end\n\n        function Component:Save(Data)\n            Data[Props.Name] = {Hue = self.Hue, Sat = self.Sat, Value = self.Value, Opacity = self.Opacity, Rainbow = self.Rainbow}\n        end\n    elseif Kind == \"Targets\" then\n        Component.Default = {\n            Players = Props.Players and true or false,\n            NPCs = Props.NPCs and true or false,\n            Invisible = Props.Invisible and true or false,\n            Walls = Props.Walls and true or false,\n            Priority = \"Players\"\n        }\n\n        local function TargetButton(Enabled: boolean, Callback: (boolean?) -> ())\n            local Button = {Enabled = Enabled, Type = \"TargetsButton\"}\n            function Button:Toggle()\n                self.Enabled = not self.Enabled\n                vape:QueueSave()\n                Callback(self.Enabled)\n            end\n            return Button\n        end\n\n        Component.Players = TargetButton(Component.Default.Players, function(Enabled) Props.Function(Enabled) end)\n        Component.NPCs = TargetButton(Component.Default.NPCs, function(Enabled) Props.Function(Enabled) end)\n        Component.Invisible = TargetButton(Component.Default.Invisible, function() Props.Function() end)\n        Component.Walls = TargetButton(Component.Default.Walls, function() Props.Function() end)\n        Component.Priority = {\n            Default = \"Players\",\n            List = {\"Players\", \"NPCs\", \"None\", \"Closest\", \"Farthest\", \"Lowest health\", \"Highest health\", \"Crosshair\"},\n            Type = \"Dropdown\",\n            Value = \"Players\"\n        }\n\n        function Component.Priority:SetValue(Value, IsClick: boolean?)\n            self.Value = table.find(self.List, Value) and Value or self.List[1] or \"None\"\n            vape:QueueSave()\n            Props.Function(self.Value, IsClick)\n        end\n\n        function Component:Load(Data)\n            if self.Players.Enabled ~= Data.Players then self.Players:Toggle() end\n            if self.NPCs.Enabled ~= Data.NPCs then self.NPCs:Toggle() end\n            if self.Invisible.Enabled ~= Data.Invisible then self.Invisible:Toggle() end\n            if self.Walls.Enabled ~= Data.Walls then self.Walls:Toggle() end\n            if Data.Priority and self.Priority.Value ~= Data.Priority then self.Priority:SetValue(Data.Priority) end\n        end\n\n        function Component:Save(Data)\n            Data.Targets = {\n                Players = self.Players.Enabled,\n                NPCs = self.NPCs.Enabled,\n                Invisible = self.Invisible.Enabled,\n                Walls = self.Walls.Enabled,\n                Priority = self.Priority.Value\n            }\n        end\n\n        if Component.Players.Enabled then Props.Function(true) end\n        if Component.NPCs.Enabled then Props.Function(true) end\n        if Component.Invisible.Enabled then Props.Function() end\n        if Component.Walls.Enabled then Props.Function() end\n    elseif Kind == \"TwoSlider\" then\n        Component.Decimal = Props.Decimal or 1\n        Component.DefaultMin = Props.DefaultMin or Props.Min\n        Component.DefaultMax = Props.DefaultMax or 10\n        Component.Max = Props.Max\n        Component.Min = Props.Min\n        Component.ValueMin = Component.DefaultMin\n        Component.ValueMax = Component.DefaultMax\n        local RandomGenerator: Random = Random.new()\n\n        function Component:GetRandomValue()\n            return RandomGenerator:NextNumber(self.ValueMin, self.ValueMax)\n        end\n\n        function Component:SetValue(IsMax: boolean, Value: number)\n            if type(Value) ~= \"number\" or Value ~= Value or Value == math.huge or Value == -math.huge then return end\n            self[IsMax and \"ValueMax\" or \"ValueMin\"] = Value\n            vape:QueueSave()\n        end\n\n        function Component:Load(Data)\n            local ValueMin: number = Data.ValueMin or Data.Value or self.ValueMin\n            local ValueMax: number = Data.ValueMax or Data.Value or self.ValueMax\n            if self.ValueMin ~= ValueMin then self:SetValue(false, ValueMin) end\n            if self.ValueMax ~= ValueMax then self:SetValue(true, ValueMax) end\n        end\n\n        function Component:Save(Data)\n            Data[Props.Name] = {ValueMin = self.ValueMin, ValueMax = self.ValueMax}\n        end\n    elseif Kind == \"TextBox\" then\n        Component.Default = Props.Default or \"\"\n        Component.Value = Component.Default\n\n        function Component:SetValue(Value: string, Enter: boolean?)\n            self.Value = Value\n            vape:QueueSave()\n            Props.Function(Enter)\n        end\n\n        function Component:Load(Data)\n            if self.Value ~= Data.Value then self:SetValue(Data.Value) end\n        end\n\n        function Component:Save(Data)\n            Data[Props.Name] = {Value = self.Value}\n        end\n    else\n        Component.Hold = Props.Hold or false\n        Component.Keys = {}\n        Component.Triggered = CreateSignal()\n\n        function Component:SetBind(Keys: {string}, Mouse: boolean?)\n            if Mouse then return Mount():SetBind(Keys, Mouse) end\n            self.Binding = nil\n            self.Keys = table.clone(Keys)\n            local Index: number? = table.find(vape.ActiveBinds, self)\n            if #Keys == 0 and Index then\n                table.remove(vape.ActiveBinds, Index)\n            elseif #Keys > 0 and not Index then\n                table.insert(vape.ActiveBinds, self)\n            end\n            vape:QueueSave()\n        end\n\n        function Component:SetVisible(Visible: boolean)\n            if Visible or #self.Keys > 0 then Mount():SetVisible(Visible) end\n        end\n\n        function Component:SetColor(Color: Color3)\n            BindColor = Color\n        end\n\n        function Component:Load(Data)\n            if Data.Hold == nil then\n                self.Hold = Props.Hold or false\n            else\n                self.Hold = Data.Hold\n            end\n            self:SetBind(Data.Keys)\n            if Data.Mobile then Mount():Load(Data) end\n        end\n\n        function Component:Save(Data)\n            Data[Props.Name or \"Bind\"] = {Keys = self.Keys, Hold = self.Hold}\n        end\n\n        function Component:Destroy()\n            local Index: number? = table.find(vape.ActiveBinds, self)\n            if Index then table.remove(vape.ActiveBinds, Index) end\n            table.clear(self.Triggered.Connections)\n        end\n    end\n\n    Component.Mount = Mount\n    Component.Deferred = true\n    setmetatable(Component, {\n        __index = function(_, Key: string)\n            if Optional[Key] then return end\n            return Mount()[Key]\n        end\n    })\n\n    if Kind == \"Toggle\" and Props.Default then Component:Toggle() end\n    if Kind == \"TextList\" and Props.Default then Component:ChangeValue() end\n    if Kind == \"Bind\" then\n        API.Bind = Component\n    else\n        API.Options[Props.Name or Kind] = Component\n    end\n\n    return Component\nend\n\nlocal BoundsCache, OldCache = {}, {}\nlocal BoundsCount: number = 0\n\nlocal function GetFontBounds(Text: string, Size: number, FontFace, Width: number?)\n    local Key = typeof(FontFace) == \"Font\" and `{Text}|{Size}|{Width or 0}|{FontFace.Family}|{FontFace.Weight.Name}|{FontFace.Style.Name}`\n    if Key then\n        local Cached: Vector2? = BoundsCache[Key] or OldCache[Key]\n        if Cached then\n            if not BoundsCache[Key] then\n                BoundsCache[Key] = Cached\n                BoundsCount += 1\n            end\n            return Cached\n        end\n    end\n\n    FontSize.Text = Text\n    FontSize.Size = Size\n    FontSize.Width = Width or math.huge\n    if typeof(FontFace) == \"Font\" then\n        FontSize.Font = FontFace\n    end\n\n    local Bounds: Vector2 = TextService:GetTextBoundsAsync(FontSize)\n\n    if Key then\n        if BoundsCount > 2048 then\n            OldCache, BoundsCache = BoundsCache, {}\n            BoundsCount = 0\n        end\n\n        BoundsCache[Key] = Bounds\n        BoundsCount += 1\n    end\n\n    return Bounds\nend\n\ndo\n    local VapeAssets: {[string]: string} = {\n        [`{vape.Directory}/assets/new/add.png`] = \"rbxassetid://121642387707174\",\n        [`{vape.Directory}/assets/new/aim.png`] = \"rbxassetid://122207028123421\",\n        [`{vape.Directory}/assets/new/allowedicon.png`] = \"rbxassetid://112336790299036\",\n        [`{vape.Directory}/assets/new/allowediconmini.png`] = \"rbxassetid://90142384730147\",\n        [`{vape.Directory}/assets/new/back.png`] = \"rbxassetid://80523803497740\",\n        [`{vape.Directory}/assets/new/backmini.png`] = \"rbxassetid://85859225495272\",\n        [`{vape.Directory}/assets/new/bind.png`] = \"rbxassetid://81399857677684\",\n        [`{vape.Directory}/assets/new/bindbkg.png`] = \"rbxassetid://101996225428926\",\n        [`{vape.Directory}/assets/new/blatant.png`] = \"rbxassetid://126929923309265\",\n        [`{vape.Directory}/assets/new/blur.png`] = \"rbxassetid://79246816170155\",\n        [`{vape.Directory}/assets/new/blurnoti.png`] = \"rbxassetid://124705876663719\",\n        [`{vape.Directory}/assets/new/cheat_switch.png`] = \"rbxassetid://99437817306124\",\n        [`{vape.Directory}/assets/new/close.png`] = \"rbxassetid://121816018671466\",\n        [`{vape.Directory}/assets/new/closemini.png`] = \"rbxassetid://108320409341289\",\n        [`{vape.Directory}/assets/new/closetiny.png`] = \"rbxassetid://71393233149714\",\n        [`{vape.Directory}/assets/new/colorpreview.png`] = \"rbxassetid://140438628568318\",\n        [`{vape.Directory}/assets/new/combat.png`] = \"rbxassetid://94762732349053\",\n        [`{vape.Directory}/assets/new/combo_display.png`] = \"rbxassetid://97746985576116\",\n        [`{vape.Directory}/assets/new/compassarrow.png`] = \"rbxassetid://100463923923900\",\