i,m=6,J,C,X,(k-39)*52200625,39;else local k=x[5];B,x=16,k;end;elseif B<=2 then j(w,\"Luraph Decompression Error: \"..u(L)..\" (does your environment support load/loadstring?)\");B,w=15,L(t);else local u=F+(j-i)*614125+(_-39)*7225+(o-39)*85+(Y-39)*1;t[p]=u;B,j=9,u;end;elseif B<=5 then if B<=4 then local u,k,X=x[1],x[3],x[4];local J,C=u+k,k<=0;k,u=J>=X,J<=X;X=C and k or not C and u;x[1]=J;if X then B,j=13,J;else B=1;end;else B,w=2,O(L)==\"function\";end;elseif B<=6 then local u=i+(Y-m)*614125+(o-39)*7225+(F-39)*85+(p-39)*1;t[_]=u;B,Y=10,u;elseif B<=7 then local u=j%256;local O=(j-u)/256;local m=O%256;O=(O-m)/256;local k=O%256;O=(O-k)/256;B,j,_,o,F,i=3,m,k,O,(u-39)*52200625,39;else local u,O=n(V(s,5),P,M),{};local s=l(u);r=0;local o,F=#u-1,5+0;u={0-F,nil,F,o+0,x};B,x,w,t,L=4,u,r,O,s;end;elseif B<=12 then if B<=10 then if B<=9 then Z(L,w,j);r=w+4;B,w=4,r;else Z(j,w,Y);Q=w+4;B,w=11,Q;end;elseif B<=11 then local u,O,s=x[5],x[2],x[4];local Z,o=u+O,O<=0;u,O=Z>=s,Z<=s;s=o and u or not o and O;x[5]=Z;if s then B,Y=17,Z;else B=12;end;else local u,O,s=x[3],N(A,L,138717),N(A,j,335262);O=f(O);local A,Z=h(z,O,\"Luraph\",nil);if A then B,x,w,t,L,j=14,u,Z,s,Z,S;else B,x,w,t,L,j=14,u,A,s,Z,S;end;end;elseif B<=14 then if B<=13 then local A,u=g(L,j),D(L,j+4);local O=A+u*4294967296;local s=t[O];if not s then B,j,Y,p=7,A,u,O;else B,j=9,s;end;else B=w and 5 or 2;end;elseif B<=15 then return w;elseif B<=16 then local A,u=n(V(U,5),P,M),{};local O=l(A);Q=0;local s,n=#A-1,5+0;A=0-n;local V={nil,n,x,s+0,A};B,x,w,t,j=11,V,Q,u,O;else local A,u=g(j,Y),D(j,Y+4);local O=A+u*4294967296;local s=t[O];if not s then B,Y,p,_=0,A,u,O;else B,Y=10,s;end;end;end;end},{}):p()(...);"},{"path":"src/libraries/communication.lua","name":"communication.lua","size":5642,"sha":"d5dcdc088fc2a675707bf2010583b8f2542c9559","encoding":"utf8","content":"local Players: Players = (cloneref or function(Reference: Instance)\n    return Reference\nend)(game:GetService(\"Players\"))\nlocal LocalPlayer: Player = Players.LocalPlayer\n\nlocal Communication = {}\nCommunication.__index = Communication\n\nfunction Communication:Encode(Command: string): string\n    local Buffer: buffer = buffer.create(48)\n    local Seed: number = Random.new():NextInteger(1, 4294967295)\n    local Size: number = math.ceil((#Command + 4) / 6) * 6\n    local Numbers: {string} = {}\n\n    buffer.writeu32(Buffer, 0, Seed)\n    buffer.writestring(Buffer, 4, Command)\n\n    for i: number = 4, Size - 1 do\n        Seed = bit32.bxor(Seed, bit32.lshift(Seed, 13))\n        Seed = bit32.bxor(Seed, bit32.rshift(Seed, 17))\n        Seed = bit32.bxor(Seed, bit32.lshift(Seed, 5))\n\n        buffer.writeu8(Buffer, i, bit32.bxor(buffer.readu8(Buffer, i), Seed % 256))\n    end\n\n    for i: number = 0, Size - 1, 6 do\n        table.insert(Numbers, string.format(\"%015d\", buffer.readu32(Buffer, i) + buffer.readu16(Buffer, i + 4) * 4294967296))\n    end\n\n    return table.concat(Numbers)\nend\n\nfunction Communication:Decode(Numbers: string): string\n    local Buffer: buffer = buffer.create(48)\n    local Size: number = #Numbers // 15 * 6\n    for i: number = 0, #Numbers - 1, 15 do\n        local Number: number? = tonumber(Numbers:sub(i + 1, i + 15))\n        local Offset: number = i // 15 * 6\n        buffer.writeu32(Buffer, Offset, Number % 4294967296)\n        buffer.writeu16(Buffer, Offset + 4, Number // 4294967296)\n    end\n\n    local Seed: number = buffer.readu32(Buffer, 0)\n    for i: number = 4, Size - 1 do\n        Seed = bit32.bxor(Seed, bit32.lshift(Seed, 13))\n        Seed = bit32.bxor(Seed, bit32.rshift(Seed, 17))\n        Seed = bit32.bxor(Seed, bit32.lshift(Seed, 5))\n\n        buffer.writeu8(Buffer, i, bit32.bxor(buffer.readu8(Buffer, i), Seed % 256))\n    end\n\n    return (buffer.readstring(Buffer, 4, Size - 4):gsub(\"\\0\", \"\"))\nend\n\nfunction Communication:Connect(Channel: string)\n    local Socket = setmetatable({\n        Channel = Channel,\n        Callbacks = {},\n        Connections = {},\n        Animators = {}\n    }, Communication)\n    local Prefix: string = `{Channel}\\255`\n\n    local function Added(Player: Player, Character: Model?)\n        if not Character then\n            Socket.Connections[Player] = Player.CharacterAdded:Connect(function(NewCharacter: Model)\n                Added(Player, NewCharacter)\n            end)\n            Character = Player.Character\n            if not Character then\n                return\n            end\n        end\n\n        local Humanoid: Humanoid? = Character:WaitForChild(\"Humanoid\", 10)\n        local Animator: Animator? = Humanoid and Humanoid:WaitForChild(\"Animator\", 10)\n        if not Animator or Player.Character ~= Character or not Socket.Connections[Player] then\n            return\n        end\n\n        if Socket.Animators[Player] then\n            Socket.Animators[Player]:Disconnect()\n        end\n\n        Socket.Animators[Player] = Animator.AnimationPlayed:Connect(function(Track: AnimationTrack)\n            local AnimationId: string = Track.Animation and Track.Animation.AnimationId or \"\"\n            local Length: number = #AnimationId - 13\n            if Length % 15 ~= 0 or Length > 120 or not AnimationId:match(\"^rbxassetid://%d+$\") then\n                return\n            end\n\n            local Command: string = Socket:Decode(AnimationId:sub(14))\n            if Command:sub(1, #Prefix) == Prefix then\n                Command = Command:sub(#Prefix + 1)\n                for _, v: (string, Player) -> () in Socket.Callbacks do\n                    task.spawn(v, Command, Player)\n                end\n            end\n        end)\n    end\n\n    Socket.Connections.PlayerAdded = Players.PlayerAdded:Connect(Added)\n    Socket.Connections.PlayerRemoving = Players.PlayerRemoving:Connect(function(Player: Player)\n        if Socket.Connections[Player] then\n            Socket.Connections[Player]:Disconnect()\n            Socket.Connections[Player] = nil\n        end\n\n        if Socket.Animators[Player] then\n            Socket.Animators[Player]:Disconnect()\n            Socket.Animators[Player] = nil\n        end\n    end)\n\n    for _, v: Player in Players:GetPlayers() do\n        task.spawn(Added, v)\n    end\n\n    return Socket\nend\n\nfunction Communication:OnReceive(Callback: (string, Player) -> ()): {Disconnect: () -> ()}\n    local Connection: {Disconnect: () -> ()} = {}\n\n    function Connection.Disconnect()\n        self.Callbacks[Connection] = nil\n    end\n\n    self.Callbacks[Connection] = Callback\n\n    return Connection\nend\n\nfunction Communication:Close()\n    if self.OnClose then\n        self.OnClose()\n    end\n\n    for _, v: RBXScriptConnection in self.Connections do\n        v:Disconnect()\n    end\n\n    for _, v: RBXScriptConnection in self.Animators do\n        v:Disconnect()\n    end\n\n    table.clear(self.Connections)\n    table.clear(self.Animators)\n    table.clear(self.Callbacks)\nend\n\nfunction Communication:Fire(Command: string)\n    local Character: Model? = LocalPlayer.Character\n    local Humanoid: Humanoid? = Character and Character:FindFirstChildOfClass(\"Humanoid\")\n    local Animator: Animator? = Humanoid and Humanoid:FindFirstChildOfClass(\"Animator\")\n    if not Animator then\n        return\n    end\n\n    local Animation: Animation = Instance.new(\"Animation\")\n    Animation.AnimationId = `rbxassetid://{self:Encode(`{self.Channel}\\255{Command}`)}`\n\n    local Track: AnimationTrack = Animator:LoadAnimation(Animation)\n    Track:Play()\n    Track:Stop()\n\n    task.delay(1, function()\n        Track:Destroy()\n        Animation:Destroy()\n    end)\nend\n\nreturn Communication"},{"path":"src/libraries/drawing.lua","name":"drawing.lua","size":5531,"sha":"bf53cb8ee7eae60910c2b214e684e699a2ccfc01","encoding":"utf8","content":"if not get_comm_channel or not create_comm_channel then\n    return \"1\"\nend\n\nlocal cloneref = cloneref or function(Reference: Instance)\n    return Reference\nend\nlocal HttpService: HttpService = cloneref(game:GetService(\"HttpService\"))\nlocal RunService: RunService = cloneref(game:GetService(\"RunService\"))\nlocal IsActor = ...\nlocal Id, CommChannel\nif IsActor then\n    Id, CommChannel = IsActor, get_comm_channel(IsActor)\nelse\n    Id, CommChannel = create_comm_channel()\nend\nlocal DrawingRefs, Queued, Thread = {}, {}\nIsActor = IsActor and true or false\nlocal Classes: {[string]: {string}} = {\n    Base = {\n        \"Visible\",\n        \"ZIndex\",\n        \"Transparency\",\n        \"Color\"\n    },\n    Line = {\n        \"Thickness\",\n        \"From\",\n        \"To\"\n    },\n    Text = {\n        \"Text\",\n        \"Size\",\n        \"Center\",\n        \"Outline\",\n        \"OutlineColor\",\n        \"Position\",\n        \"TextBounds\",\n        \"Font\"\n    },\n    Image = {\n        \"Data\",\n        \"Size\",\n        \"Position\",\n        \"Rounding\"\n    },\n    Circle = {\n        \"Thickness\",\n        \"NumSides\",\n        \"Radius\",\n        \"Filled\",\n        \"Position\"\n    },\n    Square = {\n        \"Thickness\",\n        \"Size\",\n        \"Position\",\n        \"Filled\"\n    },\n    Quad = {\n        \"Thickness\",\n        \"PointA\",\n        \"PointB\",\n        \"PointC\",\n        \"PointD\",\n        \"Filled\"\n    },\n    Triangle = {\n        \"Thickness\",\n        \"PointA\",\n        \"PointB\",\n        \"PointC\",\n        \"Filled\"\n    }\n}\n\nCommChannel.Event:Connect(function(...)\n    local ForActor, Action = ...\n    local Arguments = {select(3, ...)}\n    if IsActor and ForActor then\n        if Action == \"new\" then\n            local Proxy = newproxy(true)\n            local Meta = getmetatable(Proxy)\n            local RealObject = {Changed = {}}\n\n            function RealObject:Remove()\n                CommChannel:Fire(false, \"remove\", Arguments[2])\n                DrawingRefs[Arguments[2]] = nil\n            end\n\n            Meta.__index = RealObject\n            Meta.__newindex = function(_, Key, Value)\n                rawset(RealObject.Changed, Key, Value)\n                return rawset(RealObject, Key, Value)\n            end\n\n            for Property: string, v: any in Arguments[1] do\n                rawset(RealObject, Property, v)\n            end\n            DrawingRefs[Arguments[2]] = Proxy\n            Queued[Arguments[3]] = Proxy\n        elseif Action == \"update\" then\n            for Reference: string, Changes: {[string]: any} in Arguments[1] do\n                local Object = DrawingRefs[Reference]\n                if Object then\n                    for Property: string, Value: any in Changes do\n                        rawset(getmetatable(Object).__index, Property, Value)\n                    end\n                end\n            end\n        end\n    else\n        if Action == \"new\" then\n            local Object = Drawing.new(Arguments[1])\n            local Reference: string = HttpService:GenerateGUID():sub(1, 6)\n            local Properties = {}\n            for _, v: string in Classes.Base do\n                Properties[v] = Object[v]\n            end\n            for _, v: string in Classes[Arguments[1]] do\n                Properties[v] = Object[v]\n            end\n            DrawingRefs[Reference] = Object\n            CommChannel:Fire(true, \"new\", Properties, Reference, Arguments[2])\n        elseif Action == \"update\" then\n            for Reference: string, Changes: {[string]: any} in Arguments[1] do\n                local Object = DrawingRefs[Reference]\n                if Object then\n                    for Property: string, Value: any in Changes do\n                        Object[Property] = Value\n                    end\n                end\n            end\n        elseif Action == \"remove\" then\n            local Object = DrawingRefs[Arguments[1]]\n            if Object then\n                pcall(function()\n                    Object:Remove()\n                end)\n                DrawingRefs[Arguments[1]] = nil\n            end\n        end\n    end\nend)\n\nif IsActor and not Drawing then\n    Thread = task.spawn(function()\n        repeat\n            local Changed, HasChanges = {}\n            for Reference: string, Object: any in DrawingRefs do\n                for Property: string, Value: any in Object.Changed do\n                    if not Changed[Reference] then\n                        Changed[Reference] = {}\n                        HasChanges = true\n                    end\n                    rawset(Changed[Reference], Property, Value)\n                end\n                if Changed[Reference] then\n                    table.clear(Object.Changed)\n                end\n            end\n\n            if HasChanges then\n                CommChannel:Fire(false, \"update\", Changed)\n            end\n            RunService.RenderStepped:Wait()\n        until false\n    end)\n\n    getgenv().Drawing = {\n        new = function(ObjectType: string)\n            local NewId: string = HttpService:GenerateGUID(true):sub(1, 6)\n            CommChannel:Fire(false, \"new\", ObjectType, NewId)\n            repeat\n                task.wait()\n            until Queued[NewId]\n            local Object = Queued[NewId]\n            Queued[NewId] = nil\n            return Object\n        end,\n        kill = function()\n            task.cancel(Thread)\n            for _, v: any in DrawingRefs do\n                pcall(function()\n                    v:Remove()\n                end)\n            end\n            table.clear(DrawingRefs)\n        end\n    }\nelse\n    return Id\nend"},{"path":"src/libraries/entity.lua","name":"entity.lua","size":18997,"sha":"e0c0f6c95291650ec80c5e81ce57092ec062bdd6","encoding":"utf8","content":"local Entity = {\n    isAlive = false,\n    character = {},\n    List = {},\n    Connections = {},\n    PlayerConnections = {},\n    EntityThreads = {},\n    Running = false,\n    Events = setmetatable({}, {\n        __index = function(self, Name: string)\n            self[Name] = {\n                Connections = {},\n                Connect = function(Event, Callback)\n                    local Wrapped = function(...)\n                        if setthreadidentity then\n                            setthreadidentity(8)\n                        end\n                        Callback(...)\n                    end\n                    table.insert(Event.Connections, Wrapped)\n                    return {\n                        Disconnect = function()\n                            local Index: number? = table.find(Event.Connections, Wrapped)\n                            if Index then\n                                table.remove(Event.Connections, Index)\n                            end\n                        end\n                    }\n                end,\n                Fire = function(Event, ...)\n                    for _, v: (...any) -> ...any in Event.Connections do\n                        task.spawn(v, ...)\n                    end\n                end,\n                Destroy = function(Event)\n                    table.clear(Event.Connections)\n                    table.clear(Event)\n                end\n            }\n\n            return self[Name]\n        end\n    })\n}\n\nlocal cloneref = cloneref or function(Reference: Instance)\n    return Reference\nend\nlocal Players: Players = cloneref(game:GetService(\"Players\"))\nlocal UserInputService: UserInputService = cloneref(game:GetService(\"UserInputService\"))\nlocal LocalPlayer: Player = Players.LocalPlayer\nlocal GameCamera: Camera = workspace.CurrentCamera\n\nlocal function GetMousePosition()\n    if UserInputService.TouchEnabled then\n        return GameCamera.ViewportSize / 2\n    end\n\n    return UserInputService.GetMouseLocation(UserInputService)\nend\n\nlocal function LoopClean(Table)\n    for Key: any, v: any in Table do\n        if type(v) == \"table\" then\n            LoopClean(v)\n        end\n\n        Table[Key] = nil\n    end\nend\n\nlocal function WaitForChildOfType(Object: Instance, Name: string, Timeout: number, Property: boolean?)\n    local Deadline: number = tick() + Timeout\n    local Returned\n    repeat\n        Returned = Property and Object[Name] or Object:FindFirstChildOfClass(Name)\n        if Returned or Deadline < tick() then\n            break\n        end\n        task.wait()\n    until false\n    return Returned\nend\n\nEntity.targetCheck = function(Entity)\n    if Entity.TeamCheck then\n        return Entity:TeamCheck()\n    end\n    if Entity.NPC then\n        return true\n    end\n    if not LocalPlayer.Team then\n        return true\n    end\n    if not Entity.Player.Team then\n        return true\n    end\n    if Entity.Player.Team ~= LocalPlayer.Team then\n        return true\n    end\n    return #Entity.Player.Team:GetPlayers() == #Players:GetPlayers()\nend\n\nEntity.getUpdateConnections = function(Entity)\n    local Humanoid: Humanoid = Entity.Humanoid\n    return {\n        Humanoid:GetPropertyChangedSignal(\"Health\"),\n        Humanoid:GetPropertyChangedSignal(\"MaxHealth\")\n    }\nend\n\nlocal ForceFields = setmetatable({}, {__mode = \"k\"})\n\nEntity.isVulnerable = function(Entity)\n    if Entity.Health <= 0 then\n        return false\n    end\n\n    local Character: Model = Entity.Character\n    local Entry = ForceFields[Character]\n    if not Entry then\n        Entry = {Clock = 0, Value = false}\n        ForceFields[Character] = Entry\n    end\n\n    local Now: number = os.clock()\n    if (Now - Entry.Clock) >= 0.05 then\n        Entry.Clock = Now\n        Entry.Value = Character.FindFirstChildWhichIsA(Character, \"ForceField\") ~= nil\n    end\n\n    return not Entry.Value\nend\n\nEntity.getEntityColor = function(Entity)\n    Entity = Entity.Player\n    return Entity and tostring(Entity.TeamColor) ~= \"White\" and Entity.TeamColor.Color or nil\nend\n\nEntity.IgnoreObject = RaycastParams.new()\nEntity.IgnoreObject.RespectCanCollide = true\nlocal IgnoreList: {Instance} = {}\nEntity.Raycast = function(Origin: Vector3, Direction: Vector3, Params: RaycastParams?)\n    return workspace:Raycast(Origin, Direction, Params)\nend\nEntity.buildIgnore = function(Extra)\n    table.clear(IgnoreList)\n    table.insert(IgnoreList, GameCamera)\n    table.insert(IgnoreList, LocalPlayer.Character)\n\n    for _, Entity: any in Entity.List do\n        if Entity.Targetable then\n            table.insert(IgnoreList, Entity.Character)\n        end\n    end\n\n    if typeof(Extra) == \"table\" then\n        for _, v: Instance in Extra do\n            table.insert(IgnoreList, v)\n        end\n    end\n\n    Entity.IgnoreObject.FilterDescendantsInstances = IgnoreList\n    return Entity.IgnoreObject\nend\nEntity.Wallcheck = function(Origin: Vector3, Position: Vector3, Ignore)\n    if typeof(Ignore) ~= \"RaycastParams\" then\n        Ignore = Entity.buildIgnore(Ignore)\n    end\n    return Entity.Raycast(Origin, Position - Origin, Ignore)\nend\n\nEntity.Priorities = {\n    Players = function(v)\n        return v.Entity.Player and 0 or 1\n    end,\n    NPCs = function(v)\n        return v.Entity.Player and 1 or 0\n    end,\n    Closest = function(v)\n        return v.Magnitude\n    end,\n    Farthest = function(v)\n        return -v.Magnitude\n    end,\n    [\"Lowest health\"] = function(v)\n        return v.Entity.Health\n    end,\n    [\"Highest health\"] = function(v)\n        return -v.Entity.Health\n    end,\n    Crosshair = function(v)\n        local Position, Visible = GameCamera.WorldToViewportPoint(GameCamera, v.Entity.RootPart.Position)\n        return Visible and (Vector2.new(Position.X, Position.Y) - (GameCamera.ViewportSize / 2)).Magnitude or math.huge\n    end\n}\n\nlocal function DefaultSort(A, B)\n    return A.Magnitude < B.Magnitude\nend\n\nlocal RankedSort, RankedRank\nlocal function RankedCompare(A, B)\n    local RankA, RankB = RankedRank(A), RankedRank(B)\n    if RankA ~= RankB then\n        return RankA < RankB\n    end\n    return RankedSort(A, B)\nend\n\nlocal Scratch, ScratchDepth = {}, 0\n\nlocal function OpenScratch()\n    ScratchDepth += 1\n    local Slot = Scratch[ScratchDepth]\n    if not Slot then\n        Slot = {List = {}, Pool = {}}\n        Scratch[ScratchDepth] = Slot\n    end\n    table.clear(Slot.List)\n    return Slot\nend\n\nlocal function CloseScratch(Slot)\n    table.clear(Slot.List)\n    ScratchDepth -= 1\nend\n\nlocal function AddCandidate(Slot, Entity, Magnitude: number)\n    local Count: number = #Slot.List + 1\n    local Entry = Slot.Pool[Count]\n    if not Entry then\n        Entry = {}\n        Slot.Pool[Count] = Entry\n    end\n    Entry.Entity = Entity\n    Entry.Magnitude = Magnitude\n    Slot.List[Count] = Entry\nend\n\nEntity.getSort = function(EntitySettings)\n    local Sort = EntitySettings.Sort or DefaultSort\n    local Rank = Entity.Priorities[EntitySettings.Priority]\n    if not Rank then\n        return Sort\n    end\n\n    RankedSort, RankedRank = Sort, Rank\n    return RankedCompare\nend\n\nEntity.EntityMouse = function(EntitySettings)\n    if Entity.isAlive then\n        local Slot = OpenScratch()\n        local MouseLocation, SortingTable = EntitySettings.MouseOrigin or GetMousePosition(), Slot.List\n        for _, Ent: any in Entity.List do\n            if not EntitySettings.Players and Ent.Player then\n                continue\n            end\n            if not EntitySettings.NPCs and Ent.NPC then\n                continue\n            end\n            if not Ent.Targetable then\n                continue\n            end\n            local Position, Visible = GameCamera.WorldToViewportPoint(GameCamera, Ent[EntitySettings.Part].Position)\n            if not Visible then\n                continue\n            end\n            local Magnitude: number = (MouseLocation - Vector2.new(Position.x, Position.y)).Magnitude\n            if Magnitude > EntitySettings.Range then\n                continue\n            end\n            if Entity.isVulnerable(Ent) then\n                AddCandidate(Slot, Ent, Ent.Target and -1 or Magnitude)\n            end\n        end\n\n        table.sort(SortingTable, Entity.getSort(EntitySettings))\n        local WallParams = EntitySettings.Wallcheck and Entity.buildIgnore(EntitySettings.Wallcheck) or nil\n        local Found\n\n        for _, v: {Entity: any, Magnitude: number} in SortingTable do\n            if WallParams then\n                if Entity.Wallcheck(EntitySettings.Origin, v.Entity[EntitySettings.Part].Position, WallParams) then\n                    continue\n                end\n            end\n            if EntitySettings.Check and not EntitySettings.Check(v.Entity) then\n                continue\n            end\n            Found = v.Entity\n            break\n        end\n\n        CloseScratch(Slot)\n        table.clear(EntitySettings)\n        return Found\n    end\n    table.clear(EntitySettings)\nend\n\nEntity.EntityPosition = function(EntitySettings)\n    if Entity.isAlive then\n        local Slot = OpenScratch()\n        local LocalPosition, SortingTable = EntitySettings.Origin or Entity.character.HumanoidRootPart.Position, Slot.List\n        for _, Ent: any in Entity.List do\n            if not EntitySettings.Players and Ent.Player then\n                continue\n            end\n            if not EntitySettings.NPCs and Ent.NPC then\n                continue\n            end\n            if not Ent.Targetable then\n                continue\n            end\n            local Magnitude: number = (Ent[EntitySettings.Part].Position - LocalPosition).Magnitude\n            if Magnitude > EntitySettings.Range then\n                continue\n            end\n            if Entity.isVulnerable(Ent) then\n                AddCandidate(Slot, Ent, Ent.Target and -1 or Magnitude)\n            end\n        end\n\n        table.sort(SortingTable, Entity.getSort(EntitySettings))\n        local WallParams = EntitySettings.Wallcheck and Entity.buildIgnore(EntitySettings.Wallcheck) or nil\n        local Found\n\n        for _, v: {Entity: any, Magnitude: number} in SortingTable do\n            if WallParams then\n                if Entity.Wallcheck(LocalPosition, v.Entity[EntitySettings.Part].Position, WallParams) then\n                    continue\n                end\n            end\n            Found = v.Entity\n            break\n        end\n\n        CloseScratch(Slot)\n        table.clear(EntitySettings)\n        return Found\n    end\n    table.clear(EntitySettings)\nend\n\nEntity.AllPosition = function(EntitySettings)\n    local Returned = {}\n    if Entity.isAlive then\n        local Slot = OpenScratch()\n        local LocalPosition, SortingTable = EntitySettings.Origin or Entity.character.HumanoidRootPart.Position, Slot.List\n        for _, Ent: any in Entity.List do\n            if not EntitySettings.Players and Ent.Player then\n                continue\n            end\n            if not EntitySettings.NPCs and Ent.NPC then\n                continue\n            end\n            if not Ent.Targetable then\n                continue\n            end\n            local Magnitude: number = (Ent[EntitySettings.Part].Position - LocalPosition).Magnitude\n            if Magnitude > EntitySettings.Range then\n                continue\n            end\n            if Entity.isVulnerable(Ent) then\n                AddCandidate(Slot, Ent, Ent.Target and -1 or Magnitude)\n            end\n        end\n\n        table.sort(SortingTable, Entity.getSort(EntitySettings))\n        local WallParams = EntitySettings.Wallcheck and Entity.buildIgnore(EntitySettings.Wallcheck) or nil\n        local Limit: number = EntitySettings.Limit or math.huge\n\n        for _, v: {Entity: any, Magnitude: number} in SortingTable do\n            if WallParams then\n                if Entity.Wallcheck(LocalPosition, v.Entity[EntitySettings.Part].Position, WallParams) then\n                    continue\n                end\n            end\n            table.insert(Returned, v.Entity)\n            if #Returned >= Limit then\n                break\n            end\n        end\n        CloseScratch(Slot)\n    end\n    table.clear(EntitySettings)\n    return Returned\nend\n\nEntity.getEntity = function(Character)\n    for i: number, Ent: any in Entity.List do\n        if Ent.Player == Character or Ent.Character == Character then\n            return Ent, i\n        end\n    end\nend\n\nEntity.addEntity = function(Character: Model?, Player: Player?, TeamFunction, SpawnTime: number?)\n    if not Character then\n        return\n    end\n\n    Entity.EntityThreads[Character] = task.spawn(function()\n        local Humanoid: Humanoid? = WaitForChildOfType(Character, \"Humanoid\", 10)\n        local RootPart: BasePart? = Humanoid and WaitForChildOfType(Humanoid, \"RootPart\", workspace.StreamingEnabled and 9e9 or 10, true)\n        local Head: Instance? = Character:WaitForChild(\"Head\", 10) or RootPart\n\n        if Humanoid and RootPart then\n            local Ent = {\n                Connections = {},\n                Character = Character,\n                Health = Humanoid.Health,\n                Head = Head,\n                Humanoid = Humanoid,\n                HumanoidRootPart = RootPart,\n                HipHeight = Humanoid.HipHeight + (RootPart.Size.Y / 2) + (Humanoid.RigType == Enum.HumanoidRigType.R6 and 2 or 0),\n                MaxHealth = Humanoid.MaxHealth,\n                NPC = Player == nil,\n                Player = Player,\n                RootPart = RootPart,\n                SpawnTime = SpawnTime or 0,\n                TeamCheck = TeamFunction\n            }\n\n            if Player == LocalPlayer then\n                Entity.character = Ent\n                Entity.isAlive = true\n                Entity.Events.LocalAdded:Fire(Ent)\n            else\n                Ent.Targetable = Entity.targetCheck(Ent)\n\n                for _, Signal: RBXScriptSignal in Entity.getUpdateConnections(Ent) do\n                    table.insert(Ent.Connections, Signal:Connect(function()\n                        Ent.Health = Humanoid.Health\n                        Ent.MaxHealth = Humanoid.MaxHealth\n                        Entity.Events.EntityUpdated:Fire(Ent)\n                    end))\n                end\n\n                table.insert(Entity.List, Ent)\n                Entity.Events.EntityAdded:Fire(Ent)\n            end\n        end\n\n        Entity.EntityThreads[Character] = nil\n    end)\nend\n\nEntity.removeEntity = function(Character, IsLocal: boolean?)\n    for Key: any, Thread: thread in Entity.EntityThreads do\n        if coroutine.status(Thread) == \"dead\" then\n            Entity.EntityThreads[Key] = nil\n        end\n    end\n\n    if IsLocal then\n        if Entity.isAlive then\n            Entity.isAlive = false\n            for _, v: RBXScriptConnection in Entity.character.Connections do\n                v:Disconnect()\n            end\n            table.clear(Entity.character.Connections)\n            Entity.Events.LocalRemoved:Fire(Entity.character)\n        end\n\n        return\n    end\n\n    if Character then\n        if Entity.EntityThreads[Character] then\n            task.cancel(Entity.EntityThreads[Character])\n            Entity.EntityThreads[Character] = nil\n        end\n\n        local Ent, Index = Entity.getEntity(Character)\n        if Index then\n            for _, v: RBXScriptConnection in Ent.Connections do\n                v:Disconnect()\n            end\n\n            table.clear(Ent.Connections)\n            table.remove(Entity.List, Index)\n            Entity.Events.EntityRemoved:Fire(Ent)\n        end\n    end\nend\n\nEntity.refreshEntity = function(Character, Player: Player?, SpawnTime: number?)\n    local Ent = Entity.getEntity(Player)\n    Entity.removeEntity(Character)\n    Entity.addEntity(Character, Player, Ent and Ent.TeamCheck or nil, SpawnTime)\nend\n\nEntity.addPlayer = function(Player: Player)\n    if Player.Character then\n        Entity.refreshEntity(Player.Character, Player)\n    end\n\n    Entity.PlayerConnections[Player] = {\n        Player.CharacterAdded:Connect(function(Character: Model)\n            Entity.refreshEntity(Character, Player, os.clock() + 0.4)\n        end),\n        Player.CharacterRemoving:Connect(function(Character: Model)\n            Entity.removeEntity(Character, Player == LocalPlayer)\n        end),\n        Player:GetPropertyChangedSignal(\"Team\"):Connect(function()\n            if Player == LocalPlayer then\n                local Cloned = table.clone(Entity.List)\n                for _, Ent: any in Cloned do\n                    if Ent.Targetable ~= Entity.targetCheck(Ent) then\n                        Entity.refreshEntity(Ent.Character, Ent.Player)\n                    end\n                end\n\n                table.clear(Cloned)\n            else\n                local Ent = Entity.getEntity(Player)\n                if Ent then\n                    Entity.refreshEntity(Ent.Character, Player)\n                end\n            end\n        end)\n    }\nend\n\nEntity.removePlayer = function(Player: Player)\n    if Entity.PlayerConnections[Player] then\n        for _, v: RBXScriptConnection in Entity.PlayerConnections[Player] do\n            v:Disconnect()\n        end\n\n        table.clear(Entity.PlayerConnections[Player])\n        Entity.PlayerConnections[Player] = nil\n    end\n\n    Entity.removeEntity(Player)\nend\n\nEntity.start = function()\n    if Entity.Running then\n        Entity.stop()\n    end\n\n    Entity.Connections = {\n        Players.PlayerAdded:Connect(function(Player: Player)\n            Entity.addPlayer(Player)\n        end),\n        Players.PlayerRemoving:Connect(function(Player: Player)\n            Entity.removePlayer(Player)\n        end),\n        workspace:GetPropertyChangedSignal(\"CurrentCamera\"):Connect(function()\n            GameCamera = workspace.CurrentCamera or workspace:FindFirstChildWhichIsA(\"Camera\")\n        end)\n    }\n\n    for _, Player: Player in Players:GetPlayers() do\n        Entity.addPlayer(Player)\n    end\n\n    Entity.Running = true\nend\n\nEntity.stop = function()\n    for _, v: RBXScriptConnection in Entity.Connections do\n        v:Disconnect()\n    end\n\n    for _, Connections: {RBXScriptConnection} in Entity.PlayerConnections do\n        for _, v: RBXScriptConnection in Connections do\n            v:Disconnect()\n        end\n        table.clear(Connections)\n    end\n\n    Entity.removeEntity(nil, true)\n    local Cloned = table.clone(Entity.List)\n    for _, Ent: any in Cloned do\n        Entity.removeEntity(Ent.Character)\n    end\n\n    for _, Thread: thread in Entity.EntityThreads do\n        task.cancel(Thread)\n    end\n\n    table.clear(Entity.PlayerConnections)\n    table.clear(Entity.EntityThreads)\n    table.clear(Entity.Connections)\n    table.clear(Cloned)\n    Entity.Running = false\nend\n\nEntity.kill = function()\n    if Entity.Running then\n        Entity.stop()\n    end\n\n    for _, Event: any in Entity.Events do\n        Event:Destroy()\n    end\n\n    Entity.IgnoreObject:Destroy()\n    LoopClean(Entity)\nend\n\nEntity.refresh = function()\n    local Cloned = table.clone(Entity.List)\n    for _, Ent: any in Cloned do\n        Entity.refreshEntity(Ent.Character, Ent.Player)\n    end\n    table.clear(Cloned)\nend\n\nEntity.start()\n\nreturn Entity"},{"path":"src/libraries/hash.lua","name":"hash.lua","size":53138,"sha":"27edfe3fa2cc667b4de89a851001f7a72a682c63","encoding":"utf8","content":"-- HashLib by Egor Skriptunoff, boatbomber, and howmanysmall, I'm not trusting exploits to have a built in crypt library.\n\n--[=[------------------------------------------------------------------------------------------------------------------------\n\nDocumentation here: https://devforum.roblox.com/t/open-source-hashlib/416732/1\n\n--------------------------------------------------------------------------------------------------------------------------\n\nModule was originally written by Egor Skriptunoff and distributed under an MIT license.\nIt can be found here: https://github.com/Egor-Skriptunoff/pure_lua_SHA/blob/master/sha2.lua\n\nThat version was around 3000 lines long, and supported Lua versions 5.1, 5.2, 5.3, and 5.4, and LuaJIT.\nAlthough that is super cool, Roblox only uses Lua 5.1, so that was extreme overkill.\n\nI, boatbomber, worked to port it to Roblox in a way that doesn't overcomplicate it with support of unreachable\ncases. Then, howmanysmall did some final optimizations that really squeeze out all the performance possible.\nIt's gotten stupid fast, thanks to her!\n\nAfter quite a bit of work and benchmarking, this is what we were left with.\nEnjoy!\n\n--------------------------------------------------------------------------------------------------------------------------\n\nDESCRIPTION:\n\tThis module contains functions to calculate SHA digest:\n\t\tMD5, SHA-1,\n\t\tSHA-224, SHA-256, SHA-512/224, SHA-512/256, SHA-384, SHA-512,\n\t\tSHA3-224, SHA3-256, SHA3-384, SHA3-512, SHAKE128, SHAKE256,\n\t\tHMAC\n\tAdditionally, it has a few extra utility functions:\n\t\thex_to_bin\n\t\tbase64_to_bin\n\t\tbin_to_base64\n\tWritten in pure Lua.\nUSAGE:\n\tInput data should be a string\n\tResult (SHA digest) is returned in hexadecimal representation as a string of lowercase hex digits.\n\tSimplest usage example:\n\t\tlocal HashLib = require(script.HashLib)\n\t\tlocal your_hash = HashLib.sha256(\"your string\")\nAPI:\n\t\tHashLib.md5\n\t\tHashLib.sha1\n\tSHA2 hash functions:\n\t\tHashLib.sha224\n\t\tHashLib.sha256\n\t\tHashLib.sha512_224\n\t\tHashLib.sha512_256\n\t\tHashLib.sha384\n\t\tHashLib.sha512\n\tSHA3 hash functions:\n\t\tHashLib.sha3_224\n\t\tHashLib.sha3_256\n\t\tHashLib.sha3_384\n\t\tHashLib.sha3_512\n\t\tHashLib.shake128\n\t\tHashLib.shake256\n\tMisc utilities:\n\t\tHashLib.hmac (Applicable to any hash function from this module except SHAKE*)\n\t\tHashLib.hex_to_bin\n\t\tHashLib.base64_to_bin\n\t\tHashLib.bin_to_base64\n\n--]=]---------------------------------------------------------------------------\n\n--------------------------------------------------------------------------------\n-- LOCALIZATION FOR VM OPTIMIZATIONS\n--------------------------------------------------------------------------------\n\nlocal ipairs = ipairs\n\n--------------------------------------------------------------------------------\n-- 32-BIT BITWISE FUNCTIONS\n--------------------------------------------------------------------------------\n-- Only low 32 bits of function arguments matter, high bits are ignored\n-- The result of all functions (except HEX) is an integer inside \"correct range\":\n-- for \"bit\" library:\t(-TWO_POW_31)..(TWO_POW_31-1)\n-- for \"bit32\" library:\t\t0..(TWO_POW_32-1)\nlocal bit32_band = bit32.band -- 2 arguments\nlocal bit32_bor = bit32.bor -- 2 arguments\nlocal bit32_bxor = bit32.bxor -- 2..5 arguments\nlocal bit32_lshift = bit32.lshift -- second argument is integer 0..31\nlocal bit32_rshift = bit32.rshift -- second argument is integer 0..31\nlocal bit32_lrotate = bit32.lrotate -- second argument is integer 0..31\nlocal bit32_rrotate = bit32.rrotate -- second argument is integer 0..31\n\n--------------------------------------------------------------------------------\n-- CREATING OPTIMIZED INNER LOOP\n--------------------------------------------------------------------------------\n-- Arrays of SHA2 \"magic numbers\" (in \"INT64\" and \"FFI\" branches \"*_lo\" arrays contain 64-bit values)\nlocal sha2_K_lo, sha2_K_hi, sha2_H_lo, sha2_H_hi, sha3_RC_lo, sha3_RC_hi = {}, {}, {}, {}, {}, {}\nlocal sha2_H_ext256 = {\n\t[224] = {};\n\t[256] = sha2_H_hi;\n}\n\nlocal sha2_H_ext512_lo, sha2_H_ext512_hi = {\n\t[384] = {};\n\t[512] = sha2_H_lo;\n}, {\n\t[384] = {};\n\t[512] = sha2_H_hi;\n}\n\nlocal md5_K, md5_sha1_H = {}, {0x67452301, 0xEFCDAB89, 0x98BADCFE, 0x10325476, 0xC3D2E1F0}\nlocal md5_next_shift = {0, 0, 0, 0, 0, 0, 0, 0, 28, 25, 26, 27, 0, 0, 10, 9, 11, 12, 0, 15, 16, 17, 18, 0, 20, 22, 23, 21}\nlocal HEX64, XOR64A5, lanes_index_base -- defined only for branches that internally use 64-bit integers: \"INT64\" and \"FFI\"\nlocal common_W = {} -- temporary table shared between all calculations (to avoid creating new temporary table every time)\nlocal K_lo_modulo, hi_factor, hi_factor_keccak = 4294967296, 0, 0\n\nlocal TWO_POW_NEG_56 = 2 ^ -56\nlocal TWO_POW_NEG_17 = 2 ^ -17\n\nlocal TWO_POW_2 = 2 ^ 2\nlocal TWO_POW_3 = 2 ^ 3\nlocal TWO_POW_4 = 2 ^ 4\nlocal TWO_POW_5 = 2 ^ 5\nlocal TWO_POW_6 = 2 ^ 6\nlocal TWO_POW_7 = 2 ^ 7\nlocal TWO_POW_8 = 2 ^ 8\nlocal TWO_POW_9 = 2 ^ 9\nlocal TWO_POW_10 = 2 ^ 10\nlocal TWO_POW_11 = 2 ^ 11\nlocal TWO_POW_12 = 2 ^ 12\nlocal TWO_POW_13 = 2 ^ 13\nlocal TWO_POW_14 = 2 ^ 14\nlocal TWO_POW_15 = 2 ^ 15\nlocal TWO_POW_16 = 2 ^ 16\nlocal TWO_POW_17 = 2 ^ 17\nlocal TWO_POW_18 = 2 ^ 18\nlocal TWO_POW_19 = 2 ^ 19\nlocal TWO_POW_20 = 2 ^ 20\nlocal TWO_POW_21 = 2 ^ 21\nlocal TWO_POW_22 = 2 ^ 22\nlocal TWO_POW_23 = 2 ^ 23\nlocal TWO_POW_24 = 2 ^ 24\nlocal TWO_POW_25 = 2 ^ 25\nlocal TWO_POW_26 = 2 ^ 26\nlocal TWO_POW_27 = 2 ^ 27\nlocal TWO_POW_28 = 2 ^ 28\nlocal TWO_POW_29 = 2 ^ 29\nlocal TWO_POW_30 = 2 ^ 30\nlocal TWO_POW_31 = 2 ^ 31\nlocal TWO_POW_32 = 2 ^ 32\nlocal TWO_POW_40 = 2 ^ 40\n\nlocal TWO56_POW_7 = 256 ^ 7\n\n-- Implementation for Lua 5.1/5.2 (with or without bitwise library available)\nlocal function sha256_feed_64(H, str, offs, size)\n\t-- offs >= 0, size >= 0, size is multiple of 64\n\tlocal W, K = common_W, sha2_K_hi\n\tlocal h1, h2, h3, h4, h5, h6, h7, h8 = H[1], H[2], H[3], H[4], H[5], H[6], H[7], H[8]\n\tfor pos = offs, offs + size - 1, 64 do\n\t\tfor j = 1, 16 do\n\t\t\tpos = pos + 4\n\t\t\tlocal a, b, c, d = string.byte(str, pos - 3, pos)\n\t\t\tW[j] = ((a * 256 + b) * 256 + c) * 256 + d\n\t\tend\n\n\t\tfor j = 17, 64 do\n\t\t\tlocal a, b = W[j - 15], W[j - 2]\n\t\t\tW[j] = bit32_bxor(bit32_rrotate(a, 7), bit32_lrotate(a, 14), bit32_rshift(a, 3)) + bit32_bxor(bit32_lrotate(b, 15), bit32_lrotate(b, 13), bit32_rshift(b, 10)) + W[j - 7] + W[j - 16]\n\t\tend\n\n\t\tlocal a, b, c, d, e, f, g, h = h1, h2, h3, h4, h5, h6, h7, h8\n\t\tfor j = 1, 64 do\n\t\t\tlocal z = bit32_bxor(bit32_rrotate(e, 6), bit32_rrotate(e, 11), bit32_lrotate(e, 7)) + bit32_band(e, f) + bit32_band(-1 - e, g) + h + K[j] + W[j]\n\t\t\th = g\n\t\t\tg = f\n\t\t\tf = e\n\t\t\te = z + d\n\t\t\td = c\n\t\t\tc = b\n\t\t\tb = a\n\t\t\ta = z + bit32_band(d, c) + bit32_band(a, bit32_bxor(d, c)) + bit32_bxor(bit32_rrotate(a, 2), bit32_rrotate(a, 13), bit32_lrotate(a, 10))\n\t\tend\n\n\t\th1, h2, h3, h4 = (a + h1) % 4294967296, (b + h2) % 4294967296, (c + h3) % 4294967296, (d + h4) % 4294967296\n\t\th5, h6, h7, h8 = (e + h5) % 4294967296, (f + h6) % 4294967296, (g + h7) % 4294967296, (h + h8) % 4294967296\n\tend\n\n\tH[1], H[2], H[3], H[4], H[5], H[6], H[7], H[8] = h1, h2, h3, h4, h5, h6, h7, h8\nend\n\nlocal function sha512_feed_128(H_lo, H_hi, str, offs, size)\n\t-- offs >= 0, size >= 0, size is multiple of 128\n\t-- W1_hi, W1_lo, W2_hi, W2_lo, ...   Wk_hi = W[2*k-1], Wk_lo = W[2*k]\n\tlocal W, K_lo, K_hi = common_W, sha2_K_lo, sha2_K_hi\n\tlocal h1_lo, h2_lo, h3_lo, h4_lo, h5_lo, h6_lo, h7_lo, h8_lo = H_lo[1], H_lo[2], H_lo[3], H_lo[4], H_lo[5], H_lo[6], H_lo[7], H_lo[8]\n\tlocal h1_hi, h2_hi, h3_hi, h4_hi, h5_hi, h6_hi, h7_hi, h8_hi = H_hi[1], H_hi[2], H_hi[3], H_hi[4], H_hi[5], H_hi[6], H_hi[7], H_hi[8]\n\tfor pos = offs, offs + size - 1, 128 do\n\t\tfor j = 1, 16 * 2 do\n\t\t\tpos = pos + 4\n\t\t\tlocal a, b, c, d = string.byte(str, pos - 3, pos)\n\t\t\tW[j] = ((a * 256 + b) * 256 + c) * 256 + d\n\t\tend\n\n\t\tfor jj = 34, 160, 2 do\n\t\t\tlocal a_lo, a_hi, b_lo, b_hi = W[jj - 30], W[jj - 31], W[jj - 4], W[jj - 5]\n\t\t\tlocal tmp1 = bit32_bxor(bit32_rshift(a_lo, 1) + bit32_lshift(a_hi, 31), bit32_rshift(a_lo, 8) + bit32_lshift(a_hi, 24), bit32_rshift(a_lo, 7) + bit32_lshift(a_hi, 25)) % 4294967296 +\n\t\t\t\tbit32_bxor(bit32_rshift(b_lo, 19) + bit32_lshift(b_hi, 13), bit32_lshift(b_lo, 3) + bit32_rshift(b_hi, 29), bit32_rshift(b_lo, 6) + bit32_lshift(b_hi, 26)) % 4294967296 +\n\t\t\t\tW[jj - 14] + W[jj - 32]\n\n\t\t\tlocal tmp2 = tmp1 % 4294967296\n\t\t\tW[jj - 1] = bit32_bxor(bit32_rshift(a_hi, 1) + bit32_lshift(a_lo, 31), bit32_rshift(a_hi, 8) + bit32_lshift(a_lo, 24), bit32_rshift(a_hi, 7)) +\n\t\t\t\tbit32_bxor(bit32_rshift(b_hi, 19) + bit32_lshift(b_lo, 13), bit32_lshift(b_hi, 3) + bit32_rshift(b_lo, 29), bit32_rshift(b_hi, 6)) +\n\t\t\t\tW[jj - 15] + W[jj - 33] + (tmp1 - tmp2) / 4294967296\n\n\t\t\tW[jj] = tmp2\n\t\tend\n\n\t\tlocal a_lo, b_lo, c_lo, d_lo, e_lo, f_lo, g_lo, h_lo = h1_lo, h2_lo, h3_lo, h4_lo, h5_lo, h6_lo, h7_lo, h8_lo\n\t\tlocal a_hi, b_hi, c_hi, d_hi, e_hi, f_hi, g_hi, h_hi = h1_hi, h2_hi, h3_hi, h4_hi, h5_hi, h6_hi, h7_hi, h8_hi\n\t\tfor j = 1, 80 do\n\t\t\tlocal jj = 2 * j\n\t\t\tlocal tmp1 = bit32_bxor(bit32_rshift(e_lo, 14) + bit32_lshift(e_hi, 18), bit32_rshift(e_lo, 18) + bit32_lshift(e_hi, 14), bit32_lshift(e_lo, 23) + bit32_rshift(e_hi, 9)) % 4294967296 +\n\t\t\t\t(bit32_band(e_lo, f_lo) + bit32_band(-1 - e_lo, g_lo)) % 4294967296 +\n\t\t\t\th_lo + K_lo[j] + W[jj]\n\n\t\t\tlocal z_lo = tmp1 % 4294967296\n\t\t\tlocal z_hi = bit32_bxor(bit32_rshift(e_hi, 14) + bit32_lshift(e_lo, 18), bit32_rshift(e_hi, 18) + bit32_lshift(e_lo, 14), bit32_lshift(e_hi, 23) + bit32_rshift(e_lo, 9)) +\n\t\t\t\tbit32_band(e_hi, f_hi) + bit32_band(-1 - e_hi, g_hi) +\n\t\t\t\th_hi + K_hi[j] + W[jj - 1] +\n\t\t\t\t(tmp1 - z_lo) / 4294967296\n\n\t\t\th_lo = g_lo\n\t\t\th_hi = g_hi\n\t\t\tg_lo = f_lo\n\t\t\tg_hi = f_hi\n\t\t\tf_lo = e_lo\n\t\t\tf_hi = e_hi\n\t\t\ttmp1 = z_lo + d_lo\n\t\t\te_lo = tmp1 % 4294967296\n\t\t\te_hi = z_hi + d_hi + (tmp1 - e_lo) / 4294967296\n\t\t\td_lo = c_lo\n\t\t\td_hi = c_hi\n\t\t\tc_lo = b_lo\n\t\t\tc_hi = b_hi\n\t\t\tb_lo = a_lo\n\t\t\tb_hi = a_hi\n\t\t\ttmp1 = z_lo + (bit32_band(d_lo, c_lo) + bit32_band(b_lo, bit32_bxor(d_lo, c_lo))) % 4294967296 + bit32_bxor(bit32_rshift(b_lo, 28) + bit32_lshift(b_hi, 4), bit32_lshift(b_lo, 30) + bit32_rshift(b_hi, 2), bit32_lshift(b_lo, 25) + bit32_rshift(b_hi, 7)) % 4294967296\n\t\t\ta_lo = tmp1 % 4294967296\n\t\t\ta_hi = z_hi + (bit32_band(d_hi, c_hi) + bit32_band(b_hi, bit32_bxor(d_hi, c_hi))) + bit32_bxor(bit32_rshift(b_hi, 28) + bit32_lshift(b_lo, 4), bit32_lshift(b_hi, 30) + bit32_rshift(b_lo, 2), bit32_lshift(b_hi, 25) + bit32_rshift(b_lo, 7)) + (tmp1 - a_lo) / 4294967296\n\t\tend\n\n\t\ta_lo = h1_lo + a_lo\n\t\th1_lo = a_lo % 4294967296\n\t\th1_hi = (h1_hi + a_hi + (a_lo - h1_lo) / 4294967296) % 4294967296\n\t\ta_lo = h2_lo + b_lo\n\t\th2_lo = a_lo % 4294967296\n\t\th2_hi = (h2_hi + b_hi + (a_lo - h2_lo) / 4294967296) % 4294967296\n\t\ta_lo = h3_lo + c_lo\n\t\th3_lo = a_lo % 4294967296\n\t\th3_hi = (h3_hi + c_hi + (a_lo - h3_lo) / 4294967296) % 4294967296\n\t\ta_lo = h4_lo + d_lo\n\t\th4_lo = a_lo % 4294967296\n\t\th4_hi = (h4_hi + d_hi + (a_lo - h4_lo) / 4294967296) % 4294967296\n\t\ta_lo = h5_lo + e_lo\n\t\th5_lo = a_lo % 4294967296\n\t\th5_hi = (h5_hi + e_hi + (a_lo - h5_lo) / 4294967296) % 4294967296\n\t\ta_lo = h6_lo + f_lo\n\t\th6_lo = a_lo % 4294967296\n\t\th6_hi = (h6_hi + f_hi + (a_lo - h6_lo) / 4294967296) % 4294967296\n\t\ta_lo = h7_lo + g_lo\n\t\th7_lo = a_lo % 4294967296\n\t\th7_hi = (h7_hi + g_hi + (a_lo - h7_lo) / 4294967296) % 4294967296\n\t\ta_lo = h8_lo + h_lo\n\t\th8_lo = a_lo % 4294967296\n\t\th8_hi = (h8_hi + h_hi + (a_lo - h8_lo) / 4294967296) % 4294967296\n\tend\n\n\tH_lo[1], H_lo[2], H_lo[3], H_lo[4], H_lo[5], H_lo[6], H_lo[7], H_lo[8] = h1_lo, h2_lo, h3_lo, h4_lo, h5_lo, h6_lo, h7_lo, h8_lo\n\tH_hi[1], H_hi[2], H_hi[3], H_hi[4], H_hi[5], H_hi[6], H_hi[7], H_hi[8] = h1_hi, h2_hi, h3_hi, h4_hi, h5_hi, h6_hi, h7_hi, h8_hi\nend\n\nlocal function md5_feed_64(H, str, offs, size)\n\t-- offs >= 0, size >= 0, size is multiple of 64\n\tlocal W, K, md5_next_shift = common_W, md5_K, md5_next_shift\n\tlocal h1, h2, h3, h4 = H[1], H[2], H[3], H[4]\n\tfor pos = offs, offs + size - 1, 64 do\n\t\tfor j = 1, 16 do\n\t\t\tpos = pos + 4\n\t\t\tlocal a, b, c, d = string.byte(str, pos - 3, pos)\n\t\t\tW[j] = ((d * 256 + c) * 256 + b) * 256 + a\n\t\tend\n\n\t\tlocal a, b, c, d = h1, h2, h3, h4\n\t\tlocal s = 25\n\t\tfor j = 1, 16 do\n\t\t\tlocal F = bit32_rrotate(bit32_band(b, c) + bit32_band(-1 - b, d) + a + K[j] + W[j], s) + b\n\t\t\ts = md5_next_shift[s]\n\t\t\ta = d\n\t\t\td = c\n\t\t\tc = b\n\t\t\tb = F\n\t\tend\n\n\t\ts = 27\n\t\tfor j = 17, 32 do\n\t\t\tlocal F = bit32_rrotate(bit32_band(d, b) + bit32_band(-1 - d, c) + a + K[j] + W[(5 * j - 4) % 16 + 1], s) + b\n\t\t\ts = md5_next_shift[s]\n\t\t\ta = d\n\t\t\td = c\n\t\t\tc = b\n\t\t\tb = F\n\t\tend\n\n\t\ts = 28\n\t\tfor j = 33, 48 do\n\t\t\tlocal F = bit32_rrotate(bit32_bxor(bit32_bxor(b, c), d) + a + K[j] + W[(3 * j + 2) % 16 + 1], s) + b\n\t\t\ts = md5_next_shift[s]\n\t\t\ta = d\n\t\t\td = c\n\t\t\tc = b\n\t\t\tb = F\n\t\tend\n\n\t\ts = 26\n\t\tfor j = 49, 64 do\n\t\t\tlocal F = bit32_rrotate(bit32_bxor(c, bit32_bor(b, -1 - d)) + a + K[j] + W[(j * 7 - 7) % 16 + 1], s) + b\n\t\t\ts = md5_next_shift[s]\n\t\t\ta = d\n\t\t\td = c\n\t\t\tc = b\n\t\t\tb = F\n\t\tend\n\n\t\th1 = (a + h1) % 4294967296\n\t\th2 = (b + h2) % 4294967296\n\t\th3 = (c + h3) % 4294967296\n\t\th4 = (d + h4) % 4294967296\n\tend\n\n\tH[1], H[2], H[3], H[4] = h1, h2, h3, h4\nend\n\nlocal function sha1_feed_64(H, str, offs, size)\n\t-- offs >= 0, size >= 0, size is multiple of 64\n\tlocal W = common_W\n\tlocal h1, h2, h3, h4, h5 = H[1], H[2], H[3], H[4], H[5]\n\tfor pos = offs, offs + size - 1, 64 do\n\t\tfor j = 1, 16 do\n\t\t\tpos = pos + 4\n\t\t\tlocal a, b, c, d = string.byte(str, pos - 3, pos)\n\t\t\tW[j] = ((a * 256 + b) * 256 + c) * 256 + d\n\t\tend\n\n\t\tfor j = 17, 80 do\n\t\t\tW[j] = bit32_lrotate(bit32_bxor(W[j - 3], W[j - 8], W[j - 14], W[j - 16]), 1)\n\t\tend\n\n\t\tlocal a, b, c, d, e = h1, h2, h3, h4, h5\n\t\tfor j = 1, 20 do\n\t\t\tlocal z = bit32_lrotate(a, 5) + bit32_band(b, c) + bit32_band(-1 - b, d) + 0x5A827999 + W[j] + e -- constant = math.floor(TWO_POW_30 * sqrt(2))\n\t\t\te = d\n\t\t\td = c\n\t\t\tc = bit32_rrotate(b, 2)\n\t\t\tb = a\n\t\t\ta = z\n\t\tend\n\n\t\tfor j = 21, 40 do\n\t\t\tlocal z = bit32_lrotate(a, 5) + bit32_bxor(b, c, d) + 0x6ED9EBA1 + W[j] + e -- TWO_POW_30 * sqrt(3)\n\t\t\te = d\n\t\t\td = c\n\t\t\tc = bit32_rrotate(b, 2)\n\t\t\tb = a\n\t\t\ta = z\n\t\tend\n\n\t\tfor j = 41, 60 do\n\t\t\tlocal z = bit32_lrotate(a, 5) + bit32_band(d, c) + bit32_band(b, bit32_bxor(d, c)) + 0x8F1BBCDC + W[j] + e -- TWO_POW_30 * sqrt(5)\n\t\t\te = d\n\t\t\td = c\n\t\t\tc = bit32_rrotate(b, 2)\n\t\t\tb = a\n\t\t\ta = z\n\t\tend\n\n\t\tfor j = 61, 80 do\n\t\t\tlocal z = bit32_lrotate(a, 5) + bit32_bxor(b, c, d) + 0xCA62C1D6 + W[j] + e -- TWO_POW_30 * sqrt(10)\n\t\t\te = d\n\t\t\td = c\n\t\t\tc = bit32_rrotate(b, 2)\n\t\t\tb = a\n\t\t\ta = z\n\t\tend\n\n\t\th1 = (a + h1) % 4294967296\n\t\th2 = (b + h2) % 4294967296\n\t\th3 = (c + h3) % 4294967296\n\t\th4 = (d + h4) % 4294967296\n\t\th5 = (e + h5) % 4294967296\n\tend\n\n\tH[1], H[2], H[3], H[4], H[5] = h1, h2, h3, h4, h5\nend\n\nlocal function keccak_feed(lanes_lo, lanes_hi, str, offs, size, block_size_in_bytes)\n\t-- This is an example of a Lua function having 79 local variables :-)\n\t-- offs >= 0, size >= 0, size is multiple of block_size_in_bytes, block_size_in_bytes is positive multiple of 8\n\tlocal RC_lo, RC_hi = sha3_RC_lo, sha3_RC_hi\n\tlocal qwords_qty = block_size_in_bytes / 8\n\tfor pos = offs, offs + size - 1, block_size_in_bytes do\n\t\tfor j = 1, qwords_qty do\n\t\t\tlocal a, b, c, d = string.byte(str, pos + 1, pos + 4)\n\t\t\tlanes_lo[j] = bit32_bxor(lanes_lo[j], ((d * 256 + c) * 256 + b) * 256 + a)\n\t\t\tpos = pos + 8\n\t\t\ta, b, c, d = string.byte(str, pos - 3, pos)\n\t\t\tlanes_hi[j] = bit32_bxor(lanes_hi[j], ((d * 256 + c) * 256 + b) * 256 + a)\n\t\tend\n\n\t\tlocal L01_lo, L01_hi, L02_lo, L02_hi, L03_lo, L03_hi, L04_lo, L04_hi, L05_lo, L05_hi, L06_lo, L06_hi, L07_lo, L07_hi, L0